INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C1','kor',6,1,'u2',1,'고쳐쓰기의 뜻 — 쓴 글을 점검해 하고 싶은 말이 더 잘 전달되도록 필요한 곳만 손보는 일로, 처음 쓴 글을 버리고 처음부터 다시 쓰는 일이나 글씨를 예쁘게 다시 옮겨 적는 일이 아니다',ARRAY['6국03-06 쓰기']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C2','kor',6,1,'u2',1,'고쳐쓰기의 네 가지 일 — 주제에서 벗어난 내용 빼기 · 부족한 내용 더하기 · 어색한 표현을 알맞은 말로 바꾸기 · 순서가 뒤엉킨 부분 옮기기를 필요한 곳에만 하며, 친구 글을 고칠 때에는 다시 짜기까지 다섯 가지로 볼 수 있다',ARRAY['6국04-06 문법']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C3','kor',6,1,'u2',1,'세 수준으로 보기와 큰 것부터 — 고쳐 쓸 때에는 글 수준(제목과 내용 · 처음 · 가운데 · 끝의 흐름) · 문단 수준(중심 문장 · 어울리지 않는 뒷받침 문장) · 문장 수준(호응 · 띄어쓰기)의 세 크기로 보며, 글 → 문단 → 문장의 차례로 큰 것부터 살펴야 헛수고가 줄어든다',ARRAY['6국04-06 문법']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C4','kor',6,1,'u2',1,'고쳐 쓴 글을 나누는 까닭 — 고쳐 쓴 글을 게시판 등에 올려 다른 사람과 나누면 내가 못 본 곳을 친구가 짚어 주고, 읽는 사람의 반응을 바로 알 수 있으며, 읽는 사람이 있다고 생각하면 문장을 더 꼼꼼히 보게 되어 고쳐쓰기에 큰 도움이 된다',ARRAY['6국03-06 쓰기']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C5','kor',6,1,'u2',1,'친구 글에 의견을 말하는 방법 — 같은 내용이라도 말하는 방식에 따라 듣는 사람의 마음이 달라지므로, 잘한 곳을 먼저 말하고 고칠 곳은 반드시 까닭과 함께 말해(잘한 곳 → 고칠 곳 → 까닭) 글쓴이가 다시 고쳐 쓰고 싶어지게 한다',ARRAY['6국03-06 쓰기']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C6','kor',6,1,'u2',1,'온라인에 글을 올릴 때 지킬 것 — 여러 사람이 읽고 의견을 주고 고치기 쉬우며 사진 · 영상도 함께 올릴 수 있지만, 한 번 올린 글은 널리 퍼지므로 줄임말 · 은어 · 비속어를 쓰지 않고 자료를 옮길 때에는 출처를 밝히며 읽는 사람이 누구인지 떠올리며 쓴다',ARRAY['6국03-06 쓰기']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C7','kor',6,1,'u2',1,'고쳐쓰기는 혼나는 일이 아니다 — 고쳐 쓰라는 말은 내 글이 잘못됐다는 뜻이 아니라 여기만 손보면 하고 싶은 말이 더 잘 전해진다는 뜻이며, 완벽한 글을 만드는 일이 아니므로 한 군데를 고쳤으면 그만큼 나아진 것이고 작게 고친 것도 잘 고친 것이다',ARRAY['6국03-06 쓰기']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C8','kor',6,1,'u2',2,'제목이 내용을 나타내는가 — 글 수준에서 제목에 글의 내용과 중심 생각, 글쓴이가 느낀 것이 드러나는지 보며(「모래성 이야기」 → 「무너져도 다시 손을 대는 힘」), 글을 다 쓴 뒤 가장 하고 싶었던 말을 한 줄로 적어 제목으로 옮겨 본다',ARRAY['6국04-06 문법']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C9','kor',6,1,'u2',2,'처음 · 가운데 · 끝의 흐름 — 감상문은 처음(무엇을 보았는지 · 왜 보게 되었는지) → 가운데(간단한 줄거리 · 인상 깊은 장면과 그때의 생각) → 끝(느낀 점이나 다짐)으로 이어지며, 차례가 뒤엉켰으면 내용은 그대로 두고 문단의 차례만 옮겨도 글이 훨씬 잘 읽힌다',ARRAY['6국04-06 문법']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C10','kor',6,1,'u2',2,'중심 내용은 근거가 있으면 여럿 — 같은 글의 중심 내용도 사람마다 조금씩 다르게 말할 수 있어(다시 시작하는 힘 · 함께하면 더 오래 버틴다), 물어야 할 것은 「정답인가」가 아니라 글에서 근거를 댈 수 있는가이다',ARRAY['6국04-06 문법']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C11','kor',6,1,'u2',2,'중심 문장과 뒷받침 문장 — 문단에는 하고 싶은 말을 담은 중심 문장(보통 하나)과 그것을 자세히 설명하거나 예를 드는 뒷받침 문장이 있으며, 문단을 고칠 때에는 먼저 중심 문장을 찾고 뒷받침 문장 가운데 중심 문장과 상관없는 것이 있는지 본다',ARRAY['6국04-06 문법']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C12','kor',6,1,'u2',2,'거리가 먼 문장은 빼거나 고쳐 쓴다 — 중심 문장과 아무 관련이 없으면 지우고(우리 집 강아지도 모래를 좋아한다 → 삭제), 관련은 있는데 표현이 어긋났으면 바꾸어(여름 내내 쌓았다 → 여름 내내 모래성을 쌓았다) 무조건 지우지 않고 지울지 고칠지부터 정한다',ARRAY['6국04-06 문법']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C13','kor',6,1,'u2',2,'문장 성분과 호응 — 주어(무엇이 · 누가) · 목적어(무엇을 · 누구를) · 서술어(어찌하다 · 어떠하다)가 서로 어울리는 것을 호응이라 하며, 내용이 아무리 좋아도 호응이 어긋나면 뜻이 제대로 전해지지 않으므로 고쳐 쓸 때에는 내용과 형식을 함께 본다',ARRAY['6국04-04 문법']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C14','kor',6,1,'u2',2,'호응이 어긋나는 네 가지 — 높임(선생님이 소개했다 → 선생님께서 소개해 주셨다) · 피동과 사동(성이 파도에 무너뜨렸다 → 무너졌다) · 시제(어제 볼 것이다 → 어제 보았다) · 부정(전혀 지루했다 → 전혀 지루하지 않았다)에서 자주 어긋나며, 서술어를 짚고 앞의 말과 어울리는지 소리 내어 읽어 찾는다',ARRAY['6국04-04 문법']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C15','kor',6,1,'u2',2,'세 수준은 따로 도는 절차가 아니다 — 큰 흐름을 손보다 보면 문단이, 문단을 손보다 보면 문장이 보이므로 어느 수준에서 발견하든 그때그때 함께 고치며, 고칠 때 쓰는 부호(∨ 띄어 쓸 때 · ⌒ 붙여 쓸 때 · ⊂ 내용을 더 넣을 때)를 쓰면 지우고 다시 옮겨 쓸 필요가 없다',ARRAY['6국04-06 문법']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C16','kor',6,1,'u2',4,'띄어쓰기는 뜻을 가르는 일 — 같은 글자도 어디서 띄느냐에 따라 전혀 다른 말이 되므로(오늘 밤 나무를 심자 · 오늘 밤나무를 심자 / 큰 집 · 큰집 / 잘 못했다 · 잘못했다), 띄어쓰기는 글씨를 예쁘게 쓰는 일이 아니라 읽는 사람이 글쓴이의 뜻을 알아내게 하는 일이다',ARRAY['6국04-06 문법']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C17','kor',6,1,'u2',4,'수와 세는 말은 띄어 쓴다 — 권 · 마리 · 원 · 그루 · 장 · 잔 · 자루 · 개처럼 세는 말(단위를 나타내는 말)은 앞의 수와 띄어 쓴다(책 세 권 · 나무 두 그루 · 삼천 원 · 종이 스물네 장)',ARRAY['6국04-06 문법']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C18','kor',6,1,'u2',4,'잇거나 나열하는 말은 띄어 쓴다 — 및 · 대 · 겸 · 등처럼 두 말 사이를 잇거나 나열하는 말은 앞뒤를 모두 띄어 쓴다(학생 및 학부모 · 청군 대 백군 · 서점 겸 찻집 · 연필이나 볼펜 등)',ARRAY['6국04-06 문법']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C19','kor',6,1,'u2',4,'조사는 붙이고 홀로 못 쓰는 이름씨는 띄운다 — 이/가 · 을/를 · 은/는 · 에서 · 에게 · 도 · 만 · 처럼 같은 조사는 앞말에 붙여 쓰고(나무처럼), 것 · 수 · 데 · 지 · 만큼처럼 홀로 못 쓰는 이름씨는 띄어 쓰며(할 수 있다), 헷갈리면 앞말에 얹혀 가는 말인지 따로 뜻을 가진 말인지 물어본다',ARRAY['6국04-06 문법']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C20','kor',6,1,'u2',4,'내 띄어쓰기 습관을 점검하기 — 띄어 쓸 곳은 ∨ 부호로 표시해 두고 마지막에 한 번에 옮기면 고칠 곳이 많아도 처음부터 다시 쓸 필요가 없으며, 내가 자주 놓치는 띄어쓰기 한 가지를 스스로 정해 다음 글부터 챙긴다',ARRAY['6국04-06 문법']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C21','kor',6,1,'u2',5,'감상문과 줄거리 요약 — 줄거리 요약은 무슨 일이 일어났는지만 적어 누가 써도 거의 같은 글이 되지만, 감상문은 본 것에 더해 내가 무엇을 느끼고 생각했는지를 적어 쓴 사람마다 다른 글이 된다',ARRAY['6국03-06 쓰기']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C22','kor',6,1,'u2',5,'인상 깊은 장면과 그 까닭 — 감상문의 출발점은 마음에 남은 한 장면이며, 「이 장면이 좋았다」로 끝내지 않고 왜 그 장면이 남았는지(각자 우산을 쓰는데도 둘이 더 가까워 보여서 · 도움을 받는 게 왜 어려웠을지 생각하게 돼서)까지 적어야 감상문이 된다',ARRAY['6국03-06 쓰기']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C23','kor',6,1,'u2',5,'감상문에 담을 내용과 짜임 — 보게 된 동기 · 간단한 줄거리 · 인상 깊은 장면과 까닭 · 느낀 점이나 다짐을 담고, 처음(무엇을 · 어떻게 보게 되었는지) → 가운데(줄거리는 짧게, 장면과 생각은 길게 — 가장 긺) → 끝(느낀 점과 앞으로 하고 싶은 일)으로 짜며, 모든 장면이나 상관없는 자잘한 것은 넣지 않는다',ARRAY['6국03-06 쓰기']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C24','kor',6,1,'u2',5,'고칠 차례 — 큰 것부터, 고르게 — 초고를 고칠 때에는 제목과 글 전체의 흐름부터 잡고(문장을 다 다듬었는데 그 문장이 통째로 빠져야 하면 헛수고) 문단 → 문장 차례로 고르게 살피며, 맞춤법 · 띄어쓰기는 마지막에 하는 일이라 그것만 바로잡거나 낱말 몇 개만 바꾸는 것으로 고쳐쓰기가 끝나지 않는다',ARRAY['6국04-06 문법']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C25','kor',6,1,'u2',7,'명확한 문장의 세 가지 조건 — 한 문장에는 한 가지만 담고(길면 나눔) · 주어 · 목적어 · 서술어 가운데 빠진 것이 없게 하고 · 겹치는 표현은 하나로 줄이면(되풀이되던 「번호」 → 숫자 · 표시) 글자 수는 줄어도 뜻은 더 또렷해져 읽는 사람이 두 번 읽지 않아도 된다',ARRAY['6국04-04 문법']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C26','kor',6,1,'u2',7,'말과 달리 글에서는 필수 성분을 갖춘다 — 말할 때에는 서로 아는 것이 많아 주어와 목적어를 빼도 통하지만(여기 있어. 아까 찾던 거.), 읽는 사람은 그 자리에 없었으므로 글에서는 주어 · 목적어 · 서술어 같은 필수 성분을 갖춰야 뜻이 전해진다',ARRAY['6국04-04 문법']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C27','kor',6,1,'u2',7,'주제와 제목 정하기 — 좋은 주제는 친구들이 궁금해할 만하고 내가 끝까지 자료를 모을 수 있는 것이며(너무 넓거나 자료를 거의 찾을 수 없는 것은 어렵다), 제목은 내용과 일치하고 짧으면서 읽는 사람의 관심을 끌어야 하므로 주제를 정한 다음에 정한다',ARRAY['6국03-06 쓰기']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C28','kor',6,1,'u2',7,'믿을 수 있는 자료와 출처 — 자료는 누가 만들었는지(믿을 수 있는가) · 언제 만들었는지(지금도 맞는가) · 어디서 가져왔는지(출처를 밝혔는가)를 확인하며, 누가 언제 썼는지 알 수 없는 글이나 어디선가 들었다는 이야기처럼 확인하지 않은 자료는 쓰지 않는다',ARRAY['6국03-06 쓰기']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C29','kor',6,1,'u2',7,'설명하는 글의 짜임 — 처음(무엇을 설명할지 밝히고 관심을 끎) → 가운데(설명하려는 내용을 알기 쉽고 자세하게 — 무엇을 나타내는지 · 나누는 방법의 예 · 찾는 차례) → 끝(전체 내용을 간추리고 마무리)으로 짜며, 쓰기 전에 세 칸을 한 줄씩 채워 두면 글이 흩어지지 않는다',ARRAY['6국03-06 쓰기']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C30','kor',6,1,'u2',7,'찾은 자료는 내 말로 바꾸어 쓴다 — 찾은 자료를 그대로 붙여 넣는 것은 글쓰기가 아니며 읽고 이해한 뒤 내 말로 다시 쓰고, 읽는 사람이 아는 말로 풀어 쓰며 줄임말 · 은어 · 비속어를 쓰지 않고 가져온 곳을 함께 적으며, 디지털 매체로 쓸 때에는 자주 저장하고 내용과 이어지는 그림만 넣는다',ARRAY['6국03-06 쓰기']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C31','kor',6,1,'u2',9,'친구 글에 대한 의견의 네 갈래 — 친구 글은 먼저 무슨 말을 하려는 글인지 한 줄로 잡은 뒤, 새롭게 안 점(몰랐는데 알게 된 것) · 궁금한 점(더 알고 싶은 것) · 좋은 점(잘 쓴 곳과 까닭) · 고쳤으면 하는 점(고칠 곳과 까닭)으로 나누어 「그냥 좋아」나 「별로야」로 끝나지 않게 한다',ARRAY['6국03-06 쓰기']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C32','kor',6,1,'u2',9,'의견은 골라서 받아들인다 — 의견은 받는 것이고 고르는 것은 글쓴이이므로 친구의 의견을 모두 따를 필요는 없으며, 「이 의견을 따르면 내가 하려던 말이 더 잘 전해지는가?」를 기준으로 고르고 따르지 않기로 했다면 그 까닭을 스스로 말할 수 있으면 된다',ARRAY['6국03-06 쓰기']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C33','kor',6,1,'u2',9,'공유하는 차례와 좋은 점 — 고쳐 쓴 마지막 글을 올리고 → 제대로 올라갔는지 확인하고 → 친구 글에 댓글을 달고 → 내 글에 달린 댓글을 읽고 다시 점검하며, 댓글에는 읽었다는 것과 어떻게 했는지를 답글로 알린다; 공유하면 혼자서는 놓친 곳 · 내 글이 어떻게 읽히는지 · 새로운 생각을 얻는다',ARRAY['6국03-06 쓰기']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C34','kor',6,1,'u2',9,'맞춤법 검사기와 인공 지능 도구 — 띄어쓰기와 맞춤법을 빠르게 짚어 주고 내가 자주 틀리는 곳을 알게 해 주지만, 글의 중심 생각은 도구가 정해 주지 못하고 고칠지 말지는 글쓴이가 정하며, 도구가 고친 곳도 왜 그렇게 고쳤는지 확인하고 받아들인다',ARRAY['6국04-06 문법']::text[],34) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C35','kor',6,1,'u2',9,'사진과 영상도 글의 한 부분 — 글에 넣은 사진 · 영상이 설명하는 내용을 바로 보여 주는지(책등의 숫자가 보이는 서가 사진) 겉도는지(도서관 건물 바깥 풍경) 점검하며, 내용과 이어지지 않으면 보기 좋아도 빼는 것이 고쳐쓰기다',ARRAY['6국03-06 쓰기']::text[],35) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C36','kor',6,1,'u2',12,'소개하는 글 — 고르기와 짜임 — 물건 · 작품(감상문 형식) · 알게 된 것(설명하는 형식) 가운데 쓸 말이 세 문단쯤 나오는 것을 고르고, 처음(무엇을 소개할지 · 왜 골랐는지) → 가운데(어떤 것인지 자세히 · 나와 얽힌 그것만의 이야기) → 끝(소개를 맺으며 앞으로 하고 싶은 일)으로 쓴다',ARRAY['6국03-06 쓰기']::text[],36) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C37','kor',6,1,'u2',12,'소개는 자랑이 아니다 — 「내 자전거가 제일 좋다」처럼 쓰면 읽는 사람이 알 수 있는 것이 없으므로 「손잡이가 손 모양대로 닳아서 잡으면 손이 딱 맞는다」처럼 읽는 사람이 그려 볼 수 있게 쓰며, 친구 글에는 잘한 곳을 짚고 부족한 곳은 까닭과 함께 알려 주며 글을 조금씩 나아지게 한다',ARRAY['6국03-06 쓰기']::text[],37) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C38','kor',6,1,'u2',12,'시간 표현 · 주어와 서술어의 짝 — 어제 · 지난주 · 아까는 「보았다」, 오늘 · 지금은 「본다」, 내일 · 다음 주는 「볼 것이다」처럼 시간을 나타내는 말이 앞에 나오면 서술어가 끌려가고, 주어가 「내 생각은」이면 「~것이다」로, 주어가 스스로 한 일이 아니면 「~되다 · ~히다」로 받는다(화면이 어둠으로 채워졌다)',ARRAY['6국04-04 문법']::text[],38) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C39','kor',6,1,'u2',12,'주동과 피동 — 주체가 스스로 하는 일은 주동(내가 문을 닫다 · 그림을 걸다 · 책을 놓다), 다른 힘에 의해 그리 되는 일은 피동(문이 닫히다 · 그림이 걸리다 · 책이 놓이다)으로 쓰며, 스스로 하는 일에는 -히- · -리- · -이-를 붙이지 않는다 (기초 다지기)',ARRAY['기초 다지기(주동과 피동)']::text[],39) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X01','kor',6,'u2',ARRAY['K6-1-u2-C1']::text[],'고쳐쓰기를 처음 쓴 글을 버리고 처음부터 다시 쓰는 일이나 글씨를 예쁘게 다시 옮겨 적는 일로 여긴다','필요한 곳만 손보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X02','kor',6,'u2',ARRAY['K6-1-u2-C7']::text[],'고쳐 쓰라는 말을 내 글이 잘못됐다는 뜻으로 여겨 통째로 다시 쓰거나, 완벽하게 고쳐야 하며 작게 고친 것은 소용없다고 여긴다','작게 고친 것도 잘 고친 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X03','kor',6,'u2',ARRAY['K6-1-u2-C2']::text[],'빼기 · 더하기 · 바꾸기 · 옮기기를 서로 헷갈리거나, 고칠 필요가 없는 곳까지 손본다','필요한 곳에 알맞은 손질') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X04','kor',6,'u2',ARRAY['K6-1-u2-C3']::text[],'살필 일이 글 · 문단 · 문장 가운데 어느 수준의 일인지 헷갈린다','글 전체? 문단 하나? 한 문장?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X05','kor',6,'u2',ARRAY['K6-1-u2-C3','K6-1-u2-C24']::text[],'띄어쓰기 · 맞춤법부터 손대거나, 그것만 바로잡고 낱말 몇 개만 바꾸면 고쳐쓰기가 끝났다고 여긴다','큰 것부터, 맞춤법은 마지막') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X06','kor',6,'u2',ARRAY['K6-1-u2-C5']::text[],'고칠 곳만 늘어놓거나 「다시 써」처럼 글쓴이를 위축시키는 말로 의견을 말한다','잘한 곳을 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X07','kor',6,'u2',ARRAY['K6-1-u2-C5','K6-1-u2-C31']::text[],'「다 좋아, 고칠 곳 하나도 없어」처럼 막연한 칭찬만 해 글쓴이에게 쓸모 있는 말을 주지 못한다','어디가 왜 좋은지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X08','kor',6,'u2',ARRAY['K6-1-u2-C5']::text[],'고칠 곳을 까닭 없이 「여기 고쳐」라고만 말한다','고칠 곳은 까닭과 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X09','kor',6,'u2',ARRAY['K6-1-u2-C6','K6-1-u2-C30']::text[],'온라인에 줄임말 · 은어 · 비속어를 쓰거나, 남의 자료를 출처를 밝히지 않고 옮긴다','한 번 올린 글은 널리 퍼져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X10','kor',6,'u2',ARRAY['K6-1-u2-C4','K6-1-u2-C33']::text[],'글을 나누는 것을 칭찬받는 일로 여기거나, 나누면 더 고치지 않아도 된다고 여긴다','못 본 곳을 알게 되는 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X11','kor',6,'u2',ARRAY['K6-1-u2-C8','K6-1-u2-C27']::text[],'제목은 글감이나 줄거리만 알리면 된다고 여겨 중심 생각이나 느낀 것을 담지 않는다','가장 하고 싶었던 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X12','kor',6,'u2',ARRAY['K6-1-u2-C9','K6-1-u2-C23','K6-1-u2-C29']::text[],'처음 · 가운데 · 끝에 들어갈 내용을 뒤섞거나 문단의 차례를 뒤엉킨 채 둔다','처음 · 가운데 · 끝') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X13','kor',6,'u2',ARRAY['K6-1-u2-C10']::text[],'글의 중심 내용은 정답이 하나뿐이라고 여기거나, 근거 없이 중심 내용을 정한다','근거를 댈 수 있는가') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X14','kor',6,'u2',ARRAY['K6-1-u2-C11']::text[],'중심 문장과 뒷받침 문장을 서로 헷갈린다','하고 싶은 말 / 자세히 설명') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X15','kor',6,'u2',ARRAY['K6-1-u2-C11','K6-1-u2-C12']::text[],'주제나 중심 문장과 상관없는 문장을 그대로 둔다','중심 문장과 이어지나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X16','kor',6,'u2',ARRAY['K6-1-u2-C12']::text[],'중심 문장과 관련은 있는데 표현만 어긋난 문장까지 무조건 지운다','뺄지 고칠지부터') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X17','kor',6,'u2',ARRAY['K6-1-u2-C13']::text[],'내용만 좋으면 문장 성분의 호응이 어긋나도 뜻이 전해진다고 여긴다','내용과 형식을 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X18','kor',6,'u2',ARRAY['K6-1-u2-C14']::text[],'웃어른이 주어인데 높임 표현으로 받지 않는다(선생님이 소개했다 · 아버지가 물려줬다)','께서 · ~시다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X19','kor',6,'u2',ARRAY['K6-1-u2-C14','K6-1-u2-C39']::text[],'당하는 말을 써야 할 곳에 시키거나 스스로 하는 말을 쓴다(성이 파도에 무너뜨렸다)','누가 한 일인가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X20','kor',6,'u2',ARRAY['K6-1-u2-C14','K6-1-u2-C38']::text[],'시간을 나타내는 말과 서술어의 때를 어긋나게 쓴다(어제 볼 것이다)','어제 → 보았다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X21','kor',6,'u2',ARRAY['K6-1-u2-C14']::text[],'「전혀 · 조금도 · 별로」 같은 말 뒤에 부정하는 서술어를 쓰지 않는다(전혀 지루했다)','전혀 → ~지 않다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X22','kor',6,'u2',ARRAY['K6-1-u2-C15']::text[],'글 · 문단 · 문장 수준을 따로따로 세 번 차례대로 도는 절차로 여겨 발견한 것을 미뤄 둔다','보이는 그때그때 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X23','kor',6,'u2',ARRAY['K6-1-u2-C15','K6-1-u2-C20']::text[],'고칠 때 쓰는 부호(∨ · ⌒ · ⊂)의 쓰임을 서로 헷갈린다','띄움 · 붙임 · 더 넣음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X24','kor',6,'u2',ARRAY['K6-1-u2-C16']::text[],'띄어쓰기를 뜻과 상관없는 글씨 문제로 여겨 조금 틀려도 읽는 사람이 다 알아듣는다고 여긴다','한 칸이 뜻을 갈라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X25','kor',6,'u2',ARRAY['K6-1-u2-C17']::text[],'권 · 마리 · 장 · 개 같은 세는 말을 앞의 수에 붙여 쓴다','수 ∨ 세는 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X26','kor',6,'u2',ARRAY['K6-1-u2-C18']::text[],'및 · 대 · 겸 · 등 같은 잇거나 나열하는 말을 앞말이나 뒷말에 붙여 쓴다','잇는 말 앞뒤를 띄워요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X27','kor',6,'u2',ARRAY['K6-1-u2-C19']::text[],'이/가 · 을/를 · 처럼 · 에게 같은 조사를 앞말과 띄어 쓴다','조사는 앞말에 얹혀 가요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X28','kor',6,'u2',ARRAY['K6-1-u2-C19']::text[],'것 · 수 · 데 · 지 · 만큼 같은 홀로 못 쓰는 이름씨를 앞말에 붙여 쓴다','할 ∨ 수 ∨ 있다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X29','kor',6,'u2',ARRAY['K6-1-u2-C20']::text[],'띄어 쓸 곳이 많으면 지우고 처음부터 옮겨 쓰거나, 내가 자주 놓치는 곳을 정해 두지 않고 규칙만 외우면 된다고 여긴다','∨ 로 표시 · 내 버릇 한 가지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X30','kor',6,'u2',ARRAY['K6-1-u2-C21']::text[],'감상문을 무슨 일이 일어났는지만 적는 줄거리 요약으로 여긴다','내가 느끼고 생각한 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X31','kor',6,'u2',ARRAY['K6-1-u2-C22']::text[],'인상 깊은 장면을 고르고 「좋았다 · 재미있었다」로 끝내 왜 그 장면이 남았는지 쓰지 않는다','왜 그 장면이 남았나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X32','kor',6,'u2',ARRAY['K6-1-u2-C23']::text[],'감상문에 모든 장면이나 옷 색깔 같은 상관없는 자잘한 것을 넣고, 줄거리를 길게 늘어놓는다','줄거리는 짧게, 생각은 길게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X33','kor',6,'u2',ARRAY['K6-1-u2-C25']::text[],'한 문장에 여러 가지를 이어 붙여 길게 쓴다','한 문장에 한 가지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X34','kor',6,'u2',ARRAY['K6-1-u2-C26','K6-1-u2-C25']::text[],'글에서도 말할 때처럼 주어 · 목적어 · 서술어를 빼고 쓴다','읽는 사람은 그 자리에 없었어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X35','kor',6,'u2',ARRAY['K6-1-u2-C25']::text[],'같은 낱말이나 겹치는 표현을 되풀이해 쓴다','겹치는 것은 하나로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X36','kor',6,'u2',ARRAY['K6-1-u2-C27','K6-1-u2-C36']::text[],'너무 넓거나 쓸 말 · 자료가 거의 없는 주제를 고르거나, 내용과 다른 제목을 단다','끝까지 쓸 수 있는 주제') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X37','kor',6,'u2',ARRAY['K6-1-u2-C28']::text[],'누가 언제 만들었는지 모르는 자료나 어디선가 들은 이야기를 확인하지 않고 쓴다','누가 · 언제 · 어디서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X38','kor',6,'u2',ARRAY['K6-1-u2-C30']::text[],'찾은 자료를 이해하지 않고 그대로 옮겨 붙여도 내 글이 된다고 여긴다','내 말로 바꾸어 쓰기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X39','kor',6,'u2',ARRAY['K6-1-u2-C31']::text[],'친구의 말이 새롭게 안 점 · 궁금한 점 · 좋은 점 · 고쳤으면 하는 점 가운데 어느 갈래인지 헷갈린다','알게 됨? 궁금함? 잘함? 고칠 곳?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X40','kor',6,'u2',ARRAY['K6-1-u2-C32']::text[],'친구가 말한 의견은 모두 따라 고쳐야 한다고 여긴다','고르는 것은 글쓴이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X41','kor',6,'u2',ARRAY['K6-1-u2-C33']::text[],'글을 올린 뒤 확인하지 않거나, 달린 댓글을 읽고 답글을 달거나 다시 점검하지 않고 끝낸다','올리고 → 확인 → 댓글 → 다시 점검') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X42','kor',6,'u2',ARRAY['K6-1-u2-C34']::text[],'맞춤법 검사기나 인공 지능 도구가 고친 곳을 까닭 확인 없이 받아들이거나, 도구가 중심 생각까지 정해 준다고 여긴다','고칠지 말지는 글쓴이가') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X43','kor',6,'u2',ARRAY['K6-1-u2-C35','K6-1-u2-C30']::text[],'보기 좋은 사진 · 영상을 글의 내용과 상관없이 넣는다','내용과 이어지나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X44','kor',6,'u2',ARRAY['K6-1-u2-C37']::text[],'소개하는 글을 자랑하는 글로 여겨 「제일 좋다」처럼 읽는 사람이 그려 볼 수 없는 말을 쓴다','그려 볼 수 있게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X45','kor',6,'u2',ARRAY['K6-1-u2-C36','K6-1-u2-C37']::text[],'소개할 것만의 이야기 없이 누구에게나 있는 말(자전거는 바퀴가 두 개인 탈것)로 소개한다','그것만의 이야기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X46','kor',6,'u2',ARRAY['K6-1-u2-C38']::text[],'주어와 서술어의 짝을 어긋나게 쓴다(내 생각은 판단하면 안 된다 · 화면이 어둠으로 채웠다)','주어에 맞는 서술어') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X47','kor',6,'u2',ARRAY['K6-1-u2-C39']::text[],'스스로 하는 일과 다른 힘에 의해 그리 되는 일의 말을 헷갈린다(내가 창문을 닫혔다 · 바람에 창문이 닫았다)','스스로? 다른 힘?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L01_basic#1','kor',6,1,'u2','L01','g6_1_kor_u2_L01_basic','lesson_basic','K6-1-u2-C1',1,'mc','auto','「고쳐쓰기」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X01']::text[],false,'{"seq":1,"concept":"K6-1-u2-C1","difficulty":1,"kind":"mc","stem":"「고쳐쓰기」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"쓴 글을 점검해 더 잘 전달되도록 손보는 일","correct":true},{"t":"처음 쓴 글을 버리고 처음부터 다시 쓰는 일","mis":"K6-1-u2-X01"},{"t":"글씨를 예쁘게 다시 옮겨 적는 일","mis":"K6-1-u2-X01"},{"t":"친구 글을 그대로 베껴 쓰는 일","mis":"K6-1-u2-X01"}],"explanation":["다시 쓰기나 옮겨 적기가 아니에요.","점검한 내용을 바탕으로 해요.","필요한 곳만 손보아 글을 낫게 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L01_basic#2','kor',6,1,'u2','L01','g6_1_kor_u2_L01_basic','lesson_basic','K6-1-u2-C15',1,'mc','auto','「사물함을 정리하면 좋은 점」에서 글의 주제와 어울리지 않는 문장은 어느 것인가요?',ARRAY['K6-1-u2-X15']::text[],false,'{"seq":2,"concept":"K6-1-u2-C15","difficulty":1,"kind":"mc","stem":"「사물함을 정리하면 좋은 점」에서 글의 주제와 어울리지 않는 문장은 어느 것인가요?","options":[{"t":"우리 학교 급식실은 이번 달에 새로 바뀌었습니다.","correct":true},{"t":"종이류를 한곳에 모아 두면 구겨지는 일도 줄어듭니다.","mis":"K6-1-u2-X15"},{"t":"사물함이 어지러우면 필요한 물건을 찾는 데 시간이 오래 걸립니다.","mis":"K6-1-u2-X15"},{"t":"사물함을 자주 비우면 잃어버린 물건도 빨리 찾습니다.","mis":"K6-1-u2-X15"}],"explanation":["글의 주제는 사물함 정리예요.","급식실 이야기는 주제에서 벗어나요.","주제에서 벗어난 문장은 빼요."],"asset":{"type":"passage","lines":["사물함이 어지러우면 필요한 물건을 찾는 데 시간이 오래 걸립니다.","수업이 시작되었는데도 교과서를 못 찾아 허둥대기 쉽습니다.","종이류를 한곳에 모아 두면 구겨지는 일도 줄어듭니다.","우리 학교 급식실은 이번 달에 새로 바뀌었습니다.","사물함을 자주 비우면 잃어버린 물건도 빨리 찾습니다.","그러므로 일주일에 한 번은 사물함을 정리한다."],"title":"설명 글 「사물함을 정리하면 좋은 점」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L01_basic#3','kor',6,1,'u2','L01','g6_1_kor_u2_L01_basic','lesson_basic','K6-1-u2-C2',1,'match','auto','고칠 일과 그에 알맞은 손질을 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K6-1-u2-C2","difficulty":1,"kind":"match","stem":"고칠 일과 그에 알맞은 손질을 이으세요.","pairs":[{"l":"주제에서 벗어난 내용","r":"빼기"},{"l":"부족한 내용","r":"더하기"},{"l":"순서가 뒤엉킨 부분","r":"옮기기"}],"mis":"K6-1-u2-X03","explanation":["벗어난 것은 빼요.","모자란 것은 더해요.","뒤엉킨 것은 옮겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L01_basic#4','kor',6,1,'u2','L01','g6_1_kor_u2_L01_basic','lesson_basic','K6-1-u2-C4',1,'ox','auto','고쳐 쓴 글을 다른 사람과 나누면 내가 못 본 곳을 알게 될 수 있어요.',ARRAY['K6-1-u2-X10']::text[],false,'{"seq":4,"concept":"K6-1-u2-C4","difficulty":1,"kind":"ox","stem":"고쳐 쓴 글을 다른 사람과 나누면 내가 못 본 곳을 알게 될 수 있어요.","answer":"O","reason_options":[{"t":"친구가 내가 놓친 곳을 짚어 주고 읽는 사람의 반응을 알 수 있기 때문에","correct":true},{"t":"나누면 무조건 칭찬을 받기 때문에","mis":"K6-1-u2-X10"}],"mis":"K6-1-u2-X10","explanation":["세아는 못 본 곳을 친구가 짚어 줬어요.","읽는 사람의 반응을 바로 알 수 있어요.","고쳐쓰기에 큰 도움이 돼요."],"asset":{"type":"speech","turns":[{"who":"세아","text":"학급 게시판에 올린 내 글에 댓글이 세 개 달렸어. 내가 못 본 곳을 친구가 짚어 줬어."},{"who":"민석","text":"나도 올려 봤는데, 읽는 사람이 있다고 생각하니까 문장을 더 꼼꼼히 보게 되더라."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L01_basic#5','kor',6,1,'u2','L01','g6_1_kor_u2_L01_basic','lesson_basic','K6-1-u2-C2',2,'mc','auto','「사물함을 정리하면 좋은 점」의 마지막 문장이 어색한 까닭은 무엇인가요?',ARRAY['K6-1-u2-X15','K6-1-u2-X04','K6-1-u2-X11']::text[],false,'{"seq":5,"concept":"K6-1-u2-C2","difficulty":2,"kind":"mc","stem":"「사물함을 정리하면 좋은 점」의 마지막 문장이 어색한 까닭은 무엇인가요?","options":[{"t":"앞 문장들은 「~습니다」로 썼는데 마지막만 「정리한다」로 말투가 어긋나서","correct":true},{"t":"사물함 이야기가 아니어서","mis":"K6-1-u2-X15"},{"t":"문장이 너무 짧아서","mis":"K6-1-u2-X04"},{"t":"제목과 같은 낱말을 써서","mis":"K6-1-u2-X11"}],"explanation":["마지막 문장도 사물함 이야기예요.","말투가 앞 문장들과 달라요.","「정리합시다」처럼 말투를 맞춰요."],"asset":{"type":"passage","lines":["사물함이 어지러우면 필요한 물건을 찾는 데 시간이 오래 걸립니다.","수업이 시작되었는데도 교과서를 못 찾아 허둥대기 쉽습니다.","종이류를 한곳에 모아 두면 구겨지는 일도 줄어듭니다.","우리 학교 급식실은 이번 달에 새로 바뀌었습니다.","사물함을 자주 비우면 잃어버린 물건도 빨리 찾습니다.","그러므로 일주일에 한 번은 사물함을 정리한다."],"title":"설명 글 「사물함을 정리하면 좋은 점」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L01_basic#6','kor',6,1,'u2','L01','g6_1_kor_u2_L01_basic','lesson_basic','K6-1-u2-C3',2,'match','auto','살필 내용과 수준을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-1-u2-C3","difficulty":2,"kind":"match","stem":"살필 내용과 수준을 알맞게 이으세요.","pairs":[{"l":"제목이 내용을 잘 나타내는가","r":"글 수준"},{"l":"뒷받침 문장이 중심 문장과 어울리는가","r":"문단 수준"},{"l":"주어와 서술어가 호응하는가","r":"문장 수준"}],"mis":"K6-1-u2-X04","explanation":["제목은 글 전체를 봐야 알아요.","뒷받침 문장은 문단 하나를 보면 알아요.","호응은 한 문장만 봐도 알아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L01_basic#7','kor',6,1,'u2','L01','g6_1_kor_u2_L01_basic','lesson_basic','K6-1-u2-C5',2,'mc','auto','친구 글에 남길 댓글로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X06','K6-1-u2-X07','K6-1-u2-X08']::text[],false,'{"seq":7,"concept":"K6-1-u2-C5","difficulty":2,"kind":"mc","stem":"친구 글에 남길 댓글로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「첫 문단이 눈에 잘 들어왔어. 셋째 문장은 주제와 조금 멀어 보여.」","correct":true},{"t":"「무슨 말인지 하나도 모르겠어. 다시 써.」","mis":"K6-1-u2-X06"},{"t":"「그냥 다 좋아. 고칠 곳이 하나도 없어.」","mis":"K6-1-u2-X07"},{"t":"「셋째 문장 고쳐.」","mis":"K6-1-u2-X08"}],"explanation":["다시 쓰라는 말은 글쓴이를 위축시켜요.","막연한 칭찬은 쓸모가 적어요.","잘한 곳을 먼저, 고칠 곳은 까닭과 함께 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L01_basic#8','kor',6,1,'u2','L01','g6_1_kor_u2_L01_basic','lesson_basic','K6-1-u2-C6',2,'ox','auto','온라인 게시판에 글을 올릴 때에는 줄임말이나 은어를 써도 괜찮아요.',ARRAY['K6-1-u2-X09']::text[],false,'{"seq":8,"concept":"K6-1-u2-C6","difficulty":2,"kind":"ox","stem":"온라인 게시판에 글을 올릴 때에는 줄임말이나 은어를 써도 괜찮아요.","answer":"X","reason_options":[{"t":"한 번 올린 글은 널리 퍼지고 읽는 사람이 여럿이기 때문에","correct":true},{"t":"친구끼리는 줄임말이 더 빨리 통하기 때문에","mis":"K6-1-u2-X09"}],"mis":"K6-1-u2-X09","explanation":["올린 글은 여러 사람이 읽어요.","한 번 올리면 널리 퍼져요.","줄임말 · 은어 · 비속어를 쓰지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L01_basic#9','kor',6,1,'u2','L01','g6_1_kor_u2_L01_basic','lesson_basic','K6-1-u2-C3',2,'mc','auto','고쳐 쓸 때 살피는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X05','K6-1-u2-X04']::text[],false,'{"seq":9,"concept":"K6-1-u2-C3","difficulty":2,"kind":"mc","stem":"고쳐 쓸 때 살피는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"글 → 문단 → 문장","correct":true},{"t":"문장 → 문단 → 글","mis":"K6-1-u2-X05"},{"t":"띄어쓰기 → 글씨 → 제목","mis":"K6-1-u2-X05"},{"t":"문단 → 글 → 문장","mis":"K6-1-u2-X04"}],"explanation":["큰 것부터 봐요.","작은 것부터 고치면 헛수고가 생겨요.","글 → 문단 → 문장 차례예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L01_basic#10','kor',6,1,'u2','L01','g6_1_kor_u2_L01_basic','lesson_basic','K6-1-u2-C7',3,'mc','auto','「고쳐 쓰라는 말은 내 글이 잘못됐다는 뜻이야.」라고 생각하는 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X02','K6-1-u2-X01']::text[],false,'{"seq":10,"concept":"K6-1-u2-C7","difficulty":3,"kind":"mc","stem":"「고쳐 쓰라는 말은 내 글이 잘못됐다는 뜻이야.」라고 생각하는 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「여기만 손보면 네가 하고 싶은 말이 더 잘 전해진다는 뜻이야. 작게 고친 것도 잘 고친 거야.」","correct":true},{"t":"「맞아, 그러니까 글을 통째로 다시 써.」","mis":"K6-1-u2-X02"},{"t":"「고칠 곳이 있으면 처음부터 새로 쓰는 게 빨라.」","mis":"K6-1-u2-X01"},{"t":"「완벽하게 고치지 못할 거면 손대지 마.」","mis":"K6-1-u2-X02"}],"explanation":["고쳐쓰기는 혼나는 일이 아니에요.","다시 쓰기가 아니에요.","필요한 곳만 손봐도 글이 나아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L01_challenge#1','kor',6,1,'u2','L01','g6_1_kor_u2_L01_challenge','lesson_challenge','K6-1-u2-C2',2,'mc','auto','「사물함을 정리하면 좋은 점」에서 급식실 문장에 해야 할 손질은 무엇인가요?',ARRAY['K6-1-u2-X03','K6-1-u2-X01']::text[],false,'{"seq":1,"concept":"K6-1-u2-C2","difficulty":2,"kind":"mc","stem":"「사물함을 정리하면 좋은 점」에서 급식실 문장에 해야 할 손질은 무엇인가요?","options":[{"t":"빼기","correct":true},{"t":"더하기","mis":"K6-1-u2-X03"},{"t":"옮기기","mis":"K6-1-u2-X03"},{"t":"글씨 다시 쓰기","mis":"K6-1-u2-X01"}],"explanation":["급식실 문장은 주제와 상관없어요.","옮겨도 주제와 맞지 않아요.","주제에서 벗어난 내용은 빼요."],"asset":{"type":"passage","lines":["사물함이 어지러우면 필요한 물건을 찾는 데 시간이 오래 걸립니다.","수업이 시작되었는데도 교과서를 못 찾아 허둥대기 쉽습니다.","종이류를 한곳에 모아 두면 구겨지는 일도 줄어듭니다.","우리 학교 급식실은 이번 달에 새로 바뀌었습니다.","사물함을 자주 비우면 잃어버린 물건도 빨리 찾습니다.","그러므로 일주일에 한 번은 사물함을 정리한다."],"title":"설명 글 「사물함을 정리하면 좋은 점」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L01_challenge#2','kor',6,1,'u2','L01','g6_1_kor_u2_L01_challenge','lesson_challenge','K6-1-u2-C1',2,'ox','auto','고쳐쓰기를 할 때에는 처음 쓴 글을 버리고 처음부터 새로 써야 해요.',ARRAY['K6-1-u2-X01']::text[],false,'{"seq":2,"concept":"K6-1-u2-C1","difficulty":2,"kind":"ox","stem":"고쳐쓰기를 할 때에는 처음 쓴 글을 버리고 처음부터 새로 써야 해요.","answer":"X","reason_options":[{"t":"고쳐쓰기는 점검한 내용을 바탕으로 필요한 곳만 손보는 일이기 때문에","correct":true},{"t":"처음 쓴 글에는 좋은 곳이 하나도 없기 때문에","mis":"K6-1-u2-X01"}],"mis":"K6-1-u2-X01","explanation":["고쳐쓰기는 다시 쓰기가 아니에요.","처음 쓴 글에도 살릴 곳이 있어요.","필요한 곳만 손봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L01_challenge#3','kor',6,1,'u2','L01','g6_1_kor_u2_L01_challenge','lesson_challenge','K6-1-u2-C3',3,'error','auto','고쳐 쓸 때 살피는 수준을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u2-X04']::text[],false,'{"seq":3,"concept":"K6-1-u2-C3","difficulty":3,"kind":"error","stem":"고쳐 쓸 때 살피는 수준을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"규리 — 「제목이 내용과 어울리는지는 한 문장만 보면 알 수 있어.」","correct":true,"mis_target":"K6-1-u2-X04"},{"t":"하율 — 「처음 · 가운데 · 끝의 흐름은 글 전체를 봐야 해.」","mis":"K6-1-u2-X04"},{"t":"서진 — 「띄어쓰기는 문장 수준에서 살펴.」","mis":"K6-1-u2-X04"}],"explanation":["하율과 서진은 바르게 말했어요.","제목과 내용은 글 전체를 봐야 알아요.","규리는 글 수준의 일을 문장 수준으로 보았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L01_challenge#4','kor',6,1,'u2','L01','g6_1_kor_u2_L01_challenge','lesson_challenge','K6-1-u2-C4',3,'mc','auto','민석이가 「읽는 사람이 있다고 생각하니까 문장을 더 꼼꼼히 보게 되더라.」라고 한 말에서 알 수 있는 것은 무엇인가요?',ARRAY['K6-1-u2-X10','K6-1-u2-X05']::text[],false,'{"seq":4,"concept":"K6-1-u2-C4","difficulty":3,"kind":"mc","stem":"민석이가 「읽는 사람이 있다고 생각하니까 문장을 더 꼼꼼히 보게 되더라.」라고 한 말에서 알 수 있는 것은 무엇인가요?","options":[{"t":"글을 나누면 읽는 사람을 떠올리게 되어 고쳐쓰기에 도움이 된다","correct":true},{"t":"글을 나누면 더 고치지 않아도 된다","mis":"K6-1-u2-X10"},{"t":"글을 나누는 것은 칭찬을 받으려는 것이다","mis":"K6-1-u2-X10"},{"t":"읽는 사람이 없으면 띄어쓰기만 보면 된다","mis":"K6-1-u2-X05"}],"explanation":["읽는 사람을 떠올리면 문장을 더 꼼꼼히 봐요.","나눈 뒤에도 다시 점검해요.","나누는 것은 고쳐쓰기를 돕는 일이에요."],"asset":{"type":"speech","turns":[{"who":"세아","text":"학급 게시판에 올린 내 글에 댓글이 세 개 달렸어. 내가 못 본 곳을 친구가 짚어 줬어."},{"who":"민석","text":"나도 올려 봤는데, 읽는 사람이 있다고 생각하니까 문장을 더 꼼꼼히 보게 되더라."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L01_challenge#5','kor',6,1,'u2','L01','g6_1_kor_u2_L01_challenge','lesson_challenge','K6-1-u2-C5',3,'mc','auto','같은 내용이라도 댓글의 말하는 방식이 중요한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X06','K6-1-u2-X07','K6-1-u2-X08']::text[],false,'{"seq":5,"concept":"K6-1-u2-C5","difficulty":3,"kind":"mc","stem":"같은 내용이라도 댓글의 말하는 방식이 중요한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"말하는 방식에 따라 글쓴이가 다시 고쳐 쓰고 싶어질 수도, 쓰기 싫어질 수도 있기 때문에","correct":true},{"t":"고칠 곳은 많이 늘어놓을수록 도움이 되기 때문에","mis":"K6-1-u2-X06"},{"t":"칭찬만 하면 글쓴이가 기뻐하기 때문에","mis":"K6-1-u2-X07"},{"t":"까닭은 말하지 않아도 글쓴이가 알기 때문에","mis":"K6-1-u2-X08"}],"explanation":["고칠 곳만 늘어놓으면 위축돼요.","막연한 칭찬은 도움이 적어요.","방식에 따라 다시 쓰고 싶은 마음이 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L01_challenge#6','kor',6,1,'u2','L01','g6_1_kor_u2_L01_challenge','lesson_challenge','K6-1-u2-C6',3,'match','auto','온라인에 글을 올릴 때의 일과 알맞은 것을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-1-u2-C6","difficulty":3,"kind":"match","stem":"온라인에 글을 올릴 때의 일과 알맞은 것을 이으세요.","pairs":[{"l":"여러 사람이 읽고 의견을 준다","r":"좋은 점"},{"l":"한 번 올린 글은 널리 퍼진다","r":"주의할 점"},{"l":"자료를 옮길 때 출처를 밝힌다","r":"지킬 것"}],"mis":"K6-1-u2-X09","explanation":["의견을 받을 수 있는 것은 좋은 점이에요.","널리 퍼지는 것은 주의할 점이에요.","출처를 밝히는 것은 지킬 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L01_challenge#7','kor',6,1,'u2','L01','g6_1_kor_u2_L01_challenge','lesson_challenge','K6-1-u2-C7',3,'mc','auto','세 군데만 고쳤는데 「이 정도로는 소용없어.」라고 말하는 친구에게 알맞은 생각은 어느 것인가요?',ARRAY['K6-1-u2-X02','K6-1-u2-X01','K6-1-u2-X10']::text[],false,'{"seq":7,"concept":"K6-1-u2-C7","difficulty":3,"kind":"mc","stem":"세 군데만 고쳤는데 「이 정도로는 소용없어.」라고 말하는 친구에게 알맞은 생각은 어느 것인가요?","options":[{"t":"한 군데를 고쳤으면 그만큼 나아진 것이다","correct":true},{"t":"완벽하게 고치지 않으면 고친 것이 아니다","mis":"K6-1-u2-X02"},{"t":"다 지우고 처음부터 다시 써야 한다","mis":"K6-1-u2-X01"},{"t":"고칠 곳이 있으면 글을 올리지 않는다","mis":"K6-1-u2-X10"}],"explanation":["완벽한 글을 만드는 일이 아니에요.","작게 고친 것도 잘 고친 것이에요.","고친 만큼 글이 나아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L01_challenge#8','kor',6,1,'u2','L01','g6_1_kor_u2_L01_challenge','lesson_challenge','K6-1-u2-C2',4,'mc','auto','「사물함을 정리하면 좋은 점」을 고칠 계획으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X01','K6-1-u2-X03','K6-1-u2-X15']::text[],false,'{"seq":8,"concept":"K6-1-u2-C2","difficulty":4,"kind":"mc","stem":"「사물함을 정리하면 좋은 점」을 고칠 계획으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"급식실 문장은 빼고, 마지막 문장은 「정리합시다」로 바꾸어 말투를 맞춘다","correct":true},{"t":"글 전체를 지우고 다른 주제로 새로 쓴다","mis":"K6-1-u2-X01"},{"t":"급식실 문장을 맨 앞으로 옮긴다","mis":"K6-1-u2-X03"},{"t":"모든 문장을 「~한다」로 바꾸고 급식실 문장도 그대로 둔다","mis":"K6-1-u2-X15"}],"explanation":["필요한 곳만 손봐요.","벗어난 문장은 옮기지 않고 빼요.","어색한 말투는 바꾸어 맞춰요."],"asset":{"type":"passage","lines":["사물함이 어지러우면 필요한 물건을 찾는 데 시간이 오래 걸립니다.","수업이 시작되었는데도 교과서를 못 찾아 허둥대기 쉽습니다.","종이류를 한곳에 모아 두면 구겨지는 일도 줄어듭니다.","우리 학교 급식실은 이번 달에 새로 바뀌었습니다.","사물함을 자주 비우면 잃어버린 물건도 빨리 찾습니다.","그러므로 일주일에 한 번은 사물함을 정리한다."],"title":"설명 글 「사물함을 정리하면 좋은 점」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L01_challenge#9','kor',6,1,'u2','L01','g6_1_kor_u2_L01_challenge','lesson_challenge','K6-1-u2-C1',4,'essay','teacher','「고쳐쓰기」가 무엇인지 내 말로 설명하고, 고쳐쓰기가 「다시 쓰기」와 어떻게 다른지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u2-C1","difficulty":4,"kind":"essay","stem":"「고쳐쓰기」가 무엇인지 내 말로 설명하고, 고쳐쓰기가 「다시 쓰기」와 어떻게 다른지 쓰세요.","answer_guide":{"answer":"예: 고쳐쓰기는 쓴 글을 다시 읽고 점검해서 하고 싶은 말이 더 잘 전해지도록 필요한 곳만 손보는 일이다. 주제에서 벗어난 것은 빼고, 부족한 것은 더하고, 어색한 표현은 바꾸고, 뒤엉킨 순서는 옮긴다. 다시 쓰기는 처음 쓴 글을 버리고 처음부터 새로 쓰는 것이지만 고쳐쓰기는 처음 쓴 글을 살리면서 고칠 곳만 손본다는 점이 다르다.","scoring_points":["고쳐쓰기를 점검해 필요한 곳만 손보는 일로 설명했는가","빼기 · 더하기 · 바꾸기 · 옮기기 가운데 한 가지 이상을 들었는가","다시 쓰기와의 차이를 썼는가"]},"explanation":["점검하고 손보는 일이에요.","네 가지 손질을 떠올려요.","처음 쓴 글을 살린다는 점이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L01_challenge#10','kor',6,1,'u2','L01','g6_1_kor_u2_L01_challenge','lesson_challenge','K6-1-u2-C5',4,'essay','teacher','친구가 쓴 글에 고칠 곳이 보였어요. 친구가 다시 고쳐 쓰고 싶어지도록 댓글을 쓰고, 왜 그렇게 썼는지 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u2-C5","difficulty":4,"kind":"essay","stem":"친구가 쓴 글에 고칠 곳이 보였어요. 친구가 다시 고쳐 쓰고 싶어지도록 댓글을 쓰고, 왜 그렇게 썼는지 까닭을 쓰세요.","answer_guide":{"answer":"예: 댓글 — 「사물함이 어지러울 때 생기는 일을 예로 들어서 바로 이해가 됐어. 급식실이 바뀌었다는 문장은 사물함 이야기와 멀어 보여서 빼면 더 좋겠어.」 까닭 — 잘한 곳을 먼저 말해야 글쓴이가 위축되지 않고, 고칠 곳은 까닭을 함께 말해야 어디를 왜 고칠지 알 수 있기 때문이다.","scoring_points":["잘한 곳을 먼저 말했는가","고칠 곳을 까닭과 함께 말했는가","그렇게 쓴 까닭을 썼는가"]},"explanation":["잘한 곳부터 짚어요.","고칠 곳은 까닭과 함께 말해요.","글쓴이의 마음을 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L02_basic#1','kor',6,1,'u2','L02','g6_1_kor_u2_L02_basic','lesson_basic','K6-1-u2-C8',1,'mc','auto','해준의 감상문에 어울리는 제목으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X11','K6-1-u2-X15']::text[],false,'{"seq":1,"concept":"K6-1-u2-C8","difficulty":1,"kind":"mc","stem":"해준의 감상문에 어울리는 제목으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"무너져도 다시 손을 대는 힘","correct":true},{"t":"바닷가 여름 풍경 소개","mis":"K6-1-u2-X11"},{"t":"모래를 좋아하는 우리 집 강아지","mis":"K6-1-u2-X15"},{"t":"모래성 이야기 줄거리","mis":"K6-1-u2-X11"}],"explanation":["라 문단에서 새로 생각하게 된 것을 봐요.","줄거리나 풍경만 알리는 제목은 부족해요.","글쓴이가 느낀 것이 드러나야 해요."],"asset":{"type":"passage","lines":["가 가장 마음에 남은 곳은 마지막 장면이다. 큰 파도에 성이 무너뜨렸는데도","미르는 울지 않고 젖은 모래를 다시 끌어모은다. 나는 그 장면에서 전혀 지루했다.","나 미르는 여름 내내 쌓았다. 저녁마다 파도가 성을 지웠지만 다음 날 다시 시작했다.","새봄과 함께 물길을 파서 성을 사흘 동안 지켜 내기도 한다. 우리 집 강아지도 모래를 좋아한다.","다 선생님이 이 영화를 우리 반에 소개했다. 제목만 보고는 바다 풍경만 나오는","줄 알았는데, 무엇을 다시 시작하는 사람의 이야기였다.","라 나는 실패한 일을 다시 붙잡는 일이 어렵다고 생각해 왔다. 이 영화를 보고","다시 손을 대는 것도 하나의 힘이라고 생각하게 되었다. 나도 미르처럼 되고 싶다."],"title":"해준이 쓴 감상문 「모래성 이야기」 (가~라는 문단)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L02_basic#2','kor',6,1,'u2','L02','g6_1_kor_u2_L02_basic','lesson_basic','K6-1-u2-C11',1,'mc','auto','문단에서 하고 싶은 말을 담은 문장을 무엇이라고 하나요?',ARRAY['K6-1-u2-X14','K6-1-u2-X11']::text[],false,'{"seq":2,"concept":"K6-1-u2-C11","difficulty":1,"kind":"mc","stem":"문단에서 하고 싶은 말을 담은 문장을 무엇이라고 하나요?","options":[{"t":"중심 문장","correct":true},{"t":"뒷받침 문장","mis":"K6-1-u2-X14"},{"t":"제목","mis":"K6-1-u2-X11"},{"t":"끝 문장","mis":"K6-1-u2-X14"}],"explanation":["문단에는 하고 싶은 말이 있어요.","그 말을 담은 문장이 중심 문장이에요.","뒷받침 문장은 그것을 자세히 설명해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L02_basic#3','kor',6,1,'u2','L02','g6_1_kor_u2_L02_basic','lesson_basic','K6-1-u2-C15',1,'mc','auto','해준의 감상문 나 문단에서 빼야 할 문장은 어느 것인가요?',ARRAY['K6-1-u2-X15','K6-1-u2-X16']::text[],false,'{"seq":3,"concept":"K6-1-u2-C15","difficulty":1,"kind":"mc","stem":"해준의 감상문 나 문단에서 빼야 할 문장은 어느 것인가요?","options":[{"t":"우리 집 강아지도 모래를 좋아한다.","correct":true},{"t":"저녁마다 파도가 성을 지웠다.","mis":"K6-1-u2-X15"},{"t":"새봄과 함께 물길을 파서 성을 사흘 동안 지켜 내기도 한다.","mis":"K6-1-u2-X15"},{"t":"미르는 여름 내내 쌓았다.","mis":"K6-1-u2-X16"}],"explanation":["나 문단의 중심은 미르가 모래성을 쌓은 일이에요.","강아지 이야기는 상관이 없어요.","「여름 내내 쌓았다」는 지우지 말고 고쳐요."],"asset":{"type":"passage","lines":["가 가장 마음에 남은 곳은 마지막 장면이다. 큰 파도에 성이 무너뜨렸는데도","미르는 울지 않고 젖은 모래를 다시 끌어모은다. 나는 그 장면에서 전혀 지루했다.","나 미르는 여름 내내 쌓았다. 저녁마다 파도가 성을 지웠지만 다음 날 다시 시작했다.","새봄과 함께 물길을 파서 성을 사흘 동안 지켜 내기도 한다. 우리 집 강아지도 모래를 좋아한다.","다 선생님이 이 영화를 우리 반에 소개했다. 제목만 보고는 바다 풍경만 나오는","줄 알았는데, 무엇을 다시 시작하는 사람의 이야기였다.","라 나는 실패한 일을 다시 붙잡는 일이 어렵다고 생각해 왔다. 이 영화를 보고","다시 손을 대는 것도 하나의 힘이라고 생각하게 되었다. 나도 미르처럼 되고 싶다."],"title":"해준이 쓴 감상문 「모래성 이야기」 (가~라는 문단)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L02_basic#4','kor',6,1,'u2','L02','g6_1_kor_u2_L02_basic','lesson_basic','K6-1-u2-C13',1,'match','auto','문장 성분과 그 물음을 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K6-1-u2-C13","difficulty":1,"kind":"match","stem":"문장 성분과 그 물음을 이으세요.","pairs":[{"l":"주어","r":"무엇이 · 누가"},{"l":"목적어","r":"무엇을 · 누구를"},{"l":"서술어","r":"어찌하다 · 어떠하다"}],"mis":"K6-1-u2-X17","explanation":["주어는 누가 · 무엇이에요.","목적어는 무엇을 · 누구를이에요.","서술어는 어찌하다 · 어떠하다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L02_basic#5','kor',6,1,'u2','L02','g6_1_kor_u2_L02_basic','lesson_basic','K6-1-u2-C9',2,'match','auto','해준의 감상문 문단이 놓일 차례를 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-1-u2-C9","difficulty":2,"kind":"match","stem":"해준의 감상문 문단이 놓일 차례를 이으세요.","pairs":[{"l":"다 — 영화를 보게 된 동기와 첫인상","r":"처음"},{"l":"가 — 인상 깊은 장면","r":"가운데"},{"l":"라 — 느낀 점과 다짐","r":"끝"}],"mis":"K6-1-u2-X12","explanation":["보게 된 동기는 처음에 와요.","인상 깊은 장면은 가운데에 와요.","다짐은 끝에 와요."],"asset":{"type":"passage","lines":["가 가장 마음에 남은 곳은 마지막 장면이다. 큰 파도에 성이 무너뜨렸는데도","미르는 울지 않고 젖은 모래를 다시 끌어모은다. 나는 그 장면에서 전혀 지루했다.","나 미르는 여름 내내 쌓았다. 저녁마다 파도가 성을 지웠지만 다음 날 다시 시작했다.","새봄과 함께 물길을 파서 성을 사흘 동안 지켜 내기도 한다. 우리 집 강아지도 모래를 좋아한다.","다 선생님이 이 영화를 우리 반에 소개했다. 제목만 보고는 바다 풍경만 나오는","줄 알았는데, 무엇을 다시 시작하는 사람의 이야기였다.","라 나는 실패한 일을 다시 붙잡는 일이 어렵다고 생각해 왔다. 이 영화를 보고","다시 손을 대는 것도 하나의 힘이라고 생각하게 되었다. 나도 미르처럼 되고 싶다."],"title":"해준이 쓴 감상문 「모래성 이야기」 (가~라는 문단)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L02_basic#6','kor',6,1,'u2','L02','g6_1_kor_u2_L02_basic','lesson_basic','K6-1-u2-C14',2,'mc','auto','「선생님이 이 영화를 우리 반에 소개했다.」를 바르게 고친 것은 어느 것인가요?',ARRAY['K6-1-u2-X20','K6-1-u2-X17','K6-1-u2-X19']::text[],false,'{"seq":6,"concept":"K6-1-u2-C14","difficulty":2,"kind":"mc","stem":"「선생님이 이 영화를 우리 반에 소개했다.」를 바르게 고친 것은 어느 것인가요?","options":[{"t":"선생님께서 이 영화를 우리 반에 소개해 주셨다.","correct":true},{"t":"선생님이 이 영화를 우리 반에 소개한다.","mis":"K6-1-u2-X20"},{"t":"선생님을 이 영화가 우리 반에 소개했다.","mis":"K6-1-u2-X17"},{"t":"선생님이 이 영화를 우리 반에 소개될 것이다.","mis":"K6-1-u2-X19"}],"explanation":["선생님은 웃어른이에요.","높임 표현으로 받아야 해요.","께서 · ~시다로 고쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L02_basic#7','kor',6,1,'u2','L02','g6_1_kor_u2_L02_basic','lesson_basic','K6-1-u2-C14',2,'mc','auto','「큰 파도에 성이 무너뜨렸는데도」에서 어긋난 것은 무엇인가요?',ARRAY['K6-1-u2-X17','K6-1-u2-X18','K6-1-u2-X20']::text[],false,'{"seq":7,"concept":"K6-1-u2-C14","difficulty":2,"kind":"mc","stem":"「큰 파도에 성이 무너뜨렸는데도」에서 어긋난 것은 무엇인가요?","options":[{"t":"성이 스스로 한 일이 아니므로 「무너졌는데도」로 써야 한다","correct":true},{"t":"「큰 파도에」를 빼야 한다","mis":"K6-1-u2-X17"},{"t":"높임 표현을 써야 한다","mis":"K6-1-u2-X18"},{"t":"시간을 나타내는 말이 없다","mis":"K6-1-u2-X20"}],"explanation":["성은 파도 때문에 무너졌어요.","스스로 무너뜨린 것이 아니에요.","「무너졌는데도」로 고쳐요."],"asset":{"type":"passage","lines":["가 가장 마음에 남은 곳은 마지막 장면이다. 큰 파도에 성이 무너뜨렸는데도","미르는 울지 않고 젖은 모래를 다시 끌어모은다. 나는 그 장면에서 전혀 지루했다.","나 미르는 여름 내내 쌓았다. 저녁마다 파도가 성을 지웠지만 다음 날 다시 시작했다.","새봄과 함께 물길을 파서 성을 사흘 동안 지켜 내기도 한다. 우리 집 강아지도 모래를 좋아한다.","다 선생님이 이 영화를 우리 반에 소개했다. 제목만 보고는 바다 풍경만 나오는","줄 알았는데, 무엇을 다시 시작하는 사람의 이야기였다.","라 나는 실패한 일을 다시 붙잡는 일이 어렵다고 생각해 왔다. 이 영화를 보고","다시 손을 대는 것도 하나의 힘이라고 생각하게 되었다. 나도 미르처럼 되고 싶다."],"title":"해준이 쓴 감상문 「모래성 이야기」 (가~라는 문단)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L02_basic#8','kor',6,1,'u2','L02','g6_1_kor_u2_L02_basic','lesson_basic','K6-1-u2-C13',2,'ox','auto','내용이 좋으면 문장 성분의 호응이 조금 어긋나도 뜻은 제대로 전해져요.',ARRAY['K6-1-u2-X17']::text[],false,'{"seq":8,"concept":"K6-1-u2-C13","difficulty":2,"kind":"ox","stem":"내용이 좋으면 문장 성분의 호응이 조금 어긋나도 뜻은 제대로 전해져요.","answer":"X","reason_options":[{"t":"호응이 어긋나면 읽는 사람이 뜻을 제대로 알기 어렵기 때문에","correct":true},{"t":"내용이 형식보다 언제나 중요하기 때문에","mis":"K6-1-u2-X17"}],"mis":"K6-1-u2-X17","explanation":["호응은 형식의 문제예요.","형식이 어긋나면 뜻도 흐려져요.","내용과 형식을 함께 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L02_basic#9','kor',6,1,'u2','L02','g6_1_kor_u2_L02_basic','lesson_basic','K6-1-u2-C10',2,'ox','auto','세아와 민석이가 말한 중심 내용이 서로 다르면 둘 가운데 하나는 틀린 답이에요.',ARRAY['K6-1-u2-X13']::text[],false,'{"seq":9,"concept":"K6-1-u2-C10","difficulty":2,"kind":"ox","stem":"세아와 민석이가 말한 중심 내용이 서로 다르면 둘 가운데 하나는 틀린 답이에요.","answer":"X","reason_options":[{"t":"두 답 모두 글에서 근거를 댈 수 있으면 둘 다 좋은 답이기 때문에","correct":true},{"t":"중심 내용은 언제나 하나뿐이기 때문에","mis":"K6-1-u2-X13"}],"mis":"K6-1-u2-X13","explanation":["세아는 마지막 문단에서 근거를 찾았어요.","민석이는 사흘을 버틴 장면에서 찾았어요.","근거가 있으면 둘 다 좋은 답이에요."],"asset":{"type":"speech","turns":[{"who":"세아","text":"이 글의 중심 내용은 「다시 시작하는 힘」이라고 봤어. 마지막 문단에 그렇게 적혀 있잖아."},{"who":"민석","text":"나는 「함께하면 더 오래 버틴다」로 봤어. 새봄과 물길을 판 뒤에 사흘을 버텼다고 나오니까."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L02_basic#10','kor',6,1,'u2','L02','g6_1_kor_u2_L02_basic','lesson_basic','K6-1-u2-C14',3,'mc','auto','「나는 그 장면에서 전혀 지루했다.」를 바르게 고친 것은 어느 것인가요?',ARRAY['K6-1-u2-X20','K6-1-u2-X21','K6-1-u2-X34']::text[],false,'{"seq":10,"concept":"K6-1-u2-C14","difficulty":3,"kind":"mc","stem":"「나는 그 장면에서 전혀 지루했다.」를 바르게 고친 것은 어느 것인가요?","options":[{"t":"나는 그 장면에서 전혀 지루하지 않았다.","correct":true},{"t":"나는 그 장면에서 전혀 지루할 것이다.","mis":"K6-1-u2-X20"},{"t":"나는 그 장면에서 전혀 재미있었다.","mis":"K6-1-u2-X21"},{"t":"그 장면에서 전혀 지루했다.","mis":"K6-1-u2-X34"}],"explanation":["「전혀」 뒤에는 부정하는 말이 와요.","때나 낱말만 바꾸어도 어긋남은 그대로예요.","「지루하지 않았다」로 고쳐요."],"asset":{"type":"passage","lines":["가 가장 마음에 남은 곳은 마지막 장면이다. 큰 파도에 성이 무너뜨렸는데도","미르는 울지 않고 젖은 모래를 다시 끌어모은다. 나는 그 장면에서 전혀 지루했다.","나 미르는 여름 내내 쌓았다. 저녁마다 파도가 성을 지웠지만 다음 날 다시 시작했다.","새봄과 함께 물길을 파서 성을 사흘 동안 지켜 내기도 한다. 우리 집 강아지도 모래를 좋아한다.","다 선생님이 이 영화를 우리 반에 소개했다. 제목만 보고는 바다 풍경만 나오는","줄 알았는데, 무엇을 다시 시작하는 사람의 이야기였다.","라 나는 실패한 일을 다시 붙잡는 일이 어렵다고 생각해 왔다. 이 영화를 보고","다시 손을 대는 것도 하나의 힘이라고 생각하게 되었다. 나도 미르처럼 되고 싶다."],"title":"해준이 쓴 감상문 「모래성 이야기」 (가~라는 문단)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L02_challenge#1','kor',6,1,'u2','L02','g6_1_kor_u2_L02_challenge','lesson_challenge','K6-1-u2-C4',2,'mc','auto','해준의 감상문에서 「문단의 차례가 뒤엉켰다」는 문제는 어느 수준에서 찾을 수 있나요?',ARRAY['K6-1-u2-X04','K6-1-u2-X05']::text[],false,'{"seq":1,"concept":"K6-1-u2-C4","difficulty":2,"kind":"mc","stem":"해준의 감상문에서 「문단의 차례가 뒤엉켰다」는 문제는 어느 수준에서 찾을 수 있나요?","options":[{"t":"글 수준","correct":true},{"t":"문장 수준","mis":"K6-1-u2-X04"},{"t":"띄어쓰기 수준","mis":"K6-1-u2-X05"},{"t":"낱말 수준","mis":"K6-1-u2-X04"}],"explanation":["차례는 글 전체를 봐야 보여요.","한 문장만 봐서는 알 수 없어요.","글 수준의 문제예요."],"asset":{"type":"passage","lines":["가 가장 마음에 남은 곳은 마지막 장면이다. 큰 파도에 성이 무너뜨렸는데도","미르는 울지 않고 젖은 모래를 다시 끌어모은다. 나는 그 장면에서 전혀 지루했다.","나 미르는 여름 내내 쌓았다. 저녁마다 파도가 성을 지웠지만 다음 날 다시 시작했다.","새봄과 함께 물길을 파서 성을 사흘 동안 지켜 내기도 한다. 우리 집 강아지도 모래를 좋아한다.","다 선생님이 이 영화를 우리 반에 소개했다. 제목만 보고는 바다 풍경만 나오는","줄 알았는데, 무엇을 다시 시작하는 사람의 이야기였다.","라 나는 실패한 일을 다시 붙잡는 일이 어렵다고 생각해 왔다. 이 영화를 보고","다시 손을 대는 것도 하나의 힘이라고 생각하게 되었다. 나도 미르처럼 되고 싶다."],"title":"해준이 쓴 감상문 「모래성 이야기」 (가~라는 문단)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L02_challenge#2','kor',6,1,'u2','L02','g6_1_kor_u2_L02_challenge','lesson_challenge','K6-1-u2-C12',2,'mc','auto','「미르는 여름 내내 쌓았다.」는 어떻게 하는 것이 알맞은가요?',ARRAY['K6-1-u2-X16','K6-1-u2-X03','K6-1-u2-X34']::text[],false,'{"seq":2,"concept":"K6-1-u2-C12","difficulty":2,"kind":"mc","stem":"「미르는 여름 내내 쌓았다.」는 어떻게 하는 것이 알맞은가요?","options":[{"t":"「미르는 여름 내내 모래성을 쌓았다.」로 고쳐 쓴다","correct":true},{"t":"중심 문장과 상관없으니 지운다","mis":"K6-1-u2-X16"},{"t":"문단 맨 끝으로 옮긴다","mis":"K6-1-u2-X03"},{"t":"그대로 둔다","mis":"K6-1-u2-X34"}],"explanation":["미르가 모래성을 쌓은 일은 중심과 관련이 있어요.","무엇을 쌓았는지가 빠졌어요.","지우지 말고 고쳐 써요."],"asset":{"type":"passage","lines":["가 가장 마음에 남은 곳은 마지막 장면이다. 큰 파도에 성이 무너뜨렸는데도","미르는 울지 않고 젖은 모래를 다시 끌어모은다. 나는 그 장면에서 전혀 지루했다.","나 미르는 여름 내내 쌓았다. 저녁마다 파도가 성을 지웠지만 다음 날 다시 시작했다.","새봄과 함께 물길을 파서 성을 사흘 동안 지켜 내기도 한다. 우리 집 강아지도 모래를 좋아한다.","다 선생님이 이 영화를 우리 반에 소개했다. 제목만 보고는 바다 풍경만 나오는","줄 알았는데, 무엇을 다시 시작하는 사람의 이야기였다.","라 나는 실패한 일을 다시 붙잡는 일이 어렵다고 생각해 왔다. 이 영화를 보고","다시 손을 대는 것도 하나의 힘이라고 생각하게 되었다. 나도 미르처럼 되고 싶다."],"title":"해준이 쓴 감상문 「모래성 이야기」 (가~라는 문단)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L02_challenge#3','kor',6,1,'u2','L02','g6_1_kor_u2_L02_challenge','lesson_challenge','K6-1-u2-C10',3,'error','auto','해준의 감상문 중심 내용을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u2-X13']::text[],false,'{"seq":3,"concept":"K6-1-u2-C10","difficulty":3,"kind":"error","stem":"해준의 감상문 중심 내용을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"도하 — 「민석이 답은 틀렸어. 중심 내용은 세아가 말한 것 하나뿐이야.」","correct":true,"mis_target":"K6-1-u2-X13"},{"t":"은채 — 「세아는 마지막 문단을 근거로 들었어.」","mis":"K6-1-u2-X13"},{"t":"라온 — 「민석이도 사흘을 버텼다는 부분을 근거로 들었어.」","mis":"K6-1-u2-X13"}],"explanation":["은채와 라온은 근거를 짚었어요.","두 답 모두 근거가 있어요.","도하는 정답이 하나뿐이라고 여겼어요."],"asset":{"type":"speech","turns":[{"who":"세아","text":"이 글의 중심 내용은 「다시 시작하는 힘」이라고 봤어. 마지막 문단에 그렇게 적혀 있잖아."},{"who":"민석","text":"나는 「함께하면 더 오래 버틴다」로 봤어. 새봄과 물길을 판 뒤에 사흘을 버텼다고 나오니까."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L02_challenge#4','kor',6,1,'u2','L02','g6_1_kor_u2_L02_challenge','lesson_challenge','K6-1-u2-C11',3,'mc','auto','나 문단의 중심 문장으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X15','K6-1-u2-X14']::text[],false,'{"seq":4,"concept":"K6-1-u2-C11","difficulty":3,"kind":"mc","stem":"나 문단의 중심 문장으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"미르는 여름 내내 모래성을 쌓았다.","correct":true},{"t":"우리 집 강아지도 모래를 좋아한다.","mis":"K6-1-u2-X15"},{"t":"저녁마다 파도가 성을 지웠다.","mis":"K6-1-u2-X14"},{"t":"새봄과 함께 물길을 팠다.","mis":"K6-1-u2-X14"}],"explanation":["파도 · 물길 이야기는 자세히 설명하는 문장이에요.","강아지는 상관없는 문장이에요.","하고 싶은 말은 여름 내내 쌓은 일이에요."],"asset":{"type":"passage","lines":["가 가장 마음에 남은 곳은 마지막 장면이다. 큰 파도에 성이 무너뜨렸는데도","미르는 울지 않고 젖은 모래를 다시 끌어모은다. 나는 그 장면에서 전혀 지루했다.","나 미르는 여름 내내 쌓았다. 저녁마다 파도가 성을 지웠지만 다음 날 다시 시작했다.","새봄과 함께 물길을 파서 성을 사흘 동안 지켜 내기도 한다. 우리 집 강아지도 모래를 좋아한다.","다 선생님이 이 영화를 우리 반에 소개했다. 제목만 보고는 바다 풍경만 나오는","줄 알았는데, 무엇을 다시 시작하는 사람의 이야기였다.","라 나는 실패한 일을 다시 붙잡는 일이 어렵다고 생각해 왔다. 이 영화를 보고","다시 손을 대는 것도 하나의 힘이라고 생각하게 되었다. 나도 미르처럼 되고 싶다."],"title":"해준이 쓴 감상문 「모래성 이야기」 (가~라는 문단)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L02_challenge#5','kor',6,1,'u2','L02','g6_1_kor_u2_L02_challenge','lesson_challenge','K6-1-u2-C14',3,'match','auto','호응이 어긋난 문장과 어긋난 갈래를 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-1-u2-C14","difficulty":3,"kind":"match","stem":"호응이 어긋난 문장과 어긋난 갈래를 이으세요.","pairs":[{"l":"선생님이 소개했다","r":"높임"},{"l":"나는 어제 이 영화를 볼 것이다","r":"시제"},{"l":"나는 전혀 지루했다","r":"부정"}],"mis":"K6-1-u2-X04","explanation":["웃어른에게는 높임이에요.","어제에는 지난 때 서술어예요.","전혀 뒤에는 부정하는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L02_challenge#6','kor',6,1,'u2','L02','g6_1_kor_u2_L02_challenge','lesson_challenge','K6-1-u2-C15',3,'ox','auto','글 수준을 다 고친 뒤에만 문단을 보고, 문단을 다 고친 뒤에만 문장을 봐야 해요.',ARRAY['K6-1-u2-X22']::text[],false,'{"seq":6,"concept":"K6-1-u2-C15","difficulty":3,"kind":"ox","stem":"글 수준을 다 고친 뒤에만 문단을 보고, 문단을 다 고친 뒤에만 문장을 봐야 해요.","answer":"X","reason_options":[{"t":"어느 수준에서 발견하든 그때그때 함께 고치는 것이기 때문에","correct":true},{"t":"세 수준은 꼭 세 번 나누어 해야 하기 때문에","mis":"K6-1-u2-X22"}],"mis":"K6-1-u2-X22","explanation":["큰 것부터 보는 것은 맞아요.","하지만 따로 도는 절차는 아니에요.","보이는 그때그때 함께 고쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L02_challenge#7','kor',6,1,'u2','L02','g6_1_kor_u2_L02_challenge','lesson_challenge','K6-1-u2-C15',3,'match','auto','고칠 때 쓰는 부호와 쓰임을 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-1-u2-C15","difficulty":3,"kind":"match","stem":"고칠 때 쓰는 부호와 쓰임을 이으세요.","pairs":[{"l":"∨","r":"띄어 쓸 때"},{"l":"⌒","r":"붙여 쓸 때"},{"l":"⊂","r":"내용을 더 넣을 때"}],"mis":"K6-1-u2-X23","explanation":["∨ 는 띄울 곳에 써요.","⌒ 는 붙일 곳에 써요.","⊂ 는 내용을 더 넣을 곳에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L02_challenge#8','kor',6,1,'u2','L02','g6_1_kor_u2_L02_challenge','lesson_challenge','K6-1-u2-C3',4,'mc','auto','해준의 감상문을 고칠 때 가장 알맞은 계획은 어느 것인가요?',ARRAY['K6-1-u2-X05','K6-1-u2-X01','K6-1-u2-X03']::text[],false,'{"seq":8,"concept":"K6-1-u2-C3","difficulty":4,"kind":"mc","stem":"해준의 감상문을 고칠 때 가장 알맞은 계획은 어느 것인가요?","options":[{"t":"제목과 문단 차례를 먼저 고치고, 나 문단의 강아지 문장을 뺀 뒤, 호응이 어긋난 문장을 고친다","correct":true},{"t":"호응이 어긋난 문장부터 고치고 차례와 제목은 그대로 둔다","mis":"K6-1-u2-X05"},{"t":"강아지 문장을 뺀 뒤 처음부터 다시 쓴다","mis":"K6-1-u2-X01"},{"t":"제목만 바꾸면 나머지는 고칠 필요가 없다","mis":"K6-1-u2-X03"}],"explanation":["큰 것부터 잡아요.","다시 쓰지 않아요.","글 → 문단 → 문장을 고르게 살펴요."],"asset":{"type":"passage","lines":["가 가장 마음에 남은 곳은 마지막 장면이다. 큰 파도에 성이 무너뜨렸는데도","미르는 울지 않고 젖은 모래를 다시 끌어모은다. 나는 그 장면에서 전혀 지루했다.","나 미르는 여름 내내 쌓았다. 저녁마다 파도가 성을 지웠지만 다음 날 다시 시작했다.","새봄과 함께 물길을 파서 성을 사흘 동안 지켜 내기도 한다. 우리 집 강아지도 모래를 좋아한다.","다 선생님이 이 영화를 우리 반에 소개했다. 제목만 보고는 바다 풍경만 나오는","줄 알았는데, 무엇을 다시 시작하는 사람의 이야기였다.","라 나는 실패한 일을 다시 붙잡는 일이 어렵다고 생각해 왔다. 이 영화를 보고","다시 손을 대는 것도 하나의 힘이라고 생각하게 되었다. 나도 미르처럼 되고 싶다."],"title":"해준이 쓴 감상문 「모래성 이야기」 (가~라는 문단)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L02_challenge#9','kor',6,1,'u2','L02','g6_1_kor_u2_L02_challenge','lesson_challenge','K6-1-u2-C8',4,'essay','teacher','해준의 감상문 제목 「모래성 이야기」가 왜 알맞지 않은지 쓰고, 새 제목을 지어 그렇게 지은 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u2-C8","difficulty":4,"kind":"essay","stem":"해준의 감상문 제목 「모래성 이야기」가 왜 알맞지 않은지 쓰고, 새 제목을 지어 그렇게 지은 까닭을 쓰세요.","answer_guide":{"answer":"예: 「모래성 이야기」는 무엇을 보았는지만 알려 줄 뿐 해준이 느끼고 생각한 것이 담기지 않았다. 해준이 라 문단에서 다시 손을 대는 것도 하나의 힘이라고 생각하게 되었다고 했으므로, 새 제목은 「무너져도 다시 손을 대는 힘」으로 짓겠다. 글쓴이가 가장 하고 싶었던 말을 제목으로 옮겼기 때문이다.","scoring_points":["줄거리만 알리고 느낀 것이 없다는 점을 썼는가","글의 중심 생각이 드러나는 새 제목을 지었는가","글에서 까닭을 찾아 썼는가"]},"explanation":["제목에 무엇이 빠졌는지 봐요.","라 문단을 다시 읽어요.","하고 싶은 말을 제목으로 옮겨요."],"asset":{"type":"passage","lines":["가 가장 마음에 남은 곳은 마지막 장면이다. 큰 파도에 성이 무너뜨렸는데도","미르는 울지 않고 젖은 모래를 다시 끌어모은다. 나는 그 장면에서 전혀 지루했다.","나 미르는 여름 내내 쌓았다. 저녁마다 파도가 성을 지웠지만 다음 날 다시 시작했다.","새봄과 함께 물길을 파서 성을 사흘 동안 지켜 내기도 한다. 우리 집 강아지도 모래를 좋아한다.","다 선생님이 이 영화를 우리 반에 소개했다. 제목만 보고는 바다 풍경만 나오는","줄 알았는데, 무엇을 다시 시작하는 사람의 이야기였다.","라 나는 실패한 일을 다시 붙잡는 일이 어렵다고 생각해 왔다. 이 영화를 보고","다시 손을 대는 것도 하나의 힘이라고 생각하게 되었다. 나도 미르처럼 되고 싶다."],"title":"해준이 쓴 감상문 「모래성 이야기」 (가~라는 문단)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L02_challenge#10','kor',6,1,'u2','L02','g6_1_kor_u2_L02_challenge','lesson_challenge','K6-1-u2-C14',4,'essay','teacher','해준의 감상문에서 호응이 어긋난 문장 두 개를 찾아 바르게 고치고, 어떤 호응이 어긋났는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u2-C14","difficulty":4,"kind":"essay","stem":"해준의 감상문에서 호응이 어긋난 문장 두 개를 찾아 바르게 고치고, 어떤 호응이 어긋났는지 쓰세요.","answer_guide":{"answer":"예: 「큰 파도에 성이 무너뜨렸는데도」는 성이 스스로 한 일이 아니므로 「성이 무너졌는데도」로 고친다. 피동과 사동이 어긋났다. 「나는 그 장면에서 전혀 지루했다」는 「전혀」 뒤에 부정하는 말이 와야 하므로 「전혀 지루하지 않았다」로 고친다. 부정이 어긋났다. 「선생님이 이 영화를 우리 반에 소개했다」는 「선생님께서 소개해 주셨다」로 고친다. 높임이 어긋났다.","scoring_points":["어긋난 문장 두 개를 바르게 찾았는가","바르게 고쳐 썼는가","어긋난 갈래(높임 · 피동 · 시제 · 부정)를 썼는가"]},"explanation":["서술어를 짚어 앞말과 견주어요.","알맞게 고쳐 써요.","네 가지 갈래 가운데 무엇인지 써요."],"asset":{"type":"passage","lines":["가 가장 마음에 남은 곳은 마지막 장면이다. 큰 파도에 성이 무너뜨렸는데도","미르는 울지 않고 젖은 모래를 다시 끌어모은다. 나는 그 장면에서 전혀 지루했다.","나 미르는 여름 내내 쌓았다. 저녁마다 파도가 성을 지웠지만 다음 날 다시 시작했다.","새봄과 함께 물길을 파서 성을 사흘 동안 지켜 내기도 한다. 우리 집 강아지도 모래를 좋아한다.","다 선생님이 이 영화를 우리 반에 소개했다. 제목만 보고는 바다 풍경만 나오는","줄 알았는데, 무엇을 다시 시작하는 사람의 이야기였다.","라 나는 실패한 일을 다시 붙잡는 일이 어렵다고 생각해 왔다. 이 영화를 보고","다시 손을 대는 것도 하나의 힘이라고 생각하게 되었다. 나도 미르처럼 되고 싶다."],"title":"해준이 쓴 감상문 「모래성 이야기」 (가~라는 문단)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L04_basic#1','kor',6,1,'u2','L04','g6_1_kor_u2_L04_basic','lesson_basic','K6-1-u2-C16',1,'mc','auto','「오늘 밤나무를 심자」는 무슨 뜻인가요?',ARRAY['K6-1-u2-X24']::text[],false,'{"seq":1,"concept":"K6-1-u2-C16","difficulty":1,"kind":"mc","stem":"「오늘 밤나무를 심자」는 무슨 뜻인가요?","options":[{"t":"밤나무라는 나무를 오늘 심자","correct":true},{"t":"오늘 밤에 나무를 심자","mis":"K6-1-u2-X24"},{"t":"오늘 밤에 밤을 줍자","mis":"K6-1-u2-X24"},{"t":"어제 심은 나무를 오늘 뽑자","mis":"K6-1-u2-X24"}],"explanation":["「밤나무」가 붙어 있어요.","붙여 쓴 밤나무는 나무 이름이에요.","오늘 그 나무를 심자는 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L04_basic#2','kor',6,1,'u2','L04','g6_1_kor_u2_L04_basic','lesson_basic','K6-1-u2-C17',1,'mc','auto','세는 말을 바르게 띄어 쓴 것은 어느 것인가요?',ARRAY['K6-1-u2-X25','K6-1-u2-X24']::text[],false,'{"seq":2,"concept":"K6-1-u2-C17","difficulty":1,"kind":"mc","stem":"세는 말을 바르게 띄어 쓴 것은 어느 것인가요?","options":[{"t":"연필 다섯 자루","correct":true},{"t":"연필 다섯자루","mis":"K6-1-u2-X25"},{"t":"연필다섯 자루","mis":"K6-1-u2-X24"},{"t":"연필다섯자루","mis":"K6-1-u2-X25"}],"explanation":["「자루」는 세는 말이에요.","세는 말은 앞의 수와 띄어 써요.","연필 ∨ 다섯 ∨ 자루로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L04_basic#3','kor',6,1,'u2','L04','g6_1_kor_u2_L04_basic','lesson_basic','K6-1-u2-C18',1,'mc','auto','잇는 말을 바르게 띄어 쓴 것은 어느 것인가요?',ARRAY['K6-1-u2-X26']::text[],false,'{"seq":3,"concept":"K6-1-u2-C18","difficulty":1,"kind":"mc","stem":"잇는 말을 바르게 띄어 쓴 것은 어느 것인가요?","options":[{"t":"학생 및 학부모","correct":true},{"t":"학생및학부모","mis":"K6-1-u2-X26"},{"t":"학생 및학부모","mis":"K6-1-u2-X26"},{"t":"학생및 학부모","mis":"K6-1-u2-X26"}],"explanation":["「및」은 두 말을 잇는 말이에요.","잇는 말은 앞뒤를 모두 띄어요.","학생 ∨ 및 ∨ 학부모로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L04_basic#4','kor',6,1,'u2','L04','g6_1_kor_u2_L04_basic','lesson_basic','K6-1-u2-C19',1,'ox','auto','「나무처럼」의 「처럼」은 앞말에 붙여 써요.',ARRAY['K6-1-u2-X27']::text[],false,'{"seq":4,"concept":"K6-1-u2-C19","difficulty":1,"kind":"ox","stem":"「나무처럼」의 「처럼」은 앞말에 붙여 써요.","answer":"O","reason_options":[{"t":"「처럼」은 앞말에 얹혀 가는 조사이기 때문에","correct":true},{"t":"「처럼」은 따로 뜻을 가진 낱말이기 때문에","mis":"K6-1-u2-X27"}],"mis":"K6-1-u2-X27","explanation":["조사는 혼자 쓰이지 않아요.","앞말에 얹혀 가요.","「나무처럼」으로 붙여 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L04_basic#5','kor',6,1,'u2','L04','g6_1_kor_u2_L04_basic','lesson_basic','K6-1-u2-C18',2,'match','auto','붙여 쓴 말을 바르게 고친 것과 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-1-u2-C18","difficulty":2,"kind":"match","stem":"붙여 쓴 말을 바르게 고친 것과 이으세요.","pairs":[{"l":"청군대백군","r":"청군 대 백군"},{"l":"서점겸찻집","r":"서점 겸 찻집"},{"l":"교실및복도","r":"교실 및 복도"}],"mis":"K6-1-u2-X26","explanation":["대 · 겸 · 및은 잇는 말이에요.","잇는 말 앞뒤를 띄워요.","한 칸씩 띄우면 읽기 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L04_basic#6','kor',6,1,'u2','L04','g6_1_kor_u2_L04_basic','lesson_basic','K6-1-u2-C19',2,'mc','auto','「바꿀수있게」를 바르게 띄어 쓴 것은 어느 것인가요?',ARRAY['K6-1-u2-X28','K6-1-u2-X24']::text[],false,'{"seq":6,"concept":"K6-1-u2-C19","difficulty":2,"kind":"mc","stem":"「바꿀수있게」를 바르게 띄어 쓴 것은 어느 것인가요?","options":[{"t":"바꿀 수 있게","correct":true},{"t":"바꿀수 있게","mis":"K6-1-u2-X28"},{"t":"바꿀 수있게","mis":"K6-1-u2-X28"},{"t":"바 꿀 수 있 게","mis":"K6-1-u2-X24"}],"explanation":["「수」는 홀로 못 쓰는 이름씨예요.","홀로 못 쓰는 이름씨는 띄어 써요.","「있게」도 띄어 써요."],"asset":{"type":"passage","lines":["우리 반은 달마다 청소 당번을 새로 정합니다. 지난달에는 한줄로 앉은","차례대로 정했는데 창가 쪽만 힘든 곳을 맡아 불만이 나왔습니다.","그래서 이번에는 제비뽑기로 정하기로 했습니다.","먼저 종이 스물네장을 접어 상자에 넣었습니다.","청소 구역은 교실 및복도, 그리고 계단이었습니다.","뽑고 나서 서로 바꾸고 싶은 사람은 바꿀수있게 했습니다.","힘든 구역을 뽑은 친구에게는 다음 달에 먼저 고를 기회를 주기로 했습니다."],"title":"글 「청소 당번을 정하는 날」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L04_basic#7','kor',6,1,'u2','L04','g6_1_kor_u2_L04_basic','lesson_basic','K6-1-u2-C17',2,'mc','auto','「청소 당번을 정하는 날」에서 띄어쓰기가 잘못된 곳은 어느 것인가요?',ARRAY['K6-1-u2-X25','K6-1-u2-X27']::text[],false,'{"seq":7,"concept":"K6-1-u2-C17","difficulty":2,"kind":"mc","stem":"「청소 당번을 정하는 날」에서 띄어쓰기가 잘못된 곳은 어느 것인가요?","options":[{"t":"스물네장","correct":true},{"t":"제비뽑기로","mis":"K6-1-u2-X25"},{"t":"창가 쪽만","mis":"K6-1-u2-X27"},{"t":"다음 달에","mis":"K6-1-u2-X25"}],"explanation":["「장」은 종이를 세는 말이에요.","세는 말 앞은 띄어 써요.","스물네 ∨ 장으로 고쳐요."],"asset":{"type":"passage","lines":["우리 반은 달마다 청소 당번을 새로 정합니다. 지난달에는 한줄로 앉은","차례대로 정했는데 창가 쪽만 힘든 곳을 맡아 불만이 나왔습니다.","그래서 이번에는 제비뽑기로 정하기로 했습니다.","먼저 종이 스물네장을 접어 상자에 넣었습니다.","청소 구역은 교실 및복도, 그리고 계단이었습니다.","뽑고 나서 서로 바꾸고 싶은 사람은 바꿀수있게 했습니다.","힘든 구역을 뽑은 친구에게는 다음 달에 먼저 고를 기회를 주기로 했습니다."],"title":"글 「청소 당번을 정하는 날」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L04_basic#8','kor',6,1,'u2','L04','g6_1_kor_u2_L04_basic','lesson_basic','K6-1-u2-C16',2,'ox','auto','띄어쓰기는 글씨를 예쁘게 쓰려고 하는 일이에요.',ARRAY['K6-1-u2-X24']::text[],false,'{"seq":8,"concept":"K6-1-u2-C16","difficulty":2,"kind":"ox","stem":"띄어쓰기는 글씨를 예쁘게 쓰려고 하는 일이에요.","answer":"X","reason_options":[{"t":"어디서 띄느냐에 따라 뜻이 달라지므로 뜻을 가르는 일이기 때문에","correct":true},{"t":"띄어 쓰면 글자가 가지런해 보이기 때문에","mis":"K6-1-u2-X24"}],"mis":"K6-1-u2-X24","explanation":["「큰 집」과 「큰집」은 뜻이 달라요.","읽는 사람은 띄어쓰기로 뜻을 알아내요.","띄어쓰기는 뜻을 가르는 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L04_basic#9','kor',6,1,'u2','L04','g6_1_kor_u2_L04_basic','lesson_basic','K6-1-u2-C19',2,'match','auto','말과 띄어쓰기 방법을 이으세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u2-C19","difficulty":2,"kind":"match","stem":"말과 띄어쓰기 방법을 이으세요.","pairs":[{"l":"을 · 에게 · 만","r":"앞말에 붙여 쓴다"},{"l":"것 · 수 · 데","r":"앞말과 띄어 쓴다"},{"l":"권 · 마리 · 그루","r":"앞의 수와 띄어 쓴다"}],"mis":"K6-1-u2-X27","explanation":["조사는 붙여 써요.","홀로 못 쓰는 이름씨는 띄어요.","세는 말도 수와 띄어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L04_basic#10','kor',6,1,'u2','L04','g6_1_kor_u2_L04_basic','lesson_basic','K6-1-u2-C20',3,'mc','auto','띄어 쓸 곳이 많은 글을 고칠 때 가장 알맞은 방법은 어느 것인가요?',ARRAY['K6-1-u2-X29','K6-1-u2-X23','K6-1-u2-X24']::text[],false,'{"seq":10,"concept":"K6-1-u2-C20","difficulty":3,"kind":"mc","stem":"띄어 쓸 곳이 많은 글을 고칠 때 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"띄울 곳에 ∨ 부호로 표시해 두고 마지막에 한 번에 옮긴다","correct":true},{"t":"고칠 곳이 많으니 글을 처음부터 다시 쓴다","mis":"K6-1-u2-X29"},{"t":"띄울 곳에 ⌒ 부호를 표시한다","mis":"K6-1-u2-X23"},{"t":"띄어쓰기는 읽으면 다 아니까 그냥 둔다","mis":"K6-1-u2-X24"}],"explanation":["다시 쓰지 않아도 돼요.","⌒ 는 붙일 때 써요.","∨ 로 표시하고 한 번에 옮겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L04_challenge#1','kor',6,1,'u2','L04','g6_1_kor_u2_L04_challenge','lesson_challenge','K6-1-u2-C16',2,'mc','auto','「큰집에 다녀왔다」와 「큰 집에 다녀왔다」의 차이로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X24']::text[],false,'{"seq":1,"concept":"K6-1-u2-C16","difficulty":2,"kind":"mc","stem":"「큰집에 다녀왔다」와 「큰 집에 다녀왔다」의 차이로 알맞은 것은 어느 것인가요?","options":[{"t":"앞은 친척 어른이 사는 집이고, 뒤는 크기가 큰 집이다","correct":true},{"t":"두 문장은 뜻이 같다","mis":"K6-1-u2-X24"},{"t":"앞은 틀리고 뒤만 맞다","mis":"K6-1-u2-X24"},{"t":"둘 다 띄어쓰기가 틀렸다","mis":"K6-1-u2-X24"}],"explanation":["띄어쓰기가 다르면 뜻도 달라요.","「큰집」은 한 낱말이에요.","「큰 집」은 크기가 큰 집이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L04_challenge#2','kor',6,1,'u2','L04','g6_1_kor_u2_L04_challenge','lesson_challenge','K6-1-u2-C20',2,'mc','auto','「스물네장」을 고칠 때 쓰는 부호 표시로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X23','K6-1-u2-X25']::text[],false,'{"seq":2,"concept":"K6-1-u2-C20","difficulty":2,"kind":"mc","stem":"「스물네장」을 고칠 때 쓰는 부호 표시로 알맞은 것은 어느 것인가요?","options":[{"t":"스물네∨장","correct":true},{"t":"스물네⌒장","mis":"K6-1-u2-X23"},{"t":"스물⊂네장","mis":"K6-1-u2-X23"},{"t":"스∨물∨네∨장","mis":"K6-1-u2-X25"}],"explanation":["띄울 곳에는 ∨ 를 써요.","⌒ 는 붙일 때 써요.","세는 말 앞에만 ∨ 를 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L04_challenge#3','kor',6,1,'u2','L04','g6_1_kor_u2_L04_challenge','lesson_challenge','K6-1-u2-C17',3,'error','auto','띄어쓰기를 바르게 했는지 살폈어요. 알맞지 않게 쓴 친구는 누구인가요?',ARRAY['K6-1-u2-X25']::text[],false,'{"seq":3,"concept":"K6-1-u2-C17","difficulty":3,"kind":"error","stem":"띄어쓰기를 바르게 했는지 살폈어요. 알맞지 않게 쓴 친구는 누구인가요?","options":[{"t":"하율 — 「사탕 여섯개를 샀다.」","correct":true,"mis_target":"K6-1-u2-X25"},{"t":"서진 — 「나무 두 그루를 심었다.」","mis":"K6-1-u2-X25"},{"t":"라온 — 「우유 한 잔을 마셨다.」","mis":"K6-1-u2-X25"}],"explanation":["그루 · 잔은 수와 띄었어요.","「개」도 세는 말이에요.","사탕 여섯 ∨ 개로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L04_challenge#4','kor',6,1,'u2','L04','g6_1_kor_u2_L04_challenge','lesson_challenge','K6-1-u2-C19',3,'mc','auto','「먹을것을 챙겨 갈데가 있다.」를 바르게 고친 것은 어느 것인가요?',ARRAY['K6-1-u2-X27','K6-1-u2-X28']::text[],false,'{"seq":4,"concept":"K6-1-u2-C19","difficulty":3,"kind":"mc","stem":"「먹을것을 챙겨 갈데가 있다.」를 바르게 고친 것은 어느 것인가요?","options":[{"t":"먹을 것을 챙겨 갈 데가 있다.","correct":true},{"t":"먹을 것 을 챙겨 갈 데 가 있다.","mis":"K6-1-u2-X27"},{"t":"먹을것을 챙겨 갈 데가 있다.","mis":"K6-1-u2-X28"},{"t":"먹을 것을 챙겨 갈데가 있다.","mis":"K6-1-u2-X28"}],"explanation":["「것」 · 「데」는 홀로 못 쓰는 이름씨예요.","앞말과 띄어 써요.","뒤에 붙은 조사 「을」 · 「가」는 붙여 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L04_challenge#5','kor',6,1,'u2','L04','g6_1_kor_u2_L04_challenge','lesson_challenge','K6-1-u2-C18',3,'mc','auto','「청소 구역은 교실 및복도, 그리고 계단이었습니다.」를 바르게 고친 것은 어느 것인가요?',ARRAY['K6-1-u2-X26','K6-1-u2-X24']::text[],false,'{"seq":5,"concept":"K6-1-u2-C18","difficulty":3,"kind":"mc","stem":"「청소 구역은 교실 및복도, 그리고 계단이었습니다.」를 바르게 고친 것은 어느 것인가요?","options":[{"t":"청소 구역은 교실 및 복도, 그리고 계단이었습니다.","correct":true},{"t":"청소 구역은 교실및복도, 그리고 계단이었습니다.","mis":"K6-1-u2-X26"},{"t":"청소 구역은 교실 및복도, 그리고계단이었습니다.","mis":"K6-1-u2-X26"},{"t":"청소구역은교실및복도, 그리고 계단이었습니다.","mis":"K6-1-u2-X24"}],"explanation":["「및」은 잇는 말이에요.","잇는 말은 앞뒤를 띄어요.","교실 ∨ 및 ∨ 복도로 고쳐요."],"asset":{"type":"passage","lines":["우리 반은 달마다 청소 당번을 새로 정합니다. 지난달에는 한줄로 앉은","차례대로 정했는데 창가 쪽만 힘든 곳을 맡아 불만이 나왔습니다.","그래서 이번에는 제비뽑기로 정하기로 했습니다.","먼저 종이 스물네장을 접어 상자에 넣었습니다.","청소 구역은 교실 및복도, 그리고 계단이었습니다.","뽑고 나서 서로 바꾸고 싶은 사람은 바꿀수있게 했습니다.","힘든 구역을 뽑은 친구에게는 다음 달에 먼저 고를 기회를 주기로 했습니다."],"title":"글 「청소 당번을 정하는 날」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L04_challenge#6','kor',6,1,'u2','L04','g6_1_kor_u2_L04_challenge','lesson_challenge','K6-1-u2-C16',3,'ox','auto','「잘못했다」와 「잘 못했다」는 띄어쓰기만 다르고 뜻은 같아요.',ARRAY['K6-1-u2-X24']::text[],false,'{"seq":6,"concept":"K6-1-u2-C16","difficulty":3,"kind":"ox","stem":"「잘못했다」와 「잘 못했다」는 띄어쓰기만 다르고 뜻은 같아요.","answer":"X","reason_options":[{"t":"「잘못했다」는 틀리게 했다는 뜻이고 「잘 못했다」는 잘하지 못했다는 뜻이라 다르기 때문에","correct":true},{"t":"띄어쓰기는 뜻과 상관없기 때문에","mis":"K6-1-u2-X24"}],"mis":"K6-1-u2-X24","explanation":["붙이면 「잘못」이라는 한 낱말이에요.","띄우면 「잘」과 「못했다」예요.","한 칸이 뜻을 갈라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L04_challenge#7','kor',6,1,'u2','L04','g6_1_kor_u2_L04_challenge','lesson_challenge','K6-1-u2-C20',3,'mc','auto','「띄어쓰기는 좀 틀려도 읽으면 다 알잖아.」라고 생각하는 친구에게 알맞은 생각은 어느 것인가요?',ARRAY['K6-1-u2-X24','K6-1-u2-X29']::text[],false,'{"seq":7,"concept":"K6-1-u2-C20","difficulty":3,"kind":"mc","stem":"「띄어쓰기는 좀 틀려도 읽으면 다 알잖아.」라고 생각하는 친구에게 알맞은 생각은 어느 것인가요?","options":[{"t":"「내가 자주 틀리는 띄어쓰기 한 가지를 정해서 다음 글부터 챙겨 보자.」","correct":true},{"t":"「맞아, 띄어쓰기는 몰라도 된다.」","mis":"K6-1-u2-X24"},{"t":"「틀린 곳이 있으면 글을 처음부터 다시 쓰자.」","mis":"K6-1-u2-X29"},{"t":"「띄어쓰기 규칙만 외우면 버릇은 상관없다.」","mis":"K6-1-u2-X29"}],"explanation":["읽는 사람이 다르게 알아들을 수 있어요.","다시 쓰지 않아도 돼요.","내 버릇 한 가지를 정해 챙겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L04_challenge#8','kor',6,1,'u2','L04','g6_1_kor_u2_L04_challenge','lesson_challenge','K6-1-u2-C17',4,'mc','auto','「청소 당번을 정하는 날」에서 띄어쓰기가 잘못된 곳을 모두 바르게 고친 것은 어느 것인가요?',ARRAY['K6-1-u2-X25','K6-1-u2-X26','K6-1-u2-X28']::text[],false,'{"seq":8,"concept":"K6-1-u2-C17","difficulty":4,"kind":"mc","stem":"「청소 당번을 정하는 날」에서 띄어쓰기가 잘못된 곳을 모두 바르게 고친 것은 어느 것인가요?","options":[{"t":"한 줄로 · 스물네 장 · 교실 및 복도 · 바꿀 수 있게","correct":true},{"t":"한줄로 · 스물네장 · 교실 및 복도 · 바꿀 수 있게","mis":"K6-1-u2-X25"},{"t":"한 줄로 · 스물네 장 · 교실및복도 · 바꿀수있게","mis":"K6-1-u2-X26"},{"t":"한 줄로 · 스물 네 장 · 교실 및 복도 · 바꿀수 있게","mis":"K6-1-u2-X28"}],"explanation":["세는 말 줄 · 장 앞을 띄어요.","잇는 말 및 앞뒤를 띄어요.","홀로 못 쓰는 이름씨 수도 띄어요."],"asset":{"type":"passage","lines":["우리 반은 달마다 청소 당번을 새로 정합니다. 지난달에는 한줄로 앉은","차례대로 정했는데 창가 쪽만 힘든 곳을 맡아 불만이 나왔습니다.","그래서 이번에는 제비뽑기로 정하기로 했습니다.","먼저 종이 스물네장을 접어 상자에 넣었습니다.","청소 구역은 교실 및복도, 그리고 계단이었습니다.","뽑고 나서 서로 바꾸고 싶은 사람은 바꿀수있게 했습니다.","힘든 구역을 뽑은 친구에게는 다음 달에 먼저 고를 기회를 주기로 했습니다."],"title":"글 「청소 당번을 정하는 날」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L04_challenge#9','kor',6,1,'u2','L04','g6_1_kor_u2_L04_challenge','lesson_challenge','K6-1-u2-C16',4,'essay','teacher','띄어쓰기에 따라 뜻이 달라지는 예를 하나 들어 두 가지 뜻을 쓰고, 띄어쓰기가 왜 중요한지 설명하세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u2-C16","difficulty":4,"kind":"essay","stem":"띄어쓰기에 따라 뜻이 달라지는 예를 하나 들어 두 가지 뜻을 쓰고, 띄어쓰기가 왜 중요한지 설명하세요.","answer_guide":{"answer":"예: 「오늘밤나무를심자」는 「오늘 밤 나무를 심자」로 띄우면 오늘 밤에 나무를 심자는 뜻이 되고, 「오늘 밤나무를 심자」로 띄우면 오늘 밤나무라는 나무를 심자는 뜻이 된다. 읽는 사람은 글쓴이의 마음을 볼 수 없으므로 띄어쓰기로 뜻을 알아낸다. 그래서 띄어쓰기를 틀리면 읽는 사람이 다르게 알아들을 수 있어 중요하다.","scoring_points":["띄어쓰기에 따라 뜻이 달라지는 예를 들었는가","두 가지 뜻을 바르게 썼는가","읽는 사람이 뜻을 알아내는 일과 이어 중요성을 썼는가"]},"explanation":["뜻이 갈리는 예를 떠올려요.","두 뜻을 견주어 써요.","읽는 사람의 처지에서 설명해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L04_challenge#10','kor',6,1,'u2','L04','g6_1_kor_u2_L04_challenge','lesson_challenge','K6-1-u2-C17',4,'essay','teacher','세는 말 · 잇는 말 · 홀로 못 쓰는 이름씨의 띄어쓰기 방법을 하나씩 예를 들어 설명하고, 내가 자주 틀리는 띄어쓰기 한 가지를 정해 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u2-C17","difficulty":4,"kind":"essay","stem":"세는 말 · 잇는 말 · 홀로 못 쓰는 이름씨의 띄어쓰기 방법을 하나씩 예를 들어 설명하고, 내가 자주 틀리는 띄어쓰기 한 가지를 정해 쓰세요.","answer_guide":{"answer":"예: 세는 말은 앞의 수와 띄어 써서 「책 세 권」처럼 쓴다. 잇는 말은 앞뒤를 띄어 써서 「청군 대 백군」처럼 쓴다. 홀로 못 쓰는 이름씨는 앞말과 띄어 써서 「할 수 있다」처럼 쓴다. 나는 「할수있다」처럼 「수」를 자주 붙여 써서, 다음 글부터는 「수」 앞뒤를 꼭 확인하겠다.","scoring_points":["세 가지 띄어쓰기 방법을 예와 함께 썼는가","예가 규칙에 맞는가","내가 자주 틀리는 곳 한 가지를 정했는가"]},"explanation":["세 가지 규칙을 떠올려요.","알맞은 예를 들어요.","내 버릇 한 가지를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L05_basic#1','kor',6,1,'u2','L05','g6_1_kor_u2_L05_basic','lesson_basic','K6-1-u2-C21',1,'mc','auto','감상문에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X30','K6-1-u2-X32']::text[],false,'{"seq":1,"concept":"K6-1-u2-C21","difficulty":1,"kind":"mc","stem":"감상문에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"본 것에 더해 내가 무엇을 느끼고 생각했는지를 적은 글","correct":true},{"t":"무슨 일이 일어났는지만 적은 글","mis":"K6-1-u2-X30"},{"t":"누가 써도 똑같아지는 글","mis":"K6-1-u2-X30"},{"t":"본 것의 모든 장면을 빠짐없이 적은 글","mis":"K6-1-u2-X32"}],"explanation":["일어난 일만 적으면 줄거리 요약이에요.","감상문은 쓴 사람마다 달라요.","느끼고 생각한 것을 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L05_basic#2','kor',6,1,'u2','L05','g6_1_kor_u2_L05_basic','lesson_basic','K6-1-u2-C22',1,'mc','auto','「우산 하나」에서 여울이 다음 날 아침에 한 일은 무엇인가요?',ARRAY['K6-1-u2-X31']::text[],false,'{"seq":2,"concept":"K6-1-u2-C22","difficulty":1,"kind":"mc","stem":"「우산 하나」에서 여울이 다음 날 아침에 한 일은 무엇인가요?","options":[{"t":"부러진 우산을 고쳐 태린의 사물함 앞에 놓아 두었다","correct":true},{"t":"새 우산을 사서 선물했다","mis":"K6-1-u2-X31"},{"t":"태린의 우산을 빌려 갔다","mis":"K6-1-u2-X31"},{"t":"태린과 우산을 같이 썼다","mis":"K6-1-u2-X31"}],"explanation":["사물함 앞에 낡은 우산이 놓여 있었어요.","실로 꿰맨 자국이 있었어요.","여울이 밤새 고쳐 온 것이에요."],"asset":{"type":"passage","lines":["전학 온 여울은 말수가 적습니다. 쉬는 시간에도 창밖만 봅니다.","비가 쏟아지던 날, 같은 반 태린이 우산을 같이 쓰자고 손짓합니다.","여울은 잠깐 멈추었다가 고개를 젓고 빗속으로 뛰어갑니다.","다음 날 아침, 태린의 사물함 앞에 낡은 우산 하나가 놓여 있습니다.","살이 부러졌던 자리를 실로 꿰맨 자국이 있습니다. 여울이 밤새 고쳐 온 것입니다.","마지막 장면에서 두 아이는 각자 우산을 펴 들고 나란히 걷습니다."],"title":"단편 영화 「우산 하나」 줄거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L05_basic#3','kor',6,1,'u2','L05','g6_1_kor_u2_L05_basic','lesson_basic','K6-1-u2-C23',1,'mc','auto','감상문에 담을 내용으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K6-1-u2-X32']::text[],false,'{"seq":3,"concept":"K6-1-u2-C23","difficulty":1,"kind":"mc","stem":"감상문에 담을 내용으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"등장인물의 옷 색깔 전부","correct":true},{"t":"보게 된 동기","mis":"K6-1-u2-X32"},{"t":"인상 깊은 장면과 까닭","mis":"K6-1-u2-X32"},{"t":"느낀 점이나 다짐","mis":"K6-1-u2-X32"}],"explanation":["동기 · 장면과 까닭 · 느낀 점은 담아요.","옷 색깔 전부는 상관없는 자잘한 것이에요.","본 것과 생각한 것을 함께 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L05_basic#4','kor',6,1,'u2','L05','g6_1_kor_u2_L05_basic','lesson_basic','K6-1-u2-C23',1,'ox','auto','감상문에서는 가운데 부분에 줄거리를 길게 쓰고 생각은 짧게 써요.',ARRAY['K6-1-u2-X32']::text[],false,'{"seq":4,"concept":"K6-1-u2-C23","difficulty":1,"kind":"ox","stem":"감상문에서는 가운데 부분에 줄거리를 길게 쓰고 생각은 짧게 써요.","answer":"X","reason_options":[{"t":"가운데에는 줄거리는 짧게, 인상 깊은 장면과 생각은 길게 쓰기 때문에","correct":true},{"t":"줄거리가 감상문에서 가장 중요하기 때문에","mis":"K6-1-u2-X32"}],"mis":"K6-1-u2-X32","explanation":["가운데가 가장 길어요.","하지만 줄거리는 짧게 써요.","장면과 생각을 길게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L05_basic#5','kor',6,1,'u2','L05','g6_1_kor_u2_L05_basic','lesson_basic','K6-1-u2-C23',2,'match','auto','감상문 문장이 들어갈 곳을 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-1-u2-C23","difficulty":2,"kind":"match","stem":"감상문 문장이 들어갈 곳을 이으세요.","pairs":[{"l":"비 오는 날 이야기라는 말을 듣고 골라 보았다","r":"처음"},{"l":"여울이 고개를 젓고 뛰어가는 장면이 남았다","r":"가운데"},{"l":"나도 도움을 건넬 때 상대의 방식을 물어보겠다","r":"끝"}],"mis":"K6-1-u2-X12","explanation":["보게 된 동기는 처음이에요.","인상 깊은 장면은 가운데예요.","앞으로 할 일은 끝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L05_basic#6','kor',6,1,'u2','L05','g6_1_kor_u2_L05_basic','lesson_basic','K6-1-u2-C22',2,'mc','auto','세아가 말한 인상 깊은 장면에서 「까닭」에 해당하는 부분은 어느 것인가요?',ARRAY['K6-1-u2-X31','K6-1-u2-X30']::text[],false,'{"seq":6,"concept":"K6-1-u2-C22","difficulty":2,"kind":"mc","stem":"세아가 말한 인상 깊은 장면에서 「까닭」에 해당하는 부분은 어느 것인가요?","options":[{"t":"각자 쓰는데도 둘이 더 가까워 보여서","correct":true},{"t":"마지막 장면이 남았어","mis":"K6-1-u2-X31"},{"t":"우산을 같이 쓰지 않고","mis":"K6-1-u2-X31"},{"t":"세아가 영화를 봤다","mis":"K6-1-u2-X30"}],"explanation":["「마지막 장면」은 고른 장면이에요.","「~여서」가 까닭을 알려 줘요.","왜 그 장면이 남았는지가 까닭이에요."],"asset":{"type":"speech","turns":[{"who":"세아","text":"마지막 장면이 남았어. 우산을 같이 쓰지 않고 각자 쓰는데도 둘이 더 가까워 보여서."},{"who":"민석","text":"나는 여울이 고개를 젓는 장면. 도움을 받는 게 왜 어려웠을지 생각하게 돼서."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L05_basic#7','kor',6,1,'u2','L05','g6_1_kor_u2_L05_basic','lesson_basic','K6-1-u2-C15',2,'mc','auto','태린의 초고에서 빼야 할 문장은 어느 것인가요?',ARRAY['K6-1-u2-X15']::text[],false,'{"seq":7,"concept":"K6-1-u2-C15","difficulty":2,"kind":"mc","stem":"태린의 초고에서 빼야 할 문장은 어느 것인가요?","options":[{"t":"요즘 우리 학교 앞 문구점이 문을 닫았다.","correct":true},{"t":"비 오는 날 이야기라고 해서 골랐다.","mis":"K6-1-u2-X15"},{"t":"다음 날 태린의 사물함 앞에 낡은 우산이 놓여 있었다.","mis":"K6-1-u2-X15"},{"t":"나는 그 장면을 오래 바라보았다.","mis":"K6-1-u2-X15"}],"explanation":["보게 된 동기와 줄거리는 감상문에 필요해요.","문구점 이야기는 영화와 상관없어요.","주제에서 벗어난 문장은 빼요."],"asset":{"type":"passage","lines":["비 오는 날 이야기라고 해서 골랐다. 전학 온 여울은 말이 거의 없다.","태린이 우산을 같이 쓰자고 했지만 여울은 뛰어가 버렸다.","요즘 우리 학교 앞 문구점이 문을 닫았다.","다음 날 태린의 사물함 앞에 낡은 우산이 놓여 있었다.","가장 마음에 남은 곳은 두 사람이 우산두개를 각각 펴 들고","나란히 걷는 장면이다. 나는 그 장면을 오래 바라보았다."],"title":"감상문 초고 「우산 하나를 봤다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L05_basic#8','kor',6,1,'u2','L05','g6_1_kor_u2_L05_basic','lesson_basic','K6-1-u2-C24',2,'mc','auto','태린의 초고에서 가장 먼저 손볼 것은 어느 것인가요?',ARRAY['K6-1-u2-X05','K6-1-u2-X01']::text[],false,'{"seq":8,"concept":"K6-1-u2-C24","difficulty":2,"kind":"mc","stem":"태린의 초고에서 가장 먼저 손볼 것은 어느 것인가요?","options":[{"t":"제목과 글 전체의 흐름","correct":true},{"t":"띄어쓰기 한 곳","mis":"K6-1-u2-X05"},{"t":"글씨를 예쁘게 옮겨 쓰기","mis":"K6-1-u2-X01"},{"t":"맞춤법만 한 번에","mis":"K6-1-u2-X05"}],"explanation":["작은 것부터 고치면 헛수고가 생겨요.","옮겨 쓰기는 고쳐쓰기가 아니에요.","큰 것부터 잡아요."],"asset":{"type":"passage","lines":["비 오는 날 이야기라고 해서 골랐다. 전학 온 여울은 말이 거의 없다.","태린이 우산을 같이 쓰자고 했지만 여울은 뛰어가 버렸다.","요즘 우리 학교 앞 문구점이 문을 닫았다.","다음 날 태린의 사물함 앞에 낡은 우산이 놓여 있었다.","가장 마음에 남은 곳은 두 사람이 우산두개를 각각 펴 들고","나란히 걷는 장면이다. 나는 그 장면을 오래 바라보았다."],"title":"감상문 초고 「우산 하나를 봤다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L05_basic#9','kor',6,1,'u2','L05','g6_1_kor_u2_L05_basic','lesson_basic','K6-1-u2-C17',2,'mc','auto','태린의 초고에서 「우산두개」를 바르게 고친 것은 어느 것인가요?',ARRAY['K6-1-u2-X25','K6-1-u2-X24']::text[],false,'{"seq":9,"concept":"K6-1-u2-C17","difficulty":2,"kind":"mc","stem":"태린의 초고에서 「우산두개」를 바르게 고친 것은 어느 것인가요?","options":[{"t":"우산 두 개","correct":true},{"t":"우산두 개","mis":"K6-1-u2-X25"},{"t":"우산 두개","mis":"K6-1-u2-X25"},{"t":"우 산 두 개","mis":"K6-1-u2-X24"}],"explanation":["「개」는 세는 말이에요.","세는 말은 수와 띄어요.","「우산」과 「두」도 띄어요."],"asset":{"type":"passage","lines":["비 오는 날 이야기라고 해서 골랐다. 전학 온 여울은 말이 거의 없다.","태린이 우산을 같이 쓰자고 했지만 여울은 뛰어가 버렸다.","요즘 우리 학교 앞 문구점이 문을 닫았다.","다음 날 태린의 사물함 앞에 낡은 우산이 놓여 있었다.","가장 마음에 남은 곳은 두 사람이 우산두개를 각각 펴 들고","나란히 걷는 장면이다. 나는 그 장면을 오래 바라보았다."],"title":"감상문 초고 「우산 하나를 봤다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L05_basic#10','kor',6,1,'u2','L05','g6_1_kor_u2_L05_basic','lesson_basic','K6-1-u2-C7',3,'mc','auto','「고칠 곳이 너무 많아 보여서 아예 다시 쓸까 했어.」라는 민석이에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X01','K6-1-u2-X02','K6-1-u2-X05']::text[],false,'{"seq":10,"concept":"K6-1-u2-C7","difficulty":3,"kind":"mc","stem":"「고칠 곳이 너무 많아 보여서 아예 다시 쓸까 했어.」라는 민석이에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「세 군데만 고쳐도 훨씬 잘 읽힐 수 있어. 완벽하게 고칠 필요는 없어.」","correct":true},{"t":"「맞아, 다시 쓰는 게 제일 좋아.」","mis":"K6-1-u2-X01"},{"t":"「완벽하게 고칠 수 없으면 손대지 마.」","mis":"K6-1-u2-X02"},{"t":"「띄어쓰기만 고치면 다 끝나.」","mis":"K6-1-u2-X05"}],"explanation":["다시 쓰지 않아도 돼요.","완벽할 필요가 없어요.","작게 고친 것도 잘 고친 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L05_challenge#1','kor',6,1,'u2','L05','g6_1_kor_u2_L05_challenge','lesson_challenge','K6-1-u2-C21',2,'mc','auto','줄거리 요약과 감상문을 견준 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X30','K6-1-u2-X32']::text[],false,'{"seq":1,"concept":"K6-1-u2-C21","difficulty":2,"kind":"mc","stem":"줄거리 요약과 감상문을 견준 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"줄거리 요약은 누가 써도 비슷하지만 감상문은 쓴 사람마다 달라진다","correct":true},{"t":"두 글은 같은 글이다","mis":"K6-1-u2-X30"},{"t":"감상문에는 줄거리가 하나도 들어가지 않는다","mis":"K6-1-u2-X32"},{"t":"줄거리 요약이 감상문보다 생각이 더 많이 담긴다","mis":"K6-1-u2-X30"}],"explanation":["줄거리 요약은 일어난 일만 적어요.","감상문에도 간단한 줄거리는 들어가요.","감상문에는 내 생각이 담겨 사람마다 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L05_challenge#2','kor',6,1,'u2','L05','g6_1_kor_u2_L05_challenge','lesson_challenge','K6-1-u2-C8',2,'mc','auto','태린의 초고 제목 「우산 하나를 봤다」를 고친 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X11','K6-1-u2-X36']::text[],false,'{"seq":2,"concept":"K6-1-u2-C8","difficulty":2,"kind":"mc","stem":"태린의 초고 제목 「우산 하나를 봤다」를 고친 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"각자 쓰는 우산, 나란한 걸음","correct":true},{"t":"우산 하나 줄거리","mis":"K6-1-u2-X11"},{"t":"비 오는 날","mis":"K6-1-u2-X11"},{"t":"학교 앞 문구점","mis":"K6-1-u2-X36"}],"explanation":["지금 제목에는 느낀 점이 없어요.","글감만 알리는 제목은 부족해요.","마음에 남은 장면과 생각을 담아요."],"asset":{"type":"passage","lines":["비 오는 날 이야기라고 해서 골랐다. 전학 온 여울은 말이 거의 없다.","태린이 우산을 같이 쓰자고 했지만 여울은 뛰어가 버렸다.","요즘 우리 학교 앞 문구점이 문을 닫았다.","다음 날 태린의 사물함 앞에 낡은 우산이 놓여 있었다.","가장 마음에 남은 곳은 두 사람이 우산두개를 각각 펴 들고","나란히 걷는 장면이다. 나는 그 장면을 오래 바라보았다."],"title":"감상문 초고 「우산 하나를 봤다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L05_challenge#3','kor',6,1,'u2','L05','g6_1_kor_u2_L05_challenge','lesson_challenge','K6-1-u2-C22',3,'error','auto','감상문에 쓸 문장을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u2-X31']::text[],false,'{"seq":3,"concept":"K6-1-u2-C22","difficulty":3,"kind":"error","stem":"감상문에 쓸 문장을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"하율 — 「마지막 장면이 좋았다. 끝.」","correct":true,"mis_target":"K6-1-u2-X31"},{"t":"서진 — 「여울이 고개를 젓는 장면에서 도움을 받는 게 왜 어려웠을지 생각했다.」","mis":"K6-1-u2-X31"},{"t":"라온 — 「꿰맨 우산을 보고, 받은 마음을 갚는 방법이 여러 가지라는 걸 알았다.」","mis":"K6-1-u2-X31"}],"explanation":["서진과 라온은 까닭을 붙였어요.","하율은 왜 좋았는지 쓰지 않았어요.","장면에는 까닭을 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L05_challenge#4','kor',6,1,'u2','L05','g6_1_kor_u2_L05_challenge','lesson_challenge','K6-1-u2-C24',3,'mc','auto','감상문 초고를 고칠 때 「띄어쓰기부터 손대는 것」이 알맞지 않은 까닭은 무엇인가요?',ARRAY['K6-1-u2-X24','K6-1-u2-X40','K6-1-u2-X01']::text[],false,'{"seq":4,"concept":"K6-1-u2-C24","difficulty":3,"kind":"mc","stem":"감상문 초고를 고칠 때 「띄어쓰기부터 손대는 것」이 알맞지 않은 까닭은 무엇인가요?","options":[{"t":"띄어쓰기를 다 고친 문장이 나중에 통째로 빠져야 하면 헛수고가 되기 때문에","correct":true},{"t":"띄어쓰기는 고칠 필요가 없기 때문에","mis":"K6-1-u2-X24"},{"t":"띄어쓰기는 친구가 고쳐 주기 때문에","mis":"K6-1-u2-X40"},{"t":"띄어쓰기를 고치면 글을 다시 써야 하기 때문에","mis":"K6-1-u2-X01"}],"explanation":["띄어쓰기도 고쳐요.","다만 마지막에 해요.","큰 것부터 잡아야 헛수고가 줄어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L05_challenge#5','kor',6,1,'u2','L05','g6_1_kor_u2_L05_challenge','lesson_challenge','K6-1-u2-C24',3,'ox','auto','맞춤법과 띄어쓰기를 다 바로잡았으면 고쳐쓰기는 끝난 거예요.',ARRAY['K6-1-u2-X05']::text[],false,'{"seq":5,"concept":"K6-1-u2-C24","difficulty":3,"kind":"ox","stem":"맞춤법과 띄어쓰기를 다 바로잡았으면 고쳐쓰기는 끝난 거예요.","answer":"X","reason_options":[{"t":"글 · 문단 수준의 흐름과 내용까지 고르게 살펴야 하기 때문에","correct":true},{"t":"맞춤법이 글에서 가장 중요하기 때문에","mis":"K6-1-u2-X05"}],"mis":"K6-1-u2-X05","explanation":["맞춤법은 문장 수준의 일부예요.","주제에서 벗어난 문장 · 차례도 봐요.","세 수준을 고르게 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L05_challenge#6','kor',6,1,'u2','L05','g6_1_kor_u2_L05_challenge','lesson_challenge','K6-1-u2-C24',3,'match','auto','태린의 초고에서 고칠 곳과 수준을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-1-u2-C24","difficulty":3,"kind":"match","stem":"태린의 초고에서 고칠 곳과 수준을 이으세요.","pairs":[{"l":"제목에 느낀 점이 없음","r":"글 수준"},{"l":"문구점 문장이 끼어 있음","r":"문단 수준"},{"l":"「우산두개」 띄어쓰기","r":"문장 수준"}],"mis":"K6-1-u2-X04","explanation":["제목은 글 전체와 견줘요.","끼어든 문장은 문단에서 봐요.","띄어쓰기는 문장에서 봐요."],"asset":{"type":"passage","lines":["비 오는 날 이야기라고 해서 골랐다. 전학 온 여울은 말이 거의 없다.","태린이 우산을 같이 쓰자고 했지만 여울은 뛰어가 버렸다.","요즘 우리 학교 앞 문구점이 문을 닫았다.","다음 날 태린의 사물함 앞에 낡은 우산이 놓여 있었다.","가장 마음에 남은 곳은 두 사람이 우산두개를 각각 펴 들고","나란히 걷는 장면이다. 나는 그 장면을 오래 바라보았다."],"title":"감상문 초고 「우산 하나를 봤다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L05_challenge#7','kor',6,1,'u2','L05','g6_1_kor_u2_L05_challenge','lesson_challenge','K6-1-u2-C23',3,'mc','auto','「우산 하나」 감상문의 「끝」에 들어갈 문장으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X12','K6-1-u2-X32']::text[],false,'{"seq":7,"concept":"K6-1-u2-C23","difficulty":3,"kind":"mc","stem":"「우산 하나」 감상문의 「끝」에 들어갈 문장으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"나도 친구에게 도움을 건넬 때 그 친구가 편한 방식을 먼저 물어보겠다.","correct":true},{"t":"비 오는 날 이야기라고 해서 골랐다.","mis":"K6-1-u2-X12"},{"t":"여울이 빗속으로 뛰어갔다.","mis":"K6-1-u2-X12"},{"t":"여울의 옷은 파란색이었고 가방은 회색이었다.","mis":"K6-1-u2-X32"}],"explanation":["보게 된 동기는 처음이에요.","줄거리는 가운데예요.","끝에는 느낀 점과 앞으로 할 일을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L05_challenge#8','kor',6,1,'u2','L05','g6_1_kor_u2_L05_challenge','lesson_challenge','K6-1-u2-C23',4,'mc','auto','태린의 초고를 고친 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X03','K6-1-u2-X05','K6-1-u2-X32']::text[],false,'{"seq":8,"concept":"K6-1-u2-C23","difficulty":4,"kind":"mc","stem":"태린의 초고를 고친 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"제목을 「각자 쓰는 우산, 나란한 걸음」으로 바꾸고, 문구점 문장을 빼고, 「우산 두 개」로 띄어 쓴다","correct":true},{"t":"문구점 문장을 맨 앞으로 옮기고 나머지는 그대로 둔다","mis":"K6-1-u2-X03"},{"t":"「우산 두 개」만 고치고 제목과 문장은 그대로 둔다","mis":"K6-1-u2-X05"},{"t":"모든 장면을 빠짐없이 더 넣는다","mis":"K6-1-u2-X32"}],"explanation":["벗어난 문장은 옮기지 않고 빼요.","띄어쓰기만으로는 부족해요.","제목 · 문단 · 문장을 고르게 고쳐요."],"asset":{"type":"passage","lines":["비 오는 날 이야기라고 해서 골랐다. 전학 온 여울은 말이 거의 없다.","태린이 우산을 같이 쓰자고 했지만 여울은 뛰어가 버렸다.","요즘 우리 학교 앞 문구점이 문을 닫았다.","다음 날 태린의 사물함 앞에 낡은 우산이 놓여 있었다.","가장 마음에 남은 곳은 두 사람이 우산두개를 각각 펴 들고","나란히 걷는 장면이다. 나는 그 장면을 오래 바라보았다."],"title":"감상문 초고 「우산 하나를 봤다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L05_challenge#9','kor',6,1,'u2','L05','g6_1_kor_u2_L05_challenge','lesson_challenge','K6-1-u2-C22',4,'essay','teacher','「우산 하나」에서 가장 인상 깊은 장면을 하나 고르고, 그 장면이 왜 마음에 남았는지 까닭을 붙여 감상문의 가운데 부분을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u2-C22","difficulty":4,"kind":"essay","stem":"「우산 하나」에서 가장 인상 깊은 장면을 하나 고르고, 그 장면이 왜 마음에 남았는지 까닭을 붙여 감상문의 가운데 부분을 쓰세요.","answer_guide":{"answer":"예: 가장 마음에 남은 장면은 태린의 사물함 앞에 실로 꿰맨 낡은 우산이 놓여 있던 장면이다. 여울은 우산을 같이 쓰자는 말에 고개를 저었지만, 밤새 우산을 고쳐 와서 고마운 마음을 자기 방식으로 돌려주었다. 나는 이 장면을 보고 고마움을 표현하는 방법이 사람마다 다를 수 있다는 것을 알게 되었다.","scoring_points":["인상 깊은 장면을 하나 골랐는가","그 장면이 남은 까닭을 썼는가","줄거리는 짧게, 생각은 자세히 썼는가"]},"explanation":["한 장면을 골라요.","왜 남았는지 까닭을 붙여요.","생각을 자세히 써요."],"asset":{"type":"passage","lines":["전학 온 여울은 말수가 적습니다. 쉬는 시간에도 창밖만 봅니다.","비가 쏟아지던 날, 같은 반 태린이 우산을 같이 쓰자고 손짓합니다.","여울은 잠깐 멈추었다가 고개를 젓고 빗속으로 뛰어갑니다.","다음 날 아침, 태린의 사물함 앞에 낡은 우산 하나가 놓여 있습니다.","살이 부러졌던 자리를 실로 꿰맨 자국이 있습니다. 여울이 밤새 고쳐 온 것입니다.","마지막 장면에서 두 아이는 각자 우산을 펴 들고 나란히 걷습니다."],"title":"단편 영화 「우산 하나」 줄거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L05_challenge#10','kor',6,1,'u2','L05','g6_1_kor_u2_L05_challenge','lesson_challenge','K6-1-u2-C24',4,'essay','teacher','태린의 초고에서 고칠 곳 세 가지를 글 · 문단 · 문장 수준으로 나누어 찾고, 어떤 차례로 고칠지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u2-C24","difficulty":4,"kind":"essay","stem":"태린의 초고에서 고칠 곳 세 가지를 글 · 문단 · 문장 수준으로 나누어 찾고, 어떤 차례로 고칠지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 글 수준 — 제목 「우산 하나를 봤다」에 느낀 점이 없다. 문단 수준 — 「요즘 우리 학교 앞 문구점이 문을 닫았다」는 영화와 상관없는 문장이다. 문장 수준 — 「우산두개」는 「우산 두 개」로 띄어 써야 한다. 고칠 차례는 제목과 글의 흐름 → 문구점 문장 빼기 → 띄어쓰기이다. 큰 것부터 고쳐야 다듬은 문장이 통째로 빠지는 헛수고가 없기 때문이다.","scoring_points":["세 수준의 고칠 곳을 하나씩 찾았는가","큰 것부터의 차례를 썼는가","그 차례의 까닭을 썼는가"]},"explanation":["세 수준으로 나누어 찾아요.","큰 것부터 차례를 정해요.","헛수고가 줄어드는 까닭을 써요."],"asset":{"type":"passage","lines":["비 오는 날 이야기라고 해서 골랐다. 전학 온 여울은 말이 거의 없다.","태린이 우산을 같이 쓰자고 했지만 여울은 뛰어가 버렸다.","요즘 우리 학교 앞 문구점이 문을 닫았다.","다음 날 태린의 사물함 앞에 낡은 우산이 놓여 있었다.","가장 마음에 남은 곳은 두 사람이 우산두개를 각각 펴 들고","나란히 걷는 장면이다. 나는 그 장면을 오래 바라보았다."],"title":"감상문 초고 「우산 하나를 봤다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L07_basic#1','kor',6,1,'u2','L07','g6_1_kor_u2_L07_basic','lesson_basic','K6-1-u2-C25',1,'mc','auto','명확한 문장의 조건으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X33','K6-1-u2-X35','K6-1-u2-X34']::text[],false,'{"seq":1,"concept":"K6-1-u2-C25","difficulty":1,"kind":"mc","stem":"명확한 문장의 조건으로 알맞은 것은 어느 것인가요?","options":[{"t":"한 문장에는 한 가지만 담는다","correct":true},{"t":"한 문장에 되도록 많은 것을 담는다","mis":"K6-1-u2-X33"},{"t":"같은 낱말을 여러 번 되풀이한다","mis":"K6-1-u2-X35"},{"t":"주어와 목적어는 빼도 된다","mis":"K6-1-u2-X34"}],"explanation":["길게 이으면 한 번에 읽히지 않아요.","겹치는 표현은 줄여요.","한 문장에 한 가지만 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L07_basic#2','kor',6,1,'u2','L07','g6_1_kor_u2_L07_basic','lesson_basic','K6-1-u2-C25',1,'mc','auto','다빈이 처음 쓴 문장이 한 번에 읽히지 않는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X37','K6-1-u2-X36','K6-1-u2-X33']::text[],false,'{"seq":2,"concept":"K6-1-u2-C25","difficulty":1,"kind":"mc","stem":"다빈이 처음 쓴 문장이 한 번에 읽히지 않는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"한 문장 안에 너무 많은 것이 들어 있고 같은 낱말이 되풀이되어서","correct":true},{"t":"틀린 내용이 많아서","mis":"K6-1-u2-X37"},{"t":"주제가 도서관이 아니어서","mis":"K6-1-u2-X36"},{"t":"문장이 너무 짧아서","mis":"K6-1-u2-X33"}],"explanation":["틀린 말은 하나도 없어요.","한 문장에 여러 가지가 이어져 있어요.","「번호」가 자꾸 되풀이돼요."],"asset":{"type":"passage","lines":["도서관에 가면 책마다 번호가 붙어 있는데 그 번호는 아무렇게나 붙인 번호가","아니라 책의 내용을 나누어 놓은 번호이고 그 번호를 알면 책을 찾기가","쉬워지는데 번호를 모르면 책을 찾기가 어렵고 그래서 도서관에서는","번호를 붙여 놓는 것입니다."],"title":"다빈이 처음 쓴 문장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L07_basic#3','kor',6,1,'u2','L07','g6_1_kor_u2_L07_basic','lesson_basic','K6-1-u2-C28',1,'mc','auto','설명하는 글에 쓰기 알맞은 자료는 어느 것인가요?',ARRAY['K6-1-u2-X37','K6-1-u2-X09']::text[],false,'{"seq":3,"concept":"K6-1-u2-C28","difficulty":1,"kind":"mc","stem":"설명하는 글에 쓰기 알맞은 자료는 어느 것인가요?","options":[{"t":"도서관에서 올해 펴낸 이용 안내 자료","correct":true},{"t":"누가 언제 썼는지 알 수 없는 글","mis":"K6-1-u2-X37"},{"t":"친구가 어디선가 들었다는 이야기","mis":"K6-1-u2-X37"},{"t":"다른 사람 글을 이름 없이 옮긴 것","mis":"K6-1-u2-X09"}],"explanation":["누가 만들었는지 알 수 있어야 해요.","언제 만들었는지 알 수 있어야 해요.","확인한 자료만 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L07_basic#4','kor',6,1,'u2','L07','g6_1_kor_u2_L07_basic','lesson_basic','K6-1-u2-C29',1,'match','auto','설명하는 글의 짜임과 하는 일을 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K6-1-u2-C29","difficulty":1,"kind":"match","stem":"설명하는 글의 짜임과 하는 일을 이으세요.","pairs":[{"l":"처음","r":"무엇을 설명할지 밝히고 관심을 끈다"},{"l":"가운데","r":"설명하려는 내용을 자세하게 풀어 쓴다"},{"l":"끝","r":"전체 내용을 간추리고 마무리한다"}],"mis":"K6-1-u2-X12","explanation":["처음에는 무엇을 설명할지 밝혀요.","가운데에는 자세히 풀어 써요.","끝에는 간추려 맺어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L07_basic#5','kor',6,1,'u2','L07','g6_1_kor_u2_L07_basic','lesson_basic','K6-1-u2-C26',2,'match','auto','문장에서 빠진 성분을 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-1-u2-C26","difficulty":2,"kind":"match","stem":"문장에서 빠진 성분을 이으세요.","pairs":[{"l":"책등에 붙어 있습니다.","r":"주어 — 무엇이"},{"l":"나는 서가에서 찾았습니다.","r":"목적어 — 무엇을"},{"l":"이 숫자는 책의 갈래를.","r":"서술어 — 어찌한다"}],"mis":"K6-1-u2-X34","explanation":["무엇이 붙어 있는지 빠졌어요.","무엇을 찾았는지 빠졌어요.","어찌한다는 말이 빠졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L07_basic#6','kor',6,1,'u2','L07','g6_1_kor_u2_L07_basic','lesson_basic','K6-1-u2-C26',2,'ox','auto','말할 때 주어를 빼도 통하니까 글에서도 주어를 빼도 괜찮아요.',ARRAY['K6-1-u2-X34']::text[],false,'{"seq":6,"concept":"K6-1-u2-C26","difficulty":2,"kind":"ox","stem":"말할 때 주어를 빼도 통하니까 글에서도 주어를 빼도 괜찮아요.","answer":"X","reason_options":[{"t":"읽는 사람은 그 자리에 없었으므로 글에서는 필수 성분을 갖춰야 뜻이 전해지기 때문에","correct":true},{"t":"글은 말보다 짧게 써야 하기 때문에","mis":"K6-1-u2-X34"}],"mis":"K6-1-u2-X34","explanation":["말할 때는 서로 아는 것이 많아요.","읽는 사람은 그 자리에 없었어요.","글에서는 필수 성분을 갖춰요."],"asset":{"type":"speech","turns":[{"who":"민석","text":"(책을 들고) 여기 있어. 아까 찾던 거."},{"who":"세아","text":"고마워!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L07_basic#7','kor',6,1,'u2','L07','g6_1_kor_u2_L07_basic','lesson_basic','K6-1-u2-C25',2,'mc','auto','다빈이 고친 글에서 한 일로 알맞지 않은 것은 어느 것인가요?',ARRAY['K6-1-u2-X33','K6-1-u2-X35']::text[],false,'{"seq":7,"concept":"K6-1-u2-C25","difficulty":2,"kind":"mc","stem":"다빈이 고친 글에서 한 일로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"설명하려는 내용을 다른 것으로 바꾸었다","correct":true},{"t":"한 문장을 여러 문장으로 나누었다","mis":"K6-1-u2-X33"},{"t":"되풀이되던 「번호」를 숫자 · 표시로 바꾸었다","mis":"K6-1-u2-X35"},{"t":"뜻이 또렷한 낱말로 바꾸었다","mis":"K6-1-u2-X35"}],"explanation":["문장을 셋으로 나누었어요.","겹치는 표현을 줄였어요.","설명하려는 내용은 그대로예요."],"asset":{"type":"passage","lines":["도서관에 가면 책등마다 숫자가 붙어 있습니다.","이 숫자는 책의 내용을 갈래별로 나눈 표시입니다.","숫자를 알면 넓은 서가에서도 찾는 책 앞으로 곧장 갈 수 있습니다."],"title":"다빈이 고친 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L07_basic#8','kor',6,1,'u2','L07','g6_1_kor_u2_L07_basic','lesson_basic','K6-1-u2-C27',2,'mc','auto','설명하는 글의 주제로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X36']::text[],false,'{"seq":8,"concept":"K6-1-u2-C27","difficulty":2,"kind":"mc","stem":"설명하는 글의 주제로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"우리 동네 버스 번호의 규칙","correct":true},{"t":"세상에 있는 모든 동물","mis":"K6-1-u2-X36"},{"t":"어제 내가 먹은 아침","mis":"K6-1-u2-X36"},{"t":"우주에서 일어나는 모든 일","mis":"K6-1-u2-X36"}],"explanation":["너무 넓은 주제는 무엇부터 쓸지 몰라요.","쓸 말이 거의 없는 것도 어려워요.","궁금해할 만하고 자료를 모을 수 있는 것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L07_basic#9','kor',6,1,'u2','L07','g6_1_kor_u2_L07_basic','lesson_basic','K6-1-u2-C30',2,'ox','auto','찾은 자료를 그대로 붙여 넣으면 내가 쓴 설명하는 글이 돼요.',ARRAY['K6-1-u2-X38']::text[],false,'{"seq":9,"concept":"K6-1-u2-C30","difficulty":2,"kind":"ox","stem":"찾은 자료를 그대로 붙여 넣으면 내가 쓴 설명하는 글이 돼요.","answer":"X","reason_options":[{"t":"읽고 이해한 뒤 내 말로 다시 써야 내 글이기 때문에","correct":true},{"t":"자료가 내 글보다 정확하기 때문에","mis":"K6-1-u2-X38"}],"mis":"K6-1-u2-X38","explanation":["그대로 옮긴 문장은 내 글이 아니에요.","이해한 것을 내 말로 써요.","가져온 곳도 함께 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L07_basic#10','kor',6,1,'u2','L07','g6_1_kor_u2_L07_basic','lesson_basic','K6-1-u2-C28',3,'mc','auto','자료를 쓸 때 확인할 세 가지를 바르게 묶은 것은 어느 것인가요?',ARRAY['K6-1-u2-X37','K6-1-u2-X43']::text[],false,'{"seq":10,"concept":"K6-1-u2-C28","difficulty":3,"kind":"mc","stem":"자료를 쓸 때 확인할 세 가지를 바르게 묶은 것은 어느 것인가요?","options":[{"t":"누가 만들었는가 · 언제 만들었는가 · 어디서 가져왔는가","correct":true},{"t":"얼마나 긴가 · 그림이 있는가 · 재미있는가","mis":"K6-1-u2-X37"},{"t":"친구가 좋아하는가 · 유명한가 · 길이가 짧은가","mis":"K6-1-u2-X37"},{"t":"누가 만들었는가 · 그림이 예쁜가 · 글씨가 큰가","mis":"K6-1-u2-X43"}],"explanation":["믿을 수 있는지 봐요.","지금도 맞는지 봐요.","출처를 밝혔는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L07_challenge#1','kor',6,1,'u2','L07','g6_1_kor_u2_L07_challenge','lesson_challenge','K6-1-u2-C25',2,'mc','auto','「숫자는 갈래를 나타내고 숫자를 알면 책을 빨리 찾을 수 있고 도서관마다 안내도가 있어서 그것을 보면 된다.」를 잘 나눈 것은 어느 것인가요?',ARRAY['K6-1-u2-X33','K6-1-u2-X34','K6-1-u2-X35']::text[],false,'{"seq":1,"concept":"K6-1-u2-C25","difficulty":2,"kind":"mc","stem":"「숫자는 갈래를 나타내고 숫자를 알면 책을 빨리 찾을 수 있고 도서관마다 안내도가 있어서 그것을 보면 된다.」를 잘 나눈 것은 어느 것인가요?","options":[{"t":"숫자는 갈래를 나타냅니다. 숫자를 알면 책을 빨리 찾을 수 있습니다. 도서관마다 안내도도 있습니다.","correct":true},{"t":"숫자는 갈래를 나타내고 알면 빨리 찾을 수 있고 안내도도 있고 보면 됩니다.","mis":"K6-1-u2-X33"},{"t":"숫자는 갈래. 책은 빨리. 안내도.","mis":"K6-1-u2-X34"},{"t":"숫자 숫자 숫자는 갈래를 나타냅니다.","mis":"K6-1-u2-X35"}],"explanation":["여전히 이어 붙이면 길어요.","너무 줄이면 서술어가 빠져요.","한 문장에 한 가지씩, 서술어도 갖춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L07_challenge#2','kor',6,1,'u2','L07','g6_1_kor_u2_L07_challenge','lesson_challenge','K6-1-u2-C27',2,'mc','auto','설명하는 글의 제목으로 알맞은 것의 조건은 어느 것인가요?',ARRAY['K6-1-u2-X36','K6-1-u2-X11']::text[],false,'{"seq":2,"concept":"K6-1-u2-C27","difficulty":2,"kind":"mc","stem":"설명하는 글의 제목으로 알맞은 것의 조건은 어느 것인가요?","options":[{"t":"내용과 일치하고 짧으면서 관심을 끈다","correct":true},{"t":"내용과 상관없이 재미있으면 된다","mis":"K6-1-u2-X36"},{"t":"글감 이름만 쓰면 충분하다","mis":"K6-1-u2-X11"},{"t":"길수록 자세해서 좋다","mis":"K6-1-u2-X36"}],"explanation":["제목은 내용과 일치해야 해요.","짧으면서 관심을 끌어야 해요.","주제를 정한 다음에 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L07_challenge#3','kor',6,1,'u2','L07','g6_1_kor_u2_L07_challenge','lesson_challenge','K6-1-u2-C26',3,'error','auto','「여기 있어. 아까 찾던 거.」를 두고 이야기했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u2-X34']::text[],false,'{"seq":3,"concept":"K6-1-u2-C26","difficulty":3,"kind":"error","stem":"「여기 있어. 아까 찾던 거.」를 두고 이야기했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"하율 — 「글에 써도 똑같이 뜻이 다 통해.」","correct":true,"mis_target":"K6-1-u2-X34"},{"t":"서진 — 「말할 때는 둘 다 무엇인지 알아서 통해.」","mis":"K6-1-u2-X34"},{"t":"라온 — 「글로 쓰면 무엇이 어디 있는지 넣어야 해.」","mis":"K6-1-u2-X34"}],"explanation":["서진과 라온은 바르게 말했어요.","읽는 사람은 무엇을 찾았는지 몰라요.","하율은 글에서도 필수 성분을 빼도 된다고 여겼어요."],"asset":{"type":"speech","turns":[{"who":"민석","text":"(책을 들고) 여기 있어. 아까 찾던 거."},{"who":"세아","text":"고마워!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L07_challenge#4','kor',6,1,'u2','L07','g6_1_kor_u2_L07_challenge','lesson_challenge','K6-1-u2-C25',3,'mc','auto','「이 책은 책장 맨 위 책장 칸에 꽂힌 책입니다.」에서 고칠 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X34','K6-1-u2-X33','K6-1-u2-X35']::text[],false,'{"seq":4,"concept":"K6-1-u2-C25","difficulty":3,"kind":"mc","stem":"「이 책은 책장 맨 위 책장 칸에 꽂힌 책입니다.」에서 고칠 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"겹치는 「책」 · 「책장」을 줄여 「이 책은 책장 맨 위 칸에 꽂혀 있습니다.」로 쓴다","correct":true},{"t":"주어를 빼고 「맨 위 칸에 꽂힌 책입니다.」로 쓴다","mis":"K6-1-u2-X34"},{"t":"뒤에 문장을 더 이어 붙인다","mis":"K6-1-u2-X33"},{"t":"그대로 두어도 된다","mis":"K6-1-u2-X35"}],"explanation":["주어를 빼면 무엇인지 몰라요.","이어 붙이면 더 길어져요.","겹치는 표현을 하나로 줄여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L07_challenge#5','kor',6,1,'u2','L07','g6_1_kor_u2_L07_challenge','lesson_challenge','K6-1-u2-C28',3,'match','auto','자료와 알맞은 판단을 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-1-u2-C28","difficulty":3,"kind":"match","stem":"자료와 알맞은 판단을 이으세요.","pairs":[{"l":"도서관에서 올해 펴낸 이용 안내 자료","r":"만든 곳과 때를 알아 쓸 수 있다"},{"l":"누가 언제 썼는지 알 수 없는 글","r":"확인되지 않아 쓰지 않는다"},{"l":"책에서 옮겨 온 설명","r":"내 말로 바꾸고 출처를 적는다"}],"mis":"K6-1-u2-X37","explanation":["만든 곳과 때가 분명하면 믿을 수 있어요.","확인되지 않은 자료는 쓰지 않아요.","옮긴 것은 내 말로 바꾸고 출처를 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L07_challenge#6','kor',6,1,'u2','L07','g6_1_kor_u2_L07_challenge','lesson_challenge','K6-1-u2-C29',3,'mc','auto','「도서관 책에 붙은 번호」의 「가운데」에 들어갈 내용으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K6-1-u2-X12']::text[],false,'{"seq":6,"concept":"K6-1-u2-C29","difficulty":3,"kind":"mc","stem":"「도서관 책에 붙은 번호」의 「가운데」에 들어갈 내용으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"전체 내용을 간추리는 마지막 문장","correct":true},{"t":"숫자가 무엇을 나타내는지","mis":"K6-1-u2-X12"},{"t":"갈래를 나누는 방법의 예","mis":"K6-1-u2-X12"},{"t":"숫자로 책을 찾는 차례","mis":"K6-1-u2-X12"}],"explanation":["가운데에는 자세한 설명이 들어가요.","간추리는 문장은 끝에 들어가요.","처음 · 가운데 · 끝이 하는 일이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L07_challenge#7','kor',6,1,'u2','L07','g6_1_kor_u2_L07_challenge','lesson_challenge','K6-1-u2-C30',3,'ox','auto','디지털 매체로 글을 쓸 때에는 보기 좋은 그림이면 내용과 상관없이 넣어도 돼요.',ARRAY['K6-1-u2-X43']::text[],false,'{"seq":7,"concept":"K6-1-u2-C30","difficulty":3,"kind":"ox","stem":"디지털 매체로 글을 쓸 때에는 보기 좋은 그림이면 내용과 상관없이 넣어도 돼요.","answer":"X","reason_options":[{"t":"넣는 그림은 글의 내용과 이어져야 흐름이 끊기지 않기 때문에","correct":true},{"t":"그림이 많을수록 좋은 글이기 때문에","mis":"K6-1-u2-X43"}],"mis":"K6-1-u2-X43","explanation":["그림도 글의 한 부분이에요.","아무거나 넣으면 흐름이 끊겨요.","내용과 이어지는 그림만 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L07_challenge#8','kor',6,1,'u2','L07','g6_1_kor_u2_L07_challenge','lesson_challenge','K6-1-u2-C25',4,'mc','auto','다빈의 처음 문장과 고친 글을 견주어 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X33','K6-1-u2-X01','K6-1-u2-X35']::text[],false,'{"seq":8,"concept":"K6-1-u2-C25","difficulty":4,"kind":"mc","stem":"다빈의 처음 문장과 고친 글을 견주어 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"문장을 나누고 겹치는 표현을 줄였더니 글자 수는 줄었는데 뜻은 더 또렷해졌다","correct":true},{"t":"문장이 길수록 뜻이 더 또렷해진다","mis":"K6-1-u2-X33"},{"t":"고친 글은 설명하는 내용이 달라졌다","mis":"K6-1-u2-X01"},{"t":"「번호」를 되풀이해야 뜻이 분명하다","mis":"K6-1-u2-X35"}],"explanation":["긴 문장은 한 번에 읽히지 않아요.","내용은 그대로예요.","나누고 줄이면 더 또렷해져요."],"asset":{"type":"passage","lines":["도서관에 가면 책등마다 숫자가 붙어 있습니다.","이 숫자는 책의 내용을 갈래별로 나눈 표시입니다.","숫자를 알면 넓은 서가에서도 찾는 책 앞으로 곧장 갈 수 있습니다."],"title":"다빈이 고친 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L07_challenge#9','kor',6,1,'u2','L07','g6_1_kor_u2_L07_challenge','lesson_challenge','K6-1-u2-C25',4,'essay','teacher','다빈이 처음 쓴 긴 문장을 명확한 문장의 세 가지 조건에 맞게 고쳐 쓰고, 어떤 조건을 지켰는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u2-C25","difficulty":4,"kind":"essay","stem":"다빈이 처음 쓴 긴 문장을 명확한 문장의 세 가지 조건에 맞게 고쳐 쓰고, 어떤 조건을 지켰는지 쓰세요.","answer_guide":{"answer":"예: 도서관 책에는 번호가 붙어 있습니다. 이 번호는 책의 내용을 갈래별로 나눈 표시입니다. 번호를 알면 책을 쉽게 찾을 수 있습니다. 그래서 도서관에서는 책마다 번호를 붙여 둡니다. — 한 문장에 한 가지만 담도록 넷으로 나누었고, 문장마다 주어와 서술어를 갖췄으며, 되풀이되던 「번호」를 「표시」로 바꾸어 겹치는 표현을 줄였다.","scoring_points":["긴 문장을 여러 문장으로 나누었는가","빠진 성분 없이 고쳐 썼는가","지킨 조건을 설명했는가"]},"explanation":["한 문장에 한 가지씩 나눠요.","필수 성분을 갖춰요.","겹치는 표현을 줄였는지 써요."],"asset":{"type":"passage","lines":["도서관에 가면 책마다 번호가 붙어 있는데 그 번호는 아무렇게나 붙인 번호가","아니라 책의 내용을 나누어 놓은 번호이고 그 번호를 알면 책을 찾기가","쉬워지는데 번호를 모르면 책을 찾기가 어렵고 그래서 도서관에서는","번호를 붙여 놓는 것입니다."],"title":"다빈이 처음 쓴 문장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L07_challenge#10','kor',6,1,'u2','L07','g6_1_kor_u2_L07_challenge','lesson_challenge','K6-1-u2-C30',4,'essay','teacher','설명하는 글을 쓸 때 찾은 자료를 어떻게 써야 하는지 세 가지를 쓰고, 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u2-C30","difficulty":4,"kind":"essay","stem":"설명하는 글을 쓸 때 찾은 자료를 어떻게 써야 하는지 세 가지를 쓰고, 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 첫째, 누가 언제 만들었는지 확인한 자료만 쓴다. 믿을 수 없거나 오래된 자료는 틀린 내용을 전할 수 있기 때문이다. 둘째, 읽고 이해한 뒤 내 말로 바꾸어 쓴다. 그대로 옮긴 문장은 내 글이 아니기 때문이다. 셋째, 가져온 곳을 함께 적는다. 다른 사람이 만든 자료이고 읽는 사람이 확인할 수 있어야 하기 때문이다.","scoring_points":["자료 확인에 대해 썼는가","내 말로 바꾸어 쓰기를 썼는가","출처 밝히기와 까닭을 썼는가"]},"explanation":["누가 · 언제를 확인해요.","내 말로 바꾸어 써요.","출처를 적는 까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L09_basic#1','kor',6,1,'u2','L09','g6_1_kor_u2_L09_basic','lesson_basic','K6-1-u2-C31',1,'mc','auto','친구의 글을 읽을 때 가장 먼저 할 일은 무엇인가요?',ARRAY['K6-1-u2-X05','K6-1-u2-X06','K6-1-u2-X39']::text[],false,'{"seq":1,"concept":"K6-1-u2-C31","difficulty":1,"kind":"mc","stem":"친구의 글을 읽을 때 가장 먼저 할 일은 무엇인가요?","options":[{"t":"무슨 말을 하려는 글인지 한 줄로 잡는다","correct":true},{"t":"띄어쓰기가 틀린 곳부터 센다","mis":"K6-1-u2-X05"},{"t":"고칠 곳만 찾아 적는다","mis":"K6-1-u2-X06"},{"t":"글쓴이가 누구인지만 본다","mis":"K6-1-u2-X39"}],"explanation":["하려는 말을 알아야 고칠 곳도 보여요.","띄어쓰기는 마지막에 봐요.","먼저 하려는 말을 한 줄로 잡아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L09_basic#2','kor',6,1,'u2','L09','g6_1_kor_u2_L09_basic','lesson_basic','K6-1-u2-C31',1,'match','auto','친구의 말과 의견의 갈래를 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K6-1-u2-C31","difficulty":1,"kind":"match","stem":"친구의 말과 의견의 갈래를 이으세요.","pairs":[{"l":"숫자에 뜻이 있는 줄 몰랐어","r":"새롭게 안 점"},{"l":"도서관마다 숫자가 같은지 궁금해","r":"궁금한 점"},{"l":"첫 문단이 짧아서 읽기 좋았어","r":"좋은 점"}],"mis":"K6-1-u2-X39","explanation":["몰랐던 것을 알게 되었어요.","더 알고 싶은 것이에요.","잘 쓴 곳과 까닭이에요."],"asset":{"type":"speech","turns":[{"who":"승아","text":"숫자에 뜻이 있는 줄 몰랐어."},{"who":"우진","text":"도서관마다 숫자가 같은지 궁금해."},{"who":"정후","text":"첫 문단이 짧아서 읽기 좋았어."},{"who":"승아","text":"의자 이야기는 빼면 좋겠어. 숫자 설명과 멀어 보여서."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L09_basic#3','kor',6,1,'u2','L09','g6_1_kor_u2_L09_basic','lesson_basic','K6-1-u2-C15',1,'mc','auto','다빈의 문단에서 빼야 할 문장은 어느 것인가요?',ARRAY['K6-1-u2-X15','K6-1-u2-X16']::text[],false,'{"seq":3,"concept":"K6-1-u2-C15","difficulty":1,"kind":"mc","stem":"다빈의 문단에서 빼야 할 문장은 어느 것인가요?","options":[{"t":"도서관 의자는 푹신합니다.","correct":true},{"t":"숫자를 알면 넓은 서가에서도 책을 빨리 찾을 수 있습니다.","mis":"K6-1-u2-X15"},{"t":"같은 갈래의 책은 한곳에 모여 있습니다.","mis":"K6-1-u2-X15"},{"t":"갈래는 크게 열개로 나뉩니다.","mis":"K6-1-u2-X16"}],"explanation":["이 문단의 중심 생각은 숫자로 책을 찾는 것이에요.","의자 이야기는 상관이 없어요.","「열개」는 빼지 말고 띄어 고쳐요."],"asset":{"type":"passage","lines":["숫자를 알면 넓은 서가에서도 책을 빨리 찾을 수 있습니다.","도서관 의자는 푹신합니다.","갈래는 크게 열개로 나뉘고, 같은 갈래의 책은 한곳에 모여 있습니다."],"title":"다빈의 글 「도서관 책에 붙은 번호」 한 문단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L09_basic#4','kor',6,1,'u2','L09','g6_1_kor_u2_L09_basic','lesson_basic','K6-1-u2-C32',1,'ox','auto','친구가 말한 의견은 모두 따라 고쳐야 해요.',ARRAY['K6-1-u2-X40']::text[],false,'{"seq":4,"concept":"K6-1-u2-C32","difficulty":1,"kind":"ox","stem":"친구가 말한 의견은 모두 따라 고쳐야 해요.","answer":"X","reason_options":[{"t":"의견은 받는 것이고 고르는 것은 글쓴이이기 때문에","correct":true},{"t":"친구가 글쓴이보다 글을 더 잘 알기 때문에","mis":"K6-1-u2-X40"}],"mis":"K6-1-u2-X40","explanation":["다빈은 책 목록 의견을 따르지 않았어요.","숫자를 설명하는 글이었기 때문이에요.","하려던 말에 도움이 되는 의견을 골라요."],"asset":{"type":"speech","turns":[{"who":"정후","text":"다빈아, 글 끝에 네가 좋아하는 책 목록도 넣으면 어때?"},{"who":"다빈","text":"고맙지만 이 글은 숫자를 설명하는 글이라 그건 안 넣기로 했어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L09_basic#5','kor',6,1,'u2','L09','g6_1_kor_u2_L09_basic','lesson_basic','K6-1-u2-C5',2,'mc','auto','다빈의 글에 남길 댓글로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X06','K6-1-u2-X07','K6-1-u2-X08']::text[],false,'{"seq":5,"concept":"K6-1-u2-C5","difficulty":2,"kind":"mc","stem":"다빈의 글에 남길 댓글로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「숫자 설명이 쉬웠어. 의자 이야기는 주제와 멀어 보여서 빼면 좋겠어.」","correct":true},{"t":"「틀린 데가 너무 많아. 처음부터 다시 써야겠어.」","mis":"K6-1-u2-X06"},{"t":"「잘 썼네. 고칠 곳 하나도 없어.」","mis":"K6-1-u2-X07"},{"t":"「의자 이야기 빼.」","mis":"K6-1-u2-X08"}],"explanation":["다시 쓰라는 말은 위축시켜요.","막연한 칭찬은 쓸모가 적어요.","잘한 곳 → 고칠 곳 → 까닭 차례로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L09_basic#6','kor',6,1,'u2','L09','g6_1_kor_u2_L09_basic','lesson_basic','K6-1-u2-C17',2,'mc','auto','다빈의 문단에서 「열개」를 바르게 고친 것은 어느 것인가요?',ARRAY['K6-1-u2-X25','K6-1-u2-X27','K6-1-u2-X23']::text[],false,'{"seq":6,"concept":"K6-1-u2-C17","difficulty":2,"kind":"mc","stem":"다빈의 문단에서 「열개」를 바르게 고친 것은 어느 것인가요?","options":[{"t":"열 개","correct":true},{"t":"열개","mis":"K6-1-u2-X25"},{"t":"열 개 로","mis":"K6-1-u2-X27"},{"t":"열⌒개","mis":"K6-1-u2-X23"}],"explanation":["「개」는 세는 말이에요.","수와 세는 말은 띄어 써요.","「열 개로」처럼 조사는 붙여요."],"asset":{"type":"passage","lines":["숫자를 알면 넓은 서가에서도 책을 빨리 찾을 수 있습니다.","도서관 의자는 푹신합니다.","갈래는 크게 열개로 나뉘고, 같은 갈래의 책은 한곳에 모여 있습니다."],"title":"다빈의 글 「도서관 책에 붙은 번호」 한 문단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L09_basic#7','kor',6,1,'u2','L09','g6_1_kor_u2_L09_basic','lesson_basic','K6-1-u2-C33',2,'mc','auto','고쳐 쓴 글을 학급 게시판에 공유하는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X41','K6-1-u2-X10']::text[],false,'{"seq":7,"concept":"K6-1-u2-C33","difficulty":2,"kind":"mc","stem":"고쳐 쓴 글을 학급 게시판에 공유하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"마지막 글 올리기 → 올라갔는지 확인 → 친구 글에 댓글 → 내 글 댓글 읽고 다시 점검","correct":true},{"t":"글 올리기 → 끝","mis":"K6-1-u2-X41"},{"t":"댓글 달기 → 글 올리기 → 끝","mis":"K6-1-u2-X41"},{"t":"글 올리기 → 칭찬 기다리기","mis":"K6-1-u2-X10"}],"explanation":["올리고 끝내지 않아요.","제대로 올라갔는지 확인해요.","달린 댓글을 읽고 다시 점검해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L09_basic#8','kor',6,1,'u2','L09','g6_1_kor_u2_L09_basic','lesson_basic','K6-1-u2-C35',2,'ox','auto','글에 넣은 사진이 보기 좋아도 내용과 이어지지 않으면 빼는 것도 고쳐쓰기예요.',ARRAY['K6-1-u2-X43']::text[],false,'{"seq":8,"concept":"K6-1-u2-C35","difficulty":2,"kind":"ox","stem":"글에 넣은 사진이 보기 좋아도 내용과 이어지지 않으면 빼는 것도 고쳐쓰기예요.","answer":"O","reason_options":[{"t":"사진과 영상도 글의 한 부분이라 내용과 이어져야 하기 때문에","correct":true},{"t":"사진은 글이 아니라 고칠 필요가 없기 때문에","mis":"K6-1-u2-X43"}],"mis":"K6-1-u2-X43","explanation":["도서관 바깥 풍경은 숫자 설명과 이어지지 않아요.","책등 숫자가 보이는 서가 사진은 이어져요.","겉도는 자료는 빼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L09_basic#9','kor',6,1,'u2','L09','g6_1_kor_u2_L09_basic','lesson_basic','K6-1-u2-C34',2,'mc','auto','맞춤법 검사기를 쓸 때 알맞은 태도는 어느 것인가요?',ARRAY['K6-1-u2-X42','K6-1-u2-X41']::text[],false,'{"seq":9,"concept":"K6-1-u2-C34","difficulty":2,"kind":"mc","stem":"맞춤법 검사기를 쓸 때 알맞은 태도는 어느 것인가요?","options":[{"t":"도구가 고친 곳도 왜 그렇게 고쳤는지 확인하고 받아들인다","correct":true},{"t":"도구가 고친 대로 모두 받아들인다","mis":"K6-1-u2-X42"},{"t":"도구가 글의 중심 생각까지 정해 준다","mis":"K6-1-u2-X42"},{"t":"도구를 썼으니 다시 읽지 않는다","mis":"K6-1-u2-X41"}],"explanation":["까닭을 모르면 다음에도 똑같이 틀려요.","중심 생각은 도구가 정하지 못해요.","고칠지 말지는 글쓴이가 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L09_basic#10','kor',6,1,'u2','L09','g6_1_kor_u2_L09_basic','lesson_basic','K6-1-u2-C32',3,'mc','auto','다빈이 정후의 의견을 따르지 않은 것에 대해 알맞게 말한 것은 어느 것인가요?',ARRAY['K6-1-u2-X40','K6-1-u2-X41']::text[],false,'{"seq":10,"concept":"K6-1-u2-C32","difficulty":3,"kind":"mc","stem":"다빈이 정후의 의견을 따르지 않은 것에 대해 알맞게 말한 것은 어느 것인가요?","options":[{"t":"숫자를 설명하는 글이라 책 목록은 하려던 말을 흐리게 하므로 따르지 않은 까닭이 분명하다","correct":true},{"t":"친구 의견을 따르지 않았으니 예의가 없다","mis":"K6-1-u2-X40"},{"t":"정후의 의견이 틀렸으니 다시는 의견을 받지 않는다","mis":"K6-1-u2-X41"},{"t":"친구가 말하면 무조건 넣어야 한다","mis":"K6-1-u2-X40"}],"explanation":["의견을 고르는 것은 글쓴이예요.","기준은 하려던 말이 더 잘 전해지는가예요.","따르지 않은 까닭을 말할 수 있으면 돼요."],"asset":{"type":"speech","turns":[{"who":"정후","text":"다빈아, 글 끝에 네가 좋아하는 책 목록도 넣으면 어때?"},{"who":"다빈","text":"고맙지만 이 글은 숫자를 설명하는 글이라 그건 안 넣기로 했어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L09_challenge#1','kor',6,1,'u2','L09','g6_1_kor_u2_L09_challenge','lesson_challenge','K6-1-u2-C31',2,'mc','auto','「의자 이야기는 빼면 좋겠어. 숫자 설명과 멀어 보여서.」는 의견의 네 갈래 가운데 무엇인가요?',ARRAY['K6-1-u2-X39']::text[],false,'{"seq":1,"concept":"K6-1-u2-C31","difficulty":2,"kind":"mc","stem":"「의자 이야기는 빼면 좋겠어. 숫자 설명과 멀어 보여서.」는 의견의 네 갈래 가운데 무엇인가요?","options":[{"t":"고쳤으면 하는 점","correct":true},{"t":"새롭게 안 점","mis":"K6-1-u2-X39"},{"t":"궁금한 점","mis":"K6-1-u2-X39"},{"t":"좋은 점","mis":"K6-1-u2-X39"}],"explanation":["빼자고 말했어요.","까닭도 함께 말했어요.","고칠 곳과 까닭은 고쳤으면 하는 점이에요."],"asset":{"type":"speech","turns":[{"who":"승아","text":"숫자에 뜻이 있는 줄 몰랐어."},{"who":"우진","text":"도서관마다 숫자가 같은지 궁금해."},{"who":"정후","text":"첫 문단이 짧아서 읽기 좋았어."},{"who":"승아","text":"의자 이야기는 빼면 좋겠어. 숫자 설명과 멀어 보여서."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L09_challenge#2','kor',6,1,'u2','L09','g6_1_kor_u2_L09_challenge','lesson_challenge','K6-1-u2-C33',2,'mc','auto','승아의 댓글에 다빈이 단 답글에서 본받을 점은 무엇인가요?',ARRAY['K6-1-u2-X41','K6-1-u2-X06','K6-1-u2-X01']::text[],false,'{"seq":2,"concept":"K6-1-u2-C33","difficulty":2,"kind":"mc","stem":"승아의 댓글에 다빈이 단 답글에서 본받을 점은 무엇인가요?","options":[{"t":"읽었다는 것과 어떻게 고쳤는지를 알려 주었다","correct":true},{"t":"댓글을 읽고 아무 말도 하지 않았다","mis":"K6-1-u2-X41"},{"t":"승아의 의견이 틀렸다고 말했다","mis":"K6-1-u2-X06"},{"t":"의견을 듣고 글을 처음부터 다시 썼다","mis":"K6-1-u2-X01"}],"explanation":["댓글을 받고 끝내지 않았어요.","고마움을 표현했어요.","한 문장 더 넣어 고친 것을 알렸어요."],"asset":{"type":"speech","turns":[{"who":"승아","text":"도서관마다 숫자가 같은지 궁금하다고 했는데, 나도 그게 궁금했어."},{"who":"다빈","text":"알려 줘서 고마워. 그 부분을 한 문장 더 넣어서 고쳐 뒀어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L09_challenge#3','kor',6,1,'u2','L09','g6_1_kor_u2_L09_challenge','lesson_challenge','K6-1-u2-C32',3,'error','auto','친구 의견을 받아들이는 방법을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u2-X40']::text[],false,'{"seq":3,"concept":"K6-1-u2-C32","difficulty":3,"kind":"error","stem":"친구 의견을 받아들이는 방법을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"하율 — 「친구가 말한 건 다 넣어야 해. 안 넣으면 미안하잖아.」","correct":true,"mis_target":"K6-1-u2-X40"},{"t":"서진 — 「이 의견을 따르면 내가 하려던 말이 더 잘 전해지는지 물어봐.」","mis":"K6-1-u2-X40"},{"t":"라온 — 「따르지 않기로 했으면 까닭을 말할 수 있으면 돼.」","mis":"K6-1-u2-X40"}],"explanation":["서진은 기준을 말했어요.","라온은 까닭을 말했어요.","하율은 의견을 모두 따라야 한다고 여겼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L09_challenge#4','kor',6,1,'u2','L09','g6_1_kor_u2_L09_challenge','lesson_challenge','K6-1-u2-C10',3,'mc','auto','글을 공유하면 좋은 점으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K6-1-u2-X10']::text[],false,'{"seq":4,"concept":"K6-1-u2-C10","difficulty":3,"kind":"mc","stem":"글을 공유하면 좋은 점으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"내 글이 무조건 칭찬받는다","correct":true},{"t":"혼자서는 놓친 곳을 알게 된다","mis":"K6-1-u2-X10"},{"t":"내 글이 어떻게 읽히는지 안다","mis":"K6-1-u2-X10"},{"t":"새로운 생각을 얻는다","mis":"K6-1-u2-X10"}],"explanation":["친구가 못 본 곳을 짚어 줘요.","읽는 사람의 반응을 알아요.","공유는 칭찬받으려는 일이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L09_challenge#5','kor',6,1,'u2','L09','g6_1_kor_u2_L09_challenge','lesson_challenge','K6-1-u2-C35',3,'match','auto','다빈의 글에 넣을 사진과 알맞은 판단을 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-1-u2-C35","difficulty":3,"kind":"match","stem":"다빈의 글에 넣을 사진과 알맞은 판단을 이으세요.","pairs":[{"l":"책등의 숫자가 보이는 서가 사진","r":"내용을 바로 보여 주니 넣는다"},{"l":"도서관 건물 바깥 풍경 사진","r":"설명과 이어지지 않으니 뺀다"},{"l":"남이 찍은 서가 사진","r":"넣으려면 출처를 밝힌다"}],"mis":"K6-1-u2-X43","explanation":["설명을 보여 주는 사진은 넣어요.","겉도는 사진은 빼요.","남의 사진은 출처를 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L09_challenge#6','kor',6,1,'u2','L09','g6_1_kor_u2_L09_challenge','lesson_challenge','K6-1-u2-C34',3,'ox','auto','인공 지능 도구를 쓰면 고칠지 말지도 도구가 정해 줘요.',ARRAY['K6-1-u2-X42']::text[],false,'{"seq":6,"concept":"K6-1-u2-C34","difficulty":3,"kind":"ox","stem":"인공 지능 도구를 쓰면 고칠지 말지도 도구가 정해 줘요.","answer":"X","reason_options":[{"t":"도구는 띄어쓰기 · 맞춤법을 짚어 줄 뿐 고칠지 말지는 글쓴이가 정하기 때문에","correct":true},{"t":"도구가 글쓴이보다 언제나 옳기 때문에","mis":"K6-1-u2-X42"}],"mis":"K6-1-u2-X42","explanation":["도구는 빠르게 짚어 줘요.","중심 생각은 정해 주지 못해요.","까닭을 확인하고 글쓴이가 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L09_challenge#7','kor',6,1,'u2','L09','g6_1_kor_u2_L09_challenge','lesson_challenge','K6-1-u2-C31',3,'mc','auto','「그냥 좋아.」라고만 말하지 않고 네 갈래로 의견을 나누면 좋은 까닭은 무엇인가요?',ARRAY['K6-1-u2-X39','K6-1-u2-X06','K6-1-u2-X07']::text[],false,'{"seq":7,"concept":"K6-1-u2-C31","difficulty":3,"kind":"mc","stem":"「그냥 좋아.」라고만 말하지 않고 네 갈래로 의견을 나누면 좋은 까닭은 무엇인가요?","options":[{"t":"글쓴이가 어디를 살리고 어디를 손볼지 알 수 있는 쓸모 있는 말이 되기 때문에","correct":true},{"t":"의견이 길어져서 멋있어 보이기 때문에","mis":"K6-1-u2-X39"},{"t":"고칠 곳만 말하면 되기 때문에","mis":"K6-1-u2-X06"},{"t":"칭찬을 더 많이 할 수 있기 때문에","mis":"K6-1-u2-X07"}],"explanation":["막연한 말은 도움이 적어요.","네 갈래는 글쓴이에게 쓸모가 있어요.","살릴 곳과 손볼 곳이 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L09_challenge#8','kor',6,1,'u2','L09','g6_1_kor_u2_L09_challenge','lesson_challenge','K6-1-u2-C33',4,'mc','auto','다빈의 글이 공유되고 나서 생긴 일을 가장 알맞게 평가한 것은 어느 것인가요?',ARRAY['K6-1-u2-X40','K6-1-u2-X10','K6-1-u2-X01']::text[],false,'{"seq":8,"concept":"K6-1-u2-C33","difficulty":4,"kind":"mc","stem":"다빈의 글이 공유되고 나서 생긴 일을 가장 알맞게 평가한 것은 어느 것인가요?","options":[{"t":"승아의 궁금한 점을 받아 한 문장을 더 넣고, 정후의 의견은 까닭을 들어 넣지 않아 하려던 말이 더 또렷해졌다","correct":true},{"t":"친구 의견을 하나라도 따르지 않았으니 공유가 실패했다","mis":"K6-1-u2-X40"},{"t":"공유한 뒤에는 더 고치지 않는 것이 맞다","mis":"K6-1-u2-X10"},{"t":"댓글을 읽은 뒤 글을 처음부터 다시 쓴 것이 가장 좋다","mis":"K6-1-u2-X01"}],"explanation":["의견을 골라 받아들였어요.","공유한 뒤 다시 점검했어요.","필요한 곳만 고쳤어요."],"asset":{"type":"speech","turns":[{"who":"승아","text":"도서관마다 숫자가 같은지 궁금하다고 했는데, 나도 그게 궁금했어."},{"who":"다빈","text":"알려 줘서 고마워. 그 부분을 한 문장 더 넣어서 고쳐 뒀어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L09_challenge#9','kor',6,1,'u2','L09','g6_1_kor_u2_L09_challenge','lesson_challenge','K6-1-u2-C31',4,'essay','teacher','다빈의 글 「도서관 책에 붙은 번호」를 읽었다고 생각하고, 의견의 네 갈래(새롭게 안 점 · 궁금한 점 · 좋은 점 · 고쳤으면 하는 점)로 의견을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u2-C31","difficulty":4,"kind":"essay","stem":"다빈의 글 「도서관 책에 붙은 번호」를 읽었다고 생각하고, 의견의 네 갈래(새롭게 안 점 · 궁금한 점 · 좋은 점 · 고쳤으면 하는 점)로 의견을 쓰세요.","answer_guide":{"answer":"예: 새롭게 안 점 — 책등의 숫자가 책의 갈래를 나타낸다는 것을 처음 알았어. 궁금한 점 — 학교 도서관과 동네 도서관의 숫자도 같은지 궁금해. 좋은 점 — 문장이 짧아서 한 번에 읽혔어. 고쳤으면 하는 점 — 의자가 푹신하다는 문장은 숫자 설명과 멀어 보여서 빼면 좋겠어.","scoring_points":["네 갈래를 모두 썼는가","갈래에 맞는 내용을 썼는가","좋은 점과 고칠 점에 까닭을 붙였는가"]},"explanation":["네 갈래를 떠올려요.","갈래마다 알맞은 말을 써요.","까닭을 붙여요."],"asset":{"type":"passage","lines":["숫자를 알면 넓은 서가에서도 책을 빨리 찾을 수 있습니다.","도서관 의자는 푹신합니다.","갈래는 크게 열개로 나뉘고, 같은 갈래의 책은 한곳에 모여 있습니다."],"title":"다빈의 글 「도서관 책에 붙은 번호」 한 문단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L09_challenge#10','kor',6,1,'u2','L09','g6_1_kor_u2_L09_challenge','lesson_challenge','K6-1-u2-C32',4,'essay','teacher','친구에게 받은 의견을 받아들일지 정하는 기준을 쓰고, 다빈이 정후의 의견을 따르지 않은 것이 알맞은지 까닭을 들어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u2-C32","difficulty":4,"kind":"essay","stem":"친구에게 받은 의견을 받아들일지 정하는 기준을 쓰고, 다빈이 정후의 의견을 따르지 않은 것이 알맞은지 까닭을 들어 쓰세요.","answer_guide":{"answer":"예: 의견을 받아들일지는 「이 의견을 따르면 내가 하려던 말이 더 잘 전해지는가?」를 기준으로 정한다. 다빈의 글은 책등의 숫자가 무엇을 뜻하고 어떻게 책을 찾는지 설명하는 글이다. 좋아하는 책 목록을 넣으면 하려던 말과 멀어진다. 그래서 다빈이 고맙다고 말하고 따르지 않은 것은 알맞다.","scoring_points":["받아들이는 기준을 썼는가","다빈의 글이 하려는 말을 썼는가","알맞은지를 까닭과 함께 판단했는가"]},"explanation":["기준을 먼저 써요.","글이 하려는 말과 견주어요.","까닭을 들어 판단해요."],"asset":{"type":"speech","turns":[{"who":"정후","text":"다빈아, 글 끝에 네가 좋아하는 책 목록도 넣으면 어때?"},{"who":"다빈","text":"고맙지만 이 글은 숫자를 설명하는 글이라 그건 안 넣기로 했어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L12_basic#1','kor',6,1,'u2','L12','g6_1_kor_u2_L12_basic','lesson_basic','K6-1-u2-C36',1,'mc','auto','소개하는 글로 쓰기에 알맞은 주제는 어느 것인가요?',ARRAY['K6-1-u2-X36']::text[],false,'{"seq":1,"concept":"K6-1-u2-C36","difficulty":1,"kind":"mc","stem":"소개하는 글로 쓰기에 알맞은 주제는 어느 것인가요?","options":[{"t":"삼 년째 타고 있는 내 낡은 자전거","correct":true},{"t":"세상에 있는 모든 운동","mis":"K6-1-u2-X36"},{"t":"어제 급식에 나온 반찬 이름","mis":"K6-1-u2-X36"},{"t":"우주에 있는 모든 별","mis":"K6-1-u2-X36"}],"explanation":["너무 넓으면 무엇부터 쓸지 몰라요.","너무 좁으면 쓸 말이 없어요.","쓸 말이 세 문단쯤 나오는 것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L12_basic#2','kor',6,1,'u2','L12','g6_1_kor_u2_L12_basic','lesson_basic','K6-1-u2-C36',1,'match','auto','소개하는 글의 문장이 들어갈 곳을 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K6-1-u2-C36","difficulty":1,"kind":"match","stem":"소개하는 글의 문장이 들어갈 곳을 이으세요.","pairs":[{"l":"내가 가장 아끼는 물건은 낡은 자전거이다","r":"처음"},{"l":"손잡이 고무가 닳아 손 모양대로 파여 있다","r":"가운데"},{"l":"고쳐 가며 더 오래 타고 싶다","r":"끝"}],"mis":"K6-1-u2-X12","explanation":["무엇을 소개할지는 처음에 밝혀요.","자세한 모습은 가운데에 써요.","앞으로 하고 싶은 일은 끝에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L12_basic#3','kor',6,1,'u2','L12','g6_1_kor_u2_L12_basic','lesson_basic','K6-1-u2-C37',1,'mc','auto','소개 문장으로 더 좋은 것은 어느 것인가요?',ARRAY['K6-1-u2-X44','K6-1-u2-X45']::text[],false,'{"seq":3,"concept":"K6-1-u2-C37","difficulty":1,"kind":"mc","stem":"소개 문장으로 더 좋은 것은 어느 것인가요?","options":[{"t":"체인이 늘어나 언덕에서 한 번씩 헛돌지만 손보면 다시 잘 간다","correct":true},{"t":"내 자전거가 세상에서 제일 좋은 자전거다","mis":"K6-1-u2-X44"},{"t":"자전거는 바퀴가 두 개인 탈것이다","mis":"K6-1-u2-X45"},{"t":"내 자전거는 정말 정말 멋지다","mis":"K6-1-u2-X44"}],"explanation":["자랑은 읽는 사람이 알 수 있는 것이 없어요.","누구에게나 있는 말은 소개가 아니에요.","그려 볼 수 있게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L12_basic#4','kor',6,1,'u2','L12','g6_1_kor_u2_L12_basic','lesson_basic','K6-1-u2-C38',1,'mc','auto','「어제」와 어울리는 서술어는 어느 것인가요?',ARRAY['K6-1-u2-X20']::text[],false,'{"seq":4,"concept":"K6-1-u2-C38","difficulty":1,"kind":"mc","stem":"「어제」와 어울리는 서술어는 어느 것인가요?","options":[{"t":"보았다","correct":true},{"t":"볼 것이다","mis":"K6-1-u2-X20"},{"t":"본다","mis":"K6-1-u2-X20"},{"t":"보겠다","mis":"K6-1-u2-X20"}],"explanation":["어제는 지난 때예요.","지난 때에는 「~았다」를 써요.","「어제 보았다」로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L12_basic#5','kor',6,1,'u2','L12','g6_1_kor_u2_L12_basic','lesson_basic','K6-1-u2-C18',2,'mc','auto','청아의 초고 「아버지가 이 자전거를 나에게 물려줬다.」를 바르게 고친 것은 어느 것인가요?',ARRAY['K6-1-u2-X20','K6-1-u2-X17','K6-1-u2-X34']::text[],false,'{"seq":5,"concept":"K6-1-u2-C18","difficulty":2,"kind":"mc","stem":"청아의 초고 「아버지가 이 자전거를 나에게 물려줬다.」를 바르게 고친 것은 어느 것인가요?","options":[{"t":"아버지께서 이 자전거를 나에게 물려주셨다.","correct":true},{"t":"아버지가 이 자전거를 나에게 물려준다.","mis":"K6-1-u2-X20"},{"t":"아버지를 이 자전거가 나에게 물려줬다.","mis":"K6-1-u2-X17"},{"t":"이 자전거를 나에게 물려줬다.","mis":"K6-1-u2-X34"}],"explanation":["아버지는 웃어른이에요.","높임 표현으로 받아요.","께서 · ~셨다로 고쳐요."],"asset":{"type":"passage","lines":["내가 가장 아끼는 물건은 자전거이다. 삼년째 타고 있어서 손잡이 고무가","손 모양대로 닳았다. 아버지가 이 자전거를 나에게 물려줬다.","우리 언니는 자전거를 못 탄다.","비 오는 날에는 마루에 들여놓고 마른 천으로 닦아 둔다."],"title":"청아가 쓴 초고 「내 낡은 자전거」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L12_basic#6','kor',6,1,'u2','L12','g6_1_kor_u2_L12_basic','lesson_basic','K6-1-u2-C15',2,'mc','auto','청아의 초고에서 빼야 할 문장은 어느 것인가요?',ARRAY['K6-1-u2-X15','K6-1-u2-X14']::text[],false,'{"seq":6,"concept":"K6-1-u2-C15","difficulty":2,"kind":"mc","stem":"청아의 초고에서 빼야 할 문장은 어느 것인가요?","options":[{"t":"우리 언니는 자전거를 못 탄다.","correct":true},{"t":"손잡이 고무가 손 모양대로 닳았다.","mis":"K6-1-u2-X15"},{"t":"비 오는 날에는 마루에 들여놓고 마른 천으로 닦아 둔다.","mis":"K6-1-u2-X15"},{"t":"내가 가장 아끼는 물건은 자전거이다.","mis":"K6-1-u2-X14"}],"explanation":["글의 중심은 내 자전거예요.","언니 이야기는 내 자전거와 상관없어요.","벗어난 문장은 빼요."],"asset":{"type":"passage","lines":["내가 가장 아끼는 물건은 자전거이다. 삼년째 타고 있어서 손잡이 고무가","손 모양대로 닳았다. 아버지가 이 자전거를 나에게 물려줬다.","우리 언니는 자전거를 못 탄다.","비 오는 날에는 마루에 들여놓고 마른 천으로 닦아 둔다."],"title":"청아가 쓴 초고 「내 낡은 자전거」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L12_basic#7','kor',6,1,'u2','L12','g6_1_kor_u2_L12_basic','lesson_basic','K6-1-u2-C39',2,'blank','auto','「바람에 창문이 (  ).」의 빈칸에 알맞은 말은 어느 것인가요?',ARRAY['K6-1-u2-X47','K6-1-u2-X19','K6-1-u2-X20']::text[],false,'{"seq":7,"concept":"K6-1-u2-C39","difficulty":2,"kind":"blank","stem":"「바람에 창문이 (  ).」의 빈칸에 알맞은 말은 어느 것인가요?","options":[{"t":"닫혔다","correct":true},{"t":"닫았다","mis":"K6-1-u2-X47"},{"t":"닫혀 주었다","mis":"K6-1-u2-X19"},{"t":"닫을 것이다","mis":"K6-1-u2-X20"}],"explanation":["창문은 스스로 닫지 않아요.","바람이라는 다른 힘에 의해 닫혔어요.","당하는 말 「닫혔다」를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L12_basic#8','kor',6,1,'u2','L12','g6_1_kor_u2_L12_basic','lesson_basic','K6-1-u2-C38',2,'mc','auto','「화면이 어둠으로 채웠고」를 바르게 고친 것은 어느 것인가요?',ARRAY['K6-1-u2-X20','K6-1-u2-X34','K6-1-u2-X18']::text[],false,'{"seq":8,"concept":"K6-1-u2-C38","difficulty":2,"kind":"mc","stem":"「화면이 어둠으로 채웠고」를 바르게 고친 것은 어느 것인가요?","options":[{"t":"화면이 어둠으로 채워졌고","correct":true},{"t":"화면이 어둠으로 채울 것이고","mis":"K6-1-u2-X20"},{"t":"화면을 어둠으로 채웠고","mis":"K6-1-u2-X34"},{"t":"화면께서 어둠으로 채우셨고","mis":"K6-1-u2-X18"}],"explanation":["화면은 스스로 채운 것이 아니에요.","다른 힘에 의해 채워졌어요.","「채워졌고」로 받아요."],"asset":{"type":"passage","lines":["나는 어제 나무의 하루를 담은 다큐멘터리를 볼 것이다. 카메라는 한 그루의","나무를 일 년 동안 따라간다. 밤이 되면 나무가 낮에 만든 양분을 줄기 끝으로","보낸다는 사실을 처음 알았다.","가장 놀라운 곳은 뿌리 장면이었다. 화면이 어둠으로 채웠고, 그 속에서 뿌리가","물길을 따라 천천히 뻗어 갔다. 내 생각은 눈에 보이는 것만으로 판단하면 안 된다.","나무가 자란다는 말이 낮에만 해당하는 줄 알았다. 앞으로는 보이지 않는 곳에서","일어나는 일도 함께 헤아려 보고 싶다."],"title":"감상문 「밤에도 자라는 나무」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L12_basic#9','kor',6,1,'u2','L12','g6_1_kor_u2_L12_basic','lesson_basic','K6-1-u2-C24',2,'ox','auto','고쳐쓰기는 맞춤법을 바로잡고 낱말 몇 개를 바꾸는 일이에요.',ARRAY['K6-1-u2-X05']::text[],false,'{"seq":9,"concept":"K6-1-u2-C24","difficulty":2,"kind":"ox","stem":"고쳐쓰기는 맞춤법을 바로잡고 낱말 몇 개를 바꾸는 일이에요.","answer":"X","reason_options":[{"t":"주제에서 벗어난 문단 빼기 · 문단 차례 옮기기 · 부족한 설명 더하기까지 해야 하기 때문에","correct":true},{"t":"맞춤법이 글에서 가장 중요하기 때문에","mis":"K6-1-u2-X05"}],"mis":"K6-1-u2-X05","explanation":["맞춤법만 고치면 멈추기 쉬워요.","글 · 문단을 먼저 봐야 해요.","맞춤법과 띄어쓰기는 마지막에 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L12_basic#10','kor',6,1,'u2','L12','g6_1_kor_u2_L12_basic','lesson_basic','K6-1-u2-C37',3,'mc','auto','친구의 소개하는 글에 의견을 줄 때 알맞은 방법은 어느 것인가요?',ARRAY['K6-1-u2-X06','K6-1-u2-X07','K6-1-u2-X44']::text[],false,'{"seq":10,"concept":"K6-1-u2-C37","difficulty":3,"kind":"mc","stem":"친구의 소개하는 글에 의견을 줄 때 알맞은 방법은 어느 것인가요?","options":[{"t":"잘한 곳을 짚어 주고, 부족한 곳은 까닭과 함께 알려 준다","correct":true},{"t":"부족한 곳만 빠짐없이 적어 준다","mis":"K6-1-u2-X06"},{"t":"제일 좋다고만 말해 준다","mis":"K6-1-u2-X07"},{"t":"내 자전거가 더 좋다고 말한다","mis":"K6-1-u2-X44"}],"explanation":["고칠 곳만 늘어놓으면 위축돼요.","막연한 칭찬은 쓸모가 적어요.","주고받으며 글이 조금씩 나아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L12_challenge#1','kor',6,1,'u2','L12','g6_1_kor_u2_L12_challenge','lesson_challenge','K6-1-u2-C17',2,'mc','auto','청아의 초고에서 「삼년째」를 바르게 고친 것은 어느 것인가요?',ARRAY['K6-1-u2-X25','K6-1-u2-X27','K6-1-u2-X23']::text[],false,'{"seq":1,"concept":"K6-1-u2-C17","difficulty":2,"kind":"mc","stem":"청아의 초고에서 「삼년째」를 바르게 고친 것은 어느 것인가요?","options":[{"t":"삼 년째","correct":true},{"t":"삼년 째","mis":"K6-1-u2-X25"},{"t":"삼 년 째","mis":"K6-1-u2-X27"},{"t":"삼⌒년째","mis":"K6-1-u2-X23"}],"explanation":["「년」은 세는 말이에요.","수와 세는 말은 띄어요.","「째」는 앞말에 붙여 써요."],"asset":{"type":"passage","lines":["내가 가장 아끼는 물건은 자전거이다. 삼년째 타고 있어서 손잡이 고무가","손 모양대로 닳았다. 아버지가 이 자전거를 나에게 물려줬다.","우리 언니는 자전거를 못 탄다.","비 오는 날에는 마루에 들여놓고 마른 천으로 닦아 둔다."],"title":"청아가 쓴 초고 「내 낡은 자전거」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L12_challenge#2','kor',6,1,'u2','L12','g6_1_kor_u2_L12_challenge','lesson_challenge','K6-1-u2-C39',2,'blank','auto','「내가 못을 박고 그림을 (  ).」의 빈칸에 알맞은 말은 어느 것인가요?',ARRAY['K6-1-u2-X47','K6-1-u2-X20']::text[],false,'{"seq":2,"concept":"K6-1-u2-C39","difficulty":2,"kind":"blank","stem":"「내가 못을 박고 그림을 (  ).」의 빈칸에 알맞은 말은 어느 것인가요?","options":[{"t":"걸었다","correct":true},{"t":"걸렸다","mis":"K6-1-u2-X47"},{"t":"걸려 있었다","mis":"K6-1-u2-X47"},{"t":"걸 것이다","mis":"K6-1-u2-X20"}],"explanation":["내가 스스로 한 일이에요.","스스로 하는 일에는 -리-를 붙이지 않아요.","「걸었다」로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L12_challenge#3','kor',6,1,'u2','L12','g6_1_kor_u2_L12_challenge','lesson_challenge','K6-1-u2-C38',3,'error','auto','「밤에도 자라는 나무」의 문장을 고쳤어요. 알맞지 않게 고친 친구는 누구인가요?',ARRAY['K6-1-u2-X20','K6-1-u2-X46']::text[],false,'{"seq":3,"concept":"K6-1-u2-C38","difficulty":3,"kind":"error","stem":"「밤에도 자라는 나무」의 문장을 고쳤어요. 알맞지 않게 고친 친구는 누구인가요?","options":[{"t":"하율 — 「나는 어제 다큐멘터리를 본다.」","correct":true,"mis_target":"K6-1-u2-X20"},{"t":"서진 — 「내 생각은 눈에 보이는 것만으로 판단하면 안 된다는 것이다.」","mis":"K6-1-u2-X46"},{"t":"라온 — 「화면이 어둠으로 채워졌다.」","mis":"K6-1-u2-X46"}],"explanation":["서진은 주어와 서술어 짝을 맞췄어요.","라온은 당하는 말로 받았어요.","하율은 어제와 서술어의 때가 여전히 어긋나요."],"asset":{"type":"passage","lines":["나는 어제 나무의 하루를 담은 다큐멘터리를 볼 것이다. 카메라는 한 그루의","나무를 일 년 동안 따라간다. 밤이 되면 나무가 낮에 만든 양분을 줄기 끝으로","보낸다는 사실을 처음 알았다.","가장 놀라운 곳은 뿌리 장면이었다. 화면이 어둠으로 채웠고, 그 속에서 뿌리가","물길을 따라 천천히 뻗어 갔다. 내 생각은 눈에 보이는 것만으로 판단하면 안 된다.","나무가 자란다는 말이 낮에만 해당하는 줄 알았다. 앞으로는 보이지 않는 곳에서","일어나는 일도 함께 헤아려 보고 싶다."],"title":"감상문 「밤에도 자라는 나무」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L12_challenge#4','kor',6,1,'u2','L12','g6_1_kor_u2_L12_challenge','lesson_challenge','K6-1-u2-C38',3,'mc','auto','「내 생각은 눈에 보이는 것만으로 판단하면 안 된다.」가 어색한 까닭은 무엇인가요?',ARRAY['K6-1-u2-X20','K6-1-u2-X18','K6-1-u2-X05']::text[],false,'{"seq":4,"concept":"K6-1-u2-C38","difficulty":3,"kind":"mc","stem":"「내 생각은 눈에 보이는 것만으로 판단하면 안 된다.」가 어색한 까닭은 무엇인가요?","options":[{"t":"주어 「내 생각은」과 서술어 「안 된다」가 짝이 맞지 않아서","correct":true},{"t":"시간을 나타내는 말이 없어서","mis":"K6-1-u2-X20"},{"t":"높임 표현을 쓰지 않아서","mis":"K6-1-u2-X18"},{"t":"띄어쓰기가 틀려서","mis":"K6-1-u2-X05"}],"explanation":["주어가 「내 생각은」이에요.","서술어는 「~것이다」로 받아야 해요.","주어와 서술어의 짝을 맞춰요."],"asset":{"type":"passage","lines":["나는 어제 나무의 하루를 담은 다큐멘터리를 볼 것이다. 카메라는 한 그루의","나무를 일 년 동안 따라간다. 밤이 되면 나무가 낮에 만든 양분을 줄기 끝으로","보낸다는 사실을 처음 알았다.","가장 놀라운 곳은 뿌리 장면이었다. 화면이 어둠으로 채웠고, 그 속에서 뿌리가","물길을 따라 천천히 뻗어 갔다. 내 생각은 눈에 보이는 것만으로 판단하면 안 된다.","나무가 자란다는 말이 낮에만 해당하는 줄 알았다. 앞으로는 보이지 않는 곳에서","일어나는 일도 함께 헤아려 보고 싶다."],"title":"감상문 「밤에도 자라는 나무」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L12_challenge#5','kor',6,1,'u2','L12','g6_1_kor_u2_L12_challenge','lesson_challenge','K6-1-u2-C39',3,'match','auto','상황에 알맞은 표현을 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-1-u2-C39","difficulty":3,"kind":"match","stem":"상황에 알맞은 표현을 이으세요.","pairs":[{"l":"내가 손으로 창문을","r":"닫았다"},{"l":"언제부터인가 벽에 그림이","r":"걸려 있었다"},{"l":"나는 책상 위에 책을","r":"놓았다"}],"mis":"K6-1-u2-X47","explanation":["내가 스스로 한 일은 주동이에요.","저절로 그리 된 것은 피동이에요.","누가 한 일인지 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L12_challenge#6','kor',6,1,'u2','L12','g6_1_kor_u2_L12_challenge','lesson_challenge','K6-1-u2-C36',3,'mc','auto','청아의 소개하는 글 「가운데」에 넣기 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X45','K6-1-u2-X15','K6-1-u2-X44']::text[],false,'{"seq":6,"concept":"K6-1-u2-C36","difficulty":3,"kind":"mc","stem":"청아의 소개하는 글 「가운데」에 넣기 가장 알맞은 것은 어느 것인가요?","options":[{"t":"비 오는 날마다 마루에 들여놓고 마른 천으로 닦아 두는 이야기","correct":true},{"t":"자전거는 바퀴가 두 개라는 설명","mis":"K6-1-u2-X45"},{"t":"언니가 자전거를 못 탄다는 이야기","mis":"K6-1-u2-X15"},{"t":"내 자전거가 제일 좋다는 말","mis":"K6-1-u2-X44"}],"explanation":["누구의 자전거에나 있는 말은 소개가 아니에요.","상관없는 이야기는 빼요.","그것만의 이야기를 넣어요."],"asset":{"type":"passage","lines":["내가 가장 아끼는 물건은 자전거이다. 삼년째 타고 있어서 손잡이 고무가","손 모양대로 닳았다. 아버지가 이 자전거를 나에게 물려줬다.","우리 언니는 자전거를 못 탄다.","비 오는 날에는 마루에 들여놓고 마른 천으로 닦아 둔다."],"title":"청아가 쓴 초고 「내 낡은 자전거」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L12_challenge#7','kor',6,1,'u2','L12','g6_1_kor_u2_L12_challenge','lesson_challenge','K6-1-u2-C37',3,'ox','auto','소개하는 글은 내가 가진 것이 얼마나 좋은지 자랑하는 글이에요.',ARRAY['K6-1-u2-X44']::text[],false,'{"seq":7,"concept":"K6-1-u2-C37","difficulty":3,"kind":"ox","stem":"소개하는 글은 내가 가진 것이 얼마나 좋은지 자랑하는 글이에요.","answer":"X","reason_options":[{"t":"읽는 사람이 그려 볼 수 있게 어떤 것인지와 나와 얽힌 이야기를 알려 주는 글이기 때문에","correct":true},{"t":"자랑을 많이 할수록 소개가 잘되기 때문에","mis":"K6-1-u2-X44"}],"mis":"K6-1-u2-X44","explanation":["「제일 좋다」로는 알 수 있는 것이 없어요.","어떤 모습인지 자세히 써요.","읽는 사람이 그려 볼 수 있게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L12_challenge#8','kor',6,1,'u2','L12','g6_1_kor_u2_L12_challenge','lesson_challenge','K6-1-u2-C24',4,'mc','auto','청아의 초고를 고치는 계획으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X05','K6-1-u2-X03','K6-1-u2-X01']::text[],false,'{"seq":8,"concept":"K6-1-u2-C24","difficulty":4,"kind":"mc","stem":"청아의 초고를 고치는 계획으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"언니 문장을 빼고, 「삼 년째」로 띄어 쓰고, 「아버지께서 물려주셨다」로 높임을 맞춘다","correct":true},{"t":"「삼 년째」 띄어쓰기만 고친다","mis":"K6-1-u2-X05"},{"t":"언니 문장을 맨 끝으로 옮긴다","mis":"K6-1-u2-X03"},{"t":"글을 다 지우고 다른 물건을 소개한다","mis":"K6-1-u2-X01"}],"explanation":["띄어쓰기만 고치면 부족해요.","벗어난 문장은 옮기지 않고 빼요.","세 수준을 고르게 고쳐요."],"asset":{"type":"passage","lines":["내가 가장 아끼는 물건은 자전거이다. 삼년째 타고 있어서 손잡이 고무가","손 모양대로 닳았다. 아버지가 이 자전거를 나에게 물려줬다.","우리 언니는 자전거를 못 탄다.","비 오는 날에는 마루에 들여놓고 마른 천으로 닦아 둔다."],"title":"청아가 쓴 초고 「내 낡은 자전거」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L12_challenge#9','kor',6,1,'u2','L12','g6_1_kor_u2_L12_challenge','lesson_challenge','K6-1-u2-C36',4,'essay','teacher','내가 관심 있는 것 하나를 골라 처음 · 가운데 · 끝의 짜임으로 소개하는 글을 짧게 쓰고, 가운데에 넣은 「그것만의 이야기」가 무엇인지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u2-C36","difficulty":4,"kind":"essay","stem":"내가 관심 있는 것 하나를 골라 처음 · 가운데 · 끝의 짜임으로 소개하는 글을 짧게 쓰고, 가운데에 넣은 「그것만의 이야기」가 무엇인지 쓰세요.","answer_guide":{"answer":"예: 처음 — 내가 소개할 것은 할머니께서 떠 주신 털모자이다. 겨울마다 가장 먼저 찾는 물건이라 골랐다. 가운데 — 모자 꼭대기의 방울은 한쪽이 조금 작다. 할머니께서 실이 모자라 남은 실로 마저 만드셨기 때문이다. 그래서 나는 이 모자를 쓰면 할머니가 생각난다. 끝 — 올겨울에도 이 모자를 아껴 쓰고, 해진 곳은 직접 꿰매 보고 싶다. 그것만의 이야기 — 한쪽이 작은 방울에 얽힌 이야기.","scoring_points":["처음 · 가운데 · 끝의 짜임으로 썼는가","가운데에 그것만의 이야기를 넣었는가","자랑이 아니라 그려 볼 수 있게 썼는가"]},"explanation":["짜임에 맞춰 써요.","그것만의 이야기를 넣어요.","읽는 사람이 그려 볼 수 있게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L12_challenge#10','kor',6,1,'u2','L12','g6_1_kor_u2_L12_challenge','lesson_challenge','K6-1-u2-C38',4,'essay','teacher','「밤에도 자라는 나무」에서 호응이 어긋난 문장 세 개를 찾아 바르게 고치고, 각각 무엇이 어긋났는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u2-C38","difficulty":4,"kind":"essay","stem":"「밤에도 자라는 나무」에서 호응이 어긋난 문장 세 개를 찾아 바르게 고치고, 각각 무엇이 어긋났는지 쓰세요.","answer_guide":{"answer":"예: 「나는 어제 다큐멘터리를 볼 것이다」 → 「나는 어제 다큐멘터리를 보았다」 — 어제와 서술어의 때가 어긋났다. 「화면이 어둠으로 채웠고」 → 「화면이 어둠으로 채워졌고」 — 화면이 스스로 한 일이 아니어서 당하는 말로 받아야 한다. 「내 생각은 눈에 보이는 것만으로 판단하면 안 된다」 → 「내 생각은 눈에 보이는 것만으로 판단하면 안 된다는 것이다」 — 주어와 서술어의 짝이 어긋났다.","scoring_points":["어긋난 문장 세 개를 찾았는가","바르게 고쳐 썼는가","어긋난 까닭(때 · 피동 · 주어와 서술어 짝)을 썼는가"]},"explanation":["서술어를 짚어 앞말과 견주어요.","알맞게 고쳐 써요.","무엇이 어긋났는지 써요."],"asset":{"type":"passage","lines":["나는 어제 나무의 하루를 담은 다큐멘터리를 볼 것이다. 카메라는 한 그루의","나무를 일 년 동안 따라간다. 밤이 되면 나무가 낮에 만든 양분을 줄기 끝으로","보낸다는 사실을 처음 알았다.","가장 놀라운 곳은 뿌리 장면이었다. 화면이 어둠으로 채웠고, 그 속에서 뿌리가","물길을 따라 천천히 뻗어 갔다. 내 생각은 눈에 보이는 것만으로 판단하면 안 된다.","나무가 자란다는 말이 낮에만 해당하는 줄 알았다. 앞으로는 보이지 않는 곳에서","일어나는 일도 함께 헤아려 보고 싶다."],"title":"감상문 「밤에도 자라는 나무」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#1','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C1',1,'mc','auto','쓴 글을 점검해 하고 싶은 말이 더 잘 전달되도록 필요한 곳만 손보는 일을 무엇이라고 하나요?',ARRAY['K6-1-u2-X01']::text[],false,'{"seq":1,"concept":"K6-1-u2-C1","difficulty":1,"kind":"mc","stem":"쓴 글을 점검해 하고 싶은 말이 더 잘 전달되도록 필요한 곳만 손보는 일을 무엇이라고 하나요?","options":[{"t":"고쳐쓰기","correct":true},{"t":"옮겨 쓰기","mis":"K6-1-u2-X01"},{"t":"다시 쓰기","mis":"K6-1-u2-X01"},{"t":"베껴 쓰기","mis":"K6-1-u2-X01"}],"explanation":["글씨를 옮기는 일이 아니에요.","처음부터 새로 쓰는 일도 아니에요.","필요한 곳만 손보는 일이 고쳐쓰기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#2','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C3',1,'mc','auto','「주어와 서술어가 호응하는가」는 어느 수준에서 살필 일인가요?',ARRAY['K6-1-u2-X04']::text[],false,'{"seq":2,"concept":"K6-1-u2-C3","difficulty":1,"kind":"mc","stem":"「주어와 서술어가 호응하는가」는 어느 수준에서 살필 일인가요?","options":[{"t":"문장 수준","correct":true},{"t":"글 수준","mis":"K6-1-u2-X04"},{"t":"문단 수준","mis":"K6-1-u2-X04"},{"t":"제목 수준","mis":"K6-1-u2-X04"}],"explanation":["한 문장만 봐도 알 수 있어요.","글 전체를 볼 필요는 없어요.","문장 수준의 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#3','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C17',1,'mc','auto','「책」 · 「세」 · 「권」을 바르게 띄어 쓴 것은 어느 것인가요?',ARRAY['K6-1-u2-X25','K6-1-u2-X24']::text[],false,'{"seq":3,"concept":"K6-1-u2-C17","difficulty":1,"kind":"mc","stem":"「책」 · 「세」 · 「권」을 바르게 띄어 쓴 것은 어느 것인가요?","options":[{"t":"책 세 권","correct":true},{"t":"책 세권","mis":"K6-1-u2-X25"},{"t":"책세 권","mis":"K6-1-u2-X24"},{"t":"책세권","mis":"K6-1-u2-X25"}],"explanation":["「권」은 세는 말이에요.","세는 말은 수와 띄어요.","책 ∨ 세 ∨ 권으로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#4','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C21',1,'mc','auto','본 것에 더해 내가 무엇을 느끼고 생각했는지 적는 글을 무엇이라고 하나요?',ARRAY['K6-1-u2-X30']::text[],false,'{"seq":4,"concept":"K6-1-u2-C21","difficulty":1,"kind":"mc","stem":"본 것에 더해 내가 무엇을 느끼고 생각했는지 적는 글을 무엇이라고 하나요?","options":[{"t":"감상문","correct":true},{"t":"줄거리 요약","mis":"K6-1-u2-X30"},{"t":"안내문","mis":"K6-1-u2-X30"},{"t":"일기 예보","mis":"K6-1-u2-X30"}],"explanation":["줄거리 요약은 일어난 일만 적어요.","안내문은 알리는 글이에요.","느끼고 생각한 것을 적는 글은 감상문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#5','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C26',1,'mc','auto','「책등에 붙어 있습니다.」에서 빠진 문장 성분은 무엇인가요?',ARRAY['K6-1-u2-X34']::text[],false,'{"seq":5,"concept":"K6-1-u2-C26","difficulty":1,"kind":"mc","stem":"「책등에 붙어 있습니다.」에서 빠진 문장 성분은 무엇인가요?","options":[{"t":"주어","correct":true},{"t":"목적어","mis":"K6-1-u2-X34"},{"t":"서술어","mis":"K6-1-u2-X34"},{"t":"빠진 것이 없다","mis":"K6-1-u2-X34"}],"explanation":["무엇이 붙어 있는지 없어요.","「무엇이」가 빠졌어요.","주어를 넣어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#6','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C28',1,'mc','auto','자료를 가져온 곳을 밝힌 것을 무엇이라고 하나요?',ARRAY['K6-1-u2-X37']::text[],false,'{"seq":6,"concept":"K6-1-u2-C28","difficulty":1,"kind":"mc","stem":"자료를 가져온 곳을 밝힌 것을 무엇이라고 하나요?","options":[{"t":"출처","correct":true},{"t":"제목","mis":"K6-1-u2-X37"},{"t":"줄거리","mis":"K6-1-u2-X37"},{"t":"댓글","mis":"K6-1-u2-X37"}],"explanation":["어디서 가져왔는지가 출처예요.","제목 · 줄거리와 달라요.","자료를 옮길 때 출처를 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#7','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C39',1,'mc','auto','다른 힘에 의해 그리 되는 일을 나타낸 말은 어느 것인가요?',ARRAY['K6-1-u2-X47']::text[],false,'{"seq":7,"concept":"K6-1-u2-C39","difficulty":1,"kind":"mc","stem":"다른 힘에 의해 그리 되는 일을 나타낸 말은 어느 것인가요?","options":[{"t":"문이 닫히다","correct":true},{"t":"내가 문을 닫다","mis":"K6-1-u2-X47"},{"t":"내가 그림을 걸다","mis":"K6-1-u2-X47"},{"t":"내가 책을 놓다","mis":"K6-1-u2-X47"}],"explanation":["「내가 ~다」는 스스로 한 일이에요.","문은 스스로 닫지 않아요.","「닫히다」는 다른 힘에 의해 그리 된 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#8','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C6',1,'mc','auto','온라인 게시판에 글을 올릴 때 지킬 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X09']::text[],false,'{"seq":8,"concept":"K6-1-u2-C6","difficulty":1,"kind":"mc","stem":"온라인 게시판에 글을 올릴 때 지킬 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"자료를 옮길 때 출처를 밝힌다","correct":true},{"t":"줄임말을 많이 쓴다","mis":"K6-1-u2-X09"},{"t":"은어를 써서 재미있게 쓴다","mis":"K6-1-u2-X09"},{"t":"남의 글을 이름 없이 옮긴다","mis":"K6-1-u2-X09"}],"explanation":["한 번 올린 글은 널리 퍼져요.","줄임말 · 은어 · 비속어를 쓰지 않아요.","출처를 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#9','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C15',2,'mc','auto','하린의 감상문 초고에서 빼야 할 문장은 어느 것인가요?',ARRAY['K6-1-u2-X15','K6-1-u2-X16']::text[],false,'{"seq":9,"concept":"K6-1-u2-C15","difficulty":2,"kind":"mc","stem":"하린의 감상문 초고에서 빼야 할 문장은 어느 것인가요?","options":[{"t":"우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","correct":true},{"t":"손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","mis":"K6-1-u2-X15"},{"t":"배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","mis":"K6-1-u2-X16"},{"t":"나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","mis":"K6-1-u2-X16"}],"explanation":["글의 중심은 연극 「종이배」예요.","놀이터 이야기는 상관없어요.","띄어쓰기가 틀린 문장은 빼지 말고 고쳐요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#10','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C14',2,'mc','auto','하린의 초고에서 「할머니가 ~ 하고 말했다.」를 바르게 고친 것은 어느 것인가요?',ARRAY['K6-1-u2-X20','K6-1-u2-X17','K6-1-u2-X34']::text[],false,'{"seq":10,"concept":"K6-1-u2-C14","difficulty":2,"kind":"mc","stem":"하린의 초고에서 「할머니가 ~ 하고 말했다.」를 바르게 고친 것은 어느 것인가요?","options":[{"t":"할머니께서 ~ 하고 말씀하셨다.","correct":true},{"t":"할머니가 ~ 하고 말할 것이다.","mis":"K6-1-u2-X20"},{"t":"할머니를 ~ 하고 말했다.","mis":"K6-1-u2-X17"},{"t":"~ 하고 말했다.","mis":"K6-1-u2-X34"}],"explanation":["할머니는 웃어른이에요.","높임 표현으로 받아요.","께서 · 말씀하셨다로 고쳐요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#11','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C18',2,'mc','auto','하린의 초고 「학부모 및학생」을 바르게 고친 것은 어느 것인가요?',ARRAY['K6-1-u2-X26','K6-1-u2-X24']::text[],false,'{"seq":11,"concept":"K6-1-u2-C18","difficulty":2,"kind":"mc","stem":"하린의 초고 「학부모 및학생」을 바르게 고친 것은 어느 것인가요?","options":[{"t":"학부모 및 학생","correct":true},{"t":"학부모및학생","mis":"K6-1-u2-X26"},{"t":"학부모및 학생","mis":"K6-1-u2-X26"},{"t":"학 부 모 및 학 생","mis":"K6-1-u2-X24"}],"explanation":["「및」은 잇는 말이에요.","앞뒤를 모두 띄어요.","학부모 ∨ 및 ∨ 학생으로 써요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#12','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C5',2,'mc','auto','하린의 글에 달린 댓글 가운데 가장 알맞은 것은 누구의 댓글인가요?',ARRAY['K6-1-u2-X06','K6-1-u2-X07','K6-1-u2-X08']::text[],false,'{"seq":12,"concept":"K6-1-u2-C5","difficulty":2,"kind":"mc","stem":"하린의 글에 달린 댓글 가운데 가장 알맞은 것은 누구의 댓글인가요?","options":[{"t":"서준","correct":true},{"t":"도윤","mis":"K6-1-u2-X06"},{"t":"채아","mis":"K6-1-u2-X07"},{"t":"셋 다 알맞지 않다","mis":"K6-1-u2-X08"}],"explanation":["도윤은 다시 쓰라고 했어요.","채아는 막연하게 칭찬했어요.","서준은 잘한 곳 → 고칠 곳 → 까닭 차례로 썼어요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"틀린 데가 너무 많아. 처음부터 다시 써."},{"who":"채아","text":"잘 썼네. 고칠 곳 하나도 없어."},{"who":"서준","text":"할머니가 서두르지 않는 장면이 눈에 그려졌어. 놀이터 문장은 연극 이야기와 멀어 보여서 빼면 좋겠어."},{"who":"보미","text":"연극을 보게 된 이야기가 맨 끝에 있어서 조금 헷갈렸어. 맨 앞으로 옮기면 어때?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#13','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C32',2,'mc','auto','하린이 지호의 의견을 넣지 않은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X40','K6-1-u2-X41']::text[],false,'{"seq":13,"concept":"K6-1-u2-C32","difficulty":2,"kind":"mc","stem":"하린이 지호의 의견을 넣지 않은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"「종이배」 감상문이라 다른 연극 이름은 하려던 말과 멀어서","correct":true},{"t":"지호가 친구가 아니어서","mis":"K6-1-u2-X40"},{"t":"의견은 하나도 받지 않기로 해서","mis":"K6-1-u2-X41"},{"t":"다른 연극 이름을 몰라서","mis":"K6-1-u2-X40"}],"explanation":["고르는 것은 글쓴이예요.","하려던 말에 도움이 되는지 봐요.","하린은 까닭을 말했어요."],"asset":{"type":"speech","turns":[{"who":"지호","text":"하린아, 끝에 네가 좋아하는 다른 연극 이름도 다 적으면 어때?"},{"who":"하린","text":"고맙지만 이 글은 「종이배」 감상문이라 그건 넣지 않을래."},{"who":"하린","text":"보미 말대로 연극을 본 이야기는 맨 앞으로 옮겼어. 서준이 말대로 놀이터 문장은 뺐고."},{"who":"하린","text":"띄어쓰기는 검사기를 돌려 봤는데, 왜 그렇게 고쳤는지 하나씩 확인하고 받아들였어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#14','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C25',2,'mc','auto','로운의 글 첫 문장이 한 번에 읽히지 않는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X36','K6-1-u2-X33','K6-1-u2-X18']::text[],false,'{"seq":14,"concept":"K6-1-u2-C25","difficulty":2,"kind":"mc","stem":"로운의 글 첫 문장이 한 번에 읽히지 않는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"한 문장에 여러 가지를 이어 붙이고 「순서」를 되풀이해서","correct":true},{"t":"주제가 텃밭이 아니어서","mis":"K6-1-u2-X36"},{"t":"문장이 너무 짧아서","mis":"K6-1-u2-X33"},{"t":"높임 표현을 써서","mis":"K6-1-u2-X18"}],"explanation":["주제는 텃밭이 맞아요.","한 문장이 너무 길어요.","「순서」가 자꾸 되풀이돼요."],"asset":{"type":"passage","lines":["우리 학교 텃밭에는 물 주는 순서가 있는데 그 순서는 반마다 정해 놓은","순서이고 순서를 지키면 채소가 잘 자라는데 순서를 안 지키면 물을 두 번","주게 되고 그래서 순서를 지켜야 한다.","당번은 아침마다 텃밭에 줍니다.","상추는 물을 많이 주면 뿌리가 썩는다고 누가 그랬다.","텃밭 옆 체육 창고 문은 지난달에 새로 칠했습니다."],"title":"로운이 쓴 설명하는 글 초고 「텃밭 물 주기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#15','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C23',2,'match','auto','감상문의 짜임과 들어갈 내용을 이으세요.','{}'::text[],false,'{"seq":15,"concept":"K6-1-u2-C23","difficulty":2,"kind":"match","stem":"감상문의 짜임과 들어갈 내용을 이으세요.","pairs":[{"l":"처음","r":"무엇을 보았는지와 보게 된 까닭"},{"l":"가운데","r":"간단한 줄거리와 인상 깊은 장면, 그때의 생각"},{"l":"끝","r":"느낀 점과 앞으로 하고 싶은 일"}],"mis":"K6-1-u2-X12","explanation":["처음에는 무엇을 왜 보았는지 써요.","가운데가 가장 길어요.","끝에는 느낀 점과 다짐을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#16','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C35',2,'mc','auto','「텃밭 물 주기」에 넣기 가장 알맞은 사진은 어느 것인가요?',ARRAY['K6-1-u2-X43','K6-1-u2-X09']::text[],false,'{"seq":16,"concept":"K6-1-u2-C35","difficulty":2,"kind":"mc","stem":"「텃밭 물 주기」에 넣기 가장 알맞은 사진은 어느 것인가요?","options":[{"t":"반별 물 주기 순서가 적힌 텃밭 안내판 사진","correct":true},{"t":"학교 정문의 멋진 풍경 사진","mis":"K6-1-u2-X43"},{"t":"체육 창고 문 사진","mis":"K6-1-u2-X43"},{"t":"남이 찍은 텃밭 사진을 출처 없이","mis":"K6-1-u2-X09"}],"explanation":["보기 좋아도 내용과 멀면 빼요.","남의 사진은 출처를 밝혀요.","설명을 바로 보여 주는 사진을 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#17','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C8',3,'mc','auto','하린의 초고 제목 「종이배 이야기」를 고친 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X11','K6-1-u2-X36']::text[],false,'{"seq":17,"concept":"K6-1-u2-C8","difficulty":3,"kind":"mc","stem":"하린의 초고 제목 「종이배 이야기」를 고친 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"서두르지 않는 손이 가르쳐 준 것","correct":true},{"t":"종이배 연극 줄거리","mis":"K6-1-u2-X11"},{"t":"우리 동네 놀이터","mis":"K6-1-u2-X36"},{"t":"토요일 강당","mis":"K6-1-u2-X11"}],"explanation":["지금 제목에는 느낀 것이 없어요.","줄거리 · 장소만 알리는 제목은 부족해요.","가장 하고 싶었던 말을 제목에 담아요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#18','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C15',3,'ox','auto','글 수준을 고치다가 띄어쓰기 틀린 곳이 보이면 나중에 따로 보려고 미뤄 두어야 해요.',ARRAY['K6-1-u2-X22']::text[],false,'{"seq":18,"concept":"K6-1-u2-C15","difficulty":3,"kind":"ox","stem":"글 수준을 고치다가 띄어쓰기 틀린 곳이 보이면 나중에 따로 보려고 미뤄 두어야 해요.","answer":"X","reason_options":[{"t":"세 수준은 따로 도는 절차가 아니라 보이는 그때그때 함께 고치는 것이기 때문에","correct":true},{"t":"반드시 글 → 문단 → 문장을 세 번 나누어 해야 하기 때문에","mis":"K6-1-u2-X22"}],"mis":"K6-1-u2-X22","explanation":["큰 것부터 보는 것은 맞아요.","보이는 것은 그때 함께 고쳐요.","부호로 표시해 두면 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#19','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C10',3,'mc','auto','하린의 감상문 중심 내용을 두 친구가 다르게 말했어요. 둘 다 좋은 답이 되는 조건은 무엇인가요?',ARRAY['K6-1-u2-X13']::text[],false,'{"seq":19,"concept":"K6-1-u2-C10","difficulty":3,"kind":"mc","stem":"하린의 감상문 중심 내용을 두 친구가 다르게 말했어요. 둘 다 좋은 답이 되는 조건은 무엇인가요?","options":[{"t":"둘 다 글에서 근거를 댈 수 있어야 한다","correct":true},{"t":"둘 가운데 먼저 말한 쪽만 맞다","mis":"K6-1-u2-X13"},{"t":"선생님이 정한 답과 같아야 한다","mis":"K6-1-u2-X13"},{"t":"근거는 없어도 느낌이 같으면 된다","mis":"K6-1-u2-X13"}],"explanation":["중심 내용은 여럿일 수 있어요.","정답 하나를 찾는 일이 아니에요.","근거를 댈 수 있는지가 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#20','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C25',3,'mc','auto','로운의 글 첫 문장을 잘 나눈 것은 어느 것인가요?',ARRAY['K6-1-u2-X33','K6-1-u2-X34','K6-1-u2-X35']::text[],false,'{"seq":20,"concept":"K6-1-u2-C25","difficulty":3,"kind":"mc","stem":"로운의 글 첫 문장을 잘 나눈 것은 어느 것인가요?","options":[{"t":"우리 학교 텃밭에는 물 주는 순서가 있습니다. 반마다 정한 순서입니다. 순서를 지키면 물을 두 번 주는 일이 없습니다.","correct":true},{"t":"우리 학교 텃밭에는 순서가 있는데 반마다 정했고 지키면 잘 자라고 안 지키면 두 번 주고 그래서 지켜야 한다.","mis":"K6-1-u2-X33"},{"t":"텃밭. 순서. 반마다. 두 번.","mis":"K6-1-u2-X34"},{"t":"순서 순서 순서를 지켜야 합니다.","mis":"K6-1-u2-X35"}],"explanation":["이어 붙이면 여전히 길어요.","너무 줄이면 성분이 빠져요.","한 문장에 한 가지씩, 성분을 갖춰요."],"asset":{"type":"passage","lines":["우리 학교 텃밭에는 물 주는 순서가 있는데 그 순서는 반마다 정해 놓은","순서이고 순서를 지키면 채소가 잘 자라는데 순서를 안 지키면 물을 두 번","주게 되고 그래서 순서를 지켜야 한다.","당번은 아침마다 텃밭에 줍니다.","상추는 물을 많이 주면 뿌리가 썩는다고 누가 그랬다.","텃밭 옆 체육 창고 문은 지난달에 새로 칠했습니다."],"title":"로운이 쓴 설명하는 글 초고 「텃밭 물 주기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#21','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C37',3,'mc','auto','「종이배」 연극을 소개하는 문장으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X44','K6-1-u2-X45']::text[],false,'{"seq":21,"concept":"K6-1-u2-C37","difficulty":3,"kind":"mc","stem":"「종이배」 연극을 소개하는 문장으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"할머니는 손녀가 배를 찢을 때마다 새 종이를 건네며 「천천히」라고만 말한다","correct":true},{"t":"이 연극은 세상에서 제일 재미있는 연극이다","mis":"K6-1-u2-X44"},{"t":"연극은 무대에서 배우가 하는 공연이다","mis":"K6-1-u2-X45"},{"t":"정말 정말 꼭 보세요","mis":"K6-1-u2-X44"}],"explanation":["자랑은 알 수 있는 것이 없어요.","누구에게나 있는 말은 소개가 아니에요.","그려 볼 수 있게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#22','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C33',3,'mc','auto','하린이 고쳐 쓴 글을 공유한 뒤 할 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X41','K6-1-u2-X10','K6-1-u2-X01']::text[],false,'{"seq":22,"concept":"K6-1-u2-C33","difficulty":3,"kind":"mc","stem":"하린이 고쳐 쓴 글을 공유한 뒤 할 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"달린 댓글을 읽고 답글로 어떻게 했는지 알린 뒤 다시 점검한다","correct":true},{"t":"올리고 바로 끝낸다","mis":"K6-1-u2-X41"},{"t":"칭찬 댓글만 남기고 나머지는 지운다","mis":"K6-1-u2-X10"},{"t":"댓글을 받으면 글을 처음부터 다시 쓴다","mis":"K6-1-u2-X01"}],"explanation":["올리고 끝내지 않아요.","공유는 칭찬받으려는 일이 아니에요.","읽었다는 것과 어떻게 했는지 알려요."],"asset":{"type":"speech","turns":[{"who":"지호","text":"하린아, 끝에 네가 좋아하는 다른 연극 이름도 다 적으면 어때?"},{"who":"하린","text":"고맙지만 이 글은 「종이배」 감상문이라 그건 넣지 않을래."},{"who":"하린","text":"보미 말대로 연극을 본 이야기는 맨 앞으로 옮겼어. 서준이 말대로 놀이터 문장은 뺐고."},{"who":"하린","text":"띄어쓰기는 검사기를 돌려 봤는데, 왜 그렇게 고쳤는지 하나씩 확인하고 받아들였어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#23','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C24',4,'mc','auto','하린의 초고를 가장 알맞게 고친 계획은 어느 것인가요?',ARRAY['K6-1-u2-X05','K6-1-u2-X01','K6-1-u2-X03']::text[],false,'{"seq":23,"concept":"K6-1-u2-C24","difficulty":4,"kind":"mc","stem":"하린의 초고를 가장 알맞게 고친 계획은 어느 것인가요?","options":[{"t":"제목에 생각 담기 → 연극을 본 이야기를 맨 앞으로 옮기기 → 놀이터 문장 빼기 → 높임 · 부정 호응 고치기 → 띄어쓰기 고치기","correct":true},{"t":"띄어쓰기 고치기 → 맞춤법 고치기 → 끝","mis":"K6-1-u2-X05"},{"t":"글을 지우고 다른 연극으로 새로 쓰기","mis":"K6-1-u2-X01"},{"t":"놀이터 문장을 맨 앞으로 옮기기 → 나머지는 그대로","mis":"K6-1-u2-X03"}],"explanation":["맞춤법만으로는 부족해요.","다시 쓰지 않아요.","큰 것부터 고르게 고쳐요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#24','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C24',4,'essay','teacher','하린의 감상문 초고에서 고칠 곳을 글 · 문단 · 문장 수준에서 하나 이상씩 찾고, 어떤 차례로 고칠지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u2-C24","difficulty":4,"kind":"essay","stem":"하린의 감상문 초고에서 고칠 곳을 글 · 문단 · 문장 수준에서 하나 이상씩 찾고, 어떤 차례로 고칠지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 글 수준 — 제목 「종이배 이야기」에 느낀 것이 없고, 연극을 본 이야기가 맨 끝에 있어 차례가 뒤엉켰다. 문단 수준 — 「우리 동네 놀이터에는 새 미끄럼틀이 생겼다」는 연극과 상관없다. 문장 수준 — 「할머니가 말했다」는 「할머니께서 말씀하셨다」로, 「전혀 지루했다」는 「전혀 지루하지 않았다」로, 「두척」 · 「줄수」 · 「및학생」은 띄어 써야 한다. 제목과 차례 → 놀이터 문장 빼기 → 호응 → 띄어쓰기 차례로 고치겠다. 큰 것부터 고쳐야 다듬은 문장이 빠지는 헛수고가 없기 때문이다.","scoring_points":["글 수준의 고칠 곳을 찾았는가","문단 · 문장 수준의 고칠 곳을 찾았는가","큰 것부터의 차례와 까닭을 썼는가"]},"explanation":["세 수준으로 나누어 찾아요.","빠짐없이 찾아요.","큰 것부터의 까닭을 써요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#25','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C1',4,'essay','teacher','이 단원에서 배운 「고쳐쓰기」를 설명하고, 고쳐쓰기가 다시 쓰기나 맞춤법 고치기와 어떻게 다른지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u2-C1","difficulty":4,"kind":"essay","stem":"이 단원에서 배운 「고쳐쓰기」를 설명하고, 고쳐쓰기가 다시 쓰기나 맞춤법 고치기와 어떻게 다른지 쓰세요.","answer_guide":{"answer":"예: 고쳐쓰기는 쓴 글을 글 · 문단 · 문장의 세 수준으로 점검해서 하고 싶은 말이 더 잘 전해지도록 필요한 곳만 빼고 · 더하고 · 바꾸고 · 옮기는 일이다. 다시 쓰기는 처음 쓴 글을 버리고 새로 쓰는 일이라 다르다. 또 맞춤법이나 띄어쓰기만 고치는 것은 문장 수준의 일부일 뿐이어서, 주제에서 벗어난 문장을 빼거나 문단 차례를 옮기는 일까지 해야 고쳐쓰기이다.","scoring_points":["고쳐쓰기를 세 수준과 네 가지 손질로 설명했는가","다시 쓰기와의 차이를 썼는가","맞춤법 고치기와의 차이를 썼는가"]},"explanation":["세 수준과 네 가지 손질을 떠올려요.","다시 쓰기와 견주어요.","맞춤법 고치기와 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#1','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C1',1,'ox','auto','고쳐쓰기는 처음 쓴 글을 버리고 새로 쓰는 일이에요.',ARRAY['K6-1-u2-X01']::text[],false,'{"seq":1,"concept":"K6-1-u2-C1","difficulty":1,"kind":"ox","stem":"고쳐쓰기는 처음 쓴 글을 버리고 새로 쓰는 일이에요.","answer":"X","reason_options":[{"t":"처음 쓴 글을 살리면서 필요한 곳만 손보는 일이기 때문에","correct":true},{"t":"처음 쓴 글은 언제나 쓸모없기 때문에","mis":"K6-1-u2-X01"}],"mis":"K6-1-u2-X01","explanation":["고쳐쓰기는 다시 쓰기가 아니에요.","점검한 내용을 바탕으로 해요.","필요한 곳만 손봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#2','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C3',1,'mc','auto','「처음 · 가운데 · 끝의 흐름이 자연스러운가」는 어느 수준에서 살필 일인가요?',ARRAY['K6-1-u2-X04','K6-1-u2-X05']::text[],false,'{"seq":2,"concept":"K6-1-u2-C3","difficulty":1,"kind":"mc","stem":"「처음 · 가운데 · 끝의 흐름이 자연스러운가」는 어느 수준에서 살필 일인가요?","options":[{"t":"글 수준","correct":true},{"t":"문장 수준","mis":"K6-1-u2-X04"},{"t":"낱말 수준","mis":"K6-1-u2-X04"},{"t":"띄어쓰기 수준","mis":"K6-1-u2-X05"}],"explanation":["흐름은 글 전체를 봐야 보여요.","한 문장으로는 알 수 없어요.","글 수준의 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#3','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C18',1,'mc','auto','「아침」 · 「겸」 · 「점심」을 바르게 띄어 쓴 것은 어느 것인가요?',ARRAY['K6-1-u2-X26']::text[],false,'{"seq":3,"concept":"K6-1-u2-C18","difficulty":1,"kind":"mc","stem":"「아침」 · 「겸」 · 「점심」을 바르게 띄어 쓴 것은 어느 것인가요?","options":[{"t":"아침 겸 점심","correct":true},{"t":"아침겸점심","mis":"K6-1-u2-X26"},{"t":"아침 겸점심","mis":"K6-1-u2-X26"},{"t":"아침겸 점심","mis":"K6-1-u2-X26"}],"explanation":["「겸」은 두 말을 잇는 말이에요.","잇는 말은 앞뒤를 띄어요.","아침 ∨ 겸 ∨ 점심으로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#4','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C23',1,'mc','auto','감상문의 「처음」에 쓸 내용으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X12','K6-1-u2-X32']::text[],false,'{"seq":4,"concept":"K6-1-u2-C23","difficulty":1,"kind":"mc","stem":"감상문의 「처음」에 쓸 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"무엇을 보았는지와 보게 된 까닭","correct":true},{"t":"느낀 점과 다짐","mis":"K6-1-u2-X12"},{"t":"인상 깊은 장면과 생각","mis":"K6-1-u2-X12"},{"t":"모든 장면의 차례","mis":"K6-1-u2-X32"}],"explanation":["다짐은 끝에 써요.","인상 깊은 장면은 가운데에 써요.","처음에는 무엇을 왜 보았는지 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#5','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C26',1,'mc','auto','「나는 서가에서 찾았습니다.」에서 빠진 문장 성분은 무엇인가요?',ARRAY['K6-1-u2-X34']::text[],false,'{"seq":5,"concept":"K6-1-u2-C26","difficulty":1,"kind":"mc","stem":"「나는 서가에서 찾았습니다.」에서 빠진 문장 성분은 무엇인가요?","options":[{"t":"목적어","correct":true},{"t":"주어","mis":"K6-1-u2-X34"},{"t":"서술어","mis":"K6-1-u2-X34"},{"t":"빠진 것이 없다","mis":"K6-1-u2-X34"}],"explanation":["누가 찾았는지는 있어요.","무엇을 찾았는지가 없어요.","목적어를 넣어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#6','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C31',1,'mc','auto','「도서관마다 숫자가 같은지 궁금해.」는 의견의 네 갈래 가운데 무엇인가요?',ARRAY['K6-1-u2-X39']::text[],false,'{"seq":6,"concept":"K6-1-u2-C31","difficulty":1,"kind":"mc","stem":"「도서관마다 숫자가 같은지 궁금해.」는 의견의 네 갈래 가운데 무엇인가요?","options":[{"t":"궁금한 점","correct":true},{"t":"새롭게 안 점","mis":"K6-1-u2-X39"},{"t":"좋은 점","mis":"K6-1-u2-X39"},{"t":"고쳤으면 하는 점","mis":"K6-1-u2-X39"}],"explanation":["더 알고 싶은 것을 말했어요.","잘했다는 말이 아니에요.","궁금한 점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#7','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C39',1,'mc','auto','내가 스스로 하는 일을 나타낸 말은 어느 것인가요?',ARRAY['K6-1-u2-X47']::text[],false,'{"seq":7,"concept":"K6-1-u2-C39","difficulty":1,"kind":"mc","stem":"내가 스스로 하는 일을 나타낸 말은 어느 것인가요?","options":[{"t":"내가 그림을 걸다","correct":true},{"t":"그림이 걸리다","mis":"K6-1-u2-X47"},{"t":"책이 놓이다","mis":"K6-1-u2-X47"},{"t":"문이 닫히다","mis":"K6-1-u2-X47"}],"explanation":["「~리다 · ~이다 · ~히다」는 그리 된 일이에요.","내가 직접 한 일을 찾아요.","「그림을 걸다」가 스스로 한 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#8','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C4',1,'mc','auto','고쳐 쓴 글을 다른 사람과 나누면 좋은 점은 어느 것인가요?',ARRAY['K6-1-u2-X10','K6-1-u2-X05']::text[],false,'{"seq":8,"concept":"K6-1-u2-C4","difficulty":1,"kind":"mc","stem":"고쳐 쓴 글을 다른 사람과 나누면 좋은 점은 어느 것인가요?","options":[{"t":"읽는 사람의 반응을 바로 알 수 있다","correct":true},{"t":"글을 더 고치지 않아도 된다","mis":"K6-1-u2-X10"},{"t":"무조건 칭찬을 받는다","mis":"K6-1-u2-X10"},{"t":"맞춤법을 몰라도 된다","mis":"K6-1-u2-X05"}],"explanation":["나눈 뒤에도 다시 점검해요.","칭찬받으려는 일이 아니에요.","반응을 알면 고쳐쓰기에 도움이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#9','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C12',2,'mc','auto','하린의 초고에서 「배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.」는 어떻게 하는 것이 알맞은가요?',ARRAY['K6-1-u2-X16','K6-1-u2-X03','K6-1-u2-X25']::text[],false,'{"seq":9,"concept":"K6-1-u2-C12","difficulty":2,"kind":"mc","stem":"하린의 초고에서 「배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.」는 어떻게 하는 것이 알맞은가요?","options":[{"t":"빼지 않고 「두 척」으로 띄어 고쳐 쓴다","correct":true},{"t":"띄어쓰기가 틀렸으니 문장을 통째로 지운다","mis":"K6-1-u2-X16"},{"t":"놀이터 문장 뒤로 옮긴다","mis":"K6-1-u2-X03"},{"t":"그대로 둔다","mis":"K6-1-u2-X25"}],"explanation":["마지막 장면은 연극과 관련이 있어요.","틀린 곳은 띄어쓰기뿐이에요.","지우지 말고 고쳐요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#10','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C14',2,'mc','auto','「나는 그 장면이 전혀 지루했다.」에서 어긋난 것은 무엇인가요?',ARRAY['K6-1-u2-X18','K6-1-u2-X20','K6-1-u2-X34']::text[],false,'{"seq":10,"concept":"K6-1-u2-C14","difficulty":2,"kind":"mc","stem":"「나는 그 장면이 전혀 지루했다.」에서 어긋난 것은 무엇인가요?","options":[{"t":"「전혀」 뒤에 부정하는 서술어가 오지 않았다","correct":true},{"t":"높임 표현이 빠졌다","mis":"K6-1-u2-X18"},{"t":"시간을 나타내는 말이 없다","mis":"K6-1-u2-X20"},{"t":"주어가 빠졌다","mis":"K6-1-u2-X34"}],"explanation":["「전혀」는 부정과 어울려요.","「지루하지 않았다」로 받아야 해요.","부정 호응이 어긋났어요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#11','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C19',2,'mc','auto','하린의 초고 「기다려 줄수 있는」을 바르게 고친 것은 어느 것인가요?',ARRAY['K6-1-u2-X28','K6-1-u2-X24']::text[],false,'{"seq":11,"concept":"K6-1-u2-C19","difficulty":2,"kind":"mc","stem":"하린의 초고 「기다려 줄수 있는」을 바르게 고친 것은 어느 것인가요?","options":[{"t":"기다려 줄 수 있는","correct":true},{"t":"기다려줄수있는","mis":"K6-1-u2-X28"},{"t":"기다려 줄수있는","mis":"K6-1-u2-X28"},{"t":"기다려 줄 수있는","mis":"K6-1-u2-X24"}],"explanation":["「수」는 홀로 못 쓰는 이름씨예요.","앞말과 띄어 써요.","「있는」도 띄어 써요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#12','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C31',2,'mc','auto','보미의 댓글은 의견의 네 갈래 가운데 무엇인가요?',ARRAY['K6-1-u2-X39']::text[],false,'{"seq":12,"concept":"K6-1-u2-C31","difficulty":2,"kind":"mc","stem":"보미의 댓글은 의견의 네 갈래 가운데 무엇인가요?","options":[{"t":"고쳤으면 하는 점","correct":true},{"t":"새롭게 안 점","mis":"K6-1-u2-X39"},{"t":"궁금한 점","mis":"K6-1-u2-X39"},{"t":"좋은 점","mis":"K6-1-u2-X39"}],"explanation":["맨 앞으로 옮기자고 했어요.","헷갈린 까닭도 말했어요.","고칠 곳과 까닭은 고쳤으면 하는 점이에요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"틀린 데가 너무 많아. 처음부터 다시 써."},{"who":"채아","text":"잘 썼네. 고칠 곳 하나도 없어."},{"who":"서준","text":"할머니가 서두르지 않는 장면이 눈에 그려졌어. 놀이터 문장은 연극 이야기와 멀어 보여서 빼면 좋겠어."},{"who":"보미","text":"연극을 보게 된 이야기가 맨 끝에 있어서 조금 헷갈렸어. 맨 앞으로 옮기면 어때?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#13','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C34',2,'mc','auto','하린이 맞춤법 검사기를 쓴 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X42','K6-1-u2-X41']::text[],false,'{"seq":13,"concept":"K6-1-u2-C34","difficulty":2,"kind":"mc","stem":"하린이 맞춤법 검사기를 쓴 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"고친 곳을 하나씩 왜 그렇게 고쳤는지 확인하고 받아들였다","correct":true},{"t":"검사기가 고친 대로 모두 받아들였다","mis":"K6-1-u2-X42"},{"t":"검사기가 감상문 제목까지 정해 주었다","mis":"K6-1-u2-X42"},{"t":"검사기를 썼으니 다시 읽지 않았다","mis":"K6-1-u2-X41"}],"explanation":["까닭을 확인했어요.","중심 생각은 도구가 정하지 못해요.","고칠지 말지는 하린이 정했어요."],"asset":{"type":"speech","turns":[{"who":"지호","text":"하린아, 끝에 네가 좋아하는 다른 연극 이름도 다 적으면 어때?"},{"who":"하린","text":"고맙지만 이 글은 「종이배」 감상문이라 그건 넣지 않을래."},{"who":"하린","text":"보미 말대로 연극을 본 이야기는 맨 앞으로 옮겼어. 서준이 말대로 놀이터 문장은 뺐고."},{"who":"하린","text":"띄어쓰기는 검사기를 돌려 봤는데, 왜 그렇게 고쳤는지 하나씩 확인하고 받아들였어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#14','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C26',2,'mc','auto','「당번은 아침마다 텃밭에 줍니다.」에서 빠진 것은 무엇인가요?',ARRAY['K6-1-u2-X34']::text[],false,'{"seq":14,"concept":"K6-1-u2-C26","difficulty":2,"kind":"mc","stem":"「당번은 아침마다 텃밭에 줍니다.」에서 빠진 것은 무엇인가요?","options":[{"t":"무엇을 주는지(목적어)","correct":true},{"t":"누가 주는지(주어)","mis":"K6-1-u2-X34"},{"t":"어찌하는지(서술어)","mis":"K6-1-u2-X34"},{"t":"빠진 것이 없다","mis":"K6-1-u2-X34"}],"explanation":["당번이 주어예요.","「줍니다」가 서술어예요.","「물을」이 빠졌어요."],"asset":{"type":"passage","lines":["우리 학교 텃밭에는 물 주는 순서가 있는데 그 순서는 반마다 정해 놓은","순서이고 순서를 지키면 채소가 잘 자라는데 순서를 안 지키면 물을 두 번","주게 되고 그래서 순서를 지켜야 한다.","당번은 아침마다 텃밭에 줍니다.","상추는 물을 많이 주면 뿌리가 썩는다고 누가 그랬다.","텃밭 옆 체육 창고 문은 지난달에 새로 칠했습니다."],"title":"로운이 쓴 설명하는 글 초고 「텃밭 물 주기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#15','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C36',2,'match','auto','소개하는 글의 짜임과 들어갈 내용을 이으세요.','{}'::text[],false,'{"seq":15,"concept":"K6-1-u2-C36","difficulty":2,"kind":"match","stem":"소개하는 글의 짜임과 들어갈 내용을 이으세요.","pairs":[{"l":"처음","r":"무엇을 소개할지와 고른 까닭"},{"l":"가운데","r":"어떤 것인지와 나와 얽힌 이야기"},{"l":"끝","r":"소개를 맺으며 앞으로 하고 싶은 일"}],"mis":"K6-1-u2-X12","explanation":["처음에 무엇을 왜 골랐는지 밝혀요.","가운데에 그것만의 이야기를 넣어요.","끝에 앞으로의 일을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#16','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C30',2,'mc','auto','책에서 찾은 상추 기르기 설명을 글에 쓰는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X38','K6-1-u2-X09']::text[],false,'{"seq":16,"concept":"K6-1-u2-C30","difficulty":2,"kind":"mc","stem":"책에서 찾은 상추 기르기 설명을 글에 쓰는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"읽고 이해한 뒤 내 말로 바꾸어 쓰고 책 이름을 적는다","correct":true},{"t":"그대로 붙여 넣는다","mis":"K6-1-u2-X38"},{"t":"그대로 옮기고 책 이름은 적지 않는다","mis":"K6-1-u2-X09"},{"t":"줄임말로 짧게 바꾼다","mis":"K6-1-u2-X09"}],"explanation":["그대로 옮긴 문장은 내 글이 아니에요.","출처를 밝혀요.","이해한 것을 내 말로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#17','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C24',3,'mc','auto','하린의 초고를 고칠 때 가장 먼저 할 일은 어느 것인가요?',ARRAY['K6-1-u2-X05','K6-1-u2-X01']::text[],false,'{"seq":17,"concept":"K6-1-u2-C24","difficulty":3,"kind":"mc","stem":"하린의 초고를 고칠 때 가장 먼저 할 일은 어느 것인가요?","options":[{"t":"제목을 고치고 연극을 본 이야기를 맨 앞으로 옮긴다","correct":true},{"t":"「두척」 띄어쓰기부터 고친다","mis":"K6-1-u2-X05"},{"t":"글씨를 예쁘게 다시 옮겨 쓴다","mis":"K6-1-u2-X01"},{"t":"맞춤법만 한 번에 고치고 끝낸다","mis":"K6-1-u2-X05"}],"explanation":["작은 것부터 하면 헛수고가 생겨요.","옮겨 쓰기는 고쳐쓰기가 아니에요.","글 수준부터 잡아요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#18','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C15',3,'mc','auto','하린의 초고에서 「배 두척」을 고칠 때 쓸 부호와 쓰임을 바르게 짝 지은 것은 어느 것인가요?',ARRAY['K6-1-u2-X23','K6-1-u2-X29']::text[],false,'{"seq":18,"concept":"K6-1-u2-C15","difficulty":3,"kind":"mc","stem":"하린의 초고에서 「배 두척」을 고칠 때 쓸 부호와 쓰임을 바르게 짝 지은 것은 어느 것인가요?","options":[{"t":"두∨척 — 띄어 쓸 곳에 ∨","correct":true},{"t":"두⌒척 — 띄어 쓸 곳에 ⌒","mis":"K6-1-u2-X23"},{"t":"두⊂척 — 띄어 쓸 곳에 ⊂","mis":"K6-1-u2-X23"},{"t":"부호 없이 문장을 다시 쓴다","mis":"K6-1-u2-X29"}],"explanation":["⌒ 는 붙일 때 써요.","⊂ 는 더 넣을 때 써요.","띄울 곳에는 ∨ 예요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#19','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C11',3,'mc','auto','하린의 감상문에서 중심 생각을 가장 잘 담은 문장은 어느 것인가요?',ARRAY['K6-1-u2-X15','K6-1-u2-X14']::text[],false,'{"seq":19,"concept":"K6-1-u2-C11","difficulty":3,"kind":"mc","stem":"하린의 감상문에서 중심 생각을 가장 잘 담은 문장은 어느 것인가요?","options":[{"t":"나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄 수 있는 사람이 되겠다.","correct":true},{"t":"우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","mis":"K6-1-u2-X15"},{"t":"배 두 척을 강물에 띄우는 마지막 장면도 기억에 남는다.","mis":"K6-1-u2-X14"},{"t":"지난 토요일 학교 강당에서 연극을 보았다.","mis":"K6-1-u2-X14"}],"explanation":["놀이터 문장은 상관없어요.","장면 · 본 때는 뒷받침이에요.","하린이 하고 싶은 말은 기다려 주는 마음이에요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#20','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C27',3,'mc','auto','로운의 글 제목으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X36','K6-1-u2-X11']::text[],false,'{"seq":20,"concept":"K6-1-u2-C27","difficulty":3,"kind":"mc","stem":"로운의 글 제목으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"반마다 순서가 있는 텃밭 물 주기","correct":true},{"t":"세상의 모든 채소","mis":"K6-1-u2-X36"},{"t":"체육 창고 이야기","mis":"K6-1-u2-X36"},{"t":"우리 학교","mis":"K6-1-u2-X11"}],"explanation":["너무 넓은 제목은 내용과 달라요.","창고는 내용과 상관없어요.","내용과 일치하고 짧게 지어요."],"asset":{"type":"passage","lines":["우리 학교 텃밭에는 물 주는 순서가 있는데 그 순서는 반마다 정해 놓은","순서이고 순서를 지키면 채소가 잘 자라는데 순서를 안 지키면 물을 두 번","주게 되고 그래서 순서를 지켜야 한다.","당번은 아침마다 텃밭에 줍니다.","상추는 물을 많이 주면 뿌리가 썩는다고 누가 그랬다.","텃밭 옆 체육 창고 문은 지난달에 새로 칠했습니다."],"title":"로운이 쓴 설명하는 글 초고 「텃밭 물 주기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#21','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C39',3,'match','auto','책상과 문에 일어난 일에 알맞은 표현을 이으세요.','{}'::text[],false,'{"seq":21,"concept":"K6-1-u2-C39","difficulty":3,"kind":"match","stem":"책상과 문에 일어난 일에 알맞은 표현을 이으세요.","pairs":[{"l":"내가 책상 위에 책을","r":"놓았다"},{"l":"언제부터인가 책상 위에 책이","r":"놓여 있었다"},{"l":"바람에 문이","r":"닫혔다"}],"mis":"K6-1-u2-X47","explanation":["내가 한 일은 주동이에요.","저절로 그리 된 것은 피동이에요.","바람이라는 다른 힘이 닫았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#22','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C20',3,'mc','auto','하린이 「나는 「수」를 자주 붙여 써.」라고 알게 되었어요. 다음에 할 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X24','K6-1-u2-X29','K6-1-u2-X42']::text[],false,'{"seq":22,"concept":"K6-1-u2-C20","difficulty":3,"kind":"mc","stem":"하린이 「나는 「수」를 자주 붙여 써.」라고 알게 되었어요. 다음에 할 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"다음 글을 쓸 때 「수」 앞뒤를 꼭 확인하기로 정해 둔다","correct":true},{"t":"띄어쓰기는 원래 어려우니 신경 쓰지 않는다","mis":"K6-1-u2-X24"},{"t":"틀릴 때마다 글을 처음부터 다시 쓴다","mis":"K6-1-u2-X29"},{"t":"검사기가 알아서 고쳐 주니 확인하지 않는다","mis":"K6-1-u2-X42"}],"explanation":["띄어쓰기는 뜻 문제예요.","다시 쓰지 않아도 돼요.","내 버릇 한 가지를 정해 챙겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#23','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C32',4,'mc','auto','하린이 받은 의견을 처리한 방법을 평가한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X40','K6-1-u2-X01','K6-1-u2-X42']::text[],false,'{"seq":23,"concept":"K6-1-u2-C32","difficulty":4,"kind":"mc","stem":"하린이 받은 의견을 처리한 방법을 평가한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"하려던 말에 도움이 되는 보미 · 서준의 의견은 받아들이고, 지호의 의견은 까닭을 들어 넣지 않아 알맞다","correct":true},{"t":"지호의 의견도 꼭 넣었어야 했다","mis":"K6-1-u2-X40"},{"t":"도윤이 말대로 처음부터 다시 썼어야 했다","mis":"K6-1-u2-X01"},{"t":"검사기가 고친 대로 받아들였으니 알맞다","mis":"K6-1-u2-X42"}],"explanation":["의견을 모두 따를 필요는 없어요.","다시 쓰지 않아요.","하린은 까닭을 확인했어요."],"asset":{"type":"speech","turns":[{"who":"지호","text":"하린아, 끝에 네가 좋아하는 다른 연극 이름도 다 적으면 어때?"},{"who":"하린","text":"고맙지만 이 글은 「종이배」 감상문이라 그건 넣지 않을래."},{"who":"하린","text":"보미 말대로 연극을 본 이야기는 맨 앞으로 옮겼어. 서준이 말대로 놀이터 문장은 뺐고."},{"who":"하린","text":"띄어쓰기는 검사기를 돌려 봤는데, 왜 그렇게 고쳤는지 하나씩 확인하고 받아들였어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#24','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C5',4,'essay','teacher','하린의 글에 달린 도윤이와 채아의 댓글이 왜 알맞지 않은지 쓰고, 두 사람의 댓글을 알맞게 고쳐 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u2-C5","difficulty":4,"kind":"essay","stem":"하린의 글에 달린 도윤이와 채아의 댓글이 왜 알맞지 않은지 쓰고, 두 사람의 댓글을 알맞게 고쳐 쓰세요.","answer_guide":{"answer":"예: 도윤이는 고칠 곳만 말하고 다시 쓰라고 해서 하린이가 위축될 수 있다. 채아는 「고칠 곳 하나도 없어」라고 막연하게 칭찬해서 하린이에게 쓸모 있는 말이 되지 못한다. 고친 도윤이 댓글 — 「할머니 대사를 그대로 넣어서 장면이 생생했어. 「할머니가 말했다」는 「할머니께서 말씀하셨다」로 고치면 더 좋겠어. 할머니는 웃어른이니까.」 고친 채아 댓글 — 「마지막 다짐이 마음에 남았어. 다만 놀이터 문장은 연극과 멀어 보여서 빼면 좋겠어.」","scoring_points":["도윤이 댓글의 문제를 썼는가","채아 댓글의 문제를 썼는가","잘한 곳 → 고칠 곳 → 까닭 차례로 고쳐 썼는가"]},"explanation":["두 댓글의 문제를 찾아요.","왜 알맞지 않은지 써요.","잘한 곳 · 고칠 곳 · 까닭으로 고쳐요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"틀린 데가 너무 많아. 처음부터 다시 써."},{"who":"채아","text":"잘 썼네. 고칠 곳 하나도 없어."},{"who":"서준","text":"할머니가 서두르지 않는 장면이 눈에 그려졌어. 놀이터 문장은 연극 이야기와 멀어 보여서 빼면 좋겠어."},{"who":"보미","text":"연극을 보게 된 이야기가 맨 끝에 있어서 조금 헷갈렸어. 맨 앞으로 옮기면 어때?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#25','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C16',4,'essay','teacher','띄어쓰기를 「글씨 문제가 아니라 뜻 문제」라고 하는 까닭을 예를 들어 설명하고, 띄어쓰기 원리 두 가지를 예와 함께 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u2-C16","difficulty":4,"kind":"essay","stem":"띄어쓰기를 「글씨 문제가 아니라 뜻 문제」라고 하는 까닭을 예를 들어 설명하고, 띄어쓰기 원리 두 가지를 예와 함께 쓰세요.","answer_guide":{"answer":"예: 「큰집에 다녀왔다」와 「큰 집에 다녀왔다」는 띄어쓰기 하나로 친척 어른 댁과 크기가 큰 집으로 뜻이 갈린다. 읽는 사람은 글쓴이의 마음을 볼 수 없어서 띄어쓰기로 뜻을 알아내므로 띄어쓰기는 뜻 문제이다. 원리 첫째, 세는 말은 앞의 수와 띄어 써서 「나무 두 그루」처럼 쓴다. 둘째, 잇는 말은 앞뒤를 띄어 써서 「학생 및 학부모」처럼 쓴다.","scoring_points":["뜻이 갈리는 예를 들었는가","뜻 문제인 까닭을 썼는가","띄어쓰기 원리 두 가지를 예와 함께 썼는가"]},"explanation":["뜻이 갈리는 예를 들어요.","읽는 사람의 처지에서 써요.","원리를 예와 함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#1','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C2',1,'mc','auto','글에 부족한 내용이 있을 때 하는 손질은 어느 것인가요?',ARRAY['K6-1-u2-X03','K6-1-u2-X01']::text[],false,'{"seq":1,"concept":"K6-1-u2-C2","difficulty":1,"kind":"mc","stem":"글에 부족한 내용이 있을 때 하는 손질은 어느 것인가요?","options":[{"t":"더하기","correct":true},{"t":"빼기","mis":"K6-1-u2-X03"},{"t":"옮기기","mis":"K6-1-u2-X03"},{"t":"지우고 다시 쓰기","mis":"K6-1-u2-X01"}],"explanation":["벗어난 것은 빼요.","뒤엉킨 것은 옮겨요.","모자란 것은 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#2','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C3',1,'mc','auto','「상관없는 뒷받침 문장은 없는가」는 어느 수준에서 살필 일인가요?',ARRAY['K6-1-u2-X04','K6-1-u2-X05']::text[],false,'{"seq":2,"concept":"K6-1-u2-C3","difficulty":1,"kind":"mc","stem":"「상관없는 뒷받침 문장은 없는가」는 어느 수준에서 살필 일인가요?","options":[{"t":"문단 수준","correct":true},{"t":"글 수준","mis":"K6-1-u2-X04"},{"t":"문장 수준","mis":"K6-1-u2-X04"},{"t":"맞춤법 수준","mis":"K6-1-u2-X05"}],"explanation":["뒷받침 문장은 문단 안에 있어요.","중심 문장과 견주어 봐요.","문단 수준의 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#3','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C19',1,'mc','auto','「할수있다」를 바르게 띄어 쓴 것은 어느 것인가요?',ARRAY['K6-1-u2-X28','K6-1-u2-X24']::text[],false,'{"seq":3,"concept":"K6-1-u2-C19","difficulty":1,"kind":"mc","stem":"「할수있다」를 바르게 띄어 쓴 것은 어느 것인가요?","options":[{"t":"할 수 있다","correct":true},{"t":"할수있다","mis":"K6-1-u2-X28"},{"t":"할수 있다","mis":"K6-1-u2-X28"},{"t":"할 수있다","mis":"K6-1-u2-X24"}],"explanation":["「수」는 홀로 못 쓰는 이름씨예요.","앞말과 띄어 써요.","「있다」도 띄어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#4','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C22',1,'ox','auto','감상문에는 인상 깊은 장면과 함께 그 장면이 왜 남았는지도 써요.',ARRAY['K6-1-u2-X31']::text[],false,'{"seq":4,"concept":"K6-1-u2-C22","difficulty":1,"kind":"ox","stem":"감상문에는 인상 깊은 장면과 함께 그 장면이 왜 남았는지도 써요.","answer":"O","reason_options":[{"t":"까닭까지 써야 내가 느끼고 생각한 것이 드러나기 때문에","correct":true},{"t":"장면만 고르면 까닭은 읽는 사람이 알아서 짐작하기 때문에","mis":"K6-1-u2-X31"}],"mis":"K6-1-u2-X31","explanation":["「좋았다」로 끝내지 않아요.","왜 남았는지 써요.","그래야 감상문이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#5','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C25',1,'mc','auto','한 문장이 너무 길 때 고치는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X33','K6-1-u2-X34','K6-1-u2-X35']::text[],false,'{"seq":5,"concept":"K6-1-u2-C25","difficulty":1,"kind":"mc","stem":"한 문장이 너무 길 때 고치는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"한 가지씩 담기도록 여러 문장으로 나눈다","correct":true},{"t":"문장을 더 이어 붙인다","mis":"K6-1-u2-X33"},{"t":"주어와 서술어를 뺀다","mis":"K6-1-u2-X34"},{"t":"같은 낱말을 더 넣는다","mis":"K6-1-u2-X35"}],"explanation":["이어 붙이면 더 길어져요.","성분을 빼면 뜻이 흐려져요.","한 문장에 한 가지씩 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#6','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C31',1,'mc','auto','「숫자에 뜻이 있는 줄 몰랐어.」는 의견의 네 갈래 가운데 무엇인가요?',ARRAY['K6-1-u2-X39']::text[],false,'{"seq":6,"concept":"K6-1-u2-C31","difficulty":1,"kind":"mc","stem":"「숫자에 뜻이 있는 줄 몰랐어.」는 의견의 네 갈래 가운데 무엇인가요?","options":[{"t":"새롭게 안 점","correct":true},{"t":"궁금한 점","mis":"K6-1-u2-X39"},{"t":"좋은 점","mis":"K6-1-u2-X39"},{"t":"고쳤으면 하는 점","mis":"K6-1-u2-X39"}],"explanation":["몰랐던 것이에요.","이제 알게 되었어요.","새롭게 안 점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#7','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C38',1,'mc','auto','「내일」과 어울리는 서술어는 어느 것인가요?',ARRAY['K6-1-u2-X20','K6-1-u2-X18']::text[],false,'{"seq":7,"concept":"K6-1-u2-C38","difficulty":1,"kind":"mc","stem":"「내일」과 어울리는 서술어는 어느 것인가요?","options":[{"t":"갈 것이다","correct":true},{"t":"갔다","mis":"K6-1-u2-X20"},{"t":"간다","mis":"K6-1-u2-X20"},{"t":"가셨다","mis":"K6-1-u2-X18"}],"explanation":["내일은 아직 오지 않은 때예요.","앞으로의 일에는 「~ㄹ 것이다」를 써요.","「내일 갈 것이다」로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#8','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C33',1,'ox','auto','글을 게시판에 올린 뒤에는 제대로 올라갔는지 다시 들어가 확인해요.',ARRAY['K6-1-u2-X41']::text[],false,'{"seq":8,"concept":"K6-1-u2-C33","difficulty":1,"kind":"ox","stem":"글을 게시판에 올린 뒤에는 제대로 올라갔는지 다시 들어가 확인해요.","answer":"O","reason_options":[{"t":"올린 뒤 확인하고 댓글을 읽으며 다시 점검하는 것까지가 공유하기이기 때문에","correct":true},{"t":"한 번 올리면 다시 볼 필요가 없기 때문에","mis":"K6-1-u2-X41"}],"mis":"K6-1-u2-X41","explanation":["올리고 끝내지 않아요.","확인하고 댓글을 읽어요.","다시 점검해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#9','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C15',2,'ox','auto','하린의 초고에서 놀이터 문장은 연극 이야기와 상관없어서 빼는 것이 알맞아요.',ARRAY['K6-1-u2-X15']::text[],false,'{"seq":9,"concept":"K6-1-u2-C15","difficulty":2,"kind":"ox","stem":"하린의 초고에서 놀이터 문장은 연극 이야기와 상관없어서 빼는 것이 알맞아요.","answer":"O","reason_options":[{"t":"감상문의 중심인 연극 「종이배」와 이어지지 않는 문장이기 때문에","correct":true},{"t":"놀이터 이야기는 재미가 없기 때문에","mis":"K6-1-u2-X15"}],"mis":"K6-1-u2-X15","explanation":["중심과 견주어 봐요.","놀이터는 연극과 상관없어요.","벗어난 문장은 빼요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#10','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C14',2,'match','auto','하린의 초고 문장과 어긋난 갈래를 이으세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u2-C14","difficulty":2,"kind":"match","stem":"하린의 초고 문장과 어긋난 갈래를 이으세요.","pairs":[{"l":"할머니가 말했다","r":"높임"},{"l":"전혀 지루했다","r":"부정"},{"l":"배 두척","r":"띄어쓰기"}],"mis":"K6-1-u2-X04","explanation":["웃어른에게는 높임을 써요.","전혀 뒤에는 부정이 와요.","세는 말은 띄어요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#11','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C20',2,'mc','auto','하린의 초고에서 띄어 쓸 곳을 부호로 바르게 표시한 것은 어느 것인가요?',ARRAY['K6-1-u2-X23','K6-1-u2-X29']::text[],false,'{"seq":11,"concept":"K6-1-u2-C20","difficulty":2,"kind":"mc","stem":"하린의 초고에서 띄어 쓸 곳을 부호로 바르게 표시한 것은 어느 것인가요?","options":[{"t":"두∨척 · 및∨학생 · 줄∨수","correct":true},{"t":"두⌒척 · 및⌒학생 · 줄⌒수","mis":"K6-1-u2-X23"},{"t":"두⊂척 · 및⊂학생 · 줄⊂수","mis":"K6-1-u2-X23"},{"t":"부호 없이 글을 처음부터 다시 쓴다","mis":"K6-1-u2-X29"}],"explanation":["⌒ 는 붙일 때 써요.","⊂ 는 내용을 더 넣을 때 써요.","띄울 곳에는 ∨ 를 표시해요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#12','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C5',2,'ox','auto','도윤이의 댓글은 하린이가 다시 고쳐 쓰고 싶어지게 하는 좋은 댓글이에요.',ARRAY['K6-1-u2-X06']::text[],false,'{"seq":12,"concept":"K6-1-u2-C5","difficulty":2,"kind":"ox","stem":"도윤이의 댓글은 하린이가 다시 고쳐 쓰고 싶어지게 하는 좋은 댓글이에요.","answer":"X","reason_options":[{"t":"고칠 곳만 말하고 다시 쓰라고 해 글쓴이를 위축시키기 때문에","correct":true},{"t":"틀린 곳을 많이 말해 줄수록 좋은 댓글이기 때문에","mis":"K6-1-u2-X06"}],"mis":"K6-1-u2-X06","explanation":["잘한 곳이 하나도 없어요.","까닭도 없어요.","글쓴이가 쓰기 싫어질 수 있어요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"틀린 데가 너무 많아. 처음부터 다시 써."},{"who":"채아","text":"잘 썼네. 고칠 곳 하나도 없어."},{"who":"서준","text":"할머니가 서두르지 않는 장면이 눈에 그려졌어. 놀이터 문장은 연극 이야기와 멀어 보여서 빼면 좋겠어."},{"who":"보미","text":"연극을 보게 된 이야기가 맨 끝에 있어서 조금 헷갈렸어. 맨 앞으로 옮기면 어때?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#13','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C32',2,'ox','auto','하린은 보미와 서준의 의견은 받아들이고 지호의 의견은 받아들이지 않았어요.',ARRAY['K6-1-u2-X40']::text[],false,'{"seq":13,"concept":"K6-1-u2-C32","difficulty":2,"kind":"ox","stem":"하린은 보미와 서준의 의견은 받아들이고 지호의 의견은 받아들이지 않았어요.","answer":"O","reason_options":[{"t":"하려던 말이 더 잘 전해지는 의견만 골라 받아들였기 때문에","correct":true},{"t":"친구 의견은 모두 따라야 하기 때문에","mis":"K6-1-u2-X40"}],"mis":"K6-1-u2-X40","explanation":["보미 — 차례 옮기기를 받아들였어요.","서준 — 놀이터 문장 빼기를 받아들였어요.","지호의 의견은 까닭을 들어 넣지 않았어요."],"asset":{"type":"speech","turns":[{"who":"지호","text":"하린아, 끝에 네가 좋아하는 다른 연극 이름도 다 적으면 어때?"},{"who":"하린","text":"고맙지만 이 글은 「종이배」 감상문이라 그건 넣지 않을래."},{"who":"하린","text":"보미 말대로 연극을 본 이야기는 맨 앞으로 옮겼어. 서준이 말대로 놀이터 문장은 뺐고."},{"who":"하린","text":"띄어쓰기는 검사기를 돌려 봤는데, 왜 그렇게 고쳤는지 하나씩 확인하고 받아들였어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#14','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C28',2,'mc','auto','「상추는 물을 많이 주면 뿌리가 썩는다고 누가 그랬다.」의 문제로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X15','K6-1-u2-X33','K6-1-u2-X05']::text[],false,'{"seq":14,"concept":"K6-1-u2-C28","difficulty":2,"kind":"mc","stem":"「상추는 물을 많이 주면 뿌리가 썩는다고 누가 그랬다.」의 문제로 알맞은 것은 어느 것인가요?","options":[{"t":"누가 언제 한 말인지 알 수 없어 확인되지 않은 자료이다","correct":true},{"t":"상추는 텃밭과 상관없다","mis":"K6-1-u2-X15"},{"t":"문장이 너무 짧다","mis":"K6-1-u2-X33"},{"t":"띄어쓰기가 틀렸다","mis":"K6-1-u2-X05"}],"explanation":["상추는 텃밭과 관련 있어요.","「누가 그랬다」는 확인할 수 없어요.","믿을 수 있는 자료로 바꾸고 출처를 밝혀요."],"asset":{"type":"passage","lines":["우리 학교 텃밭에는 물 주는 순서가 있는데 그 순서는 반마다 정해 놓은","순서이고 순서를 지키면 채소가 잘 자라는데 순서를 안 지키면 물을 두 번","주게 되고 그래서 순서를 지켜야 한다.","당번은 아침마다 텃밭에 줍니다.","상추는 물을 많이 주면 뿌리가 썩는다고 누가 그랬다.","텃밭 옆 체육 창고 문은 지난달에 새로 칠했습니다."],"title":"로운이 쓴 설명하는 글 초고 「텃밭 물 주기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#15','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C29',2,'match','auto','설명하는 글 「텃밭 물 주기」의 내용이 들어갈 곳을 이으세요.','{}'::text[],false,'{"seq":15,"concept":"K6-1-u2-C29","difficulty":2,"kind":"match","stem":"설명하는 글 「텃밭 물 주기」의 내용이 들어갈 곳을 이으세요.","pairs":[{"l":"텃밭에 물 주는 순서가 왜 있는지 궁금하지 않나요?","r":"처음"},{"l":"반마다 요일을 나누어 아침에 물을 줍니다","r":"가운데"},{"l":"순서를 지키면 채소도 우리도 편해집니다","r":"끝"}],"mis":"K6-1-u2-X12","explanation":["관심을 끄는 말은 처음이에요.","자세한 설명은 가운데예요.","간추려 맺는 말은 끝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#16','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C6',2,'ox','auto','온라인에 한 번 올린 글은 널리 퍼질 수 있으므로 읽는 사람을 떠올리며 써야 해요.',ARRAY['K6-1-u2-X09']::text[],false,'{"seq":16,"concept":"K6-1-u2-C6","difficulty":2,"kind":"ox","stem":"온라인에 한 번 올린 글은 널리 퍼질 수 있으므로 읽는 사람을 떠올리며 써야 해요.","answer":"O","reason_options":[{"t":"여러 사람이 읽고 퍼질 수 있어 읽는 사람이 누구인지가 고칠 때의 기준이 되기 때문에","correct":true},{"t":"올린 글은 금방 사라지기 때문에","mis":"K6-1-u2-X09"}],"mis":"K6-1-u2-X09","explanation":["올린 글은 널리 퍼져요.","읽는 사람을 떠올려요.","그것이 고쳐쓰기의 기준이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#17','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C22',3,'ox','auto','하린은 할머니가 서두르지 않는 장면을 고르고 그 까닭을 「나도 기다려 줄 수 있는 사람이 되겠다」로 이어 썼어요.',ARRAY['K6-1-u2-X31']::text[],false,'{"seq":17,"concept":"K6-1-u2-C22","difficulty":3,"kind":"ox","stem":"하린은 할머니가 서두르지 않는 장면을 고르고 그 까닭을 「나도 기다려 줄 수 있는 사람이 되겠다」로 이어 썼어요.","answer":"O","reason_options":[{"t":"인상 깊은 장면과 그 장면에서 얻은 생각을 이어 썼기 때문에","correct":true},{"t":"장면만 쓰면 감상문이 되기 때문에","mis":"K6-1-u2-X31"}],"mis":"K6-1-u2-X31","explanation":["장면을 골랐어요.","그 장면에서 생각한 것을 썼어요.","장면과 까닭이 이어져요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#18','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C2',3,'mc','auto','하린의 초고에 해야 할 손질을 바르게 짝 지은 것은 어느 것인가요?',ARRAY['K6-1-u2-X03','K6-1-u2-X01','K6-1-u2-X05']::text[],false,'{"seq":18,"concept":"K6-1-u2-C2","difficulty":3,"kind":"mc","stem":"하린의 초고에 해야 할 손질을 바르게 짝 지은 것은 어느 것인가요?","options":[{"t":"놀이터 문장 — 빼기 · 연극을 본 이야기 — 옮기기 · 「전혀 지루했다」 — 바꾸기","correct":true},{"t":"놀이터 문장 — 옮기기 · 연극을 본 이야기 — 빼기 · 「전혀 지루했다」 — 더하기","mis":"K6-1-u2-X03"},{"t":"모든 문장 — 지우고 다시 쓰기","mis":"K6-1-u2-X01"},{"t":"놀이터 문장 — 그대로 · 연극을 본 이야기 — 그대로 · 띄어쓰기만 바꾸기","mis":"K6-1-u2-X05"}],"explanation":["벗어난 것은 빼요.","뒤엉킨 것은 옮겨요.","어색한 표현은 바꿔요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#19','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C10',3,'ox','auto','하린의 감상문 중심 내용을 「서두르지 않는 마음」으로도, 「가르쳐 주는 사람의 기다림」으로도 볼 수 있어요.',ARRAY['K6-1-u2-X13']::text[],false,'{"seq":19,"concept":"K6-1-u2-C10","difficulty":3,"kind":"ox","stem":"하린의 감상문 중심 내용을 「서두르지 않는 마음」으로도, 「가르쳐 주는 사람의 기다림」으로도 볼 수 있어요.","answer":"O","reason_options":[{"t":"두 가지 모두 할머니 장면과 하린의 다짐에서 근거를 댈 수 있기 때문에","correct":true},{"t":"중심 내용은 아무렇게나 정해도 되기 때문에","mis":"K6-1-u2-X13"}],"mis":"K6-1-u2-X13","explanation":["할머니는 서두르지 않았어요.","하린은 기다려 주겠다고 했어요.","근거가 있으면 둘 다 좋은 답이에요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#20','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C28',3,'mc','auto','「누가 그랬다」를 고치는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X37','K6-1-u2-X38']::text[],false,'{"seq":20,"concept":"K6-1-u2-C28","difficulty":3,"kind":"mc","stem":"「누가 그랬다」를 고치는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"학교 텃밭 담당 선생님이나 믿을 수 있는 책에서 확인하고 출처를 밝혀 쓴다","correct":true},{"t":"그대로 둔다","mis":"K6-1-u2-X37"},{"t":"「인터넷에서 봤다」로만 바꾼다","mis":"K6-1-u2-X37"},{"t":"그 문장을 다른 글에서 그대로 베껴 온다","mis":"K6-1-u2-X38"}],"explanation":["확인되지 않은 말은 쓰지 않아요.","「인터넷」만으로는 누가 언제 썼는지 몰라요.","확인하고 출처를 밝혀요."],"asset":{"type":"passage","lines":["우리 학교 텃밭에는 물 주는 순서가 있는데 그 순서는 반마다 정해 놓은","순서이고 순서를 지키면 채소가 잘 자라는데 순서를 안 지키면 물을 두 번","주게 되고 그래서 순서를 지켜야 한다.","당번은 아침마다 텃밭에 줍니다.","상추는 물을 많이 주면 뿌리가 썩는다고 누가 그랬다.","텃밭 옆 체육 창고 문은 지난달에 새로 칠했습니다."],"title":"로운이 쓴 설명하는 글 초고 「텃밭 물 주기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#21','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C38',3,'error','auto','문장을 고쳤어요. 알맞지 않게 고친 친구는 누구인가요?',ARRAY['K6-1-u2-X20','K6-1-u2-X46']::text[],false,'{"seq":21,"concept":"K6-1-u2-C38","difficulty":3,"kind":"error","stem":"문장을 고쳤어요. 알맞지 않게 고친 친구는 누구인가요?","options":[{"t":"하율 — 「내일 우리 반은 텃밭에 물을 주었다.」","correct":true,"mis_target":"K6-1-u2-X20"},{"t":"서진 — 「어제 우리 반은 텃밭에 물을 주었다.」","mis":"K6-1-u2-X46"},{"t":"라온 — 「텃밭이 물로 채워졌다.」","mis":"K6-1-u2-X46"}],"explanation":["서진은 어제와 「주었다」를 맞췄어요.","라온은 당하는 말로 받았어요.","하율은 내일과 「주었다」가 어긋나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#22','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C16',3,'ox','auto','「아버지가방에들어가신다」는 띄어쓰기에 따라 뜻이 달라질 수 있어요.',ARRAY['K6-1-u2-X24']::text[],false,'{"seq":22,"concept":"K6-1-u2-C16","difficulty":3,"kind":"ox","stem":"「아버지가방에들어가신다」는 띄어쓰기에 따라 뜻이 달라질 수 있어요.","answer":"O","reason_options":[{"t":"「아버지가 방에」와 「아버지 가방에」처럼 어디서 띄느냐에 따라 뜻이 갈리기 때문에","correct":true},{"t":"붙여 써도 뜻은 하나뿐이기 때문에","mis":"K6-1-u2-X24"}],"mis":"K6-1-u2-X24","explanation":["「가방」으로 읽을 수도 있어요.","「가 ∨ 방」으로 읽을 수도 있어요.","띄어쓰기가 뜻을 갈라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#23','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C29',4,'mc','auto','로운의 글을 가장 알맞게 고친 계획은 어느 것인가요?',ARRAY['K6-1-u2-X33','K6-1-u2-X37','K6-1-u2-X38']::text[],false,'{"seq":23,"concept":"K6-1-u2-C29","difficulty":4,"kind":"mc","stem":"로운의 글을 가장 알맞게 고친 계획은 어느 것인가요?","options":[{"t":"첫 문장을 나누고 · 「물을」을 넣고 · 확인되지 않은 상추 문장은 확인 뒤 출처를 밝히고 · 창고 문장은 뺀다","correct":true},{"t":"첫 문장을 더 길게 이어 붙인다","mis":"K6-1-u2-X33"},{"t":"창고 문장은 두고 상추 문장은 그대로 쓴다","mis":"K6-1-u2-X37"},{"t":"찾은 자료를 그대로 붙여 넣어 글을 늘린다","mis":"K6-1-u2-X38"}],"explanation":["길게 이으면 더 안 읽혀요.","확인되지 않은 자료는 쓰지 않아요.","나누고 · 채우고 · 확인하고 · 빼요."],"asset":{"type":"passage","lines":["우리 학교 텃밭에는 물 주는 순서가 있는데 그 순서는 반마다 정해 놓은","순서이고 순서를 지키면 채소가 잘 자라는데 순서를 안 지키면 물을 두 번","주게 되고 그래서 순서를 지켜야 한다.","당번은 아침마다 텃밭에 줍니다.","상추는 물을 많이 주면 뿌리가 썩는다고 누가 그랬다.","텃밭 옆 체육 창고 문은 지난달에 새로 칠했습니다."],"title":"로운이 쓴 설명하는 글 초고 「텃밭 물 주기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#24','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C25',4,'essay','teacher','로운의 설명하는 글 초고를 명확한 문장의 조건과 자료 확인을 생각하며 고쳐 쓰고, 무엇을 고쳤는지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u2-C25","difficulty":4,"kind":"essay","stem":"로운의 설명하는 글 초고를 명확한 문장의 조건과 자료 확인을 생각하며 고쳐 쓰고, 무엇을 고쳤는지 쓰세요.","answer_guide":{"answer":"예: 우리 학교 텃밭에는 물 주는 순서가 있습니다. 이 순서는 반마다 정해 둔 것입니다. 순서를 지키면 같은 곳에 물을 두 번 주는 일이 없어 채소가 잘 자랍니다. 당번은 아침마다 텃밭에 물을 줍니다. 상추는 물을 너무 많이 주면 뿌리가 상할 수 있어 조심해야 한다고 텃밭 담당 선생님께서 알려 주셨습니다. — 긴 첫 문장을 나누고, 되풀이되던 「순서」를 줄이고, 빠진 「물을」을 넣고, 「누가 그랬다」를 확인한 출처로 바꾸고, 창고 문장을 뺐다.","scoring_points":["긴 문장을 나누고 겹치는 표현을 줄였는가","빠진 성분을 채웠는가","확인되지 않은 자료와 상관없는 문장을 고쳤는가"]},"explanation":["한 문장에 한 가지씩 나눠요.","빠진 성분을 채워요.","자료를 확인하고 벗어난 문장을 빼요."],"asset":{"type":"passage","lines":["우리 학교 텃밭에는 물 주는 순서가 있는데 그 순서는 반마다 정해 놓은","순서이고 순서를 지키면 채소가 잘 자라는데 순서를 안 지키면 물을 두 번","주게 되고 그래서 순서를 지켜야 한다.","당번은 아침마다 텃밭에 줍니다.","상추는 물을 많이 주면 뿌리가 썩는다고 누가 그랬다.","텃밭 옆 체육 창고 문은 지난달에 새로 칠했습니다."],"title":"로운이 쓴 설명하는 글 초고 「텃밭 물 주기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#25','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C38',4,'essay','teacher','「어제」 · 「내 생각은」 · 「화면이」로 시작하는 문장을 하나씩 호응이 맞게 쓰고, 각 문장에서 서술어를 어떻게 맞추었는지 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u2-C38","difficulty":4,"kind":"essay","stem":"「어제」 · 「내 생각은」 · 「화면이」로 시작하는 문장을 하나씩 호응이 맞게 쓰고, 각 문장에서 서술어를 어떻게 맞추었는지 설명하세요.","answer_guide":{"answer":"예: 어제 나는 도서관에서 책을 빌렸다. — 어제는 지난 때라 서술어를 「빌렸다」로 맞추었다. 내 생각은 작은 고침도 소중하다는 것이다. — 주어가 「내 생각은」이라 「~것이다」로 받았다. 화면이 밝은 빛으로 채워졌다. — 화면이 스스로 한 일이 아니어서 「채워졌다」로 받았다.","scoring_points":["세 문장을 호응이 맞게 썼는가","시간 표현에 맞춘 까닭을 썼는가","주어에 맞춘 까닭(~것이다 · ~되다)을 썼는가"]},"explanation":["시간 말에 서술어를 맞춰요.","「내 생각은」은 「~것이다」로 받아요.","스스로 한 일이 아니면 「~되다 · ~히다」로 받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#1','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C2',1,'mc','auto','어색한 표현을 알맞은 말로 고치는 손질은 어느 것인가요?',ARRAY['K6-1-u2-X03']::text[],false,'{"seq":1,"concept":"K6-1-u2-C2","difficulty":1,"kind":"mc","stem":"어색한 표현을 알맞은 말로 고치는 손질은 어느 것인가요?","options":[{"t":"바꾸기","correct":true},{"t":"빼기","mis":"K6-1-u2-X03"},{"t":"더하기","mis":"K6-1-u2-X03"},{"t":"옮기기","mis":"K6-1-u2-X03"}],"explanation":["빼기는 벗어난 내용을 지우는 일이에요.","더하기는 모자란 내용을 넣는 일이에요.","어색한 표현은 바꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#2','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C3',1,'ox','auto','고쳐 쓸 때에는 글 → 문단 → 문장의 차례로 큰 것부터 살펴요.',ARRAY['K6-1-u2-X05']::text[],false,'{"seq":2,"concept":"K6-1-u2-C3","difficulty":1,"kind":"ox","stem":"고쳐 쓸 때에는 글 → 문단 → 문장의 차례로 큰 것부터 살펴요.","answer":"O","reason_options":[{"t":"큰 것부터 봐야 다듬은 문장이 통째로 빠지는 헛수고가 줄기 때문에","correct":true},{"t":"작은 것은 고칠 필요가 없기 때문에","mis":"K6-1-u2-X05"}],"mis":"K6-1-u2-X05","explanation":["큰 것부터 봐요.","작은 것도 나중에 고쳐요.","헛수고가 줄어들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#3','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C19',1,'mc','auto','조사를 바르게 붙여 쓴 문장은 어느 것인가요?',ARRAY['K6-1-u2-X27','K6-1-u2-X24']::text[],false,'{"seq":3,"concept":"K6-1-u2-C19","difficulty":1,"kind":"mc","stem":"조사를 바르게 붙여 쓴 문장은 어느 것인가요?","options":[{"t":"친구에게 편지를 썼다","correct":true},{"t":"친구 에게 편지를 썼다","mis":"K6-1-u2-X27"},{"t":"친구에게 편지 를 썼다","mis":"K6-1-u2-X27"},{"t":"친구에게편지를썼다","mis":"K6-1-u2-X24"}],"explanation":["「에게」 · 「를」은 조사예요.","조사는 앞말에 붙여요.","낱말과 낱말 사이는 띄어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#4','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C23',1,'ox','auto','감상문에는 처음부터 끝까지의 모든 장면을 빠짐없이 적어요.',ARRAY['K6-1-u2-X32']::text[],false,'{"seq":4,"concept":"K6-1-u2-C23","difficulty":1,"kind":"ox","stem":"감상문에는 처음부터 끝까지의 모든 장면을 빠짐없이 적어요.","answer":"X","reason_options":[{"t":"줄거리는 짧게 쓰고 인상 깊은 장면과 생각을 자세히 쓰기 때문에","correct":true},{"t":"모든 장면을 써야 읽는 사람이 이해하기 때문에","mis":"K6-1-u2-X32"}],"mis":"K6-1-u2-X32","explanation":["모든 장면을 쓰면 줄거리 요약이 돼요.","줄거리는 간단히 써요.","장면과 생각을 길게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#5','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C25',1,'ox','auto','같은 낱말을 여러 번 되풀이하면 뜻이 더 또렷해져요.',ARRAY['K6-1-u2-X35']::text[],false,'{"seq":5,"concept":"K6-1-u2-C25","difficulty":1,"kind":"ox","stem":"같은 낱말을 여러 번 되풀이하면 뜻이 더 또렷해져요.","answer":"X","reason_options":[{"t":"겹치는 표현은 하나로 줄여야 읽기 쉽고 뜻이 또렷해지기 때문에","correct":true},{"t":"되풀이할수록 중요하다는 뜻이 되기 때문에","mis":"K6-1-u2-X35"}],"mis":"K6-1-u2-X35","explanation":["다빈은 「번호」를 되풀이했어요.","고친 글에서는 숫자 · 표시로 갈랐어요.","겹치는 표현은 줄여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#6','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C28',1,'ox','auto','누가 언제 썼는지 알 수 없는 글도 설명하는 글의 자료로 그대로 써도 돼요.',ARRAY['K6-1-u2-X37']::text[],false,'{"seq":6,"concept":"K6-1-u2-C28","difficulty":1,"kind":"ox","stem":"누가 언제 썼는지 알 수 없는 글도 설명하는 글의 자료로 그대로 써도 돼요.","answer":"X","reason_options":[{"t":"믿을 수 있는지, 지금도 맞는지 확인할 수 없기 때문에","correct":true},{"t":"인터넷에 있는 글은 모두 맞기 때문에","mis":"K6-1-u2-X37"}],"mis":"K6-1-u2-X37","explanation":["누가 만들었는지 확인해요.","언제 만들었는지 확인해요.","확인하지 않은 자료는 쓰지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#7','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C38',1,'ox','auto','「지난주」와 「본다」는 서로 잘 어울려요.',ARRAY['K6-1-u2-X20']::text[],false,'{"seq":7,"concept":"K6-1-u2-C38","difficulty":1,"kind":"ox","stem":"「지난주」와 「본다」는 서로 잘 어울려요.","answer":"X","reason_options":[{"t":"지난주는 지난 때라 「보았다」로 받아야 하기 때문에","correct":true},{"t":"시간을 나타내는 말은 서술어와 상관없기 때문에","mis":"K6-1-u2-X20"}],"mis":"K6-1-u2-X20","explanation":["시간 말이 서술어를 끌고 가요.","지난주는 지난 때예요.","「지난주에 보았다」로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#8','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C7',1,'ox','auto','고쳐쓰기를 할 때 한 군데만 고쳐도 글은 그만큼 나아져요.',ARRAY['K6-1-u2-X02']::text[],false,'{"seq":8,"concept":"K6-1-u2-C7","difficulty":1,"kind":"ox","stem":"고쳐쓰기를 할 때 한 군데만 고쳐도 글은 그만큼 나아져요.","answer":"O","reason_options":[{"t":"고쳐쓰기는 완벽한 글을 만드는 일이 아니라 필요한 곳을 손보는 일이기 때문에","correct":true},{"t":"한 군데만 고치면 고친 것이 아니기 때문에","mis":"K6-1-u2-X02"}],"mis":"K6-1-u2-X02","explanation":["완벽할 필요가 없어요.","작게 고친 것도 잘 고친 것이에요.","고친 만큼 나아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#9','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C9',2,'mc','auto','하린의 초고에서 맨 끝 문장 「지난 토요일 학교 강당에서 ~ 이 연극을 보았다.」는 어디로 옮기는 것이 알맞은가요?',ARRAY['K6-1-u2-X12','K6-1-u2-X03','K6-1-u2-X16']::text[],false,'{"seq":9,"concept":"K6-1-u2-C9","difficulty":2,"kind":"mc","stem":"하린의 초고에서 맨 끝 문장 「지난 토요일 학교 강당에서 ~ 이 연극을 보았다.」는 어디로 옮기는 것이 알맞은가요?","options":[{"t":"글의 맨 앞(처음)","correct":true},{"t":"그대로 맨 끝","mis":"K6-1-u2-X12"},{"t":"놀이터 문장 바로 뒤","mis":"K6-1-u2-X03"},{"t":"빼 버린다","mis":"K6-1-u2-X16"}],"explanation":["언제 어디서 보았는지는 보게 된 이야기예요.","처음에 와야 해요.","내용은 그대로 두고 차례만 옮겨요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#10','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C13',2,'ox','auto','「할머니가 말했다」는 뜻이 통하니까 고칠 필요가 없어요.',ARRAY['K6-1-u2-X17']::text[],false,'{"seq":10,"concept":"K6-1-u2-C13","difficulty":2,"kind":"ox","stem":"「할머니가 말했다」는 뜻이 통하니까 고칠 필요가 없어요.","answer":"X","reason_options":[{"t":"뜻이 통해도 높임 호응이 어긋나면 바른 문장이 아니기 때문에","correct":true},{"t":"할머니는 높일 필요가 없기 때문에","mis":"K6-1-u2-X17"}],"mis":"K6-1-u2-X17","explanation":["내용과 형식을 함께 봐요.","웃어른에게는 높임이 어울려요.","「할머니께서 말씀하셨다」로 고쳐요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#11','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C17',2,'ox','auto','「배 두척」은 세는 말 「척」을 앞의 수와 띄어 「배 두 척」으로 써야 해요.',ARRAY['K6-1-u2-X25']::text[],false,'{"seq":11,"concept":"K6-1-u2-C17","difficulty":2,"kind":"ox","stem":"「배 두척」은 세는 말 「척」을 앞의 수와 띄어 「배 두 척」으로 써야 해요.","answer":"O","reason_options":[{"t":"척은 배를 세는 말이고 세는 말은 앞의 수와 띄어 쓰기 때문에","correct":true},{"t":"배와 두를 붙여 써야 하기 때문에","mis":"K6-1-u2-X25"}],"mis":"K6-1-u2-X25","explanation":["척은 배를 세는 말이에요.","수와 세는 말은 띄어요.","「배 두 척」으로 써요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#12','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C7',2,'mc','auto','채아의 댓글 「잘 썼네. 고칠 곳 하나도 없어.」를 고친 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X07','K6-1-u2-X06','K6-1-u2-X08']::text[],false,'{"seq":12,"concept":"K6-1-u2-C7","difficulty":2,"kind":"mc","stem":"채아의 댓글 「잘 썼네. 고칠 곳 하나도 없어.」를 고친 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「할머니 장면이 자세해서 좋았어. 「전혀 지루했다」는 「지루하지 않았다」로 고치면 좋겠어.」","correct":true},{"t":"「정말 정말 잘 썼어.」","mis":"K6-1-u2-X07"},{"t":"「틀린 데 많아.」","mis":"K6-1-u2-X06"},{"t":"「전혀 지루했다 고쳐.」","mis":"K6-1-u2-X08"}],"explanation":["막연한 칭찬은 쓸모가 적어요.","고칠 곳만 말하면 위축돼요.","어디가 왜 좋은지, 무엇을 고칠지 말해요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"틀린 데가 너무 많아. 처음부터 다시 써."},{"who":"채아","text":"잘 썼네. 고칠 곳 하나도 없어."},{"who":"서준","text":"할머니가 서두르지 않는 장면이 눈에 그려졌어. 놀이터 문장은 연극 이야기와 멀어 보여서 빼면 좋겠어."},{"who":"보미","text":"연극을 보게 된 이야기가 맨 끝에 있어서 조금 헷갈렸어. 맨 앞으로 옮기면 어때?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#13','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C34',2,'ox','auto','맞춤법 검사기를 쓰면 내가 자주 틀리는 곳을 알 수 있어요.',ARRAY['K6-1-u2-X42']::text[],false,'{"seq":13,"concept":"K6-1-u2-C34","difficulty":2,"kind":"ox","stem":"맞춤법 검사기를 쓰면 내가 자주 틀리는 곳을 알 수 있어요.","answer":"O","reason_options":[{"t":"검사기가 띄어쓰기와 맞춤법을 짚어 주어 내 버릇을 알게 해 주기 때문에","correct":true},{"t":"검사기가 글을 다 써 주기 때문에","mis":"K6-1-u2-X42"}],"mis":"K6-1-u2-X42","explanation":["검사기는 빠르게 짚어 줘요.","자주 틀리는 곳이 보여요.","고칠지 말지는 내가 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#14','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C15',2,'mc','auto','로운의 글에서 빼야 할 문장은 어느 것인가요?',ARRAY['K6-1-u2-X16','K6-1-u2-X15']::text[],false,'{"seq":14,"concept":"K6-1-u2-C15","difficulty":2,"kind":"mc","stem":"로운의 글에서 빼야 할 문장은 어느 것인가요?","options":[{"t":"텃밭 옆 체육 창고 문은 지난달에 새로 칠했습니다.","correct":true},{"t":"당번은 아침마다 텃밭에 줍니다.","mis":"K6-1-u2-X16"},{"t":"상추는 물을 많이 주면 뿌리가 썩는다고 누가 그랬다.","mis":"K6-1-u2-X16"},{"t":"그래서 순서를 지켜야 한다.","mis":"K6-1-u2-X15"}],"explanation":["물 주기와 관련된 문장은 고쳐 써요.","창고 문 이야기는 상관없어요.","벗어난 문장은 빼요."],"asset":{"type":"passage","lines":["우리 학교 텃밭에는 물 주는 순서가 있는데 그 순서는 반마다 정해 놓은","순서이고 순서를 지키면 채소가 잘 자라는데 순서를 안 지키면 물을 두 번","주게 되고 그래서 순서를 지켜야 한다.","당번은 아침마다 텃밭에 줍니다.","상추는 물을 많이 주면 뿌리가 썩는다고 누가 그랬다.","텃밭 옆 체육 창고 문은 지난달에 새로 칠했습니다."],"title":"로운이 쓴 설명하는 글 초고 「텃밭 물 주기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#15','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C31',2,'match','auto','「텃밭 물 주기」를 읽은 친구들의 말과 의견의 갈래를 이으세요.','{}'::text[],false,'{"seq":15,"concept":"K6-1-u2-C31","difficulty":2,"kind":"match","stem":"「텃밭 물 주기」를 읽은 친구들의 말과 의견의 갈래를 이으세요.","pairs":[{"l":"텃밭에 순서가 있는 줄 몰랐어","r":"새롭게 안 점"},{"l":"비 오는 날은 어떻게 하는지 궁금해","r":"궁금한 점"},{"l":"창고 문장은 빼면 좋겠어, 물 주기와 멀어서","r":"고쳤으면 하는 점"}],"mis":"K6-1-u2-X39","explanation":["몰랐던 것을 알게 됐어요.","더 알고 싶은 것이에요.","고칠 곳과 까닭이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#16','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C30',2,'ox','auto','줄임말이나 은어는 친구들이 아는 말이니 설명하는 글에 써도 돼요.',ARRAY['K6-1-u2-X09']::text[],false,'{"seq":16,"concept":"K6-1-u2-C30","difficulty":2,"kind":"ox","stem":"줄임말이나 은어는 친구들이 아는 말이니 설명하는 글에 써도 돼요.","answer":"X","reason_options":[{"t":"읽는 사람이 아는 말로 풀어 써야 하고 줄임말 · 은어는 뜻이 흐려지기 때문에","correct":true},{"t":"줄임말이 더 짧아 좋기 때문에","mis":"K6-1-u2-X09"}],"mis":"K6-1-u2-X09","explanation":["모든 읽는 사람이 아는 말이 아니에요.","뜻이 흐려질 수 있어요.","읽는 사람이 아는 말로 풀어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#17','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C3',3,'mc','auto','하린의 초고에서 「연극을 본 이야기가 맨 끝에 있다」는 문제를 찾으려면 어떻게 읽어야 하나요?',ARRAY['K6-1-u2-X04','K6-1-u2-X05']::text[],false,'{"seq":17,"concept":"K6-1-u2-C3","difficulty":3,"kind":"mc","stem":"하린의 초고에서 「연극을 본 이야기가 맨 끝에 있다」는 문제를 찾으려면 어떻게 읽어야 하나요?","options":[{"t":"글 전체의 처음 · 가운데 · 끝 흐름을 살핀다","correct":true},{"t":"한 문장씩 서술어만 살핀다","mis":"K6-1-u2-X04"},{"t":"띄어쓰기만 살핀다","mis":"K6-1-u2-X05"},{"t":"낱말 뜻만 살핀다","mis":"K6-1-u2-X04"}],"explanation":["한 문장만 보면 차례가 안 보여요.","띄어쓰기와 상관없어요.","글 수준에서 흐름을 봐요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#18','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C7',3,'mc','auto','하린이 「고칠 곳이 이렇게 많으니 나는 글을 못 쓰나 봐.」라고 했어요. 알맞은 말은 어느 것인가요?',ARRAY['K6-1-u2-X01','K6-1-u2-X02','K6-1-u2-X10']::text[],false,'{"seq":18,"concept":"K6-1-u2-C7","difficulty":3,"kind":"mc","stem":"하린이 「고칠 곳이 이렇게 많으니 나는 글을 못 쓰나 봐.」라고 했어요. 알맞은 말은 어느 것인가요?","options":[{"t":"「여기 몇 군데만 손보면 네가 하고 싶은 말이 더 잘 전해질 거야.」","correct":true},{"t":"「맞아, 처음부터 새로 써.」","mis":"K6-1-u2-X01"},{"t":"「완벽하게 못 고칠 거면 그만둬.」","mis":"K6-1-u2-X02"},{"t":"「고칠 곳이 많으면 올리지 마.」","mis":"K6-1-u2-X10"}],"explanation":["고쳐 쓰라는 말은 혼내는 말이 아니에요.","완벽할 필요가 없어요.","필요한 곳만 손보면 나아져요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#19','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C12',3,'mc','auto','로운의 글에서 「당번은 아침마다 텃밭에 줍니다.」는 어떻게 하는 것이 알맞은가요?',ARRAY['K6-1-u2-X16','K6-1-u2-X03','K6-1-u2-X34']::text[],false,'{"seq":19,"concept":"K6-1-u2-C12","difficulty":3,"kind":"mc","stem":"로운의 글에서 「당번은 아침마다 텃밭에 줍니다.」는 어떻게 하는 것이 알맞은가요?","options":[{"t":"빼지 않고 「당번은 아침마다 텃밭에 물을 줍니다.」로 고친다","correct":true},{"t":"물 주기와 상관없으니 뺀다","mis":"K6-1-u2-X16"},{"t":"창고 문장 뒤로 옮긴다","mis":"K6-1-u2-X03"},{"t":"그대로 둔다","mis":"K6-1-u2-X34"}],"explanation":["물 주기와 관련 있는 문장이에요.","목적어가 빠졌을 뿐이에요.","지우지 말고 고쳐 써요."],"asset":{"type":"passage","lines":["우리 학교 텃밭에는 물 주는 순서가 있는데 그 순서는 반마다 정해 놓은","순서이고 순서를 지키면 채소가 잘 자라는데 순서를 안 지키면 물을 두 번","주게 되고 그래서 순서를 지켜야 한다.","당번은 아침마다 텃밭에 줍니다.","상추는 물을 많이 주면 뿌리가 썩는다고 누가 그랬다.","텃밭 옆 체육 창고 문은 지난달에 새로 칠했습니다."],"title":"로운이 쓴 설명하는 글 초고 「텃밭 물 주기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#20','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C26',3,'ox','auto','「당번은 아침마다 텃밭에 줍니다.」는 말로 하면 통하지만 글에서는 「물을」을 넣어야 해요.',ARRAY['K6-1-u2-X34']::text[],false,'{"seq":20,"concept":"K6-1-u2-C26","difficulty":3,"kind":"ox","stem":"「당번은 아침마다 텃밭에 줍니다.」는 말로 하면 통하지만 글에서는 「물을」을 넣어야 해요.","answer":"O","reason_options":[{"t":"읽는 사람은 그 자리에 없어 무엇을 주는지 알 수 없기 때문에","correct":true},{"t":"글은 말보다 길어야 하기 때문에","mis":"K6-1-u2-X34"}],"mis":"K6-1-u2-X34","explanation":["말할 때는 서로 알아서 빼도 통해요.","읽는 사람은 그 자리에 없었어요.","필수 성분을 갖춰요."],"asset":{"type":"passage","lines":["우리 학교 텃밭에는 물 주는 순서가 있는데 그 순서는 반마다 정해 놓은","순서이고 순서를 지키면 채소가 잘 자라는데 순서를 안 지키면 물을 두 번","주게 되고 그래서 순서를 지켜야 한다.","당번은 아침마다 텃밭에 줍니다.","상추는 물을 많이 주면 뿌리가 썩는다고 누가 그랬다.","텃밭 옆 체육 창고 문은 지난달에 새로 칠했습니다."],"title":"로운이 쓴 설명하는 글 초고 「텃밭 물 주기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#21','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C19',3,'mc','auto','「나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄 수 있는 사람이 되겠다.」에서 띄어 쓴 「수」에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X27','K6-1-u2-X25','K6-1-u2-X24']::text[],false,'{"seq":21,"concept":"K6-1-u2-C19","difficulty":3,"kind":"mc","stem":"「나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄 수 있는 사람이 되겠다.」에서 띄어 쓴 「수」에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"홀로 못 쓰는 이름씨라 앞말과 띄어 쓴다","correct":true},{"t":"조사라서 앞말에 붙여 써야 한다","mis":"K6-1-u2-X27"},{"t":"세는 말이라 수와 붙여 쓴다","mis":"K6-1-u2-X25"},{"t":"띄어쓰기는 뜻과 상관없어 아무렇게나 써도 된다","mis":"K6-1-u2-X24"}],"explanation":["「수」는 조사가 아니에요.","세는 말도 아니에요.","홀로 못 쓰는 이름씨라 띄어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#22','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C4',3,'mc','auto','세아와 민석이의 말을 함께 볼 때 글을 공유하는 일의 좋은 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X10']::text[],false,'{"seq":22,"concept":"K6-1-u2-C4","difficulty":3,"kind":"mc","stem":"세아와 민석이의 말을 함께 볼 때 글을 공유하는 일의 좋은 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"내가 못 본 곳을 친구가 짚어 주고, 읽는 사람을 떠올리며 더 꼼꼼히 고치게 된다","correct":true},{"t":"친구가 대신 글을 써 준다","mis":"K6-1-u2-X10"},{"t":"공유하면 더 고칠 필요가 없다","mis":"K6-1-u2-X10"},{"t":"칭찬을 많이 받아 기분이 좋다","mis":"K6-1-u2-X10"}],"explanation":["친구는 대신 쓰지 않아요.","공유한 뒤에도 고쳐요.","못 본 곳과 읽는 사람을 알게 돼요."],"asset":{"type":"speech","turns":[{"who":"세아","text":"학급 게시판에 올린 내 글에 댓글이 세 개 달렸어. 내가 못 본 곳을 친구가 짚어 줬어."},{"who":"민석","text":"나도 올려 봤는데, 읽는 사람이 있다고 생각하니까 문장을 더 꼼꼼히 보게 되더라."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#23','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C37',4,'mc','auto','하린의 감상문을 학급 게시판에 소개하는 글로 바꿀 때 가장 알맞은 문장은 어느 것인가요?',ARRAY['K6-1-u2-X44','K6-1-u2-X45','K6-1-u2-X09']::text[],false,'{"seq":23,"concept":"K6-1-u2-C37","difficulty":4,"kind":"mc","stem":"하린의 감상문을 학급 게시판에 소개하는 글로 바꿀 때 가장 알맞은 문장은 어느 것인가요?","options":[{"t":"할머니가 손녀에게 종이배 접는 법을 서두르지 않고 가르치는 장면에서, 기다려 주는 것도 가르침이라는 걸 알게 되었습니다.","correct":true},{"t":"이 연극은 최고예요. 무조건 보세요.","mis":"K6-1-u2-X44"},{"t":"연극은 배우가 무대에서 하는 공연입니다.","mis":"K6-1-u2-X45"},{"t":"ㄹㅇ 꿀잼 연극 강추","mis":"K6-1-u2-X09"}],"explanation":["자랑은 알 수 있는 것이 없어요.","누구에게나 있는 말은 소개가 아니에요.","줄임말 없이 그려 볼 수 있게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#24','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C32',4,'essay','teacher','하린이 친구들의 의견을 어떻게 골라 받아들였는지 쓰고, 의견을 고르는 기준이 왜 필요한지 내 생각을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u2-C32","difficulty":4,"kind":"essay","stem":"하린이 친구들의 의견을 어떻게 골라 받아들였는지 쓰고, 의견을 고르는 기준이 왜 필요한지 내 생각을 쓰세요.","answer_guide":{"answer":"예: 하린은 연극을 본 이야기를 맨 앞으로 옮기자는 보미의 의견과 놀이터 문장을 빼자는 서준의 의견을 받아들였다. 다른 연극 이름을 다 적자는 지호의 의견은 「종이배」 감상문과 멀어서 넣지 않았다. 의견을 모두 따르면 글이 하려던 말과 멀어질 수 있다. 그래서 「이 의견을 따르면 내가 하려던 말이 더 잘 전해지는가?」라는 기준으로 골라야 내 글이 나아진다.","scoring_points":["받아들인 의견과 받아들이지 않은 의견을 썼는가","받아들이지 않은 까닭을 썼는가","기준이 필요한 까닭을 썼는가"]},"explanation":["세 친구의 의견을 나눠 봐요.","넣지 않은 까닭을 써요.","기준이 왜 필요한지 써요."],"asset":{"type":"speech","turns":[{"who":"지호","text":"하린아, 끝에 네가 좋아하는 다른 연극 이름도 다 적으면 어때?"},{"who":"하린","text":"고맙지만 이 글은 「종이배」 감상문이라 그건 넣지 않을래."},{"who":"하린","text":"보미 말대로 연극을 본 이야기는 맨 앞으로 옮겼어. 서준이 말대로 놀이터 문장은 뺐고."},{"who":"하린","text":"띄어쓰기는 검사기를 돌려 봤는데, 왜 그렇게 고쳤는지 하나씩 확인하고 받아들였어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#25','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C39',4,'essay','teacher','「닫다 · 닫히다」 또는 「놓다 · 놓이다」를 골라 두 말을 넣은 문장을 하나씩 만들고, 두 말이 어떻게 다른지 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u2-C39","difficulty":4,"kind":"essay","stem":"「닫다 · 닫히다」 또는 「놓다 · 놓이다」를 골라 두 말을 넣은 문장을 하나씩 만들고, 두 말이 어떻게 다른지 설명하세요.","answer_guide":{"answer":"예: 나는 책상 위에 책을 놓았다. / 책상 위에 책이 놓여 있었다. 「놓다」는 내가 스스로 하는 일을 나타내는 말이고, 「놓이다」는 다른 힘에 의해 그렇게 된 일을 나타내는 말이다. 스스로 하는 일에는 「-이-」를 붙이지 않는다.","scoring_points":["두 말을 넣은 문장을 하나씩 바르게 만들었는가","스스로 하는 일과 그리 되는 일로 차이를 설명했는가","-히- · -리- · -이-를 붙이는 경우를 바르게 썼는가"]},"explanation":["두 말을 골라요.","문장을 하나씩 만들어요.","스스로 하는가, 그리 되는가로 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C1','kor',6,1,'u3',1,'토론이 필요한 상황 — 같은 일을 두고 찬성과 반대로 생각이 갈리는 문제에서 토론이 필요하며, 답이 이미 정해져 있거나 자료를 찾아보면 곧바로 확인되는 물음(학교가 문을 연 해 · 교실 온도)은 토론 주제가 되지 않는다',ARRAY['6국01-07 듣기 · 말하기']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C2','kor',6,1,'u3',1,'토의와 토론의 다른 점 — 둘 다 문제를 해결하려고 함께 이야기하지만, 토의는 편을 나누지 않고 방법을 모으는 말하기이고 토론은 찬성 측과 반대 측으로 편이 갈리는 말하기로, 가르는 잣대는 「찬반으로 편이 갈리는가」 하나이다',ARRAY['6국01-07 듣기 · 말하기']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C3','kor',6,1,'u3',1,'토론의 뜻 — 어떤 문제를 두고 찬성 측과 반대 측으로 나뉘어 각자 근거를 들어 자기 주장이 옳음을 밝히는 말하기로, 목소리가 큰 쪽이 이기는 것이 아니라 타당한 이유와 근거를 내놓고 정해진 절차를 지켜 겨룬다',ARRAY['6국01-07 듣기 · 말하기']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C4','kor',6,1,'u3',1,'주장 · 이유 · 근거의 세 층 — 주장은 내가 옳다고 내세우는 생각, 이유는 그렇게 주장하는 까닭(내 머릿속에서 나온 문장), 근거는 이유를 뒷받침하는 객관적인 자료(밖에서 가져와 확인할 수 있는 것)이며, 세 층이 위아래로 맞물려야 말이 선다',ARRAY['6국01-02 듣기 · 말하기']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C5','kor',6,1,'u3',1,'토론의 네 단계 — 주장 펼치기(주장 · 이유 · 근거를 냄) → 반론하기(상대 허점을 짚고 답함) → 주장 다지기(남은 것을 추려 다시 세움) → 판정하기(기준을 밝히고 더 설득력 있는 쪽을 정함)의 차례로 나아가며, 각 단계에 지킬 규칙이 있다',ARRAY['6국01-07 듣기 · 말하기']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C6','kor',6,1,'u3',1,'경청하는 태도 — 상대 발언을 끝까지 듣고 메모한 뒤 말차례에 되받으며, 듣지 않으면 무엇을 되받을지도 알 수 없으므로 경청은 예의이면서 실력이다',ARRAY['6국01-07 듣기 · 말하기']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C7','kor',6,1,'u3',1,'토론의 목적 — 토론은 찬반으로 겨루는 방식이 맞지만 그렇게 겨루는 목적은 상대를 누르는 것이 아니라 더 합리적인 결정에 이르는 것이며, 근거를 겨누고 결과에 승복한다',ARRAY['6국01-07 듣기 · 말하기']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C8','kor',6,1,'u3',1,'토론 주제의 갈래 — 참인지 거짓인지 따지는 문제 · 좋고 나쁨을 따지는 문제 · 무엇을 하자고 정하는 문제가 있으나 셋을 딱 잘라 나눌 필요는 없으며, 우리가 바꿔 볼 수 있는 「무엇을 하자고 정하는 문제」가 교실 토론에 가장 잘 맞는다',ARRAY['6국01-07 듣기 · 말하기']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C9','kor',6,1,'u3',2,'주장 펼치기 — 양측이 차례로 주장 → 이유 → 근거를 함께 내놓는 단계로, 세 층이 다 있어야 주장 펼치기가 되며 사회자는 주제와 순서를 안내한다',ARRAY['6국01-07 듣기 · 말하기']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C10','kor',6,1,'u3',2,'근거가 될 수 있는 것 — 설문 조사 결과 · 통계 · 이름을 밝힌 전문가의 말처럼 밖에서 가져와 누가 언제 무엇을 조사했는지 확인할 수 있는 것이 근거이고, 「그렇게 느낀다 · 그럴 것 같다」로 끝나는 문장은 이유이다',ARRAY['6국01-02 듣기 · 말하기']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C11','kor',6,1,'u3',2,'반론의 뜻과 범위 — 반론은 상대 주장에 맞서 반대되는 자기 주장을 밝히는 말하기로, 주장 펼치기에서 나온 내용(주장 · 이유 · 근거)에 대해서만 되받고 새 이야기를 꺼내지 않으며, 정리할 때에는 발언을 그대로 옮기지 않고 핵심만 요약한다',ARRAY['6국01-07 듣기 · 말하기']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C12','kor',6,1,'u3',2,'반론에 답변하기 — 답변할 때에는 상대가 물은 그 지점에 곧바로 답하면서 그 반론이 타당하지 않음을 밝히거나, 인정할 것은 인정하고 자료로 다시 세우며, 같은 말을 되풀이하는 것(공평하니까 공평하다)은 답변이 아니다',ARRAY['6국01-07 듣기 · 말하기']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C13','kor',6,1,'u3',2,'반론은 사람을 겨누지 않는다 — 「그것도 모르십니까?」처럼 사람이나 말투를 겨눈 말은 반론이 아니고 「그 자료는 조사한 때가 나와 있지 않습니다」처럼 주장 · 이유 · 근거를 겨누어야 하며, 토론은 공식적인 말하기이므로 높임말을 쓰고 공격적인 말투로 흐르지 않는다',ARRAY['6국01-07 듣기 · 말하기']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C14','kor',6,1,'u3',2,'주장 다지기 — 같은 말을 되풀이하는 단계가 아니라 앞 두 단계에서 확인된 것만 추려 자기편 주장을 다시 세우는 단계로, 짧은 문장 · 「요컨대 · 따라서」 같은 이어 주는 말 · 또박또박 힘 있는 목소리로 말하며 무너진 근거를 다시 꺼내지 않는다',ARRAY['6국01-07 듣기 · 말하기']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C15','kor',6,1,'u3',2,'판정의 첫 조건 — 명확한 기준 — 판정할 때 가장 먼저 있어야 하는 것은 무엇을 보고 정할지 미리 밝혀 둔 명확한 기준(타당한 이유를 냈는가 · 믿을 수 있는 근거를 냈는가 등)이며, 기준이 없으면 판정이 아니라 취향이 된다',ARRAY['6국01-02 듣기 · 말하기']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C16','kor',6,1,'u3',2,'판정은 옳고 그름을 가리지 않는다 — 판정은 어느 쪽 생각이 옳은지 가려 주는 일이 아니라 정해 둔 기준으로 볼 때 어느 쪽이 더 설득력 있게 말했는지를 정하는 일이라 기준이 달라지면 결과도 달라질 수 있으며, 토론자는 그 결과에 승복한다',ARRAY['6국01-02 듣기 · 말하기']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C17','kor',6,1,'u3',2,'토론 전 과정의 규칙 — 단계마다 다른 규칙 말고도 처음부터 끝까지 지킬 규칙이 있다 — 높임말을 쓰고 · 말차례를 지키고(끼어들지 않고) · 주제와 이어지는 말만 하고 · 상대를 존중한다',ARRAY['6국01-07 듣기 · 말하기']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C18','kor',6,1,'u3',4,'학급 토론 주제 고르기 — 친구들이 관심 있어 하고 · 찬성과 반대가 뚜렷하게 갈리고 · 양쪽 모두 근거를 찾을 수 있고 · 우리 힘으로 바꿔 볼 수 있는 문제를 고르며, 늘 그래 왔던 일에도 「꼭 그래야 할까」라고 물으면 좋은 주제가 나온다',ARRAY['6국01-07 듣기 · 말하기']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C19','kor',6,1,'u3',4,'입장 먼저, 역할은 나중 — 주제가 정해지면 먼저 모두가 자기 생각(찬성 · 반대)을 정하고 역할은 그다음에 나누며, 찬성과 반대가 비슷한 수로 갈려야 토론이 팽팽해진다',ARRAY['6국01-07 듣기 · 말하기']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C20','kor',6,1,'u3',4,'토론 준비표 — 준비표에는 주장 → 이유 → 이유마다 근거를 적고 예상 반론과 답변까지 덧붙이며, 이유는 두세 가지를 준비해 하나가 무너져도 남은 것으로 버틸 수 있게 한다',ARRAY['6국01-07 듣기 · 말하기']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C21','kor',6,1,'u3',4,'근거를 찾는 곳 — 믿을 만한 곳에서 낸 책과 누리집 자료 · 그 일을 오래 해 온 전문가의 의견(누구의 말인지 반드시 적음) · 우리 반이나 학년에 직접 물어 수를 센 설문 조사에서 근거를 찾고, 모은 자료는 같은 편끼리 바꾸어 읽어 본다',ARRAY['6국01-02 듣기 · 말하기']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C22','kor',6,1,'u3',4,'예상 반론과 답변 준비 — 상대가 무엇이라 되받을지 미리 적고 그에 대한 답변을 준비하며, 이 과정에서 내 근거의 약한 곳이 먼저 드러나므로 건너뛰지 않는다',ARRAY['6국01-07 듣기 · 말하기']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C23','kor',6,1,'u3',4,'토론의 네 역할 — 사회자(주제와 규칙을 알리고 말차례를 이끎 · 주제에서 벗어나지 않게 함) · 토론자(근거를 들어 간결하고 분명하게 말하고 상대 말을 끝까지 들음) · 판정단(기준을 정해 공정하게 판정 · 자기 생각과 같은 편에 후하게 주지 않음) · 청중(메모하며 듣고 잘한 곳 · 인상 깊은 근거를 짚음)으로, 모두에게 할 일이 있다',ARRAY['6국01-07 듣기 · 말하기']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C24','kor',6,1,'u3',4,'진행 순서와 협의 시간 — 찬성 · 반대 주장 펼치기 → 반대 측 반론과 찬성 측 답변 → 찬성 측 반론과 반대 측 답변 → 찬성 · 반대 주장 다지기 → 판정단의 판정과 정리의 차례로 굴러가며, 단계 사이 협의 시간에 같은 편끼리 반론과 답변을 맞춘다',ARRAY['6국01-07 듣기 · 말하기']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C25','kor',6,1,'u3',4,'뜨거워질수록 침착하게 — 질문과 답이 빠르게 오가는 반론하기에서는 감정이 앞서기 쉬우므로 말차례를 기다리고 · 한 번에 한 가지만 되받고 · 졌다고 느껴질 때에도 침착하게 이어 가며, 지나치게 뜨거워지면 서로의 말이 들리지 않아 되받을 수도 없다',ARRAY['6국01-07 듣기 · 말하기']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C26','kor',6,1,'u3',6,'근거를 따지는 세 물음 — 근거가 타당한지는 「주장이나 이유와 관련 있는가(관련성) · 출처가 분명한가(신뢰성) · 언제 누구를 조사했는지 충분히 구체적인가(충분성)」 세 물음으로 따지되, 셋을 딱 잘라 나누기보다 한 번씩 던져 보고 전체적으로 타당한지 본다 — 내 근거를 다듬을 때도, 상대 근거에 반론할 때도 쓴다',ARRAY['6국01-02 듣기 · 말하기']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C27','kor',6,1,'u3',6,'힘을 내지 못하는 근거 — 「어떤 동영상에서 봤는데」(누가 만든 무엇인지 모름) · 「많은 사람이 그렇게 답했다」(언제 몇 명에게 물었는지 없음) · 이유와 이어지지 않는 다른 이야기처럼, 세 물음 가운데 하나만 걸려도 근거는 흔들린다',ARRAY['6국01-02 듣기 · 말하기']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C28','kor',6,1,'u3',6,'충분성은 자료 개수가 아니다 — 자료를 다섯 개나 내도 각각이 흐릿하면 그대로이며, 충분하다는 것은 자료 하나가 언제 · 누구를 · 어떻게 조사한 것인지 밝혀져 있다는 뜻이라 자세한 자료 하나로도 충분할 수 있다',ARRAY['6국01-02 듣기 · 말하기']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C29','kor',6,1,'u3',6,'경험도 근거가 될 수 있다 — 나에게만 일어난 지나치게 드문 일(운동장에서 지갑을 주웠다)은 근거가 되기 어렵지만, 여러 사람이 그럴 만하다고 여길 일을 느낌으로 두지 않고 세거나 재어서 정리하면(한 시간 동안 출입을 세었더니) 근거가 될 수 있다',ARRAY['6국01-02 듣기 · 말하기']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C30','kor',6,1,'u3',6,'믿을 만한 자료 고르기 — 공신력 있는 곳(정부 기관 · 대학 · 연구소 · 언론사)에서 · 가장 최근에 낸 · 주제와 직접 이어지는 · 한쪽에 치우치지 않은 자료를 고르며, 무언가를 팔려는 글이나 광고에 가까운 기사는 근거로 삼기 어렵다',ARRAY['6국01-02 듣기 · 말하기']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C31','kor',6,1,'u3',6,'근거를 내놓는 법 — 세부 사항을 모두 읽지 않고 중요한 내용만 추려 분명하게 전하고, 표나 그림으로 보이면 한눈에 들어오며, 말할 때 누가 언제 낸 자료인지를 먼저 밝힌다 — 「어디서 봤는데」로 시작하면 좋은 자료도 흔들린다',ARRAY['6국01-07 듣기 · 말하기']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C32','kor',6,1,'u3',8,'사회 문제로 주제 정하기 — 늘 그래 왔던 일에 「꼭 그래야 할까」라고 묻고 많은 친구가 관심 있어 할 문제를 고르되, 사회 문제는 아는 것이 적으면 겉돌기 쉬우므로 주제를 정한 뒤 먼저 알려진 사실(지금 제한 속도 · 사고 건수)부터 함께 맞춰 본다',ARRAY['6국01-07 듣기 · 말하기']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C33','kor',6,1,'u3',8,'판정단의 공정함 — 판정단은 판정 기준을 미리 정해 적어 두고, 토론에서 실제로 나온 말과 자료만으로 판정하며, 평소 자기 생각과 같은 편이나 친한 친구가 있는 편에 후하게 주지 않는다',ARRAY['6국01-02 듣기 · 말하기']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C34','kor',6,1,'u3',8,'메모하며 듣기 — 주장 펼치기는 준비한 대로 말하면 되지만 반론하기는 그 순간에 들은 것으로만 할 수 있어 승패가 여기서 갈리므로, 원고를 다시 읽지 말고 상대측 주장(한 문장) · 이유의 개수 · 근거의 출처 · 답이 닿지 않은 물음을 핵심만 짧게 메모해 가장 약한 한 곳을 되받는다',ARRAY['6국01-02 듣기 · 말하기']::text[],34) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C35','kor',6,1,'u3',8,'판정 기준 네 갈래 — 주장 펼치기(주장이 설득력 있고 이유와 근거가 타당한가) · 반론하기(상대 이유나 근거의 문제를 찾아 되받고 반론에 알맞게 답했는가) · 주장 다지기(다시 정리해 분명히 했는가) · 태도(규칙을 지키고 경청하며 예의 바르게 참여했는가)로 본다',ARRAY['6국01-02 듣기 · 말하기']::text[],35) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C36','kor',6,1,'u3',8,'판정 뒤의 마무리 — 「우리가 이겼다 · 판정이 이상하다」로 끝내면 남는 것이 승패뿐이므로 판정 결과에는 승복하고 「저 근거는 나도 다시 찾아봐야겠다」처럼 생각을 남기며, 토론 뒤 생각이 바뀌거나 더 굳어지는 것은 부끄러운 일이 아니라 토론을 제대로 한 표시이다',ARRAY['6국01-07 듣기 · 말하기']::text[],36) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C37','kor',6,1,'u3',11,'실천 토론 주제 고르기 — 역사 · 환경 · 생활 어느 갈래에서 찾든 찬반이 갈리고 양쪽 모두 근거를 찾을 수 있어야 하며, 연도나 이름처럼 자료를 찾으면 답이 하나로 나오는 물음은 토론 주제가 아니다',ARRAY['6국01-07 듣기 · 말하기']::text[],37) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C38','kor',6,1,'u3',11,'근거는 나누어 모으고 골라 쓴다 — 모둠 안에서 찾을 영역(통계 · 전문가의 말 · 다른 고장 사례)을 나누고, 누가 언제 낸 자료인지 함께 적고, 같은 편끼리 바꾸어 읽으며 세 물음을 던진 뒤 가장 센 두 가지만 골라 준비표에 옮긴다',ARRAY['6국01-02 듣기 · 말하기']::text[],38) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C39','kor',6,1,'u3',11,'원탁 토론 — 찬반 토론이 편을 나누어 정해진 단계대로 겨루고 사회자와 판정단을 두는 것과 달리, 원탁 토론은 편을 나누지 않고 모두가 대등하게 한 차례에 한 번씩 돌아가며 말하며 답이 둘로 갈리지 않는 문제에 알맞다 — 어느 쪽이든 근거를 들어 말한다는 점은 같다',ARRAY['6국01-07 듣기 · 말하기']::text[],39) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C40','kor',6,1,'u3',11,'역사 논쟁은 관점의 차이 — 역사에 관한 논쟁에는 옳고 그름이 있는 것이 아니라 무엇을 더 중요하게 여겼는지 서로 다른 관점이 있으므로(배움의 기회 · 남은 것의 진짜 모습), 한쪽을 틀린 편으로 만들지 않고 판정 뒤에도 상대 생각을 낮추어 말하지 않는다',ARRAY['6국01-07 듣기 · 말하기']::text[],40) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C41','kor',6,1,'u3',11,'토론 뒤 나눌 이야기 — 토론은 끝났을 때가 아니라 새롭게 알게 된 사실 · 다른 역할을 맡았던 친구 가운데 잘한 사람과 그 까닭 · 생각이 바뀌었거나 더 굳어진 곳을 나눌 때 비로소 마무리된다',ARRAY['6국01-07 듣기 · 말하기']::text[],41) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C42','kor',6,1,'u3',11,'토론자에게 필요한 힘 — 자기 주장을 타당한 이유와 근거로 뒷받침하는 힘 · 상대의 반론이나 질문에 알맞게 답하는 힘 · 상대 근거의 타당성을 따져 보는 힘 · 자신감 있게 그러면서도 예의 바르게 표현하는 힘이며, 말을 많이 하거나 크게 하는 것과 토론을 잘하는 것은 다르다',ARRAY['6국01-07 듣기 · 말하기']::text[],42) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C43','kor',6,1,'u3',11,'겹받침 읽기 — 겹받침은 뒤에 자음이 오면 두 자음 가운데 하나만 소리 나고 그 뒤의 ㄱ · ㄷ · ㅂ · ㅅ · ㅈ은 된소리가 된다 — ㄻ은 [ㅁ](젊다 [점따] · 옮기다 [옴기다]), ㄿ은 [ㅂ](읊다 [읍따] · 가락을 붙여 시를 읽거나 외다), ㄺ은 [ㄱ](굵다 [국따] · 늙지 [늑찌])이되 ㄺ 뒤에 ㄱ이 오면 [ㄹ](굵고 [굴꼬]) (기초 다지기)',ARRAY['기초 다지기(겹받침)']::text[],43) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X01','kor',6,'u3',ARRAY['K6-1-u3-C1','K6-1-u3-C18','K6-1-u3-C32','K6-1-u3-C37']::text[],'답이 이미 정해져 있거나 자료를 찾아보면 곧바로 확인되는 물음(학생 수 · 연도 · 지켜야 할 규칙)도 토론 주제가 된다고 여긴다','찬반이 갈리나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X02','kor',6,'u3',ARRAY['K6-1-u3-C2','K6-1-u3-C3']::text[],'편을 나누지 않고 방법을 모으는 토의와 찬반으로 편이 갈리는 토론을 헷갈린다','찬반으로 편이 갈리나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X03','kor',6,'u3',ARRAY['K6-1-u3-C3','K6-1-u3-C39']::text[],'토론을 한 사람이 여러 사람 앞에서 자기 생각을 알리는 말하기(연설 · 발표)로 여긴다','찬성 측과 반대 측') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X04','kor',6,'u3',ARRAY['K6-1-u3-C4','K6-1-u3-C10']::text[],'그렇게 주장하는 까닭(이유)과 밖에서 가져온 자료(근거)를 헷갈려, 내 느낌이나 생각을 근거로 여긴다','내 까닭? 밖의 자료?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X05','kor',6,'u3',ARRAY['K6-1-u3-C9','K6-1-u3-C4']::text[],'주장만 내세우고 이유나 근거를 함께 내지 않는다','주장 → 이유 → 근거') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X06','kor',6,'u3',ARRAY['K6-1-u3-C5','K6-1-u3-C24']::text[],'토론의 네 단계의 차례나 각 단계에서 하는 일을 헷갈린다','펼치기 → 반론 → 다지기 → 판정') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X07','kor',6,'u3',ARRAY['K6-1-u3-C6','K6-1-u3-C17']::text[],'허점이 보이면 상대 말을 끊고 끼어들어 곧바로 되받는다','말차례를 기다려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X08','kor',6,'u3',ARRAY['K6-1-u3-C6','K6-1-u3-C34']::text[],'상대 말을 듣지 않고 준비한 원고를 그대로 읽는다','듣고 메모해야 되받아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X09','kor',6,'u3',ARRAY['K6-1-u3-C7']::text[],'토론을 어떻게든 상대를 눌러 이겨야 하는 시합으로 여긴다','목적은 합리적인 결정') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X10','kor',6,'u3',ARRAY['K6-1-u3-C8']::text[],'토론 주제의 갈래를 반드시 딱 잘라 나눌 수 있어야 토론할 수 있다고 여긴다','딱 잘라 나눌 필요는 없어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X11','kor',6,'u3',ARRAY['K6-1-u3-C11','K6-1-u3-C17']::text[],'반론이나 답변에서 주장 펼치기에 나오지 않은, 주제와 상관없는 새 이야기를 꺼낸다','펼친 내용에 대해서만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X12','kor',6,'u3',ARRAY['K6-1-u3-C11','K6-1-u3-C34']::text[],'반론을 정리하거나 메모할 때 상대 발언을 한 글자도 빠짐없이 그대로 옮겨 적는다','핵심만 짧게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X13','kor',6,'u3',ARRAY['K6-1-u3-C12']::text[],'반론에 답할 때 상대가 물은 것에 답하지 않고 같은 말을 되풀이한다(공평하니까 공평합니다)','물은 그 지점에 답하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X14','kor',6,'u3',ARRAY['K6-1-u3-C13']::text[],'반론에서 주장 · 이유 · 근거가 아니라 사람이나 말투를 겨누거나, 반말 · 공격적인 말투를 쓴다','근거를 겨눠요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X15','kor',6,'u3',ARRAY['K6-1-u3-C14']::text[],'주장 다지기를 처음 한 말을 그대로 되풀이하는 단계로 여기거나, 반론에서 무너진 근거를 다시 꺼낸다','남은 것만 추려 다시') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X16','kor',6,'u3',ARRAY['K6-1-u3-C15','K6-1-u3-C35']::text[],'판정을 미리 밝힌 기준 없이 목소리 크기 · 말한 길이 · 평소 생각 같은 것으로 한다','기준이 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X17','kor',6,'u3',ARRAY['K6-1-u3-C16']::text[],'판정 결과가 어느 쪽 생각이 옳은지를 가려 준다고 여긴다','더 설득력 있게 말한 쪽') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X18','kor',6,'u3',ARRAY['K6-1-u3-C16','K6-1-u3-C36']::text[],'판정 결과가 마음에 들지 않으면 승복하지 않고 판정단 탓을 한다','결과에 승복해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X19','kor',6,'u3',ARRAY['K6-1-u3-C18','K6-1-u3-C37']::text[],'친구들이 관심 없거나 우리 힘으로 바꿀 수 없는 문제를 토론 주제로 고른다','관심 · 바꿔 볼 수 있나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X20','kor',6,'u3',ARRAY['K6-1-u3-C19']::text[],'모두가 자기 생각을 정하기 전에 역할부터 나누거나, 찬반을 한쪽으로 기울게 나눈다','생각 먼저, 역할은 나중') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X21','kor',6,'u3',ARRAY['K6-1-u3-C20']::text[],'이유를 하나만 준비해 그것이 무너지면 버틸 것이 없다','이유는 두세 가지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X22','kor',6,'u3',ARRAY['K6-1-u3-C21','K6-1-u3-C38']::text[],'전문가의 말이나 찾은 자료를 쓸 때 누구의 말인지 · 어디서 낸 자료인지 적지 않는다','누구의 말인지 적기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X23','kor',6,'u3',ARRAY['K6-1-u3-C22']::text[],'예상 반론과 답변을 미리 적어 보는 준비를 건너뛰어도 된다고 여긴다','약한 곳이 먼저 보여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X24','kor',6,'u3',ARRAY['K6-1-u3-C23','K6-1-u3-C33']::text[],'판정단이 자기 생각과 같은 편이나 친한 친구가 있는 편에 후하게 준다','나온 말과 자료만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X25','kor',6,'u3',ARRAY['K6-1-u3-C23']::text[],'사회자 · 토론자 · 판정단 · 청중이 할 일을 서로 헷갈린다','이끎 · 말함 · 정함 · 들음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X26','kor',6,'u3',ARRAY['K6-1-u3-C25']::text[],'반론하기에서 감정이 앞서 목소리를 높이거나 한꺼번에 여러 가지를 몰아친다','한 번에 한 가지, 침착하게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X27','kor',6,'u3',ARRAY['K6-1-u3-C26','K6-1-u3-C27']::text[],'주장이나 이유와 이어지지 않는 자료도 근거로 쓸 수 있다고 여긴다','이유와 이어지나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X28','kor',6,'u3',ARRAY['K6-1-u3-C26','K6-1-u3-C27']::text[],'어디서 나왔는지 확인할 수 없는 자료(어떤 누리집 · 어떤 동영상)를 근거로 쓴다','출처가 분명한가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X29','kor',6,'u3',ARRAY['K6-1-u3-C26','K6-1-u3-C27']::text[],'「많은 사람 · 다들」처럼 언제 몇 명에게 물었는지 없는 흐릿한 자료를 근거로 쓴다','언제 · 누구를?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X30','kor',6,'u3',ARRAY['K6-1-u3-C28']::text[],'자료의 개수가 많거나 길면 충분한 근거라고 여긴다','개수가 아니라 구체성') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X31','kor',6,'u3',ARRAY['K6-1-u3-C21','K6-1-u3-C29']::text[],'전문가의 말이나 내가 겪은 일, 사람에게 물은 자료는 무조건 근거가 될 수 없다고 여긴다','확인되고 정리되면 근거') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X32','kor',6,'u3',ARRAY['K6-1-u3-C29']::text[],'나에게만 일어난 드문 일이나 느낌을 세거나 재지 않고 그대로 근거로 쓴다','세거나 재어서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X33','kor',6,'u3',ARRAY['K6-1-u3-C30']::text[],'오래된 자료나 무언가를 팔려는 광고 글, 한쪽에 치우친 자료를 근거로 쓴다','공신력 · 최근 · 치우침 없음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X34','kor',6,'u3',ARRAY['K6-1-u3-C31']::text[],'근거를 내놓을 때 세부 사항을 모두 읽거나, 누가 언제 낸 자료인지 밝히지 않고 「어디서 봤는데」로 시작한다','출처를 먼저 밝혀요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X35','kor',6,'u3',ARRAY['K6-1-u3-C26']::text[],'근거를 세 물음으로 따지지 않고 숫자가 있는지 · 그럴듯해 보이는지만 보거나, 세 물음 가운데 하나만 통과하면 된다고 여긴다','세 물음을 한 번씩') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X36','kor',6,'u3',ARRAY['K6-1-u3-C32']::text[],'사회 문제를 주제로 정하고 알려진 사실을 함께 맞춰 보지 않은 채 토론한다','사실부터 함께 맞춰요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X37','kor',6,'u3',ARRAY['K6-1-u3-C23']::text[],'청중은 토론에서 할 일이 없다고 여긴다','메모하고 짚어 줘요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X38','kor',6,'u3',ARRAY['K6-1-u3-C34']::text[],'토론 중에 상대의 말투 · 목소리 크기 · 옷차림처럼 되받을 거리가 아닌 것을 메모한다','되받을 거리를 적어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X39','kor',6,'u3',ARRAY['K6-1-u3-C36']::text[],'토론 중이나 뒤에 생각이 바뀌면 진 것이라 여겨 무너진 근거를 끝까지 붙잡는다','바뀌어도 괜찮아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X40','kor',6,'u3',ARRAY['K6-1-u3-C36','K6-1-u3-C41']::text[],'토론이 끝난 뒤 승패만 말하거나 상대의 준비를 깎아내린다','배운 것을 나눠요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X41','kor',6,'u3',ARRAY['K6-1-u3-C39']::text[],'편을 나누지 않고 대등하게 말하는 원탁 토론과 편을 나누어 겨루는 찬반 토론을 헷갈린다','편을 나누나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X42','kor',6,'u3',ARRAY['K6-1-u3-C40']::text[],'역사에 관한 논쟁을 한쪽은 옳고 다른 쪽은 틀린 문제로 여긴다','무엇을 더 중요하게 여겼나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X43','kor',6,'u3',ARRAY['K6-1-u3-C38']::text[],'모은 근거를 같은 편끼리 바꾸어 읽거나 고르지 않고 모두 준비표에 옮긴다','가장 센 두 가지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X44','kor',6,'u3',ARRAY['K6-1-u3-C43']::text[],'겹받침의 두 자음을 모두 소리 내거나, 어느 자음이 소리 나는지 · 뒤 자음이 된소리가 되는지를 틀리게 읽는다(굵고 [국꼬])','ㄻ [ㅁ] · ㄿ [ㅂ] · ㄺ [ㄱ], ㄺ+ㄱ [ㄹ]') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X45','kor',6,'u3',ARRAY['K6-1-u3-C42']::text[],'말을 많이 하거나 크게 하는 것을 토론을 잘하는 것으로 여긴다','근거 · 답변 · 예의') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L01_basic#1','kor',6,1,'u3','L01','g6_1_kor_u3_L01_basic','lesson_basic','K6-1-u3-C3',1,'mc','auto','「토론」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X02','K6-1-u3-X03','K6-1-u3-X09']::text[],false,'{"seq":1,"concept":"K6-1-u3-C3","difficulty":1,"kind":"mc","stem":"「토론」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"찬성과 반대로 나뉘어 근거를 들어 자기 주장이 옳음을 밝히는 말하기","correct":true},{"t":"편을 나누지 않고 여럿이 의견을 모아 방법을 찾는 말하기","mis":"K6-1-u3-X02"},{"t":"한 사람이 여러 사람 앞에서 자기 생각을 알리는 말하기","mis":"K6-1-u3-X03"},{"t":"목소리가 큰 쪽이 이기는 말하기","mis":"K6-1-u3-X09"}],"explanation":["편 없이 방법을 모으는 것은 토의예요.","혼자 알리는 말하기는 토론이 아니에요.","찬반으로 나뉘어 근거를 들어 겨뤄요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L01_basic#2','kor',6,1,'u3','L01','g6_1_kor_u3_L01_basic','lesson_basic','K6-1-u3-C1',1,'mc','auto','다음 가운데 토론이 필요한 상황은 어느 것인가요?',ARRAY['K6-1-u3-X01']::text[],false,'{"seq":2,"concept":"K6-1-u3-C1","difficulty":1,"kind":"mc","stem":"다음 가운데 토론이 필요한 상황은 어느 것인가요?","options":[{"t":"학교 앞 도로에 과속 방지 턱을 더 놓을지 정하기","correct":true},{"t":"우리 학교가 문을 연 해가 언제인지 알아보기","mis":"K6-1-u3-X01"},{"t":"교실 온도가 몇 도인지 재어 보기","mis":"K6-1-u3-X01"},{"t":"불이 났을 때 대피하는 길 익히기","mis":"K6-1-u3-X01"}],"explanation":["문을 연 해는 찾아보면 확인돼요.","온도는 재면 알 수 있어요.","찬반으로 갈리는 문제라야 토론이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L01_basic#3','kor',6,1,'u3','L01','g6_1_kor_u3_L01_basic','lesson_basic','K6-1-u3-C4',1,'match','auto','말한 내용과 그 층을 알맞게 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K6-1-u3-C4","difficulty":1,"kind":"match","stem":"말한 내용과 그 층을 알맞게 이으세요.","pairs":[{"l":"학교 앞 도로의 제한 속도를 낮춰야 합니다","r":"주장"},{"l":"차가 빠르면 아이들이 피할 시간이 없기 때문입니다","r":"이유"},{"l":"우리 시가 지난해 낸 어린이 보행 사고 통계","r":"근거"}],"mis":"K6-1-u3-X04","explanation":["내세우는 생각은 주장이에요.","그렇게 생각한 까닭은 이유예요.","밖에서 가져온 자료는 근거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L01_basic#4','kor',6,1,'u3','L01','g6_1_kor_u3_L01_basic','lesson_basic','K6-1-u3-C2',1,'ox','auto','토의와 토론의 가장 큰 다른 점은 찬성과 반대로 편이 갈리는가예요.',ARRAY['K6-1-u3-X02']::text[],false,'{"seq":4,"concept":"K6-1-u3-C2","difficulty":1,"kind":"ox","stem":"토의와 토론의 가장 큰 다른 점은 찬성과 반대로 편이 갈리는가예요.","answer":"O","reason_options":[{"t":"토의는 편을 나누지 않고 방법을 모으고, 토론은 찬반으로 나뉘어 겨루기 때문에","correct":true},{"t":"토의는 혼자 하고 토론은 여럿이 하기 때문에","mis":"K6-1-u3-X02"}],"mis":"K6-1-u3-X02","explanation":["둘 다 여럿이 함께 이야기해요.","둘 다 문제를 해결하려고 해요.","다른 점은 찬반으로 편이 갈리는가예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L01_basic#5','kor',6,1,'u3','L01','g6_1_kor_u3_L01_basic','lesson_basic','K6-1-u3-C5',2,'mc','auto','토론의 네 단계를 차례대로 바르게 늘어놓은 것은 어느 것인가요?',ARRAY['K6-1-u3-X06']::text[],false,'{"seq":5,"concept":"K6-1-u3-C5","difficulty":2,"kind":"mc","stem":"토론의 네 단계를 차례대로 바르게 늘어놓은 것은 어느 것인가요?","options":[{"t":"주장 펼치기 → 반론하기 → 주장 다지기 → 판정하기","correct":true},{"t":"반론하기 → 주장 펼치기 → 판정하기 → 주장 다지기","mis":"K6-1-u3-X06"},{"t":"주장 펼치기 → 판정하기 → 반론하기 → 주장 다지기","mis":"K6-1-u3-X06"},{"t":"판정하기 → 주장 펼치기 → 반론하기 → 주장 다지기","mis":"K6-1-u3-X06"}],"explanation":["먼저 주장을 내놓아야 되받을 수 있어요.","다지기는 반론 뒤에 해요.","판정은 맨 마지막이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L01_basic#6','kor',6,1,'u3','L01','g6_1_kor_u3_L01_basic','lesson_basic','K6-1-u3-C6',2,'mc','auto','토론에 참여하는 태도로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X07','K6-1-u3-X08','K6-1-u3-X14']::text[],false,'{"seq":6,"concept":"K6-1-u3-C6","difficulty":2,"kind":"mc","stem":"토론에 참여하는 태도로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"상대 발언을 끝까지 듣고 메모한 뒤 말차례에 되받는다","correct":true},{"t":"허점이 보이면 말을 끊고 곧바로 지적한다","mis":"K6-1-u3-X07"},{"t":"상대가 무슨 말을 하든 준비한 원고를 그대로 읽는다","mis":"K6-1-u3-X08"},{"t":"상대 말투가 거슬리면 그 점부터 짚는다","mis":"K6-1-u3-X14"}],"explanation":["끼어들면 말차례가 무너져요.","듣지 않으면 되받을 수 없어요.","끝까지 듣고 메모한 뒤 되받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L01_basic#7','kor',6,1,'u3','L01','g6_1_kor_u3_L01_basic','lesson_basic','K6-1-u3-C1',2,'mc','auto','온유와 강토의 대화에서 토론이 필요한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X01','K6-1-u3-X02','K6-1-u3-X09']::text[],false,'{"seq":7,"concept":"K6-1-u3-C1","difficulty":2,"kind":"mc","stem":"온유와 강토의 대화에서 토론이 필요한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"같은 일을 두고 찬성과 반대로 생각이 갈리기 때문에","correct":true},{"t":"공원 넓이가 얼마인지 알아봐야 하기 때문에","mis":"K6-1-u3-X01"},{"t":"편을 나누지 않고 방법만 모으면 되기 때문에","mis":"K6-1-u3-X02"},{"t":"목소리가 큰 사람의 생각을 따르면 되기 때문에","mis":"K6-1-u3-X09"}],"explanation":["넓이는 재어 보면 알 수 있어요.","두 사람은 생각이 갈렸어요.","찬반으로 갈리면 토론이 필요해요."],"asset":{"type":"speech","turns":[{"who":"온유","text":"마을 공원 한쪽에 반려견 놀이터를 만들면 좋겠어. 목줄을 풀고 뛸 곳이 없어서 개들이 인도까지 나오잖아."},{"who":"강토","text":"나는 반대야. 공원은 모두가 쓰는 곳인데 한쪽을 떼어 주면 아이들이 뛸 곳이 줄어들어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L01_basic#8','kor',6,1,'u3','L01','g6_1_kor_u3_L01_basic','lesson_basic','K6-1-u3-C7',2,'ox','auto','토론은 상대를 어떻게든 눌러 이기는 것이 목적이에요.',ARRAY['K6-1-u3-X09']::text[],false,'{"seq":8,"concept":"K6-1-u3-C7","difficulty":2,"kind":"ox","stem":"토론은 상대를 어떻게든 눌러 이기는 것이 목적이에요.","answer":"X","reason_options":[{"t":"겨루는 방식이지만 목적은 더 합리적인 결정에 이르는 것이기 때문에","correct":true},{"t":"토론은 이기고 지는 것이 전부이기 때문에","mis":"K6-1-u3-X09"}],"mis":"K6-1-u3-X09","explanation":["토론은 찬반으로 겨뤄요.","그러나 누르는 것이 목적이 아니에요.","더 나은 답을 찾고 결과에 승복해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L01_basic#9','kor',6,1,'u3','L01','g6_1_kor_u3_L01_basic','lesson_basic','K6-1-u3-C4',2,'mc','auto','「우리 구청이 낸 지난해 안전사고 통계입니다.」는 주장 · 이유 · 근거 가운데 무엇인가요?',ARRAY['K6-1-u3-X04','K6-1-u3-X06']::text[],false,'{"seq":9,"concept":"K6-1-u3-C4","difficulty":2,"kind":"mc","stem":"「우리 구청이 낸 지난해 안전사고 통계입니다.」는 주장 · 이유 · 근거 가운데 무엇인가요?","options":[{"t":"근거","correct":true},{"t":"주장","mis":"K6-1-u3-X04"},{"t":"이유","mis":"K6-1-u3-X04"},{"t":"판정","mis":"K6-1-u3-X06"}],"explanation":["내세우는 생각이 아니에요.","내가 생각한 까닭도 아니에요.","밖에서 가져온 자료는 근거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L01_basic#10','kor',6,1,'u3','L01','g6_1_kor_u3_L01_basic','lesson_basic','K6-1-u3-C8',3,'mc','auto','교실 토론 주제로 가장 잘 맞는 것은 어느 것인가요?',ARRAY['K6-1-u3-X01','K6-1-u3-X10']::text[],false,'{"seq":10,"concept":"K6-1-u3-C8","difficulty":3,"kind":"mc","stem":"교실 토론 주제로 가장 잘 맞는 것은 어느 것인가요?","options":[{"t":"「우리 반 앉는 곳을 한 달마다 바꾸어야 한다.」처럼 무엇을 하자고 정하는 문제","correct":true},{"t":"「이 자료는 언제 만들어졌는가」처럼 찾아보면 곧바로 확인되는 물음","mis":"K6-1-u3-X01"},{"t":"세 갈래 가운데 어느 것인지 딱 잘라 나눌 수 있어야만 쓸 수 있는 문제","mis":"K6-1-u3-X10"},{"t":"「복도에서 뛰지 않는다」처럼 이미 지키기로 정해진 규칙","mis":"K6-1-u3-X01"}],"explanation":["확인되는 물음은 토론이 안 돼요.","갈래를 딱 잘라 나눌 필요는 없어요.","우리가 바꿔 볼 수 있는 일이 잘 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L01_challenge#1','kor',6,1,'u3','L01','g6_1_kor_u3_L01_challenge','lesson_challenge','K6-1-u3-C2',2,'mc','auto','「학예회에서 우리 반이 무엇을 할지 아이디어 모으기」에 알맞은 말하기는 어느 것인가요?',ARRAY['K6-1-u3-X02','K6-1-u3-X03']::text[],false,'{"seq":1,"concept":"K6-1-u3-C2","difficulty":2,"kind":"mc","stem":"「학예회에서 우리 반이 무엇을 할지 아이디어 모으기」에 알맞은 말하기는 어느 것인가요?","options":[{"t":"토의 — 편을 나누지 않고 함께 방법을 찾는 일이므로","correct":true},{"t":"토론 — 여럿이 함께 이야기하므로","mis":"K6-1-u3-X02"},{"t":"토론 — 문제를 해결하려는 말하기이므로","mis":"K6-1-u3-X02"},{"t":"연설 — 한 사람이 정해서 알리므로","mis":"K6-1-u3-X03"}],"explanation":["여럿이 이야기하는 건 토의도 같아요.","문제를 해결하려는 것도 같아요.","편이 갈리지 않으니 토의예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L01_challenge#2','kor',6,1,'u3','L01','g6_1_kor_u3_L01_challenge','lesson_challenge','K6-1-u3-C4',2,'ox','auto','「목줄을 풀 곳이 없어 인도에서 사고가 나기 쉽기 때문입니다.」는 근거예요.',ARRAY['K6-1-u3-X04']::text[],false,'{"seq":2,"concept":"K6-1-u3-C4","difficulty":2,"kind":"ox","stem":"「목줄을 풀 곳이 없어 인도에서 사고가 나기 쉽기 때문입니다.」는 근거예요.","answer":"X","reason_options":[{"t":"그렇게 주장하는 까닭이므로 이유이고, 근거는 밖에서 가져온 객관적인 자료이기 때문에","correct":true},{"t":"까닭을 말하는 문장도 모두 근거이기 때문에","mis":"K6-1-u3-X04"}],"mis":"K6-1-u3-X04","explanation":["「~때문입니다」는 까닭이에요.","까닭은 이유예요.","근거는 확인할 수 있는 자료예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L01_challenge#3','kor',6,1,'u3','L01','g6_1_kor_u3_L01_challenge','lesson_challenge','K6-1-u3-C3',3,'error','auto','토론에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u3-X02','K6-1-u3-X03']::text[],false,'{"seq":3,"concept":"K6-1-u3-C3","difficulty":3,"kind":"error","stem":"토론에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"하율 — 「토론은 편을 나누지 않고 의견을 모아 더 나은 안을 만드는 말하기야.」","correct":true,"mis_target":"K6-1-u3-X02"},{"t":"서진 — 「토론은 찬반으로 나뉘어 근거를 들어 말해.」","mis":"K6-1-u3-X03"},{"t":"라온 — 「토의와 토론 모두 문제를 해결하려고 함께 이야기해.」","mis":"K6-1-u3-X02"}],"explanation":["서진은 토론의 뜻을 바르게 말했어요.","라온은 같은 점을 바르게 말했어요.","하율이 말한 것은 토의예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L01_challenge#4','kor',6,1,'u3','L01','g6_1_kor_u3_L01_challenge','lesson_challenge','K6-1-u3-C5',3,'mc','auto','상대 주장의 잘못된 곳을 짚고, 그에 답하는 단계는 어느 것인가요?',ARRAY['K6-1-u3-X06']::text[],false,'{"seq":4,"concept":"K6-1-u3-C5","difficulty":3,"kind":"mc","stem":"상대 주장의 잘못된 곳을 짚고, 그에 답하는 단계는 어느 것인가요?","options":[{"t":"반론하기","correct":true},{"t":"주장 펼치기","mis":"K6-1-u3-X06"},{"t":"주장 다지기","mis":"K6-1-u3-X06"},{"t":"판정하기","mis":"K6-1-u3-X06"}],"explanation":["주장 펼치기는 처음 내놓는 단계예요.","다지기는 다시 세우는 단계예요.","되받는 단계는 반론하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L01_challenge#5','kor',6,1,'u3','L01','g6_1_kor_u3_L01_challenge','lesson_challenge','K6-1-u3-C6',3,'mc','auto','경청을 「예의이면서 실력」이라고 하는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X16','K6-1-u3-X08','K6-1-u3-X07']::text[],false,'{"seq":5,"concept":"K6-1-u3-C6","difficulty":3,"kind":"mc","stem":"경청을 「예의이면서 실력」이라고 하는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"상대 말을 끝까지 들어야 무엇을 되받을지 알 수 있기 때문에","correct":true},{"t":"듣는 척만 해도 판정단이 좋게 보기 때문에","mis":"K6-1-u3-X16"},{"t":"준비한 원고만 잘 읽으면 되기 때문에","mis":"K6-1-u3-X08"},{"t":"상대 말이 끝나기 전에 끼어들어야 이기기 때문에","mis":"K6-1-u3-X07"}],"explanation":["판정은 기준으로 해요.","원고만 읽으면 되받을 수 없어요.","들어야 날카롭게 되받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L01_challenge#6','kor',6,1,'u3','L01','g6_1_kor_u3_L01_challenge','lesson_challenge','K6-1-u3-C8',3,'mc','auto','어떤 문제가 토론 주제가 되는지에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X10','K6-1-u3-X01']::text[],false,'{"seq":6,"concept":"K6-1-u3-C8","difficulty":3,"kind":"mc","stem":"어떤 문제가 토론 주제가 되는지에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"갈래를 딱 잘라 나눌 필요는 없고, 무엇을 하자고 정하는 문제가 교실 토론에 잘 맞는다","correct":true},{"t":"갈래를 반드시 딱 잘라 나눌 수 있어야 토론할 수 있다","mis":"K6-1-u3-X10"},{"t":"자료를 찾으면 곧바로 답이 나오는 물음이 가장 좋은 주제다","mis":"K6-1-u3-X01"},{"t":"답이 이미 정해진 규칙일수록 토론하기 좋다","mis":"K6-1-u3-X01"}],"explanation":["갈래는 딱 잘라 나누지 않아도 돼요.","확인되는 물음은 토론이 안 돼요.","우리가 바꿔 볼 수 있는 일이 잘 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L01_challenge#7','kor',6,1,'u3','L01','g6_1_kor_u3_L01_challenge','lesson_challenge','K6-1-u3-C7',3,'mc','auto','「서로 겨루어 보면 더 나은 답이 드러난다」라고 여기는 사람의 행동으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X09','K6-1-u3-X14','K6-1-u3-X18']::text[],false,'{"seq":7,"concept":"K6-1-u3-C7","difficulty":3,"kind":"mc","stem":"「서로 겨루어 보면 더 나은 답이 드러난다」라고 여기는 사람의 행동으로 알맞은 것은 어느 것인가요?","options":[{"t":"근거를 겨누고, 판정 결과에 승복한다","correct":true},{"t":"말이 거칠어져도 상대를 끝까지 누른다","mis":"K6-1-u3-X09"},{"t":"상대의 말투를 짚어 기를 꺾는다","mis":"K6-1-u3-X14"},{"t":"판정이 마음에 들지 않으면 따르지 않는다","mis":"K6-1-u3-X18"}],"explanation":["누르려 하면 말이 거칠어져요.","말투가 아니라 근거를 겨눠요.","결과에 승복해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L01_challenge#8','kor',6,1,'u3','L01','g6_1_kor_u3_L01_challenge','lesson_challenge','K6-1-u3-C4',4,'mc','auto','온유의 주장에 붙일 근거로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X04','K6-1-u3-X05','K6-1-u3-X28']::text[],false,'{"seq":8,"concept":"K6-1-u3-C4","difficulty":4,"kind":"mc","stem":"온유의 주장에 붙일 근거로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"구청이 지난해 낸 공원 주변 반려견 안전사고 자료","correct":true},{"t":"개들이 뛰어놀면 귀여울 것 같다는 내 느낌","mis":"K6-1-u3-X04"},{"t":"반려견 놀이터를 만들어야 한다는 말을 한 번 더 하기","mis":"K6-1-u3-X05"},{"t":"어디서 봤는지 모르는 동영상 이야기","mis":"K6-1-u3-X28"}],"explanation":["느낌은 근거가 아니에요.","주장을 되풀이한 것은 근거가 아니에요.","누가 언제 낸 자료인지 확인돼야 해요."],"asset":{"type":"speech","turns":[{"who":"온유","text":"마을 공원 한쪽에 반려견 놀이터를 만들면 좋겠어. 목줄을 풀고 뛸 곳이 없어서 개들이 인도까지 나오잖아."},{"who":"강토","text":"나는 반대야. 공원은 모두가 쓰는 곳인데 한쪽을 떼어 주면 아이들이 뛸 곳이 줄어들어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L01_challenge#9','kor',6,1,'u3','L01','g6_1_kor_u3_L01_challenge','lesson_challenge','K6-1-u3-C2',4,'essay','teacher','토의와 토론이 어떻게 같고 어떻게 다른지 쓰고, 각각에 알맞은 예를 하나씩 드세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u3-C2","difficulty":4,"kind":"essay","stem":"토의와 토론이 어떻게 같고 어떻게 다른지 쓰고, 각각에 알맞은 예를 하나씩 드세요.","answer_guide":{"answer":"예: 토의와 토론은 둘 다 문제를 해결하려고 여럿이 함께 이야기한다는 점이 같다. 다른 점은 찬반으로 편이 갈리는가이다. 토의는 편을 나누지 않고 의견을 모아 더 나은 방법을 찾는다. 예를 들어 학예회에서 우리 반이 무엇을 할지 아이디어를 모으는 일이다. 토론은 찬성 측과 반대 측으로 나뉘어 근거를 들어 자기 주장이 옳음을 밝힌다. 예를 들어 공원에 반려견 놀이터를 만들어야 하는가를 두고 겨루는 일이다.","scoring_points":["같은 점을 썼는가","찬반으로 편이 갈리는가로 다른 점을 썼는가","토의와 토론의 예를 하나씩 알맞게 들었는가"]},"explanation":["함께 이야기한다는 점은 같아요.","편이 갈리는지 살펴요.","예를 하나씩 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L01_challenge#10','kor',6,1,'u3','L01','g6_1_kor_u3_L01_challenge','lesson_challenge','K6-1-u3-C4',4,'essay','teacher','「공원에 반려견 놀이터를 만들어야 한다」라는 주장에 이유와 근거를 하나씩 붙여 쓰고, 이유와 근거가 어떻게 다른지 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u3-C4","difficulty":4,"kind":"essay","stem":"「공원에 반려견 놀이터를 만들어야 한다」라는 주장에 이유와 근거를 하나씩 붙여 쓰고, 이유와 근거가 어떻게 다른지 설명하세요.","answer_guide":{"answer":"예: 이유 — 목줄을 풀 곳이 없어 개들이 인도까지 나와 사고가 나기 쉽기 때문이다. 근거 — 우리 구청이 지난해 낸 공원 주변 안전사고 통계이다. 이유는 그렇게 주장하는 까닭으로 내 머릿속에서 나온 문장이고, 근거는 그 이유를 뒷받침하는 객관적인 자료로 밖에서 가져와 누가 언제 냈는지 확인할 수 있는 것이다.","scoring_points":["주장에 이어지는 이유를 썼는가","확인할 수 있는 근거를 썼는가","이유와 근거의 차이를 바르게 설명했는가"]},"explanation":["까닭을 먼저 써요.","밖에서 가져온 자료를 붙여요.","내 까닭과 밖의 자료로 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L02_basic#1','kor',6,1,'u3','L02','g6_1_kor_u3_L02_basic','lesson_basic','K6-1-u3-C9',1,'mc','auto','주장 펼치기에서 함께 내야 하는 것은 어느 것인가요?',ARRAY['K6-1-u3-X05','K6-1-u3-X06']::text[],false,'{"seq":1,"concept":"K6-1-u3-C9","difficulty":1,"kind":"mc","stem":"주장 펼치기에서 함께 내야 하는 것은 어느 것인가요?","options":[{"t":"주장 · 이유 · 근거","correct":true},{"t":"주장만","mis":"K6-1-u3-X05"},{"t":"반론과 답변","mis":"K6-1-u3-X06"},{"t":"판정 기준","mis":"K6-1-u3-X06"}],"explanation":["주장만 내면 확인할 수 없어요.","반론은 다음 단계예요.","세 층이 다 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L02_basic#2','kor',6,1,'u3','L02','g6_1_kor_u3_L02_basic','lesson_basic','K6-1-u3-C10',1,'mc','auto','근거가 될 수 있는 것은 어느 것인가요?',ARRAY['K6-1-u3-X04','K6-1-u3-X05']::text[],false,'{"seq":2,"concept":"K6-1-u3-C10","difficulty":1,"kind":"mc","stem":"근거가 될 수 있는 것은 어느 것인가요?","options":[{"t":"우리 학교 고학년 백스무 명에게 물은 설문 결과","correct":true},{"t":"운동장이 좁아서 답답하다고 느낀다","mis":"K6-1-u3-X04"},{"t":"나누어 쓰면 더 재미없을 것 같다","mis":"K6-1-u3-X04"},{"t":"운동장은 나누어 써야 한다","mis":"K6-1-u3-X05"}],"explanation":["느낌은 이유에 가까워요.","「같다」로 끝나는 말은 근거가 아니에요.","확인할 수 있는 설문은 근거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L02_basic#3','kor',6,1,'u3','L02','g6_1_kor_u3_L02_basic','lesson_basic','K6-1-u3-C13',1,'ox','auto','반론할 때에는 「그것도 모르십니까?」처럼 말해도 돼요.',ARRAY['K6-1-u3-X14']::text[],false,'{"seq":3,"concept":"K6-1-u3-C13","difficulty":1,"kind":"ox","stem":"반론할 때에는 「그것도 모르십니까?」처럼 말해도 돼요.","answer":"X","reason_options":[{"t":"반론은 사람이 아니라 주장 · 이유 · 근거를 겨누어야 하기 때문에","correct":true},{"t":"날카롭게 말해야 반론이 세지기 때문에","mis":"K6-1-u3-X14"}],"mis":"K6-1-u3-X14","explanation":["그 말은 사람을 겨눠요.","토론은 공식적인 말하기예요.","근거를 겨누어 되받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L02_basic#4','kor',6,1,'u3','L02','g6_1_kor_u3_L02_basic','lesson_basic','K6-1-u3-C15',1,'mc','auto','판정할 때 가장 먼저 있어야 하는 것은 어느 것인가요?',ARRAY['K6-1-u3-X16']::text[],false,'{"seq":4,"concept":"K6-1-u3-C15","difficulty":1,"kind":"mc","stem":"판정할 때 가장 먼저 있어야 하는 것은 어느 것인가요?","options":[{"t":"무엇을 보고 정할지 미리 밝혀 둔 명확한 판정 기준","correct":true},{"t":"판정단이 평소 어느 쪽 생각에 가까웠는지","mis":"K6-1-u3-X16"},{"t":"어느 쪽이 더 큰 목소리로 말했는지","mis":"K6-1-u3-X16"},{"t":"어느 쪽 토론자 수가 더 많은지","mis":"K6-1-u3-X16"}],"explanation":["평소 생각은 판정과 관계없어요.","목소리 크기는 기준이 아니에요.","기준이 없으면 판정이 아니라 취향이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L02_basic#5','kor',6,1,'u3','L02','g6_1_kor_u3_L02_basic','lesson_basic','K6-1-u3-C10',2,'match','auto','운동장 토론의 발언을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-1-u3-C10","difficulty":2,"kind":"match","stem":"운동장 토론의 발언을 알맞게 이으세요.","pairs":[{"l":"부딪히는 사고가 자주 일어난다","r":"찬성 측 이유"},{"l":"학생 회의가 조사한 보건실 이용 자료","r":"찬성 측 근거"},{"l":"학년이 섞여 노는 놀이가 사라진다","r":"반대 측 이유"},{"l":"이름을 밝히지 않은 선생님의 말","r":"반대 측 근거"}],"mis":"K6-1-u3-X04","explanation":["까닭인지 자료인지 먼저 나눠요.","그다음 찬반을 갈라요.","이유 아래에 근거가 놓여요."],"asset":{"type":"speech","turns":[{"who":"사회자 라온","text":"지금부터 「점심시간 운동장은 학년별로 나누어 써야 한다」라는 주제로 토론을 시작하겠습니다. 찬성 측부터 주장을 펼쳐 주십시오."},{"who":"찬성 측 벼리","text":"점심시간 운동장은 학년별로 나누어 써야 합니다. 모든 학년이 한꺼번에 나오면 부딪히는 사고가 자주 일어나기 때문입니다. 학생 회의가 지난 학기에 조사한 보건실 이용 자료를 보면, 운동장에서 부딪혀 다친 학생이 예순두 명이었습니다."},{"who":"반대 측 새얀","text":"운동장을 학년별로 나누어서는 안 됩니다. 학년이 섞여 노는 놀이가 사라지기 때문입니다. 저희가 만난 어느 선생님께서도 학년이 섞여 놀 때 아이들이 서로 배우는 것이 많다고 하셨습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L02_basic#6','kor',6,1,'u3','L02','g6_1_kor_u3_L02_basic','lesson_basic','K6-1-u3-C11',2,'mc','auto','새얀이의 첫 반론이 겨눈 곳은 어디인가요?',ARRAY['K6-1-u3-X14','K6-1-u3-X11','K6-1-u3-X06']::text[],false,'{"seq":6,"concept":"K6-1-u3-C11","difficulty":2,"kind":"mc","stem":"새얀이의 첫 반론이 겨눈 곳은 어디인가요?","options":[{"t":"찬성 측 근거 — 보건실 자료만으로는 학년이 섞였기 때문인지 알 수 없다는 점","correct":true},{"t":"벼리의 말투","mis":"K6-1-u3-X14"},{"t":"급식실 이야기","mis":"K6-1-u3-X11"},{"t":"반대 측 자신의 주장","mis":"K6-1-u3-X06"}],"explanation":["말투를 겨누지 않았어요.","새 이야기를 꺼내지 않았어요.","찬성 측 근거를 겨누었어요."],"asset":{"type":"speech","turns":[{"who":"반대 측 새얀","text":"보건실을 찾은 학생 수만으로는 학년이 섞였기 때문인지 알 수 없습니다. 같은 학년끼리 부딪힌 경우는 몇 건이었습니까?"},{"who":"찬성 측 벼리","text":"좋은 지적입니다. 같은 학년끼리 부딪힌 경우도 있었습니다. 다만 그 가운데 마흔한 건이 서로 다른 학년 사이에서 일어났습니다."},{"who":"찬성 측 벼리","text":"반대 측께 묻겠습니다. 근거로 드신 선생님이 어느 분인지 밝히지 않으셨습니다. 확인할 수 없는 말은 근거로 삼기 어렵지 않습니까?"},{"who":"반대 측 새얀","text":"성함까지 적어 두지는 못했습니다. 다만 여러 해 아이들을 보아 오신 분입니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L02_basic#7','kor',6,1,'u3','L02','g6_1_kor_u3_L02_basic','lesson_basic','K6-1-u3-C14',2,'mc','auto','주장 다지기에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X15','K6-1-u3-X06']::text[],false,'{"seq":7,"concept":"K6-1-u3-C14","difficulty":2,"kind":"mc","stem":"주장 다지기에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"앞 두 단계에서 남은 것을 추려 자기편 주장을 다시 세운다","correct":true},{"t":"주장 펼치기에서 한 말을 그대로 되풀이한다","mis":"K6-1-u3-X15"},{"t":"반론에서 무너진 근거도 다시 꺼내 힘준다","mis":"K6-1-u3-X15"},{"t":"상대 주장을 처음으로 되받는다","mis":"K6-1-u3-X06"}],"explanation":["되풀이하는 단계가 아니에요.","무너진 근거를 꺼내면 약해져요.","남은 것을 추려 다시 세워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L02_basic#8','kor',6,1,'u3','L02','g6_1_kor_u3_L02_basic','lesson_basic','K6-1-u3-C17',2,'mc','auto','토론에서 해도 되는 말은 어느 것인가요?',ARRAY['K6-1-u3-X14','K6-1-u3-X11','K6-1-u3-X07']::text[],false,'{"seq":8,"concept":"K6-1-u3-C17","difficulty":2,"kind":"mc","stem":"토론에서 해도 되는 말은 어느 것인가요?","options":[{"t":"「말씀 잘 들었습니다. 다만 한 가지 여쭙겠습니다.」","correct":true},{"t":"「운동장 나누자고? 말도 안 돼.」","mis":"K6-1-u3-X14"},{"t":"「그런데 저는 요즘 급식이 더 문제라고 봅니다.」","mis":"K6-1-u3-X11"},{"t":"상대가 말하는 중간에 끼어들어 되받는 말","mis":"K6-1-u3-X07"}],"explanation":["반말로 깎아내리면 안 돼요.","주제와 상관없는 말이에요.","말차례를 지키고 높임말을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L02_basic#9','kor',6,1,'u3','L02','g6_1_kor_u3_L02_basic','lesson_basic','K6-1-u3-C16',2,'ox','auto','판정 결과는 어느 쪽 생각이 옳은지를 가려 주는 것이에요.',ARRAY['K6-1-u3-X17']::text[],false,'{"seq":9,"concept":"K6-1-u3-C16","difficulty":2,"kind":"ox","stem":"판정 결과는 어느 쪽 생각이 옳은지를 가려 주는 것이에요.","answer":"X","reason_options":[{"t":"정해 둔 기준으로 볼 때 어느 쪽이 더 설득력 있게 말했는지를 정하는 일이기 때문에","correct":true},{"t":"판정단은 언제나 옳은 답을 알기 때문에","mis":"K6-1-u3-X17"}],"mis":"K6-1-u3-X17","explanation":["토론이 끝나도 두 생각은 남아요.","기준이 달라지면 결과도 달라져요.","더 설득력 있게 말한 쪽을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L02_basic#10','kor',6,1,'u3','L02','g6_1_kor_u3_L02_basic','lesson_basic','K6-1-u3-C12',3,'mc','auto','벼리가 새얀이의 반론에 답한 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X13','K6-1-u3-X14','K6-1-u3-X11']::text[],false,'{"seq":10,"concept":"K6-1-u3-C12","difficulty":3,"kind":"mc","stem":"벼리가 새얀이의 반론에 답한 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"인정할 것은 인정하고, 서로 다른 학년 사이 마흔한 건이라는 자료로 다시 세웠다","correct":true},{"t":"물은 것에 답하지 않고 「안전하니까 나눠야 합니다」만 되풀이했다","mis":"K6-1-u3-X13"},{"t":"새얀이의 말투를 문제 삼았다","mis":"K6-1-u3-X14"},{"t":"새로운 주제를 꺼내 말을 돌렸다","mis":"K6-1-u3-X11"}],"explanation":["벼리는 물은 것에 곧바로 답했어요.","사람을 겨누지 않았어요.","인정하고 자료로 다시 세웠어요."],"asset":{"type":"speech","turns":[{"who":"반대 측 새얀","text":"보건실을 찾은 학생 수만으로는 학년이 섞였기 때문인지 알 수 없습니다. 같은 학년끼리 부딪힌 경우는 몇 건이었습니까?"},{"who":"찬성 측 벼리","text":"좋은 지적입니다. 같은 학년끼리 부딪힌 경우도 있었습니다. 다만 그 가운데 마흔한 건이 서로 다른 학년 사이에서 일어났습니다."},{"who":"찬성 측 벼리","text":"반대 측께 묻겠습니다. 근거로 드신 선생님이 어느 분인지 밝히지 않으셨습니다. 확인할 수 없는 말은 근거로 삼기 어렵지 않습니까?"},{"who":"반대 측 새얀","text":"성함까지 적어 두지는 못했습니다. 다만 여러 해 아이들을 보아 오신 분입니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L02_challenge#1','kor',6,1,'u3','L02','g6_1_kor_u3_L02_challenge','lesson_challenge','K6-1-u3-C11',2,'mc','auto','반론하기에서 오간 말을 정리하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X12','K6-1-u3-X11','K6-1-u3-X38']::text[],false,'{"seq":1,"concept":"K6-1-u3-C11","difficulty":2,"kind":"mc","stem":"반론하기에서 오간 말을 정리하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"발언을 그대로 옮기지 않고 핵심만 요약한다","correct":true},{"t":"상대 발언을 한 글자도 빠짐없이 옮겨 적는다","mis":"K6-1-u3-X12"},{"t":"주장 펼치기에 나오지 않은 새 이야기도 함께 되받는다","mis":"K6-1-u3-X11"},{"t":"상대의 표정까지 자세히 적는다","mis":"K6-1-u3-X38"}],"explanation":["다 옮기면 다음 말을 놓쳐요.","펼친 내용에 대해서만 되받아요.","핵심만 요약해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L02_challenge#2','kor',6,1,'u3','L02','g6_1_kor_u3_L02_challenge','lesson_challenge','K6-1-u3-C14',2,'ox','auto','주장 다지기에서는 「요컨대」, 「따라서」 같은 말을 써서 짧고 힘 있게 말하면 좋아요.',ARRAY['K6-1-u3-X15']::text[],false,'{"seq":2,"concept":"K6-1-u3-C14","difficulty":2,"kind":"ox","stem":"주장 다지기에서는 「요컨대」, 「따라서」 같은 말을 써서 짧고 힘 있게 말하면 좋아요.","answer":"O","reason_options":[{"t":"정리하는 단계라는 표시가 되고 중심이 또렷해지기 때문에","correct":true},{"t":"같은 말을 여러 번 되풀이할수록 설득력이 커지기 때문에","mis":"K6-1-u3-X15"}],"mis":"K6-1-u3-X15","explanation":["이어 주는 말은 정리의 표시예요.","짧게 말하면 중심이 또렷해요.","되풀이가 아니라 다시 세우기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L02_challenge#3','kor',6,1,'u3','L02','g6_1_kor_u3_L02_challenge','lesson_challenge','K6-1-u3-C16',3,'mc','auto','윤재의 판정에서 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X17','K6-1-u3-X18','K6-1-u3-X16']::text[],false,'{"seq":3,"concept":"K6-1-u3-C16","difficulty":3,"kind":"mc","stem":"윤재의 판정에서 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"정한 두 기준으로 보아 찬성 측이 더 설득력 있었다는 것이지, 반대 측 생각이 틀렸다는 뜻은 아니다","correct":true},{"t":"반대 측 생각은 틀렸으니 버려야 한다","mis":"K6-1-u3-X17"},{"t":"판정이 마음에 들지 않으면 반대 측은 따르지 않아도 된다","mis":"K6-1-u3-X18"},{"t":"윤재가 평소 찬성 측 생각이어서 찬성 측을 골랐다","mis":"K6-1-u3-X16"}],"explanation":["판정은 옳고 그름을 가리지 않아요.","결과에 승복해요.","윤재는 기준을 밝히고 정했어요."],"asset":{"type":"speech","turns":[{"who":"판정단 윤재","text":"저희는 두 가지 기준으로 보았습니다. 첫째, 주장에 대한 타당한 이유를 냈는가. 둘째, 객관적이고 믿을 수 있는 근거를 냈는가."},{"who":"판정단 윤재","text":"두 기준으로 볼 때 찬성 측이 조금 더 설득력 있었다고 판정합니다. 반대 측의 이유는 충분히 공감이 갔지만 근거로 든 말의 출처가 확인되지 않았습니다. 반대 측이 안전을 다르게 지킬 방법을 낸 점은 좋았습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L02_challenge#4','kor',6,1,'u3','L02','g6_1_kor_u3_L02_challenge','lesson_challenge','K6-1-u3-C13',3,'error','auto','반론하는 말을 했어요. 알맞지 않은 말을 한 친구는 누구인가요?',ARRAY['K6-1-u3-X14','K6-1-u3-X29','K6-1-u3-X27']::text[],false,'{"seq":4,"concept":"K6-1-u3-C13","difficulty":3,"kind":"error","stem":"반론하는 말을 했어요. 알맞지 않은 말을 한 친구는 누구인가요?","options":[{"t":"가온 — 「그렇게 준비도 안 하고 토론에 나온 것이 이해가 안 됩니다.」","correct":true,"mis_target":"K6-1-u3-X14"},{"t":"보미 — 「그 자료는 조사한 때가 나와 있지 않습니다.」","mis":"K6-1-u3-X29"},{"t":"지안 — 「그 이유는 주장과 이어지지 않아 보입니다.」","mis":"K6-1-u3-X27"}],"explanation":["보미는 근거를 겨누었어요.","지안은 이유를 겨누었어요.","가온은 사람을 겨누었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L02_challenge#5','kor',6,1,'u3','L02','g6_1_kor_u3_L02_challenge','lesson_challenge','K6-1-u3-C12',3,'mc','auto','「그 자료는 언제 조사했는지 나와 있지 않습니다.」라는 반론에 대한 답변으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X13','K6-1-u3-X14','K6-1-u3-X11']::text[],false,'{"seq":5,"concept":"K6-1-u3-C12","difficulty":3,"kind":"mc","stem":"「그 자료는 언제 조사했는지 나와 있지 않습니다.」라는 반론에 대한 답변으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「지난 학기에 학생 회의가 조사한 자료입니다. 조사한 때는 자료 맨 위에 적혀 있습니다.」","correct":true},{"t":"「어쨌든 저희 주장이 맞습니다.」","mis":"K6-1-u3-X13"},{"t":"「그런 것까지 따지는 건 예의가 아닙니다.」","mis":"K6-1-u3-X14"},{"t":"「그런데 요즘은 급식이 더 문제입니다.」","mis":"K6-1-u3-X11"}],"explanation":["되풀이는 답변이 아니에요.","반론한 사람을 겨누면 안 돼요.","물은 그 지점에 곧바로 답해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L02_challenge#6','kor',6,1,'u3','L02','g6_1_kor_u3_L02_challenge','lesson_challenge','K6-1-u3-C10',3,'mc','auto','새얀이가 근거로 든 「어느 선생님」의 말이 힘을 잃은 까닭은 무엇인가요?',ARRAY['K6-1-u3-X31','K6-1-u3-X27','K6-1-u3-X16']::text[],false,'{"seq":6,"concept":"K6-1-u3-C10","difficulty":3,"kind":"mc","stem":"새얀이가 근거로 든 「어느 선생님」의 말이 힘을 잃은 까닭은 무엇인가요?","options":[{"t":"누구의 말인지 밝히지 않아 확인할 수 없기 때문에","correct":true},{"t":"선생님의 말은 언제나 근거로 쓸 수 없기 때문에","mis":"K6-1-u3-X31"},{"t":"반대 측 이유와 상관없는 이야기였기 때문에","mis":"K6-1-u3-X27"},{"t":"새얀이의 목소리가 작았기 때문에","mis":"K6-1-u3-X16"}],"explanation":["전문가의 말도 근거가 될 수 있어요.","이유와는 이어졌어요.","누구의 말인지 밝혀야 해요."],"asset":{"type":"speech","turns":[{"who":"반대 측 새얀","text":"보건실을 찾은 학생 수만으로는 학년이 섞였기 때문인지 알 수 없습니다. 같은 학년끼리 부딪힌 경우는 몇 건이었습니까?"},{"who":"찬성 측 벼리","text":"좋은 지적입니다. 같은 학년끼리 부딪힌 경우도 있었습니다. 다만 그 가운데 마흔한 건이 서로 다른 학년 사이에서 일어났습니다."},{"who":"찬성 측 벼리","text":"반대 측께 묻겠습니다. 근거로 드신 선생님이 어느 분인지 밝히지 않으셨습니다. 확인할 수 없는 말은 근거로 삼기 어렵지 않습니까?"},{"who":"반대 측 새얀","text":"성함까지 적어 두지는 못했습니다. 다만 여러 해 아이들을 보아 오신 분입니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L02_challenge#7','kor',6,1,'u3','L02','g6_1_kor_u3_L02_challenge','lesson_challenge','K6-1-u3-C5',3,'match','auto','단계와 그 단계에서 하는 일을 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-1-u3-C5","difficulty":3,"kind":"match","stem":"단계와 그 단계에서 하는 일을 이으세요.","pairs":[{"l":"주장과 이유, 근거를 처음으로 내놓는다","r":"주장 펼치기"},{"l":"상대 근거의 허점을 짚고 그에 답한다","r":"반론하기"},{"l":"남은 것만 추려 자기편 주장을 다시 강조한다","r":"주장 다지기"},{"l":"기준을 밝히고 더 설득력 있는 쪽을 정한다","r":"판정하기"}],"mis":"K6-1-u3-X06","explanation":["처음 내놓는 단계부터 찾아요.","되받는 단계와 다시 세우는 단계를 갈라요.","정하는 단계는 맨 끝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L02_challenge#8','kor',6,1,'u3','L02','g6_1_kor_u3_L02_challenge','lesson_challenge','K6-1-u3-C14',4,'mc','auto','벼리와 새얀이의 주장 다지기를 평가한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X15','K6-1-u3-X14']::text[],false,'{"seq":8,"concept":"K6-1-u3-C14","difficulty":4,"kind":"mc","stem":"벼리와 새얀이의 주장 다지기를 평가한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"벼리는 반론에서 확인된 마흔한 건을 추려 다시 세웠고, 새얀이는 안전을 지킬 다른 방법으로 자기 주장을 다졌다","correct":true},{"t":"두 사람 모두 처음 한 말을 그대로 되풀이했을 뿐이다","mis":"K6-1-u3-X15"},{"t":"새얀이는 확인되지 않은 선생님 말을 다시 꺼내 힘을 더했다","mis":"K6-1-u3-X15"},{"t":"주장 다지기에서는 상대 말투를 짚는 것이 가장 중요하다","mis":"K6-1-u3-X14"}],"explanation":["두 사람은 되풀이하지 않았어요.","새얀이는 무너진 근거를 꺼내지 않았어요.","남은 것을 추려 다시 세웠어요."],"asset":{"type":"speech","turns":[{"who":"찬성 측 벼리","text":"요컨대 문제는 안전입니다. 서로 다른 학년 사이에서 일어난 마흔한 건은 학년을 나누면 줄어듭니다. 따라서 점심시간 운동장은 학년별로 나누어 써야 합니다."},{"who":"반대 측 새얀","text":"저희가 지키려는 것은 함께 노는 시간입니다. 안전은 나누지 않고도 지킬 수 있습니다. 뛰는 곳과 공놀이하는 곳을 갈라 놓으면 됩니다. 따라서 운동장을 학년별로 나눌 필요는 없습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L02_challenge#9','kor',6,1,'u3','L02','g6_1_kor_u3_L02_challenge','lesson_challenge','K6-1-u3-C13',4,'essay','teacher','반론이 「사람을 겨누지 않고 주장 · 이유 · 근거를 겨누어야 한다」는 것이 무슨 뜻인지 설명하고, 운동장 토론에서 반대 측 근거를 겨누는 반론을 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u3-C13","difficulty":4,"kind":"essay","stem":"반론이 「사람을 겨누지 않고 주장 · 이유 · 근거를 겨누어야 한다」는 것이 무슨 뜻인지 설명하고, 운동장 토론에서 반대 측 근거를 겨누는 반론을 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 반론은 상대가 내놓은 주장이나 이유, 근거에서 잘못되거나 궁금한 곳을 짚는 것이지, 상대가 준비를 못 했다거나 말투가 거슬린다고 말하는 것이 아니다. 토론은 공식적인 말하기라 높임말을 쓰고 공격적인 말투를 피한다. 반론 — 「근거로 드신 선생님의 말은 어느 분이 언제 하신 말인지 밝혀지지 않아 확인하기 어렵습니다.」","scoring_points":["사람이 아니라 주장 · 이유 · 근거를 겨눈다는 뜻을 썼는가","높임말 · 존중하는 태도를 썼는가","반대 측 근거를 겨누는 반론을 높임말로 썼는가"]},"explanation":["겨누는 곳이 어디인지 써요.","공식적인 말하기임을 떠올려요.","근거의 허점을 짚어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L02_challenge#10','kor',6,1,'u3','L02','g6_1_kor_u3_L02_challenge','lesson_challenge','K6-1-u3-C15',4,'essay','teacher','판정할 때 명확한 기준이 왜 먼저 있어야 하는지 쓰고, 「판정 결과가 늘 옳은 것은 아니다」라는 말의 뜻을 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u3-C15","difficulty":4,"kind":"essay","stem":"판정할 때 명확한 기준이 왜 먼저 있어야 하는지 쓰고, 「판정 결과가 늘 옳은 것은 아니다」라는 말의 뜻을 설명하세요.","answer_guide":{"answer":"예: 무엇을 보고 정했는지 밝히지 않으면 판정이 판정단의 취향이 되어 토론자가 결과에 승복하기 어렵다. 그래서 「타당한 이유를 냈는가 · 믿을 수 있는 근거를 냈는가」처럼 기준을 먼저 밝혀야 한다. 판정은 어느 쪽 생각이 옳은지 가리는 일이 아니라 정한 기준으로 볼 때 어느 쪽이 더 설득력 있게 말했는지 정하는 일이다. 그래서 기준이 달라지면 결과도 달라질 수 있고, 판정 뒤에도 두 생각은 그대로 남는다.","scoring_points":["기준이 없으면 취향이 되고 승복하기 어렵다는 점을 썼는가","판정은 더 설득력 있게 말한 쪽을 정하는 일임을 썼는가","기준에 따라 결과가 달라질 수 있음을 썼는가"]},"explanation":["기준이 없을 때를 떠올려요.","판정이 무엇을 정하는지 써요.","기준이 바뀌면 어떻게 될지 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L04_basic#1','kor',6,1,'u3','L04','g6_1_kor_u3_L04_basic','lesson_basic','K6-1-u3-C18',1,'mc','auto','우리 반 토론 주제로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X01']::text[],false,'{"seq":1,"concept":"K6-1-u3-C18","difficulty":1,"kind":"mc","stem":"우리 반 토론 주제로 알맞은 것은 어느 것인가요?","options":[{"t":"청소 당번을 제비뽑기로 정할 것인가","correct":true},{"t":"우리 반 학생 수가 몇 명인가","mis":"K6-1-u3-X01"},{"t":"지난주 급식 식단에 무엇이 나왔는가","mis":"K6-1-u3-X01"},{"t":"복도에서 뛰지 말아야 하는가","mis":"K6-1-u3-X01"}],"explanation":["학생 수는 세어 보면 알아요.","식단은 찾아보면 확인돼요.","찬반이 갈리고 우리가 바꿔 볼 수 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L04_basic#2','kor',6,1,'u3','L04','g6_1_kor_u3_L04_basic','lesson_basic','K6-1-u3-C23',1,'match','auto','역할과 할 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K6-1-u3-C23","difficulty":1,"kind":"match","stem":"역할과 할 일을 알맞게 이으세요.","pairs":[{"l":"주제와 규칙을 알리고 말차례를 이끈다","r":"사회자"},{"l":"근거를 들어 간결하고 분명하게 주장한다","r":"토론자"},{"l":"기준을 정해 공정하게 판정한다","r":"판정단"},{"l":"메모하며 듣고 잘한 곳을 짚어 준다","r":"청중"}],"mis":"K6-1-u3-X25","explanation":["이끄는 사람은 사회자예요.","말하는 사람은 토론자예요.","정하는 사람은 판정단, 듣고 짚는 사람은 청중이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L04_basic#3','kor',6,1,'u3','L04','g6_1_kor_u3_L04_basic','lesson_basic','K6-1-u3-C22',1,'ox','auto','예상되는 상대측 반론과 답변을 미리 적어 보는 일은 건너뛰어도 돼요.',ARRAY['K6-1-u3-X23']::text[],false,'{"seq":3,"concept":"K6-1-u3-C22","difficulty":1,"kind":"ox","stem":"예상되는 상대측 반론과 답변을 미리 적어 보는 일은 건너뛰어도 돼요.","answer":"X","reason_options":[{"t":"적어 보는 동안 내 근거의 약한 곳이 먼저 보이기 때문에","correct":true},{"t":"토론에서는 그때그때 떠오르는 대로 답하면 되기 때문에","mis":"K6-1-u3-X23"}],"mis":"K6-1-u3-X23","explanation":["상대의 반론을 미리 떠올려요.","내 근거의 약한 곳이 보여요.","그래서 건너뛰지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L04_basic#4','kor',6,1,'u3','L04','g6_1_kor_u3_L04_basic','lesson_basic','K6-1-u3-C21',1,'mc','auto','전문가의 의견을 근거로 쓸 때 반드시 함께 적어 둘 것은 어느 것인가요?',ARRAY['K6-1-u3-X38','K6-1-u3-X04','K6-1-u3-X22']::text[],false,'{"seq":4,"concept":"K6-1-u3-C21","difficulty":1,"kind":"mc","stem":"전문가의 의견을 근거로 쓸 때 반드시 함께 적어 둘 것은 어느 것인가요?","options":[{"t":"누구의 말인지","correct":true},{"t":"그 사람의 목소리","mis":"K6-1-u3-X38"},{"t":"내가 그 말을 좋아하는지","mis":"K6-1-u3-X04"},{"t":"아무것도 적지 않아도 된다","mis":"K6-1-u3-X22"}],"explanation":["목소리는 근거와 상관없어요.","내 마음은 근거가 아니에요.","누구의 말인지 적어야 확인돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L04_basic#5','kor',6,1,'u3','L04','g6_1_kor_u3_L04_basic','lesson_basic','K6-1-u3-C20',2,'mc','auto','준비표의 「우리 반 스물여섯 명에게 물어보니 …」는 어느 층인가요?',ARRAY['K6-1-u3-X05','K6-1-u3-X04','K6-1-u3-X13']::text[],false,'{"seq":5,"concept":"K6-1-u3-C20","difficulty":2,"kind":"mc","stem":"준비표의 「우리 반 스물여섯 명에게 물어보니 …」는 어느 층인가요?","options":[{"t":"근거","correct":true},{"t":"주장","mis":"K6-1-u3-X05"},{"t":"이유","mis":"K6-1-u3-X04"},{"t":"우리 측 답변","mis":"K6-1-u3-X13"}],"explanation":["하자고 내세운 말이 아니에요.","까닭을 말한 문장도 아니에요.","물어서 센 자료는 근거예요."],"asset":{"type":"passage","lines":["토론 주제 — 우리 반 청소 당번은 제비뽑기로 정해야 한다.","주장 — 청소 당번은 제비뽑기로 정해야 합니다.","이유 — 힘든 곳을 늘 같은 사람이 맡게 되는 일을 막을 수 있기 때문입니다.","근거 — 우리 반 스물여섯 명에게 물어보니, 지난 학기에 화장실 청소를","세 번 넘게 맡은 학생이 아홉 명이었습니다.","예상 반론 — 제비뽑기는 잘 맞는 일을 못 살립니다.","우리 측 답변 — 뽑은 뒤 서로 바꿀 수 있게 하면 풀립니다."],"title":"찬성 측 토론 준비표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L04_basic#6','kor',6,1,'u3','L04','g6_1_kor_u3_L04_basic','lesson_basic','K6-1-u3-C19',2,'mc','auto','토론 주제가 정해진 뒤 가장 먼저 할 일은 어느 것인가요?',ARRAY['K6-1-u3-X20','K6-1-u3-X06']::text[],false,'{"seq":6,"concept":"K6-1-u3-C19","difficulty":2,"kind":"mc","stem":"토론 주제가 정해진 뒤 가장 먼저 할 일은 어느 것인가요?","options":[{"t":"모두가 자기 생각을 먼저 정한다","correct":true},{"t":"사회자와 판정단부터 뽑는다","mis":"K6-1-u3-X20"},{"t":"친한 친구끼리 한편이 된다","mis":"K6-1-u3-X20"},{"t":"곧바로 판정 기준을 발표한다","mis":"K6-1-u3-X06"}],"explanation":["역할은 그다음에 나눠요.","친한 사이로 편을 정하지 않아요.","먼저 모두가 자기 생각을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L04_basic#7','kor',6,1,'u3','L04','g6_1_kor_u3_L04_basic','lesson_basic','K6-1-u3-C22',2,'mc','auto','준비표의 「우리 측 답변」이 알맞은 까닭은 무엇인가요?',ARRAY['K6-1-u3-X13','K6-1-u3-X11','K6-1-u3-X14']::text[],false,'{"seq":7,"concept":"K6-1-u3-C22","difficulty":2,"kind":"mc","stem":"준비표의 「우리 측 답변」이 알맞은 까닭은 무엇인가요?","options":[{"t":"「잘 맞는 일을 못 살린다」는 반론에 서로 바꿀 수 있게 하는 방법으로 곧바로 답했기 때문에","correct":true},{"t":"「어쨌든 공평하다」고만 했기 때문에","mis":"K6-1-u3-X13"},{"t":"반론과 상관없는 이야기를 했기 때문에","mis":"K6-1-u3-X11"},{"t":"반론한 친구의 말투를 짚었기 때문에","mis":"K6-1-u3-X14"}],"explanation":["되풀이는 답변이 아니에요.","반론과 이어지게 답해요.","물은 그 지점에 곧바로 답했어요."],"asset":{"type":"passage","lines":["토론 주제 — 우리 반 청소 당번은 제비뽑기로 정해야 한다.","주장 — 청소 당번은 제비뽑기로 정해야 합니다.","이유 — 힘든 곳을 늘 같은 사람이 맡게 되는 일을 막을 수 있기 때문입니다.","근거 — 우리 반 스물여섯 명에게 물어보니, 지난 학기에 화장실 청소를","세 번 넘게 맡은 학생이 아홉 명이었습니다.","예상 반론 — 제비뽑기는 잘 맞는 일을 못 살립니다.","우리 측 답변 — 뽑은 뒤 서로 바꿀 수 있게 하면 풀립니다."],"title":"찬성 측 토론 준비표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L04_basic#8','kor',6,1,'u3','L04','g6_1_kor_u3_L04_basic','lesson_basic','K6-1-u3-C25',2,'ox','auto','반론하기에서 감정이 앞설 때일수록 말차례를 기다리고 한 번에 한 가지만 되받아요.',ARRAY['K6-1-u3-X26']::text[],false,'{"seq":8,"concept":"K6-1-u3-C25","difficulty":2,"kind":"ox","stem":"반론하기에서 감정이 앞설 때일수록 말차례를 기다리고 한 번에 한 가지만 되받아요.","answer":"O","reason_options":[{"t":"지나치게 뜨거워지면 서로의 말이 들리지 않아 되받을 수도 없기 때문에","correct":true},{"t":"목소리를 높여야 상대가 물러서기 때문에","mis":"K6-1-u3-X26"}],"mis":"K6-1-u3-X26","explanation":["반론하기는 뜨거워지기 쉬워요.","듣지 못하면 되받을 수 없어요.","침착하게 한 가지씩 되받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L04_basic#9','kor',6,1,'u3','L04','g6_1_kor_u3_L04_basic','lesson_basic','K6-1-u3-C24',2,'mc','auto','진행 순서에서 「반대 측 반론과 찬성 측 답변」 바로 다음에 오는 것은 어느 것인가요?',ARRAY['K6-1-u3-X06']::text[],false,'{"seq":9,"concept":"K6-1-u3-C24","difficulty":2,"kind":"mc","stem":"진행 순서에서 「반대 측 반론과 찬성 측 답변」 바로 다음에 오는 것은 어느 것인가요?","options":[{"t":"찬성 측 반론과 반대 측 답변","correct":true},{"t":"찬성 측 주장 펼치기","mis":"K6-1-u3-X06"},{"t":"판정단의 판정","mis":"K6-1-u3-X06"},{"t":"반대 측 주장 다지기","mis":"K6-1-u3-X06"}],"explanation":["주장 펼치기는 이미 끝났어요.","판정은 맨 끝이에요.","이번에는 찬성 측이 되받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L04_basic#10','kor',6,1,'u3','L04','g6_1_kor_u3_L04_basic','lesson_basic','K6-1-u3-C18',3,'mc','auto','「늘 그래 왔던 일에도 꼭 그래야 할까」라고 물어보라고 하는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X09','K6-1-u3-X01','K6-1-u3-X19']::text[],false,'{"seq":10,"concept":"K6-1-u3-C18","difficulty":3,"kind":"mc","stem":"「늘 그래 왔던 일에도 꼭 그래야 할까」라고 물어보라고 하는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"당연해 보이던 곳에서 찬반이 갈리는 좋은 주제가 나오기 때문에","correct":true},{"t":"늘 하던 일은 모두 잘못된 일이기 때문에","mis":"K6-1-u3-X09"},{"t":"답이 정해진 일이 가장 좋은 주제이기 때문에","mis":"K6-1-u3-X01"},{"t":"우리가 바꿀 수 없는 일일수록 토론이 재미있기 때문에","mis":"K6-1-u3-X19"}],"explanation":["늘 하던 일이 모두 잘못된 것은 아니에요.","답이 정해진 일은 토론이 안 돼요.","당연한 곳에서 좋은 주제가 나와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L04_challenge#1','kor',6,1,'u3','L04','g6_1_kor_u3_L04_challenge','lesson_challenge','K6-1-u3-C20',2,'mc','auto','토론 준비표에 이유를 두세 가지 준비하는 까닭은 무엇인가요?',ARRAY['K6-1-u3-X30','K6-1-u3-X05','K6-1-u3-X15']::text[],false,'{"seq":1,"concept":"K6-1-u3-C20","difficulty":2,"kind":"mc","stem":"토론 준비표에 이유를 두세 가지 준비하는 까닭은 무엇인가요?","options":[{"t":"하나가 무너져도 남은 것으로 버틸 수 있기 때문에","correct":true},{"t":"이유가 많을수록 판정단이 무조건 점수를 주기 때문에","mis":"K6-1-u3-X30"},{"t":"이유가 많으면 근거를 찾지 않아도 되기 때문에","mis":"K6-1-u3-X05"},{"t":"같은 이유를 여러 번 말하기 위해서","mis":"K6-1-u3-X15"}],"explanation":["개수만으로 점수를 받지 않아요.","이유마다 근거가 필요해요.","하나가 무너져도 버틸 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L04_challenge#2','kor',6,1,'u3','L04','g6_1_kor_u3_L04_challenge','lesson_challenge','K6-1-u3-C23',2,'ox','auto','판정단은 자기 생각과 같은 편이면 점수를 조금 더 줘도 돼요.',ARRAY['K6-1-u3-X24']::text[],false,'{"seq":2,"concept":"K6-1-u3-C23","difficulty":2,"kind":"ox","stem":"판정단은 자기 생각과 같은 편이면 점수를 조금 더 줘도 돼요.","answer":"X","reason_options":[{"t":"판정단은 정한 기준으로 공정하게 판정해야 하기 때문에","correct":true},{"t":"판정단도 자기 생각이 있기 때문에","mis":"K6-1-u3-X24"}],"mis":"K6-1-u3-X24","explanation":["판정단도 생각이 있을 수 있어요.","그러나 판정은 기준으로 해요.","같은 편이라고 후하게 주지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L04_challenge#3','kor',6,1,'u3','L04','g6_1_kor_u3_L04_challenge','lesson_challenge','K6-1-u3-C21',3,'mc','auto','「힘든 곳을 늘 같은 사람이 맡게 된다」는 이유를 뒷받침할 근거로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X04','K6-1-u3-X29','K6-1-u3-X27']::text[],false,'{"seq":3,"concept":"K6-1-u3-C21","difficulty":3,"kind":"mc","stem":"「힘든 곳을 늘 같은 사람이 맡게 된다」는 이유를 뒷받침할 근거로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"지난 학기 청소 점검표에 남은, 학생별 화장실 청소 횟수 기록","correct":true},{"t":"청소가 귀찮다고 느낀 적이 있다는 내 생각","mis":"K6-1-u3-X04"},{"t":"제비뽑기가 재미있어 보인다는 친구 한 명의 말","mis":"K6-1-u3-X29"},{"t":"점심시간 운동장 사고 자료","mis":"K6-1-u3-X27"}],"explanation":["내 생각은 근거가 아니에요.","친구 한 명의 말은 흐릿해요.","이유와 곧바로 이어지는 기록이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L04_challenge#4','kor',6,1,'u3','L04','g6_1_kor_u3_L04_challenge','lesson_challenge','K6-1-u3-C22',3,'mc','auto','「제비뽑기를 하면 힘이 센 학생이 가벼운 구역을 뽑을 수도 있습니다.」라는 반론에 대한 답변으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X13','K6-1-u3-X08','K6-1-u3-X14']::text[],false,'{"seq":4,"concept":"K6-1-u3-C22","difficulty":3,"kind":"mc","stem":"「제비뽑기를 하면 힘이 센 학생이 가벼운 구역을 뽑을 수도 있습니다.」라는 반론에 대한 답변으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「그 점은 뽑은 뒤 서로 바꿀 수 있게 하면 풀립니다. 처음 나누는 방법이 공평해야 바꾸는 일도 공평해집니다.」","correct":true},{"t":"「어쨌든 제비뽑기가 공평합니다. 공평하니까 공평합니다.」","mis":"K6-1-u3-X13"},{"t":"「그 이야기는 들을 필요가 없습니다.」","mis":"K6-1-u3-X08"},{"t":"「힘센 사람이 양보하면 되는데 그것도 모르십니까?」","mis":"K6-1-u3-X14"}],"explanation":["되풀이는 답이 아니에요.","반론을 듣고 답해야 해요.","물은 점을 풀어 주며 답해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L04_challenge#5','kor',6,1,'u3','L04','g6_1_kor_u3_L04_challenge','lesson_challenge','K6-1-u3-C23',3,'error','auto','토론에서 맡은 일을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u3-X37','K6-1-u3-X25','K6-1-u3-X24']::text[],false,'{"seq":5,"concept":"K6-1-u3-C23","difficulty":3,"kind":"error","stem":"토론에서 맡은 일을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"다온(청중) — 「청중은 할 일이 없으니 쉬면서 들으면 돼.」","correct":true,"mis_target":"K6-1-u3-X37"},{"t":"이준(사회자) — 「주제에서 벗어나면 다시 주제로 이끌게.」","mis":"K6-1-u3-X25"},{"t":"하린(판정단) — 「내 생각과 같은 편이라고 후하게 주지 않을게.」","mis":"K6-1-u3-X24"}],"explanation":["이준은 사회자의 일을 바르게 말했어요.","하린은 판정단의 일을 바르게 말했어요.","청중도 메모하고 잘한 곳을 짚어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L04_challenge#6','kor',6,1,'u3','L04','g6_1_kor_u3_L04_challenge','lesson_challenge','K6-1-u3-C24',3,'mc','auto','토론 단계 사이에 협의 시간을 두는 까닭은 무엇인가요?',ARRAY['K6-1-u3-X09','K6-1-u3-X16','K6-1-u3-X06']::text[],false,'{"seq":6,"concept":"K6-1-u3-C24","difficulty":3,"kind":"mc","stem":"토론 단계 사이에 협의 시간을 두는 까닭은 무엇인가요?","options":[{"t":"같은 편끼리 반론과 답변을 맞춰 두기 위해서","correct":true},{"t":"상대 편 원고를 몰래 보기 위해서","mis":"K6-1-u3-X09"},{"t":"판정단이 미리 승패를 정하기 위해서","mis":"K6-1-u3-X16"},{"t":"토론을 빨리 끝내기 위해서","mis":"K6-1-u3-X06"}],"explanation":["몰래 보는 것은 규칙을 어겨요.","판정은 끝난 뒤 기준으로 해요.","같은 편끼리 맞춰 두는 시간이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L04_challenge#7','kor',6,1,'u3','L04','g6_1_kor_u3_L04_challenge','lesson_challenge','K6-1-u3-C19',3,'mc','auto','찬성과 반대를 비슷한 수로 나누는 까닭은 무엇인가요?',ARRAY['K6-1-u3-X09','K6-1-u3-X20','K6-1-u3-X16']::text[],false,'{"seq":7,"concept":"K6-1-u3-C19","difficulty":3,"kind":"mc","stem":"찬성과 반대를 비슷한 수로 나누는 까닭은 무엇인가요?","options":[{"t":"한쪽이 얇으면 토론이 기울어 팽팽하게 겨룰 수 없기 때문에","correct":true},{"t":"많은 쪽이 무조건 이기게 하려고","mis":"K6-1-u3-X09"},{"t":"역할을 먼저 정해야 하기 때문에","mis":"K6-1-u3-X20"},{"t":"판정단이 수를 세어 판정하기 때문에","mis":"K6-1-u3-X16"}],"explanation":["수로 이기는 것이 아니에요.","역할은 생각을 정한 다음이에요.","팽팽해야 토론이 살아나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L04_challenge#8','kor',6,1,'u3','L04','g6_1_kor_u3_L04_challenge','lesson_challenge','K6-1-u3-C25',4,'mc','auto','반론하기에서 말이 겹치고 목소리가 커지기 시작했어요. 토론자가 할 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X26','K6-1-u3-X14','K6-1-u3-X08']::text[],false,'{"seq":8,"concept":"K6-1-u3-C25","difficulty":4,"kind":"mc","stem":"반론하기에서 말이 겹치고 목소리가 커지기 시작했어요. 토론자가 할 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"말차례를 기다렸다가 상대 근거의 가장 약한 한 곳만 침착하게 되받는다","correct":true},{"t":"더 큰 목소리로 한꺼번에 여러 가지를 몰아친다","mis":"K6-1-u3-X26"},{"t":"상대 말투가 거칠다고 맞받아친다","mis":"K6-1-u3-X14"},{"t":"준비한 원고를 처음부터 다시 읽는다","mis":"K6-1-u3-X08"}],"explanation":["몰아치면 서로 들리지 않아요.","말투가 아니라 근거를 겨눠요.","침착하게 한 가지씩 되받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L04_challenge#9','kor',6,1,'u3','L04','g6_1_kor_u3_L04_challenge','lesson_challenge','K6-1-u3-C20',4,'essay','teacher','「우리 반 앉는 곳을 한 달마다 바꾸어야 한다」를 주제로 찬성이나 반대 가운데 하나를 골라 토론 준비표(주장 · 이유 · 근거)를 쓰고, 예상 반론과 답변을 한 가지씩 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u3-C20","difficulty":4,"kind":"essay","stem":"「우리 반 앉는 곳을 한 달마다 바꾸어야 한다」를 주제로 찬성이나 반대 가운데 하나를 골라 토론 준비표(주장 · 이유 · 근거)를 쓰고, 예상 반론과 답변을 한 가지씩 쓰세요.","answer_guide":{"answer":"예: 주장 — 앉는 곳을 한 달마다 바꾸어야 한다. 이유 — 여러 친구와 가까워질 기회가 생기기 때문이다. 근거 — 우리 반 스물여섯 명에게 지난주에 물어보니 열여덟 명이 「옆자리 친구와 더 친해졌다」고 답했다. 예상 반론 — 자주 바꾸면 수업에 집중하기 어렵다. 답변 — 한 달은 새 자리에 익숙해지기에 충분한 시간이고, 설문에서 집중이 어려웠다고 답한 사람은 적었다.","scoring_points":["주장 · 이유 · 근거를 층에 맞게 썼는가","근거에 누구에게 언제 물었는지 밝혔는가","예상 반론에 곧바로 답하는 답변을 썼는가"]},"explanation":["주장 · 이유 · 근거를 차례로 써요.","확인할 수 있는 근거를 써요.","반론에 곧바로 답해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L04_challenge#10','kor',6,1,'u3','L04','g6_1_kor_u3_L04_challenge','lesson_challenge','K6-1-u3-C23',4,'essay','teacher','토론의 네 역할 가운데 두 가지를 골라 각 역할이 할 일과 지켜야 할 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u3-C23","difficulty":4,"kind":"essay","stem":"토론의 네 역할 가운데 두 가지를 골라 각 역할이 할 일과 지켜야 할 점을 쓰세요.","answer_guide":{"answer":"예: 사회자는 토론 주제와 규칙을 알리고 말차례를 이끌며, 토론이 주제에서 벗어나지 않게 한다. 어느 쪽에도 기울지 않아야 한다. 판정단은 판정 기준을 미리 정해 적어 두고, 토론에서 나온 말과 자료로 공정하게 판정한다. 자기 생각과 같은 편이라고 후하게 주지 않아야 한다.","scoring_points":["두 역할을 골랐는가","각 역할이 할 일을 썼는가","각 역할이 지켜야 할 점을 썼는가"]},"explanation":["네 역할 가운데 둘을 골라요.","할 일을 써요.","지켜야 할 점을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L06_basic#1','kor',6,1,'u3','L06','g6_1_kor_u3_L06_basic','lesson_basic','K6-1-u3-C26',1,'match','auto','근거를 따지는 기준과 확인하는 물음을 이으세요.','{}'::text[],false,'{"seq":1,"concept":"K6-1-u3-C26","difficulty":1,"kind":"match","stem":"근거를 따지는 기준과 확인하는 물음을 이으세요.","pairs":[{"l":"주장이나 이유와 가깝게 이어지는가?","r":"관련성"},{"l":"어디서 나온 자료인지 확인할 수 있는가?","r":"신뢰성"},{"l":"언제 누구를 조사했는지 밝혀져 있는가?","r":"충분성"}],"mis":"K6-1-u3-X35","explanation":["가까운지 묻는 물음이 있어요.","어디서 왔는지 묻는 물음이 있어요.","얼마나 자세한지 묻는 물음이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L06_basic#2','kor',6,1,'u3','L06','g6_1_kor_u3_L06_basic','lesson_basic','K6-1-u3-C4',1,'mc','auto','글 ㉮의 주장은 무엇인가요?',ARRAY['K6-1-u3-X04']::text[],false,'{"seq":2,"concept":"K6-1-u3-C4","difficulty":1,"kind":"mc","stem":"글 ㉮의 주장은 무엇인가요?","options":[{"t":"학교 운동장은 저녁에도 마을 사람들에게 열어야 한다","correct":true},{"t":"동네에 마음 놓고 걷거나 뛸 곳이 마땅치 않다","mis":"K6-1-u3-X04"},{"t":"도시 계획과가 시민 사백 명에게 물은 조사","mis":"K6-1-u3-X04"},{"t":"운동장은 저녁에 비어 있다","mis":"K6-1-u3-X04"}],"explanation":["뛸 곳이 마땅치 않다는 것은 이유예요.","조사는 근거예요.","하자고 내세운 생각이 주장이에요."],"asset":{"type":"passage","lines":["학교 운동장은 저녁에도 마을 사람들에게 열어야 합니다.","우리 동네에는 마음 놓고 걷거나 뛸 곳이 마땅치 않기 때문입니다.","지난해 우리 시 도시 계획과가 시민 사백 명에게 물은 조사를 보면,","열 명 가운데 일곱 명이 가까운 곳에 운동할 공간이 부족하다고 답했습니다.","운동장은 낮 동안만 쓰이고 저녁에는 비어 있습니다.","열어 두는 시간을 정하고 관리하는 분을 두면 학교와 마을 모두에 도움이 됩니다."],"title":"글 ㉮ 「학교 운동장은 저녁에도 마을에 열어야 한다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L06_basic#3','kor',6,1,'u3','L06','g6_1_kor_u3_L06_basic','lesson_basic','K6-1-u3-C10',1,'mc','auto','글 ㉯가 든 근거는 무엇인가요?',ARRAY['K6-1-u3-X04','K6-1-u3-X05']::text[],false,'{"seq":3,"concept":"K6-1-u3-C10","difficulty":1,"kind":"mc","stem":"글 ㉯가 든 근거는 무엇인가요?","options":[{"t":"교육청이 올해 낸 학교 시설 개방 점검 자료","correct":true},{"t":"학교는 학생이 안전하게 지내야 하는 곳이다","mis":"K6-1-u3-X04"},{"t":"시에서 걷기 좋은 길을 새로 내는 쪽이 낫다","mis":"K6-1-u3-X04"},{"t":"학교 운동장은 저녁에는 닫아야 한다","mis":"K6-1-u3-X05"}],"explanation":["안전하게 지내야 한다는 것은 이유예요.","길을 내자는 것은 글쓴이의 생각이에요.","어느 기관이 언제 낸 자료인지 밝혀진 것이 근거예요."],"asset":{"type":"passage","lines":["학교 운동장은 저녁에는 닫아야 합니다.","학교는 무엇보다 학생이 안전하게 지내야 하는 곳이기 때문입니다.","저녁에 문을 열어 두면 누가 드나드는지 알기 어렵습니다.","우리 교육청이 올해 낸 학교 시설 개방 점검 자료를 보면,","저녁에 운동장을 연 학교 스물여덟 곳 가운데 열아홉 곳이","쓰레기와 시설 파손 때문에 어려움을 겪는다고 답했습니다.","시에서 걷기 좋은 길을 새로 내는 쪽이 낫습니다."],"title":"글 ㉯ 「학교 운동장은 저녁에는 닫아야 한다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L06_basic#4','kor',6,1,'u3','L06','g6_1_kor_u3_L06_basic','lesson_basic','K6-1-u3-C28',1,'ox','auto','근거 자료를 다섯 개 넘게 내면 그것만으로 충분성을 갖춘 거예요.',ARRAY['K6-1-u3-X30']::text[],false,'{"seq":4,"concept":"K6-1-u3-C28","difficulty":1,"kind":"ox","stem":"근거 자료를 다섯 개 넘게 내면 그것만으로 충분성을 갖춘 거예요.","answer":"X","reason_options":[{"t":"충분하다는 것은 자료 하나가 언제 · 누구를 · 어떻게 조사했는지 밝혀져 있다는 뜻이기 때문에","correct":true},{"t":"자료는 많을수록 무조건 힘이 세기 때문에","mis":"K6-1-u3-X30"}],"mis":"K6-1-u3-X30","explanation":["개수를 늘려도 흐릿하면 그대로예요.","자세한지가 중요해요.","자료 하나라도 자세하면 충분할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L06_basic#5','kor',6,1,'u3','L06','g6_1_kor_u3_L06_basic','lesson_basic','K6-1-u3-C27',2,'mc','auto','근거로 삼기 어려운 것은 어느 것인가요?',ARRAY['K6-1-u3-X35','K6-1-u3-X31']::text[],false,'{"seq":5,"concept":"K6-1-u3-C27","difficulty":2,"kind":"mc","stem":"근거로 삼기 어려운 것은 어느 것인가요?","options":[{"t":"어디에서 봤는지 모르는 동영상에서 들은 이야기","correct":true},{"t":"우리 시가 지난해 시민 사백 명에게 물은 조사","mis":"K6-1-u3-X35"},{"t":"교육청이 올해 낸 학교 시설 점검 자료","mis":"K6-1-u3-X35"},{"t":"모둠이 한 시간 동안 운동장 출입을 센 기록","mis":"K6-1-u3-X31"}],"explanation":["시의 조사는 출처와 때가 밝혀져 있어요.","교육청 자료도 확인할 수 있어요.","누가 만든 무엇인지 모르면 힘을 내지 못해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L06_basic#6','kor',6,1,'u3','L06','g6_1_kor_u3_L06_basic','lesson_basic','K6-1-u3-C29',2,'mc','auto','하윤이와 도겸이의 경험 가운데 근거로 쓰기에 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X32','K6-1-u3-X31']::text[],false,'{"seq":6,"concept":"K6-1-u3-C29","difficulty":2,"kind":"mc","stem":"하윤이와 도겸이의 경험 가운데 근거로 쓰기에 알맞은 것은 어느 것인가요?","options":[{"t":"도겸 — 정한 시간 동안 출입을 세어 정리했기 때문에","correct":true},{"t":"하윤 — 직접 겪은 일이라 더 생생하기 때문에","mis":"K6-1-u3-X32"},{"t":"둘 다 아니다 — 경험은 근거가 될 수 없기 때문에","mis":"K6-1-u3-X31"},{"t":"둘 다 알맞다 — 경험이면 무엇이든 되기 때문에","mis":"K6-1-u3-X32"}],"explanation":["지갑을 주운 일은 드문 일이에요.","경험도 근거가 될 수 있어요.","세거나 재어 정리해야 해요."],"asset":{"type":"speech","turns":[{"who":"하윤","text":"저는 저녁 운동장에서 지갑을 주운 적이 있습니다. 그러니 저녁 운동장은 위험합니다."},{"who":"도겸","text":"저희 모둠이 저녁 여섯 시부터 한 시간 동안 운동장 출입을 세었더니 마흔두 명이었습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L06_basic#7','kor',6,1,'u3','L06','g6_1_kor_u3_L06_basic','lesson_basic','K6-1-u3-C30',2,'mc','auto','믿을 만한 자료를 고르는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X33','K6-1-u3-X27']::text[],false,'{"seq":7,"concept":"K6-1-u3-C30","difficulty":2,"kind":"mc","stem":"믿을 만한 자료를 고르는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"공신력 있는 곳에서 가장 최근에 낸, 주제와 직접 이어지는 자료를 고른다","correct":true},{"t":"무언가를 팔려는 광고 글도 숫자가 있으면 쓴다","mis":"K6-1-u3-X33"},{"t":"오래된 자료도 숫자가 크면 쓴다","mis":"K6-1-u3-X33"},{"t":"주제와 비슷해 보이는 다른 주제의 자료를 쓴다","mis":"K6-1-u3-X27"}],"explanation":["광고에 가까운 글은 피해요.","오래된 수치는 지금과 다를 수 있어요.","주제와 직접 이어져야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L06_basic#8','kor',6,1,'u3','L06','g6_1_kor_u3_L06_basic','lesson_basic','K6-1-u3-C31',2,'mc','auto','근거를 말할 때 먼저 밝히면 좋은 것은 어느 것인가요?',ARRAY['K6-1-u3-X34','K6-1-u3-X30']::text[],false,'{"seq":8,"concept":"K6-1-u3-C31","difficulty":2,"kind":"mc","stem":"근거를 말할 때 먼저 밝히면 좋은 것은 어느 것인가요?","options":[{"t":"누가 언제 낸 자료인지","correct":true},{"t":"「어디서 봤는데」라는 말","mis":"K6-1-u3-X34"},{"t":"자료의 세부 사항 전부","mis":"K6-1-u3-X34"},{"t":"자료를 찾는 데 걸린 시간","mis":"K6-1-u3-X30"}],"explanation":["「어디서 봤는데」는 자료를 흔들어요.","세부 사항은 추려서 전해요.","출처를 먼저 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L06_basic#9','kor',6,1,'u3','L06','g6_1_kor_u3_L06_basic','lesson_basic','K6-1-u3-C29',2,'ox','auto','내가 겪은 일은 어떤 경우에도 근거가 될 수 없어요.',ARRAY['K6-1-u3-X31']::text[],false,'{"seq":9,"concept":"K6-1-u3-C29","difficulty":2,"kind":"ox","stem":"내가 겪은 일은 어떤 경우에도 근거가 될 수 없어요.","answer":"X","reason_options":[{"t":"여러 사람이 그럴 만하다고 여길 일을 세거나 재어 정리하면 근거가 될 수 있기 때문에","correct":true},{"t":"경험은 모두 나에게만 일어난 일이기 때문에","mis":"K6-1-u3-X31"}],"mis":"K6-1-u3-X31","explanation":["드문 일은 근거가 되기 어려워요.","그러나 모든 경험이 그런 건 아니에요.","세거나 재어 정리하면 근거가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L06_basic#10','kor',6,1,'u3','L06','g6_1_kor_u3_L06_basic','lesson_basic','K6-1-u3-C26',3,'mc','auto','글 ㉮의 근거를 세 물음으로 따져 본 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X35','K6-1-u3-X30','K6-1-u3-X27']::text[],false,'{"seq":10,"concept":"K6-1-u3-C26","difficulty":3,"kind":"mc","stem":"글 ㉮의 근거를 세 물음으로 따져 본 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"뛸 곳이 마땅치 않다는 이유와 이어지고, 도시 계획과라는 출처와 지난해 · 시민 사백 명이라는 조사 대상이 밝혀져 있다","correct":true},{"t":"숫자가 나왔으니 따져 볼 필요 없이 타당하다","mis":"K6-1-u3-X35"},{"t":"조사한 사람이 사백 명뿐이라 근거가 될 수 없다","mis":"K6-1-u3-X30"},{"t":"운동장 이야기라서 이유와 관련이 없다","mis":"K6-1-u3-X27"}],"explanation":["숫자만 보고 넘어가지 않아요.","사람 수만으로 따지지 않아요.","세 물음을 한 번씩 던져 봐요."],"asset":{"type":"passage","lines":["학교 운동장은 저녁에도 마을 사람들에게 열어야 합니다.","우리 동네에는 마음 놓고 걷거나 뛸 곳이 마땅치 않기 때문입니다.","지난해 우리 시 도시 계획과가 시민 사백 명에게 물은 조사를 보면,","열 명 가운데 일곱 명이 가까운 곳에 운동할 공간이 부족하다고 답했습니다.","운동장은 낮 동안만 쓰이고 저녁에는 비어 있습니다.","열어 두는 시간을 정하고 관리하는 분을 두면 학교와 마을 모두에 도움이 됩니다."],"title":"글 ㉮ 「학교 운동장은 저녁에도 마을에 열어야 한다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L06_challenge#1','kor',6,1,'u3','L06','g6_1_kor_u3_L06_challenge','lesson_challenge','K6-1-u3-C27',2,'mc','auto','「많은 사람이 그렇게 답했습니다.」라는 근거가 힘을 내지 못하는 까닭은 무엇인가요?',ARRAY['K6-1-u3-X31','K6-1-u3-X30','K6-1-u3-X27']::text[],false,'{"seq":1,"concept":"K6-1-u3-C27","difficulty":2,"kind":"mc","stem":"「많은 사람이 그렇게 답했습니다.」라는 근거가 힘을 내지 못하는 까닭은 무엇인가요?","options":[{"t":"언제 몇 명에게 물었는지 없기 때문에","correct":true},{"t":"사람에게 물은 자료는 근거가 될 수 없기 때문에","mis":"K6-1-u3-X31"},{"t":"많은 사람이 답했으니 오히려 충분하기 때문에","mis":"K6-1-u3-X30"},{"t":"주장과 반대되는 말이기 때문에","mis":"K6-1-u3-X27"}],"explanation":["설문도 근거가 될 수 있어요.","「많은」은 흐릿한 말이에요.","언제 · 누구를이 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L06_challenge#2','kor',6,1,'u3','L06','g6_1_kor_u3_L06_challenge','lesson_challenge','K6-1-u3-C26',2,'ox','auto','세 물음 가운데 하나만 걸려도 근거는 흔들릴 수 있어요.',ARRAY['K6-1-u3-X35']::text[],false,'{"seq":2,"concept":"K6-1-u3-C26","difficulty":2,"kind":"ox","stem":"세 물음 가운데 하나만 걸려도 근거는 흔들릴 수 있어요.","answer":"O","reason_options":[{"t":"이어지지 않거나 출처를 모르거나 흐릿하면 어느 쪽이든 이유를 제대로 뒷받침하지 못하기 때문에","correct":true},{"t":"세 물음 가운데 하나만 통과하면 충분하기 때문에","mis":"K6-1-u3-X35"}],"mis":"K6-1-u3-X35","explanation":["세 물음을 한 번씩 던져요.","하나만 걸려도 흔들려요.","전체적으로 타당한지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L06_challenge#3','kor',6,1,'u3','L06','g6_1_kor_u3_L06_challenge','lesson_challenge','K6-1-u3-C27',3,'error','auto','운동장을 저녁에 여는 문제로 근거를 냈어요. 근거로 알맞지 않은 것을 낸 친구는 누구인가요?',ARRAY['K6-1-u3-X27','K6-1-u3-X28','K6-1-u3-X29']::text[],false,'{"seq":3,"concept":"K6-1-u3-C27","difficulty":3,"kind":"error","stem":"운동장을 저녁에 여는 문제로 근거를 냈어요. 근거로 알맞지 않은 것을 낸 친구는 누구인가요?","options":[{"t":"수아 — 「운동장을 열면 학교가 유명해집니다.」","correct":true,"mis_target":"K6-1-u3-X27"},{"t":"민재 — 「교육청이 올해 스물여덟 곳을 점검한 자료입니다.」","mis":"K6-1-u3-X28"},{"t":"해솔 — 「우리 시가 지난해 시민 사백 명에게 물은 조사입니다.」","mis":"K6-1-u3-X29"}],"explanation":["민재는 출처와 때를 밝혔어요.","해솔도 누구를 언제 조사했는지 밝혔어요.","수아의 말은 이유와 이어지지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L06_challenge#4','kor',6,1,'u3','L06','g6_1_kor_u3_L06_challenge','lesson_challenge','K6-1-u3-C28',3,'mc','auto','「열 명 가운데 일곱 명」보다 「지난해 우리 시가 시민 사백 명에게 물어 열 명 가운데 일곱 명」이 더 센 까닭은 무엇인가요?',ARRAY['K6-1-u3-X30','K6-1-u3-X34']::text[],false,'{"seq":4,"concept":"K6-1-u3-C28","difficulty":3,"kind":"mc","stem":"「열 명 가운데 일곱 명」보다 「지난해 우리 시가 시민 사백 명에게 물어 열 명 가운데 일곱 명」이 더 센 까닭은 무엇인가요?","options":[{"t":"언제 · 누구를 조사했는지가 밝혀져 있어 더 구체적이기 때문에","correct":true},{"t":"글자 수가 더 많기 때문에","mis":"K6-1-u3-X30"},{"t":"숫자가 하나 더 들어 있기 때문에","mis":"K6-1-u3-X30"},{"t":"듣기에 더 어려워 보이기 때문에","mis":"K6-1-u3-X34"}],"explanation":["길이로 세지는 것이 아니에요.","숫자 개수도 아니에요.","언제 · 누구를이 밝혀져 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L06_challenge#5','kor',6,1,'u3','L06','g6_1_kor_u3_L06_challenge','lesson_challenge','K6-1-u3-C30',3,'mc','auto','신문 기사를 근거로 쓰려고 해요. 가장 먼저 살펴볼 것은 어느 것인가요?',ARRAY['K6-1-u3-X30','K6-1-u3-X35','K6-1-u3-X33']::text[],false,'{"seq":5,"concept":"K6-1-u3-C30","difficulty":3,"kind":"mc","stem":"신문 기사를 근거로 쓰려고 해요. 가장 먼저 살펴볼 것은 어느 것인가요?","options":[{"t":"광고에 가까운 글인지, 쓴 사람의 이름과 낸 때가 적혀 있는지","correct":true},{"t":"기사가 길고 어려운지","mis":"K6-1-u3-X30"},{"t":"사진이 많이 들어 있는지","mis":"K6-1-u3-X35"},{"t":"내 주장과 같은 말을 하는지만","mis":"K6-1-u3-X33"}],"explanation":["길고 어렵다고 믿을 만한 것은 아니에요.","사진 수로 판단하지 않아요.","광고인지 · 누가 언제 썼는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L06_challenge#6','kor',6,1,'u3','L06','g6_1_kor_u3_L06_challenge','lesson_challenge','K6-1-u3-C31',3,'mc','auto','근거를 내놓는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X34','K6-1-u3-X28']::text[],false,'{"seq":6,"concept":"K6-1-u3-C31","difficulty":3,"kind":"mc","stem":"근거를 내놓는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"중요한 내용만 추리고, 필요하면 표나 그림으로 보이며, 누가 언제 낸 자료인지 먼저 밝힌다","correct":true},{"t":"자료의 세부 사항을 처음부터 끝까지 모두 읽는다","mis":"K6-1-u3-X34"},{"t":"「어디서 봤는데」로 시작해 친근하게 말한다","mis":"K6-1-u3-X34"},{"t":"출처는 상대가 물을 때만 말한다","mis":"K6-1-u3-X28"}],"explanation":["모두 읽으면 중심이 흐려져요.","「어디서 봤는데」는 자료를 흔들어요.","출처를 먼저 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L06_challenge#7','kor',6,1,'u3','L06','g6_1_kor_u3_L06_challenge','lesson_challenge','K6-1-u3-C26',3,'mc','auto','글 ㉯의 근거를 따져 본 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X35','K6-1-u3-X30','K6-1-u3-X31']::text[],false,'{"seq":7,"concept":"K6-1-u3-C26","difficulty":3,"kind":"mc","stem":"글 ㉯의 근거를 따져 본 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"교육청 · 올해 · 스물여덟 곳이 밝혀져 있고, 학생이 안전하게 지내야 한다는 이유와 이어진다","correct":true},{"t":"학교 이야기라서 따져 볼 것도 없이 타당하다","mis":"K6-1-u3-X35"},{"t":"자료가 하나뿐이라 충분하지 않다","mis":"K6-1-u3-X30"},{"t":"교육청 자료는 사람이 만든 것이라 믿을 수 없다","mis":"K6-1-u3-X31"}],"explanation":["따져 보지 않고 넘어가지 않아요.","하나라도 자세하면 충분할 수 있어요.","세 물음으로 보면 타당해요."],"asset":{"type":"passage","lines":["학교 운동장은 저녁에는 닫아야 합니다.","학교는 무엇보다 학생이 안전하게 지내야 하는 곳이기 때문입니다.","저녁에 문을 열어 두면 누가 드나드는지 알기 어렵습니다.","우리 교육청이 올해 낸 학교 시설 개방 점검 자료를 보면,","저녁에 운동장을 연 학교 스물여덟 곳 가운데 열아홉 곳이","쓰레기와 시설 파손 때문에 어려움을 겪는다고 답했습니다.","시에서 걷기 좋은 길을 새로 내는 쪽이 낫습니다."],"title":"글 ㉯ 「학교 운동장은 저녁에는 닫아야 한다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L06_challenge#8','kor',6,1,'u3','L06','g6_1_kor_u3_L06_challenge','lesson_challenge','K6-1-u3-C29',4,'mc','auto','「저녁 운동장은 관리가 어렵다」는 이유를 경험으로 뒷받침하려고 해요. 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X04','K6-1-u3-X32','K6-1-u3-X28']::text[],false,'{"seq":8,"concept":"K6-1-u3-C29","difficulty":4,"kind":"mc","stem":"「저녁 운동장은 관리가 어렵다」는 이유를 경험으로 뒷받침하려고 해요. 가장 알맞은 것은 어느 것인가요?","options":[{"t":"모둠이 일주일 동안 저녁마다 운동장에 남은 쓰레기 수를 세어 정리한 기록","correct":true},{"t":"저녁 운동장이 무서웠던 내 느낌","mis":"K6-1-u3-X04"},{"t":"어느 날 운동장에서 넘어진 내 일 하나","mis":"K6-1-u3-X32"},{"t":"어떤 동영상에서 본 이야기","mis":"K6-1-u3-X28"}],"explanation":["느낌은 근거가 아니에요.","드문 일 하나는 힘이 약해요.","세어서 정리한 경험은 근거가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L06_challenge#9','kor',6,1,'u3','L06','g6_1_kor_u3_L06_challenge','lesson_challenge','K6-1-u3-C26',4,'essay','teacher','글 ㉯의 근거를 세 물음으로 하나씩 따져 보고, 이 근거를 더 타당하게 만들려면 무엇을 더 밝히면 좋을지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u3-C26","difficulty":4,"kind":"essay","stem":"글 ㉯의 근거를 세 물음으로 하나씩 따져 보고, 이 근거를 더 타당하게 만들려면 무엇을 더 밝히면 좋을지 쓰세요.","answer_guide":{"answer":"예: 이 자료는 쓰레기와 시설 파손 때문에 어려움을 겪는다는 내용이라 학생이 안전하게 지내야 한다는 이유와 이어진다. 교육청이 낸 자료라 출처가 분명하다. 올해, 운동장을 연 학교 스물여덟 곳을 점검했다고 밝혀 구체적이다. 더 타당하게 하려면 어떤 어려움이 몇 곳에서 있었는지, 그 학교들이 우리 학교와 비슷한 곳인지를 더 밝히면 좋겠다.","scoring_points":["관련성 · 신뢰성 · 충분성을 하나씩 따졌는가","글 ㉯의 내용으로 근거를 들어 따졌는가","더 밝힐 점을 알맞게 썼는가"]},"explanation":["세 물음을 한 번씩 던져요.","글의 내용으로 따져요.","더 밝힐 점을 찾아요."],"asset":{"type":"passage","lines":["학교 운동장은 저녁에는 닫아야 합니다.","학교는 무엇보다 학생이 안전하게 지내야 하는 곳이기 때문입니다.","저녁에 문을 열어 두면 누가 드나드는지 알기 어렵습니다.","우리 교육청이 올해 낸 학교 시설 개방 점검 자료를 보면,","저녁에 운동장을 연 학교 스물여덟 곳 가운데 열아홉 곳이","쓰레기와 시설 파손 때문에 어려움을 겪는다고 답했습니다.","시에서 걷기 좋은 길을 새로 내는 쪽이 낫습니다."],"title":"글 ㉯ 「학교 운동장은 저녁에는 닫아야 한다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L06_challenge#10','kor',6,1,'u3','L06','g6_1_kor_u3_L06_challenge','lesson_challenge','K6-1-u3-C28',4,'essay','teacher','「충분성은 자료가 많다는 뜻이 아니다」라는 말을 예를 들어 설명하고, 내가 겪은 일을 근거로 쓰려면 어떻게 해야 하는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u3-C28","difficulty":4,"kind":"essay","stem":"「충분성은 자료가 많다는 뜻이 아니다」라는 말을 예를 들어 설명하고, 내가 겪은 일을 근거로 쓰려면 어떻게 해야 하는지 쓰세요.","answer_guide":{"answer":"예: 「많은 사람이 그렇다고 했다」는 자료를 다섯 개 모아도 언제 누구에게 물었는지 없으면 여전히 흐릿하다. 반대로 「지난해 우리 시가 시민 사백 명에게 물은 조사」처럼 하나라도 언제 · 누구를 · 어떻게 조사했는지 밝혀져 있으면 충분할 수 있다. 내가 겪은 일을 근거로 쓰려면 나에게만 일어난 드문 일이 아니라 여러 사람이 그럴 만하다고 여길 일을 골라, 느낌으로 두지 말고 세거나 재어서 정리해야 한다.","scoring_points":["충분성이 개수가 아니라 구체성임을 예와 함께 썼는가","드문 경험은 근거가 되기 어렵다는 점을 썼는가","세거나 재어 정리하는 방법을 썼는가"]},"explanation":["흐릿한 자료 여러 개와 자세한 하나를 견줘요.","어떤 경험이 근거가 되기 어려운지 써요.","세거나 재는 방법을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L08_basic#1','kor',6,1,'u3','L08','g6_1_kor_u3_L08_basic','lesson_basic','K6-1-u3-C32',1,'mc','auto','사회 문제 토론 주제로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X01']::text[],false,'{"seq":1,"concept":"K6-1-u3-C32","difficulty":1,"kind":"mc","stem":"사회 문제 토론 주제로 알맞은 것은 어느 것인가요?","options":[{"t":"공공 도서관을 밤 열 시까지 열어야 하는가","correct":true},{"t":"우리 시의 인구가 몇 명인가","mis":"K6-1-u3-X01"},{"t":"신호등이 빨간불일 때 건너면 안 되는가","mis":"K6-1-u3-X01"},{"t":"어제 비가 몇 시에 왔는가","mis":"K6-1-u3-X01"}],"explanation":["인구는 찾아보면 확인돼요.","빨간불에 건너지 않는 것은 정해진 규칙이에요.","찬반이 갈리고 무엇을 하자고 정하는 문제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L08_basic#2','kor',6,1,'u3','L08','g6_1_kor_u3_L08_basic','lesson_basic','K6-1-u3-C27',1,'mc','auto','이 글의 근거에서 가장 큰 문제는 무엇인가요?',ARRAY['K6-1-u3-X30','K6-1-u3-X15','K6-1-u3-X35']::text[],false,'{"seq":2,"concept":"K6-1-u3-C27","difficulty":1,"kind":"mc","stem":"이 글의 근거에서 가장 큰 문제는 무엇인가요?","options":[{"t":"어디서 나온 자료인지 하나도 확인할 수 없다","correct":true},{"t":"글이 너무 짧다","mis":"K6-1-u3-X30"},{"t":"주장을 맨 앞과 맨 뒤에 두 번 썼다","mis":"K6-1-u3-X15"},{"t":"이모의 말에 높임말을 썼다","mis":"K6-1-u3-X35"}],"explanation":["길이는 문제가 아니에요.","주장을 다시 쓴 것은 큰 문제가 아니에요.","누리집 · 많은 사람 · 이모의 말 모두 확인할 수 없어요."],"asset":{"type":"passage","lines":["학교 주변 도로의 제한 속도를 더 낮춰서는 안 된다고 생각합니다.","어떤 누리집에서 봤는데, 속도를 낮추면 오히려 사고가 는다고 합니다.","많은 사람이 그렇게 말합니다.","게다가 저희 이모께서 운전할 때 답답하다고 하셨습니다.","따라서 제한 속도를 낮출 필요는 없습니다."],"title":"어느 학생이 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L08_basic#3','kor',6,1,'u3','L08','g6_1_kor_u3_L08_basic','lesson_basic','K6-1-u3-C33',1,'ox','auto','판정단은 토론에서 실제로 나온 말과 자료만으로 판정해요.',ARRAY['K6-1-u3-X24']::text[],false,'{"seq":3,"concept":"K6-1-u3-C33","difficulty":1,"kind":"ox","stem":"판정단은 토론에서 실제로 나온 말과 자료만으로 판정해요.","answer":"O","reason_options":[{"t":"미리 정한 기준으로 공정하게 판정해야 하기 때문에","correct":true},{"t":"평소 자기 생각을 넣어야 판정이 정확해지기 때문에","mis":"K6-1-u3-X24"}],"mis":"K6-1-u3-X24","explanation":["평소 생각은 판정과 관계없어요.","미리 정한 기준으로 봐요.","나온 말과 자료만으로 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L08_basic#4','kor',6,1,'u3','L08','g6_1_kor_u3_L08_basic','lesson_basic','K6-1-u3-C34',1,'mc','auto','토론 중에 메모해 두면 좋은 것은 어느 것인가요?',ARRAY['K6-1-u3-X38','K6-1-u3-X12']::text[],false,'{"seq":4,"concept":"K6-1-u3-C34","difficulty":1,"kind":"mc","stem":"토론 중에 메모해 두면 좋은 것은 어느 것인가요?","options":[{"t":"상대가 근거로 든 자료의 출처","correct":true},{"t":"상대의 목소리 크기와 말투","mis":"K6-1-u3-X38"},{"t":"상대가 입은 옷차림","mis":"K6-1-u3-X38"},{"t":"상대 발언 전체를 한 글자도 빠짐없이","mis":"K6-1-u3-X12"}],"explanation":["말투는 되받을 거리가 아니에요.","옷차림도 아니에요.","되받을 거리를 핵심만 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L08_basic#5','kor',6,1,'u3','L08','g6_1_kor_u3_L08_basic','lesson_basic','K6-1-u3-C35',2,'mc','auto','판정 기준 가운데 「반론하기」에서 보는 것은 어느 것인가요?',ARRAY['K6-1-u3-X06','K6-1-u3-X16','K6-1-u3-X08']::text[],false,'{"seq":5,"concept":"K6-1-u3-C35","difficulty":2,"kind":"mc","stem":"판정 기준 가운데 「반론하기」에서 보는 것은 어느 것인가요?","options":[{"t":"상대 이유나 근거의 문제를 찾아 되받았는가, 반론에 알맞게 답했는가","correct":true},{"t":"주장과 이유를 처음으로 냈는가","mis":"K6-1-u3-X06"},{"t":"누구의 목소리가 더 컸는가","mis":"K6-1-u3-X16"},{"t":"준비한 원고를 끝까지 읽었는가","mis":"K6-1-u3-X08"}],"explanation":["처음 내는 것은 주장 펼치기예요.","목소리는 기준이 아니에요.","되받고 답한 것을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L08_basic#6','kor',6,1,'u3','L08','g6_1_kor_u3_L08_basic','lesson_basic','K6-1-u3-C32',2,'mc','auto','사회 문제를 주제로 정한 뒤 먼저 할 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X36','K6-1-u3-X16','K6-1-u3-X20']::text[],false,'{"seq":6,"concept":"K6-1-u3-C32","difficulty":2,"kind":"mc","stem":"사회 문제를 주제로 정한 뒤 먼저 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"지금 제한 속도가 얼마인지, 사고가 몇 건이었는지처럼 알려진 사실부터 함께 맞춰 본다","correct":true},{"t":"아는 것이 적어도 곧바로 토론을 시작한다","mis":"K6-1-u3-X36"},{"t":"판정 결과부터 정해 둔다","mis":"K6-1-u3-X16"},{"t":"주제를 정하자마자 역할부터 나눈다","mis":"K6-1-u3-X20"}],"explanation":["아는 것이 적으면 겉돌기 쉬워요.","판정은 토론 뒤에 해요.","사실부터 함께 맞춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L08_basic#7','kor',6,1,'u3','L08','g6_1_kor_u3_L08_basic','lesson_basic','K6-1-u3-C22',2,'mc','auto','제한 속도 준비표에서 예상 반론에 대한 답변이 알맞은 까닭은 무엇인가요?',ARRAY['K6-1-u3-X13','K6-1-u3-X11','K6-1-u3-X14']::text[],false,'{"seq":7,"concept":"K6-1-u3-C22","difficulty":2,"kind":"mc","stem":"제한 속도 준비표에서 예상 반론에 대한 답변이 알맞은 까닭은 무엇인가요?","options":[{"t":"「속도 때문인지 알 수 없다」는 물음에 공사를 하지 않은 구역 자료로 곧바로 답했기 때문에","correct":true},{"t":"「어쨌든 속도를 낮추면 안전합니다」라고 되풀이했기 때문에","mis":"K6-1-u3-X13"},{"t":"자전거 사고 이야기로 넘어갔기 때문에","mis":"K6-1-u3-X11"},{"t":"상대가 준비를 안 했다고 짚었기 때문에","mis":"K6-1-u3-X14"}],"explanation":["되풀이는 답변이 아니에요.","다른 이야기로 넘어가지 않았어요.","물은 그 지점을 자료로 되받았어요."],"asset":{"type":"passage","lines":["주장 — 학교 주변 도로의 제한 속도를 더 낮춰야 합니다.","이유 — 속도가 낮을수록 멈추는 데 걸리는 거리가 짧아지기 때문입니다.","근거 — 우리 시 교통 안전과가 지난해 낸 어린이 보호 구역 사고 자료.","속도를 낮춘 구역에서 사고 건수가 줄었습니다.","예상 반론 — 줄어든 것이 속도 때문인지 공사 때문인지 알 수 없습니다.","우리 측 답변 — 같은 자료에 공사를 하지 않은 구역이 따로 나와 있고,","그 구역에서도 사고가 줄었습니다."],"title":"찬성 측 토론 준비표 (사회 문제)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L08_basic#8','kor',6,1,'u3','L08','g6_1_kor_u3_L08_basic','lesson_basic','K6-1-u3-C34',2,'ox','auto','반론하기에서는 상대 말을 듣기보다 준비한 원고를 그대로 다시 읽는 것이 안전해요.',ARRAY['K6-1-u3-X08']::text[],false,'{"seq":8,"concept":"K6-1-u3-C34","difficulty":2,"kind":"ox","stem":"반론하기에서는 상대 말을 듣기보다 준비한 원고를 그대로 다시 읽는 것이 안전해요.","answer":"X","reason_options":[{"t":"반론은 그 순간에 들은 것으로만 할 수 있어 메모하며 들어야 하기 때문에","correct":true},{"t":"원고를 읽으면 실수가 없기 때문에","mis":"K6-1-u3-X08"}],"mis":"K6-1-u3-X08","explanation":["원고를 읽으면 혼잣말이 돼요.","반론은 들은 것으로 해요.","메모하며 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L08_basic#9','kor',6,1,'u3','L08','g6_1_kor_u3_L08_basic','lesson_basic','K6-1-u3-C36',2,'mc','auto','판정이 나온 뒤에 할 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X40','K6-1-u3-X18','K6-1-u3-X39']::text[],false,'{"seq":9,"concept":"K6-1-u3-C36","difficulty":2,"kind":"mc","stem":"판정이 나온 뒤에 할 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「저 근거는 나도 다시 찾아봐야겠다.」","correct":true},{"t":"「우리가 이겼다. 더 할 말 없다.」","mis":"K6-1-u3-X40"},{"t":"「판정이 이상하다.」","mis":"K6-1-u3-X18"},{"t":"「생각이 바뀌면 지는 거야.」","mis":"K6-1-u3-X39"}],"explanation":["승패만 남기면 아쉬워요.","판정에는 승복해요.","생각을 남기는 마무리가 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L08_basic#10','kor',6,1,'u3','L08','g6_1_kor_u3_L08_basic','lesson_basic','K6-1-u3-C23',3,'mc','auto','청중이 많을 때 청중에게도 할 일을 주는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X37','K6-1-u3-X25']::text[],false,'{"seq":10,"concept":"K6-1-u3-C23","difficulty":3,"kind":"mc","stem":"청중이 많을 때 청중에게도 할 일을 주는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"청중이 메모하고 인상 깊은 근거를 말해야 토론이 살아나기 때문에","correct":true},{"t":"청중은 할 일이 없어 조용히 앉아 있으면 되기 때문에","mis":"K6-1-u3-X37"},{"t":"청중이 판정을 대신해야 하기 때문에","mis":"K6-1-u3-X25"},{"t":"청중이 토론자 대신 반론해야 하기 때문에","mis":"K6-1-u3-X25"}],"explanation":["청중에게도 할 일이 있어요.","판정은 판정단이 해요.","메모하고 인상 깊은 근거를 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L08_challenge#1','kor',6,1,'u3','L08','g6_1_kor_u3_L08_challenge','lesson_challenge','K6-1-u3-C33',2,'mc','auto','판정단이 판정의 바탕으로 삼을 것은 어느 것인가요?',ARRAY['K6-1-u3-X24','K6-1-u3-X16']::text[],false,'{"seq":1,"concept":"K6-1-u3-C33","difficulty":2,"kind":"mc","stem":"판정단이 판정의 바탕으로 삼을 것은 어느 것인가요?","options":[{"t":"미리 정한 기준으로, 토론에서 실제로 나온 말과 자료만 본다","correct":true},{"t":"평소 자기 생각과 같은 편에 후하게 준다","mis":"K6-1-u3-X24"},{"t":"친한 친구가 있는 편에 더 준다","mis":"K6-1-u3-X24"},{"t":"목소리가 큰 편을 고른다","mis":"K6-1-u3-X16"}],"explanation":["같은 편이라고 후하게 주지 않아요.","친한 사이는 판정과 관계없어요.","기준과 나온 내용만 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L08_challenge#2','kor',6,1,'u3','L08','g6_1_kor_u3_L08_challenge','lesson_challenge','K6-1-u3-C36',2,'ox','auto','토론이 끝난 뒤 생각이 조금 바뀌는 것은 부끄러운 일이에요.',ARRAY['K6-1-u3-X39']::text[],false,'{"seq":2,"concept":"K6-1-u3-C36","difficulty":2,"kind":"ox","stem":"토론이 끝난 뒤 생각이 조금 바뀌는 것은 부끄러운 일이에요.","answer":"X","reason_options":[{"t":"상대의 근거에서 배운 것이 있다는 뜻으로 토론을 한 보람이기 때문에","correct":true},{"t":"생각이 바뀌면 토론에서 진 것이기 때문에","mis":"K6-1-u3-X39"}],"mis":"K6-1-u3-X39","explanation":["판정에는 승복해요.","생각이 바뀌는 것은 진 것이 아니에요.","그것이 토론을 한 보람이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L08_challenge#3','kor',6,1,'u3','L08','g6_1_kor_u3_L08_challenge','lesson_challenge','K6-1-u3-C34',3,'mc','auto','메모할 때 발언을 그대로 옮기지 않고 핵심만 짧게 적는 까닭은 무엇인가요?',ARRAY['K6-1-u3-X12','K6-1-u3-X08','K6-1-u3-X38']::text[],false,'{"seq":3,"concept":"K6-1-u3-C34","difficulty":3,"kind":"mc","stem":"메모할 때 발언을 그대로 옮기지 않고 핵심만 짧게 적는 까닭은 무엇인가요?","options":[{"t":"다음 말을 놓치지 않고 되받을 거리를 찾기 위해서","correct":true},{"t":"발언은 모두 옮겨야 정확하지만 시간이 없어서","mis":"K6-1-u3-X12"},{"t":"상대 말은 어차피 중요하지 않기 때문에","mis":"K6-1-u3-X08"},{"t":"글씨를 예쁘게 쓰기 위해서","mis":"K6-1-u3-X38"}],"explanation":["다 옮기는 것이 좋은 메모가 아니에요.","상대 말을 들어야 되받아요.","핵심만 적어야 다음 말을 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L08_challenge#4','kor',6,1,'u3','L08','g6_1_kor_u3_L08_challenge','lesson_challenge','K6-1-u3-C27',3,'mc','auto','이 글을 더 타당하게 고치는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X29','K6-1-u3-X30','K6-1-u3-X15']::text[],false,'{"seq":4,"concept":"K6-1-u3-C27","difficulty":3,"kind":"mc","stem":"이 글을 더 타당하게 고치는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"어느 기관이 언제 낸 사고 자료인지 밝히고, 이모의 말 대신 확인할 수 있는 자료를 든다","correct":true},{"t":"「많은 사람」을 「아주 많은 사람」으로 바꾼다","mis":"K6-1-u3-X29"},{"t":"누리집 이야기를 한 번 더 쓴다","mis":"K6-1-u3-X30"},{"t":"주장을 한 번 더 써서 힘준다","mis":"K6-1-u3-X15"}],"explanation":["「아주 많은」도 흐릿해요.","같은 이야기를 늘려도 그대로예요.","출처가 분명한 자료로 바꿔요."],"asset":{"type":"passage","lines":["학교 주변 도로의 제한 속도를 더 낮춰서는 안 된다고 생각합니다.","어떤 누리집에서 봤는데, 속도를 낮추면 오히려 사고가 는다고 합니다.","많은 사람이 그렇게 말합니다.","게다가 저희 이모께서 운전할 때 답답하다고 하셨습니다.","따라서 제한 속도를 낮출 필요는 없습니다."],"title":"어느 학생이 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L08_challenge#5','kor',6,1,'u3','L08','g6_1_kor_u3_L08_challenge','lesson_challenge','K6-1-u3-C35',3,'error','auto','판정단이 기준을 말했어요. 알맞지 않은 기준을 말한 친구는 누구인가요?',ARRAY['K6-1-u3-X16','K6-1-u3-X35','K6-1-u3-X17']::text[],false,'{"seq":5,"concept":"K6-1-u3-C35","difficulty":3,"kind":"error","stem":"판정단이 기준을 말했어요. 알맞지 않은 기준을 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「더 오래 말한 쪽에 점수를 주겠습니다.」","correct":true,"mis_target":"K6-1-u3-X16"},{"t":"서하 — 「이유와 근거가 타당하고 믿을 만한가를 보겠습니다.」","mis":"K6-1-u3-X35"},{"t":"지후 — 「규칙을 지키고 예의 바르게 참여했는가를 보겠습니다.」","mis":"K6-1-u3-X17"}],"explanation":["서하는 주장 펼치기의 기준을 말했어요.","지후는 태도의 기준을 말했어요.","말한 길이는 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L08_challenge#6','kor',6,1,'u3','L08','g6_1_kor_u3_L08_challenge','lesson_challenge','K6-1-u3-C32',3,'mc','auto','사회 문제 주제를 찾을 때 던지면 좋은 물음은 어느 것인가요?',ARRAY['K6-1-u3-X01','K6-1-u3-X19','K6-1-u3-X20']::text[],false,'{"seq":6,"concept":"K6-1-u3-C32","difficulty":3,"kind":"mc","stem":"사회 문제 주제를 찾을 때 던지면 좋은 물음은 어느 것인가요?","options":[{"t":"「늘 그래 왔던 일인데 꼭 그래야 할까?」, 「많은 친구가 관심 있어 할까?」","correct":true},{"t":"「자료를 찾으면 곧바로 답이 나올까?」","mis":"K6-1-u3-X01"},{"t":"「아무도 관심 없는 일일까?」","mis":"K6-1-u3-X19"},{"t":"「한쪽 편만 있을까?」","mis":"K6-1-u3-X20"}],"explanation":["곧바로 답이 나오면 토론이 안 돼요.","관심 있어야 근거를 찾을 마음이 생겨요.","당연한 일에 물어보세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L08_challenge#7','kor',6,1,'u3','L08','g6_1_kor_u3_L08_challenge','lesson_challenge','K6-1-u3-C34',3,'mc','auto','토론의 승패가 반론하기에서 갈린다고 하는 까닭은 무엇인가요?',ARRAY['K6-1-u3-X45','K6-1-u3-X08','K6-1-u3-X16']::text[],false,'{"seq":7,"concept":"K6-1-u3-C34","difficulty":3,"kind":"mc","stem":"토론의 승패가 반론하기에서 갈린다고 하는 까닭은 무엇인가요?","options":[{"t":"주장 펼치기는 준비한 대로 말하면 되지만, 반론은 그 순간 들은 것으로만 할 수 있기 때문에","correct":true},{"t":"반론하기에서 목소리를 가장 크게 내기 때문에","mis":"K6-1-u3-X45"},{"t":"반론하기에서 원고를 가장 길게 읽기 때문에","mis":"K6-1-u3-X08"},{"t":"판정단이 반론하기만 보기 때문에","mis":"K6-1-u3-X16"}],"explanation":["목소리 크기로 갈리지 않아요.","원고를 읽으면 혼잣말이 돼요.","그 순간 들은 것으로 되받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L08_challenge#8','kor',6,1,'u3','L08','g6_1_kor_u3_L08_challenge','lesson_challenge','K6-1-u3-C36',4,'mc','auto','「판정이 이상하다」는 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X18','K6-1-u3-X24','K6-1-u3-X39']::text[],false,'{"seq":8,"concept":"K6-1-u3-C36","difficulty":4,"kind":"mc","stem":"「판정이 이상하다」는 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「판정은 정한 기준으로 본 결과니까 승복하자. 그리고 우리 근거에서 약했던 곳을 다시 찾아보자.」","correct":true},{"t":"「맞아, 우리가 옳았으니 판정은 무시하자.」","mis":"K6-1-u3-X18"},{"t":"「다음엔 판정단을 친한 친구로 하자.」","mis":"K6-1-u3-X24"},{"t":"「생각이 흔들리면 지는 거니까 절대 바꾸지 말자.」","mis":"K6-1-u3-X39"}],"explanation":["판정은 무시하지 않아요.","판정단은 공정해야 해요.","승복하고 배운 것을 남겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L08_challenge#9','kor',6,1,'u3','L08','g6_1_kor_u3_L08_challenge','lesson_challenge','K6-1-u3-C34',4,'essay','teacher','토론 중에 메모해야 할 것 세 가지를 쓰고, 메모하며 듣는 것이 반론하기에 왜 중요한지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u3-C34","difficulty":4,"kind":"essay","stem":"토론 중에 메모해야 할 것 세 가지를 쓰고, 메모하며 듣는 것이 반론하기에 왜 중요한지 쓰세요.","answer_guide":{"answer":"예: 상대측 주장을 한 문장으로, 상대가 든 이유의 개수와 내용, 상대가 근거로 든 자료의 출처(누가 언제 냈는지)를 메모한다. 주장 펼치기는 준비한 대로 말하면 되지만 반론하기는 그 순간 들은 것으로만 할 수 있다. 메모가 없으면 준비한 원고만 다시 읽게 되어 혼잣말이 되므로, 메모한 것 가운데 가장 약한 한 곳을 골라 되받아야 한다.","scoring_points":["되받을 거리가 되는 메모 세 가지를 썼는가","반론은 그 순간 들은 것으로 한다는 점을 썼는가","메모로 가장 약한 곳을 골라 되받는다는 점을 썼는가"]},"explanation":["되받을 거리를 떠올려요.","반론하기의 특징을 써요.","메모를 어떻게 쓰는지 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L08_challenge#10','kor',6,1,'u3','L08','g6_1_kor_u3_L08_challenge','lesson_challenge','K6-1-u3-C27',4,'essay','teacher','이 글의 근거가 왜 믿기 어려운지 세 물음으로 따져 쓰고, 근거를 알맞게 바꾸어 다시 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u3-C27","difficulty":4,"kind":"essay","stem":"이 글의 근거가 왜 믿기 어려운지 세 물음으로 따져 쓰고, 근거를 알맞게 바꾸어 다시 쓰세요.","answer_guide":{"answer":"예: 「어떤 누리집」은 어디인지 몰라 출처가 분명하지 않다. 「많은 사람」은 언제 몇 명에게 물었는지 없어 구체적이지 않다. 이모가 답답하다고 한 말은 한 사람의 느낌이라 속도와 사고 사이의 관계와 이어지지 않는다. 고친 근거 — 「우리 시 교통 안전과가 지난해 낸 자료를 보면, 제한 속도를 낮춘 뒤에도 사고가 줄지 않은 구역이 있었습니다.」처럼 누가 언제 낸 자료인지 밝힌다.","scoring_points":["출처 문제를 짚었는가","구체성 문제와 관련성 문제를 짚었는가","누가 언제 낸 자료인지 밝힌 근거로 바꾸어 썼는가"]},"explanation":["누리집의 문제를 짚어요.","많은 사람 · 이모의 말을 따져요.","확인할 수 있는 근거로 바꿔요."],"asset":{"type":"passage","lines":["학교 주변 도로의 제한 속도를 더 낮춰서는 안 된다고 생각합니다.","어떤 누리집에서 봤는데, 속도를 낮추면 오히려 사고가 는다고 합니다.","많은 사람이 그렇게 말합니다.","게다가 저희 이모께서 운전할 때 답답하다고 하셨습니다.","따라서 제한 속도를 낮출 필요는 없습니다."],"title":"어느 학생이 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L11_basic#1','kor',6,1,'u3','L11','g6_1_kor_u3_L11_basic','lesson_basic','K6-1-u3-C37',1,'mc','auto','역사 갈래에서 토론 주제가 되는 것은 어느 것인가요?',ARRAY['K6-1-u3-X01']::text[],false,'{"seq":1,"concept":"K6-1-u3-C37","difficulty":1,"kind":"mc","stem":"역사 갈래에서 토론 주제가 되는 것은 어느 것인가요?","options":[{"t":"우리 지역의 옛 성곽을 원래 모습으로 되살려야 하는가","correct":true},{"t":"그 성곽이 몇 해에 쌓였는가","mis":"K6-1-u3-X01"},{"t":"조선의 도읍이 어디였는가","mis":"K6-1-u3-X01"},{"t":"성곽의 길이가 얼마인가","mis":"K6-1-u3-X01"}],"explanation":["쌓은 해는 찾으면 나와요.","도읍은 자료로 확인돼요.","평가와 선택이 갈리는 물음이라야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L11_basic#2','kor',6,1,'u3','L11','g6_1_kor_u3_L11_basic','lesson_basic','K6-1-u3-C39',1,'mc','auto','원탁 토론에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X41','K6-1-u3-X03']::text[],false,'{"seq":2,"concept":"K6-1-u3-C39","difficulty":1,"kind":"mc","stem":"원탁 토론에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"편을 나누지 않고 모두가 대등하게 돌아가며 말한다","correct":true},{"t":"찬성 측과 반대 측으로 나뉘어 정해진 단계대로 겨룬다","mis":"K6-1-u3-X41"},{"t":"사회자와 판정단이 꼭 있어야 한다","mis":"K6-1-u3-X41"},{"t":"한 사람만 계속 말한다","mis":"K6-1-u3-X03"}],"explanation":["편을 나누는 것은 찬반 토론이에요.","원탁 토론은 사회자를 따로 두지 않아요.","모두가 돌아가며 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L11_basic#3','kor',6,1,'u3','L11','g6_1_kor_u3_L11_basic','lesson_basic','K6-1-u3-C43',1,'mc','auto','「굵다」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K6-1-u3-X44']::text[],false,'{"seq":3,"concept":"K6-1-u3-C43","difficulty":1,"kind":"mc","stem":"「굵다」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[국따]","correct":true},{"t":"[굴따]","mis":"K6-1-u3-X44"},{"t":"[굵다]","mis":"K6-1-u3-X44"},{"t":"[구따]","mis":"K6-1-u3-X44"}],"explanation":["ㄺ 뒤에 ㄷ이 왔어요.","ㄺ은 [ㄱ]으로 소리 나요.","뒤의 ㄷ은 된소리가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L11_basic#4','kor',6,1,'u3','L11','g6_1_kor_u3_L11_basic','lesson_basic','K6-1-u3-C40',1,'ox','auto','역사에 관한 논쟁에서는 한쪽이 옳고 다른 쪽은 틀렸다고 가려야 해요.',ARRAY['K6-1-u3-X42']::text[],false,'{"seq":4,"concept":"K6-1-u3-C40","difficulty":1,"kind":"ox","stem":"역사에 관한 논쟁에서는 한쪽이 옳고 다른 쪽은 틀렸다고 가려야 해요.","answer":"X","reason_options":[{"t":"옳고 그름이 아니라 무엇을 더 중요하게 여겼는지 관점이 다르기 때문에","correct":true},{"t":"역사에는 언제나 정답이 하나뿐이기 때문에","mis":"K6-1-u3-X42"}],"mis":"K6-1-u3-X42","explanation":["두 쪽 다 역사를 아낄 수 있어요.","아끼는 방법에 대한 생각이 달라요.","관점의 차이로 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L11_basic#5','kor',6,1,'u3','L11','g6_1_kor_u3_L11_basic','lesson_basic','K6-1-u3-C4',2,'match','auto','성곽 토론의 발언을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-1-u3-C4","difficulty":2,"kind":"match","stem":"성곽 토론의 발언을 알맞게 이으세요.","pairs":[{"l":"모습을 갖춰야 고장의 역사를 배우는 곳이 된다","r":"찬성 측 이유"},{"l":"되살린 다른 고장 성곽의 방문자 기록","r":"찬성 측 근거"},{"l":"새로 만든 부분이 많으면 옛 성곽이라 하기 어렵다","r":"반대 측 이유"},{"l":"도청이 낸 복원 기준 안내 자료","r":"반대 측 근거"}],"mis":"K6-1-u3-X04","explanation":["까닭인지 자료인지 먼저 나눠요.","그다음 찬반을 갈라요.","같은 대상을 두고도 근거가 갈려요."],"asset":{"type":"speech","turns":[{"who":"찬성 측 벼리","text":"옛 성곽을 원래 모습으로 되살려야 합니다. 지금은 돌담 일부만 남아 있어 사람들이 그곳이 성곽이었는지도 모르고 지나갑니다. 모습을 갖춰야 고장의 역사를 배우는 곳이 됩니다."},{"who":"반대 측 윤재","text":"되살려서는 안 됩니다. 남아 있는 부분이 적어 되살리려면 대부분을 새로 만들어야 합니다. 새로 만든 부분이 많아지면 그것은 옛 성곽이 아니라 새 건물입니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L11_basic#6','kor',6,1,'u3','L11','g6_1_kor_u3_L11_basic','lesson_basic','K6-1-u3-C38',2,'mc','auto','모둠이 근거를 모으는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X43','K6-1-u3-X22']::text[],false,'{"seq":6,"concept":"K6-1-u3-C38","difficulty":2,"kind":"mc","stem":"모둠이 근거를 모으는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"찾을 영역을 나누고, 누가 언제 낸 자료인지 적고, 바꾸어 읽은 뒤 가장 센 두 가지를 고른다","correct":true},{"t":"모은 자료를 하나도 빼지 않고 모두 준비표에 옮긴다","mis":"K6-1-u3-X43"},{"t":"출처는 적지 않고 내용만 적는다","mis":"K6-1-u3-X22"},{"t":"한 사람이 모든 자료를 혼자 찾아 그대로 쓴다","mis":"K6-1-u3-X43"}],"explanation":["모두 옮기면 약한 것까지 들어가요.","출처를 함께 적어요.","나누어 찾고 골라 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L11_basic#7','kor',6,1,'u3','L11','g6_1_kor_u3_L11_basic','lesson_basic','K6-1-u3-C41',2,'mc','auto','토론을 마친 뒤 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X40','K6-1-u3-X18','K6-1-u3-X39']::text[],false,'{"seq":7,"concept":"K6-1-u3-C41","difficulty":2,"kind":"mc","stem":"토론을 마친 뒤 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「사회를 맡은 친구가 말차례를 잘 지켜 줬어. 나는 성곽 기준 자료를 처음 알았어.」","correct":true},{"t":"「역시 우리 편이 이겼네. 상대는 준비가 부족했어.」","mis":"K6-1-u3-X40"},{"t":"「판정이 이상했어. 기준을 잘못 잡은 것 같아.」","mis":"K6-1-u3-X18"},{"t":"「생각이 바뀌었으니 내가 진 거야.」","mis":"K6-1-u3-X39"}],"explanation":["승패와 깎아내리기만 남기지 않아요.","판정에는 승복해요.","잘한 곳과 새로 안 것을 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L11_basic#8','kor',6,1,'u3','L11','g6_1_kor_u3_L11_basic','lesson_basic','K6-1-u3-C43',2,'mc','auto','「옮기다」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K6-1-u3-X44']::text[],false,'{"seq":8,"concept":"K6-1-u3-C43","difficulty":2,"kind":"mc","stem":"「옮기다」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[옴기다]","correct":true},{"t":"[올기다]","mis":"K6-1-u3-X44"},{"t":"[오기다]","mis":"K6-1-u3-X44"},{"t":"[옮끼다]","mis":"K6-1-u3-X44"}],"explanation":["ㄻ 뒤에 자음이 왔어요.","ㄻ은 [ㅁ]으로 소리 나요.","[옴기다]로 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L11_basic#9','kor',6,1,'u3','L11','g6_1_kor_u3_L11_basic','lesson_basic','K6-1-u3-C42',2,'mc','auto','토론을 잘하는 사람의 모습으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X45','K6-1-u3-X07','K6-1-u3-X08']::text[],false,'{"seq":9,"concept":"K6-1-u3-C42","difficulty":2,"kind":"mc","stem":"토론을 잘하는 사람의 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"반론할 때 사람이 아니라 근거를 겨눈다","correct":true},{"t":"말을 가장 많이, 가장 크게 한다","mis":"K6-1-u3-X45"},{"t":"상대가 말할 때 끼어들어 되받는다","mis":"K6-1-u3-X07"},{"t":"준비한 원고를 처음부터 끝까지 읽는다","mis":"K6-1-u3-X08"}],"explanation":["많이 · 크게 말하는 것과 잘하는 것은 달라요.","말차례를 지켜요.","근거를 겨누어 되받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L11_basic#10','kor',6,1,'u3','L11','g6_1_kor_u3_L11_basic','lesson_basic','K6-1-u3-C26',3,'mc','auto','사물함 토론에서 어느 쪽 근거가 더 타당한가요?',ARRAY['K6-1-u3-X32','K6-1-u3-X35','K6-1-u3-X31']::text[],false,'{"seq":10,"concept":"K6-1-u3-C26","difficulty":3,"kind":"mc","stem":"사물함 토론에서 어느 쪽 근거가 더 타당한가요?","options":[{"t":"찬성 측 — 지난달에 백쉰 명에게 물어 조사한 때와 사람 수가 분명하다","correct":true},{"t":"반대 측 — 친구에게 직접 물어본 이야기라 더 생생하다","mis":"K6-1-u3-X32"},{"t":"둘 다 똑같다 — 사람에게 물어본 자료라는 점이 같다","mis":"K6-1-u3-X35"},{"t":"둘 다 근거가 아니다 — 사람에게 물은 것은 근거가 될 수 없다","mis":"K6-1-u3-X31"}],"explanation":["생생함보다 구체성을 봐요.","언제 · 몇 명에게 물었는지 견줘요.","백쉰 명과 두 명은 같은 무게가 아니에요."],"asset":{"type":"passage","lines":["토론 주제 — 우리 반 사물함에 자물쇠를 달아야 한다.","찬성 측 온유 — 물건을 잃어버리는 일이 실제로 있기 때문입니다.","우리 학교 고학년 백쉰 명에게 지난달에 물어보니,","마흔여덟 명이 사물함에서 물건을 잃은 적이 있다고 답했습니다.","반대 측 새얀 — 열고 닫기가 번거롭기 때문입니다.","제 친구 두 명에게 물어보니 둘 다 불편할 것 같다고 했습니다."],"title":"두 근거 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L11_challenge#1','kor',6,1,'u3','L11','g6_1_kor_u3_L11_challenge','lesson_challenge','K6-1-u3-C39',2,'mc','auto','원탁 토론이 찬반 토론보다 알맞은 경우는 어느 것인가요?',ARRAY['K6-1-u3-X41','K6-1-u3-X09','K6-1-u3-X05']::text[],false,'{"seq":1,"concept":"K6-1-u3-C39","difficulty":2,"kind":"mc","stem":"원탁 토론이 찬반 토론보다 알맞은 경우는 어느 것인가요?","options":[{"t":"답이 찬성과 반대 둘로 갈리지 않는 문제를 이야기할 때","correct":true},{"t":"판정단이 꼭 승패를 정해야 할 때","mis":"K6-1-u3-X41"},{"t":"한쪽 편이 반드시 이겨야 할 때","mis":"K6-1-u3-X09"},{"t":"근거 없이 말해도 될 때","mis":"K6-1-u3-X05"}],"explanation":["승패를 정하는 것은 찬반 토론이에요.","이기려는 것이 목적이 아니에요.","어느 토론이든 근거를 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L11_challenge#2','kor',6,1,'u3','L11','g6_1_kor_u3_L11_challenge','lesson_challenge','K6-1-u3-C43',2,'ox','auto','「늙고」는 [늘꼬]로 읽어요.',ARRAY['K6-1-u3-X44']::text[],false,'{"seq":2,"concept":"K6-1-u3-C43","difficulty":2,"kind":"ox","stem":"「늙고」는 [늘꼬]로 읽어요.","answer":"O","reason_options":[{"t":"ㄺ 뒤에 ㄱ이 오면 [ㄹ]로 소리 나고 뒤의 ㄱ은 된소리가 되기 때문에","correct":true},{"t":"겹받침은 언제나 두 자음을 모두 소리 내기 때문에","mis":"K6-1-u3-X44"}],"mis":"K6-1-u3-X44","explanation":["ㄺ 뒤에 ㄱ이 왔어요.","이때는 [ㄹ]로 소리 나요.","[늘꼬]로 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L11_challenge#3','kor',6,1,'u3','L11','g6_1_kor_u3_L11_challenge','lesson_challenge','K6-1-u3-C40',3,'mc','auto','벼리와 윤재의 생각을 알맞게 정리한 말은 어느 것인가요?',ARRAY['K6-1-u3-X42','K6-1-u3-X02']::text[],false,'{"seq":3,"concept":"K6-1-u3-C40","difficulty":3,"kind":"mc","stem":"벼리와 윤재의 생각을 알맞게 정리한 말은 어느 것인가요?","options":[{"t":"한쪽은 배움의 기회를, 다른 쪽은 남은 것의 진짜 모습을 앞에 두었다","correct":true},{"t":"벼리는 역사를 아끼고 윤재는 역사를 아끼지 않는다","mis":"K6-1-u3-X42"},{"t":"되살리자는 쪽이 옳고 반대하는 쪽은 틀렸다","mis":"K6-1-u3-X42"},{"t":"두 사람은 편을 나누지 않고 같은 방법을 찾고 있다","mis":"K6-1-u3-X02"}],"explanation":["두 사람 다 역사를 아껴요.","옳고 그름으로 가르지 않아요.","무엇을 더 중요하게 여겼는지 봐요."],"asset":{"type":"speech","turns":[{"who":"찬성 측 벼리","text":"옛 성곽을 원래 모습으로 되살려야 합니다. 지금은 돌담 일부만 남아 있어 사람들이 그곳이 성곽이었는지도 모르고 지나갑니다. 모습을 갖춰야 고장의 역사를 배우는 곳이 됩니다."},{"who":"반대 측 윤재","text":"되살려서는 안 됩니다. 남아 있는 부분이 적어 되살리려면 대부분을 새로 만들어야 합니다. 새로 만든 부분이 많아지면 그것은 옛 성곽이 아니라 새 건물입니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L11_challenge#4','kor',6,1,'u3','L11','g6_1_kor_u3_L11_challenge','lesson_challenge','K6-1-u3-C37',3,'mc','auto','실천 토론에서 주제를 고를 때의 조건으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X19','K6-1-u3-X01','K6-1-u3-X20']::text[],false,'{"seq":4,"concept":"K6-1-u3-C37","difficulty":3,"kind":"mc","stem":"실천 토론에서 주제를 고를 때의 조건으로 알맞은 것은 어느 것인가요?","options":[{"t":"어느 갈래든 찬반이 갈리고 양쪽 모두 근거를 찾을 수 있어야 한다","correct":true},{"t":"역사 갈래에서만 고를 수 있다","mis":"K6-1-u3-X19"},{"t":"연도나 이름처럼 답이 하나로 나오는 물음이 좋다","mis":"K6-1-u3-X01"},{"t":"한쪽 근거만 있으면 된다","mis":"K6-1-u3-X20"}],"explanation":["역사 · 환경 · 생활 어디서든 찾아요.","답이 하나로 나오면 토론이 안 돼요.","양쪽 모두 근거를 찾을 수 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L11_challenge#5','kor',6,1,'u3','L11','g6_1_kor_u3_L11_challenge','lesson_challenge','K6-1-u3-C38',3,'mc','auto','「모습을 갖춰야 역사를 배우는 곳이 된다」는 이유를 뒷받침할 근거로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X04','K6-1-u3-X27','K6-1-u3-X28']::text[],false,'{"seq":5,"concept":"K6-1-u3-C38","difficulty":3,"kind":"mc","stem":"「모습을 갖춰야 역사를 배우는 곳이 된다」는 이유를 뒷받침할 근거로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"되살린 다른 고장 성곽의 학생 단체 관람 수가 해마다 는 기록","correct":true},{"t":"돌담만 있으면 심심할 것 같다는 내 느낌","mis":"K6-1-u3-X04"},{"t":"공사에는 시간이 오래 걸린다는 일반적인 이야기","mis":"K6-1-u3-X27"},{"t":"어디서 봤는지 모르는 여행 동영상","mis":"K6-1-u3-X28"}],"explanation":["느낌은 근거가 아니에요.","공사 기간은 이유와 이어지지 않아요.","이유와 이어지고 확인할 수 있는 기록이에요."],"asset":{"type":"speech","turns":[{"who":"찬성 측 벼리","text":"옛 성곽을 원래 모습으로 되살려야 합니다. 지금은 돌담 일부만 남아 있어 사람들이 그곳이 성곽이었는지도 모르고 지나갑니다. 모습을 갖춰야 고장의 역사를 배우는 곳이 됩니다."},{"who":"반대 측 윤재","text":"되살려서는 안 됩니다. 남아 있는 부분이 적어 되살리려면 대부분을 새로 만들어야 합니다. 새로 만든 부분이 많아지면 그것은 옛 성곽이 아니라 새 건물입니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L11_challenge#6','kor',6,1,'u3','L11','g6_1_kor_u3_L11_challenge','lesson_challenge','K6-1-u3-C43',3,'error','auto','겹받침 낱말을 읽었어요. 잘못 읽은 친구는 누구인가요?',ARRAY['K6-1-u3-X44']::text[],false,'{"seq":6,"concept":"K6-1-u3-C43","difficulty":3,"kind":"error","stem":"겹받침 낱말을 읽었어요. 잘못 읽은 친구는 누구인가요?","options":[{"t":"라온 — 「굵고」를 [국꼬]로 읽었다","correct":true,"mis_target":"K6-1-u3-X44"},{"t":"하율 — 「읊다」를 [읍따]로 읽었다","mis":"K6-1-u3-X44"},{"t":"서진 — 「젊지」를 [점찌]로 읽었다","mis":"K6-1-u3-X44"}],"explanation":["하율은 ㄿ을 [ㅂ]으로 읽었어요.","서진은 ㄻ을 [ㅁ]으로 읽었어요.","ㄺ 뒤에 ㄱ이 오면 [ㄹ] — [굴꼬]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L11_challenge#7','kor',6,1,'u3','L11','g6_1_kor_u3_L11_challenge','lesson_challenge','K6-1-u3-C42',3,'mc','auto','「자신감 있게, 그러면서도 예의 바르게 표현하는 힘」이 필요한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X45','K6-1-u3-X05','K6-1-u3-X14']::text[],false,'{"seq":7,"concept":"K6-1-u3-C42","difficulty":3,"kind":"mc","stem":"「자신감 있게, 그러면서도 예의 바르게 표현하는 힘」이 필요한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"근거가 좋아도 무례하게 말하면 듣는 사람이 받아들이기 어렵기 때문에","correct":true},{"t":"크게 말할수록 이기기 때문에","mis":"K6-1-u3-X45"},{"t":"예의만 지키면 근거는 없어도 되기 때문에","mis":"K6-1-u3-X05"},{"t":"상대 말투를 겨누기 위해서","mis":"K6-1-u3-X14"}],"explanation":["크게 말한다고 이기지 않아요.","근거도 함께 있어야 해요.","자신감과 예의가 함께 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L11_challenge#8','kor',6,1,'u3','L11','g6_1_kor_u3_L11_challenge','lesson_challenge','K6-1-u3-C41',4,'mc','auto','토론 뒤 소감 나누기에서 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['K6-1-u3-X40','K6-1-u3-X42','K6-1-u3-X39']::text[],false,'{"seq":8,"concept":"K6-1-u3-C41","difficulty":4,"kind":"mc","stem":"토론 뒤 소감 나누기에서 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"「반대 측이 낸 복원 기준 자료를 듣고 되살릴 때 무엇을 지켜야 하는지 생각이 더 깊어졌어. 판정을 맡은 친구가 기준을 먼저 밝혀서 좋았어.」","correct":true},{"t":"「우리 편이 이겼으니 더 할 말이 없어.」","mis":"K6-1-u3-X40"},{"t":"「반대 측은 역사를 모르는 거야.」","mis":"K6-1-u3-X42"},{"t":"「생각이 바뀌면 진 거라 끝까지 안 바꿨어.」","mis":"K6-1-u3-X39"}],"explanation":["승패만 말하면 남는 것이 없어요.","상대 관점을 낮추지 않아요.","새로 안 것과 잘한 친구를 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L11_challenge#9','kor',6,1,'u3','L11','g6_1_kor_u3_L11_challenge','lesson_challenge','K6-1-u3-C40',4,'essay','teacher','성곽 토론에서 찬성 측과 반대 측이 각각 무엇을 중요하게 여겼는지 쓰고, 역사 문제로 토론할 때 상대 생각을 어떻게 대해야 하는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u3-C40","difficulty":4,"kind":"essay","stem":"성곽 토론에서 찬성 측과 반대 측이 각각 무엇을 중요하게 여겼는지 쓰고, 역사 문제로 토론할 때 상대 생각을 어떻게 대해야 하는지 쓰세요.","answer_guide":{"answer":"예: 찬성 측 벼리는 사람들이 고장의 역사를 배울 수 있는 기회를 중요하게 여겼다. 반대 측 윤재는 남아 있는 옛 성곽의 진짜 모습을 지키는 것을 중요하게 여겼다. 두 사람 다 역사를 아끼지만 아끼는 방법이 다르다. 역사에 관한 논쟁에는 옳고 그름이 아니라 관점의 차이가 있으므로, 한쪽을 틀린 편으로 만들지 않고 판정 뒤에도 상대 생각을 낮추어 말하지 않아야 한다.","scoring_points":["찬성 측이 중요하게 여긴 것을 썼는가","반대 측이 중요하게 여긴 것을 썼는가","관점의 차이로 보고 상대를 낮추지 않는 태도를 썼는가"]},"explanation":["벼리가 앞에 둔 것을 찾아요.","윤재가 앞에 둔 것을 찾아요.","옳고 그름 대신 관점으로 봐요."],"asset":{"type":"speech","turns":[{"who":"찬성 측 벼리","text":"옛 성곽을 원래 모습으로 되살려야 합니다. 지금은 돌담 일부만 남아 있어 사람들이 그곳이 성곽이었는지도 모르고 지나갑니다. 모습을 갖춰야 고장의 역사를 배우는 곳이 됩니다."},{"who":"반대 측 윤재","text":"되살려서는 안 됩니다. 남아 있는 부분이 적어 되살리려면 대부분을 새로 만들어야 합니다. 새로 만든 부분이 많아지면 그것은 옛 성곽이 아니라 새 건물입니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L11_challenge#10','kor',6,1,'u3','L11','g6_1_kor_u3_L11_challenge','lesson_challenge','K6-1-u3-C43',4,'essay','teacher','ㄻ · ㄿ · ㄺ 겹받침이 있는 낱말을 하나씩 골라 소리 나는 대로 쓰고, 겹받침을 읽는 규칙을 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u3-C43","difficulty":4,"kind":"essay","stem":"ㄻ · ㄿ · ㄺ 겹받침이 있는 낱말을 하나씩 골라 소리 나는 대로 쓰고, 겹받침을 읽는 규칙을 설명하세요.","answer_guide":{"answer":"예: 닮다 [담따] · 읊다 [읍따] · 붉다 [북따]. 겹받침 뒤에 자음이 오면 두 자음 가운데 하나만 소리 난다. ㄻ은 [ㅁ], ㄿ은 [ㅂ], ㄺ은 [ㄱ]으로 소리 나고, 그 뒤에 오는 ㄱ · ㄷ · ㅂ · ㅅ · ㅈ은 된소리가 된다. 다만 ㄺ 뒤에 ㄱ이 오면 [ㄹ]로 소리 나서 「붉고」는 [불꼬]로 읽는다.","scoring_points":["세 겹받침 낱말을 하나씩 바르게 소리 나는 대로 썼는가","하나만 소리 나고 뒤 자음이 된소리가 된다는 규칙을 썼는가","ㄺ 뒤에 ㄱ이 올 때의 예외를 썼는가"]},"explanation":["세 겹받침을 하나씩 골라요.","어느 자음이 소리 나는지 써요.","ㄺ 뒤 ㄱ의 경우를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#1','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C3',1,'mc','auto','찬성과 반대로 나뉘어 근거를 들어 자기 주장이 옳음을 밝히는 말하기를 무엇이라고 하나요?',ARRAY['K6-1-u3-X02','K6-1-u3-X03']::text[],false,'{"seq":1,"concept":"K6-1-u3-C3","difficulty":1,"kind":"mc","stem":"찬성과 반대로 나뉘어 근거를 들어 자기 주장이 옳음을 밝히는 말하기를 무엇이라고 하나요?","options":[{"t":"토론","correct":true},{"t":"토의","mis":"K6-1-u3-X02"},{"t":"연설","mis":"K6-1-u3-X03"},{"t":"대화","mis":"K6-1-u3-X02"}],"explanation":["토의는 편을 나누지 않아요.","연설은 한 사람이 알리는 말하기예요.","찬반으로 나뉘어 겨루면 토론이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#2','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C4',1,'mc','auto','이유를 뒷받침하는 객관적인 자료를 무엇이라고 하나요?',ARRAY['K6-1-u3-X04','K6-1-u3-X06']::text[],false,'{"seq":2,"concept":"K6-1-u3-C4","difficulty":1,"kind":"mc","stem":"이유를 뒷받침하는 객관적인 자료를 무엇이라고 하나요?","options":[{"t":"근거","correct":true},{"t":"주장","mis":"K6-1-u3-X04"},{"t":"이유","mis":"K6-1-u3-X04"},{"t":"반론","mis":"K6-1-u3-X06"}],"explanation":["주장은 내세우는 생각이에요.","이유는 내 까닭이에요.","밖에서 가져온 자료가 근거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#3','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C5',1,'mc','auto','토론의 첫 단계는 무엇인가요?',ARRAY['K6-1-u3-X06']::text[],false,'{"seq":3,"concept":"K6-1-u3-C5","difficulty":1,"kind":"mc","stem":"토론의 첫 단계는 무엇인가요?","options":[{"t":"주장 펼치기","correct":true},{"t":"반론하기","mis":"K6-1-u3-X06"},{"t":"주장 다지기","mis":"K6-1-u3-X06"},{"t":"판정하기","mis":"K6-1-u3-X06"}],"explanation":["반론은 주장을 들은 뒤에 해요.","다지기는 셋째 단계예요.","먼저 주장을 펼쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#4','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C13',1,'ox','auto','반론할 때에는 상대의 말투나 사람이 아니라 주장 · 이유 · 근거를 겨누어요.',ARRAY['K6-1-u3-X14']::text[],false,'{"seq":4,"concept":"K6-1-u3-C13","difficulty":1,"kind":"ox","stem":"반론할 때에는 상대의 말투나 사람이 아니라 주장 · 이유 · 근거를 겨누어요.","answer":"O","reason_options":[{"t":"토론은 근거를 겨루는 공식적인 말하기이기 때문에","correct":true},{"t":"사람을 겨누어야 상대가 물러서기 때문에","mis":"K6-1-u3-X14"}],"mis":"K6-1-u3-X14","explanation":["사람을 겨누면 반론이 아니에요.","공식적인 말하기예요.","주장 · 이유 · 근거를 겨눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#5','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C15',1,'mc','auto','판정단이 판정하기 전에 먼저 밝혀야 하는 것은 무엇인가요?',ARRAY['K6-1-u3-X16','K6-1-u3-X24']::text[],false,'{"seq":5,"concept":"K6-1-u3-C15","difficulty":1,"kind":"mc","stem":"판정단이 판정하기 전에 먼저 밝혀야 하는 것은 무엇인가요?","options":[{"t":"판정 기준","correct":true},{"t":"평소 자기 생각","mis":"K6-1-u3-X16"},{"t":"친한 친구 이름","mis":"K6-1-u3-X24"},{"t":"좋아하는 편","mis":"K6-1-u3-X24"}],"explanation":["평소 생각은 판정과 관계없어요.","친한 사이도 관계없어요.","기준을 먼저 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#6','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C23',1,'mc','auto','주제와 규칙을 알리고 말차례를 이끄는 역할은 무엇인가요?',ARRAY['K6-1-u3-X25']::text[],false,'{"seq":6,"concept":"K6-1-u3-C23","difficulty":1,"kind":"mc","stem":"주제와 규칙을 알리고 말차례를 이끄는 역할은 무엇인가요?","options":[{"t":"사회자","correct":true},{"t":"토론자","mis":"K6-1-u3-X25"},{"t":"판정단","mis":"K6-1-u3-X25"},{"t":"청중","mis":"K6-1-u3-X25"}],"explanation":["토론자는 주장을 말해요.","판정단은 판정해요.","이끄는 사람은 사회자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#7','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C26',1,'mc','auto','근거를 따질 때 던지는 물음으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X35','K6-1-u3-X30']::text[],false,'{"seq":7,"concept":"K6-1-u3-C26","difficulty":1,"kind":"mc","stem":"근거를 따질 때 던지는 물음으로 알맞은 것은 어느 것인가요?","options":[{"t":"「출처가 분명한가?」","correct":true},{"t":"「글씨가 예쁜가?」","mis":"K6-1-u3-X35"},{"t":"「자료가 길고 어려운가?」","mis":"K6-1-u3-X30"},{"t":"「내 마음에 드는가?」","mis":"K6-1-u3-X35"}],"explanation":["글씨는 상관없어요.","길이도 상관없어요.","어디서 나왔는지 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#8','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C43',1,'mc','auto','「읊다」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K6-1-u3-X44']::text[],false,'{"seq":8,"concept":"K6-1-u3-C43","difficulty":1,"kind":"mc","stem":"「읊다」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[읍따]","correct":true},{"t":"[을따]","mis":"K6-1-u3-X44"},{"t":"[읊다]","mis":"K6-1-u3-X44"},{"t":"[으따]","mis":"K6-1-u3-X44"}],"explanation":["ㄿ 뒤에 ㄷ이 왔어요.","ㄿ은 [ㅂ]으로 소리 나요.","뒤의 ㄷ은 된소리가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#9','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C9',2,'mc','auto','도담이가 주장 펼치기에서 낸 근거는 무엇인가요?',ARRAY['K6-1-u3-X04','K6-1-u3-X05','K6-1-u3-X28']::text[],false,'{"seq":9,"concept":"K6-1-u3-C9","difficulty":2,"kind":"mc","stem":"도담이가 주장 펼치기에서 낸 근거는 무엇인가요?","options":[{"t":"도서부가 이번 학기에 고학년 이백 명에게 물은 설문","correct":true},{"t":"쉬는 시간만으로는 책을 고를 시간이 모자란다","mis":"K6-1-u3-X04"},{"t":"점심시간에도 도서실을 열어야 한다","mis":"K6-1-u3-X05"},{"t":"어떤 누리집에서 본 이야기","mis":"K6-1-u3-X28"}],"explanation":["시간이 모자란다는 것은 이유예요.","열어야 한다는 것은 주장이에요.","물어서 센 설문이 근거예요."],"asset":{"type":"speech","turns":[{"who":"사회자 하람","text":"지금부터 「점심시간에도 학교 도서실을 열어야 한다」라는 주제로 토론을 시작하겠습니다. 찬성 측부터 주장을 펼쳐 주십시오."},{"who":"찬성 측 도담","text":"점심시간에도 도서실을 열어야 합니다. 쉬는 시간만으로는 책을 고를 시간이 모자라기 때문입니다. 도서부가 이번 학기에 고학년 이백 명에게 물어보니, 백삼십 명이 점심시간에 책을 빌리고 싶다고 답했습니다."},{"who":"반대 측 서아","text":"점심시간에는 도서실을 닫아야 합니다. 도서실을 지키는 분도 쉬는 시간이 있어야 하기 때문입니다. 어떤 누리집에서 봤는데 다른 학교도 다 닫는다고 합니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#10','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C13',2,'mc','auto','서아의 첫 반론이 알맞지 않은 까닭은 무엇인가요?',ARRAY['K6-1-u3-X17','K6-1-u3-X26','K6-1-u3-X11']::text[],false,'{"seq":10,"concept":"K6-1-u3-C13","difficulty":2,"kind":"mc","stem":"서아의 첫 반론이 알맞지 않은 까닭은 무엇인가요?","options":[{"t":"「그것도 모르십니까?」처럼 사람을 겨누었기 때문에","correct":true},{"t":"높임말을 썼기 때문에","mis":"K6-1-u3-X17"},{"t":"짧게 말했기 때문에","mis":"K6-1-u3-X26"},{"t":"주제와 이어졌기 때문에","mis":"K6-1-u3-X11"}],"explanation":["높임말은 써야 해요.","짧은 것은 문제가 아니에요.","사람을 겨누면 반론이 아니에요."],"asset":{"type":"speech","turns":[{"who":"반대 측 서아","text":"그것도 모르십니까? 점심시간에는 다들 운동장에 나갑니다."},{"who":"찬성 측 도담","text":"말씀 잘 들었습니다. 다만 저희 설문에서 백삼십 명이 빌리고 싶다고 답했습니다. 다들 운동장에 나간다는 말은 저희 자료와 맞지 않습니다."},{"who":"찬성 측 도담","text":"반대 측께 묻겠습니다. 다른 학교도 다 닫는다는 누리집은 어디이고, 언제 쓴 글입니까?"},{"who":"반대 측 서아","text":"누리집 이름은 적어 두지 못했습니다. 그런데 저는 요즘 급식 줄이 더 문제라고 봅니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#11','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C14',2,'mc','auto','서아의 주장 다지기가 약한 까닭은 무엇인가요?',ARRAY['K6-1-u3-X15','K6-1-u3-X17','K6-1-u3-X22']::text[],false,'{"seq":11,"concept":"K6-1-u3-C14","difficulty":2,"kind":"mc","stem":"서아의 주장 다지기가 약한 까닭은 무엇인가요?","options":[{"t":"반론에서 무너진 누리집 근거를 다시 꺼냈기 때문에","correct":true},{"t":"짧게 말했기 때문에","mis":"K6-1-u3-X15"},{"t":"높임말을 썼기 때문에","mis":"K6-1-u3-X17"},{"t":"새 근거를 찾아 왔기 때문에","mis":"K6-1-u3-X22"}],"explanation":["짧은 것은 오히려 좋아요.","높임말은 써야 해요.","무너진 근거를 꺼내면 약해져요."],"asset":{"type":"speech","turns":[{"who":"찬성 측 도담","text":"요컨대 책을 읽고 싶은 학생이 많습니다. 백삼십 명이라는 설문은 반론에서도 흔들리지 않았습니다. 따라서 점심시간에도 도서실을 열어야 합니다."},{"who":"반대 측 서아","text":"처음에 말씀드린 대로 다른 학교도 다 닫는다는 점을 다시 말씀드립니다. 다른 학교도 다 닫으니 우리도 닫아야 합니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#12','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C33',2,'mc','auto','지우의 판정이 알맞지 않은 까닭은 무엇인가요?',ARRAY['K6-1-u3-X17','K6-1-u3-X16','K6-1-u3-X18']::text[],false,'{"seq":12,"concept":"K6-1-u3-C33","difficulty":2,"kind":"mc","stem":"지우의 판정이 알맞지 않은 까닭은 무엇인가요?","options":[{"t":"기준 없이 평소 자기 생각과 같은 편을 골랐기 때문에","correct":true},{"t":"찬성 측을 골랐기 때문에","mis":"K6-1-u3-X17"},{"t":"짧게 말했기 때문에","mis":"K6-1-u3-X16"},{"t":"판정을 했기 때문에","mis":"K6-1-u3-X18"}],"explanation":["어느 편을 골랐는지가 문제가 아니에요.","길이가 문제가 아니에요.","평소 생각으로 정한 것이 문제예요."],"asset":{"type":"speech","turns":[{"who":"판정단 지우","text":"저는 원래 도서실을 열자는 생각이어서 찬성 측이 이겼다고 봅니다."},{"who":"판정단 나래","text":"저는 미리 정한 기준, 곧 근거가 믿을 만한가와 반론에 알맞게 답했는가로 보았습니다. 이 기준으로 찬성 측이 더 설득력 있었다고 판정합니다. 반대 측이 지키는 분의 쉬는 시간을 짚은 점은 좋았습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#13','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C34',2,'mc','auto','은솔이의 메모 가운데 되받을 거리로 쓰기 어려운 것은 어느 것인가요?',ARRAY['K6-1-u3-X12','K6-1-u3-X08']::text[],false,'{"seq":13,"concept":"K6-1-u3-C34","difficulty":2,"kind":"mc","stem":"은솔이의 메모 가운데 되받을 거리로 쓰기 어려운 것은 어느 것인가요?","options":[{"t":"반대 측 말투 — 목소리가 컸음.","correct":true},{"t":"찬성 측 근거 — 도서부, 이번 학기, 고학년 이백 명 설문.","mis":"K6-1-u3-X12"},{"t":"반대 측 근거 — 어떤 누리집(어디인지 밝히지 않음).","mis":"K6-1-u3-X08"},{"t":"반대 측이 꺼낸 다른 이야기 — 급식 줄.","mis":"K6-1-u3-X08"}],"explanation":["근거의 출처는 되받을 거리예요.","밝히지 않은 출처도 짚을 곳이에요.","말투는 되받을 거리가 아니에요."],"asset":{"type":"passage","lines":["찬성 측 주장 — 점심시간에도 도서실을 열어야 한다.","찬성 측 이유 — 쉬는 시간만으로는 책 고를 시간이 모자란다.","찬성 측 근거 — 도서부, 이번 학기, 고학년 이백 명 설문.","반대 측 근거 — 어떤 누리집(어디인지 밝히지 않음).","반대 측이 꺼낸 다른 이야기 — 급식 줄.","반대 측 말투 — 목소리가 컸음."],"title":"청중 은솔이의 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#14','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C22',2,'mc','auto','예상 반론에 미리 답변을 준비하는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X09','K6-1-u3-X23','K6-1-u3-X16']::text[],false,'{"seq":14,"concept":"K6-1-u3-C22","difficulty":2,"kind":"mc","stem":"예상 반론에 미리 답변을 준비하는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"그 과정에서 내 근거의 약한 곳을 스스로 점검하게 되기 때문에","correct":true},{"t":"상대 원고를 미리 알 수 있기 때문에","mis":"K6-1-u3-X09"},{"t":"토론에서 반론하기를 건너뛰기 위해서","mis":"K6-1-u3-X23"},{"t":"판정단에게 점수를 받기 위해서","mis":"K6-1-u3-X16"}],"explanation":["상대 원고는 알 수 없어요.","반론하기는 건너뛰지 않아요.","내 근거의 약한 곳이 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#15','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C18',2,'mc','auto','우리 반 토론 주제를 고를 때 따질 조건을 바르게 말한 것은 어느 것인가요?',ARRAY['K6-1-u3-X01','K6-1-u3-X20','K6-1-u3-X19']::text[],false,'{"seq":15,"concept":"K6-1-u3-C18","difficulty":2,"kind":"mc","stem":"우리 반 토론 주제를 고를 때 따질 조건을 바르게 말한 것은 어느 것인가요?","options":[{"t":"친구들이 관심 있고, 찬반이 갈리고, 양쪽 근거를 찾을 수 있고, 우리 힘으로 바꿀 수 있는가","correct":true},{"t":"답이 정해져 있고 확인이 쉬운가","mis":"K6-1-u3-X01"},{"t":"한쪽 편만 있는가","mis":"K6-1-u3-X20"},{"t":"우리가 바꿀 수 없는 먼 일인가","mis":"K6-1-u3-X19"}],"explanation":["답이 정해지면 토론이 안 돼요.","찬반이 갈려야 해요.","관심 · 찬반 · 근거 · 바꿔 볼 수 있음을 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#16','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C29',2,'mc','auto','경험을 근거로 쓰는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X32','K6-1-u3-X31','K6-1-u3-X04']::text[],false,'{"seq":16,"concept":"K6-1-u3-C29","difficulty":2,"kind":"mc","stem":"경험을 근거로 쓰는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"느낌으로 두지 말고 세거나 재어서 정리해 내놓는다","correct":true},{"t":"나에게만 일어난 드문 일을 고른다","mis":"K6-1-u3-X32"},{"t":"경험은 근거가 될 수 없으니 쓰지 않는다","mis":"K6-1-u3-X31"},{"t":"생생하게 느낌만 말한다","mis":"K6-1-u3-X04"}],"explanation":["드문 일은 근거가 되기 어려워요.","경험도 근거가 될 수 있어요.","세거나 재어 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#17','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C24',3,'mc','auto','찬반 토론의 진행 순서로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X06']::text[],false,'{"seq":17,"concept":"K6-1-u3-C24","difficulty":3,"kind":"mc","stem":"찬반 토론의 진행 순서로 알맞은 것은 어느 것인가요?","options":[{"t":"주장 펼치기 → 반대 측 반론과 찬성 측 답변 → 찬성 측 반론과 반대 측 답변 → 주장 다지기 → 판정","correct":true},{"t":"판정 → 주장 펼치기 → 반론 → 주장 다지기","mis":"K6-1-u3-X06"},{"t":"반론 → 주장 펼치기 → 판정 → 주장 다지기","mis":"K6-1-u3-X06"},{"t":"주장 펼치기 → 주장 다지기 → 판정 → 반론","mis":"K6-1-u3-X06"}],"explanation":["판정은 맨 끝이에요.","반론은 펼친 뒤에 해요.","두 편이 번갈아 반론하고 답해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#18','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C28',3,'mc','auto','사물함 토론에서 새얀이의 근거를 더 타당하게 바꾸는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X32','K6-1-u3-X30','K6-1-u3-X28']::text[],false,'{"seq":18,"concept":"K6-1-u3-C28","difficulty":3,"kind":"mc","stem":"사물함 토론에서 새얀이의 근거를 더 타당하게 바꾸는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"언제, 몇 명에게 물었는지 밝혀 우리 반이나 학년 전체에게 물어본다","correct":true},{"t":"친구 두 명의 말을 더 생생하게 꾸민다","mis":"K6-1-u3-X32"},{"t":"두 명에게 다섯 번씩 묻는다","mis":"K6-1-u3-X30"},{"t":"누리집 이야기를 덧붙인다","mis":"K6-1-u3-X28"}],"explanation":["생생하게 꾸며도 두 명이에요.","같은 사람에게 여러 번 물어도 그대로예요.","대상을 넓히고 때를 밝혀요."],"asset":{"type":"passage","lines":["토론 주제 — 우리 반 사물함에 자물쇠를 달아야 한다.","찬성 측 온유 — 물건을 잃어버리는 일이 실제로 있기 때문입니다.","우리 학교 고학년 백쉰 명에게 지난달에 물어보니,","마흔여덟 명이 사물함에서 물건을 잃은 적이 있다고 답했습니다.","반대 측 새얀 — 열고 닫기가 번거롭기 때문입니다.","제 친구 두 명에게 물어보니 둘 다 불편할 것 같다고 했습니다."],"title":"두 근거 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#19','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C12',3,'error','auto','반론에 대한 답변을 했어요. 알맞지 않은 답변을 한 친구는 누구인가요?',ARRAY['K6-1-u3-X13']::text[],false,'{"seq":19,"concept":"K6-1-u3-C12","difficulty":3,"kind":"error","stem":"반론에 대한 답변을 했어요. 알맞지 않은 답변을 한 친구는 누구인가요?","options":[{"t":"이안 — 「어쨌든 저희가 맞습니다. 맞으니까 맞습니다.」","correct":true,"mis_target":"K6-1-u3-X13"},{"t":"서윤 — 「그 점은 인정합니다. 다만 서로 다른 학년 사이의 일이 더 많았습니다.」","mis":"K6-1-u3-X13"},{"t":"하람 — 「조사한 때는 자료 맨 위에 적혀 있습니다.」","mis":"K6-1-u3-X13"}],"explanation":["서윤은 인정하고 다시 세웠어요.","하람은 물은 것에 곧바로 답했어요.","이안은 같은 말을 되풀이했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#20','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C36',3,'mc','auto','도서실 토론 뒤 세 친구의 말 가운데 가장 알맞게 마무리한 사람은 누구인가요?',ARRAY['K6-1-u3-X18','K6-1-u3-X40','K6-1-u3-X39']::text[],false,'{"seq":20,"concept":"K6-1-u3-C36","difficulty":3,"kind":"mc","stem":"도서실 토론 뒤 세 친구의 말 가운데 가장 알맞게 마무리한 사람은 누구인가요?","options":[{"t":"도담 — 상대 근거에서 미처 생각 못 한 점을 받아들이고 더 찾아보려 했다","correct":true},{"t":"서아 — 판정이 이상하다며 판정단 탓을 했다","mis":"K6-1-u3-X18"},{"t":"아무도 없다 — 토론 뒤에는 승패만 말하면 된다","mis":"K6-1-u3-X40"},{"t":"아무도 없다 — 생각이 바뀌면 진 것이다","mis":"K6-1-u3-X39"}],"explanation":["판정에는 승복해요.","승패만 남기지 않아요.","생각을 남기는 마무리가 좋아요."],"asset":{"type":"speech","turns":[{"who":"서아","text":"판정이 이상해. 우리가 진 건 판정단 탓이야."},{"who":"은솔","text":"나는 도서부 설문 자료를 처음 알았어. 사회를 맡은 하람이가 말차례를 잘 지켜 줬어."},{"who":"도담","text":"반대 측이 말한 지키는 분의 쉬는 시간은 미처 생각 못 했어. 도서부가 돌아가며 돕는 방법을 찾아봐야겠어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#21','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C40',3,'mc','auto','「옛 건물을 헐고 남은 터를 공원으로 만들어야 한다」를 두고 토론할 때 알맞은 태도는 어느 것인가요?',ARRAY['K6-1-u3-X42','K6-1-u3-X40']::text[],false,'{"seq":21,"concept":"K6-1-u3-C40","difficulty":3,"kind":"mc","stem":"「옛 건물을 헐고 남은 터를 공원으로 만들어야 한다」를 두고 토론할 때 알맞은 태도는 어느 것인가요?","options":[{"t":"서로 무엇을 더 중요하게 여기는지 관점의 차이로 보고 상대 생각을 낮추어 말하지 않는다","correct":true},{"t":"공원으로 만들자는 쪽이 옳다고 먼저 정해 둔다","mis":"K6-1-u3-X42"},{"t":"역사를 아끼는 쪽과 아끼지 않는 쪽으로 나눈다","mis":"K6-1-u3-X42"},{"t":"판정 뒤 상대 생각은 틀렸다고 말한다","mis":"K6-1-u3-X40"}],"explanation":["옳은 쪽을 먼저 정하지 않아요.","두 쪽 다 아낄 수 있어요.","관점의 차이로 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#22','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C43',3,'mc','auto','「밝고」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K6-1-u3-X44']::text[],false,'{"seq":22,"concept":"K6-1-u3-C43","difficulty":3,"kind":"mc","stem":"「밝고」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[발꼬]","correct":true},{"t":"[박꼬]","mis":"K6-1-u3-X44"},{"t":"[발고]","mis":"K6-1-u3-X44"},{"t":"[밝고]","mis":"K6-1-u3-X44"}],"explanation":["ㄺ 뒤에 ㄱ이 왔어요.","이때는 [ㄹ]로 소리 나요.","뒤의 ㄱ은 된소리가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#23','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C27',4,'mc','auto','반대 측 서아의 주장 펼치기를 가장 알맞게 고친 것은 어느 것인가요?',ARRAY['K6-1-u3-X29','K6-1-u3-X05','K6-1-u3-X32']::text[],false,'{"seq":23,"concept":"K6-1-u3-C27","difficulty":4,"kind":"mc","stem":"반대 측 서아의 주장 펼치기를 가장 알맞게 고친 것은 어느 것인가요?","options":[{"t":"이유는 그대로 두고, 「어떤 누리집」 대신 학교가 올해 낸 도서실 운영 안내처럼 누가 언제 냈는지 확인되는 자료를 근거로 든다","correct":true},{"t":"누리집 이야기를 「많은 누리집」으로 바꾼다","mis":"K6-1-u3-X29"},{"t":"근거를 빼고 이유만 여러 번 말한다","mis":"K6-1-u3-X05"},{"t":"자기 친구 한 명의 느낌을 근거로 더한다","mis":"K6-1-u3-X32"}],"explanation":["「많은」도 흐릿해요.","근거를 빼면 확인할 수 없어요.","출처가 분명한 자료로 바꿔요."],"asset":{"type":"speech","turns":[{"who":"사회자 하람","text":"지금부터 「점심시간에도 학교 도서실을 열어야 한다」라는 주제로 토론을 시작하겠습니다. 찬성 측부터 주장을 펼쳐 주십시오."},{"who":"찬성 측 도담","text":"점심시간에도 도서실을 열어야 합니다. 쉬는 시간만으로는 책을 고를 시간이 모자라기 때문입니다. 도서부가 이번 학기에 고학년 이백 명에게 물어보니, 백삼십 명이 점심시간에 책을 빌리고 싶다고 답했습니다."},{"who":"반대 측 서아","text":"점심시간에는 도서실을 닫아야 합니다. 도서실을 지키는 분도 쉬는 시간이 있어야 하기 때문입니다. 어떤 누리집에서 봤는데 다른 학교도 다 닫는다고 합니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#24','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C13',4,'essay','teacher','서아의 반론 두 군데에서 알맞지 않은 점을 찾아 쓰고, 찬성 측 근거를 겨누는 알맞은 반론으로 고쳐 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u3-C13","difficulty":4,"kind":"essay","stem":"서아의 반론 두 군데에서 알맞지 않은 점을 찾아 쓰고, 찬성 측 근거를 겨누는 알맞은 반론으로 고쳐 쓰세요.","answer_guide":{"answer":"예: 첫째, 「그것도 모르십니까?」는 근거가 아니라 사람을 겨눈 말이다. 둘째, 「급식 줄이 더 문제」는 주장 펼치기에서 나온 내용과 상관없는 새 이야기이다. 고친 반론 — 「찬성 측 설문은 빌리고 싶다고 답한 학생 수를 보여 줍니다. 그런데 실제로 점심시간에 도서실에 올 수 있는 학생이 몇 명인지는 나와 있지 않습니다.」","scoring_points":["사람을 겨눈 점을 찾았는가","주제와 상관없는 이야기를 꺼낸 점을 찾았는가","찬성 측 근거를 겨누는 반론을 높임말로 썼는가"]},"explanation":["겨눈 곳이 어디인지 봐요.","주장 펼치기와 이어지는지 봐요.","근거를 겨누어 고쳐요."],"asset":{"type":"speech","turns":[{"who":"반대 측 서아","text":"그것도 모르십니까? 점심시간에는 다들 운동장에 나갑니다."},{"who":"찬성 측 도담","text":"말씀 잘 들었습니다. 다만 저희 설문에서 백삼십 명이 빌리고 싶다고 답했습니다. 다들 운동장에 나간다는 말은 저희 자료와 맞지 않습니다."},{"who":"찬성 측 도담","text":"반대 측께 묻겠습니다. 다른 학교도 다 닫는다는 누리집은 어디이고, 언제 쓴 글입니까?"},{"who":"반대 측 서아","text":"누리집 이름은 적어 두지 못했습니다. 그런데 저는 요즘 급식 줄이 더 문제라고 봅니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#25','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C5',4,'essay','teacher','토론의 네 단계를 차례대로 쓰고, 각 단계에서 지켜야 할 절차나 규칙을 한 가지씩 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u3-C5","difficulty":4,"kind":"essay","stem":"토론의 네 단계를 차례대로 쓰고, 각 단계에서 지켜야 할 절차나 규칙을 한 가지씩 쓰세요.","answer_guide":{"answer":"예: 주장 펼치기 — 주장과 이유, 근거를 함께 낸다. 반론하기 — 주장 펼치기에서 나온 내용에 대해서만 되받고, 사람이 아니라 근거를 겨눈다. 주장 다지기 — 같은 말을 되풀이하지 않고 남은 것만 추려 다시 세운다. 판정하기 — 판정단이 기준을 먼저 밝히고 토론에서 나온 내용만으로 정한다.","scoring_points":["네 단계를 차례대로 썼는가","단계마다 알맞은 규칙을 썼는가","판정에서 기준을 밝힌다는 점을 썼는가"]},"explanation":["네 단계의 이름을 차례로 써요.","단계마다 규칙을 하나씩 써요.","판정 기준을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#1','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C2',1,'ox','auto','토의는 편을 나누어 겨루고, 토론은 편 없이 방법을 모으는 말하기예요.',ARRAY['K6-1-u3-X02']::text[],false,'{"seq":1,"concept":"K6-1-u3-C2","difficulty":1,"kind":"ox","stem":"토의는 편을 나누어 겨루고, 토론은 편 없이 방법을 모으는 말하기예요.","answer":"X","reason_options":[{"t":"반대로 토의는 편 없이 방법을 모으고, 토론은 찬반으로 나뉘어 겨루기 때문에","correct":true},{"t":"둘은 이름만 다르고 같은 말하기이기 때문에","mis":"K6-1-u3-X02"}],"mis":"K6-1-u3-X02","explanation":["두 말이 뒤바뀌었어요.","토의는 함께 방법을 모아요.","토론은 찬반으로 나뉘어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#2','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C4',1,'mc','auto','내가 옳다고 내세우는 생각을 무엇이라고 하나요?',ARRAY['K6-1-u3-X04','K6-1-u3-X06']::text[],false,'{"seq":2,"concept":"K6-1-u3-C4","difficulty":1,"kind":"mc","stem":"내가 옳다고 내세우는 생각을 무엇이라고 하나요?","options":[{"t":"주장","correct":true},{"t":"근거","mis":"K6-1-u3-X04"},{"t":"이유","mis":"K6-1-u3-X04"},{"t":"판정","mis":"K6-1-u3-X06"}],"explanation":["근거는 자료예요.","이유는 까닭이에요.","내세우는 생각이 주장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#3','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C5',1,'mc','auto','토론의 마지막 단계는 무엇인가요?',ARRAY['K6-1-u3-X06']::text[],false,'{"seq":3,"concept":"K6-1-u3-C5","difficulty":1,"kind":"mc","stem":"토론의 마지막 단계는 무엇인가요?","options":[{"t":"판정하기","correct":true},{"t":"주장 펼치기","mis":"K6-1-u3-X06"},{"t":"반론하기","mis":"K6-1-u3-X06"},{"t":"주장 다지기","mis":"K6-1-u3-X06"}],"explanation":["펼치기는 첫 단계예요.","반론은 둘째 단계예요.","판정은 맨 끝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#4','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C13',1,'mc','auto','반론으로 알맞은 말은 어느 것인가요?',ARRAY['K6-1-u3-X14']::text[],false,'{"seq":4,"concept":"K6-1-u3-C13","difficulty":1,"kind":"mc","stem":"반론으로 알맞은 말은 어느 것인가요?","options":[{"t":"「그 자료는 조사한 때가 나와 있지 않습니다.」","correct":true},{"t":"「그것도 모르십니까?」","mis":"K6-1-u3-X14"},{"t":"「그런 게 어디 있습니까?」","mis":"K6-1-u3-X14"},{"t":"「준비를 안 하셨군요.」","mis":"K6-1-u3-X14"}],"explanation":["모르냐고 묻는 말은 사람을 겨눠요.","깎아내리는 말도 마찬가지예요.","근거의 빈 곳을 짚어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#5','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C15',1,'ox','auto','판정은 어느 쪽이 더 큰 목소리로 말했는지로 정해요.',ARRAY['K6-1-u3-X16']::text[],false,'{"seq":5,"concept":"K6-1-u3-C15","difficulty":1,"kind":"ox","stem":"판정은 어느 쪽이 더 큰 목소리로 말했는지로 정해요.","answer":"X","reason_options":[{"t":"미리 밝힌 기준으로 어느 쪽이 더 설득력 있었는지 정하기 때문에","correct":true},{"t":"목소리가 크면 자신감이 있다는 뜻이기 때문에","mis":"K6-1-u3-X16"}],"mis":"K6-1-u3-X16","explanation":["목소리 크기는 기준이 아니에요.","기준을 먼저 밝혀요.","더 설득력 있게 말한 쪽을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#6','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C23',1,'mc','auto','양측 발언을 메모하며 듣고, 끝나면 잘한 곳을 짚어 주는 역할은 무엇인가요?',ARRAY['K6-1-u3-X25']::text[],false,'{"seq":6,"concept":"K6-1-u3-C23","difficulty":1,"kind":"mc","stem":"양측 발언을 메모하며 듣고, 끝나면 잘한 곳을 짚어 주는 역할은 무엇인가요?","options":[{"t":"청중","correct":true},{"t":"사회자","mis":"K6-1-u3-X25"},{"t":"판정단","mis":"K6-1-u3-X25"},{"t":"토론자","mis":"K6-1-u3-X25"}],"explanation":["사회자는 이끌어요.","판정단은 정해요.","듣고 짚어 주는 사람은 청중이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#7','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C26',1,'ox','auto','근거는 이유와 이어지는지, 출처가 분명한지, 구체적인지 따져 봐요.',ARRAY['K6-1-u3-X35']::text[],false,'{"seq":7,"concept":"K6-1-u3-C26","difficulty":1,"kind":"ox","stem":"근거는 이유와 이어지는지, 출처가 분명한지, 구체적인지 따져 봐요.","answer":"O","reason_options":[{"t":"세 물음 가운데 하나만 걸려도 근거가 흔들리기 때문에","correct":true},{"t":"숫자만 들어 있으면 따질 필요가 없기 때문에","mis":"K6-1-u3-X35"}],"mis":"K6-1-u3-X35","explanation":["세 물음을 한 번씩 던져요.","숫자만 보고 넘어가지 않아요.","전체적으로 타당한지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#8','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C43',1,'mc','auto','「젊다」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K6-1-u3-X44']::text[],false,'{"seq":8,"concept":"K6-1-u3-C43","difficulty":1,"kind":"mc","stem":"「젊다」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[점따]","correct":true},{"t":"[절따]","mis":"K6-1-u3-X44"},{"t":"[젊다]","mis":"K6-1-u3-X44"},{"t":"[저따]","mis":"K6-1-u3-X44"}],"explanation":["ㄻ 뒤에 ㄷ이 왔어요.","ㄻ은 [ㅁ]으로 소리 나요.","뒤의 ㄷ은 된소리가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#9','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C10',2,'mc','auto','서아가 든 근거의 문제로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X05','K6-1-u3-X30','K6-1-u3-X17']::text[],false,'{"seq":9,"concept":"K6-1-u3-C10","difficulty":2,"kind":"mc","stem":"서아가 든 근거의 문제로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"어느 누리집인지 밝히지 않아 확인할 수 없다","correct":true},{"t":"이유가 하나도 없다","mis":"K6-1-u3-X05"},{"t":"너무 구체적이다","mis":"K6-1-u3-X30"},{"t":"높임말을 썼다","mis":"K6-1-u3-X17"}],"explanation":["서아도 이유는 말했어요.","구체적인 것은 문제가 아니에요.","출처를 밝히지 않았어요."],"asset":{"type":"speech","turns":[{"who":"사회자 하람","text":"지금부터 「점심시간에도 학교 도서실을 열어야 한다」라는 주제로 토론을 시작하겠습니다. 찬성 측부터 주장을 펼쳐 주십시오."},{"who":"찬성 측 도담","text":"점심시간에도 도서실을 열어야 합니다. 쉬는 시간만으로는 책을 고를 시간이 모자라기 때문입니다. 도서부가 이번 학기에 고학년 이백 명에게 물어보니, 백삼십 명이 점심시간에 책을 빌리고 싶다고 답했습니다."},{"who":"반대 측 서아","text":"점심시간에는 도서실을 닫아야 합니다. 도서실을 지키는 분도 쉬는 시간이 있어야 하기 때문입니다. 어떤 누리집에서 봤는데 다른 학교도 다 닫는다고 합니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#10','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C12',2,'mc','auto','도담이의 답변이 알맞은 까닭은 무엇인가요?',ARRAY['K6-1-u3-X13','K6-1-u3-X14','K6-1-u3-X11']::text[],false,'{"seq":10,"concept":"K6-1-u3-C12","difficulty":2,"kind":"mc","stem":"도담이의 답변이 알맞은 까닭은 무엇인가요?","options":[{"t":"「다들 운동장에 나간다」는 말이 설문 자료와 맞지 않음을 밝혔기 때문에","correct":true},{"t":"같은 말을 되풀이했기 때문에","mis":"K6-1-u3-X13"},{"t":"서아의 말투를 문제 삼았기 때문에","mis":"K6-1-u3-X14"},{"t":"새로운 주제를 꺼냈기 때문에","mis":"K6-1-u3-X11"}],"explanation":["되풀이하지 않았어요.","말투를 겨누지 않았어요.","자료로 반론이 타당하지 않음을 밝혔어요."],"asset":{"type":"speech","turns":[{"who":"반대 측 서아","text":"그것도 모르십니까? 점심시간에는 다들 운동장에 나갑니다."},{"who":"찬성 측 도담","text":"말씀 잘 들었습니다. 다만 저희 설문에서 백삼십 명이 빌리고 싶다고 답했습니다. 다들 운동장에 나간다는 말은 저희 자료와 맞지 않습니다."},{"who":"찬성 측 도담","text":"반대 측께 묻겠습니다. 다른 학교도 다 닫는다는 누리집은 어디이고, 언제 쓴 글입니까?"},{"who":"반대 측 서아","text":"누리집 이름은 적어 두지 못했습니다. 그런데 저는 요즘 급식 줄이 더 문제라고 봅니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#11','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C14',2,'mc','auto','도담이의 주장 다지기가 알맞은 까닭은 무엇인가요?',ARRAY['K6-1-u3-X15','K6-1-u3-X14','K6-1-u3-X11']::text[],false,'{"seq":11,"concept":"K6-1-u3-C14","difficulty":2,"kind":"mc","stem":"도담이의 주장 다지기가 알맞은 까닭은 무엇인가요?","options":[{"t":"반론에서도 흔들리지 않은 설문을 추려 짧게 다시 세웠기 때문에","correct":true},{"t":"처음 한 말을 그대로 되풀이했기 때문에","mis":"K6-1-u3-X15"},{"t":"상대 말투를 짚었기 때문에","mis":"K6-1-u3-X14"},{"t":"새로운 주제를 꺼냈기 때문에","mis":"K6-1-u3-X11"}],"explanation":["되풀이가 아니에요.","말투를 겨누지 않았어요.","남은 것을 추려 다시 세웠어요."],"asset":{"type":"speech","turns":[{"who":"찬성 측 도담","text":"요컨대 책을 읽고 싶은 학생이 많습니다. 백삼십 명이라는 설문은 반론에서도 흔들리지 않았습니다. 따라서 점심시간에도 도서실을 열어야 합니다."},{"who":"반대 측 서아","text":"처음에 말씀드린 대로 다른 학교도 다 닫는다는 점을 다시 말씀드립니다. 다른 학교도 다 닫으니 우리도 닫아야 합니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#12','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C15',2,'mc','auto','나래의 판정이 알맞은 까닭은 무엇인가요?',ARRAY['K6-1-u3-X17','K6-1-u3-X24','K6-1-u3-X16']::text[],false,'{"seq":12,"concept":"K6-1-u3-C15","difficulty":2,"kind":"mc","stem":"나래의 판정이 알맞은 까닭은 무엇인가요?","options":[{"t":"미리 정한 기준을 밝히고 그 기준으로 정했으며 잘한 곳도 짚었기 때문에","correct":true},{"t":"찬성 측이 옳다고 가려 주었기 때문에","mis":"K6-1-u3-X17"},{"t":"평소 자기 생각을 말했기 때문에","mis":"K6-1-u3-X24"},{"t":"목소리가 큰 쪽을 골랐기 때문에","mis":"K6-1-u3-X16"}],"explanation":["옳고 그름을 가린 것이 아니에요.","평소 생각을 넣지 않았어요.","기준을 밝히고 정했어요."],"asset":{"type":"speech","turns":[{"who":"판정단 지우","text":"저는 원래 도서실을 열자는 생각이어서 찬성 측이 이겼다고 봅니다."},{"who":"판정단 나래","text":"저는 미리 정한 기준, 곧 근거가 믿을 만한가와 반론에 알맞게 답했는가로 보았습니다. 이 기준으로 찬성 측이 더 설득력 있었다고 판정합니다. 반대 측이 지키는 분의 쉬는 시간을 짚은 점은 좋았습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#13','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C27',2,'mc','auto','은솔이의 메모로 반대 측 근거를 겨누는 반론을 만든다면 무엇을 짚어야 하나요?',ARRAY['K6-1-u3-X14','K6-1-u3-X30','K6-1-u3-X17']::text[],false,'{"seq":13,"concept":"K6-1-u3-C27","difficulty":2,"kind":"mc","stem":"은솔이의 메모로 반대 측 근거를 겨누는 반론을 만든다면 무엇을 짚어야 하나요?","options":[{"t":"어느 누리집인지 밝히지 않아 확인할 수 없다는 점","correct":true},{"t":"반대 측 목소리가 컸다는 점","mis":"K6-1-u3-X14"},{"t":"반대 측 근거가 너무 구체적이라는 점","mis":"K6-1-u3-X30"},{"t":"반대 측이 높임말을 썼다는 점","mis":"K6-1-u3-X17"}],"explanation":["목소리는 사람을 겨눠요.","구체적인 것은 문제가 아니에요.","출처가 확인되지 않는 점을 짚어요."],"asset":{"type":"passage","lines":["찬성 측 주장 — 점심시간에도 도서실을 열어야 한다.","찬성 측 이유 — 쉬는 시간만으로는 책 고를 시간이 모자란다.","찬성 측 근거 — 도서부, 이번 학기, 고학년 이백 명 설문.","반대 측 근거 — 어떤 누리집(어디인지 밝히지 않음).","반대 측이 꺼낸 다른 이야기 — 급식 줄.","반대 측 말투 — 목소리가 컸음."],"title":"청중 은솔이의 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#14','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C21',2,'mc','auto','설문 조사로 근거를 마련하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X29','K6-1-u3-X33']::text[],false,'{"seq":14,"concept":"K6-1-u3-C21","difficulty":2,"kind":"mc","stem":"설문 조사로 근거를 마련하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"우리 반이나 학년에 직접 물어 수를 세고, 언제 몇 명에게 물었는지 적는다","correct":true},{"t":"친구 한두 명에게만 물어 모두의 생각이라고 쓴다","mis":"K6-1-u3-X29"},{"t":"물은 때와 사람 수는 적지 않는다","mis":"K6-1-u3-X29"},{"t":"내 생각과 같은 답만 골라 센다","mis":"K6-1-u3-X33"}],"explanation":["한두 명은 모두가 아니에요.","때와 사람 수를 적어요.","치우치지 않게 세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#15','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C32',2,'mc','auto','사회 문제 토론에서 「알려진 사실부터 함께 맞춰 본다」고 하는 까닭은 무엇인가요?',ARRAY['K6-1-u3-X01','K6-1-u3-X16','K6-1-u3-X36']::text[],false,'{"seq":15,"concept":"K6-1-u3-C32","difficulty":2,"kind":"mc","stem":"사회 문제 토론에서 「알려진 사실부터 함께 맞춰 본다」고 하는 까닭은 무엇인가요?","options":[{"t":"아는 것이 적으면 토론이 겉돌기 쉽기 때문에","correct":true},{"t":"사실을 맞추면 토론할 필요가 없어지기 때문에","mis":"K6-1-u3-X01"},{"t":"판정 결과를 미리 정하기 위해서","mis":"K6-1-u3-X16"},{"t":"사실은 토론에 필요 없기 때문에","mis":"K6-1-u3-X36"}],"explanation":["사실을 맞춰도 생각은 갈려요.","판정은 토론 뒤에 해요.","사실을 알아야 겉돌지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#16','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C30',2,'mc','auto','근거 자료로 가장 믿을 만한 것은 어느 것인가요?',ARRAY['K6-1-u3-X33','K6-1-u3-X27']::text[],false,'{"seq":16,"concept":"K6-1-u3-C30","difficulty":2,"kind":"mc","stem":"근거 자료로 가장 믿을 만한 것은 어느 것인가요?","options":[{"t":"우리 시가 올해 낸, 주제와 직접 이어지는 조사 자료","correct":true},{"t":"물건을 팔려는 회사가 쓴 광고 글","mis":"K6-1-u3-X33"},{"t":"아주 오래전에 나온 자료","mis":"K6-1-u3-X33"},{"t":"주제와 비슷해 보이는 다른 나라 이야기","mis":"K6-1-u3-X27"}],"explanation":["광고 글은 치우쳐요.","오래된 자료는 지금과 다를 수 있어요.","공신력 · 최근 · 직접 이어짐을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#17','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C5',3,'error','auto','토론의 단계를 설명했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u3-X06','K6-1-u3-X05','K6-1-u3-X16']::text[],false,'{"seq":17,"concept":"K6-1-u3-C5","difficulty":3,"kind":"error","stem":"토론의 단계를 설명했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"도겸 — 「주장 다지기에서는 상대 근거의 허점을 처음으로 짚어.」","correct":true,"mis_target":"K6-1-u3-X06"},{"t":"하윤 — 「주장 펼치기에서는 주장 · 이유 · 근거를 함께 내.」","mis":"K6-1-u3-X05"},{"t":"지안 — 「판정하기에서는 판정단이 기준을 밝혀.」","mis":"K6-1-u3-X16"}],"explanation":["하윤은 펼치기를 바르게 말했어요.","지안은 판정하기를 바르게 말했어요.","허점을 짚는 것은 반론하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#18','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C26',3,'mc','auto','사물함 토론에서 온유의 근거가 타당한 까닭을 바르게 말한 것은 어느 것인가요?',ARRAY['K6-1-u3-X35','K6-1-u3-X31','K6-1-u3-X17']::text[],false,'{"seq":18,"concept":"K6-1-u3-C26","difficulty":3,"kind":"mc","stem":"사물함 토론에서 온유의 근거가 타당한 까닭을 바르게 말한 것은 어느 것인가요?","options":[{"t":"물건을 잃는 일이 있다는 이유와 이어지고, 지난달 · 백쉰 명이라는 조사가 밝혀져 있다","correct":true},{"t":"숫자가 크니 따져 볼 필요가 없다","mis":"K6-1-u3-X35"},{"t":"설문은 근거가 될 수 없다","mis":"K6-1-u3-X31"},{"t":"찬성 측이니 맞다","mis":"K6-1-u3-X17"}],"explanation":["숫자만 보지 않아요.","설문도 근거가 돼요.","이유와 이어지고 구체적이에요."],"asset":{"type":"passage","lines":["토론 주제 — 우리 반 사물함에 자물쇠를 달아야 한다.","찬성 측 온유 — 물건을 잃어버리는 일이 실제로 있기 때문입니다.","우리 학교 고학년 백쉰 명에게 지난달에 물어보니,","마흔여덟 명이 사물함에서 물건을 잃은 적이 있다고 답했습니다.","반대 측 새얀 — 열고 닫기가 번거롭기 때문입니다.","제 친구 두 명에게 물어보니 둘 다 불편할 것 같다고 했습니다."],"title":"두 근거 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#19','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C13',3,'mc','auto','반론할 때 높임말을 쓰고 공격적인 말투를 피하는 까닭은 무엇인가요?',ARRAY['K6-1-u3-X09','K6-1-u3-X16','K6-1-u3-X14']::text[],false,'{"seq":19,"concept":"K6-1-u3-C13","difficulty":3,"kind":"mc","stem":"반론할 때 높임말을 쓰고 공격적인 말투를 피하는 까닭은 무엇인가요?","options":[{"t":"토론은 공식적인 말하기이고, 말투가 거칠어지면 근거가 아니라 사람을 겨누게 되기 때문에","correct":true},{"t":"높임말을 쓰면 무조건 이기기 때문에","mis":"K6-1-u3-X09"},{"t":"판정단이 말투만 보기 때문에","mis":"K6-1-u3-X16"},{"t":"높임말을 쓰면 상대에게 지는 것이기 때문에","mis":"K6-1-u3-X14"}],"explanation":["이기려고 쓰는 것이 아니에요.","판정단은 기준을 봐요.","공식적인 말하기라 존중해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#20','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C41',3,'mc','auto','은솔이의 말이 토론 뒤 나눌 이야기로 알맞은 까닭은 무엇인가요?',ARRAY['K6-1-u3-X40','K6-1-u3-X18']::text[],false,'{"seq":20,"concept":"K6-1-u3-C41","difficulty":3,"kind":"mc","stem":"은솔이의 말이 토론 뒤 나눌 이야기로 알맞은 까닭은 무엇인가요?","options":[{"t":"새롭게 안 사실과 다른 역할을 맡은 친구의 잘한 점을 말했기 때문에","correct":true},{"t":"승패를 분명히 말했기 때문에","mis":"K6-1-u3-X40"},{"t":"판정 결과를 바꾸자고 했기 때문에","mis":"K6-1-u3-X18"},{"t":"상대의 준비 부족을 짚었기 때문에","mis":"K6-1-u3-X40"}],"explanation":["은솔이는 승패를 말하지 않았어요.","판정을 바꾸자고 하지 않았어요.","새로 안 것과 잘한 친구를 말했어요."],"asset":{"type":"speech","turns":[{"who":"서아","text":"판정이 이상해. 우리가 진 건 판정단 탓이야."},{"who":"은솔","text":"나는 도서부 설문 자료를 처음 알았어. 사회를 맡은 하람이가 말차례를 잘 지켜 줬어."},{"who":"도담","text":"반대 측이 말한 지키는 분의 쉬는 시간은 미처 생각 못 했어. 도서부가 돌아가며 돕는 방법을 찾아봐야겠어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#21','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C38',3,'mc','auto','모둠이 모은 근거 가운데 준비표에 옮길 것을 고르는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X43','K6-1-u3-X30','K6-1-u3-X22']::text[],false,'{"seq":21,"concept":"K6-1-u3-C38","difficulty":3,"kind":"mc","stem":"모둠이 모은 근거 가운데 준비표에 옮길 것을 고르는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"같은 편끼리 바꾸어 읽고 세 물음을 던져 가장 센 두 가지만 고른다","correct":true},{"t":"모은 것을 하나도 빼지 않고 모두 옮긴다","mis":"K6-1-u3-X43"},{"t":"가장 긴 자료부터 옮긴다","mis":"K6-1-u3-X30"},{"t":"출처를 지우고 내용만 옮긴다","mis":"K6-1-u3-X22"}],"explanation":["약한 것까지 옮기면 흔들려요.","길이로 고르지 않아요.","세 물음으로 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#22','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C43',3,'mc','auto','「묽고」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K6-1-u3-X44']::text[],false,'{"seq":22,"concept":"K6-1-u3-C43","difficulty":3,"kind":"mc","stem":"「묽고」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[물꼬]","correct":true},{"t":"[묵꼬]","mis":"K6-1-u3-X44"},{"t":"[물고]","mis":"K6-1-u3-X44"},{"t":"[묽고]","mis":"K6-1-u3-X44"}],"explanation":["ㄺ 뒤에 ㄱ이 왔어요.","이때는 [ㄹ]로 소리 나요.","뒤의 ㄱ은 된소리가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#23','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C16',4,'mc','auto','두 판정단의 판정을 견주어 평가한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X17','K6-1-u3-X24','K6-1-u3-X16']::text[],false,'{"seq":23,"concept":"K6-1-u3-C16","difficulty":4,"kind":"mc","stem":"두 판정단의 판정을 견주어 평가한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"나래는 기준을 밝히고 토론에 나온 내용으로 정해 알맞고, 지우는 기준 없이 평소 생각으로 정해 알맞지 않다","correct":true},{"t":"두 사람 모두 찬성 측을 골랐으니 똑같이 알맞다","mis":"K6-1-u3-X17"},{"t":"지우가 솔직하게 자기 생각을 말해 더 알맞다","mis":"K6-1-u3-X24"},{"t":"판정은 누가 해도 결과가 같으니 따질 필요가 없다","mis":"K6-1-u3-X16"}],"explanation":["고른 편이 같아도 방법이 달라요.","평소 생각을 넣으면 안 돼요.","기준을 밝혔는지 봐요."],"asset":{"type":"speech","turns":[{"who":"판정단 지우","text":"저는 원래 도서실을 열자는 생각이어서 찬성 측이 이겼다고 봅니다."},{"who":"판정단 나래","text":"저는 미리 정한 기준, 곧 근거가 믿을 만한가와 반론에 알맞게 답했는가로 보았습니다. 이 기준으로 찬성 측이 더 설득력 있었다고 판정합니다. 반대 측이 지키는 분의 쉬는 시간을 짚은 점은 좋았습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#24','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C33',4,'essay','teacher','지우와 나래의 판정을 견주어 어느 판정이 알맞은지 까닭과 함께 쓰고, 판정단이 지켜야 할 점을 두 가지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u3-C33","difficulty":4,"kind":"essay","stem":"지우와 나래의 판정을 견주어 어느 판정이 알맞은지 까닭과 함께 쓰고, 판정단이 지켜야 할 점을 두 가지 쓰세요.","answer_guide":{"answer":"예: 나래의 판정이 알맞다. 나래는 근거가 믿을 만한가와 반론에 알맞게 답했는가라는 기준을 먼저 밝히고, 그 기준으로 찬성 측이 더 설득력 있었다고 정했으며 반대 측이 잘한 곳도 짚었다. 지우는 기준 없이 원래 자기 생각과 같은 편을 골랐다. 판정단은 첫째, 판정 기준을 미리 정해 밝혀야 하고, 둘째, 자기 생각과 같은 편에 후하게 주지 않고 토론에서 나온 말과 자료만으로 판정해야 한다.","scoring_points":["알맞은 판정을 고르고 까닭을 썼는가","알맞지 않은 판정의 문제를 썼는가","판정단이 지킬 점 두 가지를 썼는가"]},"explanation":["두 판정을 견줘요.","기준을 밝혔는지 봐요.","공정함을 떠올려요."],"asset":{"type":"speech","turns":[{"who":"판정단 지우","text":"저는 원래 도서실을 열자는 생각이어서 찬성 측이 이겼다고 봅니다."},{"who":"판정단 나래","text":"저는 미리 정한 기준, 곧 근거가 믿을 만한가와 반론에 알맞게 답했는가로 보았습니다. 이 기준으로 찬성 측이 더 설득력 있었다고 판정합니다. 반대 측이 지키는 분의 쉬는 시간을 짚은 점은 좋았습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#25','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C7',4,'essay','teacher','「토론은 겨루는 방식이지만 목적은 이기는 것이 아니다」라는 말을 설명하고, 이 단원에서 배운 태도 두 가지와 이어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u3-C7","difficulty":4,"kind":"essay","stem":"「토론은 겨루는 방식이지만 목적은 이기는 것이 아니다」라는 말을 설명하고, 이 단원에서 배운 태도 두 가지와 이어 쓰세요.","answer_guide":{"answer":"예: 토론은 찬성과 반대로 나뉘어 겨루는 말하기이지만, 그렇게 겨루는 까닭은 더 합리적인 결정에 이르기 위해서이다. 그래서 상대를 누르려고 사람을 겨누지 않고 근거를 겨누어 반론해야 한다. 또 판정 결과에 승복하고, 토론 뒤에 생각이 바뀌는 것을 부끄러워하지 않으며 새로 알게 된 것을 나눈다.","scoring_points":["겨루는 방식과 목적을 구별해 설명했는가","근거를 겨누는 태도를 썼는가","승복하거나 생각을 나누는 태도를 썼는가"]},"explanation":["방식과 목적을 갈라요.","반론하는 태도를 떠올려요.","판정 뒤의 태도를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#1','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C2',1,'mc','auto','「우리 반 학급 문고에 어떤 책을 들일지 의견 모으기」는 토의와 토론 가운데 무엇인가요?',ARRAY['K6-1-u3-X02','K6-1-u3-X06']::text[],false,'{"seq":1,"concept":"K6-1-u3-C2","difficulty":1,"kind":"mc","stem":"「우리 반 학급 문고에 어떤 책을 들일지 의견 모으기」는 토의와 토론 가운데 무엇인가요?","options":[{"t":"토의","correct":true},{"t":"토론","mis":"K6-1-u3-X02"},{"t":"판정","mis":"K6-1-u3-X06"},{"t":"반론","mis":"K6-1-u3-X06"}],"explanation":["편이 갈리지 않아요.","판정 · 반론은 토론의 단계예요.","함께 방법을 모으니 토의예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#2','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C4',1,'ox','auto','이유는 밖에서 가져온 자료이고, 근거는 내 머릿속에서 나온 까닭이에요.',ARRAY['K6-1-u3-X04']::text[],false,'{"seq":2,"concept":"K6-1-u3-C4","difficulty":1,"kind":"ox","stem":"이유는 밖에서 가져온 자료이고, 근거는 내 머릿속에서 나온 까닭이에요.","answer":"X","reason_options":[{"t":"이유는 내가 생각한 까닭이고 근거는 밖에서 가져와 확인할 수 있는 자료이기 때문에","correct":true},{"t":"이유와 근거는 같은 말이기 때문에","mis":"K6-1-u3-X04"}],"mis":"K6-1-u3-X04","explanation":["두 말이 뒤바뀌었어요.","이유는 내 까닭이에요.","근거는 밖의 자료예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#3','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C14',1,'mc','auto','자기편 주장을 정리해 다시 힘주어 말하는 단계는 무엇인가요?',ARRAY['K6-1-u3-X06']::text[],false,'{"seq":3,"concept":"K6-1-u3-C14","difficulty":1,"kind":"mc","stem":"자기편 주장을 정리해 다시 힘주어 말하는 단계는 무엇인가요?","options":[{"t":"주장 다지기","correct":true},{"t":"주장 펼치기","mis":"K6-1-u3-X06"},{"t":"반론하기","mis":"K6-1-u3-X06"},{"t":"판정하기","mis":"K6-1-u3-X06"}],"explanation":["펼치기는 처음 내놓는 단계예요.","반론은 되받는 단계예요.","다시 세우는 단계는 주장 다지기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#4','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C11',1,'mc','auto','상대의 주장에 맞서서 반대되는 자기 주장을 밝히는 말하기를 무엇이라고 하나요?',ARRAY['K6-1-u3-X06','K6-1-u3-X02']::text[],false,'{"seq":4,"concept":"K6-1-u3-C11","difficulty":1,"kind":"mc","stem":"상대의 주장에 맞서서 반대되는 자기 주장을 밝히는 말하기를 무엇이라고 하나요?","options":[{"t":"반론","correct":true},{"t":"판정","mis":"K6-1-u3-X06"},{"t":"주장 다지기","mis":"K6-1-u3-X06"},{"t":"토의","mis":"K6-1-u3-X02"}],"explanation":["판정은 판정단이 해요.","다지기는 자기편을 다시 세워요.","맞서서 되받는 것이 반론이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#5','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C16',1,'ox','auto','토론자는 판정 결과에 승복하는 태도를 지녀요.',ARRAY['K6-1-u3-X18']::text[],false,'{"seq":5,"concept":"K6-1-u3-C16","difficulty":1,"kind":"ox","stem":"토론자는 판정 결과에 승복하는 태도를 지녀요.","answer":"O","reason_options":[{"t":"판정은 정한 기준으로 공정하게 낸 결과이기 때문에","correct":true},{"t":"판정은 늘 틀리기 때문에","mis":"K6-1-u3-X18"}],"mis":"K6-1-u3-X18","explanation":["판정은 기준으로 정해요.","결과가 마음에 안 들 수 있어요.","그래도 승복해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#6','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C23',1,'ox','auto','청중은 토론에서 할 일이 없어요.',ARRAY['K6-1-u3-X37']::text[],false,'{"seq":6,"concept":"K6-1-u3-C23","difficulty":1,"kind":"ox","stem":"청중은 토론에서 할 일이 없어요.","answer":"X","reason_options":[{"t":"메모하며 듣고 인상 깊은 근거를 말하는 할 일이 있기 때문에","correct":true},{"t":"토론자만 말하기 때문에","mis":"K6-1-u3-X37"}],"mis":"K6-1-u3-X37","explanation":["청중이 가장 많아요.","청중에게도 할 일이 있어요.","메모하고 짚어 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#7','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C28',1,'ox','auto','자료 하나라도 언제 · 누구를 · 어떻게 조사했는지 자세하면 충분할 수 있어요.',ARRAY['K6-1-u3-X30']::text[],false,'{"seq":7,"concept":"K6-1-u3-C28","difficulty":1,"kind":"ox","stem":"자료 하나라도 언제 · 누구를 · 어떻게 조사했는지 자세하면 충분할 수 있어요.","answer":"O","reason_options":[{"t":"충분성은 자료의 개수가 아니라 구체적인 정도이기 때문에","correct":true},{"t":"자료는 개수가 많아야만 충분하기 때문에","mis":"K6-1-u3-X30"}],"mis":"K6-1-u3-X30","explanation":["개수가 많다고 충분한 것이 아니에요.","자세한지가 중요해요.","하나라도 자세하면 충분할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#8','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C43',1,'mc','auto','「닮다」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K6-1-u3-X44']::text[],false,'{"seq":8,"concept":"K6-1-u3-C43","difficulty":1,"kind":"mc","stem":"「닮다」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[담따]","correct":true},{"t":"[달따]","mis":"K6-1-u3-X44"},{"t":"[닮다]","mis":"K6-1-u3-X44"},{"t":"[다따]","mis":"K6-1-u3-X44"}],"explanation":["ㄻ 뒤에 ㄷ이 왔어요.","ㄻ은 [ㅁ]으로 소리 나요.","뒤의 ㄷ은 된소리가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#9','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C9',2,'mc','auto','서아의 주장 펼치기에서 이유에 해당하는 것은 어느 것인가요?',ARRAY['K6-1-u3-X05','K6-1-u3-X04']::text[],false,'{"seq":9,"concept":"K6-1-u3-C9","difficulty":2,"kind":"mc","stem":"서아의 주장 펼치기에서 이유에 해당하는 것은 어느 것인가요?","options":[{"t":"도서실을 지키는 분도 쉬는 시간이 있어야 하기 때문","correct":true},{"t":"점심시간에는 도서실을 닫아야 한다","mis":"K6-1-u3-X05"},{"t":"어떤 누리집에서 봤는데 다른 학교도 다 닫는다","mis":"K6-1-u3-X04"},{"t":"도서부가 고학년 이백 명에게 물은 설문","mis":"K6-1-u3-X04"}],"explanation":["닫아야 한다는 것은 주장이에요.","누리집 이야기는 근거로 든 것이에요.","그렇게 주장하는 까닭이 이유예요."],"asset":{"type":"speech","turns":[{"who":"사회자 하람","text":"지금부터 「점심시간에도 학교 도서실을 열어야 한다」라는 주제로 토론을 시작하겠습니다. 찬성 측부터 주장을 펼쳐 주십시오."},{"who":"찬성 측 도담","text":"점심시간에도 도서실을 열어야 합니다. 쉬는 시간만으로는 책을 고를 시간이 모자라기 때문입니다. 도서부가 이번 학기에 고학년 이백 명에게 물어보니, 백삼십 명이 점심시간에 책을 빌리고 싶다고 답했습니다."},{"who":"반대 측 서아","text":"점심시간에는 도서실을 닫아야 합니다. 도서실을 지키는 분도 쉬는 시간이 있어야 하기 때문입니다. 어떤 누리집에서 봤는데 다른 학교도 다 닫는다고 합니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#10','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C11',2,'mc','auto','서아의 마지막 말 「저는 요즘 급식 줄이 더 문제라고 봅니다.」의 문제는 무엇인가요?',ARRAY['K6-1-u3-X30','K6-1-u3-X17','K6-1-u3-X13']::text[],false,'{"seq":10,"concept":"K6-1-u3-C11","difficulty":2,"kind":"mc","stem":"서아의 마지막 말 「저는 요즘 급식 줄이 더 문제라고 봅니다.」의 문제는 무엇인가요?","options":[{"t":"주장 펼치기에서 나온 내용과 상관없는 새 이야기를 꺼냈다","correct":true},{"t":"근거를 너무 자세히 밝혔다","mis":"K6-1-u3-X30"},{"t":"높임말을 썼다","mis":"K6-1-u3-X17"},{"t":"상대 근거를 겨누었다","mis":"K6-1-u3-X13"}],"explanation":["근거를 밝히지도 않았어요.","높임말은 맞아요.","주제와 상관없는 말이에요."],"asset":{"type":"speech","turns":[{"who":"반대 측 서아","text":"그것도 모르십니까? 점심시간에는 다들 운동장에 나갑니다."},{"who":"찬성 측 도담","text":"말씀 잘 들었습니다. 다만 저희 설문에서 백삼십 명이 빌리고 싶다고 답했습니다. 다들 운동장에 나간다는 말은 저희 자료와 맞지 않습니다."},{"who":"찬성 측 도담","text":"반대 측께 묻겠습니다. 다른 학교도 다 닫는다는 누리집은 어디이고, 언제 쓴 글입니까?"},{"who":"반대 측 서아","text":"누리집 이름은 적어 두지 못했습니다. 그런데 저는 요즘 급식 줄이 더 문제라고 봅니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#11','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C14',2,'ox','auto','주장 다지기에서는 무너진 근거도 다시 꺼내 힘주어 말해야 해요.',ARRAY['K6-1-u3-X15']::text[],false,'{"seq":11,"concept":"K6-1-u3-C14","difficulty":2,"kind":"ox","stem":"주장 다지기에서는 무너진 근거도 다시 꺼내 힘주어 말해야 해요.","answer":"X","reason_options":[{"t":"반론에서 확인된 것만 골라야 하고 무너진 근거를 꺼내면 오히려 약해지기 때문에","correct":true},{"t":"한 번 낸 근거는 끝까지 지켜야 하기 때문에","mis":"K6-1-u3-X15"}],"mis":"K6-1-u3-X15","explanation":["무너진 근거는 힘이 없어요.","확인된 것만 골라요.","추려서 다시 세워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#12','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C16',2,'ox','auto','나래의 판정은 도서실을 열자는 생각이 옳다는 뜻이에요.',ARRAY['K6-1-u3-X17']::text[],false,'{"seq":12,"concept":"K6-1-u3-C16","difficulty":2,"kind":"ox","stem":"나래의 판정은 도서실을 열자는 생각이 옳다는 뜻이에요.","answer":"X","reason_options":[{"t":"정한 기준으로 보아 찬성 측이 더 설득력 있게 말했다는 뜻이기 때문에","correct":true},{"t":"판정은 옳은 생각을 가려 주는 일이기 때문에","mis":"K6-1-u3-X17"}],"mis":"K6-1-u3-X17","explanation":["판정은 옳고 그름을 가리지 않아요.","기준으로 본 설득력이에요.","두 생각은 그대로 남아요."],"asset":{"type":"speech","turns":[{"who":"판정단 지우","text":"저는 원래 도서실을 열자는 생각이어서 찬성 측이 이겼다고 봅니다."},{"who":"판정단 나래","text":"저는 미리 정한 기준, 곧 근거가 믿을 만한가와 반론에 알맞게 답했는가로 보았습니다. 이 기준으로 찬성 측이 더 설득력 있었다고 판정합니다. 반대 측이 지키는 분의 쉬는 시간을 짚은 점은 좋았습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#13','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C34',2,'ox','auto','은솔이처럼 발언을 그대로 옮기지 않고 핵심만 짧게 적는 것이 좋아요.',ARRAY['K6-1-u3-X08']::text[],false,'{"seq":13,"concept":"K6-1-u3-C34","difficulty":2,"kind":"ox","stem":"은솔이처럼 발언을 그대로 옮기지 않고 핵심만 짧게 적는 것이 좋아요.","answer":"O","reason_options":[{"t":"다음 말을 놓치지 않고 되받을 거리를 남길 수 있기 때문에","correct":true},{"t":"상대 말은 들을 필요가 없기 때문에","mis":"K6-1-u3-X08"}],"mis":"K6-1-u3-X08","explanation":["다 옮기면 다음 말을 놓쳐요.","상대 말은 잘 들어야 해요.","핵심만 짧게 적어요."],"asset":{"type":"passage","lines":["찬성 측 주장 — 점심시간에도 도서실을 열어야 한다.","찬성 측 이유 — 쉬는 시간만으로는 책 고를 시간이 모자란다.","찬성 측 근거 — 도서부, 이번 학기, 고학년 이백 명 설문.","반대 측 근거 — 어떤 누리집(어디인지 밝히지 않음).","반대 측이 꺼낸 다른 이야기 — 급식 줄.","반대 측 말투 — 목소리가 컸음."],"title":"청중 은솔이의 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#14','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C20',2,'mc','auto','토론 준비표에 쓸 차례로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X06','K6-1-u3-X21']::text[],false,'{"seq":14,"concept":"K6-1-u3-C20","difficulty":2,"kind":"mc","stem":"토론 준비표에 쓸 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"주장 → 이유 → 이유마다 근거 → 예상 반론과 답변","correct":true},{"t":"근거 → 판정 → 주장","mis":"K6-1-u3-X06"},{"t":"예상 반론 → 주장 → 판정","mis":"K6-1-u3-X06"},{"t":"주장 → 이유 하나 → 끝","mis":"K6-1-u3-X21"}],"explanation":["판정은 준비표에 쓰지 않아요.","이유는 두세 가지, 근거와 반론까지 준비해요.","주장 아래 이유, 이유 아래 근거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#15','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C37',2,'mc','auto','실천 토론에서 주제를 찾을 수 있는 갈래로 알맞게 짝 지은 것은 어느 것인가요?',ARRAY['K6-1-u3-X01','K6-1-u3-X06','K6-1-u3-X25']::text[],false,'{"seq":15,"concept":"K6-1-u3-C37","difficulty":2,"kind":"mc","stem":"실천 토론에서 주제를 찾을 수 있는 갈래로 알맞게 짝 지은 것은 어느 것인가요?","options":[{"t":"역사 · 환경 · 생활","correct":true},{"t":"연도 · 이름 · 길이","mis":"K6-1-u3-X01"},{"t":"판정 · 반론 · 다지기","mis":"K6-1-u3-X06"},{"t":"사회자 · 청중 · 판정단","mis":"K6-1-u3-X25"}],"explanation":["연도나 이름은 답이 하나예요.","그것은 토론의 단계예요.","역사 · 환경 · 생활에서 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#16','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C39',2,'mc','auto','원탁 토론과 찬반 토론의 같은 점은 무엇인가요?',ARRAY['K6-1-u3-X41']::text[],false,'{"seq":16,"concept":"K6-1-u3-C39","difficulty":2,"kind":"mc","stem":"원탁 토론과 찬반 토론의 같은 점은 무엇인가요?","options":[{"t":"두 토론 모두 근거를 들어 말한다","correct":true},{"t":"두 토론 모두 판정단이 승패를 정한다","mis":"K6-1-u3-X41"},{"t":"두 토론 모두 편을 나눈다","mis":"K6-1-u3-X41"},{"t":"두 토론 모두 사회자가 반드시 있다","mis":"K6-1-u3-X41"}],"explanation":["원탁 토론은 판정단을 두지 않아요.","원탁 토론은 편을 나누지 않아요.","근거를 들어 말하는 점은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#17','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C24',3,'mc','auto','같은 편끼리 반론과 답변을 맞춰 두려고 단계 사이에 두는 시간을 무엇이라고 하나요?',ARRAY['K6-1-u3-X06','K6-1-u3-X23']::text[],false,'{"seq":17,"concept":"K6-1-u3-C24","difficulty":3,"kind":"mc","stem":"같은 편끼리 반론과 답변을 맞춰 두려고 단계 사이에 두는 시간을 무엇이라고 하나요?","options":[{"t":"협의 시간","correct":true},{"t":"판정 시간","mis":"K6-1-u3-X06"},{"t":"반론 시간","mis":"K6-1-u3-X06"},{"t":"쉬는 시간","mis":"K6-1-u3-X23"}],"explanation":["판정은 끝에 해요.","반론은 단계 이름이에요.","같은 편끼리 맞추는 시간이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#18','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C26',3,'error','auto','사물함 토론의 두 근거를 견주었어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u3-X35','K6-1-u3-X30','K6-1-u3-X29']::text[],false,'{"seq":18,"concept":"K6-1-u3-C26","difficulty":3,"kind":"error","stem":"사물함 토론의 두 근거를 견주었어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"보미 — 「두 근거 모두 사람에게 물었으니 똑같이 타당해.」","correct":true,"mis_target":"K6-1-u3-X35"},{"t":"지호 — 「백쉰 명과 두 명은 같은 무게가 아니야.」","mis":"K6-1-u3-X30"},{"t":"은재 — 「새얀이는 언제 물었는지도 밝히지 않았어.」","mis":"K6-1-u3-X29"}],"explanation":["지호는 사람 수를 바르게 견주었어요.","은재는 때를 바르게 짚었어요.","물은 방법이 같아도 구체성이 달라요."],"asset":{"type":"passage","lines":["토론 주제 — 우리 반 사물함에 자물쇠를 달아야 한다.","찬성 측 온유 — 물건을 잃어버리는 일이 실제로 있기 때문입니다.","우리 학교 고학년 백쉰 명에게 지난달에 물어보니,","마흔여덟 명이 사물함에서 물건을 잃은 적이 있다고 답했습니다.","반대 측 새얀 — 열고 닫기가 번거롭기 때문입니다.","제 친구 두 명에게 물어보니 둘 다 불편할 것 같다고 했습니다."],"title":"두 근거 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#19','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C11',3,'mc','auto','반론할 때 되받을 수 있는 범위로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X11','K6-1-u3-X14']::text[],false,'{"seq":19,"concept":"K6-1-u3-C11","difficulty":3,"kind":"mc","stem":"반론할 때 되받을 수 있는 범위로 알맞은 것은 어느 것인가요?","options":[{"t":"상대가 주장 펼치기에서 낸 주장 · 이유 · 근거","correct":true},{"t":"토론과 상관없는 요즘 일","mis":"K6-1-u3-X11"},{"t":"상대의 말투와 표정","mis":"K6-1-u3-X14"},{"t":"상대가 지난번 다른 토론에서 한 말","mis":"K6-1-u3-X11"}],"explanation":["상관없는 일은 꺼내지 않아요.","말투는 겨누지 않아요.","펼친 내용에 대해서만 되받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#20','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C33',3,'error','auto','판정단의 마음가짐을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u3-X24','K6-1-u3-X16']::text[],false,'{"seq":20,"concept":"K6-1-u3-C33","difficulty":3,"kind":"error","stem":"판정단의 마음가짐을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"지우 — 「나는 원래 찬성이니까 찬성 측에 점수를 더 줄 거야.」","correct":true,"mis_target":"K6-1-u3-X24"},{"t":"나래 — 「미리 정한 기준을 적어 두고 판정할게.」","mis":"K6-1-u3-X16"},{"t":"하람 — 「토론에서 나온 말과 자료만 볼게.」","mis":"K6-1-u3-X24"}],"explanation":["나래는 기준을 먼저 정했어요.","하람은 나온 내용만 봐요.","지우는 같은 편에 후하게 주려 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#21','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C39',3,'mc','auto','「우리 마을 하천을 어떻게 가꿀까」처럼 여러 생각을 모아야 하는 문제를 이야기할 때 알맞은 토론은 어느 것인가요?',ARRAY['K6-1-u3-X41','K6-1-u3-X03']::text[],false,'{"seq":21,"concept":"K6-1-u3-C39","difficulty":3,"kind":"mc","stem":"「우리 마을 하천을 어떻게 가꿀까」처럼 여러 생각을 모아야 하는 문제를 이야기할 때 알맞은 토론은 어느 것인가요?","options":[{"t":"모두가 대등하게 돌아가며 말하는 원탁 토론","correct":true},{"t":"찬성과 반대로 나뉘는 찬반 토론","mis":"K6-1-u3-X41"},{"t":"판정단이 승패를 정하는 토론","mis":"K6-1-u3-X41"},{"t":"한 사람만 말하는 연설","mis":"K6-1-u3-X03"}],"explanation":["둘로 갈리지 않는 문제예요.","승패를 정할 문제가 아니에요.","모두가 대등하게 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#22','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C43',3,'error','auto','세 친구가 겹받침이 든 말을 읽었어요. 바르지 않게 읽은 친구는 누구인가요?',ARRAY['K6-1-u3-X44']::text[],false,'{"seq":22,"concept":"K6-1-u3-C43","difficulty":3,"kind":"error","stem":"세 친구가 겹받침이 든 말을 읽었어요. 바르지 않게 읽은 친구는 누구인가요?","options":[{"t":"이안 — 「붉게」를 [북께]로 읽었다","correct":true,"mis_target":"K6-1-u3-X44"},{"t":"서아 — 「늙지」를 [늑찌]로 읽었다","mis":"K6-1-u3-X44"},{"t":"도담 — 「닮고」를 [담꼬]로 읽었다","mis":"K6-1-u3-X44"}],"explanation":["서아는 ㄺ을 [ㄱ]으로 읽었어요.","도담은 ㄻ을 [ㅁ]으로 읽었어요.","ㄺ 뒤에 ㄱ이 오면 [ㄹ] — [불께]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#23','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C14',4,'mc','auto','서아의 주장 다지기를 가장 알맞게 고친 것은 어느 것인가요?',ARRAY['K6-1-u3-X15','K6-1-u3-X14','K6-1-u3-X11']::text[],false,'{"seq":23,"concept":"K6-1-u3-C14","difficulty":4,"kind":"mc","stem":"서아의 주장 다지기를 가장 알맞게 고친 것은 어느 것인가요?","options":[{"t":"「요컨대 저희가 지키려는 것은 지키는 분의 쉬는 시간입니다. 그 시간을 지킬 방법이 없다면 점심시간에는 닫아야 합니다.」","correct":true},{"t":"「다른 학교도 다 닫으니 우리도 닫아야 합니다.」를 두 번 말한다","mis":"K6-1-u3-X15"},{"t":"「찬성 측은 준비가 부족했습니다.」라고 말한다","mis":"K6-1-u3-X14"},{"t":"「그런데 급식 줄도 문제입니다.」를 덧붙인다","mis":"K6-1-u3-X11"}],"explanation":["무너진 근거를 되풀이하지 않아요.","상대를 깎아내리지 않아요.","남은 이유로 다시 세워요."],"asset":{"type":"speech","turns":[{"who":"찬성 측 도담","text":"요컨대 책을 읽고 싶은 학생이 많습니다. 백삼십 명이라는 설문은 반론에서도 흔들리지 않았습니다. 따라서 점심시간에도 도서실을 열어야 합니다."},{"who":"반대 측 서아","text":"처음에 말씀드린 대로 다른 학교도 다 닫는다는 점을 다시 말씀드립니다. 다른 학교도 다 닫으니 우리도 닫아야 합니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#24','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C26',4,'essay','teacher','도담이와 서아가 든 근거를 세 물음으로 따져 보고, 어느 쪽 근거가 더 타당한지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u3-C26","difficulty":4,"kind":"essay","stem":"도담이와 서아가 든 근거를 세 물음으로 따져 보고, 어느 쪽 근거가 더 타당한지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 도담이의 근거는 책을 고를 시간이 모자란다는 이유와 이어지고, 도서부라는 출처가 분명하며, 이번 학기 · 고학년 이백 명이라는 조사 대상이 밝혀져 있다. 서아의 근거는 다른 학교도 다 닫는다는 것인데, 어느 누리집인지 몰라 출처가 분명하지 않고, 지키는 분의 쉬는 시간이라는 이유와도 곧바로 이어지지 않는다. 그래서 도담이의 근거가 더 타당하다.","scoring_points":["도담이의 근거를 세 물음으로 따졌는가","서아의 근거를 세 물음으로 따졌는가","더 타당한 쪽과 까닭을 썼는가"]},"explanation":["이어지는지 따져요.","출처를 따져요.","구체적인지 따져요."],"asset":{"type":"speech","turns":[{"who":"사회자 하람","text":"지금부터 「점심시간에도 학교 도서실을 열어야 한다」라는 주제로 토론을 시작하겠습니다. 찬성 측부터 주장을 펼쳐 주십시오."},{"who":"찬성 측 도담","text":"점심시간에도 도서실을 열어야 합니다. 쉬는 시간만으로는 책을 고를 시간이 모자라기 때문입니다. 도서부가 이번 학기에 고학년 이백 명에게 물어보니, 백삼십 명이 점심시간에 책을 빌리고 싶다고 답했습니다."},{"who":"반대 측 서아","text":"점심시간에는 도서실을 닫아야 합니다. 도서실을 지키는 분도 쉬는 시간이 있어야 하기 때문입니다. 어떤 누리집에서 봤는데 다른 학교도 다 닫는다고 합니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#25','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C42',4,'essay','teacher','토론자에게 필요한 힘 가운데 내가 잘하는 것과 더 길러야 할 것을 하나씩 골라 까닭과 함께 쓰고, 기르기 위해 할 일을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u3-C42","difficulty":4,"kind":"essay","stem":"토론자에게 필요한 힘 가운데 내가 잘하는 것과 더 길러야 할 것을 하나씩 골라 까닭과 함께 쓰고, 기르기 위해 할 일을 쓰세요.","answer_guide":{"answer":"예: 나는 상대 말을 끝까지 듣고 메모하는 것은 잘해서 상대 근거의 타당성을 따져 보는 힘이 있다. 그러나 반론을 받았을 때 당황해서 같은 말을 되풀이하곤 해서, 반론에 알맞게 답하는 힘을 더 길러야 한다. 그래서 다음 토론에서는 예상 반론을 미리 세 가지 적고 각각에 자료로 답하는 연습을 하겠다.","scoring_points":["잘하는 힘과 까닭을 썼는가","더 길러야 할 힘과 까닭을 썼는가","기르기 위한 구체적인 할 일을 썼는가"]},"explanation":["네 가지 힘을 떠올려요.","내 모습과 견줘요.","할 일을 구체적으로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#1','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C1',1,'mc','auto','다음 가운데 찬반이 갈려 토론이 필요한 상황은 어느 것인가요?',ARRAY['K6-1-u3-X01']::text[],false,'{"seq":1,"concept":"K6-1-u3-C1","difficulty":1,"kind":"mc","stem":"다음 가운데 찬반이 갈려 토론이 필요한 상황은 어느 것인가요?","options":[{"t":"공원 한쪽에 반려견 놀이터를 만들지 정하기","correct":true},{"t":"공원이 언제 문을 열었는지 알아보기","mis":"K6-1-u3-X01"},{"t":"공원 넓이를 재어 보기","mis":"K6-1-u3-X01"},{"t":"공원 지도 보는 법 익히기","mis":"K6-1-u3-X01"}],"explanation":["문을 연 때는 찾아보면 알아요.","넓이는 재면 알아요.","찬반이 갈리는 문제에서 토론해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#2','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C10',1,'mc','auto','다음 가운데 근거로 쓸 수 있는 자료는 무엇인가요?',ARRAY['K6-1-u3-X04','K6-1-u3-X05']::text[],false,'{"seq":2,"concept":"K6-1-u3-C10","difficulty":1,"kind":"mc","stem":"다음 가운데 근거로 쓸 수 있는 자료는 무엇인가요?","options":[{"t":"체육 교과 연구회가 낸 안전 지침","correct":true},{"t":"나누어 쓰면 더 재미없을 것 같다","mis":"K6-1-u3-X04"},{"t":"운동장이 좁아서 답답하다고 느낀다","mis":"K6-1-u3-X04"},{"t":"운동장은 나누어 써야 한다","mis":"K6-1-u3-X05"}],"explanation":["「같다」는 짐작이에요.","느낌은 근거가 아니에요.","누가 낸 자료인지 확인돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#3','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C5',1,'ox','auto','반론하기는 주장 펼치기보다 먼저 해요.',ARRAY['K6-1-u3-X06']::text[],false,'{"seq":3,"concept":"K6-1-u3-C5","difficulty":1,"kind":"ox","stem":"반론하기는 주장 펼치기보다 먼저 해요.","answer":"X","reason_options":[{"t":"상대가 주장을 펼친 뒤에야 그 주장을 되받을 수 있기 때문에","correct":true},{"t":"먼저 되받아야 이기기 때문에","mis":"K6-1-u3-X06"}],"mis":"K6-1-u3-X06","explanation":["되받으려면 들을 것이 있어야 해요.","주장 펼치기가 먼저예요.","그다음 반론하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#4','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C17',1,'mc','auto','토론에서 써야 하는 말은 어느 것인가요?',ARRAY['K6-1-u3-X14']::text[],false,'{"seq":4,"concept":"K6-1-u3-C17","difficulty":1,"kind":"mc","stem":"토론에서 써야 하는 말은 어느 것인가요?","options":[{"t":"높임말","correct":true},{"t":"반말","mis":"K6-1-u3-X14"},{"t":"줄임말","mis":"K6-1-u3-X14"},{"t":"공격적인 말투","mis":"K6-1-u3-X14"}],"explanation":["반말은 공식적인 자리에 맞지 않아요.","줄임말도 맞지 않아요.","토론에서는 높임말을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#5','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C33',1,'mc','auto','판정단이 판정할 때 바탕으로 삼는 것은 무엇인가요?',ARRAY['K6-1-u3-X24','K6-1-u3-X38']::text[],false,'{"seq":5,"concept":"K6-1-u3-C33","difficulty":1,"kind":"mc","stem":"판정단이 판정할 때 바탕으로 삼는 것은 무엇인가요?","options":[{"t":"토론에서 실제로 나온 말과 자료","correct":true},{"t":"평소 자기 생각","mis":"K6-1-u3-X24"},{"t":"토론자의 옷차림","mis":"K6-1-u3-X38"},{"t":"친한 친구가 있는 편","mis":"K6-1-u3-X24"}],"explanation":["평소 생각은 넣지 않아요.","옷차림은 상관없어요.","나온 말과 자료만 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#6','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C19',1,'mc','auto','토론 주제가 정해지면 역할보다 먼저 할 일은 무엇인가요?',ARRAY['K6-1-u3-X20','K6-1-u3-X16']::text[],false,'{"seq":6,"concept":"K6-1-u3-C19","difficulty":1,"kind":"mc","stem":"토론 주제가 정해지면 역할보다 먼저 할 일은 무엇인가요?","options":[{"t":"모두가 자기 생각을 정하기","correct":true},{"t":"판정단 뽑기","mis":"K6-1-u3-X20"},{"t":"사회자 뽑기","mis":"K6-1-u3-X20"},{"t":"판정 결과 정하기","mis":"K6-1-u3-X16"}],"explanation":["판정단은 그다음에 뽑아요.","사회자도 그다음이에요.","자기 생각을 먼저 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#7','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C27',1,'mc','auto','다음 가운데 힘을 내지 못하는 근거는 무엇인가요?',ARRAY['K6-1-u3-X35']::text[],false,'{"seq":7,"concept":"K6-1-u3-C27","difficulty":1,"kind":"mc","stem":"다음 가운데 힘을 내지 못하는 근거는 무엇인가요?","options":[{"t":"언제 몇 명에게 물었는지 없는 「많은 사람」","correct":true},{"t":"교육청이 올해 낸 학교 시설 점검 자료","mis":"K6-1-u3-X35"},{"t":"우리 시가 지난해 시민 사백 명에게 물은 조사","mis":"K6-1-u3-X35"},{"t":"학생 회의가 지난 학기에 조사한 보건실 자료","mis":"K6-1-u3-X35"}],"explanation":["교육청 자료는 출처와 때가 있어요.","시의 조사는 대상도 밝혀요.","「많은 사람」은 흐릿해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#8','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C43',1,'mc','auto','「붉다」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K6-1-u3-X44']::text[],false,'{"seq":8,"concept":"K6-1-u3-C43","difficulty":1,"kind":"mc","stem":"「붉다」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[북따]","correct":true},{"t":"[불따]","mis":"K6-1-u3-X44"},{"t":"[붉다]","mis":"K6-1-u3-X44"},{"t":"[부따]","mis":"K6-1-u3-X44"}],"explanation":["ㄺ 뒤에 ㄷ이 왔어요.","ㄺ은 [ㄱ]으로 소리 나요.","뒤의 ㄷ은 된소리가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#9','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C9',2,'ox','auto','도담이의 주장 펼치기에는 주장 · 이유 · 근거가 모두 있어요.',ARRAY['K6-1-u3-X05']::text[],false,'{"seq":9,"concept":"K6-1-u3-C9","difficulty":2,"kind":"ox","stem":"도담이의 주장 펼치기에는 주장 · 이유 · 근거가 모두 있어요.","answer":"O","reason_options":[{"t":"열자는 주장, 책 고를 시간이 모자라다는 이유, 도서부 설문이라는 근거를 냈기 때문에","correct":true},{"t":"주장만 분명하면 되기 때문에","mis":"K6-1-u3-X05"}],"mis":"K6-1-u3-X05","explanation":["주장을 냈어요.","이유를 냈어요.","확인할 수 있는 근거도 냈어요."],"asset":{"type":"speech","turns":[{"who":"사회자 하람","text":"지금부터 「점심시간에도 학교 도서실을 열어야 한다」라는 주제로 토론을 시작하겠습니다. 찬성 측부터 주장을 펼쳐 주십시오."},{"who":"찬성 측 도담","text":"점심시간에도 도서실을 열어야 합니다. 쉬는 시간만으로는 책을 고를 시간이 모자라기 때문입니다. 도서부가 이번 학기에 고학년 이백 명에게 물어보니, 백삼십 명이 점심시간에 책을 빌리고 싶다고 답했습니다."},{"who":"반대 측 서아","text":"점심시간에는 도서실을 닫아야 합니다. 도서실을 지키는 분도 쉬는 시간이 있어야 하기 때문입니다. 어떤 누리집에서 봤는데 다른 학교도 다 닫는다고 합니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#10','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C11',2,'ox','auto','도담이가 누리집의 이름과 쓴 때를 물은 것은 알맞은 반론이에요.',ARRAY['K6-1-u3-X14']::text[],false,'{"seq":10,"concept":"K6-1-u3-C11","difficulty":2,"kind":"ox","stem":"도담이가 누리집의 이름과 쓴 때를 물은 것은 알맞은 반론이에요.","answer":"O","reason_options":[{"t":"근거의 출처가 분명한지를 겨누었기 때문에","correct":true},{"t":"상대를 곤란하게 하려는 말이기 때문에","mis":"K6-1-u3-X14"}],"mis":"K6-1-u3-X14","explanation":["사람을 겨누지 않았어요.","근거를 겨누었어요.","출처를 묻는 것은 알맞은 반론이에요."],"asset":{"type":"speech","turns":[{"who":"반대 측 서아","text":"그것도 모르십니까? 점심시간에는 다들 운동장에 나갑니다."},{"who":"찬성 측 도담","text":"말씀 잘 들었습니다. 다만 저희 설문에서 백삼십 명이 빌리고 싶다고 답했습니다. 다들 운동장에 나간다는 말은 저희 자료와 맞지 않습니다."},{"who":"찬성 측 도담","text":"반대 측께 묻겠습니다. 다른 학교도 다 닫는다는 누리집은 어디이고, 언제 쓴 글입니까?"},{"who":"반대 측 서아","text":"누리집 이름은 적어 두지 못했습니다. 그런데 저는 요즘 급식 줄이 더 문제라고 봅니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#11','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C14',2,'mc','auto','주장 다지기를 할 때 알맞은 말하기 방법은 어느 것인가요?',ARRAY['K6-1-u3-X15','K6-1-u3-X07','K6-1-u3-X26']::text[],false,'{"seq":11,"concept":"K6-1-u3-C14","difficulty":2,"kind":"mc","stem":"주장 다지기를 할 때 알맞은 말하기 방법은 어느 것인가요?","options":[{"t":"짧은 문장으로, 「요컨대 · 따라서」를 써서, 또박또박 힘 있게","correct":true},{"t":"길게 늘여서 같은 말을 여러 번","mis":"K6-1-u3-X15"},{"t":"상대 말을 끊고 빠르게","mis":"K6-1-u3-X07"},{"t":"목소리를 높여 한꺼번에 여러 가지를","mis":"K6-1-u3-X26"}],"explanation":["길게 늘이면 중심이 흐려져요.","말차례를 지켜요.","짧고 또박또박 힘 있게 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#12','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C35',2,'mc','auto','판정 기준 가운데 「태도」에서 보는 것은 어느 것인가요?',ARRAY['K6-1-u3-X16','K6-1-u3-X45','K6-1-u3-X38']::text[],false,'{"seq":12,"concept":"K6-1-u3-C35","difficulty":2,"kind":"mc","stem":"판정 기준 가운데 「태도」에서 보는 것은 어느 것인가요?","options":[{"t":"규칙을 지키고 상대 말을 경청하며 예의 바르게 참여했는가","correct":true},{"t":"누가 더 오래 말했는가","mis":"K6-1-u3-X16"},{"t":"누가 더 큰 소리로 말했는가","mis":"K6-1-u3-X45"},{"t":"누가 옷을 단정하게 입었는가","mis":"K6-1-u3-X38"}],"explanation":["말한 길이는 기준이 아니에요.","목소리 크기도 아니에요.","규칙 · 경청 · 예의를 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#13','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C34',2,'mc','auto','토론자가 상대 발언을 메모하는 가장 큰 까닭은 무엇인가요?',ARRAY['K6-1-u3-X38','K6-1-u3-X16','K6-1-u3-X08']::text[],false,'{"seq":13,"concept":"K6-1-u3-C34","difficulty":2,"kind":"mc","stem":"토론자가 상대 발언을 메모하는 가장 큰 까닭은 무엇인가요?","options":[{"t":"들은 것 가운데 가장 약한 곳을 골라 되받기 위해서","correct":true},{"t":"상대 말투를 흉내 내기 위해서","mis":"K6-1-u3-X38"},{"t":"판정단에게 보여 주기 위해서","mis":"K6-1-u3-X16"},{"t":"준비한 원고를 다시 읽기 위해서","mis":"K6-1-u3-X08"}],"explanation":["말투는 메모할 거리가 아니에요.","판정단은 스스로 판정해요.","가장 약한 곳을 되받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#14','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C21',2,'ox','auto','전문가의 말을 근거로 쓸 때에는 누구의 말인지 반드시 적어 둬요.',ARRAY['K6-1-u3-X22']::text[],false,'{"seq":14,"concept":"K6-1-u3-C21","difficulty":2,"kind":"ox","stem":"전문가의 말을 근거로 쓸 때에는 누구의 말인지 반드시 적어 둬요.","answer":"O","reason_options":[{"t":"누구의 말인지 밝혀야 확인할 수 있는 근거가 되기 때문에","correct":true},{"t":"전문가의 말은 누구 것이든 똑같기 때문에","mis":"K6-1-u3-X22"}],"mis":"K6-1-u3-X22","explanation":["전문가의 말도 근거가 돼요.","누구의 말인지 밝혀야 해요.","그래야 확인할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#15','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C1',2,'ox','auto','「우리 학교 도서실에 책이 몇 권 있는가」는 토론 주제로 알맞아요.',ARRAY['K6-1-u3-X01']::text[],false,'{"seq":15,"concept":"K6-1-u3-C1","difficulty":2,"kind":"ox","stem":"「우리 학교 도서실에 책이 몇 권 있는가」는 토론 주제로 알맞아요.","answer":"X","reason_options":[{"t":"찾아보면 곧바로 확인되는 물음이라 찬반이 갈리지 않기 때문에","correct":true},{"t":"수를 따지는 문제는 모두 좋은 토론 주제이기 때문에","mis":"K6-1-u3-X01"}],"mis":"K6-1-u3-X01","explanation":["세어 보면 답이 나와요.","찬반이 갈리지 않아요.","토론 주제가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#16','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C31',2,'mc','auto','근거를 말로 내놓을 때 알맞은 첫마디는 어느 것인가요?',ARRAY['K6-1-u3-X34','K6-1-u3-X29','K6-1-u3-X04']::text[],false,'{"seq":16,"concept":"K6-1-u3-C31","difficulty":2,"kind":"mc","stem":"근거를 말로 내놓을 때 알맞은 첫마디는 어느 것인가요?","options":[{"t":"「우리 시 교통 안전과가 지난해 낸 자료에 따르면」","correct":true},{"t":"「어디서 봤는데」","mis":"K6-1-u3-X34"},{"t":"「다들 아시겠지만」","mis":"K6-1-u3-X29"},{"t":"「제 느낌에는」","mis":"K6-1-u3-X04"}],"explanation":["「어디서 봤는데」는 자료를 흔들어요.","「다들」은 흐릿해요.","누가 언제 낸 자료인지 먼저 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#17','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C5',3,'mc','auto','「상대 근거의 허점을 짚고 그에 답하는」 일과 「남은 것만 추려 다시 강조하는」 일이 바르게 짝 지어진 것은 어느 것인가요?',ARRAY['K6-1-u3-X06']::text[],false,'{"seq":17,"concept":"K6-1-u3-C5","difficulty":3,"kind":"mc","stem":"「상대 근거의 허점을 짚고 그에 답하는」 일과 「남은 것만 추려 다시 강조하는」 일이 바르게 짝 지어진 것은 어느 것인가요?","options":[{"t":"반론하기 — 주장 다지기","correct":true},{"t":"주장 펼치기 — 판정하기","mis":"K6-1-u3-X06"},{"t":"주장 다지기 — 반론하기","mis":"K6-1-u3-X06"},{"t":"판정하기 — 주장 펼치기","mis":"K6-1-u3-X06"}],"explanation":["허점을 짚는 것은 반론하기예요.","다시 강조하는 것은 주장 다지기예요.","순서가 곧 규칙이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#18','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C27',3,'mc','auto','「저희 이모께서 운전할 때 답답하다고 하셨습니다.」가 근거로 약한 까닭은 무엇인가요?',ARRAY['K6-1-u3-X31','K6-1-u3-X17','K6-1-u3-X30']::text[],false,'{"seq":18,"concept":"K6-1-u3-C27","difficulty":3,"kind":"mc","stem":"「저희 이모께서 운전할 때 답답하다고 하셨습니다.」가 근거로 약한 까닭은 무엇인가요?","options":[{"t":"한 사람의 느낌이라 제한 속도와 사고 사이의 관계를 보여 주지 못하기 때문에","correct":true},{"t":"이모는 어른이라 근거가 될 수 없기 때문에","mis":"K6-1-u3-X31"},{"t":"높임말을 썼기 때문에","mis":"K6-1-u3-X17"},{"t":"너무 자세하기 때문에","mis":"K6-1-u3-X30"}],"explanation":["어른이라서가 아니에요.","높임말은 문제가 아니에요.","이유와 이어지지 않는 느낌이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#19','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C12',3,'mc','auto','반론을 받았을 때 답변하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X13','K6-1-u3-X14','K6-1-u3-X16']::text[],false,'{"seq":19,"concept":"K6-1-u3-C12","difficulty":3,"kind":"mc","stem":"반론을 받았을 때 답변하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"반론이 타당하지 않음을 밝히거나, 인정할 것은 인정하고 다시 세운다","correct":true},{"t":"못 들은 척하거나 같은 말을 되풀이한다","mis":"K6-1-u3-X13"},{"t":"상대의 말투를 짚거나 화제를 바꾼다","mis":"K6-1-u3-X14"},{"t":"판정단에게 대신 답해 달라고 한다","mis":"K6-1-u3-X16"}],"explanation":["되풀이는 답변이 아니에요.","화제를 바꾸지 않아요.","물은 지점에 곧바로 답해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#20','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C36',3,'ox','auto','토론이 끝난 뒤 생각이 더 굳어졌다고 말하는 것도 토론을 제대로 한 표시예요.',ARRAY['K6-1-u3-X39']::text[],false,'{"seq":20,"concept":"K6-1-u3-C36","difficulty":3,"kind":"ox","stem":"토론이 끝난 뒤 생각이 더 굳어졌다고 말하는 것도 토론을 제대로 한 표시예요.","answer":"O","reason_options":[{"t":"생각이 바뀌든 굳어지든 상대 근거와 견주어 다시 살펴본 결과이기 때문에","correct":true},{"t":"생각은 처음부터 끝까지 변하면 안 되기 때문에","mis":"K6-1-u3-X39"}],"mis":"K6-1-u3-X39","explanation":["바뀌는 것도 괜찮아요.","굳어지는 것도 괜찮아요.","다시 살펴본 것이 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#21','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C40',3,'error','auto','성곽 토론 뒤에 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u3-X42']::text[],false,'{"seq":21,"concept":"K6-1-u3-C40","difficulty":3,"kind":"error","stem":"성곽 토론 뒤에 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"윤슬 — 「되살리자는 쪽은 역사를 모르는 거야.」","correct":true,"mis_target":"K6-1-u3-X42"},{"t":"가람 — 「찬성 측은 배움의 기회를 더 중요하게 여겼어.」","mis":"K6-1-u3-X42"},{"t":"도윤 — 「반대 측은 남은 것의 진짜 모습을 더 중요하게 여겼어.」","mis":"K6-1-u3-X42"}],"explanation":["가람은 관점을 바르게 정리했어요.","도윤도 관점을 바르게 정리했어요.","윤슬은 상대를 낮추어 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#22','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C43',3,'mc','auto','「긁다」와 「긁고」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K6-1-u3-X44']::text[],false,'{"seq":22,"concept":"K6-1-u3-C43","difficulty":3,"kind":"mc","stem":"「긁다」와 「긁고」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[극따] · [글꼬]","correct":true},{"t":"[글따] · [극꼬]","mis":"K6-1-u3-X44"},{"t":"[극따] · [극꼬]","mis":"K6-1-u3-X44"},{"t":"[글따] · [글꼬]","mis":"K6-1-u3-X44"}],"explanation":["ㄷ 앞에서는 [ㄱ]으로 소리 나요.","ㄱ 앞에서는 [ㄹ]로 소리 나요.","뒤 자음은 된소리가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#23','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C34',4,'mc','auto','은솔이의 메모를 가장 알맞게 고친 것은 어느 것인가요?',ARRAY['K6-1-u3-X12','K6-1-u3-X38','K6-1-u3-X08']::text[],false,'{"seq":23,"concept":"K6-1-u3-C34","difficulty":4,"kind":"mc","stem":"은솔이의 메모를 가장 알맞게 고친 것은 어느 것인가요?","options":[{"t":"「반대 측 말투」 줄을 빼고, 「찬성 측 답변이 닿지 않은 물음」 같은 되받을 거리를 적는다","correct":true},{"t":"모든 발언을 한 글자도 빠짐없이 옮겨 적는다","mis":"K6-1-u3-X12"},{"t":"양측 옷차림도 덧붙여 적는다","mis":"K6-1-u3-X38"},{"t":"메모를 지우고 준비한 원고만 본다","mis":"K6-1-u3-X08"}],"explanation":["다 옮기면 다음 말을 놓쳐요.","옷차림은 되받을 거리가 아니에요.","되받을 거리를 남겨요."],"asset":{"type":"passage","lines":["찬성 측 주장 — 점심시간에도 도서실을 열어야 한다.","찬성 측 이유 — 쉬는 시간만으로는 책 고를 시간이 모자란다.","찬성 측 근거 — 도서부, 이번 학기, 고학년 이백 명 설문.","반대 측 근거 — 어떤 누리집(어디인지 밝히지 않음).","반대 측이 꺼낸 다른 이야기 — 급식 줄.","반대 측 말투 — 목소리가 컸음."],"title":"청중 은솔이의 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#24','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C36',4,'essay','teacher','토론 뒤 서아 · 은솔 · 도담의 말을 견주어 평가하고, 토론을 어떻게 마무리하면 좋을지 내 생각을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u3-C36","difficulty":4,"kind":"essay","stem":"토론 뒤 서아 · 은솔 · 도담의 말을 견주어 평가하고, 토론을 어떻게 마무리하면 좋을지 내 생각을 쓰세요.","answer_guide":{"answer":"예: 서아는 판정단 탓을 해서 판정에 승복하지 않았고 남는 것이 승패뿐이다. 은솔이는 새롭게 안 사실과 사회자의 잘한 점을 말해 알맞다. 도담이는 상대가 짚은 점을 받아들이고 더 찾아보려 해서 생각을 남겼다. 나는 토론이 끝나면 판정에 승복하고, 새로 안 것과 다른 역할을 맡은 친구의 잘한 점을 나누며, 생각이 바뀌거나 굳어진 곳을 말하는 것이 좋은 마무리라고 생각한다.","scoring_points":["서아의 말이 알맞지 않은 까닭을 썼는가","은솔 · 도담의 말이 알맞은 까닭을 썼는가","바람직한 마무리를 내 생각으로 썼는가"]},"explanation":["세 친구의 말을 견줘요.","승패와 생각 가운데 무엇이 남는지 봐요.","내 생각을 써요."],"asset":{"type":"speech","turns":[{"who":"서아","text":"판정이 이상해. 우리가 진 건 판정단 탓이야."},{"who":"은솔","text":"나는 도서부 설문 자료를 처음 알았어. 사회를 맡은 하람이가 말차례를 잘 지켜 줬어."},{"who":"도담","text":"반대 측이 말한 지키는 분의 쉬는 시간은 미처 생각 못 했어. 도서부가 돌아가며 돕는 방법을 찾아봐야겠어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#25','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C43',4,'essay','teacher','겹받침 ㄺ이 있는 낱말 하나를 골라 뒤에 ㄷ이 올 때와 ㄱ이 올 때 어떻게 다르게 읽는지 예를 들어 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u3-C43","difficulty":4,"kind":"essay","stem":"겹받침 ㄺ이 있는 낱말 하나를 골라 뒤에 ㄷ이 올 때와 ㄱ이 올 때 어떻게 다르게 읽는지 예를 들어 설명하세요.","answer_guide":{"answer":"예: 「밝다」는 [박따]로 읽는다. ㄺ 뒤에 ㄷ이 오면 ㄺ은 [ㄱ]으로 소리 나고 뒤의 ㄷ은 된소리가 되기 때문이다. 「밝고」는 [발꼬]로 읽는다. ㄺ 뒤에 ㄱ이 오면 [ㄹ]로 소리 나고 뒤의 ㄱ이 된소리가 되기 때문이다.","scoring_points":["ㄺ이 있는 낱말을 골라 두 경우를 바르게 읽었는가","ㄷ 앞에서 [ㄱ]으로 소리 나는 까닭을 썼는가","ㄱ 앞에서 [ㄹ]로 소리 나는 까닭을 썼는가"]},"explanation":["ㄺ 낱말을 골라요.","ㄷ 앞에서 읽어요.","ㄱ 앞에서 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C1','kor',6,1,'u4',1,'관용 표현의 뜻 — 오래 쓰이면서 통째로 굳어져 낱말 하나하나의 뜻을 더한 것과는 다른 새로운 뜻을 지닌 말로, 「입을 모으다」는 실제로 입을 모은 것이 아니라 여럿이 같은 말을 한다는 뜻이다',ARRAY['6국04-03 문법']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C2','kor',6,1,'u4',1,'관용 표현 가려내기 — 낱말 뜻을 그대로 더했을 때 말이 통하면(가방을 열다 · 창문을 닦다) 관용 표현이 아니고, 뜻이 엉뚱하게 달라지면(눈코 뜰 새 없다) 관용 표현이다',ARRAY['6국04-03 문법']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C3','kor',6,1,'u4',1,'관용어와 속담 — 관용어는 두 개 이상의 낱말이 합쳐져 새로운 뜻을 이루고 오래 쓰여 굳어진 말이고, 속담은 예로부터 전해 오며 조상의 삶에서 얻은 지혜나 교훈을 담은 말이며, 둘을 묶어 관용 표현이라 한다 — 굳어진 말이라는 점은 같고 교훈을 담고 전해 오는가에서 갈린다',ARRAY['6국04-03 문법']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C4','kor',6,1,'u4',1,'관용 표현을 쓰면 좋은 점 — 길게 설명할 말을 짧은 한마디로 전해 효과적이고, 듣는 사람이 장면을 떠올리게 되어 이야기가 생생해지며, 예부터 전해 오는 말 속에 조상의 생활과 생각, 곧 우리 문화가 담겨 있다',ARRAY['6국04-03 문법']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C5','kor',6,1,'u4',1,'굳어진 모양 그대로 — 관용 표현은 통째로 굳은 말이라 낱말을 바꾸거나 풀어 늘이면(눈을 뜨고 코도 뜰 새가 없었다) 뜻을 잃으므로 모양 그대로 익혀 둔다',ARRAY['6국04-03 문법']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C6','kor',6,1,'u4',1,'많이 넣을수록 좋은 것이 아니다 — 관용 표현을 쓰는 것이 언제나 효과적인 것은 아니며, 상황과 어긋난 표현이 섞이면 오히려 뜻이 흐려지므로 먼저 볼 것은 표현의 개수가 아니라 지금 이 상황에 어울리는가이다',ARRAY['6국04-03 문법']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C7','kor',6,1,'u4',1,'상황에 알맞게 쓰기 — 표현의 뜻과 말하려는 상황이 맞물릴 때만 힘이 생기므로, 표현의 뜻을 풀어 넣어 보아 말이 어색해지면(생일 축하 자리에서 「진땀을 뺐겠구나」) 알맞지 않게 쓴 것이다',ARRAY['6국04-03 문법']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C8','kor',6,1,'u4',2,'관용어 뜻 짐작하기 — 대화 속 관용어는 앞뒤 상황을 보면 뜻을 짐작할 수 있으며, 정확한 뜻을 몰라도 괜찮으니 장면을 떠올려 짐작하는 것부터 시작하고 짐작한 뒤에 사전에서 확인하면 오래 남는다',ARRAY['6국04-03 문법']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C9','kor',6,1,'u4',2,'뜻과 쓸 상황을 함께 — 귀가 밝다(소식이나 정보를 남보다 빨리 알아챈다) · 걱정 붙들어 매다(걱정하지 말라고 안심시키다) · 진땀을 빼다(어려운 일을 겪으며 몹시 애를 쓰다)처럼 뜻을 익힐 때에는 어떤 상황에서 쓰는 말인지까지 붙여 두어야 내 말이 된다 — 뜻만 외우면 금방 잊는다',ARRAY['6국04-03 문법']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C10','kor',6,1,'u4',2,'몸을 가리키는 말이 든 관용어 — 입 · 어깨 · 귀처럼 몸의 한 부분이 든 관용어는 눈에 보이는 몸으로 눈에 보이지 않는 마음이나 태도를 나타낸 것이라, 「어깨가 무겁다」는 어깨가 아니라 책임이 커서 마음이 무겁다는 뜻이다',ARRAY['6국04-03 문법']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C11','kor',6,1,'u4',2,'매체 속 관용어 — 학교 방송 뉴스처럼 말로 전하는 매체에도, 학급 알림장처럼 글로 전하는 매체에도 관용어가 놓이며, 매체가 달라도 관용어는 전하려는 뜻을 짧고 또렷하게 만드는 같은 일을 한다',ARRAY['6국04-03 문법']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C12','kor',6,1,'u4',2,'같은 낱말로 묶어 익히기 — 「입」이 든 관용어(입이 무겁다 · 입을 모으다 · 입에 침이 마르다)처럼 같은 낱말로 묶으면 여러 표현을 한꺼번에 익힐 수 있으나, 그 낱말이 들어 있어도 뜻이 낱말 그대로라면(입을 헹구다) 관용어가 아니다',ARRAY['6국04-03 문법']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C13','kor',6,1,'u4',2,'모르는 관용어 찾는 순서 — 앞뒤 상황을 보고 먼저 뜻을 짐작하고 → 국어사전에서 중심이 되는 낱말을 찾고(귀가 밝다 → 귀) → 뜻풀이 아래쪽에 딸린 관용구와 속담을 살피고 → 짐작한 뜻과 맞춰 보며, 사전을 먼저 펴지 않는 것이 중요하다',ARRAY['6국04-03 문법']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C14','kor',6,1,'u4',3,'속담의 뜻과 힘 — 속담은 예로부터 전해 오는 말로 장면 하나로 말해 머리에 오래 남고 · 어떻게 하는 것이 나은지 교훈을 담고 · 여러 사람이 알아 풀어 설명하지 않아도 통하므로 간결하면서도 효과적이다(빈 수레가 요란하다 — 잘 알지 못하는 사람이 오히려 더 떠든다)',ARRAY['6국04-03 문법']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C15','kor',6,1,'u4',3,'속담이 그리는 장면 풀기 — 빈 수레(짐이 없으면 덜컹거려 더 시끄러움) · 첫술(밥을 뜬 첫 숟가락으로는 배가 부를 리 없음 — 무슨 일이든 한 번에 큰 성과를 얻기 어렵다) · 가랑비(가는 비에도 어느새 다 젖음 — 사소한 것이 쌓여 큰 것이 된다)처럼 장면을 풀면 뜻이 따라온다',ARRAY['6국04-03 문법']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C16','kor',6,1,'u4',3,'속담 속 옛말은 낡은 것이 아니다 — 속담에는 오늘날 잘 쓰지 않는 옛말이나 옛 생활 모습(수레 · 서당 · 풍월)이 남아 있는데, 그 낯섦은 버릴 말이라는 표시가 아니라 조상의 생각과 생활이 말에 남은 흔적이므로 무엇을 가리키는 말인지 찾아본다',ARRAY['6국04-03 문법']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C17','kor',6,1,'u4',3,'뜻이 비슷한 속담 — 첫술에 배부르랴와 급할수록 돌아가라, 가랑비에 옷 젖는 줄 모른다와 바늘 도둑이 소도둑 된다처럼 뜻이 비슷한 속담도 기우는 방향이 조금씩 달라(바늘 도둑은 나쁜 일이 커지는 쪽), 바꿔 쓸 수 있는지는 뜻만이 아니라 어떤 상황에 쓰는 말인지까지 견주어 정한다',ARRAY['6국04-03 문법']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C18','kor',6,1,'u4',3,'속담 찾는 방법 — 속담 사전 · 국어사전 · 인터넷 사전 어느 쪽이든 속담에서 중심이 되는 낱말을 앞세워 찾으며(빈 수레가 요란하다 → 수레), 사전을 첫 쪽부터 넘기거나 짐작한 뜻을 그대로 정답으로 삼지 않는다',ARRAY['6국04-03 문법']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C19','kor',6,1,'u4',3,'속담 바꾸어 짓기 — 속담 하나를 골라 오늘의 생활에 맞게 낱말만 바꾸어 새 속담을 짓되, 담긴 교훈은 살리고 어떤 상황에서 쓸 말인지도 함께 적는다',ARRAY['6국04-03 문법']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C20','kor',6,1,'u4',4,'관용 표현을 쓴 의도 읽기 — 관용 표현을 들으면 뜻만이 아니라 말한 사람이 왜 그 표현을 골랐는지 의도까지 읽어야 하며, 「목마른 사람이 우물 판다잖아. 답답한 내가 먼저 가 볼게.」는 아쉬운 사람이 먼저 나서는 것이 당연하다고 전하려는 말이다',ARRAY['6국04-03 문법']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C21','kor',6,1,'u4',4,'관용 표현은 마음을 고르는 일 — 「정말 하고 싶었다」 대신 「마음이 굴뚝같았다」를 고르면 그 마음의 크기가 함께 전해지듯, 관용 표현을 고르는 일은 뜻을 고르는 일이 아니라 전하고 싶은 마음을 고르는 일에 가깝다',ARRAY['6국04-03 문법']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C22','kor',6,1,'u4',4,'이야기 속 관용 표현 — 옛이야기 「소금 장수와 나루터」의 발등에 불이 떨어지다(급함) · 급할수록 돌아가라(돌아가는 지혜) · 낯이 뜨겁다(부끄러움)처럼 이야기에서도 관용 표현이 인물의 마음과 이야기가 담은 지혜를 한마디로 전한다',ARRAY['6국04-03 문법']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C23','kor',6,1,'u4',4,'뜻이 비슷한 관용 표현 — 발등에 불이 떨어지다 ↔ 코앞에 닥치다, 낯이 뜨겁다 ↔ 고개를 들지 못하다, 마음이 굴뚝같다 ↔ 목이 빠지게 기다리다처럼 가리키는 마음이 같은 표현을 알아 두면 상황에 더 잘 맞는 것을 고를 수 있다',ARRAY['6국04-03 문법']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C24','kor',6,1,'u4',4,'듣는 사람과 자리 — 표현의 뜻은 하나여도 누구에게 하느냐에 따라 뜻이 뒤집혀, 상을 받은 친구에게 「빈 수레가 요란하다더니」는 깎아내리는 말이 되고 자신을 돌아보며 「내가 빈 수레가 요란했구나」는 돌아보는 말이 되므로, 쓰기 전에 듣는 사람과 지금 이 자리를 함께 본다',ARRAY['6국04-03 문법']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C25','kor',6,1,'u4',4,'할 수 있는 만큼부터 — 관용 표현을 소리 내어 쓰는 일이 부담스러울 수 있으므로 쓰고 싶은 상황을 떠올려 보는 것에서 시작해 떠올리기 → 적어 보기 → 말해 보기 순서로 할 수 있는 만큼 나아가면 되며, 남들 앞에서 말할 자신이 없다고 배우지 못한 것은 아니다',ARRAY['6국04-03 문법']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C26','kor',6,1,'u4',4,'상황 짜고 대사 쓰기 — 쓰고 싶은 표현을 고르고 · 어울리는 상황을 한 줄로 적고 · 누가 누구에게 말하는지 정하고 · 표현의 뜻이 상황과 어긋나지 않는지 마지막으로 살피며, 이 넷째 칸은 건너뛰지 않는다 — 다 지은 뒤 표현을 빼고 읽어 보면 무엇이 달라지는지 보인다',ARRAY['6국04-03 문법']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C27','kor',6,1,'u4',6,'견학 기록문의 뜻 — 견학하고 새롭게 안 사실을 중심으로 보고 듣고 느낀 것을 쓴 글로, 정보 전달이 강조되므로 견학한 곳은 어디든 될 수 있지만 그 안에서 새로 안 사실은 참이어야 한다',ARRAY['6국03-03 쓰기']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C28','kor',6,1,'u4',6,'여정 · 견문 · 감상 — 여정은 어디를 거쳐 어떻게 다녔는지 다닌 길, 견문은 그곳에서 보고 들은 것 · 새롭게 안 사실, 감상은 그 일을 겪으며 생각하거나 느낀 것이며, 셋이 번갈아 엮여야 견학 기록문이 된다',ARRAY['6국03-03 쓰기']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C29','kor',6,1,'u4',6,'처음 · 가운데 · 끝 — 처음에는 견학한 까닭 · 함께 간 사람 · 장소(언제 · 누구와 · 어디에 · 왜)를 밝혀 개요를 알리고, 가운데에는 다닌 차례대로 보고 들은 것과 그때 느낀 것을 적고, 끝에는 견학한 내용을 정리하고 깨달은 점을 적는다',ARRAY['6국03-03 쓰기']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C30','kor',6,1,'u4',6,'안내문도 일기도 아니다 — 감상이 빠지면 사실만 남아 안내문이 되고, 견문이 빠지면 마음만 남아 일기가 되므로, 견학 기록문은 새롭게 안 사실을 중심에 놓되 그것을 알고 마음이 어떻게 움직였는지까지 적는 두 갈래 사이의 글이다',ARRAY['6국03-03 쓰기']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C31','kor',6,1,'u4',6,'제목과 문단으로 읽기 — 제목만 보고도 어디에 다녀온 글이고 무엇을 새로 알았을지 짐작할 수 있으며, 문단이 처음 · 가운데 · 끝 가운데 어느 자리에 있는지 먼저 보면 문단마다 맡은 몫과 중심 내용이 보인다',ARRAY['6국03-03 쓰기']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C32','kor',6,1,'u4',8,'견학 기록문을 쓰면 좋은 점 — 보고 들은 것과 그때의 마음이 흐려지지 않고 남으며 · 가 보지 못한 사람에게 그곳을 알릴 수 있고 · 그곳에 가려는 사람에게 도움이 되어, 쓰는 사람에게도 남고 읽는 사람에게도 건너간다',ARRAY['6국03-03 쓰기']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C33','kor',6,1,'u4',8,'쓸 견학 고르기 — 다녀온 곳을 여러 군데 떠올린 뒤 가장 기억에 남는 곳을 고르고 왜 기억에 남는지 한 줄로 적어 보는데, 기억에 남은 까닭이 곧 이 글의 감상이 되므로 까닭이 떠오르지 않는 곳은 쓰기 어렵다',ARRAY['6국03-03 쓰기']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C34','kor',6,1,'u4',8,'목적 · 주제 · 읽을 사람 — 왜 쓰는가(목적) · 무엇을 중심에 놓을 것인가(주제) · 누가 읽는가(읽을 사람)를 정하며, 이 가운데 읽을 사람이 글의 모양을 가장 많이 바꾸어 동생이 읽는다면 어려운 낱말은 풀어 쓰고 낯선 것은 한 줄 더 설명한다',ARRAY['6국03-03 쓰기']::text[],34) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C35','kor',6,1,'u4',8,'생각그물과 조직표 — 생각그물로 장소 · 함께 간 사람과 까닭 · 여정 · 견문 · 감상의 다섯 갈래를 순서 없이 떠오르는 대로 모은 뒤, 조직표로 처음 · 가운데 · 끝에 나누며, 가운데는 본 것 하나에 느낀 것 하나를 짝지어 가야 사실만 늘어놓은 글이 되지 않는다',ARRAY['6국03-03 쓰기']::text[],35) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C36','kor',6,1,'u4',8,'관용 표현은 감상 자리에 — 견문은 사실이고 감상은 마음이라 관용 표현이 잘 놓이는 자리는 마음 쪽이며, 사실을 전하는 견문 자리에 얹으면(소화전에 호스를 잇는데 손이 열 개라도 모자란다) 무엇이 사실인지 흐려진다',ARRAY['6국03-03 쓰기']::text[],36) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C37','kor',6,1,'u4',8,'칸 채우기가 아니다 — 견학 기록문에서 가장 중요한 것은 진솔함이며, 여정 · 견문 · 감상도 관용 표현도 채워야 할 칸이 아니라 담을 그릇이라 가장 크게 마음이 움직인 자리에 하나만 놓아도 되고 담을 것이 없으면 비워 두어도 된다',ARRAY['6국03-03 쓰기']::text[],37) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C38','kor',6,1,'u4',8,'고쳐 쓰기와 나누기 — 고쳐 쓸 때에는 견학한 까닭이 드러나는가 · 여정 · 견문 · 감상이 전해지는가 · 처음 · 가운데 · 끝의 짜임이 맞는가 · 관용 표현이 상황에 맞게 놓였는가를 살피고(글씨 모양이나 길이는 아님), 나눌 때에는 내가 정한 읽을 사람이 실제로 읽을 수 있는 방법을 고른다',ARRAY['6국03-03 쓰기']::text[],38) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C39','kor',6,1,'u4',11,'묶어서 만드는 관용 표현 사전 — 공통으로 들어가는 낱말(동물 — 원숭이도 나무에서 떨어진다 · 서당 개 삼 년이면 풍월을 읊는다 · 고양이 목에 방울 달기 / 몸 — 어깨너머로 배우다 · 목에 힘을 주다 · 등을 떠밀다)이나 같은 마음(놀람 · 부끄러움 · 간절함 · 바쁨)으로 묶으며, 낱말로 묶으면 찾기가 쉽고 마음으로 묶으면 쓰기가 쉽다',ARRAY['6국04-03 문법']::text[],39) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C40','kor',6,1,'u4',11,'사전 한 장의 세 칸 — 사전 한 장에는 관용 표현(굳어진 모양 그대로) · 뜻(사전에서 확인한 뜻을 내 말로 줄여서) · 쓸 수 있는 상황(내가 겪은 일이나 겪을 법한 일)을 담으며, 뜻만 적힌 사전은 한 번 보고 덮게 되지만 내 상황이 적힌 사전은 필요할 때 떠오른다',ARRAY['6국04-03 문법']::text[],40) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C41','kor',6,1,'u4',11,'표현을 고르는 기준 — 아무도 모르는 어려운 표현을 많이 채우는 것이 아니라, 개수도 어려움도 아닌 「내가 쓸 자리가 떠오르는가」로 고르며, 쓸 상황이 떠오르지 않는 표현은 다음으로 미뤄도 된다',ARRAY['6국04-03 문법']::text[],41) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u4-C42','kor',6,1,'u4',11,'상황에 따른 언어 예절 — 쉬는 시간 친구와의 비공식적인 말하기에서는 둘레에 방해가 되지 않게 작은 소리로 · 말차례를 지키며 · 반응을 보이며 듣고, 학급 전체 앞 발표 같은 공식적인 말하기에서는 존댓말로 · 모두 들을 수 있는 크기로 · 바른 자세로 듣는 사람을 보며 · 끝까지 경청하며, 예절을 정하는 기준은 외운 목록이 아니라 「듣는 사람이 편하게 들을 수 있는가」라서 목소리 크기 · 표정 · 자세까지 함께 살핀다 (기초 다지기)',ARRAY['기초 다지기(언어 예절)']::text[],42) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X01','kor',6,'u4',ARRAY['K6-1-u4-C1','K6-1-u4-C2']::text[],'관용 표현을 낱말 하나하나의 뜻을 그대로 더한 말로 여겨 글자 그대로 풀어 읽는다','낱말 뜻의 합과 다른 뜻') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X02','kor',6,'u4',ARRAY['K6-1-u4-C2']::text[],'낱말 뜻 그대로 통하는 말(가방을 열다 · 창문을 닦다)도 관용 표현으로 고른다','뜻이 엉뚱하게 달라지나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X03','kor',6,'u4',ARRAY['K6-1-u4-C12','K6-1-u4-C39']::text[],'입 · 어깨 · 동물 이름 같은 낱말이 들어 있기만 하면 뜻이 낱말 그대로여도 관용 표현이라고 여긴다','낱말과 뜻을 함께 따져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X04','kor',6,'u4',ARRAY['K6-1-u4-C3']::text[],'관용어와 속담을 헷갈리거나, 둘을 묶어 관용 표현이라 부른다는 것을 모른다','교훈을 담고 전해 오나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X05','kor',6,'u4',ARRAY['K6-1-u4-C1']::text[],'관용 표현을 어려운 한자로 줄인 전문가의 말이나 사전 낱말을 길게 이어 붙인 말로 여긴다','오래 쓰여 굳어진 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X06','kor',6,'u4',ARRAY['K6-1-u4-C5']::text[],'관용 표현의 낱말을 바꾸거나 풀어 늘여 써도 뜻이 그대로라고 여긴다','모양 그대로 익혀요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X07','kor',6,'u4',ARRAY['K6-1-u4-C6','K6-1-u4-C37']::text[],'관용 표현을 많이 넣을수록 좋은 말이나 글이 된다고 여긴다','개수가 아니라 어울림') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X08','kor',6,'u4',ARRAY['K6-1-u4-C7']::text[],'표현의 뜻과 어긋난 상황에 관용 표현을 쓴다(생일 축하에 「진땀을 뺐겠구나」)','뜻을 풀어 넣어 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X09','kor',6,'u4',ARRAY['K6-1-u4-C4','K6-1-u4-C21']::text[],'관용 표현을 쓰나 그냥 말하나 전해지는 것이 똑같다고 여겨 좋은 점을 모른다','짧게 · 생생하게 · 문화') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X10','kor',6,'u4',ARRAY['K6-1-u4-C8','K6-1-u4-C13']::text[],'모르는 관용어를 앞뒤 상황으로 짐작해 보지 않고 곧바로 사전부터 펴거나, 정확히 모르면 아예 넘어간다','짐작 먼저, 사전은 나중') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X11','kor',6,'u4',ARRAY['K6-1-u4-C9','K6-1-u4-C40']::text[],'관용 표현의 뜻만 외우고 어떤 상황에서 쓰는 말인지는 붙여 두지 않는다','뜻과 쓸 상황을 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X12','kor',6,'u4',ARRAY['K6-1-u4-C10']::text[],'몸이 든 관용어를 실제 몸의 상태로 읽는다(귀가 밝다 = 소리를 잘 듣는다)','몸으로 마음을 나타내요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X13','kor',6,'u4',ARRAY['K6-1-u4-C11']::text[],'뉴스나 안내문 같은 매체에서는 관용어를 쓸 수 없거나 하는 일이 달라진다고 여긴다','매체가 달라도 같은 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X14','kor',6,'u4',ARRAY['K6-1-u4-C13','K6-1-u4-C18']::text[],'사전에서 관용 표현이나 속담을 찾을 때 중심이 되는 낱말을 잡지 않고 첫 쪽부터 넘기거나 문장 전체를 찾는다','중심 낱말을 앞세워요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X15','kor',6,'u4',ARRAY['K6-1-u4-C14','K6-1-u4-C3']::text[],'그 자리에서 지어낸 말과 예로부터 전해 오며 교훈을 담은 속담을 헷갈린다','예로부터 전해 오나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X16','kor',6,'u4',ARRAY['K6-1-u4-C15']::text[],'속담이 그리는 장면을 잘못 풀어 뜻을 거꾸로 알거나 엉뚱하게 안다','장면을 먼저 그려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X17','kor',6,'u4',ARRAY['K6-1-u4-C16']::text[],'속담 속 옛말이나 옛 생활 모습을 낡아서 버릴 말로 여긴다','옛 생활이 남은 흔적') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X18','kor',6,'u4',ARRAY['K6-1-u4-C17']::text[],'뜻이 비슷한 속담은 어느 상황에서나 그대로 바꿔 쓸 수 있다고 여긴다','기우는 방향을 견줘요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X19','kor',6,'u4',ARRAY['K6-1-u4-C19']::text[],'속담을 바꾸어 지을 때 담긴 교훈까지 바꿔 버리거나 쓸 상황을 적지 않는다','교훈은 살리고 상황도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X20','kor',6,'u4',ARRAY['K6-1-u4-C20']::text[],'관용 표현을 쓴 의도를 꾸짖거나 자랑하려는 것으로 잘못 읽는다','그 말 뒤에 무엇이 붙었나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X21','kor',6,'u4',ARRAY['K6-1-u4-C22','K6-1-u4-C1']::text[],'이야기 속 관용 표현을 실제로 일어난 일(정말 발등에 불이 붙음)로 읽는다','인물의 마음을 나타내요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X22','kor',6,'u4',ARRAY['K6-1-u4-C23']::text[],'가리키는 마음이 다른 표현끼리 바꿔 쓸 수 있다고 여긴다','같은 마음인가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X23','kor',6,'u4',ARRAY['K6-1-u4-C24']::text[],'듣는 사람과 자리를 살피지 않고 관용 표현으로 남을 깎아내리거나 상처를 준다','누구에게 하는 말인가') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X24','kor',6,'u4',ARRAY['K6-1-u4-C25']::text[],'남들 앞에서 소리 내어 말하지 못하면 관용 표현을 배우지 못한 것이라고 여긴다','떠올리기부터 시작해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X25','kor',6,'u4',ARRAY['K6-1-u4-C26']::text[],'상황을 짤 때 표현의 뜻이 상황과 어긋나지 않는지 살피는 마지막 칸을 건너뛴다','넷째 칸은 꼭') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X26','kor',6,'u4',ARRAY['K6-1-u4-C27']::text[],'견학 기록문에서 새로 안 사실을 그럴듯하게 지어내도 된다고 여긴다','새로 안 사실은 참이어야') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X27','kor',6,'u4',ARRAY['K6-1-u4-C28']::text[],'여정 · 견문 · 감상을 헷갈린다(새로 안 사실을 감상으로, 느낀 것을 견문으로)','길 · 본 것 · 마음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X28','kor',6,'u4',ARRAY['K6-1-u4-C29']::text[],'처음 · 가운데 · 끝에 들어갈 내용을 헷갈린다','개요 · 본 것과 느낌 · 정리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X29','kor',6,'u4',ARRAY['K6-1-u4-C30']::text[],'감상을 빼고 새로 안 사실만 늘어놓아도 견학 기록문이라고 여긴다','사실만 남으면 안내문') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X30','kor',6,'u4',ARRAY['K6-1-u4-C30']::text[],'견문을 빼고 「재미있었다 · 신기했다」 같은 느낌만 적어도 견학 기록문이라고 여긴다','마음만 남으면 일기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X31','kor',6,'u4',ARRAY['K6-1-u4-C31']::text[],'문단이 처음 · 가운데 · 끝 가운데 어느 자리에 있는지 보지 않고 중심 내용을 찾거나, 제목에서 짐작할 수 있는 것을 놓친다','자리부터 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X32','kor',6,'u4',ARRAY['K6-1-u4-C32']::text[],'견학 기록문을 쓰면 좋은 점을 글씨 연습이나 외운 낱말 개수 늘리기로 여긴다','남기고 · 전하고 · 도움') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X33','kor',6,'u4',ARRAY['K6-1-u4-C33']::text[],'왜 기억에 남는지 살피지 않고 쓸 견학을 고른다','까닭이 곧 감상') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X34','kor',6,'u4',ARRAY['K6-1-u4-C34']::text[],'읽을 사람을 생각하지 않고 누구에게나 같은 낱말 · 같은 설명으로 쓴다','누가 읽나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X35','kor',6,'u4',ARRAY['K6-1-u4-C35']::text[],'가운데에 본 것만 늘어놓고 느낀 것을 짝짓지 않거나, 생각그물 단계에서부터 순서를 맞추느라 재료를 모으지 못한다','본 것 하나에 느낀 것 하나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X36','kor',6,'u4',ARRAY['K6-1-u4-C36']::text[],'관용 표현을 사실을 전하는 견문 자리에 얹는다','관용 표현은 마음 쪽') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X37','kor',6,'u4',ARRAY['K6-1-u4-C37']::text[],'정해진 칸이나 개수를 다 채워야 한다고 여겨 담을 것이 없는 자리에도 억지로 써 넣는다','비워 두어도 돼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X38','kor',6,'u4',ARRAY['K6-1-u4-C38']::text[],'고쳐 쓸 때 글씨 모양이나 글의 길이를 살핀다','갈래가 갖출 것을 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X39','kor',6,'u4',ARRAY['K6-1-u4-C38']::text[],'읽을 사람이 실제로 읽을 수 없는 방법으로 글을 나눈다(서랍에 넣어 둠)','정말 읽을 수 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X40','kor',6,'u4',ARRAY['K6-1-u4-C41']::text[],'관용 표현 사전에 아무도 모르는 어려운 표현을 많이 채울수록 좋은 사전이라고 여긴다','내가 쓸 자리가 떠오르나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X41','kor',6,'u4',ARRAY['K6-1-u4-C40']::text[],'사전 한 장에 표현이 만들어진 때나 아는 친구의 수처럼 꺼내 쓰는 데 쓸모없는 것을 담는다','표현 · 뜻 · 쓸 상황') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X42','kor',6,'u4',ARRAY['K6-1-u4-C42']::text[],'공식적인 말하기와 비공식적인 말하기에서 지킬 예절을 같다고 여긴다','자리와 듣는 사람이 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X43','kor',6,'u4',ARRAY['K6-1-u4-C42']::text[],'언어 예절을 상황과 상관없이 외울 목록으로 여기거나, 말의 내용만 지키면 목소리 · 표정 · 자세는 상관없다고 여긴다','편하게 들을 수 있나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u4-X44','kor',6,'u4',ARRAY['K6-1-u4-C39']::text[],'관용 표현을 낱말이나 마음으로 묶지 않고 흩어 두거나, 두 묶는 방법이 무엇에 좋은지 헷갈린다','찾기 쉬움 · 쓰기 쉬움') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L01_basic#1','kor',6,1,'u4','L01','g6_1_kor_u4_L01_basic','lesson_basic','K6-1-u4-C1',1,'mc','auto','「관용 표현」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X05','K6-1-u4-X15']::text[],false,'{"seq":1,"concept":"K6-1-u4-C1","difficulty":1,"kind":"mc","stem":"「관용 표현」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"오래 쓰이며 굳어져 낱말 뜻의 합과는 다른 새로운 뜻을 지닌 말","correct":true},{"t":"사전에 실린 낱말을 뜻 그대로 이어 붙여 길게 늘인 말","mis":"K6-1-u4-X05"},{"t":"어려운 한자를 써서 뜻을 짧게 줄인 전문가의 말","mis":"K6-1-u4-X05"},{"t":"그 자리에서 처음 지어낸 재미있는 말","mis":"K6-1-u4-X15"}],"explanation":["뜻 그대로 이은 말이 아니에요.","전문가의 말도 아니에요.","오래 쓰여 굳어진 새로운 뜻의 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L01_basic#2','kor',6,1,'u4','L01','g6_1_kor_u4_L01_basic','lesson_basic','K6-1-u4-C2',1,'mc','auto','다음 가운데 관용 표현은 어느 것인가요?',ARRAY['K6-1-u4-X02']::text[],false,'{"seq":2,"concept":"K6-1-u4-C2","difficulty":1,"kind":"mc","stem":"다음 가운데 관용 표현은 어느 것인가요?","options":[{"t":"눈코 뜰 새 없다","correct":true},{"t":"가방을 열다","mis":"K6-1-u4-X02"},{"t":"창문을 닦다","mis":"K6-1-u4-X02"},{"t":"물을 마시다","mis":"K6-1-u4-X02"}],"explanation":["가방을 연다는 말은 뜻 그대로예요.","창문을 닦는 것도 뜻 그대로예요.","눈코 뜰 새 없다는 「몹시 바쁘다」는 새 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L01_basic#3','kor',6,1,'u4','L01','g6_1_kor_u4_L01_basic','lesson_basic','K6-1-u4-C3',1,'ox','auto','관용어와 속담을 묶어 관용 표현이라고 해요.',ARRAY['K6-1-u4-X04']::text[],false,'{"seq":3,"concept":"K6-1-u4-C3","difficulty":1,"kind":"ox","stem":"관용어와 속담을 묶어 관용 표현이라고 해요.","answer":"O","reason_options":[{"t":"둘 다 오래 쓰이며 굳어진 말이기 때문에","correct":true},{"t":"속담은 관용 표현에 들지 않기 때문에","mis":"K6-1-u4-X04"}],"mis":"K6-1-u4-X04","explanation":["관용어도 굳어진 말이에요.","속담도 굳어진 말이에요.","둘을 묶어 관용 표현이라고 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L01_basic#4','kor',6,1,'u4','L01','g6_1_kor_u4_L01_basic','lesson_basic','K6-1-u4-C1',1,'match','auto','관용 표현과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K6-1-u4-C1","difficulty":1,"kind":"match","stem":"관용 표현과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"입을 모으다","r":"여럿이 같은 말을 하다"},{"l":"어깨가 무겁다","r":"책임이 커서 마음이 무겁다"},{"l":"눈코 뜰 새 없다","r":"몹시 바쁘다"}],"mis":"K6-1-u4-X01","explanation":["정말 입을 모은 것이 아니에요.","어깨에 짐을 올린 것도 아니에요.","낱말 뜻의 합과 다른 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L01_basic#5','kor',6,1,'u4','L01','g6_1_kor_u4_L01_basic','lesson_basic','K6-1-u4-C4',2,'mc','auto','관용 표현을 쓰면 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X07','K6-1-u4-X01','K6-1-u4-X05']::text[],false,'{"seq":5,"concept":"K6-1-u4-C4","difficulty":2,"kind":"mc","stem":"관용 표현을 쓰면 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"길게 설명할 말을 짧은 한마디로 전할 수 있다","correct":true},{"t":"표현을 많이 넣을수록 글이 저절로 좋아진다","mis":"K6-1-u4-X07"},{"t":"낱말 뜻 그대로라 누구나 풀이 없이 안다","mis":"K6-1-u4-X01"},{"t":"어려운 말이라 듣는 사람을 놀라게 한다","mis":"K6-1-u4-X05"}],"explanation":["많이 넣는다고 좋아지지 않아요.","낱말 뜻 그대로가 아니에요.","짧은 한마디로 긴 말을 대신해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L01_basic#6','kor',6,1,'u4','L01','g6_1_kor_u4_L01_basic','lesson_basic','K6-1-u4-C5',2,'mc','auto','「눈코 뜰 새 없다」를 바르게 쓴 문장은 어느 것인가요?',ARRAY['K6-1-u4-X06']::text[],false,'{"seq":6,"concept":"K6-1-u4-C5","difficulty":2,"kind":"mc","stem":"「눈코 뜰 새 없다」를 바르게 쓴 문장은 어느 것인가요?","options":[{"t":"「시험 준비로 눈코 뜰 새 없었다.」","correct":true},{"t":"「눈을 뜨고 코도 뜰 새가 없었다.」","mis":"K6-1-u4-X06"},{"t":"「눈과 코를 모두 뜰 새가 없었다.」","mis":"K6-1-u4-X06"},{"t":"「귀코 뜰 새 없었다.」","mis":"K6-1-u4-X06"}],"explanation":["낱말을 풀어 늘이면 뜻이 사라져요.","낱말을 바꿔도 뜻을 잃어요.","굳어진 모양 그대로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L01_basic#7','kor',6,1,'u4','L01','g6_1_kor_u4_L01_basic','lesson_basic','K6-1-u4-C6',2,'ox','auto','관용 표현을 많이 넣을수록 좋은 글이 돼요.',ARRAY['K6-1-u4-X07']::text[],false,'{"seq":7,"concept":"K6-1-u4-C6","difficulty":2,"kind":"ox","stem":"관용 표현을 많이 넣을수록 좋은 글이 돼요.","answer":"X","reason_options":[{"t":"상황과 어긋난 표현이 섞이면 오히려 뜻이 흐려지기 때문에","correct":true},{"t":"표현이 많으면 그만큼 생생해지기 때문에","mis":"K6-1-u4-X07"}],"mis":"K6-1-u4-X07","explanation":["개수가 먼저가 아니에요.","어긋난 표현은 뜻을 흐려요.","상황에 어울리는 하나가 힘이 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L01_basic#8','kor',6,1,'u4','L01','g6_1_kor_u4_L01_basic','lesson_basic','K6-1-u4-C7',2,'mc','auto','관용 표현을 상황에 알맞게 쓴 것은 어느 것인가요?',ARRAY['K6-1-u4-X08']::text[],false,'{"seq":8,"concept":"K6-1-u4-C7","difficulty":2,"kind":"mc","stem":"관용 표현을 상황에 알맞게 쓴 것은 어느 것인가요?","options":[{"t":"「처음 심은 씨앗이 바로 열매를 맺진 않아. 첫술에 배부르랴.」","correct":true},{"t":"생일을 맞은 친구에게 「오늘은 정말 진땀을 뺐겠구나.」","mis":"K6-1-u4-X08"},{"t":"비밀을 다 말해 버린 친구에게 「너는 참 입이 무거워.」","mis":"K6-1-u4-X08"},{"t":"한가한 주말에 「눈코 뜰 새 없이 쉬었다.」","mis":"K6-1-u4-X08"}],"explanation":["생일 축하와 진땀은 어긋나요.","비밀을 말한 친구는 입이 무겁지 않아요.","뜻과 상황이 맞물려야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L01_basic#9','kor',6,1,'u4','L01','g6_1_kor_u4_L01_basic','lesson_basic','K6-1-u4-C1',2,'mc','auto','다솔이가 말한 「어깨가 무겁겠다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X01','K6-1-u4-X20']::text[],false,'{"seq":9,"concept":"K6-1-u4-C1","difficulty":2,"kind":"mc","stem":"다솔이가 말한 「어깨가 무겁겠다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"당번을 맡은 책임이 커서 마음이 무겁겠다","correct":true},{"t":"물통을 들어 어깨가 아프겠다","mis":"K6-1-u4-X01"},{"t":"어깨에 짐을 올려 무게가 늘겠다","mis":"K6-1-u4-X01"},{"t":"다들 아라를 믿지 않겠다","mis":"K6-1-u4-X20"}],"explanation":["실제 어깨 이야기가 아니에요.","짐을 올린 것도 아니에요.","믿고 맡긴 만큼 책임이 커요."],"asset":{"type":"speech","turns":[{"who":"아라","text":"텃밭 물주기 당번을 누가 맡을지 정하는데, 다들 나를 하라고 입을 모으더라."},{"who":"다솔","text":"그만큼 믿는다는 뜻이지. 그래도 어깨가 무겁겠다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L01_basic#10','kor',6,1,'u4','L01','g6_1_kor_u4_L01_basic','lesson_basic','K6-1-u4-C3',3,'mc','auto','관용어와 속담을 가르는 기준으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X04','K6-1-u4-X03']::text[],false,'{"seq":10,"concept":"K6-1-u4-C3","difficulty":3,"kind":"mc","stem":"관용어와 속담을 가르는 기준으로 알맞은 것은 어느 것인가요?","options":[{"t":"예로부터 전해 오며 지혜나 교훈을 담고 있는가","correct":true},{"t":"낱말이 두 개 이상 들어 있는가","mis":"K6-1-u4-X04"},{"t":"몸을 가리키는 말이 들어 있는가","mis":"K6-1-u4-X03"},{"t":"글자 수가 많은가","mis":"K6-1-u4-X04"}],"explanation":["관용어도 낱말이 여럿이에요.","몸 낱말은 가르는 기준이 아니에요.","교훈을 담고 전해 오면 속담이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L01_challenge#1','kor',6,1,'u4','L01','g6_1_kor_u4_L01_challenge','lesson_challenge','K6-1-u4-C2',2,'mc','auto','다음 가운데 관용 표현이 아닌 것은 어느 것인가요?',ARRAY['K6-1-u4-X01']::text[],false,'{"seq":1,"concept":"K6-1-u4-C2","difficulty":2,"kind":"mc","stem":"다음 가운데 관용 표현이 아닌 것은 어느 것인가요?","options":[{"t":"창문을 닦다","correct":true},{"t":"입이 무겁다","mis":"K6-1-u4-X01"},{"t":"진땀을 빼다","mis":"K6-1-u4-X01"},{"t":"입을 모으다","mis":"K6-1-u4-X01"}],"explanation":["입이 무겁다는 말이 신중하다는 뜻이에요.","진땀을 빼다는 몹시 애를 쓴다는 뜻이에요.","창문을 닦다는 뜻 그대로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L01_challenge#2','kor',6,1,'u4','L01','g6_1_kor_u4_L01_challenge','lesson_challenge','K6-1-u4-C5',2,'ox','auto','「어깨가 무겁다」를 「두 어깨가 아주 무겁다」로 바꿔 써도 뜻이 같아요.',ARRAY['K6-1-u4-X06']::text[],false,'{"seq":2,"concept":"K6-1-u4-C5","difficulty":2,"kind":"ox","stem":"「어깨가 무겁다」를 「두 어깨가 아주 무겁다」로 바꿔 써도 뜻이 같아요.","answer":"X","reason_options":[{"t":"관용 표현은 통째로 굳은 말이라 낱말을 바꾸거나 늘이면 뜻을 잃기 때문에","correct":true},{"t":"낱말 뜻만 같으면 모양은 바꿔도 되기 때문에","mis":"K6-1-u4-X06"}],"mis":"K6-1-u4-X06","explanation":["낱말을 더하면 모양이 달라져요.","모양이 달라지면 굳은 뜻이 사라져요.","모양 그대로 익혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L01_challenge#3','kor',6,1,'u4','L01','g6_1_kor_u4_L01_challenge','lesson_challenge','K6-1-u4-C3',3,'mc','auto','다음 가운데 속담은 어느 것인가요?',ARRAY['K6-1-u4-X04']::text[],false,'{"seq":3,"concept":"K6-1-u4-C3","difficulty":3,"kind":"mc","stem":"다음 가운데 속담은 어느 것인가요?","options":[{"t":"빈 수레가 요란하다","correct":true},{"t":"입이 무겁다","mis":"K6-1-u4-X04"},{"t":"진땀을 빼다","mis":"K6-1-u4-X04"},{"t":"눈코 뜰 새 없다","mis":"K6-1-u4-X04"}],"explanation":["입이 무겁다는 관용어예요.","진땀을 빼다도 관용어예요.","교훈을 담고 전해 오는 말이 속담이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L01_challenge#4','kor',6,1,'u4','L01','g6_1_kor_u4_L01_challenge','lesson_challenge','K6-1-u4-C6',3,'error','auto','관용 표현에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u4-X07','K6-1-u4-X06']::text[],false,'{"seq":4,"concept":"K6-1-u4-C6","difficulty":3,"kind":"error","stem":"관용 표현에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"누리 — 「관용 표현은 많이 넣을수록 글이 좋아져.」","correct":true,"mis_target":"K6-1-u4-X07"},{"t":"다온 — 「상황에 어울리는 하나를 놓는 게 중요해.」","mis":"K6-1-u4-X07"},{"t":"시우 — 「굳어진 모양 그대로 써야 뜻이 살아.」","mis":"K6-1-u4-X06"}],"explanation":["다온이는 바르게 말했어요.","시우도 바르게 말했어요.","개수보다 어울림이 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L01_challenge#5','kor',6,1,'u4','L01','g6_1_kor_u4_L01_challenge','lesson_challenge','K6-1-u4-C4',3,'mc','auto','「책임이 커서 마음이 무겁다」 대신 「어깨가 무겁다」라고 말하면 좋아지는 점은 어느 것인가요?',ARRAY['K6-1-u4-X01','K6-1-u4-X09','K6-1-u4-X05']::text[],false,'{"seq":5,"concept":"K6-1-u4-C4","difficulty":3,"kind":"mc","stem":"「책임이 커서 마음이 무겁다」 대신 「어깨가 무겁다」라고 말하면 좋아지는 점은 어느 것인가요?","options":[{"t":"짧은 한마디로 전하면서 듣는 사람이 장면을 떠올리게 된다","correct":true},{"t":"뜻이 사전과 달라져 더 정확해진다","mis":"K6-1-u4-X01"},{"t":"말이 길어져 더 공손해진다","mis":"K6-1-u4-X09"},{"t":"어려워 보여 똑똑해 보인다","mis":"K6-1-u4-X05"}],"explanation":["뜻이 달라지는 것이 아니에요.","말은 오히려 짧아져요.","짧고 생생하게 전해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L01_challenge#6','kor',6,1,'u4','L01','g6_1_kor_u4_L01_challenge','lesson_challenge','K6-1-u4-C7',3,'mc','auto','「진땀을 빼다」를 알맞게 쓸 수 있는 상황은 어느 것인가요?',ARRAY['K6-1-u4-X08','K6-1-u4-X01']::text[],false,'{"seq":6,"concept":"K6-1-u4-C7","difficulty":3,"kind":"mc","stem":"「진땀을 빼다」를 알맞게 쓸 수 있는 상황은 어느 것인가요?","options":[{"t":"준비가 부족한 채로 발표를 겨우 마쳤을 때","correct":true},{"t":"친구의 생일을 축하할 때","mis":"K6-1-u4-X08"},{"t":"더운 날 운동장에서 땀을 흘렸을 때","mis":"K6-1-u4-X01"},{"t":"비밀을 잘 지키는 친구를 칭찬할 때","mis":"K6-1-u4-X08"}],"explanation":["축하하는 자리와 어긋나요.","실제로 땀을 흘린 이야기가 아니에요.","몹시 애쓴 상황에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L01_challenge#7','kor',6,1,'u4','L01','g6_1_kor_u4_L01_challenge','lesson_challenge','K6-1-u4-C1',3,'mc','auto','「입을 모으다」의 뜻이 바르게 살아난 문장은 어느 것인가요?',ARRAY['K6-1-u4-X01','K6-1-u4-X08']::text[],false,'{"seq":7,"concept":"K6-1-u4-C1","difficulty":3,"kind":"mc","stem":"「입을 모으다」의 뜻이 바르게 살아난 문장은 어느 것인가요?","options":[{"t":"「반 친구들이 입을 모아 다솔이를 칭찬했다.」","correct":true},{"t":"「사진을 찍으려고 입술을 동그랗게 입을 모았다.」","mis":"K6-1-u4-X01"},{"t":"「혼자서 입을 모아 말했다.」","mis":"K6-1-u4-X08"},{"t":"「입을 모으면 입이 작아진다.」","mis":"K6-1-u4-X01"}],"explanation":["입술을 오므린 이야기가 아니에요.","혼자서는 입을 모을 수 없어요.","여럿이 같은 말을 한다는 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L01_challenge#8','kor',6,1,'u4','L01','g6_1_kor_u4_L01_challenge','lesson_challenge','K6-1-u4-C6',4,'mc','auto','아라가 쓴 텃밭 일기를 가장 알맞게 고친 것은 어느 것인가요?',ARRAY['K6-1-u4-X07','K6-1-u4-X06']::text[],false,'{"seq":8,"concept":"K6-1-u4-C6","difficulty":4,"kind":"mc","stem":"아라가 쓴 텃밭 일기를 가장 알맞게 고친 것은 어느 것인가요?","options":[{"t":"어울리지 않는 표현은 덜어 내고, 마음이 가장 크게 움직인 자리에 꼭 맞는 하나만 남긴다","correct":true},{"t":"관용 표현을 하나 더 넣어 더 생생하게 만든다","mis":"K6-1-u4-X07"},{"t":"관용 표현을 모두 낱말 뜻대로 풀어 늘인다","mis":"K6-1-u4-X06"},{"t":"표현이 많아 좋은 글이니 그대로 둔다","mis":"K6-1-u4-X07"}],"explanation":["더 넣으면 더 흐려져요.","풀어 늘이면 뜻을 잃어요.","제자리에 하나면 충분해요."],"asset":{"type":"passage","lines":["오늘 텃밭에 물을 주었다. 다들 나를 당번으로 하자고 입을 모았다.","물뿌리개를 드니 눈코 뜰 새 없이 무거웠다.","진땀을 빼며 어깨가 무겁게 물을 주고, 입이 무겁게 집에 왔다."],"title":"아라가 쓴 텃밭 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L01_challenge#9','kor',6,1,'u4','L01','g6_1_kor_u4_L01_challenge','lesson_challenge','K6-1-u4-C1',4,'essay','teacher','「입을 모으다」와 「가방을 열다」를 견주어, 무엇이 관용 표현이고 왜 그런지 설명하세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u4-C1","difficulty":4,"kind":"essay","stem":"「입을 모으다」와 「가방을 열다」를 견주어, 무엇이 관용 표현이고 왜 그런지 설명하세요.","answer_guide":{"answer":"예: 「입을 모으다」는 관용 표현이다. 실제로 입을 모은 것이 아니라 여럿이 같은 말을 한다는 새로운 뜻이 있기 때문이다. 「가방을 열다」는 가방을 연다는 낱말 뜻 그대로라서 관용 표현이 아니다.","scoring_points":["「입을 모으다」를 관용 표현으로 골랐는가","낱말 뜻의 합과 다른 새로운 뜻이라는 까닭을 썼는가","「가방을 열다」가 뜻 그대로라는 점을 견주어 썼는가"]},"explanation":["두 말을 뜻 그대로 읽어 봐요.","뜻이 달라지는 쪽을 찾아요.","까닭을 견주어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L01_challenge#10','kor',6,1,'u4','L01','g6_1_kor_u4_L01_challenge','lesson_challenge','K6-1-u4-C6',4,'essay','teacher','「관용 표현을 쓰는 것이 언제나 효과적인 것은 아니다」라는 말을 예를 들어 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u4-C6","difficulty":4,"kind":"essay","stem":"「관용 표현을 쓰는 것이 언제나 효과적인 것은 아니다」라는 말을 예를 들어 설명하세요.","answer_guide":{"answer":"예: 관용 표현은 상황에 맞을 때만 힘이 생긴다. 생일을 맞은 친구에게 「진땀을 뺐겠구나」라고 하면 뜻이 어긋나 어색해진다. 또 한 글에 관용 표현을 여러 개 넣으면 오히려 뜻이 흐려진다. 그래서 개수보다 지금 상황에 어울리는 표현인지를 먼저 살펴야 한다.","scoring_points":["상황에 맞을 때만 효과가 있다는 점을 썼는가","어긋나게 쓴 예를 들었는가","개수보다 어울림이 먼저라는 점을 썼는가"]},"explanation":["어긋난 예를 떠올려요.","많이 넣었을 때를 떠올려요.","먼저 볼 것을 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L02_basic#1','kor',6,1,'u4','L02','g6_1_kor_u4_L02_basic','lesson_basic','K6-1-u4-C8',1,'mc','auto','대화 속 관용어의 뜻을 처음 알아볼 때 먼저 할 일은 어느 것인가요?',ARRAY['K6-1-u4-X10','K6-1-u4-X01']::text[],false,'{"seq":1,"concept":"K6-1-u4-C8","difficulty":1,"kind":"mc","stem":"대화 속 관용어의 뜻을 처음 알아볼 때 먼저 할 일은 어느 것인가요?","options":[{"t":"앞뒤 상황을 보고 뜻을 짐작해 본다","correct":true},{"t":"짐작하지 말고 사전부터 편다","mis":"K6-1-u4-X10"},{"t":"뜻을 모르면 그냥 넘어간다","mis":"K6-1-u4-X10"},{"t":"낱말 뜻을 그대로 더해 읽는다","mis":"K6-1-u4-X01"}],"explanation":["사전은 짐작한 뒤에 펴요.","모르면 짐작부터 해 봐요.","앞뒤 상황이 실마리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L02_basic#2','kor',6,1,'u4','L02','g6_1_kor_u4_L02_basic','lesson_basic','K6-1-u4-C9',1,'mc','auto','「걱정 붙들어 매다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X01']::text[],false,'{"seq":2,"concept":"K6-1-u4-C9","difficulty":1,"kind":"mc","stem":"「걱정 붙들어 매다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"걱정하지 말라고 안심시키다","correct":true},{"t":"걱정거리를 끈으로 꽁꽁 묶어 두다","mis":"K6-1-u4-X01"},{"t":"걱정을 오래 붙잡고 놓지 않다","mis":"K6-1-u4-X01"},{"t":"걱정거리를 남에게 넘기다","mis":"K6-1-u4-X01"}],"explanation":["끈으로 묶는 이야기가 아니에요.","걱정을 붙잡는 것도 아니에요.","안심하라는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L02_basic#3','kor',6,1,'u4','L02','g6_1_kor_u4_L02_basic','lesson_basic','K6-1-u4-C12',1,'mc','auto','다음 가운데 「입」이 들어간 관용어는 어느 것인가요?',ARRAY['K6-1-u4-X03']::text[],false,'{"seq":3,"concept":"K6-1-u4-C12","difficulty":1,"kind":"mc","stem":"다음 가운데 「입」이 들어간 관용어는 어느 것인가요?","options":[{"t":"입이 무겁다","correct":true},{"t":"입을 헹구다","mis":"K6-1-u4-X03"},{"t":"입을 벌려 하품하다","mis":"K6-1-u4-X03"},{"t":"입에 밥을 넣다","mis":"K6-1-u4-X03"}],"explanation":["입을 헹구는 것은 뜻 그대로예요.","하품도 뜻 그대로예요.","말이 신중하다는 새 뜻이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L02_basic#4','kor',6,1,'u4','L02','g6_1_kor_u4_L02_basic','lesson_basic','K6-1-u4-C9',1,'ox','auto','관용어는 뜻만 외우면 충분해요.',ARRAY['K6-1-u4-X11']::text[],false,'{"seq":4,"concept":"K6-1-u4-C9","difficulty":1,"kind":"ox","stem":"관용어는 뜻만 외우면 충분해요.","answer":"X","reason_options":[{"t":"어떤 상황에서 쓰는 말인지까지 붙여 두어야 내 말이 되기 때문에","correct":true},{"t":"뜻을 알면 쓸 상황은 저절로 떠오르기 때문에","mis":"K6-1-u4-X11"}],"mis":"K6-1-u4-X11","explanation":["뜻만 외우면 금방 잊어요.","쓸 상황을 함께 붙여요.","그래야 내 말이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L02_basic#5','kor',6,1,'u4','L02','g6_1_kor_u4_L02_basic','lesson_basic','K6-1-u4-C10',2,'mc','auto','다솔이가 예솔이를 두고 「귀가 밝다」고 한 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X12','K6-1-u4-X01']::text[],false,'{"seq":5,"concept":"K6-1-u4-C10","difficulty":2,"kind":"mc","stem":"다솔이가 예솔이를 두고 「귀가 밝다」고 한 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"소식이나 정보를 남보다 빨리 알아챈다","correct":true},{"t":"작은 소리도 잘 듣는 귀를 가졌다","mis":"K6-1-u4-X12"},{"t":"귀가 하얗고 깨끗하다","mis":"K6-1-u4-X12"},{"t":"들은 말을 함부로 옮긴다","mis":"K6-1-u4-X01"}],"explanation":["뒤에 이어진 말을 봐요.","귀의 생김새 이야기가 아니에요.","누가 무엇을 어디에 뒀는지 다 안다고 했어요."],"asset":{"type":"speech","turns":[{"who":"아라","text":"체육관 열쇠를 분명히 가방에 넣었는데 없어. 점심시간이 다 가는데 어쩌지."},{"who":"다솔","text":"예솔이한테 물어보자. 그 애는 귀가 밝아서, 누가 뭘 어디에 뒀다는 말은 다 듣고 있거든."},{"who":"예솔","text":"아침에 선생님이 교무실 서랍에 넣어 두셨다고 하셨어. 걱정 붙들어 매."},{"who":"아라","text":"휴, 이제야 마음이 놓인다. 아침 내내 진땀을 뺐어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L02_basic#6','kor',6,1,'u4','L02','g6_1_kor_u4_L02_basic','lesson_basic','K6-1-u4-C9',2,'match','auto','상황에 어울리는 관용어를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-1-u4-C9","difficulty":2,"kind":"match","stem":"상황에 어울리는 관용어를 알맞게 이으세요.","pairs":[{"l":"불안해하는 동생을 안심시킬 때","r":"걱정 붙들어 매"},{"l":"학급 대표를 맡아 부담이 클 때","r":"어깨가 무겁다"},{"l":"할 일이 몰려 쉴 틈이 없을 때","r":"눈코 뜰 새 없다"}],"mis":"K6-1-u4-X08","explanation":["안심시키는 말을 찾아요.","책임이 큰 마음을 찾아요.","몹시 바쁜 마음을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L02_basic#7','kor',6,1,'u4','L02','g6_1_kor_u4_L02_basic','lesson_basic','K6-1-u4-C11',2,'mc','auto','학교 방송 뉴스의 「눈코 뜰 새 없이」가 전하려는 것은 어느 것인가요?',ARRAY['K6-1-u4-X08','K6-1-u4-X12','K6-1-u4-X13']::text[],false,'{"seq":7,"concept":"K6-1-u4-C11","difficulty":2,"kind":"mc","stem":"학교 방송 뉴스의 「눈코 뜰 새 없이」가 전하려는 것은 어느 것인가요?","options":[{"t":"준비할 일이 많아 쉴 틈 없이 바쁘게 움직인다","correct":true},{"t":"준비가 끝나 여유롭게 기다리고 있다","mis":"K6-1-u4-X08"},{"t":"눈과 코가 아픈 학생이 많다","mis":"K6-1-u4-X12"},{"t":"방송에서는 관용어를 쓰면 안 된다","mis":"K6-1-u4-X13"}],"explanation":["여유로운 것과 반대예요.","눈과 코의 이야기가 아니에요.","얼마나 바쁜지를 한마디로 전했어요."],"asset":{"type":"passage","lines":["학교 방송 뉴스 — 「체육 대회 준비로 우리 학년 전체가","눈코 뜰 새 없이 움직이고 있습니다. 지금까지 방송실에서 전해 드렸습니다.」","학급 알림장 — 「도서 반납일이 지난 책이 많습니다.","반납만 하면 되니 걱정 붙들어 매고 내일까지 가져오세요.」"],"title":"매체 속 관용어"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L02_basic#8','kor',6,1,'u4','L02','g6_1_kor_u4_L02_basic','lesson_basic','K6-1-u4-C11',2,'ox','auto','학급 알림장처럼 글로 전하는 매체에는 관용어를 쓸 수 없어요.',ARRAY['K6-1-u4-X13']::text[],false,'{"seq":8,"concept":"K6-1-u4-C11","difficulty":2,"kind":"ox","stem":"학급 알림장처럼 글로 전하는 매체에는 관용어를 쓸 수 없어요.","answer":"X","reason_options":[{"t":"매체가 달라도 관용어는 뜻을 짧고 또렷하게 만드는 같은 일을 하기 때문에","correct":true},{"t":"관용어는 말로 할 때만 쓰는 표현이기 때문에","mis":"K6-1-u4-X13"}],"mis":"K6-1-u4-X13","explanation":["알림장에도 관용어가 놓였어요.","말로도 글로도 써요.","하는 일은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L02_basic#9','kor',6,1,'u4','L02','g6_1_kor_u4_L02_basic','lesson_basic','K6-1-u4-C13',2,'mc','auto','「귀가 밝다」의 뜻을 국어사전에서 찾을 때 알맞은 방법은 어느 것인가요?',ARRAY['K6-1-u4-X14']::text[],false,'{"seq":9,"concept":"K6-1-u4-C13","difficulty":2,"kind":"mc","stem":"「귀가 밝다」의 뜻을 국어사전에서 찾을 때 알맞은 방법은 어느 것인가요?","options":[{"t":"중심이 되는 낱말 「귀」를 찾아 뜻풀이 아래쪽에 딸린 관용구를 본다","correct":true},{"t":"「귀가 밝다」 문장 전체를 한 번에 찾는다","mis":"K6-1-u4-X14"},{"t":"사전의 첫 쪽부터 차례로 넘겨 본다","mis":"K6-1-u4-X14"},{"t":"아무 낱말이나 먼저 눈에 띄는 것을 찾는다","mis":"K6-1-u4-X14"}],"explanation":["문장 전체로는 찾기 어려워요.","첫 쪽부터 넘기면 오래 걸려요.","중심 낱말을 앞세워 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L02_basic#10','kor',6,1,'u4','L02','g6_1_kor_u4_L02_basic','lesson_basic','K6-1-u4-C10',3,'mc','auto','몸을 가리키는 말이 든 관용어가 나타내는 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X12']::text[],false,'{"seq":10,"concept":"K6-1-u4-C10","difficulty":3,"kind":"mc","stem":"몸을 가리키는 말이 든 관용어가 나타내는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"눈에 보이는 몸으로 눈에 보이지 않는 마음이나 태도를 나타낸다","correct":true},{"t":"몸이 아프거나 다친 상태를 알려 준다","mis":"K6-1-u4-X12"},{"t":"몸의 생김새를 자세히 그려 준다","mis":"K6-1-u4-X12"},{"t":"몸을 움직이는 운동 방법을 알려 준다","mis":"K6-1-u4-X12"}],"explanation":["몸 상태 이야기가 아니에요.","생김새도 아니에요.","마음과 태도를 몸으로 나타내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L02_challenge#1','kor',6,1,'u4','L02','g6_1_kor_u4_L02_challenge','lesson_challenge','K6-1-u4-C12',2,'mc','auto','다음 가운데 「어깨」가 들어간 관용어가 아닌 것은 어느 것인가요?',ARRAY['K6-1-u4-X01']::text[],false,'{"seq":1,"concept":"K6-1-u4-C12","difficulty":2,"kind":"mc","stem":"다음 가운데 「어깨」가 들어간 관용어가 아닌 것은 어느 것인가요?","options":[{"t":"어깨를 주무르다","correct":true},{"t":"어깨가 무겁다","mis":"K6-1-u4-X01"},{"t":"어깨를 나란히 하다","mis":"K6-1-u4-X01"},{"t":"어깨가 처지다","mis":"K6-1-u4-X01"}],"explanation":["어깨가 무겁다는 책임이 크다는 뜻이에요.","어깨를 나란히 하다는 비슷한 힘을 지닌다는 뜻이에요.","어깨를 주무르는 것은 뜻 그대로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L02_challenge#2','kor',6,1,'u4','L02','g6_1_kor_u4_L02_challenge','lesson_challenge','K6-1-u4-C8',2,'ox','auto','관용어의 뜻을 정확히 모르면 짐작하지 말고 넘어가야 해요.',ARRAY['K6-1-u4-X10']::text[],false,'{"seq":2,"concept":"K6-1-u4-C8","difficulty":2,"kind":"ox","stem":"관용어의 뜻을 정확히 모르면 짐작하지 말고 넘어가야 해요.","answer":"X","reason_options":[{"t":"앞뒤 상황을 보고 짐작한 뒤 사전에서 확인하면 뜻이 오래 남기 때문에","correct":true},{"t":"틀리게 짐작하면 안 되기 때문에","mis":"K6-1-u4-X10"}],"mis":"K6-1-u4-X10","explanation":["정확히 몰라도 괜찮아요.","짐작부터 시작해요.","짐작한 뒤 사전으로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L02_challenge#3','kor',6,1,'u4','L02','g6_1_kor_u4_L02_challenge','lesson_challenge','K6-1-u4-C8',3,'mc','auto','예솔이가 말한 「걱정 붙들어 매」의 뜻을 짐작하는 실마리로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X01','K6-1-u4-X10']::text[],false,'{"seq":3,"concept":"K6-1-u4-C8","difficulty":3,"kind":"mc","stem":"예솔이가 말한 「걱정 붙들어 매」의 뜻을 짐작하는 실마리로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"예솔이가 열쇠가 있는 곳을 알려 준 다음에 이 말을 했다는 점","correct":true},{"t":"「붙들어 매다」를 낱말 뜻 그대로 풀어 본 것","mis":"K6-1-u4-X01"},{"t":"대화에 나온 사람이 몇 명인지","mis":"K6-1-u4-X10"},{"t":"사전을 펴 보기 전에는 실마리가 없다는 점","mis":"K6-1-u4-X10"}],"explanation":["낱말 뜻대로는 풀리지 않아요.","사람 수는 실마리가 아니에요.","앞뒤 상황이 실마리예요."],"asset":{"type":"speech","turns":[{"who":"아라","text":"체육관 열쇠를 분명히 가방에 넣었는데 없어. 점심시간이 다 가는데 어쩌지."},{"who":"다솔","text":"예솔이한테 물어보자. 그 애는 귀가 밝아서, 누가 뭘 어디에 뒀다는 말은 다 듣고 있거든."},{"who":"예솔","text":"아침에 선생님이 교무실 서랍에 넣어 두셨다고 하셨어. 걱정 붙들어 매."},{"who":"아라","text":"휴, 이제야 마음이 놓인다. 아침 내내 진땀을 뺐어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L02_challenge#4','kor',6,1,'u4','L02','g6_1_kor_u4_L02_challenge','lesson_challenge','K6-1-u4-C13',3,'error','auto','모르는 관용어를 찾는 방법을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u4-X10','K6-1-u4-X14']::text[],false,'{"seq":4,"concept":"K6-1-u4-C13","difficulty":3,"kind":"error","stem":"모르는 관용어를 찾는 방법을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"태오 — 「모르는 관용어가 나오면 짐작하지 말고 사전부터 펴야 해.」","correct":true,"mis_target":"K6-1-u4-X10"},{"t":"소윤 — 「중심 낱말을 찾고 뜻풀이 아래쪽 관용구를 봐.」","mis":"K6-1-u4-X14"},{"t":"이안 — 「짐작한 뜻과 사전의 뜻을 맞춰 봐.」","mis":"K6-1-u4-X10"}],"explanation":["소윤이는 찾는 방법을 바르게 말했어요.","이안이도 바르게 말했어요.","사전을 먼저 펴지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L02_challenge#5','kor',6,1,'u4','L02','g6_1_kor_u4_L02_challenge','lesson_challenge','K6-1-u4-C9',3,'mc','auto','「걱정 붙들어 매다」를 쓰기에 가장 알맞은 상황은 어느 것인가요?',ARRAY['K6-1-u4-X08','K6-1-u4-X01']::text[],false,'{"seq":5,"concept":"K6-1-u4-C9","difficulty":3,"kind":"mc","stem":"「걱정 붙들어 매다」를 쓰기에 가장 알맞은 상황은 어느 것인가요?","options":[{"t":"잃어버린 줄 알았던 공책을 찾았다고 불안해하는 짝에게 알려 줄 때","correct":true},{"t":"짝이 크게 다쳐 함께 걱정할 때","mis":"K6-1-u4-X08"},{"t":"이삿짐을 끈으로 묶을 때","mis":"K6-1-u4-X01"},{"t":"짝이 시험을 잘 봐 축하할 때","mis":"K6-1-u4-X08"}],"explanation":["함께 걱정하는 자리와 어긋나요.","끈으로 묶는 이야기가 아니에요.","안심시키는 자리에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L02_challenge#6','kor',6,1,'u4','L02','g6_1_kor_u4_L02_challenge','lesson_challenge','K6-1-u4-C11',3,'mc','auto','학급 알림장에서 「걱정 붙들어 매고」를 쓴 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X01','K6-1-u4-X20','K6-1-u4-X07']::text[],false,'{"seq":6,"concept":"K6-1-u4-C11","difficulty":3,"kind":"mc","stem":"학급 알림장에서 「걱정 붙들어 매고」를 쓴 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"반납만 하면 되니 부담 갖지 말라고 안심시키려고","correct":true},{"t":"책을 끈으로 묶어 가져오라고","mis":"K6-1-u4-X01"},{"t":"반납하지 않은 학생을 꾸짖으려고","mis":"K6-1-u4-X20"},{"t":"알림장에는 관용어를 꼭 넣어야 해서","mis":"K6-1-u4-X07"}],"explanation":["끈 이야기가 아니에요.","꾸짖는 말이 아니에요.","안심하고 가져오라는 뜻이에요."],"asset":{"type":"passage","lines":["학교 방송 뉴스 — 「체육 대회 준비로 우리 학년 전체가","눈코 뜰 새 없이 움직이고 있습니다. 지금까지 방송실에서 전해 드렸습니다.」","학급 알림장 — 「도서 반납일이 지난 책이 많습니다.","반납만 하면 되니 걱정 붙들어 매고 내일까지 가져오세요.」"],"title":"매체 속 관용어"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L02_challenge#7','kor',6,1,'u4','L02','g6_1_kor_u4_L02_challenge','lesson_challenge','K6-1-u4-C10',3,'match','auto','몸을 가리키는 말이 든 관용어와 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-1-u4-C10","difficulty":3,"kind":"match","stem":"몸을 가리키는 말이 든 관용어와 그 뜻을 알맞게 이으세요.","pairs":[{"l":"입이 무겁다","r":"말이 신중해 함부로 옮기지 않는다"},{"l":"입에 침이 마르다","r":"남을 거듭 칭찬하다"},{"l":"어깨를 나란히 하다","r":"서로 비슷한 힘을 지니다"}],"mis":"K6-1-u4-X12","explanation":["입이 실제로 무거운 것이 아니에요.","침이 정말 마른 것도 아니에요.","몸으로 마음과 태도를 나타냈어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L02_challenge#8','kor',6,1,'u4','L02','g6_1_kor_u4_L02_challenge','lesson_challenge','K6-1-u4-C12',4,'mc','auto','「귀」가 든 관용어 묶음을 만들 때 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X03','K6-1-u4-X01','K6-1-u4-X10']::text[],false,'{"seq":8,"concept":"K6-1-u4-C12","difficulty":4,"kind":"mc","stem":"「귀」가 든 관용어 묶음을 만들 때 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「귀가 밝다」와 「귀에 익다」는 넣고, 「귀를 씻다」는 뜻이 낱말 그대로라 뺀다","correct":true},{"t":"「귀」가 들었으니 셋 다 넣는다","mis":"K6-1-u4-X03"},{"t":"「귀를 씻다」만 넣고 나머지는 뺀다","mis":"K6-1-u4-X01"},{"t":"뜻을 모르는 것이 있으니 모두 뺀다","mis":"K6-1-u4-X10"}],"explanation":["낱말만 보고 넣지 않아요.","뜻 그대로인 말은 관용어가 아니에요.","낱말과 뜻을 함께 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L02_challenge#9','kor',6,1,'u4','L02','g6_1_kor_u4_L02_challenge','lesson_challenge','K6-1-u4-C8',4,'essay','teacher','「짐작 먼저, 사전은 나중」 순서로 관용어를 익히면 좋은 까닭을 쓰고, 「귀가 밝다」로 그 방법을 차례대로 설명하세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u4-C8","difficulty":4,"kind":"essay","stem":"「짐작 먼저, 사전은 나중」 순서로 관용어를 익히면 좋은 까닭을 쓰고, 「귀가 밝다」로 그 방법을 차례대로 설명하세요.","answer_guide":{"answer":"예: 먼저 짐작해 보고 사전으로 확인하면 내가 생각한 뜻과 견주게 되어 뜻이 오래 남는다. 「귀가 밝다」는 「누가 뭘 어디에 뒀다는 말은 다 듣고 있다」는 뒷말을 보고 소식을 빨리 안다는 뜻으로 짐작한다. 그다음 사전에서 「귀」를 찾아 뜻풀이 아래 관용구를 보고, 짐작한 뜻과 맞춰 본다.","scoring_points":["짐작 먼저 하면 좋은 까닭을 썼는가","앞뒤 상황으로 짐작하는 방법을 썼는가","중심 낱말로 사전에서 확인하는 순서를 썼는가"]},"explanation":["까닭을 먼저 써요.","앞뒤 말을 실마리로 써요.","사전 찾는 순서를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L02_challenge#10','kor',6,1,'u4','L02','g6_1_kor_u4_L02_challenge','lesson_challenge','K6-1-u4-C9',4,'essay','teacher','「입에 침이 마르다」의 뜻과 쓸 수 있는 상황을 쓰고, 내 경험이 드러나는 문장을 하나 지으세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u4-C9","difficulty":4,"kind":"essay","stem":"「입에 침이 마르다」의 뜻과 쓸 수 있는 상황을 쓰고, 내 경험이 드러나는 문장을 하나 지으세요.","answer_guide":{"answer":"예: 「입에 침이 마르다」는 남을 거듭 칭찬한다는 뜻이다. 누군가 한 일이 아주 좋아서 여러 번 칭찬할 때 쓴다. 지은 문장 — 「할머니께서는 내가 담근 김치가 맛있다고 입에 침이 마르게 칭찬하셨다.」","scoring_points":["뜻을 바르게 썼는가","쓸 수 있는 상황을 썼는가","내 경험이 드러나게 알맞은 문장을 지었는가"]},"explanation":["뜻을 먼저 써요.","쓸 상황을 붙여요.","내 경험으로 문장을 지어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L03_basic#1','kor',6,1,'u4','L03','g6_1_kor_u4_L03_basic','lesson_basic','K6-1-u4-C14',1,'mc','auto','「속담」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X15','K6-1-u4-X01']::text[],false,'{"seq":1,"concept":"K6-1-u4-C14","difficulty":1,"kind":"mc","stem":"「속담」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"예로부터 전해 오며 지혜나 교훈을 담은 말","correct":true},{"t":"그 자리에서 새로 지어낸 말","mis":"K6-1-u4-X15"},{"t":"낱말 뜻을 그대로 이은 말","mis":"K6-1-u4-X01"},{"t":"요즘 새로 생긴 줄임말","mis":"K6-1-u4-X15"}],"explanation":["지어낸 말이 아니에요.","뜻 그대로 이은 말도 아니에요.","예로부터 전해 오는 교훈의 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L03_basic#2','kor',6,1,'u4','L03','g6_1_kor_u4_L03_basic','lesson_basic','K6-1-u4-C15',1,'mc','auto','「첫술에 배부르랴」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X16']::text[],false,'{"seq":2,"concept":"K6-1-u4-C15","difficulty":1,"kind":"mc","stem":"「첫술에 배부르랴」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"무슨 일이든 한 번에 큰 성과를 얻기는 어렵다","correct":true},{"t":"밥은 첫 숟가락이 가장 맛있다","mis":"K6-1-u4-X16"},{"t":"처음부터 많이 먹어야 배가 부르다","mis":"K6-1-u4-X16"},{"t":"한 번 하면 무슨 일이든 다 끝난다","mis":"K6-1-u4-X16"}],"explanation":["밥맛 이야기가 아니에요.","많이 먹으라는 말도 아니에요.","첫 숟가락으로는 배가 부르지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L03_basic#3','kor',6,1,'u4','L03','g6_1_kor_u4_L03_basic','lesson_basic','K6-1-u4-C14',1,'mc','auto','대화에서 쓰인 속담은 어느 것인가요?',ARRAY['K6-1-u4-X15']::text[],false,'{"seq":3,"concept":"K6-1-u4-C14","difficulty":1,"kind":"mc","stem":"대화에서 쓰인 속담은 어느 것인가요?","options":[{"t":"빈 수레가 요란하다","correct":true},{"t":"세 골이나 먹었어","mis":"K6-1-u4-X15"},{"t":"오늘부터 하면 되지","mis":"K6-1-u4-X15"},{"t":"골키퍼를 제일 잘한다","mis":"K6-1-u4-X15"}],"explanation":["그 자리에서 한 말이에요.","이것도 그 자리에서 한 말이에요.","예로부터 전해 오는 말을 골라요."],"asset":{"type":"speech","turns":[{"who":"예솔","text":"한별이가 자기가 골키퍼를 제일 잘한다고 계속 말하더라. 그런데 오늘 경기에서는 세 골이나 먹었어."},{"who":"한별","text":"맞아. 빈 수레가 요란하다더니 내 이야기였네. 말 대신 연습을 했어야 했는데."},{"who":"예솔","text":"오늘부터 하면 되지. 첫술에 배부르랴."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L03_basic#4','kor',6,1,'u4','L03','g6_1_kor_u4_L03_basic','lesson_basic','K6-1-u4-C16',1,'ox','auto','「수레」처럼 요즘 잘 쓰지 않는 말이 든 속담은 낡아서 쓰지 않는 게 좋아요.',ARRAY['K6-1-u4-X17']::text[],false,'{"seq":4,"concept":"K6-1-u4-C16","difficulty":1,"kind":"ox","stem":"「수레」처럼 요즘 잘 쓰지 않는 말이 든 속담은 낡아서 쓰지 않는 게 좋아요.","answer":"X","reason_options":[{"t":"옛말은 조상의 생활이 말에 남은 흔적이라 우리 문화를 담고 있기 때문에","correct":true},{"t":"요즘 쓰지 않는 낱말이 들어 있으면 틀린 말이기 때문에","mis":"K6-1-u4-X17"}],"mis":"K6-1-u4-X17","explanation":["옛말이 있다고 못 쓰는 말이 되지 않아요.","옛 생활이 말에 남았어요.","무엇을 가리키는지 찾아봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L03_basic#5','kor',6,1,'u4','L03','g6_1_kor_u4_L03_basic','lesson_basic','K6-1-u4-C15',2,'match','auto','속담과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-1-u4-C15","difficulty":2,"kind":"match","stem":"속담과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"빈 수레가 요란하다","r":"잘 알지 못하는 사람이 오히려 더 떠든다"},{"l":"첫술에 배부르랴","r":"한 번에 큰 성과를 얻기 어렵다"},{"l":"가랑비에 옷 젖는 줄 모른다","r":"사소한 것이 쌓여 큰 것이 되는 줄 모른다"}],"mis":"K6-1-u4-X16","explanation":["빈 수레는 덜컹거려 시끄러워요.","첫 숟가락으로는 배가 안 불러요.","가는 비에도 어느새 젖어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L03_basic#6','kor',6,1,'u4','L03','g6_1_kor_u4_L03_basic','lesson_basic','K6-1-u4-C14',2,'mc','auto','한별이가 「빈 수레가 요란하다더니 내 이야기였네.」라고 말한 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X20','K6-1-u4-X01']::text[],false,'{"seq":6,"concept":"K6-1-u4-C14","difficulty":2,"kind":"mc","stem":"한별이가 「빈 수레가 요란하다더니 내 이야기였네.」라고 말한 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"말만 앞세우고 연습하지 않은 자신을 돌아본다","correct":true},{"t":"경기에서 이긴 것을 자랑한다","mis":"K6-1-u4-X20"},{"t":"예솔이를 꾸짖는다","mis":"K6-1-u4-X20"},{"t":"수레를 끌고 와서 시끄러웠다고 말한다","mis":"K6-1-u4-X01"}],"explanation":["세 골이나 먹었어요.","예솔이를 꾸짖는 말이 아니에요.","자기 이야기라고 했어요."],"asset":{"type":"speech","turns":[{"who":"예솔","text":"한별이가 자기가 골키퍼를 제일 잘한다고 계속 말하더라. 그런데 오늘 경기에서는 세 골이나 먹었어."},{"who":"한별","text":"맞아. 빈 수레가 요란하다더니 내 이야기였네. 말 대신 연습을 했어야 했는데."},{"who":"예솔","text":"오늘부터 하면 되지. 첫술에 배부르랴."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L03_basic#7','kor',6,1,'u4','L03','g6_1_kor_u4_L03_basic','lesson_basic','K6-1-u4-C17',2,'mc','auto','「첫술에 배부르랴」와 뜻이 겹치는 속담은 어느 것인가요?',ARRAY['K6-1-u4-X18']::text[],false,'{"seq":7,"concept":"K6-1-u4-C17","difficulty":2,"kind":"mc","stem":"「첫술에 배부르랴」와 뜻이 겹치는 속담은 어느 것인가요?","options":[{"t":"급할수록 돌아가라","correct":true},{"t":"빈 수레가 요란하다","mis":"K6-1-u4-X18"},{"t":"고양이 목에 방울 달기","mis":"K6-1-u4-X18"},{"t":"바늘 도둑이 소도둑 된다","mis":"K6-1-u4-X18"}],"explanation":["빈 수레는 떠드는 이야기예요.","방울 달기는 해내기 어려운 일이에요.","서두른다고 빨라지지 않는다는 뜻이 겹쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L03_basic#8','kor',6,1,'u4','L03','g6_1_kor_u4_L03_basic','lesson_basic','K6-1-u4-C18',2,'mc','auto','「빈 수레가 요란하다」를 사전에서 찾을 때 앞세울 중심 낱말은 어느 것인가요?',ARRAY['K6-1-u4-X14']::text[],false,'{"seq":8,"concept":"K6-1-u4-C18","difficulty":2,"kind":"mc","stem":"「빈 수레가 요란하다」를 사전에서 찾을 때 앞세울 중심 낱말은 어느 것인가요?","options":[{"t":"수레","correct":true},{"t":"「빈 수레가 요란하다」 문장 전체","mis":"K6-1-u4-X14"},{"t":"사전의 맨 첫 낱말","mis":"K6-1-u4-X14"},{"t":"속담에 들어 있는 「가」","mis":"K6-1-u4-X14"}],"explanation":["문장 전체로 찾지 않아요.","첫 낱말부터 넘기지 않아요.","중심이 되는 낱말을 잡아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L03_basic#9','kor',6,1,'u4','L03','g6_1_kor_u4_L03_basic','lesson_basic','K6-1-u4-C15',2,'mc','auto','「가랑비에 옷 젖는 줄 모른다」가 그리는 장면으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X16']::text[],false,'{"seq":9,"concept":"K6-1-u4-C15","difficulty":2,"kind":"mc","stem":"「가랑비에 옷 젖는 줄 모른다」가 그리는 장면으로 알맞은 것은 어느 것인가요?","options":[{"t":"가늘게 내리는 비라 젖는 줄 모르다가 어느새 다 젖는다","correct":true},{"t":"굵은 비가 한꺼번에 쏟아져 금방 젖는다","mis":"K6-1-u4-X16"},{"t":"비가 와도 옷이 전혀 젖지 않는다","mis":"K6-1-u4-X16"},{"t":"비가 그친 뒤 옷이 빨리 마른다","mis":"K6-1-u4-X16"}],"explanation":["굵은 비가 아니에요.","젖지 않는 것도 아니에요.","조금씩 쌓여 다 젖어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L03_basic#10','kor',6,1,'u4','L03','g6_1_kor_u4_L03_basic','lesson_basic','K6-1-u4-C17',3,'mc','auto','「가랑비에 옷 젖는 줄 모른다」와 「바늘 도둑이 소도둑 된다」를 견준 말로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X18','K6-1-u4-X16','K6-1-u4-X15']::text[],false,'{"seq":10,"concept":"K6-1-u4-C17","difficulty":3,"kind":"mc","stem":"「가랑비에 옷 젖는 줄 모른다」와 「바늘 도둑이 소도둑 된다」를 견준 말로 알맞은 것은 어느 것인가요?","options":[{"t":"둘 다 작은 것이 쌓여 커진다는 뜻이지만 뒤의 것은 나쁜 일이 커지는 쪽으로 기운다","correct":true},{"t":"뜻이 똑같아 어느 상황에서나 바꿔 써도 된다","mis":"K6-1-u4-X18"},{"t":"두 속담은 뜻이 서로 반대이다","mis":"K6-1-u4-X16"},{"t":"앞의 것만 속담이고 뒤의 것은 관용어이다","mis":"K6-1-u4-X15"}],"explanation":["기우는 방향이 달라요.","뜻이 반대는 아니에요.","둘 다 속담이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L03_challenge#1','kor',6,1,'u4','L03','g6_1_kor_u4_L03_challenge','lesson_challenge','K6-1-u4-C14',2,'mc','auto','속담이 간결하면서도 효과적인 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X05','K6-1-u4-X09','K6-1-u4-X15']::text[],false,'{"seq":1,"concept":"K6-1-u4-C14","difficulty":2,"kind":"mc","stem":"속담이 간결하면서도 효과적인 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"장면 하나로 말해 오래 남고, 여러 사람이 알아 풀어 설명하지 않아도 통한다","correct":true},{"t":"어려운 낱말이 많아 귀하게 들린다","mis":"K6-1-u4-X05"},{"t":"길게 풀어 설명해 자세하다","mis":"K6-1-u4-X09"},{"t":"그 자리에서 지어내 새롭다","mis":"K6-1-u4-X15"}],"explanation":["어려워서 힘이 센 것이 아니에요.","길게 풀지 않아요.","장면과 교훈으로 짧게 통해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L03_challenge#2','kor',6,1,'u4','L03','g6_1_kor_u4_L03_challenge','lesson_challenge','K6-1-u4-C18',2,'ox','auto','속담 사전 · 국어사전 · 인터넷 사전은 모두 중심 낱말을 앞세워 속담을 찾아요.',ARRAY['K6-1-u4-X14']::text[],false,'{"seq":2,"concept":"K6-1-u4-C18","difficulty":2,"kind":"ox","stem":"속담 사전 · 국어사전 · 인터넷 사전은 모두 중심 낱말을 앞세워 속담을 찾아요.","answer":"O","reason_options":[{"t":"사전은 낱말을 기준으로 짜여 있기 때문에","correct":true},{"t":"속담 문장 전체를 넣어야만 찾을 수 있기 때문에","mis":"K6-1-u4-X14"}],"mis":"K6-1-u4-X14","explanation":["셋은 생김새가 달라요.","그래도 찾는 길은 같아요.","중심 낱말을 앞세워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L03_challenge#3','kor',6,1,'u4','L03','g6_1_kor_u4_L03_challenge','lesson_challenge','K6-1-u4-C15',3,'mc','auto','다음 상황에 알맞은 속담은 어느 것인가요?',ARRAY['K6-1-u4-X08','K6-1-u4-X18']::text[],false,'{"seq":3,"concept":"K6-1-u4-C15","difficulty":3,"kind":"mc","stem":"다음 상황에 알맞은 속담은 어느 것인가요?","options":[{"t":"가랑비에 옷 젖는 줄 모른다","correct":true},{"t":"빈 수레가 요란하다","mis":"K6-1-u4-X08"},{"t":"첫술에 배부르랴","mis":"K6-1-u4-X18"},{"t":"고양이 목에 방울 달기","mis":"K6-1-u4-X08"}],"explanation":["떠드는 이야기가 아니에요.","한 번에 안 된다는 뜻과는 달라요.","작은 것이 쌓여 커졌어요."],"asset":{"type":"passage","lines":["날마다 십 분씩만 책을 읽었다. 대단한 일이라고 생각하지 않았는데,","한 학기가 지나고 보니 읽은 책이 스무 권이 넘어 있었다."],"title":"어느 학생의 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L03_challenge#4','kor',6,1,'u4','L03','g6_1_kor_u4_L03_challenge','lesson_challenge','K6-1-u4-C16',3,'error','auto','속담 속 옛말을 두고 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u4-X17']::text[],false,'{"seq":4,"concept":"K6-1-u4-C16","difficulty":3,"kind":"error","stem":"속담 속 옛말을 두고 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"로하 — 「서당은 요즘 없으니 이 속담은 버려야 해.」","correct":true,"mis_target":"K6-1-u4-X17"},{"t":"지안 — 「서당이 무엇인지 찾아보면 옛 생활을 알 수 있어.」","mis":"K6-1-u4-X17"},{"t":"하윤 — 「풍월이 무슨 말인지 사전에서 찾아볼래.」","mis":"K6-1-u4-X17"}],"explanation":["지안이는 옛 생활을 알아보려 했어요.","하윤이는 낯선 말을 찾아보려 했어요.","옛말은 버릴 말이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L03_challenge#5','kor',6,1,'u4','L03','g6_1_kor_u4_L03_challenge','lesson_challenge','K6-1-u4-C17',3,'mc','auto','뜻이 비슷한 속담을 바꿔 쓸 수 있는지 정할 때 가장 알맞은 방법은 어느 것인가요?',ARRAY['K6-1-u4-X18','K6-1-u4-X03']::text[],false,'{"seq":5,"concept":"K6-1-u4-C17","difficulty":3,"kind":"mc","stem":"뜻이 비슷한 속담을 바꿔 쓸 수 있는지 정할 때 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"뜻만이 아니라 어떤 상황에 쓰는 말인지, 기우는 방향까지 견준다","correct":true},{"t":"두 속담의 글자 수가 같은지 본다","mis":"K6-1-u4-X18"},{"t":"같은 낱말이 들었는지만 본다","mis":"K6-1-u4-X03"},{"t":"뜻이 조금이라도 겹치면 바꿔 쓴다","mis":"K6-1-u4-X18"}],"explanation":["글자 수와는 상관없어요.","같은 낱말은 기준이 아니에요.","쓸 상황까지 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L03_challenge#6','kor',6,1,'u4','L03','g6_1_kor_u4_L03_challenge','lesson_challenge','K6-1-u4-C19',3,'mc','auto','「빈 수레가 요란하다」를 오늘 생활에 맞게 바꿔 지은 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X19','K6-1-u4-X06']::text[],false,'{"seq":6,"concept":"K6-1-u4-C19","difficulty":3,"kind":"mc","stem":"「빈 수레가 요란하다」를 오늘 생활에 맞게 바꿔 지은 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"「빈 필통이 요란하다」","correct":true},{"t":"「꽉 찬 필통이 요란하다」","mis":"K6-1-u4-X19"},{"t":"「빈 필통이 조용하다」","mis":"K6-1-u4-X19"},{"t":"「빈 수레가 요란하고 시끄럽다」","mis":"K6-1-u4-X06"}],"explanation":["꽉 차면 교훈이 달라져요.","조용하면 뜻이 반대가 돼요.","낱말만 바꾸고 교훈은 살려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L03_challenge#7','kor',6,1,'u4','L03','g6_1_kor_u4_L03_challenge','lesson_challenge','K6-1-u4-C18',3,'mc','auto','「서당 개 삼 년이면 풍월을 읊는다」에서 「풍월」의 뜻을 모를 때 가장 알맞은 방법은 어느 것인가요?',ARRAY['K6-1-u4-X14','K6-1-u4-X10','K6-1-u4-X17']::text[],false,'{"seq":7,"concept":"K6-1-u4-C18","difficulty":3,"kind":"mc","stem":"「서당 개 삼 년이면 풍월을 읊는다」에서 「풍월」의 뜻을 모를 때 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"장면과 앞뒤 말로 짐작해 본 뒤 「풍월」을 사전에서 찾아 맞춰 본다","correct":true},{"t":"사전의 첫 쪽부터 넘기며 속담이 나올 때까지 읽는다","mis":"K6-1-u4-X14"},{"t":"짐작한 뜻을 찾아보지 않고 그대로 정답으로 삼는다","mis":"K6-1-u4-X10"},{"t":"모르는 낱말이 있으니 이 속담은 쓰지 않는다","mis":"K6-1-u4-X17"}],"explanation":["첫 쪽부터는 오래 걸려요.","짐작은 확인해야 해요.","짐작한 뒤 사전으로 맞춰 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L03_challenge#8','kor',6,1,'u4','L03','g6_1_kor_u4_L03_challenge','lesson_challenge','K6-1-u4-C17',4,'mc','auto','「처음에는 친구 지우개를 말없이 빌려 쓰던 것이 버릇이 되어, 나중에는 친구 물건을 허락 없이 가져가는 일이 잦아졌다.」에 가장 알맞은 속담과 까닭은 어느 것인가요?',ARRAY['K6-1-u4-X18','K6-1-u4-X08','K6-1-u4-X16']::text[],false,'{"seq":8,"concept":"K6-1-u4-C17","difficulty":4,"kind":"mc","stem":"「처음에는 친구 지우개를 말없이 빌려 쓰던 것이 버릇이 되어, 나중에는 친구 물건을 허락 없이 가져가는 일이 잦아졌다.」에 가장 알맞은 속담과 까닭은 어느 것인가요?","options":[{"t":"「바늘 도둑이 소도둑 된다」 — 작은 잘못이 커지는 쪽으로 기우는 말이라 이 상황에 꼭 맞는다","correct":true},{"t":"「가랑비에 옷 젖는 줄 모른다」 — 작은 것이 쌓인다는 뜻이 같으니 더 알맞다","mis":"K6-1-u4-X18"},{"t":"「첫술에 배부르랴」 — 한 번에 되지 않는 일이기 때문이다","mis":"K6-1-u4-X08"},{"t":"「빈 수레가 요란하다」 — 물건을 가져가면 시끄럽기 때문이다","mis":"K6-1-u4-X16"}],"explanation":["뜻이 겹쳐도 기우는 방향이 달라요.","한 번에 안 되는 이야기가 아니에요.","작은 잘못이 커진 상황이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L03_challenge#9','kor',6,1,'u4','L03','g6_1_kor_u4_L03_challenge','lesson_challenge','K6-1-u4-C16',4,'essay','teacher','속담 속에서 낯선 옛말을 만났을 때 어떻게 대하면 좋을지 쓰고, 속담 하나를 예로 들어 설명하세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u4-C16","difficulty":4,"kind":"essay","stem":"속담 속에서 낯선 옛말을 만났을 때 어떻게 대하면 좋을지 쓰고, 속담 하나를 예로 들어 설명하세요.","answer_guide":{"answer":"예: 낯선 옛말은 버릴 말이 아니라 조상의 생활이 남은 흔적이므로 무엇을 가리키는지 찾아보면 좋다. 「빈 수레가 요란하다」의 수레는 옛날 짐을 싣고 다니던 것인데, 짐이 없으면 덜컹거려 더 시끄럽다. 이 장면을 알면 잘 모르는 사람이 더 떠든다는 뜻이 저절로 이해되고 옛 생활도 엿볼 수 있다.","scoring_points":["옛말을 버리지 않고 찾아본다는 태도를 썼는가","옛말이 옛 생활의 흔적이라는 점을 썼는가","속담 하나를 예로 들어 설명했는가"]},"explanation":["옛말을 어떻게 대할지 써요.","옛 생활과 이어 봐요.","예를 하나 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L03_challenge#10','kor',6,1,'u4','L03','g6_1_kor_u4_L03_challenge','lesson_challenge','K6-1-u4-C19',4,'essay','teacher','속담 하나를 골라 오늘 생활에 맞게 바꾸어 짓고, 담긴 교훈과 쓸 수 있는 상황을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u4-C19","difficulty":4,"kind":"essay","stem":"속담 하나를 골라 오늘 생활에 맞게 바꾸어 짓고, 담긴 교훈과 쓸 수 있는 상황을 쓰세요.","answer_guide":{"answer":"예: 「가랑비에 옷 젖는 줄 모른다」를 「한 장씩 넘긴 책이 책장을 채운다」로 바꾸었다. 작은 것이 쌓여 큰 것이 된다는 교훈은 그대로 살렸다. 날마다 조금씩 읽은 책이 어느새 많이 쌓였을 때 쓸 수 있다.","scoring_points":["속담을 골라 낱말을 바꾸어 지었는가","원래 속담의 교훈을 살렸는가","쓸 수 있는 상황을 썼는가"]},"explanation":["속담을 하나 골라요.","교훈은 그대로 살려요.","쓸 상황을 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L04_basic#1','kor',6,1,'u4','L04','g6_1_kor_u4_L04_basic','lesson_basic','K6-1-u4-C20',1,'mc','auto','대화에서 쓰인 관용 표현은 어느 것인가요?',ARRAY['K6-1-u4-X15']::text[],false,'{"seq":1,"concept":"K6-1-u4-C20","difficulty":1,"kind":"mc","stem":"대화에서 쓰인 관용 표현은 어느 것인가요?","options":[{"t":"목마른 사람이 우물 판다","correct":true},{"t":"답답한 내가 먼저 가 볼게","mis":"K6-1-u4-X15"},{"t":"쉬는 시간마다 혼자 앉아 있어","mis":"K6-1-u4-X15"},{"t":"누군가 먼저 가서 말을 걸면 좋을 텐데","mis":"K6-1-u4-X15"}],"explanation":["그 자리에서 한 말이에요.","이것도 그 자리에서 한 말이에요.","예로부터 전해 오는 말을 골라요."],"asset":{"type":"speech","turns":[{"who":"초아","text":"새롬이가 전학 온 지 일주일이 됐는데 아직 아무하고도 말을 안 해. 쉬는 시간마다 혼자 앉아 있어."},{"who":"다솔","text":"누군가 먼저 가서 말을 걸면 좋을 텐데, 다들 눈치만 보고 있네."},{"who":"초아","text":"목마른 사람이 우물 판다잖아. 답답한 내가 먼저 가 볼게."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L04_basic#2','kor',6,1,'u4','L04','g6_1_kor_u4_L04_basic','lesson_basic','K6-1-u4-C21',1,'mc','auto','「마음이 굴뚝같다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X01','K6-1-u4-X22']::text[],false,'{"seq":2,"concept":"K6-1-u4-C21","difficulty":1,"kind":"mc","stem":"「마음이 굴뚝같다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"무엇을 몹시 하고 싶어 하다","correct":true},{"t":"마음이 굴뚝처럼 시커멓다","mis":"K6-1-u4-X01"},{"t":"마음이 답답해 연기가 난다","mis":"K6-1-u4-X01"},{"t":"하기 싫은 마음이 크다","mis":"K6-1-u4-X22"}],"explanation":["굴뚝 색깔 이야기가 아니에요.","연기 이야기도 아니에요.","몹시 하고 싶은 마음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L04_basic#3','kor',6,1,'u4','L04','g6_1_kor_u4_L04_basic','lesson_basic','K6-1-u4-C22',1,'mc','auto','「낯이 뜨겁다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X21','K6-1-u4-X22']::text[],false,'{"seq":3,"concept":"K6-1-u4-C22","difficulty":1,"kind":"mc","stem":"「낯이 뜨겁다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"부끄러워 얼굴이 달아오르다","correct":true},{"t":"얼굴에 열이 나서 아프다","mis":"K6-1-u4-X21"},{"t":"화가 나서 소리를 지르다","mis":"K6-1-u4-X22"},{"t":"날씨가 더워 땀이 나다","mis":"K6-1-u4-X21"}],"explanation":["아파서 열이 나는 것이 아니에요.","화난 마음과는 달라요.","부끄러운 마음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L04_basic#4','kor',6,1,'u4','L04','g6_1_kor_u4_L04_basic','lesson_basic','K6-1-u4-C24',1,'ox','auto','같은 관용 표현이라도 누구에게 하느냐에 따라 뜻이 달라질 수 있어요.',ARRAY['K6-1-u4-X23']::text[],false,'{"seq":4,"concept":"K6-1-u4-C24","difficulty":1,"kind":"ox","stem":"같은 관용 표현이라도 누구에게 하느냐에 따라 뜻이 달라질 수 있어요.","answer":"O","reason_options":[{"t":"같은 표현도 남을 가리키면 상처가 되고 자기를 가리키면 돌아봄이 되기 때문에","correct":true},{"t":"관용 표현은 굳어진 말이라 어디서나 똑같이 전해지기 때문에","mis":"K6-1-u4-X23"}],"mis":"K6-1-u4-X23","explanation":["뜻은 하나여도","듣는 사람이 달라지면","전해지는 것이 뒤집혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L04_basic#5','kor',6,1,'u4','L04','g6_1_kor_u4_L04_basic','lesson_basic','K6-1-u4-C20',2,'mc','auto','초아가 「목마른 사람이 우물 판다잖아.」를 앞에 놓고 말한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X20','K6-1-u4-X21']::text[],false,'{"seq":5,"concept":"K6-1-u4-C20","difficulty":2,"kind":"mc","stem":"초아가 「목마른 사람이 우물 판다잖아.」를 앞에 놓고 말한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"답답한 내가 먼저 나서는 것이 당연하다고 전하려고","correct":true},{"t":"나서지 않는 친구들을 꾸짖으려고","mis":"K6-1-u4-X20"},{"t":"속담을 많이 안다는 것을 자랑하려고","mis":"K6-1-u4-X20"},{"t":"우물을 파러 가겠다고 알리려고","mis":"K6-1-u4-X21"}],"explanation":["꾸짖는 말이 아니에요.","자랑하려는 말도 아니에요.","그 말 뒤에 「내가 먼저 가 볼게」를 붙였어요."],"asset":{"type":"speech","turns":[{"who":"초아","text":"새롬이가 전학 온 지 일주일이 됐는데 아직 아무하고도 말을 안 해. 쉬는 시간마다 혼자 앉아 있어."},{"who":"다솔","text":"누군가 먼저 가서 말을 걸면 좋을 텐데, 다들 눈치만 보고 있네."},{"who":"초아","text":"목마른 사람이 우물 판다잖아. 답답한 내가 먼저 가 볼게."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L04_basic#6','kor',6,1,'u4','L04','g6_1_kor_u4_L04_basic','lesson_basic','K6-1-u4-C22',2,'mc','auto','「급할수록 돌아가라」가 담은 지혜가 드러난 소금 장수의 행동은 어느 것인가요?',ARRAY['K6-1-u4-X16','K6-1-u4-X20']::text[],false,'{"seq":6,"concept":"K6-1-u4-C22","difficulty":2,"kind":"mc","stem":"「급할수록 돌아가라」가 담은 지혜가 드러난 소금 장수의 행동은 어느 것인가요?","options":[{"t":"강을 따라 반나절을 걸어 얕은 여울목으로 건넜다","correct":true},{"t":"뱃삯을 두 배로 내고 서둘러 배를 탔다","mis":"K6-1-u4-X16"},{"t":"장에 가지 않고 집으로 되돌아갔다","mis":"K6-1-u4-X16"},{"t":"사공과 다투어 뱃삯을 깎았다","mis":"K6-1-u4-X20"}],"explanation":["서두르는 행동이에요.","포기하는 행동이에요.","돌아가는 길로 침착하게 해냈어요."],"asset":{"type":"passage","lines":["소금 장수는 강을 따라 위쪽으로 반나절을 걸어 얕은 여울목을 찾았다.","그는 지게를 지고 걸어서 강을 건넜고, 소금은 저물녘까지 모두 팔렸다.","그날 하루를 빈 배로 보낸 사공은 다음 날 소금 장수를 다시 만나자","낯이 뜨거워 고개를 들지 못했다."],"title":"옛이야기 「소금 장수와 나루터」 — 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L04_basic#7','kor',6,1,'u4','L04','g6_1_kor_u4_L04_basic','lesson_basic','K6-1-u4-C23',2,'match','auto','뜻이 비슷해 바꿔 쓸 수 있는 표현끼리 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-1-u4-C23","difficulty":2,"kind":"match","stem":"뜻이 비슷해 바꿔 쓸 수 있는 표현끼리 알맞게 이으세요.","pairs":[{"l":"발등에 불이 떨어지다","r":"코앞에 닥치다"},{"l":"낯이 뜨겁다","r":"고개를 들지 못하다"},{"l":"마음이 굴뚝같다","r":"목이 빠지게 기다리다"}],"mis":"K6-1-u4-X22","explanation":["급한 마음끼리 이어요.","부끄러운 마음끼리 이어요.","간절한 마음끼리 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L04_basic#8','kor',6,1,'u4','L04','g6_1_kor_u4_L04_basic','lesson_basic','K6-1-u4-C24',2,'mc','auto','관용 표현을 알맞게 쓴 말은 어느 것인가요?',ARRAY['K6-1-u4-X23','K6-1-u4-X08']::text[],false,'{"seq":8,"concept":"K6-1-u4-C24","difficulty":2,"kind":"mc","stem":"관용 표현을 알맞게 쓴 말은 어느 것인가요?","options":[{"t":"「아직 서툴지만 첫술에 배부르랴. 천천히 해 볼게.」","correct":true},{"t":"상을 받은 친구에게 「개구리 올챙이 적 생각 못 하는구나.」","mis":"K6-1-u4-X23"},{"t":"아파서 결석한 친구에게 「눈코 뜰 새 없이 바빴겠구나.」","mis":"K6-1-u4-X08"},{"t":"발표를 잘한 친구에게 「빈 수레가 요란하다더니.」","mis":"K6-1-u4-X23"}],"explanation":["축하할 자리에서 깎아내려요.","아픈 친구와 바쁨은 어긋나요.","자기를 가리키는 자리라 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L04_basic#9','kor',6,1,'u4','L04','g6_1_kor_u4_L04_basic','lesson_basic','K6-1-u4-C25',2,'ox','auto','관용 표현을 친구들 앞에서 소리 내어 말하지 못하면 배우지 못한 거예요.',ARRAY['K6-1-u4-X24']::text[],false,'{"seq":9,"concept":"K6-1-u4-C25","difficulty":2,"kind":"ox","stem":"관용 표현을 친구들 앞에서 소리 내어 말하지 못하면 배우지 못한 거예요.","answer":"X","reason_options":[{"t":"쓰고 싶은 상황을 떠올리고 적어 보는 것부터 할 수 있는 만큼 나아가면 되기 때문에","correct":true},{"t":"관용 표현은 말로 해야만 배운 것이기 때문에","mis":"K6-1-u4-X24"}],"mis":"K6-1-u4-X24","explanation":["부담스러울 수 있어요.","떠올리기부터 시작해요.","적어 보기, 말해 보기로 나아가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L04_basic#10','kor',6,1,'u4','L04','g6_1_kor_u4_L04_basic','lesson_basic','K6-1-u4-C26',3,'mc','auto','관용 표현을 쓸 상황을 짤 때 건너뛰지 말아야 할 마지막 칸은 어느 것인가요?',ARRAY['K6-1-u4-X07','K6-1-u4-X25']::text[],false,'{"seq":10,"concept":"K6-1-u4-C26","difficulty":3,"kind":"mc","stem":"관용 표현을 쓸 상황을 짤 때 건너뛰지 말아야 할 마지막 칸은 어느 것인가요?","options":[{"t":"표현의 뜻이 상황과 어긋나지 않는지 살피기","correct":true},{"t":"관용 표현을 몇 개 넣었는지 세기","mis":"K6-1-u4-X07"},{"t":"가장 어려운 표현으로 바꾸기","mis":"K6-1-u4-X25"},{"t":"대사를 되도록 길게 늘이기","mis":"K6-1-u4-X25"}],"explanation":["개수를 세는 칸이 아니에요.","어려운 표현이 좋은 것도 아니에요.","뜻과 상황이 맞는지 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L04_challenge#1','kor',6,1,'u4','L04','g6_1_kor_u4_L04_challenge','lesson_challenge','K6-1-u4-C21',2,'mc','auto','새롬이가 「정말 하고 싶었다」 대신 「마음이 굴뚝같았는데」라고 말해서 더 전해진 것은 어느 것인가요?',ARRAY['K6-1-u4-X21','K6-1-u4-X20','K6-1-u4-X09']::text[],false,'{"seq":1,"concept":"K6-1-u4-C21","difficulty":2,"kind":"mc","stem":"새롬이가 「정말 하고 싶었다」 대신 「마음이 굴뚝같았는데」라고 말해서 더 전해진 것은 어느 것인가요?","options":[{"t":"말을 걸고 싶은 마음이 얼마나 컸는지","correct":true},{"t":"굴뚝이 있는 집에 산다는 것","mis":"K6-1-u4-X21"},{"t":"사실은 말을 걸기 싫었다는 것","mis":"K6-1-u4-X20"},{"t":"그냥 말한 것과 아무 차이가 없다","mis":"K6-1-u4-X09"}],"explanation":["굴뚝 이야기가 아니에요.","싫었다는 것이 아니에요.","마음의 크기가 함께 전해졌어요."],"asset":{"type":"speech","turns":[{"who":"새롬","text":"그때 네가 먼저 와 줘서 고마웠어. 사실 나도 말을 걸고 싶은 마음이 굴뚝같았는데, 첫마디가 안 나오더라."},{"who":"초아","text":"나도 사실은 떨렸어. 그런데 누구 한 사람은 먼저 움직여야 하잖아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L04_challenge#2','kor',6,1,'u4','L04','g6_1_kor_u4_L04_challenge','lesson_challenge','K6-1-u4-C22',2,'ox','auto','「소금 장수는 발등에 불이 떨어진 심정이었다」는 소금 장수의 발등에 실제로 불이 붙었다는 뜻이에요.',ARRAY['K6-1-u4-X21']::text[],false,'{"seq":2,"concept":"K6-1-u4-C22","difficulty":2,"kind":"ox","stem":"「소금 장수는 발등에 불이 떨어진 심정이었다」는 소금 장수의 발등에 실제로 불이 붙었다는 뜻이에요.","answer":"X","reason_options":[{"t":"장이 오늘뿐이라 몹시 급한 마음을 나타낸 표현이기 때문에","correct":true},{"t":"이야기에 쓰인 말은 모두 실제로 일어난 일이기 때문에","mis":"K6-1-u4-X21"}],"mis":"K6-1-u4-X21","explanation":["「심정」이라고 했어요.","실제 불 이야기가 아니에요.","몹시 급한 마음이에요."],"asset":{"type":"passage","lines":["옛날, 소금을 지고 장을 다니는 장수가 있었다. 강 건너 장에 가려고","나루터에 닿았는데, 사공이 팔짱을 낀 채 말했다.","「오늘은 물이 불었으니 뱃삯을 두 배로 내시오.」","장이 서는 날은 오늘 하루뿐이었다. 소금 장수는 발등에 불이 떨어진","심정이었지만 지게를 내려놓고 생각했다. 「급할수록 돌아가라고 했지.」"],"title":"옛이야기 「소금 장수와 나루터」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L04_challenge#3','kor',6,1,'u4','L04','g6_1_kor_u4_L04_challenge','lesson_challenge','K6-1-u4-C22',3,'mc','auto','사공이 「낯이 뜨거워 고개를 들지 못했다」에 담긴 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X21','K6-1-u4-X20']::text[],false,'{"seq":3,"concept":"K6-1-u4-C22","difficulty":3,"kind":"mc","stem":"사공이 「낯이 뜨거워 고개를 들지 못했다」에 담긴 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"욕심을 부려 뱃삯을 올린 일이 부끄럽다","correct":true},{"t":"햇볕에 얼굴이 탔다","mis":"K6-1-u4-X21"},{"t":"소금 장수에게 화가 났다","mis":"K6-1-u4-X20"},{"t":"배를 지키느라 목이 아팠다","mis":"K6-1-u4-X21"}],"explanation":["햇볕 이야기가 아니에요.","화난 마음이 아니에요.","빈 배로 하루를 보낸 뒤의 부끄러움이에요."],"asset":{"type":"passage","lines":["소금 장수는 강을 따라 위쪽으로 반나절을 걸어 얕은 여울목을 찾았다.","그는 지게를 지고 걸어서 강을 건넜고, 소금은 저물녘까지 모두 팔렸다.","그날 하루를 빈 배로 보낸 사공은 다음 날 소금 장수를 다시 만나자","낯이 뜨거워 고개를 들지 못했다."],"title":"옛이야기 「소금 장수와 나루터」 — 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L04_challenge#4','kor',6,1,'u4','L04','g6_1_kor_u4_L04_challenge','lesson_challenge','K6-1-u4-C24',3,'error','auto','「빈 수레가 요란하다」를 쓴 친구들이에요. 알맞지 않게 쓴 친구는 누구인가요?',ARRAY['K6-1-u4-X23']::text[],false,'{"seq":4,"concept":"K6-1-u4-C24","difficulty":3,"kind":"error","stem":"「빈 수레가 요란하다」를 쓴 친구들이에요. 알맞지 않게 쓴 친구는 누구인가요?","options":[{"t":"지호 — 노래 대회에서 상을 받은 짝에게 「빈 수레가 요란하다더니.」라고 말했다","correct":true,"mis_target":"K6-1-u4-X23"},{"t":"라희 — 연습을 미룬 자신을 돌아보며 「내가 빈 수레가 요란했구나.」라고 썼다","mis":"K6-1-u4-X23"},{"t":"도하 — 준비 없이 큰소리치던 자신을 떠올리며 일기에 이 속담을 썼다","mis":"K6-1-u4-X23"}],"explanation":["라희는 자신을 돌아봤어요.","도하도 자신을 돌아봤어요.","상 받은 짝에게는 깎아내리는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L04_challenge#5','kor',6,1,'u4','L04','g6_1_kor_u4_L04_challenge','lesson_challenge','K6-1-u4-C20',3,'mc','auto','소금 장수가 「급할수록 돌아가라고 했지.」라고 혼잣말한 의도로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X20','K6-1-u4-X16']::text[],false,'{"seq":5,"concept":"K6-1-u4-C20","difficulty":3,"kind":"mc","stem":"소금 장수가 「급할수록 돌아가라고 했지.」라고 혼잣말한 의도로 알맞은 것은 어느 것인가요?","options":[{"t":"서두르기보다 다른 길을 찾아 침착하게 가려고 스스로 마음을 다잡으려고","correct":true},{"t":"사공에게 겁을 주려고","mis":"K6-1-u4-X20"},{"t":"장에 가는 것을 그만두려고","mis":"K6-1-u4-X16"},{"t":"속담을 외운 것을 뽐내려고","mis":"K6-1-u4-X20"}],"explanation":["사공에게 한 말이 아니에요.","그만두지 않았어요.","스스로 마음을 다잡았어요."],"asset":{"type":"passage","lines":["옛날, 소금을 지고 장을 다니는 장수가 있었다. 강 건너 장에 가려고","나루터에 닿았는데, 사공이 팔짱을 낀 채 말했다.","「오늘은 물이 불었으니 뱃삯을 두 배로 내시오.」","장이 서는 날은 오늘 하루뿐이었다. 소금 장수는 발등에 불이 떨어진","심정이었지만 지게를 내려놓고 생각했다. 「급할수록 돌아가라고 했지.」"],"title":"옛이야기 「소금 장수와 나루터」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L04_challenge#6','kor',6,1,'u4','L04','g6_1_kor_u4_L04_challenge','lesson_challenge','K6-1-u4-C23',3,'mc','auto','「발등에 불이 떨어지다」와 바꿔 쓸 수 있는 표현은 어느 것인가요?',ARRAY['K6-1-u4-X22']::text[],false,'{"seq":6,"concept":"K6-1-u4-C23","difficulty":3,"kind":"mc","stem":"「발등에 불이 떨어지다」와 바꿔 쓸 수 있는 표현은 어느 것인가요?","options":[{"t":"코앞에 닥치다","correct":true},{"t":"낯이 뜨겁다","mis":"K6-1-u4-X22"},{"t":"어깨너머로 배우다","mis":"K6-1-u4-X22"},{"t":"입이 무겁다","mis":"K6-1-u4-X22"}],"explanation":["낯이 뜨겁다는 부끄러움이에요.","어깨너머로 배우다는 보고 배우는 거예요.","급한 마음끼리 바꿔 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L04_challenge#7','kor',6,1,'u4','L04','g6_1_kor_u4_L04_challenge','lesson_challenge','K6-1-u4-C26',3,'mc','auto','짧은 대화를 지은 뒤 관용 표현을 빼고 다시 읽어 보는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X09','K6-1-u4-X07','K6-1-u4-X25']::text[],false,'{"seq":7,"concept":"K6-1-u4-C26","difficulty":3,"kind":"mc","stem":"짧은 대화를 지은 뒤 관용 표현을 빼고 다시 읽어 보는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"그 표현이 대화에 무엇을 더했는지 알 수 있어서","correct":true},{"t":"관용 표현이 없는 대화가 언제나 더 좋아서","mis":"K6-1-u4-X09"},{"t":"관용 표현의 개수를 늘리려고","mis":"K6-1-u4-X07"},{"t":"읽는 시간을 줄이려고","mis":"K6-1-u4-X25"}],"explanation":["빼는 것이 늘 좋은 것은 아니에요.","개수를 늘리려는 것이 아니에요.","표현이 더한 것을 견줘 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L04_challenge#8','kor',6,1,'u4','L04','g6_1_kor_u4_L04_challenge','lesson_challenge','K6-1-u4-C24',4,'mc','auto','짝이 넘어져 무릎을 다치고 울고 있어요. 이 자리에서 가장 알맞은 말은 어느 것인가요?',ARRAY['K6-1-u4-X23','K6-1-u4-X08','K6-1-u4-X07']::text[],false,'{"seq":8,"concept":"K6-1-u4-C24","difficulty":4,"kind":"mc","stem":"짝이 넘어져 무릎을 다치고 울고 있어요. 이 자리에서 가장 알맞은 말은 어느 것인가요?","options":[{"t":"관용 표현을 넣지 않고 「많이 아팠지? 보건실에 같이 가자.」라고 말한다","correct":true},{"t":"「원숭이도 나무에서 떨어진다더니.」라고 웃으며 말한다","mis":"K6-1-u4-X23"},{"t":"「첫술에 배부르랴.」라고 말한다","mis":"K6-1-u4-X08"},{"t":"관용 표현을 셋 넣어 길게 위로한다","mis":"K6-1-u4-X07"}],"explanation":["아픈 친구를 웃으며 놀리면 안 돼요.","뜻이 상황과 어긋나요.","관용 표현이 언제나 알맞은 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L04_challenge#9','kor',6,1,'u4','L04','g6_1_kor_u4_L04_challenge','lesson_challenge','K6-1-u4-C20',4,'essay','teacher','초아가 「목마른 사람이 우물 판다잖아.」라고 말한 의도를 쓰고, 「내가 먼저 가 볼게.」라고만 말했을 때와 무엇이 다른지 견주어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u4-C20","difficulty":4,"kind":"essay","stem":"초아가 「목마른 사람이 우물 판다잖아.」라고 말한 의도를 쓰고, 「내가 먼저 가 볼게.」라고만 말했을 때와 무엇이 다른지 견주어 쓰세요.","answer_guide":{"answer":"예: 초아는 새롬이를 걱정하는 답답한 사람이 자기이니 자기가 먼저 나서는 것이 당연하다고 전하려고 이 속담을 썼다. 「내가 먼저 가 볼게.」라고만 하면 뜻은 통하지만 왜 나서는지와 그때의 마음은 보이지 않는다. 속담을 앞에 놓으니 나서는 까닭과 마음이 함께 전해진다.","scoring_points":["초아의 의도를 바르게 썼는가","그냥 말했을 때 빠지는 것을 썼는가","속담이 더한 까닭과 마음을 견주어 썼는가"]},"explanation":["속담 뒤에 붙은 말을 봐요.","그냥 말한 것과 견줘요.","무엇이 더 전해졌는지 써요."],"asset":{"type":"speech","turns":[{"who":"초아","text":"새롬이가 전학 온 지 일주일이 됐는데 아직 아무하고도 말을 안 해. 쉬는 시간마다 혼자 앉아 있어."},{"who":"다솔","text":"누군가 먼저 가서 말을 걸면 좋을 텐데, 다들 눈치만 보고 있네."},{"who":"초아","text":"목마른 사람이 우물 판다잖아. 답답한 내가 먼저 가 볼게."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L04_challenge#10','kor',6,1,'u4','L04','g6_1_kor_u4_L04_challenge','lesson_challenge','K6-1-u4-C26',4,'essay','teacher','관용 표현 하나를 골라 상황 짜기 네 칸(표현 · 상황 · 누가 누구에게 · 어긋나지 않는지)을 채우고, 그 표현이 한 번 들어간 짧은 대화를 지으세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u4-C26","difficulty":4,"kind":"essay","stem":"관용 표현 하나를 골라 상황 짜기 네 칸(표현 · 상황 · 누가 누구에게 · 어긋나지 않는지)을 채우고, 그 표현이 한 번 들어간 짧은 대화를 지으세요.","answer_guide":{"answer":"예: 표현 — 발등에 불이 떨어지다. 상황 — 숙제 마감이 내일 아침인데 아직 시작하지 않았다. 누가 누구에게 — 형이 동생에게. 살피기 — 급한 마음을 나타내는 말이라 상황과 어긋나지 않는다. 대화 — 형: 「숙제 다 했어?」 동생: 「아직 하나도 안 했어.」 형: 「발등에 불이 떨어졌네. 지금 바로 시작하자.」 동생: 「응, 도와줘.」","scoring_points":["네 칸을 모두 채웠는가","표현의 뜻과 상황이 어긋나지 않는가","표현이 한 번 들어간 대화를 지었는가"]},"explanation":["표현과 상황을 정해요.","누가 누구에게 말할지 정해요.","마지막 칸을 꼭 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L06_basic#1','kor',6,1,'u4','L06','g6_1_kor_u4_L06_basic','lesson_basic','K6-1-u4-C27',1,'mc','auto','「견학 기록문」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X30','K6-1-u4-X29','K6-1-u4-X26']::text[],false,'{"seq":1,"concept":"K6-1-u4-C27","difficulty":1,"kind":"mc","stem":"「견학 기록문」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"견학하고 새롭게 안 사실을 중심으로 보고 듣고 느낀 것을 쓴 글","correct":true},{"t":"하루 일을 돌아보며 마음만 적은 글","mis":"K6-1-u4-X30"},{"t":"어떤 곳을 알리려고 사실만 적은 안내문","mis":"K6-1-u4-X29"},{"t":"지어낸 인물이 나오는 이야기","mis":"K6-1-u4-X26"}],"explanation":["마음만 있으면 일기예요.","사실만 있으면 안내문이에요.","새로 안 사실과 마음이 함께 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L06_basic#2','kor',6,1,'u4','L06','g6_1_kor_u4_L06_basic','lesson_basic','K6-1-u4-C28',1,'match','auto','견학 기록문의 세 가지와 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K6-1-u4-C28","difficulty":1,"kind":"match","stem":"견학 기록문의 세 가지와 그 뜻을 알맞게 이으세요.","pairs":[{"l":"여정","r":"어디를 거쳐 어떻게 다녔는지, 다닌 길"},{"l":"견문","r":"보고 들은 것, 새롭게 안 사실"},{"l":"감상","r":"생각하거나 느낀 것"}],"mis":"K6-1-u4-X27","explanation":["다닌 길은 여정이에요.","보고 들은 것은 견문이에요.","느낀 것은 감상이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L06_basic#3','kor',6,1,'u4','L06','g6_1_kor_u4_L06_basic','lesson_basic','K6-1-u4-C29',1,'mc','auto','견학 기록문의 처음 부분에 쓰는 내용으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X28']::text[],false,'{"seq":3,"concept":"K6-1-u4-C29","difficulty":1,"kind":"mc","stem":"견학 기록문의 처음 부분에 쓰는 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"견학한 까닭 · 함께 간 사람 · 견학 장소","correct":true},{"t":"견학한 내용 정리와 깨달은 점","mis":"K6-1-u4-X28"},{"t":"전시실에서 본 것과 그때의 마음","mis":"K6-1-u4-X28"},{"t":"다음에 가고 싶은 다른 곳의 목록","mis":"K6-1-u4-X28"}],"explanation":["정리와 깨달음은 끝이에요.","본 것과 마음은 가운데예요.","처음에는 개요를 알려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L06_basic#4','kor',6,1,'u4','L06','g6_1_kor_u4_L06_basic','lesson_basic','K6-1-u4-C30',1,'ox','auto','견학 기록문에는 새로 안 사실과 그때의 마음이 함께 들어가야 해요.',ARRAY['K6-1-u4-X29']::text[],false,'{"seq":4,"concept":"K6-1-u4-C30","difficulty":1,"kind":"ox","stem":"견학 기록문에는 새로 안 사실과 그때의 마음이 함께 들어가야 해요.","answer":"O","reason_options":[{"t":"사실만 남으면 안내문이 되고 마음만 남으면 일기가 되기 때문에","correct":true},{"t":"새로 안 사실만 적어도 충분하기 때문에","mis":"K6-1-u4-X29"}],"mis":"K6-1-u4-X29","explanation":["사실만으로는 부족해요.","마음만으로도 부족해요.","둘이 함께 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L06_basic#5','kor',6,1,'u4','L06','g6_1_kor_u4_L06_basic','lesson_basic','K6-1-u4-C31',2,'mc','auto','「갯벌 생태관을 다녀와서」라는 제목만 보고 짐작할 수 있는 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X31','K6-1-u4-X26']::text[],false,'{"seq":5,"concept":"K6-1-u4-C31","difficulty":2,"kind":"mc","stem":"「갯벌 생태관을 다녀와서」라는 제목만 보고 짐작할 수 있는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"갯벌을 다루는 전시관에 다녀온 뒤 쓴 글이고, 갯벌에 대해 새로 안 것이 담겼을 것이다","correct":true},{"t":"갯벌을 지키자고 주장하는 글일 것이다","mis":"K6-1-u4-X31"},{"t":"갯벌에 사는 인물이 나오는 옛이야기일 것이다","mis":"K6-1-u4-X26"},{"t":"생태관에 가는 길만 적은 글일 것이다","mis":"K6-1-u4-X31"}],"explanation":["「다녀와서」는 주장하는 말이 아니에요.","옛이야기가 아니에요.","다녀온 곳과 새로 안 것을 짐작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L06_basic#6','kor',6,1,'u4','L06','g6_1_kor_u4_L06_basic','lesson_basic','K6-1-u4-C28',2,'mc','auto','첫째 문단에서 여정에 해당하는 것은 어느 것인가요?',ARRAY['K6-1-u4-X27']::text[],false,'{"seq":6,"concept":"K6-1-u4-C28","difficulty":2,"kind":"mc","stem":"첫째 문단에서 여정에 해당하는 것은 어느 것인가요?","options":[{"t":"「버스로 사십 분을 달려 바닷가 마을에 닿았다.」","correct":true},{"t":"「목이 빠지게 기다리던 날이었다.」","mis":"K6-1-u4-X27"},{"t":"「학교에서 갯벌 이야기를 들었다.」","mis":"K6-1-u4-X27"},{"t":"「실제 갯벌을 보고 싶었다.」","mis":"K6-1-u4-X27"}],"explanation":["기다린 마음은 감상 쪽이에요.","들은 까닭은 여정이 아니에요.","어떻게 다녔는지가 여정이에요."],"asset":{"type":"passage","lines":["지난 토요일, 가족과 함께 우리 고장의 갯벌 생태관에 다녀왔다.","학교에서 갯벌 이야기를 들은 뒤로 실제 갯벌을 보고 싶었는데,","마침 주말에 문을 연다고 해서 목이 빠지게 기다리던 날이었다.","버스로 사십 분을 달려 바닷가 마을에 닿았다."],"title":"「갯벌 생태관을 다녀와서」 — 첫째 문단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L06_basic#7','kor',6,1,'u4','L06','g6_1_kor_u4_L06_basic','lesson_basic','K6-1-u4-C28',2,'mc','auto','셋째 · 넷째 문단에서 견문에 해당하는 것은 어느 것인가요?',ARRAY['K6-1-u4-X27']::text[],false,'{"seq":7,"concept":"K6-1-u4-C28","difficulty":2,"kind":"mc","stem":"셋째 · 넷째 문단에서 견문에 해당하는 것은 어느 것인가요?","options":[{"t":"「짱뚱어는 물 밖에서도 살갗으로 숨을 쉴 수 있다.」","correct":true},{"t":"「마지막으로 관찰 데크에 올랐다.」","mis":"K6-1-u4-X27"},{"t":"「다음 전시실로 들어갔다.」","mis":"K6-1-u4-X27"},{"t":"「쉬어 가는 곳이었다는 것을 처음 알아 놀랐다.」","mis":"K6-1-u4-X27"}],"explanation":["관찰 데크에 오른 것은 여정이에요.","전시실로 간 것도 여정이에요.","새로 안 사실이 견문이에요."],"asset":{"type":"passage","lines":["다음 전시실에는 집게발 한쪽이 유난히 큰 칠게와 짱뚱어가 있었다.","짱뚱어는 물 밖에서도 살갗으로 숨을 쉴 수 있어서","썰물 때 갯벌 위를 돌아다닌다고 한다.","마지막으로 오른 관찰 데크에서는 망원경으로 새를 볼 수 있었다.","봄과 가을이면 도요새가 이 갯벌에 들러 먹이를 먹고 힘을 채운다고 했다.","갯벌이 새들에게 쉬어 가는 곳이었다는 것을 처음 알았다."],"title":"「갯벌 생태관을 다녀와서」 — 셋째 · 넷째 문단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L06_basic#8','kor',6,1,'u4','L06','g6_1_kor_u4_L06_basic','lesson_basic','K6-1-u4-C27',2,'ox','auto','견학 기록문을 쓸 때 견학한 곳에서 새로 안 사실은 그럴듯하게 꾸며 써도 돼요.',ARRAY['K6-1-u4-X26']::text[],false,'{"seq":8,"concept":"K6-1-u4-C27","difficulty":2,"kind":"ox","stem":"견학 기록문을 쓸 때 견학한 곳에서 새로 안 사실은 그럴듯하게 꾸며 써도 돼요.","answer":"X","reason_options":[{"t":"견학 기록문은 정보를 전하는 글이라 새로 안 사실은 참이어야 하기 때문에","correct":true},{"t":"읽는 사람이 재미있기만 하면 되기 때문에","mis":"K6-1-u4-X26"}],"mis":"K6-1-u4-X26","explanation":["견학 기록문은 사실을 실어 날라요.","꾸민 사실은 거짓을 전해요.","새로 안 사실은 참이어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L06_basic#9','kor',6,1,'u4','L06','g6_1_kor_u4_L06_basic','lesson_basic','K6-1-u4-C29',2,'mc','auto','견학 기록문의 끝 부분에 들어갈 문장으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X28']::text[],false,'{"seq":9,"concept":"K6-1-u4-C29","difficulty":2,"kind":"mc","stem":"견학 기록문의 끝 부분에 들어갈 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"「이번 견학으로 갯벌이 수많은 생물이 기대어 사는 곳임을 알게 되었다.」","correct":true},{"t":"「지난 토요일, 가족과 함께 갯벌 생태관에 다녀왔다.」","mis":"K6-1-u4-X28"},{"t":"「다음 전시실에는 칠게와 짱뚱어가 있었다.」","mis":"K6-1-u4-X28"},{"t":"「버스로 바닷가 마을에 닿았다.」","mis":"K6-1-u4-X28"}],"explanation":["간 때와 사람은 처음이에요.","전시실에서 본 것은 가운데예요.","정리하고 깨달은 점이 끝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L06_basic#10','kor',6,1,'u4','L06','g6_1_kor_u4_L06_basic','lesson_basic','K6-1-u4-C30',3,'mc','auto','견학 기록문에서 감상이 모두 빠지면 어떤 글에 가까워질까요?',ARRAY['K6-1-u4-X30','K6-1-u4-X29']::text[],false,'{"seq":10,"concept":"K6-1-u4-C30","difficulty":3,"kind":"mc","stem":"견학 기록문에서 감상이 모두 빠지면 어떤 글에 가까워질까요?","options":[{"t":"그곳을 알리는 안내문","correct":true},{"t":"하루를 돌아보는 일기","mis":"K6-1-u4-X30"},{"t":"마음을 전하는 편지","mis":"K6-1-u4-X29"},{"t":"그래도 견학 기록문","mis":"K6-1-u4-X29"}],"explanation":["일기는 마음만 남은 글이에요.","편지도 마음을 전해요.","사실만 남으면 안내문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L06_challenge#1','kor',6,1,'u4','L06','g6_1_kor_u4_L06_challenge','lesson_challenge','K6-1-u4-C31',2,'mc','auto','견학 기록문에서 문단의 중심 내용을 찾을 때 먼저 볼 것은 어느 것인가요?',ARRAY['K6-1-u4-X31','K6-1-u4-X07']::text[],false,'{"seq":1,"concept":"K6-1-u4-C31","difficulty":2,"kind":"mc","stem":"견학 기록문에서 문단의 중심 내용을 찾을 때 먼저 볼 것은 어느 것인가요?","options":[{"t":"그 문단이 처음 · 가운데 · 끝 가운데 어느 자리에 있는지","correct":true},{"t":"문단에 낱말이 몇 개 있는지","mis":"K6-1-u4-X31"},{"t":"관용 표현이 몇 개 들었는지","mis":"K6-1-u4-X07"},{"t":"가장 긴 문장이 무엇인지","mis":"K6-1-u4-X31"}],"explanation":["낱말 수는 몫을 알려 주지 않아요.","관용 표현 개수도 아니에요.","자리에 따라 맡은 몫이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L06_challenge#2','kor',6,1,'u4','L06','g6_1_kor_u4_L06_challenge','lesson_challenge','K6-1-u4-C28',2,'ox','auto','견학 기록문에서 여정 · 견문 · 감상은 차례대로 한 번씩만 나와요.',ARRAY['K6-1-u4-X27']::text[],false,'{"seq":2,"concept":"K6-1-u4-C28","difficulty":2,"kind":"ox","stem":"견학 기록문에서 여정 · 견문 · 감상은 차례대로 한 번씩만 나와요.","answer":"X","reason_options":[{"t":"다닌 길을 따라 셋이 번갈아 엮이기 때문에","correct":true},{"t":"여정을 다 적은 뒤 견문을, 마지막에 감상을 몰아 써야 하기 때문에","mis":"K6-1-u4-X27"}],"mis":"K6-1-u4-X27","explanation":["길을 적고","본 것을 적고 마음을 적고","다음 곳에서 다시 되풀이해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L06_challenge#3','kor',6,1,'u4','L06','g6_1_kor_u4_L06_challenge','lesson_challenge','K6-1-u4-C30',3,'mc','auto','이 글이 견학 기록문이 되려면 무엇을 더해야 할까요?',ARRAY['K6-1-u4-X30','K6-1-u4-X07']::text[],false,'{"seq":3,"concept":"K6-1-u4-C30","difficulty":3,"kind":"mc","stem":"이 글이 견학 기록문이 되려면 무엇을 더해야 할까요?","options":[{"t":"그곳에서 보고 들어 새로 안 사실","correct":true},{"t":"「재미있었다」를 여러 번 더 쓴다","mis":"K6-1-u4-X30"},{"t":"관용 표현을 많이 넣는다","mis":"K6-1-u4-X07"},{"t":"지금도 견학 기록문이니 그대로 둔다","mis":"K6-1-u4-X30"}],"explanation":["느낌을 늘려도 그대로예요.","관용 표현 개수가 문제가 아니에요.","견문이 빠져 일기에 가까워요."],"asset":{"type":"passage","lines":["오늘 갯벌 생태관에 갔다.","재미있었다. 신기했다. 또 오고 싶다."],"title":"어느 학생의 견학 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L06_challenge#4','kor',6,1,'u4','L06','g6_1_kor_u4_L06_challenge','lesson_challenge','K6-1-u4-C27',3,'error','auto','견학 기록문에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u4-X26','K6-1-u4-X29']::text[],false,'{"seq":4,"concept":"K6-1-u4-C27","difficulty":3,"kind":"error","stem":"견학 기록문에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"세아 — 「견학한 곳에서 새로 안 사실은 재미있게 지어내도 괜찮아.」","correct":true,"mis_target":"K6-1-u4-X26"},{"t":"준서 — 「견학한 곳은 우리 고장 어디라도 될 수 있어.」","mis":"K6-1-u4-X26"},{"t":"유나 — 「새로 안 사실을 중심에 놓고 내 마음도 적어.」","mis":"K6-1-u4-X29"}],"explanation":["준서는 바르게 말했어요.","유나도 바르게 말했어요.","새로 안 사실은 참이어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L06_challenge#5','kor',6,1,'u4','L06','g6_1_kor_u4_L06_challenge','lesson_challenge','K6-1-u4-C29',3,'mc','auto','첫째 문단에 들어 있지 않은 것은 어느 것인가요?',ARRAY['K6-1-u4-X28']::text[],false,'{"seq":5,"concept":"K6-1-u4-C29","difficulty":3,"kind":"mc","stem":"첫째 문단에 들어 있지 않은 것은 어느 것인가요?","options":[{"t":"갯벌 흙 속 생물이 물을 거른다는 사실","correct":true},{"t":"간 때 — 지난 토요일","mis":"K6-1-u4-X28"},{"t":"함께 간 사람 — 가족","mis":"K6-1-u4-X28"},{"t":"간 까닭 — 실제 갯벌을 보고 싶어서","mis":"K6-1-u4-X28"}],"explanation":["간 때가 들어 있어요.","함께 간 사람도 들어 있어요.","새로 안 사실은 가운데에 나와요."],"asset":{"type":"passage","lines":["지난 토요일, 가족과 함께 우리 고장의 갯벌 생태관에 다녀왔다.","학교에서 갯벌 이야기를 들은 뒤로 실제 갯벌을 보고 싶었는데,","마침 주말에 문을 연다고 해서 목이 빠지게 기다리던 날이었다.","버스로 사십 분을 달려 바닷가 마을에 닿았다."],"title":"「갯벌 생태관을 다녀와서」 — 첫째 문단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L06_challenge#6','kor',6,1,'u4','L06','g6_1_kor_u4_L06_challenge','lesson_challenge','K6-1-u4-C28',3,'mc','auto','둘째 문단의 「입이 딱 벌어졌다」는 여정 · 견문 · 감상 가운데 무엇인가요?',ARRAY['K6-1-u4-X27','K6-1-u4-X28']::text[],false,'{"seq":6,"concept":"K6-1-u4-C28","difficulty":3,"kind":"mc","stem":"둘째 문단의 「입이 딱 벌어졌다」는 여정 · 견문 · 감상 가운데 무엇인가요?","options":[{"t":"감상","correct":true},{"t":"견문","mis":"K6-1-u4-X27"},{"t":"여정","mis":"K6-1-u4-X27"},{"t":"처음 부분의 까닭","mis":"K6-1-u4-X28"}],"explanation":["새로 안 사실이 아니에요.","다닌 길도 아니에요.","놀란 마음을 나타냈어요."],"asset":{"type":"passage","lines":["가장 먼저 들어간 곳은 갯벌을 설명하는 전시실이었다.","갯벌은 밀물 때 바닷물에 잠기고 썰물 때 드러나는 땅이라고 한다.","갯벌 흙 속에는 눈에 보이지 않을 만큼 작은 생물이 헤아릴 수 없이 많고,","이 생물들이 바닷물로 흘러든 더러운 물질을 걸러 준다고 했다.","바닷물을 걸러 주는 일을 흙이 한다는 말에 입이 딱 벌어졌다."],"title":"「갯벌 생태관을 다녀와서」 — 둘째 문단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L06_challenge#7','kor',6,1,'u4','L06','g6_1_kor_u4_L06_challenge','lesson_challenge','K6-1-u4-C31',3,'mc','auto','셋째 · 넷째 문단의 중심 내용으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X31']::text[],false,'{"seq":7,"concept":"K6-1-u4-C31","difficulty":3,"kind":"mc","stem":"셋째 · 넷째 문단의 중심 내용으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"갯벌 생물과 도요새를 보며 갯벌이 생물이 기대어 쉬는 곳임을 알았다","correct":true},{"t":"가족과 함께 갯벌 생태관에 다녀왔다","mis":"K6-1-u4-X31"},{"t":"갯벌의 소중함을 알고 눈여겨보기로 했다","mis":"K6-1-u4-X31"},{"t":"버스를 타고 바닷가 마을에 갔다","mis":"K6-1-u4-X31"}],"explanation":["다녀온 것은 첫째 문단이에요.","다짐은 끝 문단이에요.","가운데 문단은 본 것과 안 것이에요."],"asset":{"type":"passage","lines":["다음 전시실에는 집게발 한쪽이 유난히 큰 칠게와 짱뚱어가 있었다.","짱뚱어는 물 밖에서도 살갗으로 숨을 쉴 수 있어서","썰물 때 갯벌 위를 돌아다닌다고 한다.","마지막으로 오른 관찰 데크에서는 망원경으로 새를 볼 수 있었다.","봄과 가을이면 도요새가 이 갯벌에 들러 먹이를 먹고 힘을 채운다고 했다.","갯벌이 새들에게 쉬어 가는 곳이었다는 것을 처음 알았다."],"title":"「갯벌 생태관을 다녀와서」 — 셋째 · 넷째 문단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L06_challenge#8','kor',6,1,'u4','L06','g6_1_kor_u4_L06_challenge','lesson_challenge','K6-1-u4-C30',4,'mc','auto','두 친구가 쓴 글을 가장 알맞게 평가한 것은 어느 것인가요?',ARRAY['K6-1-u4-X29','K6-1-u4-X30']::text[],false,'{"seq":8,"concept":"K6-1-u4-C30","difficulty":4,"kind":"mc","stem":"두 친구가 쓴 글을 가장 알맞게 평가한 것은 어느 것인가요?","options":[{"t":"㉮는 감상이 빠져 안내문에, ㉯는 견문이 빠져 일기에 가깝고, 둘을 엮어야 견학 기록문이 된다","correct":true},{"t":"㉮만 견학 기록문이다","mis":"K6-1-u4-X29"},{"t":"㉯만 견학 기록문이다","mis":"K6-1-u4-X30"},{"t":"둘 다 견학 기록문이다","mis":"K6-1-u4-X29"}],"explanation":["㉮에는 마음이 없어요.","㉯에는 새로 안 사실이 없어요.","두 가지가 함께 있어야 해요."],"asset":{"type":"passage","lines":["㉮ 갯벌은 썰물 때 드러나는 땅이다. 짱뚱어는 살갗으로 숨을 쉰다.","　 도요새는 봄과 가을에 갯벌에 들른다.","㉯ 갯벌에 갔다. 재미있었다. 신기했다. 또 오고 싶다."],"title":"두 친구가 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L06_challenge#9','kor',6,1,'u4','L06','g6_1_kor_u4_L06_challenge','lesson_challenge','K6-1-u4-C28',4,'essay','teacher','이 부분에서 여정 · 견문 · 감상을 하나씩 찾아 쓰고, 각각 그렇게 본 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u4-C28","difficulty":4,"kind":"essay","stem":"이 부분에서 여정 · 견문 · 감상을 하나씩 찾아 쓰고, 각각 그렇게 본 까닭을 쓰세요.","answer_guide":{"answer":"예: 여정 — 「마지막으로 오른 관찰 데크」처럼 다음 곳으로 옮겨 간 길이 드러난다. 견문 — 「짱뚱어는 물 밖에서도 살갗으로 숨을 쉴 수 있다」는 그곳에서 새로 안 사실이다. 감상 — 「쉬어 가는 곳이었다는 것을 처음 알았다」에는 몰랐던 것을 깨달은 글쓴이의 마음이 담겼다.","scoring_points":["여정을 바르게 찾았는가","견문을 바르게 찾았는가","감상을 찾고 까닭을 썼는가"]},"explanation":["다닌 길을 찾아요.","새로 안 사실을 찾아요.","마음이 드러난 곳을 찾아요."],"asset":{"type":"passage","lines":["다음 전시실에는 집게발 한쪽이 유난히 큰 칠게와 짱뚱어가 있었다.","짱뚱어는 물 밖에서도 살갗으로 숨을 쉴 수 있어서","썰물 때 갯벌 위를 돌아다닌다고 한다.","마지막으로 오른 관찰 데크에서는 망원경으로 새를 볼 수 있었다.","봄과 가을이면 도요새가 이 갯벌에 들러 먹이를 먹고 힘을 채운다고 했다.","갯벌이 새들에게 쉬어 가는 곳이었다는 것을 처음 알았다."],"title":"「갯벌 생태관을 다녀와서」 — 셋째 · 넷째 문단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L06_challenge#10','kor',6,1,'u4','L06','g6_1_kor_u4_L06_challenge','lesson_challenge','K6-1-u4-C30',4,'essay','teacher','견학 기록문이 안내문과 일기와 어떻게 다른지 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u4-C30","difficulty":4,"kind":"essay","stem":"견학 기록문이 안내문과 일기와 어떻게 다른지 설명하세요.","answer_guide":{"answer":"예: 안내문은 그곳에 대한 사실만 알려 주고, 일기는 그날 느낀 마음을 중심으로 적는다. 견학 기록문은 그 사이에 서는 글로, 견학하고 새롭게 안 사실을 중심에 놓으면서 그것을 알고 내 마음이 어떻게 움직였는지도 함께 적는다. 그래서 견문과 감상이 함께 있어야 한다.","scoring_points":["안내문의 특징을 썼는가","일기의 특징을 썼는가","견학 기록문은 견문과 감상을 함께 담는다고 썼는가"]},"explanation":["안내문을 떠올려요.","일기를 떠올려요.","그 사이의 글을 설명해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L08_basic#1','kor',6,1,'u4','L08','g6_1_kor_u4_L08_basic','lesson_basic','K6-1-u4-C32',1,'mc','auto','견학 기록문을 쓰면 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X32','K6-1-u4-X38']::text[],false,'{"seq":1,"concept":"K6-1-u4-C32","difficulty":1,"kind":"mc","stem":"견학 기록문을 쓰면 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"보고 들은 것과 그때의 마음을 오래 남길 수 있다","correct":true},{"t":"글씨를 빨리 쓰는 연습이 된다","mis":"K6-1-u4-X32"},{"t":"외운 낱말의 개수를 늘릴 수 있다","mis":"K6-1-u4-X32"},{"t":"다른 사람 글보다 길게 쓸 수 있다","mis":"K6-1-u4-X38"}],"explanation":["글씨 연습이 목적이 아니에요.","낱말 외우기도 아니에요.","흐려지는 것을 붙잡아 남겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L08_basic#2','kor',6,1,'u4','L08','g6_1_kor_u4_L08_basic','lesson_basic','K6-1-u4-C33',1,'mc','auto','쓸 견학을 고를 때 가장 중요한 일은 어느 것인가요?',ARRAY['K6-1-u4-X33']::text[],false,'{"seq":2,"concept":"K6-1-u4-C33","difficulty":1,"kind":"mc","stem":"쓸 견학을 고를 때 가장 중요한 일은 어느 것인가요?","options":[{"t":"왜 기억에 남는지 한 줄로 적어 보기","correct":true},{"t":"가장 먼 곳을 고르기","mis":"K6-1-u4-X33"},{"t":"사진을 가장 많이 찍은 곳 고르기","mis":"K6-1-u4-X33"},{"t":"친구가 다녀온 곳을 따라 고르기","mis":"K6-1-u4-X33"}],"explanation":["먼 곳이 좋은 것은 아니에요.","사진 수로 정하지 않아요.","기억에 남은 까닭이 감상이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L08_basic#3','kor',6,1,'u4','L08','g6_1_kor_u4_L08_basic','lesson_basic','K6-1-u4-C34',1,'mc','auto','목적 · 주제 · 읽을 사람 가운데 글의 모양을 가장 많이 바꾸는 것은 어느 것인가요?',ARRAY['K6-1-u4-X38','K6-1-u4-X34']::text[],false,'{"seq":3,"concept":"K6-1-u4-C34","difficulty":1,"kind":"mc","stem":"목적 · 주제 · 읽을 사람 가운데 글의 모양을 가장 많이 바꾸는 것은 어느 것인가요?","options":[{"t":"읽을 사람","correct":true},{"t":"글씨 크기","mis":"K6-1-u4-X38"},{"t":"종이 색깔","mis":"K6-1-u4-X38"},{"t":"제목의 글자 수","mis":"K6-1-u4-X34"}],"explanation":["글씨 크기는 셋에 들지 않아요.","종이 색도 아니에요.","누가 읽느냐에 따라 낱말과 설명이 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L08_basic#4','kor',6,1,'u4','L08','g6_1_kor_u4_L08_basic','lesson_basic','K6-1-u4-C36',1,'ox','auto','관용 표현은 견문 자리보다 감상 자리에 얹는 것이 잘 어울려요.',ARRAY['K6-1-u4-X36']::text[],false,'{"seq":4,"concept":"K6-1-u4-C36","difficulty":1,"kind":"ox","stem":"관용 표현은 견문 자리보다 감상 자리에 얹는 것이 잘 어울려요.","answer":"O","reason_options":[{"t":"견문은 사실이고 감상은 마음이라 사실 자리에 얹으면 무엇이 사실인지 흐려지기 때문에","correct":true},{"t":"관용 표현은 어디에 넣어도 똑같기 때문에","mis":"K6-1-u4-X36"}],"mis":"K6-1-u4-X36","explanation":["견문은 사실이에요.","감상은 마음이에요.","관용 표현은 마음 쪽에 놓여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L08_basic#5','kor',6,1,'u4','L08','g6_1_kor_u4_L08_basic','lesson_basic','K6-1-u4-C34',2,'mc','auto','읽을 사람이 저학년 동생이라면 무엇을 바꾸면 좋을까요?',ARRAY['K6-1-u4-X34','K6-1-u4-X30']::text[],false,'{"seq":5,"concept":"K6-1-u4-C34","difficulty":2,"kind":"mc","stem":"읽을 사람이 저학년 동생이라면 무엇을 바꾸면 좋을까요?","options":[{"t":"어려운 낱말은 풀어 쓰고 낯선 것은 한 줄 더 설명한다","correct":true},{"t":"문단을 모두 없애고 한 덩어리로 길게 쓴다","mis":"K6-1-u4-X34"},{"t":"새로 안 사실은 빼고 느낀 점만 남긴다","mis":"K6-1-u4-X30"},{"t":"어른이 읽을 때와 똑같이 쓴다","mis":"K6-1-u4-X34"}],"explanation":["문단을 없애면 더 읽기 어려워요.","견문을 빼면 일기가 돼요.","동생이 멈출 곳을 풀어 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L08_basic#6','kor',6,1,'u4','L08','g6_1_kor_u4_L08_basic','lesson_basic','K6-1-u4-C35',2,'match','auto','「소방서를 다녀와서」에 쓸 내용과 들어갈 자리를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-1-u4-C35","difficulty":2,"kind":"match","stem":"「소방서를 다녀와서」에 쓸 내용과 들어갈 자리를 알맞게 이으세요.","pairs":[{"l":"소방관이 하는 일을 알아보려고 반 친구들과 소방서에 갔다","r":"처음"},{"l":"방화복을 들어 보니 생각보다 훨씬 무거웠다","r":"가운데"},{"l":"소방관의 하루가 어떤 하루인지 알게 되었다","r":"끝"}],"mis":"K6-1-u4-X28","explanation":["까닭과 함께 간 사람은 처음이에요.","본 것과 느낀 것은 가운데예요.","정리와 깨달음은 끝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L08_basic#7','kor',6,1,'u4','L08','g6_1_kor_u4_L08_basic','lesson_basic','K6-1-u4-C35',2,'mc','auto','조직표의 가운데를 짤 때 알맞은 요령은 어느 것인가요?',ARRAY['K6-1-u4-X35','K6-1-u4-X30','K6-1-u4-X07']::text[],false,'{"seq":7,"concept":"K6-1-u4-C35","difficulty":2,"kind":"mc","stem":"조직표의 가운데를 짤 때 알맞은 요령은 어느 것인가요?","options":[{"t":"본 것 하나에 느낀 것 하나를 짝지어 간다","correct":true},{"t":"본 것만 모두 늘어놓고 느낌은 끝에 몰아 쓴다","mis":"K6-1-u4-X35"},{"t":"느낀 것만 적는다","mis":"K6-1-u4-X30"},{"t":"문단마다 관용 표현을 하나씩 넣는다","mis":"K6-1-u4-X07"}],"explanation":["사실만 늘어놓은 글이 돼요.","느낌만 있으면 일기가 돼요.","본 것과 느낀 것을 짝지어요."],"asset":{"type":"passage","lines":["처음 — 까닭(소방관이 하는 일 알아보기) · 반 친구들과 · 우리 고장 소방서","가운데 첫째 — 차고의 소방차 / 소화전에 호스를 잇는다는 것을 앎","　→ 소방차 한 대로 다 되는 줄 알았던 생각이 바뀜","가운데 둘째 — 방화복을 들어 봄 / 무게가 상당함 → 입고 뛴다는 말에 놀람","가운데 셋째 — 신고 받는 곳 / 위치부터 말해야 함 → 나도 그래야겠다고 생각함","끝 — 소방관의 하루는 기다림과 준비로 채워짐 → 길을 비켜 주겠다는 다짐"],"title":"「소방서를 다녀와서」 조직표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L08_basic#8','kor',6,1,'u4','L08','g6_1_kor_u4_L08_basic','lesson_basic','K6-1-u4-C36',2,'mc','auto','관용 표현을 알맞은 자리에 놓은 문장은 어느 것인가요?',ARRAY['K6-1-u4-X36']::text[],false,'{"seq":8,"concept":"K6-1-u4-C36","difficulty":2,"kind":"mc","stem":"관용 표현을 알맞은 자리에 놓은 문장은 어느 것인가요?","options":[{"t":"「이것을 입고 뛴다니 손이 열 개라도 모자라겠다.」","correct":true},{"t":"「소화전에 호스를 잇는데 손이 열 개라도 모자란다.」","mis":"K6-1-u4-X36"},{"t":"「신고할 때 위치를 먼저 말하는 것은 눈코 뜰 새 없다.」","mis":"K6-1-u4-X36"},{"t":"「물탱크의 물은 진땀을 빼며 금방 바닥난다.」","mis":"K6-1-u4-X36"}],"explanation":["사실 자리에 얹었어요.","이것도 사실 자리예요.","놀란 마음 자리에 놓였어요."],"asset":{"type":"passage","lines":["먼저 차고에서 소방차를 보았다. 나는 소방차에 실린 물만으로","불을 끄는 줄 알았는데, 물탱크의 물은 금방 바닥나기 때문에","길가의 소화전에 호스를 이어 물을 끌어 쓴다고 한다.","다음으로 방화복을 들어 보았다. 한 손으로는 들리지 않을 만큼 무거웠다.","이것을 다 입고 계단을 뛰어오른다는 말에","손이 열 개라도 모자라겠다는 생각이 들었다."],"title":"「소방서를 다녀와서」 — 가운데 부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L08_basic#9','kor',6,1,'u4','L08','g6_1_kor_u4_L08_basic','lesson_basic','K6-1-u4-C38',2,'mc','auto','견학 기록문을 고쳐 쓸 때 살펴볼 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X38','K6-1-u4-X07']::text[],false,'{"seq":9,"concept":"K6-1-u4-C38","difficulty":2,"kind":"mc","stem":"견학 기록문을 고쳐 쓸 때 살펴볼 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"여정 · 견문 · 감상이 전해지는가","correct":true},{"t":"글씨를 예쁘게 썼는가","mis":"K6-1-u4-X38"},{"t":"다른 사람 글보다 긴가","mis":"K6-1-u4-X38"},{"t":"관용 표현을 많이 넣었는가","mis":"K6-1-u4-X07"}],"explanation":["글씨 모양은 갈래를 정하지 않아요.","길이도 아니에요.","갈래가 갖출 것을 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L08_basic#10','kor',6,1,'u4','L08','g6_1_kor_u4_L08_basic','lesson_basic','K6-1-u4-C37',3,'mc','auto','「관용 표현을 세 개 넣으랬으니 문단마다 하나씩 넣자.」라는 생각에 대해 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['K6-1-u4-X37','K6-1-u4-X07','K6-1-u4-X09']::text[],false,'{"seq":10,"concept":"K6-1-u4-C37","difficulty":3,"kind":"mc","stem":"「관용 표현을 세 개 넣으랬으니 문단마다 하나씩 넣자.」라는 생각에 대해 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"마음이 없는 자리에 얹힌 표현은 겉도니, 가장 크게 마음이 움직인 자리에 하나만 놓아도 된다","correct":true},{"t":"세 개를 다 채워야 좋은 글이 된다","mis":"K6-1-u4-X37"},{"t":"더 많이 넣을수록 좋은 글이 된다","mis":"K6-1-u4-X07"},{"t":"관용 표현은 하나도 쓰면 안 된다","mis":"K6-1-u4-X09"}],"explanation":["칸을 채우는 글이 아니에요.","개수가 문제가 아니에요.","제자리에 하나면 충분해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L08_challenge#1','kor',6,1,'u4','L08','g6_1_kor_u4_L08_challenge','lesson_challenge','K6-1-u4-C35',2,'mc','auto','생각그물로 견학 기록문의 재료를 모을 때 알맞은 방법은 어느 것인가요?',ARRAY['K6-1-u4-X35','K6-1-u4-X29','K6-1-u4-X30']::text[],false,'{"seq":1,"concept":"K6-1-u4-C35","difficulty":2,"kind":"mc","stem":"생각그물로 견학 기록문의 재료를 모을 때 알맞은 방법은 어느 것인가요?","options":[{"t":"순서는 신경 쓰지 않고 다섯 갈래로 떠오르는 대로 모은다","correct":true},{"t":"처음부터 처음 · 가운데 · 끝 차례대로만 적는다","mis":"K6-1-u4-X35"},{"t":"견문 갈래만 가득 채운다","mis":"K6-1-u4-X29"},{"t":"감상 갈래만 가득 채운다","mis":"K6-1-u4-X30"}],"explanation":["순서는 조직표에서 잡아요.","견문만 모으면 감상이 없어요.","다섯 갈래를 고루 모아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L08_challenge#2','kor',6,1,'u4','L08','g6_1_kor_u4_L08_challenge','lesson_challenge','K6-1-u4-C37',2,'ox','auto','견학 기록문에서 담을 것이 없는 자리는 비워 두어도 돼요.',ARRAY['K6-1-u4-X37']::text[],false,'{"seq":2,"concept":"K6-1-u4-C37","difficulty":2,"kind":"ox","stem":"견학 기록문에서 담을 것이 없는 자리는 비워 두어도 돼요.","answer":"O","reason_options":[{"t":"가장 중요한 것은 진솔함이고 칸은 채울 것이 아니라 담을 그릇이기 때문에","correct":true},{"t":"정해진 칸을 다 채워야 견학 기록문이 되기 때문에","mis":"K6-1-u4-X37"}],"mis":"K6-1-u4-X37","explanation":["억지로 채우면 겉돌아요.","진솔함이 가장 중요해요.","담을 것이 없으면 비워도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L08_challenge#3','kor',6,1,'u4','L08','g6_1_kor_u4_L08_challenge','lesson_challenge','K6-1-u4-C33',3,'mc','auto','쓸 견학을 고를 때 「기억에 남은 까닭」을 적어 두는 것이 중요한 까닭은 어느 것인가요?',ARRAY['K6-1-u4-X38','K6-1-u4-X28','K6-1-u4-X33']::text[],false,'{"seq":3,"concept":"K6-1-u4-C33","difficulty":3,"kind":"mc","stem":"쓸 견학을 고를 때 「기억에 남은 까닭」을 적어 두는 것이 중요한 까닭은 어느 것인가요?","options":[{"t":"그 까닭이 곧 글의 감상이 되기 때문에","correct":true},{"t":"까닭이 길수록 글이 길어지기 때문에","mis":"K6-1-u4-X38"},{"t":"처음 부분에는 까닭만 쓰면 되기 때문에","mis":"K6-1-u4-X28"},{"t":"읽을 사람이 까닭을 외워야 하기 때문에","mis":"K6-1-u4-X33"}],"explanation":["길이를 늘리려는 것이 아니에요.","처음에는 까닭 말고도 써요.","까닭이 감상으로 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L08_challenge#4','kor',6,1,'u4','L08','g6_1_kor_u4_L08_challenge','lesson_challenge','K6-1-u4-C36',3,'error','auto','「소방서를 다녀와서」에 관용 표현을 넣어 보았어요. 알맞지 않게 넣은 친구는 누구인가요?',ARRAY['K6-1-u4-X36']::text[],false,'{"seq":4,"concept":"K6-1-u4-C36","difficulty":3,"kind":"error","stem":"「소방서를 다녀와서」에 관용 표현을 넣어 보았어요. 알맞지 않게 넣은 친구는 누구인가요?","options":[{"t":"은호 — 「물탱크의 물은 발등에 불이 떨어지게 금방 바닥난다.」","correct":true,"mis_target":"K6-1-u4-X36"},{"t":"서진 — 「돌아오는 길에 마주친 소방차가 오래도록 눈에 선했다.」","mis":"K6-1-u4-X36"},{"t":"나윤 — 「이것을 입고 뛴다니 손이 열 개라도 모자라겠다는 생각이 들었다.」","mis":"K6-1-u4-X36"}],"explanation":["서진이는 마음 자리에 놓았어요.","나윤이도 마음 자리에 놓았어요.","사실 자리에 얹으면 흐려져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L08_challenge#5','kor',6,1,'u4','L08','g6_1_kor_u4_L08_challenge','lesson_challenge','K6-1-u4-C38',3,'mc','auto','읽을 사람이 가족이라면 견학 기록문을 어떻게 나누면 좋을까요?',ARRAY['K6-1-u4-X39']::text[],false,'{"seq":5,"concept":"K6-1-u4-C38","difficulty":3,"kind":"mc","stem":"읽을 사람이 가족이라면 견학 기록문을 어떻게 나누면 좋을까요?","options":[{"t":"가족이 함께 보는 곳에 붙이거나 가족에게 직접 읽어 준다","correct":true},{"t":"공책에 써서 서랍에 넣어 둔다","mis":"K6-1-u4-X39"},{"t":"가장 많이 인쇄해 여러 곳에 붙인다","mis":"K6-1-u4-X39"},{"t":"가족이 보지 않는 반 게시판에만 올린다","mis":"K6-1-u4-X39"}],"explanation":["서랍 속 글은 읽을 수 없어요.","많이 붙인다고 읽는 것이 아니에요.","읽을 사람이 정말 읽을 수 있는 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L08_challenge#6','kor',6,1,'u4','L08','g6_1_kor_u4_L08_challenge','lesson_challenge','K6-1-u4-C35',3,'mc','auto','조직표의 「소방차 한 대로 다 되는 줄 알았던 생각이 바뀜」은 무엇인가요?',ARRAY['K6-1-u4-X27','K6-1-u4-X28']::text[],false,'{"seq":6,"concept":"K6-1-u4-C35","difficulty":3,"kind":"mc","stem":"조직표의 「소방차 한 대로 다 되는 줄 알았던 생각이 바뀜」은 무엇인가요?","options":[{"t":"견문에 짝지은 감상","correct":true},{"t":"여정","mis":"K6-1-u4-X27"},{"t":"처음 부분의 견학한 까닭","mis":"K6-1-u4-X28"},{"t":"끝 부분의 정리","mis":"K6-1-u4-X28"}],"explanation":["다닌 길이 아니에요.","견학한 까닭도 아니에요.","새로 안 사실 뒤에 붙인 마음이에요."],"asset":{"type":"passage","lines":["처음 — 까닭(소방관이 하는 일 알아보기) · 반 친구들과 · 우리 고장 소방서","가운데 첫째 — 차고의 소방차 / 소화전에 호스를 잇는다는 것을 앎","　→ 소방차 한 대로 다 되는 줄 알았던 생각이 바뀜","가운데 둘째 — 방화복을 들어 봄 / 무게가 상당함 → 입고 뛴다는 말에 놀람","가운데 셋째 — 신고 받는 곳 / 위치부터 말해야 함 → 나도 그래야겠다고 생각함","끝 — 소방관의 하루는 기다림과 준비로 채워짐 → 길을 비켜 주겠다는 다짐"],"title":"「소방서를 다녀와서」 조직표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L08_challenge#7','kor',6,1,'u4','L08','g6_1_kor_u4_L08_challenge','lesson_challenge','K6-1-u4-C32',3,'mc','auto','견학 기록문이 읽는 사람에게 주는 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X32']::text[],false,'{"seq":7,"concept":"K6-1-u4-C32","difficulty":3,"kind":"mc","stem":"견학 기록문이 읽는 사람에게 주는 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"가 보지 못한 사람에게 그곳을 알리고, 가려는 사람이 무엇을 볼지 미리 알게 한다","correct":true},{"t":"읽는 사람의 글씨가 좋아진다","mis":"K6-1-u4-X32"},{"t":"쓴 사람이 외운 낱말 수가 늘어난다","mis":"K6-1-u4-X32"},{"t":"읽는 사람은 견학을 갈 필요가 없어진다","mis":"K6-1-u4-X32"}],"explanation":["글씨와는 상관없어요.","낱말 수도 아니에요.","그곳의 모습이 읽는 사람에게 건너가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L08_challenge#8','kor',6,1,'u4','L08','g6_1_kor_u4_L08_challenge','lesson_challenge','K6-1-u4-C34',4,'mc','auto','이 부분을 저학년 동생에게 읽어 줄 글로 고친다면 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X30','K6-1-u4-X07','K6-1-u4-X34']::text[],false,'{"seq":8,"concept":"K6-1-u4-C34","difficulty":4,"kind":"mc","stem":"이 부분을 저학년 동생에게 읽어 줄 글로 고친다면 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「물탱크」 「소화전」 「방화복」을 동생이 알 수 있게 풀어 쓰고 한 줄씩 더 설명한다","correct":true},{"t":"새로 안 사실을 빼고 느낌만 남긴다","mis":"K6-1-u4-X30"},{"t":"관용 표현을 더 넣어 재미있게 만든다","mis":"K6-1-u4-X07"},{"t":"누가 읽든 같으니 그대로 둔다","mis":"K6-1-u4-X34"}],"explanation":["견문을 빼면 안 돼요.","관용 표현 개수가 문제가 아니에요.","읽을 사람에 맞게 풀어 줘요."],"asset":{"type":"passage","lines":["먼저 차고에서 소방차를 보았다. 나는 소방차에 실린 물만으로","불을 끄는 줄 알았는데, 물탱크의 물은 금방 바닥나기 때문에","길가의 소화전에 호스를 이어 물을 끌어 쓴다고 한다.","다음으로 방화복을 들어 보았다. 한 손으로는 들리지 않을 만큼 무거웠다.","이것을 다 입고 계단을 뛰어오른다는 말에","손이 열 개라도 모자라겠다는 생각이 들었다."],"title":"「소방서를 다녀와서」 — 가운데 부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L08_challenge#9','kor',6,1,'u4','L08','g6_1_kor_u4_L08_challenge','lesson_challenge','K6-1-u4-C35',4,'essay','teacher','내가 다녀온 견학 하나로 조직표를 짜 보세요. 처음 · 가운데 둘 · 끝으로 나누고, 가운데에는 본 것 하나에 느낀 것 하나를 짝지으세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u4-C35","difficulty":4,"kind":"essay","stem":"내가 다녀온 견학 하나로 조직표를 짜 보세요. 처음 · 가운데 둘 · 끝으로 나누고, 가운데에는 본 것 하나에 느낀 것 하나를 짝지으세요.","answer_guide":{"answer":"예: 처음 — 별을 가까이 보고 싶어서 가족과 고장의 천문대에 갔다. 가운데 첫째 — 망원경 방에서 달을 보았다 / 달 표면에 크고 작은 구덩이가 많았다 → 매끈할 줄 알았는데 놀랐다. 가운데 둘째 — 별자리 방에서 설명을 들었다 / 별은 스스로 빛을 낸다 → 밤하늘이 다르게 보였다. 끝 — 하늘에 대해 새로 안 것이 많았다 → 다음에는 별자리 지도를 들고 밤하늘을 보겠다.","scoring_points":["처음에 까닭 · 함께 간 사람 · 장소를 썼는가","가운데마다 본 것과 느낀 것을 짝지었는가","끝에 정리와 깨달은 점을 썼는가"]},"explanation":["처음에 개요를 써요.","가운데는 본 것과 느낀 것을 짝지어요.","끝에 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L08_challenge#10','kor',6,1,'u4','L08','g6_1_kor_u4_L08_challenge','lesson_challenge','K6-1-u4-C37',4,'essay','teacher','「여정 · 견문 · 감상도, 관용 표현도 채워야 할 칸이 아니라 담을 그릇이다」라는 말을 설명하고, 관용 표현을 어디에 몇 개 놓을지 내 생각을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u4-C37","difficulty":4,"kind":"essay","stem":"「여정 · 견문 · 감상도, 관용 표현도 채워야 할 칸이 아니라 담을 그릇이다」라는 말을 설명하고, 관용 표현을 어디에 몇 개 놓을지 내 생각을 쓰세요.","answer_guide":{"answer":"예: 견학 기록문에서 가장 중요한 것은 진솔함이라, 마음이 없는 자리에 억지로 표현을 채우면 글이 겉돈다. 그래서 담을 것이 있을 때 담고, 없으면 비워 두어도 된다. 나는 관용 표현을 문단마다 넣지 않고, 가장 크게 놀라거나 마음이 움직인 감상 자리에 하나만 놓겠다.","scoring_points":["칸 채우기가 아니라는 뜻을 설명했는가","진솔함이 중요하다는 점을 썼는가","관용 표현을 놓을 자리와 개수를 내 생각으로 썼는가"]},"explanation":["칸과 그릇을 견줘요.","진솔함을 떠올려요.","자리와 개수를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L11_basic#1','kor',6,1,'u4','L11','g6_1_kor_u4_L11_basic','lesson_basic','K6-1-u4-C39',1,'mc','auto','다음 가운데 동물이 들어간 관용 표현은 어느 것인가요?',ARRAY['K6-1-u4-X03']::text[],false,'{"seq":1,"concept":"K6-1-u4-C39","difficulty":1,"kind":"mc","stem":"다음 가운데 동물이 들어간 관용 표현은 어느 것인가요?","options":[{"t":"원숭이도 나무에서 떨어진다","correct":true},{"t":"강아지에게 물을 주었다","mis":"K6-1-u4-X03"},{"t":"새가 나뭇가지에 앉았다","mis":"K6-1-u4-X03"},{"t":"고양이가 낮잠을 잤다","mis":"K6-1-u4-X03"}],"explanation":["강아지 이야기가 뜻 그대로예요.","새 이야기도 뜻 그대로예요.","잘하는 사람도 실수한다는 새 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L11_basic#2','kor',6,1,'u4','L11','g6_1_kor_u4_L11_basic','lesson_basic','K6-1-u4-C40',1,'mc','auto','관용 표현 사전 한 장에 담을 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X41']::text[],false,'{"seq":2,"concept":"K6-1-u4-C40","difficulty":1,"kind":"mc","stem":"관용 표현 사전 한 장에 담을 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"표현 · 뜻 · 쓸 수 있는 상황","correct":true},{"t":"표현이 만들어진 정확한 때","mis":"K6-1-u4-X41"},{"t":"그 표현을 아는 친구의 수","mis":"K6-1-u4-X41"},{"t":"그 표현을 쓴 횟수","mis":"K6-1-u4-X41"}],"explanation":["만들어진 때는 꺼내 쓰는 데 쓸모없어요.","친구 수도 마찬가지예요.","세 칸이 있어야 꺼내 쓸 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L11_basic#3','kor',6,1,'u4','L11','g6_1_kor_u4_L11_basic','lesson_basic','K6-1-u4-C42',1,'mc','auto','학급 전체 앞에서 발표할 때 지킬 예절로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X42','K6-1-u4-X43']::text[],false,'{"seq":3,"concept":"K6-1-u4-C42","difficulty":1,"kind":"mc","stem":"학급 전체 앞에서 발표할 때 지킬 예절로 알맞은 것은 어느 것인가요?","options":[{"t":"존댓말로, 모두 들을 수 있는 크기로 말한다","correct":true},{"t":"둘레에 들리지 않게 작은 소리로 말한다","mis":"K6-1-u4-X42"},{"t":"생각날 때마다 끼어들어 말한다","mis":"K6-1-u4-X43"},{"t":"친구와 쉬는 시간에 하듯 반말로 말한다","mis":"K6-1-u4-X42"}],"explanation":["작은 소리는 짝과 이야기할 때예요.","끼어들면 안 돼요.","여럿이 듣는 자리에 맞게 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L11_basic#4','kor',6,1,'u4','L11','g6_1_kor_u4_L11_basic','lesson_basic','K6-1-u4-C41',1,'ox','auto','관용 표현 사전에는 아무도 모르는 어려운 표현을 많이 모을수록 좋아요.',ARRAY['K6-1-u4-X40']::text[],false,'{"seq":4,"concept":"K6-1-u4-C41","difficulty":1,"kind":"ox","stem":"관용 표현 사전에는 아무도 모르는 어려운 표현을 많이 모을수록 좋아요.","answer":"X","reason_options":[{"t":"개수도 어려움도 아닌 내가 쓸 자리가 떠오르는 표현을 골라야 하기 때문에","correct":true},{"t":"어려운 표현이 많아야 좋은 사전이기 때문에","mis":"K6-1-u4-X40"}],"mis":"K6-1-u4-X40","explanation":["만든 나조차 안 쓰는 사전이 돼요.","개수가 기준이 아니에요.","쓸 자리가 떠오르는 표현을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L11_basic#5','kor',6,1,'u4','L11','g6_1_kor_u4_L11_basic','lesson_basic','K6-1-u4-C39',2,'match','auto','몸을 가리키는 말이 든 표현과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-1-u4-C39","difficulty":2,"kind":"match","stem":"몸을 가리키는 말이 든 표현과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"어깨너머로 배우다","r":"옆에서 보고 들으며 배우다"},{"l":"목에 힘을 주다","r":"잘난 체하며 거만하게 굴다"},{"l":"등을 떠밀다","r":"하기 싫어하는 사람을 억지로 나서게 하다"}],"mis":"K6-1-u4-X12","explanation":["어깨 위로 넘어다보는 장면이에요.","목을 꼿꼿이 세운 장면이에요.","등을 밀어 내보내는 장면이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L11_basic#6','kor',6,1,'u4','L11','g6_1_kor_u4_L11_basic','lesson_basic','K6-1-u4-C39',2,'mc','auto','「고양이 목에 방울 달기」를 쓰기에 알맞은 상황은 어느 것인가요?',ARRAY['K6-1-u4-X08','K6-1-u4-X01']::text[],false,'{"seq":6,"concept":"K6-1-u4-C39","difficulty":2,"kind":"mc","stem":"「고양이 목에 방울 달기」를 쓰기에 알맞은 상황은 어느 것인가요?","options":[{"t":"학급 회의에서 모두 좋다고 했지만 맡겠다고 나서는 사람이 없을 때","correct":true},{"t":"늘 잘하던 친구가 한 번 틀렸을 때","mis":"K6-1-u4-X08"},{"t":"옆에서 지켜보다 어느새 할 줄 알게 되었을 때","mis":"K6-1-u4-X08"},{"t":"고양이에게 목걸이를 사 줄 때","mis":"K6-1-u4-X01"}],"explanation":["실수 이야기는 원숭이 속담이에요.","보고 익힌 것은 서당 개 속담이에요.","말은 좋은데 해내기 어려운 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L11_basic#7','kor',6,1,'u4','L11','g6_1_kor_u4_L11_basic','lesson_basic','K6-1-u4-C39',2,'mc','auto','관용 표현을 낱말로 묶을 때와 마음으로 묶을 때를 알맞게 견준 것은 어느 것인가요?',ARRAY['K6-1-u4-X44']::text[],false,'{"seq":7,"concept":"K6-1-u4-C39","difficulty":2,"kind":"mc","stem":"관용 표현을 낱말로 묶을 때와 마음으로 묶을 때를 알맞게 견준 것은 어느 것인가요?","options":[{"t":"낱말로 묶으면 찾기가 쉽고, 마음으로 묶으면 쓰기가 쉽다","correct":true},{"t":"낱말로 묶으면 쓰기가 쉽고, 마음으로 묶으면 찾기가 쉽다","mis":"K6-1-u4-X44"},{"t":"둘 다 쓸모가 없으니 흩어 두는 게 낫다","mis":"K6-1-u4-X44"},{"t":"둘은 똑같아서 어느 쪽이든 차이가 없다","mis":"K6-1-u4-X44"}],"explanation":["두 말이 뒤바뀌었어요.","묶어 두면 빨리 떠올라요.","둘은 좋은 점이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L11_basic#8','kor',6,1,'u4','L11','g6_1_kor_u4_L11_basic','lesson_basic','K6-1-u4-C28',2,'mc','auto','「도서관 서고를 다녀와서」 앞부분에서 여정에 해당하는 것은 어느 것인가요?',ARRAY['K6-1-u4-X27']::text[],false,'{"seq":8,"concept":"K6-1-u4-C28","difficulty":2,"kind":"mc","stem":"「도서관 서고를 다녀와서」 앞부분에서 여정에 해당하는 것은 어느 것인가요?","options":[{"t":"「사서 선생님을 따라 처음 일반 서고에 들어갔다.」","correct":true},{"t":"「책의 주제에 따라 숫자를 정해 꽂는다.」","mis":"K6-1-u4-X27"},{"t":"「내가 늘 헤매던 까닭이 그제야 가닥이 잡혔다.」","mis":"K6-1-u4-X27"},{"t":"「모든 책에는 숫자가 붙어 있었다.」","mis":"K6-1-u4-X27"}],"explanation":["숫자로 꽂는 것은 새로 안 사실이에요.","깨달은 마음은 감상이에요.","어디로 들어갔는지가 여정이에요."],"asset":{"type":"passage","lines":["지난 화요일, 우리 반은 고장의 도서관에 갔다.","사서 선생님을 따라 처음 들어간 곳은 일반 서고였다.","모든 책에는 숫자가 붙어 있었다. 책의 주제에 따라 숫자를 정해 두고","그 차례대로 꽂는다고 한다. 내가 늘 헤매던 까닭이 그제야 가닥이 잡혔다."],"title":"「도서관 서고를 다녀와서」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L11_basic#9','kor',6,1,'u4','L11','g6_1_kor_u4_L11_basic','lesson_basic','K6-1-u4-C42',2,'mc','auto','쉬는 시간에 친구와 이야기할 때 지킬 예절로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X42','K6-1-u4-X43']::text[],false,'{"seq":9,"concept":"K6-1-u4-C42","difficulty":2,"kind":"mc","stem":"쉬는 시간에 친구와 이야기할 때 지킬 예절로 알맞은 것은 어느 것인가요?","options":[{"t":"둘레에 방해가 되지 않게 작은 소리로, 말차례를 지키며 반응을 보인다","correct":true},{"t":"발표할 때처럼 모두 들리게 큰 소리로 말한다","mis":"K6-1-u4-X42"},{"t":"친구 말이 끝나기 전에 끼어든다","mis":"K6-1-u4-X43"},{"t":"고개를 돌리고 대꾸하지 않는다","mis":"K6-1-u4-X43"}],"explanation":["큰 소리는 둘레에 방해가 돼요.","말차례를 지켜요.","고개를 끄덕이며 반응해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L11_basic#10','kor',6,1,'u4','L11','g6_1_kor_u4_L11_basic','lesson_basic','K6-1-u4-C42',3,'mc','auto','상황에 따라 언어 예절을 정하는 기준으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X43']::text[],false,'{"seq":10,"concept":"K6-1-u4-C42","difficulty":3,"kind":"mc","stem":"상황에 따라 언어 예절을 정하는 기준으로 알맞은 것은 어느 것인가요?","options":[{"t":"듣는 사람이 편하게 들을 수 있는가","correct":true},{"t":"외운 예절 목록에 있는가","mis":"K6-1-u4-X43"},{"t":"내가 편하게 말할 수 있는가","mis":"K6-1-u4-X43"},{"t":"목소리가 충분히 큰가","mis":"K6-1-u4-X43"}],"explanation":["목록에 없는 상황도 있어요.","말하는 사람이 기준이 아니에요.","듣는 사람을 두고 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L11_challenge#1','kor',6,1,'u4','L11','g6_1_kor_u4_L11_challenge','lesson_challenge','K6-1-u4-C9',2,'mc','auto','「손때가 묻은 책」의 「손때가 묻다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X01','K6-1-u4-X12']::text[],false,'{"seq":1,"concept":"K6-1-u4-C9","difficulty":2,"kind":"mc","stem":"「손때가 묻은 책」의 「손때가 묻다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"오래 쓰고 매만져 정이 들다","correct":true},{"t":"손을 씻지 않아 책이 더러워졌다","mis":"K6-1-u4-X01"},{"t":"새로 사서 아주 깨끗하다","mis":"K6-1-u4-X01"},{"t":"손으로 만지면 안 되는 책이다","mis":"K6-1-u4-X12"}],"explanation":["더러워진 이야기가 아니에요.","새 책과 반대예요.","오래 아껴 써 온 마음이에요."],"asset":{"type":"passage","lines":["다음으로 간 보존 서고는 공기가 서늘했다.","종이는 습기와 더위에 약해서 온도와 습도를 늘 일정하게 지킨다고 했다.","오래된 책은 따로 두고, 넘길 때에도 두 손으로 조심해 다룬다고 한다.","표지가 닳고 손때가 묻은 책들이 나란히 서 있는 모습을 한참 바라보았다.","이번 견학으로 도서관이 책을 지키는 곳이라는 것을 알게 되었다."],"title":"「도서관 서고를 다녀와서」 — 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L11_challenge#2','kor',6,1,'u4','L11','g6_1_kor_u4_L11_challenge','lesson_challenge','K6-1-u4-C40',2,'ox','auto','관용 표현 사전의 쓸 상황은 내가 겪은 일이나 겪을 법한 일로 적어요.',ARRAY['K6-1-u4-X11']::text[],false,'{"seq":2,"concept":"K6-1-u4-C40","difficulty":2,"kind":"ox","stem":"관용 표현 사전의 쓸 상황은 내가 겪은 일이나 겪을 법한 일로 적어요.","answer":"O","reason_options":[{"t":"내 상황이 적힌 사전이라야 필요할 때 떠오르기 때문에","correct":true},{"t":"쓸 상황은 사전에 적힌 예문을 그대로 옮겨야 하기 때문에","mis":"K6-1-u4-X11"}],"mis":"K6-1-u4-X11","explanation":["뜻만 적으면 한 번 보고 덮어요.","내 상황이라야 떠올라요.","셋째 칸이 가장 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L11_challenge#3','kor',6,1,'u4','L11','g6_1_kor_u4_L11_challenge','lesson_challenge','K6-1-u4-C9',3,'mc','auto','「내가 늘 헤매던 까닭이 그제야 가닥이 잡혔다.」에 담긴 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X01','K6-1-u4-X21']::text[],false,'{"seq":3,"concept":"K6-1-u4-C9","difficulty":3,"kind":"mc","stem":"「내가 늘 헤매던 까닭이 그제야 가닥이 잡혔다.」에 담긴 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"헝클어져 있던 일의 갈피가 잡혀 까닭을 깨달았다","correct":true},{"t":"흩어진 실을 한 가닥으로 묶었다","mis":"K6-1-u4-X01"},{"t":"도서관에서 길을 잃고 헤맸다","mis":"K6-1-u4-X21"},{"t":"머리카락을 가지런히 묶었다","mis":"K6-1-u4-X01"}],"explanation":["실을 묶은 이야기가 아니에요.","길을 잃은 것도 아니에요.","왜 헤맸는지 깨달았어요."],"asset":{"type":"passage","lines":["지난 화요일, 우리 반은 고장의 도서관에 갔다.","사서 선생님을 따라 처음 들어간 곳은 일반 서고였다.","모든 책에는 숫자가 붙어 있었다. 책의 주제에 따라 숫자를 정해 두고","그 차례대로 꽂는다고 한다. 내가 늘 헤매던 까닭이 그제야 가닥이 잡혔다."],"title":"「도서관 서고를 다녀와서」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L11_challenge#4','kor',6,1,'u4','L11','g6_1_kor_u4_L11_challenge','lesson_challenge','K6-1-u4-C42',3,'error','auto','친구의 발표를 듣는 모습이에요. 예절에 알맞지 않은 친구는 누구인가요?',ARRAY['K6-1-u4-X42']::text[],false,'{"seq":4,"concept":"K6-1-u4-C42","difficulty":3,"kind":"error","stem":"친구의 발표를 듣는 모습이에요. 예절에 알맞지 않은 친구는 누구인가요?","options":[{"t":"하린 — 발표하는 친구 쪽을 보지 않고 짝과 작은 소리로 이야기했다","correct":true,"mis_target":"K6-1-u4-X42"},{"t":"시안 — 바른 자세로 발표하는 친구를 보며 끝까지 들었다","mis":"K6-1-u4-X42"},{"t":"연우 — 발표가 끝난 뒤 존댓말로 궁금한 것을 물었다","mis":"K6-1-u4-X42"}],"explanation":["시안이는 끝까지 경청했어요.","연우는 끝난 뒤 존댓말로 물었어요.","발표 중에는 짝과 이야기하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L11_challenge#5','kor',6,1,'u4','L11','g6_1_kor_u4_L11_challenge','lesson_challenge','K6-1-u4-C41',3,'mc','auto','관용 표현 사전에 넣을 표현을 고르는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X40']::text[],false,'{"seq":5,"concept":"K6-1-u4-C41","difficulty":3,"kind":"mc","stem":"관용 표현 사전에 넣을 표현을 고르는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"이번 달에 한 번은 쓸 자리가 떠오르는 표현 다섯 개를 고른다","correct":true},{"t":"아무도 모르는 어려운 표현을 스무 개 고른다","mis":"K6-1-u4-X40"},{"t":"가장 긴 표현부터 고른다","mis":"K6-1-u4-X40"},{"t":"사전 앞쪽에 나오는 표현을 차례대로 고른다","mis":"K6-1-u4-X40"}],"explanation":["어려운 표현은 쓰지 않게 돼요.","길이는 기준이 아니에요.","쓸 자리가 떠오르는지가 기준이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L11_challenge#6','kor',6,1,'u4','L11','g6_1_kor_u4_L11_challenge','lesson_challenge','K6-1-u4-C39',3,'mc','auto','「서당 개 삼 년이면 풍월을 읊는다」를 쓰기에 알맞은 상황은 어느 것인가요?',ARRAY['K6-1-u4-X08','K6-1-u4-X01']::text[],false,'{"seq":6,"concept":"K6-1-u4-C39","difficulty":3,"kind":"mc","stem":"「서당 개 삼 년이면 풍월을 읊는다」를 쓰기에 알맞은 상황은 어느 것인가요?","options":[{"t":"옆에서 지켜보기만 했는데 어느새 할 줄 알게 되었을 때","correct":true},{"t":"늘 잘하던 친구가 한 번 실수했을 때","mis":"K6-1-u4-X08"},{"t":"모두 찬성했지만 아무도 나서지 않는 일을 두고","mis":"K6-1-u4-X08"},{"t":"강아지를 오래 길렀을 때","mis":"K6-1-u4-X01"}],"explanation":["실수는 원숭이 속담이에요.","나서지 않는 일은 방울 달기예요.","오래 보고 들어 저절로 익혔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L11_challenge#7','kor',6,1,'u4','L11','g6_1_kor_u4_L11_challenge','lesson_challenge','K6-1-u4-C42',3,'mc','auto','공식적인 말하기에서 목소리 크기 · 표정 · 자세까지 살피는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X43','K6-1-u4-X42']::text[],false,'{"seq":7,"concept":"K6-1-u4-C42","difficulty":3,"kind":"mc","stem":"공식적인 말하기에서 목소리 크기 · 표정 · 자세까지 살피는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"말의 내용뿐 아니라 이것들도 듣는 사람이 편하게 듣는 데 영향을 주기 때문에","correct":true},{"t":"외워야 할 예절 목록에 적혀 있기 때문에","mis":"K6-1-u4-X43"},{"t":"말의 내용은 중요하지 않기 때문에","mis":"K6-1-u4-X43"},{"t":"비공식적인 자리와 예절이 같기 때문에","mis":"K6-1-u4-X42"}],"explanation":["목록이라서가 아니에요.","내용도 중요해요.","듣는 사람이 편한지가 기준이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L11_challenge#8','kor',6,1,'u4','L11','g6_1_kor_u4_L11_challenge','lesson_challenge','K6-1-u4-C40',4,'mc','auto','누리가 만든 사전 한 장을 가장 알맞게 고친 것은 어느 것인가요?',ARRAY['K6-1-u4-X41','K6-1-u4-X11','K6-1-u4-X40']::text[],false,'{"seq":8,"concept":"K6-1-u4-C40","difficulty":4,"kind":"mc","stem":"누리가 만든 사전 한 장을 가장 알맞게 고친 것은 어느 것인가요?","options":[{"t":"뜻은 「여러 번 들어 익숙하다」처럼 내 말로 줄이고, 쓸 상황에 내가 겪은 일을 적고, 친구 수는 뺀다","correct":true},{"t":"아는 친구의 수를 더 정확히 세어 적는다","mis":"K6-1-u4-X41"},{"t":"사전 뜻풀이를 더 길게 옮겨 적는다","mis":"K6-1-u4-X11"},{"t":"다른 표현을 세 개 더 채워 넣는다","mis":"K6-1-u4-X40"}],"explanation":["친구 수는 쓸모가 없어요.","길게 옮기면 내 말이 아니에요.","세 칸을 제대로 채워요."],"asset":{"type":"passage","lines":["표현 — 귀에 익다","뜻 — (사전 뜻풀이를 한 글자도 빼지 않고 길게 옮겨 적음)","쓸 수 있는 상황 — (비어 있음)","덧붙임 — 이 표현을 아는 우리 반 친구의 수"],"title":"누리가 만든 관용 표현 사전 한 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L11_challenge#9','kor',6,1,'u4','L11','g6_1_kor_u4_L11_challenge','lesson_challenge','K6-1-u4-C39',4,'essay','teacher','관용 표현 사전의 주제를 하나 정하고(낱말로 묶기 또는 마음으로 묶기), 그 주제에 맞는 표현 두 개를 골라 표현 · 뜻 · 쓸 수 있는 상황을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u4-C39","difficulty":4,"kind":"essay","stem":"관용 표현 사전의 주제를 하나 정하고(낱말로 묶기 또는 마음으로 묶기), 그 주제에 맞는 표현 두 개를 골라 표현 · 뜻 · 쓸 수 있는 상황을 쓰세요.","answer_guide":{"answer":"예: 주제 — 마음으로 묶기, 「간절함」. 표현 하나 — 목이 빠지게 기다리다 / 몹시 애타게 기다리다 / 방학에 할머니 댁에 갈 날을 기다릴 때. 표현 둘 — 마음이 굴뚝같다 / 무엇을 몹시 하고 싶어 하다 / 감기로 축구 시합에 못 나갔지만 뛰고 싶을 때.","scoring_points":["묶는 방법과 주제를 정했는가","주제에 맞는 표현 두 개를 골랐는가","표현마다 뜻과 내 쓸 상황을 썼는가"]},"explanation":["묶는 방법을 정해요.","주제에 맞는 표현을 골라요.","세 칸을 채워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_L11_challenge#10','kor',6,1,'u4','L11','g6_1_kor_u4_L11_challenge','lesson_challenge','K6-1-u4-C42',4,'essay','teacher','쉬는 시간에 친구와 이야기할 때와 학급 전체 앞에서 발표할 때 지킬 예절이 어떻게 다른지 쓰고, 왜 달라지는지 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u4-C42","difficulty":4,"kind":"essay","stem":"쉬는 시간에 친구와 이야기할 때와 학급 전체 앞에서 발표할 때 지킬 예절이 어떻게 다른지 쓰고, 왜 달라지는지 설명하세요.","answer_guide":{"answer":"예: 쉬는 시간에는 둘레에 방해가 되지 않게 작은 소리로 말하고, 말차례를 지키며 고개를 끄덕이는 등 반응을 보인다. 발표할 때에는 존댓말로, 모두 들을 수 있는 크기로, 바른 자세로 듣는 사람을 보며 말한다. 듣는 사람의 수와 자리가 달라 듣는 사람이 편하게 들을 수 있는 방법도 달라지기 때문이다.","scoring_points":["비공식적인 말하기의 예절을 썼는가","공식적인 말하기의 예절을 썼는가","듣는 사람을 기준으로 달라지는 까닭을 썼는가"]},"explanation":["쉬는 시간을 떠올려요.","발표하는 자리를 떠올려요.","듣는 사람을 두고 까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#1','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C1',1,'mc','auto','오래 쓰이며 굳어져 낱말 뜻의 합과는 다른 새로운 뜻을 지닌 말을 무엇이라고 하나요?',ARRAY['K6-1-u4-X05']::text[],false,'{"seq":1,"concept":"K6-1-u4-C1","difficulty":1,"kind":"mc","stem":"오래 쓰이며 굳어져 낱말 뜻의 합과는 다른 새로운 뜻을 지닌 말을 무엇이라고 하나요?","options":[{"t":"관용 표현","correct":true},{"t":"줄임말","mis":"K6-1-u4-X05"},{"t":"흉내 내는 말","mis":"K6-1-u4-X05"},{"t":"높임말","mis":"K6-1-u4-X05"}],"explanation":["줄임말은 짧게 줄인 말이에요.","흉내 내는 말은 소리나 모양을 흉내 내요.","굳어져 새 뜻을 지닌 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#2','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C3',1,'mc','auto','「진땀을 빼다」는 관용어와 속담 가운데 무엇인가요?',ARRAY['K6-1-u4-X04','K6-1-u4-X01']::text[],false,'{"seq":2,"concept":"K6-1-u4-C3","difficulty":1,"kind":"mc","stem":"「진땀을 빼다」는 관용어와 속담 가운데 무엇인가요?","options":[{"t":"관용어","correct":true},{"t":"속담","mis":"K6-1-u4-X04"},{"t":"관용 표현이 아니다","mis":"K6-1-u4-X01"},{"t":"표어","mis":"K6-1-u4-X04"}],"explanation":["교훈을 담은 말이 아니에요.","뜻 그대로가 아니에요.","낱말이 합쳐져 새 뜻을 이룬 관용어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#3','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C9',1,'mc','auto','「진땀을 빼다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X01']::text[],false,'{"seq":3,"concept":"K6-1-u4-C9","difficulty":1,"kind":"mc","stem":"「진땀을 빼다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"어려운 일을 겪으며 몹시 애를 쓰다","correct":true},{"t":"흐르는 땀을 수건으로 닦다","mis":"K6-1-u4-X01"},{"t":"땀이 전혀 나지 않다","mis":"K6-1-u4-X01"},{"t":"더워서 겉옷을 벗다","mis":"K6-1-u4-X01"}],"explanation":["땀 닦는 이야기가 아니에요.","땀이 안 나는 것도 아니에요.","몹시 애쓴다는 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#4','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C15',1,'mc','auto','「빈 수레가 요란하다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X16','K6-1-u4-X17']::text[],false,'{"seq":4,"concept":"K6-1-u4-C15","difficulty":1,"kind":"mc","stem":"「빈 수레가 요란하다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"잘 알지 못하는 사람이 오히려 더 떠든다","correct":true},{"t":"빈 수레는 가벼워 끌기 쉽다","mis":"K6-1-u4-X16"},{"t":"짐을 많이 실어야 수레가 잘 간다","mis":"K6-1-u4-X16"},{"t":"수레는 시끄러우니 쓰지 말아야 한다","mis":"K6-1-u4-X17"}],"explanation":["끌기 쉽다는 이야기가 아니에요.","짐 싣는 법도 아니에요.","빈 수레가 덜컹거려 시끄러워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#5','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C24',1,'mc','auto','관용 표현을 쓰기 전에 뜻과 함께 살필 것은 어느 것인가요?',ARRAY['K6-1-u4-X07','K6-1-u4-X40']::text[],false,'{"seq":5,"concept":"K6-1-u4-C24","difficulty":1,"kind":"mc","stem":"관용 표현을 쓰기 전에 뜻과 함께 살필 것은 어느 것인가요?","options":[{"t":"듣는 사람과 지금 이 자리","correct":true},{"t":"표현의 글자 수","mis":"K6-1-u4-X07"},{"t":"표현을 몇 개 넣는지","mis":"K6-1-u4-X07"},{"t":"표현이 얼마나 어려운지","mis":"K6-1-u4-X40"}],"explanation":["글자 수는 상관없어요.","개수도 상관없어요.","누구에게, 어떤 자리인지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#6','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C27',1,'mc','auto','견학하고 새롭게 안 사실을 중심으로 보고 듣고 느낀 것을 쓴 글은 무엇인가요?',ARRAY['K6-1-u4-X30','K6-1-u4-X29','K6-1-u4-X26']::text[],false,'{"seq":6,"concept":"K6-1-u4-C27","difficulty":1,"kind":"mc","stem":"견학하고 새롭게 안 사실을 중심으로 보고 듣고 느낀 것을 쓴 글은 무엇인가요?","options":[{"t":"견학 기록문","correct":true},{"t":"일기","mis":"K6-1-u4-X30"},{"t":"안내문","mis":"K6-1-u4-X29"},{"t":"지어낸 이야기","mis":"K6-1-u4-X26"}],"explanation":["일기는 마음 중심이에요.","안내문은 사실만 있어요.","새로 안 사실과 마음이 함께 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#7','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C34',1,'mc','auto','견학 기록문을 쓰기 전에 정해 둘 세 가지는 어느 것인가요?',ARRAY['K6-1-u4-X38','K6-1-u4-X07','K6-1-u4-X34']::text[],false,'{"seq":7,"concept":"K6-1-u4-C34","difficulty":1,"kind":"mc","stem":"견학 기록문을 쓰기 전에 정해 둘 세 가지는 어느 것인가요?","options":[{"t":"목적 · 주제 · 읽을 사람","correct":true},{"t":"글씨체 · 종이 · 펜","mis":"K6-1-u4-X38"},{"t":"길이 · 문단 수 · 관용 표현 개수","mis":"K6-1-u4-X07"},{"t":"제목 · 사진 · 날씨","mis":"K6-1-u4-X34"}],"explanation":["도구는 정할 것이 아니에요.","개수는 기준이 아니에요.","왜, 무엇을, 누구에게 쓸지 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#8','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C40',1,'mc','auto','관용 표현 사전 한 장에 쓸 상황을 적는 까닭은 어느 것인가요?',ARRAY['K6-1-u4-X37','K6-1-u4-X41']::text[],false,'{"seq":8,"concept":"K6-1-u4-C40","difficulty":1,"kind":"mc","stem":"관용 표현 사전 한 장에 쓸 상황을 적는 까닭은 어느 것인가요?","options":[{"t":"필요할 때 떠올라 꺼내 쓸 수 있어서","correct":true},{"t":"쪽수를 채우려고","mis":"K6-1-u4-X37"},{"t":"표현이 생긴 때를 알리려고","mis":"K6-1-u4-X41"},{"t":"아는 친구 수를 세려고","mis":"K6-1-u4-X41"}],"explanation":["쪽수 채우기가 아니에요.","생긴 때는 쓸모없어요.","내 상황이 적혀야 떠올라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#9','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C9',2,'mc','auto','하늬가 말한 「코앞에 닥쳤는데」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X01','K6-1-u4-X08','K6-1-u4-X12']::text[],false,'{"seq":9,"concept":"K6-1-u4-C9","difficulty":2,"kind":"mc","stem":"하늬가 말한 「코앞에 닥쳤는데」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"대회가 아주 가까이 다가왔다","correct":true},{"t":"코 바로 앞에 무엇이 놓였다","mis":"K6-1-u4-X01"},{"t":"대회가 아주 멀리 남았다","mis":"K6-1-u4-X08"},{"t":"코가 막혀 노래하기 어렵다","mis":"K6-1-u4-X12"}],"explanation":["코 앞에 물건이 놓인 것이 아니에요.","멀리 남은 것과 반대예요.","날이 바짝 다가왔다는 뜻이에요."],"asset":{"type":"speech","turns":[{"who":"하늬","text":"합창 대회가 코앞에 닥쳤는데 반주를 맡은 이든이가 아직 악보를 다 못 외웠대. 걱정이야."},{"who":"가온","text":"이든이는 늘 잘하잖아. 원숭이도 나무에서 떨어진다고, 이번엔 좀 늦을 수도 있지."},{"who":"이든","text":"사실 어깨가 무거워서 밤마다 연습했어. 그래도 첫술에 배부르랴, 내일은 더 나아질 거야."},{"who":"하늬","text":"그럼 걱정 붙들어 맬게. 우리 모두 네 반주를 목이 빠지게 기다릴게."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#10','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C23',2,'mc','auto','하늬의 「목이 빠지게 기다릴게」와 가리키는 마음이 가장 가까운 표현은 어느 것인가요?',ARRAY['K6-1-u4-X22']::text[],false,'{"seq":10,"concept":"K6-1-u4-C23","difficulty":2,"kind":"mc","stem":"하늬의 「목이 빠지게 기다릴게」와 가리키는 마음이 가장 가까운 표현은 어느 것인가요?","options":[{"t":"마음이 굴뚝같다","correct":true},{"t":"낯이 뜨겁다","mis":"K6-1-u4-X22"},{"t":"발등에 불이 떨어지다","mis":"K6-1-u4-X22"},{"t":"입이 무겁다","mis":"K6-1-u4-X22"}],"explanation":["낯이 뜨겁다는 부끄러움이에요.","발등에 불은 급함이에요.","간절한 마음끼리 가까워요."],"asset":{"type":"speech","turns":[{"who":"하늬","text":"합창 대회가 코앞에 닥쳤는데 반주를 맡은 이든이가 아직 악보를 다 못 외웠대. 걱정이야."},{"who":"가온","text":"이든이는 늘 잘하잖아. 원숭이도 나무에서 떨어진다고, 이번엔 좀 늦을 수도 있지."},{"who":"이든","text":"사실 어깨가 무거워서 밤마다 연습했어. 그래도 첫술에 배부르랴, 내일은 더 나아질 거야."},{"who":"하늬","text":"그럼 걱정 붙들어 맬게. 우리 모두 네 반주를 목이 빠지게 기다릴게."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#11','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C29',2,'mc','auto','로아 글의 첫 두 줄에 들어 있는 처음 부분의 내용은 어느 것인가요?',ARRAY['K6-1-u4-X28']::text[],false,'{"seq":11,"concept":"K6-1-u4-C29","difficulty":2,"kind":"mc","stem":"로아 글의 첫 두 줄에 들어 있는 처음 부분의 내용은 어느 것인가요?","options":[{"t":"언제 · 누구와 · 왜 · 어디에 갔는지","correct":true},{"t":"견학을 정리하고 깨달은 점","mis":"K6-1-u4-X28"},{"t":"물을 소독하는 방법","mis":"K6-1-u4-X28"},{"t":"다음에 가고 싶은 곳","mis":"K6-1-u4-X28"}],"explanation":["깨달은 점은 끝이에요.","소독은 가운데의 견문이에요.","처음에는 개요를 알려요."],"asset":{"type":"passage","lines":["지난 금요일, 우리 반은 수돗물이 어떻게 만들어지는지 알아보려고","고장의 정수장에 다녀왔다. 학교에서 버스를 타고 강가로 갔다.","먼저 강물을 끌어오는 곳을 보았다. 강물에는 흙 알갱이가 섞여 있어서","약품을 넣어 작은 알갱이끼리 뭉치게 한 뒤 가라앉힌다고 했다.","흙탕물이 맑아지는 모습에 입이 딱 벌어졌다."],"title":"로아의 견학 기록문 「정수장을 다녀와서」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#12','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C28',2,'mc','auto','로아 글 뒷부분에서 여정이 드러난 것은 어느 것인가요?',ARRAY['K6-1-u4-X27']::text[],false,'{"seq":12,"concept":"K6-1-u4-C28","difficulty":2,"kind":"mc","stem":"로아 글 뒷부분에서 여정이 드러난 것은 어느 것인가요?","options":[{"t":"「다음으로 모래와 자갈을 깐 층으로 물을 거르는 곳에 갔다.」","correct":true},{"t":"「소독을 해서 해로운 균을 없앤다고 했다.」","mis":"K6-1-u4-X27"},{"t":"「물을 틀어 놓은 채로 양치하지 않아야겠다.」","mis":"K6-1-u4-X27"},{"t":"「여러 단계를 거친다는 것을 알았다.」","mis":"K6-1-u4-X27"}],"explanation":["소독은 새로 안 사실이에요.","다짐은 감상과 깨달음이에요.","어디로 옮겨 갔는지가 여정이에요."],"asset":{"type":"passage","lines":["다음으로 모래와 자갈을 깐 층으로 물을 거르는 곳에 갔다.","마지막으로 소독을 해서 물속의 해로운 균을 없앤 뒤 집으로 보낸다고 했다.","수도꼭지만 틀면 나오던 물이 이렇게 여러 단계를 거친다는 것을 알았다.","앞으로는 물을 틀어 놓은 채로 양치하지 않아야겠다."],"title":"로아의 견학 기록문 「정수장을 다녀와서」 — 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#13','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C36',2,'mc','auto','다음 가운데 관용 표현이 감상 자리에 알맞게 놓인 문장은 어느 것인가요?',ARRAY['K6-1-u4-X36']::text[],false,'{"seq":13,"concept":"K6-1-u4-C36","difficulty":2,"kind":"mc","stem":"다음 가운데 관용 표현이 감상 자리에 알맞게 놓인 문장은 어느 것인가요?","options":[{"t":"「흙탕물이 맑아지는 모습에 입이 딱 벌어졌다.」","correct":true},{"t":"「약품은 눈코 뜰 새 없이 알갱이를 뭉치게 한다.」","mis":"K6-1-u4-X36"},{"t":"「소독은 진땀을 빼며 해로운 균을 없앤다.」","mis":"K6-1-u4-X36"},{"t":"「모래층은 손이 열 개라도 모자라게 물을 거른다.」","mis":"K6-1-u4-X36"}],"explanation":["사실 자리에 얹었어요.","이것도 사실 자리예요.","놀란 마음 자리에 놓였어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#14','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C29',2,'mc','auto','로아의 조직표에서 처음 칸에 더해야 할 것은 어느 것인가요?',ARRAY['K6-1-u4-X28','K6-1-u4-X07']::text[],false,'{"seq":14,"concept":"K6-1-u4-C29","difficulty":2,"kind":"mc","stem":"로아의 조직표에서 처음 칸에 더해야 할 것은 어느 것인가요?","options":[{"t":"견학한 까닭(수돗물이 어떻게 만들어지는지 알아보려고)","correct":true},{"t":"견학을 정리한 깨달은 점","mis":"K6-1-u4-X28"},{"t":"소독하는 방법","mis":"K6-1-u4-X28"},{"t":"넣을 관용 표현","mis":"K6-1-u4-X07"}],"explanation":["깨달은 점은 끝 칸이에요.","소독은 가운데 칸이에요.","처음에는 까닭도 들어가요."],"asset":{"type":"passage","lines":["처음 — 지난 금요일 · 반 친구들과 · 고장의 정수장","가운데 첫째 — 강물 끌어오는 곳 / 알갱이를 뭉쳐 가라앉힘 / (느낀 것 없음)","가운데 둘째 — 모래와 자갈 층 / 물을 거름 / (느낀 것 없음)","가운데 셋째 — 소독하는 곳 / 해로운 균을 없앰 / (느낀 것 없음)","끝 — 정말 재미있었다."],"title":"로아의 조직표 (고치기 전)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#15','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C17',2,'mc','auto','「급할수록 돌아가라」와 「첫술에 배부르랴」를 바꿔 쓸 수 있는지 정할 때 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X18','K6-1-u4-X16']::text[],false,'{"seq":15,"concept":"K6-1-u4-C17","difficulty":2,"kind":"mc","stem":"「급할수록 돌아가라」와 「첫술에 배부르랴」를 바꿔 쓸 수 있는지 정할 때 알맞은 것은 어느 것인가요?","options":[{"t":"서두른다고 빨라지지 않는다는 뜻이 겹치지만, 쓸 상황까지 견주어 정한다","correct":true},{"t":"뜻이 겹치니 언제나 바꿔 쓴다","mis":"K6-1-u4-X18"},{"t":"글자 수가 달라 바꿀 수 없다","mis":"K6-1-u4-X18"},{"t":"두 속담은 뜻이 반대이다","mis":"K6-1-u4-X16"}],"explanation":["늘 바꿀 수 있는 것은 아니에요.","글자 수는 상관없어요.","쓸 상황까지 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#16','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C42',2,'mc','auto','시온이의 발표에서 고칠 점으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X42']::text[],false,'{"seq":16,"concept":"K6-1-u4-C42","difficulty":2,"kind":"mc","stem":"시온이의 발표에서 고칠 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"모두 들을 수 있는 크기로, 듣는 사람을 보며, 존댓말로 말한다","correct":true},{"t":"지금보다 더 작은 목소리로 말한다","mis":"K6-1-u4-X42"},{"t":"반말을 그대로 쓴다","mis":"K6-1-u4-X42"},{"t":"쉬는 시간에 짝과 이야기하듯 편하게 말한다","mis":"K6-1-u4-X42"}],"explanation":["작은 목소리는 여럿에게 안 들려요.","여럿 앞에서는 존댓말을 써요.","공식적인 자리에 맞게 말해요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"이제 시온이가 모둠에서 조사한 내용을 반 친구들 앞에서 발표하겠습니다."},{"who":"시온","text":"(작은 목소리로, 칠판 쪽을 보며) 우리 모둠은 정수장에 대해 알아봤어. 물을 여러 번 거른대."},{"who":"다인","text":"(발표 도중에 짝에게) 이따 쉬는 시간에 뭐 할래?"},{"who":"태하","text":"(발표가 끝나자) 잘 들었습니다. 소독은 어떻게 하는지 여쭤봐도 될까요?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#17','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C1',3,'error','auto','「입을 모으다」를 설명했어요. 알맞지 않게 설명한 친구는 누구인가요?',ARRAY['K6-1-u4-X01']::text[],false,'{"seq":17,"concept":"K6-1-u4-C1","difficulty":3,"kind":"error","stem":"「입을 모으다」를 설명했어요. 알맞지 않게 설명한 친구는 누구인가요?","options":[{"t":"하랑 — 「입술을 동그랗게 모은다는 뜻이야.」","correct":true,"mis_target":"K6-1-u4-X01"},{"t":"다은 — 「여럿이 같은 말을 한다는 뜻이야.」","mis":"K6-1-u4-X01"},{"t":"주원 — 「낱말 뜻의 합과는 다른 뜻을 지녔어.」","mis":"K6-1-u4-X01"}],"explanation":["다은이는 뜻을 바르게 말했어요.","주원이는 성질을 바르게 말했어요.","글자 그대로 읽으면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#18','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C17',3,'error','auto','비슷한 속담을 견주어 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u4-X18']::text[],false,'{"seq":18,"concept":"K6-1-u4-C17","difficulty":3,"kind":"error","stem":"비슷한 속담을 견주어 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"은재 — 「가랑비 속담과 바늘 도둑 속담은 기우는 방향까지 똑같아.」","correct":true,"mis_target":"K6-1-u4-X18"},{"t":"민결 — 「둘 다 작은 것이 쌓인다는 뜻이 겹쳐.」","mis":"K6-1-u4-X18"},{"t":"서율 — 「바늘 도둑은 나쁜 일이 커지는 쪽이야.」","mis":"K6-1-u4-X18"}],"explanation":["민결이는 겹치는 뜻을 바르게 말했어요.","서율이는 기우는 방향을 바르게 말했어요.","기우는 방향은 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#19','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C24',3,'error','auto','친구들이 관용 표현을 쓴 말이에요. 알맞지 않게 쓴 친구는 누구인가요?',ARRAY['K6-1-u4-X08','K6-1-u4-X23']::text[],false,'{"seq":19,"concept":"K6-1-u4-C24","difficulty":3,"kind":"error","stem":"친구들이 관용 표현을 쓴 말이에요. 알맞지 않게 쓴 친구는 누구인가요?","options":[{"t":"라온 — 아파서 결석한 짝에게 「눈코 뜰 새 없이 바빴겠구나.」라고 했다","correct":true,"mis_target":"K6-1-u4-X08"},{"t":"예린 — 늘 잘하던 친구가 실수하자 「원숭이도 나무에서 떨어진다잖아.」라고 위로했다","mis":"K6-1-u4-X23"},{"t":"도윤 — 연습을 미룬 자신에게 「내가 빈 수레가 요란했구나.」라고 썼다","mis":"K6-1-u4-X23"}],"explanation":["예린이는 위로하는 자리에 맞게 썼어요.","도윤이는 자신을 돌아봤어요.","아픈 친구에게 바빴냐고 하면 어긋나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#20','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C30',3,'error','auto','견학 기록문을 고쳐 쓰자는 의견이에요. 알맞지 않은 의견을 낸 친구는 누구인가요?',ARRAY['K6-1-u4-X29','K6-1-u4-X30','K6-1-u4-X35']::text[],false,'{"seq":20,"concept":"K6-1-u4-C30","difficulty":3,"kind":"error","stem":"견학 기록문을 고쳐 쓰자는 의견이에요. 알맞지 않은 의견을 낸 친구는 누구인가요?","options":[{"t":"하율 — 「사실만 늘어놓으면 깔끔하니 마음은 다 지우자.」","correct":true,"mis_target":"K6-1-u4-X29"},{"t":"지유 — 「느낌만 있으니 새로 안 사실을 더하자.」","mis":"K6-1-u4-X30"},{"t":"건우 — 「본 것 하나에 느낀 것 하나를 붙이자.」","mis":"K6-1-u4-X35"}],"explanation":["지유는 견문을 더하자고 했어요.","건우는 짝짓자고 했어요.","마음을 다 지우면 안내문이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#21','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C34',3,'mc','auto','같은 정수장 견학을 할머니께 보낼 글로 쓴다면 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X34','K6-1-u4-X30','K6-1-u4-X07']::text[],false,'{"seq":21,"concept":"K6-1-u4-C34","difficulty":3,"kind":"mc","stem":"같은 정수장 견학을 할머니께 보낼 글로 쓴다면 가장 알맞은 것은 어느 것인가요?","options":[{"t":"할머니가 궁금해하실 만한 것을 골라 읽기 편하게 쓰고, 큰 글씨나 직접 읽어 드리는 방법도 생각한다","correct":true},{"t":"누구에게 보내든 똑같이 쓴다","mis":"K6-1-u4-X34"},{"t":"새로 안 사실을 빼고 느낌만 쓴다","mis":"K6-1-u4-X30"},{"t":"관용 표현을 가득 넣는다","mis":"K6-1-u4-X07"}],"explanation":["읽을 사람이 달라지면 글도 달라져요.","견문을 빼면 안 돼요.","읽을 사람을 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#22','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C41',3,'error','auto','관용 표현 사전을 만들 계획이에요. 알맞지 않은 계획을 말한 친구는 누구인가요?',ARRAY['K6-1-u4-X40']::text[],false,'{"seq":22,"concept":"K6-1-u4-C41","difficulty":3,"kind":"error","stem":"관용 표현 사전을 만들 계획이에요. 알맞지 않은 계획을 말한 친구는 누구인가요?","options":[{"t":"태린 — 「아무도 모르는 어려운 표현으로 스무 개를 채울래.」","correct":true,"mis_target":"K6-1-u4-X40"},{"t":"소이 — 「이번 달에 한 번은 쓸 표현 다섯 개를 고를래.」","mis":"K6-1-u4-X40"},{"t":"하진 — 「쓸 상황이 안 떠오르는 표현은 다음으로 미룰래.」","mis":"K6-1-u4-X40"}],"explanation":["소이는 쓸 표현을 골랐어요.","하진이도 바르게 계획했어요.","어려운 표현을 채우면 쓰지 않게 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#23','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C20',4,'mc','auto','합창 대회 대화에서 세 친구가 관용 표현을 쓴 방식을 가장 알맞게 평가한 것은 어느 것인가요?',ARRAY['K6-1-u4-X07','K6-1-u4-X01','K6-1-u4-X20']::text[],false,'{"seq":23,"concept":"K6-1-u4-C20","difficulty":4,"kind":"mc","stem":"합창 대회 대화에서 세 친구가 관용 표현을 쓴 방식을 가장 알맞게 평가한 것은 어느 것인가요?","options":[{"t":"저마다 상황과 듣는 사람에 맞는 표현을 골라 감싸 주고, 다짐하고, 응원하는 마음을 짧고 또렷하게 전했다","correct":true},{"t":"관용 표현을 많이 넣었으니 좋은 대화다","mis":"K6-1-u4-X07"},{"t":"모두 낱말 뜻 그대로 썼다","mis":"K6-1-u4-X01"},{"t":"가온이는 이든이를 놀리려고 속담을 썼다","mis":"K6-1-u4-X20"}],"explanation":["개수 때문에 좋은 것이 아니에요.","낱말 뜻 그대로가 아니에요.","가온이는 감싸 주려 했어요."],"asset":{"type":"speech","turns":[{"who":"하늬","text":"합창 대회가 코앞에 닥쳤는데 반주를 맡은 이든이가 아직 악보를 다 못 외웠대. 걱정이야."},{"who":"가온","text":"이든이는 늘 잘하잖아. 원숭이도 나무에서 떨어진다고, 이번엔 좀 늦을 수도 있지."},{"who":"이든","text":"사실 어깨가 무거워서 밤마다 연습했어. 그래도 첫술에 배부르랴, 내일은 더 나아질 거야."},{"who":"하늬","text":"그럼 걱정 붙들어 맬게. 우리 모두 네 반주를 목이 빠지게 기다릴게."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#24','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C24',4,'essay','teacher','대회에서 이든이가 반주를 한 군데 틀렸어요. 하늬가 할 말을 관용 표현 하나를 넣어 쓰고, 그 표현이 이 자리와 듣는 사람에게 알맞은 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u4-C24","difficulty":4,"kind":"essay","stem":"대회에서 이든이가 반주를 한 군데 틀렸어요. 하늬가 할 말을 관용 표현 하나를 넣어 쓰고, 그 표현이 이 자리와 듣는 사람에게 알맞은 까닭을 쓰세요.","answer_guide":{"answer":"예: 「원숭이도 나무에서 떨어진다잖아. 그동안 밤마다 연습한 거 다 알아. 다음엔 더 잘될 거야.」 이든이는 실수해서 속상할 것이므로 위로하는 말이 필요하다. 「원숭이도 나무에서 떨어진다」는 잘하는 사람도 실수할 때가 있다는 뜻이라 이든이를 감싸 주는 자리에 맞는다. 「빈 수레가 요란하다」처럼 깎아내리는 표현은 이 자리에 맞지 않는다.","scoring_points":["관용 표현 하나를 넣어 하늬의 말을 썼는가","표현의 뜻이 상황과 맞는 까닭을 썼는가","듣는 사람의 마음을 생각한 까닭을 썼는가"]},"explanation":["이든이의 마음을 떠올려요.","위로하는 표현을 골라요.","까닭을 함께 써요."],"asset":{"type":"speech","turns":[{"who":"하늬","text":"합창 대회가 코앞에 닥쳤는데 반주를 맡은 이든이가 아직 악보를 다 못 외웠대. 걱정이야."},{"who":"가온","text":"이든이는 늘 잘하잖아. 원숭이도 나무에서 떨어진다고, 이번엔 좀 늦을 수도 있지."},{"who":"이든","text":"사실 어깨가 무거워서 밤마다 연습했어. 그래도 첫술에 배부르랴, 내일은 더 나아질 거야."},{"who":"하늬","text":"그럼 걱정 붙들어 맬게. 우리 모두 네 반주를 목이 빠지게 기다릴게."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_a#25','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C6',4,'essay','teacher','「관용 표현은 제자리에 놓일 때만 힘을 낸다」는 말을 개수 · 듣는 사람 · 글의 자리 세 가지와 이어 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u4-C6","difficulty":4,"kind":"essay","stem":"「관용 표현은 제자리에 놓일 때만 힘을 낸다」는 말을 개수 · 듣는 사람 · 글의 자리 세 가지와 이어 설명하세요.","answer_guide":{"answer":"예: 첫째, 관용 표현은 많이 넣는다고 좋아지지 않고 상황에 맞는 하나가 힘이 크다. 둘째, 같은 표현도 누구에게 하느냐에 따라 위로가 되기도 하고 상처가 되기도 하므로 듣는 사람과 자리를 살펴야 한다. 셋째, 견학 기록문에서는 사실을 전하는 견문 자리가 아니라 마음이 드러나는 감상 자리에 놓아야 한다.","scoring_points":["개수의 문제를 썼는가","듣는 사람과 자리의 문제를 썼는가","글에서 놓일 자리(감상)를 썼는가"]},"explanation":["개수를 떠올려요.","듣는 사람을 떠올려요.","견학 기록문의 자리를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#1','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C2',1,'ox','auto','「창문을 닦다」는 관용 표현이에요.',ARRAY['K6-1-u4-X02']::text[],false,'{"seq":1,"concept":"K6-1-u4-C2","difficulty":1,"kind":"ox","stem":"「창문을 닦다」는 관용 표현이에요.","answer":"X","reason_options":[{"t":"낱말 뜻을 그대로 더해도 말이 통하기 때문에","correct":true},{"t":"두 낱말이 합쳐진 말은 모두 관용 표현이기 때문에","mis":"K6-1-u4-X02"}],"mis":"K6-1-u4-X02","explanation":["창문을 정말 닦는 말이에요.","뜻이 달라지지 않아요.","뜻 그대로면 관용 표현이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#2','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C4',1,'mc','auto','관용 표현에 우리 문화가 담겨 있다는 것을 보여 주는 것은 어느 것인가요?',ARRAY['K6-1-u4-X17','K6-1-u4-X01','K6-1-u4-X05']::text[],false,'{"seq":2,"concept":"K6-1-u4-C4","difficulty":1,"kind":"mc","stem":"관용 표현에 우리 문화가 담겨 있다는 것을 보여 주는 것은 어느 것인가요?","options":[{"t":"속담 속 수레 · 서당처럼 옛 생활 모습이 남아 있다","correct":true},{"t":"요즘 새로 만든 말이 많다","mis":"K6-1-u4-X17"},{"t":"낱말 뜻 그대로라 누구나 안다","mis":"K6-1-u4-X01"},{"t":"외국에서 들어온 말이 대부분이다","mis":"K6-1-u4-X05"}],"explanation":["오래 전해 온 말이에요.","낱말 뜻 그대로가 아니에요.","옛 생활이 말 속에 남았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#3','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C9',1,'mc','auto','「눈코 뜰 새 없다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X01','K6-1-u4-X12','K6-1-u4-X08']::text[],false,'{"seq":3,"concept":"K6-1-u4-C9","difficulty":1,"kind":"mc","stem":"「눈코 뜰 새 없다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"몹시 바쁘다","correct":true},{"t":"잠이 와서 눈이 감긴다","mis":"K6-1-u4-X01"},{"t":"감기로 코가 막혔다","mis":"K6-1-u4-X12"},{"t":"아무 일도 없어 한가하다","mis":"K6-1-u4-X08"}],"explanation":["졸린 이야기가 아니에요.","코가 막힌 것도 아니에요.","쉴 틈 없이 바쁘다는 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#4','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C15',1,'mc','auto','「가랑비에 옷 젖는 줄 모른다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X16']::text[],false,'{"seq":4,"concept":"K6-1-u4-C15","difficulty":1,"kind":"mc","stem":"「가랑비에 옷 젖는 줄 모른다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"사소한 것이 쌓여 큰 것이 되는 줄 모른다","correct":true},{"t":"비 오는 날에는 우산을 꼭 챙겨라","mis":"K6-1-u4-X16"},{"t":"젖은 옷은 금방 마른다","mis":"K6-1-u4-X16"},{"t":"큰비가 와야 옷이 젖는다","mis":"K6-1-u4-X16"}],"explanation":["우산 이야기가 아니에요.","옷 마르는 이야기도 아니에요.","작은 것이 쌓여 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#5','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C24',1,'ox','auto','상을 받은 친구에게 「빈 수레가 요란하다더니.」라고 말하는 것은 알맞아요.',ARRAY['K6-1-u4-X23']::text[],false,'{"seq":5,"concept":"K6-1-u4-C24","difficulty":1,"kind":"ox","stem":"상을 받은 친구에게 「빈 수레가 요란하다더니.」라고 말하는 것은 알맞아요.","answer":"X","reason_options":[{"t":"축하하려던 말이 깎아내리는 말이 되기 때문에","correct":true},{"t":"속담을 쓰면 말이 생생해지기 때문에","mis":"K6-1-u4-X23"}],"mis":"K6-1-u4-X23","explanation":["뜻은 하나지만","남을 가리키면 상처가 돼요.","듣는 사람과 자리를 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#6','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C28',1,'mc','auto','「그곳에서 보고 들은 것, 새롭게 안 사실」을 무엇이라고 하나요?',ARRAY['K6-1-u4-X27','K6-1-u4-X31']::text[],false,'{"seq":6,"concept":"K6-1-u4-C28","difficulty":1,"kind":"mc","stem":"「그곳에서 보고 들은 것, 새롭게 안 사실」을 무엇이라고 하나요?","options":[{"t":"견문","correct":true},{"t":"여정","mis":"K6-1-u4-X27"},{"t":"감상","mis":"K6-1-u4-X27"},{"t":"제목","mis":"K6-1-u4-X31"}],"explanation":["여정은 다닌 길이에요.","감상은 느낀 것이에요.","보고 들은 것은 견문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#7','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C35',1,'mc','auto','견학 기록문의 가운데가 사실만 늘어놓은 글이 되지 않게 하는 방법은 어느 것인가요?',ARRAY['K6-1-u4-X35','K6-1-u4-X29','K6-1-u4-X07']::text[],false,'{"seq":7,"concept":"K6-1-u4-C35","difficulty":1,"kind":"mc","stem":"견학 기록문의 가운데가 사실만 늘어놓은 글이 되지 않게 하는 방법은 어느 것인가요?","options":[{"t":"본 것 하나에 느낀 것 하나를 붙여 간다","correct":true},{"t":"느낌은 모두 끝에 몰아 쓴다","mis":"K6-1-u4-X35"},{"t":"사실 문장을 더 늘린다","mis":"K6-1-u4-X29"},{"t":"문단마다 관용 표현을 넣는다","mis":"K6-1-u4-X07"}],"explanation":["몰아 쓰면 가운데는 사실만 남아요.","사실을 늘리면 더 안내문 같아요.","본 것과 느낀 것을 짝지어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#8','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C42',1,'mc','auto','다음 가운데 공식적인 말하기 상황은 어느 것인가요?',ARRAY['K6-1-u4-X42']::text[],false,'{"seq":8,"concept":"K6-1-u4-C42","difficulty":1,"kind":"mc","stem":"다음 가운데 공식적인 말하기 상황은 어느 것인가요?","options":[{"t":"학급 전체 앞에서 조사한 내용을 발표할 때","correct":true},{"t":"쉬는 시간에 짝과 이야기할 때","mis":"K6-1-u4-X42"},{"t":"집에서 동생과 놀 때","mis":"K6-1-u4-X42"},{"t":"점심을 먹으며 친구와 이야기할 때","mis":"K6-1-u4-X42"}],"explanation":["짝과의 이야기는 비공식적이에요.","동생과도 비공식적이에요.","여럿 앞에서 발표하는 자리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#9','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C20',2,'mc','auto','가온이가 「원숭이도 나무에서 떨어진다고」를 쓴 의도로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X20','K6-1-u4-X21']::text[],false,'{"seq":9,"concept":"K6-1-u4-C20","difficulty":2,"kind":"mc","stem":"가온이가 「원숭이도 나무에서 떨어진다고」를 쓴 의도로 알맞은 것은 어느 것인가요?","options":[{"t":"늘 잘하던 이든이도 늦을 수 있다고 감싸 주려고","correct":true},{"t":"이든이를 놀리려고","mis":"K6-1-u4-X20"},{"t":"원숭이 이야기를 들려주려고","mis":"K6-1-u4-X21"},{"t":"이든이에게 반주를 그만두라고 하려고","mis":"K6-1-u4-X20"}],"explanation":["놀리는 말이 아니에요.","원숭이 이야기가 아니에요.","실수해도 괜찮다고 감싸 줬어요."],"asset":{"type":"speech","turns":[{"who":"하늬","text":"합창 대회가 코앞에 닥쳤는데 반주를 맡은 이든이가 아직 악보를 다 못 외웠대. 걱정이야."},{"who":"가온","text":"이든이는 늘 잘하잖아. 원숭이도 나무에서 떨어진다고, 이번엔 좀 늦을 수도 있지."},{"who":"이든","text":"사실 어깨가 무거워서 밤마다 연습했어. 그래도 첫술에 배부르랴, 내일은 더 나아질 거야."},{"who":"하늬","text":"그럼 걱정 붙들어 맬게. 우리 모두 네 반주를 목이 빠지게 기다릴게."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#10','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C24',2,'mc','auto','대회에서 이든이가 반주를 한 군데 틀렸어요. 하늬가 할 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X23','K6-1-u4-X08']::text[],false,'{"seq":10,"concept":"K6-1-u4-C24","difficulty":2,"kind":"mc","stem":"대회에서 이든이가 반주를 한 군데 틀렸어요. 하늬가 할 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「원숭이도 나무에서 떨어진다잖아. 다음엔 더 잘될 거야.」","correct":true},{"t":"「빈 수레가 요란하다더니.」","mis":"K6-1-u4-X23"},{"t":"「개구리 올챙이 적 생각 못 하는구나.」","mis":"K6-1-u4-X23"},{"t":"「고양이 목에 방울 달기네.」","mis":"K6-1-u4-X08"}],"explanation":["깎아내리는 말이 돼요.","이것도 상처가 돼요.","실수한 친구를 위로하는 자리예요."],"asset":{"type":"speech","turns":[{"who":"하늬","text":"합창 대회가 코앞에 닥쳤는데 반주를 맡은 이든이가 아직 악보를 다 못 외웠대. 걱정이야."},{"who":"가온","text":"이든이는 늘 잘하잖아. 원숭이도 나무에서 떨어진다고, 이번엔 좀 늦을 수도 있지."},{"who":"이든","text":"사실 어깨가 무거워서 밤마다 연습했어. 그래도 첫술에 배부르랴, 내일은 더 나아질 거야."},{"who":"하늬","text":"그럼 걱정 붙들어 맬게. 우리 모두 네 반주를 목이 빠지게 기다릴게."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#11','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C28',2,'mc','auto','로아 글 앞부분에서 견문에 해당하는 것은 어느 것인가요?',ARRAY['K6-1-u4-X27']::text[],false,'{"seq":11,"concept":"K6-1-u4-C28","difficulty":2,"kind":"mc","stem":"로아 글 앞부분에서 견문에 해당하는 것은 어느 것인가요?","options":[{"t":"「약품을 넣어 작은 알갱이끼리 뭉치게 한 뒤 가라앉힌다고 했다.」","correct":true},{"t":"「학교에서 버스를 타고 강가로 갔다.」","mis":"K6-1-u4-X27"},{"t":"「흙탕물이 맑아지는 모습에 입이 딱 벌어졌다.」","mis":"K6-1-u4-X27"},{"t":"「먼저 강물을 끌어오는 곳을 보았다.」","mis":"K6-1-u4-X27"}],"explanation":["버스를 탄 것은 여정이에요.","놀란 마음은 감상이에요.","새로 안 사실이 견문이에요."],"asset":{"type":"passage","lines":["지난 금요일, 우리 반은 수돗물이 어떻게 만들어지는지 알아보려고","고장의 정수장에 다녀왔다. 학교에서 버스를 타고 강가로 갔다.","먼저 강물을 끌어오는 곳을 보았다. 강물에는 흙 알갱이가 섞여 있어서","약품을 넣어 작은 알갱이끼리 뭉치게 한 뒤 가라앉힌다고 했다.","흙탕물이 맑아지는 모습에 입이 딱 벌어졌다."],"title":"로아의 견학 기록문 「정수장을 다녀와서」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#12','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C29',2,'mc','auto','「앞으로는 물을 틀어 놓은 채로 양치하지 않아야겠다.」는 글의 어느 부분에 어울리나요?',ARRAY['K6-1-u4-X28','K6-1-u4-X31']::text[],false,'{"seq":12,"concept":"K6-1-u4-C29","difficulty":2,"kind":"mc","stem":"「앞으로는 물을 틀어 놓은 채로 양치하지 않아야겠다.」는 글의 어느 부분에 어울리나요?","options":[{"t":"끝 — 깨달은 점과 다짐","correct":true},{"t":"처음 — 견학한 까닭","mis":"K6-1-u4-X28"},{"t":"가운데 — 새로 안 사실","mis":"K6-1-u4-X28"},{"t":"제목","mis":"K6-1-u4-X31"}],"explanation":["까닭이 아니에요.","새로 안 사실이 아니에요.","정리와 다짐은 끝이에요."],"asset":{"type":"passage","lines":["다음으로 모래와 자갈을 깐 층으로 물을 거르는 곳에 갔다.","마지막으로 소독을 해서 물속의 해로운 균을 없앤 뒤 집으로 보낸다고 했다.","수도꼭지만 틀면 나오던 물이 이렇게 여러 단계를 거친다는 것을 알았다.","앞으로는 물을 틀어 놓은 채로 양치하지 않아야겠다."],"title":"로아의 견학 기록문 「정수장을 다녀와서」 — 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#13','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C37',2,'mc','auto','로아가 「관용 표현을 세 개는 넣어야 해.」라며 문단마다 넣으려 할 때 해 줄 말로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X07','K6-1-u4-X37','K6-1-u4-X09']::text[],false,'{"seq":13,"concept":"K6-1-u4-C37","difficulty":2,"kind":"mc","stem":"로아가 「관용 표현을 세 개는 넣어야 해.」라며 문단마다 넣으려 할 때 해 줄 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「마음이 가장 크게 움직인 자리에 하나면 충분해.」","correct":true},{"t":"「셋이 모자라면 다섯 개 넣어.」","mis":"K6-1-u4-X07"},{"t":"「칸을 채우는 게 제일 중요해.」","mis":"K6-1-u4-X37"},{"t":"「관용 표현은 하나도 쓰지 마.」","mis":"K6-1-u4-X09"}],"explanation":["많이 넣는다고 좋아지지 않아요.","칸 채우기가 아니에요.","제자리에 하나면 충분해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#14','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C35',2,'mc','auto','로아의 조직표 가운데 칸들의 문제로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X30','K6-1-u4-X27','K6-1-u4-X29']::text[],false,'{"seq":14,"concept":"K6-1-u4-C35","difficulty":2,"kind":"mc","stem":"로아의 조직표 가운데 칸들의 문제로 알맞은 것은 어느 것인가요?","options":[{"t":"본 것에 짝지은 느낀 것이 없어 사실만 늘어놓은 글이 되기 쉽다","correct":true},{"t":"견문이 너무 많아 일기가 된다","mis":"K6-1-u4-X30"},{"t":"차례가 없어 여정이 보이지 않는다","mis":"K6-1-u4-X27"},{"t":"고칠 곳이 없다","mis":"K6-1-u4-X29"}],"explanation":["견문이 많으면 일기가 아니라 안내문 쪽이에요.","차례는 있어요.","느낀 것이 빠졌어요."],"asset":{"type":"passage","lines":["처음 — 지난 금요일 · 반 친구들과 · 고장의 정수장","가운데 첫째 — 강물 끌어오는 곳 / 알갱이를 뭉쳐 가라앉힘 / (느낀 것 없음)","가운데 둘째 — 모래와 자갈 층 / 물을 거름 / (느낀 것 없음)","가운데 셋째 — 소독하는 곳 / 해로운 균을 없앰 / (느낀 것 없음)","끝 — 정말 재미있었다."],"title":"로아의 조직표 (고치기 전)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#15','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C19',2,'mc','auto','속담을 바꾸어 지을 때 꼭 함께 적을 것은 어느 것인가요?',ARRAY['K6-1-u4-X19','K6-1-u4-X41']::text[],false,'{"seq":15,"concept":"K6-1-u4-C19","difficulty":2,"kind":"mc","stem":"속담을 바꾸어 지을 때 꼭 함께 적을 것은 어느 것인가요?","options":[{"t":"어떤 상황에서 쓸 말인지","correct":true},{"t":"바꾼 낱말의 글자 수","mis":"K6-1-u4-X19"},{"t":"원래 속담이 생긴 때","mis":"K6-1-u4-X41"},{"t":"바꾼 속담을 아는 친구의 수","mis":"K6-1-u4-X41"}],"explanation":["글자 수는 상관없어요.","생긴 때는 쓸모없어요.","쓸 상황을 함께 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#16','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C42',2,'mc','auto','다인이의 행동을 알맞게 평가한 것은 어느 것인가요?',ARRAY['K6-1-u4-X43','K6-1-u4-X42']::text[],false,'{"seq":16,"concept":"K6-1-u4-C42","difficulty":2,"kind":"mc","stem":"다인이의 행동을 알맞게 평가한 것은 어느 것인가요?","options":[{"t":"공식적인 자리에서 발표를 끝까지 경청하지 않았다","correct":true},{"t":"작은 소리였으니 괜찮다","mis":"K6-1-u4-X43"},{"t":"쉬는 시간 이야기라 괜찮다","mis":"K6-1-u4-X42"},{"t":"다인이는 예절을 잘 지켰다","mis":"K6-1-u4-X43"}],"explanation":["작은 소리여도 경청하지 않았어요.","발표 도중이었어요.","끝까지 들어야 해요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"이제 시온이가 모둠에서 조사한 내용을 반 친구들 앞에서 발표하겠습니다."},{"who":"시온","text":"(작은 목소리로, 칠판 쪽을 보며) 우리 모둠은 정수장에 대해 알아봤어. 물을 여러 번 거른대."},{"who":"다인","text":"(발표 도중에 짝에게) 이따 쉬는 시간에 뭐 할래?"},{"who":"태하","text":"(발표가 끝나자) 잘 들었습니다. 소독은 어떻게 하는지 여쭤봐도 될까요?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#17','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C5',3,'mc','auto','「손이 열 개라도 모자라다」를 바르게 쓴 문장은 어느 것인가요?',ARRAY['K6-1-u4-X06']::text[],false,'{"seq":17,"concept":"K6-1-u4-C5","difficulty":3,"kind":"mc","stem":"「손이 열 개라도 모자라다」를 바르게 쓴 문장은 어느 것인가요?","options":[{"t":"「잔치 준비로 손이 열 개라도 모자랐다.」","correct":true},{"t":"「잔치 준비로 손이 아홉 개라도 모자랐다.」","mis":"K6-1-u4-X06"},{"t":"「잔치 준비로 손가락이 열 개라도 모자랐다.」","mis":"K6-1-u4-X06"},{"t":"「잔치 준비로 두 손이 열 개라도 넉넉했다.」","mis":"K6-1-u4-X06"}],"explanation":["수를 바꾸면 안 돼요.","낱말을 바꿔도 안 돼요.","굳어진 모양 그대로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#18','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C16',3,'mc','auto','「서당 개 삼 년이면 풍월을 읊는다」에서 「서당」이 옛날 아이들이 글을 배우던 곳임을 알고 나서 할 생각으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X17','K6-1-u4-X01']::text[],false,'{"seq":18,"concept":"K6-1-u4-C16","difficulty":3,"kind":"mc","stem":"「서당 개 삼 년이면 풍월을 읊는다」에서 「서당」이 옛날 아이들이 글을 배우던 곳임을 알고 나서 할 생각으로 알맞은 것은 어느 것인가요?","options":[{"t":"옛 배움터가 말 속에 남아 옛 생활을 엿볼 수 있다","correct":true},{"t":"서당이 없어졌으니 틀린 속담이다","mis":"K6-1-u4-X17"},{"t":"개가 실제로 글을 읽었다는 뜻이다","mis":"K6-1-u4-X01"},{"t":"요즘 말로만 바꿔 써야 한다","mis":"K6-1-u4-X17"}],"explanation":["없어졌다고 틀린 말이 아니에요.","개가 글을 읽은 것이 아니에요.","옛 생활이 남은 흔적이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#19','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C20',3,'mc','auto','초아와 같은 의도로 「목마른 사람이 우물 판다」를 쓴 말은 어느 것인가요?',ARRAY['K6-1-u4-X20','K6-1-u4-X01']::text[],false,'{"seq":19,"concept":"K6-1-u4-C20","difficulty":3,"kind":"mc","stem":"초아와 같은 의도로 「목마른 사람이 우물 판다」를 쓴 말은 어느 것인가요?","options":[{"t":"「목마른 사람이 우물 판다잖아. 궁금한 내가 먼저 선생님께 여쭤볼게.」","correct":true},{"t":"「너희는 왜 아무도 안 나서니? 목마른 사람이 우물 판다잖아.」","mis":"K6-1-u4-X20"},{"t":"「나는 이런 속담도 알아. 목마른 사람이 우물 판다.」","mis":"K6-1-u4-X20"},{"t":"「목마른 사람이 우물 판다니까 우물을 파러 가자.」","mis":"K6-1-u4-X01"}],"explanation":["남을 꾸짖는 말이 됐어요.","자랑하는 말이 됐어요.","아쉬운 내가 먼저 나선다는 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#20','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C31',3,'mc','auto','「도서관 서고를 다녀와서」라는 제목만 보고 짐작할 수 있는 것은 어느 것인가요?',ARRAY['K6-1-u4-X31','K6-1-u4-X26']::text[],false,'{"seq":20,"concept":"K6-1-u4-C31","difficulty":3,"kind":"mc","stem":"「도서관 서고를 다녀와서」라는 제목만 보고 짐작할 수 있는 것은 어느 것인가요?","options":[{"t":"도서관에서 책을 보관하는 곳에 다녀와 새로 안 것을 쓴 글일 것이다","correct":true},{"t":"도서관 이용 규칙을 지키자고 주장하는 글일 것이다","mis":"K6-1-u4-X31"},{"t":"책 속 인물이 나오는 이야기일 것이다","mis":"K6-1-u4-X26"},{"t":"서고에 가는 길만 적은 글일 것이다","mis":"K6-1-u4-X31"}],"explanation":["주장하는 글이 아니에요.","이야기가 아니에요.","다녀온 곳과 새로 안 것을 짐작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#21','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C38',3,'error','auto','고쳐 쓸 때 한 일이에요. 알맞지 않게 고친 친구는 누구인가요?',ARRAY['K6-1-u4-X38','K6-1-u4-X36']::text[],false,'{"seq":21,"concept":"K6-1-u4-C38","difficulty":3,"kind":"error","stem":"고쳐 쓸 때 한 일이에요. 알맞지 않게 고친 친구는 누구인가요?","options":[{"t":"시하 — 짝 글보다 짧아서 아무 문장이나 더 늘렸다","correct":true,"mis_target":"K6-1-u4-X38"},{"t":"로운 — 여정 · 견문 · 감상이 다 전해지는지 다시 읽었다","mis":"K6-1-u4-X38"},{"t":"채이 — 관용 표현이 상황에 맞게 놓였는지 살폈다","mis":"K6-1-u4-X36"}],"explanation":["로운이는 갈래가 갖출 것을 살폈어요.","채이도 바르게 살폈어요.","길이는 고쳐 쓸 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#22','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C40',3,'mc','auto','「목에 힘을 주다」 사전 한 장에서 「쓸 수 있는 상황」 칸을 알맞게 쓴 것은 어느 것인가요?',ARRAY['K6-1-u4-X11','K6-1-u4-X41','K6-1-u4-X01']::text[],false,'{"seq":22,"concept":"K6-1-u4-C40","difficulty":3,"kind":"mc","stem":"「목에 힘을 주다」 사전 한 장에서 「쓸 수 있는 상황」 칸을 알맞게 쓴 것은 어느 것인가요?","options":[{"t":"상을 받고 나서 친구들 앞에서 거만하게 구는 사람을 두고","correct":true},{"t":"잘난 체하며 거만하게 굴다(뜻을 한 번 더 씀)","mis":"K6-1-u4-X11"},{"t":"이 표현이 처음 생긴 때","mis":"K6-1-u4-X41"},{"t":"목 운동을 하는 방법","mis":"K6-1-u4-X01"}],"explanation":["뜻은 둘째 칸이에요.","생긴 때는 쓸모없어요.","내가 쓸 상황을 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#23','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C30',4,'mc','auto','로아 글을 고치려는 의견 가운데 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X29','K6-1-u4-X30','K6-1-u4-X07']::text[],false,'{"seq":23,"concept":"K6-1-u4-C30","difficulty":4,"kind":"mc","stem":"로아 글을 고치려는 의견 가운데 가장 알맞은 것은 어느 것인가요?","options":[{"t":"사실 문장은 그대로 두고, 모래와 자갈 층과 소독 문장 뒤에 그때의 마음을 한 문장씩 붙인다","correct":true},{"t":"감상 문장을 모두 지워 깔끔한 안내문으로 만든다","mis":"K6-1-u4-X29"},{"t":"견문을 모두 지우고 느낌만 남긴다","mis":"K6-1-u4-X30"},{"t":"문장마다 관용 표현을 하나씩 넣는다","mis":"K6-1-u4-X07"}],"explanation":["감상을 지우면 안내문이 돼요.","견문을 지우면 일기가 돼요.","본 것에 느낀 것을 짝지어요."],"asset":{"type":"passage","lines":["다음으로 모래와 자갈을 깐 층으로 물을 거르는 곳에 갔다.","마지막으로 소독을 해서 물속의 해로운 균을 없앤 뒤 집으로 보낸다고 했다.","수도꼭지만 틀면 나오던 물이 이렇게 여러 단계를 거친다는 것을 알았다.","앞으로는 물을 틀어 놓은 채로 양치하지 않아야겠다."],"title":"로아의 견학 기록문 「정수장을 다녀와서」 — 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#24','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C28',4,'essay','teacher','로아 글 앞부분에서 여정 · 견문 · 감상을 하나씩 찾아 쓰고, 각각 그렇게 본 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u4-C28","difficulty":4,"kind":"essay","stem":"로아 글 앞부분에서 여정 · 견문 · 감상을 하나씩 찾아 쓰고, 각각 그렇게 본 까닭을 쓰세요.","answer_guide":{"answer":"예: 여정 — 「학교에서 버스를 타고 강가로 갔다」는 어떻게 다녔는지 보여 준다. 견문 — 「약품을 넣어 작은 알갱이끼리 뭉치게 한 뒤 가라앉힌다」는 정수장에서 새로 안 사실이다. 감상 — 「흙탕물이 맑아지는 모습에 입이 딱 벌어졌다」는 놀란 마음을 나타낸다.","scoring_points":["여정을 찾고 까닭을 썼는가","견문을 찾고 까닭을 썼는가","감상을 찾고 까닭을 썼는가"]},"explanation":["다닌 길을 찾아요.","새로 안 사실을 찾아요.","마음이 드러난 곳을 찾아요."],"asset":{"type":"passage","lines":["지난 금요일, 우리 반은 수돗물이 어떻게 만들어지는지 알아보려고","고장의 정수장에 다녀왔다. 학교에서 버스를 타고 강가로 갔다.","먼저 강물을 끌어오는 곳을 보았다. 강물에는 흙 알갱이가 섞여 있어서","약품을 넣어 작은 알갱이끼리 뭉치게 한 뒤 가라앉힌다고 했다.","흙탕물이 맑아지는 모습에 입이 딱 벌어졌다."],"title":"로아의 견학 기록문 「정수장을 다녀와서」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_b#25','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C30',4,'essay','teacher','견학 기록문이 안내문이나 일기와 다른 점을 쓰고, 좋은 견학 기록문이 갖추어야 할 것을 세 가지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u4-C30","difficulty":4,"kind":"essay","stem":"견학 기록문이 안내문이나 일기와 다른 점을 쓰고, 좋은 견학 기록문이 갖추어야 할 것을 세 가지 쓰세요.","answer_guide":{"answer":"예: 안내문은 사실만, 일기는 마음만 중심으로 쓰지만 견학 기록문은 새롭게 안 사실을 중심에 놓고 그때의 마음도 함께 적는다. 좋은 견학 기록문은 첫째, 여정 · 견문 · 감상이 드러나고, 둘째, 처음 · 가운데 · 끝의 짜임이 있으며, 셋째, 새로 안 사실이 참이고 마음이 진솔하게 담겨 있어야 한다.","scoring_points":["안내문 · 일기와 다른 점을 썼는가","여정 · 견문 · 감상이나 짜임을 썼는가","사실이 참이고 마음이 진솔해야 함을 썼는가"]},"explanation":["두 글과 견줘요.","갖출 것을 떠올려요.","세 가지를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#1','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C2',1,'mc','auto','다음 가운데 낱말 뜻의 합과 다른 새 뜻을 지닌 관용 표현은 어느 것인가요?',ARRAY['K6-1-u4-X02']::text[],false,'{"seq":1,"concept":"K6-1-u4-C2","difficulty":1,"kind":"mc","stem":"다음 가운데 낱말 뜻의 합과 다른 새 뜻을 지닌 관용 표현은 어느 것인가요?","options":[{"t":"입이 무겁다","correct":true},{"t":"문을 닫다","mis":"K6-1-u4-X02"},{"t":"손을 씻다","mis":"K6-1-u4-X02"},{"t":"책을 읽다","mis":"K6-1-u4-X02"}],"explanation":["문을 닫는 것은 뜻 그대로예요.","손을 씻는 것도 뜻 그대로예요.","말이 신중하다는 새 뜻이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#2','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C5',1,'ox','auto','관용 표현은 굳어진 모양 그대로 익혀야 해요.',ARRAY['K6-1-u4-X06']::text[],false,'{"seq":2,"concept":"K6-1-u4-C5","difficulty":1,"kind":"ox","stem":"관용 표현은 굳어진 모양 그대로 익혀야 해요.","answer":"O","reason_options":[{"t":"낱말을 바꾸거나 늘이면 뜻을 잃기 때문에","correct":true},{"t":"모양은 마음대로 바꿔도 뜻이 같기 때문에","mis":"K6-1-u4-X06"}],"mis":"K6-1-u4-X06","explanation":["통째로 굳은 말이에요.","바꾸면 뜻이 사라져요.","모양 그대로 익혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#3','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C12',1,'mc','auto','「입이 무겁다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X12','K6-1-u4-X01']::text[],false,'{"seq":3,"concept":"K6-1-u4-C12","difficulty":1,"kind":"mc","stem":"「입이 무겁다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"말이 신중해 함부로 옮기지 않는다","correct":true},{"t":"입을 다쳐 말하기 힘들다","mis":"K6-1-u4-X12"},{"t":"음식을 많이 먹는다","mis":"K6-1-u4-X01"},{"t":"입술이 두툼하다","mis":"K6-1-u4-X12"}],"explanation":["다친 이야기가 아니에요.","먹는 이야기도 아니에요.","말을 함부로 옮기지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#4','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C16',1,'ox','auto','속담 속 낯선 옛말을 찾아보면 옛 생활을 알 수 있어요.',ARRAY['K6-1-u4-X17']::text[],false,'{"seq":4,"concept":"K6-1-u4-C16","difficulty":1,"kind":"ox","stem":"속담 속 낯선 옛말을 찾아보면 옛 생활을 알 수 있어요.","answer":"O","reason_options":[{"t":"옛말에 조상의 생활과 생각이 남아 있기 때문에","correct":true},{"t":"옛말은 낡아서 알 필요가 없기 때문에","mis":"K6-1-u4-X17"}],"mis":"K6-1-u4-X17","explanation":["옛말은 버릴 말이 아니에요.","옛 생활이 남은 흔적이에요.","찾아보면 우리 문화가 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#5','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C21',1,'mc','auto','「마음이 굴뚝같았다」를 고르면 「정말 하고 싶었다」보다 더 전해지는 것은 어느 것인가요?',ARRAY['K6-1-u4-X21','K6-1-u4-X20','K6-1-u4-X09']::text[],false,'{"seq":5,"concept":"K6-1-u4-C21","difficulty":1,"kind":"mc","stem":"「마음이 굴뚝같았다」를 고르면 「정말 하고 싶었다」보다 더 전해지는 것은 어느 것인가요?","options":[{"t":"하고 싶은 마음의 크기","correct":true},{"t":"굴뚝이 얼마나 높은지","mis":"K6-1-u4-X21"},{"t":"하기 싫은 마음","mis":"K6-1-u4-X20"},{"t":"아무것도 더 전해지지 않는다","mis":"K6-1-u4-X09"}],"explanation":["굴뚝 이야기가 아니에요.","싫은 마음이 아니에요.","마음의 크기가 함께 전해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#6','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C28',1,'mc','auto','「어디를 거쳐 어떻게 다녔는지, 다닌 길」을 무엇이라고 하나요?',ARRAY['K6-1-u4-X27','K6-1-u4-X28']::text[],false,'{"seq":6,"concept":"K6-1-u4-C28","difficulty":1,"kind":"mc","stem":"「어디를 거쳐 어떻게 다녔는지, 다닌 길」을 무엇이라고 하나요?","options":[{"t":"여정","correct":true},{"t":"견문","mis":"K6-1-u4-X27"},{"t":"감상","mis":"K6-1-u4-X27"},{"t":"끝 부분","mis":"K6-1-u4-X28"}],"explanation":["견문은 보고 들은 것이에요.","감상은 느낀 것이에요.","다닌 길은 여정이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#7','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C36',1,'ox','auto','관용 표현은 사실을 전하는 견문 자리에 얹는 것이 좋아요.',ARRAY['K6-1-u4-X36']::text[],false,'{"seq":7,"concept":"K6-1-u4-C36","difficulty":1,"kind":"ox","stem":"관용 표현은 사실을 전하는 견문 자리에 얹는 것이 좋아요.","answer":"X","reason_options":[{"t":"견문은 사실이라 관용 표현을 얹으면 무엇이 사실인지 흐려지기 때문에","correct":true},{"t":"사실 자리에 얹어야 글이 재미있어지기 때문에","mis":"K6-1-u4-X36"}],"mis":"K6-1-u4-X36","explanation":["견문은 사실이에요.","관용 표현은 마음을 나타내요.","감상 자리에 놓아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#8','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C42',1,'ox','auto','공식적인 말하기와 비공식적인 말하기에서 지킬 예절은 똑같아요.',ARRAY['K6-1-u4-X42']::text[],false,'{"seq":8,"concept":"K6-1-u4-C42","difficulty":1,"kind":"ox","stem":"공식적인 말하기와 비공식적인 말하기에서 지킬 예절은 똑같아요.","answer":"X","reason_options":[{"t":"듣는 사람과 자리가 달라 편하게 들을 수 있는 방법도 달라지기 때문에","correct":true},{"t":"예절은 어디서나 한 가지 목록이기 때문에","mis":"K6-1-u4-X42"}],"mis":"K6-1-u4-X42","explanation":["같은 교실이라도","듣는 사람과 자리가 달라지면","예절도 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#9','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C10',2,'mc','auto','이든이가 말한 「어깨가 무거워서」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X12','K6-1-u4-X20']::text[],false,'{"seq":9,"concept":"K6-1-u4-C10","difficulty":2,"kind":"mc","stem":"이든이가 말한 「어깨가 무거워서」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"반주를 맡은 책임이 커서 마음이 무거웠다","correct":true},{"t":"악보 가방이 무거웠다","mis":"K6-1-u4-X12"},{"t":"피아노를 옮겨 어깨가 아팠다","mis":"K6-1-u4-X12"},{"t":"반주가 하기 싫었다","mis":"K6-1-u4-X20"}],"explanation":["가방 이야기가 아니에요.","어깨가 아픈 것도 아니에요.","책임이 큰 마음이에요."],"asset":{"type":"speech","turns":[{"who":"하늬","text":"합창 대회가 코앞에 닥쳤는데 반주를 맡은 이든이가 아직 악보를 다 못 외웠대. 걱정이야."},{"who":"가온","text":"이든이는 늘 잘하잖아. 원숭이도 나무에서 떨어진다고, 이번엔 좀 늦을 수도 있지."},{"who":"이든","text":"사실 어깨가 무거워서 밤마다 연습했어. 그래도 첫술에 배부르랴, 내일은 더 나아질 거야."},{"who":"하늬","text":"그럼 걱정 붙들어 맬게. 우리 모두 네 반주를 목이 빠지게 기다릴게."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#10','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C11',2,'mc','auto','학급 안내문에 「대회가 코앞에 닥쳤으니 모두 연습해 주세요.」라고 쓴 것을 알맞게 평가한 것은 어느 것인가요?',ARRAY['K6-1-u4-X13','K6-1-u4-X01']::text[],false,'{"seq":10,"concept":"K6-1-u4-C11","difficulty":2,"kind":"mc","stem":"학급 안내문에 「대회가 코앞에 닥쳤으니 모두 연습해 주세요.」라고 쓴 것을 알맞게 평가한 것은 어느 것인가요?","options":[{"t":"글로 전하는 매체에서도 관용어가 급함을 짧고 또렷하게 전한다","correct":true},{"t":"안내문에는 관용어를 쓰면 안 된다","mis":"K6-1-u4-X13"},{"t":"글로 쓰면 말로 할 때와 뜻이 달라진다","mis":"K6-1-u4-X13"},{"t":"코앞에 물건을 두라는 뜻이다","mis":"K6-1-u4-X01"}],"explanation":["안내문에도 쓸 수 있어요.","뜻은 그대로예요.","매체가 달라도 하는 일은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#11','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C28',2,'mc','auto','「흙탕물이 맑아지는 모습에 입이 딱 벌어졌다.」는 무엇에 해당하나요?',ARRAY['K6-1-u4-X27','K6-1-u4-X28']::text[],false,'{"seq":11,"concept":"K6-1-u4-C28","difficulty":2,"kind":"mc","stem":"「흙탕물이 맑아지는 모습에 입이 딱 벌어졌다.」는 무엇에 해당하나요?","options":[{"t":"감상","correct":true},{"t":"여정","mis":"K6-1-u4-X27"},{"t":"견문","mis":"K6-1-u4-X27"},{"t":"견학한 까닭","mis":"K6-1-u4-X28"}],"explanation":["다닌 길이 아니에요.","새로 안 사실이 아니에요.","놀란 마음이에요."],"asset":{"type":"passage","lines":["지난 금요일, 우리 반은 수돗물이 어떻게 만들어지는지 알아보려고","고장의 정수장에 다녀왔다. 학교에서 버스를 타고 강가로 갔다.","먼저 강물을 끌어오는 곳을 보았다. 강물에는 흙 알갱이가 섞여 있어서","약품을 넣어 작은 알갱이끼리 뭉치게 한 뒤 가라앉힌다고 했다.","흙탕물이 맑아지는 모습에 입이 딱 벌어졌다."],"title":"로아의 견학 기록문 「정수장을 다녀와서」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#12','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C35',2,'mc','auto','로아 글 뒷부분의 모래와 자갈 층 문장 뒤에 무엇을 붙이면 본 것과 느낀 것이 짝지어질까요?',ARRAY['K6-1-u4-X35','K6-1-u4-X07']::text[],false,'{"seq":12,"concept":"K6-1-u4-C35","difficulty":2,"kind":"mc","stem":"로아 글 뒷부분의 모래와 자갈 층 문장 뒤에 무엇을 붙이면 본 것과 느낀 것이 짝지어질까요?","options":[{"t":"「모래와 자갈만으로 물이 걸러진다니 신기했다.」처럼 그때의 마음 한 문장","correct":true},{"t":"모래가 몇 층인지 같은 사실 문장 하나 더","mis":"K6-1-u4-X35"},{"t":"관용 표현 세 개","mis":"K6-1-u4-X07"},{"t":"아무것도 붙이지 않고 다음 문장으로","mis":"K6-1-u4-X35"}],"explanation":["사실을 더하면 사실만 늘어요.","개수는 문제가 아니에요.","본 것 뒤에 마음을 붙여요."],"asset":{"type":"passage","lines":["다음으로 모래와 자갈을 깐 층으로 물을 거르는 곳에 갔다.","마지막으로 소독을 해서 물속의 해로운 균을 없앤 뒤 집으로 보낸다고 했다.","수도꼭지만 틀면 나오던 물이 이렇게 여러 단계를 거친다는 것을 알았다.","앞으로는 물을 틀어 놓은 채로 양치하지 않아야겠다."],"title":"로아의 견학 기록문 「정수장을 다녀와서」 — 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#13','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C38',2,'mc','auto','로아가 글을 고쳐 쓸 때 살펴볼 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X38','K6-1-u4-X07']::text[],false,'{"seq":13,"concept":"K6-1-u4-C38","difficulty":2,"kind":"mc","stem":"로아가 글을 고쳐 쓸 때 살펴볼 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"견학한 까닭이 드러나는가","correct":true},{"t":"글씨를 예쁘게 썼는가","mis":"K6-1-u4-X38"},{"t":"짝의 글보다 긴가","mis":"K6-1-u4-X38"},{"t":"관용 표현을 많이 넣었는가","mis":"K6-1-u4-X07"}],"explanation":["글씨는 갈래를 정하지 않아요.","길이도 아니에요.","견학 기록문이 갖출 것을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#14','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C29',2,'mc','auto','로아의 조직표 끝 칸을 알맞게 고친 것은 어느 것인가요?',ARRAY['K6-1-u4-X30','K6-1-u4-X28']::text[],false,'{"seq":14,"concept":"K6-1-u4-C29","difficulty":2,"kind":"mc","stem":"로아의 조직표 끝 칸을 알맞게 고친 것은 어느 것인가요?","options":[{"t":"물이 여러 단계를 거친다는 것을 정리하고, 물을 아껴 쓰겠다는 깨달은 점을 쓴다","correct":true},{"t":"「정말 정말 재미있었다」로 늘린다","mis":"K6-1-u4-X30"},{"t":"새로 본 시설을 끝에 더한다","mis":"K6-1-u4-X28"},{"t":"끝 칸을 처음 칸과 바꾼다","mis":"K6-1-u4-X28"}],"explanation":["느낌만 늘리면 일기 같아요.","새 견문은 가운데예요.","끝에는 정리와 깨달음을 써요."],"asset":{"type":"passage","lines":["처음 — 지난 금요일 · 반 친구들과 · 고장의 정수장","가운데 첫째 — 강물 끌어오는 곳 / 알갱이를 뭉쳐 가라앉힘 / (느낀 것 없음)","가운데 둘째 — 모래와 자갈 층 / 물을 거름 / (느낀 것 없음)","가운데 셋째 — 소독하는 곳 / 해로운 균을 없앰 / (느낀 것 없음)","끝 — 정말 재미있었다."],"title":"로아의 조직표 (고치기 전)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#15','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C13',2,'mc','auto','「귀에 익다」의 뜻을 몰라 찾을 때 알맞은 순서는 어느 것인가요?',ARRAY['K6-1-u4-X14','K6-1-u4-X11','K6-1-u4-X10']::text[],false,'{"seq":15,"concept":"K6-1-u4-C13","difficulty":2,"kind":"mc","stem":"「귀에 익다」의 뜻을 몰라 찾을 때 알맞은 순서는 어느 것인가요?","options":[{"t":"앞뒤 상황으로 짐작 → 「귀」를 사전에서 찾아 뜻풀이 아래 관용구 → 짐작과 맞춰 보기","correct":true},{"t":"사전의 첫 쪽부터 넘기기 → 나올 때까지 읽기","mis":"K6-1-u4-X14"},{"t":"뜻은 모른 채 「귀에 익다」를 통째로 외우기","mis":"K6-1-u4-X11"},{"t":"짐작한 뜻을 찾아보지 않고 정답으로 삼기","mis":"K6-1-u4-X10"}],"explanation":["첫 쪽부터는 오래 걸려요.","뜻을 모른 채 외우면 쓰지 못해요.","짐작한 뒤 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#16','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C42',2,'ox','auto','태하가 발표가 끝난 뒤 존댓말로 질문한 것은 공식적인 말하기 예절에 맞아요.',ARRAY['K6-1-u4-X42']::text[],false,'{"seq":16,"concept":"K6-1-u4-C42","difficulty":2,"kind":"ox","stem":"태하가 발표가 끝난 뒤 존댓말로 질문한 것은 공식적인 말하기 예절에 맞아요.","answer":"O","reason_options":[{"t":"발표를 끝까지 듣고 여럿이 듣는 자리에 맞게 존댓말을 썼기 때문에","correct":true},{"t":"질문은 언제나 반말로 해야 하기 때문에","mis":"K6-1-u4-X42"}],"mis":"K6-1-u4-X42","explanation":["끝까지 들었어요.","끝난 뒤 물었어요.","자리에 맞게 존댓말을 썼어요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"이제 시온이가 모둠에서 조사한 내용을 반 친구들 앞에서 발표하겠습니다."},{"who":"시온","text":"(작은 목소리로, 칠판 쪽을 보며) 우리 모둠은 정수장에 대해 알아봤어. 물을 여러 번 거른대."},{"who":"다인","text":"(발표 도중에 짝에게) 이따 쉬는 시간에 뭐 할래?"},{"who":"태하","text":"(발표가 끝나자) 잘 들었습니다. 소독은 어떻게 하는지 여쭤봐도 될까요?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#17','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C7',3,'mc','auto','「입에 침이 마르다」를 알맞게 쓴 문장은 어느 것인가요?',ARRAY['K6-1-u4-X01','K6-1-u4-X08']::text[],false,'{"seq":17,"concept":"K6-1-u4-C7","difficulty":3,"kind":"mc","stem":"「입에 침이 마르다」를 알맞게 쓴 문장은 어느 것인가요?","options":[{"t":"「할머니께서는 손주 자랑에 입에 침이 마르셨다.」","correct":true},{"t":"「물을 오래 안 마셔 입에 침이 말랐다.」","mis":"K6-1-u4-X01"},{"t":"「짝이 미워서 입에 침이 마르게 흉을 보았다.」","mis":"K6-1-u4-X08"},{"t":"「비밀을 지키느라 입에 침이 말랐다.」","mis":"K6-1-u4-X08"}],"explanation":["실제로 침이 마른 이야기예요.","거듭 칭찬하는 뜻과 어긋나요.","거듭 칭찬하는 자리에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#18','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C14',3,'mc','auto','「작은 잘못을 그냥 넘기다 보면 큰 잘못이 된다」는 교훈을 담은 속담은 어느 것인가요?',ARRAY['K6-1-u4-X16']::text[],false,'{"seq":18,"concept":"K6-1-u4-C14","difficulty":3,"kind":"mc","stem":"「작은 잘못을 그냥 넘기다 보면 큰 잘못이 된다」는 교훈을 담은 속담은 어느 것인가요?","options":[{"t":"바늘 도둑이 소도둑 된다","correct":true},{"t":"첫술에 배부르랴","mis":"K6-1-u4-X16"},{"t":"빈 수레가 요란하다","mis":"K6-1-u4-X16"},{"t":"서당 개 삼 년이면 풍월을 읊는다","mis":"K6-1-u4-X16"}],"explanation":["한 번에 안 된다는 교훈이에요.","떠드는 이야기예요.","보고 익히는 이야기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#19','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C25',3,'mc','auto','관용 표현으로 대화하기가 부담스러운 친구에게 해 줄 말로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X24']::text[],false,'{"seq":19,"concept":"K6-1-u4-C25","difficulty":3,"kind":"mc","stem":"관용 표현으로 대화하기가 부담스러운 친구에게 해 줄 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「쓰고 싶은 상황을 떠올려 공책에 적어 보는 것부터 해 보자.」","correct":true},{"t":"「앞에 나와 크게 말할 때까지 연습해.」","mis":"K6-1-u4-X24"},{"t":"「말로 못 하면 배우지 못한 거야.」","mis":"K6-1-u4-X24"},{"t":"「그럼 관용 표현은 배우지 마.」","mis":"K6-1-u4-X24"}],"explanation":["처음부터 크게 말하지 않아도 돼요.","말 못 해도 배운 거예요.","할 수 있는 만큼부터 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#20','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C36',3,'mc','auto','「종이는 습기와 더위에 약해서 온도와 습도를 일정하게 지킨다」는 문장에 관용 표현을 얹지 않는 까닭은 어느 것인가요?',ARRAY['K6-1-u4-X36','K6-1-u4-X09']::text[],false,'{"seq":20,"concept":"K6-1-u4-C36","difficulty":3,"kind":"mc","stem":"「종이는 습기와 더위에 약해서 온도와 습도를 일정하게 지킨다」는 문장에 관용 표현을 얹지 않는 까닭은 어느 것인가요?","options":[{"t":"사실을 전하는 견문 자리라 얹으면 무엇이 사실인지 흐려지기 때문에","correct":true},{"t":"관용 표현은 글 끝에만 쓸 수 있기 때문에","mis":"K6-1-u4-X36"},{"t":"서고와 관련된 관용 표현이 없기 때문에","mis":"K6-1-u4-X36"},{"t":"관용 표현은 견학 기록문에 쓰면 안 되기 때문에","mis":"K6-1-u4-X09"}],"explanation":["끝에만 쓰는 것이 아니에요.","관련 표현이 있고 없고가 아니에요.","견문은 사실을 전해요."],"asset":{"type":"passage","lines":["다음으로 간 보존 서고는 공기가 서늘했다.","종이는 습기와 더위에 약해서 온도와 습도를 늘 일정하게 지킨다고 했다.","오래된 책은 따로 두고, 넘길 때에도 두 손으로 조심해 다룬다고 한다.","표지가 닳고 손때가 묻은 책들이 나란히 서 있는 모습을 한참 바라보았다.","이번 견학으로 도서관이 책을 지키는 곳이라는 것을 알게 되었다."],"title":"「도서관 서고를 다녀와서」 — 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#21','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C35',3,'mc','auto','생각그물과 조직표를 쓰는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X35']::text[],false,'{"seq":21,"concept":"K6-1-u4-C35","difficulty":3,"kind":"mc","stem":"생각그물과 조직표를 쓰는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"생각그물로 떠오르는 대로 모은 뒤 조직표에서 처음 · 가운데 · 끝으로 순서를 잡는다","correct":true},{"t":"조직표로 순서를 먼저 정하고 생각그물은 쓰지 않는다","mis":"K6-1-u4-X35"},{"t":"생각그물만 그리고 바로 글을 끝낸다","mis":"K6-1-u4-X35"},{"t":"둘 다 쓰지 않고 떠오르는 대로 쓴다","mis":"K6-1-u4-X35"}],"explanation":["재료부터 모아요.","순서도 잡아야 해요.","모으고, 나누고, 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#22','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C42',3,'mc','auto','같은 교실에서 학급 회의 때 의견을 말할 때와 짝과 회의 준비를 이야기할 때 예절이 다른 까닭은 어느 것인가요?',ARRAY['K6-1-u4-X42','K6-1-u4-X43']::text[],false,'{"seq":22,"concept":"K6-1-u4-C42","difficulty":3,"kind":"mc","stem":"같은 교실에서 학급 회의 때 의견을 말할 때와 짝과 회의 준비를 이야기할 때 예절이 다른 까닭은 어느 것인가요?","options":[{"t":"같은 교실이어도 듣는 사람과 자리가 달라 편하게 듣는 방법이 달라지기 때문에","correct":true},{"t":"교실이 같으니 예절도 같다","mis":"K6-1-u4-X42"},{"t":"회의 때만 예절이 있다","mis":"K6-1-u4-X43"},{"t":"짝과 이야기할 때는 예절이 필요 없다","mis":"K6-1-u4-X43"}],"explanation":["교실이 같아도 자리가 달라요.","어느 자리에나 예절이 있어요.","듣는 사람을 두고 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#23','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C29',4,'mc','auto','로아의 조직표 전체를 가장 알맞게 고친 것은 어느 것인가요?',ARRAY['K6-1-u4-X30','K6-1-u4-X35','K6-1-u4-X28']::text[],false,'{"seq":23,"concept":"K6-1-u4-C29","difficulty":4,"kind":"mc","stem":"로아의 조직표 전체를 가장 알맞게 고친 것은 어느 것인가요?","options":[{"t":"처음에 견학한 까닭을 더하고, 가운데마다 느낀 것을 하나씩 짝짓고, 끝에 정리와 깨달은 점을 쓴다","correct":true},{"t":"끝의 「정말 재미있었다」를 세 번 쓴다","mis":"K6-1-u4-X30"},{"t":"가운데 칸을 하나로 합치고 느낌은 뺀다","mis":"K6-1-u4-X35"},{"t":"처음을 지우고 가운데부터 시작한다","mis":"K6-1-u4-X28"}],"explanation":["느낌만 늘리면 일기 같아요.","느낌을 빼면 사실만 남아요.","세 부분을 모두 고쳐요."],"asset":{"type":"passage","lines":["처음 — 지난 금요일 · 반 친구들과 · 고장의 정수장","가운데 첫째 — 강물 끌어오는 곳 / 알갱이를 뭉쳐 가라앉힘 / (느낀 것 없음)","가운데 둘째 — 모래와 자갈 층 / 물을 거름 / (느낀 것 없음)","가운데 셋째 — 소독하는 곳 / 해로운 균을 없앰 / (느낀 것 없음)","끝 — 정말 재미있었다."],"title":"로아의 조직표 (고치기 전)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#24','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C36',4,'essay','teacher','로아 글 뒷부분에 관용 표현을 하나 넣는다면 어느 문장 뒤에 어떤 표현을 넣을지 쓰고, 그 자리를 고른 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u4-C36","difficulty":4,"kind":"essay","stem":"로아 글 뒷부분에 관용 표현을 하나 넣는다면 어느 문장 뒤에 어떤 표현을 넣을지 쓰고, 그 자리를 고른 까닭을 쓰세요.","answer_guide":{"answer":"예: 「수도꼭지만 틀면 나오던 물이 이렇게 여러 단계를 거친다는 것을 알았다.」 뒤에 「그동안 물을 펑펑 쓴 것을 생각하니 낯이 뜨거웠다.」를 넣겠다. 이 문장은 깨달은 마음이 드러나는 감상 자리라서 관용 표현이 잘 어울린다. 소독이나 모래층처럼 사실을 전하는 견문 자리에 넣으면 무엇이 사실인지 흐려진다.","scoring_points":["넣을 자리와 관용 표현을 썼는가","그 자리가 감상 자리라는 까닭을 썼는가","견문 자리에 넣지 않는 까닭을 썼는가"]},"explanation":["마음이 드러난 문장을 찾아요.","어울리는 표현을 골라요.","견문 자리와 견줘요."],"asset":{"type":"passage","lines":["다음으로 모래와 자갈을 깐 층으로 물을 거르는 곳에 갔다.","마지막으로 소독을 해서 물속의 해로운 균을 없앤 뒤 집으로 보낸다고 했다.","수도꼭지만 틀면 나오던 물이 이렇게 여러 단계를 거친다는 것을 알았다.","앞으로는 물을 틀어 놓은 채로 양치하지 않아야겠다."],"title":"로아의 견학 기록문 「정수장을 다녀와서」 — 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_c#25','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C21',4,'essay','teacher','「관용 표현을 고르는 일은 전하고 싶은 마음을 고르는 일이다」라는 말을 예를 들어 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u4-C21","difficulty":4,"kind":"essay","stem":"「관용 표현을 고르는 일은 전하고 싶은 마음을 고르는 일이다」라는 말을 예를 들어 설명하세요.","answer_guide":{"answer":"예: 「정말 하고 싶었다」라고 말하면 뜻은 통하지만, 「마음이 굴뚝같았다」라고 하면 얼마나 하고 싶었는지 그 마음의 크기까지 전해진다. 또 「내가 먼저 가 볼게」 대신 「목마른 사람이 우물 판다잖아. 답답한 내가 먼저 가 볼게」라고 하면 나서는 까닭과 마음이 함께 전해진다. 그래서 관용 표현을 고르는 것은 어떤 마음을 전할지 고르는 일이다.","scoring_points":["그냥 말한 것과 관용 표현을 견준 예를 들었는가","관용 표현으로 더 전해지는 마음을 썼는가","마음을 고르는 일이라는 뜻을 정리했는가"]},"explanation":["그냥 말한 것과 견줘요.","더 전해지는 것을 찾아요.","마음을 고르는 일로 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#1','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C3',1,'mc','auto','예로부터 전해 오며 지혜나 교훈을 담은 말을 무엇이라고 하나요?',ARRAY['K6-1-u4-X04','K6-1-u4-X15']::text[],false,'{"seq":1,"concept":"K6-1-u4-C3","difficulty":1,"kind":"mc","stem":"예로부터 전해 오며 지혜나 교훈을 담은 말을 무엇이라고 하나요?","options":[{"t":"속담","correct":true},{"t":"관용어","mis":"K6-1-u4-X04"},{"t":"줄임말","mis":"K6-1-u4-X15"},{"t":"표어","mis":"K6-1-u4-X15"}],"explanation":["관용어는 교훈을 꼭 담지는 않아요.","줄임말은 전해 오는 말이 아니에요.","교훈을 담고 전해 오면 속담이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#2','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C6',1,'mc','auto','관용 표현을 쓸 때 가장 먼저 살필 것은 어느 것인가요?',ARRAY['K6-1-u4-X07','K6-1-u4-X40']::text[],false,'{"seq":2,"concept":"K6-1-u4-C6","difficulty":1,"kind":"mc","stem":"관용 표현을 쓸 때 가장 먼저 살필 것은 어느 것인가요?","options":[{"t":"지금 이 상황에 어울리는가","correct":true},{"t":"몇 개나 넣었는가","mis":"K6-1-u4-X07"},{"t":"얼마나 어려운 표현인가","mis":"K6-1-u4-X40"},{"t":"몇 글자인가","mis":"K6-1-u4-X07"}],"explanation":["개수가 먼저가 아니에요.","어려운 표현이 좋은 것도 아니에요.","상황에 어울리는지가 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#3','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C8',1,'ox','auto','모르는 관용어는 앞뒤 상황을 보고 먼저 짐작해 봐요.',ARRAY['K6-1-u4-X10']::text[],false,'{"seq":3,"concept":"K6-1-u4-C8","difficulty":1,"kind":"ox","stem":"모르는 관용어는 앞뒤 상황을 보고 먼저 짐작해 봐요.","answer":"O","reason_options":[{"t":"짐작한 뒤 사전에서 확인하면 뜻이 오래 남기 때문에","correct":true},{"t":"짐작하면 틀리니 사전부터 펴야 하기 때문에","mis":"K6-1-u4-X10"}],"mis":"K6-1-u4-X10","explanation":["정확히 몰라도 괜찮아요.","앞뒤 상황이 실마리예요.","짐작한 뒤 사전으로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#4','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C18',1,'mc','auto','속담을 사전에서 찾을 때 앞세울 것은 어느 것인가요?',ARRAY['K6-1-u4-X14']::text[],false,'{"seq":4,"concept":"K6-1-u4-C18","difficulty":1,"kind":"mc","stem":"속담을 사전에서 찾을 때 앞세울 것은 어느 것인가요?","options":[{"t":"속담에서 중심이 되는 낱말","correct":true},{"t":"속담 전체 문장","mis":"K6-1-u4-X14"},{"t":"사전의 맨 첫 쪽","mis":"K6-1-u4-X14"},{"t":"속담이 생긴 때","mis":"K6-1-u4-X14"}],"explanation":["문장 전체로 찾지 않아요.","첫 쪽부터 넘기지 않아요.","중심 낱말을 잡아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#5','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C23',1,'mc','auto','「낯이 뜨겁다」와 바꿔 쓸 수 있는 표현은 어느 것인가요?',ARRAY['K6-1-u4-X22']::text[],false,'{"seq":5,"concept":"K6-1-u4-C23","difficulty":1,"kind":"mc","stem":"「낯이 뜨겁다」와 바꿔 쓸 수 있는 표현은 어느 것인가요?","options":[{"t":"고개를 들지 못하다","correct":true},{"t":"코앞에 닥치다","mis":"K6-1-u4-X22"},{"t":"목이 빠지게 기다리다","mis":"K6-1-u4-X22"},{"t":"어깨가 무겁다","mis":"K6-1-u4-X22"}],"explanation":["코앞에 닥치다는 급함이에요.","목이 빠지게 기다리다는 간절함이에요.","부끄러운 마음끼리 바꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#6','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C29',1,'ox','auto','견학 기록문의 끝 부분에는 견학한 내용을 정리하고 깨달은 점을 써요.',ARRAY['K6-1-u4-X28']::text[],false,'{"seq":6,"concept":"K6-1-u4-C29","difficulty":1,"kind":"ox","stem":"견학 기록문의 끝 부분에는 견학한 내용을 정리하고 깨달은 점을 써요.","answer":"O","reason_options":[{"t":"끝은 견학을 정리하고 마무리하는 자리이기 때문에","correct":true},{"t":"끝에는 견학한 까닭과 장소를 처음 밝혀야 하기 때문에","mis":"K6-1-u4-X28"}],"mis":"K6-1-u4-X28","explanation":["까닭과 장소는 처음이에요.","본 것은 가운데예요.","끝에서 정리하고 깨달은 점을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#7','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C38',1,'mc','auto','쓴 견학 기록문을 나눌 방법을 고르는 기준은 어느 것인가요?',ARRAY['K6-1-u4-X39','K6-1-u4-X38']::text[],false,'{"seq":7,"concept":"K6-1-u4-C38","difficulty":1,"kind":"mc","stem":"쓴 견학 기록문을 나눌 방법을 고르는 기준은 어느 것인가요?","options":[{"t":"내가 정한 읽을 사람이 정말 읽을 수 있는가","correct":true},{"t":"가장 많이 인쇄할 수 있는가","mis":"K6-1-u4-X39"},{"t":"가장 빨리 끝나는가","mis":"K6-1-u4-X39"},{"t":"가장 예뻐 보이는가","mis":"K6-1-u4-X38"}],"explanation":["많이 인쇄한다고 읽는 것이 아니에요.","빨리 끝나는 것이 기준이 아니에요.","읽을 사람에게 닿는지가 기준이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#8','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C39',1,'mc','auto','「어깨너머로 배우다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X12','K6-1-u4-X01','K6-1-u4-X22']::text[],false,'{"seq":8,"concept":"K6-1-u4-C39","difficulty":1,"kind":"mc","stem":"「어깨너머로 배우다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"옆에서 보고 들으며 배우다","correct":true},{"t":"어깨를 다쳐 쉬면서 배우다","mis":"K6-1-u4-X12"},{"t":"친구 어깨 위에 올라가 보다","mis":"K6-1-u4-X01"},{"t":"하기 싫은 사람을 억지로 나서게 하다","mis":"K6-1-u4-X22"}],"explanation":["다친 이야기가 아니에요.","어깨 위에 오른 것도 아니에요.","옆에서 보고 익혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#9','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C15',2,'mc','auto','이든이가 「첫술에 배부르랴」를 쓴 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X01','K6-1-u4-X16']::text[],false,'{"seq":9,"concept":"K6-1-u4-C15","difficulty":2,"kind":"mc","stem":"이든이가 「첫술에 배부르랴」를 쓴 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"한 번에 잘되지 않아도 조금씩 나아질 것이라는 마음을 전하려고","correct":true},{"t":"밥을 먹고 연습하겠다고 하려고","mis":"K6-1-u4-X01"},{"t":"이번 대회는 포기하겠다고 하려고","mis":"K6-1-u4-X16"},{"t":"처음부터 완벽해야 한다고 하려고","mis":"K6-1-u4-X16"}],"explanation":["밥 이야기가 아니에요.","포기하는 말이 아니에요.","한 번에 되지 않아도 괜찮다는 말이에요."],"asset":{"type":"speech","turns":[{"who":"하늬","text":"합창 대회가 코앞에 닥쳤는데 반주를 맡은 이든이가 아직 악보를 다 못 외웠대. 걱정이야."},{"who":"가온","text":"이든이는 늘 잘하잖아. 원숭이도 나무에서 떨어진다고, 이번엔 좀 늦을 수도 있지."},{"who":"이든","text":"사실 어깨가 무거워서 밤마다 연습했어. 그래도 첫술에 배부르랴, 내일은 더 나아질 거야."},{"who":"하늬","text":"그럼 걱정 붙들어 맬게. 우리 모두 네 반주를 목이 빠지게 기다릴게."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#10','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C22',2,'ox','auto','「소금 장수와 나루터」에서 「급할수록 돌아가라」는 이야기가 담은 지혜를 한마디로 전해요.',ARRAY['K6-1-u4-X21']::text[],false,'{"seq":10,"concept":"K6-1-u4-C22","difficulty":2,"kind":"ox","stem":"「소금 장수와 나루터」에서 「급할수록 돌아가라」는 이야기가 담은 지혜를 한마디로 전해요.","answer":"O","reason_options":[{"t":"서두르는 대신 돌아가 얕은 여울목으로 건넌 소금 장수의 행동과 이어지기 때문에","correct":true},{"t":"실제로 먼 길을 돌아가라는 뜻만 있기 때문에","mis":"K6-1-u4-X21"}],"mis":"K6-1-u4-X21","explanation":["소금 장수는 서두르지 않았어요.","다른 길을 찾았어요.","돌아가는 지혜가 담겼어요."],"asset":{"type":"passage","lines":["소금 장수는 강을 따라 위쪽으로 반나절을 걸어 얕은 여울목을 찾았다.","그는 지게를 지고 걸어서 강을 건넜고, 소금은 저물녘까지 모두 팔렸다.","그날 하루를 빈 배로 보낸 사공은 다음 날 소금 장수를 다시 만나자","낯이 뜨거워 고개를 들지 못했다."],"title":"옛이야기 「소금 장수와 나루터」 — 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#11','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C27',2,'mc','auto','로아의 글이 견학 기록문으로서 믿을 만한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X26','K6-1-u4-X07','K6-1-u4-X30']::text[],false,'{"seq":11,"concept":"K6-1-u4-C27","difficulty":2,"kind":"mc","stem":"로아의 글이 견학 기록문으로서 믿을 만한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"새로 안 사실(알갱이를 뭉쳐 가라앉힘)이 실제로 참인 내용이기 때문에","correct":true},{"t":"재미있게 지어낸 사실이 많기 때문에","mis":"K6-1-u4-X26"},{"t":"관용 표현을 많이 넣었기 때문에","mis":"K6-1-u4-X07"},{"t":"느낌만 솔직하게 적었기 때문에","mis":"K6-1-u4-X30"}],"explanation":["지어낸 사실은 믿을 수 없어요.","관용 표현 개수와는 상관없어요.","새로 안 사실이 참이어야 해요."],"asset":{"type":"passage","lines":["지난 금요일, 우리 반은 수돗물이 어떻게 만들어지는지 알아보려고","고장의 정수장에 다녀왔다. 학교에서 버스를 타고 강가로 갔다.","먼저 강물을 끌어오는 곳을 보았다. 강물에는 흙 알갱이가 섞여 있어서","약품을 넣어 작은 알갱이끼리 뭉치게 한 뒤 가라앉힌다고 했다.","흙탕물이 맑아지는 모습에 입이 딱 벌어졌다."],"title":"로아의 견학 기록문 「정수장을 다녀와서」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#12','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C30',2,'ox','auto','로아 글에서 「입이 딱 벌어졌다」 같은 감상을 모두 지우면 안내문에 가까워져요.',ARRAY['K6-1-u4-X29']::text[],false,'{"seq":12,"concept":"K6-1-u4-C30","difficulty":2,"kind":"ox","stem":"로아 글에서 「입이 딱 벌어졌다」 같은 감상을 모두 지우면 안내문에 가까워져요.","answer":"O","reason_options":[{"t":"감상이 빠지면 사실만 남기 때문에","correct":true},{"t":"감상이 없어도 견학 기록문이 되기 때문에","mis":"K6-1-u4-X29"}],"mis":"K6-1-u4-X29","explanation":["감상은 마음이에요.","마음이 빠지면 사실만 남아요.","사실만 남으면 안내문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#13','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C34',2,'mc','auto','로아가 이 글을 저학년 동생에게 읽어 준다면 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X30','K6-1-u4-X34','K6-1-u4-X07']::text[],false,'{"seq":13,"concept":"K6-1-u4-C34","difficulty":2,"kind":"mc","stem":"로아가 이 글을 저학년 동생에게 읽어 준다면 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「소독」 「약품」처럼 어려운 낱말을 쉽게 풀어 말한다","correct":true},{"t":"새로 안 사실을 모두 뺀다","mis":"K6-1-u4-X30"},{"t":"쓴 그대로 읽는다","mis":"K6-1-u4-X34"},{"t":"관용 표현을 더 넣는다","mis":"K6-1-u4-X07"}],"explanation":["견문을 빼면 안 돼요.","읽을 사람을 생각해요.","동생이 알 수 있게 풀어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#14','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C33',2,'ox','auto','로아가 조직표를 짜기 전에 왜 정수장이 기억에 남았는지 한 줄로 적어 두면 감상을 쓰기 쉬워요.',ARRAY['K6-1-u4-X33']::text[],false,'{"seq":14,"concept":"K6-1-u4-C33","difficulty":2,"kind":"ox","stem":"로아가 조직표를 짜기 전에 왜 정수장이 기억에 남았는지 한 줄로 적어 두면 감상을 쓰기 쉬워요.","answer":"O","reason_options":[{"t":"기억에 남은 까닭이 곧 글의 감상이 되기 때문에","correct":true},{"t":"까닭은 글에 쓰지 않는 것이기 때문에","mis":"K6-1-u4-X33"}],"mis":"K6-1-u4-X33","explanation":["까닭을 먼저 적어요.","그 까닭이 마음이에요.","감상으로 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#15','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C39',2,'mc','auto','「놀람 · 부끄러움 · 간절함」처럼 묶은 관용 표현 사전을 알맞게 설명한 것은 어느 것인가요?',ARRAY['K6-1-u4-X44']::text[],false,'{"seq":15,"concept":"K6-1-u4-C39","difficulty":2,"kind":"mc","stem":"「놀람 · 부끄러움 · 간절함」처럼 묶은 관용 표현 사전을 알맞게 설명한 것은 어느 것인가요?","options":[{"t":"마음으로 묶은 사전이라 쓸 때 꺼내기 쉽다","correct":true},{"t":"낱말로 묶은 사전이라 찾기 쉽다","mis":"K6-1-u4-X44"},{"t":"아무렇게나 묶은 사전이다","mis":"K6-1-u4-X44"},{"t":"묶지 않아 흩어진 사전이다","mis":"K6-1-u4-X44"}],"explanation":["같은 낱말로 묶은 것이 아니에요.","같은 마음끼리 묶었어요.","마음으로 묶으면 쓰기가 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#16','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C42',2,'mc','auto','시온이의 발표를 고칠 때 세울 기준으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X43']::text[],false,'{"seq":16,"concept":"K6-1-u4-C42","difficulty":2,"kind":"mc","stem":"시온이의 발표를 고칠 때 세울 기준으로 알맞은 것은 어느 것인가요?","options":[{"t":"듣는 친구들이 편하게 들을 수 있는가","correct":true},{"t":"예절 목록을 몇 개 지켰는가","mis":"K6-1-u4-X43"},{"t":"시온이가 편하게 말할 수 있는가","mis":"K6-1-u4-X43"},{"t":"발표가 얼마나 짧은가","mis":"K6-1-u4-X43"}],"explanation":["목록 개수가 기준이 아니에요.","말하는 사람이 기준이 아니에요.","듣는 사람을 두고 정해요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"이제 시온이가 모둠에서 조사한 내용을 반 친구들 앞에서 발표하겠습니다."},{"who":"시온","text":"(작은 목소리로, 칠판 쪽을 보며) 우리 모둠은 정수장에 대해 알아봤어. 물을 여러 번 거른대."},{"who":"다인","text":"(발표 도중에 짝에게) 이따 쉬는 시간에 뭐 할래?"},{"who":"태하","text":"(발표가 끝나자) 잘 들었습니다. 소독은 어떻게 하는지 여쭤봐도 될까요?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#17','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C6',3,'mc','auto','텃밭 일기 한 편에 관용 표현 네 개를 모두 넣으려는 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X07','K6-1-u4-X06']::text[],false,'{"seq":17,"concept":"K6-1-u4-C6","difficulty":3,"kind":"mc","stem":"텃밭 일기 한 편에 관용 표현 네 개를 모두 넣으려는 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"상황에 꼭 맞는 하나를 골라 제자리에 놓자","correct":true},{"t":"넷 다 넣으면 더 생생해지니 그대로 넣자","mis":"K6-1-u4-X07"},{"t":"더 찾아서 다섯 개로 늘리자","mis":"K6-1-u4-X07"},{"t":"넷 모두 낱말 뜻대로 풀어 쓰자","mis":"K6-1-u4-X06"}],"explanation":["많이 넣으면 뜻이 흐려져요.","개수를 늘릴 일이 아니에요.","제자리에 하나가 힘이 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#18','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C18',3,'mc','auto','인터넷 사전으로 속담을 찾는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X14','K6-1-u4-X10']::text[],false,'{"seq":18,"concept":"K6-1-u4-C18","difficulty":3,"kind":"mc","stem":"인터넷 사전으로 속담을 찾는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"중심 낱말을 검색한 뒤 관용구와 속담을 갈라 보는 기능을 쓴다","correct":true},{"t":"속담 사전의 첫 쪽부터 넘긴다","mis":"K6-1-u4-X14"},{"t":"짐작한 뜻을 검색해 바로 정답으로 삼는다","mis":"K6-1-u4-X10"},{"t":"속담과 상관없는 낱말을 아무거나 넣는다","mis":"K6-1-u4-X14"}],"explanation":["인터넷 사전은 넘기지 않아요.","짐작은 확인해야 해요.","중심 낱말을 앞세워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#19','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C26',3,'mc','auto','「발등에 불이 떨어지다」로 짧은 대화를 지을 때 알맞은 상황은 어느 것인가요?',ARRAY['K6-1-u4-X01','K6-1-u4-X25']::text[],false,'{"seq":19,"concept":"K6-1-u4-C26","difficulty":3,"kind":"mc","stem":"「발등에 불이 떨어지다」로 짧은 대화를 지을 때 알맞은 상황은 어느 것인가요?","options":[{"t":"숙제 마감이 내일 아침인데 아직 시작하지 않은 동생에게 형이 말하는 장면","correct":true},{"t":"불꽃놀이를 구경하는 장면","mis":"K6-1-u4-X01"},{"t":"시간이 많이 남아 느긋한 장면","mis":"K6-1-u4-X25"},{"t":"상을 받아 기뻐하는 장면","mis":"K6-1-u4-X25"}],"explanation":["실제 불 이야기가 아니에요.","느긋한 것과 반대예요.","몹시 급한 상황에 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#20','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C27',3,'mc','auto','견학한 곳을 이름 없는 곳으로 지어 쓸 때 꼭 지켜야 할 것은 어느 것인가요?',ARRAY['K6-1-u4-X26','K6-1-u4-X29']::text[],false,'{"seq":20,"concept":"K6-1-u4-C27","difficulty":3,"kind":"mc","stem":"견학한 곳을 이름 없는 곳으로 지어 쓸 때 꼭 지켜야 할 것은 어느 것인가요?","options":[{"t":"그 안에서 새로 안 사실은 실제로 참이어야 한다","correct":true},{"t":"새로 안 사실도 마음껏 지어도 된다","mis":"K6-1-u4-X26"},{"t":"견학한 곳은 반드시 유명한 곳이어야 한다","mis":"K6-1-u4-X26"},{"t":"감상은 빼야 한다","mis":"K6-1-u4-X29"}],"explanation":["사실을 지으면 거짓을 전해요.","이름 없는 곳도 괜찮아요.","무대는 지어도 사실은 참이어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#21','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C32',3,'mc','auto','견학 기록문을 쓰는 까닭을 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['K6-1-u4-X32','K6-1-u4-X37']::text[],false,'{"seq":21,"concept":"K6-1-u4-C32","difficulty":3,"kind":"mc","stem":"견학 기록문을 쓰는 까닭을 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"쓰는 사람에게도 남고, 읽는 사람에게도 건너간다","correct":true},{"t":"글씨 연습과 낱말 외우기에 좋다","mis":"K6-1-u4-X32"},{"t":"정해진 칸을 채우는 연습이 된다","mis":"K6-1-u4-X37"},{"t":"견학 숙제를 빨리 끝낼 수 있다","mis":"K6-1-u4-X32"}],"explanation":["글씨 연습이 목적이 아니에요.","칸 채우기가 아니에요.","남기고, 전하고, 도움이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#22','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C39',3,'mc','auto','동물이 든 표현과 몸이 든 표현으로 나눈 사전의 좋은 점은 어느 것인가요?',ARRAY['K6-1-u4-X11','K6-1-u4-X44','K6-1-u4-X40']::text[],false,'{"seq":22,"concept":"K6-1-u4-C39","difficulty":3,"kind":"mc","stem":"동물이 든 표현과 몸이 든 표현으로 나눈 사전의 좋은 점은 어느 것인가요?","options":[{"t":"같은 낱말로 묶어 필요할 때 빨리 찾을 수 있다","correct":true},{"t":"쓸 상황을 적지 않아도 된다","mis":"K6-1-u4-X11"},{"t":"마음으로 묶은 것과 똑같다","mis":"K6-1-u4-X44"},{"t":"표현 개수가 저절로 많아진다","mis":"K6-1-u4-X40"}],"explanation":["쓸 상황은 늘 적어요.","마음으로 묶은 것과는 달라요.","낱말로 묶으면 찾기가 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#23','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C42',4,'mc','auto','시온이네 반 발표 장면 전체를 가장 알맞게 평가한 것은 어느 것인가요?',ARRAY['K6-1-u4-X42','K6-1-u4-X43']::text[],false,'{"seq":23,"concept":"K6-1-u4-C42","difficulty":4,"kind":"mc","stem":"시온이네 반 발표 장면 전체를 가장 알맞게 평가한 것은 어느 것인가요?","options":[{"t":"시온이는 목소리 크기 · 자세 · 존댓말을, 다인이는 경청을 고쳐야 하고, 태하는 공식적인 자리에 맞게 말했다","correct":true},{"t":"세 사람 모두 예절을 잘 지켰다","mis":"K6-1-u4-X42"},{"t":"태하가 끼어들어 잘못했다","mis":"K6-1-u4-X43"},{"t":"다인이는 작은 소리라 괜찮고 시온이만 고치면 된다","mis":"K6-1-u4-X43"}],"explanation":["잘못한 사람이 있어요.","태하는 끝난 뒤 물었어요.","다인이도 경청하지 않았어요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"이제 시온이가 모둠에서 조사한 내용을 반 친구들 앞에서 발표하겠습니다."},{"who":"시온","text":"(작은 목소리로, 칠판 쪽을 보며) 우리 모둠은 정수장에 대해 알아봤어. 물을 여러 번 거른대."},{"who":"다인","text":"(발표 도중에 짝에게) 이따 쉬는 시간에 뭐 할래?"},{"who":"태하","text":"(발표가 끝나자) 잘 들었습니다. 소독은 어떻게 하는지 여쭤봐도 될까요?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#24','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C42',4,'essay','teacher','시온이의 발표를 공식적인 말하기 예절에 맞게 고쳐 쓰고, 「듣는 사람이 편하게 들을 수 있는가」라는 기준으로 고친 까닭을 설명하세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u4-C42","difficulty":4,"kind":"essay","stem":"시온이의 발표를 공식적인 말하기 예절에 맞게 고쳐 쓰고, 「듣는 사람이 편하게 들을 수 있는가」라는 기준으로 고친 까닭을 설명하세요.","answer_guide":{"answer":"예: (반 친구들을 바라보며, 모두에게 들리는 목소리로) 「저희 모둠은 정수장에 대해 알아보았습니다. 정수장에서는 물을 여러 단계를 거쳐 깨끗하게 만든다고 합니다.」 여럿이 듣는 자리라 작은 목소리로는 뒤쪽 친구들이 들을 수 없고, 칠판을 보고 말하면 듣는 사람이 집중하기 어렵다. 또 공식적인 자리이므로 존댓말을 써야 듣는 사람이 편하게 들을 수 있다.","scoring_points":["존댓말로 고쳐 썼는가","목소리 크기와 자세를 고쳤는가","듣는 사람을 기준으로 까닭을 설명했는가"]},"explanation":["말을 고쳐요.","목소리와 자세도 고쳐요.","듣는 사람을 두고 설명해요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"이제 시온이가 모둠에서 조사한 내용을 반 친구들 앞에서 발표하겠습니다."},{"who":"시온","text":"(작은 목소리로, 칠판 쪽을 보며) 우리 모둠은 정수장에 대해 알아봤어. 물을 여러 번 거른대."},{"who":"다인","text":"(발표 도중에 짝에게) 이따 쉬는 시간에 뭐 할래?"},{"who":"태하","text":"(발표가 끝나자) 잘 들었습니다. 소독은 어떻게 하는지 여쭤봐도 될까요?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u4_review_d#25','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C41',4,'essay','teacher','나만의 관용 표현 사전에 넣을 표현 하나를 골라 표현 · 뜻 · 쓸 수 있는 상황을 쓰고, 그 표현을 고른 기준을 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u4-C41","difficulty":4,"kind":"essay","stem":"나만의 관용 표현 사전에 넣을 표현 하나를 골라 표현 · 뜻 · 쓸 수 있는 상황을 쓰고, 그 표현을 고른 기준을 설명하세요.","answer_guide":{"answer":"예: 표현 — 귀에 익다. 뜻 — 여러 번 들어 익숙하다. 쓸 수 있는 상황 — 처음 배우는 노래인데 엄마가 자주 부르셔서 이미 익숙할 때. 고른 기준 — 어렵거나 멋있어 보이는 표현보다 이번 달에 내가 실제로 쓸 자리가 떠오르는 표현이라서 골랐다.","scoring_points":["표현과 뜻을 바르게 썼는가","내가 겪은 쓸 상황을 썼는가","내가 쓸 자리가 떠오르는가라는 기준을 썼는가"]},"explanation":["표현을 하나 골라요.","세 칸을 채워요.","고른 기준을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C1','kor',6,1,'u5',1,'주장하는 글의 뜻 — 주장하는 글은 어떤 문제에 대해 다른 사람을 설득할 목적으로 쓰는 글로, 본 것을 그대로 전하는 글이나 마음을 적는 일기와 달리 「어떻게 하면 좋겠다」는 생각을 세워 남을 움직이려 한다',ARRAY['6국03-02 쓰기']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C2','kor',6,1,'u5',1,'주장 · 이유 · 근거 — 주장은 어떤 문제에 대해 내세우는 글쓴이의 의견, 이유는 그렇게 주장하는 주관적인 까닭, 근거는 이유를 뒷받침하는 객관적인 자료이며, 주장만 있으면 우기는 말이 되고 근거가 없으면 혼자만의 생각에 머문다 — 본 것을 그대로 말한 문장은 주장이 아니라 문제 상황이다',ARRAY['6국03-02 쓰기']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C3','kor',6,1,'u5',1,'주장하는 글을 쓰면 좋은 점 — 왜 그렇게 여기는지 스스로 따져 보게 되어 생각이 정돈되고 · 글로 남아 여러 사람을 움직이며 · 무엇이 문제인지 찾다 보면 둘레를 다시 보게 되고, 함께 쓰는 곳을 위한 글이라 쓰는 사람에게 책임이 따른다',ARRAY['6국03-02 쓰기']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C4','kor',6,1,'u5',1,'문제마다 다른 주장 — 같은 학교 안이라도 무엇이 불편한지가 다르면 펼칠 주장도 달라지므로, 먼저 불편을 잡고 그 불편을 없앨 방법을 주장으로 세운다(사물함 칸이 없다 → 반마다 칸을 정하자)',ARRAY['6국03-02 쓰기']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C5','kor',6,1,'u5',1,'쓰는 동안 점검하면 좋은 점 — 점검하지 않고 쓰면 다 쓰고 나서야 하려던 말이 아니었음을 깨달아 고칠 곳이 한꺼번에 몰리지만, 쓰면서 점검하면 어긋난 부분을 그때그때 바로잡고 내 글을 한 걸음 떨어져 볼 수 있다',ARRAY['6국03-05 쓰기']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C6','kor',6,1,'u5',1,'완성이 아니라 과정 — 이 단원은 흠 없는 글 한 편을 내놓는 시간이 아니라 쓰고 살펴보고 고치는 길을 익히는 시간이며, 처음부터 잘 쓴 사람이 아니라 다시 살펴본 사람이 좋은 글에 닿으므로 우선 한 줄부터 적어 본다',ARRAY['6국03-05 쓰기']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C7','kor',6,1,'u5',2,'이유는 내 생각, 근거는 밖에서 — 이유는 「∼하기 때문이다」로 이어지는 내 주관적인 까닭이고, 근거는 조사 결과 · 기사 · 전문가의 말처럼 밖에서 가져와 누구나 확인할 수 있는 자료라서, 둘을 섞지 않는 것이 첫걸음이다',ARRAY['6국03-02 쓰기']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C8','kor',6,1,'u5',2,'글에서 근거 찾기 — 글쓴이의 생각을 말한 문장과, 밖에서 가져와 출처를 붙인 자료를 갈라 보면 근거가 보이며, 설문 결과 · 직접 센 기록 · 선생님 면담처럼 누구나 확인할 수 있는 것이 근거다',ARRAY['6국03-02 쓰기']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C9','kor',6,1,'u5',2,'이유의 타당성 — 이유를 볼 때에는 「주장과 이유가 관련 있는가」 · 「이유가 주장을 잘 설명하는가」를 물으며, 옳은 말이어도 주장과 이어지지 않으면(운동장을 나누자 ← 급식을 남기면 아깝다) 이유가 되지 못한다',ARRAY['6국03-02 쓰기']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C10','kor',6,1,'u5',2,'근거의 타당성 — 근거를 볼 때에는 「이유와 근거가 관련 있는가」 · 「근거의 출처를 믿을 수 있는가」 · 「이유를 뒷받침하는 객관적인 자료인가」를 묻고, 주장하는 글은 고개를 끄덕이며만 읽지 않고 「정말 그런가」를 물으며 읽는다',ARRAY['6국03-02 쓰기']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C11','kor',6,1,'u5',2,'서론 — 서론은 문제 제기와 주장 밝히기를 하는 부분으로, 왜 이 글을 쓰게 되었는지 · 지금 무엇이 불편한지를 밝히고 글쓴이의 의견을 뚜렷이 드러내며, 이어서 무엇을 살펴볼지 한 줄로 안내하기도 한다',ARRAY['6국03-02 쓰기']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C12','kor',6,1,'u5',2,'본론 — 본론은 이유와 그 이유를 뒷받침하는 근거로 주장을 펼쳐 나가는 부분으로, 이유는 「첫째 · 둘째」처럼 갈라 적으면 따라오기 쉽고, 하나의 이유에 근거가 여러 개 붙기도 한다',ARRAY['6국03-02 쓰기']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C13','kor',6,1,'u5',2,'결론 — 결론은 앞에서 말한 이유를 짧게 모아 요약하고 주장을 한 번 더 강조하는 부분이며, 때로는 「이렇게 하면 어떻게 될 것이다」처럼 앞을 내다보는 내용을 담고, 처음 꺼내는 새 근거를 두는 부분이 아니다',ARRAY['6국03-02 쓰기']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C14','kor',6,1,'u5',2,'중심 문장과 뒷받침 문장 — 중심 문장은 그 문단을 대표하는 한 문장이고 나머지는 그것을 받쳐 주는 뒷받침 문장이며, 본론 문단에서는 대개 「첫째, ∼하기 때문이다」가 중심 문장이고 수나 조사 결과가 든 문장은 대개 뒷받침 문장이다 — 중심 문장만 이어 읽으면 글의 뼈대가 드러난다',ARRAY['6국03-02 쓰기']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C15','kor',6,1,'u5',2,'출처가 붙었다고 다 타당하지는 않다 — 출처는 자료가 어디서 왔는지를 알려 줄 뿐이라 「이 자료가 이 이유를 정말 뒷받침하는가」를 한 번 더 보아야 하며, 타당하다고 판단했다면 그렇게 판단한 까닭도 함께 말할 수 있어야 한다 — 「그냥 그럴 것 같아서」는 판단이 아니다',ARRAY['6국03-02 쓰기']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C16','kor',6,1,'u5',4,'인용 자료의 갈래 — 주장하는 글에는 수로 나타낸 통계 자료 · 그 일을 잘 아는 사람의 전문가 의견 · 누구나 확인할 수 있는 기록이나 규칙인 사실 자료 · 실험이나 조사의 결과가 들어오며, 넷 다 내가 만든 것이 아니라 출처를 밝혀야 한다',ARRAY['6국03-02 쓰기']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C17','kor',6,1,'u5',4,'인용과 표절 — 인용은 다른 사람의 말이나 글 · 자료를 가져와 내 글에서 쓰는 것으로 글을 튼튼하게 하지만, 출처를 밝히지 않거나 · 여러 글에서 조각조각 가져와 내 글인 척하거나 · 표나 사진을 출처 없이 쓰면 표절이 된다',ARRAY['6국03-02 쓰기']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C18','kor',6,1,'u5',4,'출처를 밝히는 까닭 — 출처를 밝히면 만든 사람의 권리를 지키고 · 어디까지가 내 말인지 읽는 사람이 알 수 있고 · 원래 어떤 상황에서 나온 말인지 확인할 수 있어 뜻이 정확히 전해지며, 이것은 예의가 아니라 지켜야 할 약속이다',ARRAY['6국03-02 쓰기']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C19','kor',6,1,'u5',4,'뜻을 비틀지 않기 — 인용에는 출처를 밝히는 일과 뜻을 왜곡하지 않는 일이 함께 붙으므로, 만든 사람이 하려던 말을 먼저 정확히 이해하고 그대로 살려 옮긴 뒤 출처를 붙이며, 출처를 적었어도 뜻을 과장하거나 비틀면 소용이 없다',ARRAY['6국03-02 쓰기']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C20','kor',6,1,'u5',4,'저작물 · 저작자 · 저작권 — 저작물은 사람의 생각이나 감정을 표현한 창작물, 저작자는 그것을 만든 사람, 저작권은 저작자가 저작물에 대해 가지는 권리이며, 글 · 그림 · 사진 · 노래 · 영상이 모두 저작물이고 내가 쓴 주장하는 글도 저작물이라 나도 저작자다',ARRAY['6국03-02 쓰기']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C21','kor',6,1,'u5',4,'출처의 네 가지 — 출처에는 누가 만들었는가(만든 사람이나 기관) · 언제 나왔는가(만든 시기) · 무엇인가(자료의 이름) · 어디에 실렸는가(실린 곳)가 들어가며, 네 가지가 다 있어야 읽는 사람이 직접 찾아가 확인할 수 있다 — 하나라도 빠지면 「어딘가에서 봤다」와 다르지 않다',ARRAY['6국03-02 쓰기']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C22','kor',6,1,'u5',4,'출처 적는 차례와 부호 — 출처를 적는 차례와 부호는 조금씩 다를 수 있지만 네 가지가 빠지지 않는 것이 중요하며, 표나 그래프를 가져올 때에는 제목과 만든 곳을 함께 적는다',ARRAY['6국03-02 쓰기']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C23','kor',6,1,'u5',4,'믿을 수 있는 자료 — 공공 기관의 누리집 · 신문과 방송의 기사 · 학교가 낸 기록 · 내가 직접 한 조사와 면담은 믿을 만하고, 누가 썼는지 · 언제 올라왔는지 모르는 글이나 옮겨 적은 것만 있는 글은 한 번 더 확인하며, 직접 조사한 자료도 언제 · 누구에게 · 어디서 했는지 적어 두면 훌륭한 근거가 된다',ARRAY['6국03-02 쓰기']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C24','kor',6,1,'u5',4,'많이 인용할수록 좋은 글이 아니다 — 자료를 잔뜩 붙이고 내 문장이 몇 줄뿐이면 글쓴이의 생각이 남지 않으므로, 내 이유를 세우고 그 이유에 꼭 맞는 자료를 붙이며, 주장과 분명한 관련이 없는 자료는 글을 무겁게만 한다',ARRAY['6국03-02 쓰기']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C25','kor',6,1,'u5',4,'쓰기 윤리 — 글을 쓰는 사람은 확인되지 않은 사실을 쓰지 않았는가 · 인용할 때 출처를 정확히 밝혔는가 · 다른 사람을 헐뜯는 말을 쓰지 않았는가를 스스로 물으며, 글의 길이나 어려운 낱말의 수는 쓰기 윤리와 관계가 없다',ARRAY['6국03-02 쓰기']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C26','kor',6,1,'u5',6,'주제 · 목적 · 대상 — 주장을 펼치기 전에 어떤 문제를 다룰지(주제) · 무엇을 이루고 싶은지(목적) · 누가 들을지(대상)를 정하면 할 말이 좁혀지며, 대상이 달라지면 주장 자체가 아니라 고르는 근거와 말하는 방법이 달라진다',ARRAY['6국03-02 쓰기']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C27','kor',6,1,'u5',6,'주장은 명료하게 — 주장은 무엇을 하자는 것인지 한 가지로 읽혀야 하며(「비 오는 날 우산은 우산꽂이에 꽂읍시다」), 뜻이 흐리거나(「우산을 잘 관리합시다」) 두 가지로 읽히면(「복도를 더 좋게 만듭시다」) 아무리 좋은 근거를 붙여도 무엇을 설득당한 것인지 남지 않는다',ARRAY['6국03-02 쓰기']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C28','kor',6,1,'u5',6,'이유 세우기 — 이유는 내 주관적인 까닭이지만 하나하나가 주장을 뒷받침해야 하므로, 주장이 이루어지면 사라지는 불편이라야 이유가 되고, 주장과 이어지지 않으면 사실이어도 이유가 되지 못한다',ARRAY['6국03-02 쓰기']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C29','kor',6,1,'u5',6,'근거를 찾는 길 — 직접 조사하기(설문 · 수 세기) · 여쭈어 보기(면담) · 기사와 책 찾기 · 공공 자료 보기 가운데 어느 길로 찾든, 이 자료가 그 이유를 정말 뒷받침하는가와 출처를 믿을 수 있는가를 보며, 이유가 말하는 낱말(넘어짐 · 잃어버림 · 미끄러움)이 든 자료를 짝짓는다',ARRAY['6국03-02 쓰기']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C30','kor',6,1,'u5',6,'객관적인 자료 — 「나는 그렇게 느꼈다」나 「아마 다들 그럴 것이다」는 아무리 진심이어도 객관적인 자료가 아니며, 그 자리에 없던 사람도 나중에 찾아가 확인할 수 있어야 근거다',ARRAY['6국03-02 쓰기']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C31','kor',6,1,'u5',6,'예상되는 반박에 대비하기 — 반대할 사람이 할 말을 미리 떠올리는 것은 내 주장을 차갑게 다시 보는 일로, 못 들은 척하면 발표하는 그 자리에서 무너지지만 맞는 말을 받아들여 내용을 보태면 주장이 더 단단해진다',ARRAY['6국03-02 쓰기']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C32','kor',6,1,'u5',6,'말로 먼저 펼쳐 보기 — 정리한 내용을 종이에 쓰기 전에 서론(문제와 주장) → 본론(이유마다 근거와 출처) → 결론(주장을 다시 힘주어) 차례로 소리 내어 말해 보면 쓰기 부담이 줄고, 말한 뒤 주장이 뚜렷했는지 · 출처를 밝혔는지 스스로 확인한다',ARRAY['6국03-02 쓰기']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C33','kor',6,1,'u5',8,'주제를 고르는 두 조건 — 주장하는 글의 주제는 주장 · 이유 · 근거를 댈 수 있고 · 여러 사람에게 알릴 만한 문제여야 하며, 좋은 주제는 내가 실제로 겪은 일 가운데 우리가 바꿀 수 있는 일에서 나온다 — 나 혼자만의 일이나 근거를 찾을 수 없는 일은 글이 되지 않는다',ARRAY['6국03-05 쓰기']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C34','kor',6,1,'u5',8,'계획하기 — 계획하기는 글을 쓸 준비를 하는 과정으로 글을 쓰는 목적 · 글의 주제 · 글을 읽을 사람을 정하며, 이것이 정해지면 어떤 말투로 쓸지와 어떤 근거를 고를지도 함께 정해진다',ARRAY['6국03-05 쓰기']::text[],34) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C35','kor',6,1,'u5',8,'계획하기는 쓰기 전에만이 아니다 — 계획하기는 글을 쓰기 전에만 거치는 단계가 아니라, 쓰다가 읽을 사람이 달라져야 함을 알면 언제든 계획으로 되돌아가 고칠 수 있으며, 어긋난 계획을 붙들고 끝까지 가지 않는다',ARRAY['6국03-05 쓰기']::text[],35) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C36','kor',6,1,'u5',8,'내용 생성하기 — 내용 생성하기는 쓸 거리를 떠올리고 자료를 모으는 과정으로, 핵심 낱말과 짧은 문장으로 떠오르는 것을 최대한 많이 꺼내 놓고(문장 다듬기는 나중), 찾은 자료의 출처를 그때 함께 적어 두어야 나중에 찾아 헤매지 않는다',ARRAY['6국03-05 쓰기']::text[],36) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C37','kor',6,1,'u5',8,'내용 조직하기와 통일성 — 내용 조직하기는 떠올린 것을 서론 · 본론 · 결론 짜임에 맞게 늘어놓아 개요를 짜는 과정이며, 이때 글의 주제와 세부 내용이 서로 가깝게 이어지는 성질인 통일성을 살펴 옳은 말이라도 주제와 이어지지 않는 내용은 걸러 낸다',ARRAY['6국03-05 쓰기']::text[],37) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C38','kor',6,1,'u5',8,'중심 문장부터 세우기 — 중심 문장이 없으면 문단이 어색해지지만 뒷받침 문장은 없어도 문단이 하나의 생각을 담을 수 있으므로, 문단을 짤 때에는 「이 문단에서 하고 싶은 말」을 한 문장으로 먼저 세우고 그 아래에 근거와 설명을 붙인다',ARRAY['6국03-05 쓰기']::text[],38) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C39','kor',6,1,'u5',8,'표현하기 — 표현하기는 조직한 것을 바탕으로 스스로 문장을 써 처음 글을 쓰는 과정으로, 조직하기까지 낱말과 어구로 적었던 것을 문장으로 풀며, 읽을 사람이 이해할 수 있게 쓰고, 쓰다가 더 좋은 생각이 떠오르면 앞 단계로 돌아가 내용을 보태도 된다',ARRAY['6국03-05 쓰기']::text[],39) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C40','kor',6,1,'u5',10,'점검하고 조정하기 — 점검은 다 쓴 뒤에 채점하는 일이 아니라 쓰는 도중에 내가 한 일을 되돌아보고 · 고칠 곳을 찾고 · 방향을 다시 잡는 일이며, 쓰기 과정 다섯 단계 한가운데에 놓여 어느 단계에서나 일어난다',ARRAY['6국03-05 쓰기']::text[],40) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C41','kor',6,1,'u5',10,'쓰기 과정 다섯 단계 — 계획하기(목적 · 주제 · 읽을 사람 정하기) → 내용 생성하기(쓸 거리 떠올리고 자료 모으기) → 내용 조직하기(짜임에 맞게 늘어놓기) → 표현하기(문장으로 써 내려가기) → 고쳐쓰기(손볼 곳 찾아 고치기)',ARRAY['6국03-05 쓰기']::text[],41) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C42','kor',6,1,'u5',10,'쓰기는 되돌아오는 성질을 지닌다 — 쓰기 과정은 앞으로만 가는 길이 아니라 쓰다가 근거가 약하면 내용 생성하기로, 조직하다가 계획으로 되돌아가는 것이 정상이며, 되돌아가는 것은 처음부터 다시 하는 실패가 아니라 쓰기의 성질이라 되돌아간 단계에서 글이 좋아진다',ARRAY['6국03-05 쓰기']::text[],42) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C43','kor',6,1,'u5',10,'단계마다 점검할 것 — 계획하기는 목적 · 주제 · 읽을 사람을 정했는가, 내용 생성하기는 아는 것을 먼저 꺼내고 모자란 부분을 채울 자료를 찾았는가, 내용 조직하기는 짜임에 맞게 · 관련 있는 것끼리 묶어 늘어놓았는가, 표현하기는 짜임대로 문장이 되었고 읽을 사람이 알아듣는가를 묻는다 — 표현하기 점검의 잣대는 내가 아니라 읽을 사람이다',ARRAY['6국03-05 쓰기']::text[],43) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C44','kor',6,1,'u5',10,'점검은 흠 잡기가 아니다 — 고칠 곳을 찾아냈다는 것은 볼 줄 알게 되었다는 뜻이고 이 단원이 재는 것은 완성된 글의 흠이 아니라 고쳐 가는 과정이므로, 다시 쓰기가 버거우면 원래 글 위에 쪽지를 붙여 고칠 말만 얹어도 되고 한 군데만 고쳐도 점검을 한 것이다',ARRAY['6국03-05 쓰기']::text[],44) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C45','kor',6,1,'u5',10,'고쳐쓰기의 세 수준 — 글 수준(주제가 드러나는가 · 짜임에 맞는가) · 문단 수준(중심 문장을 뒷받침 문장이 받치는가 · 문장끼리 이어지는가) · 문장과 낱말 수준(이해하기 쉬운가 · 띄어쓰기와 맞춤법)으로 나누어 고치며, 큰 것부터 손보면 헛수고가 줄지만 반드시 이 차례일 필요는 없어 눈에 띄는 곳부터 손대도 된다',ARRAY['6국03-05 쓰기']::text[],45) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C46','kor',6,1,'u5',10,'띄어쓰기와 맞춤법 살피기 — 문장과 낱말 수준에서는 띄어쓰기가 바른가 · 맞춤법이 틀리지 않았는가 · 읽는 사람이 알기 쉬운 낱말을 골랐는가를 민감하게 살펴 바르게 고치며(「안돼요」 → 「안 돼요」), 이것도 글쓰기의 한 부분이다',ARRAY['6국04-06 문법']::text[],46) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C47','kor',6,1,'u5',12,'실천할 문제와 한 문장 주장 — 실천 활동의 문제는 우리 힘으로 바꿀 수 있고 근거를 댈 수 있어야 하며(비 오는 날이 많다 ✗), 주장은 「∼합시다 · ∼하지 맙시다」처럼 할 일이 드러나는 한 문장으로 만든다 — 길어질수록 흐려진다',ARRAY['6국03-02 쓰기']::text[],47) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C48','kor',6,1,'u5',12,'주장을 펼치는 여러 방법과 근거 — 만화 · 공익 광고 · 표어 · 노랫말 바꾸기처럼 방법은 여러 가지지만 주장 · 이유 · 근거는 그대로 있어야 하며, 큰 글씨나 화려한 그림은 눈길을 끌 뿐 생각을 바꾸지 못하므로 어떤 방법이든 확인할 수 있는 근거 하나는 남긴다 — 사람을 움직이는 것은 목소리의 크기가 아니라 근거다',ARRAY['6국03-02 쓰기']::text[],48) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C49','kor',6,1,'u5',12,'네 칸 짜임 — 의견(하고 싶은 말 한 문장) → 까닭(왜 그렇게 여기는지) → 사례(실제로 있었던 일이나 조사 결과) → 제안(그러니 이렇게 하자)의 네 칸은 서론 · 본론 · 결론을 짧게 줄인 틀로, 표어 · 만화 · 짧은 알림 글처럼 길게 쓸 수 없는 곳에서 근거가 사라지는 것을 막는다',ARRAY['6국03-02 쓰기']::text[],49) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C50','kor',6,1,'u5',12,'말한 대로 해 보기 — 주장하는 글이 닿아야 할 마지막 걸음은 종이가 아니라 생활이라, 내가 알린 대로 내가 먼저 일주일 동안 해 보고 날마다 지켰는지 표시하고 무엇이 달라졌는지 적으며, 잘된 점과 아쉬운 점 한 줄이 다음 주장의 출발선이 된다',ARRAY['6국03-02 쓰기']::text[],50) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C51','kor',6,1,'u5',12,'흐린 출처 알아보기 — 「어떤 조사에 따르면」 · 「어떤 선생님께서」처럼 누가 · 언제 · 무엇을 · 어디에 실었는지가 빠진 출처는 읽는 사람이 확인할 길이 없어 근거가 아니라 짐작이나 떠도는 말이 되며, 만든 사람의 권리도 지키지 못한 것이 된다',ARRAY['6국03-02 쓰기']::text[],51) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C52','kor',6,1,'u5',12,'비와 눈을 가리키는 우리말 — 같은 비 · 눈이라도 언제 · 얼마나 · 어떻게 내리느냐에 따라 여우비(볕이 난 날 잠깐 오다 그치는 비) · 먼지잼(먼지나 겨우 가라앉힐 만큼 조금 오는 비) · 밤비(밤에 내리는 비) · 도둑눈(밤사이 사람들 모르게 내린 눈) · 숫눈(쌓인 뒤 아무도 밟지 않은 눈) · 가루눈(가루처럼 잘게 내리는 눈)처럼 이름이 달라지며, 사전에서 「비」나 「눈」을 표제어로 잡고 딸린 말을 찾아 넓힌다 (기초 다지기)',ARRAY['기초 다지기(우리말)']::text[],52) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X01','kor',6,'u5',ARRAY['K6-1-u5-C1']::text[],'주장하는 글을 본 것을 그대로 전하는 글이나 마음만 적는 일기와 같은 글로 여긴다','설득할 목적이 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X02','kor',6,'u5',ARRAY['K6-1-u5-C2','K6-1-u5-C4']::text[],'본 것을 그대로 말한 문제 상황 문장을 주장으로 고른다','어떻게 하자고 내세웠나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X03','kor',6,'u5',ARRAY['K6-1-u5-C7','K6-1-u5-C2']::text[],'이유와 근거를 섞어, 내 생각을 근거로 여기거나 밖에서 가져온 자료를 이유로 여긴다','내 생각 · 밖의 자료') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X04','kor',6,'u5',ARRAY['K6-1-u5-C2']::text[],'주장만 힘주어 말하면 이유나 근거가 없어도 설득된다고 여긴다','주장만 있으면 우기는 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X05','kor',6,'u5',ARRAY['K6-1-u5-C3']::text[],'주장하는 글을 쓰면 좋은 점을 모르거나, 나만을 위한 글이라 책임이 따르지 않는다고 여긴다','정돈 · 움직임 · 책임') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X06','kor',6,'u5',ARRAY['K6-1-u5-C5','K6-1-u5-C40']::text[],'글쓰기를 점검하는 일을 글씨 · 줄 수 · 빠르기를 재는 일로 여긴다','무엇을 다시 보게 되나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X07','kor',6,'u5',ARRAY['K6-1-u5-C6','K6-1-u5-C44']::text[],'처음부터 흠 없는 완성 글을 내야 한다고 여겨 첫 문장부터 손이 멈춘다','과정을 익히는 시간') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X08','kor',6,'u5',ARRAY['K6-1-u5-C9','K6-1-u5-C28']::text[],'옳은 말이기만 하면 주장과 이어지지 않아도 이유가 된다고 여긴다','주장과 관련 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X09','kor',6,'u5',ARRAY['K6-1-u5-C30','K6-1-u5-C8']::text[],'「나는 그렇게 느꼈다」 · 「아마 다들 그럴 것이다」 같은 느낌이나 짐작을 근거로 쓴다','남이 확인할 수 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X10','kor',6,'u5',ARRAY['K6-1-u5-C11','K6-1-u5-C12','K6-1-u5-C13']::text[],'서론 · 본론 · 결론이 맡은 몫을 헷갈린다(서론에 근거만 잔뜩 · 본론에 문제 제기만)','제기 · 펼치기 · 모으기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X11','kor',6,'u5',ARRAY['K6-1-u5-C13']::text[],'결론에서 처음 꺼내는 새로운 근거를 내놓아야 한다고 여긴다','결론은 모으고 힘주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X12','kor',6,'u5',ARRAY['K6-1-u5-C12']::text[],'하나의 이유에는 근거가 꼭 하나만 붙어야 한다고 여긴다','여러 개 붙기도 해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X13','kor',6,'u5',ARRAY['K6-1-u5-C14','K6-1-u5-C38']::text[],'수나 조사 결과가 든 뒷받침 문장을 그 문단의 중심 문장으로 고른다','문단을 한 문장으로 줄이면') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X14','kor',6,'u5',ARRAY['K6-1-u5-C15']::text[],'출처가 붙어 있기만 하면 그 근거는 무조건 타당하다고 여긴다','이 이유를 정말 받치나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X15','kor',6,'u5',ARRAY['K6-1-u5-C15','K6-1-u5-C10']::text[],'타당한지를 까닭 없이 「그냥 그럴 것 같아서」로 판단한다','판단에도 까닭을') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X16','kor',6,'u5',ARRAY['K6-1-u5-C16','K6-1-u5-C17']::text[],'남이 만든 표 · 말 · 문장도 내 글에 넣으면 출처를 밝히지 않아도 된다고 여기거나, 내가 세운 주장에도 출처가 필요하다고 여긴다','내가 만들었나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X17','kor',6,'u5',ARRAY['K6-1-u5-C17']::text[],'여러 글에서 조각조각 가져와 이어 붙이면 내 글이 된다고 여긴다','조각 이어 붙이기도 표절') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X18','kor',6,'u5',ARRAY['K6-1-u5-C18']::text[],'출처를 밝히는 일을 해도 되고 안 해도 되는 예의 정도로 여긴다','지켜야 할 약속') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X19','kor',6,'u5',ARRAY['K6-1-u5-C19']::text[],'출처만 적으면 원래 뜻을 내 주장에 맞게 세게 바꾸거나 비틀어도 된다고 여긴다','뜻을 그대로 살려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X20','kor',6,'u5',ARRAY['K6-1-u5-C20']::text[],'저작물 · 저작자 · 저작권을 헷갈리거나, 학생이 쓴 글은 저작물이 아니라고 여긴다','물건 · 사람 · 권리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X21','kor',6,'u5',ARRAY['K6-1-u5-C21']::text[],'출처의 네 가지 가운데 하나쯤 빠져도 읽는 사람이 찾아갈 수 있다고 여긴다','네 가지가 다 있어야') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X22','kor',6,'u5',ARRAY['K6-1-u5-C22']::text[],'출처를 적는 차례와 부호는 하나로 정해져 있어 조금만 달라도 틀린다고 여기거나, 표를 가져올 때 제목과 만든 곳을 빠뜨린다','차례보다 네 가지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X23','kor',6,'u5',ARRAY['K6-1-u5-C23']::text[],'누가 썼는지 · 언제 올라왔는지 모르는 글을 믿을 만한 자료로 여기거나, 직접 한 조사는 근거가 될 수 없다고 여긴다','찾아가 확인할 수 있나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X24','kor',6,'u5',ARRAY['K6-1-u5-C24']::text[],'자료를 많이 인용할수록 좋은 글이 된다고 여긴다','내 생각이 남나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X25','kor',6,'u5',ARRAY['K6-1-u5-C25']::text[],'쓰기 윤리를 글의 길이나 어려운 낱말 수로 여기거나, 남을 헐뜯는 말은 상관없다고 여긴다','참 · 출처 · 헐뜯지 않기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X26','kor',6,'u5',ARRAY['K6-1-u5-C26']::text[],'듣는 사람이 달라지면 주장 자체를 바꿔야 한다고 여기거나, 대상을 생각하지 않고 근거와 말투를 고른다','바뀌는 것은 전하는 방법') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X27','kor',6,'u5',ARRAY['K6-1-u5-C27','K6-1-u5-C47']::text[],'뜻이 흐리거나 두 가지로 읽히는 주장(「복도를 더 좋게 만듭시다」)도 괜찮다고 여긴다','한 가지로 읽히나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X28','kor',6,'u5',ARRAY['K6-1-u5-C31']::text[],'반대하는 말은 못 들은 척해야 내 주장이 흔들리지 않는다고 여긴다','미리 떠올리면 단단해져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X29','kor',6,'u5',ARRAY['K6-1-u5-C33']::text[],'나 혼자만의 일이나 근거를 찾을 수 없는 일을 주장하는 글의 주제로 고른다','근거 · 여럿에게 알릴 만함') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X30','kor',6,'u5',ARRAY['K6-1-u5-C35']::text[],'계획은 이미 세웠으니 쓰는 도중에 계획으로 되돌아가면 안 된다고 여긴다','언제든 되돌아가요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X31','kor',6,'u5',ARRAY['K6-1-u5-C36']::text[],'내용 생성하기 단계에서 문장부터 다듬느라 떠오르는 것을 꺼내 놓지 못한다','핵심 낱말로 많이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X32','kor',6,'u5',ARRAY['K6-1-u5-C36']::text[],'자료를 찾을 때 출처는 나중에 적으면 된다고 미뤄 둔다','지금 적어 두어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X33','kor',6,'u5',ARRAY['K6-1-u5-C37']::text[],'옳은 말이면 글의 주제와 이어지지 않아도 넣어도 된다고 여긴다(통일성)','주제와 이어지나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X34','kor',6,'u5',ARRAY['K6-1-u5-C38']::text[],'중심 문장 없이 뒷받침 문장만 늘어놓아 문단을 짠다','하고 싶은 말 한 문장') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X35','kor',6,'u5',ARRAY['K6-1-u5-C39','K6-1-u5-C43']::text[],'표현하기를 점검할 때 내가 읽어 매끄러우면 된다고 여겨 나만 아는 줄임말을 그대로 둔다','잣대는 읽을 사람') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X36','kor',6,'u5',ARRAY['K6-1-u5-C40']::text[],'점검을 글을 다 쓴 뒤에 한 번 채점하는 일로 여긴다','쓰는 도중에 방향을') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X37','kor',6,'u5',ARRAY['K6-1-u5-C41']::text[],'쓰기 과정 다섯 단계의 이름과 하는 일을 헷갈린다','정하기 · 모으기 · 늘어놓기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X38','kor',6,'u5',ARRAY['K6-1-u5-C42']::text[],'앞 단계로 되돌아가면 처음부터 다시 하는 실패라고 여긴다','쓰기의 성질') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X39','kor',6,'u5',ARRAY['K6-1-u5-C43']::text[],'점검 질문을 엉뚱한 단계에 붙인다(계획하기에서 띄어쓰기를 묻는 식)','그 단계에서 한 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X40','kor',6,'u5',ARRAY['K6-1-u5-C44']::text[],'고칠 곳이 많으면 망한 글이라 여기거나, 고치려면 반드시 새 종이에 전부 다시 써야 한다고 여긴다','쪽지 하나도 점검') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X41','kor',6,'u5',ARRAY['K6-1-u5-C45']::text[],'고쳐쓰기 세 수준을 헷갈리거나, 반드시 맞춤법부터 또는 반드시 정해진 차례로만 고쳐야 한다고 여긴다','크기를 견줘요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X42','kor',6,'u5',ARRAY['K6-1-u5-C46']::text[],'띄어쓰기와 맞춤법은 글쓰기와 상관없는 일이라 살피지 않아도 된다고 여긴다','낱말도 민감하게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X43','kor',6,'u5',ARRAY['K6-1-u5-C47']::text[],'우리 힘으로 바꿀 수 없는 문제(날씨 · 방학 길이)를 실천 활동의 문제로 고른다','우리가 바꿀 수 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X44','kor',6,'u5',ARRAY['K6-1-u5-C48']::text[],'큰 글씨나 화려한 그림처럼 눈에 띄기만 하면 근거가 없어도 설득된다고 여긴다','근거 하나는 남겨요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X45','kor',6,'u5',ARRAY['K6-1-u5-C49']::text[],'네 칸 짜임(의견 · 까닭 · 사례 · 제안)의 차례나 칸마다 들어갈 것을 헷갈린다','꺼내고 · 왜 · 실제 · 다시') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X46','kor',6,'u5',ARRAY['K6-1-u5-C50']::text[],'주장을 알리고 나면 끝이라 여겨 내가 먼저 해 보는 일은 하지 않아도 된다고 여긴다','마지막 걸음은 생활') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X47','kor',6,'u5',ARRAY['K6-1-u5-C51','K6-1-u5-C21']::text[],'「어떤 조사에 따르면」 · 「어떤 선생님께서」처럼 흐린 말도 출처를 밝힌 것으로 여긴다','누가 · 언제 · 무엇 · 어디') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X48','kor',6,'u5',ARRAY['K6-1-u5-C52']::text[],'비와 눈을 가리키는 우리말의 뜻을 헷갈리거나, 우리말에는 비와 눈을 갈라 부르는 말이 없다고 여긴다','언제 · 얼마나 · 어떻게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L01_basic#1','kor',6,1,'u5','L01','g6_1_kor_u5_L01_basic','lesson_basic','K6-1-u5-C1',1,'mc','auto','「주장하는 글」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X01']::text[],false,'{"seq":1,"concept":"K6-1-u5-C1","difficulty":1,"kind":"mc","stem":"「주장하는 글」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"어떤 문제에 대해 다른 사람을 설득할 목적으로 쓰는 글","correct":true},{"t":"본 것을 있는 그대로 전하려고 쓰는 글","mis":"K6-1-u5-X01"},{"t":"그날 있었던 일과 마음을 적어 두는 글","mis":"K6-1-u5-X01"},{"t":"재미있는 일을 꾸며 지어낸 글","mis":"K6-1-u5-X01"}],"explanation":["본 것만 전하는 글이 아니에요.","일기와도 달라요.","다른 사람을 설득하려고 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L01_basic#2','kor',6,1,'u5','L01','g6_1_kor_u5_L01_basic','lesson_basic','K6-1-u5-C2',1,'match','auto','낱말과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K6-1-u5-C2","difficulty":1,"kind":"match","stem":"낱말과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"주장","r":"어떤 문제에 대해 내세우는 글쓴이의 의견"},{"l":"이유","r":"그렇게 주장하는 주관적인 까닭"},{"l":"근거","r":"이유를 뒷받침하는 객관적인 자료"}],"mis":"K6-1-u5-X03","explanation":["주장은 의견이에요.","이유는 내 까닭이에요.","근거는 밖에서 가져온 자료예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L01_basic#3','kor',6,1,'u5','L01','g6_1_kor_u5_L01_basic','lesson_basic','K6-1-u5-C2',1,'mc','auto','예찬이와 규리의 대화에서 주장에 해당하는 말은 어느 것인가요?',ARRAY['K6-1-u5-X02']::text[],false,'{"seq":3,"concept":"K6-1-u5-C2","difficulty":1,"kind":"mc","stem":"예찬이와 규리의 대화에서 주장에 해당하는 말은 어느 것인가요?","options":[{"t":"반마다 칸을 나누어 쓰면 좋겠어","correct":true},{"t":"신발주머니가 바닥에 쏟아져 있잖아","mis":"K6-1-u5-X02"},{"t":"체육관 사물함이 늘 뒤엉켜 있어","mis":"K6-1-u5-X02"},{"t":"칸이 정해져 있지 않아서 그래","mis":"K6-1-u5-X02"}],"explanation":["본 것을 그대로 말했어요.","문제 상황을 말했어요.","어떻게 하자고 내세운 말이 주장이에요."],"asset":{"type":"speech","turns":[{"who":"예찬","text":"체육관 사물함이 늘 뒤엉켜 있어. 수업이 끝나면 신발주머니가 바닥에 쏟아져 있잖아."},{"who":"규리","text":"칸이 정해져 있지 않아서 그래. 반마다 칸을 나누어 쓰면 좋겠어."},{"who":"예찬","text":"그 생각을 우리끼리만 말하면 바뀌지 않아. 글로 써서 다른 반에도 알리자."},{"who":"규리","text":"그럼 왜 그래야 하는지도 함께 적어야겠다. 그냥 하자고만 하면 아무도 안 들을 테니까."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L01_basic#4','kor',6,1,'u5','L01','g6_1_kor_u5_L01_basic','lesson_basic','K6-1-u5-C6',1,'ox','auto','이 단원은 흠 없는 글 한 편을 완성해 내놓는 것이 가장 중요한 시간이에요.',ARRAY['K6-1-u5-X07']::text[],false,'{"seq":4,"concept":"K6-1-u5-C6","difficulty":1,"kind":"ox","stem":"이 단원은 흠 없는 글 한 편을 완성해 내놓는 것이 가장 중요한 시간이에요.","answer":"X","reason_options":[{"t":"쓰고 살펴보고 고치는 글쓰기 과정을 익히는 시간이기 때문에","correct":true},{"t":"좋은 글은 처음부터 흠 없이 써야 하기 때문에","mis":"K6-1-u5-X07"}],"mis":"K6-1-u5-X07","explanation":["완성이 목표가 아니에요.","과정을 살펴보는 단원이에요.","우선 한 줄부터 적어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L01_basic#5','kor',6,1,'u5','L01','g6_1_kor_u5_L01_basic','lesson_basic','K6-1-u5-C3',2,'mc','auto','주장하는 글을 쓰면 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X05','K6-1-u5-X04','K6-1-u5-X06']::text[],false,'{"seq":5,"concept":"K6-1-u5-C3","difficulty":2,"kind":"mc","stem":"주장하는 글을 쓰면 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"왜 그렇게 여기는지 스스로 따져 보게 되어 생각이 정돈된다","correct":true},{"t":"나만 보는 글이라 아무렇게나 써도 된다","mis":"K6-1-u5-X05"},{"t":"이유 없이 주장만 크게 말해도 남이 따른다","mis":"K6-1-u5-X04"},{"t":"글씨를 바르게 쓰는 연습이 된다","mis":"K6-1-u5-X06"}],"explanation":["함께 쓰는 곳을 위한 글이라 책임이 따라요.","주장만으로는 우기는 말이 돼요.","생각이 정돈되고 남을 움직여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L01_basic#6','kor',6,1,'u5','L01','g6_1_kor_u5_L01_basic','lesson_basic','K6-1-u5-C4',2,'match','auto','문제 상황과 그때 펼칠 만한 주장을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-1-u5-C4","difficulty":2,"kind":"match","stem":"문제 상황과 그때 펼칠 만한 주장을 알맞게 이으세요.","pairs":[{"l":"체육관 사물함에 칸이 없다","r":"반마다 쓸 칸을 정해 둡시다"},{"l":"빌린 책이 제때 돌아오지 않는다","r":"반납일을 지켜 돌려줍시다"},{"l":"비 오는 날 우산이 복도에 흩어진다","r":"우산은 우산꽂이에 모아 둡시다"}],"mis":"K6-1-u5-X02","explanation":["불편을 먼저 잡아요.","불편을 없앨 방법이 주장이에요.","문제가 다르면 주장도 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L01_basic#7','kor',6,1,'u5','L01','g6_1_kor_u5_L01_basic','lesson_basic','K6-1-u5-C5',2,'mc','auto','글을 쓰는 과정을 점검하면 알 수 있는 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X06']::text[],false,'{"seq":7,"concept":"K6-1-u5-C5","difficulty":2,"kind":"mc","stem":"글을 쓰는 과정을 점검하면 알 수 있는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"보완할 점을 찾아 다시 조정할 수 있다","correct":true},{"t":"글을 몇 줄 썼는지 정확히 셀 수 있다","mis":"K6-1-u5-X06"},{"t":"글을 더 빨리 끝낼 수 있다","mis":"K6-1-u5-X06"},{"t":"글씨가 얼마나 반듯한지 잴 수 있다","mis":"K6-1-u5-X06"}],"explanation":["줄 수를 재는 일이 아니에요.","빠르기를 재는 일도 아니에요.","내 글을 한 걸음 떨어져 보게 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L01_basic#8','kor',6,1,'u5','L01','g6_1_kor_u5_L01_basic','lesson_basic','K6-1-u5-C2',2,'ox','auto','이유는 있는데 근거가 없으면 글쓴이 혼자만의 생각에 머물러요.',ARRAY['K6-1-u5-X04']::text[],false,'{"seq":8,"concept":"K6-1-u5-C2","difficulty":2,"kind":"ox","stem":"이유는 있는데 근거가 없으면 글쓴이 혼자만의 생각에 머물러요.","answer":"O","reason_options":[{"t":"누구나 확인할 수 있는 자료가 이유를 받쳐 주지 않기 때문에","correct":true},{"t":"이유만 있으면 누구나 그대로 믿기 때문에","mis":"K6-1-u5-X04"}],"mis":"K6-1-u5-X04","explanation":["이유는 내 까닭이에요.","근거가 받쳐 주어야 해요.","셋이 함께 다녀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L01_basic#9','kor',6,1,'u5','L01','g6_1_kor_u5_L01_basic','lesson_basic','K6-1-u5-C1',2,'mc','auto','규리가 「왜 그래야 하는지도 함께 적어야겠다」고 말한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X06','K6-1-u5-X01','K6-1-u5-X04']::text[],false,'{"seq":9,"concept":"K6-1-u5-C1","difficulty":2,"kind":"mc","stem":"규리가 「왜 그래야 하는지도 함께 적어야겠다」고 말한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"그냥 하자고만 하면 다른 사람이 따르지 않아 설득하기 어렵기 때문이다","correct":true},{"t":"글을 길게 써야 상을 받을 수 있기 때문이다","mis":"K6-1-u5-X06"},{"t":"본 것을 빠짐없이 전하는 글이기 때문이다","mis":"K6-1-u5-X01"},{"t":"주장만 쓰면 충분하기 때문이다","mis":"K6-1-u5-X04"}],"explanation":["길이를 늘리려는 것이 아니에요.","본 것만 전하는 글이 아니에요.","까닭이 있어야 설득돼요."],"asset":{"type":"speech","turns":[{"who":"예찬","text":"체육관 사물함이 늘 뒤엉켜 있어. 수업이 끝나면 신발주머니가 바닥에 쏟아져 있잖아."},{"who":"규리","text":"칸이 정해져 있지 않아서 그래. 반마다 칸을 나누어 쓰면 좋겠어."},{"who":"예찬","text":"그 생각을 우리끼리만 말하면 바뀌지 않아. 글로 써서 다른 반에도 알리자."},{"who":"규리","text":"그럼 왜 그래야 하는지도 함께 적어야겠다. 그냥 하자고만 하면 아무도 안 들을 테니까."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L01_basic#10','kor',6,1,'u5','L01','g6_1_kor_u5_L01_basic','lesson_basic','K6-1-u5-C5',3,'mc','auto','점검하지 않고 끝까지 쓴 뒤에 생기기 쉬운 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X36','K6-1-u5-X06']::text[],false,'{"seq":10,"concept":"K6-1-u5-C5","difficulty":3,"kind":"mc","stem":"점검하지 않고 끝까지 쓴 뒤에 생기기 쉬운 일로 알맞은 것은 어느 것인가요?","options":[{"t":"다 쓰고 나서야 하려던 말이 아니었음을 깨달아 고칠 곳이 한꺼번에 몰린다","correct":true},{"t":"고칠 곳이 하나도 생기지 않는다","mis":"K6-1-u5-X36"},{"t":"글씨가 저절로 반듯해진다","mis":"K6-1-u5-X06"},{"t":"어긋난 부분을 그때그때 바로잡게 된다","mis":"K6-1-u5-X36"}],"explanation":["고칠 곳은 늘 생겨요.","글씨와는 관계없어요.","쓰면서 점검해야 그때그때 바로잡아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L01_challenge#1','kor',6,1,'u5','L01','g6_1_kor_u5_L01_challenge','lesson_challenge','K6-1-u5-C2',2,'mc','auto','대화에서 주장이 아닌 것은 어느 것인가요?',ARRAY['K6-1-u5-X02']::text[],false,'{"seq":1,"concept":"K6-1-u5-C2","difficulty":2,"kind":"mc","stem":"대화에서 주장이 아닌 것은 어느 것인가요?","options":[{"t":"수업이 끝나면 신발주머니가 바닥에 쏟아져 있잖아","correct":true},{"t":"반마다 칸을 나누어 쓰면 좋겠어","mis":"K6-1-u5-X02"},{"t":"글로 써서 다른 반에도 알리자","mis":"K6-1-u5-X02"},{"t":"왜 그래야 하는지도 함께 적자","mis":"K6-1-u5-X02"}],"explanation":["칸을 나누자는 것은 주장이에요.","알리자는 것도 내세운 말이에요.","본 것을 그대로 말한 문장은 문제 상황이에요."],"asset":{"type":"speech","turns":[{"who":"예찬","text":"체육관 사물함이 늘 뒤엉켜 있어. 수업이 끝나면 신발주머니가 바닥에 쏟아져 있잖아."},{"who":"규리","text":"칸이 정해져 있지 않아서 그래. 반마다 칸을 나누어 쓰면 좋겠어."},{"who":"예찬","text":"그 생각을 우리끼리만 말하면 바뀌지 않아. 글로 써서 다른 반에도 알리자."},{"who":"규리","text":"그럼 왜 그래야 하는지도 함께 적어야겠다. 그냥 하자고만 하면 아무도 안 들을 테니까."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L01_challenge#2','kor',6,1,'u5','L01','g6_1_kor_u5_L01_challenge','lesson_challenge','K6-1-u5-C3',2,'ox','auto','주장하는 글은 함께 쓰는 곳을 위한 글이라서 쓰는 사람에게 책임이 따라요.',ARRAY['K6-1-u5-X05']::text[],false,'{"seq":2,"concept":"K6-1-u5-C3","difficulty":2,"kind":"ox","stem":"주장하는 글은 함께 쓰는 곳을 위한 글이라서 쓰는 사람에게 책임이 따라요.","answer":"O","reason_options":[{"t":"여러 사람에게 닿아 생각과 생활을 움직이는 글이기 때문에","correct":true},{"t":"나 혼자만 읽고 덮는 글이기 때문에","mis":"K6-1-u5-X05"}],"mis":"K6-1-u5-X05","explanation":["여러 사람에게 가 닿아요.","나만을 위한 글이 아니에요.","그래서 책임이 따라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L01_challenge#3','kor',6,1,'u5','L01','g6_1_kor_u5_L01_challenge','lesson_challenge','K6-1-u5-C6',3,'error','auto','단원을 시작하며 한 다짐이에요. 알맞지 않은 다짐은 누구의 것인가요?',ARRAY['K6-1-u5-X07']::text[],false,'{"seq":3,"concept":"K6-1-u5-C6","difficulty":3,"kind":"error","stem":"단원을 시작하며 한 다짐이에요. 알맞지 않은 다짐은 누구의 것인가요?","options":[{"t":"예찬 — 「한 번에 흠 없는 글을 써내야 해. 못 쓰면 어떡하지.」","correct":true,"mis_target":"K6-1-u5-X07"},{"t":"규리 — 「우선 한 줄부터 써 놓고 살펴보며 다듬을래.」","mis":"K6-1-u5-X07"},{"t":"슬아 — 「쓰고 살펴보고 고치는 길을 익혀 볼게.」","mis":"K6-1-u5-X07"}],"explanation":["규리는 바르게 다짐했어요.","슬아도 바르게 다짐했어요.","처음부터 완성할 필요는 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L01_challenge#4','kor',6,1,'u5','L01','g6_1_kor_u5_L01_challenge','lesson_challenge','K6-1-u5-C4',3,'mc','auto','「급식실 앞에서 줄이 엉켜 서로 밀친다」는 문제에 알맞은 주장은 어느 것인가요?',ARRAY['K6-1-u5-X02','K6-1-u5-X08','K6-1-u5-X27']::text[],false,'{"seq":4,"concept":"K6-1-u5-C4","difficulty":3,"kind":"mc","stem":"「급식실 앞에서 줄이 엉켜 서로 밀친다」는 문제에 알맞은 주장은 어느 것인가요?","options":[{"t":"급식실 앞에서는 한 줄로 섭시다","correct":true},{"t":"급식실 앞이 몹시 북적입니다","mis":"K6-1-u5-X02"},{"t":"반찬을 골고루 먹읍시다","mis":"K6-1-u5-X08"},{"t":"학교 생활을 더 좋게 합시다","mis":"K6-1-u5-X27"}],"explanation":["문제 상황을 다시 말했어요.","줄과 이어지지 않아요.","불편을 없앨 방법이 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L01_challenge#5','kor',6,1,'u5','L01','g6_1_kor_u5_L01_challenge','lesson_challenge','K6-1-u5-C2',3,'mc','auto','「주장만 있고 이유가 없는 말」은 어떤 말이 되나요?',ARRAY['K6-1-u5-X03','K6-1-u5-X01','K6-1-u5-X04']::text[],false,'{"seq":5,"concept":"K6-1-u5-C2","difficulty":3,"kind":"mc","stem":"「주장만 있고 이유가 없는 말」은 어떤 말이 되나요?","options":[{"t":"왜 그래야 하는지 밝히지 않고 우기는 말","correct":true},{"t":"누구나 확인할 수 있는 객관적인 말","mis":"K6-1-u5-X03"},{"t":"본 것을 정확하게 전하는 말","mis":"K6-1-u5-X01"},{"t":"저절로 남을 설득하는 말","mis":"K6-1-u5-X04"}],"explanation":["객관적인 자료는 근거예요.","본 것을 전하는 말과 달라요.","이유가 있어야 설득돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L01_challenge#6','kor',6,1,'u5','L01','g6_1_kor_u5_L01_challenge','lesson_challenge','K6-1-u5-C5',3,'mc','auto','쓰는 도중에 「이 이유가 주장과 맞나?」를 물어보면 좋아지는 점은 어느 것인가요?',ARRAY['K6-1-u5-X36','K6-1-u5-X06','K6-1-u5-X38']::text[],false,'{"seq":6,"concept":"K6-1-u5-C5","difficulty":3,"kind":"mc","stem":"쓰는 도중에 「이 이유가 주장과 맞나?」를 물어보면 좋아지는 점은 어느 것인가요?","options":[{"t":"어긋난 부분을 그때그때 바로잡을 수 있다","correct":true},{"t":"다 쓰고 나서 한꺼번에 고칠 수 있다","mis":"K6-1-u5-X36"},{"t":"줄 수가 늘어 글이 풍성해진다","mis":"K6-1-u5-X06"},{"t":"이유를 더는 고치지 않아도 된다","mis":"K6-1-u5-X38"}],"explanation":["몰아서 고치면 손대기 어려워요.","줄 수와는 관계없어요.","그때그때 바로잡아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L01_challenge#7','kor',6,1,'u5','L01','g6_1_kor_u5_L01_challenge','lesson_challenge','K6-1-u5-C6',3,'mc','auto','「처음부터 잘 쓴 사람이 아니라 다시 살펴본 사람이 좋은 글에 닿는다」는 말의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X07','K6-1-u5-X38','K6-1-u5-X06']::text[],false,'{"seq":7,"concept":"K6-1-u5-C6","difficulty":3,"kind":"mc","stem":"「처음부터 잘 쓴 사람이 아니라 다시 살펴본 사람이 좋은 글에 닿는다」는 말의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"좋은 글은 써 놓고 살펴보며 고쳐 가는 과정에서 만들어진다","correct":true},{"t":"타고난 사람만 좋은 글을 쓴다","mis":"K6-1-u5-X07"},{"t":"한 번 쓴 글은 고치지 않는 것이 좋다","mis":"K6-1-u5-X38"},{"t":"살펴보는 일은 글씨를 고치는 일이다","mis":"K6-1-u5-X06"}],"explanation":["누구나 고쳐 가며 써요.","고치는 것이 과정이에요.","살펴보는 것은 내용과 짜임이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L01_challenge#8','kor',6,1,'u5','L01','g6_1_kor_u5_L01_challenge','lesson_challenge','K6-1-u5-C3',4,'mc','auto','「주장하는 글을 쓰다 보면 둘레를 다시 보게 된다」는 말을 가장 잘 보여 주는 것은 어느 것인가요?',ARRAY['K6-1-u5-X05','K6-1-u5-X06','K6-1-u5-X04']::text[],false,'{"seq":8,"concept":"K6-1-u5-C3","difficulty":4,"kind":"mc","stem":"「주장하는 글을 쓰다 보면 둘레를 다시 보게 된다」는 말을 가장 잘 보여 주는 것은 어느 것인가요?","options":[{"t":"사물함 문제를 쓰려고 살피다가 그동안 지나쳤던 체육관 신발장 문제도 눈에 들어왔다","correct":true},{"t":"글을 쓰느라 둘레에 무슨 일이 있는지 신경 쓰지 못했다","mis":"K6-1-u5-X05"},{"t":"글씨를 쓰려고 책상 둘레를 정리했다","mis":"K6-1-u5-X06"},{"t":"주장만 크게 말하자 친구들이 모두 따라왔다","mis":"K6-1-u5-X04"}],"explanation":["오히려 둘레가 보여요.","책상 정리 이야기가 아니에요.","문제를 찾다 보면 지나친 일이 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L01_challenge#9','kor',6,1,'u5','L01','g6_1_kor_u5_L01_challenge','lesson_challenge','K6-1-u5-C2',4,'essay','teacher','예찬이와 규리가 쓸 글의 주장을 한 문장으로 쓰고, 이유 하나와 그 이유를 받쳐 줄 근거로 쓸 만한 자료를 하나씩 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u5-C2","difficulty":4,"kind":"essay","stem":"예찬이와 규리가 쓸 글의 주장을 한 문장으로 쓰고, 이유 하나와 그 이유를 받쳐 줄 근거로 쓸 만한 자료를 하나씩 쓰세요.","answer_guide":{"answer":"예: 주장 — 체육관 사물함을 반마다 칸을 나누어 씁시다. 이유 — 칸이 정해지면 신발주머니가 바닥에 쏟아지는 일이 줄기 때문이다. 근거 — 일주일 동안 수업이 끝난 뒤 바닥에 떨어진 신발주머니 수를 세어 적은 기록.","scoring_points":["주장을 할 일이 드러나는 한 문장으로 썼는가","주장과 이어진 이유를 썼는가","누구나 확인할 수 있는 자료를 근거로 들었는가"]},"explanation":["하자는 말로 주장을 세워요.","왜 그런지 이유를 붙여요.","확인할 수 있는 자료를 골라요."],"asset":{"type":"speech","turns":[{"who":"예찬","text":"체육관 사물함이 늘 뒤엉켜 있어. 수업이 끝나면 신발주머니가 바닥에 쏟아져 있잖아."},{"who":"규리","text":"칸이 정해져 있지 않아서 그래. 반마다 칸을 나누어 쓰면 좋겠어."},{"who":"예찬","text":"그 생각을 우리끼리만 말하면 바뀌지 않아. 글로 써서 다른 반에도 알리자."},{"who":"규리","text":"그럼 왜 그래야 하는지도 함께 적어야겠다. 그냥 하자고만 하면 아무도 안 들을 테니까."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L01_challenge#10','kor',6,1,'u5','L01','g6_1_kor_u5_L01_challenge','lesson_challenge','K6-1-u5-C6',4,'essay','teacher','글쓰기를 앞두고 「못 쓰면 어떡하지」 하고 걱정하는 친구에게, 이 단원에서 배우는 것이 무엇인지 알려 주며 해 줄 말을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u5-C6","difficulty":4,"kind":"essay","stem":"글쓰기를 앞두고 「못 쓰면 어떡하지」 하고 걱정하는 친구에게, 이 단원에서 배우는 것이 무엇인지 알려 주며 해 줄 말을 쓰세요.","answer_guide":{"answer":"예: 이 단원은 처음부터 흠 없는 글을 내는 시간이 아니라 쓰고 살펴보고 고치는 과정을 익히는 시간이야. 처음부터 잘 쓴 사람보다 다시 살펴본 사람이 좋은 글에 닿는대. 그러니 우선 한 줄부터 써 놓고 같이 고쳐 가 보자.","scoring_points":["완성이 아니라 과정을 익히는 단원임을 썼는가","살펴보고 고치는 일의 가치를 썼는가","부담을 덜어 주는 말을 썼는가"]},"explanation":["걱정하는 마음을 떠올려요.","이 단원이 배우는 것을 써요.","해 볼 수 있는 첫걸음을 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L02_basic#1','kor',6,1,'u5','L02','g6_1_kor_u5_L02_basic','lesson_basic','K6-1-u5-C7',1,'mc','auto','이유와 근거를 바르게 가른 것은 어느 것인가요?',ARRAY['K6-1-u5-X03']::text[],false,'{"seq":1,"concept":"K6-1-u5-C7","difficulty":1,"kind":"mc","stem":"이유와 근거를 바르게 가른 것은 어느 것인가요?","options":[{"t":"이유는 내 생각이고, 근거는 밖에서 가져온 자료이다","correct":true},{"t":"이유는 밖에서 가져온 자료이고, 근거는 내 생각이다","mis":"K6-1-u5-X03"},{"t":"이유와 근거는 같은 말이다","mis":"K6-1-u5-X03"},{"t":"근거는 주장을 다시 한번 말한 것이다","mis":"K6-1-u5-X03"}],"explanation":["거꾸로 말했어요.","둘은 섞지 않아요.","내 까닭과 밖의 자료를 갈라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L02_basic#2','kor',6,1,'u5','L02','g6_1_kor_u5_L02_basic','lesson_basic','K6-1-u5-C8',1,'mc','auto','「점심시간 운동장을 나누어 씁시다」에서 근거에 해당하는 것은 어느 것인가요?',ARRAY['K6-1-u5-X03','K6-1-u5-X02','K6-1-u5-X09']::text[],false,'{"seq":2,"concept":"K6-1-u5-C8","difficulty":1,"kind":"mc","stem":"「점심시간 운동장을 나누어 씁시다」에서 근거에 해당하는 것은 어느 것인가요?","options":[{"t":"스물다섯 명 가운데 열여덟 명이 부딪힐 뻔했다는 설문 결과","correct":true},{"t":"나누어 쓰면 더 안전하게 놀 수 있기 때문이다","mis":"K6-1-u5-X03"},{"t":"운동장을 학년에 따라 나누어 써야 한다","mis":"K6-1-u5-X02"},{"t":"뒤를 살피느라 멈칫할 일이 줄어든다","mis":"K6-1-u5-X09"}],"explanation":["「때문이다」는 이유예요.","하자는 말은 주장이에요.","출처가 붙은 조사 결과가 근거예요."],"asset":{"type":"passage","lines":["① 점심시간이면 운동장은 공놀이와 달리기와 줄넘기가 한꺼번에 벌어져","서로 부딪힐까 봐 마음을 놓지 못한다. 점심시간 운동장을 학년에 따라","나누어 써야 한다. 지금부터 그렇게 해야 하는 까닭을 살펴보자.","② 첫째, 나누어 쓰면 더 안전하게 놀 수 있기 때문이다. 우리 반 스물다섯","명 가운데 열여덟 명이 다른 사람과 부딪힐 뻔한 적이 있다고 답했다.","(솔바람반(2026), 「점심시간 운동장 이용 설문」, 학급 게시판.)","넉넉한 곳에서 놀면 뒤를 살피느라 멈칫할 일이 줄어든다."],"title":"「점심시간 운동장을 나누어 씁시다」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L02_basic#3','kor',6,1,'u5','L02','g6_1_kor_u5_L02_basic','lesson_basic','K6-1-u5-C11',1,'ox','auto','서론에서는 문제를 제기하고 주장을 밝혀요.',ARRAY['K6-1-u5-X10']::text[],false,'{"seq":3,"concept":"K6-1-u5-C11","difficulty":1,"kind":"ox","stem":"서론에서는 문제를 제기하고 주장을 밝혀요.","answer":"O","reason_options":[{"t":"왜 이 글을 쓰게 되었는지와 글쓴이의 의견을 먼저 드러내는 부분이기 때문에","correct":true},{"t":"이유와 근거를 모두 늘어놓는 부분이기 때문에","mis":"K6-1-u5-X10"}],"mis":"K6-1-u5-X10","explanation":["서론은 글의 앞부분이에요.","문제와 주장을 먼저 밝혀요.","이유와 근거는 본론에서 펼쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L02_basic#4','kor',6,1,'u5','L02','g6_1_kor_u5_L02_basic','lesson_basic','K6-1-u5-C12',1,'match','auto','글의 부분과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K6-1-u5-C12","difficulty":1,"kind":"match","stem":"글의 부분과 하는 일을 알맞게 이으세요.","pairs":[{"l":"서론","r":"문제를 제기하고 주장을 밝힌다"},{"l":"본론","r":"이유와 근거로 주장을 펼친다"},{"l":"결론","r":"요약하고 다시 한번 강조한다"}],"mis":"K6-1-u5-X10","explanation":["서론은 꺼내요.","본론은 펼쳐요.","결론은 모아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L02_basic#5','kor',6,1,'u5','L02','g6_1_kor_u5_L02_basic','lesson_basic','K6-1-u5-C9',2,'mc','auto','「운동장을 나누어 쓰자」는 주장과 관련이 없는 이유는 어느 것인가요?',ARRAY['K6-1-u5-X08']::text[],false,'{"seq":5,"concept":"K6-1-u5-C9","difficulty":2,"kind":"mc","stem":"「운동장을 나누어 쓰자」는 주장과 관련이 없는 이유는 어느 것인가요?","options":[{"t":"급식을 남기면 아깝기 때문이다","correct":true},{"t":"더 안전하게 놀 수 있기 때문이다","mis":"K6-1-u5-X08"},{"t":"놀 곳을 두고 벌어지는 다툼이 줄어들기 때문이다","mis":"K6-1-u5-X08"},{"t":"하려던 놀이를 끝까지 할 수 있기 때문이다","mis":"K6-1-u5-X08"}],"explanation":["안전은 운동장과 이어져요.","다툼도 이어져요.","급식은 운동장을 나누는 일과 이어지지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L02_basic#6','kor',6,1,'u5','L02','g6_1_kor_u5_L02_basic','lesson_basic','K6-1-u5-C14',2,'mc','auto','②문단의 중심 문장은 어느 것인가요?',ARRAY['K6-1-u5-X13','K6-1-u5-X10']::text[],false,'{"seq":6,"concept":"K6-1-u5-C14","difficulty":2,"kind":"mc","stem":"②문단의 중심 문장은 어느 것인가요?","options":[{"t":"첫째, 나누어 쓰면 더 안전하게 놀 수 있기 때문이다","correct":true},{"t":"스물다섯 명 가운데 열여덟 명이 부딪힐 뻔한 적이 있다고 답했다","mis":"K6-1-u5-X13"},{"t":"넉넉한 곳에서 놀면 뒤를 살피느라 멈칫할 일이 줄어든다","mis":"K6-1-u5-X13"},{"t":"점심시간 운동장을 학년에 따라 나누어 써야 한다","mis":"K6-1-u5-X10"}],"explanation":["수가 든 문장은 받쳐 주는 쪽이에요.","이 문장도 뒷받침 문장이에요.","문단 전체를 한 문장으로 줄여요."],"asset":{"type":"passage","lines":["① 점심시간이면 운동장은 공놀이와 달리기와 줄넘기가 한꺼번에 벌어져","서로 부딪힐까 봐 마음을 놓지 못한다. 점심시간 운동장을 학년에 따라","나누어 써야 한다. 지금부터 그렇게 해야 하는 까닭을 살펴보자.","② 첫째, 나누어 쓰면 더 안전하게 놀 수 있기 때문이다. 우리 반 스물다섯","명 가운데 열여덟 명이 다른 사람과 부딪힐 뻔한 적이 있다고 답했다.","(솔바람반(2026), 「점심시간 운동장 이용 설문」, 학급 게시판.)","넉넉한 곳에서 놀면 뒤를 살피느라 멈칫할 일이 줄어든다."],"title":"「점심시간 운동장을 나누어 씁시다」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L02_basic#7','kor',6,1,'u5','L02','g6_1_kor_u5_L02_basic','lesson_basic','K6-1-u5-C12',2,'ox','auto','본론에서 하나의 이유에는 근거가 꼭 하나만 붙어야 해요.',ARRAY['K6-1-u5-X12']::text[],false,'{"seq":7,"concept":"K6-1-u5-C12","difficulty":2,"kind":"ox","stem":"본론에서 하나의 이유에는 근거가 꼭 하나만 붙어야 해요.","answer":"X","reason_options":[{"t":"하나의 이유에 근거가 여러 개 붙기도 하기 때문에","correct":true},{"t":"근거가 둘이면 이유가 흐려지기 때문에","mis":"K6-1-u5-X12"}],"mis":"K6-1-u5-X12","explanation":["근거 수는 정해져 있지 않아요.","여러 근거가 받치기도 해요.","이유와 이어지는지가 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L02_basic#8','kor',6,1,'u5','L02','g6_1_kor_u5_L02_basic','lesson_basic','K6-1-u5-C13',2,'mc','auto','⑤문단이 결론인 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X11','K6-1-u5-X10']::text[],false,'{"seq":8,"concept":"K6-1-u5-C13","difficulty":2,"kind":"mc","stem":"⑤문단이 결론인 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"세 가지 까닭을 모아 말하고 주장을 다시 강조했기 때문이다","correct":true},{"t":"처음 꺼내는 새 근거를 내놓았기 때문이다","mis":"K6-1-u5-X11"},{"t":"문제를 처음으로 제기했기 때문이다","mis":"K6-1-u5-X10"},{"t":"설문 결과를 자세히 밝혔기 때문이다","mis":"K6-1-u5-X10"}],"explanation":["결론은 새 근거를 꺼내지 않아요.","문제 제기는 서론이에요.","모으고 다시 힘주는 부분이에요."],"asset":{"type":"passage","lines":["③ 둘째, 하려던 놀이를 끝까지 할 수 있기 때문이다. 사흘 동안 세어 보니","줄넘기를 하다 공에 밀려 그만둔 무리가 하루 평균 네 무리였다.","(솔바람반(2026), 「사흘 동안의 운동장 관찰 기록」, 학급 게시판.)","④ 셋째, 다툼이 줄어들기 때문이다. 학년 선생님께 여쭈어 보니 점심시간","다툼 가운데 놀 곳을 두고 벌어지는 다툼이 가장 잦다고 하셨다.","(김○○ 선생님 면담(2026), 「점심시간 생활 지도」, 육 학년 교무실.)","⑤ 지금까지 세 가지 까닭을 살펴보았다. 요일마다 학년을 정하는 방법도","있다. 모두에게 넉넉한 점심시간이 되도록 운동장을 나누어 쓰자."],"title":"「점심시간 운동장을 나누어 씁시다」 — 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L02_basic#9','kor',6,1,'u5','L02','g6_1_kor_u5_L02_basic','lesson_basic','K6-1-u5-C10',2,'mc','auto','근거가 타당한지 판단할 때 던질 물음으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X15','K6-1-u5-X09']::text[],false,'{"seq":9,"concept":"K6-1-u5-C10","difficulty":2,"kind":"mc","stem":"근거가 타당한지 판단할 때 던질 물음으로 알맞은 것은 어느 것인가요?","options":[{"t":"이 근거가 이유를 뒷받침하는가?","correct":true},{"t":"근거의 글자 수가 많은가?","mis":"K6-1-u5-X15"},{"t":"근거가 맨 앞에 나오는가?","mis":"K6-1-u5-X15"},{"t":"근거가 글쓴이의 느낌인가?","mis":"K6-1-u5-X09"}],"explanation":["길이는 기준이 아니에요.","놓인 차례도 아니에요.","받쳐 주는지가 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L02_basic#10','kor',6,1,'u5','L02','g6_1_kor_u5_L02_basic','lesson_basic','K6-1-u5-C15',3,'mc','auto','「출처가 적혀 있네. 그럼 맞는 말이겠지.」라고 읽는 태도의 문제점은 어느 것인가요?',ARRAY['K6-1-u5-X14','K6-1-u5-X21','K6-1-u5-X15']::text[],false,'{"seq":10,"concept":"K6-1-u5-C15","difficulty":3,"kind":"mc","stem":"「출처가 적혀 있네. 그럼 맞는 말이겠지.」라고 읽는 태도의 문제점은 어느 것인가요?","options":[{"t":"출처는 어디서 왔는지 알려 줄 뿐, 자료가 이유를 정말 받치는지는 따로 보아야 한다","correct":true},{"t":"출처가 있으면 언제나 맞는 말이다","mis":"K6-1-u5-X14"},{"t":"출처는 아예 읽지 않아도 된다","mis":"K6-1-u5-X21"},{"t":"그냥 그럴 것 같으면 맞는 말로 여겨도 된다","mis":"K6-1-u5-X15"}],"explanation":["출처가 곧 타당함은 아니에요.","출처도 꼭 살펴요.","판단에도 까닭이 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L02_challenge#1','kor',6,1,'u5','L02','g6_1_kor_u5_L02_challenge','lesson_challenge','K6-1-u5-C11',2,'mc','auto','①문단에서 「지금부터 그렇게 해야 하는 까닭을 살펴보자.」가 하는 일은 어느 것인가요?',ARRAY['K6-1-u5-X10','K6-1-u5-X27']::text[],false,'{"seq":1,"concept":"K6-1-u5-C11","difficulty":2,"kind":"mc","stem":"①문단에서 「지금부터 그렇게 해야 하는 까닭을 살펴보자.」가 하는 일은 어느 것인가요?","options":[{"t":"이어서 무엇을 살펴볼지 한 줄로 안내한다","correct":true},{"t":"주장한 내용을 요약한다","mis":"K6-1-u5-X10"},{"t":"이유를 뒷받침하는 근거를 든다","mis":"K6-1-u5-X10"},{"t":"처음 꺼내는 새 주장을 밝힌다","mis":"K6-1-u5-X27"}],"explanation":["요약은 결론에서 해요.","근거는 본론에서 들어요.","서론은 이어질 내용을 안내하기도 해요."],"asset":{"type":"passage","lines":["① 점심시간이면 운동장은 공놀이와 달리기와 줄넘기가 한꺼번에 벌어져","서로 부딪힐까 봐 마음을 놓지 못한다. 점심시간 운동장을 학년에 따라","나누어 써야 한다. 지금부터 그렇게 해야 하는 까닭을 살펴보자.","② 첫째, 나누어 쓰면 더 안전하게 놀 수 있기 때문이다. 우리 반 스물다섯","명 가운데 열여덟 명이 다른 사람과 부딪힐 뻔한 적이 있다고 답했다.","(솔바람반(2026), 「점심시간 운동장 이용 설문」, 학급 게시판.)","넉넉한 곳에서 놀면 뒤를 살피느라 멈칫할 일이 줄어든다."],"title":"「점심시간 운동장을 나누어 씁시다」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L02_challenge#2','kor',6,1,'u5','L02','g6_1_kor_u5_L02_challenge','lesson_challenge','K6-1-u5-C14',2,'ox','auto','중심 문장만 이어 읽어도 글 전체의 뼈대가 드러나요.',ARRAY['K6-1-u5-X13']::text[],false,'{"seq":2,"concept":"K6-1-u5-C14","difficulty":2,"kind":"ox","stem":"중심 문장만 이어 읽어도 글 전체의 뼈대가 드러나요.","answer":"O","reason_options":[{"t":"중심 문장이 문단마다 하고 싶은 말을 대표하기 때문에","correct":true},{"t":"뒷받침 문장에만 글의 뜻이 담기기 때문에","mis":"K6-1-u5-X13"}],"mis":"K6-1-u5-X13","explanation":["중심 문장이 문단을 대표해요.","뒷받침 문장은 받쳐 줘요.","중심 문장으로 뼈대가 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L02_challenge#3','kor',6,1,'u5','L02','g6_1_kor_u5_L02_challenge','lesson_challenge','K6-1-u5-C8',3,'match','auto','이유와 그 이유를 받친 근거를 알맞게 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K6-1-u5-C8","difficulty":3,"kind":"match","stem":"이유와 그 이유를 받친 근거를 알맞게 이으세요.","pairs":[{"l":"더 안전하게 놀 수 있다","r":"부딪힐 뻔했다는 학급 설문"},{"l":"놀이를 끝까지 할 수 있다","r":"그만둔 무리를 센 관찰 기록"},{"l":"다툼이 줄어든다","r":"다툼에 대한 선생님 면담"}],"mis":"K6-1-u5-X03","explanation":["안전은 부딪힘과 이어져요.","놀이는 그만둔 무리와 이어져요.","다툼은 선생님 말씀과 이어져요."],"asset":{"type":"passage","lines":["③ 둘째, 하려던 놀이를 끝까지 할 수 있기 때문이다. 사흘 동안 세어 보니","줄넘기를 하다 공에 밀려 그만둔 무리가 하루 평균 네 무리였다.","(솔바람반(2026), 「사흘 동안의 운동장 관찰 기록」, 학급 게시판.)","④ 셋째, 다툼이 줄어들기 때문이다. 학년 선생님께 여쭈어 보니 점심시간","다툼 가운데 놀 곳을 두고 벌어지는 다툼이 가장 잦다고 하셨다.","(김○○ 선생님 면담(2026), 「점심시간 생활 지도」, 육 학년 교무실.)","⑤ 지금까지 세 가지 까닭을 살펴보았다. 요일마다 학년을 정하는 방법도","있다. 모두에게 넉넉한 점심시간이 되도록 운동장을 나누어 쓰자."],"title":"「점심시간 운동장을 나누어 씁시다」 — 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L02_challenge#4','kor',6,1,'u5','L02','g6_1_kor_u5_L02_challenge','lesson_challenge','K6-1-u5-C10',3,'error','auto','이 글을 읽고 근거를 판단한 말이에요. 알맞지 않은 말은 누구의 것인가요?',ARRAY['K6-1-u5-X15','K6-1-u5-X14','K6-1-u5-X23']::text[],false,'{"seq":4,"concept":"K6-1-u5-C10","difficulty":3,"kind":"error","stem":"이 글을 읽고 근거를 판단한 말이에요. 알맞지 않은 말은 누구의 것인가요?","options":[{"t":"슬아 — 「근거가 길게 적혀 있으니 타당한 근거야.」","correct":true,"mis_target":"K6-1-u5-X15"},{"t":"규리 — 「설문이 「부딪힐 뻔했는지」를 물었으니 안전 이유를 받쳐 줘.」","mis":"K6-1-u5-X14"},{"t":"민찬 — 「직접 센 기록이라 누구나 다시 세어 확인할 수 있어.」","mis":"K6-1-u5-X23"}],"explanation":["규리는 이유와 이어지는지 보았어요.","민찬은 확인할 수 있는지 보았어요.","길이는 타당성의 기준이 아니에요."],"asset":{"type":"passage","lines":["① 점심시간이면 운동장은 공놀이와 달리기와 줄넘기가 한꺼번에 벌어져","서로 부딪힐까 봐 마음을 놓지 못한다. 점심시간 운동장을 학년에 따라","나누어 써야 한다. 지금부터 그렇게 해야 하는 까닭을 살펴보자.","② 첫째, 나누어 쓰면 더 안전하게 놀 수 있기 때문이다. 우리 반 스물다섯","명 가운데 열여덟 명이 다른 사람과 부딪힐 뻔한 적이 있다고 답했다.","(솔바람반(2026), 「점심시간 운동장 이용 설문」, 학급 게시판.)","넉넉한 곳에서 놀면 뒤를 살피느라 멈칫할 일이 줄어든다."],"title":"「점심시간 운동장을 나누어 씁시다」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L02_challenge#5','kor',6,1,'u5','L02','g6_1_kor_u5_L02_challenge','lesson_challenge','K6-1-u5-C9',3,'mc','auto','이유가 타당한지 묻는 두 물음으로 바르게 짝지은 것은 어느 것인가요?',ARRAY['K6-1-u5-X15','K6-1-u5-X03','K6-1-u5-X08']::text[],false,'{"seq":5,"concept":"K6-1-u5-C9","difficulty":3,"kind":"mc","stem":"이유가 타당한지 묻는 두 물음으로 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"주장과 이유가 관련 있는가? · 이유가 주장을 잘 설명하는가?","correct":true},{"t":"이유가 길게 쓰였는가? · 이유가 맨 처음에 나오는가?","mis":"K6-1-u5-X15"},{"t":"이유에 숫자가 있는가? · 이유에 출처가 있는가?","mis":"K6-1-u5-X03"},{"t":"이유가 옳은 말인가? · 이유가 재미있는가?","mis":"K6-1-u5-X08"}],"explanation":["길이와 차례는 기준이 아니에요.","수와 출처는 근거를 볼 때예요.","옳은 말이어도 주장과 이어져야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L02_challenge#6','kor',6,1,'u5','L02','g6_1_kor_u5_L02_challenge','lesson_challenge','K6-1-u5-C13',3,'mc','auto','결론에 「요일마다 학년을 정하는 방법도 있다」를 넣은 것은 어떤 내용을 담은 것인가요?',ARRAY['K6-1-u5-X11','K6-1-u5-X10','K6-1-u5-X03']::text[],false,'{"seq":6,"concept":"K6-1-u5-C13","difficulty":3,"kind":"mc","stem":"결론에 「요일마다 학년을 정하는 방법도 있다」를 넣은 것은 어떤 내용을 담은 것인가요?","options":[{"t":"주장이 이루어질 방법과 앞으로를 내다보는 내용","correct":true},{"t":"처음 꺼내는 새로운 근거","mis":"K6-1-u5-X11"},{"t":"문제를 처음 제기하는 내용","mis":"K6-1-u5-X10"},{"t":"이유를 받치는 설문 결과","mis":"K6-1-u5-X03"}],"explanation":["새 근거가 아니에요.","문제 제기는 서론이에요.","결론은 전망을 담기도 해요."],"asset":{"type":"passage","lines":["③ 둘째, 하려던 놀이를 끝까지 할 수 있기 때문이다. 사흘 동안 세어 보니","줄넘기를 하다 공에 밀려 그만둔 무리가 하루 평균 네 무리였다.","(솔바람반(2026), 「사흘 동안의 운동장 관찰 기록」, 학급 게시판.)","④ 셋째, 다툼이 줄어들기 때문이다. 학년 선생님께 여쭈어 보니 점심시간","다툼 가운데 놀 곳을 두고 벌어지는 다툼이 가장 잦다고 하셨다.","(김○○ 선생님 면담(2026), 「점심시간 생활 지도」, 육 학년 교무실.)","⑤ 지금까지 세 가지 까닭을 살펴보았다. 요일마다 학년을 정하는 방법도","있다. 모두에게 넉넉한 점심시간이 되도록 운동장을 나누어 쓰자."],"title":"「점심시간 운동장을 나누어 씁시다」 — 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L02_challenge#7','kor',6,1,'u5','L02','g6_1_kor_u5_L02_challenge','lesson_challenge','K6-1-u5-C14',3,'mc','auto','④문단의 「학년 선생님께 여쭈어 보니 … 가장 잦다고 하셨다.」가 중심 문장이 아닌 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X13','K6-1-u5-X23','K6-1-u5-X03']::text[],false,'{"seq":7,"concept":"K6-1-u5-C14","difficulty":3,"kind":"mc","stem":"④문단의 「학년 선생님께 여쭈어 보니 … 가장 잦다고 하셨다.」가 중심 문장이 아닌 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"「셋째, 다툼이 줄어들기 때문이다」를 받쳐 주는 면담 내용이기 때문이다","correct":true},{"t":"문단에서 가장 긴 문장이기 때문이다","mis":"K6-1-u5-X13"},{"t":"선생님 말씀은 근거가 될 수 없기 때문이다","mis":"K6-1-u5-X23"},{"t":"출처가 붙어 있어 주장이기 때문이다","mis":"K6-1-u5-X03"}],"explanation":["길이로 정하지 않아요.","면담도 근거가 돼요.","받쳐 주는 문장이라 뒷받침 문장이에요."],"asset":{"type":"passage","lines":["③ 둘째, 하려던 놀이를 끝까지 할 수 있기 때문이다. 사흘 동안 세어 보니","줄넘기를 하다 공에 밀려 그만둔 무리가 하루 평균 네 무리였다.","(솔바람반(2026), 「사흘 동안의 운동장 관찰 기록」, 학급 게시판.)","④ 셋째, 다툼이 줄어들기 때문이다. 학년 선생님께 여쭈어 보니 점심시간","다툼 가운데 놀 곳을 두고 벌어지는 다툼이 가장 잦다고 하셨다.","(김○○ 선생님 면담(2026), 「점심시간 생활 지도」, 육 학년 교무실.)","⑤ 지금까지 세 가지 까닭을 살펴보았다. 요일마다 학년을 정하는 방법도","있다. 모두에게 넉넉한 점심시간이 되도록 운동장을 나누어 쓰자."],"title":"「점심시간 운동장을 나누어 씁시다」 — 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L02_challenge#8','kor',6,1,'u5','L02','g6_1_kor_u5_L02_challenge','lesson_challenge','K6-1-u5-C15',4,'mc','auto','「출처가 붙어 있다고 다 타당한 근거는 아니다」를 가장 잘 보여 주는 예는 어느 것인가요?',ARRAY['K6-1-u5-X14','K6-1-u5-X47']::text[],false,'{"seq":8,"concept":"K6-1-u5-C15","difficulty":4,"kind":"mc","stem":"「출처가 붙어 있다고 다 타당한 근거는 아니다」를 가장 잘 보여 주는 예는 어느 것인가요?","options":[{"t":"「운동장을 나누자」는 글에 출처를 밝힌 「급식 잔반 설문」을 근거로 붙였다","correct":true},{"t":"「부딪힐 뻔한 적이 있다」는 설문을 안전 이유에 붙였다","mis":"K6-1-u5-X14"},{"t":"선생님 면담을 다툼 이유에 붙였다","mis":"K6-1-u5-X14"},{"t":"출처 없이 「다들 그렇대」라고 썼다","mis":"K6-1-u5-X47"}],"explanation":["이것은 이유와 이어진 근거예요.","이것도 이어진 근거예요.","출처가 있어도 이유와 이어지지 않으면 힘이 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L02_challenge#9','kor',6,1,'u5','L02','g6_1_kor_u5_L02_challenge','lesson_challenge','K6-1-u5-C10',4,'essay','teacher','③문단의 근거가 이유를 잘 뒷받침하는지 판단하고, 그렇게 판단한 까닭을 두 가지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u5-C10","difficulty":4,"kind":"essay","stem":"③문단의 근거가 이유를 잘 뒷받침하는지 판단하고, 그렇게 판단한 까닭을 두 가지 쓰세요.","answer_guide":{"answer":"예: 잘 뒷받침한다. 첫째, 이유는 「하려던 놀이를 끝까지 할 수 있다」인데 근거가 「놀이를 그만둔 무리 수」를 세어서 이유와 바로 이어진다. 둘째, 사흘 동안 직접 센 기록이고 언제 · 누가 · 어디에 실었는지 출처가 밝혀져 있어 누구나 다시 확인할 수 있다.","scoring_points":["뒷받침하는지 판단을 밝혔는가","이유와 근거의 관련을 까닭으로 썼는가","출처나 확인 가능성을 까닭으로 썼는가"]},"explanation":["판단을 먼저 밝혀요.","이유와 근거를 견줘요.","출처를 살펴요."],"asset":{"type":"passage","lines":["③ 둘째, 하려던 놀이를 끝까지 할 수 있기 때문이다. 사흘 동안 세어 보니","줄넘기를 하다 공에 밀려 그만둔 무리가 하루 평균 네 무리였다.","(솔바람반(2026), 「사흘 동안의 운동장 관찰 기록」, 학급 게시판.)","④ 셋째, 다툼이 줄어들기 때문이다. 학년 선생님께 여쭈어 보니 점심시간","다툼 가운데 놀 곳을 두고 벌어지는 다툼이 가장 잦다고 하셨다.","(김○○ 선생님 면담(2026), 「점심시간 생활 지도」, 육 학년 교무실.)","⑤ 지금까지 세 가지 까닭을 살펴보았다. 요일마다 학년을 정하는 방법도","있다. 모두에게 넉넉한 점심시간이 되도록 운동장을 나누어 쓰자."],"title":"「점심시간 운동장을 나누어 씁시다」 — 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L02_challenge#10','kor',6,1,'u5','L02','g6_1_kor_u5_L02_challenge','lesson_challenge','K6-1-u5-C12',4,'essay','teacher','이 글의 짜임을 서론 · 본론 · 결론으로 나누고, 각 부분이 어떤 일을 하는지 문단 번호를 들어 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u5-C12","difficulty":4,"kind":"essay","stem":"이 글의 짜임을 서론 · 본론 · 결론으로 나누고, 각 부분이 어떤 일을 하는지 문단 번호를 들어 설명하세요.","answer_guide":{"answer":"예: 서론은 ①문단으로, 운동장이 붐비는 문제를 꺼내고 「운동장을 학년에 따라 나누어 써야 한다」는 주장을 밝혔다. 본론은 ②~④문단으로, 안전 · 놀이 · 다툼의 세 이유마다 설문 · 관찰 기록 · 면담의 근거를 붙여 주장을 펼쳤다. 결론은 ⑤문단으로, 세 까닭을 모아 말하고 주장을 다시 강조했다.","scoring_points":["서론과 그 일을 썼는가","본론과 이유 · 근거를 썼는가","결론과 요약 · 강조를 썼는가"]},"explanation":["문단 번호를 나눠요.","각 부분이 하는 일을 써요.","이유와 근거도 짚어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L04_basic#1','kor',6,1,'u5','L04','g6_1_kor_u5_L04_basic','lesson_basic','K6-1-u5-C17',1,'mc','auto','「인용」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X16','K6-1-u5-X17','K6-1-u5-X10']::text[],false,'{"seq":1,"concept":"K6-1-u5-C17","difficulty":1,"kind":"mc","stem":"「인용」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"다른 사람의 말이나 글, 자료를 가져와 자신의 글에서 쓰는 것","correct":true},{"t":"내 생각을 처음으로 지어내 쓰는 것","mis":"K6-1-u5-X16"},{"t":"남의 글을 조각조각 이어 붙여 내 글인 척하는 것","mis":"K6-1-u5-X17"},{"t":"글의 마지막에 주장을 다시 쓰는 것","mis":"K6-1-u5-X10"}],"explanation":["내가 지어낸 것은 인용이 아니에요.","그것은 표절이에요.","가져와 쓰는 것이 인용이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L04_basic#2','kor',6,1,'u5','L04','g6_1_kor_u5_L04_basic','lesson_basic','K6-1-u5-C20',1,'match','auto','낱말과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K6-1-u5-C20","difficulty":1,"kind":"match","stem":"낱말과 뜻을 알맞게 이으세요.","pairs":[{"l":"저작물","r":"생각이나 감정을 표현한 창작물"},{"l":"저작자","r":"그 창작물을 만든 사람"},{"l":"저작권","r":"만든 사람이 가지는 권리"}],"mis":"K6-1-u5-X20","explanation":["「물」은 만든 것이에요.","「자」는 사람이에요.","「권」은 권리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L04_basic#3','kor',6,1,'u5','L04','g6_1_kor_u5_L04_basic','lesson_basic','K6-1-u5-C21',1,'mc','auto','출처에 들어가야 할 네 가지로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X21']::text[],false,'{"seq":3,"concept":"K6-1-u5-C21","difficulty":1,"kind":"mc","stem":"출처에 들어가야 할 네 가지로 알맞은 것은 어느 것인가요?","options":[{"t":"만든 사람 · 만든 시기 · 자료의 이름 · 실린 곳","correct":true},{"t":"만든 사람 · 자료의 길이 · 글씨체 · 쪽수","mis":"K6-1-u5-X21"},{"t":"자료의 이름 · 내 이름 · 읽은 날 · 느낌","mis":"K6-1-u5-X21"},{"t":"만든 사람 · 자료의 이름만","mis":"K6-1-u5-X21"}],"explanation":["길이나 글씨체는 아니에요.","내 느낌은 넣지 않아요.","네 가지가 다 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L04_basic#4','kor',6,1,'u5','L04','g6_1_kor_u5_L04_basic','lesson_basic','K6-1-u5-C16',1,'ox','auto','내가 직접 겪은 일을 쓴 문장에도 반드시 출처를 밝혀야 해요.',ARRAY['K6-1-u5-X16']::text[],false,'{"seq":4,"concept":"K6-1-u5-C16","difficulty":1,"kind":"ox","stem":"내가 직접 겪은 일을 쓴 문장에도 반드시 출처를 밝혀야 해요.","answer":"X","reason_options":[{"t":"출처는 내가 만들지 않은 것을 가져다 쓸 때 밝히는 것이기 때문에","correct":true},{"t":"내가 쓴 문장은 모두 인용이기 때문에","mis":"K6-1-u5-X16"}],"mis":"K6-1-u5-X16","explanation":["내 경험은 내가 만든 것이에요.","남이 만든 것에 출처를 붙여요.","무엇을 가져왔는지 갈라 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L04_basic#5','kor',6,1,'u5','L04','g6_1_kor_u5_L04_basic','lesson_basic','K6-1-u5-C16',2,'mc','auto','다음 가운데 출처를 밝혀야 하는 것은 어느 것인가요?',ARRAY['K6-1-u5-X16']::text[],false,'{"seq":5,"concept":"K6-1-u5-C16","difficulty":2,"kind":"mc","stem":"다음 가운데 출처를 밝혀야 하는 것은 어느 것인가요?","options":[{"t":"누리집에서 내려받은 표","correct":true},{"t":"내가 세운 주장","mis":"K6-1-u5-X16"},{"t":"내가 어제 직접 겪은 일","mis":"K6-1-u5-X16"},{"t":"내가 떠올린 이유","mis":"K6-1-u5-X16"}],"explanation":["주장은 내 생각이에요.","내 경험이에요.","남이 만든 표는 출처를 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L04_basic#6','kor',6,1,'u5','L04','g6_1_kor_u5_L04_basic','lesson_basic','K6-1-u5-C18',2,'mc','auto','출처를 밝혀야 하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X25','K6-1-u5-X18']::text[],false,'{"seq":6,"concept":"K6-1-u5-C18","difficulty":2,"kind":"mc","stem":"출처를 밝혀야 하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"만든 사람의 권리를 지키고 어디까지가 내 말인지 알리기 위해","correct":true},{"t":"글을 길어 보이게 하려고","mis":"K6-1-u5-X25"},{"t":"하고 싶을 때만 지키는 예의라서","mis":"K6-1-u5-X18"},{"t":"읽는 사람을 헷갈리게 하려고","mis":"K6-1-u5-X18"}],"explanation":["길이를 늘리려는 것이 아니에요.","예의가 아니라 약속이에요.","권리를 지키고 내 말과 남의 말을 갈라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L04_basic#7','kor',6,1,'u5','L04','g6_1_kor_u5_L04_basic','lesson_basic','K6-1-u5-C21',2,'mc','auto','「솔바람반, 「우리 반 독서 시간 조사」, 학급 게시판.」에서 빠진 것은 어느 것인가요?',ARRAY['K6-1-u5-X21']::text[],false,'{"seq":7,"concept":"K6-1-u5-C21","difficulty":2,"kind":"mc","stem":"「솔바람반, 「우리 반 독서 시간 조사」, 학급 게시판.」에서 빠진 것은 어느 것인가요?","options":[{"t":"자료를 만든 시기","correct":true},{"t":"인용한 자료의 이름","mis":"K6-1-u5-X21"},{"t":"자료가 실린 곳","mis":"K6-1-u5-X21"},{"t":"자료를 만든 사람","mis":"K6-1-u5-X21"}],"explanation":["이름은 적혀 있어요.","실린 곳도 적혀 있어요.","언제 만든 자료인지 빠졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L04_basic#8','kor',6,1,'u5','L04','g6_1_kor_u5_L04_basic','lesson_basic','K6-1-u5-C19',2,'ox','auto','출처만 정확히 적으면 원래 뜻을 내 주장에 맞게 조금 세게 바꿔도 돼요.',ARRAY['K6-1-u5-X19']::text[],false,'{"seq":8,"concept":"K6-1-u5-C19","difficulty":2,"kind":"ox","stem":"출처만 정확히 적으면 원래 뜻을 내 주장에 맞게 조금 세게 바꿔도 돼요.","answer":"X","reason_options":[{"t":"인용에는 출처를 밝히는 일과 뜻을 비틀지 않는 일이 함께 붙기 때문에","correct":true},{"t":"출처가 있으면 뜻은 어떻게 써도 되기 때문에","mis":"K6-1-u5-X19"}],"mis":"K6-1-u5-X19","explanation":["출처만으로는 부족해요.","뜻을 그대로 살려 옮겨요.","둘 다 지켜야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L04_basic#9','kor',6,1,'u5','L04','g6_1_kor_u5_L04_basic','lesson_basic','K6-1-u5-C21',2,'match','auto','출처의 각 부분과 그것이 무엇인지 알맞게 이으세요. — ○○초등학교 도서관(2026), 「사월 대출 통계」, 도서관 게시판.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u5-C21","difficulty":2,"kind":"match","stem":"출처의 각 부분과 그것이 무엇인지 알맞게 이으세요. — ○○초등학교 도서관(2026), 「사월 대출 통계」, 도서관 게시판.","pairs":[{"l":"○○초등학교 도서관","r":"만든 사람이나 기관"},{"l":"2026","r":"만든 시기"},{"l":"「사월 대출 통계」","r":"인용한 자료의 이름"},{"l":"도서관 게시판","r":"자료가 실린 곳"}],"mis":"K6-1-u5-X21","explanation":["맨 앞은 만든 쪽이에요.","괄호 안은 때예요.","낫표 안은 이름, 끝은 실린 곳이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L04_basic#10','kor',6,1,'u5','L04','g6_1_kor_u5_L04_basic','lesson_basic','K6-1-u5-C24',3,'mc','auto','자료를 다섯 개 붙이고 내 문장은 두 줄뿐인 글의 문제점은 어느 것인가요?',ARRAY['K6-1-u5-X24','K6-1-u5-X14']::text[],false,'{"seq":10,"concept":"K6-1-u5-C24","difficulty":3,"kind":"mc","stem":"자료를 다섯 개 붙이고 내 문장은 두 줄뿐인 글의 문제점은 어느 것인가요?","options":[{"t":"읽고 나면 글쓴이가 무슨 생각인지 남지 않는다","correct":true},{"t":"자료가 많아 저절로 설득력이 커진다","mis":"K6-1-u5-X24"},{"t":"출처를 모두 밝혔으니 문제가 없다","mis":"K6-1-u5-X14"},{"t":"내 문장이 짧아 더 깔끔하다","mis":"K6-1-u5-X24"}],"explanation":["많다고 힘이 커지지 않아요.","출처만으로는 모자라요.","글에 담을 것은 내 생각이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L04_challenge#1','kor',6,1,'u5','L04','g6_1_kor_u5_L04_challenge','lesson_challenge','K6-1-u5-C17',2,'mc','auto','다음 가운데 표절에 해당하는 것은 어느 것인가요?',ARRAY['K6-1-u5-X17','K6-1-u5-X16','K6-1-u5-X19']::text[],false,'{"seq":1,"concept":"K6-1-u5-C17","difficulty":2,"kind":"mc","stem":"다음 가운데 표절에 해당하는 것은 어느 것인가요?","options":[{"t":"여러 글에서 한 문장씩 가져와 이어 붙이고 내 글로 냈다","correct":true},{"t":"설문 결과를 가져오며 출처를 밝혔다","mis":"K6-1-u5-X17"},{"t":"내가 겪은 일을 내 말로 썼다","mis":"K6-1-u5-X16"},{"t":"선생님 말씀을 뜻 그대로 옮기고 출처를 붙였다","mis":"K6-1-u5-X19"}],"explanation":["출처를 밝힌 인용이에요.","내 경험은 표절이 아니에요.","조각 이어 붙이기도 표절이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L04_challenge#2','kor',6,1,'u5','L04','g6_1_kor_u5_L04_challenge','lesson_challenge','K6-1-u5-C20',2,'ox','auto','내가 쓴 주장하는 글도 저작물이고, 나도 그 글의 저작자예요.',ARRAY['K6-1-u5-X20']::text[],false,'{"seq":2,"concept":"K6-1-u5-C20","difficulty":2,"kind":"ox","stem":"내가 쓴 주장하는 글도 저작물이고, 나도 그 글의 저작자예요.","answer":"O","reason_options":[{"t":"내 생각을 표현한 창작물이기 때문에","correct":true},{"t":"책으로 나온 글만 저작물이기 때문에","mis":"K6-1-u5-X20"}],"mis":"K6-1-u5-X20","explanation":["글은 생각을 표현한 거예요.","책이 아니어도 저작물이에요.","나도 저작자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L04_challenge#3','kor',6,1,'u5','L04','g6_1_kor_u5_L04_challenge','lesson_challenge','K6-1-u5-C22',3,'mc','auto','두 학생이 같은 자료의 출처를 차례만 다르게 적었어요. 어떻게 보아야 하나요?',ARRAY['K6-1-u5-X22']::text[],false,'{"seq":3,"concept":"K6-1-u5-C22","difficulty":3,"kind":"mc","stem":"두 학생이 같은 자료의 출처를 차례만 다르게 적었어요. 어떻게 보아야 하나요?","options":[{"t":"네 가지가 빠지지 않았다면 둘 다 바르게 적은 것이다","correct":true},{"t":"정해진 차례가 하나뿐이라 한 사람은 틀렸다","mis":"K6-1-u5-X22"},{"t":"차례가 다르면 다른 자료가 된다","mis":"K6-1-u5-X22"},{"t":"부호를 다르게 쓰면 출처가 아니다","mis":"K6-1-u5-X22"}],"explanation":["차례는 조금씩 다를 수 있어요.","같은 자료예요.","네 가지가 빠지지 않는 것이 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L04_challenge#4','kor',6,1,'u5','L04','g6_1_kor_u5_L04_challenge','lesson_challenge','K6-1-u5-C21',3,'mc','auto','빠진 것이 「자료가 실린 곳」인 출처는 어느 것인가요?',ARRAY['K6-1-u5-X21']::text[],false,'{"seq":4,"concept":"K6-1-u5-C21","difficulty":3,"kind":"mc","stem":"빠진 것이 「자료가 실린 곳」인 출처는 어느 것인가요?","options":[{"t":"ㄴ","correct":true},{"t":"ㄱ","mis":"K6-1-u5-X21"},{"t":"ㄷ","mis":"K6-1-u5-X21"},{"t":"ㄹ","mis":"K6-1-u5-X21"}],"explanation":["ㄱ은 만든 시기가 없어요.","ㄷ은 만든 사람이 없어요.","ㄴ은 어디에 실렸는지가 없어요."],"asset":{"type":"passage","lines":["ㄱ. 솔바람반, 「우리 반 독서 시간 조사」, 학급 게시판.","ㄴ. 솔바람반(2026), 「우리 반 독서 시간 조사」.","ㄷ. (2026), 「우리 반 독서 시간 조사」, 학급 게시판.","ㄹ. 솔바람반(2026), 학급 게시판."],"title":"무엇인가 빠진 출처 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L04_challenge#5','kor',6,1,'u5','L04','g6_1_kor_u5_L04_challenge','lesson_challenge','K6-1-u5-C23',3,'mc','auto','근거로 쓰기 전에 한 번 더 확인해야 하는 자료는 어느 것인가요?',ARRAY['K6-1-u5-X23']::text[],false,'{"seq":5,"concept":"K6-1-u5-C23","difficulty":3,"kind":"mc","stem":"근거로 쓰기 전에 한 번 더 확인해야 하는 자료는 어느 것인가요?","options":[{"t":"누가 썼는지 알 수 없고 언제 올라왔는지도 모르는 글","correct":true},{"t":"학교가 낸 기록","mis":"K6-1-u5-X23"},{"t":"신문에 실린 기사","mis":"K6-1-u5-X23"},{"t":"언제 · 누구에게 · 어디서 했는지 적어 둔 우리 반 설문","mis":"K6-1-u5-X23"}],"explanation":["학교 기록은 믿을 만해요.","기사도 믿을 만해요.","누가 언제 썼는지 모르면 확인할 길이 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L04_challenge#6','kor',6,1,'u5','L04','g6_1_kor_u5_L04_challenge','lesson_challenge','K6-1-u5-C19',3,'mc','auto','선생님께서 「먼 곳을 잠깐 바라보면 눈 피로에 도움이 된다」고 하셨어요. 뜻을 비틀어 옮긴 것은 어느 것인가요?',ARRAY['K6-1-u5-X19']::text[],false,'{"seq":6,"concept":"K6-1-u5-C19","difficulty":3,"kind":"mc","stem":"선생님께서 「먼 곳을 잠깐 바라보면 눈 피로에 도움이 된다」고 하셨어요. 뜻을 비틀어 옮긴 것은 어느 것인가요?","options":[{"t":"먼 곳만 바라보면 눈이 나빠지지 않는다고 하셨다","correct":true},{"t":"먼 곳을 잠깐 바라보면 눈 피로에 도움이 된다고 하셨다","mis":"K6-1-u5-X19"},{"t":"눈이 피로할 때 먼 곳을 잠깐 보는 것이 좋다고 하셨다","mis":"K6-1-u5-X19"},{"t":"눈이 피로하면 먼 곳을 잠깐 바라보라고 하셨다","mis":"K6-1-u5-X19"}],"explanation":["뜻을 그대로 옮겼어요.","같은 뜻이에요.","「도움이 된다」를 「나빠지지 않는다」로 과장했어요."],"asset":{"type":"passage","lines":["ㄱ. 보건 선생님께 여쭈어 보니, 눈이 피로할 때에는 먼 곳을 잠깐","바라보는 것이 도움이 된다고 하셨다.","(박○○ 보건 교사 면담(2026), 「눈 건강 상담」, 보건실.)","ㄴ. 학교 도서관 대출 기록을 보니, 지난달 가장 많이 빌려 간 갈래는 이야기책이었다.","(○○초등학교 도서관(2026), 「사월 대출 통계」, 도서관 게시판.)"],"title":"출처를 밝혀 쓴 두 문장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L04_challenge#7','kor',6,1,'u5','L04','g6_1_kor_u5_L04_challenge','lesson_challenge','K6-1-u5-C25',3,'error','auto','글을 다 쓰고 스스로 물어본 말이에요. 쓰기 윤리를 점검하는 물음이 아닌 것은 누구의 것인가요?',ARRAY['K6-1-u5-X25']::text[],false,'{"seq":7,"concept":"K6-1-u5-C25","difficulty":3,"kind":"error","stem":"글을 다 쓰고 스스로 물어본 말이에요. 쓰기 윤리를 점검하는 물음이 아닌 것은 누구의 것인가요?","options":[{"t":"예찬 — 「글을 다른 친구보다 길게 썼는가?」","correct":true,"mis_target":"K6-1-u5-X25"},{"t":"규리 — 「확인되지 않은 사실을 쓰지는 않았는가?」","mis":"K6-1-u5-X25"},{"t":"슬아 — 「다른 사람을 헐뜯는 말을 쓰지는 않았는가?」","mis":"K6-1-u5-X25"}],"explanation":["규리는 참인지 물었어요.","슬아는 남을 다치게 하지 않았는지 물었어요.","길이는 쓰기 윤리와 관계없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L04_challenge#8','kor',6,1,'u5','L04','g6_1_kor_u5_L04_challenge','lesson_challenge','K6-1-u5-C22',4,'mc','auto','누리집에서 찾은 그래프를 내 글에 넣으려고 해요. 가장 알맞게 한 것은 어느 것인가요?',ARRAY['K6-1-u5-X16','K6-1-u5-X21','K6-1-u5-X17']::text[],false,'{"seq":8,"concept":"K6-1-u5-C22","difficulty":4,"kind":"mc","stem":"누리집에서 찾은 그래프를 내 글에 넣으려고 해요. 가장 알맞게 한 것은 어느 것인가요?","options":[{"t":"그래프의 제목과 만든 곳을 포함해 출처의 네 가지를 함께 적었다","correct":true},{"t":"그래프 모양만 내 손으로 다시 그려 넣고 출처는 뺐다","mis":"K6-1-u5-X16"},{"t":"「누리집에서 찾음」이라고만 적었다","mis":"K6-1-u5-X21"},{"t":"그래프를 그대로 붙이고 내 글이라고 했다","mis":"K6-1-u5-X17"}],"explanation":["다시 그려도 남이 만든 자료예요.","어느 누리집인지 확인할 수 없어요.","표 · 그래프는 제목과 만든 곳도 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L04_challenge#9','kor',6,1,'u5','L04','g6_1_kor_u5_L04_challenge','lesson_challenge','K6-1-u5-C21',4,'essay','teacher','「네 가지가 다 있어야 읽는 사람이 직접 찾아가 확인할 수 있다」는 말을, 출처에서 하나가 빠졌을 때 생기는 일을 예로 들어 설명하세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u5-C21","difficulty":4,"kind":"essay","stem":"「네 가지가 다 있어야 읽는 사람이 직접 찾아가 확인할 수 있다」는 말을, 출처에서 하나가 빠졌을 때 생기는 일을 예로 들어 설명하세요.","answer_guide":{"answer":"예: 출처에서 만든 시기가 빠지면 읽는 사람은 그 조사를 언제 했는지 알 수 없어, 같은 반이 여러 번 한 조사 가운데 어느 것인지 찾을 수 없다. 실린 곳이 빠지면 어디에 가서 확인해야 할지 모른다. 하나라도 빠지면 「어딘가에서 봤다」와 다르지 않게 되므로 네 가지를 모두 적어야 한다.","scoring_points":["네 가지 가운데 하나가 빠진 예를 들었는가","확인할 수 없게 되는 까닭을 썼는가","네 가지를 모두 적어야 함을 정리했는가"]},"explanation":["빠진 것을 하나 골라요.","읽는 사람 쪽에서 생각해요.","네 가지가 왜 필요한지 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L04_challenge#10','kor',6,1,'u5','L04','g6_1_kor_u5_L04_challenge','lesson_challenge','K6-1-u5-C24',4,'essay','teacher','앞으로 쓸 주장하는 글에 넣을 자료 하나를 정하고, 출처를 네 가지를 갖추어 적은 뒤 그 자료가 어떤 이유를 받쳐 주는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u5-C24","difficulty":4,"kind":"essay","stem":"앞으로 쓸 주장하는 글에 넣을 자료 하나를 정하고, 출처를 네 가지를 갖추어 적은 뒤 그 자료가 어떤 이유를 받쳐 주는지 쓰세요.","answer_guide":{"answer":"예: 자료 — 우리 반에서 한 「아침 독서 시간 설문」. 출처 — 새솔반(2026), 「아침 독서 시간 설문」, 학급 게시판. 이 자료는 「아침 독서 시간을 늘리면 책 읽는 습관이 생기기 때문이다」라는 이유를 받쳐 준다. 자료를 여러 개 붙이기보다 이유에 꼭 맞는 이 자료 하나를 쓰겠다.","scoring_points":["내가 쓸 자료를 정했는가","출처의 네 가지를 갖추어 적었는가","그 자료가 받치는 이유를 썼는가"]},"explanation":["직접 만들 수 있는 자료도 좋아요.","네 칸을 빠짐없이 적어요.","어떤 이유를 받치는지 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L06_basic#1','kor',6,1,'u5','L06','g6_1_kor_u5_L06_basic','lesson_basic','K6-1-u5-C26',1,'match','auto','발표 전에 정할 것과 그 예를 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"K6-1-u5-C26","difficulty":1,"kind":"match","stem":"발표 전에 정할 것과 그 예를 알맞게 이으세요.","pairs":[{"l":"주제","r":"비 오는 날 복도에 흩어지는 우산"},{"l":"목적","r":"우산을 우산꽂이에 모으자고 설득하기"},{"l":"대상","r":"같은 층을 쓰는 다른 반 친구들"}],"mis":"K6-1-u5-X26","explanation":["주제는 다룰 문제예요.","목적은 이루고 싶은 것이에요.","대상은 들을 사람이에요."],"asset":{"type":"passage","lines":["주제 — 비 오는 날 복도에 흩어지는 우산","목적 — 우산을 우산꽂이에 모으자고 설득하고 싶다","대상 — 같은 층을 쓰는 다른 반 친구들","주장 — 비 오는 날 우산은 우산꽂이에 꽂읍시다.","이유 — 첫째, 걸려 넘어질 수 있다 / 둘째, 우산이 섞여 잃어버린다","　　　 셋째, 물이 흘러 바닥이 미끄러워진다"],"title":"우산 발표 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L06_basic#2','kor',6,1,'u5','L06','g6_1_kor_u5_L06_basic','lesson_basic','K6-1-u5-C27',1,'mc','auto','뜻이 한 가지로 뚜렷하게 읽히는 주장은 어느 것인가요?',ARRAY['K6-1-u5-X27']::text[],false,'{"seq":2,"concept":"K6-1-u5-C27","difficulty":1,"kind":"mc","stem":"뜻이 한 가지로 뚜렷하게 읽히는 주장은 어느 것인가요?","options":[{"t":"비 오는 날 우산은 우산꽂이에 꽂읍시다","correct":true},{"t":"우산을 잘 관리합시다","mis":"K6-1-u5-X27"},{"t":"복도를 더 좋게 만듭시다","mis":"K6-1-u5-X27"},{"t":"우리 모두 노력합시다","mis":"K6-1-u5-X27"}],"explanation":["무엇을 하자는지 흐려요.","사람마다 다르게 읽어요.","무엇을 · 어디에 · 언제가 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L06_basic#3','kor',6,1,'u5','L06','g6_1_kor_u5_L06_basic','lesson_basic','K6-1-u5-C30',1,'ox','auto','「나는 어제 그렇게 느꼈다」는 진심이라면 근거가 될 수 있어요.',ARRAY['K6-1-u5-X09']::text[],false,'{"seq":3,"concept":"K6-1-u5-C30","difficulty":1,"kind":"ox","stem":"「나는 어제 그렇게 느꼈다」는 진심이라면 근거가 될 수 있어요.","answer":"X","reason_options":[{"t":"다른 사람이 찾아가 확인할 수 있는 객관적인 자료가 아니기 때문에","correct":true},{"t":"진심으로 느낀 것은 모두 객관적이기 때문에","mis":"K6-1-u5-X09"}],"mis":"K6-1-u5-X09","explanation":["느낌은 내 안에 있어요.","남이 확인할 수 없어요.","확인할 수 있어야 근거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L06_basic#4','kor',6,1,'u5','L06','g6_1_kor_u5_L06_basic','lesson_basic','K6-1-u5-C28',1,'mc','auto','「우산을 우산꽂이에 꽂자」의 이유로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X08']::text[],false,'{"seq":4,"concept":"K6-1-u5-C28","difficulty":1,"kind":"mc","stem":"「우산을 우산꽂이에 꽂자」의 이유로 알맞은 것은 어느 것인가요?","options":[{"t":"복도에 놓인 우산에 걸려 넘어질 수 있기 때문입니다","correct":true},{"t":"비 오는 날에는 날씨가 흐리기 때문입니다","mis":"K6-1-u5-X08"},{"t":"가방이 무거우면 어깨가 아프기 때문입니다","mis":"K6-1-u5-X08"},{"t":"우산은 색이 여러 가지이기 때문입니다","mis":"K6-1-u5-X08"}],"explanation":["사실이어도 주장과 이어지지 않아요.","우산과 관계없어요.","주장이 이루어지면 사라지는 불편이라야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L06_basic#5','kor',6,1,'u5','L06','g6_1_kor_u5_L06_basic','lesson_basic','K6-1-u5-C29',2,'match','auto','이유와 그 이유를 받쳐 줄 근거를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-1-u5-C29","difficulty":2,"kind":"match","stem":"이유와 그 이유를 받쳐 줄 근거를 알맞게 이으세요.","pairs":[{"l":"걸려 넘어질 수 있다","r":"비 온 날 복도에 놓인 우산을 센 관찰 기록"},{"l":"우산을 잃어버린다","r":"주인을 못 찾은 우산 수를 적은 분실물 기록"},{"l":"바닥이 미끄럽다","r":"물기 있는 바닥을 조심하라는 학교 안전 안내문"}],"mis":"K6-1-u5-X03","explanation":["넘어짐은 놓인 우산 수와 이어져요.","잃어버림은 분실물 기록과 이어져요.","미끄러움은 안전 안내문과 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L06_basic#6','kor',6,1,'u5','L06','g6_1_kor_u5_L06_basic','lesson_basic','K6-1-u5-C26',2,'mc','auto','듣는 사람이 달라지면 무엇이 달라지나요?',ARRAY['K6-1-u5-X26','K6-1-u5-X08']::text[],false,'{"seq":6,"concept":"K6-1-u5-C26","difficulty":2,"kind":"mc","stem":"듣는 사람이 달라지면 무엇이 달라지나요?","options":[{"t":"고르는 근거와 말하는 방법","correct":true},{"t":"내가 세운 주장 자체","mis":"K6-1-u5-X26"},{"t":"발표하는 요일과 시각","mis":"K6-1-u5-X26"},{"t":"주장과 이유의 관계","mis":"K6-1-u5-X08"}],"explanation":["주장은 그대로예요.","시간은 관계없어요.","전하는 방법이 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L06_basic#7','kor',6,1,'u5','L06','g6_1_kor_u5_L06_basic','lesson_basic','K6-1-u5-C30',2,'mc','auto','다음 가운데 근거로 쓸 수 있는 것은 어느 것인가요?',ARRAY['K6-1-u5-X09','K6-1-u5-X23']::text[],false,'{"seq":7,"concept":"K6-1-u5-C30","difficulty":2,"kind":"mc","stem":"다음 가운데 근거로 쓸 수 있는 것은 어느 것인가요?","options":[{"t":"학교 분실물 기록에 적힌 우산의 수","correct":true},{"t":"내가 어제 아침에 느낀 기분","mis":"K6-1-u5-X09"},{"t":"아마 다들 그럴 것이라는 짐작","mis":"K6-1-u5-X09"},{"t":"친구가 그런 것 같다고 한 말","mis":"K6-1-u5-X23"}],"explanation":["기분은 확인할 수 없어요.","짐작은 자료가 아니에요.","누구나 찾아가 확인할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L06_basic#8','kor',6,1,'u5','L06','g6_1_kor_u5_L06_basic','lesson_basic','K6-1-u5-C31',2,'ox','auto','반대할 사람이 할 말을 미리 떠올려 보면 내 주장이 더 단단해져요.',ARRAY['K6-1-u5-X28']::text[],false,'{"seq":8,"concept":"K6-1-u5-C31","difficulty":2,"kind":"ox","stem":"반대할 사람이 할 말을 미리 떠올려 보면 내 주장이 더 단단해져요.","answer":"O","reason_options":[{"t":"맞는 지적을 받아들여 내용을 보탤 수 있기 때문에","correct":true},{"t":"반대하는 말은 못 들은 척해야 주장이 흔들리지 않기 때문에","mis":"K6-1-u5-X28"}],"mis":"K6-1-u5-X28","explanation":["반박을 미리 떠올려요.","맞는 말이면 받아들여요.","내 주장을 차갑게 다시 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L06_basic#9','kor',6,1,'u5','L06','g6_1_kor_u5_L06_basic','lesson_basic','K6-1-u5-C32',2,'mc','auto','정리한 주장을 소리 내어 말해 볼 때의 차례로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X10','K6-1-u5-X04']::text[],false,'{"seq":9,"concept":"K6-1-u5-C32","difficulty":2,"kind":"mc","stem":"정리한 주장을 소리 내어 말해 볼 때의 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"문제와 주장 → 이유마다 근거와 출처 → 주장을 다시 힘주어","correct":true},{"t":"근거와 출처 → 문제와 주장 → 새 근거","mis":"K6-1-u5-X10"},{"t":"주장을 다시 힘주어 → 문제 → 이유","mis":"K6-1-u5-X10"},{"t":"이유만 차례로 → 마무리 인사","mis":"K6-1-u5-X04"}],"explanation":["근거부터 말하면 무엇을 받치는지 몰라요.","결론부터 시작하지 않아요.","서론 · 본론 · 결론 차례예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L06_basic#10','kor',6,1,'u5','L06','g6_1_kor_u5_L06_basic','lesson_basic','K6-1-u5-C31',3,'mc','auto','슬아가 「우산꽂이가 하나뿐이라 다 안 들어가는데요?」라고 했을 때 가장 알맞은 대처는 어느 것인가요?',ARRAY['K6-1-u5-X28','K6-1-u5-X27','K6-1-u5-X25']::text[],false,'{"seq":10,"concept":"K6-1-u5-C31","difficulty":3,"kind":"mc","stem":"슬아가 「우산꽂이가 하나뿐이라 다 안 들어가는데요?」라고 했을 때 가장 알맞은 대처는 어느 것인가요?","options":[{"t":"맞는 말이니 「층마다 우산꽂이를 하나씩 더 두자」는 내용을 함께 넣는다","correct":true},{"t":"못 들은 척하고 발표를 이어 간다","mis":"K6-1-u5-X28"},{"t":"주장을 「우산을 잘 관리합시다」로 바꾼다","mis":"K6-1-u5-X27"},{"t":"반대하는 친구의 말을 끊는다","mis":"K6-1-u5-X25"}],"explanation":["그 자리에서 무너져요.","주장이 흐려져요.","받아들여 보태면 단단해져요."],"asset":{"type":"speech","turns":[{"who":"발표자","text":"비 오는 날 우산은 우산꽂이에 꽂읍시다. 첫째, 복도에 놓인 우산에 걸려 넘어질 수 있기 때문입니다."},{"who":"슬아","text":"우산꽂이가 하나뿐이라 다 안 들어가는데요?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L06_challenge#1','kor',6,1,'u5','L06','g6_1_kor_u5_L06_challenge','lesson_challenge','K6-1-u5-C27',2,'ox','auto','「복도를 더 좋게 만듭시다」는 사람마다 다르게 읽혀 힘을 잃는 주장이에요.',ARRAY['K6-1-u5-X27']::text[],false,'{"seq":1,"concept":"K6-1-u5-C27","difficulty":2,"kind":"ox","stem":"「복도를 더 좋게 만듭시다」는 사람마다 다르게 읽혀 힘을 잃는 주장이에요.","answer":"O","reason_options":[{"t":"청소로도 꾸미기로도 읽혀 무엇을 하면 되는지 한 가지로 읽히지 않기 때문에","correct":true},{"t":"좋은 말이니 누구나 같은 뜻으로 읽기 때문에","mis":"K6-1-u5-X27"}],"mis":"K6-1-u5-X27","explanation":["청소로 읽는 사람도 있어요.","꾸미기로 읽는 사람도 있어요.","한 가지로 읽혀야 힘이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L06_challenge#2','kor',6,1,'u5','L06','g6_1_kor_u5_L06_challenge','lesson_challenge','K6-1-u5-C29',2,'mc','auto','근거를 찾는 길과 그 예가 바르게 이어진 것은 어느 것인가요?',ARRAY['K6-1-u5-X29','K6-1-u5-X23']::text[],false,'{"seq":2,"concept":"K6-1-u5-C29","difficulty":2,"kind":"mc","stem":"근거를 찾는 길과 그 예가 바르게 이어진 것은 어느 것인가요?","options":[{"t":"여쭈어 보기 — 그 일을 잘 아는 어른께 면담을 청한다","correct":true},{"t":"직접 조사하기 — 신문 기사를 찾아 옮겨 적는다","mis":"K6-1-u5-X29"},{"t":"공공 자료 보기 — 친구의 짐작을 듣는다","mis":"K6-1-u5-X23"},{"t":"기사 · 책 찾기 — 우리 반에 설문을 한다","mis":"K6-1-u5-X29"}],"explanation":["직접 조사는 설문이나 수 세기예요.","짐작은 공공 자료가 아니에요.","설문은 직접 조사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L06_challenge#3','kor',6,1,'u5','L06','g6_1_kor_u5_L06_challenge','lesson_challenge','K6-1-u5-C28',3,'mc','auto','「우산은 우산꽂이에 꽂읍시다」의 이유를 고치려고 해요. 이유로 세울 수 있는 것은 어느 것인가요?',ARRAY['K6-1-u5-X08']::text[],false,'{"seq":3,"concept":"K6-1-u5-C28","difficulty":3,"kind":"mc","stem":"「우산은 우산꽂이에 꽂읍시다」의 이유를 고치려고 해요. 이유로 세울 수 있는 것은 어느 것인가요?","options":[{"t":"우산에서 흐른 물로 복도 바닥이 미끄러워지기 때문입니다","correct":true},{"t":"비가 오면 기분이 가라앉기 때문입니다","mis":"K6-1-u5-X08"},{"t":"우산꽂이는 값이 싸기 때문입니다","mis":"K6-1-u5-X08"},{"t":"복도는 넓기 때문입니다","mis":"K6-1-u5-X08"}],"explanation":["기분은 우산을 꽂는 일과 이어지지 않아요.","값은 주장을 설명하지 못해요.","꽂으면 사라지는 불편이라 이유가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L06_challenge#4','kor',6,1,'u5','L06','g6_1_kor_u5_L06_challenge','lesson_challenge','K6-1-u5-C30',3,'error','auto','근거를 고른 말이에요. 알맞지 않은 말은 누구의 것인가요?',ARRAY['K6-1-u5-X09','K6-1-u5-X23','K6-1-u5-X29']::text[],false,'{"seq":4,"concept":"K6-1-u5-C30","difficulty":3,"kind":"error","stem":"근거를 고른 말이에요. 알맞지 않은 말은 누구의 것인가요?","options":[{"t":"민찬 — 「다들 넘어질 뻔했을 거라는 내 짐작을 근거로 쓸래.」","correct":true,"mis_target":"K6-1-u5-X09"},{"t":"규리 — 「우리 층에서 우산에 걸린 적이 있는지 설문을 해 볼래.」","mis":"K6-1-u5-X23"},{"t":"예찬 — 「보건 선생님께 복도에서 다친 일을 여쭈어 볼래.」","mis":"K6-1-u5-X29"}],"explanation":["규리는 직접 조사를 골랐어요.","예찬은 면담을 골랐어요.","짐작은 근거가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L06_challenge#5','kor',6,1,'u5','L06','g6_1_kor_u5_L06_challenge','lesson_challenge','K6-1-u5-C10',3,'mc','auto','근거가 타당한지 묻는 세 물음 가운데 셋째 물음이 특히 까다로운 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X14','K6-1-u5-X15','K6-1-u5-X09']::text[],false,'{"seq":5,"concept":"K6-1-u5-C10","difficulty":3,"kind":"mc","stem":"근거가 타당한지 묻는 세 물음 가운데 셋째 물음이 특히 까다로운 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"진심으로 느낀 것도 객관적인 자료는 아니어서 가려내기 어렵기 때문이다","correct":true},{"t":"출처만 있으면 객관적이기 때문이다","mis":"K6-1-u5-X14"},{"t":"근거가 길수록 객관적이기 때문이다","mis":"K6-1-u5-X15"},{"t":"짐작도 객관적인 자료이기 때문이다","mis":"K6-1-u5-X09"}],"explanation":["출처가 곧 객관은 아니에요.","길이는 기준이 아니에요.","느낌과 짐작은 객관적인 자료가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L06_challenge#6','kor',6,1,'u5','L06','g6_1_kor_u5_L06_challenge','lesson_challenge','K6-1-u5-C26',3,'mc','auto','같은 주장을 낮은 학년 동생들에게 발표한다면 무엇을 바꾸는 것이 알맞은가요?',ARRAY['K6-1-u5-X27','K6-1-u5-X04','K6-1-u5-X26']::text[],false,'{"seq":6,"concept":"K6-1-u5-C26","difficulty":3,"kind":"mc","stem":"같은 주장을 낮은 학년 동생들에게 발표한다면 무엇을 바꾸는 것이 알맞은가요?","options":[{"t":"어려운 낱말을 쉽게 풀고 동생들이 겪은 일과 이어진 근거를 고른다","correct":true},{"t":"주장을 「우산을 잘 관리합시다」로 바꾼다","mis":"K6-1-u5-X27"},{"t":"근거를 빼고 주장만 크게 말한다","mis":"K6-1-u5-X04"},{"t":"같은 말과 같은 근거를 그대로 쓴다","mis":"K6-1-u5-X26"}],"explanation":["주장을 흐리면 안 돼요.","근거가 있어야 해요.","대상에 맞게 근거와 말투를 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L06_challenge#7','kor',6,1,'u5','L06','g6_1_kor_u5_L06_challenge','lesson_challenge','K6-1-u5-C31',3,'mc','auto','「반대할 사람을 미리 떠올리는 것은 내 주장을 차갑게 다시 보는 일」이라는 말의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X25','K6-1-u5-X28']::text[],false,'{"seq":7,"concept":"K6-1-u5-C31","difficulty":3,"kind":"mc","stem":"「반대할 사람을 미리 떠올리는 것은 내 주장을 차갑게 다시 보는 일」이라는 말의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"내 편이 아닌 눈으로 주장의 빈틈을 찾아본다는 뜻이다","correct":true},{"t":"반대하는 사람을 차갑게 대한다는 뜻이다","mis":"K6-1-u5-X25"},{"t":"반대 의견이 나오면 주장을 버린다는 뜻이다","mis":"K6-1-u5-X28"},{"t":"내 편만 떠올리며 쓴다는 뜻이다","mis":"K6-1-u5-X28"}],"explanation":["사람을 차갑게 대하는 게 아니에요.","버리는 것이 아니라 보태요.","내 편만 떠올리면 내 편만 설득해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L06_challenge#8','kor',6,1,'u5','L06','g6_1_kor_u5_L06_challenge','lesson_challenge','K6-1-u5-C32',4,'mc','auto','발표를 말로 먼저 해 본 뒤 스스로 확인할 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X44','K6-1-u5-X06','K6-1-u5-X25']::text[],false,'{"seq":8,"concept":"K6-1-u5-C32","difficulty":4,"kind":"mc","stem":"발표를 말로 먼저 해 본 뒤 스스로 확인할 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"주장이 뚜렷이 드러났는지, 근거의 출처를 밝혔는지","correct":true},{"t":"목소리가 다른 친구보다 컸는지","mis":"K6-1-u5-X44"},{"t":"말한 시간이 얼마나 길었는지","mis":"K6-1-u5-X06"},{"t":"어려운 낱말을 몇 개 썼는지","mis":"K6-1-u5-X25"}],"explanation":["크기가 설득을 만들지 않아요.","길이는 관계없어요.","주장과 출처를 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L06_challenge#9','kor',6,1,'u5','L06','g6_1_kor_u5_L06_challenge','lesson_challenge','K6-1-u5-C31',4,'essay','teacher','「비 오는 날 우산은 우산꽂이에 꽂읍시다」에 대해 나올 만한 반박을 하나 떠올려 쓰고, 그 반박을 받아들여 주장을 어떻게 보탤지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u5-C31","difficulty":4,"kind":"essay","stem":"「비 오는 날 우산은 우산꽂이에 꽂읍시다」에 대해 나올 만한 반박을 하나 떠올려 쓰고, 그 반박을 받아들여 주장을 어떻게 보탤지 쓰세요.","answer_guide":{"answer":"예: 반박 — 「우산꽂이에 꽂으면 내 우산을 다른 사람이 가져갈 수도 있어요.」 대처 — 그 걱정이 맞으므로 우산 손잡이에 이름표를 붙이자는 내용을 함께 넣겠다. 그러면 잃어버릴 걱정이 줄어 주장이 더 단단해진다.","scoring_points":["나올 만한 반박을 썼는가","반박을 못 들은 척하지 않고 받아들였는가","주장에 보탤 내용을 구체적으로 썼는가"]},"explanation":["반대할 사람의 마음이 되어요.","맞는 말인지 따져요.","보탤 내용을 써요."],"asset":{"type":"speech","turns":[{"who":"발표자","text":"비 오는 날 우산은 우산꽂이에 꽂읍시다. 첫째, 복도에 놓인 우산에 걸려 넘어질 수 있기 때문입니다."},{"who":"슬아","text":"우산꽂이가 하나뿐이라 다 안 들어가는데요?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L06_challenge#10','kor',6,1,'u5','L06','g6_1_kor_u5_L06_challenge','lesson_challenge','K6-1-u5-C29',4,'essay','teacher','「셋째, 물이 흘러 바닥이 미끄러워진다」는 이유를 받쳐 줄 근거를 직접 만들려고 해요. 어떤 자료를 어떻게 만들지 쓰고, 출처를 네 가지를 갖추어 적으세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u5-C29","difficulty":4,"kind":"essay","stem":"「셋째, 물이 흘러 바닥이 미끄러워진다」는 이유를 받쳐 줄 근거를 직접 만들려고 해요. 어떤 자료를 어떻게 만들지 쓰고, 출처를 네 가지를 갖추어 적으세요.","answer_guide":{"answer":"예: 비 오는 날 사흘 동안 쉬는 시간마다 복도 바닥에 물이 고인 곳의 수를 세어 기록하겠다. 출처 — 솔바람반(2026), 「비 오는 날 복도 바닥 관찰 기록」, 학급 게시판. 이렇게 하면 누구나 다시 세어 확인할 수 있는 근거가 된다.","scoring_points":["이유와 이어진 자료를 정했는가","자료를 만드는 방법을 썼는가","출처를 네 가지를 갖추어 적었는가"]},"explanation":["이유의 낱말을 잡아요.","직접 세거나 물어봐요.","출처 네 칸을 채워요."],"asset":{"type":"passage","lines":["주제 — 비 오는 날 복도에 흩어지는 우산","목적 — 우산을 우산꽂이에 모으자고 설득하고 싶다","대상 — 같은 층을 쓰는 다른 반 친구들","주장 — 비 오는 날 우산은 우산꽂이에 꽂읍시다.","이유 — 첫째, 걸려 넘어질 수 있다 / 둘째, 우산이 섞여 잃어버린다","　　　 셋째, 물이 흘러 바닥이 미끄러워진다"],"title":"우산 발표 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L08_basic#1','kor',6,1,'u5','L08','g6_1_kor_u5_L08_basic','lesson_basic','K6-1-u5-C33',1,'mc','auto','주장하는 글의 주제로 쓸 수 있는 문제는 어느 것인가요?',ARRAY['K6-1-u5-X29']::text[],false,'{"seq":1,"concept":"K6-1-u5-C33","difficulty":1,"kind":"mc","stem":"주장하는 글의 주제로 쓸 수 있는 문제는 어느 것인가요?","options":[{"t":"빌린 책이 제때 돌아오지 않는다","correct":true},{"t":"내가 어제 늦잠을 잤다","mis":"K6-1-u5-X29"},{"t":"오늘 날씨가 흐리다","mis":"K6-1-u5-X29"},{"t":"내 필통 색이 마음에 들지 않는다","mis":"K6-1-u5-X29"}],"explanation":["나 혼자만의 일이에요.","근거를 대어 바꿀 수 있는 일이 아니에요.","근거를 댈 수 있고 여럿에게 알릴 만해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L08_basic#2','kor',6,1,'u5','L08','g6_1_kor_u5_L08_basic','lesson_basic','K6-1-u5-C34',1,'match','auto','계획하기에서 정할 것과 민찬이가 정한 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K6-1-u5-C34","difficulty":1,"kind":"match","stem":"계획하기에서 정할 것과 민찬이가 정한 내용을 알맞게 이으세요.","pairs":[{"l":"글을 쓰는 목적","r":"반납일을 지키자고 설득하고 싶다"},{"l":"글의 주제","r":"빌린 책은 반납일을 지켜 돌려주기"},{"l":"글을 읽을 사람","r":"도서관을 함께 쓰는 우리 학교 학생들"}],"mis":"K6-1-u5-X37","explanation":["목적은 이루고 싶은 것이에요.","주제는 무엇에 대한 글인지예요.","읽을 사람은 누가 읽는지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L08_basic#3','kor',6,1,'u5','L08','g6_1_kor_u5_L08_basic','lesson_basic','K6-1-u5-C35',1,'ox','auto','계획하기는 글을 쓰기 전에 한 번만 거치는 단계예요.',ARRAY['K6-1-u5-X30']::text[],false,'{"seq":3,"concept":"K6-1-u5-C35","difficulty":1,"kind":"ox","stem":"계획하기는 글을 쓰기 전에 한 번만 거치는 단계예요.","answer":"X","reason_options":[{"t":"쓰다가도 필요하면 언제든 계획으로 되돌아가 고칠 수 있기 때문에","correct":true},{"t":"한 번 세운 계획은 끝까지 지켜야 하기 때문에","mis":"K6-1-u5-X30"}],"mis":"K6-1-u5-X30","explanation":["쓰는 도중에도 돌아가요.","어긋난 계획을 붙들지 않아요.","되돌아가는 것이 정상이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L08_basic#4','kor',6,1,'u5','L08','g6_1_kor_u5_L08_basic','lesson_basic','K6-1-u5-C37',1,'mc','auto','「통일성」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X33','K6-1-u5-X06']::text[],false,'{"seq":4,"concept":"K6-1-u5-C37","difficulty":1,"kind":"mc","stem":"「통일성」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"글의 주제와 세부 내용이 서로 가깝게 이어져 있는 성질","correct":true},{"t":"문단의 길이가 모두 같은 성질","mis":"K6-1-u5-X33"},{"t":"모든 문장이 옳은 말인 성질","mis":"K6-1-u5-X33"},{"t":"글씨 크기가 고른 성질","mis":"K6-1-u5-X06"}],"explanation":["길이는 관계없어요.","옳은 말이어도 주제와 멀 수 있어요.","주제와 이어지는지가 통일성이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L08_basic#5','kor',6,1,'u5','L08','g6_1_kor_u5_L08_basic','lesson_basic','K6-1-u5-C34',2,'mc','auto','읽을 사람이 정해지면 함께 고를 수 있는 것은 어느 것인가요?',ARRAY['K6-1-u5-X26','K6-1-u5-X06']::text[],false,'{"seq":5,"concept":"K6-1-u5-C34","difficulty":2,"kind":"mc","stem":"읽을 사람이 정해지면 함께 고를 수 있는 것은 어느 것인가요?","options":[{"t":"알맞은 표현과 내세울 근거","correct":true},{"t":"글을 쓸 문단의 개수","mis":"K6-1-u5-X26"},{"t":"사용할 연필의 색","mis":"K6-1-u5-X06"},{"t":"글을 쓰는 목적 자체","mis":"K6-1-u5-X26"}],"explanation":["문단 수가 정해지는 것이 아니에요.","연필 색은 관계없어요.","표현과 근거를 읽을 사람에 맞춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L08_basic#6','kor',6,1,'u5','L08','g6_1_kor_u5_L08_basic','lesson_basic','K6-1-u5-C36',2,'ox','auto','내용 생성하기 단계에서는 문장을 다듬기보다 떠오르는 것을 많이 꺼내 놓는 것이 먼저예요.',ARRAY['K6-1-u5-X31']::text[],false,'{"seq":6,"concept":"K6-1-u5-C36","difficulty":2,"kind":"ox","stem":"내용 생성하기 단계에서는 문장을 다듬기보다 떠오르는 것을 많이 꺼내 놓는 것이 먼저예요.","answer":"O","reason_options":[{"t":"핵심 낱말과 짧은 문장으로 쓸 거리를 모으는 단계이기 때문에","correct":true},{"t":"처음부터 완성된 문장으로만 적어야 하기 때문에","mis":"K6-1-u5-X31"}],"mis":"K6-1-u5-X31","explanation":["지금은 모으는 단계예요.","문장 다듬기는 나중이에요.","핵심 낱말로 많이 꺼내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L08_basic#7','kor',6,1,'u5','L08','g6_1_kor_u5_L08_basic','lesson_basic','K6-1-u5-C36',2,'mc','auto','자료를 찾았을 때 출처를 바로 적어 두어야 하는 까닭은 어느 것인가요?',ARRAY['K6-1-u5-X32','K6-1-u5-X22','K6-1-u5-X25']::text[],false,'{"seq":7,"concept":"K6-1-u5-C36","difficulty":2,"kind":"mc","stem":"자료를 찾았을 때 출처를 바로 적어 두어야 하는 까닭은 어느 것인가요?","options":[{"t":"나중에 찾아 헤매지 않고, 적어 둔 출처가 그대로 글에 들어가기 때문이다","correct":true},{"t":"출처는 다 쓴 뒤에 생각해도 되기 때문이다","mis":"K6-1-u5-X32"},{"t":"표는 모두 옮겨 그려야 하기 때문이다","mis":"K6-1-u5-X22"},{"t":"출처를 적으면 글이 길어 보이기 때문이다","mis":"K6-1-u5-X25"}],"explanation":["나중엔 어디서 봤는지 잊어요.","다 옮겨 그리지 않아도 돼요.","길이 때문이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L08_basic#8','kor',6,1,'u5','L08','g6_1_kor_u5_L08_basic','lesson_basic','K6-1-u5-C37',2,'mc','auto','「반납일을 지키자」는 글의 통일성을 깨는 문장은 어느 것인가요?',ARRAY['K6-1-u5-X33']::text[],false,'{"seq":8,"concept":"K6-1-u5-C37","difficulty":2,"kind":"mc","stem":"「반납일을 지키자」는 글의 통일성을 깨는 문장은 어느 것인가요?","options":[{"t":"도서관에서는 조용히 해야 하므로 떠들지 맙시다","correct":true},{"t":"그 책을 기다리는 사람이 있습니다","mis":"K6-1-u5-X33"},{"t":"늦어질수록 돌려줄 일을 잊기 쉽습니다","mis":"K6-1-u5-X33"},{"t":"도서관 일이 늘어납니다","mis":"K6-1-u5-X33"}],"explanation":["반납과 이어져요.","반납과 이어져요.","옳은 말이어도 주제와 이어지지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L08_basic#9','kor',6,1,'u5','L08','g6_1_kor_u5_L08_basic','lesson_basic','K6-1-u5-C38',2,'mc','auto','문단을 짤 때 먼저 세워야 하는 것은 어느 것인가요?',ARRAY['K6-1-u5-X34']::text[],false,'{"seq":9,"concept":"K6-1-u5-C38","difficulty":2,"kind":"mc","stem":"문단을 짤 때 먼저 세워야 하는 것은 어느 것인가요?","options":[{"t":"이 문단에서 하고 싶은 말을 담은 중심 문장","correct":true},{"t":"조사 결과가 든 뒷받침 문장","mis":"K6-1-u5-X34"},{"t":"문단을 꾸미는 재미있는 문장","mis":"K6-1-u5-X34"},{"t":"다음 문단에서 할 말","mis":"K6-1-u5-X34"}],"explanation":["뒷받침 문장은 그 아래에 붙여요.","꾸미는 문장이 먼저가 아니에요.","중심 문장부터 세워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L08_basic#10','kor',6,1,'u5','L08','g6_1_kor_u5_L08_basic','lesson_basic','K6-1-u5-C39',3,'mc','auto','「기다리는 사람 · 예약 대기 열한 명」을 표현하기 단계에서 바르게 쓴 것은 어느 것인가요?',ARRAY['K6-1-u5-X31']::text[],false,'{"seq":10,"concept":"K6-1-u5-C39","difficulty":3,"kind":"mc","stem":"「기다리는 사람 · 예약 대기 열한 명」을 표현하기 단계에서 바르게 쓴 것은 어느 것인가요?","options":[{"t":"「첫째, 그 책을 기다리는 사람이 있기 때문입니다.」","correct":true},{"t":"「기다리는 사람 · 예약 대기 열한 명」","mis":"K6-1-u5-X31"},{"t":"「예약 대기」","mis":"K6-1-u5-X31"},{"t":"「기다림 — 많음」","mis":"K6-1-u5-X31"}],"explanation":["조직하기의 메모 그대로예요.","낱말 하나로는 문장이 아니에요.","표현하기는 스스로 문장을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L08_challenge#1','kor',6,1,'u5','L08','g6_1_kor_u5_L08_challenge','lesson_challenge','K6-1-u5-C33',2,'mc','auto','주장하는 글의 주제가 되려면 넘겨야 할 두 조건은 어느 것인가요?',ARRAY['K6-1-u5-X29']::text[],false,'{"seq":1,"concept":"K6-1-u5-C33","difficulty":2,"kind":"mc","stem":"주장하는 글의 주제가 되려면 넘겨야 할 두 조건은 어느 것인가요?","options":[{"t":"주장 · 이유 · 근거를 댈 수 있다 · 여러 사람에게 알릴 만하다","correct":true},{"t":"나만 아는 일이다 · 길게 쓸 수 있다","mis":"K6-1-u5-X29"},{"t":"재미있다 · 어려운 낱말이 많다","mis":"K6-1-u5-X29"},{"t":"근거가 없어도 된다 · 혼자만의 일이다","mis":"K6-1-u5-X29"}],"explanation":["나만 아는 일은 설득할 상대가 없어요.","재미나 어려움이 조건이 아니에요.","근거와 알릴 상대가 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L08_challenge#2','kor',6,1,'u5','L08','g6_1_kor_u5_L08_challenge','lesson_challenge','K6-1-u5-C35',3,'error','auto','글을 쓰다가 한 말이에요. 쓰기 과정을 잘못 이해한 말은 누구의 것인가요?',ARRAY['K6-1-u5-X30','K6-1-u5-X38']::text[],false,'{"seq":2,"concept":"K6-1-u5-C35","difficulty":3,"kind":"error","stem":"글을 쓰다가 한 말이에요. 쓰기 과정을 잘못 이해한 말은 누구의 것인가요?","options":[{"t":"예찬 — 「계획은 이미 세웠으니 이제 되돌아가면 안 돼.」","correct":true,"mis_target":"K6-1-u5-X30"},{"t":"민찬 — 「쓰다 보니 읽을 사람이 달라져야겠네. 계획으로 돌아가자.」","mis":"K6-1-u5-X30"},{"t":"규리 — 「조직하다 보니 근거가 모자라. 내용 생성으로 돌아갈래.」","mis":"K6-1-u5-X38"}],"explanation":["민찬은 바르게 되돌아갔어요.","규리도 바르게 되돌아갔어요.","계획으로 언제든 돌아갈 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L08_challenge#3','kor',6,1,'u5','L08','g6_1_kor_u5_L08_challenge','lesson_challenge','K6-1-u5-C36',3,'match','auto','민찬이의 이유와 근거를 알맞게 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K6-1-u5-C36","difficulty":3,"kind":"match","stem":"민찬이의 이유와 근거를 알맞게 이으세요.","pairs":[{"l":"기다리는 사람이 있다","r":"지난달 예약 대기 열한 명이라는 기록"},{"l":"늦을수록 잊기 쉽다","r":"열네 명이 잊은 적 있다는 설문"},{"l":"도서관 일이 늘어난다","r":"정리에 시간이 많이 든다는 면담"}],"mis":"K6-1-u5-X03","explanation":["기다림은 예약 대기와 이어져요.","잊음은 설문과 이어져요.","일이 늚은 면담과 이어져요."],"asset":{"type":"passage","lines":["근거 하나 — 예약해 놓고 기다리는 사람이 지난달에 열한 명이었다.","(○○초등학교 도서관(2026), 「사월 예약 대기 기록」, 도서관 게시판.)","근거 둘 — 우리 반 스물다섯 명 가운데 열네 명이 반납일을 잊은 적이 있다고 답했다.","(솔바람반(2026), 「도서 반납 습관 설문」, 학급 게시판.)","근거 셋 — 늦게 돌아온 책을 다시 정리하는 데 시간이 많이 든다고 하셨다.","(이○○ 사서 선생님 면담(2026), 「도서관 운영 이야기」, 학교 도서관.)"],"title":"민찬이 모은 근거와 출처"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L08_challenge#4','kor',6,1,'u5','L08','g6_1_kor_u5_L08_challenge','lesson_challenge','K6-1-u5-C37',3,'mc','auto','민찬이의 개요에 「도서관 책상은 깨끗이 써야 한다」를 본론에 넣으려 해요. 어떻게 하는 것이 알맞은가요?',ARRAY['K6-1-u5-X33','K6-1-u5-X11','K6-1-u5-X27']::text[],false,'{"seq":4,"concept":"K6-1-u5-C37","difficulty":3,"kind":"mc","stem":"민찬이의 개요에 「도서관 책상은 깨끗이 써야 한다」를 본론에 넣으려 해요. 어떻게 하는 것이 알맞은가요?","options":[{"t":"옳은 말이지만 반납일과 이어지지 않으므로 개요에서 걸러 낸다","correct":true},{"t":"옳은 말이니 그대로 넣는다","mis":"K6-1-u5-X33"},{"t":"결론에 새 이유로 넣는다","mis":"K6-1-u5-X11"},{"t":"서론의 주장으로 바꾼다","mis":"K6-1-u5-X27"}],"explanation":["옳아도 주제와 멀면 통일성이 깨져요.","결론은 새 이유를 꺼내지 않아요.","주장이 흐려져요."],"asset":{"type":"passage","lines":["서론 — 도서관에는 반납일이 지난 책이 늘 쌓여 있다.","　　　 빌린 책은 반납일을 지켜 돌려주어야 한다.","본론 — 첫째, 기다리는 사람이 있다.(예약 대기 기록)","　　　 둘째, 늦어질수록 잊기 쉽다.(반납 습관 설문)","　　　 셋째, 도서관 일이 늘어난다.(사서 선생님 면담)","결론 — 반납일을 지키면 모두가 더 편하게 책을 빌릴 수 있다.","　　　 오늘 빌린 책의 반납일을 지금 적어 두자."],"title":"민찬의 개요 「빌린 책은 반납일을 지켜 돌려줍시다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L08_challenge#5','kor',6,1,'u5','L08','g6_1_kor_u5_L08_challenge','lesson_challenge','K6-1-u5-C38',3,'mc','auto','「뒷받침 문장은 없어도 문단이 하나의 생각을 담을 수 있지만, 중심 문장은 없으면 어색하다」는 말의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X13','K6-1-u5-X34']::text[],false,'{"seq":5,"concept":"K6-1-u5-C38","difficulty":3,"kind":"mc","stem":"「뒷받침 문장은 없어도 문단이 하나의 생각을 담을 수 있지만, 중심 문장은 없으면 어색하다」는 말의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"문단이 하고 싶은 말은 중심 문장이 맡고 있다는 뜻이다","correct":true},{"t":"뒷받침 문장이 문단의 중심이라는 뜻이다","mis":"K6-1-u5-X13"},{"t":"중심 문장은 없어도 된다는 뜻이다","mis":"K6-1-u5-X34"},{"t":"문단에는 문장이 하나만 있어야 한다는 뜻이다","mis":"K6-1-u5-X34"}],"explanation":["뒷받침 문장은 받쳐 줘요.","중심 문장이 빠지면 어색해요.","중심 문장이 문단을 대표해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L08_challenge#6','kor',6,1,'u5','L08','g6_1_kor_u5_L08_challenge','lesson_challenge','K6-1-u5-C39',3,'mc','auto','표현하기를 하다가 더 좋은 근거가 떠올랐을 때 알맞은 행동은 어느 것인가요?',ARRAY['K6-1-u5-X38','K6-1-u5-X32']::text[],false,'{"seq":6,"concept":"K6-1-u5-C39","difficulty":3,"kind":"mc","stem":"표현하기를 하다가 더 좋은 근거가 떠올랐을 때 알맞은 행동은 어느 것인가요?","options":[{"t":"앞 단계로 돌아가 근거와 출처를 보태고 다시 써 나간다","correct":true},{"t":"표현하기를 시작했으니 떠오른 생각은 버린다","mis":"K6-1-u5-X38"},{"t":"출처는 빼고 근거만 그 자리에서 넣는다","mis":"K6-1-u5-X32"},{"t":"처음부터 모든 단계를 다시 한다","mis":"K6-1-u5-X38"}],"explanation":["되돌아가도 괜찮아요.","출처도 함께 적어요.","처음부터가 아니라 그 단계로 돌아가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L08_challenge#7','kor',6,1,'u5','L08','g6_1_kor_u5_L08_challenge','lesson_challenge','K6-1-u5-C13',2,'mc','auto','민찬이의 개요에서 결론에 담긴 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X11','K6-1-u5-X10']::text[],false,'{"seq":7,"concept":"K6-1-u5-C13","difficulty":2,"kind":"mc","stem":"민찬이의 개요에서 결론에 담긴 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"반납일을 지키면 좋아질 모습과, 지금 할 일을 다시 힘주어 말한 것","correct":true},{"t":"처음 꺼내는 새 근거","mis":"K6-1-u5-X11"},{"t":"도서관에 책이 쌓인 문제 제기","mis":"K6-1-u5-X10"},{"t":"세 이유를 받치는 출처","mis":"K6-1-u5-X10"}],"explanation":["새 근거는 꺼내지 않아요.","문제 제기는 서론이에요.","출처는 본론에 있어요."],"asset":{"type":"passage","lines":["서론 — 도서관에는 반납일이 지난 책이 늘 쌓여 있다.","　　　 빌린 책은 반납일을 지켜 돌려주어야 한다.","본론 — 첫째, 기다리는 사람이 있다.(예약 대기 기록)","　　　 둘째, 늦어질수록 잊기 쉽다.(반납 습관 설문)","　　　 셋째, 도서관 일이 늘어난다.(사서 선생님 면담)","결론 — 반납일을 지키면 모두가 더 편하게 책을 빌릴 수 있다.","　　　 오늘 빌린 책의 반납일을 지금 적어 두자."],"title":"민찬의 개요 「빌린 책은 반납일을 지켜 돌려줍시다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L08_challenge#8','kor',6,1,'u5','L08','g6_1_kor_u5_L08_challenge','lesson_challenge','K6-1-u5-C34',4,'mc','auto','민찬이가 쓰다가 「선생님들께도 이 글을 보여 드리자」고 읽을 사람을 넓혔어요. 가장 알맞은 다음 행동은 어느 것인가요?',ARRAY['K6-1-u5-X30','K6-1-u5-X26','K6-1-u5-X24']::text[],false,'{"seq":8,"concept":"K6-1-u5-C34","difficulty":4,"kind":"mc","stem":"민찬이가 쓰다가 「선생님들께도 이 글을 보여 드리자」고 읽을 사람을 넓혔어요. 가장 알맞은 다음 행동은 어느 것인가요?","options":[{"t":"계획하기로 돌아가 읽을 사람을 고치고, 선생님들께 맞는 말투와 근거인지 다시 살핀다","correct":true},{"t":"계획은 이미 끝났으니 그대로 쓴다","mis":"K6-1-u5-X30"},{"t":"읽을 사람이 늘었으니 주장을 바꾼다","mis":"K6-1-u5-X26"},{"t":"근거를 다섯 개 더 붙인다","mis":"K6-1-u5-X24"}],"explanation":["계획으로 돌아가도 돼요.","주장은 그대로예요.","많이 붙인다고 좋아지지 않아요."],"asset":{"type":"passage","lines":["서론 — 도서관에는 반납일이 지난 책이 늘 쌓여 있다.","　　　 빌린 책은 반납일을 지켜 돌려주어야 한다.","본론 — 첫째, 기다리는 사람이 있다.(예약 대기 기록)","　　　 둘째, 늦어질수록 잊기 쉽다.(반납 습관 설문)","　　　 셋째, 도서관 일이 늘어난다.(사서 선생님 면담)","결론 — 반납일을 지키면 모두가 더 편하게 책을 빌릴 수 있다.","　　　 오늘 빌린 책의 반납일을 지금 적어 두자."],"title":"민찬의 개요 「빌린 책은 반납일을 지켜 돌려줍시다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L08_challenge#9','kor',6,1,'u5','L08','g6_1_kor_u5_L08_challenge','lesson_challenge','K6-1-u5-C37',4,'essay','teacher','민찬이의 개요가 통일성을 갖추었는지 판단하고, 그 까닭을 서론 · 본론 · 결론과 이어 설명하세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u5-C37","difficulty":4,"kind":"essay","stem":"민찬이의 개요가 통일성을 갖추었는지 판단하고, 그 까닭을 서론 · 본론 · 결론과 이어 설명하세요.","answer_guide":{"answer":"예: 통일성을 갖추었다. 서론에서 반납일이 지난 책 문제를 꺼내고 「반납일을 지켜 돌려주자」고 주장했다. 본론의 세 이유(기다리는 사람 · 잊기 쉬움 · 도서관 일)는 모두 반납일을 지켜야 하는 까닭이고 근거도 그 이유에 맞는다. 결론도 반납일을 지키자는 주장으로 모았다. 주제와 멀어진 내용이 없다.","scoring_points":["통일성에 대한 판단을 밝혔는가","본론의 이유가 주제와 이어지는지 썼는가","서론과 결론이 같은 주제로 모이는지 썼는가"]},"explanation":["주제를 먼저 잡아요.","이유마다 주제와 이어지는지 봐요.","처음과 끝도 견줘요."],"asset":{"type":"passage","lines":["서론 — 도서관에는 반납일이 지난 책이 늘 쌓여 있다.","　　　 빌린 책은 반납일을 지켜 돌려주어야 한다.","본론 — 첫째, 기다리는 사람이 있다.(예약 대기 기록)","　　　 둘째, 늦어질수록 잊기 쉽다.(반납 습관 설문)","　　　 셋째, 도서관 일이 늘어난다.(사서 선생님 면담)","결론 — 반납일을 지키면 모두가 더 편하게 책을 빌릴 수 있다.","　　　 오늘 빌린 책의 반납일을 지금 적어 두자."],"title":"민찬의 개요 「빌린 책은 반납일을 지켜 돌려줍시다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L08_challenge#10','kor',6,1,'u5','L08','g6_1_kor_u5_L08_challenge','lesson_challenge','K6-1-u5-C36',4,'essay','teacher','내가 주장하는 글을 쓴다면 어떤 주제로 쓸지 정하고, 내용 생성하기 단계에서 꺼낼 이유 두 가지와 근거로 찾을 자료를 핵심 낱말로 적으세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u5-C36","difficulty":4,"kind":"essay","stem":"내가 주장하는 글을 쓴다면 어떤 주제로 쓸지 정하고, 내용 생성하기 단계에서 꺼낼 이유 두 가지와 근거로 찾을 자료를 핵심 낱말로 적으세요.","answer_guide":{"answer":"예: 주제 — 빈 교실의 불은 끄고 나갑시다. 이유 — 첫째, 전기 낭비 · 둘째, 끄는 사람 따로 없음. 근거로 찾을 자료 — 일주일 동안 빈 교실에 불이 켜진 횟수 관찰 기록(우리 반) · 시설 담당 선생님 면담. 출처는 자료를 찾는 대로 적어 두겠다.","scoring_points":["근거를 댈 수 있고 여럿에게 알릴 만한 주제를 정했는가","이유 두 가지를 핵심 낱말로 꺼냈는가","찾을 자료와 출처를 적어 둘 계획을 썼는가"]},"explanation":["겪은 일 가운데 골라요.","문장보다 핵심 낱말로 꺼내요.","자료와 출처를 함께 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L10_basic#1','kor',6,1,'u5','L10','g6_1_kor_u5_L10_basic','lesson_basic','K6-1-u5-C41',1,'mc','auto','쓰기 과정 다섯 단계를 차례대로 바르게 늘어놓은 것은 어느 것인가요?',ARRAY['K6-1-u5-X37']::text[],false,'{"seq":1,"concept":"K6-1-u5-C41","difficulty":1,"kind":"mc","stem":"쓰기 과정 다섯 단계를 차례대로 바르게 늘어놓은 것은 어느 것인가요?","options":[{"t":"계획하기 → 내용 생성하기 → 내용 조직하기 → 표현하기 → 고쳐쓰기","correct":true},{"t":"내용 생성하기 → 계획하기 → 표현하기 → 내용 조직하기 → 고쳐쓰기","mis":"K6-1-u5-X37"},{"t":"표현하기 → 고쳐쓰기 → 계획하기 → 내용 생성하기 → 내용 조직하기","mis":"K6-1-u5-X37"},{"t":"계획하기 → 표현하기 → 내용 생성하기 → 고쳐쓰기 → 내용 조직하기","mis":"K6-1-u5-X37"}],"explanation":["계획이 먼저예요.","표현하기가 처음이 아니에요.","정하고 · 모으고 · 늘어놓고 · 쓰고 · 고쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L10_basic#2','kor',6,1,'u5','L10','g6_1_kor_u5_L10_basic','lesson_basic','K6-1-u5-C41',1,'match','auto','내가 한 일과 쓰기 과정을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K6-1-u5-C41","difficulty":1,"kind":"match","stem":"내가 한 일과 쓰기 과정을 알맞게 이으세요.","pairs":[{"l":"글을 읽을 사람을 누구로 할지 정했다","r":"계획하기"},{"l":"도서관 기록을 찾아 출처를 적어 두었다","r":"내용 생성하기"},{"l":"이유 셋을 서론 · 본론 · 결론에 나누어 늘어놓았다","r":"내용 조직하기"},{"l":"쓴 글에서 어색한 문장을 찾아 고쳤다","r":"고쳐쓰기"}],"mis":"K6-1-u5-X37","explanation":["정하는 일은 계획하기예요.","모으는 일은 내용 생성하기예요.","늘어놓는 일은 조직하기, 손보는 일은 고쳐쓰기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L10_basic#3','kor',6,1,'u5','L10','g6_1_kor_u5_L10_basic','lesson_basic','K6-1-u5-C42',1,'ox','auto','표현하기까지 왔다가 내용 생성하기로 되돌아가는 것은 실패예요.',ARRAY['K6-1-u5-X38']::text[],false,'{"seq":3,"concept":"K6-1-u5-C42","difficulty":1,"kind":"ox","stem":"표현하기까지 왔다가 내용 생성하기로 되돌아가는 것은 실패예요.","answer":"X","reason_options":[{"t":"쓰기는 되돌아오는 성질을 지녀 되돌아간 단계에서 글이 좋아지기 때문에","correct":true},{"t":"앞으로만 가야 좋은 글이 되기 때문에","mis":"K6-1-u5-X38"}],"mis":"K6-1-u5-X38","explanation":["되돌아가는 것이 정상이에요.","처음부터 다시 하는 게 아니에요.","여러 번 돌아온 글이 좋은 글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L10_basic#4','kor',6,1,'u5','L10','g6_1_kor_u5_L10_basic','lesson_basic','K6-1-u5-C45',1,'match','auto','고친 내용과 그 수준을 알맞게 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K6-1-u5-C45","difficulty":1,"kind":"match","stem":"고친 내용과 그 수준을 알맞게 이으세요.","pairs":[{"l":"결론이 없어서 마지막 문단을 새로 썼다","r":"글 수준"},{"l":"중심 문장만 있어 받쳐 주는 문장 두 줄을 보탰다","r":"문단 수준"},{"l":"「안돼요」를 「안 돼요」로 고쳤다","r":"문장과 낱말 수준"}],"mis":"K6-1-u5-X41","explanation":["글 전체가 달라지는 고침이에요.","한 문단 안의 고침이에요.","낱말 하나의 고침이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L10_basic#5','kor',6,1,'u5','L10','g6_1_kor_u5_L10_basic','lesson_basic','K6-1-u5-C40',2,'mc','auto','점검하고 조정하기에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X36','K6-1-u5-X06']::text[],false,'{"seq":5,"concept":"K6-1-u5-C40","difficulty":2,"kind":"mc","stem":"점검하고 조정하기에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"쓰기 과정 다섯 단계 어디에서나 일어나며 쓰는 도중에 방향을 다시 잡는 일이다","correct":true},{"t":"글을 다 쓴 뒤에 한 번 채점하는 일이다","mis":"K6-1-u5-X36"},{"t":"고쳐쓰기 단계에서만 하는 일이다","mis":"K6-1-u5-X36"},{"t":"글씨와 분량을 재는 일이다","mis":"K6-1-u5-X06"}],"explanation":["채점이 아니에요.","어느 단계에서나 해요.","방향을 다시 잡는 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L10_basic#6','kor',6,1,'u5','L10','g6_1_kor_u5_L10_basic','lesson_basic','K6-1-u5-C43',2,'mc','auto','계획하기를 점검하는 질문으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X39']::text[],false,'{"seq":6,"concept":"K6-1-u5-C43","difficulty":2,"kind":"mc","stem":"계획하기를 점검하는 질문으로 알맞은 것은 어느 것인가요?","options":[{"t":"글을 읽을 사람이 누구인지 정했나요?","correct":true},{"t":"띄어쓰기가 틀리지 않게 썼나요?","mis":"K6-1-u5-X39"},{"t":"문장과 문장이 자연스럽게 이어지나요?","mis":"K6-1-u5-X39"},{"t":"관련 있는 내용끼리 묶었나요?","mis":"K6-1-u5-X39"}],"explanation":["띄어쓰기는 고쳐쓰기에서 봐요.","문장 잇기는 표현과 고쳐쓰기예요.","계획하기는 읽을 사람을 정했는지 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L10_basic#7','kor',6,1,'u5','L10','g6_1_kor_u5_L10_basic','lesson_basic','K6-1-u5-C44',2,'ox','auto','다시 쓰기가 버거우면 원래 글 위에 쪽지를 붙여 고칠 말만 얹어도 돼요.',ARRAY['K6-1-u5-X40']::text[],false,'{"seq":7,"concept":"K6-1-u5-C44","difficulty":2,"kind":"ox","stem":"다시 쓰기가 버거우면 원래 글 위에 쪽지를 붙여 고칠 말만 얹어도 돼요.","answer":"O","reason_options":[{"t":"이 단원이 재는 것은 완성된 글의 흠이 아니라 고쳐 가는 과정이기 때문에","correct":true},{"t":"고치려면 반드시 새 종이에 전부 다시 써야 하기 때문에","mis":"K6-1-u5-X40"}],"mis":"K6-1-u5-X40","explanation":["새 종이가 꼭 필요하지 않아요.","한 군데만 고쳐도 점검이에요.","과정을 보는 단원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L10_basic#8','kor',6,1,'u5','L10','g6_1_kor_u5_L10_basic','lesson_basic','K6-1-u5-C46',2,'mc','auto','문장과 낱말 수준에서 살필 것은 어느 것인가요?',ARRAY['K6-1-u5-X41','K6-1-u5-X42']::text[],false,'{"seq":8,"concept":"K6-1-u5-C46","difficulty":2,"kind":"mc","stem":"문장과 낱말 수준에서 살필 것은 어느 것인가요?","options":[{"t":"띄어쓰기와 맞춤법이 바른가","correct":true},{"t":"문단의 차례를 바꿔야 하는가","mis":"K6-1-u5-X41"},{"t":"서론에 주장이 드러나는가","mis":"K6-1-u5-X41"},{"t":"띄어쓰기는 글쓰기와 관계없으니 살피지 않는다","mis":"K6-1-u5-X42"}],"explanation":["문단 차례는 더 큰 수준이에요.","주장은 글 수준에서 봐요.","낱말도 민감하게 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L10_basic#9','kor',6,1,'u5','L10','g6_1_kor_u5_L10_basic','lesson_basic','K6-1-u5-C43',2,'mc','auto','표현하기를 점검할 때의 잣대로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X35','K6-1-u5-X06','K6-1-u5-X25']::text[],false,'{"seq":9,"concept":"K6-1-u5-C43","difficulty":2,"kind":"mc","stem":"표현하기를 점검할 때의 잣대로 알맞은 것은 어느 것인가요?","options":[{"t":"읽을 사람이 알아듣는가","correct":true},{"t":"내가 읽어서 매끄러운가","mis":"K6-1-u5-X35"},{"t":"글이 길게 쓰였는가","mis":"K6-1-u5-X06"},{"t":"어려운 낱말이 많은가","mis":"K6-1-u5-X25"}],"explanation":["나만 매끄러우면 안 돼요.","길이는 잣대가 아니에요.","잣대는 읽을 사람이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L10_basic#10','kor',6,1,'u5','L10','g6_1_kor_u5_L10_basic','lesson_basic','K6-1-u5-C45',3,'mc','auto','「큰 것부터 손보면 헛수고가 줄어든다」는 말의 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X41','K6-1-u5-X42']::text[],false,'{"seq":10,"concept":"K6-1-u5-C45","difficulty":3,"kind":"mc","stem":"「큰 것부터 손보면 헛수고가 줄어든다」는 말의 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"문단을 통째로 지울 참이라면 그 안의 맞춤법을 먼저 고칠 까닭이 없기 때문이다","correct":true},{"t":"맞춤법을 가장 먼저 고쳐야 하기 때문이다","mis":"K6-1-u5-X41"},{"t":"작은 것은 고치지 않아도 되기 때문이다","mis":"K6-1-u5-X42"},{"t":"반드시 이 차례로만 고쳐야 하기 때문이다","mis":"K6-1-u5-X41"}],"explanation":["맞춤법부터가 아니에요.","작은 것도 고쳐요.","꼭 이 차례일 필요는 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L10_challenge#1','kor',6,1,'u5','L10','g6_1_kor_u5_L10_challenge','lesson_challenge','K6-1-u5-C40',2,'mc','auto','과정을 점검하면 좋은 점으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K6-1-u5-X36']::text[],false,'{"seq":1,"concept":"K6-1-u5-C40","difficulty":2,"kind":"mc","stem":"과정을 점검하면 좋은 점으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"다 쓴 글에 점수를 매겨 다른 친구와 견줄 수 있다","correct":true},{"t":"어느 단계를 건너뛰었는지 보인다","mis":"K6-1-u5-X36"},{"t":"쓰는 도중에 고칠 점을 찾을 수 있다","mis":"K6-1-u5-X36"},{"t":"남은 부분을 다르게 써 나갈 수 있다","mis":"K6-1-u5-X36"}],"explanation":["되돌아보는 좋은 점이에요.","고칠 곳을 찾는 좋은 점이에요.","점검은 채점이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L10_challenge#2','kor',6,1,'u5','L10','g6_1_kor_u5_L10_challenge','lesson_challenge','K6-1-u5-C45',2,'ox','auto','고쳐쓰기는 반드시 글 수준 → 문단 수준 → 문장과 낱말 수준의 차례로만 해야 해요.',ARRAY['K6-1-u5-X41']::text[],false,'{"seq":2,"concept":"K6-1-u5-C45","difficulty":2,"kind":"ox","stem":"고쳐쓰기는 반드시 글 수준 → 문단 수준 → 문장과 낱말 수준의 차례로만 해야 해요.","answer":"X","reason_options":[{"t":"큰 것부터가 좋지만 눈에 띄는 곳부터 손대도 되기 때문에","correct":true},{"t":"차례를 어기면 고친 것이 아니기 때문에","mis":"K6-1-u5-X41"}],"mis":"K6-1-u5-X41","explanation":["큰 것부터가 헛수고를 줄여요.","그래도 반드시는 아니에요.","어느 수준부터 손대도 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L10_challenge#3','kor',6,1,'u5','L10','g6_1_kor_u5_L10_challenge','lesson_challenge','K6-1-u5-C43',3,'mc','auto','내용 생성하기를 점검할 때 「아는 것부터 먼저 꺼냈는가」를 묻는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X09','K6-1-u5-X23','K6-1-u5-X31']::text[],false,'{"seq":3,"concept":"K6-1-u5-C43","difficulty":3,"kind":"mc","stem":"내용 생성하기를 점검할 때 「아는 것부터 먼저 꺼냈는가」를 묻는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"아는 것을 꺼내 보아야 무엇이 모자란지 보이고, 그다음에 자료를 찾아야 헤매지 않기 때문이다","correct":true},{"t":"아는 것만으로 글을 다 쓸 수 있기 때문이다","mis":"K6-1-u5-X09"},{"t":"자료는 찾지 않는 것이 좋기 때문이다","mis":"K6-1-u5-X23"},{"t":"문장을 먼저 다듬어야 하기 때문이다","mis":"K6-1-u5-X31"}],"explanation":["모자란 곳은 자료로 채워요.","자료도 찾아요.","지금은 꺼내는 단계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L10_challenge#4','kor',6,1,'u5','L10','g6_1_kor_u5_L10_challenge','lesson_challenge','K6-1-u5-C43',3,'error','auto','점검 질문을 단계에 붙였어요. 잘못 붙인 것은 누구의 것인가요?',ARRAY['K6-1-u5-X39','K6-1-u5-X35']::text[],false,'{"seq":4,"concept":"K6-1-u5-C43","difficulty":3,"kind":"error","stem":"점검 질문을 단계에 붙였어요. 잘못 붙인 것은 누구의 것인가요?","options":[{"t":"슬아 — 계획하기: 「맞춤법을 틀리지 않게 썼나요?」","correct":true,"mis_target":"K6-1-u5-X39"},{"t":"민찬 — 내용 조직하기: 「관련 있는 내용끼리 묶었나요?」","mis":"K6-1-u5-X39"},{"t":"규리 — 표현하기: 「읽을 사람이 이해하기 쉽게 썼나요?」","mis":"K6-1-u5-X35"}],"explanation":["민찬은 조직하기에 맞게 붙였어요.","규리는 표현하기에 맞게 붙였어요.","맞춤법은 계획하기의 질문이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L10_challenge#5','kor',6,1,'u5','L10','g6_1_kor_u5_L10_challenge','lesson_challenge','K6-1-u5-C44',3,'mc','auto','「고칠 곳이 이렇게 많다니, 내 글은 망했구나.」라고 말한 친구에게 해 줄 말로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X40','K6-1-u5-X36','K6-1-u5-X07']::text[],false,'{"seq":5,"concept":"K6-1-u5-C44","difficulty":3,"kind":"mc","stem":"「고칠 곳이 이렇게 많다니, 내 글은 망했구나.」라고 말한 친구에게 해 줄 말로 알맞은 것은 어느 것인가요?","options":[{"t":"고칠 곳을 찾아냈다는 건 네가 볼 줄 알게 되었다는 뜻이야","correct":true},{"t":"고칠 곳이 많으면 버리고 새로 쓰는 게 나아","mis":"K6-1-u5-X40"},{"t":"점검은 흠을 세는 일이니 어쩔 수 없어","mis":"K6-1-u5-X36"},{"t":"처음부터 잘 썼어야지","mis":"K6-1-u5-X07"}],"explanation":["버리지 않고 고쳐 가요.","점검은 흠 세기가 아니에요.","과정을 익히는 시간이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L10_challenge#6','kor',6,1,'u5','L10','g6_1_kor_u5_L10_challenge','lesson_challenge','K6-1-u5-C46',3,'mc','auto','「도서관 에서 빌린책은 꼭 돌려 줍시다.」를 문장과 낱말 수준에서 바르게 고친 것은 어느 것인가요?',ARRAY['K6-1-u5-X42']::text[],false,'{"seq":6,"concept":"K6-1-u5-C46","difficulty":3,"kind":"mc","stem":"「도서관 에서 빌린책은 꼭 돌려 줍시다.」를 문장과 낱말 수준에서 바르게 고친 것은 어느 것인가요?","options":[{"t":"「도서관에서 빌린 책은 꼭 돌려줍시다.」","correct":true},{"t":"「도서관 에서 빌린책은 꼭 돌려줍시다.」","mis":"K6-1-u5-X42"},{"t":"「도서관에서 빌린책은 꼭 돌려 줍시다.」","mis":"K6-1-u5-X42"},{"t":"「도서관 에서 빌린 책은 꼭 돌려 줍시다.」","mis":"K6-1-u5-X42"}],"explanation":["「도서관에서」는 붙여 써요.","「빌린 책」은 띄어 써요.","「돌려줍시다」는 한 낱말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L10_challenge#7','kor',6,1,'u5','L10','g6_1_kor_u5_L10_challenge','lesson_challenge','K6-1-u5-C42',3,'mc','auto','「여러 번 돌아온 글이 좋은 글이다」라는 말과 가장 가까운 것은 어느 것인가요?',ARRAY['K6-1-u5-X38','K6-1-u5-X30','K6-1-u5-X41']::text[],false,'{"seq":7,"concept":"K6-1-u5-C42","difficulty":3,"kind":"mc","stem":"「여러 번 돌아온 글이 좋은 글이다」라는 말과 가장 가까운 것은 어느 것인가요?","options":[{"t":"쓰다가 근거가 약한 것을 알고 내용 생성하기로 돌아가 자료를 보탠 글","correct":true},{"t":"한 번에 끝까지 쓰고 다시 보지 않은 글","mis":"K6-1-u5-X38"},{"t":"계획을 바꾸지 않으려고 어긋난 내용을 그대로 둔 글","mis":"K6-1-u5-X30"},{"t":"맞춤법만 여러 번 고친 글","mis":"K6-1-u5-X41"}],"explanation":["다시 보지 않으면 고칠 곳을 놓쳐요.","어긋난 계획을 붙들면 안 돼요.","되돌아가 보탤 때 좋아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L10_challenge#8','kor',6,1,'u5','L10','g6_1_kor_u5_L10_challenge','lesson_challenge','K6-1-u5-C45',4,'mc','auto','글을 점검해 보니 「결론이 없음 · ③문단에 뒷받침 문장이 없음 · 맞춤법 두 군데」가 나왔어요. 헛수고를 줄이는 고칠 차례로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X41','K6-1-u5-X42','K6-1-u5-X40']::text[],false,'{"seq":8,"concept":"K6-1-u5-C45","difficulty":4,"kind":"mc","stem":"글을 점검해 보니 「결론이 없음 · ③문단에 뒷받침 문장이 없음 · 맞춤법 두 군데」가 나왔어요. 헛수고를 줄이는 고칠 차례로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"결론을 새로 쓰고 → ③문단에 뒷받침 문장을 보태고 → 맞춤법을 고친다","correct":true},{"t":"맞춤법을 고치고 → 결론을 쓰고 → 뒷받침 문장을 보탠다","mis":"K6-1-u5-X41"},{"t":"맞춤법만 고치고 나머지는 그대로 둔다","mis":"K6-1-u5-X42"},{"t":"글을 버리고 새 종이에 처음부터 다시 쓴다","mis":"K6-1-u5-X40"}],"explanation":["작은 것부터면 헛수고가 생길 수 있어요.","큰 고침도 필요해요.","버리지 않고 크기대로 손봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L10_challenge#9','kor',6,1,'u5','L10','g6_1_kor_u5_L10_challenge','lesson_challenge','K6-1-u5-C42',4,'essay','teacher','「쓰기는 되돌아오는 성질을 지닌다」는 말을, 내가 쓰는 도중에 앞 단계로 되돌아가는 예를 들어 설명하세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u5-C42","difficulty":4,"kind":"essay","stem":"「쓰기는 되돌아오는 성질을 지닌다」는 말을, 내가 쓰는 도중에 앞 단계로 되돌아가는 예를 들어 설명하세요.","answer_guide":{"answer":"예: 표현하기를 하다가 둘째 이유의 근거가 「다들 그렇대」 같은 짐작뿐이라는 것을 알게 되면, 내용 생성하기로 돌아가 우리 반 설문을 하고 출처를 적어 근거를 바꾼다. 또 쓰다가 읽을 사람이 동생들이라는 것이 떠오르면 계획하기로 돌아가 말투를 고친다. 이렇게 되돌아가는 것은 실패가 아니라 쓰기의 성질이고, 되돌아간 단계에서 글이 좋아진다.","scoring_points":["쓰는 도중 되돌아가는 예를 들었는가","어느 단계로 왜 돌아가는지 썼는가","되돌아감이 실패가 아니라는 점을 썼는가"]},"explanation":["쓰다가 생길 일을 떠올려요.","돌아갈 단계를 정해요.","되돌아감의 뜻을 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L10_challenge#10','kor',6,1,'u5','L10','g6_1_kor_u5_L10_challenge','lesson_challenge','K6-1-u5-C45',4,'essay','teacher','지난 시간에 쓴 주장하는 글을 고친다고 할 때, 글 · 문단 · 문장과 낱말 수준에서 살펴볼 것을 하나씩 쓰고, 어디부터 손댈지 정해 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u5-C45","difficulty":4,"kind":"essay","stem":"지난 시간에 쓴 주장하는 글을 고친다고 할 때, 글 · 문단 · 문장과 낱말 수준에서 살펴볼 것을 하나씩 쓰고, 어디부터 손댈지 정해 까닭을 쓰세요.","answer_guide":{"answer":"예: 글 수준 — 서론에 주장이 분명히 드러나는가. 문단 수준 — 본론 문단마다 중심 문장을 뒷받침 문장이 받쳐 주는가. 문장과 낱말 수준 — 띄어쓰기와 맞춤법이 바른가. 나는 글 수준부터 손보겠다. 주장이 흐리면 문단이 통째로 바뀔 수 있어 맞춤법을 먼저 고치면 헛수고가 되기 때문이다.","scoring_points":["세 수준에서 살필 것을 하나씩 썼는가","손댈 곳을 정했는가","그렇게 정한 까닭을 썼는가"]},"explanation":["세 크기를 떠올려요.","어디부터 할지 골라요.","까닭을 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L12_basic#1','kor',6,1,'u5','L12','g6_1_kor_u5_L12_basic','lesson_basic','K6-1-u5-C47',1,'mc','auto','실천 활동으로 고르기에 알맞은 문제는 어느 것인가요?',ARRAY['K6-1-u5-X43']::text[],false,'{"seq":1,"concept":"K6-1-u5-C47","difficulty":1,"kind":"mc","stem":"실천 활동으로 고르기에 알맞은 문제는 어느 것인가요?","options":[{"t":"사물함 위에 주인 없는 물건이 쌓인다","correct":true},{"t":"비 오는 날이 너무 많다","mis":"K6-1-u5-X43"},{"t":"방학이 너무 짧다","mis":"K6-1-u5-X43"},{"t":"하늘이 흐리다","mis":"K6-1-u5-X43"}],"explanation":["날씨는 우리 힘으로 바꿀 수 없어요.","방학 길이도 우리가 정할 수 없어요.","우리가 바꿀 수 있고 근거를 댈 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L12_basic#2','kor',6,1,'u5','L12','g6_1_kor_u5_L12_basic','lesson_basic','K6-1-u5-C47',1,'mc','auto','주장으로 알맞은 문장은 어느 것인가요?',ARRAY['K6-1-u5-X02','K6-1-u5-X27']::text[],false,'{"seq":2,"concept":"K6-1-u5-C47","difficulty":1,"kind":"mc","stem":"주장으로 알맞은 문장은 어느 것인가요?","options":[{"t":"사물함 위에는 물건을 두지 맙시다","correct":true},{"t":"사물함 위에 물건이 많이 쌓여 있습니다","mis":"K6-1-u5-X02"},{"t":"학교 생활을 더 좋게 합시다","mis":"K6-1-u5-X27"},{"t":"우리 모두 노력이 필요합니다","mis":"K6-1-u5-X27"}],"explanation":["문제 상황을 말했어요.","무엇을 하자는지 흐려요.","할 일이 한 문장으로 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L12_basic#3','kor',6,1,'u5','L12','g6_1_kor_u5_L12_basic','lesson_basic','K6-1-u5-C49',1,'match','auto','네 칸과 그 칸에 들어갈 문장을 알맞게 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K6-1-u5-C49","difficulty":1,"kind":"match","stem":"네 칸과 그 칸에 들어갈 문장을 알맞게 이으세요.","pairs":[{"l":"의견","r":"사물함 위에는 물건을 두지 맙시다"},{"l":"까닭","r":"떨어지면 다칠 수 있기 때문입니다"},{"l":"사례","r":"사흘 동안 세어 보니 하루 평균 아홉 개였습니다"},{"l":"제안","r":"오늘부터 사물함 위를 비워 둡시다"}],"mis":"K6-1-u5-X45","explanation":["처음은 꺼내는 말이에요.","까닭과 사례가 가운데에 와요.","끝은 다시 밀어 주는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L12_basic#4','kor',6,1,'u5','L12','g6_1_kor_u5_L12_basic','lesson_basic','K6-1-u5-C48',1,'ox','auto','표어를 만들 때 글씨를 크게 하고 알록달록 꾸미기만 하면 근거가 없어도 설득이 돼요.',ARRAY['K6-1-u5-X44']::text[],false,'{"seq":4,"concept":"K6-1-u5-C48","difficulty":1,"kind":"ox","stem":"표어를 만들 때 글씨를 크게 하고 알록달록 꾸미기만 하면 근거가 없어도 설득이 돼요.","answer":"X","reason_options":[{"t":"눈길을 끌 뿐 생각을 바꾸는 것은 확인할 수 있는 근거이기 때문에","correct":true},{"t":"눈에 띄는 것이 곧 설득이기 때문에","mis":"K6-1-u5-X44"}],"mis":"K6-1-u5-X44","explanation":["눈길은 잠깐이에요.","근거가 생각을 바꿔요.","근거 하나는 남겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L12_basic#5','kor',6,1,'u5','L12','g6_1_kor_u5_L12_basic','lesson_basic','K6-1-u5-C29',2,'match','auto','예찬이의 이유와 근거를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-1-u5-C29","difficulty":2,"kind":"match","stem":"예찬이의 이유와 근거를 알맞게 이으세요.","pairs":[{"l":"물건이 떨어져 다칠 수 있다","r":"사물함 위 물건을 센 사흘 동안의 관찰 기록"},{"l":"주인을 못 찾고 버려진다","r":"주인을 못 찾은 물건이 절반이 넘는 분실물 기록"},{"l":"청소할 때 손이 더 간다","r":"치우는 데 시간이 더 든다는 청소 담당 선생님 면담"}],"mis":"K6-1-u5-X03","explanation":["다침은 떨어질 물건 수와 이어져요.","잃어버림은 분실물 기록과 이어져요.","청소는 담당 선생님 말씀과 이어져요."],"asset":{"type":"passage","lines":["주장 — 사물함 위에는 물건을 두지 맙시다.","이유 하나 — 물건이 떨어져 다칠 수 있기 때문입니다.","근거 — 우리 층 사물함 위 물건을 사흘 동안 세어 보니 하루 평균 아홉 개였다.","(솔바람반(2026), 「사흘 동안의 사물함 관찰 기록」, 학급 게시판.)","이유 둘 — 주인을 찾지 못한 채 버려지기 때문입니다.","근거 — 지난달 분실물함에 들어온 물건 가운데 절반 넘게 주인을 찾지 못했다.","(○○초등학교(2026), 「사월 분실물 기록」, 학교 안내판.)"],"title":"예찬이 세운 주장과 근거"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L12_basic#6','kor',6,1,'u5','L12','g6_1_kor_u5_L12_basic','lesson_basic','K6-1-u5-C48',2,'mc','auto','설득의 힘이 가장 센 것은 어느 것인가요?',ARRAY['K6-1-u5-X44','K6-1-u5-X24']::text[],false,'{"seq":6,"concept":"K6-1-u5-C48","difficulty":2,"kind":"mc","stem":"설득의 힘이 가장 센 것은 어느 것인가요?","options":[{"t":"「사흘 동안 하루 평균 아홉 개」라는 관찰 기록을 표어 아래에 붙였다","correct":true},{"t":"표어 글씨를 가장 크게 키웠다","mis":"K6-1-u5-X44"},{"t":"종이를 여러 색으로 알록달록 칠했다","mis":"K6-1-u5-X44"},{"t":"표어를 여러 장 붙였다","mis":"K6-1-u5-X24"}],"explanation":["크기가 설득을 만들지 않아요.","색은 눈길만 끌어요.","확인할 수 있는 사실 하나가 세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L12_basic#7','kor',6,1,'u5','L12','g6_1_kor_u5_L12_basic','lesson_basic','K6-1-u5-C48',2,'mc','auto','주장을 펼치는 방법을 표어로 바꿀 때 지켜야 할 것은 어느 것인가요?',ARRAY['K6-1-u5-X44','K6-1-u5-X26','K6-1-u5-X45']::text[],false,'{"seq":7,"concept":"K6-1-u5-C48","difficulty":2,"kind":"mc","stem":"주장을 펼치는 방법을 표어로 바꿀 때 지켜야 할 것은 어느 것인가요?","options":[{"t":"방법이 바뀌어도 주장 · 이유 · 근거는 그대로 남긴다","correct":true},{"t":"표어는 짧으니 근거를 빼도 된다","mis":"K6-1-u5-X44"},{"t":"표어로 바꾸면 주장도 바꿔야 한다","mis":"K6-1-u5-X26"},{"t":"표어는 길게 써야 한다","mis":"K6-1-u5-X45"}],"explanation":["짧아도 근거 하나는 남겨요.","주장은 그대로예요.","길게 쓸 수 없어 네 칸 짜임을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L12_basic#8','kor',6,1,'u5','L12','g6_1_kor_u5_L12_basic','lesson_basic','K6-1-u5-C50',2,'ox','auto','주장하는 글이 닿아야 할 마지막 걸음은 종이가 아니라 생활이에요.',ARRAY['K6-1-u5-X46']::text[],false,'{"seq":8,"concept":"K6-1-u5-C50","difficulty":2,"kind":"ox","stem":"주장하는 글이 닿아야 할 마지막 걸음은 종이가 아니라 생활이에요.","answer":"O","reason_options":[{"t":"내가 알린 대로 내가 먼저 해 보는 것이 가장 센 근거이기 때문에","correct":true},{"t":"주장을 알리고 나면 할 일이 끝나기 때문에","mis":"K6-1-u5-X46"}],"mis":"K6-1-u5-X46","explanation":["알리고 끝이 아니에요.","먼저 해 보아요.","생활에서 달라져야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L12_basic#9','kor',6,1,'u5','L12','g6_1_kor_u5_L12_basic','lesson_basic','K6-1-u5-C49',2,'mc','auto','네 칸 짜임(의견 · 까닭 · 사례 · 제안)은 무엇을 줄인 틀인가요?',ARRAY['K6-1-u5-X37','K6-1-u5-X21','K6-1-u5-X41']::text[],false,'{"seq":9,"concept":"K6-1-u5-C49","difficulty":2,"kind":"mc","stem":"네 칸 짜임(의견 · 까닭 · 사례 · 제안)은 무엇을 줄인 틀인가요?","options":[{"t":"서론 · 본론 · 결론","correct":true},{"t":"쓰기 과정 다섯 단계","mis":"K6-1-u5-X37"},{"t":"출처의 네 가지","mis":"K6-1-u5-X21"},{"t":"고쳐쓰기의 세 수준","mis":"K6-1-u5-X41"}],"explanation":["쓰기 과정과 다른 틀이에요.","출처의 네 칸과 달라요.","글의 짜임을 짧게 줄인 틀이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L12_basic#10','kor',6,1,'u5','L12','g6_1_kor_u5_L12_basic','lesson_basic','K6-1-u5-C51',3,'mc','auto','「어떤 조사에 따르면, 읽지 않는 책을 둔 학생이 많다고 한다.」의 문제점으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X47','K6-1-u5-X25','K6-1-u5-X23']::text[],false,'{"seq":10,"concept":"K6-1-u5-C51","difficulty":3,"kind":"mc","stem":"「어떤 조사에 따르면, 읽지 않는 책을 둔 학생이 많다고 한다.」의 문제점으로 알맞은 것은 어느 것인가요?","options":[{"t":"누가 · 언제 · 무엇을 · 어디에 실었는지 없어 읽는 사람이 확인할 길이 없다","correct":true},{"t":"조사라는 말이 들어 있으니 문제가 없다","mis":"K6-1-u5-X47"},{"t":"문장이 짧아서 문제가 된다","mis":"K6-1-u5-X25"},{"t":"조사 결과는 근거가 될 수 없다","mis":"K6-1-u5-X23"}],"explanation":["「조사」라는 말만으로는 출처가 아니에요.","길이 문제가 아니에요.","조사 결과도 출처가 있으면 근거예요."],"asset":{"type":"passage","lines":["① 학년이 올라가면 지난해에 보던 책이 쌓인다. 현관에 헌책 나눔 상자를 두면 좋겠다.","② 첫째, 책이 필요한 사람에게 옮겨 가기 때문이다. 어떤 조사에 따르면,","집에 읽지 않는 책을 여러 권 두고 있는 학생이 많다고 한다.","③ 둘째, 종이를 덜 쓰게 되기 때문이다. 우리 반 스물다섯 명 가운데 스물한 명이","헌책을 받아 본 적이 있다고 답했다. (솔바람반(2026), 「헌책 이용 설문」, 학급 게시판.)","④ 셋째, 책을 고르는 재미가 생기기 때문이다. 어떤 선생님께서","남의 손을 거친 책을 아이들이 더 궁금해한다고 하셨다.","⑤ 상자 하나면 된다. 헌책 나눔 상자를 두어 책이 다시 읽히게 하자."],"title":"「헌책 나눔 상자를 두면 좋겠습니다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L12_challenge#1','kor',6,1,'u5','L12','g6_1_kor_u5_L12_challenge','lesson_challenge','K6-1-u5-C47',2,'mc','auto','주장을 한 문장으로 만들어야 하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X24','K6-1-u5-X04','K6-1-u5-X02']::text[],false,'{"seq":1,"concept":"K6-1-u5-C47","difficulty":2,"kind":"mc","stem":"주장을 한 문장으로 만들어야 하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"길어질수록 흐려져 무엇을 할지 모르게 되기 때문이다","correct":true},{"t":"짧은 글이 늘 더 좋은 글이기 때문이다","mis":"K6-1-u5-X24"},{"t":"이유와 근거를 빼기 위해서이다","mis":"K6-1-u5-X04"},{"t":"주장은 문제 상황을 말하는 문장이기 때문이다","mis":"K6-1-u5-X02"}],"explanation":["길이 자체가 좋고 나쁨은 아니에요.","이유와 근거는 그대로예요.","할 일이 또렷해야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L12_challenge#2','kor',6,1,'u5','L12','g6_1_kor_u5_L12_challenge','lesson_challenge','K6-1-u5-C48',3,'error','auto','자기가 고른 표현 방법에 대해 한 말이에요. 알맞지 않은 말은 누구의 것인가요?',ARRAY['K6-1-u5-X44','K6-1-u5-X26']::text[],false,'{"seq":2,"concept":"K6-1-u5-C48","difficulty":3,"kind":"error","stem":"자기가 고른 표현 방법에 대해 한 말이에요. 알맞지 않은 말은 누구의 것인가요?","options":[{"t":"규리 — 「만화는 그림이 다 말해 주니까 근거는 넣지 않을래.」","correct":true,"mis_target":"K6-1-u5-X44"},{"t":"예찬 — 「표어 아래에 관찰 기록 한 줄을 붙일래.」","mis":"K6-1-u5-X44"},{"t":"슬아 — 「노랫말을 바꿔도 주장과 근거는 그대로 넣을래.」","mis":"K6-1-u5-X26"}],"explanation":["예찬은 근거를 남겼어요.","슬아도 근거를 남겼어요.","만화에도 근거 하나는 남겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L12_challenge#3','kor',6,1,'u5','L12','g6_1_kor_u5_L12_challenge','lesson_challenge','K6-1-u5-C47',3,'mc','auto','「급식실 앞에서 줄이 엉킨다」는 문제를 실천 활동으로 고른 것이 알맞은 까닭은 어느 것인가요?',ARRAY['K6-1-u5-X43','K6-1-u5-X09','K6-1-u5-X29']::text[],false,'{"seq":3,"concept":"K6-1-u5-C47","difficulty":3,"kind":"mc","stem":"「급식실 앞에서 줄이 엉킨다」는 문제를 실천 활동으로 고른 것이 알맞은 까닭은 어느 것인가요?","options":[{"t":"우리 힘으로 바꿀 수 있고, 직접 세거나 물어 근거를 댈 수 있기 때문이다","correct":true},{"t":"우리가 바꿀 수 없는 일이라 더 중요하기 때문이다","mis":"K6-1-u5-X43"},{"t":"근거가 없어도 다들 알기 때문이다","mis":"K6-1-u5-X09"},{"t":"나 혼자만 겪는 일이기 때문이다","mis":"K6-1-u5-X29"}],"explanation":["바꿀 수 있어야 실천이 돼요.","근거가 있어야 해요.","여럿에게 걸린 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L12_challenge#4','kor',6,1,'u5','L12','g6_1_kor_u5_L12_challenge','lesson_challenge','K6-1-u5-C49',3,'mc','auto','「오늘부터 사물함 위를 비워 둡시다」가 들어갈 칸은 어느 것인가요?',ARRAY['K6-1-u5-X45']::text[],false,'{"seq":4,"concept":"K6-1-u5-C49","difficulty":3,"kind":"mc","stem":"「오늘부터 사물함 위를 비워 둡시다」가 들어갈 칸은 어느 것인가요?","options":[{"t":"제안","correct":true},{"t":"의견","mis":"K6-1-u5-X45"},{"t":"까닭","mis":"K6-1-u5-X45"},{"t":"사례","mis":"K6-1-u5-X45"}],"explanation":["의견은 처음 꺼내는 말이에요.","까닭은 왜 그런지예요.","그러니 이렇게 하자는 말은 제안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L12_challenge#5','kor',6,1,'u5','L12','g6_1_kor_u5_L12_challenge','lesson_challenge','K6-1-u5-C51',3,'mc','auto','「어떤 선생님께서 … 궁금해한다고 하셨다」를 믿을 수 있는 근거로 고치는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X47','K6-1-u5-X19','K6-1-u5-X16']::text[],false,'{"seq":5,"concept":"K6-1-u5-C51","difficulty":3,"kind":"mc","stem":"「어떤 선생님께서 … 궁금해한다고 하셨다」를 믿을 수 있는 근거로 고치는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"누구에게 · 언제 · 무엇에 대해 여쭈었는지와 실린 곳을 갖추어 출처를 밝힌다","correct":true},{"t":"「어떤 선생님」을 「많은 선생님」으로 바꾼다","mis":"K6-1-u5-X47"},{"t":"선생님 말씀을 더 세게 바꿔 쓴다","mis":"K6-1-u5-X19"},{"t":"출처 없이 내 생각인 것처럼 쓴다","mis":"K6-1-u5-X16"}],"explanation":["「많은」도 확인할 수 없어요.","뜻을 비틀면 안 돼요.","네 가지를 갖추어야 확인할 수 있어요."],"asset":{"type":"passage","lines":["① 학년이 올라가면 지난해에 보던 책이 쌓인다. 현관에 헌책 나눔 상자를 두면 좋겠다.","② 첫째, 책이 필요한 사람에게 옮겨 가기 때문이다. 어떤 조사에 따르면,","집에 읽지 않는 책을 여러 권 두고 있는 학생이 많다고 한다.","③ 둘째, 종이를 덜 쓰게 되기 때문이다. 우리 반 스물다섯 명 가운데 스물한 명이","헌책을 받아 본 적이 있다고 답했다. (솔바람반(2026), 「헌책 이용 설문」, 학급 게시판.)","④ 셋째, 책을 고르는 재미가 생기기 때문이다. 어떤 선생님께서","남의 손을 거친 책을 아이들이 더 궁금해한다고 하셨다.","⑤ 상자 하나면 된다. 헌책 나눔 상자를 두어 책이 다시 읽히게 하자."],"title":"「헌책 나눔 상자를 두면 좋겠습니다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L12_challenge#6','kor',6,1,'u5','L12','g6_1_kor_u5_L12_challenge','lesson_challenge','K6-1-u5-C50',3,'mc','auto','「말한 대로 해 보기」를 바르게 한 것은 어느 것인가요?',ARRAY['K6-1-u5-X46']::text[],false,'{"seq":6,"concept":"K6-1-u5-C50","difficulty":3,"kind":"mc","stem":"「말한 대로 해 보기」를 바르게 한 것은 어느 것인가요?","options":[{"t":"일주일 동안 사물함 위를 비웠는지 날마다 표시하고, 무엇이 달라졌는지 한 줄로 적었다","correct":true},{"t":"표어를 붙인 뒤 할 일은 다 했다고 여겼다","mis":"K6-1-u5-X46"},{"t":"친구들에게만 하라고 하고 나는 하지 않았다","mis":"K6-1-u5-X46"},{"t":"지켰는지 표시하지 않고 기억에만 맡겼다","mis":"K6-1-u5-X46"}],"explanation":["알리고 끝이 아니에요.","내가 먼저 해 봐요.","날마다 표시해 둬요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L12_challenge#7','kor',6,1,'u5','L12','g6_1_kor_u5_L12_challenge','lesson_challenge','K6-1-u5-C52',2,'mc','auto','밤사이 사람들 모르게 내린 눈을 가리키는 우리말은 어느 것인가요?',ARRAY['K6-1-u5-X48']::text[],false,'{"seq":7,"concept":"K6-1-u5-C52","difficulty":2,"kind":"mc","stem":"밤사이 사람들 모르게 내린 눈을 가리키는 우리말은 어느 것인가요?","options":[{"t":"도둑눈","correct":true},{"t":"숫눈","mis":"K6-1-u5-X48"},{"t":"가루눈","mis":"K6-1-u5-X48"},{"t":"여우비","mis":"K6-1-u5-X48"}],"explanation":["숫눈은 아무도 밟지 않은 눈이에요.","가루눈은 가루처럼 잘게 내리는 눈이에요.","모르게 내렸으니 도둑눈이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L12_challenge#8','kor',6,1,'u5','L12','g6_1_kor_u5_L12_challenge','lesson_challenge','K6-1-u5-C48',4,'mc','auto','사물함 표어 두 가지 가운데 더 설득력 있는 것을 고르고 그 까닭을 바르게 말한 것은 어느 것인가요? ㄱ 「사물함 위를 비웁시다!!!」(커다란 글씨) ㄴ 「사물함 위를 비웁시다 — 사흘 동안 하루 평균 아홉 개가 떨어질 뻔했어요」',ARRAY['K6-1-u5-X44','K6-1-u5-X24']::text[],false,'{"seq":8,"concept":"K6-1-u5-C48","difficulty":4,"kind":"mc","stem":"사물함 표어 두 가지 가운데 더 설득력 있는 것을 고르고 그 까닭을 바르게 말한 것은 어느 것인가요? ㄱ 「사물함 위를 비웁시다!!!」(커다란 글씨) ㄴ 「사물함 위를 비웁시다 — 사흘 동안 하루 평균 아홉 개가 떨어질 뻔했어요」","options":[{"t":"ㄴ — 읽는 사람이 「정말?」 하고 물을 때 보여 줄 사실이 있기 때문이다","correct":true},{"t":"ㄱ — 글씨가 커서 멀리서도 보이기 때문이다","mis":"K6-1-u5-X44"},{"t":"ㄱ — 느낌표가 많아 힘이 느껴지기 때문이다","mis":"K6-1-u5-X44"},{"t":"ㄴ — 글자가 많아 더 길기 때문이다","mis":"K6-1-u5-X24"}],"explanation":["크기는 눈길만 끌어요.","느낌표는 근거가 아니에요.","길이가 아니라 사실이 힘이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L12_challenge#9','kor',6,1,'u5','L12','g6_1_kor_u5_L12_challenge','lesson_challenge','K6-1-u5-C49',4,'essay','teacher','「특별실을 쓰고 뒷정리를 하지 않고 나간다」는 문제로 네 칸 짜임(의견 · 까닭 · 사례 · 제안)의 짧은 글을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u5-C49","difficulty":4,"kind":"essay","stem":"「특별실을 쓰고 뒷정리를 하지 않고 나간다」는 문제로 네 칸 짜임(의견 · 까닭 · 사례 · 제안)의 짧은 글을 쓰세요.","answer_guide":{"answer":"예: 의견 — 특별실을 쓰고 나갈 때 뒷정리를 합시다. 까닭 — 다음에 쓰는 반이 정리부터 하느라 수업 시간이 줄기 때문입니다. 사례 — 우리 반이 일주일 동안 과학실에 들어갈 때마다 세어 보니 다섯 번 가운데 네 번은 의자가 흩어져 있었습니다. 제안 — 나가기 전에 의자 넣기와 재료 정리를 함께 합시다.","scoring_points":["의견을 할 일이 드러나는 한 문장으로 썼는가","까닭과 확인할 수 있는 사례를 썼는가","제안으로 다시 밀어 주었는가"]},"explanation":["하고 싶은 말을 먼저 꺼내요.","까닭과 사례로 받쳐요.","그러니 이렇게 하자고 마무리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L12_challenge#10','kor',6,1,'u5','L12','g6_1_kor_u5_L12_challenge','lesson_challenge','K6-1-u5-C48',4,'essay','teacher','「사람을 움직이는 것은 목소리의 크기가 아니라 근거다」라는 말을, 이 단원에서 배운 것과 이어 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u5-C48","difficulty":4,"kind":"essay","stem":"「사람을 움직이는 것은 목소리의 크기가 아니라 근거다」라는 말을, 이 단원에서 배운 것과 이어 설명하세요.","answer_guide":{"answer":"예: 큰 글씨나 화려한 그림, 큰 목소리는 잠깐 눈길을 끌 뿐 왜 그래야 하는지 알려 주지 못한다. 이 단원에서는 주장 아래에 이유를 세우고, 그 이유를 누구나 확인할 수 있는 근거와 출처로 받쳐야 한다고 배웠다. 「사흘 동안 하루 평균 아홉 개」 같은 사실 하나가 있어야 읽는 사람이 확인하고 생각을 바꾼다. 그래서 어떤 방법으로 펼치든 근거 하나는 남겨야 한다.","scoring_points":["크기나 꾸밈만으로는 설득되지 않는 까닭을 썼는가","이유와 근거 · 출처의 역할을 이어 썼는가","근거를 남겨야 한다는 점을 정리했는가"]},"explanation":["눈에 띄는 것과 설득을 견줘요.","근거의 힘을 떠올려요.","배운 것과 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#1','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C1',1,'mc','auto','어떤 문제에 대해 다른 사람을 설득할 목적으로 쓰는 글을 무엇이라고 하나요?',ARRAY['K6-1-u5-X01']::text[],false,'{"seq":1,"concept":"K6-1-u5-C1","difficulty":1,"kind":"mc","stem":"어떤 문제에 대해 다른 사람을 설득할 목적으로 쓰는 글을 무엇이라고 하나요?","options":[{"t":"주장하는 글","correct":true},{"t":"일기","mis":"K6-1-u5-X01"},{"t":"견학 기록문","mis":"K6-1-u5-X01"},{"t":"이야기","mis":"K6-1-u5-X01"}],"explanation":["일기는 마음을 적어요.","견학 기록문은 보고 들은 것을 써요.","설득하려는 글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#2','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C11',1,'mc','auto','주장하는 글에서 문제를 제기하고 주장을 밝히는 부분은 어디인가요?',ARRAY['K6-1-u5-X10']::text[],false,'{"seq":2,"concept":"K6-1-u5-C11","difficulty":1,"kind":"mc","stem":"주장하는 글에서 문제를 제기하고 주장을 밝히는 부분은 어디인가요?","options":[{"t":"서론","correct":true},{"t":"본론","mis":"K6-1-u5-X10"},{"t":"결론","mis":"K6-1-u5-X10"},{"t":"제목","mis":"K6-1-u5-X10"}],"explanation":["본론은 펼쳐요.","결론은 모아요.","서론에서 꺼내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#3','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C17',1,'mc','auto','남의 것을 가져다 쓰면서 출처를 밝히지 않는 것을 무엇이라고 하나요?',ARRAY['K6-1-u5-X17']::text[],false,'{"seq":3,"concept":"K6-1-u5-C17","difficulty":1,"kind":"mc","stem":"남의 것을 가져다 쓰면서 출처를 밝히지 않는 것을 무엇이라고 하나요?","options":[{"t":"표절","correct":true},{"t":"인용","mis":"K6-1-u5-X17"},{"t":"요약","mis":"K6-1-u5-X17"},{"t":"주장","mis":"K6-1-u5-X17"}],"explanation":["인용은 출처를 밝히며 가져와요.","요약은 줄이는 거예요.","출처를 숨기면 표절이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#4','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C21',1,'ox','auto','출처에는 만든 사람 · 만든 시기 · 자료의 이름 · 실린 곳이 들어가요.',ARRAY['K6-1-u5-X21']::text[],false,'{"seq":4,"concept":"K6-1-u5-C21","difficulty":1,"kind":"ox","stem":"출처에는 만든 사람 · 만든 시기 · 자료의 이름 · 실린 곳이 들어가요.","answer":"O","reason_options":[{"t":"네 가지가 다 있어야 읽는 사람이 직접 찾아가 확인할 수 있기 때문에","correct":true},{"t":"자료의 이름만 있으면 충분하기 때문에","mis":"K6-1-u5-X21"}],"mis":"K6-1-u5-X21","explanation":["네 가지예요.","하나라도 빠지면 찾기 어려워요.","확인할 수 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#5','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C30',1,'ox','auto','「아마 다들 그럴 것이다」라는 짐작도 근거가 될 수 있어요.',ARRAY['K6-1-u5-X09']::text[],false,'{"seq":5,"concept":"K6-1-u5-C30","difficulty":1,"kind":"ox","stem":"「아마 다들 그럴 것이다」라는 짐작도 근거가 될 수 있어요.","answer":"X","reason_options":[{"t":"누구나 찾아가 확인할 수 있는 객관적인 자료가 아니기 때문에","correct":true},{"t":"많은 사람이 그렇게 여기면 객관적이기 때문에","mis":"K6-1-u5-X09"}],"mis":"K6-1-u5-X09","explanation":["짐작은 확인할 수 없어요.","객관적인 자료가 아니에요.","확인할 수 있어야 근거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#6','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C34',1,'mc','auto','글을 쓰는 목적 · 주제 · 읽을 사람을 정하는 단계는 어느 것인가요?',ARRAY['K6-1-u5-X37']::text[],false,'{"seq":6,"concept":"K6-1-u5-C34","difficulty":1,"kind":"mc","stem":"글을 쓰는 목적 · 주제 · 읽을 사람을 정하는 단계는 어느 것인가요?","options":[{"t":"계획하기","correct":true},{"t":"내용 생성하기","mis":"K6-1-u5-X37"},{"t":"표현하기","mis":"K6-1-u5-X37"},{"t":"고쳐쓰기","mis":"K6-1-u5-X37"}],"explanation":["내용 생성하기는 쓸 거리를 모아요.","표현하기는 문장을 써요.","정하는 단계는 계획하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#7','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C42',1,'ox','auto','글을 쓰다가 앞 단계로 되돌아가는 것은 쓰기의 성질이에요.',ARRAY['K6-1-u5-X38']::text[],false,'{"seq":7,"concept":"K6-1-u5-C42","difficulty":1,"kind":"ox","stem":"글을 쓰다가 앞 단계로 되돌아가는 것은 쓰기의 성질이에요.","answer":"O","reason_options":[{"t":"점검과 조정이 어느 단계에서나 일어나 되돌아올 수 있기 때문에","correct":true},{"t":"앞으로만 가야 좋은 글이 되기 때문에","mis":"K6-1-u5-X38"}],"mis":"K6-1-u5-X38","explanation":["되돌아가도 괜찮아요.","어느 단계에서나 점검해요.","되돌아간 단계에서 글이 좋아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#8','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C52',1,'mc','auto','볕이 난 날 잠깐 오다가 그치는 비를 가리키는 우리말은 어느 것인가요?',ARRAY['K6-1-u5-X48']::text[],false,'{"seq":8,"concept":"K6-1-u5-C52","difficulty":1,"kind":"mc","stem":"볕이 난 날 잠깐 오다가 그치는 비를 가리키는 우리말은 어느 것인가요?","options":[{"t":"여우비","correct":true},{"t":"밤비","mis":"K6-1-u5-X48"},{"t":"먼지잼","mis":"K6-1-u5-X48"},{"t":"도둑눈","mis":"K6-1-u5-X48"}],"explanation":["밤비는 밤에 내리는 비예요.","먼지잼은 아주 조금 오는 비예요.","볕 속에 잠깐 오는 비예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#9','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C51',2,'mc','auto','「헌책 나눔 상자」 글에서 출처가 제대로 밝혀지지 않은 곳은 어느 것인가요?',ARRAY['K6-1-u5-X47','K6-1-u5-X02']::text[],false,'{"seq":9,"concept":"K6-1-u5-C51","difficulty":2,"kind":"mc","stem":"「헌책 나눔 상자」 글에서 출처가 제대로 밝혀지지 않은 곳은 어느 것인가요?","options":[{"t":"어떤 조사에 따르면","correct":true},{"t":"솔바람반(2026), 「헌책 이용 설문」, 학급 게시판","mis":"K6-1-u5-X47"},{"t":"우리 반 스물다섯 명 가운데 스물한 명","mis":"K6-1-u5-X47"},{"t":"헌책 나눔 상자를 두어 책이 다시 읽히게 하자","mis":"K6-1-u5-X02"}],"explanation":["네 가지를 갖춘 출처예요.","출처가 붙은 조사 결과예요.","누가 · 언제 한 조사인지 없어요."],"asset":{"type":"passage","lines":["① 학년이 올라가면 지난해에 보던 책이 쌓인다. 현관에 헌책 나눔 상자를 두면 좋겠다.","② 첫째, 책이 필요한 사람에게 옮겨 가기 때문이다. 어떤 조사에 따르면,","집에 읽지 않는 책을 여러 권 두고 있는 학생이 많다고 한다.","③ 둘째, 종이를 덜 쓰게 되기 때문이다. 우리 반 스물다섯 명 가운데 스물한 명이","헌책을 받아 본 적이 있다고 답했다. (솔바람반(2026), 「헌책 이용 설문」, 학급 게시판.)","④ 셋째, 책을 고르는 재미가 생기기 때문이다. 어떤 선생님께서","남의 손을 거친 책을 아이들이 더 궁금해한다고 하셨다.","⑤ 상자 하나면 된다. 헌책 나눔 상자를 두어 책이 다시 읽히게 하자."],"title":"「헌책 나눔 상자를 두면 좋겠습니다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#10','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C9',2,'mc','auto','「헌책 나눔 상자」 글의 이유 가운데 주장과 이어지는 것은 어느 것인가요?',ARRAY['K6-1-u5-X08']::text[],false,'{"seq":10,"concept":"K6-1-u5-C9","difficulty":2,"kind":"mc","stem":"「헌책 나눔 상자」 글의 이유 가운데 주장과 이어지는 것은 어느 것인가요?","options":[{"t":"책이 필요한 사람에게 옮겨 가기 때문이다","correct":true},{"t":"현관이 넓기 때문이다","mis":"K6-1-u5-X08"},{"t":"책을 많이 읽으면 키가 크기 때문이다","mis":"K6-1-u5-X08"},{"t":"헌책은 값이 싸기 때문이다","mis":"K6-1-u5-X08"}],"explanation":["현관 넓이는 이유가 아니에요.","주장과 이어지지 않아요.","나눔 상자의 쓸모와 이어져요."],"asset":{"type":"passage","lines":["① 학년이 올라가면 지난해에 보던 책이 쌓인다. 현관에 헌책 나눔 상자를 두면 좋겠다.","② 첫째, 책이 필요한 사람에게 옮겨 가기 때문이다. 어떤 조사에 따르면,","집에 읽지 않는 책을 여러 권 두고 있는 학생이 많다고 한다.","③ 둘째, 종이를 덜 쓰게 되기 때문이다. 우리 반 스물다섯 명 가운데 스물한 명이","헌책을 받아 본 적이 있다고 답했다. (솔바람반(2026), 「헌책 이용 설문」, 학급 게시판.)","④ 셋째, 책을 고르는 재미가 생기기 때문이다. 어떤 선생님께서","남의 손을 거친 책을 아이들이 더 궁금해한다고 하셨다.","⑤ 상자 하나면 된다. 헌책 나눔 상자를 두어 책이 다시 읽히게 하자."],"title":"「헌책 나눔 상자를 두면 좋겠습니다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#11','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C2',2,'mc','auto','우재 초고의 주장은 어느 것인가요?',ARRAY['K6-1-u5-X02','K6-1-u5-X03']::text[],false,'{"seq":11,"concept":"K6-1-u5-C2","difficulty":2,"kind":"mc","stem":"우재 초고의 주장은 어느 것인가요?","options":[{"t":"급식실 앞에서는 한 줄로 서야 한다","correct":true},{"t":"점심시간 급식실 앞은 늘 북적인다","mis":"K6-1-u5-X02"},{"t":"밀치다 넘어질 일이 줄기 때문이다","mis":"K6-1-u5-X03"},{"t":"열다섯 명이 밀린 적이 있다고 답했다","mis":"K6-1-u5-X03"}],"explanation":["문제 상황이에요.","이유예요.","하자고 내세운 말이에요."],"asset":{"type":"passage","lines":["① 점심시간 급식실 앞은 늘 북적인다. 줄이 두세 갈래로 엉켜 서로 밀치기도 한다.","급식실 앞에서는 한 줄로 서야 한다.","② 첫째, 한 줄로 서면 밀치다 넘어질 일이 줄기 때문이다. 우리 반 스물네 명","가운데 열다섯 명이 급식실 앞에서 밀린 적이 있다고 답했다.","(새솔반(2026), 「급식실 앞 줄서기 설문」, 학급 게시판.)","③ 둘째, 먼저 온 사람이 먼저 먹을 수 있기 때문이다. 어떤 조사에 따르면","줄이 엉키면 늦게 온 사람이 먼저 들어가는 일이 많다고 한다.","급식실 반찬은 골고루 먹어야 키가 큰다."],"title":"우재의 초고 「급식실 앞에서는 한 줄로 섭시다」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#12','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C37',2,'mc','auto','우재 초고 앞부분에서 통일성을 깨는 문장은 어느 것인가요?',ARRAY['K6-1-u5-X33']::text[],false,'{"seq":12,"concept":"K6-1-u5-C37","difficulty":2,"kind":"mc","stem":"우재 초고 앞부분에서 통일성을 깨는 문장은 어느 것인가요?","options":[{"t":"급식실 반찬은 골고루 먹어야 키가 큰다","correct":true},{"t":"급식실 앞에서는 한 줄로 서야 한다","mis":"K6-1-u5-X33"},{"t":"먼저 온 사람이 먼저 먹을 수 있기 때문이다","mis":"K6-1-u5-X33"},{"t":"줄이 두세 갈래로 엉켜 서로 밀치기도 한다","mis":"K6-1-u5-X33"}],"explanation":["글의 주장이에요.","줄서기와 이어진 이유예요.","옳은 말이어도 줄서기와 이어지지 않아요."],"asset":{"type":"passage","lines":["① 점심시간 급식실 앞은 늘 북적인다. 줄이 두세 갈래로 엉켜 서로 밀치기도 한다.","급식실 앞에서는 한 줄로 서야 한다.","② 첫째, 한 줄로 서면 밀치다 넘어질 일이 줄기 때문이다. 우리 반 스물네 명","가운데 열다섯 명이 급식실 앞에서 밀린 적이 있다고 답했다.","(새솔반(2026), 「급식실 앞 줄서기 설문」, 학급 게시판.)","③ 둘째, 먼저 온 사람이 먼저 먹을 수 있기 때문이다. 어떤 조사에 따르면","줄이 엉키면 늦게 온 사람이 먼저 들어가는 일이 많다고 한다.","급식실 반찬은 골고루 먹어야 키가 큰다."],"title":"우재의 초고 「급식실 앞에서는 한 줄로 섭시다」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#13','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C46',2,'mc','auto','우재 초고 뒷부분에서 띄어쓰기를 바르게 고친 것은 어느 것인가요?',ARRAY['K6-1-u5-X42']::text[],false,'{"seq":13,"concept":"K6-1-u5-C46","difficulty":2,"kind":"mc","stem":"우재 초고 뒷부분에서 띄어쓰기를 바르게 고친 것은 어느 것인가요?","options":[{"t":"「한줄로」 → 「한 줄로」","correct":true},{"t":"「점심시간의」 → 「점심 시간의」","mis":"K6-1-u5-X42"},{"t":"「살펴보았다」 → 「살펴 보았다」","mis":"K6-1-u5-X42"},{"t":"「편안한」 → 「편 안한」","mis":"K6-1-u5-X42"}],"explanation":["「점심시간」은 붙여 써요.","「살펴보다」는 한 낱말이에요.","「한 줄」은 띄어 써요."],"asset":{"type":"passage","lines":["④ 셋째, 줄을 정리하시는 선생님의 일이 줄기 때문이다. 급식 지도를 맡으신","선생님께서 엉킨 줄을 푸는 데 점심시간의 많은 부분을 쓰신다고 하셨다.","(최○○ 선생님 면담(2026), 「급식 지도 이야기」, 급식실.)","⑤ 지금까지 세 가지 까닭을 살펴보았다. 한 줄로 서는 일은 어렵지 않다.","급식실 앞에서는 한줄로 서서 모두가 편안한 점심시간을 만들자.","줄을 서지 않고 끼어드는 사람은 정말 이기적인 사람이다."],"title":"우재의 초고 — 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#14','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C42',2,'mc','auto','대화에서 하영이가 「처음부터가 아니라 잠깐 돌아가는 거야」라고 한 말의 뜻은 어느 것인가요?',ARRAY['K6-1-u5-X38','K6-1-u5-X07']::text[],false,'{"seq":14,"concept":"K6-1-u5-C42","difficulty":2,"kind":"mc","stem":"대화에서 하영이가 「처음부터가 아니라 잠깐 돌아가는 거야」라고 한 말의 뜻은 어느 것인가요?","options":[{"t":"앞 단계로 되돌아가는 것은 실패가 아니라 쓰기의 성질이다","correct":true},{"t":"되돌아가면 처음부터 다시 써야 한다","mis":"K6-1-u5-X38"},{"t":"다 쓴 글은 고치지 않아야 한다","mis":"K6-1-u5-X07"},{"t":"되돌아가는 것은 계획이 틀렸다는 뜻이다","mis":"K6-1-u5-X38"}],"explanation":["처음부터가 아니에요.","고쳐도 괜찮아요.","되돌아가는 것은 정상이에요."],"asset":{"type":"speech","turns":[{"who":"우재","text":"다 썼는데 둘째 이유의 근거가 「어떤 조사에 따르면」이야. 다시 자료를 찾으면 처음부터 다시 하는 거잖아."},{"who":"하영","text":"처음부터가 아니라 내용 생성하기로 잠깐 돌아가는 거야. 우리 반에서 직접 세어 보면 되지."},{"who":"우재","text":"그리고 이 글은 동생들도 읽을 텐데 「급식 지도」 같은 말은 어려울까?"},{"who":"하영","text":"그건 계획하기에서 읽을 사람을 다시 보는 거네. 고칠 곳을 찾았다는 건 네가 볼 줄 알게 됐다는 뜻이야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#15','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C49',2,'mc','auto','하영이의 네 칸 글에서 「우리 반 스물네 명 가운데 열다섯 명이 밀린 적이 있다고 답했습니다」가 들어간 칸은 어느 것인가요?',ARRAY['K6-1-u5-X45']::text[],false,'{"seq":15,"concept":"K6-1-u5-C49","difficulty":2,"kind":"mc","stem":"하영이의 네 칸 글에서 「우리 반 스물네 명 가운데 열다섯 명이 밀린 적이 있다고 답했습니다」가 들어간 칸은 어느 것인가요?","options":[{"t":"사례","correct":true},{"t":"의견","mis":"K6-1-u5-X45"},{"t":"까닭","mis":"K6-1-u5-X45"},{"t":"제안","mis":"K6-1-u5-X45"}],"explanation":["의견은 하고 싶은 말이에요.","까닭은 왜 그런지예요.","조사 결과는 사례 칸에 들어가요."],"asset":{"type":"passage","lines":["표어 — 「한 줄이면 모두가 먼저」","의견 — 급식실 앞에서는 한 줄로 섭시다.","까닭 — 엉킨 줄에서는 밀려 넘어질 수 있기 때문입니다.","사례 — 우리 반 스물네 명 가운데 열다섯 명이 밀린 적이 있다고 답했습니다.","제안 — 내일 점심부터 급식실 앞에서는 한 줄로 서 봅시다."],"title":"하영이 만든 표어와 네 칸 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#16','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C52',2,'match','auto','비와 눈이 내린 날의 문장과 알맞은 우리말을 이으세요.','{}'::text[],false,'{"seq":16,"concept":"K6-1-u5-C52","difficulty":2,"kind":"match","stem":"비와 눈이 내린 날의 문장과 알맞은 우리말을 이으세요.","pairs":[{"l":"ㄱ","r":"여우비"},{"l":"ㄴ","r":"도둑눈"},{"l":"ㄷ","r":"먼지잼"},{"l":"ㄹ","r":"숫눈"}],"mis":"K6-1-u5-X48","explanation":["볕 속에 잠깐 온 비예요.","모르게 내린 눈이에요.","조금 온 비와 밟지 않은 눈이에요."],"asset":{"type":"passage","lines":["ㄱ. 볕이 쨍한데 잠깐 비가 오다 그쳤다.","ㄴ. 아침에 일어나 보니 밤사이 아무도 모르게 눈이 쌓여 있었다.","ㄷ. 먼지나 겨우 가라앉힐 만큼 비가 아주 조금 내렸다.","ㄹ. 운동장에 쌓인 눈을 아직 아무도 밟지 않았다."],"title":"비와 눈이 내린 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#17','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C15',3,'mc','auto','「우산꽂이에 꽂자」는 글에 출처를 갖춘 「우리 반 아침 독서 설문」을 근거로 붙였어요. 이 근거를 판단한 말로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X14','K6-1-u5-X15']::text[],false,'{"seq":17,"concept":"K6-1-u5-C15","difficulty":3,"kind":"mc","stem":"「우산꽂이에 꽂자」는 글에 출처를 갖춘 「우리 반 아침 독서 설문」을 근거로 붙였어요. 이 근거를 판단한 말로 알맞은 것은 어느 것인가요?","options":[{"t":"출처는 갖추었지만 이유와 관련이 없어 타당한 근거가 아니다","correct":true},{"t":"출처가 있으니 타당한 근거이다","mis":"K6-1-u5-X14"},{"t":"설문이니 어느 이유에 붙여도 된다","mis":"K6-1-u5-X14"},{"t":"그냥 그럴 것 같아 타당하다","mis":"K6-1-u5-X15"}],"explanation":["출처가 곧 타당함은 아니에요.","이유와 이어져야 해요.","판단에는 까닭이 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#18','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C19',3,'mc','auto','사서 선생님이 「늦게 온 책을 다시 정리하는 데 시간이 많이 든다」고 하셨어요. 출처를 밝혔어도 잘못 옮긴 것은 어느 것인가요?',ARRAY['K6-1-u5-X19']::text[],false,'{"seq":18,"concept":"K6-1-u5-C19","difficulty":3,"kind":"mc","stem":"사서 선생님이 「늦게 온 책을 다시 정리하는 데 시간이 많이 든다」고 하셨어요. 출처를 밝혔어도 잘못 옮긴 것은 어느 것인가요?","options":[{"t":"사서 선생님께서 늦게 온 책 때문에 도서관 일을 할 수 없다고 하셨다","correct":true},{"t":"사서 선생님께서 늦게 온 책을 다시 정리하는 데 시간이 많이 든다고 하셨다","mis":"K6-1-u5-X19"},{"t":"늦게 돌아온 책은 정리에 시간이 많이 든다고 하셨다","mis":"K6-1-u5-X19"},{"t":"사서 선생님 말씀으로는 늦은 책 정리에 시간이 많이 든다","mis":"K6-1-u5-X19"}],"explanation":["뜻 그대로예요.","뜻 그대로예요.","「많이 든다」를 「할 수 없다」로 과장했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#19','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C27',3,'mc','auto','「급식실을 더 좋게 만듭시다」를 명료한 주장으로 고친 것은 어느 것인가요?',ARRAY['K6-1-u5-X27','K6-1-u5-X02']::text[],false,'{"seq":19,"concept":"K6-1-u5-C27","difficulty":3,"kind":"mc","stem":"「급식실을 더 좋게 만듭시다」를 명료한 주장으로 고친 것은 어느 것인가요?","options":[{"t":"급식실 앞에서는 한 줄로 섭시다","correct":true},{"t":"급식실을 아름답게 꾸밉시다","mis":"K6-1-u5-X27"},{"t":"급식실에 대해 생각해 봅시다","mis":"K6-1-u5-X27"},{"t":"급식실 문제가 많습니다","mis":"K6-1-u5-X02"}],"explanation":["주장이 다른 쪽으로 바뀌었어요.","무엇을 하자는지 흐려요.","문제 상황이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#20','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C43',3,'error','auto','우재의 점검 질문이에요. 단계와 질문이 어긋난 것은 누구의 것인가요?',ARRAY['K6-1-u5-X39']::text[],false,'{"seq":20,"concept":"K6-1-u5-C43","difficulty":3,"kind":"error","stem":"우재의 점검 질문이에요. 단계와 질문이 어긋난 것은 누구의 것인가요?","options":[{"t":"하영 — 내용 생성하기: 「띄어쓰기가 틀리지 않았나요?」","correct":true,"mis_target":"K6-1-u5-X39"},{"t":"우재 — 계획하기: 「읽을 사람이 누구인지 정했나요?」","mis":"K6-1-u5-X39"},{"t":"민찬 — 내용 조직하기: 「주장 · 이유 · 근거가 짜임에 맞게 놓였나요?」","mis":"K6-1-u5-X39"}],"explanation":["우재는 바르게 붙였어요.","민찬도 바르게 붙였어요.","띄어쓰기는 내용 생성하기 질문이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#21','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C45',3,'mc','auto','우재 초고의 고칠 곳 가운데 글 수준에 해당하는 것은 어느 것인가요?',ARRAY['K6-1-u5-X41']::text[],false,'{"seq":21,"concept":"K6-1-u5-C45","difficulty":3,"kind":"mc","stem":"우재 초고의 고칠 곳 가운데 글 수준에 해당하는 것은 어느 것인가요?","options":[{"t":"주제와 이어지지 않는 「급식실 반찬」 문장이 섞여 글 전체의 통일성이 흐려졌다","correct":true},{"t":"「한줄로」를 「한 줄로」로 띄어 써야 한다","mis":"K6-1-u5-X41"},{"t":"④문단에 문장 하나를 보태야 한다","mis":"K6-1-u5-X41"},{"t":"「이기적인」이라는 낱말 하나만 바꾼다","mis":"K6-1-u5-X41"}],"explanation":["띄어쓰기는 문장과 낱말 수준이에요.","한 문단 안의 일이에요.","주제가 드러나는지는 글 수준이에요."],"asset":{"type":"passage","lines":["① 점심시간 급식실 앞은 늘 북적인다. 줄이 두세 갈래로 엉켜 서로 밀치기도 한다.","급식실 앞에서는 한 줄로 서야 한다.","② 첫째, 한 줄로 서면 밀치다 넘어질 일이 줄기 때문이다. 우리 반 스물네 명","가운데 열다섯 명이 급식실 앞에서 밀린 적이 있다고 답했다.","(새솔반(2026), 「급식실 앞 줄서기 설문」, 학급 게시판.)","③ 둘째, 먼저 온 사람이 먼저 먹을 수 있기 때문이다. 어떤 조사에 따르면","줄이 엉키면 늦게 온 사람이 먼저 들어가는 일이 많다고 한다.","급식실 반찬은 골고루 먹어야 키가 큰다."],"title":"우재의 초고 「급식실 앞에서는 한 줄로 섭시다」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#22','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C48',3,'mc','auto','「한 줄이면 모두가 먼저」 표어만 붙이고 아래 네 칸 글을 뗐어요. 무엇이 약해지나요?',ARRAY['K6-1-u5-X44','K6-1-u5-X47']::text[],false,'{"seq":22,"concept":"K6-1-u5-C48","difficulty":3,"kind":"mc","stem":"「한 줄이면 모두가 먼저」 표어만 붙이고 아래 네 칸 글을 뗐어요. 무엇이 약해지나요?","options":[{"t":"「정말?」이라는 물음에 보여 줄 근거가 사라져 설득의 힘이 약해진다","correct":true},{"t":"글씨가 작아져 설득이 약해진다","mis":"K6-1-u5-X44"},{"t":"표어가 짧아져 주장이 사라진다","mis":"K6-1-u5-X47"},{"t":"약해지는 것이 없다","mis":"K6-1-u5-X44"}],"explanation":["크기 문제가 아니에요.","주장은 표어에 남아 있어요.","근거가 빠졌어요."],"asset":{"type":"passage","lines":["표어 — 「한 줄이면 모두가 먼저」","의견 — 급식실 앞에서는 한 줄로 섭시다.","까닭 — 엉킨 줄에서는 밀려 넘어질 수 있기 때문입니다.","사례 — 우리 반 스물네 명 가운데 열다섯 명이 밀린 적이 있다고 답했습니다.","제안 — 내일 점심부터 급식실 앞에서는 한 줄로 서 봅시다."],"title":"하영이 만든 표어와 네 칸 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#23','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C37',4,'mc','auto','우재 초고 전체를 가장 알맞게 평가한 것은 어느 것인가요?',ARRAY['K6-1-u5-X14','K6-1-u5-X40','K6-1-u5-X41']::text[],false,'{"seq":23,"concept":"K6-1-u5-C37","difficulty":4,"kind":"mc","stem":"우재 초고 전체를 가장 알맞게 평가한 것은 어느 것인가요?","options":[{"t":"짜임과 이유는 갖추었지만, 통일성을 깨는 문장 · 흐린 출처 · 헐뜯는 말 · 띄어쓰기를 고쳐야 한다","correct":true},{"t":"근거가 셋이니 고칠 곳이 없다","mis":"K6-1-u5-X14"},{"t":"고칠 곳이 많으니 버리고 새로 써야 한다","mis":"K6-1-u5-X40"},{"t":"맞춤법만 고치면 좋은 글이 된다","mis":"K6-1-u5-X41"}],"explanation":["출처가 흐린 근거가 있어요.","버리지 않고 고쳐요.","큰 고침도 필요해요."],"asset":{"type":"passage","lines":["① 점심시간 급식실 앞은 늘 북적인다. 줄이 두세 갈래로 엉켜 서로 밀치기도 한다.","급식실 앞에서는 한 줄로 서야 한다.","② 첫째, 한 줄로 서면 밀치다 넘어질 일이 줄기 때문이다. 우리 반 스물네 명","가운데 열다섯 명이 급식실 앞에서 밀린 적이 있다고 답했다.","(새솔반(2026), 「급식실 앞 줄서기 설문」, 학급 게시판.)","③ 둘째, 먼저 온 사람이 먼저 먹을 수 있기 때문이다. 어떤 조사에 따르면","줄이 엉키면 늦게 온 사람이 먼저 들어가는 일이 많다고 한다.","급식실 반찬은 골고루 먹어야 키가 큰다."],"title":"우재의 초고 「급식실 앞에서는 한 줄로 섭시다」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#24','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C37',4,'essay','teacher','우재 초고 앞부분에서 통일성을 깨는 문장을 찾아 쓰고, 그 문장을 어떻게 할지와 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u5-C37","difficulty":4,"kind":"essay","stem":"우재 초고 앞부분에서 통일성을 깨는 문장을 찾아 쓰고, 그 문장을 어떻게 할지와 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 「급식실 반찬은 골고루 먹어야 키가 큰다.」가 통일성을 깬다. 이 문장은 옳은 말이지만 「급식실 앞에서는 한 줄로 서자」는 주제와 이어지지 않는다. 그래서 이 문장은 지운다. 주제와 멀어진 내용이 섞이면 읽는 사람이 글쓴이가 무엇을 주장하는지 헷갈리기 때문이다.","scoring_points":["통일성을 깨는 문장을 찾았는가","지우거나 고치는 방법을 썼는가","주제와 이어지지 않는다는 까닭을 썼는가"]},"explanation":["주제를 먼저 잡아요.","주제와 먼 문장을 찾아요.","까닭을 붙여요."],"asset":{"type":"passage","lines":["① 점심시간 급식실 앞은 늘 북적인다. 줄이 두세 갈래로 엉켜 서로 밀치기도 한다.","급식실 앞에서는 한 줄로 서야 한다.","② 첫째, 한 줄로 서면 밀치다 넘어질 일이 줄기 때문이다. 우리 반 스물네 명","가운데 열다섯 명이 급식실 앞에서 밀린 적이 있다고 답했다.","(새솔반(2026), 「급식실 앞 줄서기 설문」, 학급 게시판.)","③ 둘째, 먼저 온 사람이 먼저 먹을 수 있기 때문이다. 어떤 조사에 따르면","줄이 엉키면 늦게 온 사람이 먼저 들어가는 일이 많다고 한다.","급식실 반찬은 골고루 먹어야 키가 큰다."],"title":"우재의 초고 「급식실 앞에서는 한 줄로 섭시다」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#25','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C42',4,'essay','teacher','이 단원의 이름 「자신의 글쓰기 과정을 살펴봐요」가 무엇을 뜻하는지, 쓰기 과정 다섯 단계와 「되돌아감」을 넣어 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u5-C42","difficulty":4,"kind":"essay","stem":"이 단원의 이름 「자신의 글쓰기 과정을 살펴봐요」가 무엇을 뜻하는지, 쓰기 과정 다섯 단계와 「되돌아감」을 넣어 설명하세요.","answer_guide":{"answer":"예: 글쓰기는 계획하기 · 내용 생성하기 · 내용 조직하기 · 표현하기 · 고쳐쓰기의 다섯 단계를 지나지만, 한 줄로 곧게 가는 길이 아니다. 쓰다가 근거가 약하면 내용 생성하기로, 읽을 사람이 달라지면 계획하기로 되돌아간다. 이 단원은 완성된 글 한 편보다 내가 어느 단계에서 무엇을 했고 어디로 되돌아갔는지 스스로 살펴보는 법을 배우는 단원이다.","scoring_points":["쓰기 과정 다섯 단계를 썼는가","되돌아감이 정상이라는 점을 썼는가","완성보다 과정을 살펴본다는 뜻을 정리했는가"]},"explanation":["다섯 단계를 떠올려요.","되돌아가는 예를 넣어요.","단원 이름의 뜻을 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#1','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C2',1,'mc','auto','「이유를 뒷받침하는 객관적인 자료」를 무엇이라고 하나요?',ARRAY['K6-1-u5-X03']::text[],false,'{"seq":1,"concept":"K6-1-u5-C2","difficulty":1,"kind":"mc","stem":"「이유를 뒷받침하는 객관적인 자료」를 무엇이라고 하나요?","options":[{"t":"근거","correct":true},{"t":"주장","mis":"K6-1-u5-X03"},{"t":"이유","mis":"K6-1-u5-X03"},{"t":"제목","mis":"K6-1-u5-X03"}],"explanation":["주장은 의견이에요.","이유는 내 까닭이에요.","밖에서 가져온 자료가 근거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#2','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C12',1,'mc','auto','이유와 근거, 그리고 그 출처를 제시하는 부분은 어디인가요?',ARRAY['K6-1-u5-X10']::text[],false,'{"seq":2,"concept":"K6-1-u5-C12","difficulty":1,"kind":"mc","stem":"이유와 근거, 그리고 그 출처를 제시하는 부분은 어디인가요?","options":[{"t":"본론","correct":true},{"t":"서론","mis":"K6-1-u5-X10"},{"t":"결론","mis":"K6-1-u5-X10"},{"t":"제목","mis":"K6-1-u5-X10"}],"explanation":["서론은 문제와 주장을 밝혀요.","결론은 요약하고 강조해요.","본론에서 주장을 펼쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#3','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C20',1,'mc','auto','저작물을 만든 사람을 무엇이라고 하나요?',ARRAY['K6-1-u5-X20']::text[],false,'{"seq":3,"concept":"K6-1-u5-C20","difficulty":1,"kind":"mc","stem":"저작물을 만든 사람을 무엇이라고 하나요?","options":[{"t":"저작자","correct":true},{"t":"저작물","mis":"K6-1-u5-X20"},{"t":"저작권","mis":"K6-1-u5-X20"},{"t":"독자","mis":"K6-1-u5-X20"}],"explanation":["저작물은 만든 것이에요.","저작권은 권리예요.","만든 사람은 저작자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#4','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C21',1,'mc','auto','「새솔반(2026), 「급식실 앞 줄서기 설문」, 학급 게시판.」에서 「학급 게시판」은 무엇에 해당하나요?',ARRAY['K6-1-u5-X21']::text[],false,'{"seq":4,"concept":"K6-1-u5-C21","difficulty":1,"kind":"mc","stem":"「새솔반(2026), 「급식실 앞 줄서기 설문」, 학급 게시판.」에서 「학급 게시판」은 무엇에 해당하나요?","options":[{"t":"자료가 실린 곳","correct":true},{"t":"자료를 만든 사람","mis":"K6-1-u5-X21"},{"t":"자료를 만든 시기","mis":"K6-1-u5-X21"},{"t":"인용한 자료의 이름","mis":"K6-1-u5-X21"}],"explanation":["만든 쪽은 맨 앞이에요.","시기는 괄호 안이에요.","끝은 실린 곳이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#5','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C27',1,'mc','auto','다음 가운데 무엇을 하자는지 한 가지로 읽히는 주장은 어느 것인가요?',ARRAY['K6-1-u5-X27']::text[],false,'{"seq":5,"concept":"K6-1-u5-C27","difficulty":1,"kind":"mc","stem":"다음 가운데 무엇을 하자는지 한 가지로 읽히는 주장은 어느 것인가요?","options":[{"t":"빈 교실을 나올 때 불을 끕시다","correct":true},{"t":"교실을 더 아낍시다","mis":"K6-1-u5-X27"},{"t":"학교를 좋게 만듭시다","mis":"K6-1-u5-X27"},{"t":"모두 노력합시다","mis":"K6-1-u5-X27"}],"explanation":["무엇을 아끼자는지 흐려요.","사람마다 다르게 읽어요.","할 일이 한 가지로 읽혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#6','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C36',1,'mc','auto','쓸 거리를 떠올리고 자료를 모으는 단계는 어느 것인가요?',ARRAY['K6-1-u5-X37']::text[],false,'{"seq":6,"concept":"K6-1-u5-C36","difficulty":1,"kind":"mc","stem":"쓸 거리를 떠올리고 자료를 모으는 단계는 어느 것인가요?","options":[{"t":"내용 생성하기","correct":true},{"t":"계획하기","mis":"K6-1-u5-X37"},{"t":"내용 조직하기","mis":"K6-1-u5-X37"},{"t":"고쳐쓰기","mis":"K6-1-u5-X37"}],"explanation":["계획하기는 정하는 단계예요.","조직하기는 늘어놓아요.","모으는 단계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#7','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C40',1,'ox','auto','점검은 글을 다 쓴 뒤에 한 번만 하는 일이에요.',ARRAY['K6-1-u5-X36']::text[],false,'{"seq":7,"concept":"K6-1-u5-C40","difficulty":1,"kind":"ox","stem":"점검은 글을 다 쓴 뒤에 한 번만 하는 일이에요.","answer":"X","reason_options":[{"t":"쓰는 도중 어느 단계에서나 방향을 다시 잡는 일이기 때문에","correct":true},{"t":"다 쓴 글을 채점하는 일이기 때문에","mis":"K6-1-u5-X36"}],"mis":"K6-1-u5-X36","explanation":["도중에도 해요.","채점이 아니에요.","방향을 다시 잡아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#8','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C52',1,'mc','auto','쌓인 뒤에 아직 아무도 밟지 않은 눈을 가리키는 우리말은 어느 것인가요?',ARRAY['K6-1-u5-X48']::text[],false,'{"seq":8,"concept":"K6-1-u5-C52","difficulty":1,"kind":"mc","stem":"쌓인 뒤에 아직 아무도 밟지 않은 눈을 가리키는 우리말은 어느 것인가요?","options":[{"t":"숫눈","correct":true},{"t":"도둑눈","mis":"K6-1-u5-X48"},{"t":"가루눈","mis":"K6-1-u5-X48"},{"t":"여우비","mis":"K6-1-u5-X48"}],"explanation":["도둑눈은 모르게 내린 눈이에요.","가루눈은 잘게 내리는 눈이에요.","아무도 밟지 않은 눈이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#9','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C51',2,'mc','auto','④문단의 「어떤 선생님께서」가 근거로 힘을 잃는 까닭은 어느 것인가요?',ARRAY['K6-1-u5-X23','K6-1-u5-X25','K6-1-u5-X24']::text[],false,'{"seq":9,"concept":"K6-1-u5-C51","difficulty":2,"kind":"mc","stem":"④문단의 「어떤 선생님께서」가 근거로 힘을 잃는 까닭은 어느 것인가요?","options":[{"t":"말한 사람과 여쭌 때가 없어 전문가 의견이 아니라 떠도는 말이 되기 때문이다","correct":true},{"t":"선생님 말씀은 근거가 될 수 없기 때문이다","mis":"K6-1-u5-X23"},{"t":"문장이 길기 때문이다","mis":"K6-1-u5-X25"},{"t":"선생님이 한 분뿐이기 때문이다","mis":"K6-1-u5-X24"}],"explanation":["면담도 근거가 돼요.","길이 때문이 아니에요.","누구 · 언제가 빠졌어요."],"asset":{"type":"passage","lines":["① 학년이 올라가면 지난해에 보던 책이 쌓인다. 현관에 헌책 나눔 상자를 두면 좋겠다.","② 첫째, 책이 필요한 사람에게 옮겨 가기 때문이다. 어떤 조사에 따르면,","집에 읽지 않는 책을 여러 권 두고 있는 학생이 많다고 한다.","③ 둘째, 종이를 덜 쓰게 되기 때문이다. 우리 반 스물다섯 명 가운데 스물한 명이","헌책을 받아 본 적이 있다고 답했다. (솔바람반(2026), 「헌책 이용 설문」, 학급 게시판.)","④ 셋째, 책을 고르는 재미가 생기기 때문이다. 어떤 선생님께서","남의 손을 거친 책을 아이들이 더 궁금해한다고 하셨다.","⑤ 상자 하나면 된다. 헌책 나눔 상자를 두어 책이 다시 읽히게 하자."],"title":"「헌책 나눔 상자를 두면 좋겠습니다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#10','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C8',2,'match','auto','헌책 글의 이유와 그것을 뒷받침한 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u5-C8","difficulty":2,"kind":"match","stem":"헌책 글의 이유와 그것을 뒷받침한 내용을 알맞게 이으세요.","pairs":[{"l":"필요한 사람에게 옮겨 간다","r":"읽지 않는 책을 둔 학생이 많다"},{"l":"종이를 덜 쓰게 된다","r":"스물한 명이 헌책을 받아 본 적이 있다"},{"l":"책 고르는 재미가 생긴다","r":"남의 손을 거친 책을 더 궁금해한다"}],"mis":"K6-1-u5-X03","explanation":["옮겨 감은 쌓인 책과 이어져요.","종이는 헌책 이용과 이어져요.","재미는 궁금함과 이어져요."],"asset":{"type":"passage","lines":["① 학년이 올라가면 지난해에 보던 책이 쌓인다. 현관에 헌책 나눔 상자를 두면 좋겠다.","② 첫째, 책이 필요한 사람에게 옮겨 가기 때문이다. 어떤 조사에 따르면,","집에 읽지 않는 책을 여러 권 두고 있는 학생이 많다고 한다.","③ 둘째, 종이를 덜 쓰게 되기 때문이다. 우리 반 스물다섯 명 가운데 스물한 명이","헌책을 받아 본 적이 있다고 답했다. (솔바람반(2026), 「헌책 이용 설문」, 학급 게시판.)","④ 셋째, 책을 고르는 재미가 생기기 때문이다. 어떤 선생님께서","남의 손을 거친 책을 아이들이 더 궁금해한다고 하셨다.","⑤ 상자 하나면 된다. 헌책 나눔 상자를 두어 책이 다시 읽히게 하자."],"title":"「헌책 나눔 상자를 두면 좋겠습니다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#11','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C8',2,'mc','auto','우재 초고 ②문단에서 근거에 해당하는 것은 어느 것인가요?',ARRAY['K6-1-u5-X03','K6-1-u5-X02']::text[],false,'{"seq":11,"concept":"K6-1-u5-C8","difficulty":2,"kind":"mc","stem":"우재 초고 ②문단에서 근거에 해당하는 것은 어느 것인가요?","options":[{"t":"스물네 명 가운데 열다섯 명이 밀린 적이 있다는 설문 결과","correct":true},{"t":"한 줄로 서면 밀치다 넘어질 일이 줄기 때문이다","mis":"K6-1-u5-X03"},{"t":"급식실 앞에서는 한 줄로 서야 한다","mis":"K6-1-u5-X02"},{"t":"줄이 두세 갈래로 엉킨다","mis":"K6-1-u5-X02"}],"explanation":["「때문이다」는 이유예요.","주장이에요.","출처가 붙은 조사 결과예요."],"asset":{"type":"passage","lines":["① 점심시간 급식실 앞은 늘 북적인다. 줄이 두세 갈래로 엉켜 서로 밀치기도 한다.","급식실 앞에서는 한 줄로 서야 한다.","② 첫째, 한 줄로 서면 밀치다 넘어질 일이 줄기 때문이다. 우리 반 스물네 명","가운데 열다섯 명이 급식실 앞에서 밀린 적이 있다고 답했다.","(새솔반(2026), 「급식실 앞 줄서기 설문」, 학급 게시판.)","③ 둘째, 먼저 온 사람이 먼저 먹을 수 있기 때문이다. 어떤 조사에 따르면","줄이 엉키면 늦게 온 사람이 먼저 들어가는 일이 많다고 한다.","급식실 반찬은 골고루 먹어야 키가 큰다."],"title":"우재의 초고 「급식실 앞에서는 한 줄로 섭시다」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#12','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C51',2,'mc','auto','우재 초고 ③문단의 근거를 고쳐야 하는 까닭은 어느 것인가요?',ARRAY['K6-1-u5-X03','K6-1-u5-X25','K6-1-u5-X10']::text[],false,'{"seq":12,"concept":"K6-1-u5-C51","difficulty":2,"kind":"mc","stem":"우재 초고 ③문단의 근거를 고쳐야 하는 까닭은 어느 것인가요?","options":[{"t":"「어떤 조사에 따르면」이라 누가 · 언제 한 조사인지 확인할 수 없기 때문이다","correct":true},{"t":"조사 결과는 이유가 되기 때문이다","mis":"K6-1-u5-X03"},{"t":"문장이 두 줄이라 짧기 때문이다","mis":"K6-1-u5-X25"},{"t":"「둘째」라는 말이 있기 때문이다","mis":"K6-1-u5-X10"}],"explanation":["조사 결과는 근거예요.","길이 문제가 아니에요.","출처가 흐려 확인할 수 없어요."],"asset":{"type":"passage","lines":["① 점심시간 급식실 앞은 늘 북적인다. 줄이 두세 갈래로 엉켜 서로 밀치기도 한다.","급식실 앞에서는 한 줄로 서야 한다.","② 첫째, 한 줄로 서면 밀치다 넘어질 일이 줄기 때문이다. 우리 반 스물네 명","가운데 열다섯 명이 급식실 앞에서 밀린 적이 있다고 답했다.","(새솔반(2026), 「급식실 앞 줄서기 설문」, 학급 게시판.)","③ 둘째, 먼저 온 사람이 먼저 먹을 수 있기 때문이다. 어떤 조사에 따르면","줄이 엉키면 늦게 온 사람이 먼저 들어가는 일이 많다고 한다.","급식실 반찬은 골고루 먹어야 키가 큰다."],"title":"우재의 초고 「급식실 앞에서는 한 줄로 섭시다」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#13','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C25',2,'mc','auto','우재 초고 뒷부분에서 쓰기 윤리에 어긋난 문장은 어느 것인가요?',ARRAY['K6-1-u5-X25']::text[],false,'{"seq":13,"concept":"K6-1-u5-C25","difficulty":2,"kind":"mc","stem":"우재 초고 뒷부분에서 쓰기 윤리에 어긋난 문장은 어느 것인가요?","options":[{"t":"줄을 서지 않고 끼어드는 사람은 정말 이기적인 사람이다","correct":true},{"t":"한 줄로 서는 일은 어렵지 않다","mis":"K6-1-u5-X25"},{"t":"지금까지 세 가지 까닭을 살펴보았다","mis":"K6-1-u5-X25"},{"t":"모두가 편안한 점심시간을 만들자","mis":"K6-1-u5-X25"}],"explanation":["사실을 말한 문장이에요.","요약하는 문장이에요.","다른 사람을 헐뜯는 말이에요."],"asset":{"type":"passage","lines":["④ 셋째, 줄을 정리하시는 선생님의 일이 줄기 때문이다. 급식 지도를 맡으신","선생님께서 엉킨 줄을 푸는 데 점심시간의 많은 부분을 쓰신다고 하셨다.","(최○○ 선생님 면담(2026), 「급식 지도 이야기」, 급식실.)","⑤ 지금까지 세 가지 까닭을 살펴보았다. 한 줄로 서는 일은 어렵지 않다.","급식실 앞에서는 한줄로 서서 모두가 편안한 점심시간을 만들자.","줄을 서지 않고 끼어드는 사람은 정말 이기적인 사람이다."],"title":"우재의 초고 — 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#14','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C34',2,'mc','auto','우재가 「동생들도 읽을 텐데」라고 한 것은 어느 단계를 다시 살핀 것인가요?',ARRAY['K6-1-u5-X39']::text[],false,'{"seq":14,"concept":"K6-1-u5-C34","difficulty":2,"kind":"mc","stem":"우재가 「동생들도 읽을 텐데」라고 한 것은 어느 단계를 다시 살핀 것인가요?","options":[{"t":"계획하기 — 글을 읽을 사람","correct":true},{"t":"내용 조직하기 — 짜임","mis":"K6-1-u5-X39"},{"t":"고쳐쓰기 — 맞춤법","mis":"K6-1-u5-X39"},{"t":"내용 생성하기 — 자료","mis":"K6-1-u5-X39"}],"explanation":["짜임 이야기가 아니에요.","맞춤법 이야기가 아니에요.","읽을 사람을 다시 보는 것은 계획하기예요."],"asset":{"type":"speech","turns":[{"who":"우재","text":"다 썼는데 둘째 이유의 근거가 「어떤 조사에 따르면」이야. 다시 자료를 찾으면 처음부터 다시 하는 거잖아."},{"who":"하영","text":"처음부터가 아니라 내용 생성하기로 잠깐 돌아가는 거야. 우리 반에서 직접 세어 보면 되지."},{"who":"우재","text":"그리고 이 글은 동생들도 읽을 텐데 「급식 지도」 같은 말은 어려울까?"},{"who":"하영","text":"그건 계획하기에서 읽을 사람을 다시 보는 거네. 고칠 곳을 찾았다는 건 네가 볼 줄 알게 됐다는 뜻이야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#15','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C48',2,'ox','auto','하영이의 표어는 근거 없이 눈에 띄는 말만 내세웠어요.',ARRAY['K6-1-u5-X44']::text[],false,'{"seq":15,"concept":"K6-1-u5-C48","difficulty":2,"kind":"ox","stem":"하영이의 표어는 근거 없이 눈에 띄는 말만 내세웠어요.","answer":"X","reason_options":[{"t":"표어 아래에 네 칸 글로 까닭과 사례를 붙여 근거를 남겼기 때문에","correct":true},{"t":"표어는 근거가 없어도 설득되기 때문에","mis":"K6-1-u5-X44"}],"mis":"K6-1-u5-X44","explanation":["표어만 있는 게 아니에요.","사례가 있어요.","근거 하나를 남겼어요."],"asset":{"type":"passage","lines":["표어 — 「한 줄이면 모두가 먼저」","의견 — 급식실 앞에서는 한 줄로 섭시다.","까닭 — 엉킨 줄에서는 밀려 넘어질 수 있기 때문입니다.","사례 — 우리 반 스물네 명 가운데 열다섯 명이 밀린 적이 있다고 답했습니다.","제안 — 내일 점심부터 급식실 앞에서는 한 줄로 서 봅시다."],"title":"하영이 만든 표어와 네 칸 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#16','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C52',2,'mc','auto','「먼지잼」이 어울리는 날은 어느 것인가요?',ARRAY['K6-1-u5-X48']::text[],false,'{"seq":16,"concept":"K6-1-u5-C52","difficulty":2,"kind":"mc","stem":"「먼지잼」이 어울리는 날은 어느 것인가요?","options":[{"t":"먼지나 겨우 가라앉힐 만큼 비가 아주 조금 내린 날","correct":true},{"t":"밤새도록 비가 내린 날","mis":"K6-1-u5-X48"},{"t":"볕이 쨍한데 잠깐 비가 온 날","mis":"K6-1-u5-X48"},{"t":"가루처럼 잘게 눈이 내린 날","mis":"K6-1-u5-X48"}],"explanation":["밤에 내리는 비는 밤비예요.","그것은 여우비예요.","아주 조금 온 비예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#17','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C10',3,'mc','auto','근거의 타당성을 묻는 세 물음을 모두 넘긴 근거는 어느 것인가요? (이유: 물기 때문에 복도가 미끄럽다)',ARRAY['K6-1-u5-X09','K6-1-u5-X23','K6-1-u5-X14']::text[],false,'{"seq":17,"concept":"K6-1-u5-C10","difficulty":3,"kind":"mc","stem":"근거의 타당성을 묻는 세 물음을 모두 넘긴 근거는 어느 것인가요? (이유: 물기 때문에 복도가 미끄럽다)","options":[{"t":"비 온 날 복도에 물이 고인 곳을 사흘 동안 센 기록과 그 출처","correct":true},{"t":"비 오는 날은 기분이 처진다는 내 느낌","mis":"K6-1-u5-X09"},{"t":"누가 썼는지 모르는 누리집 글","mis":"K6-1-u5-X23"},{"t":"출처를 갖춘 우리 반 급식 잔반 기록","mis":"K6-1-u5-X14"}],"explanation":["느낌은 객관적이지 않아요.","출처를 믿기 어려워요.","이유와 이어지고 · 믿을 수 있고 · 객관적이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#18','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C17',3,'mc','auto','내 글에 표절이 없는지 확인하는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X25','K6-1-u5-X17']::text[],false,'{"seq":18,"concept":"K6-1-u5-C17","difficulty":3,"kind":"mc","stem":"내 글에 표절이 없는지 확인하는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"남에게서 가져온 문장 · 표 · 자료마다 출처를 붙였는지 하나씩 짚어 본다","correct":true},{"t":"글이 다른 글보다 긴지 본다","mis":"K6-1-u5-X25"},{"t":"어려운 낱말이 많은지 본다","mis":"K6-1-u5-X25"},{"t":"여러 글에서 가져온 조각이면 괜찮다고 여긴다","mis":"K6-1-u5-X17"}],"explanation":["길이와 관계없어요.","어려운 낱말과 관계없어요.","조각도 표절이 될 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#19','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C31',3,'mc','auto','우재의 주장에 「한 줄로 서면 줄이 너무 길어져 복도를 막아요」라는 반박이 나왔어요. 가장 알맞은 대처는 어느 것인가요?',ARRAY['K6-1-u5-X28','K6-1-u5-X27','K6-1-u5-X25']::text[],false,'{"seq":19,"concept":"K6-1-u5-C31","difficulty":3,"kind":"mc","stem":"우재의 주장에 「한 줄로 서면 줄이 너무 길어져 복도를 막아요」라는 반박이 나왔어요. 가장 알맞은 대처는 어느 것인가요?","options":[{"t":"맞는 걱정이니 「벽을 따라 한 줄로 서자」는 내용을 보탠다","correct":true},{"t":"반박을 못 들은 척한다","mis":"K6-1-u5-X28"},{"t":"주장을 「모두 노력합시다」로 바꾼다","mis":"K6-1-u5-X27"},{"t":"반박한 친구를 이기적이라고 쓴다","mis":"K6-1-u5-X25"}],"explanation":["그 자리에서 무너져요.","주장이 흐려져요.","헐뜯으면 쓰기 윤리에 어긋나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#20','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C41',3,'mc','auto','「점심시간 급식실 앞 → 한 줄 서기」를 정한 뒤 「설문 · 면담」을 모은 우재가 다음에 할 단계는 어느 것인가요?',ARRAY['K6-1-u5-X37']::text[],false,'{"seq":20,"concept":"K6-1-u5-C41","difficulty":3,"kind":"mc","stem":"「점심시간 급식실 앞 → 한 줄 서기」를 정한 뒤 「설문 · 면담」을 모은 우재가 다음에 할 단계는 어느 것인가요?","options":[{"t":"내용 조직하기 — 서론 · 본론 · 결론에 나누어 개요를 짠다","correct":true},{"t":"고쳐쓰기 — 맞춤법을 고친다","mis":"K6-1-u5-X37"},{"t":"계획하기 — 목적을 처음 정한다","mis":"K6-1-u5-X37"},{"t":"표현하기 없이 바로 끝낸다","mis":"K6-1-u5-X37"}],"explanation":["아직 쓴 글이 없어요.","계획은 이미 세웠어요.","모은 것을 늘어놓을 차례예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#21','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C46',3,'mc','auto','「안돼요」와 「안 돼요」 가운데 바른 것과 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X42']::text[],false,'{"seq":21,"concept":"K6-1-u5-C46","difficulty":3,"kind":"mc","stem":"「안돼요」와 「안 돼요」 가운데 바른 것과 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"「안 돼요」 — 「안」과 「돼요」를 띄어 쓰기 때문이다","correct":true},{"t":"「안돼요」 — 소리 나는 대로 붙여 쓰기 때문이다","mis":"K6-1-u5-X42"},{"t":"둘 다 맞다 — 띄어쓰기는 뜻과 관계없기 때문이다","mis":"K6-1-u5-X42"},{"t":"「안 되요」 — 「되」로 써야 하기 때문이다","mis":"K6-1-u5-X42"}],"explanation":["붙여 쓰지 않아요.","띄어쓰기도 민감하게 살펴요.","「돼요」가 바른 맞춤법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#22','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C47',3,'mc','auto','하영이가 처음 「급식 시간을 늘립시다」로 실천 주장을 세웠다가 바꾼 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X47','K6-1-u5-X24','K6-1-u5-X34']::text[],false,'{"seq":22,"concept":"K6-1-u5-C47","difficulty":3,"kind":"mc","stem":"하영이가 처음 「급식 시간을 늘립시다」로 실천 주장을 세웠다가 바꾼 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"급식 시간은 학생이 정할 수 없어, 우리가 바꿀 수 있는 「한 줄로 서기」로 바꾸었다","correct":true},{"t":"주장이 너무 짧아서","mis":"K6-1-u5-X47"},{"t":"근거가 너무 많아서","mis":"K6-1-u5-X24"},{"t":"읽을 사람이 정해져 있지 않아서","mis":"K6-1-u5-X34"}],"explanation":["짧아서가 아니에요.","근거 수 문제가 아니에요.","우리 힘으로 바꿀 수 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#23','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C51',4,'mc','auto','우재가 ③문단 근거를 고친 것 가운데 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X47','K6-1-u5-X19','K6-1-u5-X21']::text[],false,'{"seq":23,"concept":"K6-1-u5-C51","difficulty":4,"kind":"mc","stem":"우재가 ③문단 근거를 고친 것 가운데 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「일주일 동안 줄이 엉킨 날 늦게 온 사람이 먼저 들어간 횟수를 세어 보니 … (새솔반(2026), 「급식실 앞 관찰 기록」, 학급 게시판.)」","correct":true},{"t":"「많은 사람들이 그렇다고 한다.」","mis":"K6-1-u5-X47"},{"t":"「어떤 조사에 따르면 아주아주 많다고 한다.」","mis":"K6-1-u5-X19"},{"t":"「누리집에서 봤는데 정말 그렇다.」","mis":"K6-1-u5-X21"}],"explanation":["누가 말했는지 몰라요.","흐린 출처에 과장까지 했어요.","어느 누리집인지 확인할 수 없어요."],"asset":{"type":"passage","lines":["① 점심시간 급식실 앞은 늘 북적인다. 줄이 두세 갈래로 엉켜 서로 밀치기도 한다.","급식실 앞에서는 한 줄로 서야 한다.","② 첫째, 한 줄로 서면 밀치다 넘어질 일이 줄기 때문이다. 우리 반 스물네 명","가운데 열다섯 명이 급식실 앞에서 밀린 적이 있다고 답했다.","(새솔반(2026), 「급식실 앞 줄서기 설문」, 학급 게시판.)","③ 둘째, 먼저 온 사람이 먼저 먹을 수 있기 때문이다. 어떤 조사에 따르면","줄이 엉키면 늦게 온 사람이 먼저 들어가는 일이 많다고 한다.","급식실 반찬은 골고루 먹어야 키가 큰다."],"title":"우재의 초고 「급식실 앞에서는 한 줄로 섭시다」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#24','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C51',4,'essay','teacher','「헌책 나눔 상자」 글에서 출처가 흐린 곳 두 군데를 찾아 쓰고, 그중 하나를 학생이 직접 만들 수 있는 근거로 바꾸어 출처를 네 가지를 갖추어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u5-C51","difficulty":4,"kind":"essay","stem":"「헌책 나눔 상자」 글에서 출처가 흐린 곳 두 군데를 찾아 쓰고, 그중 하나를 학생이 직접 만들 수 있는 근거로 바꾸어 출처를 네 가지를 갖추어 쓰세요.","answer_guide":{"answer":"예: 출처가 흐린 곳은 ②문단의 「어떤 조사에 따르면」과 ④문단의 「어떤 선생님께서」이다. ②문단을 바꾸면 — 우리 반 스물다섯 명에게 물어보니 열아홉 명이 집에 읽지 않는 책이 다섯 권 넘게 있다고 답했다. (솔바람반(2026), 「집에 있는 읽지 않는 책 설문」, 학급 게시판.)","scoring_points":["흐린 곳 두 군데를 찾았는가","학생이 직접 만들 수 있는 근거로 바꾸었는가","출처를 네 가지를 갖추어 적었는가"]},"explanation":["누가 · 언제가 빠진 곳을 찾아요.","직접 세거나 물을 수 있는 자료로 바꿔요.","네 칸을 채워요."],"asset":{"type":"passage","lines":["① 학년이 올라가면 지난해에 보던 책이 쌓인다. 현관에 헌책 나눔 상자를 두면 좋겠다.","② 첫째, 책이 필요한 사람에게 옮겨 가기 때문이다. 어떤 조사에 따르면,","집에 읽지 않는 책을 여러 권 두고 있는 학생이 많다고 한다.","③ 둘째, 종이를 덜 쓰게 되기 때문이다. 우리 반 스물다섯 명 가운데 스물한 명이","헌책을 받아 본 적이 있다고 답했다. (솔바람반(2026), 「헌책 이용 설문」, 학급 게시판.)","④ 셋째, 책을 고르는 재미가 생기기 때문이다. 어떤 선생님께서","남의 손을 거친 책을 아이들이 더 궁금해한다고 하셨다.","⑤ 상자 하나면 된다. 헌책 나눔 상자를 두어 책이 다시 읽히게 하자."],"title":"「헌책 나눔 상자를 두면 좋겠습니다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#25','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C10',4,'essay','teacher','좋은 근거가 갖추어야 할 것을 세 가지 쓰고, 그 가운데 출처가 왜 중요한지 「확인」이라는 말을 넣어 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u5-C10","difficulty":4,"kind":"essay","stem":"좋은 근거가 갖추어야 할 것을 세 가지 쓰고, 그 가운데 출처가 왜 중요한지 「확인」이라는 말을 넣어 설명하세요.","answer_guide":{"answer":"예: 좋은 근거는 첫째, 이유와 관련이 있어야 하고, 둘째, 출처를 믿을 수 있어야 하며, 셋째, 느낌이나 짐작이 아닌 객관적인 자료여야 한다. 출처가 중요한 까닭은 만든 사람 · 시기 · 자료의 이름 · 실린 곳이 다 있어야 읽는 사람이 직접 찾아가 확인할 수 있기 때문이다. 확인할 수 없으면 근거가 아니라 짐작이 된다.","scoring_points":["근거가 갖출 것 세 가지를 썼는가","출처의 네 가지를 썼는가","확인할 수 있어야 근거라는 점을 썼는가"]},"explanation":["세 물음을 떠올려요.","출처 네 칸을 떠올려요.","확인과 이어 설명해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#1','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C7',1,'ox','auto','「∼하기 때문이다」로 이어지는 내 까닭은 이유예요.',ARRAY['K6-1-u5-X03']::text[],false,'{"seq":1,"concept":"K6-1-u5-C7","difficulty":1,"kind":"ox","stem":"「∼하기 때문이다」로 이어지는 내 까닭은 이유예요.","answer":"O","reason_options":[{"t":"이유는 그렇게 주장하는 주관적인 까닭이기 때문에","correct":true},{"t":"밖에서 가져와 출처를 붙인 자료이기 때문에","mis":"K6-1-u5-X03"}],"mis":"K6-1-u5-X03","explanation":["내 까닭이에요.","출처를 붙이는 것은 근거예요.","이유와 근거를 섞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#2','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C13',1,'ox','auto','결론에서는 처음 꺼내는 새로운 근거를 내놓아요.',ARRAY['K6-1-u5-X11']::text[],false,'{"seq":2,"concept":"K6-1-u5-C13","difficulty":1,"kind":"ox","stem":"결론에서는 처음 꺼내는 새로운 근거를 내놓아요.","answer":"X","reason_options":[{"t":"결론은 주장한 내용을 요약하고 다시 한번 강조하는 부분이기 때문에","correct":true},{"t":"마지막에 가장 센 새 근거를 두어야 하기 때문에","mis":"K6-1-u5-X11"}],"mis":"K6-1-u5-X11","explanation":["새 근거는 본론에 둬요.","결론은 모으는 부분이에요.","다시 한번 힘주어 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#3','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C18',1,'ox','auto','출처를 밝히는 일은 해도 되고 안 해도 되는 예의예요.',ARRAY['K6-1-u5-X18']::text[],false,'{"seq":3,"concept":"K6-1-u5-C18","difficulty":1,"kind":"ox","stem":"출처를 밝히는 일은 해도 되고 안 해도 되는 예의예요.","answer":"X","reason_options":[{"t":"만든 사람의 권리를 지키기 위해 꼭 지켜야 할 약속이기 때문에","correct":true},{"t":"읽는 사람이 원할 때만 밝히면 되기 때문에","mis":"K6-1-u5-X18"}],"mis":"K6-1-u5-X18","explanation":["예의가 아니에요.","약속이에요.","권리를 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#4','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C21',1,'mc','auto','같은 출처에서 「2026」은 무엇에 해당하나요?',ARRAY['K6-1-u5-X21','K6-1-u5-X22']::text[],false,'{"seq":4,"concept":"K6-1-u5-C21","difficulty":1,"kind":"mc","stem":"같은 출처에서 「2026」은 무엇에 해당하나요?","options":[{"t":"자료를 만든 시기","correct":true},{"t":"자료가 실린 곳","mis":"K6-1-u5-X21"},{"t":"자료를 만든 사람","mis":"K6-1-u5-X21"},{"t":"자료의 쪽수","mis":"K6-1-u5-X22"}],"explanation":["실린 곳은 끝에 적어요.","만든 쪽은 맨 앞이에요.","괄호 안 숫자는 때예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#5','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C23',1,'mc','auto','근거로 쓰기에 믿을 만한 자료는 어느 것인가요?',ARRAY['K6-1-u5-X23']::text[],false,'{"seq":5,"concept":"K6-1-u5-C23","difficulty":1,"kind":"mc","stem":"근거로 쓰기에 믿을 만한 자료는 어느 것인가요?","options":[{"t":"언제 · 누구에게 · 어디서 했는지 적어 둔 우리 반 설문","correct":true},{"t":"누가 썼는지 모르는 글","mis":"K6-1-u5-X23"},{"t":"언제 올라온 것인지 모를 자료","mis":"K6-1-u5-X23"},{"t":"친구가 들었다고 한 소문","mis":"K6-1-u5-X23"}],"explanation":["누가 썼는지 몰라요.","언제인지 몰라요.","직접 조사도 출처를 적으면 근거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#6','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C37',1,'mc','auto','떠올린 내용을 서론 · 본론 · 결론 짜임에 맞게 늘어놓는 단계는 어느 것인가요?',ARRAY['K6-1-u5-X37']::text[],false,'{"seq":6,"concept":"K6-1-u5-C37","difficulty":1,"kind":"mc","stem":"떠올린 내용을 서론 · 본론 · 결론 짜임에 맞게 늘어놓는 단계는 어느 것인가요?","options":[{"t":"내용 조직하기","correct":true},{"t":"내용 생성하기","mis":"K6-1-u5-X37"},{"t":"표현하기","mis":"K6-1-u5-X37"},{"t":"계획하기","mis":"K6-1-u5-X37"}],"explanation":["생성하기는 꺼내 놓아요.","표현하기는 문장으로 써요.","늘어놓는 단계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#7','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C44',1,'ox','auto','고칠 곳을 찾아냈다는 것은 볼 줄 알게 되었다는 뜻이에요.',ARRAY['K6-1-u5-X40']::text[],false,'{"seq":7,"concept":"K6-1-u5-C44","difficulty":1,"kind":"ox","stem":"고칠 곳을 찾아냈다는 것은 볼 줄 알게 되었다는 뜻이에요.","answer":"O","reason_options":[{"t":"점검은 흠 잡기가 아니라 나아지기 위한 조정이기 때문에","correct":true},{"t":"고칠 곳이 많으면 망한 글이기 때문에","mis":"K6-1-u5-X40"}],"mis":"K6-1-u5-X40","explanation":["찾아낸 만큼 나아져요.","흠 잡기가 아니에요.","과정을 보는 단원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#8','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C47',1,'mc','auto','우리 힘으로 바꿀 수 있어 실천 활동으로 알맞은 문제는 어느 것인가요?',ARRAY['K6-1-u5-X43']::text[],false,'{"seq":8,"concept":"K6-1-u5-C47","difficulty":1,"kind":"mc","stem":"우리 힘으로 바꿀 수 있어 실천 활동으로 알맞은 문제는 어느 것인가요?","options":[{"t":"특별실을 쓰고 뒷정리를 하지 않고 나간다","correct":true},{"t":"겨울이 너무 춥다","mis":"K6-1-u5-X43"},{"t":"해가 너무 일찍 진다","mis":"K6-1-u5-X43"},{"t":"바다가 너무 멀다","mis":"K6-1-u5-X43"}],"explanation":["날씨는 바꿀 수 없어요.","해 지는 시각도 바꿀 수 없어요.","우리가 바꿀 수 있는 문제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#9','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C51',2,'ox','auto','「어떤 조사에 따르면」처럼 쓰면 읽는 사람이 그 조사를 찾아가 확인할 수 있어요.',ARRAY['K6-1-u5-X47']::text[],false,'{"seq":9,"concept":"K6-1-u5-C51","difficulty":2,"kind":"ox","stem":"「어떤 조사에 따르면」처럼 쓰면 읽는 사람이 그 조사를 찾아가 확인할 수 있어요.","answer":"X","reason_options":[{"t":"누가 · 언제 · 무엇을 · 어디에 실었는지가 모두 빠져 있기 때문에","correct":true},{"t":"「조사」라는 말이 들어 있으니 출처를 밝힌 것이기 때문에","mis":"K6-1-u5-X47"}],"mis":"K6-1-u5-X47","explanation":["네 가지가 모두 없어요.","확인할 길이 없어요.","근거가 아니라 짐작이 돼요."],"asset":{"type":"passage","lines":["① 학년이 올라가면 지난해에 보던 책이 쌓인다. 현관에 헌책 나눔 상자를 두면 좋겠다.","② 첫째, 책이 필요한 사람에게 옮겨 가기 때문이다. 어떤 조사에 따르면,","집에 읽지 않는 책을 여러 권 두고 있는 학생이 많다고 한다.","③ 둘째, 종이를 덜 쓰게 되기 때문이다. 우리 반 스물다섯 명 가운데 스물한 명이","헌책을 받아 본 적이 있다고 답했다. (솔바람반(2026), 「헌책 이용 설문」, 학급 게시판.)","④ 셋째, 책을 고르는 재미가 생기기 때문이다. 어떤 선생님께서","남의 손을 거친 책을 아이들이 더 궁금해한다고 하셨다.","⑤ 상자 하나면 된다. 헌책 나눔 상자를 두어 책이 다시 읽히게 하자."],"title":"「헌책 나눔 상자를 두면 좋겠습니다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#10','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C13',2,'mc','auto','⑤문단 「상자 하나면 된다. … 다시 읽히게 하자.」는 글의 어느 부분인가요?',ARRAY['K6-1-u5-X10','K6-1-u5-X11']::text[],false,'{"seq":10,"concept":"K6-1-u5-C13","difficulty":2,"kind":"mc","stem":"⑤문단 「상자 하나면 된다. … 다시 읽히게 하자.」는 글의 어느 부분인가요?","options":[{"t":"결론 — 주장을 다시 강조한다","correct":true},{"t":"서론 — 문제를 제기한다","mis":"K6-1-u5-X10"},{"t":"본론 — 새 근거를 든다","mis":"K6-1-u5-X11"},{"t":"본론 — 이유를 처음 밝힌다","mis":"K6-1-u5-X10"}],"explanation":["문제 제기는 ①문단이에요.","새 근거가 없어요.","마지막에 다시 힘주어 말해요."],"asset":{"type":"passage","lines":["① 학년이 올라가면 지난해에 보던 책이 쌓인다. 현관에 헌책 나눔 상자를 두면 좋겠다.","② 첫째, 책이 필요한 사람에게 옮겨 가기 때문이다. 어떤 조사에 따르면,","집에 읽지 않는 책을 여러 권 두고 있는 학생이 많다고 한다.","③ 둘째, 종이를 덜 쓰게 되기 때문이다. 우리 반 스물다섯 명 가운데 스물한 명이","헌책을 받아 본 적이 있다고 답했다. (솔바람반(2026), 「헌책 이용 설문」, 학급 게시판.)","④ 셋째, 책을 고르는 재미가 생기기 때문이다. 어떤 선생님께서","남의 손을 거친 책을 아이들이 더 궁금해한다고 하셨다.","⑤ 상자 하나면 된다. 헌책 나눔 상자를 두어 책이 다시 읽히게 하자."],"title":"「헌책 나눔 상자를 두면 좋겠습니다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#11','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C12',2,'ox','auto','우재 초고 ②문단은 본론으로, 이유와 근거가 함께 놓였어요.',ARRAY['K6-1-u5-X10']::text[],false,'{"seq":11,"concept":"K6-1-u5-C12","difficulty":2,"kind":"ox","stem":"우재 초고 ②문단은 본론으로, 이유와 근거가 함께 놓였어요.","answer":"O","reason_options":[{"t":"「첫째」로 이유를 밝히고 설문 결과와 출처를 붙였기 때문에","correct":true},{"t":"문제를 처음 꺼내고 주장을 밝혔기 때문에","mis":"K6-1-u5-X10"}],"mis":"K6-1-u5-X10","explanation":["첫째로 이유를 갈랐어요.","근거와 출처가 있어요.","문제 제기는 ①문단이에요."],"asset":{"type":"passage","lines":["① 점심시간 급식실 앞은 늘 북적인다. 줄이 두세 갈래로 엉켜 서로 밀치기도 한다.","급식실 앞에서는 한 줄로 서야 한다.","② 첫째, 한 줄로 서면 밀치다 넘어질 일이 줄기 때문이다. 우리 반 스물네 명","가운데 열다섯 명이 급식실 앞에서 밀린 적이 있다고 답했다.","(새솔반(2026), 「급식실 앞 줄서기 설문」, 학급 게시판.)","③ 둘째, 먼저 온 사람이 먼저 먹을 수 있기 때문이다. 어떤 조사에 따르면","줄이 엉키면 늦게 온 사람이 먼저 들어가는 일이 많다고 한다.","급식실 반찬은 골고루 먹어야 키가 큰다."],"title":"우재의 초고 「급식실 앞에서는 한 줄로 섭시다」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#12','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C33',2,'ox','auto','「급식실 반찬은 골고루 먹어야 키가 큰다」는 옳은 말이니 우재 초고에 그대로 두어도 돼요.',ARRAY['K6-1-u5-X33']::text[],false,'{"seq":12,"concept":"K6-1-u5-C33","difficulty":2,"kind":"ox","stem":"「급식실 반찬은 골고루 먹어야 키가 큰다」는 옳은 말이니 우재 초고에 그대로 두어도 돼요.","answer":"X","reason_options":[{"t":"옳은 말이어도 「한 줄로 서자」는 주제와 이어지지 않아 통일성을 깨기 때문에","correct":true},{"t":"옳은 말은 어느 글에 넣어도 되기 때문에","mis":"K6-1-u5-X33"}],"mis":"K6-1-u5-X33","explanation":["주제를 먼저 봐요.","줄서기와 관계없어요.","걸러 내야 해요."],"asset":{"type":"passage","lines":["① 점심시간 급식실 앞은 늘 북적인다. 줄이 두세 갈래로 엉켜 서로 밀치기도 한다.","급식실 앞에서는 한 줄로 서야 한다.","② 첫째, 한 줄로 서면 밀치다 넘어질 일이 줄기 때문이다. 우리 반 스물네 명","가운데 열다섯 명이 급식실 앞에서 밀린 적이 있다고 답했다.","(새솔반(2026), 「급식실 앞 줄서기 설문」, 학급 게시판.)","③ 둘째, 먼저 온 사람이 먼저 먹을 수 있기 때문이다. 어떤 조사에 따르면","줄이 엉키면 늦게 온 사람이 먼저 들어가는 일이 많다고 한다.","급식실 반찬은 골고루 먹어야 키가 큰다."],"title":"우재의 초고 「급식실 앞에서는 한 줄로 섭시다」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#13','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C12',2,'ox','auto','우재 초고 ④문단의 근거는 이유와 이어지고 출처도 갖추었어요.',ARRAY['K6-1-u5-X23']::text[],false,'{"seq":13,"concept":"K6-1-u5-C12","difficulty":2,"kind":"ox","stem":"우재 초고 ④문단의 근거는 이유와 이어지고 출처도 갖추었어요.","answer":"O","reason_options":[{"t":"선생님의 일이 준다는 이유를 급식 지도 선생님 면담이 받치고 네 가지 출처가 있기 때문에","correct":true},{"t":"선생님 말씀은 근거가 될 수 없기 때문에","mis":"K6-1-u5-X23"}],"mis":"K6-1-u5-X23","explanation":["면담은 근거가 돼요.","이유와 이어져요.","출처 네 가지가 있어요."],"asset":{"type":"passage","lines":["④ 셋째, 줄을 정리하시는 선생님의 일이 줄기 때문이다. 급식 지도를 맡으신","선생님께서 엉킨 줄을 푸는 데 점심시간의 많은 부분을 쓰신다고 하셨다.","(최○○ 선생님 면담(2026), 「급식 지도 이야기」, 급식실.)","⑤ 지금까지 세 가지 까닭을 살펴보았다. 한 줄로 서는 일은 어렵지 않다.","급식실 앞에서는 한줄로 서서 모두가 편안한 점심시간을 만들자.","줄을 서지 않고 끼어드는 사람은 정말 이기적인 사람이다."],"title":"우재의 초고 — 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#14','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C44',2,'ox','auto','하영이는 고칠 곳을 찾은 것을 우재가 볼 줄 알게 된 것으로 받아들였어요.',ARRAY['K6-1-u5-X40']::text[],false,'{"seq":14,"concept":"K6-1-u5-C44","difficulty":2,"kind":"ox","stem":"하영이는 고칠 곳을 찾은 것을 우재가 볼 줄 알게 된 것으로 받아들였어요.","answer":"O","reason_options":[{"t":"점검은 흠을 잡는 일이 아니라 나아지기 위한 조정이기 때문에","correct":true},{"t":"고칠 곳이 있으면 글이 망한 것이기 때문에","mis":"K6-1-u5-X40"}],"mis":"K6-1-u5-X40","explanation":["하영이는 격려했어요.","흠 잡기가 아니에요.","찾아낸 만큼 나아져요."],"asset":{"type":"speech","turns":[{"who":"우재","text":"다 썼는데 둘째 이유의 근거가 「어떤 조사에 따르면」이야. 다시 자료를 찾으면 처음부터 다시 하는 거잖아."},{"who":"하영","text":"처음부터가 아니라 내용 생성하기로 잠깐 돌아가는 거야. 우리 반에서 직접 세어 보면 되지."},{"who":"우재","text":"그리고 이 글은 동생들도 읽을 텐데 「급식 지도」 같은 말은 어려울까?"},{"who":"하영","text":"그건 계획하기에서 읽을 사람을 다시 보는 거네. 고칠 곳을 찾았다는 건 네가 볼 줄 알게 됐다는 뜻이야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#15','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C49',2,'mc','auto','하영이의 네 칸 글이 서론 · 본론 · 결론과 이어지는 것으로 바른 것은 어느 것인가요?',ARRAY['K6-1-u5-X45']::text[],false,'{"seq":15,"concept":"K6-1-u5-C49","difficulty":2,"kind":"mc","stem":"하영이의 네 칸 글이 서론 · 본론 · 결론과 이어지는 것으로 바른 것은 어느 것인가요?","options":[{"t":"의견은 서론, 까닭과 사례는 본론, 제안은 결론에 가깝다","correct":true},{"t":"의견과 까닭은 결론에 가깝다","mis":"K6-1-u5-X45"},{"t":"사례는 서론에 가깝다","mis":"K6-1-u5-X45"},{"t":"제안은 본론에 가깝다","mis":"K6-1-u5-X45"}],"explanation":["의견은 처음 꺼내는 말이에요.","사례는 펼치는 부분이에요.","제안은 다시 힘주는 말이에요."],"asset":{"type":"passage","lines":["표어 — 「한 줄이면 모두가 먼저」","의견 — 급식실 앞에서는 한 줄로 섭시다.","까닭 — 엉킨 줄에서는 밀려 넘어질 수 있기 때문입니다.","사례 — 우리 반 스물네 명 가운데 열다섯 명이 밀린 적이 있다고 답했습니다.","제안 — 내일 점심부터 급식실 앞에서는 한 줄로 서 봅시다."],"title":"하영이 만든 표어와 네 칸 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#16','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C52',2,'ox','auto','우리말에는 비와 눈을 언제 · 얼마나 내리느냐에 따라 갈라 부르는 말이 많아요.',ARRAY['K6-1-u5-X48']::text[],false,'{"seq":16,"concept":"K6-1-u5-C52","difficulty":2,"kind":"ox","stem":"우리말에는 비와 눈을 언제 · 얼마나 내리느냐에 따라 갈라 부르는 말이 많아요.","answer":"O","reason_options":[{"t":"여우비 · 먼지잼 · 도둑눈 · 숫눈처럼 이름이 다르기 때문에","correct":true},{"t":"비와 눈은 한 가지 이름으로만 부르기 때문에","mis":"K6-1-u5-X48"}],"mis":"K6-1-u5-X48","explanation":["갈라 부르는 말이 많아요.","사전에 실려 있어요.","언제 · 얼마나에 따라 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#17','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C15',3,'error','auto','근거를 판단하고 그 까닭을 말했어요. 판단의 까닭이 알맞지 않은 사람은 누구인가요?',ARRAY['K6-1-u5-X15','K6-1-u5-X14','K6-1-u5-X47']::text[],false,'{"seq":17,"concept":"K6-1-u5-C15","difficulty":3,"kind":"error","stem":"근거를 판단하고 그 까닭을 말했어요. 판단의 까닭이 알맞지 않은 사람은 누구인가요?","options":[{"t":"규리 — 「이 근거는 타당해. 그냥 그럴 것 같거든.」","correct":true,"mis_target":"K6-1-u5-X15"},{"t":"예찬 — 「타당해. 넘어질 뻔한 수를 세어서 안전 이유와 바로 이어지거든.」","mis":"K6-1-u5-X14"},{"t":"민찬 — 「타당하지 않아. 출처가 「어떤 조사」라서 확인할 수 없거든.」","mis":"K6-1-u5-X47"}],"explanation":["예찬은 관련을 까닭으로 들었어요.","민찬은 출처를 까닭으로 들었어요.","「그냥 그럴 것 같아서」는 판단이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#18','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C18',3,'mc','auto','출처를 밝히면 「어디까지가 내 말인지」 읽는 사람이 알 수 있다는 것이 왜 중요한가요?',ARRAY['K6-1-u5-X25','K6-1-u5-X24','K6-1-u5-X18']::text[],false,'{"seq":18,"concept":"K6-1-u5-C18","difficulty":3,"kind":"mc","stem":"출처를 밝히면 「어디까지가 내 말인지」 읽는 사람이 알 수 있다는 것이 왜 중요한가요?","options":[{"t":"글쓴이의 생각과 남에게서 가져온 생각이 갈라져 읽는 사람이 무엇을 확인할지 알기 때문이다","correct":true},{"t":"글이 길어 보여 더 믿음직하기 때문이다","mis":"K6-1-u5-X25"},{"t":"내 생각은 숨기는 것이 좋기 때문이다","mis":"K6-1-u5-X24"},{"t":"출처는 예의라서 상관없기 때문이다","mis":"K6-1-u5-X18"}],"explanation":["길이로 믿음이 생기지 않아요.","내 생각이 중심이에요.","출처는 약속이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#19','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C26',3,'mc','auto','우재가 글을 선생님들께 보여 드리기로 했어요. 무엇을 다시 살피는 것이 알맞은가요?',ARRAY['K6-1-u5-X26','K6-1-u5-X04']::text[],false,'{"seq":19,"concept":"K6-1-u5-C26","difficulty":3,"kind":"mc","stem":"우재가 글을 선생님들께 보여 드리기로 했어요. 무엇을 다시 살피는 것이 알맞은가요?","options":[{"t":"선생님들께 맞는 말투와, 선생님들이 고개를 끄덕일 근거","correct":true},{"t":"「한 줄로 서자」는 주장 자체를 바꾼다","mis":"K6-1-u5-X26"},{"t":"근거를 모두 빼고 주장만 남긴다","mis":"K6-1-u5-X04"},{"t":"누구에게 보이든 그대로 둔다","mis":"K6-1-u5-X26"}],"explanation":["주장은 그대로예요.","근거가 있어야 해요.","대상에 맞게 전하는 방법을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#20','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C43',3,'mc','auto','표현하기 점검에서 「급식 지도」라는 말이 동생들에게 어려운지 살핀 까닭은 어느 것인가요?',ARRAY['K6-1-u5-X35','K6-1-u5-X25']::text[],false,'{"seq":20,"concept":"K6-1-u5-C43","difficulty":3,"kind":"mc","stem":"표현하기 점검에서 「급식 지도」라는 말이 동생들에게 어려운지 살핀 까닭은 어느 것인가요?","options":[{"t":"표현하기 점검의 잣대가 내가 아니라 읽을 사람이기 때문이다","correct":true},{"t":"내가 읽어 매끄러우면 되기 때문이다","mis":"K6-1-u5-X35"},{"t":"어려운 낱말이 많을수록 좋기 때문이다","mis":"K6-1-u5-X25"},{"t":"줄임말은 누구나 알기 때문이다","mis":"K6-1-u5-X35"}],"explanation":["나만 알면 안 돼요.","어려운 낱말이 좋은 게 아니에요.","읽을 사람이 알아들어야 해요."],"asset":{"type":"speech","turns":[{"who":"우재","text":"다 썼는데 둘째 이유의 근거가 「어떤 조사에 따르면」이야. 다시 자료를 찾으면 처음부터 다시 하는 거잖아."},{"who":"하영","text":"처음부터가 아니라 내용 생성하기로 잠깐 돌아가는 거야. 우리 반에서 직접 세어 보면 되지."},{"who":"우재","text":"그리고 이 글은 동생들도 읽을 텐데 「급식 지도」 같은 말은 어려울까?"},{"who":"하영","text":"그건 계획하기에서 읽을 사람을 다시 보는 거네. 고칠 곳을 찾았다는 건 네가 볼 줄 알게 됐다는 뜻이야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#21','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C41',3,'ox','auto','문단 수준의 고침은 「중심 문장을 뒷받침 문장이 받쳐 주는가」를 살펴 문단 안을 손보는 일이에요.',ARRAY['K6-1-u5-X41']::text[],false,'{"seq":21,"concept":"K6-1-u5-C41","difficulty":3,"kind":"ox","stem":"문단 수준의 고침은 「중심 문장을 뒷받침 문장이 받쳐 주는가」를 살펴 문단 안을 손보는 일이에요.","answer":"O","reason_options":[{"t":"한 문단 안에서 중심 문장과 뒷받침 문장, 문장끼리의 이음을 보는 크기이기 때문에","correct":true},{"t":"글 전체의 주제를 바꾸는 크기이기 때문에","mis":"K6-1-u5-X41"}],"mis":"K6-1-u5-X41","explanation":["한 문단 안의 일이에요.","글 전체는 글 수준이에요.","고침에도 크기가 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#22','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C50',3,'mc','auto','일주일 실천을 마친 하영이가 다음 주장을 펼칠 출발선으로 남길 것은 어느 것인가요?',ARRAY['K6-1-u5-X44','K6-1-u5-X25','K6-1-u5-X46']::text[],false,'{"seq":22,"concept":"K6-1-u5-C50","difficulty":3,"kind":"mc","stem":"일주일 실천을 마친 하영이가 다음 주장을 펼칠 출발선으로 남길 것은 어느 것인가요?","options":[{"t":"잘된 점과 아쉬운 점을 한 줄씩 적은 것","correct":true},{"t":"표어를 만든 종이의 색","mis":"K6-1-u5-X44"},{"t":"반대한 친구의 이름","mis":"K6-1-u5-X25"},{"t":"아무것도 남기지 않는다","mis":"K6-1-u5-X46"}],"explanation":["색은 출발선이 아니에요.","남을 겨누지 않아요.","되짚어 적어 두어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#23','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C42',4,'mc','auto','우재와 하영이의 대화 전체가 보여 주는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X38','K6-1-u5-X36','K6-1-u5-X30']::text[],false,'{"seq":23,"concept":"K6-1-u5-C42","difficulty":4,"kind":"mc","stem":"우재와 하영이의 대화 전체가 보여 주는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"쓰기는 점검하며 내용 생성하기와 계획하기로 되돌아가는 과정이고, 그것은 실패가 아니다","correct":true},{"t":"글은 한 번에 끝까지 써야 한다","mis":"K6-1-u5-X38"},{"t":"점검은 다 쓴 뒤에 흠을 세는 일이다","mis":"K6-1-u5-X36"},{"t":"읽을 사람은 쓰기 전에만 정한다","mis":"K6-1-u5-X30"}],"explanation":["한 번에 쓰지 않아도 돼요.","흠 세기가 아니에요.","쓰는 도중에도 다시 정해요."],"asset":{"type":"speech","turns":[{"who":"우재","text":"다 썼는데 둘째 이유의 근거가 「어떤 조사에 따르면」이야. 다시 자료를 찾으면 처음부터 다시 하는 거잖아."},{"who":"하영","text":"처음부터가 아니라 내용 생성하기로 잠깐 돌아가는 거야. 우리 반에서 직접 세어 보면 되지."},{"who":"우재","text":"그리고 이 글은 동생들도 읽을 텐데 「급식 지도」 같은 말은 어려울까?"},{"who":"하영","text":"그건 계획하기에서 읽을 사람을 다시 보는 거네. 고칠 곳을 찾았다는 건 네가 볼 줄 알게 됐다는 뜻이야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#24','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C46',4,'essay','teacher','우재 초고 뒷부분을 고쳐쓰기 세 수준 가운데 두 수준에서 하나씩 고치고, 무엇을 왜 고쳤는지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u5-C46","difficulty":4,"kind":"essay","stem":"우재 초고 뒷부분을 고쳐쓰기 세 수준 가운데 두 수준에서 하나씩 고치고, 무엇을 왜 고쳤는지 쓰세요.","answer_guide":{"answer":"예: 문장과 낱말 수준 — 「한줄로」를 「한 줄로」로 고쳤다. 「한」과 「줄」은 띄어 써야 하기 때문이다. 글 수준 — 「줄을 서지 않고 끼어드는 사람은 정말 이기적인 사람이다.」를 지웠다. 다른 사람을 헐뜯는 말이라 쓰기 윤리에 어긋나고, 결론은 주장을 다시 힘주는 부분이기 때문이다.","scoring_points":["두 수준에서 하나씩 고쳤는가","띄어쓰기나 맞춤법을 바르게 고쳤는가","고친 까닭을 썼는가"]},"explanation":["수준을 두 가지 골라요.","고친 곳을 밝혀요.","까닭을 써요."],"asset":{"type":"passage","lines":["④ 셋째, 줄을 정리하시는 선생님의 일이 줄기 때문이다. 급식 지도를 맡으신","선생님께서 엉킨 줄을 푸는 데 점심시간의 많은 부분을 쓰신다고 하셨다.","(최○○ 선생님 면담(2026), 「급식 지도 이야기」, 급식실.)","⑤ 지금까지 세 가지 까닭을 살펴보았다. 한 줄로 서는 일은 어렵지 않다.","급식실 앞에서는 한줄로 서서 모두가 편안한 점심시간을 만들자.","줄을 서지 않고 끼어드는 사람은 정말 이기적인 사람이다."],"title":"우재의 초고 — 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#25','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C19',4,'essay','teacher','인용할 때 지켜야 할 두 가지를 쓰고, 둘 가운데 하나만 지키면 왜 안 되는지 예를 들어 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u5-C19","difficulty":4,"kind":"essay","stem":"인용할 때 지켜야 할 두 가지를 쓰고, 둘 가운데 하나만 지키면 왜 안 되는지 예를 들어 설명하세요.","answer_guide":{"answer":"예: 인용할 때에는 출처를 밝히는 일과 뜻을 비틀지 않는 일을 함께 지켜야 한다. 사서 선생님이 「정리에 시간이 많이 든다」고 하셨는데 출처를 붙인 채 「도서관 일을 할 수 없다」고 옮기면, 출처는 지켰지만 만든 사람의 뜻을 과장한 것이다. 반대로 뜻은 그대로 옮겨도 출처를 빼면 표절이 된다. 둘 다 지켜야 만든 사람의 권리를 지킨 것이다.","scoring_points":["출처 밝히기와 뜻 지키기를 썼는가","하나만 지킨 예를 들었는가","저작자의 권리와 이어 정리했는가"]},"explanation":["두 가지를 써요.","하나만 지킨 예를 떠올려요.","권리와 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#1','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C2',1,'mc','auto','다음 가운데 주장에 해당하는 문장은 어느 것인가요?',ARRAY['K6-1-u5-X02','K6-1-u5-X03']::text[],false,'{"seq":1,"concept":"K6-1-u5-C2","difficulty":1,"kind":"mc","stem":"다음 가운데 주장에 해당하는 문장은 어느 것인가요?","options":[{"t":"헌책 나눔 상자를 두어 책이 다시 읽히게 하자","correct":true},{"t":"지난해에 보던 책이 쌓인다","mis":"K6-1-u5-X02"},{"t":"종이를 덜 쓰게 되기 때문이다","mis":"K6-1-u5-X03"},{"t":"스물한 명이 헌책을 받아 본 적이 있다고 답했다","mis":"K6-1-u5-X03"}],"explanation":["문제 상황이에요.","이유예요.","하자고 내세운 말이 주장이에요."],"asset":{"type":"passage","lines":["① 학년이 올라가면 지난해에 보던 책이 쌓인다. 현관에 헌책 나눔 상자를 두면 좋겠다.","② 첫째, 책이 필요한 사람에게 옮겨 가기 때문이다. 어떤 조사에 따르면,","집에 읽지 않는 책을 여러 권 두고 있는 학생이 많다고 한다.","③ 둘째, 종이를 덜 쓰게 되기 때문이다. 우리 반 스물다섯 명 가운데 스물한 명이","헌책을 받아 본 적이 있다고 답했다. (솔바람반(2026), 「헌책 이용 설문」, 학급 게시판.)","④ 셋째, 책을 고르는 재미가 생기기 때문이다. 어떤 선생님께서","남의 손을 거친 책을 아이들이 더 궁금해한다고 하셨다.","⑤ 상자 하나면 된다. 헌책 나눔 상자를 두어 책이 다시 읽히게 하자."],"title":"「헌책 나눔 상자를 두면 좋겠습니다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#2','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C14',1,'mc','auto','문단을 대표하는 한 문장을 무엇이라고 하나요?',ARRAY['K6-1-u5-X13','K6-1-u5-X34']::text[],false,'{"seq":2,"concept":"K6-1-u5-C14","difficulty":1,"kind":"mc","stem":"문단을 대표하는 한 문장을 무엇이라고 하나요?","options":[{"t":"중심 문장","correct":true},{"t":"뒷받침 문장","mis":"K6-1-u5-X13"},{"t":"예시 문장","mis":"K6-1-u5-X13"},{"t":"끝맺는 문장","mis":"K6-1-u5-X34"}],"explanation":["뒷받침 문장은 받쳐 줘요.","예시 문장은 예를 들어요.","중심 문장이 문단을 대표해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#3','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C17',1,'ox','auto','여러 글에서 한 문장씩 가져와 이어 붙이고 내 글이라고 하는 것도 표절이에요.',ARRAY['K6-1-u5-X17']::text[],false,'{"seq":3,"concept":"K6-1-u5-C17","difficulty":1,"kind":"ox","stem":"여러 글에서 한 문장씩 가져와 이어 붙이고 내 글이라고 하는 것도 표절이에요.","answer":"O","reason_options":[{"t":"남이 쓴 것을 출처 없이 내 것처럼 썼기 때문에","correct":true},{"t":"한 글에서 통째로 가져온 것만 표절이기 때문에","mis":"K6-1-u5-X17"}],"mis":"K6-1-u5-X17","explanation":["조각도 남의 것이에요.","출처가 없어요.","조각 이어 붙이기도 표절이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#4','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C22',1,'ox','auto','출처를 적는 차례와 부호는 조금씩 달라도 네 가지가 빠지지 않으면 돼요.',ARRAY['K6-1-u5-X22']::text[],false,'{"seq":4,"concept":"K6-1-u5-C22","difficulty":1,"kind":"ox","stem":"출처를 적는 차례와 부호는 조금씩 달라도 네 가지가 빠지지 않으면 돼요.","answer":"O","reason_options":[{"t":"중요한 것은 네 가지를 빠짐없이 갖추는 것이기 때문에","correct":true},{"t":"차례가 하나라도 다르면 틀린 출처이기 때문에","mis":"K6-1-u5-X22"}],"mis":"K6-1-u5-X22","explanation":["차례는 다를 수 있어요.","네 가지가 핵심이에요.","빠짐이 없어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#5','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C24',1,'mc','auto','많이 인용할수록 좋은 글이 되지 않는 까닭은 어느 것인가요?',ARRAY['K6-1-u5-X18','K6-1-u5-X23','K6-1-u5-X24']::text[],false,'{"seq":5,"concept":"K6-1-u5-C24","difficulty":1,"kind":"mc","stem":"많이 인용할수록 좋은 글이 되지 않는 까닭은 어느 것인가요?","options":[{"t":"글에 담아야 할 글쓴이의 생각이 남지 않기 때문이다","correct":true},{"t":"출처를 적기 귀찮기 때문이다","mis":"K6-1-u5-X18"},{"t":"자료는 근거가 될 수 없기 때문이다","mis":"K6-1-u5-X23"},{"t":"글이 짧아지기 때문이다","mis":"K6-1-u5-X24"}],"explanation":["귀찮음의 문제가 아니에요.","자료는 근거가 돼요.","내 생각이 중심이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#6','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C39',1,'mc','auto','조직한 것을 바탕으로 스스로 문장을 써 처음 글을 쓰는 단계는 어느 것인가요?',ARRAY['K6-1-u5-X37']::text[],false,'{"seq":6,"concept":"K6-1-u5-C39","difficulty":1,"kind":"mc","stem":"조직한 것을 바탕으로 스스로 문장을 써 처음 글을 쓰는 단계는 어느 것인가요?","options":[{"t":"표현하기","correct":true},{"t":"내용 조직하기","mis":"K6-1-u5-X37"},{"t":"계획하기","mis":"K6-1-u5-X37"},{"t":"내용 생성하기","mis":"K6-1-u5-X37"}],"explanation":["조직하기는 낱말과 어구로도 돼요.","계획하기는 정해요.","문장을 써 내려가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#7','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C35',1,'ox','auto','쓰다가 읽을 사람이 달라져야 함을 알면 계획하기로 돌아가도 돼요.',ARRAY['K6-1-u5-X30']::text[],false,'{"seq":7,"concept":"K6-1-u5-C35","difficulty":1,"kind":"ox","stem":"쓰다가 읽을 사람이 달라져야 함을 알면 계획하기로 돌아가도 돼요.","answer":"O","reason_options":[{"t":"계획하기는 글을 쓰기 전에만 거치는 단계가 아니기 때문에","correct":true},{"t":"계획은 한 번 세우면 바꿀 수 없기 때문에","mis":"K6-1-u5-X30"}],"mis":"K6-1-u5-X30","explanation":["쓰는 도중에도 계획을 고쳐요.","어긋난 계획을 붙들지 않아요.","언제든 돌아갈 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#8','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C52',1,'mc','auto','가루처럼 잘게 내리는 눈을 가리키는 우리말은 어느 것인가요?',ARRAY['K6-1-u5-X48']::text[],false,'{"seq":8,"concept":"K6-1-u5-C52","difficulty":1,"kind":"mc","stem":"가루처럼 잘게 내리는 눈을 가리키는 우리말은 어느 것인가요?","options":[{"t":"가루눈","correct":true},{"t":"숫눈","mis":"K6-1-u5-X48"},{"t":"먼지잼","mis":"K6-1-u5-X48"},{"t":"밤비","mis":"K6-1-u5-X48"}],"explanation":["숫눈은 밟지 않은 눈이에요.","먼지잼은 비예요.","가루처럼 내리는 눈이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#9','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C21',2,'mc','auto','③문단의 출처가 믿을 만한 까닭은 어느 것인가요?',ARRAY['K6-1-u5-X14','K6-1-u5-X21','K6-1-u5-X15']::text[],false,'{"seq":9,"concept":"K6-1-u5-C21","difficulty":2,"kind":"mc","stem":"③문단의 출처가 믿을 만한 까닭은 어느 것인가요?","options":[{"t":"만든 사람 · 시기 · 자료의 이름 · 실린 곳이 모두 있어 찾아가 확인할 수 있기 때문이다","correct":true},{"t":"숫자가 들어 있기 때문이다","mis":"K6-1-u5-X14"},{"t":"문단의 가운데에 있기 때문이다","mis":"K6-1-u5-X21"},{"t":"내 생각과 같기 때문이다","mis":"K6-1-u5-X15"}],"explanation":["수가 있다고 믿을 만한 것은 아니에요.","놓인 곳은 관계없어요.","네 가지를 갖췄어요."],"asset":{"type":"passage","lines":["① 학년이 올라가면 지난해에 보던 책이 쌓인다. 현관에 헌책 나눔 상자를 두면 좋겠다.","② 첫째, 책이 필요한 사람에게 옮겨 가기 때문이다. 어떤 조사에 따르면,","집에 읽지 않는 책을 여러 권 두고 있는 학생이 많다고 한다.","③ 둘째, 종이를 덜 쓰게 되기 때문이다. 우리 반 스물다섯 명 가운데 스물한 명이","헌책을 받아 본 적이 있다고 답했다. (솔바람반(2026), 「헌책 이용 설문」, 학급 게시판.)","④ 셋째, 책을 고르는 재미가 생기기 때문이다. 어떤 선생님께서","남의 손을 거친 책을 아이들이 더 궁금해한다고 하셨다.","⑤ 상자 하나면 된다. 헌책 나눔 상자를 두어 책이 다시 읽히게 하자."],"title":"「헌책 나눔 상자를 두면 좋겠습니다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#10','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C11',2,'mc','auto','①문단이 서론인 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X10']::text[],false,'{"seq":10,"concept":"K6-1-u5-C11","difficulty":2,"kind":"mc","stem":"①문단이 서론인 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"책이 쌓이는 문제를 꺼내고 나눔 상자를 두자는 주장을 밝혔기 때문이다","correct":true},{"t":"세 가지 까닭을 모아 말했기 때문이다","mis":"K6-1-u5-X10"},{"t":"이유마다 근거를 붙였기 때문이다","mis":"K6-1-u5-X10"},{"t":"처음 꺼내는 근거가 많기 때문이다","mis":"K6-1-u5-X10"}],"explanation":["모아 말하는 것은 결론이에요.","이유와 근거는 본론이에요.","문제와 주장을 밝혔어요."],"asset":{"type":"passage","lines":["① 학년이 올라가면 지난해에 보던 책이 쌓인다. 현관에 헌책 나눔 상자를 두면 좋겠다.","② 첫째, 책이 필요한 사람에게 옮겨 가기 때문이다. 어떤 조사에 따르면,","집에 읽지 않는 책을 여러 권 두고 있는 학생이 많다고 한다.","③ 둘째, 종이를 덜 쓰게 되기 때문이다. 우리 반 스물다섯 명 가운데 스물한 명이","헌책을 받아 본 적이 있다고 답했다. (솔바람반(2026), 「헌책 이용 설문」, 학급 게시판.)","④ 셋째, 책을 고르는 재미가 생기기 때문이다. 어떤 선생님께서","남의 손을 거친 책을 아이들이 더 궁금해한다고 하셨다.","⑤ 상자 하나면 된다. 헌책 나눔 상자를 두어 책이 다시 읽히게 하자."],"title":"「헌책 나눔 상자를 두면 좋겠습니다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#11','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C14',2,'mc','auto','우재 초고 ②문단의 중심 문장은 어느 것인가요?',ARRAY['K6-1-u5-X13','K6-1-u5-X10']::text[],false,'{"seq":11,"concept":"K6-1-u5-C14","difficulty":2,"kind":"mc","stem":"우재 초고 ②문단의 중심 문장은 어느 것인가요?","options":[{"t":"첫째, 한 줄로 서면 밀치다 넘어질 일이 줄기 때문이다","correct":true},{"t":"우리 반 스물네 명 가운데 열다섯 명이 밀린 적이 있다고 답했다","mis":"K6-1-u5-X13"},{"t":"새솔반(2026), 「급식실 앞 줄서기 설문」, 학급 게시판","mis":"K6-1-u5-X13"},{"t":"급식실 앞에서는 한 줄로 서야 한다","mis":"K6-1-u5-X10"}],"explanation":["조사 결과는 뒷받침 문장이에요.","출처는 근거에 붙은 것이에요.","문단을 대표하는 문장이에요."],"asset":{"type":"passage","lines":["① 점심시간 급식실 앞은 늘 북적인다. 줄이 두세 갈래로 엉켜 서로 밀치기도 한다.","급식실 앞에서는 한 줄로 서야 한다.","② 첫째, 한 줄로 서면 밀치다 넘어질 일이 줄기 때문이다. 우리 반 스물네 명","가운데 열다섯 명이 급식실 앞에서 밀린 적이 있다고 답했다.","(새솔반(2026), 「급식실 앞 줄서기 설문」, 학급 게시판.)","③ 둘째, 먼저 온 사람이 먼저 먹을 수 있기 때문이다. 어떤 조사에 따르면","줄이 엉키면 늦게 온 사람이 먼저 들어가는 일이 많다고 한다.","급식실 반찬은 골고루 먹어야 키가 큰다."],"title":"우재의 초고 「급식실 앞에서는 한 줄로 섭시다」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#12','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C36',2,'mc','auto','우재가 ③문단 근거를 고치려고 할 때 돌아갈 쓰기 단계는 어느 것인가요?',ARRAY['K6-1-u5-X41','K6-1-u5-X38','K6-1-u5-X31']::text[],false,'{"seq":12,"concept":"K6-1-u5-C36","difficulty":2,"kind":"mc","stem":"우재가 ③문단 근거를 고치려고 할 때 돌아갈 쓰기 단계는 어느 것인가요?","options":[{"t":"내용 생성하기","correct":true},{"t":"고쳐쓰기만 하면 된다","mis":"K6-1-u5-X41"},{"t":"처음부터 다시 쓴다","mis":"K6-1-u5-X38"},{"t":"표현하기에서 문장만 다듬는다","mis":"K6-1-u5-X31"}],"explanation":["근거를 새로 찾아야 해요.","처음부터가 아니에요.","자료 모으기 단계로 돌아가요."],"asset":{"type":"speech","turns":[{"who":"우재","text":"다 썼는데 둘째 이유의 근거가 「어떤 조사에 따르면」이야. 다시 자료를 찾으면 처음부터 다시 하는 거잖아."},{"who":"하영","text":"처음부터가 아니라 내용 생성하기로 잠깐 돌아가는 거야. 우리 반에서 직접 세어 보면 되지."},{"who":"우재","text":"그리고 이 글은 동생들도 읽을 텐데 「급식 지도」 같은 말은 어려울까?"},{"who":"하영","text":"그건 계획하기에서 읽을 사람을 다시 보는 거네. 고칠 곳을 찾았다는 건 네가 볼 줄 알게 됐다는 뜻이야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#13','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C13',2,'mc','auto','우재 초고 ⑤문단이 결론으로 하는 일은 어느 것인가요?',ARRAY['K6-1-u5-X11','K6-1-u5-X10']::text[],false,'{"seq":13,"concept":"K6-1-u5-C13","difficulty":2,"kind":"mc","stem":"우재 초고 ⑤문단이 결론으로 하는 일은 어느 것인가요?","options":[{"t":"세 가지 까닭을 모아 말하고 한 줄로 서자는 주장을 다시 강조한다","correct":true},{"t":"처음 꺼내는 근거를 든다","mis":"K6-1-u5-X11"},{"t":"급식실 문제를 처음 제기한다","mis":"K6-1-u5-X10"},{"t":"이유마다 출처를 붙인다","mis":"K6-1-u5-X10"}],"explanation":["새 근거는 두지 않아요.","문제 제기는 서론이에요.","모으고 다시 힘줘요."],"asset":{"type":"passage","lines":["④ 셋째, 줄을 정리하시는 선생님의 일이 줄기 때문이다. 급식 지도를 맡으신","선생님께서 엉킨 줄을 푸는 데 점심시간의 많은 부분을 쓰신다고 하셨다.","(최○○ 선생님 면담(2026), 「급식 지도 이야기」, 급식실.)","⑤ 지금까지 세 가지 까닭을 살펴보았다. 한 줄로 서는 일은 어렵지 않다.","급식실 앞에서는 한줄로 서서 모두가 편안한 점심시간을 만들자.","줄을 서지 않고 끼어드는 사람은 정말 이기적인 사람이다."],"title":"우재의 초고 — 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#14','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C23',2,'mc','auto','하영이가 「우리 반에서 직접 세어 보면 되지」라고 한 근거가 믿을 만해지려면 무엇을 함께 적어야 하나요?',ARRAY['K6-1-u5-X09','K6-1-u5-X23']::text[],false,'{"seq":14,"concept":"K6-1-u5-C23","difficulty":2,"kind":"mc","stem":"하영이가 「우리 반에서 직접 세어 보면 되지」라고 한 근거가 믿을 만해지려면 무엇을 함께 적어야 하나요?","options":[{"t":"언제 · 누구에게 · 어디서 조사했는지와 실린 곳","correct":true},{"t":"세어 본 사람의 느낌","mis":"K6-1-u5-X09"},{"t":"친구들의 짐작","mis":"K6-1-u5-X09"},{"t":"아무것도 적지 않아도 된다","mis":"K6-1-u5-X23"}],"explanation":["느낌은 근거가 아니에요.","짐작도 아니에요.","직접 조사도 출처를 적어요."],"asset":{"type":"speech","turns":[{"who":"우재","text":"다 썼는데 둘째 이유의 근거가 「어떤 조사에 따르면」이야. 다시 자료를 찾으면 처음부터 다시 하는 거잖아."},{"who":"하영","text":"처음부터가 아니라 내용 생성하기로 잠깐 돌아가는 거야. 우리 반에서 직접 세어 보면 되지."},{"who":"우재","text":"그리고 이 글은 동생들도 읽을 텐데 「급식 지도」 같은 말은 어려울까?"},{"who":"하영","text":"그건 계획하기에서 읽을 사람을 다시 보는 거네. 고칠 곳을 찾았다는 건 네가 볼 줄 알게 됐다는 뜻이야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#15','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C50',2,'mc','auto','하영이가 표어를 붙인 뒤 해야 할 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X46','K6-1-u5-X44','K6-1-u5-X25']::text[],false,'{"seq":15,"concept":"K6-1-u5-C50","difficulty":2,"kind":"mc","stem":"하영이가 표어를 붙인 뒤 해야 할 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"내일부터 일주일 동안 자신이 먼저 한 줄로 서고 날마다 지켰는지 표시한다","correct":true},{"t":"표어를 붙였으니 할 일을 다 했다","mis":"K6-1-u5-X46"},{"t":"표어 글씨를 더 크게 다시 쓴다","mis":"K6-1-u5-X44"},{"t":"반대하는 친구의 표어를 뗀다","mis":"K6-1-u5-X25"}],"explanation":["붙이고 끝이 아니에요.","크기가 설득이 아니에요.","남의 것을 떼면 안 돼요."],"asset":{"type":"passage","lines":["표어 — 「한 줄이면 모두가 먼저」","의견 — 급식실 앞에서는 한 줄로 섭시다.","까닭 — 엉킨 줄에서는 밀려 넘어질 수 있기 때문입니다.","사례 — 우리 반 스물네 명 가운데 열다섯 명이 밀린 적이 있다고 답했습니다.","제안 — 내일 점심부터 급식실 앞에서는 한 줄로 서 봅시다."],"title":"하영이 만든 표어와 네 칸 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#16','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C52',2,'mc','auto','사전에서 다른 비 이름을 더 찾을 때 알맞은 방법은 어느 것인가요?',ARRAY['K6-1-u5-X48']::text[],false,'{"seq":16,"concept":"K6-1-u5-C52","difficulty":2,"kind":"mc","stem":"사전에서 다른 비 이름을 더 찾을 때 알맞은 방법은 어느 것인가요?","options":[{"t":"「비」를 표제어로 잡고 그 아래에 딸린 말을 살핀다","correct":true},{"t":"사전 첫 쪽부터 차례로 넘긴다","mis":"K6-1-u5-X48"},{"t":"짐작한 이름을 그대로 맞다고 여긴다","mis":"K6-1-u5-X48"},{"t":"「여우」를 찾아 동물 뜻만 읽는다","mis":"K6-1-u5-X48"}],"explanation":["처음부터 넘기면 오래 걸려요.","짐작은 확인해야 해요.","「비」를 잡고 딸린 말을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#17','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C9',3,'mc','auto','「빈 교실의 불을 끕시다」에 붙이기에 타당하지 않은 이유는 어느 것인가요?',ARRAY['K6-1-u5-X08']::text[],false,'{"seq":17,"concept":"K6-1-u5-C9","difficulty":3,"kind":"mc","stem":"「빈 교실의 불을 끕시다」에 붙이기에 타당하지 않은 이유는 어느 것인가요?","options":[{"t":"교실 벽 색이 칙칙하기 때문이다","correct":true},{"t":"쓰지 않는 전기가 낭비되기 때문이다","mis":"K6-1-u5-X08"},{"t":"켜 둔 선풍기가 뜨거워질 수 있기 때문이다","mis":"K6-1-u5-X08"},{"t":"끄는 사람이 정해져 있지 않아 늘 켜져 있기 때문이다","mis":"K6-1-u5-X08"}],"explanation":["전기 낭비는 이어져요.","안전과 이어져요.","벽 색은 불을 끄는 일과 이어지지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#18','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C20',3,'mc','auto','친구가 내가 쓴 주장하는 글을 자기 이름으로 학급 신문에 실었어요. 무엇을 지키지 않은 것인가요?',ARRAY['K6-1-u5-X20']::text[],false,'{"seq":18,"concept":"K6-1-u5-C20","difficulty":3,"kind":"mc","stem":"친구가 내가 쓴 주장하는 글을 자기 이름으로 학급 신문에 실었어요. 무엇을 지키지 않은 것인가요?","options":[{"t":"저작자인 나의 저작권","correct":true},{"t":"학급 신문의 편집 규칙","mis":"K6-1-u5-X20"},{"t":"친구의 저작권","mis":"K6-1-u5-X20"},{"t":"지키지 않은 것이 없다","mis":"K6-1-u5-X20"}],"explanation":["신문 규칙 문제만이 아니에요.","글을 쓴 사람은 나예요.","내 글도 저작물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#19','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C32',3,'mc','auto','발표를 글로 쓰기 전에 말로 먼저 해 보면 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X46','K6-1-u5-X44','K6-1-u5-X32']::text[],false,'{"seq":19,"concept":"K6-1-u5-C32","difficulty":3,"kind":"mc","stem":"발표를 글로 쓰기 전에 말로 먼저 해 보면 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"쓰기 부담을 줄이면서 주장과 근거의 흐름을 먼저 확인할 수 있다","correct":true},{"t":"말로 했으니 글은 쓰지 않아도 된다","mis":"K6-1-u5-X46"},{"t":"목소리를 키우면 근거가 필요 없어진다","mis":"K6-1-u5-X44"},{"t":"출처는 말할 때만 밝힌다","mis":"K6-1-u5-X32"}],"explanation":["글로도 옮겨요.","크기가 아니라 근거예요.","글에도 출처를 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#20','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C40',3,'mc','auto','우재가 다 쓴 뒤에야 「어떤 조사에 따르면」을 발견했어요. 쓰는 도중에 점검했다면 무엇이 달랐을까요?',ARRAY['K6-1-u5-X36','K6-1-u5-X06','K6-1-u5-X37']::text[],false,'{"seq":20,"concept":"K6-1-u5-C40","difficulty":3,"kind":"mc","stem":"우재가 다 쓴 뒤에야 「어떤 조사에 따르면」을 발견했어요. 쓰는 도중에 점검했다면 무엇이 달랐을까요?","options":[{"t":"내용 생성하기 단계에서 출처가 흐린 것을 바로 알아차려 그때 자료를 바꿀 수 있었다","correct":true},{"t":"달라질 것이 없다","mis":"K6-1-u5-X36"},{"t":"글이 더 길어졌을 것이다","mis":"K6-1-u5-X06"},{"t":"표현하기 단계를 건너뛸 수 있었다","mis":"K6-1-u5-X37"}],"explanation":["도중 점검은 그때 바로잡게 해요.","길이 문제가 아니에요.","단계를 건너뛰는 게 아니에요."],"asset":{"type":"speech","turns":[{"who":"우재","text":"다 썼는데 둘째 이유의 근거가 「어떤 조사에 따르면」이야. 다시 자료를 찾으면 처음부터 다시 하는 거잖아."},{"who":"하영","text":"처음부터가 아니라 내용 생성하기로 잠깐 돌아가는 거야. 우리 반에서 직접 세어 보면 되지."},{"who":"우재","text":"그리고 이 글은 동생들도 읽을 텐데 「급식 지도」 같은 말은 어려울까?"},{"who":"하영","text":"그건 계획하기에서 읽을 사람을 다시 보는 거네. 고칠 곳을 찾았다는 건 네가 볼 줄 알게 됐다는 뜻이야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#21','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C44',3,'mc','auto','고칠 곳이 많아 다시 쓰기가 버거운 우재에게 알맞은 방법은 어느 것인가요?',ARRAY['K6-1-u5-X40','K6-1-u5-X07','K6-1-u5-X41']::text[],false,'{"seq":21,"concept":"K6-1-u5-C44","difficulty":3,"kind":"mc","stem":"고칠 곳이 많아 다시 쓰기가 버거운 우재에게 알맞은 방법은 어느 것인가요?","options":[{"t":"원래 글 위에 쪽지를 붙여 고칠 말만 얹고, 어디를 왜 고쳤는지 한 줄 적는다","correct":true},{"t":"글을 버리고 다른 주제로 새로 쓴다","mis":"K6-1-u5-X40"},{"t":"고칠 곳이 많으니 아무것도 고치지 않는다","mis":"K6-1-u5-X07"},{"t":"맞춤법 하나만 고치고 나머지는 덮는다","mis":"K6-1-u5-X41"}],"explanation":["버리지 않아도 돼요.","한 군데부터 고쳐요.","큰 고침도 쪽지로 할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#22','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C49',3,'mc','auto','「까닭」 칸과 「사례」 칸의 차이로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X45']::text[],false,'{"seq":22,"concept":"K6-1-u5-C49","difficulty":3,"kind":"mc","stem":"「까닭」 칸과 「사례」 칸의 차이로 알맞은 것은 어느 것인가요?","options":[{"t":"까닭은 왜 그렇게 여기는지 밝히고, 사례는 실제로 있었던 일이나 조사 결과를 든다","correct":true},{"t":"까닭과 사례는 같은 칸이다","mis":"K6-1-u5-X45"},{"t":"사례는 하고 싶은 말을 처음 꺼낸다","mis":"K6-1-u5-X45"},{"t":"까닭은 그러니 이렇게 하자고 마무리한다","mis":"K6-1-u5-X45"}],"explanation":["두 칸은 하는 일이 달라요.","처음 꺼내는 건 의견이에요.","마무리는 제안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#23','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C48',4,'mc','auto','하영이의 표어와 네 칸 글을 가장 알맞게 평가한 것은 어느 것인가요?',ARRAY['K6-1-u5-X44','K6-1-u5-X45','K6-1-u5-X14']::text[],false,'{"seq":23,"concept":"K6-1-u5-C48","difficulty":4,"kind":"mc","stem":"하영이의 표어와 네 칸 글을 가장 알맞게 평가한 것은 어느 것인가요?","options":[{"t":"짧은 표어로 눈길을 끌고, 네 칸 짜임으로 까닭과 확인할 수 있는 사례를 남겨 설득력을 갖추었다","correct":true},{"t":"표어가 짧으니 근거는 없어도 된다","mis":"K6-1-u5-X44"},{"t":"네 칸 가운데 제안은 빼도 된다","mis":"K6-1-u5-X45"},{"t":"출처를 밝혔으니 더 볼 것이 없다","mis":"K6-1-u5-X14"}],"explanation":["짧아도 근거는 남겨요.","제안으로 다시 밀어 줘요.","출처가 곧 타당함은 아니에요."],"asset":{"type":"passage","lines":["표어 — 「한 줄이면 모두가 먼저」","의견 — 급식실 앞에서는 한 줄로 섭시다.","까닭 — 엉킨 줄에서는 밀려 넘어질 수 있기 때문입니다.","사례 — 우리 반 스물네 명 가운데 열다섯 명이 밀린 적이 있다고 답했습니다.","제안 — 내일 점심부터 급식실 앞에서는 한 줄로 서 봅시다."],"title":"하영이 만든 표어와 네 칸 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#24','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C31',4,'essay','teacher','우재의 주장 「급식실 앞에서는 한 줄로 섭시다」에 나올 만한 반박을 하나 쓰고, 반박을 받아들여 결론을 어떻게 고칠지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u5-C31","difficulty":4,"kind":"essay","stem":"우재의 주장 「급식실 앞에서는 한 줄로 섭시다」에 나올 만한 반박을 하나 쓰고, 반박을 받아들여 결론을 어떻게 고칠지 쓰세요.","answer_guide":{"answer":"예: 반박 — 「한 줄로 서면 줄이 길어져 복도를 막아 다른 사람이 지나가기 어려워요.」 이 걱정이 맞으므로 결론을 「급식실 앞에서는 벽을 따라 한 줄로 서서 모두가 편안한 점심시간을 만들자.」로 고치겠다. 반박을 미리 받아들이면 주장이 더 단단해진다.","scoring_points":["나올 만한 반박을 썼는가","반박을 받아들여 결론을 고쳤는가","주장이 단단해지는 까닭을 썼는가"]},"explanation":["반대할 사람이 되어 봐요.","받아들일 점을 찾아요.","결론에 보태요."],"asset":{"type":"passage","lines":["④ 셋째, 줄을 정리하시는 선생님의 일이 줄기 때문이다. 급식 지도를 맡으신","선생님께서 엉킨 줄을 푸는 데 점심시간의 많은 부분을 쓰신다고 하셨다.","(최○○ 선생님 면담(2026), 「급식 지도 이야기」, 급식실.)","⑤ 지금까지 세 가지 까닭을 살펴보았다. 한 줄로 서는 일은 어렵지 않다.","급식실 앞에서는 한줄로 서서 모두가 편안한 점심시간을 만들자.","줄을 서지 않고 끼어드는 사람은 정말 이기적인 사람이다."],"title":"우재의 초고 — 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#25','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C47',4,'essay','teacher','우리 학교에서 내가 바꿀 수 있는 문제 하나로 주장을 한 문장으로 세우고, 이유 하나 · 근거 하나(출처 포함)를 쓴 뒤, 말한 대로 어떻게 실천할지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u5-C47","difficulty":4,"kind":"essay","stem":"우리 학교에서 내가 바꿀 수 있는 문제 하나로 주장을 한 문장으로 세우고, 이유 하나 · 근거 하나(출처 포함)를 쓴 뒤, 말한 대로 어떻게 실천할지 쓰세요.","answer_guide":{"answer":"예: 주장 — 다 쓴 미술 도구는 제자리에 돌려놓읍시다. 이유 — 다음 반이 도구를 찾느라 수업 시간이 줄기 때문이다. 근거 — 일주일 동안 미술실에 들어갈 때마다 세어 보니 다섯 번 가운데 세 번은 붓이 흩어져 있었다. (솔바람반(2026), 「미술실 도구 관찰 기록」, 학급 게시판.) 실천 — 일주일 동안 내가 쓴 도구를 돌려놓았는지 날마다 표시하고, 끝나면 달라진 점을 한 줄로 적겠다.","scoring_points":["바꿀 수 있는 문제로 한 문장 주장을 세웠는가","이유와 출처를 갖춘 근거를 썼는가","말한 대로 해 볼 실천 방법을 썼는가"]},"explanation":["우리 힘으로 바꿀 문제를 골라요.","이유와 근거 · 출처를 붙여요.","먼저 해 볼 방법을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C1','kor',6,1,'u6',1,'비판적 읽기의 뜻 — 비판적으로 읽는다는 것은 글을 그대로 받아들이지 않고 내용과 표현이 알맞은지 판단하며 읽는 것으로, 게시판에 붙어 있거나 책에 적혀 있다고 해서 모두 옳은 것은 아니다',ARRAY['6국02-03 읽기']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C2','kor',6,1,'u6',1,'「이상하다」는 물음 — 읽다가 의문이 드는 곳 · 받아들이기 어려운 곳 · 오해하기 쉬운 곳을 「이상한데?」 하고 멈추어 짚는 것이 비판적 읽기의 첫걸음이며, 그 물음을 그냥 넘기지 않고 어디가 왜 이상한지 따져 본다',ARRAY['6국02-03 읽기']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C3','kor',6,1,'u6',1,'판단하며 읽기의 두 갈래 — 글은 「무엇을 말하는가」와 「어떻게 말하는가」로 이루어져 있어, 내용의 타당성(주장 · 이유 · 근거가 이치에 맞는가)과 표현의 적절성(거짓 · 과장 · 감춤이 없는가)을 함께 살핀다',ARRAY['6국02-03 읽기']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C4','kor',6,1,'u6',1,'글의 목적에 따라 살필 것 — 주장하는 글에서는 그 주장이 나에게 도움이 되는지, 물건을 알리는 광고에서는 특징을 제대로 나타냈는지, 무엇을 알려 주는 글에서는 그 정보를 믿을 만한지를 먼저 살핀다',ARRAY['6국02-03 읽기']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C5','kor',6,1,'u6',1,'비판은 흠 잡기가 아니다 — 틀린 데를 많이 찾을수록 잘 읽은 것이 아니라, 맞는 곳은 받아들이고 이상한 곳은 까닭을 대며 짚는 것이 비판적 읽기이며, 그 목적은 글을 깎아내리는 것이 아니라 나에게 필요한 정보를 골라내는 것이다',ARRAY['6국02-03 읽기']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C6','kor',6,1,'u6',1,'판단에는 언제나 까닭 — 「이상해」 · 「별로야」처럼 까닭 없는 판단은 판단이 아니라 기분이며, 그렇게 판단한 까닭을 함께 대야 다른 사람이 따져 보고 고칠 곳을 알 수 있다',ARRAY['6국02-03 읽기']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C7','kor',6,1,'u6',2,'주장하는 글의 짜임과 주장 찾기 — 서론은 관심을 끌고 글의 방향을 알리고, 본론은 이유와 그 이유를 받치는 근거를 내놓고, 결론은 글을 마무리하며 주장을 다시 정리하므로, 서론과 결론이 함께 가리키는 말이 주장이다',ARRAY['6국02-03 읽기']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C8','kor',6,1,'u6',2,'타당성의 뜻 — 타당성은 이치에 맞는 옳은 성질이고, 내용의 타당성은 글의 내용이 이치에 맞게 옳은지를 말하며, 「주장은 가치 있고 중요한가 · 이유는 주장을 뒷받침하는가 · 근거는 이유를 뒷받침하는가」 세 물음으로 잰다',ARRAY['6국02-03 읽기']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C9','kor',6,1,'u6',2,'기준 하나 — 주장의 가치 — 주장이 가치 있고 중요한지는 그 주장이 여러 사람에게 도움이 되는가와 많은 사람이 받아들일 수 있는가로 재며, 하자는 대로 했을 때 다른 문제가 생기는 주장(물을 아끼려면 세수를 하지 말자)은 가치 있다고 보기 어렵다',ARRAY['6국02-03 읽기']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C10','kor',6,1,'u6',2,'기준 둘 — 이유의 뒷받침 — 이유는 주장과 관련이 있고 많은 사람이 받아들일 수 있어야 하며, 맞는 말이라도 주장과 이어지지 않으면(도서관 책을 접지 말자 ← 도서관은 조용한 곳이다) 이유가 되지 못한다 — 참인 문장이라고 다 이유는 아니다',ARRAY['6국02-03 읽기']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C11','kor',6,1,'u6',2,'주장과 어긋나는 이유 — 이유가 주장과 반대 방향을 가리키면(급식을 남기지 말자 ← 반찬을 골라 먹는 재미가 있다) 글은 오히려 힘을 잃으므로, 이유를 넣기 전에 「이 문장이 내 주장 편에 서 있는가」를 묻는다',ARRAY['6국02-03 읽기']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C12','kor',6,1,'u6',2,'기준 셋 — 근거의 뒷받침 — 근거는 이유와 관련이 있고 객관적인 사실이나 정보를 활용해야 하며, 담당하시는 분께 여쭈어 확인한 사실은 근거가 되지만 「늘어난 것 같다」는 한 사람의 짐작은 근거가 되지 못한다',ARRAY['6국02-03 읽기']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C13','kor',6,1,'u6',2,'타당성은 어느 글에서나 — 타당성은 주장하는 글에서만 재는 것이 아니라 알림글 · 소식 · 설명하는 글처럼 내용을 담은 글이면 어디에든 같은 물음으로 물어볼 수 있다',ARRAY['6국02-03 읽기']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C14','kor',6,1,'u6',2,'스스로 세우는 판단 기준 — 판단 기준은 세 가지만 있는 것이 아니라 「거짓 정보는 없는가」 · 「한쪽으로 치우치지 않았는가」 · 「쓸데없는 정보가 들어 있지 않은가」처럼 알맞은 기준을 물음의 꼴로 스스로 더 세워 써도 좋다',ARRAY['6국02-03 읽기']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C15','kor',6,1,'u6',4,'적혀 있어도 한 번 더 확인 — 글에 적혀 있다고 해서 모두 그대로 일어나지는 않으므로, 큰 글씨만 읽고 넘어가지 말고 작은 글씨와 뒷부분까지 읽으며 읽는 사람이 한 번 더 확인한다',ARRAY['6국02-03 읽기']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C16','kor',6,1,'u6',4,'이유와 근거 짝짓기 — 한 편의 글을 판단하려면 먼저 근거가 어느 이유에 붙는지 잡아야 하며, 주장하는 글에서는 대개 이유와 그 근거가 같은 문단 안에 붙어 있다',ARRAY['6국02-03 읽기']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C17','kor',6,1,'u6',4,'판단과 까닭은 한 짝 — 「가치 있다 — 다치는 일을 줄여 주고 누구나 받아들일 만하므로」처럼 판단에 까닭이 붙은 답이 좋은 답이며, 「글에 그렇게 적혀 있으므로」는 판단이 같아도 까닭이 되지 못한다',ARRAY['6국02-03 읽기']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C18','kor',6,1,'u6',4,'사실이 아닌 이유 — 「안전모를 쓰면 자전거가 더 빨리 달린다」처럼 실제로 일어나지 않는 일을 이유로 들면 이유가 되지 못할 뿐 아니라 읽는 사람을 잘못 알게 하며, 한 문장이 「사실이 아님」과 「주장과 어긋남」 두 곳에 함께 걸리기도 한다',ARRAY['6국02-03 읽기']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C19','kor',6,1,'u6',4,'되짚어 확인할 수 있는 근거 — 직접 세어 본 기록 · 물건에 적힌 안내 · 담당하시는 분께 여쭈어본 답처럼 다른 사람도 같은 길로 다시 가 볼 수 있는 것이 좋은 근거이며, 한 사람에게서 전해 들은 말은 누구도 다시 확인할 수 없어 근거가 되기 어렵다',ARRAY['6국02-03 읽기']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C20','kor',6,1,'u6',4,'차례대로 재기 — 한 편의 글은 주장 → 이유 → 근거의 차례로 세 기준을 하나씩 대어 재며, 판단할 때마다 왜 그렇게 판단했는지를 함께 말한다',ARRAY['6국02-03 읽기']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C21','kor',6,1,'u6',4,'받아들일 것을 골라내기 — 걸린 곳을 찾았다고 글 전체를 버리지 않으며, 한 편의 글은 고르게 타당하지도 고르게 부족하지도 않으므로 걸린 곳만 까닭을 대어 짚고 타당한 부분은 받아들인다 — 받아들일 것을 골라내는 일도 판단이다',ARRAY['6국02-03 읽기']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C22','kor',6,1,'u6',4,'둘레의 글에 대어 보기 — 교실 게시판 · 학교 누리집 · 물건 포장에 적힌 글에서도 주장 · 이유 · 근거를 옮겨 적고 세 기준으로 재며, 걸리는 곳은 왜 걸리는지와 어떻게 고치면 좋을지를 함께 적는다',ARRAY['6국02-03 읽기']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C23','kor',6,1,'u6',7,'표현의 적절성 — 앞에서 글이 무엇을 말하는가를 재었다면, 표현의 적절성은 그것을 어떻게 말하는가 — 그 내용을 알맞은 말로 나타냈는가를 재는 것이며, 가장 눈에 띄게 말하는 광고에서부터 살펴본다',ARRAY['6국02-03 읽기']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C24','kor',6,1,'u6',7,'광고가 뜻을 전하는 방법 — 광고는 글 · 그림 · 색 · 크기 · 배치로 뜻을 전하므로 큰 글씨 · 진한 색 · 느낌표는 「여기를 봐 달라」는 자국이며, 무엇을 크게 했는지만큼 무엇을 작게 했는지도 보아야 한다',ARRAY['6국02-03 읽기']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C25','kor',6,1,'u6',7,'거짓된 표현 — 거짓된 표현은 없는 것을 있는 것처럼 말한 표현으로, 물통 광고의 「뚜껑을 열어도 얼음이 녹지 않아요」처럼 실제로 일어날 수 없는 일을 있다고 말한 것이다(뚜껑을 열면 바깥 공기가 바로 들어온다)',ARRAY['6국02-03 읽기']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C26','kor',6,1,'u6',7,'과장된 표현 — 과장된 표현은 있는 것을 실제보다 부풀린 표현으로, 「무조건 · 절대 · 최고 · 백 퍼센트」나 「이것 하나면 끝」 같은 말은 보는 사람의 판단을 흐린다',ARRAY['6국02-03 읽기']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C27','kor',6,1,'u6',7,'감추는 내용 — 감추는 내용은 알아야 할 것을 밝히지 않은 것으로, 「가장 많이 팔린」처럼 언제 · 어디에서 · 무엇과 견주었는지 빠졌거나 꼭 알려야 할 조건을 눈에 들어오지 않을 만큼 작게 적은 것이다 — 읽고 나서 「그런데 어디에서?」가 남는다',ARRAY['6국02-03 읽기']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C28','kor',6,1,'u6',7,'거짓과 과장을 가르는 자 — 거짓과 과장은 「그 기능이 실제로 있는가」로 가르며, 없는 기능을 있다고 하면 거짓, 있는 기능을 부풀리면 과장이다(새지 않게 만든 뚜껑을 「절대 새지 않는다」고 하면 과장)',ARRAY['6국02-03 읽기']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C29','kor',6,1,'u6',7,'한 표현이 두 기준에 — 「이보다 좋은 물통은 없습니다」는 실제보다 부풀린 과장이면서 어떤 점에서 좋다는 것인지 밝히지 않은 감춤이기도 하듯, 한 문구가 두 기준에 함께 걸릴 수 있으며 기준은 서로를 밀어내지 않는다',ARRAY['6국02-03 읽기']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C30','kor',6,1,'u6',7,'광고만의 일이 아니다 — 부풀리고 감추는 일은 광고만의 특성이 아니라 설득하려는 글이면 어디서든 일어날 수 있고, 부풀리지 않았다고 다 믿을 수 있는 것도 아니라 오래되어 지금과 맞지 않거나 두루뭉술해 오해하게 만드는 정보도 믿기 어려운 표현이다',ARRAY['6국02-03 읽기']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C31','kor',6,1,'u6',7,'둘레의 광고 재어 보기 — 둘레의 광고 하나를 골라 눈에 띄는 문구를 옮겨 적고 세 기준으로 ○와 ×를 매기되, 매길 때마다 그렇게 판단한 까닭을 한 줄씩 함께 적는다',ARRAY['6국02-03 읽기']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C32','kor',6,1,'u6',9,'설명하는 글에서 더 조심할 까닭 — 광고는 알리려고 쓴 글인 줄 알고 걸러 읽지만 설명하는 글은 알려 주려고 쓴 글이라 여겨 그대로 외우기 쉬우므로, 거짓된 표현은 잘못된 지식이, 과장된 표현은 지나친 믿음이, 감추는 내용은 한쪽만 아는 사람이 된다',ARRAY['6국02-03 읽기']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C33','kor',6,1,'u6',9,'기준 하나로 글 전체를 훑기 — 한 문단에서 세 기준을 한꺼번에 재려 하면 놓치기 쉬우므로, 거짓된 표현을 들고 글 전체를 훑고, 다시 과장을, 마지막으로 감춤을 들고 처음부터 훑는다',ARRAY['6국02-03 읽기']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C34','kor',6,1,'u6',9,'넓게 말하는 말에 멈추기 — 설명하는 글에서 「대부분 · 모두 · 언제나」 같은 말이 나오면 한 번 멈추어 그렇게 넓게 말할 만한 사실인지 묻고, 확인할 수 있는 만큼만 말했는지 본다',ARRAY['6국02-03 읽기']::text[],34) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C35','kor',6,1,'u6',9,'과장은 알아채기 더 어렵다 — 과장된 표현은 거짓말이 아니라 있는 것을 부풀린 말이어서 더 알아채기 어렵고, 읽는 사람이 지나치게 믿게 만든다',ARRAY['6국02-03 읽기']::text[],35) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C36','kor',6,1,'u6',9,'감춤은 한쪽만 알게 한다 — 감추는 내용은 틀린 말을 하지 않으면서도 읽는 사람을 한쪽만 알게 하므로(「옹기는 어디에나 놓아도 좋다」 — 무겁고 잘 깨진다는 점을 빼놓음), 읽고 나서 되묻고 싶은 것이 남으면 그 자국을 따라간다',ARRAY['6국02-03 읽기']::text[],36) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C37','kor',6,1,'u6',9,'걸린 문장 고쳐 쓰기 — 거짓은 확인할 수 있는 만큼만 말하게, 과장은 부풀린 것을 덜어 내 있는 만큼 말하게, 감춤은 알아야 할 것을 더 밝히게 고쳐 쓰며, 고쳐 쓸 줄 알아야 판단이 끝까지 간 것이다',ARRAY['6국02-03 읽기']::text[],37) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C38','kor',6,1,'u6',9,'다른 관점의 글 더 찾아 읽기 — 한 편의 글은 한쪽(좋은 점)만 드러낼 수 있으므로 「불편한 점은 없었을까?」 · 「왜 오늘날에는 덜 쓸까?」처럼 다른 쪽에서 물음을 세우고, 관련 있는 글을 더 찾아 읽어 그 글에 없던 사실을 보태며 한 편만 읽고 판단하지 않는다',ARRAY['6국02-04 읽기']::text[],38) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C39','kor',6,1,'u6',9,'까닭이 붙은 판단은 따져 볼 수 있다 — 까닭이 붙은 판단은 친구가 따져 보고 다른 답을 낼 수도 있으며, 까닭이 타당하면 나와 다른 판단도 받아들일 수 있다 — 판단은 하나로 정해진 답을 맞히는 일이 아니다',ARRAY['6국02-03 읽기']::text[],39) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C40','kor',6,1,'u6',12,'판단하던 자를 뒤집어 만들기 — 읽을 때 걸렸던 것들(가치 없는 주장 · 어긋난 이유 · 확인할 수 없는 근거 · 거짓 · 과장 · 감춤)이 만들 때 하지 말아야 할 것이 되며, 남의 글에서 찾아낸 흠은 내 글에서도 똑같이 흠이다',ARRAY['6국02-03 읽기']::text[],40) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C41','kor',6,1,'u6',12,'공익 광고의 주제 — 공익 광고는 여럿이 함께 겪는 문제 가운데 내가 겪었고 다른 사람도 겪으며 고치면 나아지는 일을 주제로 고르며, 이것은 「주장이 가치 있고 중요한가」를 만드는 쪽에서 묻는 일이다',ARRAY['6국02-03 읽기']::text[],41) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C42','kor',6,1,'u6',12,'부풀린 문구 고쳐 쓰기 — 부풀린 문구는 뜻은 그대로 두고 크기만 줄여 고치며(「백 퍼센트 망가집니다」 → 「빌려준 지우개가 반으로 돌아왔습니다」), 덜어 낸 쪽은 힘이 약해지지 않고 보는 사람이 겪은 일에 더 가까워져 오히려 오래 남는다',ARRAY['6국02-03 읽기']::text[],42) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C43','kor',6,1,'u6',12,'광고는 눈에 띄면서도 믿을 수 있게 — 광고는 짧은 시간과 좁은 지면에서 인상을 남겨야 하므로 「틀린 말만 없으면 된다」는 아무도 보지 않는 광고가 되고 「눈에 띄기만 하면 된다」는 믿을 수 없는 광고가 되며, 눈에 띄려고 손댄 곳은 발표할 때 그 까닭을 밝힌다',ARRAY['6국02-03 읽기']::text[],43) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C44','kor',6,1,'u6',12,'표현 요소 고르기 — 가장 하고 싶은 한 줄만 크게(다 크게 하면 아무것도 크지 않다) · 문제 장면은 그림이 대신 · 진한 색은 강조할 곳에만 · 꼭 알려야 할 조건은 읽을 수 있는 크기로 적는다',ARRAY['6국02-03 읽기']::text[],44) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C45','kor',6,1,'u6',12,'만든 뜻까지 발표하기 — 광고를 발표할 때에는 어떤 문제를 보고 주제를 골랐는지 · 어떤 표현 요소로 무엇을 강조했는지 · 눈에 띄려고 부풀린 곳이 있다면 그 까닭까지 밝히며, 「여기는 일부러 세게 썼다」고 스스로 밝히는 사람은 보는 사람을 속이지 않는다',ARRAY['6국02-03 읽기']::text[],45) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C46','kor',6,1,'u6',12,'친구의 광고 판단하기 — 친구의 광고는 사람이 아니라 문구를 두고, 어느 문구가 걸리는지 짚고 그렇게 판단한 까닭을 함께 말하며, 잘한 점과 보완할 점을 함께 말한다 — 판단은 결과와 근거가 한 짝이다',ARRAY['6국02-03 읽기']::text[],46) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C47','kor',6,1,'u6',12,'두 자를 한꺼번에 대기 — 내용의 타당성 세 물음과 표현의 적절성 세 물음, 여섯 물음을 주장하는 글 · 광고 · 설명하는 글에 그대로 대어 받아들일 것과 물릴 것을 스스로 가르며, 걸린 곳이 있어도 주장까지 버리지는 않는다',ARRAY['6국02-03 읽기']::text[],47) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C48','kor',6,1,'u6',12,'뜻을 혼동하기 쉬운 낱말 — 늘이다(본디보다 길게 하다) · 늘리다(수나 양을 많아지게 하다), 맞히다(답을 옳게 대다, 겨냥한 곳에 닿게 하다) · 맞추다(서로 대어 보다, 맞게 하다), 좇다(뜻이나 목표를 따르다) · 쫓다(몰아내다, 뒤를 급히 따라가다)는 소리가 비슷해도 쓰이는 곳이 다르다 (기초 다지기)',ARRAY['기초 다지기(우리말)']::text[],48) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C49','kor',6,1,'u6',12,'맞춤법을 혼동하기 쉬운 말 — 「되어요」가 줄어든 「돼요」(안 되요 ✕), 몇 날을 뜻하는 한 낱말 「며칠」(몇일 ✕), 「오래간만에」가 줄어든 「오랜만에」(오랫만에 ✕), 병이 없어졌다는 「낫다」의 「나았다」(낳았다 ✕)처럼, 헷갈릴 때에는 본디 말로 늘여 보면 가려진다 (기초 다지기)',ARRAY['기초 다지기(우리말)']::text[],49) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X01','kor',6,'u6',ARRAY['K6-1-u6-C1']::text[],'게시판에 붙어 있거나 책에 적힌 글은 다 옳다고 여겨 그대로 받아들인다','붙어 있다고 다 맞나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X02','kor',6,'u6',ARRAY['K6-1-u6-C2']::text[],'읽다가 이상하다고 느껴도 그냥 넘어가, 그 물음이 비판적 읽기의 첫걸음인 줄 모른다','「이상한데?」에서 멈춰요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X03','kor',6,'u6',ARRAY['K6-1-u6-C3','K6-1-u6-C23']::text[],'판단하며 읽기를 내용만 따지는 일로 여겨 표현은 살피지 않거나, 두 갈래(타당성 · 적절성)를 헷갈린다','무엇을 · 어떻게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X04','kor',6,'u6',ARRAY['K6-1-u6-C4']::text[],'글의 목적과 상관없이 살필 것을 고르거나, 광고와 설명하는 글에서 살필 것을 헷갈린다','무엇을 하려고 쓴 글?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X05','kor',6,'u6',ARRAY['K6-1-u6-C5']::text[],'틀린 데를 많이 찾아낼수록 잘 읽은 것이라 여겨 맞는 말까지 트집을 잡는다','목적은 골라내기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X06','kor',6,'u6',ARRAY['K6-1-u6-C6','K6-1-u6-C31','K6-1-u6-C39','K6-1-u6-C46']::text[],'「그냥 이상해」 · 「별로야」처럼 까닭 없이 판단한다','판단엔 까닭이 한 짝') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X07','kor',6,'u6',ARRAY['K6-1-u6-C7']::text[],'서론 · 본론 · 결론의 몫을 헷갈리거나, 본론의 이유 하나를 글 전체의 주장으로 고른다','서론과 결론이 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X08','kor',6,'u6',ARRAY['K6-1-u6-C8']::text[],'타당성을 글의 길이나 어려운 낱말의 수로 여긴다','이치에 맞게 옳은가') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X09','kor',6,'u6',ARRAY['K6-1-u6-C9','K6-1-u6-C41']::text[],'하자는 대로 하면 다른 문제가 생기는 주장도 가치 있고 중요하다고 여긴다','여럿에게 도움이 되나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X10','kor',6,'u6',ARRAY['K6-1-u6-C10']::text[],'맞는 말이기만 하면 주장과 관련이 없어도 이유가 된다고 여긴다','주장과 이어지나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X11','kor',6,'u6',ARRAY['K6-1-u6-C11']::text[],'주장과 반대 방향을 가리키는 이유도 이유가 된다고 여긴다','내 주장 편인가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X12','kor',6,'u6',ARRAY['K6-1-u6-C12']::text[],'「∼한 것 같다」는 한 사람의 짐작을 옮긴 말도 근거가 된다고 여긴다','누가 직접 확인했나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X13','kor',6,'u6',ARRAY['K6-1-u6-C13']::text[],'타당성은 주장하는 글에서만 잰다고 여겨 알림글 · 설명하는 글은 그대로 믿는다','내용을 담은 글이면 어디든') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X14','kor',6,'u6',ARRAY['K6-1-u6-C14']::text[],'판단 기준은 정해진 세 가지뿐이라 스스로 기준을 더 세우면 안 된다고 여긴다','물음의 꼴로 더 세워요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X15','kor',6,'u6',ARRAY['K6-1-u6-C15','K6-1-u6-C24']::text[],'큰 글씨만 읽고 작은 글씨나 뒷부분은 확인하지 않아도 된다고 여긴다','작게 쓴 것도 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X16','kor',6,'u6',ARRAY['K6-1-u6-C16']::text[],'근거를 엉뚱한 이유에 붙여 놓고 판단한다','같은 문단 안에') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X17','kor',6,'u6',ARRAY['K6-1-u6-C17']::text[],'「글에 그렇게 적혀 있으니까」를 판단의 까닭으로 든다','적혀 있는 건 까닭이 아니에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X18','kor',6,'u6',ARRAY['K6-1-u6-C18']::text[],'글에 이유로 적혀 있으면 사실일 것이라 여겨 실제로 일어나는 일인지 묻지 않는다','정말 그런 일이 일어나나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X19','kor',6,'u6',ARRAY['K6-1-u6-C19']::text[],'한 사람에게서 전해 들은 말도 누가 말했는지만 적혀 있으면 확인할 수 있는 근거라고 여긴다','다시 가 볼 수 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X20','kor',6,'u6',ARRAY['K6-1-u6-C20']::text[],'한 편의 글을 잴 때 기준을 차례 없이 뒤섞어 대다가 빠뜨린다','주장 → 이유 → 근거') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X21','kor',6,'u6',ARRAY['K6-1-u6-C21','K6-1-u6-C47']::text[],'걸린 곳이 하나라도 있으면 글 전체를 믿을 수 없다며 버린다','받아들일 것도 골라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X22','kor',6,'u6',ARRAY['K6-1-u6-C22']::text[],'배운 기준은 공부 시간의 글에만 쓰고 둘레의 글에는 대어 보지 않는다','게시판 · 포장 글에도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X23','kor',6,'u6',ARRAY['K6-1-u6-C23']::text[],'표현의 적절성을 글씨가 예쁜지 · 문장이 긴지로 여긴다','어떻게 말했나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X24','kor',6,'u6',ARRAY['K6-1-u6-C24']::text[],'광고에서 크게 쓴 것만 보고, 무엇을 작게 썼는지는 살피지 않는다','작게 쓴 까닭도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X25','kor',6,'u6',ARRAY['K6-1-u6-C25','K6-1-u6-C28']::text[],'없는 기능을 있다고 한 거짓과 있는 기능을 부풀린 과장을 헷갈린다','그 기능이 실제로 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X26','kor',6,'u6',ARRAY['K6-1-u6-C26']::text[],'「절대 · 무조건 · 최고」 같은 말을 광고에 적혀 있으니 그대로 믿는다','어떤 경우에도 그럴까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X27','kor',6,'u6',ARRAY['K6-1-u6-C27','K6-1-u6-C36']::text[],'틀린 말이 없으면 감춘 것도 없다고 여겨, 언제 · 어디에서 · 무엇과 견주었는지 빠진 말을 그냥 믿는다','「그런데 어디에서?」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X28','kor',6,'u6',ARRAY['K6-1-u6-C29']::text[],'한 표현은 한 가지 기준에만 걸린다고 여긴다','두 기준에 함께도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X29','kor',6,'u6',ARRAY['K6-1-u6-C30']::text[],'부풀리고 감추는 일은 광고에서만 일어난다고 여겨 주장하는 글 · 안내문은 그대로 믿는다','설득하려는 글이면 어디서든') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X30','kor',6,'u6',ARRAY['K6-1-u6-C30']::text[],'부풀리지 않았으면 오래되었거나 두루뭉술한 정보도 다 믿을 수 있다고 여긴다','오래된 · 흐린 정보') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X31','kor',6,'u6',ARRAY['K6-1-u6-C32']::text[],'설명하는 글은 알려 주려고 쓴 글이라 적힌 대로 외워도 된다고 여긴다','잘못된 지식이 될 수 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X32','kor',6,'u6',ARRAY['K6-1-u6-C33']::text[],'한 문단에서 세 기준을 한꺼번에 재려다 놓치거나, 글 전체를 훑지 않는다','기준 하나로 전체를') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X33','kor',6,'u6',ARRAY['K6-1-u6-C34']::text[],'「대부분 · 모두 · 언제나」 같은 넓게 말하는 말을 그냥 지나친다','그렇게 넓게 말할 만한가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X34','kor',6,'u6',ARRAY['K6-1-u6-C35']::text[],'과장된 표현은 거짓말이 아니니 그대로 믿어도 괜찮다고 여긴다','지나친 믿음이 돼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X35','kor',6,'u6',ARRAY['K6-1-u6-C37','K6-1-u6-C42']::text[],'걸린 문장을 찾기만 하고 고쳐 쓰지 못하거나, 고치면서 뜻까지 바꾼다','덜어 내기 · 더 밝히기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X36','kor',6,'u6',ARRAY['K6-1-u6-C38']::text[],'한 편의 글만 읽고 판단을 끝내 다른 관점의 글을 찾아 읽지 않는다','다른 쪽에서 물어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X37','kor',6,'u6',ARRAY['K6-1-u6-C39']::text[],'나와 다른 판단은 까닭을 들어 보지도 않고 틀렸다고 여긴다','까닭이 타당한가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X38','kor',6,'u6',ARRAY['K6-1-u6-C40']::text[],'남의 글에서 찾은 흠을 내가 만들 때에는 괜찮다고 여긴다','내 글에서도 흠') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X39','kor',6,'u6',ARRAY['K6-1-u6-C41']::text[],'여럿에게 도움이 되지 않거나 고쳐도 나아지지 않는 일을 공익 광고의 주제로 고른다','고치면 나아지나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X40','kor',6,'u6',ARRAY['K6-1-u6-C42']::text[],'부풀린 말을 덜어 내면 광고의 힘이 약해진다고 여긴다','사실에 가까운 말이 오래 남아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X41','kor',6,'u6',ARRAY['K6-1-u6-C43']::text[],'광고는 틀린 말만 없으면 눈에 띄지 않아도 된다고 여긴다','아무도 보지 않는 광고') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X42','kor',6,'u6',ARRAY['K6-1-u6-C43','K6-1-u6-C45']::text[],'광고는 눈에 띄기만 하면 부풀리고 감춰도 된다고 여기거나, 일부러 세게 쓴 곳을 숨긴다','믿을 수 없는 광고') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X43','kor',6,'u6',ARRAY['K6-1-u6-C44']::text[],'여러 줄을 다 크게 · 온통 진하게 하거나, 꼭 알릴 조건을 읽을 수 없을 만큼 작게 적는다','한 줄만 크게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X44','kor',6,'u6',ARRAY['K6-1-u6-C45']::text[],'광고를 발표할 때 결과물만 보이고 고른 까닭 · 강조한 것 · 세게 쓴 까닭은 말하지 않는다','만든 뜻까지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X45','kor',6,'u6',ARRAY['K6-1-u6-C46']::text[],'친구의 광고를 판단할 때 문구가 아니라 만든 사람을 두고 말하거나, 잘한 점은 말하지 않는다','문구를 · 잘한 점도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X46','kor',6,'u6',ARRAY['K6-1-u6-C47','K6-1-u6-C3']::text[],'두 자 가운데 하나만 대고 판단을 끝낸다(내용만 보거나 표현만 본다)','여섯 물음을 다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X47','kor',6,'u6',ARRAY['K6-1-u6-C48']::text[],'늘이다 · 늘리다, 맞히다 · 맞추다, 좇다 · 쫓다의 뜻을 헷갈려 바꾸어 쓴다','문장에 넣어 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X48','kor',6,'u6',ARRAY['K6-1-u6-C49']::text[],'「안 되요 · 몇일 · 오랫만에 · 낳았다」처럼 맞춤법을 틀리게 쓴다','본디 말로 늘여 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L01_basic#1','kor',6,1,'u6','L01','g6_1_kor_u6_L01_basic','lesson_basic','K6-1-u6-C1',1,'mc','auto','「비판적으로 읽는다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X01','K6-1-u6-X05','K6-1-u6-X03']::text[],false,'{"seq":1,"concept":"K6-1-u6-C1","difficulty":1,"kind":"mc","stem":"「비판적으로 읽는다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"글을 그대로 받아들이지 않고 내용과 표현이 알맞은지 판단하며 읽는 것","correct":true},{"t":"적힌 내용을 믿고 그대로 외우며 읽는 것","mis":"K6-1-u6-X01"},{"t":"글에서 흠을 될수록 많이 찾아 깎아내리는 것","mis":"K6-1-u6-X05"},{"t":"소리 내어 또박또박 읽는 것","mis":"K6-1-u6-X03"}],"explanation":["그대로 믿는 것은 판단이 아니에요.","깎아내리는 것이 목적이 아니에요.","내용과 표현을 판단하며 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L01_basic#2','kor',6,1,'u6','L01','g6_1_kor_u6_L01_basic','lesson_basic','K6-1-u6-C1',1,'ox','auto','게시판에 붙어 있는 글은 모두 옳은 내용이에요.',ARRAY['K6-1-u6-X01']::text[],false,'{"seq":2,"concept":"K6-1-u6-C1","difficulty":1,"kind":"ox","stem":"게시판에 붙어 있는 글은 모두 옳은 내용이에요.","answer":"X","reason_options":[{"t":"붙어 있다고 다 맞는 말은 아니어서 따져 보며 읽어야 하기 때문에","correct":true},{"t":"여러 사람이 보는 곳에 붙인 글이기 때문에","mis":"K6-1-u6-X01"}],"mis":"K6-1-u6-X01","explanation":["붙은 곳이 옳음을 보장하지 않아요.","여러 사람이 보는 글도 틀릴 수 있어요.","따져 보며 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L01_basic#3','kor',6,1,'u6','L01','g6_1_kor_u6_L01_basic','lesson_basic','K6-1-u6-C2',1,'mc','auto','하영이가 「우리가 따져 보자」고 한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X15','K6-1-u6-X08','K6-1-u6-X05']::text[],false,'{"seq":3,"concept":"K6-1-u6-C2","difficulty":1,"kind":"mc","stem":"하영이가 「우리가 따져 보자」고 한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"게시판에 붙어 있다고 다 맞는 말은 아니기 때문이다","correct":true},{"t":"글씨가 너무 작아 읽기 어렵기 때문이다","mis":"K6-1-u6-X15"},{"t":"글이 너무 길기 때문이다","mis":"K6-1-u6-X08"},{"t":"걸어 다니자는 주장이 틀렸기 때문이다","mis":"K6-1-u6-X05"}],"explanation":["글씨 크기 이야기가 아니에요.","길이 때문이 아니에요.","이상한 줄을 따져 보려는 거예요."],"asset":{"type":"speech","turns":[{"who":"우재","text":"급식실 앞 게시판에 새 글이 붙었어. 걸어 다니자는 내용이야."},{"who":"하영","text":"맞는 말이네. 국을 들고 부딪히면 크게 다칠 수 있으니까."},{"who":"우재","text":"그런데 가운데에 이상한 줄이 하나 있어. 읽고 나서 고개가 갸웃해졌어."},{"who":"하영","text":"어디 보자. 붙어 있다고 다 맞는 말은 아니니까 우리가 따져 보자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L01_basic#4','kor',6,1,'u6','L01','g6_1_kor_u6_L01_basic','lesson_basic','K6-1-u6-C3',1,'match','auto','말과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K6-1-u6-C3","difficulty":1,"kind":"match","stem":"말과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"내용의 타당성","r":"글에 담긴 내용이 이치에 맞고 옳은가"},{"l":"표현의 적절성","r":"그 내용을 알맞은 말로 나타냈는가"},{"l":"비판적으로 읽기","r":"두 가지를 함께 살피며 읽기"}],"mis":"K6-1-u6-X03","explanation":["타당성은 무엇을 말하는가예요.","적절성은 어떻게 말하는가예요.","둘을 함께 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L01_basic#5','kor',6,1,'u6','L01','g6_1_kor_u6_L01_basic','lesson_basic','K6-1-u6-C2',2,'mc','auto','이 글을 읽으며 「이상한데?」 하고 멈출 만한 문장은 어느 것인가요?',ARRAY['K6-1-u6-X05']::text[],false,'{"seq":5,"concept":"K6-1-u6-C2","difficulty":2,"kind":"mc","stem":"이 글을 읽으며 「이상한데?」 하고 멈출 만한 문장은 어느 것인가요?","options":[{"t":"뛰어다니면 키가 자라지 않습니다","correct":true},{"t":"뜨거운 국을 든 사람과 부딪히면 크게 다칠 수 있습니다","mis":"K6-1-u6-X05"},{"t":"지나가는 사람의 식판을 쳐서 음식을 쏟게 할 수 있습니다","mis":"K6-1-u6-X05"},{"t":"급식실은 여러 사람이 함께 쓰는 곳입니다","mis":"K6-1-u6-X05"}],"explanation":["다치는 일과 이어진 맞는 말이에요.","이것도 실제로 일어나는 일이에요.","뛰는 일과 키는 관계가 없어요 — 바르게는 「뛰다가 넘어지면 크게 다칠 수 있습니다」예요."],"asset":{"type":"passage","lines":["점심시간에 급식실에서 뛰는 친구들이 있습니다. 급식실에서는 걸어 다녔으면 좋겠습니다.","첫째, 뜨거운 국을 든 사람과 부딪히면 크게 다칠 수 있습니다.","둘째, 뛰어다니면 키가 자라지 않습니다.","셋째, 지나가는 사람의 식판을 쳐서 음식을 쏟게 할 수 있습니다.","급식실은 여러 사람이 함께 쓰는 곳입니다. 조금만 천천히 걸읍시다."],"title":"「급식실에서는 걸어 다닙시다」 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L01_basic#6','kor',6,1,'u6','L01','g6_1_kor_u6_L01_basic','lesson_basic','K6-1-u6-C4',2,'match','auto','읽는 글과 그 글에서 먼저 살필 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-1-u6-C4","difficulty":2,"kind":"match","stem":"읽는 글과 그 글에서 먼저 살필 것을 알맞게 이으세요.","pairs":[{"l":"주장하는 글","r":"그 주장이 나에게 도움이 되는지"},{"l":"물건을 알리는 광고","r":"물건의 특징을 제대로 나타냈는지"},{"l":"무엇을 알려 주는 글","r":"알려 주는 정보를 믿을 만한지"}],"mis":"K6-1-u6-X04","explanation":["주장하는 글은 주장을 봐요.","광고는 특징을 제대로 나타냈는지 봐요.","글의 목적이 살필 것을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L01_basic#7','kor',6,1,'u6','L01','g6_1_kor_u6_L01_basic','lesson_basic','K6-1-u6-C5',2,'ox','auto','틀린 데를 많이 찾아낼수록 글을 잘 읽은 거예요.',ARRAY['K6-1-u6-X05']::text[],false,'{"seq":7,"concept":"K6-1-u6-C5","difficulty":2,"kind":"ox","stem":"틀린 데를 많이 찾아낼수록 글을 잘 읽은 거예요.","answer":"X","reason_options":[{"t":"맞는 곳은 받아들이고 이상한 곳만 까닭을 대어 짚는 것이 비판적 읽기이기 때문에","correct":true},{"t":"흠을 많이 찾을수록 글을 꼼꼼히 본 것이기 때문에","mis":"K6-1-u6-X05"}],"mis":"K6-1-u6-X05","explanation":["트집이 목적이 아니에요.","맞는 말까지 트집 잡게 돼요.","필요한 정보를 골라내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L01_basic#8','kor',6,1,'u6','L01','g6_1_kor_u6_L01_basic','lesson_basic','K6-1-u6-C6',2,'mc','auto','급식실 글을 판단한 말 가운데 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X06','K6-1-u6-X05','K6-1-u6-X01']::text[],false,'{"seq":8,"concept":"K6-1-u6-C6","difficulty":2,"kind":"mc","stem":"급식실 글을 판단한 말 가운데 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「둘째 이유는 걸려. 뛰는 일과 키가 자라는 일은 관계가 없으니까.」","correct":true},{"t":"「둘째 이유는 그냥 이상해.」","mis":"K6-1-u6-X06"},{"t":"「이 글은 전부 엉터리야.」","mis":"K6-1-u6-X05"},{"t":"「게시판에 붙었으니 다 맞아.」","mis":"K6-1-u6-X01"}],"explanation":["까닭이 빠졌어요.","맞는 곳까지 버렸어요.","판단에 까닭이 붙었어요 — 그 문장은 「뛰다가 넘어지면 다칠 수 있다」로 바로잡아요."],"asset":{"type":"passage","lines":["점심시간에 급식실에서 뛰는 친구들이 있습니다. 급식실에서는 걸어 다녔으면 좋겠습니다.","첫째, 뜨거운 국을 든 사람과 부딪히면 크게 다칠 수 있습니다.","둘째, 뛰어다니면 키가 자라지 않습니다.","셋째, 지나가는 사람의 식판을 쳐서 음식을 쏟게 할 수 있습니다.","급식실은 여러 사람이 함께 쓰는 곳입니다. 조금만 천천히 걸읍시다."],"title":"「급식실에서는 걸어 다닙시다」 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L01_basic#9','kor',6,1,'u6','L01','g6_1_kor_u6_L01_basic','lesson_basic','K6-1-u6-C3',2,'mc','auto','「거짓된 표현 · 부풀린 표현 · 감추는 내용이 없는가」를 살피는 갈래는 어느 것인가요?',ARRAY['K6-1-u6-X03','K6-1-u6-X23']::text[],false,'{"seq":9,"concept":"K6-1-u6-C3","difficulty":2,"kind":"mc","stem":"「거짓된 표현 · 부풀린 표현 · 감추는 내용이 없는가」를 살피는 갈래는 어느 것인가요?","options":[{"t":"표현의 적절성","correct":true},{"t":"내용의 타당성","mis":"K6-1-u6-X03"},{"t":"글의 짜임","mis":"K6-1-u6-X03"},{"t":"글씨의 바르기","mis":"K6-1-u6-X23"}],"explanation":["타당성은 주장 · 이유 · 근거를 봐요.","짜임과는 달라요.","어떻게 말했는지 보는 갈래예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L01_basic#10','kor',6,1,'u6','L01','g6_1_kor_u6_L01_basic','lesson_basic','K6-1-u6-C2',3,'mc','auto','「이상한데?」 하는 물음이 비판적 읽기의 첫걸음인 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X21','K6-1-u6-X06','K6-1-u6-X05']::text[],false,'{"seq":10,"concept":"K6-1-u6-C2","difficulty":3,"kind":"mc","stem":"「이상한데?」 하는 물음이 비판적 읽기의 첫걸음인 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"어디가 왜 이상한지 따져 보게 되어 글을 그대로 받아들이지 않게 되기 때문이다","correct":true},{"t":"이상한 글은 바로 버려야 하기 때문이다","mis":"K6-1-u6-X21"},{"t":"이상하다고 말하면 판단이 끝나기 때문이다","mis":"K6-1-u6-X06"},{"t":"이상한 곳을 많이 찾을수록 좋기 때문이다","mis":"K6-1-u6-X05"}],"explanation":["버리지 않고 따져 봐요.","물음에서 시작할 뿐이에요.","어디가 왜 이상한지 찾아가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L01_challenge#1','kor',6,1,'u6','L01','g6_1_kor_u6_L01_challenge','lesson_challenge','K6-1-u6-C3',2,'mc','auto','「글은 무엇을 말하는가와 어떻게 말하는가로 이루어져 있다」에서 「무엇을 말하는가」를 재는 갈래는 어느 것인가요?',ARRAY['K6-1-u6-X03','K6-1-u6-X23','K6-1-u6-X08']::text[],false,'{"seq":1,"concept":"K6-1-u6-C3","difficulty":2,"kind":"mc","stem":"「글은 무엇을 말하는가와 어떻게 말하는가로 이루어져 있다」에서 「무엇을 말하는가」를 재는 갈래는 어느 것인가요?","options":[{"t":"내용의 타당성","correct":true},{"t":"표현의 적절성","mis":"K6-1-u6-X03"},{"t":"글자의 크기","mis":"K6-1-u6-X23"},{"t":"글의 길이","mis":"K6-1-u6-X08"}],"explanation":["어떻게 말하는가를 재는 갈래예요.","크기와는 관계없어요.","내용이 이치에 맞는지 재요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L01_challenge#2','kor',6,1,'u6','L01','g6_1_kor_u6_L01_challenge','lesson_challenge','K6-1-u6-C5',2,'error','auto','급식실 글을 읽은 사람들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K6-1-u6-X05','K6-1-u6-X06']::text[],false,'{"seq":2,"concept":"K6-1-u6-C5","difficulty":2,"kind":"error","stem":"급식실 글을 읽은 사람들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"다른 친구 — 「이상한 줄이 하나 있으니 이 글은 다 엉터리야.」","correct":true,"mis_target":"K6-1-u6-X05"},{"t":"하영 — 「다치는 이야기는 받아들이고, 키 이야기만 까닭을 대어 짚자.」","mis":"K6-1-u6-X05"},{"t":"우재 — 「이상한 곳은 왜 이상한지 말해 볼게.」","mis":"K6-1-u6-X06"}],"explanation":["하영이는 받아들일 것을 골랐어요.","우재는 까닭을 대려 해요.","한 줄 때문에 맞는 곳까지 버리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L01_challenge#3','kor',6,1,'u6','L01','g6_1_kor_u6_L01_challenge','lesson_challenge','K6-1-u6-C4',3,'mc','auto','물건을 알리는 광고를 읽을 때 먼저 살필 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X04']::text[],false,'{"seq":3,"concept":"K6-1-u6-C4","difficulty":3,"kind":"mc","stem":"물건을 알리는 광고를 읽을 때 먼저 살필 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"물건의 특징을 제대로 나타냈는지","correct":true},{"t":"그 주장이 나에게 도움이 되는지만","mis":"K6-1-u6-X04"},{"t":"등장인물의 마음이 어떠한지","mis":"K6-1-u6-X04"},{"t":"광고를 몇 번 보았는지","mis":"K6-1-u6-X04"}],"explanation":["그건 주장하는 글에서 먼저 봐요.","이야기를 읽을 때 살필 거예요.","알리려는 물건의 특징을 제대로 말했는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L01_challenge#4','kor',6,1,'u6','L01','g6_1_kor_u6_L01_challenge','lesson_challenge','K6-1-u6-C1',3,'mc','auto','우재가 「읽고 나서 고개가 갸웃해졌어」라고 한 말에서 보이는 태도로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X01','K6-1-u6-X21','K6-1-u6-X05']::text[],false,'{"seq":4,"concept":"K6-1-u6-C1","difficulty":3,"kind":"mc","stem":"우재가 「읽고 나서 고개가 갸웃해졌어」라고 한 말에서 보이는 태도로 알맞은 것은 어느 것인가요?","options":[{"t":"글을 그대로 믿지 않고 이상한 곳을 찾아보려는 태도","correct":true},{"t":"붙어 있는 글은 다 믿는 태도","mis":"K6-1-u6-X01"},{"t":"이상하면 읽기를 그만두는 태도","mis":"K6-1-u6-X21"},{"t":"글쓴이를 탓하려는 태도","mis":"K6-1-u6-X05"}],"explanation":["그대로 믿지 않았어요.","그만두지 않고 따져 봐요.","탓하려는 게 아니에요."],"asset":{"type":"speech","turns":[{"who":"우재","text":"급식실 앞 게시판에 새 글이 붙었어. 걸어 다니자는 내용이야."},{"who":"하영","text":"맞는 말이네. 국을 들고 부딪히면 크게 다칠 수 있으니까."},{"who":"우재","text":"그런데 가운데에 이상한 줄이 하나 있어. 읽고 나서 고개가 갸웃해졌어."},{"who":"하영","text":"어디 보자. 붙어 있다고 다 맞는 말은 아니니까 우리가 따져 보자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L01_challenge#5','kor',6,1,'u6','L01','g6_1_kor_u6_L01_challenge','lesson_challenge','K6-1-u6-C6',3,'ox','auto','「이 문장은 이상해」라고만 말해도 판단을 다 한 거예요.',ARRAY['K6-1-u6-X06']::text[],false,'{"seq":5,"concept":"K6-1-u6-C6","difficulty":3,"kind":"ox","stem":"「이 문장은 이상해」라고만 말해도 판단을 다 한 거예요.","answer":"X","reason_options":[{"t":"왜 그렇게 판단했는지 까닭을 대야 다른 사람이 따져 볼 수 있기 때문에","correct":true},{"t":"이상하다고 느낀 것이 판단의 전부이기 때문에","mis":"K6-1-u6-X06"}],"mis":"K6-1-u6-X06","explanation":["느낌만으로는 부족해요.","까닭이 함께 가요.","까닭이 있어야 판단이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L01_challenge#6','kor',6,1,'u6','L01','g6_1_kor_u6_L01_challenge','lesson_challenge','K6-1-u6-C3',3,'mc','auto','판단하며 읽기의 두 갈래를 모두 쓴 판단은 어느 것인가요?',ARRAY['K6-1-u6-X46','K6-1-u6-X23','K6-1-u6-X08']::text[],false,'{"seq":6,"concept":"K6-1-u6-C3","difficulty":3,"kind":"mc","stem":"판단하며 읽기의 두 갈래를 모두 쓴 판단은 어느 것인가요?","options":[{"t":"「키 이야기는 주장과 이어지지 않고, 〈크게 다칠 수 있다〉는 부풀리지 않은 알맞은 말이다.」","correct":true},{"t":"「키 이야기는 주장과 이어지지 않는다.」로 끝낸다","mis":"K6-1-u6-X46"},{"t":"「글씨가 반듯해서 좋은 글이다.」","mis":"K6-1-u6-X23"},{"t":"「글이 짧아서 타당하다.」","mis":"K6-1-u6-X08"}],"explanation":["내용 한 갈래만 보았어요.","글씨는 갈래가 아니에요.","내용과 표현을 함께 살폈어요 — 키 문장은 「뛰다가 넘어지면 다칠 수 있다」로 바로잡아요."],"asset":{"type":"passage","lines":["점심시간에 급식실에서 뛰는 친구들이 있습니다. 급식실에서는 걸어 다녔으면 좋겠습니다.","첫째, 뜨거운 국을 든 사람과 부딪히면 크게 다칠 수 있습니다.","둘째, 뛰어다니면 키가 자라지 않습니다.","셋째, 지나가는 사람의 식판을 쳐서 음식을 쏟게 할 수 있습니다.","급식실은 여러 사람이 함께 쓰는 곳입니다. 조금만 천천히 걸읍시다."],"title":"「급식실에서는 걸어 다닙시다」 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L01_challenge#7','kor',6,1,'u6','L01','g6_1_kor_u6_L01_challenge','lesson_challenge','K6-1-u6-C5',3,'mc','auto','비판적으로 읽는 목적으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X05','K6-1-u6-X01']::text[],false,'{"seq":7,"concept":"K6-1-u6-C5","difficulty":3,"kind":"mc","stem":"비판적으로 읽는 목적으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"글에서 나에게 필요한 정보를 골라내는 것","correct":true},{"t":"글을 깎아내리는 것","mis":"K6-1-u6-X05"},{"t":"글쓴이와 다투어 이기는 것","mis":"K6-1-u6-X05"},{"t":"적힌 것을 그대로 외우는 것","mis":"K6-1-u6-X01"}],"explanation":["깎아내리려는 게 아니에요.","다툼이 목적이 아니에요.","쓸 것을 골라내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L01_challenge#8','kor',6,1,'u6','L01','g6_1_kor_u6_L01_challenge','lesson_challenge','K6-1-u6-C2',4,'mc','auto','급식실 글의 둘째 이유를 읽고 세울 물음으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X02','K6-1-u6-X05','K6-1-u6-X01']::text[],false,'{"seq":8,"concept":"K6-1-u6-C2","difficulty":4,"kind":"mc","stem":"급식실 글의 둘째 이유를 읽고 세울 물음으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「뛰는 일과 키가 자라는 일이 정말 관계가 있을까?」","correct":true},{"t":"「잘 모르겠지만 그냥 넘어가자.」","mis":"K6-1-u6-X02"},{"t":"「다른 문장에서도 틀린 곳을 더 찾아보자.」","mis":"K6-1-u6-X05"},{"t":"「게시판에 붙었으니 맞겠지.」","mis":"K6-1-u6-X01"}],"explanation":["넘기지 말고 멈춰요.","트집 잡기가 아니에요.","이상한 곳을 물음으로 바꿨어요 — 둘은 관계가 없어요."],"asset":{"type":"passage","lines":["점심시간에 급식실에서 뛰는 친구들이 있습니다. 급식실에서는 걸어 다녔으면 좋겠습니다.","첫째, 뜨거운 국을 든 사람과 부딪히면 크게 다칠 수 있습니다.","둘째, 뛰어다니면 키가 자라지 않습니다.","셋째, 지나가는 사람의 식판을 쳐서 음식을 쏟게 할 수 있습니다.","급식실은 여러 사람이 함께 쓰는 곳입니다. 조금만 천천히 걸읍시다."],"title":"「급식실에서는 걸어 다닙시다」 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L01_challenge#9','kor',6,1,'u6','L01','g6_1_kor_u6_L01_challenge','lesson_challenge','K6-1-u6-C5',4,'essay','teacher','급식실 글을 읽고 「틀린 곳이 있으니 이 글은 아무것도 믿을 수 없어.」라고 말하는 친구에게, 받아들일 곳과 짚을 곳을 나누어 까닭과 함께 해 줄 말을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u6-C5","difficulty":4,"kind":"essay","stem":"급식실 글을 읽고 「틀린 곳이 있으니 이 글은 아무것도 믿을 수 없어.」라고 말하는 친구에게, 받아들일 곳과 짚을 곳을 나누어 까닭과 함께 해 줄 말을 쓰세요.","answer_guide":{"answer":"예: 이 글에서 「뜨거운 국을 든 사람과 부딪히면 크게 다칠 수 있다」와 「식판을 쳐서 음식을 쏟게 할 수 있다」는 실제로 일어나는 일이라 받아들여도 좋아. 짚을 곳은 「뛰어다니면 키가 자라지 않는다」 하나야. 뛰는 일과 키가 자라는 일은 관계가 없으니까. 틀린 곳 하나 때문에 걸어 다니자는 주장까지 버리지 말고, 그 문장만 「뛰다가 넘어지면 다칠 수 있다」로 바로잡으면 돼.","scoring_points":["받아들일 곳을 까닭과 함께 썼는가","짚을 곳을 까닭과 함께 썼는가","글 전체를 버리지 않는다는 뜻을 담았는가"]},"explanation":["맞는 곳을 먼저 찾아요.","걸린 곳은 까닭을 대요.","흠 잡기가 아님을 말해요."],"asset":{"type":"passage","lines":["점심시간에 급식실에서 뛰는 친구들이 있습니다. 급식실에서는 걸어 다녔으면 좋겠습니다.","첫째, 뜨거운 국을 든 사람과 부딪히면 크게 다칠 수 있습니다.","둘째, 뛰어다니면 키가 자라지 않습니다.","셋째, 지나가는 사람의 식판을 쳐서 음식을 쏟게 할 수 있습니다.","급식실은 여러 사람이 함께 쓰는 곳입니다. 조금만 천천히 걸읍시다."],"title":"「급식실에서는 걸어 다닙시다」 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L01_challenge#10','kor',6,1,'u6','L01','g6_1_kor_u6_L01_challenge','lesson_challenge','K6-1-u6-C3',4,'essay','teacher','판단하며 읽기의 두 갈래를 쓰고, 급식실 글에 대어 볼 물음을 갈래마다 하나씩 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u6-C3","difficulty":4,"kind":"essay","stem":"판단하며 읽기의 두 갈래를 쓰고, 급식실 글에 대어 볼 물음을 갈래마다 하나씩 쓰세요.","answer_guide":{"answer":"예: 두 갈래는 내용의 타당성과 표현의 적절성이다. 내용의 타당성으로는 「이유가 걸어 다니자는 주장과 이어지는가?」를 물을 수 있다. 표현의 적절성으로는 「부풀리거나 사실이 아닌 말로 나타내지 않았는가?」를 물을 수 있다. 무엇을 말하는가와 어떻게 말하는가를 함께 보아야 비판적으로 읽은 것이다.","scoring_points":["두 갈래의 이름을 썼는가","갈래마다 알맞은 물음을 썼는가","두 갈래를 함께 살핀다는 뜻을 썼는가"]},"explanation":["무엇과 어떻게를 떠올려요.","갈래마다 물음을 만들어요.","함께 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L02_basic#1','kor',6,1,'u6','L02','g6_1_kor_u6_L02_basic','lesson_basic','K6-1-u6-C8',1,'mc','auto','「타당성」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X08','K6-1-u6-X23']::text[],false,'{"seq":1,"concept":"K6-1-u6-C8","difficulty":1,"kind":"mc","stem":"「타당성」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"이치에 맞는 옳은 성질","correct":true},{"t":"글이 길고 자세한 성질","mis":"K6-1-u6-X08"},{"t":"어려운 낱말이 많은 성질","mis":"K6-1-u6-X08"},{"t":"글씨가 바르고 고른 성질","mis":"K6-1-u6-X23"}],"explanation":["길이와는 관계없어요.","어려운 낱말 수가 아니에요.","이치에 맞게 옳은지를 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L02_basic#2','kor',6,1,'u6','L02','g6_1_kor_u6_L02_basic','lesson_basic','K6-1-u6-C7',1,'match','auto','주장하는 글의 부분과 그 부분이 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K6-1-u6-C7","difficulty":1,"kind":"match","stem":"주장하는 글의 부분과 그 부분이 하는 일을 알맞게 이으세요.","pairs":[{"l":"서론","r":"읽는 사람의 관심을 끌고 글의 방향을 알림"},{"l":"본론","r":"주장을 뒷받침하는 이유와 근거를 제시함"},{"l":"결론","r":"글을 마무리하고 주장을 다시 정리함"}],"mis":"K6-1-u6-X07","explanation":["서론은 방향을 알려요.","본론은 이유와 근거예요.","결론은 주장을 다시 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L02_basic#3','kor',6,1,'u6','L02','g6_1_kor_u6_L02_basic','lesson_basic','K6-1-u6-C7',1,'mc','auto','「급식을 남기지 맙시다」의 주장은 무엇인가요?',ARRAY['K6-1-u6-X07','K6-1-u6-X11']::text[],false,'{"seq":3,"concept":"K6-1-u6-C7","difficulty":1,"kind":"mc","stem":"「급식을 남기지 맙시다」의 주장은 무엇인가요?","options":[{"t":"급식을 남기지 말자","correct":true},{"t":"식단표를 매일 확인하자","mis":"K6-1-u6-X07"},{"t":"급식을 더 많이 받자","mis":"K6-1-u6-X07"},{"t":"반찬을 골라 먹자","mis":"K6-1-u6-X11"}],"explanation":["근거에 나온 말이에요.","주장과 반대예요.","서론과 결론이 함께 가리켜요."],"asset":{"type":"passage","lines":["④ 셋째, 급식에는 여러 가지 반찬이 나와서 골라 먹는 재미가 있습니다.","⑤ 넷째, 남긴 음식을 치우는 데에도 힘이 듭니다.","우리 반 친구가 잔반이 예전보다 늘어난 것 같다고 말했습니다.","⑥ 급식은 여러 사람의 손을 거쳐 우리 앞에 옵니다.","먹을 만큼만 받고, 받은 만큼은 먹읍시다."],"title":"「급식을 남기지 맙시다」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L02_basic#4','kor',6,1,'u6','L02','g6_1_kor_u6_L02_basic','lesson_basic','K6-1-u6-C8',1,'mc','auto','내용의 타당성을 재는 세 물음에 들지 않는 것은 어느 것인가요?',ARRAY['K6-1-u6-X08']::text[],false,'{"seq":4,"concept":"K6-1-u6-C8","difficulty":1,"kind":"mc","stem":"내용의 타당성을 재는 세 물음에 들지 않는 것은 어느 것인가요?","options":[{"t":"글씨가 반듯하고 고른가?","correct":true},{"t":"주장은 가치 있고 중요한가?","mis":"K6-1-u6-X08"},{"t":"이유는 주장을 적절하게 뒷받침하는가?","mis":"K6-1-u6-X08"},{"t":"근거는 이유를 적절하게 뒷받침하는가?","mis":"K6-1-u6-X08"}],"explanation":["첫째 물음이에요.","둘째 물음이에요.","세 물음은 주장 · 이유 · 근거를 재요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L02_basic#5','kor',6,1,'u6','L02','g6_1_kor_u6_L02_basic','lesson_basic','K6-1-u6-C9',2,'mc','auto','가치 있고 중요한 주장은 어느 것인가요?',ARRAY['K6-1-u6-X09']::text[],false,'{"seq":5,"concept":"K6-1-u6-C9","difficulty":2,"kind":"mc","stem":"가치 있고 중요한 주장은 어느 것인가요?","options":[{"t":"복도 정수기 앞에서는 차례를 지킵시다","correct":true},{"t":"줄 서기 싫으면 물을 마시지 맙시다","mis":"K6-1-u6-X09"},{"t":"물을 아끼려면 세수를 하지 맙시다","mis":"K6-1-u6-X09"},{"t":"목이 마르면 앞사람을 밀고 먼저 마십시다","mis":"K6-1-u6-X09"}],"explanation":["다른 문제를 만들어요.","많은 사람이 받아들이기 어려워요.","여럿에게 도움이 되는 주장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L02_basic#6','kor',6,1,'u6','L02','g6_1_kor_u6_L02_basic','lesson_basic','K6-1-u6-C10',2,'mc','auto','「도서관 책을 접지 맙시다」를 뒷받침하는 이유로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X10']::text[],false,'{"seq":6,"concept":"K6-1-u6-C10","difficulty":2,"kind":"mc","stem":"「도서관 책을 접지 맙시다」를 뒷받침하는 이유로 알맞은 것은 어느 것인가요?","options":[{"t":"접힌 자국은 펴지지 않기 때문입니다","correct":true},{"t":"도서관은 조용한 곳이기 때문입니다","mis":"K6-1-u6-X10"},{"t":"책에는 여러 가지 이야기가 담겨 있기 때문입니다","mis":"K6-1-u6-X10"},{"t":"도서관 책은 무겁기 때문입니다","mis":"K6-1-u6-X10"}],"explanation":["맞는 말이지만 접는 일과 관계없어요.","책을 접는 일과 이어지지 않아요.","접는 일과 바로 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L02_basic#7','kor',6,1,'u6','L02','g6_1_kor_u6_L02_basic','lesson_basic','K6-1-u6-C11',2,'mc','auto','문단 ④가 주장을 뒷받침하지 못하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X08','K6-1-u6-X18']::text[],false,'{"seq":7,"concept":"K6-1-u6-C11","difficulty":2,"kind":"mc","stem":"문단 ④가 주장을 뒷받침하지 못하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"골라 먹는 일을 좋게 말해 남기지 말자는 주장과 어긋나기 때문이다","correct":true},{"t":"문단이 너무 짧기 때문이다","mis":"K6-1-u6-X08"},{"t":"반찬 이야기는 모두 거짓이기 때문이다","mis":"K6-1-u6-X18"},{"t":"근거가 너무 많기 때문이다","mis":"K6-1-u6-X08"}],"explanation":["길이 문제가 아니에요.","반찬이 여러 가지인 건 사실이에요.","주장과 반대 방향이에요 — 바르게는 「여러 반찬이 나오니 조금씩 담아 골고루 먹을 수 있습니다」예요."],"asset":{"type":"passage","lines":["④ 셋째, 급식에는 여러 가지 반찬이 나와서 골라 먹는 재미가 있습니다.","⑤ 넷째, 남긴 음식을 치우는 데에도 힘이 듭니다.","우리 반 친구가 잔반이 예전보다 늘어난 것 같다고 말했습니다.","⑥ 급식은 여러 사람의 손을 거쳐 우리 앞에 옵니다.","먹을 만큼만 받고, 받은 만큼은 먹읍시다."],"title":"「급식을 남기지 맙시다」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L02_basic#8','kor',6,1,'u6','L02','g6_1_kor_u6_L02_basic','lesson_basic','K6-1-u6-C12',2,'mc','auto','「급식을 남기지 맙시다」에서 근거로 알맞지 않은 것은 어느 것인가요?',ARRAY['K6-1-u6-X05']::text[],false,'{"seq":8,"concept":"K6-1-u6-C12","difficulty":2,"kind":"mc","stem":"「급식을 남기지 맙시다」에서 근거로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"우리 반 친구가 잔반이 예전보다 늘어난 것 같다고 말했다","correct":true},{"t":"영양 선생님께서 잔반통을 하루에 두 번씩 비운다고 하셨다","mis":"K6-1-u6-X05"},{"t":"식단표에 영양소를 나누어 담도록 짜여 있다고 안내되어 있다","mis":"K6-1-u6-X05"},{"t":"남긴 음식은 그대로 버려진다","mis":"K6-1-u6-X05"}],"explanation":["여쭈어 확인한 사실이에요.","누구나 볼 수 있는 안내예요.","한 사람의 짐작이에요 — 직접 세거나 여쭈어 확인한 사실로 바꿔야 해요."],"asset":{"type":"passage","lines":["① 점심시간이 끝난 급식실 잔반통에는 먹지 않은 밥과 반찬이 수북이 쌓여 있습니다.","급식을 남기지 않았으면 좋겠습니다.","② 첫째, 남긴 음식은 그대로 버려져 아깝게 사라집니다. 우리 학교 영양 선생님께","여쭈어보았더니, 잔반통이 매일 가득 차서 하루에 두 번씩 비운다고 하셨습니다.","③ 둘째, 골고루 먹어야 몸에 필요한 영양소를 얻을 수 있습니다. 급식실 앞 식단표에","밥과 국, 반찬이 영양소를 나누어 담도록 짜여 있다고 안내되어 있습니다."],"title":"「급식을 남기지 맙시다」 — 앞부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L02_basic#9','kor',6,1,'u6','L02','g6_1_kor_u6_L02_basic','lesson_basic','K6-1-u6-C13',2,'ox','auto','타당성은 주장하는 글에서만 따져요.',ARRAY['K6-1-u6-X13']::text[],false,'{"seq":9,"concept":"K6-1-u6-C13","difficulty":2,"kind":"ox","stem":"타당성은 주장하는 글에서만 따져요.","answer":"X","reason_options":[{"t":"알림글 · 소식 · 설명하는 글처럼 내용을 담은 글이면 같은 물음을 할 수 있기 때문에","correct":true},{"t":"다른 글에는 주장이 없어 따질 것이 없기 때문에","mis":"K6-1-u6-X13"}],"mis":"K6-1-u6-X13","explanation":["주장하는 글만이 아니에요.","알림글도 따져 볼 수 있어요.","내용을 담은 글이면 어디든요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L02_basic#10','kor',6,1,'u6','L02','g6_1_kor_u6_L02_basic','lesson_basic','K6-1-u6-C14',3,'mc','auto','스스로 세운 판단 기준으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X08','K6-1-u6-X14','K6-1-u6-X23']::text[],false,'{"seq":10,"concept":"K6-1-u6-C14","difficulty":3,"kind":"mc","stem":"스스로 세운 판단 기준으로 알맞은 것은 어느 것인가요?","options":[{"t":"「한쪽 이야기만 담지는 않았는가?」","correct":true},{"t":"「글이 몇 줄인가?」","mis":"K6-1-u6-X08"},{"t":"「기준은 세 가지뿐이니 더 세우지 않는다.」","mis":"K6-1-u6-X14"},{"t":"「제목 글씨가 예쁜가?」","mis":"K6-1-u6-X23"}],"explanation":["줄 수는 타당성과 관계없어요.","기준은 더 세워도 좋아요.","물음의 꼴로 세운 알맞은 기준이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L02_challenge#1','kor',6,1,'u6','L02','g6_1_kor_u6_L02_challenge','lesson_challenge','K6-1-u6-C10',2,'mc','auto','「참인 문장이라고 해서 다 이유가 되는 것은 아니다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X18','K6-1-u6-X10','K6-1-u6-X12']::text[],false,'{"seq":1,"concept":"K6-1-u6-C10","difficulty":2,"kind":"mc","stem":"「참인 문장이라고 해서 다 이유가 되는 것은 아니다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"맞는 말이라도 주장과 관련이 없으면 이유가 되지 못한다","correct":true},{"t":"이유는 거짓이어도 된다","mis":"K6-1-u6-X18"},{"t":"맞는 말은 모두 이유로 써야 한다","mis":"K6-1-u6-X10"},{"t":"이유에는 짐작만 쓴다","mis":"K6-1-u6-X12"}],"explanation":["거짓이면 더 안 돼요.","관련이 있어야 해요.","주장과 이어져야 이유예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L02_challenge#2','kor',6,1,'u6','L02','g6_1_kor_u6_L02_challenge','lesson_challenge','K6-1-u6-C8',2,'sa','auto','「이치에 맞는 옳은 성질」을 뜻하는 낱말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-1-u6-C8","difficulty":2,"kind":"sa","stem":"「이치에 맞는 옳은 성질」을 뜻하는 낱말을 쓰세요.","answer":["타당성"],"explanation":["이치에 맞는가를 떠올려요.","내용을 재는 말이에요.","타당성이에요."],"mis":"K6-1-u6-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L02_challenge#3','kor',6,1,'u6','L02','g6_1_kor_u6_L02_challenge','lesson_challenge','K6-1-u6-C11',3,'mc','auto','문단 ④를 주장 편으로 알맞게 고쳐 쓴 것은 어느 것인가요?',ARRAY['K6-1-u6-X11','K6-1-u6-X10']::text[],false,'{"seq":3,"concept":"K6-1-u6-C11","difficulty":3,"kind":"mc","stem":"문단 ④를 주장 편으로 알맞게 고쳐 쓴 것은 어느 것인가요?","options":[{"t":"여러 반찬이 나오니 조금씩 담아 골고루 먹을 수 있습니다","correct":true},{"t":"좋아하는 반찬만 골라 먹으면 즐겁습니다","mis":"K6-1-u6-X11"},{"t":"급식에는 반찬이 여러 가지 나옵니다","mis":"K6-1-u6-X10"},{"t":"반찬이 많은 날에는 남겨도 됩니다","mis":"K6-1-u6-X11"}],"explanation":["여전히 반대 방향이에요.","사실이지만 주장과 이어지지 않아요.","같은 사실을 주장 쪽으로 이었어요."],"asset":{"type":"passage","lines":["④ 셋째, 급식에는 여러 가지 반찬이 나와서 골라 먹는 재미가 있습니다.","⑤ 넷째, 남긴 음식을 치우는 데에도 힘이 듭니다.","우리 반 친구가 잔반이 예전보다 늘어난 것 같다고 말했습니다.","⑥ 급식은 여러 사람의 손을 거쳐 우리 앞에 옵니다.","먹을 만큼만 받고, 받은 만큼은 먹읍시다."],"title":"「급식을 남기지 맙시다」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L02_challenge#4','kor',6,1,'u6','L02','g6_1_kor_u6_L02_challenge','lesson_challenge','K6-1-u6-C12',3,'mc','auto','「급식을 남기지 맙시다」 문단 ⑤의 근거를 알맞게 고쳐 쓴 것은 어느 것인가요?',ARRAY['K6-1-u6-X12','K6-1-u6-X26']::text[],false,'{"seq":4,"concept":"K6-1-u6-C12","difficulty":3,"kind":"mc","stem":"「급식을 남기지 맙시다」 문단 ⑤의 근거를 알맞게 고쳐 쓴 것은 어느 것인가요?","options":[{"t":"영양 선생님께 여쭈어보니 남은 음식을 치우는 데 날마다 손이 많이 든다고 하셨습니다","correct":true},{"t":"다른 친구도 그런 것 같다고 했습니다","mis":"K6-1-u6-X12"},{"t":"아마 다들 힘들 것입니다","mis":"K6-1-u6-X12"},{"t":"잔반은 정말 정말 많습니다","mis":"K6-1-u6-X26"}],"explanation":["짐작이 하나 더 붙었을 뿐이에요.","짐작이에요.","여쭈어 확인한 사실이에요 — 「늘어난 것 같다」는 짐작은 근거가 못 돼요."],"asset":{"type":"passage","lines":["④ 셋째, 급식에는 여러 가지 반찬이 나와서 골라 먹는 재미가 있습니다.","⑤ 넷째, 남긴 음식을 치우는 데에도 힘이 듭니다.","우리 반 친구가 잔반이 예전보다 늘어난 것 같다고 말했습니다.","⑥ 급식은 여러 사람의 손을 거쳐 우리 앞에 옵니다.","먹을 만큼만 받고, 받은 만큼은 먹읍시다."],"title":"「급식을 남기지 맙시다」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L02_challenge#5','kor',6,1,'u6','L02','g6_1_kor_u6_L02_challenge','lesson_challenge','K6-1-u6-C9',3,'ox','auto','「물을 아끼려면 세수를 하지 맙시다」는 물을 아끼자는 뜻이니 가치 있는 주장이에요.',ARRAY['K6-1-u6-X09']::text[],false,'{"seq":5,"concept":"K6-1-u6-C9","difficulty":3,"kind":"ox","stem":"「물을 아끼려면 세수를 하지 맙시다」는 물을 아끼자는 뜻이니 가치 있는 주장이에요.","answer":"X","reason_options":[{"t":"하자는 대로 하면 몸을 깨끗이 하지 못하는 다른 문제가 생기고 많은 사람이 받아들이기 어렵기 때문에","correct":true},{"t":"물을 아끼는 일은 어떤 방법이든 늘 좋은 일이기 때문에","mis":"K6-1-u6-X09"}],"mis":"K6-1-u6-X09","explanation":["뜻이 좋아도 방법을 봐요.","다른 문제를 만들어요.","여럿에게 도움이 되어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L02_challenge#6','kor',6,1,'u6','L02','g6_1_kor_u6_L02_challenge','lesson_challenge','K6-1-u6-C8',3,'match','auto','판단 물음과 그 물음이 재는 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-1-u6-C8","difficulty":3,"kind":"match","stem":"판단 물음과 그 물음이 재는 것을 알맞게 이으세요.","pairs":[{"l":"가치 있고 중요한가?","r":"주장"},{"l":"주장을 적절하게 뒷받침하는가?","r":"이유"},{"l":"이유를 적절하게 뒷받침하는가?","r":"근거"}],"mis":"K6-1-u6-X08","explanation":["가치는 주장을 재요.","이유가 주장을 받쳐요.","근거가 이유를 받쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L02_challenge#7','kor',6,1,'u6','L02','g6_1_kor_u6_L02_challenge','lesson_challenge','K6-1-u6-C13',3,'mc','auto','급식실 앞에 「이번 주부터 급식실 문을 조금 일찍 엽니다. 줄이 길어 기다리는 시간이 많기 때문입니다.」라는 알림글이 붙었어요. 알맞은 태도는 어느 것인가요?',ARRAY['K6-1-u6-X13','K6-1-u6-X05','K6-1-u6-X15']::text[],false,'{"seq":7,"concept":"K6-1-u6-C13","difficulty":3,"kind":"mc","stem":"급식실 앞에 「이번 주부터 급식실 문을 조금 일찍 엽니다. 줄이 길어 기다리는 시간이 많기 때문입니다.」라는 알림글이 붙었어요. 알맞은 태도는 어느 것인가요?","options":[{"t":"알림글에도 「까닭이 알림 내용과 이어지는가」를 물어볼 수 있다","correct":true},{"t":"알림글은 주장하는 글이 아니니 따질 것이 없다","mis":"K6-1-u6-X13"},{"t":"알림글은 틀린 곳을 많이 찾아야 한다","mis":"K6-1-u6-X05"},{"t":"알림글은 큰 글씨만 읽으면 된다","mis":"K6-1-u6-X15"}],"explanation":["알림글도 내용을 담았어요.","트집이 목적이 아니에요.","같은 물음을 댈 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L02_challenge#8','kor',6,1,'u6','L02','g6_1_kor_u6_L02_challenge','lesson_challenge','K6-1-u6-C14',4,'mc','auto','「쓸데없는 정보가 들어 있지 않은가?」라는 기준을 이 글에 대었을 때 걸리는 곳은 어느 것인가요?',ARRAY['K6-1-u6-X05','K6-1-u6-X07']::text[],false,'{"seq":8,"concept":"K6-1-u6-C14","difficulty":4,"kind":"mc","stem":"「쓸데없는 정보가 들어 있지 않은가?」라는 기준을 이 글에 대었을 때 걸리는 곳은 어느 것인가요?","options":[{"t":"문단 ④ — 골라 먹는 재미 이야기는 남기지 말자는 주장에 쓸모가 없고 오히려 어긋난다","correct":true},{"t":"문단 ⑤의 「남긴 음식을 치우는 데에도 힘이 듭니다」","mis":"K6-1-u6-X05"},{"t":"문단 ⑥의 「급식은 여러 사람의 손을 거쳐 우리 앞에 옵니다」","mis":"K6-1-u6-X07"},{"t":"문단 ⑥의 「먹을 만큼만 받고, 받은 만큼은 먹읍시다」","mis":"K6-1-u6-X07"}],"explanation":["주장과 이어진 이유예요.","결론의 마무리예요.","내가 세운 기준으로도 문단 ④가 걸려요 — 바르게는 「조금씩 담아 골고루 먹을 수 있다」예요."],"asset":{"type":"passage","lines":["④ 셋째, 급식에는 여러 가지 반찬이 나와서 골라 먹는 재미가 있습니다.","⑤ 넷째, 남긴 음식을 치우는 데에도 힘이 듭니다.","우리 반 친구가 잔반이 예전보다 늘어난 것 같다고 말했습니다.","⑥ 급식은 여러 사람의 손을 거쳐 우리 앞에 옵니다.","먹을 만큼만 받고, 받은 만큼은 먹읍시다."],"title":"「급식을 남기지 맙시다」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L02_challenge#9','kor',6,1,'u6','L02','g6_1_kor_u6_L02_challenge','lesson_challenge','K6-1-u6-C9',4,'essay','teacher','「급식을 남기지 맙시다」를 세 기준(주장 · 이유 · 근거)으로 판단하고, 기준마다 판단의 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u6-C9","difficulty":4,"kind":"essay","stem":"「급식을 남기지 맙시다」를 세 기준(주장 · 이유 · 근거)으로 판단하고, 기준마다 판단의 까닭을 쓰세요.","answer_guide":{"answer":"예: 주장 — 급식을 남기지 말자는 주장은 여러 사람에게 도움이 되고 누구나 받아들일 만해 가치 있다. 이유 — 문단 ②·③·⑤는 주장과 이어지지만 문단 ④는 골라 먹는 재미를 좋게 말해 주장과 어긋난다. 근거 — 영양 선생님께 여쭈어 확인한 사실은 알맞지만 「잔반이 늘어난 것 같다」는 친구의 말은 한 사람의 짐작이라 근거가 되지 못한다.","scoring_points":["주장의 가치를 까닭과 함께 판단했는가","어긋난 이유를 찾고 까닭을 썼는가","짐작 근거를 찾고 까닭을 썼는가"]},"explanation":["세 물음을 차례로 대요.","걸린 곳은 까닭을 대요.","받아들일 곳도 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L02_challenge#10','kor',6,1,'u6','L02','g6_1_kor_u6_L02_challenge','lesson_challenge','K6-1-u6-C14',4,'essay','teacher','오늘 배운 세 기준 말고 내가 쓸 판단 기준 하나를 물음의 꼴로 세우고, 그 기준을 「급식을 남기지 맙시다」에 대어 본 결과를 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u6-C14","difficulty":4,"kind":"essay","stem":"오늘 배운 세 기준 말고 내가 쓸 판단 기준 하나를 물음의 꼴로 세우고, 그 기준을 「급식을 남기지 맙시다」에 대어 본 결과를 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 내 기준 — 「문제가 아닌 일을 문제라고 하지는 않는가?」 이 기준을 대어 보니 이 글은 잔반통에 남은 음식이 쌓이는 일을 문제로 삼았는데, 영양 선생님 말씀처럼 실제로 잔반통을 하루에 두 번씩 비우므로 문제가 맞다. 그래서 이 기준에는 걸리지 않는다.","scoring_points":["물음의 꼴로 기준을 세웠는가","그 기준을 글에 대어 보았는가","판단의 까닭을 썼는가"]},"explanation":["물음의 꼴로 적어요.","글에 직접 대어 봐요.","결과에 까닭을 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L04_basic#1','kor',6,1,'u6','L04','g6_1_kor_u6_L04_basic','lesson_basic','K6-1-u6-C15',1,'mc','auto','채린이가 겪은 일에서 알 수 있는 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X15','K6-1-u6-X01']::text[],false,'{"seq":1,"concept":"K6-1-u6-C15","difficulty":1,"kind":"mc","stem":"채린이가 겪은 일에서 알 수 있는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"글에 적혀 있다고 모두 그대로 일어나지는 않는다","correct":true},{"t":"큰 글씨만 읽으면 충분하다","mis":"K6-1-u6-X15"},{"t":"포장에 적힌 말은 다 맞다","mis":"K6-1-u6-X01"},{"t":"작은 글씨는 읽지 않아도 된다","mis":"K6-1-u6-X15"}],"explanation":["작은 글씨에 조건이 있었어요.","포장 글도 따져 봐요.","한 번 더 확인해요."],"asset":{"type":"speech","turns":[{"who":"채린","text":"지난주에 「이 지우개는 자국이 하나도 남지 않는다」는 말을 보고 샀거든."},{"who":"소담","text":"써 보니까 어땠는데?"},{"who":"채린","text":"자국은 남더라. 포장을 다시 읽어 봤더니 작은 글씨로 종이에 따라 다르다고 적혀 있었어."},{"who":"소담","text":"앞의 큰 글씨만 읽었으니 그런 거네. 다음부터는 뒤까지 읽어 봐야겠다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L04_basic#2','kor',6,1,'u6','L04','g6_1_kor_u6_L04_basic','lesson_basic','K6-1-u6-C16',1,'match','auto','안전모 글의 이유와 그 이유를 받치는 근거를 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K6-1-u6-C16","difficulty":1,"kind":"match","stem":"안전모 글의 이유와 그 이유를 받치는 근거를 알맞게 이으세요.","pairs":[{"l":"넘어질 때 머리를 지켜 준다","r":"안쪽 스티로폼 층이 부딪히는 힘을 나누어 받는다"},{"l":"나를 지키는 습관을 일찍 들일 수 있다","r":"사흘 동안 세어 보니 열 대 가운데 두 대뿐이었다"},{"l":"머리에 잘 맞게 써야 제 몫을 한다","r":"옆집 형이 헐렁한 것은 소용없다고 말해 주었다"}],"mis":"K6-1-u6-X16","explanation":["머리를 지키는 까닭이에요.","습관을 보여 주는 기록이에요.","같은 문단 안에서 짝을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L04_basic#3','kor',6,1,'u6','L04','g6_1_kor_u6_L04_basic','lesson_basic','K6-1-u6-C20',1,'mc','auto','한 편의 글을 세 기준으로 재는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X20']::text[],false,'{"seq":3,"concept":"K6-1-u6-C20","difficulty":1,"kind":"mc","stem":"한 편의 글을 세 기준으로 재는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"주장 → 이유 → 근거","correct":true},{"t":"근거 → 주장 → 이유","mis":"K6-1-u6-X20"},{"t":"이유 → 근거 → 주장","mis":"K6-1-u6-X20"},{"t":"아무 차례로나 한꺼번에","mis":"K6-1-u6-X20"}],"explanation":["근거부터 재면 짝을 놓쳐요.","주장부터 봐요.","주장, 이유, 근거 차례예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L04_basic#4','kor',6,1,'u6','L04','g6_1_kor_u6_L04_basic','lesson_basic','K6-1-u6-C21',1,'ox','auto','걸린 곳이 두 군데 있으면 그 글 전체를 버려야 해요.',ARRAY['K6-1-u6-X21']::text[],false,'{"seq":4,"concept":"K6-1-u6-C21","difficulty":1,"kind":"ox","stem":"걸린 곳이 두 군데 있으면 그 글 전체를 버려야 해요.","answer":"X","reason_options":[{"t":"걸린 곳만 까닭을 대어 짚고 타당한 부분은 받아들이면 되기 때문에","correct":true},{"t":"틀린 곳이 있는 글은 하나도 믿을 수 없기 때문에","mis":"K6-1-u6-X21"}],"mis":"K6-1-u6-X21","explanation":["쓸 수 있는 정보까지 버리게 돼요.","고르게 부족한 글은 드물어요.","받아들일 것을 골라내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L04_basic#5','kor',6,1,'u6','L04','g6_1_kor_u6_L04_basic','lesson_basic','K6-1-u6-C17',2,'mc','auto','「이 글의 주장은 가치 있고 중요한가요?」에 가장 좋은 답은 어느 것인가요?',ARRAY['K6-1-u6-X17','K6-1-u6-X09','K6-1-u6-X06']::text[],false,'{"seq":5,"concept":"K6-1-u6-C17","difficulty":2,"kind":"mc","stem":"「이 글의 주장은 가치 있고 중요한가요?」에 가장 좋은 답은 어느 것인가요?","options":[{"t":"가치 있다 — 다치는 일을 줄여 주고 누구나 받아들일 만하다","correct":true},{"t":"가치 있다 — 글에 그렇게 적혀 있기 때문이다","mis":"K6-1-u6-X17"},{"t":"가치 없다 — 안전모를 쓰면 번거롭기 때문이다","mis":"K6-1-u6-X09"},{"t":"가치 있다","mis":"K6-1-u6-X06"}],"explanation":["적혀 있다는 건 까닭이 아니에요.","번거로움보다 다치지 않는 게 커요.","판단과 까닭이 한 짝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L04_basic#6','kor',6,1,'u6','L04','g6_1_kor_u6_L04_basic','lesson_basic','K6-1-u6-C18',2,'mc','auto','주장을 뒷받침하지 못하는 이유는 어느 것인가요?',ARRAY['K6-1-u6-X05']::text[],false,'{"seq":6,"concept":"K6-1-u6-C18","difficulty":2,"kind":"mc","stem":"주장을 뒷받침하지 못하는 이유는 어느 것인가요?","options":[{"t":"안전모를 쓰면 자전거가 더 빨리 달린다","correct":true},{"t":"넘어질 때 머리를 지켜 준다","mis":"K6-1-u6-X05"},{"t":"나를 지키는 습관을 일찍 들일 수 있다","mis":"K6-1-u6-X05"},{"t":"머리에 잘 맞게 써야 제 몫을 한다","mis":"K6-1-u6-X05"}],"explanation":["주장과 이어지는 이유예요.","이것도 주장과 이어져요.","사실도 아니고 주장과도 어긋나요 — 바르게는 「구멍이 뚫려 있어 오래 써도 답답하지 않습니다」예요."],"asset":{"type":"passage","lines":["① 자전거를 타는 사람이 늘어난 만큼 넘어지는 일도 늘었습니다.","자전거를 탈 때에는 안전모를 썼으면 좋겠습니다.","② 첫째, 넘어질 때 머리를 지켜 줍니다. 안전모 안쪽에 든 두꺼운 스티로폼 층이","부딪히는 힘을 나누어 받습니다.","③ 둘째, 안전모를 쓰면 자전거가 더 빨리 달립니다.","안전모에는 구멍이 여러 개 뚫려 있어 바람이 지나갑니다."],"title":"「자전거를 탈 때 안전모를 씁시다」 — 앞부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L04_basic#7','kor',6,1,'u6','L04','g6_1_kor_u6_L04_basic','lesson_basic','K6-1-u6-C19',2,'mc','auto','근거로 알맞지 않은 것은 어느 것인가요?',ARRAY['K6-1-u6-X05']::text[],false,'{"seq":7,"concept":"K6-1-u6-C19","difficulty":2,"kind":"mc","stem":"근거로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"옆집 형이 헐렁한 안전모는 소용이 없다고 말해 주었다","correct":true},{"t":"보관대를 사흘 동안 세어 보니 열 대 가운데 두 대뿐이었다","mis":"K6-1-u6-X05"},{"t":"안쪽 스티로폼 층이 부딪히는 힘을 나누어 받는다","mis":"K6-1-u6-X05"},{"t":"안전모 상자에 끈을 턱 아래에서 조이라고 적혀 있다","mis":"K6-1-u6-X05"}],"explanation":["직접 센 기록이에요.","누구나 확인할 수 있는 사실이에요.","전해 들은 말이라 다시 확인할 수 없어요 — 상자에 적힌 안내처럼 확인할 수 있는 것으로 바꿔요."],"asset":{"type":"passage","lines":["④ 셋째, 나를 지키는 습관을 일찍 들일 수 있습니다. 우리 학교 자전거 보관대를","사흘 동안 세어 보니, 안전모를 함께 걸어 둔 자전거는 열 대 가운데 두 대뿐이었습니다.","⑤ 넷째, 안전모는 머리에 잘 맞게 써야 제 몫을 합니다.","옆집 형이 헐렁한 안전모는 소용이 없다고 말해 주었습니다.","⑥ 그 잠깐이 오래 남을 일을 막아 줍니다. 자전거를 탈 때에는 안전모를 씁시다."],"title":"「자전거를 탈 때 안전모를 씁시다」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L04_basic#8','kor',6,1,'u6','L04','g6_1_kor_u6_L04_basic','lesson_basic','K6-1-u6-C19',2,'mc','auto','좋은 근거들의 공통점으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X19','K6-1-u6-X12','K6-1-u6-X08']::text[],false,'{"seq":8,"concept":"K6-1-u6-C19","difficulty":2,"kind":"mc","stem":"좋은 근거들의 공통점으로 알맞은 것은 어느 것인가요?","options":[{"t":"다른 사람도 같은 길로 다시 가 확인할 수 있다","correct":true},{"t":"아는 사람이 말해 주었다","mis":"K6-1-u6-X19"},{"t":"글쓴이가 강하게 믿는다","mis":"K6-1-u6-X12"},{"t":"문장이 길고 자세하다","mis":"K6-1-u6-X08"}],"explanation":["전해 들은 말은 확인하기 어려워요.","믿음은 근거가 아니에요.","되짚어 확인할 수 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L04_basic#9','kor',6,1,'u6','L04','g6_1_kor_u6_L04_basic','lesson_basic','K6-1-u6-C22',2,'mc','auto','둘레의 글을 판단하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X22','K6-1-u6-X05','K6-1-u6-X01']::text[],false,'{"seq":9,"concept":"K6-1-u6-C22","difficulty":2,"kind":"mc","stem":"둘레의 글을 판단하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"게시판 글의 주장 · 이유 · 근거를 옮겨 적고 세 기준으로 재어, 걸리는 곳은 까닭과 고칠 방법을 적는다","correct":true},{"t":"배운 기준은 공부 시간의 글에만 쓴다","mis":"K6-1-u6-X22"},{"t":"걸리는 곳의 개수만 센다","mis":"K6-1-u6-X05"},{"t":"포장에 적힌 글은 그대로 믿는다","mis":"K6-1-u6-X01"}],"explanation":["둘레의 글에도 대어 봐요.","개수가 아니라 까닭이에요.","포장 글도 따져 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L04_basic#10','kor',6,1,'u6','L04','g6_1_kor_u6_L04_basic','lesson_basic','K6-1-u6-C21',3,'mc','auto','안전모 글에서 받아들여도 좋은 부분만 모은 것은 어느 것인가요?',ARRAY['K6-1-u6-X18','K6-1-u6-X21','K6-1-u6-X01']::text[],false,'{"seq":10,"concept":"K6-1-u6-C21","difficulty":3,"kind":"mc","stem":"안전모 글에서 받아들여도 좋은 부분만 모은 것은 어느 것인가요?","options":[{"t":"안전모를 쓰자는 주장 · 머리를 지켜 준다는 이유 · 사흘 동안 센 기록","correct":true},{"t":"더 빨리 달린다는 이유 · 옆집 형에게서 전해 들은 말","mis":"K6-1-u6-X18"},{"t":"받아들일 것이 하나도 없다","mis":"K6-1-u6-X21"},{"t":"글에 있는 모든 문장","mis":"K6-1-u6-X01"}],"explanation":["두 곳은 걸린 곳이에요 — 안전모는 빠르기와 관계없어요.","걸린 곳은 두 군데뿐이에요.","걸린 곳을 빼고 골라냈어요."],"asset":{"type":"passage","lines":["④ 셋째, 나를 지키는 습관을 일찍 들일 수 있습니다. 우리 학교 자전거 보관대를","사흘 동안 세어 보니, 안전모를 함께 걸어 둔 자전거는 열 대 가운데 두 대뿐이었습니다.","⑤ 넷째, 안전모는 머리에 잘 맞게 써야 제 몫을 합니다.","옆집 형이 헐렁한 안전모는 소용이 없다고 말해 주었습니다.","⑥ 그 잠깐이 오래 남을 일을 막아 줍니다. 자전거를 탈 때에는 안전모를 씁시다."],"title":"「자전거를 탈 때 안전모를 씁시다」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L04_challenge#1','kor',6,1,'u6','L04','g6_1_kor_u6_L04_challenge','lesson_challenge','K6-1-u6-C15',2,'mc','auto','소담이가 「다음부터는 뒤까지 읽어 봐야겠다」고 한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X15','K6-1-u6-X01','K6-1-u6-X21']::text[],false,'{"seq":1,"concept":"K6-1-u6-C15","difficulty":2,"kind":"mc","stem":"소담이가 「다음부터는 뒤까지 읽어 봐야겠다」고 한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"큰 글씨만 읽어서 작은 글씨에 적힌 조건을 놓쳤기 때문이다","correct":true},{"t":"큰 글씨가 틀렸으니 작은 글씨는 볼 필요가 없기 때문이다","mis":"K6-1-u6-X15"},{"t":"포장에 적힌 말은 늘 맞기 때문이다","mis":"K6-1-u6-X01"},{"t":"지우개를 버리려고 하기 때문이다","mis":"K6-1-u6-X21"}],"explanation":["작은 글씨에 답이 있었어요.","포장 글도 따져 봐요.","조건까지 읽고 확인해요."],"asset":{"type":"speech","turns":[{"who":"채린","text":"지난주에 「이 지우개는 자국이 하나도 남지 않는다」는 말을 보고 샀거든."},{"who":"소담","text":"써 보니까 어땠는데?"},{"who":"채린","text":"자국은 남더라. 포장을 다시 읽어 봤더니 작은 글씨로 종이에 따라 다르다고 적혀 있었어."},{"who":"소담","text":"앞의 큰 글씨만 읽었으니 그런 거네. 다음부터는 뒤까지 읽어 봐야겠다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L04_challenge#2','kor',6,1,'u6','L04','g6_1_kor_u6_L04_challenge','lesson_challenge','K6-1-u6-C18',2,'ox','auto','「안전모를 쓰면 자전거가 더 빨리 달린다」는 두 곳에서 걸려요.',ARRAY['K6-1-u6-X28']::text[],false,'{"seq":2,"concept":"K6-1-u6-C18","difficulty":2,"kind":"ox","stem":"「안전모를 쓰면 자전거가 더 빨리 달린다」는 두 곳에서 걸려요.","answer":"O","reason_options":[{"t":"실제로 일어나지 않는 일이고, 빨리 달리는 일은 안전하자는 주장과도 어긋나기 때문에","correct":true},{"t":"한 문장은 한 곳에만 걸리기 때문에","mis":"K6-1-u6-X28"}],"mis":"K6-1-u6-X28","explanation":["사실이 아니에요.","주장과도 어긋나요.","한 문장이 두 곳에 걸릴 수 있어요 — 안전모는 빠르기와 관계없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L04_challenge#3','kor',6,1,'u6','L04','g6_1_kor_u6_L04_challenge','lesson_challenge','K6-1-u6-C16',3,'mc','auto','「사흘 동안 세어 보니 열 대 가운데 두 대뿐이었다」가 받치는 이유는 어느 것인가요?',ARRAY['K6-1-u6-X16']::text[],false,'{"seq":3,"concept":"K6-1-u6-C16","difficulty":3,"kind":"mc","stem":"「사흘 동안 세어 보니 열 대 가운데 두 대뿐이었다」가 받치는 이유는 어느 것인가요?","options":[{"t":"나를 지키는 습관을 일찍 들일 수 있다","correct":true},{"t":"넘어질 때 머리를 지켜 준다","mis":"K6-1-u6-X16"},{"t":"자전거가 더 빨리 달린다","mis":"K6-1-u6-X16"},{"t":"머리에 잘 맞게 써야 제 몫을 한다","mis":"K6-1-u6-X16"}],"explanation":["그 이유의 근거는 스티로폼 층이에요.","이 이유는 걸린 문장이에요.","같은 문단 ④ 안에서 짝을 찾아요."],"asset":{"type":"passage","lines":["④ 셋째, 나를 지키는 습관을 일찍 들일 수 있습니다. 우리 학교 자전거 보관대를","사흘 동안 세어 보니, 안전모를 함께 걸어 둔 자전거는 열 대 가운데 두 대뿐이었습니다.","⑤ 넷째, 안전모는 머리에 잘 맞게 써야 제 몫을 합니다.","옆집 형이 헐렁한 안전모는 소용이 없다고 말해 주었습니다.","⑥ 그 잠깐이 오래 남을 일을 막아 줍니다. 자전거를 탈 때에는 안전모를 씁시다."],"title":"「자전거를 탈 때 안전모를 씁시다」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L04_challenge#4','kor',6,1,'u6','L04','g6_1_kor_u6_L04_challenge','lesson_challenge','K6-1-u6-C19',3,'mc','auto','안전모 글 문단 ⑤의 근거를 알맞게 고쳐 쓴 것은 어느 것인가요?',ARRAY['K6-1-u6-X19','K6-1-u6-X12']::text[],false,'{"seq":4,"concept":"K6-1-u6-C19","difficulty":3,"kind":"mc","stem":"안전모 글 문단 ⑤의 근거를 알맞게 고쳐 쓴 것은 어느 것인가요?","options":[{"t":"안전모 상자에는 머리둘레에 맞는 크기를 고르고 끈을 턱 아래에서 조이라고 적혀 있다","correct":true},{"t":"옆 반 친구도 그렇다고 말해 주었다","mis":"K6-1-u6-X19"},{"t":"아마 다들 그렇게 생각할 것이다","mis":"K6-1-u6-X12"},{"t":"형이 아주 크게 말해 주었다","mis":"K6-1-u6-X19"}],"explanation":["전해 들은 말이 하나 더 붙었을 뿐이에요.","짐작이에요.","누구나 확인할 수 있는 사실이에요."],"asset":{"type":"passage","lines":["④ 셋째, 나를 지키는 습관을 일찍 들일 수 있습니다. 우리 학교 자전거 보관대를","사흘 동안 세어 보니, 안전모를 함께 걸어 둔 자전거는 열 대 가운데 두 대뿐이었습니다.","⑤ 넷째, 안전모는 머리에 잘 맞게 써야 제 몫을 합니다.","옆집 형이 헐렁한 안전모는 소용이 없다고 말해 주었습니다.","⑥ 그 잠깐이 오래 남을 일을 막아 줍니다. 자전거를 탈 때에는 안전모를 씁시다."],"title":"「자전거를 탈 때 안전모를 씁시다」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L04_challenge#5','kor',6,1,'u6','L04','g6_1_kor_u6_L04_challenge','lesson_challenge','K6-1-u6-C17',3,'mc','auto','「가치 있다 — 글에 그렇게 적혀 있으므로」가 좋은 답이 아닌 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X37','K6-1-u6-X08','K6-1-u6-X01']::text[],false,'{"seq":5,"concept":"K6-1-u6-C17","difficulty":3,"kind":"mc","stem":"「가치 있다 — 글에 그렇게 적혀 있으므로」가 좋은 답이 아닌 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"적혀 있다는 것은 주장이 왜 가치 있는지를 말해 주지 않기 때문이다","correct":true},{"t":"가치 있다는 판단이 틀렸기 때문이다","mis":"K6-1-u6-X37"},{"t":"까닭이 너무 짧기 때문이다","mis":"K6-1-u6-X08"},{"t":"글은 언제나 옳기 때문이다","mis":"K6-1-u6-X01"}],"explanation":["판단은 맞았어요.","길이 문제가 아니에요.","까닭이 판단을 받쳐야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L04_challenge#6','kor',6,1,'u6','L04','g6_1_kor_u6_L04_challenge','lesson_challenge','K6-1-u6-C20',3,'mc','auto','안전모 글의 근거를 따지기 전에 먼저 할 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X08','K6-1-u6-X20']::text[],false,'{"seq":6,"concept":"K6-1-u6-C20","difficulty":3,"kind":"mc","stem":"안전모 글의 근거를 따지기 전에 먼저 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"주장과 이유를 먼저 재고, 근거가 어느 이유에 붙는지 잡는다","correct":true},{"t":"근거의 글자 수를 센다","mis":"K6-1-u6-X08"},{"t":"근거만 보고 주장은 건너뛴다","mis":"K6-1-u6-X20"},{"t":"세 기준을 아무 문단에나 한꺼번에 댄다","mis":"K6-1-u6-X20"}],"explanation":["글자 수는 관계없어요.","주장부터 재요.","주장 → 이유 → 근거 차례예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L04_challenge#7','kor',6,1,'u6','L04','g6_1_kor_u6_L04_challenge','lesson_challenge','K6-1-u6-C21',3,'mc','auto','「여섯 문단 가운데 걸린 곳은 두 군데」라고 판단한 뒤에 할 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X21','K6-1-u6-X05','K6-1-u6-X35']::text[],false,'{"seq":7,"concept":"K6-1-u6-C21","difficulty":3,"kind":"mc","stem":"「여섯 문단 가운데 걸린 곳은 두 군데」라고 판단한 뒤에 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"걸린 두 곳은 고칠 방법을 적고, 나머지는 받아들인다","correct":true},{"t":"걸린 곳이 있으니 글을 버린다","mis":"K6-1-u6-X21"},{"t":"걸린 곳을 더 찾을 때까지 트집을 잡는다","mis":"K6-1-u6-X05"},{"t":"걸린 곳도 그냥 둔다","mis":"K6-1-u6-X35"}],"explanation":["쓸 정보까지 버려요.","트집이 목적이 아니에요.","받아들일 것과 고칠 것을 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L04_challenge#8','kor',6,1,'u6','L04','g6_1_kor_u6_L04_challenge','lesson_challenge','K6-1-u6-C22',4,'mc','auto','교실 게시판에 「쉬는 시간에는 교실에서만 놉시다. 운동장은 넓기 때문입니다.」가 붙었어요. 가장 알맞은 판단은 어느 것인가요?',ARRAY['K6-1-u6-X08','K6-1-u6-X22','K6-1-u6-X06']::text[],false,'{"seq":8,"concept":"K6-1-u6-C22","difficulty":4,"kind":"mc","stem":"교실 게시판에 「쉬는 시간에는 교실에서만 놉시다. 운동장은 넓기 때문입니다.」가 붙었어요. 가장 알맞은 판단은 어느 것인가요?","options":[{"t":"이유가 주장과 이어지지 않는다 — 운동장이 넓다는 말은 교실에서만 놀자는 주장을 받치지 못한다","correct":true},{"t":"주장이 짧아서 가치가 없다","mis":"K6-1-u6-X08"},{"t":"게시판 글이니 판단하지 않는다","mis":"K6-1-u6-X22"},{"t":"그냥 별로다","mis":"K6-1-u6-X06"}],"explanation":["길이로 가치를 재지 않아요.","둘레의 글에도 대어 봐요.","판단에 까닭이 붙었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L04_challenge#9','kor',6,1,'u6','L04','g6_1_kor_u6_L04_challenge','lesson_challenge','K6-1-u6-C21',4,'essay','teacher','안전모 글을 판단한 결과를 「받아들일 것」과 「걸린 것」으로 나누어 쓰고, 각각의 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u6-C21","difficulty":4,"kind":"essay","stem":"안전모 글을 판단한 결과를 「받아들일 것」과 「걸린 것」으로 나누어 쓰고, 각각의 까닭을 쓰세요.","answer_guide":{"answer":"예: 받아들일 것 — 안전모를 쓰자는 주장(다치는 일을 줄여 주어 가치 있다), 머리를 지켜 준다는 이유와 스티로폼 층 근거(누구나 확인할 수 있다), 사흘 동안 센 기록(직접 센 기록이다). 걸린 것 — 문단 ③ 「더 빨리 달린다」(사실이 아니고 주장과도 어긋난다), 문단 ⑤ 옆집 형의 말(전해 들은 말이라 확인할 수 없다).","scoring_points":["받아들일 것을 까닭과 함께 썼는가","걸린 두 곳을 까닭과 함께 썼는가","글 전체를 버리지 않았는가"]},"explanation":["정리표를 떠올려요.","걸린 곳은 둘이에요.","까닭을 붙여요."],"asset":{"type":"passage","lines":["④ 셋째, 나를 지키는 습관을 일찍 들일 수 있습니다. 우리 학교 자전거 보관대를","사흘 동안 세어 보니, 안전모를 함께 걸어 둔 자전거는 열 대 가운데 두 대뿐이었습니다.","⑤ 넷째, 안전모는 머리에 잘 맞게 써야 제 몫을 합니다.","옆집 형이 헐렁한 안전모는 소용이 없다고 말해 주었습니다.","⑥ 그 잠깐이 오래 남을 일을 막아 줍니다. 자전거를 탈 때에는 안전모를 씁시다."],"title":"「자전거를 탈 때 안전모를 씁시다」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L04_challenge#10','kor',6,1,'u6','L04','g6_1_kor_u6_L04_challenge','lesson_challenge','K6-1-u6-C18',4,'essay','teacher','문단 ③의 이유가 걸리는 두 곳을 쓰고, 주장 편에 서도록 고쳐 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u6-C18","difficulty":4,"kind":"essay","stem":"문단 ③의 이유가 걸리는 두 곳을 쓰고, 주장 편에 서도록 고쳐 쓰세요.","answer_guide":{"answer":"예: 첫째, 안전모는 자전거의 빠르기와 관계가 없어 실제로 일어나지 않는 일이다. 둘째, 빨리 달리는 일은 안전을 지키자는 주장과도 어긋난다. 고쳐 쓰면 — 「안전모에는 구멍이 뚫려 있어 오래 써도 답답하지 않습니다.」","scoring_points":["사실이 아님을 썼는가","주장과 어긋남을 썼는가","주장 편으로 고쳐 썼는가"]},"explanation":["정말 일어나는 일인지 물어요.","주장 편인지 물어요.","같은 사실을 주장 쪽으로 이어요."],"asset":{"type":"passage","lines":["① 자전거를 타는 사람이 늘어난 만큼 넘어지는 일도 늘었습니다.","자전거를 탈 때에는 안전모를 썼으면 좋겠습니다.","② 첫째, 넘어질 때 머리를 지켜 줍니다. 안전모 안쪽에 든 두꺼운 스티로폼 층이","부딪히는 힘을 나누어 받습니다.","③ 둘째, 안전모를 쓰면 자전거가 더 빨리 달립니다.","안전모에는 구멍이 여러 개 뚫려 있어 바람이 지나갑니다."],"title":"「자전거를 탈 때 안전모를 씁시다」 — 앞부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L07_basic#1','kor',6,1,'u6','L07','g6_1_kor_u6_L07_basic','lesson_basic','K6-1-u6-C23',1,'mc','auto','「표현의 적절성」이 재는 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X23','K6-1-u6-X03']::text[],false,'{"seq":1,"concept":"K6-1-u6-C23","difficulty":1,"kind":"mc","stem":"「표현의 적절성」이 재는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"그 내용을 알맞은 말로 나타냈는가","correct":true},{"t":"글씨가 예쁜가","mis":"K6-1-u6-X23"},{"t":"문장이 긴가","mis":"K6-1-u6-X23"},{"t":"주장이 가치 있고 중요한가","mis":"K6-1-u6-X03"}],"explanation":["글씨는 재지 않아요.","길이도 아니에요.","어떻게 말했는가를 재요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L07_basic#2','kor',6,1,'u6','L07','g6_1_kor_u6_L07_basic','lesson_basic','K6-1-u6-C26',1,'match','auto','표현의 적절성을 재는 기준과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K6-1-u6-C26","difficulty":1,"kind":"match","stem":"표현의 적절성을 재는 기준과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"거짓된 표현","r":"없는 것을 있는 것처럼 말함"},{"l":"과장된 표현","r":"있는 것을 실제보다 부풀림"},{"l":"감추는 내용","r":"알아야 할 것을 밝히지 않음"}],"mis":"K6-1-u6-X25","explanation":["없는 걸 있다고 하면 거짓이에요.","있는 걸 부풀리면 과장이에요.","빠뜨리면 감춤이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L07_basic#3','kor',6,1,'u6','L07','g6_1_kor_u6_L07_basic','lesson_basic','K6-1-u6-C24',1,'mc','auto','재이가 깨달은 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X24','K6-1-u6-X01']::text[],false,'{"seq":3,"concept":"K6-1-u6-C24","difficulty":1,"kind":"mc","stem":"재이가 깨달은 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"무엇을 크게 했는지만큼 무엇을 작게 했는지도 보아야 한다","correct":true},{"t":"큰 글씨만 보면 된다","mis":"K6-1-u6-X24"},{"t":"작은 글씨는 실수로 작게 쓴 것이다","mis":"K6-1-u6-X24"},{"t":"빨간 글씨는 다 맞는 말이다","mis":"K6-1-u6-X01"}],"explanation":["큰 글씨만 보면 조건을 놓쳐요.","일부러 작게 쓴 거예요.","작게 쓴 것도 살펴요."],"asset":{"type":"speech","turns":[{"who":"라율","text":"문구점 앞에 「하나 사면 하나 더」라고 크고 빨갛게 적혀 있었어."},{"who":"재이","text":"그 글씨만 눈에 들어오지. 그런데 밑에 작게 뭐라고 더 적혀 있지 않았어?"},{"who":"라율","text":"맞아. 가서 보니 정해진 물건 몇 가지만 그렇다고 아주 작게 적혀 있더라."},{"who":"재이","text":"큰 글씨는 눈에 띄라고 크게 쓴 거고, 작은 글씨는 안 보이라고 작게 쓴 거네."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L07_basic#4','kor',6,1,'u6','L07','g6_1_kor_u6_L07_basic','lesson_basic','K6-1-u6-C24',1,'mc','auto','광고에서 「여기를 봐 달라」고 표시한 자국으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X24']::text[],false,'{"seq":4,"concept":"K6-1-u6-C24","difficulty":1,"kind":"mc","stem":"광고에서 「여기를 봐 달라」고 표시한 자국으로 알맞은 것은 어느 것인가요?","options":[{"t":"큰 글씨 · 진한 색 · 느낌표","correct":true},{"t":"아주 작은 글씨","mis":"K6-1-u6-X24"},{"t":"흐린 회색 글씨","mis":"K6-1-u6-X24"},{"t":"비워 둔 곳","mis":"K6-1-u6-X24"}],"explanation":["작은 글씨는 눈에 덜 띄어요.","흐린 글씨도 그래요.","크게 · 진하게 · 느낌표로 강조해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L07_basic#5','kor',6,1,'u6','L07','g6_1_kor_u6_L07_basic','lesson_basic','K6-1-u6-C25',2,'mc','auto','물통 광고에서 거짓된 표현은 어느 것인가요?',ARRAY['K6-1-u6-X05','K6-1-u6-X25']::text[],false,'{"seq":5,"concept":"K6-1-u6-C25","difficulty":2,"kind":"mc","stem":"물통 광고에서 거짓된 표현은 어느 것인가요?","options":[{"t":"뚜껑을 열어도 얼음이 녹지 않아요","correct":true},{"t":"두 겹 벽이 바깥 열을 막아 줍니다","mis":"K6-1-u6-X05"},{"t":"가방에 넣어 들고 다닐 수 있습니다","mis":"K6-1-u6-X05"},{"t":"여름 준비, 이것 하나면 끝!","mis":"K6-1-u6-X25"}],"explanation":["실제로 있는 기능이에요.","「이것 하나면 끝」은 부풀린 과장이라 거짓과 갈라요.","뚜껑을 열면 바깥 공기가 바로 들어와 얼음이 녹아요 — 거짓이에요."],"asset":{"type":"passage","lines":["장면 ① 물통을 든 아이가 환하게 웃는 큰 그림","　　「여름 준비, 이것 하나면 끝!」 「하루 종일 시원한 물통」","장면 ② 물통 안에 얼음이 가득한 그림","　　「얼음이 하루 종일 그대로! 뚜껑을 열어도 녹지 않아요.」","　　「두 겹 벽이 바깥 열을 막아 줍니다.」"],"title":"물통 광고 「하루 종일 시원한 물통」 — 앞 장면 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L07_basic#6','kor',6,1,'u6','L07','g6_1_kor_u6_L07_basic','lesson_basic','K6-1-u6-C26',2,'mc','auto','과장된 표현과 그 까닭을 알맞게 짝지은 것은 어느 것인가요?',ARRAY['K6-1-u6-X25','K6-1-u6-X24','K6-1-u6-X27']::text[],false,'{"seq":6,"concept":"K6-1-u6-C26","difficulty":2,"kind":"mc","stem":"과장된 표현과 그 까닭을 알맞게 짝지은 것은 어느 것인가요?","options":[{"t":"「절대 새지 않는」 — 새지 않게 만든 것은 맞지만 어떤 경우에도 그렇다고 부풀렸다","correct":true},{"t":"「절대 새지 않는」 — 없는 기능을 있다고 했다","mis":"K6-1-u6-X25"},{"t":"「※ 뚜껑을 끝까지 … 샐 수 있음」 — 작게 써서 부풀렸다","mis":"K6-1-u6-X24"},{"t":"「가장 많이 팔린 일등」 — 어떤 경우에도 그렇다고 했다","mis":"K6-1-u6-X27"}],"explanation":["새지 않게 만든 기능은 있어요.","작은 글씨는 부풀린 게 아니에요.","있는 기능을 부풀렸어요 — 작은 글씨가 스스로 샐 수 있다고 밝혀요."],"asset":{"type":"passage","lines":["장면 ③ 「일등」이라고 적힌 커다란 금빛 딱지","　　「이보다 좋은 물통은 없습니다! 가장 많이 팔린 일등!」","장면 ④ 물통을 가방에 거꾸로 넣은 그림","　　「절대 새지 않는 안심 뚜껑!」","　　(아주 작은 글씨) ※ 뚜껑을 끝까지 돌려 닫지 않으면 샐 수 있음."],"title":"물통 광고 — 뒤 장면 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L07_basic#7','kor',6,1,'u6','L07','g6_1_kor_u6_L07_basic','lesson_basic','K6-1-u6-C27',2,'mc','auto','감추는 내용이 있는 문구는 어느 것인가요?',ARRAY['K6-1-u6-X05','K6-1-u6-X24']::text[],false,'{"seq":7,"concept":"K6-1-u6-C27","difficulty":2,"kind":"mc","stem":"감추는 내용이 있는 문구는 어느 것인가요?","options":[{"t":"가장 많이 팔린 일등!","correct":true},{"t":"두 겹 벽이 바깥 열을 막아 줍니다","mis":"K6-1-u6-X05"},{"t":"물을 담아 들고 다니는 물통","mis":"K6-1-u6-X05"},{"t":"※ 뚜껑을 끝까지 돌려 닫지 않으면 샐 수 있음","mis":"K6-1-u6-X24"}],"explanation":["있는 기능을 밝혔어요.","되묻고 싶은 게 남지 않아요.","언제 · 어디에서 · 무엇과 견주어 일등인지 밝히지 않았어요."],"asset":{"type":"passage","lines":["장면 ③ 「일등」이라고 적힌 커다란 금빛 딱지","　　「이보다 좋은 물통은 없습니다! 가장 많이 팔린 일등!」","장면 ④ 물통을 가방에 거꾸로 넣은 그림","　　「절대 새지 않는 안심 뚜껑!」","　　(아주 작은 글씨) ※ 뚜껑을 끝까지 돌려 닫지 않으면 샐 수 있음."],"title":"물통 광고 — 뒤 장면 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L07_basic#8','kor',6,1,'u6','L07','g6_1_kor_u6_L07_basic','lesson_basic','K6-1-u6-C28',2,'mc','auto','거짓된 표현과 과장된 표현을 가르는 자로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X24','K6-1-u6-X23','K6-1-u6-X25']::text[],false,'{"seq":8,"concept":"K6-1-u6-C28","difficulty":2,"kind":"mc","stem":"거짓된 표현과 과장된 표현을 가르는 자로 알맞은 것은 어느 것인가요?","options":[{"t":"그 기능이 실제로 있는가","correct":true},{"t":"글씨가 얼마나 큰가","mis":"K6-1-u6-X24"},{"t":"느낌표가 몇 개인가","mis":"K6-1-u6-X23"},{"t":"값이 얼마인가","mis":"K6-1-u6-X25"}],"explanation":["크기로 가르지 않아요.","느낌표 개수가 아니에요.","없으면 거짓, 부풀리면 과장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L07_basic#9','kor',6,1,'u6','L07','g6_1_kor_u6_L07_basic','lesson_basic','K6-1-u6-C30',2,'ox','auto','부풀리고 감추는 일은 광고에서만 일어나요.',ARRAY['K6-1-u6-X29']::text[],false,'{"seq":9,"concept":"K6-1-u6-C30","difficulty":2,"kind":"ox","stem":"부풀리고 감추는 일은 광고에서만 일어나요.","answer":"X","reason_options":[{"t":"설득하려는 글이면 주장하는 글이나 안내문에서도 일어날 수 있기 때문에","correct":true},{"t":"광고는 물건을 팔려는 글이라 광고만 그렇기 때문에","mis":"K6-1-u6-X29"}],"mis":"K6-1-u6-X29","explanation":["광고만의 일이 아니에요.","안내문도 따져 봐요.","어떤 글 앞에서도 세 물음을 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L07_basic#10','kor',6,1,'u6','L07','g6_1_kor_u6_L07_basic','lesson_basic','K6-1-u6-C29',3,'mc','auto','「이보다 좋은 물통은 없습니다!」를 바르게 판단한 것은 어느 것인가요?',ARRAY['K6-1-u6-X28','K6-1-u6-X25','K6-1-u6-X26']::text[],false,'{"seq":10,"concept":"K6-1-u6-C29","difficulty":3,"kind":"mc","stem":"「이보다 좋은 물통은 없습니다!」를 바르게 판단한 것은 어느 것인가요?","options":[{"t":"실제보다 부풀린 과장이면서, 어떤 점에서 좋은지 밝히지 않은 감춤이기도 하다","correct":true},{"t":"과장일 뿐 감춤과는 상관없다","mis":"K6-1-u6-X28"},{"t":"없는 기능을 말한 거짓일 뿐이다","mis":"K6-1-u6-X25"},{"t":"알맞은 표현이다","mis":"K6-1-u6-X26"}],"explanation":["한 기준에만 걸리지 않아요.","물통의 기능은 있어요.","두 기준에 함께 걸려요."],"asset":{"type":"passage","lines":["장면 ③ 「일등」이라고 적힌 커다란 금빛 딱지","　　「이보다 좋은 물통은 없습니다! 가장 많이 팔린 일등!」","장면 ④ 물통을 가방에 거꾸로 넣은 그림","　　「절대 새지 않는 안심 뚜껑!」","　　(아주 작은 글씨) ※ 뚜껑을 끝까지 돌려 닫지 않으면 샐 수 있음."],"title":"물통 광고 — 뒤 장면 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L07_challenge#1','kor',6,1,'u6','L07','g6_1_kor_u6_L07_challenge','lesson_challenge','K6-1-u6-C25',2,'sa','auto','없는 기능을 있다고 말한 표현을 무엇이라고 하는지 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-1-u6-C25","difficulty":2,"kind":"sa","stem":"없는 기능을 있다고 말한 표현을 무엇이라고 하는지 쓰세요.","answer":["거짓된표현","거짓된 표현"],"explanation":["과장과 헷갈리지 말아요.","그 기능이 실제로 없어요.","거짓된 표현이에요."],"mis":"K6-1-u6-X25"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L07_challenge#2','kor',6,1,'u6','L07','g6_1_kor_u6_L07_challenge','lesson_challenge','K6-1-u6-C26',2,'ox','auto','「여름 준비, 이것 하나면 끝!」은 과장된 표현이에요.',ARRAY['K6-1-u6-X25']::text[],false,'{"seq":2,"concept":"K6-1-u6-C26","difficulty":2,"kind":"ox","stem":"「여름 준비, 이것 하나면 끝!」은 과장된 표현이에요.","answer":"O","reason_options":[{"t":"여름 준비에는 모자나 옷도 있어 물통 하나로 끝나지 않는데 부풀렸기 때문에","correct":true},{"t":"물통에 없는 기능을 있다고 했기 때문에","mis":"K6-1-u6-X25"}],"mis":"K6-1-u6-X25","explanation":["부풀린 말이에요.","물통은 쓸모가 있으니 거짓은 아니에요.","하나로 다 된다고 하면 과장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L07_challenge#3','kor',6,1,'u6','L07','g6_1_kor_u6_L07_challenge','lesson_challenge','K6-1-u6-C27',3,'mc','auto','감추는 표현을 밝히는 표현으로 알맞게 고친 것은 어느 것인가요?',ARRAY['K6-1-u6-X26','K6-1-u6-X27']::text[],false,'{"seq":3,"concept":"K6-1-u6-C27","difficulty":3,"kind":"mc","stem":"감추는 표현을 밝히는 표현으로 알맞게 고친 것은 어느 것인가요?","options":[{"t":"「아이를 돕는 물통」 → 「물을 여섯 시간 동안 차게 지켜 주는 물통」","correct":true},{"t":"「아이를 돕는 물통」 → 「세상 모든 아이를 돕는 물통」","mis":"K6-1-u6-X26"},{"t":"「아이를 돕는 물통」 → 「아이를 아주아주 돕는 물통」","mis":"K6-1-u6-X26"},{"t":"「아이를 돕는 물통」 → 「아이를 돕는 바로 그 물통」","mis":"K6-1-u6-X27"}],"explanation":["더 부풀렸어요.","크기만 키웠어요.","무엇을 얼마나 하는지 밝혔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L07_challenge#4','kor',6,1,'u6','L07','g6_1_kor_u6_L07_challenge','lesson_challenge','K6-1-u6-C24',3,'mc','auto','물통 광고가 「※ 뚜껑을 끝까지 돌려 닫지 않으면 샐 수 있음」을 아주 작게 적은 것을 바르게 판단한 것은 어느 것인가요?',ARRAY['K6-1-u6-X15','K6-1-u6-X27','K6-1-u6-X24']::text[],false,'{"seq":4,"concept":"K6-1-u6-C24","difficulty":3,"kind":"mc","stem":"물통 광고가 「※ 뚜껑을 끝까지 돌려 닫지 않으면 샐 수 있음」을 아주 작게 적은 것을 바르게 판단한 것은 어느 것인가요?","options":[{"t":"꼭 알아야 할 조건을 눈에 들어오지 않게 적어, 큰 글씨 「절대 새지 않는」과 함께 보면 감추는 내용에 가깝다","correct":true},{"t":"작은 글씨는 읽지 않아도 된다","mis":"K6-1-u6-X15"},{"t":"조건을 적었으니 아무 문제가 없다","mis":"K6-1-u6-X27"},{"t":"작게 쓴 것은 실수일 뿐이다","mis":"K6-1-u6-X24"}],"explanation":["조건이 거기 있어요.","읽을 수 있는 크기여야 해요.","작게 한 것도 뜻이 있어요. (바로잡기: 새지 않게 만든 뚜껑도 끝까지 닫지 않으면 샐 수 있어요.)"],"asset":{"type":"passage","lines":["장면 ③ 「일등」이라고 적힌 커다란 금빛 딱지","　　「이보다 좋은 물통은 없습니다! 가장 많이 팔린 일등!」","장면 ④ 물통을 가방에 거꾸로 넣은 그림","　　「절대 새지 않는 안심 뚜껑!」","　　(아주 작은 글씨) ※ 뚜껑을 끝까지 돌려 닫지 않으면 샐 수 있음."],"title":"물통 광고 — 뒤 장면 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L07_challenge#5','kor',6,1,'u6','L07','g6_1_kor_u6_L07_challenge','lesson_challenge','K6-1-u6-C30',3,'mc','auto','부풀리지 않았지만 믿기 어려운 표현은 어느 것인가요?',ARRAY['K6-1-u6-X05','K6-1-u6-X26']::text[],false,'{"seq":5,"concept":"K6-1-u6-C30","difficulty":3,"kind":"mc","stem":"부풀리지 않았지만 믿기 어려운 표현은 어느 것인가요?","options":[{"t":"아주 오래전에 조사한 내용을 지금도 그렇다고 적은 안내문","correct":true},{"t":"어제 직접 세어 본 기록","mis":"K6-1-u6-X05"},{"t":"「절대 새지 않는」처럼 부풀린 말","mis":"K6-1-u6-X26"},{"t":"상자에 적힌 사용 안내","mis":"K6-1-u6-X05"}],"explanation":["확인할 수 있는 기록이에요.","부풀리지 않은 것을 찾아야 해요.","오래되어 지금과 맞지 않을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L07_challenge#6','kor',6,1,'u6','L07','g6_1_kor_u6_L07_challenge','lesson_challenge','K6-1-u6-C29',3,'mc','auto','한 표현이 두 기준에 함께 걸릴 수 있음을 알면 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X28','K6-1-u6-X21']::text[],false,'{"seq":6,"concept":"K6-1-u6-C29","difficulty":3,"kind":"mc","stem":"한 표현이 두 기준에 함께 걸릴 수 있음을 알면 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"기준 하나로 끝내지 않고 남은 기준으로도 다시 훑어 놓치는 곳이 줄어든다","correct":true},{"t":"걸리는 기준 하나만 찾으면 된다","mis":"K6-1-u6-X28"},{"t":"표현마다 기준을 하나씩만 붙인다","mis":"K6-1-u6-X28"},{"t":"두 기준에 걸리면 그 광고를 버린다","mis":"K6-1-u6-X21"}],"explanation":["하나 찾고 멈추면 놓쳐요.","기준은 서로를 밀어내지 않아요.","버리지 않고 짚어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L07_challenge#7','kor',6,1,'u6','L07','g6_1_kor_u6_L07_challenge','lesson_challenge','K6-1-u6-C28',3,'mc','auto','「두 겹 벽이 바깥 열을 막아 줍니다」는 알맞고 「뚜껑을 열어도 얼음이 녹지 않아요」는 거짓인 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X23','K6-1-u6-X24','K6-1-u6-X05']::text[],false,'{"seq":7,"concept":"K6-1-u6-C28","difficulty":3,"kind":"mc","stem":"「두 겹 벽이 바깥 열을 막아 줍니다」는 알맞고 「뚜껑을 열어도 얼음이 녹지 않아요」는 거짓인 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"앞은 실제로 있는 기능이고, 뒤는 뚜껑을 열면 바깥 공기가 들어와 막을 수 없는 일을 있다고 했기 때문이다","correct":true},{"t":"앞의 문장이 더 짧기 때문이다","mis":"K6-1-u6-X23"},{"t":"뒤의 문장에는 느낌표가 없기 때문이다","mis":"K6-1-u6-X24"},{"t":"둘 다 거짓이기 때문이다","mis":"K6-1-u6-X05"}],"explanation":["길이로 가르지 않아요.","느낌표와 관계없어요.","기능이 실제로 있는지로 갈라요 — 뚜껑을 열면 얼음은 녹아요."],"asset":{"type":"passage","lines":["장면 ① 물통을 든 아이가 환하게 웃는 큰 그림","　　「여름 준비, 이것 하나면 끝!」 「하루 종일 시원한 물통」","장면 ② 물통 안에 얼음이 가득한 그림","　　「얼음이 하루 종일 그대로! 뚜껑을 열어도 녹지 않아요.」","　　「두 겹 벽이 바깥 열을 막아 줍니다.」"],"title":"물통 광고 「하루 종일 시원한 물통」 — 앞 장면 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L07_challenge#8','kor',6,1,'u6','L07','g6_1_kor_u6_L07_challenge','lesson_challenge','K6-1-u6-C31',4,'mc','auto','둘레의 광고를 재어 공책에 적은 것 가운데 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X06','K6-1-u6-X17','K6-1-u6-X45']::text[],false,'{"seq":8,"concept":"K6-1-u6-C31","difficulty":4,"kind":"mc","stem":"둘레의 광고를 재어 공책에 적은 것 가운데 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「한 번만 발라도 하루 종일 촉촉」 — 과장 ×: 바르는 양과 날씨에 따라 다를 텐데 부풀렸다","correct":true},{"t":"「한 번만 발라도 하루 종일 촉촉」 — × : 그냥 별로","mis":"K6-1-u6-X06"},{"t":"「한 번만 발라도 하루 종일 촉촉」 — ○ : 광고에 적혀 있으니까","mis":"K6-1-u6-X17"},{"t":"「한 번만 발라도 하루 종일 촉촉」 — × : 만든 회사가 싫어서","mis":"K6-1-u6-X45"}],"explanation":["까닭이 없어요.","적혀 있다는 건 까닭이 아니에요.","판단과 까닭이 한 짝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L07_challenge#9','kor',6,1,'u6','L07','g6_1_kor_u6_L07_challenge','lesson_challenge','K6-1-u6-C27',4,'essay','teacher','물통 광고에서 감추는 내용을 하나 찾아 왜 감춤인지 쓰고, 감춘 것을 밝히는 문구로 고쳐 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u6-C27","difficulty":4,"kind":"essay","stem":"물통 광고에서 감추는 내용을 하나 찾아 왜 감춤인지 쓰고, 감춘 것을 밝히는 문구로 고쳐 쓰세요.","answer_guide":{"answer":"예: 「가장 많이 팔린 일등!」은 감추는 내용이다. 언제, 어디에서, 무엇과 견주어 일등인지 밝히지 않아 읽고 나서 「그런데 어디에서?」라는 물음이 남는다. 고쳐 쓰면 — 「지난 여름 우리 동네 문구점에서 물통 가운데 가장 많이 팔렸어요.」","scoring_points":["감추는 문구를 찾았는가","무엇을 감추었는지 까닭을 썼는가","감춘 것을 밝히도록 고쳐 썼는가"]},"explanation":["「그런데 어디에서?」가 남는 문구를 찾아요.","빠진 것을 말해요.","빠진 것을 채워 고쳐요."],"asset":{"type":"passage","lines":["장면 ③ 「일등」이라고 적힌 커다란 금빛 딱지","　　「이보다 좋은 물통은 없습니다! 가장 많이 팔린 일등!」","장면 ④ 물통을 가방에 거꾸로 넣은 그림","　　「절대 새지 않는 안심 뚜껑!」","　　(아주 작은 글씨) ※ 뚜껑을 끝까지 돌려 닫지 않으면 샐 수 있음."],"title":"물통 광고 — 뒤 장면 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L07_challenge#10','kor',6,1,'u6','L07','g6_1_kor_u6_L07_challenge','lesson_challenge','K6-1-u6-C30',4,'essay','teacher','「부풀리고 감추는 건 광고니까 그런 거야.」라고 말하는 친구에게, 광고가 아닌 글의 예와 「부풀리지 않았어도 믿기 어려운 경우」를 넣어 해 줄 말을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u6-C30","difficulty":4,"kind":"essay","stem":"「부풀리고 감추는 건 광고니까 그런 거야.」라고 말하는 친구에게, 광고가 아닌 글의 예와 「부풀리지 않았어도 믿기 어려운 경우」를 넣어 해 줄 말을 쓰세요.","answer_guide":{"answer":"예: 부풀리고 감추는 일은 광고만 하는 게 아니야. 주장하는 글에서 「이것만 하면 모든 문제가 사라진다」고 쓰거나, 안내문에서 꼭 알아야 할 조건을 작게 적는 것도 같아. 그리고 부풀리지 않았어도 아주 오래전에 조사한 내용을 지금도 그렇다고 쓰거나 두루뭉술하게 써서 오해하게 하면 믿기 어려워. 그러니 어떤 글이든 세 물음을 대어 봐야 해.","scoring_points":["광고가 아닌 글의 예를 들었는가","부풀리지 않아도 믿기 어려운 경우를 썼는가","어떤 글에나 기준을 댄다고 정리했는가"]},"explanation":["설득하려는 다른 글을 떠올려요.","오래된 · 흐린 정보를 떠올려요.","세 물음으로 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L09_basic#1','kor',6,1,'u6','L09','g6_1_kor_u6_L09_basic','lesson_basic','K6-1-u6-C32',1,'mc','auto','설명하는 글을 읽을 때 더 조심해야 하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X05','K6-1-u6-X08','K6-1-u6-X03']::text[],false,'{"seq":1,"concept":"K6-1-u6-C32","difficulty":1,"kind":"mc","stem":"설명하는 글을 읽을 때 더 조심해야 하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"알려 주려고 쓴 글이라 여겨 적힌 대로 외우기 쉽기 때문이다","correct":true},{"t":"설명하는 글은 언제나 거짓이기 때문이다","mis":"K6-1-u6-X05"},{"t":"설명하는 글은 짧기 때문이다","mis":"K6-1-u6-X08"},{"t":"설명하는 글에는 표현이 없기 때문이다","mis":"K6-1-u6-X03"}],"explanation":["늘 거짓인 건 아니에요.","길이와 관계없어요.","그대로 외우기 쉬워 조심해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L09_basic#2','kor',6,1,'u6','L09','g6_1_kor_u6_L09_basic','lesson_basic','K6-1-u6-C32',1,'mc','auto','「숨을 쉬는 그릇, 옹기」가 설명하는 것은 무엇인가요?',ARRAY['K6-1-u6-X04']::text[],false,'{"seq":2,"concept":"K6-1-u6-C32","difficulty":1,"kind":"mc","stem":"「숨을 쉬는 그릇, 옹기」가 설명하는 것은 무엇인가요?","options":[{"t":"옹기의 특징과 쓰임","correct":true},{"t":"김치를 담그는 차례","mis":"K6-1-u6-X04"},{"t":"옛집을 짓는 방법","mis":"K6-1-u6-X04"},{"t":"흙을 고르는 방법","mis":"K6-1-u6-X04"}],"explanation":["김치는 담는 음식으로 나올 뿐이에요.","옛집은 옹기를 둔 곳이에요.","제목과 문단 ①이 함께 가리켜요."],"asset":{"type":"passage","lines":["① 옹기는 흙을 빚어 높은 열에 구운 그릇입니다. 옛사람들은 김치와 간장, 된장처럼","오래 두고 먹는 음식을 옹기에 담았습니다.","② 흙을 구울 때 흙 속에 섞인 아주 작은 알갱이가 타면서 벽에 눈에 보이지 않는","작은 구멍이 남습니다. 이 구멍으로 공기가 아주 천천히 드나듭니다.","③ 김치나 장은 시간이 지나면서 맛이 드는 음식입니다. 이런 음식은 공기가 조금씩","드나드는 그릇에서 맛이 잘 듭니다."],"title":"「숨을 쉬는 그릇, 옹기」 — 앞부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L09_basic#3','kor',6,1,'u6','L09','g6_1_kor_u6_L09_basic','lesson_basic','K6-1-u6-C35',1,'ox','auto','과장된 표현은 거짓말이 아니니 그대로 믿어도 돼요.',ARRAY['K6-1-u6-X34']::text[],false,'{"seq":3,"concept":"K6-1-u6-C35","difficulty":1,"kind":"ox","stem":"과장된 표현은 거짓말이 아니니 그대로 믿어도 돼요.","answer":"X","reason_options":[{"t":"있는 것을 부풀려 읽는 사람을 지나치게 믿게 만들기 때문에","correct":true},{"t":"거짓만 아니면 알맞은 표현이기 때문에","mis":"K6-1-u6-X34"}],"mis":"K6-1-u6-X34","explanation":["거짓이 아니어도 걸러요.","더 알아채기 어려워요.","지나친 믿음이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L09_basic#4','kor',6,1,'u6','L09','g6_1_kor_u6_L09_basic','lesson_basic','K6-1-u6-C32',1,'match','auto','설명하는 글의 걸린 표현과 그것이 읽는 사람에게 남기는 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K6-1-u6-C32","difficulty":1,"kind":"match","stem":"설명하는 글의 걸린 표현과 그것이 읽는 사람에게 남기는 것을 알맞게 이으세요.","pairs":[{"l":"거짓된 표현","r":"잘못된 지식"},{"l":"과장된 표현","r":"지나친 믿음"},{"l":"감추는 내용","r":"한쪽만 아는 사람"}],"mis":"K6-1-u6-X31","explanation":["거짓은 잘못 알게 해요.","과장은 지나치게 믿게 해요.","감춤은 한쪽만 알게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L09_basic#5','kor',6,1,'u6','L09','g6_1_kor_u6_L09_basic','lesson_basic','K6-1-u6-C34',2,'mc','auto','옹기 글에서 거짓된 표현은 어느 것인가요?',ARRAY['K6-1-u6-X05','K6-1-u6-X25']::text[],false,'{"seq":5,"concept":"K6-1-u6-C34","difficulty":2,"kind":"mc","stem":"옹기 글에서 거짓된 표현은 어느 것인가요?","options":[{"t":"요즘 대부분의 가정에서도 김치를 옹기에만 담아 보관합니다","correct":true},{"t":"볕이 잘 들고 바람이 통하는 곳에 옹기를 나란히 두었습니다","mis":"K6-1-u6-X05"},{"t":"옹기를 보면 옛사람들이 살림의 이치를 담았음을 알 수 있습니다","mis":"K6-1-u6-X05"},{"t":"옹기는 어디에나 놓아도 좋습니다","mis":"K6-1-u6-X25"}],"explanation":["사실이에요.","글쓴이의 정리예요.","오늘날엔 김치를 냉장고나 밀폐 용기에 더 많이 담아요 — 바르게는 「오늘날에도 장을 담그는 집에서는 옹기를 씁니다」예요."],"asset":{"type":"passage","lines":["④ 옛집에는 볕이 잘 들고 바람이 통하는 곳에 옹기를 나란히 두었습니다.","옹기는 어디에나 놓아도 좋습니다.","⑤ 옹기에 담아 두면 음식이 절대 상하지 않습니다. 그래서 요즘 대부분의 가정에서도","김치를 옹기에만 담아 보관합니다.","⑥ 옹기를 보면 옛사람들이 그릇 하나에도 살림의 이치를 담았음을 알 수 있습니다."],"title":"「숨을 쉬는 그릇, 옹기」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L09_basic#6','kor',6,1,'u6','L09','g6_1_kor_u6_L09_basic','lesson_basic','K6-1-u6-C35',2,'mc','auto','옹기 글에서 과장된 표현은 어느 것인가요?',ARRAY['K6-1-u6-X05','K6-1-u6-X28']::text[],false,'{"seq":6,"concept":"K6-1-u6-C35","difficulty":2,"kind":"mc","stem":"옹기 글에서 과장된 표현은 어느 것인가요?","options":[{"t":"옹기에 담아 두면 음식이 절대 상하지 않습니다","correct":true},{"t":"옛집에는 옹기를 나란히 두었습니다","mis":"K6-1-u6-X05"},{"t":"옹기는 어디에나 놓아도 좋습니다","mis":"K6-1-u6-X28"},{"t":"옹기를 보면 살림의 이치를 알 수 있습니다","mis":"K6-1-u6-X05"}],"explanation":["사실이에요.","이건 감추는 내용이에요.","옹기에 담아도 오래 두면 상해요 — 바르게는 「김치나 장의 맛이 천천히 듭니다」예요."],"asset":{"type":"passage","lines":["④ 옛집에는 볕이 잘 들고 바람이 통하는 곳에 옹기를 나란히 두었습니다.","옹기는 어디에나 놓아도 좋습니다.","⑤ 옹기에 담아 두면 음식이 절대 상하지 않습니다. 그래서 요즘 대부분의 가정에서도","김치를 옹기에만 담아 보관합니다.","⑥ 옹기를 보면 옛사람들이 그릇 하나에도 살림의 이치를 담았음을 알 수 있습니다."],"title":"「숨을 쉬는 그릇, 옹기」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L09_basic#7','kor',6,1,'u6','L09','g6_1_kor_u6_L09_basic','lesson_basic','K6-1-u6-C36',2,'mc','auto','「옹기는 어디에나 놓아도 좋습니다」가 감춘 것은 어느 것인가요?',ARRAY['K6-1-u6-X27']::text[],false,'{"seq":7,"concept":"K6-1-u6-C36","difficulty":2,"kind":"mc","stem":"「옹기는 어디에나 놓아도 좋습니다」가 감춘 것은 어느 것인가요?","options":[{"t":"옹기는 무겁고 잘 깨진다는 점","correct":true},{"t":"옹기는 흙으로 만든다는 점","mis":"K6-1-u6-X27"},{"t":"옹기에 김치를 담았다는 점","mis":"K6-1-u6-X27"},{"t":"감춘 것이 없다","mis":"K6-1-u6-X27"}],"explanation":["앞 문단에서 밝혔어요.","그것도 밝혔어요.","알아야 할 것을 빼놓았어요 — 바르게는 「무겁고 잘 깨지므로 옮기지 않아도 되는 곳에 두어야 합니다」예요."],"asset":{"type":"passage","lines":["④ 옛집에는 볕이 잘 들고 바람이 통하는 곳에 옹기를 나란히 두었습니다.","옹기는 어디에나 놓아도 좋습니다.","⑤ 옹기에 담아 두면 음식이 절대 상하지 않습니다. 그래서 요즘 대부분의 가정에서도","김치를 옹기에만 담아 보관합니다.","⑥ 옹기를 보면 옛사람들이 그릇 하나에도 살림의 이치를 담았음을 알 수 있습니다."],"title":"「숨을 쉬는 그릇, 옹기」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L09_basic#8','kor',6,1,'u6','L09','g6_1_kor_u6_L09_basic','lesson_basic','K6-1-u6-C33',2,'mc','auto','설명하는 글에 세 기준을 대는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X32']::text[],false,'{"seq":8,"concept":"K6-1-u6-C33","difficulty":2,"kind":"mc","stem":"설명하는 글에 세 기준을 대는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"거짓을 들고 글 전체를 훑고, 다시 과장을, 마지막으로 감춤을 들고 처음부터 훑는다","correct":true},{"t":"한 문단에서 세 기준을 한꺼번에 잰다","mis":"K6-1-u6-X32"},{"t":"첫 문단만 꼼꼼히 잰다","mis":"K6-1-u6-X32"},{"t":"마음에 드는 문단만 잰다","mis":"K6-1-u6-X32"}],"explanation":["한꺼번에 재면 놓쳐요.","글 전체를 훑어요.","기준 하나로 전체를 훑어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L09_basic#9','kor',6,1,'u6','L09','g6_1_kor_u6_L09_basic','lesson_basic','K6-1-u6-C38',2,'mc','auto','옹기 글을 읽고 다른 관점에서 세울 물음으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X36','K6-1-u6-X31']::text[],false,'{"seq":9,"concept":"K6-1-u6-C38","difficulty":2,"kind":"mc","stem":"옹기 글을 읽고 다른 관점에서 세울 물음으로 알맞은 것은 어느 것인가요?","options":[{"t":"「옹기를 쓰면서 불편한 점은 없었을까?」","correct":true},{"t":"「옹기는 왜 이렇게 좋을까?」","mis":"K6-1-u6-X36"},{"t":"「이 글을 다 외웠을까?」","mis":"K6-1-u6-X31"},{"t":"「다른 글은 읽을 필요가 없겠지?」","mis":"K6-1-u6-X36"}],"explanation":["같은 쪽에서 본 물음이에요.","외우기가 목적이 아니에요.","다른 쪽에서 물었어요 — 관련 글을 더 찾아 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L09_basic#10','kor',6,1,'u6','L09','g6_1_kor_u6_L09_basic','lesson_basic','K6-1-u6-C37',3,'mc','auto','걸린 문장과 고쳐 쓴 문장의 짝이 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X35','K6-1-u6-X33']::text[],false,'{"seq":10,"concept":"K6-1-u6-C37","difficulty":3,"kind":"mc","stem":"걸린 문장과 고쳐 쓴 문장의 짝이 알맞은 것은 어느 것인가요?","options":[{"t":"「절대 상하지 않는다」 → 「김치나 장의 맛이 천천히 든다」","correct":true},{"t":"「어디에나 놓아도 좋다」 → 「어디에나 놓아도 정말 좋다」","mis":"K6-1-u6-X35"},{"t":"「대부분 옹기에만 담는다」 → 「모두 옹기에만 담는다」","mis":"K6-1-u6-X33"},{"t":"「절대 상하지 않는다」 → 「옹기는 그릇이다」","mis":"K6-1-u6-X35"}],"explanation":["감춘 것을 밝히지 않았어요.","더 넓게 말했어요.","부풀린 것을 덜어 냈어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L09_challenge#1','kor',6,1,'u6','L09','g6_1_kor_u6_L09_challenge','lesson_challenge','K6-1-u6-C34',2,'mc','auto','설명하는 글에서 나오면 한 번 멈추어야 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X33']::text[],false,'{"seq":1,"concept":"K6-1-u6-C34","difficulty":2,"kind":"mc","stem":"설명하는 글에서 나오면 한 번 멈추어야 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"대부분 · 모두 · 언제나","correct":true},{"t":"그리고 · 그래서","mis":"K6-1-u6-X33"},{"t":"옛날 · 요즘","mis":"K6-1-u6-X33"},{"t":"크다 · 작다","mis":"K6-1-u6-X33"}],"explanation":["이어 주는 말이에요.","때를 나타낼 뿐이에요.","넓게 말하는 말에 멈춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L09_challenge#2','kor',6,1,'u6','L09','g6_1_kor_u6_L09_challenge','lesson_challenge','K6-1-u6-C39',2,'ox','auto','까닭이 타당하면 나와 다른 판단도 받아들일 수 있어요.',ARRAY['K6-1-u6-X37']::text[],false,'{"seq":2,"concept":"K6-1-u6-C39","difficulty":2,"kind":"ox","stem":"까닭이 타당하면 나와 다른 판단도 받아들일 수 있어요.","answer":"O","reason_options":[{"t":"까닭이 붙은 판단은 따져 볼 수 있고, 판단은 하나로 정해진 답을 맞히는 일이 아니기 때문에","correct":true},{"t":"판단은 언제나 하나로 정해져 있기 때문에","mis":"K6-1-u6-X37"}],"mis":"K6-1-u6-X37","explanation":["까닭을 들어 봐요.","따져 보고 받아들여요.","다른 판단도 열려 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L09_challenge#3','kor',6,1,'u6','L09','g6_1_kor_u6_L09_challenge','lesson_challenge','K6-1-u6-C36',3,'mc','auto','감추는 내용을 찾는 신호로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X25','K6-1-u6-X24','K6-1-u6-X23']::text[],false,'{"seq":3,"concept":"K6-1-u6-C36","difficulty":3,"kind":"mc","stem":"감추는 내용을 찾는 신호로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"읽고 나서 되묻고 싶은 것이 남는다","correct":true},{"t":"문장에 사실이 아닌 말이 있다","mis":"K6-1-u6-X25"},{"t":"느낌표가 많다","mis":"K6-1-u6-X24"},{"t":"문장이 길다","mis":"K6-1-u6-X23"}],"explanation":["그건 거짓의 신호예요.","느낌표 수와 관계없어요.","되물을 게 남으면 따라가 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L09_challenge#4','kor',6,1,'u6','L09','g6_1_kor_u6_L09_challenge','lesson_challenge','K6-1-u6-C33',3,'mc','auto','한 문단에서 세 기준을 한꺼번에 재지 않는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X32','K6-1-u6-X46']::text[],false,'{"seq":4,"concept":"K6-1-u6-C33","difficulty":3,"kind":"mc","stem":"한 문단에서 세 기준을 한꺼번에 재지 않는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"한꺼번에 재면 놓치기 쉽고, 글 전체가 고르게 알맞거나 고르게 어긋나지는 않기 때문이다","correct":true},{"t":"세 기준은 한 문단에만 쓰기 때문이다","mis":"K6-1-u6-X32"},{"t":"기준은 하나만 쓰면 되기 때문이다","mis":"K6-1-u6-X46"},{"t":"문단은 따질 필요가 없기 때문이다","mis":"K6-1-u6-X32"}],"explanation":["글 전체에 대요.","세 기준을 다 대요.","기준 하나로 전체를 훑어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L09_challenge#5','kor',6,1,'u6','L09','g6_1_kor_u6_L09_challenge','lesson_challenge','K6-1-u6-C39',3,'mc','auto','「이 문장은 과장됐어」에 까닭을 붙여 말한 것은 어느 것인가요?',ARRAY['K6-1-u6-X06','K6-1-u6-X37','K6-1-u6-X45']::text[],false,'{"seq":5,"concept":"K6-1-u6-C39","difficulty":3,"kind":"mc","stem":"「이 문장은 과장됐어」에 까닭을 붙여 말한 것은 어느 것인가요?","options":[{"t":"「옹기에 담아도 오래 두면 상하니까 과장됐어.」","correct":true},{"t":"「그냥 과장된 느낌이야.」","mis":"K6-1-u6-X06"},{"t":"「내 판단과 다르면 다 틀린 거야.」","mis":"K6-1-u6-X37"},{"t":"「글쓴이가 별로라서 과장이야.」","mis":"K6-1-u6-X45"}],"explanation":["느낌뿐이에요.","까닭을 들어 봐야 해요.","사람이 아니라 문장을 판단해요."],"asset":{"type":"passage","lines":["④ 옛집에는 볕이 잘 들고 바람이 통하는 곳에 옹기를 나란히 두었습니다.","옹기는 어디에나 놓아도 좋습니다.","⑤ 옹기에 담아 두면 음식이 절대 상하지 않습니다. 그래서 요즘 대부분의 가정에서도","김치를 옹기에만 담아 보관합니다.","⑥ 옹기를 보면 옛사람들이 그릇 하나에도 살림의 이치를 담았음을 알 수 있습니다."],"title":"「숨을 쉬는 그릇, 옹기」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L09_challenge#6','kor',6,1,'u6','L09','g6_1_kor_u6_L09_challenge','lesson_challenge','K6-1-u6-C38',3,'mc','auto','다른 관점의 글을 더 찾아 읽은 뒤 할 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X21','K6-1-u6-X36','K6-1-u6-X01']::text[],false,'{"seq":6,"concept":"K6-1-u6-C38","difficulty":3,"kind":"mc","stem":"다른 관점의 글을 더 찾아 읽은 뒤 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"처음 글에 없던 사실을 보태 적고, 판단을 다시 해 본다","correct":true},{"t":"처음 글이 틀렸다며 버린다","mis":"K6-1-u6-X21"},{"t":"두 글 가운데 마음에 드는 쪽만 믿는다","mis":"K6-1-u6-X36"},{"t":"새로 읽은 글은 따지지 않고 믿는다","mis":"K6-1-u6-X01"}],"explanation":["버리지 않고 보태요.","두 쪽을 함께 봐요.","새 글도 따져 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L09_challenge#7','kor',6,1,'u6','L09','g6_1_kor_u6_L09_challenge','lesson_challenge','K6-1-u6-C32',3,'mc','auto','「요즘 대부분의 가정에서도 김치를 옹기에만 담아 보관합니다」를 그대로 외운 학생에게 생길 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X25','K6-1-u6-X31']::text[],false,'{"seq":7,"concept":"K6-1-u6-C32","difficulty":3,"kind":"mc","stem":"「요즘 대부분의 가정에서도 김치를 옹기에만 담아 보관합니다」를 그대로 외운 학생에게 생길 일로 알맞은 것은 어느 것인가요?","options":[{"t":"오늘날 김치를 보관하는 방법에 대해 잘못된 지식을 갖게 된다","correct":true},{"t":"한쪽만 아는 사람이 된다","mis":"K6-1-u6-X25"},{"t":"아무 일도 생기지 않는다","mis":"K6-1-u6-X31"},{"t":"옹기를 더 정확히 알게 된다","mis":"K6-1-u6-X31"}],"explanation":["그건 감추는 내용이 남기는 거예요.","외운 것이 지식이 돼요.","거짓은 잘못된 지식이 돼요 — 오늘날엔 냉장고나 밀폐 용기를 더 많이 써요."],"asset":{"type":"passage","lines":["④ 옛집에는 볕이 잘 들고 바람이 통하는 곳에 옹기를 나란히 두었습니다.","옹기는 어디에나 놓아도 좋습니다.","⑤ 옹기에 담아 두면 음식이 절대 상하지 않습니다. 그래서 요즘 대부분의 가정에서도","김치를 옹기에만 담아 보관합니다.","⑥ 옹기를 보면 옛사람들이 그릇 하나에도 살림의 이치를 담았음을 알 수 있습니다."],"title":"「숨을 쉬는 그릇, 옹기」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L09_challenge#8','kor',6,1,'u6','L09','g6_1_kor_u6_L09_challenge','lesson_challenge','K6-1-u6-C37',4,'mc','auto','「옹기는 어디에나 놓아도 좋습니다」를 가장 알맞게 고친 것은 어느 것인가요?',ARRAY['K6-1-u6-X35','K6-1-u6-X26']::text[],false,'{"seq":8,"concept":"K6-1-u6-C37","difficulty":4,"kind":"mc","stem":"「옹기는 어디에나 놓아도 좋습니다」를 가장 알맞게 고친 것은 어느 것인가요?","options":[{"t":"옹기는 무겁고 잘 깨지므로 옮기지 않아도 되는 곳에 두어야 합니다","correct":true},{"t":"옹기는 어디에나 놓아도 아주 좋습니다","mis":"K6-1-u6-X35"},{"t":"옹기는 절대 깨지지 않으니 어디에나 둡니다","mis":"K6-1-u6-X26"},{"t":"옹기는 어디에도 두지 맙시다","mis":"K6-1-u6-X35"}],"explanation":["감춘 것을 밝히지 않았어요.","거꾸로 부풀렸어요.","알아야 할 것을 밝혔어요."],"asset":{"type":"passage","lines":["④ 옛집에는 볕이 잘 들고 바람이 통하는 곳에 옹기를 나란히 두었습니다.","옹기는 어디에나 놓아도 좋습니다.","⑤ 옹기에 담아 두면 음식이 절대 상하지 않습니다. 그래서 요즘 대부분의 가정에서도","김치를 옹기에만 담아 보관합니다.","⑥ 옹기를 보면 옛사람들이 그릇 하나에도 살림의 이치를 담았음을 알 수 있습니다."],"title":"「숨을 쉬는 그릇, 옹기」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L09_challenge#9','kor',6,1,'u6','L09','g6_1_kor_u6_L09_challenge','lesson_challenge','K6-1-u6-C38',4,'essay','teacher','옹기 글은 옹기의 좋은 점만 드러내요. 다른 관점의 물음을 두 가지 쓰고, 그 답을 어디에서 찾을지와 한 편만 읽고 판단하면 안 되는 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u6-C38","difficulty":4,"kind":"essay","stem":"옹기 글은 옹기의 좋은 점만 드러내요. 다른 관점의 물음을 두 가지 쓰고, 그 답을 어디에서 찾을지와 한 편만 읽고 판단하면 안 되는 까닭을 쓰세요.","answer_guide":{"answer":"예: 물음 — 「옹기를 쓰면서 불편한 점은 없었을까?」, 「왜 오늘날에는 옹기를 덜 쓸까?」 학교 도서관의 책이나 백과사전에서 옹기와 관련 있는 글을 한 편 더 찾아 읽겠다. 한 편의 글은 한쪽 이야기만 담을 수 있어서, 그것만 읽고 판단하면 옹기를 한쪽만 아는 사람이 되기 때문이다.","scoring_points":["다른 관점의 물음을 두 가지 썼는가","찾아 읽을 곳을 썼는가","한 편만 읽으면 안 되는 까닭을 썼는가"]},"explanation":["다른 쪽에서 물어요.","찾을 곳을 정해요.","한쪽만 알게 되는 위험을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L09_challenge#10','kor',6,1,'u6','L09','g6_1_kor_u6_L09_challenge','lesson_challenge','K6-1-u6-C37',4,'essay','teacher','옹기 글의 걸린 문장 셋 가운데 둘을 골라, 어느 기준에 걸리는지 · 그 까닭 · 고쳐 쓴 문장을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u6-C37","difficulty":4,"kind":"essay","stem":"옹기 글의 걸린 문장 셋 가운데 둘을 골라, 어느 기준에 걸리는지 · 그 까닭 · 고쳐 쓴 문장을 쓰세요.","answer_guide":{"answer":"예: 「옹기에 담아 두면 음식이 절대 상하지 않습니다」는 과장된 표현이다. 옹기에 담아도 오래 두면 상하기 때문이다. 고쳐 쓰면 「옹기에 담아 두면 김치나 장의 맛이 천천히 듭니다.」 「옹기는 어디에나 놓아도 좋습니다」는 감추는 내용이 있다. 무겁고 잘 깨진다는 점을 밝히지 않았다. 고쳐 쓰면 「옹기는 무겁고 잘 깨지므로 옮기지 않아도 되는 곳에 두어야 합니다.」","scoring_points":["걸리는 기준을 바르게 썼는가","까닭을 썼는가","기준에 맞게 고쳐 썼는가"]},"explanation":["기준을 먼저 정해요.","까닭을 대요.","덜어 내거나 더 밝혀요."],"asset":{"type":"passage","lines":["④ 옛집에는 볕이 잘 들고 바람이 통하는 곳에 옹기를 나란히 두었습니다.","옹기는 어디에나 놓아도 좋습니다.","⑤ 옹기에 담아 두면 음식이 절대 상하지 않습니다. 그래서 요즘 대부분의 가정에서도","김치를 옹기에만 담아 보관합니다.","⑥ 옹기를 보면 옛사람들이 그릇 하나에도 살림의 이치를 담았음을 알 수 있습니다."],"title":"「숨을 쉬는 그릇, 옹기」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L12_basic#1','kor',6,1,'u6','L12','g6_1_kor_u6_L12_basic','lesson_basic','K6-1-u6-C41',1,'mc','auto','공익 광고의 주제로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X39']::text[],false,'{"seq":1,"concept":"K6-1-u6-C41","difficulty":1,"kind":"mc","stem":"공익 광고의 주제로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"빌린 물건은 빌린 그대로 돌려주자","correct":true},{"t":"망가뜨릴까 걱정되니 아무것도 빌려주지 말자","mis":"K6-1-u6-X39"},{"t":"빌려 간 사람이 알아서 하게 두자","mis":"K6-1-u6-X39"},{"t":"내 물건이 얼마나 좋은지 자랑하자","mis":"K6-1-u6-X39"}],"explanation":["다른 문제를 만들어요.","고쳐지지 않아요.","여럿에게 도움이 되고 고치면 나아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L12_basic#2','kor',6,1,'u6','L12','g6_1_kor_u6_L12_basic','lesson_basic','K6-1-u6-C48',1,'match','auto','문장의 빈칸에 알맞은 낱말을 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K6-1-u6-C48","difficulty":1,"kind":"match","stem":"문장의 빈칸에 알맞은 낱말을 이으세요.","pairs":[{"l":"고무줄을 길게 (　)","r":"늘이다"},{"l":"쉬는 시간을 조금 더 (　)","r":"늘리다"},{"l":"과녁 한가운데를 (　)","r":"맞히다"}],"mis":"K6-1-u6-X47","explanation":["길게 하면 늘이다예요.","많게 하면 늘리다예요.","겨냥한 곳에 닿게 하면 맞히다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L12_basic#3','kor',6,1,'u6','L12','g6_1_kor_u6_L12_basic','lesson_basic','K6-1-u6-C49',1,'mc','auto','바르게 쓴 문장은 어느 것인가요?',ARRAY['K6-1-u6-X48']::text[],false,'{"seq":3,"concept":"K6-1-u6-C49","difficulty":1,"kind":"mc","stem":"바르게 쓴 문장은 어느 것인가요?","options":[{"t":"그렇게 하면 안 돼요.","correct":true},{"t":"감기가 다 낳았습니다.","mis":"K6-1-u6-X48"},{"t":"몇일이나 걸릴까요?","mis":"K6-1-u6-X48"},{"t":"오랫만에 사촌을 만났습니다.","mis":"K6-1-u6-X48"}],"explanation":["병이 없어지면 「나았다」예요.","「며칠」이 바른 말이에요.","「되어요」가 줄면 「돼요」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L12_basic#4','kor',6,1,'u6','L12','g6_1_kor_u6_L12_basic','lesson_basic','K6-1-u6-C40',1,'mc','auto','만드는 사람이 되어 광고를 만들 때 지킬 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X38','K6-1-u6-X42']::text[],false,'{"seq":4,"concept":"K6-1-u6-C40","difficulty":1,"kind":"mc","stem":"만드는 사람이 되어 광고를 만들 때 지킬 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"읽을 때 걸렸던 것들이 만들 때 하지 말아야 할 것이 된다","correct":true},{"t":"남의 글에서 찾은 흠도 내 글에서는 괜찮다","mis":"K6-1-u6-X38"},{"t":"만들 때는 눈에 띄기만 하면 된다","mis":"K6-1-u6-X42"},{"t":"만들 때는 배운 기준을 잊어도 된다","mis":"K6-1-u6-X38"}],"explanation":["내 글에서도 흠이에요.","믿을 수 있어야 해요.","자를 뒤집어 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L12_basic#5','kor',6,1,'u6','L12','g6_1_kor_u6_L12_basic','lesson_basic','K6-1-u6-C42',2,'mc','auto','첫 번째 초안에서 고치지 않아도 되는 문구는 어느 것인가요?',ARRAY['K6-1-u6-X26']::text[],false,'{"seq":5,"concept":"K6-1-u6-C42","difficulty":2,"kind":"mc","stem":"첫 번째 초안에서 고치지 않아도 되는 문구는 어느 것인가요?","options":[{"t":"ㄹ. 빌린 그대로 — 그것이 다음에도 빌릴 수 있는 길","correct":true},{"t":"ㄱ. 빌려주면 백 퍼센트 망가집니다!","mis":"K6-1-u6-X26"},{"t":"ㄴ. 이 광고 하나면 우리 반 문제가 모두 사라집니다.","mis":"K6-1-u6-X26"},{"t":"ㄷ. 빌린 물건, 절대 그냥 돌려주지 마세요.","mis":"K6-1-u6-X26"}],"explanation":["늘 망가지지는 않아요 — 부풀렸어요.","광고 하나로 다 사라지지 않아요.","부풀리지 않고 뜻이 분명해요 — ㄱ~ㄷ은 부풀린 말이라 고쳐 써요."],"asset":{"type":"passage","lines":["장면 — 반으로 갈라진 지우개 옆에 빈 필통이 열려 있는 그림","ㄱ. 빌려주면 백 퍼센트 망가집니다!","ㄴ. 이 광고 하나면 우리 반 문제가 모두 사라집니다.","ㄷ. 빌린 물건, 절대 그냥 돌려주지 마세요.","ㄹ. 빌린 그대로 — 그것이 다음에도 빌릴 수 있는 길"],"title":"공익 광고 첫 번째 초안 「빌린 물건은 빌린 그대로」 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L12_basic#6','kor',6,1,'u6','L12','g6_1_kor_u6_L12_basic','lesson_basic','K6-1-u6-C42',2,'match','auto','부풀린 문구와 알맞게 고친 문구를 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-1-u6-C42","difficulty":2,"kind":"match","stem":"부풀린 문구와 알맞게 고친 문구를 이으세요.","pairs":[{"l":"백 퍼센트 망가집니다","r":"빌려준 지우개가 반으로 돌아왔습니다"},{"l":"문제가 모두 사라집니다","r":"한 사람이 지키면 한 사람이 웃습니다"},{"l":"절대 그냥 돌려주지 마세요","r":"돌려줄 때 한 번만 살펴 주세요"}],"mis":"K6-1-u6-X35","explanation":["겪은 일로 바꿨어요.","있는 만큼 말했어요.","뜻은 두고 크기만 줄였어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L12_basic#7','kor',6,1,'u6','L12','g6_1_kor_u6_L12_basic','lesson_basic','K6-1-u6-C43',2,'ox','auto','광고는 틀린 말만 없으면 눈에 띄지 않아도 돼요.',ARRAY['K6-1-u6-X41']::text[],false,'{"seq":7,"concept":"K6-1-u6-C43","difficulty":2,"kind":"ox","stem":"광고는 틀린 말만 없으면 눈에 띄지 않아도 돼요.","answer":"X","reason_options":[{"t":"짧은 순간에 인상을 남겨야 하는 글이라 아무도 보지 않으면 뜻을 전하지 못하기 때문에","correct":true},{"t":"광고는 적절성만 재면 되기 때문에","mis":"K6-1-u6-X41"}],"mis":"K6-1-u6-X41","explanation":["눈에 띄어야 해요.","적절성만 재지는 않아요.","믿을 수 있으면서 눈에 띄게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L12_basic#8','kor',6,1,'u6','L12','g6_1_kor_u6_L12_basic','lesson_basic','K6-1-u6-C44',2,'mc','auto','광고의 표현 요소를 알맞게 고른 것은 어느 것인가요?',ARRAY['K6-1-u6-X43']::text[],false,'{"seq":8,"concept":"K6-1-u6-C44","difficulty":2,"kind":"mc","stem":"광고의 표현 요소를 알맞게 고른 것은 어느 것인가요?","options":[{"t":"가장 하고 싶은 한 줄만 크게 하고, 꼭 알릴 조건은 읽을 수 있는 크기로 적는다","correct":true},{"t":"모든 줄을 다 크게 한다","mis":"K6-1-u6-X43"},{"t":"온통 진한 색으로 칠한다","mis":"K6-1-u6-X43"},{"t":"조건은 아주 작게 적는다","mis":"K6-1-u6-X43"}],"explanation":["다 크면 아무것도 크지 않아요.","온통 진하면 강조가 사라져요.","조건은 읽을 수 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L12_basic#9','kor',6,1,'u6','L12','g6_1_kor_u6_L12_basic','lesson_basic','K6-1-u6-C46',2,'mc','auto','친구의 광고를 판단하는 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X06','K6-1-u6-X45']::text[],false,'{"seq":9,"concept":"K6-1-u6-C46","difficulty":2,"kind":"mc","stem":"친구의 광고를 판단하는 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「〈모두 사라집니다〉가 부풀려졌어. 실제로는 늘 그렇지는 않으니까. 그림은 주제를 잘 보여 줘.」","correct":true},{"t":"「이건 과장이야.」","mis":"K6-1-u6-X06"},{"t":"「너는 원래 부풀리기를 잘하잖아.」","mis":"K6-1-u6-X45"},{"t":"「별로인 것 같아.」","mis":"K6-1-u6-X06"}],"explanation":["까닭이 없어요.","사람이 아니라 문구를 봐요.","까닭과 잘한 점이 함께 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L12_basic#10','kor',6,1,'u6','L12','g6_1_kor_u6_L12_basic','lesson_basic','K6-1-u6-C47',3,'mc','auto','「그늘막을 더 세웁시다」에서 표현이 알맞지 않은 문장과 걸리는 기준을 바르게 짝지은 것은 어느 것인가요?',ARRAY['K6-1-u6-X03','K6-1-u6-X05','K6-1-u6-X26']::text[],false,'{"seq":10,"concept":"K6-1-u6-C47","difficulty":3,"kind":"mc","stem":"「그늘막을 더 세웁시다」에서 표현이 알맞지 않은 문장과 걸리는 기준을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"「더위가 모두 사라집니다」 — 과장 / 「절대 덥지 않습니다」 — 거짓","correct":true},{"t":"「이야기를 나눌 수 있어 즐겁습니다」 — 과장","mis":"K6-1-u6-X03"},{"t":"「세우는 데 오래 걸리지 않습니다」 — 거짓","mis":"K6-1-u6-X05"},{"t":"「절대 덥지 않습니다」 — 알맞은 표현","mis":"K6-1-u6-X26"}],"explanation":["그건 내용(어긋난 이유)에서 걸려요.","걸리지 않는 문장이에요.","그늘막 아래도 더울 수 있어요 — 바르게는 「볕을 가려 조금 덜 덥습니다」예요."],"asset":{"type":"passage","lines":["④ 셋째, 그늘막 아래에서는 친구들과 이야기를 나눌 수 있어 즐겁습니다.","⑤ 그늘막 하나면 여름 더위가 모두 사라집니다. 그늘막 아래에서는 절대 덥지 않습니다.","⑥ 그늘막은 세우는 데 오래 걸리지 않습니다.","여름이 오기 전에 건널목 앞에 그늘막을 더 세웁시다."],"title":"「그늘막을 더 세웁시다」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L12_challenge#1','kor',6,1,'u6','L12','g6_1_kor_u6_L12_challenge','lesson_challenge','K6-1-u6-C45',2,'mc','auto','광고를 발표할 때 밝힐 것으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K6-1-u6-X44','K6-1-u6-X42']::text[],false,'{"seq":1,"concept":"K6-1-u6-C45","difficulty":2,"kind":"mc","stem":"광고를 발표할 때 밝힐 것으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"친구 광고보다 내 광고가 낫다는 말","correct":true},{"t":"어떤 문제를 보고 이 주제를 골랐는지","mis":"K6-1-u6-X44"},{"t":"어떤 표현 요소로 무엇을 강조했는지","mis":"K6-1-u6-X44"},{"t":"일부러 세게 쓴 곳과 그 까닭","mis":"K6-1-u6-X42"}],"explanation":["밝혀야 할 거예요.","이것도 밝혀요.","발표는 견주어 이기는 일이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L12_challenge#2','kor',6,1,'u6','L12','g6_1_kor_u6_L12_challenge','lesson_challenge','K6-1-u6-C48',2,'mc','auto','「목표를 (　) 끝까지 노력했다.」의 빈칸에 알맞은 낱말은 어느 것인가요?',ARRAY['K6-1-u6-X47']::text[],false,'{"seq":2,"concept":"K6-1-u6-C48","difficulty":2,"kind":"mc","stem":"「목표를 (　) 끝까지 노력했다.」의 빈칸에 알맞은 낱말은 어느 것인가요?","options":[{"t":"좇아","correct":true},{"t":"쫓아","mis":"K6-1-u6-X47"},{"t":"맞혀","mis":"K6-1-u6-X47"},{"t":"늘여","mis":"K6-1-u6-X47"}],"explanation":["몰아내거나 급히 따라가는 뜻이에요.","답을 대는 뜻이에요.","목표를 따르는 것은 「좇다」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L12_challenge#3','kor',6,1,'u6','L12','g6_1_kor_u6_L12_challenge','lesson_challenge','K6-1-u6-C42',3,'mc','auto','부풀린 말을 덜어 낸 광고가 오히려 오래 남는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X40','K6-1-u6-X41']::text[],false,'{"seq":3,"concept":"K6-1-u6-C42","difficulty":3,"kind":"mc","stem":"부풀린 말을 덜어 낸 광고가 오히려 오래 남는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"보는 사람이 겪은 일에 가까워 믿고 받아들이기 쉽기 때문이다","correct":true},{"t":"덜어 내면 힘이 약해지기 때문이다","mis":"K6-1-u6-X40"},{"t":"글이 짧아져 아무도 읽지 않기 때문이다","mis":"K6-1-u6-X40"},{"t":"눈에 띄지 않아도 되기 때문이다","mis":"K6-1-u6-X41"}],"explanation":["힘은 그대로예요.","짧아도 남아요.","사실에 가까운 말이 오래 남아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L12_challenge#4','kor',6,1,'u6','L12','g6_1_kor_u6_L12_challenge','lesson_challenge','K6-1-u6-C43',3,'mc','auto','눈에 띄게 하려고 일부러 세게 쓴 곳이 있을 때 할 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X42','K6-1-u6-X41']::text[],false,'{"seq":4,"concept":"K6-1-u6-C43","difficulty":3,"kind":"mc","stem":"눈에 띄게 하려고 일부러 세게 쓴 곳이 있을 때 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"발표할 때 그렇게 한 까닭을 밝힌다","correct":true},{"t":"아무 말 없이 그대로 둔다","mis":"K6-1-u6-X42"},{"t":"눈에 띄지 않게 모두 지운다","mis":"K6-1-u6-X41"},{"t":"더 크게 부풀린다","mis":"K6-1-u6-X42"}],"explanation":["숨기면 속이는 셈이에요.","눈에 띄는 것도 필요해요.","스스로 밝히면 속이지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L12_challenge#5','kor',6,1,'u6','L12','g6_1_kor_u6_L12_challenge','lesson_challenge','K6-1-u6-C49',3,'mc','auto','맞춤법이 헷갈릴 때 가리는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X48']::text[],false,'{"seq":5,"concept":"K6-1-u6-C49","difficulty":3,"kind":"mc","stem":"맞춤법이 헷갈릴 때 가리는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"본디 말로 늘여 소리 내어 본다(되어요 · 오래간만에)","correct":true},{"t":"소리 나는 대로 쓴다","mis":"K6-1-u6-X48"},{"t":"짧은 쪽을 고른다","mis":"K6-1-u6-X48"},{"t":"아무 쪽이나 쓴다","mis":"K6-1-u6-X48"}],"explanation":["소리대로 쓰면 틀리기 쉬워요.","짧다고 맞지 않아요.","본디 말로 늘이면 가려져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L12_challenge#6','kor',6,1,'u6','L12','g6_1_kor_u6_L12_challenge','lesson_challenge','K6-1-u6-C41',3,'mc','auto','「청소 시간에 맡은 곳만 하고 남은 것을 지나친다」가 공익 광고 주제로 알맞은 까닭은 어느 것인가요?',ARRAY['K6-1-u6-X39','K6-1-u6-X42']::text[],false,'{"seq":6,"concept":"K6-1-u6-C41","difficulty":3,"kind":"mc","stem":"「청소 시간에 맡은 곳만 하고 남은 것을 지나친다」가 공익 광고 주제로 알맞은 까닭은 어느 것인가요?","options":[{"t":"여럿이 함께 겪고, 고치면 나아지는 일이기 때문이다","correct":true},{"t":"나 혼자만 겪는 일이기 때문이다","mis":"K6-1-u6-X39"},{"t":"고쳐도 달라지지 않는 일이기 때문이다","mis":"K6-1-u6-X39"},{"t":"눈에 띄는 그림을 그릴 수 있기 때문이다","mis":"K6-1-u6-X42"}],"explanation":["여럿이 겪어요.","고치면 나아져요.","그림보다 주제의 가치가 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L12_challenge#7','kor',6,1,'u6','L12','g6_1_kor_u6_L12_challenge','lesson_challenge','K6-1-u6-C46',3,'mc','auto','판단이 「결과와 근거가 한 짝」이어야 하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X06','K6-1-u6-X45']::text[],false,'{"seq":7,"concept":"K6-1-u6-C46","difficulty":3,"kind":"mc","stem":"판단이 「결과와 근거가 한 짝」이어야 하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"근거 없는 판단은 기분일 뿐이라 친구가 무엇을 어떻게 고칠지 알 수 없기 때문이다","correct":true},{"t":"판단은 짧을수록 좋기 때문이다","mis":"K6-1-u6-X06"},{"t":"친구를 이기려면 근거가 필요하기 때문이다","mis":"K6-1-u6-X45"},{"t":"근거는 속으로만 생각해도 되기 때문이다","mis":"K6-1-u6-X06"}],"explanation":["짧으면 까닭이 빠져요.","이기려는 게 아니에요.","말해야 고칠 곳을 알아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L12_challenge#8','kor',6,1,'u6','L12','g6_1_kor_u6_L12_challenge','lesson_challenge','K6-1-u6-C47',4,'mc','auto','「그늘막을 더 세웁시다」를 두 자로 잰 결과로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X21','K6-1-u6-X46']::text[],false,'{"seq":8,"concept":"K6-1-u6-C47","difficulty":4,"kind":"mc","stem":"「그늘막을 더 세웁시다」를 두 자로 잰 결과로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"주장과 문단 ②·③, 직접 센 근거는 받아들이고, 문단 ④(어긋난 이유)와 ⑤(과장 · 거짓)는 까닭을 대어 짚는다","correct":true},{"t":"걸린 곳이 셋이니 주장까지 버린다","mis":"K6-1-u6-X21"},{"t":"내용은 타당하니 표현은 볼 필요가 없다","mis":"K6-1-u6-X46"},{"t":"표현만 고치면 이유는 볼 필요가 없다","mis":"K6-1-u6-X46"}],"explanation":["주장까지 버리지 않아요.","표현도 재요.","받아들일 것과 물릴 것을 갈랐어요 — ⑤문단은 「볕을 가려 조금 덜 덥다」로 바로잡아요."],"asset":{"type":"passage","lines":["① 신호를 기다리는 동안 볕을 피할 곳이 없습니다.","학교 앞 건널목에 그늘막을 더 세웠으면 좋겠습니다.","② 첫째, 볕을 가려 주면 기다리는 동안 덜 지칩니다. 지난 여름 우리 반에서 세어 보니","아침마다 건널목 앞에 스무 명 남짓이 함께 서 있었습니다.","③ 둘째, 그늘막은 색이 밝아 멀리서도 눈에 띕니다.","차를 모는 사람이 건널목을 일찍 알아볼 수 있습니다."],"title":"「그늘막을 더 세웁시다」 — 앞부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L12_challenge#9','kor',6,1,'u6','L12','g6_1_kor_u6_L12_challenge','lesson_challenge','K6-1-u6-C42',4,'essay','teacher','첫 번째 초안의 ㄱ~ㄷ 가운데 두 문구를 골라 무엇이 걸리는지 쓰고, 뜻은 살리면서 알맞게 고쳐 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u6-C42","difficulty":4,"kind":"essay","stem":"첫 번째 초안의 ㄱ~ㄷ 가운데 두 문구를 골라 무엇이 걸리는지 쓰고, 뜻은 살리면서 알맞게 고쳐 쓰세요.","answer_guide":{"answer":"예: ㄱ 「빌려주면 백 퍼센트 망가집니다!」는 늘 그렇게 되지는 않으니 부풀린 과장이다. 고쳐 쓰면 「빌려준 지우개가 반으로 돌아왔습니다.」 ㄴ 「이 광고 하나면 우리 반 문제가 모두 사라집니다.」는 광고 하나로 모든 문제가 사라지지 않으니 과장이다. 고쳐 쓰면 「한 사람이 지키면 한 사람이 웃습니다.」","scoring_points":["두 문구를 골랐는가","무엇이 걸리는지 까닭을 썼는가","뜻을 살려 알맞게 고쳐 썼는가"]},"explanation":["부풀린 말을 찾아요.","실제로 늘 그런지 물어요.","크기만 줄여 고쳐요. (바로잡기: 광고 하나로 문제가 다 사라지지 않아요.)"],"asset":{"type":"passage","lines":["장면 — 반으로 갈라진 지우개 옆에 빈 필통이 열려 있는 그림","ㄱ. 빌려주면 백 퍼센트 망가집니다!","ㄴ. 이 광고 하나면 우리 반 문제가 모두 사라집니다.","ㄷ. 빌린 물건, 절대 그냥 돌려주지 마세요.","ㄹ. 빌린 그대로 — 그것이 다음에도 빌릴 수 있는 길"],"title":"공익 광고 첫 번째 초안 「빌린 물건은 빌린 그대로」 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L12_challenge#10','kor',6,1,'u6','L12','g6_1_kor_u6_L12_challenge','lesson_challenge','K6-1-u6-C43',4,'essay','teacher','광고를 만들 때 「틀린 말만 없으면 되지」와 「눈에 띄기만 하면 되지」 사이에서 어떻게 할지 쓰고, 내가 만들 광고의 크게 쓸 한 줄과 발표 때 밝힐 말을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u6-C43","difficulty":4,"kind":"essay","stem":"광고를 만들 때 「틀린 말만 없으면 되지」와 「눈에 띄기만 하면 되지」 사이에서 어떻게 할지 쓰고, 내가 만들 광고의 크게 쓸 한 줄과 발표 때 밝힐 말을 쓰세요.","answer_guide":{"answer":"예: 틀린 말만 없으면 아무도 보지 않고, 눈에 띄기만 하면 믿을 수 없다. 그래서 사실에 가까운 말로 쓰되 가장 하고 싶은 한 줄만 크게 하겠다. 크게 쓸 한 줄 — 「돌려줄 때 한 번만 살펴 주세요」. 발표 때 — 「빌린 물건이 망가져 돌아온 일을 보고 주제를 골랐고, 반으로 갈라진 지우개 그림을 크게 그려 문제를 보여 주었습니다. 그림을 일부러 크게 그린 까닭은 한눈에 문제를 보여 주고 싶어서입니다.」","scoring_points":["두 쪽 사이에서 어떻게 할지 썼는가","크게 쓸 한 줄을 알맞게 썼는가","발표 때 고른 까닭과 강조한 것을 밝혔는가"]},"explanation":["양쪽을 다 막아요.","한 줄만 크게 해요.","손댄 곳의 까닭을 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#1','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C1',1,'mc','auto','글을 그대로 받아들이지 않고 내용과 표현이 알맞은지 판단하며 읽는 것을 무엇이라고 하나요?',ARRAY['K6-1-u6-X01','K6-1-u6-X03']::text[],false,'{"seq":1,"concept":"K6-1-u6-C1","difficulty":1,"kind":"mc","stem":"글을 그대로 받아들이지 않고 내용과 표현이 알맞은지 판단하며 읽는 것을 무엇이라고 하나요?","options":[{"t":"비판적으로 읽기","correct":true},{"t":"훑어 읽기","mis":"K6-1-u6-X01"},{"t":"소리 내어 읽기","mis":"K6-1-u6-X03"},{"t":"외우며 읽기","mis":"K6-1-u6-X01"}],"explanation":["빠르게 보는 읽기예요.","읽는 방법이 달라요.","판단하며 읽는 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#2','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C8',1,'mc','auto','내용의 타당성을 재는 세 물음이 차례로 재는 것은 무엇인가요?',ARRAY['K6-1-u6-X08','K6-1-u6-X07','K6-1-u6-X03']::text[],false,'{"seq":2,"concept":"K6-1-u6-C8","difficulty":1,"kind":"mc","stem":"내용의 타당성을 재는 세 물음이 차례로 재는 것은 무엇인가요?","options":[{"t":"주장 · 이유 · 근거","correct":true},{"t":"제목 · 그림 · 글씨","mis":"K6-1-u6-X08"},{"t":"서론 · 본론 · 결론","mis":"K6-1-u6-X07"},{"t":"거짓 · 과장 · 감춤","mis":"K6-1-u6-X03"}],"explanation":["겉모습을 재지 않아요.","짜임이 아니에요.","그건 표현의 적절성이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#3','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C7',1,'mc','auto','주장하는 글에서 주장을 찾을 때 함께 보면 좋은 두 부분은 어디인가요?',ARRAY['K6-1-u6-X07']::text[],false,'{"seq":3,"concept":"K6-1-u6-C7","difficulty":1,"kind":"mc","stem":"주장하는 글에서 주장을 찾을 때 함께 보면 좋은 두 부분은 어디인가요?","options":[{"t":"서론과 결론","correct":true},{"t":"본론의 첫째 이유와 둘째 이유","mis":"K6-1-u6-X07"},{"t":"제목과 그림","mis":"K6-1-u6-X07"},{"t":"근거와 출처","mis":"K6-1-u6-X07"}],"explanation":["이유는 주장을 받쳐요.","그림만으로는 몰라요.","서론과 결론이 함께 가리켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#4','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C25',1,'mc','auto','없는 것을 있는 것처럼 말한 표현을 무엇이라고 하나요?',ARRAY['K6-1-u6-X25','K6-1-u6-X26']::text[],false,'{"seq":4,"concept":"K6-1-u6-C25","difficulty":1,"kind":"mc","stem":"없는 것을 있는 것처럼 말한 표현을 무엇이라고 하나요?","options":[{"t":"거짓된 표현","correct":true},{"t":"과장된 표현","mis":"K6-1-u6-X25"},{"t":"감추는 내용","mis":"K6-1-u6-X25"},{"t":"알맞은 표현","mis":"K6-1-u6-X26"}],"explanation":["과장은 있는 것을 부풀려요.","감춤은 빼놓는 거예요.","없는 걸 있다고 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#5','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C24',1,'mc','auto','광고를 볼 때 큰 글씨와 함께 꼭 살펴야 할 것은 어느 것인가요?',ARRAY['K6-1-u6-X24','K6-1-u6-X23']::text[],false,'{"seq":5,"concept":"K6-1-u6-C24","difficulty":1,"kind":"mc","stem":"광고를 볼 때 큰 글씨와 함께 꼭 살펴야 할 것은 어느 것인가요?","options":[{"t":"작게 적은 글씨","correct":true},{"t":"광고의 테두리 색","mis":"K6-1-u6-X24"},{"t":"광고를 붙인 높이","mis":"K6-1-u6-X24"},{"t":"광고에 쓰인 글자 수","mis":"K6-1-u6-X23"}],"explanation":["테두리가 아니에요.","높이와 관계없어요.","작게 쓴 데 조건이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#6','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C32',1,'mc','auto','설명하는 글의 거짓된 표현이 읽는 사람에게 남기는 것은 어느 것인가요?',ARRAY['K6-1-u6-X25','K6-1-u6-X31']::text[],false,'{"seq":6,"concept":"K6-1-u6-C32","difficulty":1,"kind":"mc","stem":"설명하는 글의 거짓된 표현이 읽는 사람에게 남기는 것은 어느 것인가요?","options":[{"t":"잘못된 지식","correct":true},{"t":"지나친 믿음","mis":"K6-1-u6-X25"},{"t":"한쪽만 아는 생각","mis":"K6-1-u6-X25"},{"t":"아무것도 남지 않는다","mis":"K6-1-u6-X31"}],"explanation":["과장이 남기는 거예요.","감춤이 남기는 거예요.","거짓은 잘못된 지식이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#7','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C41',1,'mc','auto','공익 광고의 주제로 고를 일은 어느 것인가요?',ARRAY['K6-1-u6-X39','K6-1-u6-X42']::text[],false,'{"seq":7,"concept":"K6-1-u6-C41","difficulty":1,"kind":"mc","stem":"공익 광고의 주제로 고를 일은 어느 것인가요?","options":[{"t":"여럿이 함께 겪고 고치면 나아지는 일","correct":true},{"t":"나 혼자만 겪는 일","mis":"K6-1-u6-X39"},{"t":"고쳐도 달라지지 않는 일","mis":"K6-1-u6-X39"},{"t":"눈에 띄는 그림을 그리기 쉬운 일","mis":"K6-1-u6-X42"}],"explanation":["여럿이 겪어야 해요.","나아질 수 있어야 해요.","주제의 가치가 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#8','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C48',1,'mc','auto','「바지 길이를 길게 (　)」의 빈칸에 알맞은 낱말은 어느 것인가요?',ARRAY['K6-1-u6-X47']::text[],false,'{"seq":8,"concept":"K6-1-u6-C48","difficulty":1,"kind":"mc","stem":"「바지 길이를 길게 (　)」의 빈칸에 알맞은 낱말은 어느 것인가요?","options":[{"t":"늘였다","correct":true},{"t":"늘렸다","mis":"K6-1-u6-X47"},{"t":"맞혔다","mis":"K6-1-u6-X47"},{"t":"쫓았다","mis":"K6-1-u6-X47"}],"explanation":["수나 양을 많게 할 때 써요.","답을 대는 뜻이에요.","길게 하면 「늘이다」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#9','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C7',2,'mc','auto','담희 글의 주장은 무엇인가요?',ARRAY['K6-1-u6-X11','K6-1-u6-X07']::text[],false,'{"seq":9,"concept":"K6-1-u6-C7","difficulty":2,"kind":"mc","stem":"담희 글의 주장은 무엇인가요?","options":[{"t":"쉬는 시간마다 창문을 열어 두자","correct":true},{"t":"창문을 닫아 두자","mis":"K6-1-u6-X11"},{"t":"감기에 걸리지 않게 하자","mis":"K6-1-u6-X07"},{"t":"셋째 시간을 줄이자","mis":"K6-1-u6-X07"}],"explanation":["주장과 반대예요.","이유에 나온 말이에요.","서론과 결론이 함께 가리켜요. (바로잡기: 창문을 열어도 감기에 걸릴 수 있어요.) (바로잡기: 창문을 열어도 해결 안 되는 문제가 있어요.)"],"asset":{"type":"passage","lines":["④ 셋째, 창문을 열어 두면 감기에 걸리지 않습니다.","옆 반 친구가 그렇게 말해 주었습니다.","⑤ 창문만 열면 교실의 모든 문제가 사라집니다.","⑥ 추운 날에는 잠깐만 열어도 됩니다. 쉬는 시간마다 창문을 열어 둡시다."],"title":"담희의 글 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#10','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C12',2,'mc','auto','담희 글에서 근거로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X19','K6-1-u6-X26','K6-1-u6-X16']::text[],false,'{"seq":10,"concept":"K6-1-u6-C12","difficulty":2,"kind":"mc","stem":"담희 글에서 근거로 알맞은 것은 어느 것인가요?","options":[{"t":"일주일 동안 창문을 열어 보니 「답답하다」고 적은 친구가 날마다 줄었다","correct":true},{"t":"옆 반 친구가 감기에 안 걸린다고 말해 주었다","mis":"K6-1-u6-X19"},{"t":"창문만 열면 모든 문제가 사라진다","mis":"K6-1-u6-X26"},{"t":"추운 날에는 잠깐만 열어도 된다","mis":"K6-1-u6-X16"}],"explanation":["전해 들은 말이에요.","부풀린 말이에요.","직접 해 보고 적은 기록이에요."],"asset":{"type":"passage","lines":["① 셋째 시간이 끝날 무렵이면 교실 공기가 답답해집니다.","쉬는 시간마다 창문을 열어 두면 좋겠습니다.","② 첫째, 바깥 공기가 들어와 교실 공기가 바뀝니다. 우리 반이 일주일 동안","쉬는 시간마다 창문을 열어 보니, 「답답하다」고 적은 친구가 날마다 줄었습니다.","③ 둘째, 창문을 닫아 두면 바깥 소리가 들어오지 않아 수업에 마음을 모을 수 있습니다."],"title":"담희의 글 「쉬는 시간마다 창문을 열어 둡시다」 — 앞부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#11','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C25',2,'mc','auto','형광펜 광고에서 거짓된 표현은 어느 것인가요?',ARRAY['K6-1-u6-X05','K6-1-u6-X25']::text[],false,'{"seq":11,"concept":"K6-1-u6-C25","difficulty":2,"kind":"mc","stem":"형광펜 광고에서 거짓된 표현은 어느 것인가요?","options":[{"t":"공부가 저절로 되는 형광펜!","correct":true},{"t":"다섯 가지 색이 한 묶음","mis":"K6-1-u6-X05"},{"t":"뚜껑을 닫아 두면 잘 마르지 않아요","mis":"K6-1-u6-X05"},{"t":"영원히 마르지 않는 잉크!","mis":"K6-1-u6-X25"}],"explanation":["사실을 밝힌 말이에요.","실제로 있는 기능이에요.","형광펜에는 공부를 대신해 주는 기능이 없어요 — 거짓이에요. (바로잡기: 뚜껑을 열어 두면 잉크는 마를 수 있어요.)"],"asset":{"type":"passage","lines":["장면 ① 형광펜을 든 아이가 웃는 큰 그림 「공부가 저절로 되는 형광펜!」","장면 ② 「다섯 가지 색이 한 묶음」 「뚜껑을 닫아 두면 잘 마르지 않아요.」","장면 ③ 금빛 딱지 「세상에서 가장 밝은 색! 가장 많이 팔린 형광펜!」","장면 ④ 「영원히 마르지 않는 잉크!」","　　(아주 작은 글씨) ※ 뚜껑을 열어 두면 금방 마를 수 있음."],"title":"형광펜 광고 「쓱쓱 형광펜」 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#12','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C27',2,'mc','auto','형광펜 광고에서 감추는 내용이 있는 문구는 어느 것인가요?',ARRAY['K6-1-u6-X05','K6-1-u6-X24']::text[],false,'{"seq":12,"concept":"K6-1-u6-C27","difficulty":2,"kind":"mc","stem":"형광펜 광고에서 감추는 내용이 있는 문구는 어느 것인가요?","options":[{"t":"가장 많이 팔린 형광펜!","correct":true},{"t":"다섯 가지 색이 한 묶음","mis":"K6-1-u6-X05"},{"t":"뚜껑을 닫아 두면 잘 마르지 않아요","mis":"K6-1-u6-X05"},{"t":"※ 뚜껑을 열어 두면 금방 마를 수 있음","mis":"K6-1-u6-X24"}],"explanation":["밝힌 말이에요.","되묻고 싶은 게 없어요.","언제 · 어디에서 · 무엇과 견주었는지 빠졌어요."],"asset":{"type":"passage","lines":["장면 ① 형광펜을 든 아이가 웃는 큰 그림 「공부가 저절로 되는 형광펜!」","장면 ② 「다섯 가지 색이 한 묶음」 「뚜껑을 닫아 두면 잘 마르지 않아요.」","장면 ③ 금빛 딱지 「세상에서 가장 밝은 색! 가장 많이 팔린 형광펜!」","장면 ④ 「영원히 마르지 않는 잉크!」","　　(아주 작은 글씨) ※ 뚜껑을 열어 두면 금방 마를 수 있음."],"title":"형광펜 광고 「쓱쓱 형광펜」 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#13','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C34',2,'mc','auto','갯벌 글에서 거짓된 표현은 어느 것인가요?',ARRAY['K6-1-u6-X05','K6-1-u6-X25']::text[],false,'{"seq":13,"concept":"K6-1-u6-C34","difficulty":2,"kind":"mc","stem":"갯벌 글에서 거짓된 표현은 어느 것인가요?","options":[{"t":"요즘 우리나라 바닷가는 모두 갯벌로 이루어져 있습니다","correct":true},{"t":"바닷물은 하루에 두 번쯤 들어왔다가 빠져나갑니다","mis":"K6-1-u6-X05"},{"t":"갯벌에는 게, 조개, 갯지렁이가 삽니다","mis":"K6-1-u6-X05"},{"t":"갯벌은 언제든 걸어 들어가 놀아도 좋습니다","mis":"K6-1-u6-X25"}],"explanation":["사실이에요.","사실이에요.","모래 바닷가 · 바위 바닷가도 있어요 — 바르게는 「우리나라 바닷가 가운데에는 갯벌이 넓게 펼쳐진 곳이 있습니다」예요. (바로잡기: 갯벌 생물도 지나치게 잡으면 줄어들어요.)"],"asset":{"type":"passage","lines":["④ 갯벌은 언제든 걸어 들어가 놀아도 좋습니다.","⑤ 갯벌 생물은 아무리 많이 잡아도 절대 줄어들지 않습니다.","요즘 우리나라 바닷가는 모두 갯벌로 이루어져 있습니다.","⑥ 갯벌을 보면 바다와 땅이 함께 만든 살림터를 알 수 있습니다."],"title":"「바다와 땅 사이, 갯벌」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#14','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C33',2,'mc','auto','갯벌 글에 세 기준을 대는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X32']::text[],false,'{"seq":14,"concept":"K6-1-u6-C33","difficulty":2,"kind":"mc","stem":"갯벌 글에 세 기준을 대는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"거짓을 들고 문단 ①~⑥을 훑고, 다시 과장을, 마지막으로 감춤을 들고 처음부터 훑는다","correct":true},{"t":"문단 ④에서만 세 기준을 한꺼번에 잰다","mis":"K6-1-u6-X32"},{"t":"제목만 보고 판단한다","mis":"K6-1-u6-X32"},{"t":"좋아 보이는 문단은 건너뛴다","mis":"K6-1-u6-X32"}],"explanation":["한 문단만 보면 놓쳐요.","글 전체를 훑어요.","기준 하나로 전체를 훑어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#15','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C42',2,'mc','auto','도율이의 초안에서 고치지 않아도 되는 문구는 어느 것인가요?',ARRAY['K6-1-u6-X26']::text[],false,'{"seq":15,"concept":"K6-1-u6-C42","difficulty":2,"kind":"mc","stem":"도율이의 초안에서 고치지 않아도 되는 문구는 어느 것인가요?","options":[{"t":"ㄹ. 잠가요, 비누칠하는 동안","correct":true},{"t":"ㄱ. 물을 틀어 두면 지구의 물이 하루 만에 말라 버립니다!","mis":"K6-1-u6-X26"},{"t":"ㄴ. 이 광고만 보면 물 낭비가 모두 사라집니다.","mis":"K6-1-u6-X26"},{"t":"ㄷ. 비누칠할 때 물을 틀어 두면 무조건 벌금!","mis":"K6-1-u6-X26"}],"explanation":["사실이 아니에요 — 지구의 물이 하루 만에 마르지 않아요.","부풀렸어요.","뜻이 분명하고 부풀리지 않았어요 — ㄷ도 없는 벌금 규칙을 있다고 한 거짓이에요."],"asset":{"type":"passage","lines":["장면 — 비누 거품이 묻은 손 아래로 물이 콸콸 흐르는 그림","ㄱ. 물을 틀어 두면 지구의 물이 하루 만에 말라 버립니다!","ㄴ. 이 광고만 보면 물 낭비가 모두 사라집니다.","ㄷ. 비누칠할 때 물을 틀어 두면 무조건 벌금!","ㄹ. 잠가요, 비누칠하는 동안"],"title":"도율의 공익 광고 초안 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#16','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C21',2,'mc','auto','도율이의 첫 말 「이 글은 다 버리는 게 낫겠다」에 대한 판단으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X21','K6-1-u6-X01','K6-1-u6-X05']::text[],false,'{"seq":16,"concept":"K6-1-u6-C21","difficulty":2,"kind":"mc","stem":"도율이의 첫 말 「이 글은 다 버리는 게 낫겠다」에 대한 판단으로 알맞은 것은 어느 것인가요?","options":[{"t":"걸린 곳만 짚고 주장과 직접 센 기록은 받아들여야 한다","correct":true},{"t":"걸린 곳이 셋이니 버리는 게 맞다","mis":"K6-1-u6-X21"},{"t":"걸린 곳이 있어도 모두 받아들여야 한다","mis":"K6-1-u6-X01"},{"t":"더 많은 흠을 찾아야 한다","mis":"K6-1-u6-X05"}],"explanation":["쓸 것까지 버려요.","걸린 곳은 짚어요.","받아들일 것과 물릴 것을 나눠요."],"asset":{"type":"speech","turns":[{"who":"도율","text":"담희 글에 이상한 데가 세 군데나 있어. 이 글은 다 버리는 게 낫겠다."},{"who":"담희","text":"걸린 곳만 짚어 줘. 창문을 열자는 주장과 직접 센 기록도 틀렸어?"},{"who":"도율","text":"그건 아니야. 그리고 ⑤문단은 그냥 별로야."},{"who":"담희","text":"별로라고만 하면 어디를 고칠지 모르겠어. 왜 걸리는지 까닭을 말해 줄래?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#17','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C20',3,'mc','auto','담희 글을 차례대로 잰 결과로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X21','K6-1-u6-X10','K6-1-u6-X19']::text[],false,'{"seq":17,"concept":"K6-1-u6-C20","difficulty":3,"kind":"mc","stem":"담희 글을 차례대로 잰 결과로 알맞은 것은 어느 것인가요?","options":[{"t":"주장은 가치 있음 → 이유 ③은 어긋나고 ④는 사실이 아님 → 근거 ④는 전해 들은 말이라 걸림","correct":true},{"t":"근거가 하나 걸렸으니 주장도 가치 없음","mis":"K6-1-u6-X21"},{"t":"이유 ③은 맞는 말이니 뒷받침함","mis":"K6-1-u6-X10"},{"t":"전해 들은 말도 누가 말했는지 있으니 알맞음","mis":"K6-1-u6-X19"}],"explanation":["주장의 가치는 따로 재요.","맞는 말이어도 어긋나요.","주장 → 이유 → 근거 차례로 쟀어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#18','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C37',3,'mc','auto','「공부가 저절로 되는 형광펜!」을 알맞게 고친 것은 어느 것인가요?',ARRAY['K6-1-u6-X35','K6-1-u6-X26']::text[],false,'{"seq":18,"concept":"K6-1-u6-C37","difficulty":3,"kind":"mc","stem":"「공부가 저절로 되는 형광펜!」을 알맞게 고친 것은 어느 것인가요?","options":[{"t":"중요한 곳을 눈에 띄게 표시해 주는 형광펜","correct":true},{"t":"공부가 정말 저절로 되는 형광펜","mis":"K6-1-u6-X35"},{"t":"세상 모든 공부를 대신하는 형광펜","mis":"K6-1-u6-X26"},{"t":"형광펜을 쓰지 맙시다","mis":"K6-1-u6-X35"}],"explanation":["거짓을 그대로 두었어요.","더 부풀렸어요.","형광펜이 실제로 하는 일만 말했어요."],"asset":{"type":"passage","lines":["장면 ① 형광펜을 든 아이가 웃는 큰 그림 「공부가 저절로 되는 형광펜!」","장면 ② 「다섯 가지 색이 한 묶음」 「뚜껑을 닫아 두면 잘 마르지 않아요.」","장면 ③ 금빛 딱지 「세상에서 가장 밝은 색! 가장 많이 팔린 형광펜!」","장면 ④ 「영원히 마르지 않는 잉크!」","　　(아주 작은 글씨) ※ 뚜껑을 열어 두면 금방 마를 수 있음."],"title":"형광펜 광고 「쓱쓱 형광펜」 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#19','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C37',3,'mc','auto','「갯벌은 언제든 걸어 들어가 놀아도 좋습니다」를 알맞게 고친 것은 어느 것인가요?',ARRAY['K6-1-u6-X35','K6-1-u6-X33']::text[],false,'{"seq":19,"concept":"K6-1-u6-C37","difficulty":3,"kind":"mc","stem":"「갯벌은 언제든 걸어 들어가 놀아도 좋습니다」를 알맞게 고친 것은 어느 것인가요?","options":[{"t":"갯벌에 들어갈 때에는 바닷물이 들어오는 때를 확인하고 어른과 함께 가야 합니다","correct":true},{"t":"갯벌은 언제든 정말 놀아도 좋습니다","mis":"K6-1-u6-X35"},{"t":"갯벌에는 절대 들어가지 맙시다","mis":"K6-1-u6-X35"},{"t":"갯벌은 언제나 안전합니다","mis":"K6-1-u6-X33"}],"explanation":["감춘 것을 밝히지 않았어요.","뜻까지 바꿨어요.","알아야 할 것을 밝혔어요."],"asset":{"type":"passage","lines":["④ 갯벌은 언제든 걸어 들어가 놀아도 좋습니다.","⑤ 갯벌 생물은 아무리 많이 잡아도 절대 줄어들지 않습니다.","요즘 우리나라 바닷가는 모두 갯벌로 이루어져 있습니다.","⑥ 갯벌을 보면 바다와 땅이 함께 만든 살림터를 알 수 있습니다."],"title":"「바다와 땅 사이, 갯벌」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#20','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C42',3,'mc','auto','「이 광고만 보면 물 낭비가 모두 사라집니다」를 알맞게 고친 것은 어느 것인가요?',ARRAY['K6-1-u6-X35','K6-1-u6-X26']::text[],false,'{"seq":20,"concept":"K6-1-u6-C42","difficulty":3,"kind":"mc","stem":"「이 광고만 보면 물 낭비가 모두 사라집니다」를 알맞게 고친 것은 어느 것인가요?","options":[{"t":"한 사람이 잠그면 한 컵만큼 물이 남습니다","correct":true},{"t":"이 광고만 보면 물 낭비가 정말 다 사라집니다","mis":"K6-1-u6-X35"},{"t":"물 낭비는 영원히 사라집니다","mis":"K6-1-u6-X26"},{"t":"물을 아예 쓰지 맙시다","mis":"K6-1-u6-X35"}],"explanation":["부풀린 그대로예요.","더 부풀렸어요.","뜻은 살리고 크기만 줄였어요."],"asset":{"type":"passage","lines":["장면 — 비누 거품이 묻은 손 아래로 물이 콸콸 흐르는 그림","ㄱ. 물을 틀어 두면 지구의 물이 하루 만에 말라 버립니다!","ㄴ. 이 광고만 보면 물 낭비가 모두 사라집니다.","ㄷ. 비누칠할 때 물을 틀어 두면 무조건 벌금!","ㄹ. 잠가요, 비누칠하는 동안"],"title":"도율의 공익 광고 초안 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#21','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C47',3,'mc','auto','「그늘막을 더 세웁시다」에 두 자를 모두 댄 판단은 어느 것인가요?',ARRAY['K6-1-u6-X46','K6-1-u6-X21']::text[],false,'{"seq":21,"concept":"K6-1-u6-C47","difficulty":3,"kind":"mc","stem":"「그늘막을 더 세웁시다」에 두 자를 모두 댄 판단은 어느 것인가요?","options":[{"t":"내용: 문단 ④가 주장과 어긋남 · 표현: 문단 ⑤가 과장과 거짓","correct":true},{"t":"내용: 문단 ④가 어긋남 — 표현은 보지 않음","mis":"K6-1-u6-X46"},{"t":"표현: 문단 ⑤가 과장 — 내용은 보지 않음","mis":"K6-1-u6-X46"},{"t":"걸린 곳이 있으니 모두 버림","mis":"K6-1-u6-X21"}],"explanation":["표현도 봐야 해요.","내용도 봐야 해요.","여섯 물음을 다 댔어요 — ⑤는 「볕을 가려 조금 덜 덥다」로 바로잡아요. (바로잡기: 그늘막 아래도 더울 수 있어요.)"],"asset":{"type":"passage","lines":["④ 셋째, 그늘막 아래에서는 친구들과 이야기를 나눌 수 있어 즐겁습니다.","⑤ 그늘막 하나면 여름 더위가 모두 사라집니다. 그늘막 아래에서는 절대 덥지 않습니다.","⑥ 그늘막은 세우는 데 오래 걸리지 않습니다.","여름이 오기 전에 건널목 앞에 그늘막을 더 세웁시다."],"title":"「그늘막을 더 세웁시다」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#22','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C48',3,'mc','auto','낱말을 바르게 쓴 문장은 어느 것인가요?',ARRAY['K6-1-u6-X47']::text[],false,'{"seq":22,"concept":"K6-1-u6-C48","difficulty":3,"kind":"mc","stem":"낱말을 바르게 쓴 문장은 어느 것인가요?","options":[{"t":"고양이가 마당의 참새를 쫓았다.","correct":true},{"t":"꿈을 쫓아 열심히 공부했다.","mis":"K6-1-u6-X47"},{"t":"수수께끼의 답을 맞추었다.","mis":"K6-1-u6-X47"},{"t":"모둠 수를 하나 늘였다.","mis":"K6-1-u6-X47"}],"explanation":["목표를 따르면 「좇다」예요.","답을 옳게 대면 「맞히다」예요.","수를 많게 하면 「늘리다」예요 — 몰아내거나 뒤를 따르면 「쫓다」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#23','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C47',4,'mc','auto','담희 글 전체를 가장 알맞게 평가한 것은 어느 것인가요?',ARRAY['K6-1-u6-X21','K6-1-u6-X01','K6-1-u6-X46']::text[],false,'{"seq":23,"concept":"K6-1-u6-C47","difficulty":4,"kind":"mc","stem":"담희 글 전체를 가장 알맞게 평가한 것은 어느 것인가요?","options":[{"t":"주장과 문단 ②의 이유 · 기록은 받아들일 만하지만, 어긋난 이유 ③ · 사실이 아닌 이유와 전해 들은 근거 ④ · 과장 ⑤를 고쳐야 한다","correct":true},{"t":"걸린 곳이 많으니 버리고 새로 써야 한다","mis":"K6-1-u6-X21"},{"t":"주장이 좋으니 고칠 곳이 없다","mis":"K6-1-u6-X01"},{"t":"표현만 고치면 된다","mis":"K6-1-u6-X46"}],"explanation":["버리지 않고 고쳐요.","걸린 곳이 있어요.","내용도 걸린 곳이 있어요."],"asset":{"type":"passage","lines":["④ 셋째, 창문을 열어 두면 감기에 걸리지 않습니다.","옆 반 친구가 그렇게 말해 주었습니다.","⑤ 창문만 열면 교실의 모든 문제가 사라집니다.","⑥ 추운 날에는 잠깐만 열어도 됩니다. 쉬는 시간마다 창문을 열어 둡시다."],"title":"담희의 글 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#24','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C18',4,'essay','teacher','담희 글에서 내용이 걸리는 곳 두 군데를 찾아 까닭을 쓰고, 그중 하나를 주장 편에 서도록 고쳐 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u6-C18","difficulty":4,"kind":"essay","stem":"담희 글에서 내용이 걸리는 곳 두 군데를 찾아 까닭을 쓰고, 그중 하나를 주장 편에 서도록 고쳐 쓰세요.","answer_guide":{"answer":"예: 문단 ③ 「창문을 닫아 두면 바깥 소리가 들어오지 않아 수업에 마음을 모을 수 있다」는 닫자는 쪽을 가리켜 열어 두자는 주장과 어긋난다. 문단 ④ 「창문을 열어 두면 감기에 걸리지 않는다」는 사실이 아니고, 옆 반 친구의 말은 전해 들은 말이라 확인할 수 없다. 문단 ③을 고치면 — 「둘째, 바깥 공기를 들이면 머리가 맑아진 느낌이 들어 다음 시간을 더 상쾌하게 시작할 수 있습니다.」","scoring_points":["걸리는 곳 두 군데를 찾았는가","각각 까닭을 썼는가","하나를 주장 편으로 고쳐 썼는가"]},"explanation":["세 기준을 차례로 대요.","까닭을 붙여요.","같은 문제를 주장 쪽으로 이어요."],"asset":{"type":"passage","lines":["④ 셋째, 창문을 열어 두면 감기에 걸리지 않습니다.","옆 반 친구가 그렇게 말해 주었습니다.","⑤ 창문만 열면 교실의 모든 문제가 사라집니다.","⑥ 추운 날에는 잠깐만 열어도 됩니다. 쉬는 시간마다 창문을 열어 둡시다."],"title":"담희의 글 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#25','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C47',4,'essay','teacher','이 단원이 남긴 여섯 물음을 쓰고, 그 물음을 쓸 때 꼭 함께 해야 할 일 한 가지를 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u6-C47","difficulty":4,"kind":"essay","stem":"이 단원이 남긴 여섯 물음을 쓰고, 그 물음을 쓸 때 꼭 함께 해야 할 일 한 가지를 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 내용의 타당성 — 주장은 가치 있고 중요한가, 이유는 주장을 뒷받침하는가, 근거는 이유를 뒷받침하는가. 표현의 적절성 — 거짓된 표현이 있는가, 과장된 표현이 있는가, 감추는 내용이 있는가. 이 물음을 쓸 때에는 그렇게 판단한 까닭을 함께 대야 한다. 까닭 없는 판단은 기분일 뿐이라 다른 사람이 따져 볼 수 없기 때문이다.","scoring_points":["내용의 타당성 세 물음을 썼는가","표현의 적절성 세 물음을 썼는가","까닭을 함께 대야 함을 썼는가"]},"explanation":["두 자를 떠올려요.","여섯 물음을 써요.","까닭과 이어 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#1','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C3',1,'mc','auto','판단하며 읽기의 두 갈래로 알맞게 묶은 것은 어느 것인가요?',ARRAY['K6-1-u6-X23','K6-1-u6-X03','K6-1-u6-X07']::text[],false,'{"seq":1,"concept":"K6-1-u6-C3","difficulty":1,"kind":"mc","stem":"판단하며 읽기의 두 갈래로 알맞게 묶은 것은 어느 것인가요?","options":[{"t":"내용의 타당성 · 표현의 적절성","correct":true},{"t":"글의 길이 · 글씨의 크기","mis":"K6-1-u6-X23"},{"t":"제목 · 그림","mis":"K6-1-u6-X03"},{"t":"서론 · 결론","mis":"K6-1-u6-X07"}],"explanation":["길이와 크기는 갈래가 아니에요.","제목과 그림만이 아니에요.","무엇을 · 어떻게 말하는가예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#2','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C12',1,'mc','auto','근거가 갖추어야 할 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X12','K6-1-u6-X07','K6-1-u6-X19']::text[],false,'{"seq":2,"concept":"K6-1-u6-C12","difficulty":1,"kind":"mc","stem":"근거가 갖추어야 할 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"이유와 관련이 있고 객관적인 사실이나 정보를 활용한다","correct":true},{"t":"글쓴이의 짐작을 담는다","mis":"K6-1-u6-X12"},{"t":"주장을 한 번 더 말한다","mis":"K6-1-u6-X07"},{"t":"전해 들은 말을 옮긴다","mis":"K6-1-u6-X19"}],"explanation":["짐작은 근거가 못 돼요.","주장을 되풀이하는 건 근거가 아니에요.","확인할 수 있는 사실이어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#3','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C13',1,'ox','auto','알림글이나 설명하는 글에도 타당성을 물어볼 수 있어요.',ARRAY['K6-1-u6-X13']::text[],false,'{"seq":3,"concept":"K6-1-u6-C13","difficulty":1,"kind":"ox","stem":"알림글이나 설명하는 글에도 타당성을 물어볼 수 있어요.","answer":"O","reason_options":[{"t":"내용을 담은 글이면 어디에든 같은 물음을 댈 수 있기 때문에","correct":true},{"t":"주장하는 글에서만 잴 수 있기 때문에","mis":"K6-1-u6-X13"}],"mis":"K6-1-u6-X13","explanation":["주장하는 글만이 아니에요.","내용을 담은 글이면 돼요.","어디에나 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#4','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C26',1,'mc','auto','있는 것을 실제보다 부풀린 표현을 무엇이라고 하나요?',ARRAY['K6-1-u6-X25','K6-1-u6-X27','K6-1-u6-X34']::text[],false,'{"seq":4,"concept":"K6-1-u6-C26","difficulty":1,"kind":"mc","stem":"있는 것을 실제보다 부풀린 표현을 무엇이라고 하나요?","options":[{"t":"과장된 표현","correct":true},{"t":"거짓된 표현","mis":"K6-1-u6-X25"},{"t":"감추는 내용","mis":"K6-1-u6-X27"},{"t":"알맞은 표현","mis":"K6-1-u6-X34"}],"explanation":["기능이 있으면 거짓이 아니에요.","감춤과 달라요.","부풀리면 과장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#5','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C28',1,'mc','auto','거짓과 과장을 가르는 물음으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X24','K6-1-u6-X25','K6-1-u6-X23']::text[],false,'{"seq":5,"concept":"K6-1-u6-C28","difficulty":1,"kind":"mc","stem":"거짓과 과장을 가르는 물음으로 알맞은 것은 어느 것인가요?","options":[{"t":"「그 기능이 실제로 있는가?」","correct":true},{"t":"「글씨가 큰가?」","mis":"K6-1-u6-X24"},{"t":"「값이 싼가?」","mis":"K6-1-u6-X25"},{"t":"「그림이 예쁜가?」","mis":"K6-1-u6-X23"}],"explanation":["크기로 가르지 않아요.","값과 관계없어요.","기능이 있는지로 갈라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#6','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C34',1,'mc','auto','설명하는 글에서 「대부분 · 모두 · 언제나」가 나오면 할 일은 어느 것인가요?',ARRAY['K6-1-u6-X33','K6-1-u6-X26','K6-1-u6-X31']::text[],false,'{"seq":6,"concept":"K6-1-u6-C34","difficulty":1,"kind":"mc","stem":"설명하는 글에서 「대부분 · 모두 · 언제나」가 나오면 할 일은 어느 것인가요?","options":[{"t":"그렇게 넓게 말할 만한 사실인지 멈추어 묻는다","correct":true},{"t":"그냥 지나친다","mis":"K6-1-u6-X33"},{"t":"더 넓게 「세상 모든」으로 바꾼다","mis":"K6-1-u6-X26"},{"t":"그 문장을 외운다","mis":"K6-1-u6-X31"}],"explanation":["멈춰 봐요.","더 부풀리면 안 돼요.","넓게 말할 만한지 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#7','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C44',1,'mc','auto','광고에서 크게 쓸 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X43']::text[],false,'{"seq":7,"concept":"K6-1-u6-C44","difficulty":1,"kind":"mc","stem":"광고에서 크게 쓸 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"가장 하고 싶은 한 줄","correct":true},{"t":"모든 줄","mis":"K6-1-u6-X43"},{"t":"꼭 알려야 할 조건만 아주 작게","mis":"K6-1-u6-X43"},{"t":"아무 줄이나","mis":"K6-1-u6-X43"}],"explanation":["다 크면 아무것도 크지 않아요.","조건은 읽을 수 있게 적어요.","한 줄만 크게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#8','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C48',1,'mc','auto','「퍼즐 조각을 서로 (　) 보았다」의 빈칸에 알맞은 낱말은 어느 것인가요?',ARRAY['K6-1-u6-X47']::text[],false,'{"seq":8,"concept":"K6-1-u6-C48","difficulty":1,"kind":"mc","stem":"「퍼즐 조각을 서로 (　) 보았다」의 빈칸에 알맞은 낱말은 어느 것인가요?","options":[{"t":"맞추어","correct":true},{"t":"맞히어","mis":"K6-1-u6-X47"},{"t":"늘이어","mis":"K6-1-u6-X47"},{"t":"좇아","mis":"K6-1-u6-X47"}],"explanation":["답을 옳게 대는 뜻이에요.","길게 하는 뜻이에요.","서로 대어 보면 「맞추다」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#9','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C11',2,'mc','auto','담희 글에서 주장과 어긋나는 이유는 어느 것인가요?',ARRAY['K6-1-u6-X05','K6-1-u6-X07']::text[],false,'{"seq":9,"concept":"K6-1-u6-C11","difficulty":2,"kind":"mc","stem":"담희 글에서 주장과 어긋나는 이유는 어느 것인가요?","options":[{"t":"창문을 닫아 두면 바깥 소리가 들어오지 않아 수업에 마음을 모을 수 있다","correct":true},{"t":"바깥 공기가 들어와 교실 공기가 바뀐다","mis":"K6-1-u6-X05"},{"t":"셋째 시간이 끝날 무렵 교실 공기가 답답해진다","mis":"K6-1-u6-X07"},{"t":"추운 날에는 잠깐만 열어도 된다","mis":"K6-1-u6-X05"}],"explanation":["주장과 이어지는 이유예요.","문제를 꺼낸 서론이에요.","닫자는 쪽을 가리켜 어긋나요 — 열자는 주장 편으로 고쳐야 해요."],"asset":{"type":"passage","lines":["① 셋째 시간이 끝날 무렵이면 교실 공기가 답답해집니다.","쉬는 시간마다 창문을 열어 두면 좋겠습니다.","② 첫째, 바깥 공기가 들어와 교실 공기가 바뀝니다. 우리 반이 일주일 동안","쉬는 시간마다 창문을 열어 보니, 「답답하다」고 적은 친구가 날마다 줄었습니다.","③ 둘째, 창문을 닫아 두면 바깥 소리가 들어오지 않아 수업에 마음을 모을 수 있습니다."],"title":"담희의 글 「쉬는 시간마다 창문을 열어 둡시다」 — 앞부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#10','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C19',2,'mc','auto','「옆 반 친구가 그렇게 말해 주었습니다」가 근거로 알맞지 않은 까닭은 어느 것인가요?',ARRAY['K6-1-u6-X19','K6-1-u6-X08']::text[],false,'{"seq":10,"concept":"K6-1-u6-C19","difficulty":2,"kind":"mc","stem":"「옆 반 친구가 그렇게 말해 주었습니다」가 근거로 알맞지 않은 까닭은 어느 것인가요?","options":[{"t":"한 사람에게서 전해 들은 말이라 누구도 다시 확인할 수 없기 때문이다","correct":true},{"t":"옆 반 친구는 어리기 때문이다","mis":"K6-1-u6-X19"},{"t":"근거가 너무 길기 때문이다","mis":"K6-1-u6-X08"},{"t":"친구 이름을 밝히지 않았기 때문이다","mis":"K6-1-u6-X19"}],"explanation":["나이 문제가 아니에요.","길이 문제가 아니에요.","이름을 밝혀도 전해 들은 말이에요 — 확인할 수 있는 근거로 바꿔요. (바로잡기: 창문을 열어도 감기에 걸릴 수 있어요.) (바로잡기: 창문을 열어도 해결 안 되는 문제가 있어요.)"],"asset":{"type":"passage","lines":["④ 셋째, 창문을 열어 두면 감기에 걸리지 않습니다.","옆 반 친구가 그렇게 말해 주었습니다.","⑤ 창문만 열면 교실의 모든 문제가 사라집니다.","⑥ 추운 날에는 잠깐만 열어도 됩니다. 쉬는 시간마다 창문을 열어 둡시다."],"title":"담희의 글 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#11','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C26',2,'mc','auto','「영원히 마르지 않는 잉크!」가 걸리는 기준과 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X25','K6-1-u6-X17','K6-1-u6-X27']::text[],false,'{"seq":11,"concept":"K6-1-u6-C26","difficulty":2,"kind":"mc","stem":"「영원히 마르지 않는 잉크!」가 걸리는 기준과 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"과장 — 잘 마르지 않게 만든 것은 맞지만 어떤 경우에도 그렇다고 부풀렸다","correct":true},{"t":"거짓 — 잉크가 아예 없다","mis":"K6-1-u6-X25"},{"t":"알맞음 — 광고에 적혀 있다","mis":"K6-1-u6-X17"},{"t":"감춤 — 색을 밝히지 않았다","mis":"K6-1-u6-X27"}],"explanation":["기능은 있어요.","적혀 있다는 건 까닭이 아니에요.","있는 기능을 부풀렸어요 — 작은 글씨가 마를 수 있다고 밝혀요. (바로잡기: 형광펜에는 공부를 대신해 주는 기능이 없어요.)"],"asset":{"type":"passage","lines":["장면 ① 형광펜을 든 아이가 웃는 큰 그림 「공부가 저절로 되는 형광펜!」","장면 ② 「다섯 가지 색이 한 묶음」 「뚜껑을 닫아 두면 잘 마르지 않아요.」","장면 ③ 금빛 딱지 「세상에서 가장 밝은 색! 가장 많이 팔린 형광펜!」","장면 ④ 「영원히 마르지 않는 잉크!」","　　(아주 작은 글씨) ※ 뚜껑을 열어 두면 금방 마를 수 있음."],"title":"형광펜 광고 「쓱쓱 형광펜」 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#12','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C24',2,'mc','auto','형광펜 광고가 「※ 뚜껑을 열어 두면 금방 마를 수 있음」을 아주 작게 적은 것을 바르게 판단한 것은 어느 것인가요?',ARRAY['K6-1-u6-X15','K6-1-u6-X27','K6-1-u6-X24']::text[],false,'{"seq":12,"concept":"K6-1-u6-C24","difficulty":2,"kind":"mc","stem":"형광펜 광고가 「※ 뚜껑을 열어 두면 금방 마를 수 있음」을 아주 작게 적은 것을 바르게 판단한 것은 어느 것인가요?","options":[{"t":"꼭 알아야 할 조건을 눈에 들어오지 않게 적어, 「영원히 마르지 않는」과 함께 보면 감추는 내용에 가깝다","correct":true},{"t":"작은 글씨는 안 읽어도 된다","mis":"K6-1-u6-X15"},{"t":"적었으니 아무 문제가 없다","mis":"K6-1-u6-X27"},{"t":"실수로 작게 썼을 뿐이다","mis":"K6-1-u6-X24"}],"explanation":["조건이 거기 있어요.","읽을 수 있는 크기여야 해요.","작게 쓴 것도 뜻이 있어요."],"asset":{"type":"passage","lines":["장면 ① 형광펜을 든 아이가 웃는 큰 그림 「공부가 저절로 되는 형광펜!」","장면 ② 「다섯 가지 색이 한 묶음」 「뚜껑을 닫아 두면 잘 마르지 않아요.」","장면 ③ 금빛 딱지 「세상에서 가장 밝은 색! 가장 많이 팔린 형광펜!」","장면 ④ 「영원히 마르지 않는 잉크!」","　　(아주 작은 글씨) ※ 뚜껑을 열어 두면 금방 마를 수 있음."],"title":"형광펜 광고 「쓱쓱 형광펜」 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#13','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C35',2,'mc','auto','갯벌 글에서 과장된 표현은 어느 것인가요?',ARRAY['K6-1-u6-X28','K6-1-u6-X05']::text[],false,'{"seq":13,"concept":"K6-1-u6-C35","difficulty":2,"kind":"mc","stem":"갯벌 글에서 과장된 표현은 어느 것인가요?","options":[{"t":"갯벌 생물은 아무리 많이 잡아도 절대 줄어들지 않습니다","correct":true},{"t":"갯벌은 언제든 걸어 들어가 놀아도 좋습니다","mis":"K6-1-u6-X28"},{"t":"갯벌을 보면 살림터를 알 수 있습니다","mis":"K6-1-u6-X05"},{"t":"갯벌 생물이 바닷물을 깨끗하게 하는 데 도움을 줍니다","mis":"K6-1-u6-X05"}],"explanation":["이건 감추는 내용이에요.","글쓴이의 정리예요.","지나치게 잡으면 줄어들어요 — 바르게는 「알맞게 잡으면 다시 늘어날 수 있습니다」예요. (바로잡기: 우리나라에는 모래 바닷가 · 바위 바닷가도 있어요.) (바로잡기: 바닷물이 들어오는 때에는 갯벌에 들어가면 위험해요.)"],"asset":{"type":"passage","lines":["④ 갯벌은 언제든 걸어 들어가 놀아도 좋습니다.","⑤ 갯벌 생물은 아무리 많이 잡아도 절대 줄어들지 않습니다.","요즘 우리나라 바닷가는 모두 갯벌로 이루어져 있습니다.","⑥ 갯벌을 보면 바다와 땅이 함께 만든 살림터를 알 수 있습니다."],"title":"「바다와 땅 사이, 갯벌」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#14','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C38',2,'mc','auto','갯벌 글을 읽고 다른 관점에서 세울 물음으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X36','K6-1-u6-X31']::text[],false,'{"seq":14,"concept":"K6-1-u6-C38","difficulty":2,"kind":"mc","stem":"갯벌 글을 읽고 다른 관점에서 세울 물음으로 알맞은 것은 어느 것인가요?","options":[{"t":"「갯벌이 줄어들면 어떤 일이 생길까?」","correct":true},{"t":"「갯벌은 왜 이렇게 좋을까?」","mis":"K6-1-u6-X36"},{"t":"「이 글만 읽으면 충분하겠지?」","mis":"K6-1-u6-X36"},{"t":"「이 글을 다 외웠을까?」","mis":"K6-1-u6-X31"}],"explanation":["같은 쪽의 물음이에요.","한 편만 읽고 끝내지 않아요.","다른 쪽에서 물었어요 — 관련 글을 더 찾아 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#15','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C40',2,'mc','auto','도율이가 초안을 스스로 검사할 때 쓸 물음으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X23','K6-1-u6-X42','K6-1-u6-X38']::text[],false,'{"seq":15,"concept":"K6-1-u6-C40","difficulty":2,"kind":"mc","stem":"도율이가 초안을 스스로 검사할 때 쓸 물음으로 알맞은 것은 어느 것인가요?","options":[{"t":"「없는 것을 있다고 했는가 · 부풀렸는가 · 감추었는가?」","correct":true},{"t":"「글씨가 예쁜가?」","mis":"K6-1-u6-X23"},{"t":"「남의 광고보다 센가?」","mis":"K6-1-u6-X42"},{"t":"「내 광고니까 괜찮은가?」","mis":"K6-1-u6-X38"}],"explanation":["겉모습이 아니에요.","세기를 겨루지 않아요.","읽을 때의 자를 만들 때도 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#16','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C6',2,'mc','auto','담희가 도율이에게 「까닭을 말해 줄래?」라고 한 까닭은 어느 것인가요?',ARRAY['K6-1-u6-X45','K6-1-u6-X06','K6-1-u6-X21']::text[],false,'{"seq":16,"concept":"K6-1-u6-C6","difficulty":2,"kind":"mc","stem":"담희가 도율이에게 「까닭을 말해 줄래?」라고 한 까닭은 어느 것인가요?","options":[{"t":"까닭 없는 판단으로는 어디를 어떻게 고칠지 알 수 없기 때문이다","correct":true},{"t":"도율이를 이기고 싶기 때문이다","mis":"K6-1-u6-X45"},{"t":"「별로야」만으로 충분하기 때문이다","mis":"K6-1-u6-X06"},{"t":"⑤문단을 버리고 싶기 때문이다","mis":"K6-1-u6-X21"}],"explanation":["이기려는 게 아니에요.","까닭이 있어야 해요.","판단은 결과와 근거가 한 짝이에요."],"asset":{"type":"speech","turns":[{"who":"도율","text":"담희 글에 이상한 데가 세 군데나 있어. 이 글은 다 버리는 게 낫겠다."},{"who":"담희","text":"걸린 곳만 짚어 줘. 창문을 열자는 주장과 직접 센 기록도 틀렸어?"},{"who":"도율","text":"그건 아니야. 그리고 ⑤문단은 그냥 별로야."},{"who":"담희","text":"별로라고만 하면 어디를 고칠지 모르겠어. 왜 걸리는지 까닭을 말해 줄래?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#17','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C21',3,'mc','auto','담희 글에서 받아들여도 좋은 부분만 모은 것은 어느 것인가요?',ARRAY['K6-1-u6-X11','K6-1-u6-X21','K6-1-u6-X01']::text[],false,'{"seq":17,"concept":"K6-1-u6-C21","difficulty":3,"kind":"mc","stem":"담희 글에서 받아들여도 좋은 부분만 모은 것은 어느 것인가요?","options":[{"t":"창문을 열자는 주장 · 공기가 바뀐다는 이유 · 일주일 동안 적은 기록","correct":true},{"t":"창문을 닫으면 조용하다는 이유 · 옆 반 친구의 말","mis":"K6-1-u6-X11"},{"t":"받아들일 것이 하나도 없다","mis":"K6-1-u6-X21"},{"t":"글의 모든 문장","mis":"K6-1-u6-X01"}],"explanation":["걸린 곳들이에요.","걸린 곳만 짚어요.","걸린 곳을 빼고 골라냈어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#18','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C27',3,'mc','auto','「가장 많이 팔린 형광펜!」을 감춘 것 없이 고친 것은 어느 것인가요?',ARRAY['K6-1-u6-X27','K6-1-u6-X26']::text[],false,'{"seq":18,"concept":"K6-1-u6-C27","difficulty":3,"kind":"mc","stem":"「가장 많이 팔린 형광펜!」을 감춘 것 없이 고친 것은 어느 것인가요?","options":[{"t":"지난달 우리 학교 앞 문구점에서 형광펜 가운데 가장 많이 팔렸어요","correct":true},{"t":"정말 가장 많이 팔린 형광펜!","mis":"K6-1-u6-X27"},{"t":"세상에서 가장 많이 팔린 형광펜!","mis":"K6-1-u6-X26"},{"t":"누구나 아는 그 형광펜!","mis":"K6-1-u6-X27"}],"explanation":["언제 · 어디인지 여전히 없어요.","더 넓게 부풀렸어요.","언제 · 어디에서를 밝혔어요."],"asset":{"type":"passage","lines":["장면 ① 형광펜을 든 아이가 웃는 큰 그림 「공부가 저절로 되는 형광펜!」","장면 ② 「다섯 가지 색이 한 묶음」 「뚜껑을 닫아 두면 잘 마르지 않아요.」","장면 ③ 금빛 딱지 「세상에서 가장 밝은 색! 가장 많이 팔린 형광펜!」","장면 ④ 「영원히 마르지 않는 잉크!」","　　(아주 작은 글씨) ※ 뚜껑을 열어 두면 금방 마를 수 있음."],"title":"형광펜 광고 「쓱쓱 형광펜」 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#19','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C36',3,'mc','auto','갯벌 글 문단 ④를 읽고 남는 「되묻고 싶은 것」으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X27']::text[],false,'{"seq":19,"concept":"K6-1-u6-C36","difficulty":3,"kind":"mc","stem":"갯벌 글 문단 ④를 읽고 남는 「되묻고 싶은 것」으로 알맞은 것은 어느 것인가요?","options":[{"t":"「바닷물이 들어올 때에도 괜찮을까?」","correct":true},{"t":"「갯벌은 넓을까?」","mis":"K6-1-u6-X27"},{"t":"「게는 어디에 살까?」","mis":"K6-1-u6-X27"},{"t":"「되물을 것이 없다.」","mis":"K6-1-u6-X27"}],"explanation":["앞에서 밝혔어요.","문단 ②에 있어요.","그 물음이 감춘 것을 가리켜요."],"asset":{"type":"passage","lines":["④ 갯벌은 언제든 걸어 들어가 놀아도 좋습니다.","⑤ 갯벌 생물은 아무리 많이 잡아도 절대 줄어들지 않습니다.","요즘 우리나라 바닷가는 모두 갯벌로 이루어져 있습니다.","⑥ 갯벌을 보면 바다와 땅이 함께 만든 살림터를 알 수 있습니다."],"title":"「바다와 땅 사이, 갯벌」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#20','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C45',3,'mc','auto','도율이가 발표할 때 밝힐 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X44','K6-1-u6-X42']::text[],false,'{"seq":20,"concept":"K6-1-u6-C45","difficulty":3,"kind":"mc","stem":"도율이가 발표할 때 밝힐 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「수돗가에서 물이 그냥 흐르는 것을 보고 골랐어요. 그림의 물줄기를 일부러 크게 그린 까닭은 낭비를 한눈에 보여 주고 싶어서예요.」","correct":true},{"t":"「광고를 만들었어요. 끝.」","mis":"K6-1-u6-X44"},{"t":"「세게 쓴 곳은 말하지 않을게요.」","mis":"K6-1-u6-X42"},{"t":"「제 광고가 반에서 제일 나아요.」","mis":"K6-1-u6-X44"}],"explanation":["만든 뜻이 빠졌어요.","숨기면 속이는 셈이에요.","고른 까닭 · 강조한 것 · 세게 그린 까닭을 밝혔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#21','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C3',3,'mc','auto','광고 · 주장하는 글 · 설명하는 글에 모두 댈 수 있는 것은 어느 것인가요?',ARRAY['K6-1-u6-X29','K6-1-u6-X13','K6-1-u6-X23']::text[],false,'{"seq":21,"concept":"K6-1-u6-C3","difficulty":3,"kind":"mc","stem":"광고 · 주장하는 글 · 설명하는 글에 모두 댈 수 있는 것은 어느 것인가요?","options":[{"t":"내용의 타당성 세 물음과 표현의 적절성 세 물음","correct":true},{"t":"광고에만 쓰는 세 물음","mis":"K6-1-u6-X29"},{"t":"주장하는 글에만 쓰는 세 물음","mis":"K6-1-u6-X13"},{"t":"글씨 크기를 재는 자","mis":"K6-1-u6-X23"}],"explanation":["광고만의 일이 아니에요.","주장하는 글만도 아니에요.","여섯 물음은 어디에나 대요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#22','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C49',3,'mc','auto','맞춤법이 모두 바른 문장은 어느 것인가요?',ARRAY['K6-1-u6-X48']::text[],false,'{"seq":22,"concept":"K6-1-u6-C49","difficulty":3,"kind":"mc","stem":"맞춤법이 모두 바른 문장은 어느 것인가요?","options":[{"t":"며칠 아팠는데 이제 다 나았어요.","correct":true},{"t":"몇일 아팠는데 이제 다 나았어요.","mis":"K6-1-u6-X48"},{"t":"며칠 아팠는데 이제 다 낳았어요.","mis":"K6-1-u6-X48"},{"t":"몇일 아팠는데 이제 다 낳았어요.","mis":"K6-1-u6-X48"}],"explanation":["「며칠」이에요.","병은 「나았다」예요.","둘 다 바르게 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#23','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C47',4,'mc','auto','형광펜 광고 전체를 가장 알맞게 평가한 것은 어느 것인가요?',ARRAY['K6-1-u6-X29','K6-1-u6-X21','K6-1-u6-X28']::text[],false,'{"seq":23,"concept":"K6-1-u6-C47","difficulty":4,"kind":"mc","stem":"형광펜 광고 전체를 가장 알맞게 평가한 것은 어느 것인가요?","options":[{"t":"「다섯 가지 색」 · 「닫아 두면 잘 마르지 않음」은 알맞지만, 거짓 하나(공부가 저절로) · 과장(가장 밝은 · 영원히) · 감춤(가장 많이 팔린 · 작은 글씨)이 있다","correct":true},{"t":"광고는 원래 그러니 따질 것이 없다","mis":"K6-1-u6-X29"},{"t":"걸린 곳이 있으니 모든 문구가 엉터리다","mis":"K6-1-u6-X21"},{"t":"과장만 있고 거짓과 감춤은 없다","mis":"K6-1-u6-X28"}],"explanation":["광고도 따져요.","알맞은 문구도 있어요.","세 기준 모두에 걸린 곳이 있어요."],"asset":{"type":"passage","lines":["장면 ① 형광펜을 든 아이가 웃는 큰 그림 「공부가 저절로 되는 형광펜!」","장면 ② 「다섯 가지 색이 한 묶음」 「뚜껑을 닫아 두면 잘 마르지 않아요.」","장면 ③ 금빛 딱지 「세상에서 가장 밝은 색! 가장 많이 팔린 형광펜!」","장면 ④ 「영원히 마르지 않는 잉크!」","　　(아주 작은 글씨) ※ 뚜껑을 열어 두면 금방 마를 수 있음."],"title":"형광펜 광고 「쓱쓱 형광펜」 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#24','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C29',4,'essay','teacher','형광펜 광고에서 두 기준에 함께 걸리는 문구를 하나 찾아 두 기준과 까닭을 쓰고, 알맞게 고쳐 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u6-C29","difficulty":4,"kind":"essay","stem":"형광펜 광고에서 두 기준에 함께 걸리는 문구를 하나 찾아 두 기준과 까닭을 쓰고, 알맞게 고쳐 쓰세요.","answer_guide":{"answer":"예: 「세상에서 가장 밝은 색!」은 과장이다. 형광펜의 색이 밝기는 해도 세상에서 가장 밝다고 부풀렸다. 동시에 감추는 내용도 있다. 무엇과 견주어 가장 밝은지 밝히지 않았다. 고쳐 쓰면 — 「어두운 글씨 위에서도 잘 보이는 밝은 색」.","scoring_points":["두 기준에 걸리는 문구를 찾았는가","두 기준과 까닭을 썼는가","알맞게 고쳐 썼는가"]},"explanation":["한 기준에서 멈추지 말아요.","기준마다 까닭을 대요.","덜어 내고 밝혀요."],"asset":{"type":"passage","lines":["장면 ① 형광펜을 든 아이가 웃는 큰 그림 「공부가 저절로 되는 형광펜!」","장면 ② 「다섯 가지 색이 한 묶음」 「뚜껑을 닫아 두면 잘 마르지 않아요.」","장면 ③ 금빛 딱지 「세상에서 가장 밝은 색! 가장 많이 팔린 형광펜!」","장면 ④ 「영원히 마르지 않는 잉크!」","　　(아주 작은 글씨) ※ 뚜껑을 열어 두면 금방 마를 수 있음."],"title":"형광펜 광고 「쓱쓱 형광펜」 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#25','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C5',4,'essay','teacher','「비판적으로 읽기는 흠을 잡는 일이 아니다」라는 말의 뜻을, 이 단원에서 읽은 글 하나를 예로 들어 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u6-C5","difficulty":4,"kind":"essay","stem":"「비판적으로 읽기는 흠을 잡는 일이 아니다」라는 말의 뜻을, 이 단원에서 읽은 글 하나를 예로 들어 설명하세요.","answer_guide":{"answer":"예: 안전모 글에는 「더 빨리 달린다」와 「옆집 형의 말」처럼 걸린 곳이 두 군데 있었다. 그렇다고 글 전체를 버리지 않고, 안전모를 쓰자는 주장과 머리를 지켜 준다는 이유, 직접 센 기록은 받아들였다. 비판적으로 읽는다는 것은 틀린 곳을 많이 찾는 것이 아니라 받아들일 것과 물릴 것을 까닭을 대어 스스로 가르는 일이다.","scoring_points":["단원의 글 하나를 예로 들었는가","받아들인 것과 짚은 것을 나누었는가","흠 잡기가 아닌 까닭을 정리했는가"]},"explanation":["읽은 글을 떠올려요.","받아들인 것도 써요.","골라내는 읽기로 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#1','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C5',1,'ox','auto','비판적으로 읽는 목적은 글을 깎아내리는 거예요.',ARRAY['K6-1-u6-X05']::text[],false,'{"seq":1,"concept":"K6-1-u6-C5","difficulty":1,"kind":"ox","stem":"비판적으로 읽는 목적은 글을 깎아내리는 거예요.","answer":"X","reason_options":[{"t":"맞는 곳은 받아들이고 나에게 필요한 정보를 골라내는 것이 목적이기 때문에","correct":true},{"t":"흠을 찾아내야 잘 읽은 것이기 때문에","mis":"K6-1-u6-X05"}],"mis":"K6-1-u6-X05","explanation":["깎아내리기가 아니에요.","트집이 목적이 아니에요.","골라내는 읽기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#2','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C10',1,'ox','auto','맞는 말이면 주장과 관련이 없어도 이유가 돼요.',ARRAY['K6-1-u6-X10']::text[],false,'{"seq":2,"concept":"K6-1-u6-C10","difficulty":1,"kind":"ox","stem":"맞는 말이면 주장과 관련이 없어도 이유가 돼요.","answer":"X","reason_options":[{"t":"이유는 주장과 관련이 있어야 주장을 뒷받침할 수 있기 때문에","correct":true},{"t":"참인 문장은 모두 이유로 쓸 수 있기 때문에","mis":"K6-1-u6-X10"}],"mis":"K6-1-u6-X10","explanation":["참이어도 관련이 있어야 해요.","주장과 이어져야 해요.","참인 문장이라고 다 이유는 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#3','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C14',1,'mc','auto','판단 기준에 대한 생각으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X14','K6-1-u6-X06','K6-1-u6-X05']::text[],false,'{"seq":3,"concept":"K6-1-u6-C14","difficulty":1,"kind":"mc","stem":"판단 기준에 대한 생각으로 알맞은 것은 어느 것인가요?","options":[{"t":"세 기준 말고도 알맞은 기준을 물음의 꼴로 스스로 세워 쓸 수 있다","correct":true},{"t":"기준은 정해진 세 가지뿐이다","mis":"K6-1-u6-X14"},{"t":"기준은 그날 기분에 따라 정한다","mis":"K6-1-u6-X06"},{"t":"기준이 많을수록 흠을 많이 찾아 좋다","mis":"K6-1-u6-X05"}],"explanation":["더 세워도 좋아요.","기분은 기준이 아니에요.","흠 찾기가 목적이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#4','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C27',1,'mc','auto','알아야 할 것을 밝히지 않은 것을 무엇이라고 하나요?',ARRAY['K6-1-u6-X27','K6-1-u6-X14']::text[],false,'{"seq":4,"concept":"K6-1-u6-C27","difficulty":1,"kind":"mc","stem":"알아야 할 것을 밝히지 않은 것을 무엇이라고 하나요?","options":[{"t":"감추는 내용","correct":true},{"t":"거짓된 표현","mis":"K6-1-u6-X27"},{"t":"과장된 표현","mis":"K6-1-u6-X27"},{"t":"스스로 세운 기준","mis":"K6-1-u6-X14"}],"explanation":["틀린 말은 없을 수 있어요.","부풀린 것도 아니에요.","빼놓으면 감춤이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#5','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C15',1,'ox','auto','포장에 크게 적힌 말만 읽으면 물건을 다 안 거예요.',ARRAY['K6-1-u6-X15']::text[],false,'{"seq":5,"concept":"K6-1-u6-C15","difficulty":1,"kind":"ox","stem":"포장에 크게 적힌 말만 읽으면 물건을 다 안 거예요.","answer":"X","reason_options":[{"t":"작은 글씨나 뒷부분에 조건이 적혀 있을 수 있어 한 번 더 확인해야 하기 때문에","correct":true},{"t":"큰 글씨에 모든 것이 적혀 있기 때문에","mis":"K6-1-u6-X15"}],"mis":"K6-1-u6-X15","explanation":["작은 글씨도 읽어요.","뒷부분까지 봐요.","한 번 더 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#6','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C35',1,'ox','auto','과장된 표현은 거짓말이 아니라서 더 알아채기 어려워요.',ARRAY['K6-1-u6-X34']::text[],false,'{"seq":6,"concept":"K6-1-u6-C35","difficulty":1,"kind":"ox","stem":"과장된 표현은 거짓말이 아니라서 더 알아채기 어려워요.","answer":"O","reason_options":[{"t":"있는 것을 부풀린 말이라 읽는 사람이 지나치게 믿게 되기 때문에","correct":true},{"t":"과장은 아무 문제가 없는 표현이기 때문에","mis":"K6-1-u6-X34"}],"mis":"K6-1-u6-X34","explanation":["문제가 있어요.","지나친 믿음을 남겨요.","그래서 더 조심해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#7','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C40',1,'ox','auto','남의 글에서 찾아낸 흠은 내가 만든 글에서도 흠이에요.',ARRAY['K6-1-u6-X38']::text[],false,'{"seq":7,"concept":"K6-1-u6-C40","difficulty":1,"kind":"ox","stem":"남의 글에서 찾아낸 흠은 내가 만든 글에서도 흠이에요.","answer":"O","reason_options":[{"t":"읽을 때 걸렸던 것들이 만들 때 하지 말아야 할 것이 되기 때문에","correct":true},{"t":"내 글은 내가 만들었으니 괜찮기 때문에","mis":"K6-1-u6-X38"}],"mis":"K6-1-u6-X38","explanation":["내 글도 같은 자로 재요.","자를 뒤집어 들어요.","똑같이 흠이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#8','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C49',1,'mc','auto','「몇 날」을 뜻하는 말을 바르게 쓴 것은 어느 것인가요?',ARRAY['K6-1-u6-X48']::text[],false,'{"seq":8,"concept":"K6-1-u6-C49","difficulty":1,"kind":"mc","stem":"「몇 날」을 뜻하는 말을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"며칠","correct":true},{"t":"몇일","mis":"K6-1-u6-X48"},{"t":"몇 일","mis":"K6-1-u6-X48"},{"t":"멷일","mis":"K6-1-u6-X48"}],"explanation":["한 낱말로 「며칠」이에요.","띄어 쓰지 않아요.","몇 날을 뜻하는 「며칠」이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#9','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C18',2,'mc','auto','담희 글 문단 ④의 이유가 걸리는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X10','K6-1-u6-X08','K6-1-u6-X18']::text[],false,'{"seq":9,"concept":"K6-1-u6-C18","difficulty":2,"kind":"mc","stem":"담희 글 문단 ④의 이유가 걸리는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"창문을 열어도 감기에 걸릴 수 있어 사실이 아니기 때문이다","correct":true},{"t":"창문 이야기가 아니기 때문이다","mis":"K6-1-u6-X10"},{"t":"문단이 짧기 때문이다","mis":"K6-1-u6-X08"},{"t":"감기는 누구나 알기 때문이다","mis":"K6-1-u6-X18"}],"explanation":["창문 이야기가 맞아요.","길이 문제가 아니에요.","실제로 일어나지 않는 일이에요 — 바르게는 「바깥 공기가 들어와 답답함이 줄어듭니다」처럼 말해요."],"asset":{"type":"passage","lines":["④ 셋째, 창문을 열어 두면 감기에 걸리지 않습니다.","옆 반 친구가 그렇게 말해 주었습니다.","⑤ 창문만 열면 교실의 모든 문제가 사라집니다.","⑥ 추운 날에는 잠깐만 열어도 됩니다. 쉬는 시간마다 창문을 열어 둡시다."],"title":"담희의 글 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#10','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C16',2,'mc','auto','「「답답하다」고 적은 친구가 날마다 줄었다」는 어느 이유를 받치나요?',ARRAY['K6-1-u6-X16']::text[],false,'{"seq":10,"concept":"K6-1-u6-C16","difficulty":2,"kind":"mc","stem":"「「답답하다」고 적은 친구가 날마다 줄었다」는 어느 이유를 받치나요?","options":[{"t":"바깥 공기가 들어와 교실 공기가 바뀐다","correct":true},{"t":"창문을 닫으면 조용하다","mis":"K6-1-u6-X16"},{"t":"감기에 걸리지 않는다","mis":"K6-1-u6-X16"},{"t":"모든 문제가 사라진다","mis":"K6-1-u6-X16"}],"explanation":["반대 쪽 이유예요.","사실이 아닌 이유예요.","같은 문단 ② 안에서 짝을 찾아요."],"asset":{"type":"passage","lines":["① 셋째 시간이 끝날 무렵이면 교실 공기가 답답해집니다.","쉬는 시간마다 창문을 열어 두면 좋겠습니다.","② 첫째, 바깥 공기가 들어와 교실 공기가 바뀝니다. 우리 반이 일주일 동안","쉬는 시간마다 창문을 열어 보니, 「답답하다」고 적은 친구가 날마다 줄었습니다.","③ 둘째, 창문을 닫아 두면 바깥 소리가 들어오지 않아 수업에 마음을 모을 수 있습니다."],"title":"담희의 글 「쉬는 시간마다 창문을 열어 둡시다」 — 앞부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#11','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C28',2,'mc','auto','「공부가 저절로 되는」은 거짓, 「영원히 마르지 않는」은 과장으로 가른 까닭은 어느 것인가요?',ARRAY['K6-1-u6-X24','K6-1-u6-X23','K6-1-u6-X25']::text[],false,'{"seq":11,"concept":"K6-1-u6-C28","difficulty":2,"kind":"mc","stem":"「공부가 저절로 되는」은 거짓, 「영원히 마르지 않는」은 과장으로 가른 까닭은 어느 것인가요?","options":[{"t":"앞은 형광펜에 없는 기능이고, 뒤는 있는 기능(잘 마르지 않음)을 부풀렸기 때문이다","correct":true},{"t":"앞의 글씨가 더 크기 때문이다","mis":"K6-1-u6-X24"},{"t":"뒤에 느낌표가 있기 때문이다","mis":"K6-1-u6-X23"},{"t":"둘 다 같은 것이기 때문이다","mis":"K6-1-u6-X25"}],"explanation":["크기로 가르지 않아요.","느낌표와 관계없어요.","기능이 실제로 있는지로 갈라요. (바로잡기: 형광펜에는 공부를 대신해 주는 기능이 없어요.) (바로잡기: 뚜껑을 열어 두면 잉크는 마를 수 있어요.)"],"asset":{"type":"passage","lines":["장면 ① 형광펜을 든 아이가 웃는 큰 그림 「공부가 저절로 되는 형광펜!」","장면 ② 「다섯 가지 색이 한 묶음」 「뚜껑을 닫아 두면 잘 마르지 않아요.」","장면 ③ 금빛 딱지 「세상에서 가장 밝은 색! 가장 많이 팔린 형광펜!」","장면 ④ 「영원히 마르지 않는 잉크!」","　　(아주 작은 글씨) ※ 뚜껑을 열어 두면 금방 마를 수 있음."],"title":"형광펜 광고 「쓱쓱 형광펜」 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#12','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C30',2,'ox','auto','안내문이나 주장하는 글도 부풀리거나 감출 수 있어요.',ARRAY['K6-1-u6-X29']::text[],false,'{"seq":12,"concept":"K6-1-u6-C30","difficulty":2,"kind":"ox","stem":"안내문이나 주장하는 글도 부풀리거나 감출 수 있어요.","answer":"O","reason_options":[{"t":"설득하려는 글이면 어디서든 일어날 수 있기 때문에","correct":true},{"t":"부풀리고 감추는 건 광고에서만 일어나기 때문에","mis":"K6-1-u6-X29"}],"mis":"K6-1-u6-X29","explanation":["광고만의 일이 아니에요.","어떤 글에도 세 물음을 대요.","설득하는 글이면 어디든요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#13','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C36',2,'mc','auto','「갯벌은 언제든 걸어 들어가 놀아도 좋습니다」가 감춘 것은 어느 것인가요?',ARRAY['K6-1-u6-X27']::text[],false,'{"seq":13,"concept":"K6-1-u6-C36","difficulty":2,"kind":"mc","stem":"「갯벌은 언제든 걸어 들어가 놀아도 좋습니다」가 감춘 것은 어느 것인가요?","options":[{"t":"바닷물이 들어오는 때에는 위험하니 그때를 확인해야 한다는 점","correct":true},{"t":"갯벌이 넓다는 점","mis":"K6-1-u6-X27"},{"t":"갯벌에 게가 산다는 점","mis":"K6-1-u6-X27"},{"t":"감춘 것이 없다","mis":"K6-1-u6-X27"}],"explanation":["앞에서 밝혔어요.","그것도 밝혔어요.","알아야 할 것을 빼놓았어요 — 바르게는 「바닷물이 들어오는 때를 확인하고 어른과 함께 들어가야 합니다」예요. (바로잡기: 우리나라에는 모래 바닷가 · 바위 바닷가도 있어요.)"],"asset":{"type":"passage","lines":["④ 갯벌은 언제든 걸어 들어가 놀아도 좋습니다.","⑤ 갯벌 생물은 아무리 많이 잡아도 절대 줄어들지 않습니다.","요즘 우리나라 바닷가는 모두 갯벌로 이루어져 있습니다.","⑥ 갯벌을 보면 바다와 땅이 함께 만든 살림터를 알 수 있습니다."],"title":"「바다와 땅 사이, 갯벌」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#14','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C37',2,'mc','auto','「갯벌 생물은 아무리 많이 잡아도 절대 줄어들지 않습니다」를 알맞게 고친 것은 어느 것인가요?',ARRAY['K6-1-u6-X35','K6-1-u6-X33']::text[],false,'{"seq":14,"concept":"K6-1-u6-C37","difficulty":2,"kind":"mc","stem":"「갯벌 생물은 아무리 많이 잡아도 절대 줄어들지 않습니다」를 알맞게 고친 것은 어느 것인가요?","options":[{"t":"갯벌 생물은 알맞게 잡으면 다시 늘어날 수 있지만, 지나치게 잡으면 줄어듭니다","correct":true},{"t":"갯벌 생물은 아무리 잡아도 정말 절대 줄지 않습니다","mis":"K6-1-u6-X35"},{"t":"갯벌 생물은 하나도 잡지 맙시다","mis":"K6-1-u6-X35"},{"t":"갯벌 생물은 언제나 늘어납니다","mis":"K6-1-u6-X33"}],"explanation":["더 부풀렸어요.","뜻까지 바꿨어요.","있는 만큼 말했어요."],"asset":{"type":"passage","lines":["④ 갯벌은 언제든 걸어 들어가 놀아도 좋습니다.","⑤ 갯벌 생물은 아무리 많이 잡아도 절대 줄어들지 않습니다.","요즘 우리나라 바닷가는 모두 갯벌로 이루어져 있습니다.","⑥ 갯벌을 보면 바다와 땅이 함께 만든 살림터를 알 수 있습니다."],"title":"「바다와 땅 사이, 갯벌」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#15','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C41',2,'mc','auto','도율이가 고른 주제 「비누칠하는 동안 물 잠그기」가 알맞은 까닭은 어느 것인가요?',ARRAY['K6-1-u6-X39','K6-1-u6-X42']::text[],false,'{"seq":15,"concept":"K6-1-u6-C41","difficulty":2,"kind":"mc","stem":"도율이가 고른 주제 「비누칠하는 동안 물 잠그기」가 알맞은 까닭은 어느 것인가요?","options":[{"t":"여럿이 함께 겪고, 고치면 물을 덜 쓰게 되어 나아지는 일이기 때문이다","correct":true},{"t":"나 혼자만 겪는 일이기 때문이다","mis":"K6-1-u6-X39"},{"t":"고쳐도 달라지지 않기 때문이다","mis":"K6-1-u6-X39"},{"t":"부풀리기 쉬운 주제이기 때문이다","mis":"K6-1-u6-X42"}],"explanation":["여럿이 겪어요.","고치면 나아져요.","부풀리기 쉬운 게 까닭이 아니에요. (바로잡기: 물을 틀어 놓아도 지구의 물이 하루 만에 마르지 않아요.) (바로잡기: 물을 틀어 두었다고 벌금을 내는 벌금 규칙은 없어요.)"],"asset":{"type":"passage","lines":["장면 — 비누 거품이 묻은 손 아래로 물이 콸콸 흐르는 그림","ㄱ. 물을 틀어 두면 지구의 물이 하루 만에 말라 버립니다!","ㄴ. 이 광고만 보면 물 낭비가 모두 사라집니다.","ㄷ. 비누칠할 때 물을 틀어 두면 무조건 벌금!","ㄹ. 잠가요, 비누칠하는 동안"],"title":"도율의 공익 광고 초안 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#16','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C46',2,'mc','auto','도율이가 ⑤문단을 알맞게 판단해 말한 것은 어느 것인가요?',ARRAY['K6-1-u6-X06','K6-1-u6-X45','K6-1-u6-X21']::text[],false,'{"seq":16,"concept":"K6-1-u6-C46","difficulty":2,"kind":"mc","stem":"도율이가 ⑤문단을 알맞게 판단해 말한 것은 어느 것인가요?","options":[{"t":"「〈모든 문제가 사라진다〉는 부풀렸어. 창문을 열어도 해결 안 되는 문제가 있으니까. 그래도 직접 센 기록은 좋아.」","correct":true},{"t":"「⑤문단은 그냥 별로야.」","mis":"K6-1-u6-X06"},{"t":"「너는 늘 과장하잖아.」","mis":"K6-1-u6-X45"},{"t":"「⑤문단 때문에 글 전체가 엉터리야.」","mis":"K6-1-u6-X21"}],"explanation":["까닭이 없어요.","사람을 겨누지 않아요.","까닭과 잘한 점이 함께 있어요."],"asset":{"type":"speech","turns":[{"who":"도율","text":"담희 글에 이상한 데가 세 군데나 있어. 이 글은 다 버리는 게 낫겠다."},{"who":"담희","text":"걸린 곳만 짚어 줘. 창문을 열자는 주장과 직접 센 기록도 틀렸어?"},{"who":"도율","text":"그건 아니야. 그리고 ⑤문단은 그냥 별로야."},{"who":"담희","text":"별로라고만 하면 어디를 고칠지 모르겠어. 왜 걸리는지 까닭을 말해 줄래?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#17','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C17',3,'mc','auto','「담희 글의 문단 ④는 뒷받침하지 못한다」에 붙일 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X17','K6-1-u6-X06','K6-1-u6-X20']::text[],false,'{"seq":17,"concept":"K6-1-u6-C17","difficulty":3,"kind":"mc","stem":"「담희 글의 문단 ④는 뒷받침하지 못한다」에 붙일 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"창문을 열어도 감기에 걸릴 수 있어 사실이 아니고, 근거도 전해 들은 말이라 확인할 수 없기 때문이다","correct":true},{"t":"담희 글에 그렇게 적혀 있기 때문이다","mis":"K6-1-u6-X17"},{"t":"감기 이야기는 재미없기 때문이다","mis":"K6-1-u6-X06"},{"t":"문단 ④가 맨 뒤에 있기 때문이다","mis":"K6-1-u6-X20"}],"explanation":["적혀 있다는 건 까닭이 아니에요.","재미로 재지 않아요.","두 곳을 까닭과 함께 짚었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#18','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C31',3,'mc','auto','둘레의 광고를 재며 공책에 적은 것 가운데 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X06','K6-1-u6-X17','K6-1-u6-X45']::text[],false,'{"seq":18,"concept":"K6-1-u6-C31","difficulty":3,"kind":"mc","stem":"둘레의 광고를 재며 공책에 적은 것 가운데 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「먹기만 하면 키가 쑥쑥」 — 거짓 ×: 먹는 것 하나로 키가 크지는 않아 없는 효과를 말했다","correct":true},{"t":"「먹기만 하면 키가 쑥쑥」 — ×: 그냥 싫다","mis":"K6-1-u6-X06"},{"t":"「먹기만 하면 키가 쑥쑥」 — ○: 상자에 크게 적혀 있다","mis":"K6-1-u6-X17"},{"t":"「먹기만 하면 키가 쑥쑥」 — ×: 광고 모델이 별로다","mis":"K6-1-u6-X45"}],"explanation":["까닭이 없어요.","크게 적힌 건 까닭이 아니에요.","판단에 까닭이 붙었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#19','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C39',3,'mc','auto','친구는 갯벌 글 ⑤문단의 「절대 줄어들지 않는다」를 거짓이라고 했어요. 알맞은 태도는 어느 것인가요?',ARRAY['K6-1-u6-X37','K6-1-u6-X21']::text[],false,'{"seq":19,"concept":"K6-1-u6-C39","difficulty":3,"kind":"mc","stem":"친구는 갯벌 글 ⑤문단의 「절대 줄어들지 않는다」를 거짓이라고 했어요. 알맞은 태도는 어느 것인가요?","options":[{"t":"까닭을 들어 보고, 그 까닭이 타당하면 내 판단(과장)과 달라도 받아들일 수 있다","correct":true},{"t":"내 판단과 다르니 틀렸다고 한다","mis":"K6-1-u6-X37"},{"t":"까닭은 듣지 않고 기준 이름만 따진다","mis":"K6-1-u6-X37"},{"t":"둘 다 틀렸으니 판단하지 않는다","mis":"K6-1-u6-X21"}],"explanation":["까닭부터 들어요.","까닭이 중요해요.","판단은 정해진 답 맞히기가 아니에요."],"asset":{"type":"passage","lines":["④ 갯벌은 언제든 걸어 들어가 놀아도 좋습니다.","⑤ 갯벌 생물은 아무리 많이 잡아도 절대 줄어들지 않습니다.","요즘 우리나라 바닷가는 모두 갯벌로 이루어져 있습니다.","⑥ 갯벌을 보면 바다와 땅이 함께 만든 살림터를 알 수 있습니다."],"title":"「바다와 땅 사이, 갯벌」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#20','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C43',3,'mc','auto','도율이가 「잠가요, 비누칠하는 동안」만 작게 적고 꾸밈 없이 두었다면 생길 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X41','K6-1-u6-X42']::text[],false,'{"seq":20,"concept":"K6-1-u6-C43","difficulty":3,"kind":"mc","stem":"도율이가 「잠가요, 비누칠하는 동안」만 작게 적고 꾸밈 없이 두었다면 생길 일로 알맞은 것은 어느 것인가요?","options":[{"t":"틀린 말은 없지만 눈에 띄지 않아 아무도 보지 않는 광고가 되기 쉽다","correct":true},{"t":"가장 좋은 광고가 된다","mis":"K6-1-u6-X41"},{"t":"믿을 수 없는 광고가 된다","mis":"K6-1-u6-X42"},{"t":"아무 일도 없다","mis":"K6-1-u6-X41"}],"explanation":["보아야 뜻이 전해져요.","부풀리지 않아 믿을 수는 있어요.","눈에 띄게도 만들어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#21','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C14',3,'mc','auto','그늘막 글에 내가 세운 기준 「한쪽 이야기만 담지는 않았는가?」를 대었을 때 알맞은 판단은 어느 것인가요?',ARRAY['K6-1-u6-X14','K6-1-u6-X01','K6-1-u6-X06']::text[],false,'{"seq":21,"concept":"K6-1-u6-C14","difficulty":3,"kind":"mc","stem":"그늘막 글에 내가 세운 기준 「한쪽 이야기만 담지는 않았는가?」를 대었을 때 알맞은 판단은 어느 것인가요?","options":[{"t":"그늘막의 좋은 점만 담아, 세우는 데 드는 비용이나 세울 곳 같은 다른 쪽 이야기가 빠졌다","correct":true},{"t":"기준은 세 가지뿐이라 이 기준은 댈 수 없다","mis":"K6-1-u6-X14"},{"t":"그늘막 글은 흠이 없다","mis":"K6-1-u6-X01"},{"t":"그냥 한쪽 같다","mis":"K6-1-u6-X06"}],"explanation":["스스로 기준을 세워도 돼요.","따져 보아요.","판단에 까닭이 붙었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#22','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C9',3,'mc','auto','하자는 대로 했을 때 다른 문제가 생겨 가치 있다고 보기 어려운 주장은 어느 것인가요?',ARRAY['K6-1-u6-X05']::text[],false,'{"seq":22,"concept":"K6-1-u6-C9","difficulty":3,"kind":"mc","stem":"하자는 대로 했을 때 다른 문제가 생겨 가치 있다고 보기 어려운 주장은 어느 것인가요?","options":[{"t":"창문을 열어 두려면 겨울에도 하루 종일 열어 둡시다","correct":true},{"t":"쉬는 시간마다 창문을 잠깐 열어 둡시다","mis":"K6-1-u6-X05"},{"t":"복도 정수기 앞에서는 차례를 지킵시다","mis":"K6-1-u6-X05"},{"t":"빌린 물건은 빌린 그대로 돌려줍시다","mis":"K6-1-u6-X05"}],"explanation":["여럿에게 도움이 되는 주장이에요.","이것도 가치 있어요.","추위라는 다른 문제를 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#23','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C47',4,'mc','auto','갯벌 글 전체를 가장 알맞게 평가한 것은 어느 것인가요?',ARRAY['K6-1-u6-X31','K6-1-u6-X21','K6-1-u6-X46']::text[],false,'{"seq":23,"concept":"K6-1-u6-C47","difficulty":4,"kind":"mc","stem":"갯벌 글 전체를 가장 알맞게 평가한 것은 어느 것인가요?","options":[{"t":"문단 ①~③의 설명은 그대로 배워도 좋지만, ④의 감춤 · ⑤의 과장과 거짓을 고치고 다른 관점의 글도 찾아 읽는다","correct":true},{"t":"설명하는 글이니 그대로 외운다","mis":"K6-1-u6-X31"},{"t":"걸린 곳이 있으니 갯벌 이야기는 모두 믿지 않는다","mis":"K6-1-u6-X21"},{"t":"표현은 괜찮고 내용만 따지면 된다","mis":"K6-1-u6-X46"}],"explanation":["외우기 전에 따져요.","맞는 설명은 배워요.","표현에 걸린 곳이 있어요."],"asset":{"type":"passage","lines":["④ 갯벌은 언제든 걸어 들어가 놀아도 좋습니다.","⑤ 갯벌 생물은 아무리 많이 잡아도 절대 줄어들지 않습니다.","요즘 우리나라 바닷가는 모두 갯벌로 이루어져 있습니다.","⑥ 갯벌을 보면 바다와 땅이 함께 만든 살림터를 알 수 있습니다."],"title":"「바다와 땅 사이, 갯벌」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#24','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C36',4,'essay','teacher','갯벌 글의 문단 ④가 무엇을 감추었는지 쓰고, 그것을 알지 못한 채 읽은 사람에게 생길 수 있는 일과 고쳐 쓴 문장을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u6-C36","difficulty":4,"kind":"essay","stem":"갯벌 글의 문단 ④가 무엇을 감추었는지 쓰고, 그것을 알지 못한 채 읽은 사람에게 생길 수 있는 일과 고쳐 쓴 문장을 쓰세요.","answer_guide":{"answer":"예: 「갯벌은 언제든 걸어 들어가 놀아도 좋습니다」는 바닷물이 들어오는 때에는 위험하다는 점을 감추었다. 이것을 모르는 사람은 물이 들어오는 줄 모르고 멀리 들어갔다가 위험해질 수 있다. 고쳐 쓰면 — 「갯벌에 들어갈 때에는 바닷물이 들어오는 때를 확인하고 어른과 함께 가야 합니다.」","scoring_points":["감춘 것을 썼는가","읽는 사람에게 생길 일을 썼는가","감춘 것을 밝혀 고쳐 썼는가"]},"explanation":["되묻고 싶은 것을 찾아요.","한쪽만 알면 생길 일을 떠올려요.","알아야 할 것을 밝혀요."],"asset":{"type":"passage","lines":["④ 갯벌은 언제든 걸어 들어가 놀아도 좋습니다.","⑤ 갯벌 생물은 아무리 많이 잡아도 절대 줄어들지 않습니다.","요즘 우리나라 바닷가는 모두 갯벌로 이루어져 있습니다.","⑥ 갯벌을 보면 바다와 땅이 함께 만든 살림터를 알 수 있습니다."],"title":"「바다와 땅 사이, 갯벌」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#25','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C32',4,'essay','teacher','광고보다 설명하는 글을 읽을 때 더 조심해야 하는 까닭을 쓰고, 설명하는 글에서 거짓 · 과장 · 감춤이 각각 무엇을 남기는지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u6-C32","difficulty":4,"kind":"essay","stem":"광고보다 설명하는 글을 읽을 때 더 조심해야 하는 까닭을 쓰고, 설명하는 글에서 거짓 · 과장 · 감춤이 각각 무엇을 남기는지 쓰세요.","answer_guide":{"answer":"예: 광고는 알리려고 쓴 글인 줄 알아 부풀린 말을 걸러 읽지만, 설명하는 글은 알려 주려고 쓴 글이라 여겨 적힌 대로 외우기 쉽다. 그래서 거짓된 표현은 잘못된 지식이 되고, 과장된 표현은 지나친 믿음이 되며, 감추는 내용은 한쪽만 아는 사람을 만든다.","scoring_points":["더 조심해야 하는 까닭을 썼는가","세 가지가 남기는 것을 썼는가","광고와 견주어 설명했는가"]},"explanation":["읽는 사람의 마음을 떠올려요.","세 가지를 하나씩 써요.","광고와 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#1','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C2',1,'ox','auto','읽다가 「이상한데?」 하고 멈추는 것이 비판적 읽기의 첫걸음이에요.',ARRAY['K6-1-u6-X21']::text[],false,'{"seq":1,"concept":"K6-1-u6-C2","difficulty":1,"kind":"ox","stem":"읽다가 「이상한데?」 하고 멈추는 것이 비판적 읽기의 첫걸음이에요.","answer":"O","reason_options":[{"t":"의문이 드는 곳을 짚어야 어디가 왜 이상한지 따져 볼 수 있기 때문에","correct":true},{"t":"이상한 곳이 있으면 바로 글을 버리기 위해서이기 때문에","mis":"K6-1-u6-X21"}],"mis":"K6-1-u6-X21","explanation":["버리려고 멈추는 게 아니에요.","따져 보려고 멈춰요.","물음에서 시작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#2','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C9',1,'mc','auto','주장이 가치 있고 중요한지 재는 물음으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X09','K6-1-u6-X08','K6-1-u6-X23']::text[],false,'{"seq":2,"concept":"K6-1-u6-C9","difficulty":1,"kind":"mc","stem":"주장이 가치 있고 중요한지 재는 물음으로 알맞은 것은 어느 것인가요?","options":[{"t":"여러 사람에게 도움이 되고 많은 사람이 받아들일 수 있는가?","correct":true},{"t":"글쓴이가 그 주장을 좋아하는가?","mis":"K6-1-u6-X09"},{"t":"주장이 짧은가?","mis":"K6-1-u6-X08"},{"t":"주장에 느낌표가 있는가?","mis":"K6-1-u6-X23"}],"explanation":["글쓴이의 마음으로 재지 않아요.","길이로 재지 않아요.","여럿에게 도움이 되는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#3','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C20',1,'mc','auto','한 편의 글을 재는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X20']::text[],false,'{"seq":3,"concept":"K6-1-u6-C20","difficulty":1,"kind":"mc","stem":"한 편의 글을 재는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"주장을 재고, 이유를 재고, 근거를 잰다","correct":true},{"t":"근거부터 재고 주장은 마지막에 본다","mis":"K6-1-u6-X20"},{"t":"마음에 드는 문단부터 잰다","mis":"K6-1-u6-X20"},{"t":"세 기준을 한꺼번에 아무 데나 댄다","mis":"K6-1-u6-X20"}],"explanation":["주장부터 봐요.","차례가 있어요.","주장 → 이유 → 근거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#4','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C23',1,'mc','auto','표현의 적절성은 무엇을 재나요?',ARRAY['K6-1-u6-X23','K6-1-u6-X03']::text[],false,'{"seq":4,"concept":"K6-1-u6-C23","difficulty":1,"kind":"mc","stem":"표현의 적절성은 무엇을 재나요?","options":[{"t":"내용을 어떻게 말했는가","correct":true},{"t":"글씨를 얼마나 예쁘게 썼는가","mis":"K6-1-u6-X23"},{"t":"글이 얼마나 긴가","mis":"K6-1-u6-X23"},{"t":"주장이 가치 있는가","mis":"K6-1-u6-X03"}],"explanation":["겉모습이 아니에요.","길이도 아니에요.","어떻게 말했는지 재요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#5','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C29',1,'ox','auto','한 광고 문구가 과장이면서 감춤일 수도 있어요.',ARRAY['K6-1-u6-X28']::text[],false,'{"seq":5,"concept":"K6-1-u6-C29","difficulty":1,"kind":"ox","stem":"한 광고 문구가 과장이면서 감춤일 수도 있어요.","answer":"O","reason_options":[{"t":"한 문구가 두 기준에 함께 걸릴 수 있기 때문에","correct":true},{"t":"한 문구는 한 기준에만 걸리기 때문에","mis":"K6-1-u6-X28"}],"mis":"K6-1-u6-X28","explanation":["기준은 서로 밀어내지 않아요.","두 기준에 함께 걸려요.","하나씩 들고 훑어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#6','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C36',1,'ox','auto','틀린 말이 하나도 없으면 감춘 것도 없어요.',ARRAY['K6-1-u6-X27']::text[],false,'{"seq":6,"concept":"K6-1-u6-C36","difficulty":1,"kind":"ox","stem":"틀린 말이 하나도 없으면 감춘 것도 없어요.","answer":"X","reason_options":[{"t":"틀린 말 없이도 알아야 할 것을 빼놓아 한쪽만 알게 할 수 있기 때문에","correct":true},{"t":"감춤은 틀린 말을 할 때만 생기기 때문에","mis":"K6-1-u6-X27"}],"mis":"K6-1-u6-X27","explanation":["틀린 말이 없어도 감출 수 있어요.","빼놓은 것을 봐요.","되묻고 싶은 게 남는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#7','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C46',1,'ox','auto','친구의 광고를 판단할 때에는 만든 사람이 아니라 문구를 두고 말해요.',ARRAY['K6-1-u6-X45']::text[],false,'{"seq":7,"concept":"K6-1-u6-C46","difficulty":1,"kind":"ox","stem":"친구의 광고를 판단할 때에는 만든 사람이 아니라 문구를 두고 말해요.","answer":"O","reason_options":[{"t":"어느 문구가 왜 걸리는지 짚어야 친구가 고칠 곳을 알 수 있기 때문에","correct":true},{"t":"만든 사람을 두고 말해야 더 정확하기 때문에","mis":"K6-1-u6-X45"}],"mis":"K6-1-u6-X45","explanation":["사람을 겨누지 않아요.","문구를 짚어요.","까닭과 잘한 점도 함께요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#8','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C49',1,'mc','auto','「오래간만에」가 줄어든 말을 바르게 쓴 것은 어느 것인가요?',ARRAY['K6-1-u6-X48']::text[],false,'{"seq":8,"concept":"K6-1-u6-C49","difficulty":1,"kind":"mc","stem":"「오래간만에」가 줄어든 말을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"오랜만에","correct":true},{"t":"오랫만에","mis":"K6-1-u6-X48"},{"t":"오렌만에","mis":"K6-1-u6-X48"},{"t":"오랜마네","mis":"K6-1-u6-X48"}],"explanation":["「오래간만에」가 줄었어요.","「랜」이에요.","「오랜만에」가 바른 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#9','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C10',2,'ox','auto','담희 글 문단 ③은 맞는 말일 수 있지만 주장을 뒷받침하지 못해요.',ARRAY['K6-1-u6-X10']::text[],false,'{"seq":9,"concept":"K6-1-u6-C10","difficulty":2,"kind":"ox","stem":"담희 글 문단 ③은 맞는 말일 수 있지만 주장을 뒷받침하지 못해요.","answer":"O","reason_options":[{"t":"닫아 두자는 쪽을 가리켜 열어 두자는 주장과 어긋나기 때문에","correct":true},{"t":"맞는 말이면 모두 이유가 되기 때문에","mis":"K6-1-u6-X10"}],"mis":"K6-1-u6-X10","explanation":["맞는 말이어도 방향을 봐요.","주장 편이어야 해요.","어긋난 이유예요 — 주장 쪽 이유로 바꿔 써요."],"asset":{"type":"passage","lines":["① 셋째 시간이 끝날 무렵이면 교실 공기가 답답해집니다.","쉬는 시간마다 창문을 열어 두면 좋겠습니다.","② 첫째, 바깥 공기가 들어와 교실 공기가 바뀝니다. 우리 반이 일주일 동안","쉬는 시간마다 창문을 열어 보니, 「답답하다」고 적은 친구가 날마다 줄었습니다.","③ 둘째, 창문을 닫아 두면 바깥 소리가 들어오지 않아 수업에 마음을 모을 수 있습니다."],"title":"담희의 글 「쉬는 시간마다 창문을 열어 둡시다」 — 앞부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#10','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C17',2,'mc','auto','「담희 글의 주장은 가치 있나요?」에 가장 좋은 답은 어느 것인가요?',ARRAY['K6-1-u6-X17','K6-1-u6-X21','K6-1-u6-X06']::text[],false,'{"seq":10,"concept":"K6-1-u6-C17","difficulty":2,"kind":"mc","stem":"「담희 글의 주장은 가치 있나요?」에 가장 좋은 답은 어느 것인가요?","options":[{"t":"가치 있다 — 답답한 공기를 바꾸어 여럿에게 도움이 되고 누구나 받아들일 만하다","correct":true},{"t":"가치 있다 — 글에 그렇게 적혀 있다","mis":"K6-1-u6-X17"},{"t":"가치 없다 — 걸린 곳이 있다","mis":"K6-1-u6-X21"},{"t":"가치 있다","mis":"K6-1-u6-X06"}],"explanation":["적혀 있는 건 까닭이 아니에요.","걸린 곳과 주장의 가치는 따로예요.","판단과 까닭이 한 짝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#11','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C29',2,'mc','auto','「세상에서 가장 밝은 색!」을 바르게 판단한 것은 어느 것인가요?',ARRAY['K6-1-u6-X28','K6-1-u6-X26','K6-1-u6-X25']::text[],false,'{"seq":11,"concept":"K6-1-u6-C29","difficulty":2,"kind":"mc","stem":"「세상에서 가장 밝은 색!」을 바르게 판단한 것은 어느 것인가요?","options":[{"t":"부풀린 과장이면서, 무엇과 견주어 가장 밝은지 밝히지 않은 감춤이기도 하다","correct":true},{"t":"과장일 뿐이다","mis":"K6-1-u6-X28"},{"t":"알맞은 표현이다","mis":"K6-1-u6-X26"},{"t":"없는 기능을 말한 거짓이다","mis":"K6-1-u6-X25"}],"explanation":["한 기준에만 걸리지 않아요.","부풀렸어요.","두 기준에 함께 걸려요. (바로잡기: 형광펜에는 공부를 대신해 주는 기능이 없어요.)"],"asset":{"type":"passage","lines":["장면 ① 형광펜을 든 아이가 웃는 큰 그림 「공부가 저절로 되는 형광펜!」","장면 ② 「다섯 가지 색이 한 묶음」 「뚜껑을 닫아 두면 잘 마르지 않아요.」","장면 ③ 금빛 딱지 「세상에서 가장 밝은 색! 가장 많이 팔린 형광펜!」","장면 ④ 「영원히 마르지 않는 잉크!」","　　(아주 작은 글씨) ※ 뚜껑을 열어 두면 금방 마를 수 있음."],"title":"형광펜 광고 「쓱쓱 형광펜」 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#12','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C30',2,'ox','auto','부풀린 말만 없으면 그 정보는 다 믿을 수 있어요.',ARRAY['K6-1-u6-X30']::text[],false,'{"seq":12,"concept":"K6-1-u6-C30","difficulty":2,"kind":"ox","stem":"부풀린 말만 없으면 그 정보는 다 믿을 수 있어요.","answer":"X","reason_options":[{"t":"오래되어 지금과 맞지 않거나 두루뭉술해 오해하게 하는 정보도 믿기 어렵기 때문에","correct":true},{"t":"부풀리지 않은 정보는 언제나 정확하기 때문에","mis":"K6-1-u6-X30"}],"mis":"K6-1-u6-X30","explanation":["부풀림만 보지 않아요.","오래된 · 흐린 정보도 따져요.","언제 · 무엇인지 분명한지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#13','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C32',2,'mc','auto','갯벌 글을 「알려 주는 글이니까」 하고 그대로 외우면 생길 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X31','K6-1-u6-X21']::text[],false,'{"seq":13,"concept":"K6-1-u6-C32","difficulty":2,"kind":"mc","stem":"갯벌 글을 「알려 주는 글이니까」 하고 그대로 외우면 생길 일로 알맞은 것은 어느 것인가요?","options":[{"t":"바닷가는 다 갯벌이라는 잘못된 지식과, 생물이 절대 줄지 않는다는 지나친 믿음이 남는다","correct":true},{"t":"아무 일도 생기지 않는다","mis":"K6-1-u6-X31"},{"t":"갯벌을 더 정확히 알게 된다","mis":"K6-1-u6-X31"},{"t":"갯벌 글을 더는 읽지 않게 된다","mis":"K6-1-u6-X21"}],"explanation":["외운 것이 지식이 돼요.","흠까지 외우게 돼요.","거짓은 잘못된 지식, 과장은 지나친 믿음이 돼요. (바로잡기: 우리나라에는 모래 바닷가 · 바위 바닷가도 있어요.) (바로잡기: 바닷물이 들어오는 때에는 갯벌에 들어가면 위험해요.) (바로잡기: 갯벌 생물도 지나치게 잡으면 줄어들어요.)"],"asset":{"type":"passage","lines":["④ 갯벌은 언제든 걸어 들어가 놀아도 좋습니다.","⑤ 갯벌 생물은 아무리 많이 잡아도 절대 줄어들지 않습니다.","요즘 우리나라 바닷가는 모두 갯벌로 이루어져 있습니다.","⑥ 갯벌을 보면 바다와 땅이 함께 만든 살림터를 알 수 있습니다."],"title":"「바다와 땅 사이, 갯벌」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#14','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C13',2,'ox','auto','갯벌 글처럼 설명하는 글도 내용이 타당한지 따져 읽어요.',ARRAY['K6-1-u6-X13']::text[],false,'{"seq":14,"concept":"K6-1-u6-C13","difficulty":2,"kind":"ox","stem":"갯벌 글처럼 설명하는 글도 내용이 타당한지 따져 읽어요.","answer":"O","reason_options":[{"t":"내용을 담은 글이면 같은 물음으로 살필 수 있기 때문에","correct":true},{"t":"설명하는 글은 따질 것이 없기 때문에","mis":"K6-1-u6-X13"}],"mis":"K6-1-u6-X13","explanation":["설명하는 글도 따져요.","내용을 담았으니까요.","어디에나 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#15','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C44',2,'mc','auto','도율이 광고에서 크게 쓸 한 줄로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X43','K6-1-u6-X42']::text[],false,'{"seq":15,"concept":"K6-1-u6-C44","difficulty":2,"kind":"mc","stem":"도율이 광고에서 크게 쓸 한 줄로 알맞은 것은 어느 것인가요?","options":[{"t":"잠가요, 비누칠하는 동안","correct":true},{"t":"ㄱ~ㄹ 네 줄 모두","mis":"K6-1-u6-X43"},{"t":"「무조건 벌금!」","mis":"K6-1-u6-X42"},{"t":"그림 아래 작은 설명","mis":"K6-1-u6-X43"}],"explanation":["다 크면 아무것도 크지 않아요.","거짓을 크게 하면 안 돼요.","하고 싶은 한 줄만 크게요. (바로잡기: 물을 틀어 놓아도 지구의 물이 하루 만에 마르지 않아요.) (바로잡기: 물을 틀어 두었다고 벌금을 내는 벌금 규칙은 없어요.)"],"asset":{"type":"passage","lines":["장면 — 비누 거품이 묻은 손 아래로 물이 콸콸 흐르는 그림","ㄱ. 물을 틀어 두면 지구의 물이 하루 만에 말라 버립니다!","ㄴ. 이 광고만 보면 물 낭비가 모두 사라집니다.","ㄷ. 비누칠할 때 물을 틀어 두면 무조건 벌금!","ㄹ. 잠가요, 비누칠하는 동안"],"title":"도율의 공익 광고 초안 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#16','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C5',2,'ox','auto','도율이처럼 이상한 곳을 많이 찾은 것만으로 글을 잘 읽은 거예요.',ARRAY['K6-1-u6-X05']::text[],false,'{"seq":16,"concept":"K6-1-u6-C5","difficulty":2,"kind":"ox","stem":"도율이처럼 이상한 곳을 많이 찾은 것만으로 글을 잘 읽은 거예요.","answer":"X","reason_options":[{"t":"맞는 곳은 받아들이고 걸린 곳은 까닭을 대어 짚어야 비판적으로 읽은 것이기 때문에","correct":true},{"t":"흠을 많이 찾을수록 잘 읽은 것이기 때문에","mis":"K6-1-u6-X05"}],"mis":"K6-1-u6-X05","explanation":["개수가 아니에요.","까닭이 함께 가요.","골라내는 읽기예요."],"asset":{"type":"speech","turns":[{"who":"도율","text":"담희 글에 이상한 데가 세 군데나 있어. 이 글은 다 버리는 게 낫겠다."},{"who":"담희","text":"걸린 곳만 짚어 줘. 창문을 열자는 주장과 직접 센 기록도 틀렸어?"},{"who":"도율","text":"그건 아니야. 그리고 ⑤문단은 그냥 별로야."},{"who":"담희","text":"별로라고만 하면 어디를 고칠지 모르겠어. 왜 걸리는지 까닭을 말해 줄래?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#17','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C18',3,'mc','auto','담희 글 문단 ④를 주장 편에 서도록 고친 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X26','K6-1-u6-X11','K6-1-u6-X10']::text[],false,'{"seq":17,"concept":"K6-1-u6-C18","difficulty":3,"kind":"mc","stem":"담희 글 문단 ④를 주장 편에 서도록 고친 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"셋째, 바깥 공기가 들어오면 답답함이 줄어 쉬는 시간이 더 상쾌해집니다","correct":true},{"t":"셋째, 창문을 열면 감기가 절대 안 걸립니다","mis":"K6-1-u6-X26"},{"t":"셋째, 창문을 닫으면 따뜻합니다","mis":"K6-1-u6-X11"},{"t":"셋째, 옆 반도 창문을 엽니다","mis":"K6-1-u6-X10"}],"explanation":["더 부풀렸어요.","주장과 반대예요.","사실이고 주장 편이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#18','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C29',3,'mc','auto','형광펜 광고의 「영원히 마르지 않는 잉크!」를 두 기준으로 모두 판단한 것은 어느 것인가요?',ARRAY['K6-1-u6-X28','K6-1-u6-X25','K6-1-u6-X26']::text[],false,'{"seq":18,"concept":"K6-1-u6-C29","difficulty":3,"kind":"mc","stem":"형광펜 광고의 「영원히 마르지 않는 잉크!」를 두 기준으로 모두 판단한 것은 어느 것인가요?","options":[{"t":"어떤 경우에도 마르지 않는다고 부풀린 과장이고, 마를 수 있다는 조건을 아주 작게 적어 감춤에도 가깝다","correct":true},{"t":"과장 하나에만 걸린다","mis":"K6-1-u6-X28"},{"t":"거짓 하나에만 걸린다","mis":"K6-1-u6-X25"},{"t":"어느 기준에도 걸리지 않는다","mis":"K6-1-u6-X26"}],"explanation":["작은 글씨까지 봐요.","기능은 있어요.","두 기준에 함께 걸려요."],"asset":{"type":"passage","lines":["장면 ① 형광펜을 든 아이가 웃는 큰 그림 「공부가 저절로 되는 형광펜!」","장면 ② 「다섯 가지 색이 한 묶음」 「뚜껑을 닫아 두면 잘 마르지 않아요.」","장면 ③ 금빛 딱지 「세상에서 가장 밝은 색! 가장 많이 팔린 형광펜!」","장면 ④ 「영원히 마르지 않는 잉크!」","　　(아주 작은 글씨) ※ 뚜껑을 열어 두면 금방 마를 수 있음."],"title":"형광펜 광고 「쓱쓱 형광펜」 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#19','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C38',3,'mc','auto','갯벌 글과 함께 읽으면 좋은 글로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X36']::text[],false,'{"seq":19,"concept":"K6-1-u6-C38","difficulty":3,"kind":"mc","stem":"갯벌 글과 함께 읽으면 좋은 글로 알맞은 것은 어느 것인가요?","options":[{"t":"갯벌이 줄어든 바닷가 마을의 변화를 다룬 글","correct":true},{"t":"갯벌의 좋은 점만 한 번 더 늘어놓은 글","mis":"K6-1-u6-X36"},{"t":"갯벌과 관계없는 이야기책","mis":"K6-1-u6-X36"},{"t":"함께 읽을 글은 필요 없다","mis":"K6-1-u6-X36"}],"explanation":["같은 쪽의 글이에요.","관련 있는 글이어야 해요.","다른 관점의 관련 글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#20','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C44',3,'mc','auto','도율이 광고에서 진한 색을 쓸 곳으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X43','K6-1-u6-X41']::text[],false,'{"seq":20,"concept":"K6-1-u6-C44","difficulty":3,"kind":"mc","stem":"도율이 광고에서 진한 색을 쓸 곳으로 알맞은 것은 어느 것인가요?","options":[{"t":"「잠가요, 비누칠하는 동안」 한 줄","correct":true},{"t":"광고 전체","mis":"K6-1-u6-X43"},{"t":"그림 아래 작은 설명 글","mis":"K6-1-u6-X43"},{"t":"아무 데도 쓰지 않는다","mis":"K6-1-u6-X41"}],"explanation":["온통 진하면 강조가 사라져요.","강조할 곳이 아니에요.","강조할 한 줄에만 써요."],"asset":{"type":"passage","lines":["장면 — 비누 거품이 묻은 손 아래로 물이 콸콸 흐르는 그림","ㄱ. 물을 틀어 두면 지구의 물이 하루 만에 말라 버립니다!","ㄴ. 이 광고만 보면 물 낭비가 모두 사라집니다.","ㄷ. 비누칠할 때 물을 틀어 두면 무조건 벌금!","ㄹ. 잠가요, 비누칠하는 동안"],"title":"도율의 공익 광고 초안 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#21','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C22',3,'mc','auto','단원을 마친 뒤 둘레의 글을 읽을 때 할 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X22','K6-1-u6-X15','K6-1-u6-X01']::text[],false,'{"seq":21,"concept":"K6-1-u6-C22","difficulty":3,"kind":"mc","stem":"단원을 마친 뒤 둘레의 글을 읽을 때 할 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"게시판 글 · 포장 글 · 광고에 여섯 물음을 대고, 판단마다 까닭을 적는다","correct":true},{"t":"공부 시간 글에만 여섯 물음을 댄다","mis":"K6-1-u6-X22"},{"t":"큰 글씨만 읽는다","mis":"K6-1-u6-X15"},{"t":"붙어 있는 글은 그대로 믿는다","mis":"K6-1-u6-X01"}],"explanation":["둘레의 글에도 대어 봐요.","작은 글씨도 봐요.","판단과 까닭을 함께 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#22','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C39',3,'mc','auto','같은 문장을 두고 친구와 판단이 달랐어요. 판단을 나누는 말로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X37','K6-1-u6-X06','K6-1-u6-X45']::text[],false,'{"seq":22,"concept":"K6-1-u6-C39","difficulty":3,"kind":"mc","stem":"같은 문장을 두고 친구와 판단이 달랐어요. 판단을 나누는 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「나는 이렇게 판단했어. 까닭은 이거야. 네 까닭도 들어 볼게.」","correct":true},{"t":"「내 말이 맞아. 더 말할 것 없어.」","mis":"K6-1-u6-X37"},{"t":"「그냥 내 느낌이 그래.」","mis":"K6-1-u6-X06"},{"t":"「네가 하는 말은 늘 틀려.」","mis":"K6-1-u6-X45"}],"explanation":["까닭을 들어 봐요.","까닭이 빠졌어요.","사람을 겨누지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#23','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C47',4,'mc','auto','도율이의 초안 전체를 가장 알맞게 평가한 것은 어느 것인가요?',ARRAY['K6-1-u6-X42','K6-1-u6-X21','K6-1-u6-X38']::text[],false,'{"seq":23,"concept":"K6-1-u6-C47","difficulty":4,"kind":"mc","stem":"도율이의 초안 전체를 가장 알맞게 평가한 것은 어느 것인가요?","options":[{"t":"주제는 가치 있고 ㄹ은 알맞지만, ㄱ · ㄷ은 사실이 아니고 ㄴ은 부풀려 고쳐 써야 한다","correct":true},{"t":"눈에 띄니 그대로 써도 된다","mis":"K6-1-u6-X42"},{"t":"걸린 문구가 있으니 주제를 바꾼다","mis":"K6-1-u6-X21"},{"t":"내 광고니 고칠 필요가 없다","mis":"K6-1-u6-X38"}],"explanation":["믿을 수 있어야 해요.","주제는 좋아요.","만들 때도 같은 자를 대요."],"asset":{"type":"passage","lines":["장면 — 비누 거품이 묻은 손 아래로 물이 콸콸 흐르는 그림","ㄱ. 물을 틀어 두면 지구의 물이 하루 만에 말라 버립니다!","ㄴ. 이 광고만 보면 물 낭비가 모두 사라집니다.","ㄷ. 비누칠할 때 물을 틀어 두면 무조건 벌금!","ㄹ. 잠가요, 비누칠하는 동안"],"title":"도율의 공익 광고 초안 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#24','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C43',4,'essay','teacher','도율이의 초안을 고쳐 공익 광고를 완성한다고 할 때, 크게 쓸 한 줄 · 고쳐 쓸 문구 하나 · 발표 때 밝힐 말을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u6-C43","difficulty":4,"kind":"essay","stem":"도율이의 초안을 고쳐 공익 광고를 완성한다고 할 때, 크게 쓸 한 줄 · 고쳐 쓸 문구 하나 · 발표 때 밝힐 말을 쓰세요.","answer_guide":{"answer":"예: 크게 쓸 한 줄 — 「잠가요, 비누칠하는 동안」. 고쳐 쓸 문구 — ㄴ 「이 광고만 보면 물 낭비가 모두 사라집니다」를 「한 사람이 잠그면 한 컵만큼 물이 남습니다」로 고친다. 발표 — 「수돗가에서 물이 흐르는 것을 보고 이 주제를 골랐어요. 물줄기를 일부러 크게 그린 까닭은 낭비를 한눈에 보여 주고 싶어서예요.」","scoring_points":["크게 쓸 한 줄을 알맞게 골랐는가","걸린 문구를 알맞게 고쳤는가","발표 때 까닭을 밝혔는가"]},"explanation":["한 줄만 크게 해요.","부풀린 말을 덜어요.","손댄 곳의 까닭을 밝혀요."],"asset":{"type":"passage","lines":["장면 — 비누 거품이 묻은 손 아래로 물이 콸콸 흐르는 그림","ㄱ. 물을 틀어 두면 지구의 물이 하루 만에 말라 버립니다!","ㄴ. 이 광고만 보면 물 낭비가 모두 사라집니다.","ㄷ. 비누칠할 때 물을 틀어 두면 무조건 벌금!","ㄹ. 잠가요, 비누칠하는 동안"],"title":"도율의 공익 광고 초안 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#25','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C38',4,'essay','teacher','내 둘레에서 한쪽 이야기만 담은 글이나 광고를 하나 떠올려, 다른 관점의 물음 두 가지와 그 답을 찾을 방법을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u6-C38","difficulty":4,"kind":"essay","stem":"내 둘레에서 한쪽 이야기만 담은 글이나 광고를 하나 떠올려, 다른 관점의 물음 두 가지와 그 답을 찾을 방법을 쓰세요.","answer_guide":{"answer":"예: 학교 앞 문구점의 「새로 나온 필통, 무엇이든 다 들어가요」 광고는 좋은 점만 담았다. 물음 — 「무겁지는 않을까?」, 「쉽게 망가지지는 않을까?」 써 본 친구에게 여쭈어 보거나, 물건 상자에 적힌 무게와 사용 안내를 읽어 보겠다. 한쪽 이야기만 듣고 고르면 나중에 후회할 수 있기 때문이다.","scoring_points":["한쪽 이야기만 담은 글을 떠올렸는가","다른 관점의 물음을 두 가지 썼는가","답을 찾을 방법을 썼는가"]},"explanation":["좋은 점만 말한 글을 떠올려요.","다른 쪽에서 물어요.","찾아갈 길을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u1-C1','math',6,1,'u1',2,'나누어떨어지지 않는 나눗셈 — 몫과 나머지로만 두면 한 사람 몫을 알 수 없음을 알고, 남은 것까지 똑같이 나누면 몫을 분수로 적을 수 있음을 알며 약분·분수의 곱셈을 되짚기',ARRAY['6수01-10']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u1-C2','math',6,1,'u1',2,'몫이 1보다 작은 (자연수)÷(자연수) — 1을 나누는 수만큼 똑같이 나눈 한 조각을 바탕으로 나누어지는 수는 분자, 나누는 수는 분모로 몫을 나타내고, 나누어지는 수가 더 작아도 나눌 수 있음을 알기',ARRAY['6수01-10']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u1-C3','math',6,1,'u1',3,'몫이 1보다 큰 (자연수)÷(자연수) — 먼저 1씩 나누고 남은 것을 마저 나누거나 모두 똑같이 잘라 나누어, 몫을 대분수와 가분수로 나타내고 두 몫이 같은 수임을 알기',ARRAY['6수01-10']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u1-C4','math',6,1,'u1',4,'(자연수)÷(자연수)를 분수의 곱셈으로 — ÷(자연수)는 그 수만큼 똑같이 나눈 것 중의 1이므로 나누는 수를 분모로 하는 단위분수를 곱하는 것과 같고, 나누는 수를 그대로 곱하면 커져 안 됨을 알기',ARRAY['6수01-10']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u1-C5','math',6,1,'u1',5,'(진분수)÷(자연수) — 분자가 나누어떨어지면 분자만 나누어도 되고, 나누어떨어지지 않으면 (진분수) × (단위분수)로 바꾸어 계산하며, 1보다 큰 자연수로 나눈 몫은 처음 분수보다 작음을 알기',ARRAY['6수01-10']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u1-C6','math',6,1,'u1',6,'(대분수)÷(자연수) — 대분수를 먼저 가분수로 고친 뒤 나누는 수의 단위분수를 곱하고, 자연수 부분이나 분수 부분만 나누는 실수를 피하며 몫을 약분해 대분수로 나타내기',ARRAY['6수01-10']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u1-C7','math',6,1,'u1',7,'문제 해결 — 수평인 저울에서 양쪽의 같은 것을 덜어 내 「노란 뚜껑 1개 = 파란 뚜껑 몇 개」 관계를 찾고, 그 수로 무게를 나누어 한 개의 무게를 구하며 조건을 바꾸어 새 문제를 풀기',ARRAY['6수01-10']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u1-X01','math',6,'u1',ARRAY['M6-1-u1-C1','M6-1-u1-C2','M6-1-u1-C3']::text[],'몫을 분수로 적을 때 분자·분모 자리를 잘못 둔다(2 ÷ 3을 ⟨3/2⟩나 ⟨1/3⟩로)','나누어지는 수가 분자, 나누는 수가 분모') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u1-X02','math',6,'u1',ARRAY['M6-1-u1-C1','M6-1-u1-C3']::text[],'나누어떨어지지 않으면 더 나눌 수 없다고 보거나 몫과 나머지로만 둔다','남은 것도 마저 나누면 분수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u1-X03','math',6,'u1',ARRAY['M6-1-u1-C1','M6-1-u1-C2','M6-1-u1-C3']::text[],'작은 수를 큰 수로는 나눌 수 없다고 보거나, 몫이 1보다 작은지·큰지를 잘못 가린다','나누어지는 수가 작으면 몫은 1보다 작아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u1-X04','math',6,'u1',ARRAY['M6-1-u1-C3']::text[],'몫을 대분수로 나타낼 때 자연수 부분·분자·분모 자리를 잘못 둔다(13 ÷ 5를 ⟨3 2/5⟩나 ⟨2 3/13⟩로)','몫은 자연수, 나머지는 분자') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u1-X05','math',6,'u1',ARRAY['M6-1-u1-C3','M6-1-u1-C6','M6-1-u1-C7']::text[],'대분수를 가분수로 잘못 고친다(자연수와 분자를 더하거나 곱하고, 분모를 곱하지 않는다)','자연수 × 분모 + 분자') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u1-X06','math',6,'u1',ARRAY['M6-1-u1-C4','M6-1-u1-C5','M6-1-u1-C6','M6-1-u1-C7']::text[],'÷(자연수)를 ×(자연수)로 바꾸어 나누는 수를 그대로 곱한다','나누면 작아져요 — 단위분수를 곱해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u1-X07','math',6,'u1',ARRAY['M6-1-u1-C4','M6-1-u1-C5','M6-1-u1-C6']::text[],'곱셈으로 바꿀 때 단위분수를 잘못 만든다(나누어지는 수를 단위분수로 하거나 분수를 뒤집는다)','나누는 수를 분모로 하는 단위분수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u1-X08','math',6,'u1',ARRAY['M6-1-u1-C5']::text[],'(분수)÷(자연수)에서 분모를 자연수로 나누거나 분자와 분모를 함께 나눈다','분모가 아니라 분자를 나눠요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u1-X09','math',6,'u1',ARRAY['M6-1-u1-C5','M6-1-u1-C6']::text[],'나눗셈 대신 분모에 나누는 수를 더하거나 분자에서 뺀다(연산을 섞는다)','나누기는 단위분수를 곱하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u1-X10','math',6,'u1',ARRAY['M6-1-u1-C6','M6-1-u1-C7']::text[],'대분수를 가분수로 고치지 않고 자연수 부분만 또는 분수 부분만 나눈다','대분수는 먼저 가분수로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u1-X11','math',6,'u1',ARRAY['M6-1-u1-C2','M6-1-u1-C3','M6-1-u1-C4','M6-1-u1-C5','M6-1-u1-C6']::text[],'몫을 견줄 때 나누는 수가 클수록 몫이 크다고 여기거나, 나누어지는 수만 보고 판단한다','같은 양을 더 많이 나누면 작아져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u1-X12','math',6,'u1',ARRAY['M6-1-u1-C1','M6-1-u1-C3','M6-1-u1-C5','M6-1-u1-C6']::text[],'계산 마무리 실수 — 약분하지 않거나 가분수·대분수로 잘못 고친다','몫은 약분해서 대분수로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u1-X13','math',6,'u1',ARRAY['M6-1-u1-C7']::text[],'저울에서 양쪽의 같은 것을 덜어 내지 않고 관계를 잘못 찾는다(노란 1개 = 파란 5개로 본다)','양쪽에서 같은 것을 덜어 내기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u1-X14','math',6,'u1',ARRAY['M6-1-u1-C1','M6-1-u1-C2','M6-1-u1-C4','M6-1-u1-C5','M6-1-u1-C7']::text[],'문장에서 식을 거꾸로 세우거나 나눗셈 대신 다른 연산을 쓴다','「무엇을 몇으로」 나누나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u1-X15','math',6,'u1',ARRAY['M6-1-u1-C1','M6-1-u1-C2','M6-1-u1-C3','M6-1-u1-C4','M6-1-u1-C5','M6-1-u1-C6','M6-1-u1-C7']::text[],'묻는 말을 거꾸로 읽거나 놓친다 — 잘못된↔알맞은, 큰↔작은, 분자↔분모·합','물음의 「잘못·가장·분모」에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L02_basic#1','math',6,1,'u1','L02','g6_1_math_u1_L02_basic','lesson_basic','M6-1-u1-C1',1,'mc','auto','과자 반죽 2개를 3명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 과자 반죽을 구하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u1-X14']::text[],true,'{"seq":1,"concept":"M6-1-u1-C1","difficulty":1,"kind":"mc","stem":"과자 반죽 2개를 3명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 과자 반죽을 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"2 ÷ 3","correct":true},{"t":"3 ÷ 2","mis":"M6-1-u1-X14"},{"t":"2 × 3","mis":"M6-1-u1-X14"},{"t":"2 + 3","mis":"M6-1-u1-X14"}],"explanation":["전체 2개를 3으로 똑같이 나누는 거예요.","나누어지는 수 2가 앞, 나누는 수 3이 뒤에 와요.","그래서 식은 2 ÷ 3이에요."],"variant_rule":{"alt":[{"stem":"시루떡 3개를 4명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 시루떡을 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"3 ÷ 4","correct":true},{"t":"4 ÷ 3","mis":"M6-1-u1-X14"},{"t":"3 × 4","mis":"M6-1-u1-X14"},{"t":"3 + 4","mis":"M6-1-u1-X14"}],"explanation":["전체 3개를 4로 똑같이 나누는 거예요.","나누어지는 수 3이 앞, 나누는 수 4가 뒤에 와요.","그래서 식은 3 ÷ 4예요."]},{"stem":"흰 종이 2장을 5명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 흰 종이를 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"2 ÷ 5","correct":true},{"t":"5 ÷ 2","mis":"M6-1-u1-X14"},{"t":"2 × 5","mis":"M6-1-u1-X14"},{"t":"2 + 5","mis":"M6-1-u1-X14"}],"explanation":["전체 2장을 5로 똑같이 나누는 거예요.","나누어지는 수 2가 앞, 나누는 수 5가 뒤에 와요.","그래서 식은 2 ÷ 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L02_basic#2','math',6,1,'u1','L02','g6_1_math_u1_L02_basic','lesson_basic','M6-1-u1-C2',1,'mc','auto','시루떡 1개를 4명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 시루떡은 몇 개인지 분수로 나타내면 얼마인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X09']::text[],true,'{"seq":2,"concept":"M6-1-u1-C2","difficulty":1,"kind":"mc","stem":"시루떡 1개를 4명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 시루떡은 몇 개인지 분수로 나타내면 얼마인가요?","options":[{"t":"⟨1/4⟩","correct":true},{"t":"4","mis":"M6-1-u1-X01"},{"t":"⟨1/5⟩","mis":"M6-1-u1-X09"},{"t":"1","mis":"M6-1-u1-X01"}],"explanation":["시루떡 1개를 4로 똑같이 나누는 것은 1 ÷ 4예요.","나누어지는 수 1은 분자, 나누는 수 4는 분모가 돼요.","1 ÷ 4 = ⟨1/4⟩ — ⟨1/4⟩개예요."],"variant_rule":{"alt":[{"stem":"식빵 1개를 6명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 식빵은 몇 개인지 분수로 나타내면 얼마인가요?","options":[{"t":"⟨1/6⟩","correct":true},{"t":"6","mis":"M6-1-u1-X01"},{"t":"⟨1/7⟩","mis":"M6-1-u1-X09"},{"t":"1","mis":"M6-1-u1-X01"}],"explanation":["식빵 1개를 6으로 똑같이 나누는 것은 1 ÷ 6이에요.","나누어지는 수 1은 분자, 나누는 수 6은 분모가 돼요.","1 ÷ 6 = ⟨1/6⟩ — ⟨1/6⟩개예요."]},{"stem":"과자 반죽 2개를 3명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 과자 반죽은 몇 개인지 분수로 나타내면 얼마인가요?","options":[{"t":"⟨2/3⟩","correct":true},{"t":"⟨1 1/2⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/3⟩","mis":"M6-1-u1-X01"},{"t":"⟨2/5⟩","mis":"M6-1-u1-X09"}],"explanation":["과자 반죽 2개를 3으로 똑같이 나누는 것은 2 ÷ 3이에요.","나누어지는 수 2는 분자, 나누는 수 3은 분모가 돼요.","2 ÷ 3 = ⟨2/3⟩ — ⟨2/3⟩개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L02_basic#3','math',6,1,'u1','L02','g6_1_math_u1_L02_basic','lesson_basic','M6-1-u1-C2',1,'sa','auto','3 ÷ 5의 몫을 분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-1-u1-C2","difficulty":1,"kind":"sa","stem":"3 ÷ 5의 몫을 분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["(자연수)÷(자연수)의 몫은 분수로 나타낼 수 있어요.","나누어지는 수 3은 분자, 나누는 수 5는 분모예요.","3 ÷ 5 = ⟨3/5⟩이니 분자는 3이에요."],"mis":"M6-1-u1-X01","variant_rule":{"alt":[{"stem":"2 ÷ 7의 몫을 분수로 나타낼 때 분모에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["(자연수)÷(자연수)의 몫은 분수로 나타낼 수 있어요.","나누어지는 수 2는 분자, 나누는 수 7은 분모예요.","2 ÷ 7 = ⟨2/7⟩니 분모는 7이에요."]},{"stem":"4 ÷ 9의 몫을 분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["(자연수)÷(자연수)의 몫은 분수로 나타낼 수 있어요.","나누어지는 수 4는 분자, 나누는 수 9는 분모예요.","4 ÷ 9 = ⟨4/9⟩니 분자는 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L02_basic#4','math',6,1,'u1','L02','g6_1_math_u1_L02_basic','lesson_basic','M6-1-u1-C1',1,'mc','auto','⟨9/36⟩를 약분하여 가장 간단한 분수로 나타내면 어느 것인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X12']::text[],true,'{"seq":4,"concept":"M6-1-u1-C1","difficulty":1,"kind":"mc","stem":"⟨9/36⟩를 약분하여 가장 간단한 분수로 나타내면 어느 것인가요?","options":[{"t":"⟨1/4⟩","correct":true},{"t":"⟨4/1⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/5⟩","mis":"M6-1-u1-X12"},{"t":"⟨1/2⟩","mis":"M6-1-u1-X12"}],"explanation":["분모와 분자를 같은 수로 나누는 것이 약분이에요.","9와 36의 최대공약수는 9예요.","9 ÷ 9 = 1, 36 ÷ 9 = 4라 ⟨9/36⟩ = ⟨1/4⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨12/18⟩를 약분하여 가장 간단한 분수로 나타내면 어느 것인가요?","options":[{"t":"⟨2/3⟩","correct":true},{"t":"⟨3/2⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/2⟩","mis":"M6-1-u1-X12"},{"t":"1","mis":"M6-1-u1-X12"}],"explanation":["분모와 분자를 같은 수로 나누는 것이 약분이에요.","12와 18의 최대공약수는 6이에요.","12 ÷ 6 = 2, 18 ÷ 6 = 3이라 ⟨12/18⟩ = ⟨2/3⟩예요."]},{"stem":"⟨15/45⟩를 약분하여 가장 간단한 분수로 나타내면 어느 것인가요?","options":[{"t":"⟨1/3⟩","correct":true},{"t":"⟨3/1⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/4⟩","mis":"M6-1-u1-X12"},{"t":"⟨2/3⟩","mis":"M6-1-u1-X12"}],"explanation":["분모와 분자를 같은 수로 나누는 것이 약분이에요.","15와 45의 최대공약수는 15예요.","15 ÷ 15 = 1, 45 ÷ 15 = 3이라 ⟨15/45⟩ = ⟨1/3⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L02_basic#5','math',6,1,'u1','L02','g6_1_math_u1_L02_basic','lesson_basic','M6-1-u1-C1',2,'mc','auto','2 ÷ 3은 나누어떨어지지 않아요. 이 나눗셈의 몫을 나타내는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u1-X02','M6-1-u1-X14']::text[],true,'{"seq":5,"concept":"M6-1-u1-C1","difficulty":2,"kind":"mc","stem":"2 ÷ 3은 나누어떨어지지 않아요. 이 나눗셈의 몫을 나타내는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"남은 것도 똑같이 나누어 몫을 분수로 적는다","correct":true},{"t":"나눌 수 없다고 적는다","mis":"M6-1-u1-X02"},{"t":"몫 0, 나머지 2로만 적고 끝낸다","mis":"M6-1-u1-X02"},{"t":"나누어지는 수를 3으로 바꾸어 나눈다","mis":"M6-1-u1-X14"}],"explanation":["2 ÷ 3을 몫과 나머지로만 두면 한 사람이 실제로 얼마를 가지는지 알 수 없어요.","남은 2도 3으로 똑같이 나누어 줄 수 있어요.","그러면 몫을 ⟨2/3⟩처럼 분수로 적을 수 있어요."],"variant_rule":{"alt":[{"stem":"3 ÷ 5는 나누어떨어지지 않아요. 이 나눗셈의 몫을 나타내는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"남은 것도 똑같이 나누어 몫을 분수로 적는다","correct":true},{"t":"나눌 수 없다고 적는다","mis":"M6-1-u1-X02"},{"t":"몫 0, 나머지 3로만 적고 끝낸다","mis":"M6-1-u1-X02"},{"t":"나누어지는 수를 5로 바꾸어 나눈다","mis":"M6-1-u1-X14"}],"explanation":["3 ÷ 5를 몫과 나머지로만 두면 한 사람이 실제로 얼마를 가지는지 알 수 없어요.","남은 3도 5로 똑같이 나누어 줄 수 있어요.","그러면 몫을 ⟨3/5⟩처럼 분수로 적을 수 있어요."]},{"stem":"5 ÷ 4는 나누어떨어지지 않아요. 이 나눗셈의 몫을 나타내는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"남은 것도 똑같이 나누어 몫을 분수로 적는다","correct":true},{"t":"나눌 수 없다고 적는다","mis":"M6-1-u1-X02"},{"t":"몫 1, 나머지 1로만 적고 끝낸다","mis":"M6-1-u1-X02"},{"t":"나누어지는 수를 4로 바꾸어 나눈다","mis":"M6-1-u1-X14"}],"explanation":["5 ÷ 4를 몫과 나머지로만 두면 한 사람이 실제로 얼마를 가지는지 알 수 없어요.","남은 1도 4로 똑같이 나누어 줄 수 있어요.","그러면 몫을 ⟨1 1/4⟩처럼 분수로 적을 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L02_basic#6','math',6,1,'u1','L02','g6_1_math_u1_L02_basic','lesson_basic','M6-1-u1-C1',2,'sa','auto','과자 반죽 2개를 3명이 나누려고 과자 반죽을 하나씩 모두 3조각으로 잘랐어요. 조각은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u1-C1","difficulty":2,"kind":"sa","stem":"과자 반죽 2개를 3명이 나누려고 과자 반죽을 하나씩 모두 3조각으로 잘랐어요. 조각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["과자 반죽 하나를 3조각으로 잘라요.","과자 반죽 2개 모두 자르면 2 × 3 = 6조각이에요.","그래서 조각은 모두 6개예요."],"mis":"M6-1-u1-X15","variant_rule":{"alt":[{"stem":"시루떡 3개를 4명이 나누려고 시루떡을 하나씩 모두 4조각으로 잘랐어요. 한 명이 가지는 조각은 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["조각은 모두 3 × 4 = 12개예요.","12조각을 4명이 똑같이 나누면 12 ÷ 4 = 3조각씩이에요.","한 조각이 ⟨1/4⟩이니 한 명 몫은 ⟨3/4⟩이에요."]},{"stem":"피자 2판을 5명이 나누려고 피자를 하나씩 모두 5조각으로 잘랐어요. 조각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["피자 하나를 5조각으로 잘라요.","피자 2판 모두 자르면 2 × 5 = 10조각이에요.","그래서 조각은 모두 10개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L02_basic#7','math',6,1,'u1','L02','g6_1_math_u1_L02_basic','lesson_basic','M6-1-u1-C2',2,'mc','auto','3 ÷ 8의 몫을 분수로 나타내면 얼마인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X09']::text[],true,'{"seq":7,"concept":"M6-1-u1-C2","difficulty":2,"kind":"mc","stem":"3 ÷ 8의 몫을 분수로 나타내면 얼마인가요?","options":[{"t":"⟨3/8⟩","correct":true},{"t":"⟨2 2/3⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/8⟩","mis":"M6-1-u1-X01"},{"t":"⟨3/11⟩","mis":"M6-1-u1-X09"}],"explanation":["1 ÷ 8 = ⟨1/8⟩ — 1을 8로 나눈 한 조각이에요.","3 ÷ 8은 그 조각이 3개예요.","3 ÷ 8 = ⟨3/8⟩이에요."],"variant_rule":{"alt":[{"stem":"5 ÷ 9의 몫을 분수로 나타내면 얼마인가요?","options":[{"t":"⟨5/9⟩","correct":true},{"t":"⟨1 4/5⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/9⟩","mis":"M6-1-u1-X01"},{"t":"⟨5/14⟩","mis":"M6-1-u1-X09"}],"explanation":["1 ÷ 9 = ⟨1/9⟩ — 1을 9로 나눈 한 조각이에요.","5 ÷ 9는 그 조각이 5개예요.","5 ÷ 9 = ⟨5/9⟩예요."]},{"stem":"4 ÷ 7의 몫을 분수로 나타내면 얼마인가요?","options":[{"t":"⟨4/7⟩","correct":true},{"t":"⟨1 3/4⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/7⟩","mis":"M6-1-u1-X01"},{"t":"⟨4/11⟩","mis":"M6-1-u1-X09"}],"explanation":["1 ÷ 7 = ⟨1/7⟩ — 1을 7로 나눈 한 조각이에요.","4 ÷ 7은 그 조각이 4개예요.","4 ÷ 7 = ⟨4/7⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L02_basic#8','math',6,1,'u1','L02','g6_1_math_u1_L02_basic','lesson_basic','M6-1-u1-C2',2,'mc','auto','몫이 1보다 작은 나눗셈은 어느 것인가요?',ARRAY['M6-1-u1-X03']::text[],true,'{"seq":8,"concept":"M6-1-u1-C2","difficulty":2,"kind":"mc","stem":"몫이 1보다 작은 나눗셈은 어느 것인가요?","options":[{"t":"5 ÷ 8","correct":true},{"t":"3 ÷ 3","mis":"M6-1-u1-X03"},{"t":"9 ÷ 7","mis":"M6-1-u1-X03"},{"t":"11 ÷ 4","mis":"M6-1-u1-X03"}],"explanation":["나누어지는 수가 나누는 수보다 작으면 몫은 1보다 작고, 크면 1보다 커요.","5 ÷ 8 = ⟨5/8⟩, 3 ÷ 3 = 1, 9 ÷ 7 = ⟨1 2/7⟩, 11 ÷ 4 = ⟨2 3/4⟩이에요.","그래서 몫이 1보다 작은 것은 5 ÷ 8이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 몫이 1보다 작은 나눗셈은 어느 것인가요?","options":[{"t":"4 ÷ 9","correct":true},{"t":"7 ÷ 6","mis":"M6-1-u1-X03"},{"t":"5 ÷ 5","mis":"M6-1-u1-X03"},{"t":"8 ÷ 3","mis":"M6-1-u1-X03"}],"explanation":["나누어지는 수가 나누는 수보다 작으면 몫은 1보다 작고, 크면 1보다 커요.","7 ÷ 6 = ⟨1 1/6⟩, 4 ÷ 9 = ⟨4/9⟩, 5 ÷ 5 = 1, 8 ÷ 3 = ⟨2 2/3⟩예요.","그래서 몫이 1보다 작은 것은 4 ÷ 9예요."]},{"stem":"이번에는 다른 보기예요. 몫이 1보다 작은 나눗셈은 어느 것인가요?","options":[{"t":"2 ÷ 11","correct":true},{"t":"6 ÷ 6","mis":"M6-1-u1-X03"},{"t":"10 ÷ 9","mis":"M6-1-u1-X03"},{"t":"13 ÷ 5","mis":"M6-1-u1-X03"}],"explanation":["나누어지는 수가 나누는 수보다 작으면 몫은 1보다 작고, 크면 1보다 커요.","6 ÷ 6 = 1, 10 ÷ 9 = ⟨1 1/9⟩, 2 ÷ 11 = ⟨2/11⟩, 13 ÷ 5 = ⟨2 3/5⟩이에요.","그래서 몫이 1보다 작은 것은 2 ÷ 11이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L02_basic#9','math',6,1,'u1','L02','g6_1_math_u1_L02_basic','lesson_basic','M6-1-u1-C2',2,'match','auto','나눗셈과 몫을 알맞게 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u1-C2","difficulty":2,"kind":"match","stem":"나눗셈과 몫을 알맞게 이으세요.","pairs":[{"l":"1 ÷ 3","r":"⟨1/3⟩"},{"l":"2 ÷ 5","r":"⟨2/5⟩"},{"l":"4 ÷ 7","r":"⟨4/7⟩"}],"mis":"M6-1-u1-X01","explanation":["나누어지는 수가 분자, 나누는 수가 분모예요.","1 ÷ 3 = ⟨1/3⟩, 2 ÷ 5 = ⟨2/5⟩, 4 ÷ 7 = ⟨4/7⟩예요.","분자와 분모 자리를 바꾸지 않도록 해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 나눗셈과 몫을 알맞게 이으세요.","pairs":[{"l":"3 ÷ 4","r":"⟨3/4⟩"},{"l":"1 ÷ 6","r":"⟨1/6⟩"},{"l":"5 ÷ 8","r":"⟨5/8⟩"}],"explanation":["나누어지는 수가 분자, 나누는 수가 분모예요.","3 ÷ 4 = ⟨3/4⟩, 1 ÷ 6 = ⟨1/6⟩, 5 ÷ 8 = ⟨5/8⟩예요.","분자와 분모 자리를 바꾸지 않도록 해요."]},{"stem":"이번에는 다른 보기예요. 나눗셈과 몫을 알맞게 이으세요.","pairs":[{"l":"2 ÷ 9","r":"⟨2/9⟩"},{"l":"7 ÷ 10","r":"⟨7/10⟩"},{"l":"3 ÷ 11","r":"⟨3/11⟩"}],"explanation":["나누어지는 수가 분자, 나누는 수가 분모예요.","2 ÷ 9 = ⟨2/9⟩, 7 ÷ 10 = ⟨7/10⟩, 3 ÷ 11 = ⟨3/11⟩이에요.","분자와 분모 자리를 바꾸지 않도록 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L02_basic#10','math',6,1,'u1','L02','g6_1_math_u1_L02_basic','lesson_basic','M6-1-u1-C2',3,'mc','auto','가 모둠은 시루떡 3개를 4명이, 나 모둠은 시루떡 4개를 5명이 똑같이 나누었어요. 한 명이 가지는 시루떡이 더 많은 모둠은 어디인가요?',ARRAY['M6-1-u1-X11','M6-1-u1-X03']::text[],true,'{"seq":10,"concept":"M6-1-u1-C2","difficulty":3,"kind":"mc","stem":"가 모둠은 시루떡 3개를 4명이, 나 모둠은 시루떡 4개를 5명이 똑같이 나누었어요. 한 명이 가지는 시루떡이 더 많은 모둠은 어디인가요?","options":[{"t":"나 모둠","correct":true},{"t":"가 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 3 ÷ 4 = ⟨3/4⟩, 나 모둠은 4 ÷ 5 = ⟨4/5⟩예요.","20으로 통분하면 ⟨3/4⟩ = ⟨15/20⟩, ⟨4/5⟩ = ⟨16/20⟩이에요.","⟨3/4⟩ < ⟨4/5⟩라 나 모둠이 더 많아요."],"variant_rule":{"alt":[{"stem":"가 모둠은 빵 2개를 3명이, 나 모둠은 빵 3개를 5명이 똑같이 나누었어요. 한 명이 가지는 빵이 더 많은 모둠은 어디인가요?","options":[{"t":"가 모둠","correct":true},{"t":"나 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 2 ÷ 3 = ⟨2/3⟩, 나 모둠은 3 ÷ 5 = ⟨3/5⟩이에요.","15로 통분하면 ⟨2/3⟩ = ⟨10/15⟩, ⟨3/5⟩ = ⟨9/15⟩예요.","⟨2/3⟩ > ⟨3/5⟩이라 가 모둠이 더 많아요."]},{"stem":"가 모둠은 주스 5 L를 6명이, 나 모둠은 주스 3 L를 4명이 똑같이 나누었어요. 한 명이 가지는 주스가 더 많은 모둠은 어디인가요?","options":[{"t":"가 모둠","correct":true},{"t":"나 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 5 ÷ 6 = ⟨5/6⟩, 나 모둠은 3 ÷ 4 = ⟨3/4⟩이에요.","12로 통분하면 ⟨5/6⟩ = ⟨10/12⟩, ⟨3/4⟩ = ⟨9/12⟩예요.","⟨5/6⟩ > ⟨3/4⟩이라 가 모둠이 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L02_challenge#1','math',6,1,'u1','L02','g6_1_math_u1_L02_challenge','lesson_challenge','M6-1-u1-C2',2,'sa','auto','주스 5 L를 8명이 똑같이 나누어 마시려고 해요. 한 명이 마시는 주스를 분수로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u1-C2","difficulty":2,"kind":"sa","stem":"주스 5 L를 8명이 똑같이 나누어 마시려고 해요. 한 명이 마시는 주스를 분수로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["주스 5 L를 8로 나누니 5 ÷ 8이에요.","5 ÷ 8 = ⟨5/8⟩예요.","분모와 분자의 합은 8 + 5 = 13이에요."],"mis":"M6-1-u1-X15","variant_rule":{"alt":[{"stem":"색 테이프 3 m를 7명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 색 테이프를 분수로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["색 테이프 3 m를 7로 나누니 3 ÷ 7이에요.","3 ÷ 7 = ⟨3/7⟩이에요.","분모와 분자의 합은 7 + 3 = 10이에요."]},{"stem":"색 모래 4 kg을 9모둠이 똑같이 나누어 가지려고 해요. 한 모둠이 가지는 색 모래를 분수로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["색 모래 4 kg을 9로 나누니 4 ÷ 9예요.","4 ÷ 9 = ⟨4/9⟩예요.","분모와 분자의 합은 9 + 4 = 13이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L02_challenge#2','math',6,1,'u1','L02','g6_1_math_u1_L02_challenge','lesson_challenge','M6-1-u1-C1',2,'ox','auto','2 ÷ 3을 「몫 0, 나머지 2」로만 적어도 한 사람이 실제로 얼마를 가지는지 알 수 있어요.',ARRAY['M6-1-u1-X02']::text[],true,'{"seq":2,"concept":"M6-1-u1-C1","difficulty":2,"kind":"ox","stem":"2 ÷ 3을 「몫 0, 나머지 2」로만 적어도 한 사람이 실제로 얼마를 가지는지 알 수 있어요.","answer":"X","reason_options":[{"t":"남은 2도 마저 나눌 수 있는데 나누지 않아 한 사람 몫을 알 수 없어서","correct":true},{"t":"몫과 나머지만 알면 한 사람 몫을 모두 알 수 있어서","mis":"M6-1-u1-X02"}],"mis":"M6-1-u1-X02","explanation":["나머지 2는 아직 나누지 않은 양이에요.","남은 것도 3으로 똑같이 나누어야 한 사람 몫이 정해져요.","2 ÷ 3 = ⟨2/3⟩ — 몫을 분수로 적으면 한 사람 몫이 보여요."],"variant_rule":{"alt":[{"stem":"3 ÷ 4를 「몫 0, 나머지 3」로만 적어도 한 사람이 실제로 얼마를 가지는지 알 수 있어요.","answer":"X","reason_options":[{"t":"남은 3도 마저 나눌 수 있는데 나누지 않아 한 사람 몫을 알 수 없어서","correct":true},{"t":"몫과 나머지만 알면 한 사람 몫을 모두 알 수 있어서","mis":"M6-1-u1-X02"}],"explanation":["나머지 3은 아직 나누지 않은 양이에요.","남은 것도 4로 똑같이 나누어야 한 사람 몫이 정해져요.","3 ÷ 4 = ⟨3/4⟩ — 몫을 분수로 적으면 한 사람 몫이 보여요."]},{"stem":"5 ÷ 6을 「몫 0, 나머지 5」로만 적어도 한 사람이 실제로 얼마를 가지는지 알 수 있어요.","answer":"X","reason_options":[{"t":"남은 5도 마저 나눌 수 있는데 나누지 않아 한 사람 몫을 알 수 없어서","correct":true},{"t":"몫과 나머지만 알면 한 사람 몫을 모두 알 수 있어서","mis":"M6-1-u1-X02"}],"explanation":["나머지 5는 아직 나누지 않은 양이에요.","남은 것도 6으로 똑같이 나누어야 한 사람 몫이 정해져요.","5 ÷ 6 = ⟨5/6⟩ — 몫을 분수로 적으면 한 사람 몫이 보여요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L02_challenge#3','math',6,1,'u1','L02','g6_1_math_u1_L02_challenge','lesson_challenge','M6-1-u1-C2',3,'error','auto','(자연수)÷(자연수)에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u1-X03','M6-1-u1-X15']::text[],true,'{"seq":3,"concept":"M6-1-u1-C2","difficulty":3,"kind":"error","stem":"(자연수)÷(자연수)에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「나누어지는 수가 나누는 수보다 커야만 나눌 수 있어.」","correct":true,"mis_target":"M6-1-u1-X03"},{"t":"도윤 — 「나누는 수가 분모, 나누어지는 수가 분자가 돼.」","mis":"M6-1-u1-X15"},{"t":"하린 — 「몫이 1보다 작을 수도 있어.」","mis":"M6-1-u1-X15"}],"explanation":["1 ÷ 4처럼 나누어지는 수가 더 작아도 똑같이 나눌 수 있어요.","그때 한 명 몫은 1보다 작은 ⟨1/4⟩이 될 뿐이에요.","수아는 작은 수는 나눌 수 없다고 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"3 ÷ 5의 몫을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민준 — 「몫은 ⟨5/3⟩야.」","correct":true,"mis_target":"M6-1-u1-X01"},{"t":"서연 — 「몫은 ⟨3/5⟩이야.」","mis":"M6-1-u1-X15"},{"t":"지호 — 「몫은 1보다 작아.」","mis":"M6-1-u1-X15"}],"explanation":["3 ÷ 5에서 나누어지는 수 3은 분자, 나누는 수 5는 분모예요.","3 ÷ 5 = ⟨3/5⟩ — 1보다 작아요.","민준은 분자와 분모를 거꾸로 적었어요."]},{"stem":"4 ÷ 9의 몫을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「몫은 ⟨9/4⟩야.」","correct":true,"mis_target":"M6-1-u1-X01"},{"t":"나린 — 「몫은 ⟨4/9⟩야.」","mis":"M6-1-u1-X15"},{"t":"유진 — 「몫은 1보다 작아.」","mis":"M6-1-u1-X15"}],"explanation":["4 ÷ 9에서 나누어지는 수 4는 분자, 나누는 수 9는 분모예요.","4 ÷ 9 = ⟨4/9⟩ — 1보다 작아요.","가온은 분자와 분모를 거꾸로 적었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L02_challenge#4','math',6,1,'u1','L02','g6_1_math_u1_L02_challenge','lesson_challenge','M6-1-u1-C2',3,'sa','auto','□ ÷ 7 = ⟨3/7⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u1-C2","difficulty":3,"kind":"sa","stem":"□ ÷ 7 = ⟨3/7⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["(자연수)÷(자연수)의 몫에서 나누어지는 수가 분자예요.","⟨3/7⟩의 분자는 3이에요.","3 ÷ 7 = ⟨3/7⟩이니 □는 3이에요."],"mis":"M6-1-u1-X01","variant_rule":{"alt":[{"stem":"5 ÷ □ = ⟨5/8⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["(자연수)÷(자연수)의 몫에서 나누는 수가 분모예요.","⟨5/8⟩의 분모는 8이에요.","5 ÷ 8 = ⟨5/8⟩니 □는 8이에요."]},{"stem":"□ ÷ 11 = ⟨4/11⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["(자연수)÷(자연수)의 몫에서 나누어지는 수가 분자예요.","⟨4/11⟩의 분자는 4예요.","4 ÷ 11 = ⟨4/11⟩니 □는 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L02_challenge#5','math',6,1,'u1','L02','g6_1_math_u1_L02_challenge','lesson_challenge','M6-1-u1-C2',3,'mc','auto','(자연수)÷(자연수)의 몫이 1보다 작아지는 때는 언제인가요?',ARRAY['M6-1-u1-X03']::text[],true,'{"seq":5,"concept":"M6-1-u1-C2","difficulty":3,"kind":"mc","stem":"(자연수)÷(자연수)의 몫이 1보다 작아지는 때는 언제인가요?","options":[{"t":"나누어지는 수가 나누는 수보다 작을 때","correct":true},{"t":"나누어지는 수가 나누는 수보다 클 때","mis":"M6-1-u1-X03"},{"t":"두 수가 같을 때","mis":"M6-1-u1-X03"},{"t":"나누는 수가 1일 때","mis":"M6-1-u1-X03"}],"explanation":["(자연수)÷(자연수)의 몫은 (나누어지는 수)를 분자, (나누는 수)를 분모로 하는 분수예요.","분자가 분모보다 작으면 1보다 작고, 같으면 1, 크면 1보다 커요.","예를 들어 3 ÷ 5 = ⟨3/5⟩이 돼요 — 그래서 답은 「나누어지는 수가 나누는 수보다 작을 때」예요."],"variant_rule":{"alt":[{"stem":"(자연수)÷(자연수)의 몫이 1보다 커지는 때는 언제인가요?","options":[{"t":"나누어지는 수가 나누는 수보다 클 때","correct":true},{"t":"나누어지는 수가 나누는 수보다 작을 때","mis":"M6-1-u1-X03"},{"t":"두 수가 같을 때","mis":"M6-1-u1-X03"},{"t":"나누는 수가 나누어지는 수보다 클 때","mis":"M6-1-u1-X03"}],"explanation":["(자연수)÷(자연수)의 몫은 (나누어지는 수)를 분자, (나누는 수)를 분모로 하는 분수예요.","분자가 분모보다 작으면 1보다 작고, 같으면 1, 크면 1보다 커요.","예를 들어 7 ÷ 4 = ⟨1 3/4⟩이 돼요 — 그래서 답은 「나누어지는 수가 나누는 수보다 클 때」예요."]},{"stem":"(자연수)÷(자연수)의 몫이 1이 되는 때는 언제인가요?","options":[{"t":"나누어지는 수와 나누는 수가 같을 때","correct":true},{"t":"나누어지는 수가 나누는 수보다 작을 때","mis":"M6-1-u1-X03"},{"t":"나누어지는 수가 나누는 수보다 클 때","mis":"M6-1-u1-X03"},{"t":"나누는 수가 1일 때","mis":"M6-1-u1-X03"}],"explanation":["(자연수)÷(자연수)의 몫은 (나누어지는 수)를 분자, (나누는 수)를 분모로 하는 분수예요.","분자가 분모보다 작으면 1보다 작고, 같으면 1, 크면 1보다 커요.","예를 들어 5 ÷ 5 = ⟨5/5⟩ = 1이 돼요 — 그래서 답은 「나누어지는 수와 나누는 수가 같을 때」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L02_challenge#6','math',6,1,'u1','L02','g6_1_math_u1_L02_challenge','lesson_challenge','M6-1-u1-C2',3,'ox','auto','1 ÷ 4의 몫은 ⟨1/4⟩이에요.',ARRAY['M6-1-u1-X03']::text[],true,'{"seq":6,"concept":"M6-1-u1-C2","difficulty":3,"kind":"ox","stem":"1 ÷ 4의 몫은 ⟨1/4⟩이에요.","answer":"O","reason_options":[{"t":"1을 4로 똑같이 나눈 한 조각이 ⟨1/4⟩이므로","correct":true},{"t":"나누어지는 수가 더 작아 나눌 수 없으므로","mis":"M6-1-u1-X03"}],"mis":"M6-1-u1-X03","explanation":["1을 4조각으로 똑같이 나누면 한 조각은 ⟨1/4⟩이에요.","나누어지는 수가 작아도 나눌 수 있어요.","1 ÷ 4 = ⟨1/4⟩ — 맞아요."],"variant_rule":{"alt":[{"stem":"2 ÷ 7의 몫은 ⟨7/2⟩이에요.","answer":"X","reason_options":[{"t":"나누어지는 수 2가 분자, 나누는 수 7이 분모라 ⟨2/7⟩이므로","correct":true},{"t":"큰 수를 분자에 두어야 하므로","mis":"M6-1-u1-X01"}],"explanation":["나누어지는 수가 분자, 나누는 수가 분모예요.","2 ÷ 7 = ⟨2/7⟩예요.","⟨7/2⟩은 거꾸로 적은 거예요."]},{"stem":"5 ÷ 8과 8 ÷ 5의 몫은 같아요.","answer":"X","reason_options":[{"t":"5 ÷ 8 = ⟨5/8⟩, 8 ÷ 5 = ⟨1 3/5⟩으로 서로 달라서","correct":true},{"t":"같은 두 수로 나누었으니 몫이 같아서","mis":"M6-1-u1-X01"}],"explanation":["5 ÷ 8 = ⟨5/8⟩ — 1보다 작아요.","8 ÷ 5 = ⟨1 3/5⟩ — 1보다 커요.","나누는 순서가 바뀌면 몫도 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L02_challenge#7','math',6,1,'u1','L02','g6_1_math_u1_L02_challenge','lesson_challenge','M6-1-u1-C2',3,'mc','auto','가 모둠은 피자 2판을 3명이, 나 모둠은 피자 3판을 4명이 똑같이 나누었어요. 한 명이 가지는 피자가 더 많은 모둠은 어디인가요?',ARRAY['M6-1-u1-X11','M6-1-u1-X03']::text[],true,'{"seq":7,"concept":"M6-1-u1-C2","difficulty":3,"kind":"mc","stem":"가 모둠은 피자 2판을 3명이, 나 모둠은 피자 3판을 4명이 똑같이 나누었어요. 한 명이 가지는 피자가 더 많은 모둠은 어디인가요?","options":[{"t":"나 모둠","correct":true},{"t":"가 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 2 ÷ 3 = ⟨2/3⟩, 나 모둠은 3 ÷ 4 = ⟨3/4⟩이에요.","12로 통분하면 ⟨2/3⟩ = ⟨8/12⟩, ⟨3/4⟩ = ⟨9/12⟩예요.","⟨2/3⟩ < ⟨3/4⟩이라 나 모둠이 더 많아요."],"variant_rule":{"alt":[{"stem":"가 모둠은 시루떡 4개를 7명이, 나 모둠은 시루떡 3개를 5명이 똑같이 나누었어요. 한 명이 가지는 시루떡이 더 많은 모둠은 어디인가요?","options":[{"t":"나 모둠","correct":true},{"t":"가 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 4 ÷ 7 = ⟨4/7⟩, 나 모둠은 3 ÷ 5 = ⟨3/5⟩이에요.","35로 통분하면 ⟨4/7⟩ = ⟨20/35⟩, ⟨3/5⟩ = ⟨21/35⟩이에요.","⟨4/7⟩ < ⟨3/5⟩이라 나 모둠이 더 많아요."]},{"stem":"가 모둠은 과자 반죽 5개를 8명이, 나 모둠은 과자 반죽 2개를 3명이 똑같이 나누었어요. 한 명이 가지는 과자 반죽이 더 많은 모둠은 어디인가요?","options":[{"t":"나 모둠","correct":true},{"t":"가 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 5 ÷ 8 = ⟨5/8⟩, 나 모둠은 2 ÷ 3 = ⟨2/3⟩예요.","24로 통분하면 ⟨5/8⟩ = ⟨15/24⟩, ⟨2/3⟩ = ⟨16/24⟩이에요.","⟨5/8⟩ < ⟨2/3⟩라 나 모둠이 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L02_challenge#8','math',6,1,'u1','L02','g6_1_math_u1_L02_challenge','lesson_challenge','M6-1-u1-C2',4,'sa','auto','□ ÷ 9의 몫이 1보다 작을 때, □에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u1-C2","difficulty":4,"kind":"sa","stem":"□ ÷ 9의 몫이 1보다 작을 때, □에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["□ ÷ 9 = ⟨□/9⟩이에요.","몫이 1보다 작으려면 □가 9보다 작아야 해요.","1부터 8까지 8개예요."],"mis":"M6-1-u1-X03","variant_rule":{"alt":[{"stem":"□ ÷ 12의 몫이 1보다 작을 때, □에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["□ ÷ 12 = ⟨□/12⟩이에요.","몫이 1보다 작으려면 □가 12보다 작아야 해요.","1부터 11까지 11개예요."]},{"stem":"□ ÷ 15의 몫이 1보다 작을 때, □에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["□ ÷ 15 = ⟨□/15⟩이에요.","몫이 1보다 작으려면 □가 15보다 작아야 해요.","1부터 14까지 14개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L02_challenge#9','math',6,1,'u1','L02','g6_1_math_u1_L02_challenge','lesson_challenge','M6-1-u1-C2',4,'sa','auto','색 테이프 5 m를 몇 명이 똑같이 나누었더니 한 명이 ⟨5/8⟩ m씩 가졌어요. 나눈 사람은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u1-C2","difficulty":4,"kind":"sa","stem":"색 테이프 5 m를 몇 명이 똑같이 나누었더니 한 명이 ⟨5/8⟩ m씩 가졌어요. 나눈 사람은 몇 명인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["색 테이프 5 m를 □명이 나누면 한 명 몫은 5 ÷ □예요.","5 ÷ □ = ⟨5/8⟩ — 나누는 수가 분모예요.","그래서 8명이 나누었어요."],"mis":"M6-1-u1-X01","variant_rule":{"alt":[{"stem":"주스 3 L를 몇 명이 똑같이 나누었더니 한 명이 ⟨3/7⟩ L씩 가졌어요. 나눈 사람은 몇 명인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["주스 3 L를 □명이 나누면 한 명 몫은 3 ÷ □예요.","3 ÷ □ = ⟨3/7⟩ — 나누는 수가 분모예요.","그래서 7명이 나누었어요."]},{"stem":"시루떡 4개를 몇 명이 똑같이 나누었더니 한 명이 ⟨4/9⟩개씩 가졌어요. 나눈 사람은 몇 명인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["시루떡 4개를 □명이 나누면 한 명 몫은 4 ÷ □예요.","4 ÷ □ = ⟨4/9⟩ — 나누는 수가 분모예요.","그래서 9명이 나누었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L02_challenge#10','math',6,1,'u1','L02','g6_1_math_u1_L02_challenge','lesson_challenge','M6-1-u1-C1',4,'essay','teacher','과자 반죽 2개를 3명이 똑같이 나누려고 해요. 2 ÷ 3을 「몫 0, 나머지 2」로 적으면 무엇이 부족한지 쓰고, 한 명 몫을 분수로 나타내는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u1-C1","difficulty":4,"kind":"essay","stem":"과자 반죽 2개를 3명이 똑같이 나누려고 해요. 2 ÷ 3을 「몫 0, 나머지 2」로 적으면 무엇이 부족한지 쓰고, 한 명 몫을 분수로 나타내는 방법을 설명해 보세요.","answer_guide":{"answer":"예: 몫 0, 나머지 2로 적으면 한 명이 실제로 얼마를 가지는지 알 수 없고, 남은 반죽 2개를 나누지 않고 둔 셈이 된다. 반죽 2개를 각각 3조각으로 자르면 조각은 모두 6개이고, 한 명은 2조각씩 가진다. 한 조각이 ⟨1/3⟩개이므로 한 명 몫은 ⟨2/3⟩개, 곧 2 ÷ 3 = ⟨2/3⟩이다.","scoring_points":["몫과 나머지로는 한 명 몫을 알 수 없다고 썼는가","남은 것도 똑같이 나누는 방법(조각으로 자르기)을 설명했는가","2 ÷ 3 = ⟨2/3⟩를 구했는가"]},"explanation":["몫 0, 나머지 2로는 한 명 몫이 보이지 않아요.","반죽을 3조각씩 자르면 한 명은 2조각씩 가져요.","2 ÷ 3 = ⟨2/3⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L03_basic#1','math',6,1,'u1','L03','g6_1_math_u1_L03_basic','lesson_basic','M6-1-u1-C3',1,'mc','auto','빵 7개를 4명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 빵을 대분수로 나타내면 몇 개인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X02','M6-1-u1-X04']::text[],true,'{"seq":1,"concept":"M6-1-u1-C3","difficulty":1,"kind":"mc","stem":"빵 7개를 4명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 빵을 대분수로 나타내면 몇 개인가요?","options":[{"t":"⟨1 3/4⟩","correct":true},{"t":"⟨4/7⟩","mis":"M6-1-u1-X01"},{"t":"⟨3/4⟩","mis":"M6-1-u1-X02"},{"t":"⟨1 3/7⟩","mis":"M6-1-u1-X04"}],"explanation":["먼저 1씩 나누어 주면 3이 남아요 — 7 ÷ 4는 몫 1, 나머지 3이에요.","남은 3도 4로 똑같이 나누면 ⟨3/4⟩씩 더 가져요.","7 ÷ 4 = ⟨1 3/4⟩ — ⟨1 3/4⟩개예요."],"variant_rule":{"alt":[{"stem":"흰 종이 4장을 3명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 흰 종이를 대분수로 나타내면 몇 장인가요?","options":[{"t":"⟨1 1/3⟩","correct":true},{"t":"⟨3/4⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/3⟩","mis":"M6-1-u1-X02"},{"t":"⟨1 1/4⟩","mis":"M6-1-u1-X04"}],"explanation":["먼저 1씩 나누어 주면 1이 남아요 — 4 ÷ 3은 몫 1, 나머지 1이에요.","남은 1도 3으로 똑같이 나누면 ⟨1/3⟩씩 더 가져요.","4 ÷ 3 = ⟨1 1/3⟩ — ⟨1 1/3⟩장예요."]},{"stem":"시루떡 5개를 2명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 시루떡을 대분수로 나타내면 몇 개인가요?","options":[{"t":"⟨2 1/2⟩","correct":true},{"t":"⟨2/5⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/2⟩","mis":"M6-1-u1-X02"},{"t":"⟨2 1/5⟩","mis":"M6-1-u1-X04"}],"explanation":["먼저 2씩 나누어 주면 1이 남아요 — 5 ÷ 2는 몫 2, 나머지 1이에요.","남은 1도 2로 똑같이 나누면 ⟨1/2⟩씩 더 가져요.","5 ÷ 2 = ⟨2 1/2⟩ — ⟨2 1/2⟩개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L03_basic#2','math',6,1,'u1','L03','g6_1_math_u1_L03_basic','lesson_basic','M6-1-u1-C3',1,'sa','auto','9 ÷ 5의 몫을 가분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u1-C3","difficulty":1,"kind":"sa","stem":"9 ÷ 5의 몫을 가분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["몫이 1보다 커도 나누어지는 수가 분자, 나누는 수가 분모예요.","9 ÷ 5 = ⟨9/5⟩예요.","그래서 분자는 9예요."],"mis":"M6-1-u1-X01","variant_rule":{"alt":[{"stem":"11 ÷ 4의 몫을 가분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["몫이 1보다 커도 나누어지는 수가 분자, 나누는 수가 분모예요.","11 ÷ 4 = ⟨11/4⟩이에요.","그래서 분자는 11이에요."]},{"stem":"13 ÷ 6의 몫을 가분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["몫이 1보다 커도 나누어지는 수가 분자, 나누는 수가 분모예요.","13 ÷ 6 = ⟨13/6⟩이에요.","그래서 분자는 13이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L03_basic#3','math',6,1,'u1','L03','g6_1_math_u1_L03_basic','lesson_basic','M6-1-u1-C3',1,'mc','auto','⟨1 2/3⟩를 가분수로 나타내면 어느 것인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X05']::text[],true,'{"seq":3,"concept":"M6-1-u1-C3","difficulty":1,"kind":"mc","stem":"⟨1 2/3⟩를 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨5/3⟩","correct":true},{"t":"⟨3/5⟩","mis":"M6-1-u1-X01"},{"t":"⟨3/3⟩","mis":"M6-1-u1-X05"},{"t":"⟨2/3⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 1은 ⟨3/3⟩이에요 — 1 × 3 = 3.","여기에 ⟨2/3⟩를 더하면 분자는 3 + 2 = 5예요.","⟨1 2/3⟩ = ⟨5/3⟩예요."],"variant_rule":{"alt":[{"stem":"⟨2 1/4⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨9/4⟩","correct":true},{"t":"⟨4/9⟩","mis":"M6-1-u1-X01"},{"t":"⟨3/4⟩","mis":"M6-1-u1-X05"},{"t":"⟨2/4⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 2는 ⟨8/4⟩이에요 — 2 × 4 = 8.","여기에 ⟨1/4⟩을 더하면 분자는 8 + 1 = 9예요.","⟨2 1/4⟩ = ⟨9/4⟩예요."]},{"stem":"⟨1 3/5⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨8/5⟩","correct":true},{"t":"⟨5/8⟩","mis":"M6-1-u1-X01"},{"t":"⟨4/5⟩","mis":"M6-1-u1-X05"},{"t":"⟨3/5⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 1은 ⟨5/5⟩예요 — 1 × 5 = 5.","여기에 ⟨3/5⟩을 더하면 분자는 5 + 3 = 8이에요.","⟨1 3/5⟩ = ⟨8/5⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L03_basic#4','math',6,1,'u1','L03','g6_1_math_u1_L03_basic','lesson_basic','M6-1-u1-C3',1,'sa','auto','13 ÷ 5의 몫을 대분수로 나타낼 때 자연수 부분에 오는 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u1-C3","difficulty":1,"kind":"sa","stem":"13 ÷ 5의 몫을 대분수로 나타낼 때 자연수 부분에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["13 ÷ 5는 몫 2, 나머지 3이에요.","남은 3도 5로 나누면 ⟨3/5⟩ — 몫은 ⟨2 3/5⟩이에요.","그래서 자연수 부분은 2예요."],"mis":"M6-1-u1-X04","variant_rule":{"alt":[{"stem":"11 ÷ 3의 몫을 대분수로 나타낼 때 자연수 부분에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["11 ÷ 3은 몫 3, 나머지 2예요.","남은 2도 3으로 나누면 ⟨2/3⟩ — 몫은 ⟨3 2/3⟩예요.","그래서 자연수 부분은 3이에요."]},{"stem":"17 ÷ 4의 몫을 대분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["17 ÷ 4는 몫 4, 나머지 1이에요.","남은 1도 4로 나누면 ⟨1/4⟩ — 몫은 ⟨4 1/4⟩이에요.","그래서 분자는 1이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L03_basic#5','math',6,1,'u1','L03','g6_1_math_u1_L03_basic','lesson_basic','M6-1-u1-C3',2,'mc','auto','⟨11/4⟩을 대분수로 나타내면 어느 것인가요?',ARRAY['M6-1-u1-X04','M6-1-u1-X12']::text[],true,'{"seq":5,"concept":"M6-1-u1-C3","difficulty":2,"kind":"mc","stem":"⟨11/4⟩을 대분수로 나타내면 어느 것인가요?","options":[{"t":"⟨2 3/4⟩","correct":true},{"t":"⟨3 2/4⟩","mis":"M6-1-u1-X04"},{"t":"⟨2 3/11⟩","mis":"M6-1-u1-X04"},{"t":"⟨2 1/4⟩","mis":"M6-1-u1-X12"}],"explanation":["분모 4만큼 모이면 1이에요.","11을 4씩 묶으면 2묶음이고 3이 남아요.","⟨11/4⟩ = ⟨2 3/4⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨13/5⟩을 대분수로 나타내면 어느 것인가요?","options":[{"t":"⟨2 3/5⟩","correct":true},{"t":"⟨3 2/5⟩","mis":"M6-1-u1-X04"},{"t":"⟨2 3/13⟩","mis":"M6-1-u1-X04"},{"t":"⟨2 2/5⟩","mis":"M6-1-u1-X12"}],"explanation":["분모 5만큼 모이면 1이에요.","13을 5씩 묶으면 2묶음이고 3이 남아요.","⟨13/5⟩ = ⟨2 3/5⟩이에요."]},{"stem":"⟨17/6⟩을 대분수로 나타내면 어느 것인가요?","options":[{"t":"⟨2 5/6⟩","correct":true},{"t":"⟨5 2/6⟩","mis":"M6-1-u1-X04"},{"t":"⟨2 5/17⟩","mis":"M6-1-u1-X04"},{"t":"⟨2 1/6⟩","mis":"M6-1-u1-X12"}],"explanation":["분모 6만큼 모이면 1이에요.","17을 6씩 묶으면 2묶음이고 5가 남아요.","⟨17/6⟩ = ⟨2 5/6⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L03_basic#6','math',6,1,'u1','L03','g6_1_math_u1_L03_basic','lesson_basic','M6-1-u1-C3',2,'mc','auto','몫이 1보다 큰 나눗셈은 어느 것인가요?',ARRAY['M6-1-u1-X03']::text[],true,'{"seq":6,"concept":"M6-1-u1-C3","difficulty":2,"kind":"mc","stem":"몫이 1보다 큰 나눗셈은 어느 것인가요?","options":[{"t":"11 ÷ 4","correct":true},{"t":"5 ÷ 8","mis":"M6-1-u1-X03"},{"t":"3 ÷ 3","mis":"M6-1-u1-X03"},{"t":"7 ÷ 9","mis":"M6-1-u1-X03"}],"explanation":["나누어지는 수가 나누는 수보다 작으면 몫은 1보다 작고, 크면 1보다 커요.","5 ÷ 8 = ⟨5/8⟩, 3 ÷ 3 = 1, 7 ÷ 9 = ⟨7/9⟩, 11 ÷ 4 = ⟨2 3/4⟩이에요.","그래서 몫이 1보다 큰 것은 11 ÷ 4예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 몫이 1보다 큰 나눗셈은 어느 것인가요?","options":[{"t":"9 ÷ 7","correct":true},{"t":"4 ÷ 9","mis":"M6-1-u1-X03"},{"t":"6 ÷ 6","mis":"M6-1-u1-X03"},{"t":"2 ÷ 5","mis":"M6-1-u1-X03"}],"explanation":["나누어지는 수가 나누는 수보다 작으면 몫은 1보다 작고, 크면 1보다 커요.","4 ÷ 9 = ⟨4/9⟩, 6 ÷ 6 = 1, 9 ÷ 7 = ⟨1 2/7⟩, 2 ÷ 5 = ⟨2/5⟩예요.","그래서 몫이 1보다 큰 것은 9 ÷ 7이에요."]},{"stem":"이번에는 다른 보기예요. 몫이 1보다 큰 나눗셈은 어느 것인가요?","options":[{"t":"13 ÷ 6","correct":true},{"t":"8 ÷ 8","mis":"M6-1-u1-X03"},{"t":"3 ÷ 10","mis":"M6-1-u1-X03"},{"t":"5 ÷ 7","mis":"M6-1-u1-X03"}],"explanation":["나누어지는 수가 나누는 수보다 작으면 몫은 1보다 작고, 크면 1보다 커요.","8 ÷ 8 = 1, 3 ÷ 10 = ⟨3/10⟩, 13 ÷ 6 = ⟨2 1/6⟩, 5 ÷ 7 = ⟨5/7⟩예요.","그래서 몫이 1보다 큰 것은 13 ÷ 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L03_basic#7','math',6,1,'u1','L03','g6_1_math_u1_L03_basic','lesson_basic','M6-1-u1-C3',2,'ox','auto','4 ÷ 3의 몫은 ⟨4/3⟩로도 ⟨1 1/3⟩로도 나타낼 수 있어요.',ARRAY['M6-1-u1-X11']::text[],true,'{"seq":7,"concept":"M6-1-u1-C3","difficulty":2,"kind":"ox","stem":"4 ÷ 3의 몫은 ⟨4/3⟩로도 ⟨1 1/3⟩로도 나타낼 수 있어요.","answer":"O","reason_options":[{"t":"⟨4/3⟩ = ⟨1 1/3⟩ — 같은 수를 가분수와 대분수로 적은 것이므로","correct":true},{"t":"두 수는 크기가 달라 하나만 맞으므로","mis":"M6-1-u1-X11"}],"mis":"M6-1-u1-X11","explanation":["4 ÷ 3 = ⟨4/3⟩예요.","⟨4/3⟩ = ⟨1 1/3⟩이에요.","그래서 둘 다 맞아요."],"variant_rule":{"alt":[{"stem":"7 ÷ 2의 몫은 「3 나머지 1」로만 나타낼 수 있어요.","answer":"X","reason_options":[{"t":"남은 1도 2로 나누면 몫을 ⟨3 1/2⟩로 나타낼 수 있으므로","correct":true},{"t":"나머지가 있으면 분수로 나타낼 수 없으므로","mis":"M6-1-u1-X02"}],"explanation":["7 ÷ 2는 몫 3, 나머지 1이에요.","남은 1을 2로 나누면 ⟨1/2⟩이에요.","7 ÷ 2 = ⟨3 1/2⟩이에요."]},{"stem":"13 ÷ 6의 몫을 가분수로 나타내면 ⟨6/13⟩이에요.","answer":"X","reason_options":[{"t":"나누어지는 수 13이 분자, 나누는 수 6이 분모라 ⟨13/6⟩이므로","correct":true},{"t":"몫이 1보다 크면 분모가 더 커야 하므로","mis":"M6-1-u1-X01"}],"explanation":["나누어지는 수가 분자예요.","13 ÷ 6 = ⟨13/6⟩이에요.","⟨6/13⟩은 1보다 작아 몫이 될 수 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L03_basic#8','math',6,1,'u1','L03','g6_1_math_u1_L03_basic','lesson_basic','M6-1-u1-C3',2,'match','auto','나눗셈과 몫을 대분수로 나타낸 것을 알맞게 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u1-C3","difficulty":2,"kind":"match","stem":"나눗셈과 몫을 대분수로 나타낸 것을 알맞게 이으세요.","pairs":[{"l":"7 ÷ 2","r":"⟨3 1/2⟩"},{"l":"8 ÷ 3","r":"⟨2 2/3⟩"},{"l":"9 ÷ 4","r":"⟨2 1/4⟩"}],"mis":"M6-1-u1-X04","explanation":["몫과 나머지를 먼저 구하고 남은 것을 나누어요.","7 ÷ 2 = ⟨3 1/2⟩, 8 ÷ 3 = ⟨2 2/3⟩, 9 ÷ 4 = ⟨2 1/4⟩이에요.","나머지가 분자, 나누는 수가 분모예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 나눗셈과 몫을 대분수로 나타낸 것을 알맞게 이으세요.","pairs":[{"l":"5 ÷ 3","r":"⟨1 2/3⟩"},{"l":"11 ÷ 4","r":"⟨2 3/4⟩"},{"l":"7 ÷ 5","r":"⟨1 2/5⟩"}],"explanation":["몫과 나머지를 먼저 구하고 남은 것을 나누어요.","5 ÷ 3 = ⟨1 2/3⟩, 11 ÷ 4 = ⟨2 3/4⟩, 7 ÷ 5 = ⟨1 2/5⟩예요.","나머지가 분자, 나누는 수가 분모예요."]},{"stem":"이번에는 다른 보기예요. 나눗셈과 몫을 대분수로 나타낸 것을 알맞게 이으세요.","pairs":[{"l":"13 ÷ 6","r":"⟨2 1/6⟩"},{"l":"10 ÷ 3","r":"⟨3 1/3⟩"},{"l":"9 ÷ 2","r":"⟨4 1/2⟩"}],"explanation":["몫과 나머지를 먼저 구하고 남은 것을 나누어요.","13 ÷ 6 = ⟨2 1/6⟩, 10 ÷ 3 = ⟨3 1/3⟩, 9 ÷ 2 = ⟨4 1/2⟩이에요.","나머지가 분자, 나누는 수가 분모예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L03_basic#9','math',6,1,'u1','L03','g6_1_math_u1_L03_basic','lesson_basic','M6-1-u1-C3',2,'sa','auto','쌀 17 kg을 5봉지에 똑같이 나누어 담으려고 해요. 한 봉지에 담는 쌀을 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u1-C3","difficulty":2,"kind":"sa","stem":"쌀 17 kg을 5봉지에 똑같이 나누어 담으려고 해요. 한 봉지에 담는 쌀을 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["17 ÷ 5는 몫 3, 나머지 2예요.","남은 2도 나누면 17 ÷ 5 = ⟨3 2/5⟩예요.","자연수 부분과 분자의 합은 3 + 2 = 5예요."],"mis":"M6-1-u1-X15","variant_rule":{"alt":[{"stem":"끈 13 m를 4도막으로 똑같이 나누어 자르려고 해요. 한 도막의 길이를 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["13 ÷ 4는 몫 3, 나머지 1이에요.","남은 1도 나누면 13 ÷ 4 = ⟨3 1/4⟩이에요.","자연수 부분과 분자의 합은 3 + 1 = 4예요."]},{"stem":"색 모래 11 kg을 3모둠이 똑같이 나누어 가지려고 해요. 한 모둠이 가지는 색 모래를 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["11 ÷ 3은 몫 3, 나머지 2예요.","남은 2도 나누면 11 ÷ 3 = ⟨3 2/3⟩예요.","자연수 부분과 분자의 합은 3 + 2 = 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L03_basic#10','math',6,1,'u1','L03','g6_1_math_u1_L03_basic','lesson_basic','M6-1-u1-C3',3,'mc','auto','가 모둠은 시루떡 9개를 4명이, 나 모둠은 시루떡 7개를 3명이 똑같이 나누었어요. 한 명이 가지는 시루떡이 더 많은 모둠은 어디인가요?',ARRAY['M6-1-u1-X11','M6-1-u1-X03']::text[],true,'{"seq":10,"concept":"M6-1-u1-C3","difficulty":3,"kind":"mc","stem":"가 모둠은 시루떡 9개를 4명이, 나 모둠은 시루떡 7개를 3명이 똑같이 나누었어요. 한 명이 가지는 시루떡이 더 많은 모둠은 어디인가요?","options":[{"t":"나 모둠","correct":true},{"t":"가 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 9 ÷ 4 = ⟨2 1/4⟩, 나 모둠은 7 ÷ 3 = ⟨2 1/3⟩이에요.","12로 통분하면 ⟨2 1/4⟩ = ⟨27/12⟩, ⟨2 1/3⟩ = ⟨28/12⟩이에요.","⟨2 1/4⟩ < ⟨2 1/3⟩이라 나 모둠이 더 많아요."],"variant_rule":{"alt":[{"stem":"가 모둠은 빵 7개를 5명이, 나 모둠은 빵 4개를 3명이 똑같이 나누었어요. 한 명이 가지는 빵이 더 많은 모둠은 어디인가요?","options":[{"t":"가 모둠","correct":true},{"t":"나 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 7 ÷ 5 = ⟨1 2/5⟩, 나 모둠은 4 ÷ 3 = ⟨1 1/3⟩이에요.","15로 통분하면 ⟨1 2/5⟩ = ⟨21/15⟩, ⟨1 1/3⟩ = ⟨20/15⟩이에요.","⟨1 2/5⟩ > ⟨1 1/3⟩이라 가 모둠이 더 많아요."]},{"stem":"가 모둠은 피자 11판을 4명이, 나 모둠은 피자 8판을 3명이 똑같이 나누었어요. 한 명이 가지는 피자가 더 많은 모둠은 어디인가요?","options":[{"t":"가 모둠","correct":true},{"t":"나 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 11 ÷ 4 = ⟨2 3/4⟩, 나 모둠은 8 ÷ 3 = ⟨2 2/3⟩예요.","12로 통분하면 ⟨2 3/4⟩ = ⟨33/12⟩, ⟨2 2/3⟩ = ⟨32/12⟩예요.","⟨2 3/4⟩ > ⟨2 2/3⟩라 가 모둠이 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L03_challenge#1','math',6,1,'u1','L03','g6_1_math_u1_L03_challenge','lesson_challenge','M6-1-u1-C3',2,'sa','auto','19 ÷ 4의 몫을 대분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u1-C3","difficulty":2,"kind":"sa","stem":"19 ÷ 4의 몫을 대분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["19 ÷ 4는 몫 4, 나머지 3이에요.","남은 3도 4로 나누면 ⟨3/4⟩ — 몫은 ⟨4 3/4⟩이에요.","그래서 분자는 3이에요."],"mis":"M6-1-u1-X04","variant_rule":{"alt":[{"stem":"23 ÷ 6의 몫을 대분수로 나타낼 때 자연수 부분에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["23 ÷ 6은 몫 3, 나머지 5예요.","남은 5도 6으로 나누면 ⟨5/6⟩ — 몫은 ⟨3 5/6⟩예요.","그래서 자연수 부분은 3이에요."]},{"stem":"26 ÷ 7의 몫을 대분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["26 ÷ 7은 몫 3, 나머지 5예요.","남은 5도 7로 나누면 ⟨5/7⟩ — 몫은 ⟨3 5/7⟩예요.","그래서 분자는 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L03_challenge#2','math',6,1,'u1','L03','g6_1_math_u1_L03_challenge','lesson_challenge','M6-1-u1-C3',2,'mc','auto','흰 종이 4장을 3명이 나누어요. 「먼저 1장씩 나누고 남은 것을 또 나누기」로 구한 ⟨1 1/3⟩과 「모두 3조각씩 잘라 나누기」로 구한 ⟨4/3⟩는 어떤 관계인가요?',ARRAY['M6-1-u1-X11','M6-1-u1-X02']::text[],true,'{"seq":2,"concept":"M6-1-u1-C3","difficulty":2,"kind":"mc","stem":"흰 종이 4장을 3명이 나누어요. 「먼저 1장씩 나누고 남은 것을 또 나누기」로 구한 ⟨1 1/3⟩과 「모두 3조각씩 잘라 나누기」로 구한 ⟨4/3⟩는 어떤 관계인가요?","options":[{"t":"같은 양을 다르게 적은 것이다","correct":true},{"t":"대분수 쪽이 더 많다","mis":"M6-1-u1-X11"},{"t":"가분수 쪽이 더 많다","mis":"M6-1-u1-X11"},{"t":"한 가지 방법만 맞다","mis":"M6-1-u1-X02"}],"explanation":["방법 ①은 1씩 나누고 남은 1을 3으로 나누어 ⟨1 1/3⟩이에요.","방법 ②는 ⟨1/3⟩ 조각을 4개씩 가져 ⟨4/3⟩예요.","⟨4/3⟩ = ⟨1 1/3⟩ — 같은 수예요."],"variant_rule":{"alt":[{"stem":"시루떡 5개를 2명이 나누어요. 「먼저 2개씩 나누고 남은 것을 또 나누기」로 구한 ⟨2 1/2⟩과 「모두 2조각씩 잘라 나누기」로 구한 ⟨5/2⟩는 어떤 관계인가요?","options":[{"t":"같은 양을 다르게 적은 것이다","correct":true},{"t":"대분수 쪽이 더 많다","mis":"M6-1-u1-X11"},{"t":"가분수 쪽이 더 많다","mis":"M6-1-u1-X11"},{"t":"한 가지 방법만 맞다","mis":"M6-1-u1-X02"}],"explanation":["방법 ①은 2씩 나누고 남은 1을 2로 나누어 ⟨2 1/2⟩이에요.","방법 ②는 ⟨1/2⟩ 조각을 5개씩 가져 ⟨5/2⟩예요.","⟨5/2⟩ = ⟨2 1/2⟩ — 같은 수예요."]},{"stem":"빵 7개를 3명이 나누어요. 「먼저 2개씩 나누고 남은 것을 또 나누기」로 구한 ⟨2 1/3⟩과 「모두 3조각씩 잘라 나누기」로 구한 ⟨7/3⟩은 어떤 관계인가요?","options":[{"t":"같은 양을 다르게 적은 것이다","correct":true},{"t":"대분수 쪽이 더 많다","mis":"M6-1-u1-X11"},{"t":"가분수 쪽이 더 많다","mis":"M6-1-u1-X11"},{"t":"한 가지 방법만 맞다","mis":"M6-1-u1-X02"}],"explanation":["방법 ①은 2씩 나누고 남은 1을 3으로 나누어 ⟨2 1/3⟩이에요.","방법 ②는 ⟨1/3⟩ 조각을 7개씩 가져 ⟨7/3⟩이에요.","⟨7/3⟩ = ⟨2 1/3⟩ — 같은 수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L03_challenge#3','math',6,1,'u1','L03','g6_1_math_u1_L03_challenge','lesson_challenge','M6-1-u1-C3',3,'error','auto','11 ÷ 3의 몫을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u1-X02','M6-1-u1-X15']::text[],true,'{"seq":3,"concept":"M6-1-u1-C3","difficulty":3,"kind":"error","stem":"11 ÷ 3의 몫을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「몫 3, 나머지 2야. 더는 나눌 수 없어.」","correct":true,"mis_target":"M6-1-u1-X02"},{"t":"도윤 — 「몫은 ⟨11/3⟩이야.」","mis":"M6-1-u1-X15"},{"t":"하린 — 「몫은 ⟨3 2/3⟩야.」","mis":"M6-1-u1-X15"}],"explanation":["남은 2도 3으로 똑같이 나눌 수 있어요.","그러면 11 ÷ 3 = ⟨11/3⟩ = ⟨3 2/3⟩예요.","수아는 남은 것을 나눌 수 없다고 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"9 ÷ 2의 몫을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민준 — 「몫 4, 나머지 1이야. 더는 나눌 수 없어.」","correct":true,"mis_target":"M6-1-u1-X02"},{"t":"서연 — 「몫은 ⟨9/2⟩야.」","mis":"M6-1-u1-X15"},{"t":"지호 — 「몫은 ⟨4 1/2⟩이야.」","mis":"M6-1-u1-X15"}],"explanation":["남은 1도 2로 똑같이 나눌 수 있어요.","그러면 9 ÷ 2 = ⟨9/2⟩ = ⟨4 1/2⟩이에요.","민준은 남은 것을 나눌 수 없다고 잘못 말했어요."]},{"stem":"14 ÷ 5의 몫을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「몫 2, 나머지 4야. 더는 나눌 수 없어.」","correct":true,"mis_target":"M6-1-u1-X02"},{"t":"나린 — 「몫은 ⟨14/5⟩야.」","mis":"M6-1-u1-X15"},{"t":"유진 — 「몫은 ⟨2 4/5⟩야.」","mis":"M6-1-u1-X15"}],"explanation":["남은 4도 5로 똑같이 나눌 수 있어요.","그러면 14 ÷ 5 = ⟨14/5⟩ = ⟨2 4/5⟩예요.","가온은 남은 것을 나눌 수 없다고 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L03_challenge#4','math',6,1,'u1','L03','g6_1_math_u1_L03_challenge','lesson_challenge','M6-1-u1-C3',3,'mc','auto','가 모둠은 주스 7 L를 4명이, 나 모둠은 주스 9 L를 5명이 똑같이 나누었어요. 한 명이 가지는 주스가 더 많은 모둠은 어디인가요?',ARRAY['M6-1-u1-X11','M6-1-u1-X03']::text[],true,'{"seq":4,"concept":"M6-1-u1-C3","difficulty":3,"kind":"mc","stem":"가 모둠은 주스 7 L를 4명이, 나 모둠은 주스 9 L를 5명이 똑같이 나누었어요. 한 명이 가지는 주스가 더 많은 모둠은 어디인가요?","options":[{"t":"나 모둠","correct":true},{"t":"가 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 7 ÷ 4 = ⟨1 3/4⟩, 나 모둠은 9 ÷ 5 = ⟨1 4/5⟩예요.","20으로 통분하면 ⟨1 3/4⟩ = ⟨35/20⟩, ⟨1 4/5⟩ = ⟨36/20⟩이에요.","⟨1 3/4⟩ < ⟨1 4/5⟩라 나 모둠이 더 많아요."],"variant_rule":{"alt":[{"stem":"가 모둠은 색 모래 10 kg을 3명이, 나 모둠은 색 모래 13 kg을 4명이 똑같이 나누었어요. 한 명이 가지는 색 모래가 더 많은 모둠은 어디인가요?","options":[{"t":"가 모둠","correct":true},{"t":"나 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 10 ÷ 3 = ⟨3 1/3⟩, 나 모둠은 13 ÷ 4 = ⟨3 1/4⟩이에요.","12로 통분하면 ⟨3 1/3⟩ = ⟨40/12⟩, ⟨3 1/4⟩ = ⟨39/12⟩예요.","⟨3 1/3⟩ > ⟨3 1/4⟩이라 가 모둠이 더 많아요."]},{"stem":"가 모둠은 시루떡 8개를 5명이, 나 모둠은 시루떡 5개를 3명이 똑같이 나누었어요. 한 명이 가지는 시루떡이 더 많은 모둠은 어디인가요?","options":[{"t":"나 모둠","correct":true},{"t":"가 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 8 ÷ 5 = ⟨1 3/5⟩, 나 모둠은 5 ÷ 3 = ⟨1 2/3⟩예요.","15로 통분하면 ⟨1 3/5⟩ = ⟨24/15⟩, ⟨1 2/3⟩ = ⟨25/15⟩예요.","⟨1 3/5⟩ < ⟨1 2/3⟩라 나 모둠이 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L03_challenge#5','math',6,1,'u1','L03','g6_1_math_u1_L03_challenge','lesson_challenge','M6-1-u1-C3',3,'sa','auto','쌀 23 kg을 6봉지에 똑같이 나누어 담으려고 해요. 한 봉지에 담는 쌀을 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u1-C3","difficulty":3,"kind":"sa","stem":"쌀 23 kg을 6봉지에 똑같이 나누어 담으려고 해요. 한 봉지에 담는 쌀을 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["23 ÷ 6은 몫 3, 나머지 5예요.","남은 5도 나누면 23 ÷ 6 = ⟨3 5/6⟩예요.","자연수 부분과 분자의 합은 3 + 5 = 8이에요."],"mis":"M6-1-u1-X15","variant_rule":{"alt":[{"stem":"색 테이프 19 m를 7명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 색 테이프를 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["19 ÷ 7은 몫 2, 나머지 5예요.","남은 5도 나누면 19 ÷ 7 = ⟨2 5/7⟩예요.","자연수 부분과 분자의 합은 2 + 5 = 7이에요."]},{"stem":"주스 22 L를 9명이 똑같이 나누어 마시려고 해요. 한 명이 마시는 주스를 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["22 ÷ 9는 몫 2, 나머지 4예요.","남은 4도 나누면 22 ÷ 9 = ⟨2 4/9⟩예요.","자연수 부분과 분자의 합은 2 + 4 = 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L03_challenge#6','math',6,1,'u1','L03','g6_1_math_u1_L03_challenge','lesson_challenge','M6-1-u1-C3',3,'sa','auto','29 ÷ 6의 몫은 어떤 두 자연수 사이에 있어요. 두 수 가운데 작은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u1-C3","difficulty":3,"kind":"sa","stem":"29 ÷ 6의 몫은 어떤 두 자연수 사이에 있어요. 두 수 가운데 작은 수는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["6 × 4 = 24, 6 × 5 = 30이에요.","29 ÷ 6 = ⟨4 5/6⟩예요.","4와 5 사이에 있으니 작은 수는 4예요."],"mis":"M6-1-u1-X03","variant_rule":{"alt":[{"stem":"38 ÷ 7의 몫은 어떤 두 자연수 사이에 있어요. 두 수 가운데 작은 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["7 × 5 = 35, 7 × 6 = 42예요.","38 ÷ 7 = ⟨5 3/7⟩이에요.","5와 6 사이에 있으니 작은 수는 5예요."]},{"stem":"47 ÷ 9의 몫은 어떤 두 자연수 사이에 있어요. 두 수 가운데 작은 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["9 × 5 = 45, 9 × 6 = 54예요.","47 ÷ 9 = ⟨5 2/9⟩예요.","5와 6 사이에 있으니 작은 수는 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L03_challenge#7','math',6,1,'u1','L03','g6_1_math_u1_L03_challenge','lesson_challenge','M6-1-u1-C3',3,'ox','auto','9 ÷ 4의 몫은 ⟨2 4/9⟩예요.',ARRAY['M6-1-u1-X04']::text[],true,'{"seq":7,"concept":"M6-1-u1-C3","difficulty":3,"kind":"ox","stem":"9 ÷ 4의 몫은 ⟨2 4/9⟩예요.","answer":"X","reason_options":[{"t":"9 ÷ 4 = ⟨2 1/4⟩ — 나머지 1을 4로 나누어야 하므로","correct":true},{"t":"몫 2 뒤에 나누어지는 수를 분모로 쓰므로","mis":"M6-1-u1-X04"}],"mis":"M6-1-u1-X04","explanation":["9 ÷ 4는 몫 2, 나머지 1이에요.","남은 1을 4로 나누면 ⟨1/4⟩이에요.","9 ÷ 4 = ⟨2 1/4⟩이에요."],"variant_rule":{"alt":[{"stem":"11 ÷ 5의 몫은 2보다 크고 3보다 작아요.","answer":"O","reason_options":[{"t":"11 ÷ 5 = ⟨2 1/5⟩이므로","correct":true},{"t":"11이 5보다 크니 몫은 5보다 크므로","mis":"M6-1-u1-X03"}],"explanation":["5 × 2 = 10, 5 × 3 = 15예요.","11 ÷ 5 = ⟨2 1/5⟩이에요.","그래서 2와 3 사이 — 맞아요."]},{"stem":"몫이 1보다 큰 나눗셈은 나누어지는 수가 나누는 수보다 커요.","answer":"O","reason_options":[{"t":"분자가 분모보다 커야 1보다 큰 분수가 되므로","correct":true},{"t":"나누는 수가 커야 몫이 커지므로","mis":"M6-1-u1-X11"}],"explanation":["몫 = (나누어지는 수)/(나누는 수)예요.","분자가 분모보다 크면 1보다 큰 분수예요.","그래서 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L03_challenge#8','math',6,1,'u1','L03','g6_1_math_u1_L03_challenge','lesson_challenge','M6-1-u1-C3',4,'sa','auto','□ ÷ 6의 몫을 대분수로 나타내면 ⟨2 5/6⟩예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u1-C3","difficulty":4,"kind":"sa","stem":"□ ÷ 6의 몫을 대분수로 나타내면 ⟨2 5/6⟩예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["□ ÷ 6 = ⟨□/6⟩이니 ⟨2 5/6⟩를 가분수로 고치면 돼요.","2 × 6 + 5 = 17이에요.","⟨2 5/6⟩ = ⟨17/6⟩이니 □는 17이에요."],"mis":"M6-1-u1-X05","variant_rule":{"alt":[{"stem":"□ ÷ 7의 몫을 대분수로 나타내면 ⟨3 2/7⟩예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["23"],"explanation":["□ ÷ 7 = ⟨□/7⟩이니 ⟨3 2/7⟩를 가분수로 고치면 돼요.","3 × 7 + 2 = 23이에요.","⟨3 2/7⟩ = ⟨23/7⟩이니 □는 23이에요."]},{"stem":"□ ÷ 8의 몫을 대분수로 나타내면 ⟨4 3/8⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["□ ÷ 8 = ⟨□/8⟩이니 ⟨4 3/8⟩을 가분수로 고치면 돼요.","4 × 8 + 3 = 35예요.","⟨4 3/8⟩ = ⟨35/8⟩니 □는 35예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L03_challenge#9','math',6,1,'u1','L03','g6_1_math_u1_L03_challenge','lesson_challenge','M6-1-u1-C3',4,'sa','auto','□ ÷ 4의 몫이 2보다 크고 3보다 작을 때, □에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u1-C3","difficulty":4,"kind":"sa","stem":"□ ÷ 4의 몫이 2보다 크고 3보다 작을 때, □에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["8 ÷ 4 = 2, 12 ÷ 4 = 3이에요.","□는 8보다 크고 12보다 작아야 해요.","9부터 11까지 3개예요."],"mis":"M6-1-u1-X03","variant_rule":{"alt":[{"stem":"□ ÷ 5의 몫이 3보다 크고 4보다 작을 때, □에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["15 ÷ 5 = 3, 20 ÷ 5 = 4예요.","□는 15보다 크고 20보다 작아야 해요.","16부터 19까지 4개예요."]},{"stem":"□ ÷ 6의 몫이 2보다 크고 3보다 작을 때, □에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["12 ÷ 6 = 2, 18 ÷ 6 = 3이에요.","□는 12보다 크고 18보다 작아야 해요.","13부터 17까지 5개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L03_challenge#10','math',6,1,'u1','L03','g6_1_math_u1_L03_challenge','lesson_challenge','M6-1-u1-C3',4,'essay','teacher','흰 종이 4장을 3명이 똑같이 나누어 가지려고 해요. 서로 다른 두 가지 방법으로 한 명 몫을 구하고, 두 몫이 같은 수인 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u1-C3","difficulty":4,"kind":"essay","stem":"흰 종이 4장을 3명이 똑같이 나누어 가지려고 해요. 서로 다른 두 가지 방법으로 한 명 몫을 구하고, 두 몫이 같은 수인 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 방법 ① 3장을 1장씩 나누면 1장이 남고, 남은 1장을 3명이 나누면 ⟨1/3⟩장씩 더 가져 ⟨1 1/3⟩장이다. 방법 ② 4장을 모두 3조각씩 자르면 한 조각은 ⟨1/3⟩장이고 한 명은 4조각을 가져 ⟨4/3⟩장이다. ⟨4/3⟩를 대분수로 고치면 ⟨1 1/3⟩이므로 두 몫은 같은 양을 다르게 적은 것이다.","scoring_points":["먼저 1장씩 나누고 남은 것을 나누는 방법으로 ⟨1 1/3⟩장을 구했는가","모두 3조각씩 잘라 ⟨4/3⟩장을 구했는가","⟨4/3⟩ = ⟨1 1/3⟩이라 같다고 설명했는가"]},"explanation":["방법 ①은 ⟨1 1/3⟩장이에요.","방법 ②는 ⟨4/3⟩장이에요.","⟨4/3⟩ = ⟨1 1/3⟩ — 같은 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L04_basic#1','math',6,1,'u1','L04','g6_1_math_u1_L04_basic','lesson_basic','M6-1-u1-C4',1,'mc','auto','7 ÷ 4를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X07']::text[],true,'{"seq":1,"concept":"M6-1-u1-C4","difficulty":1,"kind":"mc","stem":"7 ÷ 4를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"7 × ⟨1/4⟩","correct":true},{"t":"7 × 4","mis":"M6-1-u1-X06"},{"t":"4 × ⟨1/7⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/7⟩ × ⟨1/4⟩","mis":"M6-1-u1-X07"}],"explanation":["÷ 4는 4로 똑같이 나눈 것 중의 1이에요.","× ⟨1/4⟩도 4로 똑같이 나눈 것 중의 1이에요.","그래서 7 ÷ 4 = 7 × ⟨1/4⟩ = ⟨1 3/4⟩이에요."],"variant_rule":{"alt":[{"stem":"3 ÷ 2를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"3 × ⟨1/2⟩","correct":true},{"t":"3 × 2","mis":"M6-1-u1-X06"},{"t":"2 × ⟨1/3⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/3⟩ × ⟨1/2⟩","mis":"M6-1-u1-X07"}],"explanation":["÷ 2는 2로 똑같이 나눈 것 중의 1이에요.","× ⟨1/2⟩도 2로 똑같이 나눈 것 중의 1이에요.","그래서 3 ÷ 2 = 3 × ⟨1/2⟩ = ⟨1 1/2⟩이에요."]},{"stem":"5 ÷ 8을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"5 × ⟨1/8⟩","correct":true},{"t":"5 × 8","mis":"M6-1-u1-X06"},{"t":"8 × ⟨1/5⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/5⟩ × ⟨1/8⟩","mis":"M6-1-u1-X07"}],"explanation":["÷ 8은 8로 똑같이 나눈 것 중의 1이에요.","× ⟨1/8⟩도 8로 똑같이 나눈 것 중의 1이에요.","그래서 5 ÷ 8 = 5 × ⟨1/8⟩ = ⟨5/8⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L04_basic#2','math',6,1,'u1','L04','g6_1_math_u1_L04_basic','lesson_basic','M6-1-u1-C4',1,'sa','auto','9 ÷ 4 = 9 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u1-C4","difficulty":1,"kind":"sa","stem":"9 ÷ 4 = 9 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["÷ 4는 4로 나눈 것 중의 1이에요.","그래서 ⟨1/4⟩을 곱하는 것과 같아요.","9 ÷ 4 = 9 × ⟨1/4⟩ — □는 4예요."],"mis":"M6-1-u1-X07","variant_rule":{"alt":[{"stem":"5 ÷ 6 = 5 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["÷ 6은 6으로 나눈 것 중의 1이에요.","그래서 ⟨1/6⟩을 곱하는 것과 같아요.","5 ÷ 6 = 5 × ⟨1/6⟩ — □는 6이에요."]},{"stem":"8 ÷ 3 = 8 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["÷ 3은 3으로 나눈 것 중의 1이에요.","그래서 ⟨1/3⟩을 곱하는 것과 같아요.","8 ÷ 3 = 8 × ⟨1/3⟩ — □는 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L04_basic#3','math',6,1,'u1','L04','g6_1_math_u1_L04_basic','lesson_basic','M6-1-u1-C4',1,'sa','auto','매듭 장식을 만들려고 끈 6 m를 7도막으로 똑같이 나누어 잘랐어요. 한 도막의 길이는 6 × ⟨1/□⟩ m예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-1-u1-C4","difficulty":1,"kind":"sa","stem":"매듭 장식을 만들려고 끈 6 m를 7도막으로 똑같이 나누어 잘랐어요. 한 도막의 길이는 6 × ⟨1/□⟩ m예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["한 도막의 길이는 6 ÷ 7이에요.","÷ 7은 × ⟨1/7⟩과 같아요.","6 ÷ 7 = 6 × ⟨1/7⟩ = ⟨6/7⟩ — □는 7이에요."],"mis":"M6-1-u1-X07","variant_rule":{"alt":[{"stem":"매듭 장식을 만들려고 끈 3 m를 5도막으로 똑같이 나누어 잘랐어요. 한 도막의 길이는 3 × ⟨1/□⟩ m예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["한 도막의 길이는 3 ÷ 5예요.","÷ 5는 × ⟨1/5⟩과 같아요.","3 ÷ 5 = 3 × ⟨1/5⟩ = ⟨3/5⟩ — □는 5예요."]},{"stem":"매듭 장식을 만들려고 끈 8 m를 9도막으로 똑같이 나누어 잘랐어요. 한 도막의 길이는 8 × ⟨1/□⟩ m예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["한 도막의 길이는 8 ÷ 9예요.","÷ 9는 × ⟨1/9⟩과 같아요.","8 ÷ 9 = 8 × ⟨1/9⟩ = ⟨8/9⟩ — □는 9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L04_basic#4','math',6,1,'u1','L04','g6_1_math_u1_L04_basic','lesson_basic','M6-1-u1-C4',1,'ox','auto','5 ÷ 3 = 5 × 3이에요.',ARRAY['M6-1-u1-X06']::text[],true,'{"seq":4,"concept":"M6-1-u1-C4","difficulty":1,"kind":"ox","stem":"5 ÷ 3 = 5 × 3이에요.","answer":"X","reason_options":[{"t":"÷ 3은 3으로 나눈 것 중의 1이라 5 × ⟨1/3⟩이 되어야 하므로","correct":true},{"t":"나눗셈을 곱셈으로 바꾸면 나누는 수를 그대로 곱하므로","mis":"M6-1-u1-X06"}],"mis":"M6-1-u1-X06","explanation":["5를 3으로 나누면 양이 작아져야 해요.","5 × 3 = 15는 오히려 커요.","5 ÷ 3 = 5 × ⟨1/3⟩ = ⟨1 2/3⟩예요."],"variant_rule":{"alt":[{"stem":"7 ÷ 4 = 7 × ⟨1/4⟩이에요.","answer":"O","reason_options":[{"t":"÷ 4는 4로 나눈 것 중의 1, × ⟨1/4⟩과 뜻이 같으므로","correct":true},{"t":"분모와 분자를 바꾸어 곱하므로","mis":"M6-1-u1-X07"}],"explanation":["÷ 4는 4로 똑같이 나눈 것 중의 1이에요.","× ⟨1/4⟩도 4로 나눈 것 중의 1이에요.","7 ÷ 4 = 7 × ⟨1/4⟩ = ⟨1 3/4⟩ — 맞아요."]},{"stem":"6 ÷ 7과 6 × ⟨1/7⟩은 계산 결과가 같아요.","answer":"O","reason_options":[{"t":"두 식 모두 6을 7로 똑같이 나눈 것 중의 1이므로","correct":true},{"t":"6 × 7을 7로 한 번 더 나누므로","mis":"M6-1-u1-X06"}],"explanation":["6 ÷ 7 = ⟨6/7⟩이에요.","6 × ⟨1/7⟩ = ⟨6/7⟩이에요.","둘 다 ⟨6/7⟩ — 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L04_basic#5','math',6,1,'u1','L04','g6_1_math_u1_L04_basic','lesson_basic','M6-1-u1-C4',2,'mc','auto','13 ÷ 4를 분수의 곱셈으로 나타내어 계산하면 얼마인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X07']::text[],true,'{"seq":5,"concept":"M6-1-u1-C4","difficulty":2,"kind":"mc","stem":"13 ÷ 4를 분수의 곱셈으로 나타내어 계산하면 얼마인가요?","options":[{"t":"⟨3 1/4⟩","correct":true},{"t":"52","mis":"M6-1-u1-X06"},{"t":"⟨4/13⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/52⟩","mis":"M6-1-u1-X07"}],"explanation":["13 ÷ 4 = 13 × ⟨1/4⟩이에요.","13 × ⟨1/4⟩ = ⟨13/4⟩이에요.","⟨13/4⟩ = ⟨3 1/4⟩이에요."],"variant_rule":{"alt":[{"stem":"5 ÷ 3을 분수의 곱셈으로 나타내어 계산하면 얼마인가요?","options":[{"t":"⟨1 2/3⟩","correct":true},{"t":"15","mis":"M6-1-u1-X06"},{"t":"⟨3/5⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/15⟩","mis":"M6-1-u1-X07"}],"explanation":["5 ÷ 3 = 5 × ⟨1/3⟩이에요.","5 × ⟨1/3⟩ = ⟨5/3⟩예요.","⟨5/3⟩ = ⟨1 2/3⟩예요."]},{"stem":"4 ÷ 9를 분수의 곱셈으로 나타내어 계산하면 얼마인가요?","options":[{"t":"⟨4/9⟩","correct":true},{"t":"36","mis":"M6-1-u1-X06"},{"t":"⟨2 1/4⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/36⟩","mis":"M6-1-u1-X07"}],"explanation":["4 ÷ 9 = 4 × ⟨1/9⟩이에요.","4 × ⟨1/9⟩ = ⟨4/9⟩예요.","그래서 몫은 ⟨4/9⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L04_basic#6','math',6,1,'u1','L04','g6_1_math_u1_L04_basic','lesson_basic','M6-1-u1-C4',2,'match','auto','나눗셈과 같은 곱셈식을 알맞게 이으세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u1-C4","difficulty":2,"kind":"match","stem":"나눗셈과 같은 곱셈식을 알맞게 이으세요.","pairs":[{"l":"2 ÷ 5","r":"2 × ⟨1/5⟩"},{"l":"4 ÷ 3","r":"4 × ⟨1/3⟩"},{"l":"7 ÷ 8","r":"7 × ⟨1/8⟩"}],"mis":"M6-1-u1-X07","explanation":["÷(자연수)는 그 수를 분모로 하는 단위분수를 곱해요.","2 ÷ 5 = 2 × ⟨1/5⟩, 4 ÷ 3 = 4 × ⟨1/3⟩, 7 ÷ 8 = 7 × ⟨1/8⟩이에요.","나누어지는 수는 그대로 두어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 나눗셈과 같은 곱셈식을 알맞게 이으세요.","pairs":[{"l":"5 ÷ 6","r":"5 × ⟨1/6⟩"},{"l":"3 ÷ 7","r":"3 × ⟨1/7⟩"},{"l":"9 ÷ 2","r":"9 × ⟨1/2⟩"}],"explanation":["÷(자연수)는 그 수를 분모로 하는 단위분수를 곱해요.","5 ÷ 6 = 5 × ⟨1/6⟩, 3 ÷ 7 = 3 × ⟨1/7⟩, 9 ÷ 2 = 9 × ⟨1/2⟩이에요.","나누어지는 수는 그대로 두어요."]},{"stem":"이번에는 다른 보기예요. 나눗셈과 같은 곱셈식을 알맞게 이으세요.","pairs":[{"l":"1 ÷ 4","r":"1 × ⟨1/4⟩"},{"l":"6 ÷ 5","r":"6 × ⟨1/5⟩"},{"l":"8 ÷ 9","r":"8 × ⟨1/9⟩"}],"explanation":["÷(자연수)는 그 수를 분모로 하는 단위분수를 곱해요.","1 ÷ 4 = 1 × ⟨1/4⟩, 6 ÷ 5 = 6 × ⟨1/5⟩, 8 ÷ 9 = 8 × ⟨1/9⟩이에요.","나누어지는 수는 그대로 두어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L04_basic#7','math',6,1,'u1','L04','g6_1_math_u1_L04_basic','lesson_basic','M6-1-u1-C4',2,'mc','auto','□ ÷ 7을 □ × ⟨1/7⟩로 바꾸어 계산해도 되는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X07','M6-1-u1-X14']::text[],true,'{"seq":7,"concept":"M6-1-u1-C4","difficulty":2,"kind":"mc","stem":"□ ÷ 7을 □ × ⟨1/7⟩로 바꾸어 계산해도 되는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"7로 똑같이 나눈 한 조각이 전체의 ⟨1/7⟩이기 때문","correct":true},{"t":"7로 나누는 것과 7배 하는 것이 같기 때문","mis":"M6-1-u1-X06"},{"t":"분모와 분자를 바꾸면 되기 때문","mis":"M6-1-u1-X07"},{"t":"나눗셈은 언제나 곱셈이기 때문","mis":"M6-1-u1-X14"}],"explanation":["÷ 7은 7로 똑같이 나눈 것 중의 1을 구해요.","× ⟨1/7⟩도 7로 나눈 것 중의 1을 구해요.","뜻이 같아서 바꾸어 계산할 수 있어요."],"variant_rule":{"alt":[{"stem":"□ ÷ 5를 □ × ⟨1/5⟩로 바꾸어 계산해도 되는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"5로 똑같이 나눈 한 조각이 전체의 ⟨1/5⟩이기 때문","correct":true},{"t":"5로 나누는 것과 5배 하는 것이 같기 때문","mis":"M6-1-u1-X06"},{"t":"분모와 분자를 바꾸면 되기 때문","mis":"M6-1-u1-X07"},{"t":"나눗셈은 언제나 곱셈이기 때문","mis":"M6-1-u1-X14"}],"explanation":["÷ 5는 5로 똑같이 나눈 것 중의 1을 구해요.","× ⟨1/5⟩도 5로 나눈 것 중의 1을 구해요.","뜻이 같아서 바꾸어 계산할 수 있어요."]},{"stem":"□ ÷ 9를 □ × ⟨1/9⟩로 바꾸어 계산해도 되는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"9로 똑같이 나눈 한 조각이 전체의 ⟨1/9⟩이기 때문","correct":true},{"t":"9로 나누는 것과 9배 하는 것이 같기 때문","mis":"M6-1-u1-X06"},{"t":"분모와 분자를 바꾸면 되기 때문","mis":"M6-1-u1-X07"},{"t":"나눗셈은 언제나 곱셈이기 때문","mis":"M6-1-u1-X14"}],"explanation":["÷ 9는 9로 똑같이 나눈 것 중의 1을 구해요.","× ⟨1/9⟩도 9로 나눈 것 중의 1을 구해요.","뜻이 같아서 바꾸어 계산할 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L04_basic#8','math',6,1,'u1','L04','g6_1_math_u1_L04_basic','lesson_basic','M6-1-u1-C4',2,'mc','auto','9 ÷ 5를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X07']::text[],true,'{"seq":8,"concept":"M6-1-u1-C4","difficulty":2,"kind":"mc","stem":"9 ÷ 5를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"9 × ⟨1/5⟩","correct":true},{"t":"9 × 5","mis":"M6-1-u1-X06"},{"t":"5 × ⟨1/9⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/9⟩ × ⟨1/5⟩","mis":"M6-1-u1-X07"}],"explanation":["÷ 5는 5로 똑같이 나눈 것 중의 1이에요.","× ⟨1/5⟩도 5로 똑같이 나눈 것 중의 1이에요.","그래서 9 ÷ 5 = 9 × ⟨1/5⟩ = ⟨1 4/5⟩예요."],"variant_rule":{"alt":[{"stem":"4 ÷ 7을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"4 × ⟨1/7⟩","correct":true},{"t":"4 × 7","mis":"M6-1-u1-X06"},{"t":"7 × ⟨1/4⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/4⟩ × ⟨1/7⟩","mis":"M6-1-u1-X07"}],"explanation":["÷ 7은 7로 똑같이 나눈 것 중의 1이에요.","× ⟨1/7⟩도 7로 똑같이 나눈 것 중의 1이에요.","그래서 4 ÷ 7 = 4 × ⟨1/7⟩ = ⟨4/7⟩예요."]},{"stem":"11 ÷ 6을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"11 × ⟨1/6⟩","correct":true},{"t":"11 × 6","mis":"M6-1-u1-X06"},{"t":"6 × ⟨1/11⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/11⟩ × ⟨1/6⟩","mis":"M6-1-u1-X07"}],"explanation":["÷ 6은 6으로 똑같이 나눈 것 중의 1이에요.","× ⟨1/6⟩도 6으로 똑같이 나눈 것 중의 1이에요.","그래서 11 ÷ 6 = 11 × ⟨1/6⟩ = ⟨1 5/6⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L04_basic#9','math',6,1,'u1','L04','g6_1_math_u1_L04_basic','lesson_basic','M6-1-u1-C4',2,'error','auto','다음 중 나눗셈을 분수의 곱셈으로 잘못 나타낸 것은 어느 것인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X15']::text[],true,'{"seq":9,"concept":"M6-1-u1-C4","difficulty":2,"kind":"error","stem":"다음 중 나눗셈을 분수의 곱셈으로 잘못 나타낸 것은 어느 것인가요?","options":[{"t":"7 ÷ 2 = 7 × 2","correct":true,"mis_target":"M6-1-u1-X06"},{"t":"5 ÷ 3 = 5 × ⟨1/3⟩","mis":"M6-1-u1-X15"},{"t":"1 ÷ 6 = 1 × ⟨1/6⟩","mis":"M6-1-u1-X15"}],"explanation":["÷(자연수)는 그 자연수를 분모로 하는 단위분수를 곱하는 것과 같아요.","7 ÷ 2 = 7 × ⟨1/2⟩이어야 해요.","7 × 2는 오히려 커져요 — 잘못 나타낸 거예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 중 나눗셈을 분수의 곱셈으로 잘못 나타낸 것은 어느 것인가요?","options":[{"t":"6 ÷ 5 = 6 × 5","correct":true,"mis_target":"M6-1-u1-X06"},{"t":"9 ÷ 4 = 9 × ⟨1/4⟩","mis":"M6-1-u1-X15"},{"t":"2 ÷ 7 = 2 × ⟨1/7⟩","mis":"M6-1-u1-X15"}],"explanation":["÷(자연수)는 그 자연수를 분모로 하는 단위분수를 곱하는 것과 같아요.","6 ÷ 5 = 6 × ⟨1/5⟩이어야 해요.","6 × 5는 오히려 커져요 — 잘못 나타낸 거예요."]},{"stem":"이번에는 다른 보기예요. 다음 중 나눗셈을 분수의 곱셈으로 잘못 나타낸 것은 어느 것인가요?","options":[{"t":"3 ÷ 4 = 3 × 4","correct":true,"mis_target":"M6-1-u1-X06"},{"t":"4 ÷ 9 = 4 × ⟨1/9⟩","mis":"M6-1-u1-X15"},{"t":"8 ÷ 3 = 8 × ⟨1/3⟩","mis":"M6-1-u1-X15"}],"explanation":["÷(자연수)는 그 자연수를 분모로 하는 단위분수를 곱하는 것과 같아요.","3 ÷ 4 = 3 × ⟨1/4⟩이어야 해요.","3 × 4는 오히려 커져요 — 잘못 나타낸 거예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L04_basic#10','math',6,1,'u1','L04','g6_1_math_u1_L04_basic','lesson_basic','M6-1-u1-C4',3,'mc','auto','끈 8 m를 5도막으로 나눈 한 도막과 끈 5 m를 3도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?',ARRAY['M6-1-u1-X11','M6-1-u1-X03']::text[],true,'{"seq":10,"concept":"M6-1-u1-C4","difficulty":3,"kind":"mc","stem":"끈 8 m를 5도막으로 나눈 한 도막과 끈 5 m를 3도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?","options":[{"t":"끈 5 m를 3도막으로 나눈 한 도막","correct":true},{"t":"끈 8 m를 5도막으로 나눈 한 도막","mis":"M6-1-u1-X11"},{"t":"두 도막의 길이가 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["8 ÷ 5 = 8 × ⟨1/5⟩ = ⟨1 3/5⟩, 5 ÷ 3 = 5 × ⟨1/3⟩ = ⟨1 2/3⟩예요.","15로 통분하면 ⟨1 3/5⟩ = ⟨24/15⟩, ⟨1 2/3⟩ = ⟨25/15⟩예요.","그래서 더 긴 것은 끈 5 m를 3도막으로 나눈 한 도막이에요."],"variant_rule":{"alt":[{"stem":"끈 7 m를 4도막으로 나눈 한 도막과 끈 9 m를 5도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?","options":[{"t":"끈 9 m를 5도막으로 나눈 한 도막","correct":true},{"t":"끈 7 m를 4도막으로 나눈 한 도막","mis":"M6-1-u1-X11"},{"t":"두 도막의 길이가 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["7 ÷ 4 = 7 × ⟨1/4⟩ = ⟨1 3/4⟩, 9 ÷ 5 = 9 × ⟨1/5⟩ = ⟨1 4/5⟩예요.","20으로 통분하면 ⟨1 3/4⟩ = ⟨35/20⟩, ⟨1 4/5⟩ = ⟨36/20⟩이에요.","그래서 더 긴 것은 끈 9 m를 5도막으로 나눈 한 도막이에요."]},{"stem":"끈 5 m를 6도막으로 나눈 한 도막과 끈 4 m를 5도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?","options":[{"t":"끈 5 m를 6도막으로 나눈 한 도막","correct":true},{"t":"끈 4 m를 5도막으로 나눈 한 도막","mis":"M6-1-u1-X11"},{"t":"두 도막의 길이가 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["5 ÷ 6 = 5 × ⟨1/6⟩ = ⟨5/6⟩, 4 ÷ 5 = 4 × ⟨1/5⟩ = ⟨4/5⟩예요.","30으로 통분하면 ⟨5/6⟩ = ⟨25/30⟩, ⟨4/5⟩ = ⟨24/30⟩예요.","그래서 더 긴 것은 끈 5 m를 6도막으로 나눈 한 도막이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L04_challenge#1','math',6,1,'u1','L04','g6_1_math_u1_L04_challenge','lesson_challenge','M6-1-u1-C4',2,'sa','auto','13 ÷ 6 = 13 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u1-C4","difficulty":2,"kind":"sa","stem":"13 ÷ 6 = 13 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["÷ 6은 6으로 나눈 것 중의 1이에요.","그래서 ⟨1/6⟩을 곱하는 것과 같아요.","13 ÷ 6 = 13 × ⟨1/6⟩ — □는 6이에요."],"mis":"M6-1-u1-X07","variant_rule":{"alt":[{"stem":"7 ÷ 9 = 7 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["÷ 9는 9로 나눈 것 중의 1이에요.","그래서 ⟨1/9⟩을 곱하는 것과 같아요.","7 ÷ 9 = 7 × ⟨1/9⟩ — □는 9예요."]},{"stem":"11 ÷ 3 = 11 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["÷ 3은 3으로 나눈 것 중의 1이에요.","그래서 ⟨1/3⟩을 곱하는 것과 같아요.","11 ÷ 3 = 11 × ⟨1/3⟩ — □는 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L04_challenge#2','math',6,1,'u1','L04','g6_1_math_u1_L04_challenge','lesson_challenge','M6-1-u1-C4',2,'mc','auto','17 ÷ 5를 분수의 곱셈으로 나타내어 계산하면 얼마인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X07']::text[],true,'{"seq":2,"concept":"M6-1-u1-C4","difficulty":2,"kind":"mc","stem":"17 ÷ 5를 분수의 곱셈으로 나타내어 계산하면 얼마인가요?","options":[{"t":"⟨3 2/5⟩","correct":true},{"t":"85","mis":"M6-1-u1-X06"},{"t":"⟨5/17⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/85⟩","mis":"M6-1-u1-X07"}],"explanation":["17 ÷ 5 = 17 × ⟨1/5⟩이에요.","17 × ⟨1/5⟩ = ⟨17/5⟩이에요.","⟨17/5⟩ = ⟨3 2/5⟩예요."],"variant_rule":{"alt":[{"stem":"7 ÷ 8을 분수의 곱셈으로 나타내어 계산하면 얼마인가요?","options":[{"t":"⟨7/8⟩","correct":true},{"t":"56","mis":"M6-1-u1-X06"},{"t":"⟨1 1/7⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/56⟩","mis":"M6-1-u1-X07"}],"explanation":["7 ÷ 8 = 7 × ⟨1/8⟩이에요.","7 × ⟨1/8⟩ = ⟨7/8⟩이에요.","그래서 몫은 ⟨7/8⟩이에요."]},{"stem":"19 ÷ 6을 분수의 곱셈으로 나타내어 계산하면 얼마인가요?","options":[{"t":"⟨3 1/6⟩","correct":true},{"t":"114","mis":"M6-1-u1-X06"},{"t":"⟨6/19⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/114⟩","mis":"M6-1-u1-X07"}],"explanation":["19 ÷ 6 = 19 × ⟨1/6⟩이에요.","19 × ⟨1/6⟩ = ⟨19/6⟩예요.","⟨19/6⟩ = ⟨3 1/6⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L04_challenge#3','math',6,1,'u1','L04','g6_1_math_u1_L04_challenge','lesson_challenge','M6-1-u1-C4',3,'mc','auto','5 ÷ 3을 계산할 때 5 × 3으로 하면 안 되는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u1-X15','M6-1-u1-X06','M6-1-u1-X07']::text[],true,'{"seq":3,"concept":"M6-1-u1-C4","difficulty":3,"kind":"mc","stem":"5 ÷ 3을 계산할 때 5 × 3으로 하면 안 되는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나누면 양이 작아져야 하는데 3을 곱하면 오히려 커지기 때문","correct":true},{"t":"곱셈은 나눗셈보다 계산이 어렵기 때문","mis":"M6-1-u1-X15"},{"t":"5 × 3도 맞지만 답이 자연수라서","mis":"M6-1-u1-X06"},{"t":"나누어지는 수를 단위분수로 바꾸어야 하기 때문","mis":"M6-1-u1-X07"}],"explanation":["5를 3으로 나누면 ⟨1 2/3⟩로 5보다 작아져야 해요.","5 × 3 = 15는 오히려 커요.","그래서 5 × ⟨1/3⟩을 곱해요."],"variant_rule":{"alt":[{"stem":"7 ÷ 4를 계산할 때 7 × 4로 하면 안 되는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나누면 양이 작아져야 하는데 4를 곱하면 오히려 커지기 때문","correct":true},{"t":"곱셈은 나눗셈보다 계산이 어렵기 때문","mis":"M6-1-u1-X15"},{"t":"7 × 4도 맞지만 답이 자연수라서","mis":"M6-1-u1-X06"},{"t":"나누어지는 수를 단위분수로 바꾸어야 하기 때문","mis":"M6-1-u1-X07"}],"explanation":["7을 4로 나누면 ⟨1 3/4⟩으로 7보다 작아져야 해요.","7 × 4 = 28은 오히려 커요.","그래서 7 × ⟨1/4⟩을 곱해요."]},{"stem":"9 ÷ 2를 계산할 때 9 × 2로 하면 안 되는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나누면 양이 작아져야 하는데 2를 곱하면 오히려 커지기 때문","correct":true},{"t":"곱셈은 나눗셈보다 계산이 어렵기 때문","mis":"M6-1-u1-X15"},{"t":"9 × 2도 맞지만 답이 자연수라서","mis":"M6-1-u1-X06"},{"t":"나누어지는 수를 단위분수로 바꾸어야 하기 때문","mis":"M6-1-u1-X07"}],"explanation":["9를 2로 나누면 ⟨4 1/2⟩로 9보다 작아져야 해요.","9 × 2 = 18은 오히려 커요.","그래서 9 × ⟨1/2⟩을 곱해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L04_challenge#4','math',6,1,'u1','L04','g6_1_math_u1_L04_challenge','lesson_challenge','M6-1-u1-C4',3,'error','auto','다음 중 나눗셈을 분수의 곱셈으로 잘못 나타낸 것은 어느 것인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X15']::text[],true,'{"seq":4,"concept":"M6-1-u1-C4","difficulty":3,"kind":"error","stem":"다음 중 나눗셈을 분수의 곱셈으로 잘못 나타낸 것은 어느 것인가요?","options":[{"t":"9 ÷ 4 = 9 × 4","correct":true,"mis_target":"M6-1-u1-X06"},{"t":"8 ÷ 5 = 8 × ⟨1/5⟩","mis":"M6-1-u1-X15"},{"t":"3 ÷ 7 = 3 × ⟨1/7⟩","mis":"M6-1-u1-X15"}],"explanation":["÷(자연수)는 그 자연수를 분모로 하는 단위분수를 곱하는 것과 같아요.","9 ÷ 4 = 9 × ⟨1/4⟩이어야 해요.","9 × 4는 오히려 커져요 — 잘못 나타낸 거예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 중 나눗셈을 분수의 곱셈으로 잘못 나타낸 것은 어느 것인가요?","options":[{"t":"4 ÷ 6 = 4 × 6","correct":true,"mis_target":"M6-1-u1-X06"},{"t":"5 ÷ 9 = 5 × ⟨1/9⟩","mis":"M6-1-u1-X15"},{"t":"7 ÷ 3 = 7 × ⟨1/3⟩","mis":"M6-1-u1-X15"}],"explanation":["÷(자연수)는 그 자연수를 분모로 하는 단위분수를 곱하는 것과 같아요.","4 ÷ 6 = 4 × ⟨1/6⟩이어야 해요.","4 × 6은 오히려 커져요 — 잘못 나타낸 거예요."]},{"stem":"이번에는 다른 보기예요. 다음 중 나눗셈을 분수의 곱셈으로 잘못 나타낸 것은 어느 것인가요?","options":[{"t":"10 ÷ 3 = 10 × 3","correct":true,"mis_target":"M6-1-u1-X06"},{"t":"2 ÷ 3 = 2 × ⟨1/3⟩","mis":"M6-1-u1-X15"},{"t":"6 ÷ 11 = 6 × ⟨1/11⟩","mis":"M6-1-u1-X15"}],"explanation":["÷(자연수)는 그 자연수를 분모로 하는 단위분수를 곱하는 것과 같아요.","10 ÷ 3 = 10 × ⟨1/3⟩이어야 해요.","10 × 3은 오히려 커져요 — 잘못 나타낸 거예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L04_challenge#5','math',6,1,'u1','L04','g6_1_math_u1_L04_challenge','lesson_challenge','M6-1-u1-C4',3,'mc','auto','끈 11 m를 4도막으로 나눈 한 도막과 끈 8 m를 3도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?',ARRAY['M6-1-u1-X11','M6-1-u1-X03']::text[],true,'{"seq":5,"concept":"M6-1-u1-C4","difficulty":3,"kind":"mc","stem":"끈 11 m를 4도막으로 나눈 한 도막과 끈 8 m를 3도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?","options":[{"t":"끈 11 m를 4도막으로 나눈 한 도막","correct":true},{"t":"끈 8 m를 3도막으로 나눈 한 도막","mis":"M6-1-u1-X11"},{"t":"두 도막의 길이가 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["11 ÷ 4 = 11 × ⟨1/4⟩ = ⟨2 3/4⟩, 8 ÷ 3 = 8 × ⟨1/3⟩ = ⟨2 2/3⟩예요.","12로 통분하면 ⟨2 3/4⟩ = ⟨33/12⟩, ⟨2 2/3⟩ = ⟨32/12⟩예요.","그래서 더 긴 것은 끈 11 m를 4도막으로 나눈 한 도막이에요."],"variant_rule":{"alt":[{"stem":"끈 9 m를 7도막으로 나눈 한 도막과 끈 4 m를 3도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?","options":[{"t":"끈 4 m를 3도막으로 나눈 한 도막","correct":true},{"t":"끈 9 m를 7도막으로 나눈 한 도막","mis":"M6-1-u1-X11"},{"t":"두 도막의 길이가 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["9 ÷ 7 = 9 × ⟨1/7⟩ = ⟨1 2/7⟩, 4 ÷ 3 = 4 × ⟨1/3⟩ = ⟨1 1/3⟩이에요.","21로 통분하면 ⟨1 2/7⟩ = ⟨27/21⟩, ⟨1 1/3⟩ = ⟨28/21⟩이에요.","그래서 더 긴 것은 끈 4 m를 3도막으로 나눈 한 도막이에요."]},{"stem":"끈 13 m를 5도막으로 나눈 한 도막과 끈 8 m를 3도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?","options":[{"t":"끈 8 m를 3도막으로 나눈 한 도막","correct":true},{"t":"끈 13 m를 5도막으로 나눈 한 도막","mis":"M6-1-u1-X11"},{"t":"두 도막의 길이가 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["13 ÷ 5 = 13 × ⟨1/5⟩ = ⟨2 3/5⟩, 8 ÷ 3 = 8 × ⟨1/3⟩ = ⟨2 2/3⟩예요.","15로 통분하면 ⟨2 3/5⟩ = ⟨39/15⟩, ⟨2 2/3⟩ = ⟨40/15⟩이에요.","그래서 더 긴 것은 끈 8 m를 3도막으로 나눈 한 도막이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L04_challenge#6','math',6,1,'u1','L04','g6_1_math_u1_L04_challenge','lesson_challenge','M6-1-u1-C4',3,'ox','auto','3 ÷ 8 = 8 × ⟨1/3⟩이에요.',ARRAY['M6-1-u1-X07']::text[],true,'{"seq":6,"concept":"M6-1-u1-C4","difficulty":3,"kind":"ox","stem":"3 ÷ 8 = 8 × ⟨1/3⟩이에요.","answer":"X","reason_options":[{"t":"나누는 수 8을 분모로 하는 단위분수를 곱해 3 × ⟨1/8⟩이어야 하므로","correct":true},{"t":"두 수를 바꾸어 써도 곱은 같으므로","mis":"M6-1-u1-X07"}],"mis":"M6-1-u1-X07","explanation":["3 ÷ 8 = ⟨3/8⟩이에요.","8 × ⟨1/3⟩ = ⟨2 2/3⟩로 값이 달라요.","바른 식은 3 ÷ 8 = 3 × ⟨1/8⟩이에요."],"variant_rule":{"alt":[{"stem":"9 ÷ 2를 곱셈으로 바꾸면 9 × ⟨1/2⟩이고, 몫은 ⟨4 1/2⟩이에요.","answer":"O","reason_options":[{"t":"9 × ⟨1/2⟩ = ⟨9/2⟩ = ⟨4 1/2⟩이므로","correct":true},{"t":"9 × 2 = 18의 반이 몫이므로","mis":"M6-1-u1-X06"}],"explanation":["9 ÷ 2 = 9 × ⟨1/2⟩이에요.","9 × ⟨1/2⟩ = ⟨9/2⟩예요.","⟨9/2⟩ = ⟨4 1/2⟩ — 맞아요."]},{"stem":"1 ÷ 5 = 5 × ⟨1/5⟩이에요.","answer":"X","reason_options":[{"t":"나누어지는 수 1에 ⟨1/5⟩을 곱해 1 × ⟨1/5⟩이어야 하므로","correct":true},{"t":"두 수의 자리를 바꾸어도 되므로","mis":"M6-1-u1-X07"}],"explanation":["1 ÷ 5는 1을 5로 나눈 한 조각이에요.","1 ÷ 5 = 1 × ⟨1/5⟩ = ⟨1/5⟩이에요.","5 × ⟨1/5⟩ = 1이라 값이 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L04_challenge#7','math',6,1,'u1','L04','g6_1_math_u1_L04_challenge','lesson_challenge','M6-1-u1-C4',3,'sa','auto','13 ÷ 4를 분수의 곱셈으로 나타내어 계산한 몫을 대분수로 나타냈어요. 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u1-C4","difficulty":3,"kind":"sa","stem":"13 ÷ 4를 분수의 곱셈으로 나타내어 계산한 몫을 대분수로 나타냈어요. 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["13 ÷ 4 = 13 × ⟨1/4⟩ = ⟨13/4⟩이에요.","⟨13/4⟩ = ⟨3 1/4⟩이에요.","자연수 부분과 분자의 합은 3 + 1 = 4예요."],"mis":"M6-1-u1-X15","variant_rule":{"alt":[{"stem":"17 ÷ 3을 분수의 곱셈으로 나타내어 계산한 몫을 대분수로 나타냈어요. 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["17 ÷ 3 = 17 × ⟨1/3⟩ = ⟨17/3⟩이에요.","⟨17/3⟩ = ⟨5 2/3⟩예요.","자연수 부분과 분자의 합은 5 + 2 = 7이에요."]},{"stem":"23 ÷ 5를 분수의 곱셈으로 나타내어 계산한 몫을 대분수로 나타냈어요. 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["23 ÷ 5 = 23 × ⟨1/5⟩ = ⟨23/5⟩이에요.","⟨23/5⟩ = ⟨4 3/5⟩이에요.","자연수 부분과 분자의 합은 4 + 3 = 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L04_challenge#8','math',6,1,'u1','L04','g6_1_math_u1_L04_challenge','lesson_challenge','M6-1-u1-C4',4,'sa','auto','□ × ⟨1/6⟩ = ⟨2 1/6⟩일 때 □에 알맞은 자연수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u1-C4","difficulty":4,"kind":"sa","stem":"□ × ⟨1/6⟩ = ⟨2 1/6⟩일 때 □에 알맞은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["□ × ⟨1/6⟩은 □ ÷ 6과 같고 몫은 ⟨□/6⟩이에요.","⟨2 1/6⟩을 가분수로 고치면 ⟨13/6⟩이에요 — 2 × 6 + 1 = 13.","그래서 □는 13이에요."],"mis":"M6-1-u1-X05","variant_rule":{"alt":[{"stem":"□ × ⟨1/5⟩ = ⟨3 2/5⟩일 때 □에 알맞은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["□ × ⟨1/5⟩은 □ ÷ 5와 같고 몫은 ⟨□/5⟩이에요.","⟨3 2/5⟩를 가분수로 고치면 ⟨17/5⟩이에요 — 3 × 5 + 2 = 17.","그래서 □는 17이에요."]},{"stem":"□ × ⟨1/9⟩ = ⟨1 4/9⟩일 때 □에 알맞은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["□ × ⟨1/9⟩은 □ ÷ 9와 같고 몫은 ⟨□/9⟩이에요.","⟨1 4/9⟩를 가분수로 고치면 ⟨13/9⟩이에요 — 1 × 9 + 4 = 13.","그래서 □는 13이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L04_challenge#9','math',6,1,'u1','L04','g6_1_math_u1_L04_challenge','lesson_challenge','M6-1-u1-C4',4,'mc','auto','3 ÷ 4 ÷ 2를 분수의 곱셈으로 나타내어 계산하면 얼마인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X09']::text[],true,'{"seq":9,"concept":"M6-1-u1-C4","difficulty":4,"kind":"mc","stem":"3 ÷ 4 ÷ 2를 분수의 곱셈으로 나타내어 계산하면 얼마인가요?","options":[{"t":"⟨3/8⟩","correct":true},{"t":"24","mis":"M6-1-u1-X06"},{"t":"⟨1 1/2⟩","mis":"M6-1-u1-X06"},{"t":"⟨1/2⟩","mis":"M6-1-u1-X09"}],"explanation":["÷ 4는 × ⟨1/4⟩, ÷ 2는 × ⟨1/2⟩이에요.","3 ÷ 4 ÷ 2 = 3 × ⟨1/4⟩ × ⟨1/2⟩이에요.","3 × ⟨1/4⟩ × ⟨1/2⟩ = ⟨3/8⟩이에요."],"variant_rule":{"alt":[{"stem":"5 ÷ 2 ÷ 3을 분수의 곱셈으로 나타내어 계산하면 얼마인가요?","options":[{"t":"⟨5/6⟩","correct":true},{"t":"30","mis":"M6-1-u1-X06"},{"t":"⟨7 1/2⟩","mis":"M6-1-u1-X06"},{"t":"1","mis":"M6-1-u1-X09"}],"explanation":["÷ 2는 × ⟨1/2⟩, ÷ 3은 × ⟨1/3⟩이에요.","5 ÷ 2 ÷ 3 = 5 × ⟨1/2⟩ × ⟨1/3⟩이에요.","5 × ⟨1/2⟩ × ⟨1/3⟩ = ⟨5/6⟩예요."]},{"stem":"2 ÷ 3 ÷ 5를 분수의 곱셈으로 나타내어 계산하면 얼마인가요?","options":[{"t":"⟨2/15⟩","correct":true},{"t":"30","mis":"M6-1-u1-X06"},{"t":"⟨3 1/3⟩","mis":"M6-1-u1-X06"},{"t":"⟨1/4⟩","mis":"M6-1-u1-X09"}],"explanation":["÷ 3은 × ⟨1/3⟩, ÷ 5는 × ⟨1/5⟩이에요.","2 ÷ 3 ÷ 5 = 2 × ⟨1/3⟩ × ⟨1/5⟩이에요.","2 × ⟨1/3⟩ × ⟨1/5⟩ = ⟨2/15⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L04_challenge#10','math',6,1,'u1','L04','g6_1_math_u1_L04_challenge','lesson_challenge','M6-1-u1-C4',4,'essay','teacher','친구가 5 ÷ 3을 「5 × 3 = 15」로 계산했어요. 이 계산이 잘못된 까닭을 쓰고, 분수의 곱셈으로 바르게 계산해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u1-C4","difficulty":4,"kind":"essay","stem":"친구가 5 ÷ 3을 「5 × 3 = 15」로 계산했어요. 이 계산이 잘못된 까닭을 쓰고, 분수의 곱셈으로 바르게 계산해 보세요.","answer_guide":{"answer":"예: 5를 3으로 나누면 3으로 똑같이 나눈 것 중의 1이므로 5보다 작아져야 하는데, 5 × 3 = 15는 오히려 커졌다. ÷ 3은 × ⟨1/3⟩과 같으므로 5 ÷ 3 = 5 × ⟨1/3⟩ = ⟨5/3⟩ = ⟨1 2/3⟩이다.","scoring_points":["나누면 작아져야 하는데 15는 커졌다고 썼는가","÷ 3 = × ⟨1/3⟩임을 밝혔는가","5 ÷ 3 = ⟨1 2/3⟩(또는 ⟨5/3⟩)를 구했는가"]},"explanation":["5를 3으로 나누면 5보다 작아져야 해요.","÷ 3은 × ⟨1/3⟩이에요.","5 ÷ 3 = 5 × ⟨1/3⟩ = ⟨1 2/3⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L05_basic#1','math',6,1,'u1','L05','g6_1_math_u1_L05_basic','lesson_basic','M6-1-u1-C5',1,'mc','auto','⟨8/9⟩ ÷ 2를 계산하면 얼마인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X09','M6-1-u1-X07']::text[],true,'{"seq":1,"concept":"M6-1-u1-C5","difficulty":1,"kind":"mc","stem":"⟨8/9⟩ ÷ 2를 계산하면 얼마인가요?","options":[{"t":"⟨4/9⟩","correct":true},{"t":"⟨1 7/9⟩","mis":"M6-1-u1-X06"},{"t":"⟨8/11⟩","mis":"M6-1-u1-X09"},{"t":"⟨9/16⟩","mis":"M6-1-u1-X07"}],"explanation":["⟨8/9⟩은 ⟨1/9⟩이 8개예요.","분자 8을 2로 나누면 8 ÷ 2 = 4 — ⟨1/9⟩이 4개예요.","그래서 ⟨8/9⟩ ÷ 2 = ⟨4/9⟩예요."],"variant_rule":{"alt":[{"stem":"⟨6/7⟩ ÷ 3을 계산하면 얼마인가요?","options":[{"t":"⟨2/7⟩","correct":true},{"t":"⟨2 4/7⟩","mis":"M6-1-u1-X06"},{"t":"⟨3/5⟩","mis":"M6-1-u1-X09"},{"t":"⟨7/18⟩","mis":"M6-1-u1-X07"}],"explanation":["⟨6/7⟩은 ⟨1/7⟩이 6개예요.","분자 6을 3으로 나누면 6 ÷ 3 = 2 — ⟨1/7⟩이 2개예요.","그래서 ⟨6/7⟩ ÷ 3 = ⟨2/7⟩예요."]},{"stem":"⟨4/5⟩ ÷ 2를 계산하면 얼마인가요?","options":[{"t":"⟨2/5⟩","correct":true},{"t":"⟨1 3/5⟩","mis":"M6-1-u1-X06"},{"t":"⟨4/7⟩","mis":"M6-1-u1-X09"},{"t":"⟨5/8⟩","mis":"M6-1-u1-X07"}],"explanation":["⟨4/5⟩는 ⟨1/5⟩이 4개예요.","분자 4를 2로 나누면 4 ÷ 2 = 2 — ⟨1/5⟩이 2개예요.","그래서 ⟨4/5⟩ ÷ 2 = ⟨2/5⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L05_basic#2','math',6,1,'u1','L05','g6_1_math_u1_L05_basic','lesson_basic','M6-1-u1-C5',1,'mc','auto','⟨5/7⟩ ÷ 3을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X07']::text[],true,'{"seq":2,"concept":"M6-1-u1-C5","difficulty":1,"kind":"mc","stem":"⟨5/7⟩ ÷ 3을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨5/7⟩ × ⟨1/3⟩","correct":true},{"t":"⟨5/7⟩ × 3","mis":"M6-1-u1-X06"},{"t":"⟨7/5⟩ × ⟨1/3⟩","mis":"M6-1-u1-X07"},{"t":"3 × ⟨5/7⟩","mis":"M6-1-u1-X06"}],"explanation":["÷ 3은 3으로 똑같이 나눈 것 중의 1이에요.","그래서 × ⟨1/3⟩과 같아요.","⟨5/7⟩ ÷ 3 = ⟨5/7⟩ × ⟨1/3⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨2/9⟩ ÷ 4를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨2/9⟩ × ⟨1/4⟩","correct":true},{"t":"⟨2/9⟩ × 4","mis":"M6-1-u1-X06"},{"t":"⟨9/2⟩ × ⟨1/4⟩","mis":"M6-1-u1-X07"},{"t":"4 × ⟨2/9⟩","mis":"M6-1-u1-X06"}],"explanation":["÷ 4는 4로 똑같이 나눈 것 중의 1이에요.","그래서 × ⟨1/4⟩과 같아요.","⟨2/9⟩ ÷ 4 = ⟨2/9⟩ × ⟨1/4⟩이에요."]},{"stem":"⟨3/8⟩ ÷ 5를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨3/8⟩ × ⟨1/5⟩","correct":true},{"t":"⟨3/8⟩ × 5","mis":"M6-1-u1-X06"},{"t":"⟨8/3⟩ × ⟨1/5⟩","mis":"M6-1-u1-X07"},{"t":"5 × ⟨3/8⟩","mis":"M6-1-u1-X06"}],"explanation":["÷ 5는 5로 똑같이 나눈 것 중의 1이에요.","그래서 × ⟨1/5⟩과 같아요.","⟨3/8⟩ ÷ 5 = ⟨3/8⟩ × ⟨1/5⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L05_basic#3','math',6,1,'u1','L05','g6_1_math_u1_L05_basic','lesson_basic','M6-1-u1-C5',1,'sa','auto','⟨6/7⟩ ÷ 2의 몫은 ⟨1/7⟩이 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-1-u1-C5","difficulty":1,"kind":"sa","stem":"⟨6/7⟩ ÷ 2의 몫은 ⟨1/7⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨6/7⟩은 ⟨1/7⟩이 6개예요.","6개를 2로 똑같이 나누면 6 ÷ 2 = 3개예요.","⟨6/7⟩ ÷ 2 = ⟨3/7⟩ — ⟨1/7⟩이 3개예요."],"mis":"M6-1-u1-X08","variant_rule":{"alt":[{"stem":"⟨9/10⟩ ÷ 3의 몫은 ⟨1/10⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨9/10⟩는 ⟨1/10⟩이 9개예요.","9개를 3으로 똑같이 나누면 9 ÷ 3 = 3개예요.","⟨9/10⟩ ÷ 3 = ⟨3/10⟩ — ⟨1/10⟩이 3개예요."]},{"stem":"⟨8/11⟩ ÷ 4의 몫은 ⟨1/11⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["⟨8/11⟩은 ⟨1/11⟩이 8개예요.","8개를 4로 똑같이 나누면 8 ÷ 4 = 2개예요.","⟨8/11⟩ ÷ 4 = ⟨2/11⟩ — ⟨1/11⟩이 2개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L05_basic#4','math',6,1,'u1','L05','g6_1_math_u1_L05_basic','lesson_basic','M6-1-u1-C5',1,'ox','auto','⟨6/7⟩ ÷ 2 = ⟨3/7⟩이에요.',ARRAY['M6-1-u1-X08']::text[],true,'{"seq":4,"concept":"M6-1-u1-C5","difficulty":1,"kind":"ox","stem":"⟨6/7⟩ ÷ 2 = ⟨3/7⟩이에요.","answer":"O","reason_options":[{"t":"분자 6을 2로 나누어 ⟨1/7⟩이 3개가 되므로","correct":true},{"t":"분모 7을 2로 나누어야 하므로","mis":"M6-1-u1-X08"}],"mis":"M6-1-u1-X08","explanation":["⟨6/7⟩은 ⟨1/7⟩이 6개예요.","6 ÷ 2 = 3이에요.","⟨6/7⟩ ÷ 2 = ⟨3/7⟩ — 맞아요."],"variant_rule":{"alt":[{"stem":"⟨3/5⟩ ÷ 4 = ⟨3/5⟩ × ⟨1/4⟩이에요.","answer":"O","reason_options":[{"t":"÷ 4는 4로 나눈 것 중의 1, × ⟨1/4⟩과 같으므로","correct":true},{"t":"× 4와 ÷ 4는 같으므로","mis":"M6-1-u1-X06"}],"explanation":["÷ 4는 4로 똑같이 나눈 것 중의 1이에요.","⟨3/5⟩ ÷ 4 = ⟨3/5⟩ × ⟨1/4⟩ = ⟨3/20⟩이에요.","그래서 맞아요."]},{"stem":"⟨4/5⟩ ÷ 3은 분자 4가 3으로 나누어떨어지지 않으므로 계산할 수 없어요.","answer":"X","reason_options":[{"t":"⟨4/5⟩ × ⟨1/3⟩ = ⟨4/15⟩로 계산할 수 있으므로","correct":true},{"t":"분자가 나누어떨어져야만 나눌 수 있으므로","mis":"M6-1-u1-X02"}],"explanation":["분자가 나누어떨어지지 않아도 단위분수를 곱하면 돼요.","⟨4/5⟩ ÷ 3 = ⟨4/5⟩ × ⟨1/3⟩이에요.","⟨4/5⟩ × ⟨1/3⟩ = ⟨4/15⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L05_basic#5','math',6,1,'u1','L05','g6_1_math_u1_L05_basic','lesson_basic','M6-1-u1-C5',2,'mc','auto','⟨4/5⟩ ÷ 3을 계산하면 얼마인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X09','M6-1-u1-X07']::text[],true,'{"seq":5,"concept":"M6-1-u1-C5","difficulty":2,"kind":"mc","stem":"⟨4/5⟩ ÷ 3을 계산하면 얼마인가요?","options":[{"t":"⟨4/15⟩","correct":true},{"t":"⟨2 2/5⟩","mis":"M6-1-u1-X06"},{"t":"⟨1/2⟩","mis":"M6-1-u1-X09"},{"t":"⟨5/12⟩","mis":"M6-1-u1-X07"}],"explanation":["분자 4는 3으로 나누어떨어지지 않아요.","⟨4/5⟩ ÷ 3 = ⟨4/5⟩ × ⟨1/3⟩로 바꾸어요.","⟨4/5⟩ × ⟨1/3⟩ = ⟨4/15⟩예요."],"variant_rule":{"alt":[{"stem":"⟨3/7⟩ ÷ 2를 계산하면 얼마인가요?","options":[{"t":"⟨3/14⟩","correct":true},{"t":"⟨6/7⟩","mis":"M6-1-u1-X06"},{"t":"⟨1/3⟩","mis":"M6-1-u1-X09"},{"t":"⟨1 1/6⟩","mis":"M6-1-u1-X07"}],"explanation":["분자 3은 2로 나누어떨어지지 않아요.","⟨3/7⟩ ÷ 2 = ⟨3/7⟩ × ⟨1/2⟩로 바꾸어요.","⟨3/7⟩ × ⟨1/2⟩ = ⟨3/14⟩이에요."]},{"stem":"⟨5/6⟩ ÷ 4를 계산하면 얼마인가요?","options":[{"t":"⟨5/24⟩","correct":true},{"t":"⟨3 1/3⟩","mis":"M6-1-u1-X06"},{"t":"⟨1/2⟩","mis":"M6-1-u1-X09"},{"t":"⟨3/10⟩","mis":"M6-1-u1-X07"}],"explanation":["분자 5는 4로 나누어떨어지지 않아요.","⟨5/6⟩ ÷ 4 = ⟨5/6⟩ × ⟨1/4⟩로 바꾸어요.","⟨5/6⟩ × ⟨1/4⟩ = ⟨5/24⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L05_basic#6','math',6,1,'u1','L05','g6_1_math_u1_L05_basic','lesson_basic','M6-1-u1-C5',2,'sa','auto','⟨2/11⟩ ÷ 5를 분수의 곱셈으로 바꾸어 계산하면 몫의 분모는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u1-C5","difficulty":2,"kind":"sa","stem":"⟨2/11⟩ ÷ 5를 분수의 곱셈으로 바꾸어 계산하면 몫의 분모는 얼마인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["⟨2/11⟩ ÷ 5 = ⟨2/11⟩ × ⟨1/5⟩이에요.","분모끼리 곱하면 11 × 5 = 55예요.","⟨2/11⟩ × ⟨1/5⟩ = ⟨2/55⟩ — 분모는 55예요."],"mis":"M6-1-u1-X08","variant_rule":{"alt":[{"stem":"⟨3/8⟩ ÷ 7을 분수의 곱셈으로 바꾸어 계산하면 몫의 분모는 얼마인가요? 숫자로 쓰세요.","answer":["56"],"explanation":["⟨3/8⟩ ÷ 7 = ⟨3/8⟩ × ⟨1/7⟩이에요.","분모끼리 곱하면 8 × 7 = 56이에요.","⟨3/8⟩ × ⟨1/7⟩ = ⟨3/56⟩ — 분모는 56이에요."]},{"stem":"⟨5/9⟩ ÷ 4를 분수의 곱셈으로 바꾸어 계산하면 몫의 분모는 얼마인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["⟨5/9⟩ ÷ 4 = ⟨5/9⟩ × ⟨1/4⟩이에요.","분모끼리 곱하면 9 × 4 = 36이에요.","⟨5/9⟩ × ⟨1/4⟩ = ⟨5/36⟩ — 분모는 36이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L05_basic#7','math',6,1,'u1','L05','g6_1_math_u1_L05_basic','lesson_basic','M6-1-u1-C5',2,'sa','auto','물 ⟨9/10⟩ L를 3명이 똑같이 나누어 마셨어요. 한 명이 마신 물은 ⟨1/10⟩이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u1-C5","difficulty":2,"kind":"sa","stem":"물 ⟨9/10⟩ L를 3명이 똑같이 나누어 마셨어요. 한 명이 마신 물은 ⟨1/10⟩이 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨9/10⟩는 ⟨1/10⟩이 9개예요.","9개를 3으로 나누면 9 ÷ 3 = 3개예요.","한 명이 마신 물은 ⟨3/10⟩ L — ⟨1/10⟩이 3개예요."],"mis":"M6-1-u1-X08","variant_rule":{"alt":[{"stem":"주스 ⟨8/9⟩ L를 4명이 똑같이 나누어 마셨어요. 한 명이 마신 주스는 ⟨1/9⟩이 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["⟨8/9⟩은 ⟨1/9⟩이 8개예요.","8개를 4로 나누면 8 ÷ 4 = 2개예요.","한 명이 마신 주스는 ⟨2/9⟩ L — ⟨1/9⟩이 2개예요."]},{"stem":"색 모래 ⟨6/7⟩ kg을 2모둠이 똑같이 나누어 가졌어요. 한 모둠이 가진 색 모래는 ⟨1/7⟩이 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨6/7⟩은 ⟨1/7⟩이 6개예요.","6개를 2로 나누면 6 ÷ 2 = 3개예요.","한 모둠이 가진 색 모래는 ⟨3/7⟩ kg — ⟨1/7⟩이 3개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L05_basic#8','math',6,1,'u1','L05','g6_1_math_u1_L05_basic','lesson_basic','M6-1-u1-C5',2,'match','auto','나눗셈과 몫을 알맞게 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u1-C5","difficulty":2,"kind":"match","stem":"나눗셈과 몫을 알맞게 이으세요.","pairs":[{"l":"⟨6/7⟩ ÷ 3","r":"⟨2/7⟩"},{"l":"⟨4/5⟩ ÷ 3","r":"⟨4/15⟩"},{"l":"⟨2/9⟩ ÷ 2","r":"⟨1/9⟩"}],"mis":"M6-1-u1-X06","explanation":["분자가 나누어떨어지면 분자만, 아니면 단위분수를 곱해요.","⟨6/7⟩ ÷ 3 = ⟨2/7⟩, ⟨4/5⟩ ÷ 3 = ⟨4/15⟩, ⟨2/9⟩ ÷ 2 = ⟨1/9⟩이에요.","나누는 수를 그대로 곱하지 않도록 해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 나눗셈과 몫을 알맞게 이으세요.","pairs":[{"l":"⟨8/9⟩ ÷ 4","r":"⟨2/9⟩"},{"l":"⟨3/4⟩ ÷ 2","r":"⟨3/8⟩"},{"l":"⟨5/6⟩ ÷ 5","r":"⟨1/6⟩"}],"explanation":["분자가 나누어떨어지면 분자만, 아니면 단위분수를 곱해요.","⟨8/9⟩ ÷ 4 = ⟨2/9⟩, ⟨3/4⟩ ÷ 2 = ⟨3/8⟩, ⟨5/6⟩ ÷ 5 = ⟨1/6⟩이에요.","나누는 수를 그대로 곱하지 않도록 해요."]},{"stem":"이번에는 다른 보기예요. 나눗셈과 몫을 알맞게 이으세요.","pairs":[{"l":"⟨9/10⟩ ÷ 3","r":"⟨3/10⟩"},{"l":"⟨1/3⟩ ÷ 4","r":"⟨1/12⟩"},{"l":"⟨4/7⟩ ÷ 2","r":"⟨2/7⟩"}],"explanation":["분자가 나누어떨어지면 분자만, 아니면 단위분수를 곱해요.","⟨9/10⟩ ÷ 3 = ⟨3/10⟩, ⟨1/3⟩ ÷ 4 = ⟨1/12⟩, ⟨4/7⟩ ÷ 2 = ⟨2/7⟩예요.","나누는 수를 그대로 곱하지 않도록 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L05_basic#9','math',6,1,'u1','L05','g6_1_math_u1_L05_basic','lesson_basic','M6-1-u1-C5',2,'mc','auto','⟨4/5⟩ ÷ 2와 ⟨4/5⟩ ÷ 3 가운데 몫이 더 큰 것은 어느 것인가요?',ARRAY['M6-1-u1-X11','M6-1-u1-X15']::text[],true,'{"seq":9,"concept":"M6-1-u1-C5","difficulty":2,"kind":"mc","stem":"⟨4/5⟩ ÷ 2와 ⟨4/5⟩ ÷ 3 가운데 몫이 더 큰 것은 어느 것인가요?","options":[{"t":"⟨4/5⟩ ÷ 2","correct":true},{"t":"⟨4/5⟩ ÷ 3","mis":"M6-1-u1-X11"},{"t":"두 몫이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X15"}],"explanation":["⟨4/5⟩ ÷ 2 = ⟨2/5⟩, ⟨4/5⟩ ÷ 3 = ⟨4/15⟩예요.","15로 통분하면 ⟨2/5⟩ = ⟨6/15⟩, ⟨4/15⟩ = ⟨4/15⟩예요.","같은 양을 더 적게 나눌수록 몫이 커요 — ⟨4/5⟩ ÷ 2가 더 커요."],"variant_rule":{"alt":[{"stem":"⟨6/7⟩ ÷ 2와 ⟨6/7⟩ ÷ 3 가운데 몫이 더 큰 것은 어느 것인가요?","options":[{"t":"⟨6/7⟩ ÷ 2","correct":true},{"t":"⟨6/7⟩ ÷ 3","mis":"M6-1-u1-X11"},{"t":"두 몫이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X15"}],"explanation":["⟨6/7⟩ ÷ 2 = ⟨3/7⟩, ⟨6/7⟩ ÷ 3 = ⟨2/7⟩예요.","7로 통분하면 ⟨3/7⟩ = ⟨3/7⟩, ⟨2/7⟩ = ⟨2/7⟩예요.","같은 양을 더 적게 나눌수록 몫이 커요 — ⟨6/7⟩ ÷ 2가 더 커요."]},{"stem":"⟨3/4⟩ ÷ 2와 ⟨3/4⟩ ÷ 5 가운데 몫이 더 큰 것은 어느 것인가요?","options":[{"t":"⟨3/4⟩ ÷ 2","correct":true},{"t":"⟨3/4⟩ ÷ 5","mis":"M6-1-u1-X11"},{"t":"두 몫이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X15"}],"explanation":["⟨3/4⟩ ÷ 2 = ⟨3/8⟩, ⟨3/4⟩ ÷ 5 = ⟨3/20⟩이에요.","40으로 통분하면 ⟨3/8⟩ = ⟨15/40⟩, ⟨3/20⟩ = ⟨6/40⟩이에요.","같은 양을 더 적게 나눌수록 몫이 커요 — ⟨3/4⟩ ÷ 2가 더 커요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L05_basic#10','math',6,1,'u1','L05','g6_1_math_u1_L05_basic','lesson_basic','M6-1-u1-C5',3,'mc','auto','진분수를 1보다 큰 자연수로 나눌 때 몫에 대한 설명으로 옳은 것은 어느 것인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X11','M6-1-u1-X03']::text[],true,'{"seq":10,"concept":"M6-1-u1-C5","difficulty":3,"kind":"mc","stem":"진분수를 1보다 큰 자연수로 나눌 때 몫에 대한 설명으로 옳은 것은 어느 것인가요?","options":[{"t":"몫은 처음 진분수보다 항상 작다","correct":true},{"t":"몫은 처음 진분수보다 항상 크다","mis":"M6-1-u1-X06"},{"t":"나누는 수가 클수록 몫이 커진다","mis":"M6-1-u1-X11"},{"t":"몫은 언제나 자연수가 된다","mis":"M6-1-u1-X03"}],"explanation":["(진분수)÷(자연수)는 (진분수) × (단위분수)로 바꾸어 계산해요.","1보다 큰 수로 나누면 처음보다 작아지고, 더 큰 수로 나눌수록 더 작아져요.","그래서 답은 「몫은 처음 진분수보다 항상 작다」예요."],"variant_rule":{"alt":[{"stem":"진분수를 1보다 큰 자연수로 나눌 때 몫에 대한 설명으로 옳지 않은 것은 어느 것인가요?","options":[{"t":"나누는 수가 클수록 몫이 커진다","correct":true},{"t":"몫은 처음 진분수보다 작다","mis":"M6-1-u1-X15"},{"t":"단위분수를 곱해 구할 수 있다","mis":"M6-1-u1-X15"},{"t":"분자가 나누어떨어지면 분자만 나누어도 된다","mis":"M6-1-u1-X15"}],"explanation":["(진분수)÷(자연수)는 (진분수) × (단위분수)로 바꾸어 계산해요.","1보다 큰 수로 나누면 처음보다 작아지고, 더 큰 수로 나눌수록 더 작아져요.","그래서 답은 「나누는 수가 클수록 몫이 커진다」예요."]},{"stem":"(진분수)÷(자연수)를 계산하는 방법으로 언제나 쓸 수 있는 것은 어느 것인가요?","options":[{"t":"(진분수) × (나누는 수를 분모로 하는 단위분수)","correct":true},{"t":"(진분수) × (나누는 수)","mis":"M6-1-u1-X06"},{"t":"분모만 나누는 수로 나누기","mis":"M6-1-u1-X08"},{"t":"분모에 나누는 수를 더하기","mis":"M6-1-u1-X09"}],"explanation":["(진분수)÷(자연수)는 (진분수) × (단위분수)로 바꾸어 계산해요.","1보다 큰 수로 나누면 처음보다 작아지고, 더 큰 수로 나눌수록 더 작아져요.","그래서 답은 「(진분수) × (나누는 수를 분모로 하는 단위분수)」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L05_challenge#1','math',6,1,'u1','L05','g6_1_math_u1_L05_challenge','lesson_challenge','M6-1-u1-C5',2,'sa','auto','손 세정제 ⟨4/5⟩ L를 3병에 똑같이 나누어 담았어요. 한 병에 담은 손 세정제를 분수로 나타낼 때 분모는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u1-C5","difficulty":2,"kind":"sa","stem":"손 세정제 ⟨4/5⟩ L를 3병에 똑같이 나누어 담았어요. 한 병에 담은 손 세정제를 분수로 나타낼 때 분모는 얼마인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["분자 4는 3으로 나누어떨어지지 않아요.","⟨4/5⟩ ÷ 3 = ⟨4/5⟩ × ⟨1/3⟩ = ⟨4/15⟩예요.","한 병에 담은 손 세정제는 ⟨4/15⟩ L — 분모는 15예요."],"mis":"M6-1-u1-X08","variant_rule":{"alt":[{"stem":"주스 ⟨5/6⟩ L를 2명이 똑같이 나누어 마셨어요. 한 명이 마신 주스를 분수로 나타낼 때 분모는 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["분자 5는 2로 나누어떨어지지 않아요.","⟨5/6⟩ ÷ 2 = ⟨5/6⟩ × ⟨1/2⟩ = ⟨5/12⟩예요.","한 명이 마신 주스는 ⟨5/12⟩ L — 분모는 12예요."]},{"stem":"물 ⟨3/8⟩ L를 4명이 똑같이 나누어 마셨어요. 한 명이 마신 물을 분수로 나타낼 때 분모는 얼마인가요? 숫자로 쓰세요.","answer":["32"],"explanation":["분자 3은 4로 나누어떨어지지 않아요.","⟨3/8⟩ ÷ 4 = ⟨3/8⟩ × ⟨1/4⟩ = ⟨3/32⟩이에요.","한 명이 마신 물은 ⟨3/32⟩ L — 분모는 32예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L05_challenge#2','math',6,1,'u1','L05','g6_1_math_u1_L05_challenge','lesson_challenge','M6-1-u1-C5',2,'mc','auto','⟨7/9⟩ ÷ 3을 계산하면 얼마인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X09','M6-1-u1-X07']::text[],true,'{"seq":2,"concept":"M6-1-u1-C5","difficulty":2,"kind":"mc","stem":"⟨7/9⟩ ÷ 3을 계산하면 얼마인가요?","options":[{"t":"⟨7/27⟩","correct":true},{"t":"⟨2 1/3⟩","mis":"M6-1-u1-X06"},{"t":"⟨7/12⟩","mis":"M6-1-u1-X09"},{"t":"⟨3/7⟩","mis":"M6-1-u1-X07"}],"explanation":["분자 7은 3으로 나누어떨어지지 않아요.","⟨7/9⟩ ÷ 3 = ⟨7/9⟩ × ⟨1/3⟩로 바꾸어요.","⟨7/9⟩ × ⟨1/3⟩ = ⟨7/27⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨9/11⟩ ÷ 3을 계산하면 얼마인가요?","options":[{"t":"⟨3/11⟩","correct":true},{"t":"⟨2 5/11⟩","mis":"M6-1-u1-X06"},{"t":"⟨9/14⟩","mis":"M6-1-u1-X09"},{"t":"⟨11/27⟩","mis":"M6-1-u1-X07"}],"explanation":["⟨9/11⟩는 ⟨1/11⟩이 9개예요.","분자 9를 3으로 나누면 9 ÷ 3 = 3 — ⟨1/11⟩이 3개예요.","그래서 ⟨9/11⟩ ÷ 3 = ⟨3/11⟩이에요."]},{"stem":"⟨5/8⟩ ÷ 3을 계산하면 얼마인가요?","options":[{"t":"⟨5/24⟩","correct":true},{"t":"⟨1 7/8⟩","mis":"M6-1-u1-X06"},{"t":"⟨5/11⟩","mis":"M6-1-u1-X09"},{"t":"⟨8/15⟩","mis":"M6-1-u1-X07"}],"explanation":["분자 5는 3으로 나누어떨어지지 않아요.","⟨5/8⟩ ÷ 3 = ⟨5/8⟩ × ⟨1/3⟩로 바꾸어요.","⟨5/8⟩ × ⟨1/3⟩ = ⟨5/24⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L05_challenge#3','math',6,1,'u1','L05','g6_1_math_u1_L05_challenge','lesson_challenge','M6-1-u1-C5',3,'error','auto','⟨3/5⟩ ÷ 4에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X15']::text[],true,'{"seq":3,"concept":"M6-1-u1-C5","difficulty":3,"kind":"error","stem":"⟨3/5⟩ ÷ 4에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「⟨3/5⟩ × 4 = ⟨2 2/5⟩로 계산해.」","correct":true,"mis_target":"M6-1-u1-X06"},{"t":"도윤 — 「⟨3/5⟩ × ⟨1/4⟩로 바꾸어 계산하면 돼.」","mis":"M6-1-u1-X15"},{"t":"하린 — 「몫은 ⟨3/5⟩보다 작아.」","mis":"M6-1-u1-X15"}],"explanation":["4로 나누면 양이 작아져야 해요.","⟨3/5⟩ × 4 = ⟨2 2/5⟩는 오히려 커요.","⟨3/5⟩ ÷ 4 = ⟨3/5⟩ × ⟨1/4⟩ = ⟨3/20⟩ — 수아는 나누는 수를 그대로 곱했어요."],"variant_rule":{"alt":[{"stem":"⟨2/7⟩ ÷ 3에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민준 — 「⟨2/7⟩ × 3 = ⟨6/7⟩으로 계산해.」","correct":true,"mis_target":"M6-1-u1-X06"},{"t":"서연 — 「⟨2/7⟩ × ⟨1/3⟩로 바꾸어 계산하면 돼.」","mis":"M6-1-u1-X15"},{"t":"지호 — 「몫은 ⟨2/7⟩보다 작아.」","mis":"M6-1-u1-X15"}],"explanation":["3으로 나누면 양이 작아져야 해요.","⟨2/7⟩ × 3 = ⟨6/7⟩은 오히려 커요.","⟨2/7⟩ ÷ 3 = ⟨2/7⟩ × ⟨1/3⟩ = ⟨2/21⟩ — 민준은 나누는 수를 그대로 곱했어요."]},{"stem":"⟨5/9⟩ ÷ 2에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「⟨5/9⟩ × 2 = ⟨1 1/9⟩로 계산해.」","correct":true,"mis_target":"M6-1-u1-X06"},{"t":"나린 — 「⟨5/9⟩ × ⟨1/2⟩로 바꾸어 계산하면 돼.」","mis":"M6-1-u1-X15"},{"t":"유진 — 「몫은 ⟨5/9⟩보다 작아.」","mis":"M6-1-u1-X15"}],"explanation":["2로 나누면 양이 작아져야 해요.","⟨5/9⟩ × 2 = ⟨1 1/9⟩은 오히려 커요.","⟨5/9⟩ ÷ 2 = ⟨5/9⟩ × ⟨1/2⟩ = ⟨5/18⟩ — 가온은 나누는 수를 그대로 곱했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L05_challenge#4','math',6,1,'u1','L05','g6_1_math_u1_L05_challenge','lesson_challenge','M6-1-u1-C5',3,'mc','auto','⟨6/7⟩ ÷ 3을 「분자만 나누기」와 「단위분수 곱하기」 두 방법으로 계산했어요. 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u1-X12','M6-1-u1-X02','M6-1-u1-X06']::text[],true,'{"seq":4,"concept":"M6-1-u1-C5","difficulty":3,"kind":"mc","stem":"⟨6/7⟩ ÷ 3을 「분자만 나누기」와 「단위분수 곱하기」 두 방법으로 계산했어요. 알맞은 것은 어느 것인가요?","options":[{"t":"두 방법의 몫은 ⟨2/7⟩로 같다","correct":true},{"t":"분자만 나누면 ⟨2/7⟩, 곱하면 ⟨6/21⟩이라 몫이 다르다","mis":"M6-1-u1-X12"},{"t":"분자만 나누는 방법은 쓸 수 없다","mis":"M6-1-u1-X02"},{"t":"곱하는 방법은 ⟨6/7⟩ × 3으로 해야 한다","mis":"M6-1-u1-X06"}],"explanation":["분자만 나누면 6 ÷ 3 = 2라 ⟨2/7⟩예요.","곱하면 ⟨6/7⟩ × ⟨1/3⟩ = ⟨6/21⟩이에요.","⟨6/21⟩ = ⟨2/7⟩ — 약분하면 같은 수예요."],"variant_rule":{"alt":[{"stem":"⟨8/9⟩ ÷ 4를 「분자만 나누기」와 「단위분수 곱하기」 두 방법으로 계산했어요. 알맞은 것은 어느 것인가요?","options":[{"t":"두 방법의 몫은 ⟨2/9⟩로 같다","correct":true},{"t":"분자만 나누면 ⟨2/9⟩, 곱하면 ⟨8/36⟩이라 몫이 다르다","mis":"M6-1-u1-X12"},{"t":"분자만 나누는 방법은 쓸 수 없다","mis":"M6-1-u1-X02"},{"t":"곱하는 방법은 ⟨8/9⟩ × 4로 해야 한다","mis":"M6-1-u1-X06"}],"explanation":["분자만 나누면 8 ÷ 4 = 2라 ⟨2/9⟩예요.","곱하면 ⟨8/9⟩ × ⟨1/4⟩ = ⟨8/36⟩이에요.","⟨8/36⟩ = ⟨2/9⟩ — 약분하면 같은 수예요."]},{"stem":"⟨10/11⟩ ÷ 5를 「분자만 나누기」와 「단위분수 곱하기」 두 방법으로 계산했어요. 알맞은 것은 어느 것인가요?","options":[{"t":"두 방법의 몫은 ⟨2/11⟩로 같다","correct":true},{"t":"분자만 나누면 ⟨2/11⟩, 곱하면 ⟨10/55⟩이라 몫이 다르다","mis":"M6-1-u1-X12"},{"t":"분자만 나누는 방법은 쓸 수 없다","mis":"M6-1-u1-X02"},{"t":"곱하는 방법은 ⟨10/11⟩ × 5로 해야 한다","mis":"M6-1-u1-X06"}],"explanation":["분자만 나누면 10 ÷ 5 = 2라 ⟨2/11⟩예요.","곱하면 ⟨10/11⟩ × ⟨1/5⟩ = ⟨10/55⟩이에요.","⟨10/55⟩ = ⟨2/11⟩ — 약분하면 같은 수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L05_challenge#5','math',6,1,'u1','L05','g6_1_math_u1_L05_challenge','lesson_challenge','M6-1-u1-C5',3,'mc','auto','⟨5/8⟩ ÷ 3과 ⟨5/8⟩ ÷ 4 가운데 몫이 더 큰 것은 어느 것인가요?',ARRAY['M6-1-u1-X11','M6-1-u1-X15']::text[],true,'{"seq":5,"concept":"M6-1-u1-C5","difficulty":3,"kind":"mc","stem":"⟨5/8⟩ ÷ 3과 ⟨5/8⟩ ÷ 4 가운데 몫이 더 큰 것은 어느 것인가요?","options":[{"t":"⟨5/8⟩ ÷ 3","correct":true},{"t":"⟨5/8⟩ ÷ 4","mis":"M6-1-u1-X11"},{"t":"두 몫이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X15"}],"explanation":["⟨5/8⟩ ÷ 3 = ⟨5/24⟩, ⟨5/8⟩ ÷ 4 = ⟨5/32⟩예요.","96으로 통분하면 ⟨5/24⟩ = ⟨20/96⟩, ⟨5/32⟩ = ⟨15/96⟩예요.","같은 양을 더 적게 나눌수록 몫이 커요 — ⟨5/8⟩ ÷ 3이 더 커요."],"variant_rule":{"alt":[{"stem":"⟨7/9⟩ ÷ 2와 ⟨7/9⟩ ÷ 5 가운데 몫이 더 큰 것은 어느 것인가요?","options":[{"t":"⟨7/9⟩ ÷ 2","correct":true},{"t":"⟨7/9⟩ ÷ 5","mis":"M6-1-u1-X11"},{"t":"두 몫이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X15"}],"explanation":["⟨7/9⟩ ÷ 2 = ⟨7/18⟩, ⟨7/9⟩ ÷ 5 = ⟨7/45⟩이에요.","90으로 통분하면 ⟨7/18⟩ = ⟨35/90⟩, ⟨7/45⟩ = ⟨14/90⟩예요.","같은 양을 더 적게 나눌수록 몫이 커요 — ⟨7/9⟩ ÷ 2가 더 커요."]},{"stem":"⟨9/10⟩ ÷ 3과 ⟨9/10⟩ ÷ 4 가운데 몫이 더 큰 것은 어느 것인가요?","options":[{"t":"⟨9/10⟩ ÷ 3","correct":true},{"t":"⟨9/10⟩ ÷ 4","mis":"M6-1-u1-X11"},{"t":"두 몫이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X15"}],"explanation":["⟨9/10⟩ ÷ 3 = ⟨3/10⟩, ⟨9/10⟩ ÷ 4 = ⟨9/40⟩예요.","40으로 통분하면 ⟨3/10⟩ = ⟨12/40⟩, ⟨9/40⟩ = ⟨9/40⟩예요.","같은 양을 더 적게 나눌수록 몫이 커요 — ⟨9/10⟩ ÷ 3이 더 커요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L05_challenge#6','math',6,1,'u1','L05','g6_1_math_u1_L05_challenge','lesson_challenge','M6-1-u1-C5',3,'ox','auto','⟨2/9⟩ ÷ 3 = ⟨2/3⟩예요.',ARRAY['M6-1-u1-X08']::text[],true,'{"seq":6,"concept":"M6-1-u1-C5","difficulty":3,"kind":"ox","stem":"⟨2/9⟩ ÷ 3 = ⟨2/3⟩예요.","answer":"X","reason_options":[{"t":"분모를 나누면 몫이 커지므로 ⟨2/9⟩ × ⟨1/3⟩ = ⟨2/27⟩이어야 하므로","correct":true},{"t":"분모 9를 3으로 나누면 되므로","mis":"M6-1-u1-X08"}],"mis":"M6-1-u1-X08","explanation":["⟨2/3⟩는 ⟨2/9⟩보다 커요 — 나누었는데 커질 수 없어요.","⟨2/9⟩ ÷ 3 = ⟨2/9⟩ × ⟨1/3⟩이에요.","몫은 ⟨2/27⟩예요."],"variant_rule":{"alt":[{"stem":"⟨5/6⟩ ÷ 2의 몫은 ⟨5/6⟩보다 커요.","answer":"X","reason_options":[{"t":"1보다 큰 수로 나누면 몫이 처음보다 작아지므로","correct":true},{"t":"나눗셈을 하면 몫이 커지므로","mis":"M6-1-u1-X11"}],"explanation":["⟨5/6⟩ ÷ 2 = ⟨5/12⟩예요.","⟨5/6⟩ = ⟨10/12⟩이고 ⟨5/12⟩ < ⟨10/12⟩이에요.","그래서 몫은 처음보다 작아요."]},{"stem":"⟨3/4⟩ ÷ 5 = ⟨3/9⟩이에요.","answer":"X","reason_options":[{"t":"분모에 5를 더한 것이라 ⟨3/4⟩ × ⟨1/5⟩ = ⟨3/20⟩이어야 하므로","correct":true},{"t":"나누는 수를 분모에 더하면 되므로","mis":"M6-1-u1-X09"}],"explanation":["⟨3/4⟩ ÷ 5 = ⟨3/4⟩ × ⟨1/5⟩이에요.","분모끼리 곱해 4 × 5 = 20이에요.","몫은 ⟨3/20⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L05_challenge#7','math',6,1,'u1','L05','g6_1_math_u1_L05_challenge','lesson_challenge','M6-1-u1-C5',3,'mc','auto','어떤 진분수를 3으로 나누었더니 ⟨2/15⟩가 되었어요. 어떤 진분수는 얼마인가요?',ARRAY['M6-1-u1-X14','M6-1-u1-X09']::text[],true,'{"seq":7,"concept":"M6-1-u1-C5","difficulty":3,"kind":"mc","stem":"어떤 진분수를 3으로 나누었더니 ⟨2/15⟩가 되었어요. 어떤 진분수는 얼마인가요?","options":[{"t":"⟨2/5⟩","correct":true},{"t":"⟨2/45⟩","mis":"M6-1-u1-X14"},{"t":"⟨3 2/15⟩","mis":"M6-1-u1-X14"},{"t":"⟨1/9⟩","mis":"M6-1-u1-X09"}],"explanation":["어떤 진분수 ÷ 3 = ⟨2/15⟩예요.","거꾸로 생각하면 어떤 진분수 = ⟨2/15⟩ × 3이에요.","⟨2/15⟩ × 3 = ⟨2/5⟩예요."],"variant_rule":{"alt":[{"stem":"어떤 진분수를 2로 나누었더니 ⟨3/14⟩이 되었어요. 어떤 진분수는 얼마인가요?","options":[{"t":"⟨3/7⟩","correct":true},{"t":"⟨3/28⟩","mis":"M6-1-u1-X14"},{"t":"⟨2 3/14⟩","mis":"M6-1-u1-X14"},{"t":"⟨3/16⟩","mis":"M6-1-u1-X09"}],"explanation":["어떤 진분수 ÷ 2 = ⟨3/14⟩이에요.","거꾸로 생각하면 어떤 진분수 = ⟨3/14⟩ × 2예요.","⟨3/14⟩ × 2 = ⟨3/7⟩이에요."]},{"stem":"어떤 진분수를 5로 나누었더니 ⟨4/45⟩가 되었어요. 어떤 진분수는 얼마인가요?","options":[{"t":"⟨4/9⟩","correct":true},{"t":"⟨4/225⟩","mis":"M6-1-u1-X14"},{"t":"⟨5 4/45⟩","mis":"M6-1-u1-X14"},{"t":"⟨2/25⟩","mis":"M6-1-u1-X09"}],"explanation":["어떤 진분수 ÷ 5 = ⟨4/45⟩예요.","거꾸로 생각하면 어떤 진분수 = ⟨4/45⟩ × 5예요.","⟨4/45⟩ × 5 = ⟨4/9⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L05_challenge#8','math',6,1,'u1','L05','g6_1_math_u1_L05_challenge','lesson_challenge','M6-1-u1-C5',4,'sa','auto','⟨□/9⟩ ÷ 4 = ⟨2/9⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u1-C5","difficulty":4,"kind":"sa","stem":"⟨□/9⟩ ÷ 4 = ⟨2/9⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["분모가 그대로 9니 분자만 4로 나눈 거예요.","4로 나누어 2가 된 수는 2 × 4 = 8이에요.","⟨8/9⟩ ÷ 4 = ⟨2/9⟩ — □는 8이에요."],"mis":"M6-1-u1-X06","variant_rule":{"alt":[{"stem":"⟨3/5⟩ ÷ □ = ⟨3/20⟩일 때 □에 알맞은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["⟨3/5⟩ ÷ □ = ⟨3/5⟩ × ⟨1/□⟩이에요.","분자는 그대로이고 분모가 5에서 20으로 4배가 되었어요.","⟨3/5⟩ ÷ 4 = ⟨3/20⟩ — □는 4예요."]},{"stem":"⟨□/11⟩ ÷ 5 = ⟨2/11⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["분모가 그대로 11이니 분자만 5로 나눈 거예요.","5로 나누어 2가 된 수는 2 × 5 = 10이에요.","⟨10/11⟩ ÷ 5 = ⟨2/11⟩ — □는 10이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L05_challenge#9','math',6,1,'u1','L05','g6_1_math_u1_L05_challenge','lesson_challenge','M6-1-u1-C5',4,'sa','auto','⟨8/9⟩ ÷ □의 몫이 ⟨1/9⟩보다 클 때, □에 들어갈 수 있는 가장 큰 자연수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u1-C5","difficulty":4,"kind":"sa","stem":"⟨8/9⟩ ÷ □의 몫이 ⟨1/9⟩보다 클 때, □에 들어갈 수 있는 가장 큰 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["⟨8/9⟩은 ⟨1/9⟩이 8개예요.","□로 나눈 몫이 ⟨1/9⟩보다 크려면 8개를 □로 나눈 수가 1보다 커야 해요.","□는 8보다 작아야 하니 가장 큰 수는 7이에요."],"mis":"M6-1-u1-X11","variant_rule":{"alt":[{"stem":"⟨6/7⟩ ÷ □의 몫이 ⟨1/7⟩보다 클 때, □에 들어갈 수 있는 가장 큰 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["⟨6/7⟩은 ⟨1/7⟩이 6개예요.","□로 나눈 몫이 ⟨1/7⟩보다 크려면 6개를 □로 나눈 수가 1보다 커야 해요.","□는 6보다 작아야 하니 가장 큰 수는 5예요."]},{"stem":"⟨10/11⟩ ÷ □의 몫이 ⟨1/11⟩보다 클 때, □에 들어갈 수 있는 가장 큰 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["⟨10/11⟩은 ⟨1/11⟩이 10개예요.","□로 나눈 몫이 ⟨1/11⟩보다 크려면 10개를 □로 나눈 수가 1보다 커야 해요.","□는 10보다 작아야 하니 가장 큰 수는 9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L05_challenge#10','math',6,1,'u1','L05','g6_1_math_u1_L05_challenge','lesson_challenge','M6-1-u1-C5',4,'essay','teacher','손 세정제 ⟨4/5⟩ L를 3병에 똑같이 나누어 담으려고 해요. 분자 4가 3으로 나누어떨어지지 않을 때 한 병에 담는 양을 구하는 방법을 설명하고 답을 구해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u1-C5","difficulty":4,"kind":"essay","stem":"손 세정제 ⟨4/5⟩ L를 3병에 똑같이 나누어 담으려고 해요. 분자 4가 3으로 나누어떨어지지 않을 때 한 병에 담는 양을 구하는 방법을 설명하고 답을 구해 보세요.","answer_guide":{"answer":"예: 분자 4는 3으로 나누어떨어지지 않으므로 ⟨4/5⟩ 전체를 3등분한 것 중의 1을 구한다. 이것은 ⟨4/5⟩에 ⟨1/3⟩을 곱하는 것과 같아 ⟨4/5⟩ ÷ 3 = ⟨4/5⟩ × ⟨1/3⟩ = ⟨4/15⟩이다. 한 병에는 ⟨4/15⟩ L를 담는다.","scoring_points":["분자가 나누어떨어지지 않음을 짚었는가","÷ 3을 × ⟨1/3⟩로 바꾸는 방법을 썼는가","⟨4/15⟩ L를 구했는가"]},"explanation":["분자 4는 3으로 나누어떨어지지 않아요.","⟨4/5⟩ ÷ 3 = ⟨4/5⟩ × ⟨1/3⟩이에요.","한 병에는 ⟨4/15⟩ L예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L06_basic#1','math',6,1,'u1','L06','g6_1_math_u1_L06_basic','lesson_basic','M6-1-u1-C6',1,'mc','auto','⟨1 1/6⟩을 가분수로 나타내면 어느 것인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X05']::text[],true,'{"seq":1,"concept":"M6-1-u1-C6","difficulty":1,"kind":"mc","stem":"⟨1 1/6⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨7/6⟩","correct":true},{"t":"⟨6/7⟩","mis":"M6-1-u1-X01"},{"t":"⟨2/6⟩","mis":"M6-1-u1-X05"},{"t":"⟨1/6⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 1은 ⟨6/6⟩이에요 — 1 × 6 = 6.","여기에 ⟨1/6⟩을 더하면 분자는 6 + 1 = 7이에요.","⟨1 1/6⟩ = ⟨7/6⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨2 3/4⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨11/4⟩","correct":true},{"t":"⟨4/11⟩","mis":"M6-1-u1-X01"},{"t":"⟨5/4⟩","mis":"M6-1-u1-X05"},{"t":"⟨6/4⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 2는 ⟨8/4⟩이에요 — 2 × 4 = 8.","여기에 ⟨3/4⟩을 더하면 분자는 8 + 3 = 11이에요.","⟨2 3/4⟩ = ⟨11/4⟩이에요."]},{"stem":"⟨1 4/7⟩를 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨11/7⟩","correct":true},{"t":"⟨7/11⟩","mis":"M6-1-u1-X01"},{"t":"⟨5/7⟩","mis":"M6-1-u1-X05"},{"t":"⟨4/7⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 1은 ⟨7/7⟩이에요 — 1 × 7 = 7.","여기에 ⟨4/7⟩를 더하면 분자는 7 + 4 = 11이에요.","⟨1 4/7⟩ = ⟨11/7⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L06_basic#2','math',6,1,'u1','L06','g6_1_math_u1_L06_basic','lesson_basic','M6-1-u1-C6',1,'sa','auto','⟨2 4/9⟩ ÷ 3을 계산하려고 ⟨2 4/9⟩를 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u1-C6","difficulty":1,"kind":"sa","stem":"⟨2 4/9⟩ ÷ 3을 계산하려고 ⟨2 4/9⟩를 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["대분수는 먼저 가분수로 고쳐요.","2 × 9 + 4 = 22예요.","⟨2 4/9⟩ = ⟨22/9⟩ — 분자는 22예요."],"mis":"M6-1-u1-X05","variant_rule":{"alt":[{"stem":"⟨3 2/5⟩ ÷ 4를 계산하려고 ⟨3 2/5⟩를 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["대분수는 먼저 가분수로 고쳐요.","3 × 5 + 2 = 17이에요.","⟨3 2/5⟩ = ⟨17/5⟩ — 분자는 17이에요."]},{"stem":"⟨1 5/8⟩ ÷ 2를 계산하려고 ⟨1 5/8⟩를 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["대분수는 먼저 가분수로 고쳐요.","1 × 8 + 5 = 13이에요.","⟨1 5/8⟩ = ⟨13/8⟩ — 분자는 13이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L06_basic#3','math',6,1,'u1','L06','g6_1_math_u1_L06_basic','lesson_basic','M6-1-u1-C6',1,'sa','auto','⟨1 2/3⟩ ÷ 3을 계산하여 기약분수로 나타내면 몫의 분모는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-1-u1-C6","difficulty":1,"kind":"sa","stem":"⟨1 2/3⟩ ÷ 3을 계산하여 기약분수로 나타내면 몫의 분모는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["⟨1 2/3⟩ = ⟨5/3⟩예요.","⟨5/3⟩ ÷ 3 = ⟨5/3⟩ × ⟨1/3⟩ = ⟨5/9⟩예요.","그래서 몫의 분모는 9예요."],"mis":"M6-1-u1-X15","variant_rule":{"alt":[{"stem":"⟨2 1/4⟩ ÷ 3을 계산하여 기약분수로 나타내면 몫의 분모는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["⟨2 1/4⟩ = ⟨9/4⟩예요.","⟨9/4⟩ ÷ 3 = ⟨9/4⟩ × ⟨1/3⟩ = ⟨3/4⟩이에요.","그래서 몫의 분모는 4예요."]},{"stem":"⟨1 3/5⟩ ÷ 2를 계산하여 기약분수로 나타내면 몫의 분모는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["⟨1 3/5⟩ = ⟨8/5⟩이에요.","⟨8/5⟩ ÷ 2 = ⟨8/5⟩ × ⟨1/2⟩ = ⟨4/5⟩예요.","그래서 몫의 분모는 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L06_basic#4','math',6,1,'u1','L06','g6_1_math_u1_L06_basic','lesson_basic','M6-1-u1-C6',1,'ox','auto','⟨2 1/4⟩ = ⟨9/4⟩예요.',ARRAY['M6-1-u1-X05']::text[],true,'{"seq":4,"concept":"M6-1-u1-C6","difficulty":1,"kind":"ox","stem":"⟨2 1/4⟩ = ⟨9/4⟩예요.","answer":"O","reason_options":[{"t":"2 × 4 + 1 = 9이므로","correct":true},{"t":"자연수와 분자를 더하므로","mis":"M6-1-u1-X05"}],"mis":"M6-1-u1-X05","explanation":["자연수 2는 ⟨8/4⟩이에요.","⟨8/4⟩ + ⟨1/4⟩ = ⟨9/4⟩예요.","그래서 맞아요."],"variant_rule":{"alt":[{"stem":"⟨1 2/3⟩ ÷ 3을 계산할 때 자연수 1만 3으로 나누고 ⟨2/3⟩는 그대로 두어도 돼요.","answer":"X","reason_options":[{"t":"분수 부분도 함께 나누어야 하니 ⟨5/3⟩ × ⟨1/3⟩로 계산해야 하므로","correct":true},{"t":"자연수 부분만 나누면 되므로","mis":"M6-1-u1-X10"}],"explanation":["⟨1 2/3⟩ = ⟨5/3⟩예요.","⟨5/3⟩ ÷ 3 = ⟨5/3⟩ × ⟨1/3⟩ = ⟨5/9⟩예요.","분수 부분을 그대로 두면 틀려요."]},{"stem":"⟨1 3/5⟩을 가분수로 고치면 ⟨4/5⟩예요.","answer":"X","reason_options":[{"t":"1 × 5 + 3 = 8이라 ⟨8/5⟩이므로","correct":true},{"t":"자연수와 분자를 더하면 되므로","mis":"M6-1-u1-X05"}],"explanation":["자연수 1은 ⟨5/5⟩예요.","⟨5/5⟩ + ⟨3/5⟩ = ⟨8/5⟩이에요.","⟨4/5⟩는 자연수와 분자를 더한 실수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L06_basic#5','math',6,1,'u1','L06','g6_1_math_u1_L06_basic','lesson_basic','M6-1-u1-C6',2,'mc','auto','⟨1 1/6⟩ ÷ 7을 계산하면 얼마인가요?',ARRAY['M6-1-u1-X10','M6-1-u1-X06']::text[],true,'{"seq":5,"concept":"M6-1-u1-C6","difficulty":2,"kind":"mc","stem":"⟨1 1/6⟩ ÷ 7을 계산하면 얼마인가요?","options":[{"t":"⟨1/6⟩","correct":true},{"t":"⟨1 1/42⟩","mis":"M6-1-u1-X10"},{"t":"⟨13/42⟩","mis":"M6-1-u1-X10"},{"t":"⟨8 1/6⟩","mis":"M6-1-u1-X06"}],"explanation":["⟨1 1/6⟩을 가분수로 고치면 ⟨7/6⟩이에요.","⟨7/6⟩ ÷ 7 = ⟨7/6⟩ × ⟨1/7⟩이에요.","⟨7/6⟩ × ⟨1/7⟩ = ⟨1/6⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨2 3/7⟩ ÷ 4를 계산하면 얼마인가요?","options":[{"t":"⟨17/28⟩","correct":true},{"t":"⟨2 3/28⟩","mis":"M6-1-u1-X10"},{"t":"⟨13/14⟩","mis":"M6-1-u1-X10"},{"t":"⟨9 5/7⟩","mis":"M6-1-u1-X06"}],"explanation":["⟨2 3/7⟩을 가분수로 고치면 ⟨17/7⟩이에요.","⟨17/7⟩ ÷ 4 = ⟨17/7⟩ × ⟨1/4⟩이에요.","⟨17/7⟩ × ⟨1/4⟩ = ⟨17/28⟩이에요."]},{"stem":"⟨1 2/3⟩ ÷ 3을 계산하면 얼마인가요?","options":[{"t":"⟨5/9⟩","correct":true},{"t":"⟨1 2/9⟩","mis":"M6-1-u1-X10"},{"t":"1","mis":"M6-1-u1-X10"},{"t":"5","mis":"M6-1-u1-X06"}],"explanation":["⟨1 2/3⟩를 가분수로 고치면 ⟨5/3⟩예요.","⟨5/3⟩ ÷ 3 = ⟨5/3⟩ × ⟨1/3⟩이에요.","⟨5/3⟩ × ⟨1/3⟩ = ⟨5/9⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L06_basic#6','math',6,1,'u1','L06','g6_1_math_u1_L06_basic','lesson_basic','M6-1-u1-C6',2,'mc','auto','(대분수)÷(자연수)를 계산하는 순서로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u1-X10','M6-1-u1-X07']::text[],true,'{"seq":6,"concept":"M6-1-u1-C6","difficulty":2,"kind":"mc","stem":"(대분수)÷(자연수)를 계산하는 순서로 알맞은 것은 어느 것인가요?","options":[{"t":"대분수를 가분수로 고친 뒤 나누는 수의 단위분수를 곱한다","correct":true},{"t":"대분수의 분모에만 나누는 수를 곱한다","mis":"M6-1-u1-X10"},{"t":"자연수 부분만 나누는 수로 나누고 분수 부분은 그대로 둔다","mis":"M6-1-u1-X10"},{"t":"대분수를 뒤집은 뒤 나누는 수를 곱한다","mis":"M6-1-u1-X07"}],"explanation":["(대분수)÷(자연수)는 두 걸음이에요.","① 대분수를 가분수로 고치고 ② 나누는 수의 단위분수를 곱해요.","그래서 답은 「대분수를 가분수로 고친 뒤 나누는 수의 단위분수를 곱한다」예요."],"variant_rule":{"alt":[{"stem":"(대분수)÷(자연수)를 계산할 때 가장 먼저 할 일은 무엇인가요?","options":[{"t":"대분수를 가분수로 고친다","correct":true},{"t":"나누는 수를 그대로 곱한다","mis":"M6-1-u1-X06"},{"t":"분모를 나누는 수로 나눈다","mis":"M6-1-u1-X08"},{"t":"자연수 부분을 지운다","mis":"M6-1-u1-X10"}],"explanation":["(대분수)÷(자연수)는 두 걸음이에요.","① 대분수를 가분수로 고치고 ② 나누는 수의 단위분수를 곱해요.","그래서 답은 「대분수를 가분수로 고친다」예요."]},{"stem":"(대분수)÷(자연수)를 계산할 때 대분수를 가분수로 먼저 고치는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 덩어리를 한 덩어리로 모아 한 번에 나누려고","correct":true},{"t":"대분수는 곱할 수 없어서","mis":"M6-1-u1-X15"},{"t":"가분수로 고치면 몫이 커져서","mis":"M6-1-u1-X11"},{"t":"나누는 수를 그대로 곱하려고","mis":"M6-1-u1-X06"}],"explanation":["(대분수)÷(자연수)는 두 걸음이에요.","① 대분수를 가분수로 고치고 ② 나누는 수의 단위분수를 곱해요.","그래서 답은 「두 덩어리를 한 덩어리로 모아 한 번에 나누려고」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L06_basic#7','math',6,1,'u1','L06','g6_1_math_u1_L06_basic','lesson_basic','M6-1-u1-C6',2,'sa','auto','페인트 ⟨3 2/5⟩ L를 4명이 똑같이 나누어 가졌어요. 한 명이 가지는 페인트를 분수로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u1-C6","difficulty":2,"kind":"sa","stem":"페인트 ⟨3 2/5⟩ L를 4명이 똑같이 나누어 가졌어요. 한 명이 가지는 페인트를 분수로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["37"],"explanation":["⟨3 2/5⟩ = ⟨17/5⟩이에요.","⟨17/5⟩ ÷ 4 = ⟨17/5⟩ × ⟨1/4⟩ = ⟨17/20⟩이에요.","한 명이 가지는 페인트는 ⟨17/20⟩ L — 분모와 분자의 합은 20 + 17 = 37이에요."],"mis":"M6-1-u1-X15","variant_rule":{"alt":[{"stem":"유기견 보호소에서 사료 ⟨1 2/3⟩통을 3곳에 똑같이 나누어 주려고 해요. 한 곳에 주는 사료를 분수로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["⟨1 2/3⟩ = ⟨5/3⟩예요.","⟨5/3⟩ ÷ 3 = ⟨5/3⟩ × ⟨1/3⟩ = ⟨5/9⟩예요.","한 곳에 주는 사료는 ⟨5/9⟩통 — 분모와 분자의 합은 9 + 5 = 14예요."]},{"stem":"찰흙 ⟨2 1/4⟩ kg을 5모둠이 똑같이 나누어 가졌어요. 한 모둠이 가지는 찰흙을 분수로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["29"],"explanation":["⟨2 1/4⟩ = ⟨9/4⟩예요.","⟨9/4⟩ ÷ 5 = ⟨9/4⟩ × ⟨1/5⟩ = ⟨9/20⟩예요.","한 모둠이 가지는 찰흙은 ⟨9/20⟩ kg — 분모와 분자의 합은 20 + 9 = 29예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L06_basic#8','math',6,1,'u1','L06','g6_1_math_u1_L06_basic','lesson_basic','M6-1-u1-C6',2,'mc','auto','⟨2 3/7⟩ ÷ 4를 바르게 계산한 것은 어느 것인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X10','M6-1-u1-X07']::text[],true,'{"seq":8,"concept":"M6-1-u1-C6","difficulty":2,"kind":"mc","stem":"⟨2 3/7⟩ ÷ 4를 바르게 계산한 것은 어느 것인가요?","options":[{"t":"⟨17/7⟩ × ⟨1/4⟩ = ⟨17/28⟩","correct":true},{"t":"⟨2 3/7⟩ × 4","mis":"M6-1-u1-X06"},{"t":"⟨2 3/7⟩의 분모에만 4를 곱해 ⟨2 3/28⟩","mis":"M6-1-u1-X10"},{"t":"⟨7/17⟩ × ⟨1/4⟩","mis":"M6-1-u1-X07"}],"explanation":["먼저 ⟨2 3/7⟩ = ⟨17/7⟩로 고쳐요.","⟨17/7⟩ ÷ 4 = ⟨17/7⟩ × ⟨1/4⟩이에요.","⟨17/7⟩ × ⟨1/4⟩ = ⟨17/28⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨1 1/5⟩ ÷ 3을 바르게 계산한 것은 어느 것인가요?","options":[{"t":"⟨6/5⟩ × ⟨1/3⟩ = ⟨2/5⟩","correct":true},{"t":"⟨1 1/5⟩ × 3","mis":"M6-1-u1-X06"},{"t":"⟨1 1/5⟩의 분모에만 3을 곱해 ⟨1 1/15⟩","mis":"M6-1-u1-X10"},{"t":"⟨5/6⟩ × ⟨1/3⟩","mis":"M6-1-u1-X07"}],"explanation":["먼저 ⟨1 1/5⟩ = ⟨6/5⟩으로 고쳐요.","⟨6/5⟩ ÷ 3 = ⟨6/5⟩ × ⟨1/3⟩이에요.","⟨6/5⟩ × ⟨1/3⟩ = ⟨2/5⟩예요."]},{"stem":"⟨3 1/2⟩ ÷ 5를 바르게 계산한 것은 어느 것인가요?","options":[{"t":"⟨7/2⟩ × ⟨1/5⟩ = ⟨7/10⟩","correct":true},{"t":"⟨3 1/2⟩ × 5","mis":"M6-1-u1-X06"},{"t":"⟨3 1/2⟩의 분모에만 5를 곱해 ⟨3 1/10⟩","mis":"M6-1-u1-X10"},{"t":"⟨2/7⟩ × ⟨1/5⟩","mis":"M6-1-u1-X07"}],"explanation":["먼저 ⟨3 1/2⟩ = ⟨7/2⟩로 고쳐요.","⟨7/2⟩ ÷ 5 = ⟨7/2⟩ × ⟨1/5⟩이에요.","⟨7/2⟩ × ⟨1/5⟩ = ⟨7/10⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L06_basic#9','math',6,1,'u1','L06','g6_1_math_u1_L06_basic','lesson_basic','M6-1-u1-C6',2,'match','auto','나눗셈과 몫을 알맞게 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u1-C6","difficulty":2,"kind":"match","stem":"나눗셈과 몫을 알맞게 이으세요.","pairs":[{"l":"⟨1 1/2⟩ ÷ 3","r":"⟨1/2⟩"},{"l":"⟨2 2/3⟩ ÷ 4","r":"⟨2/3⟩"},{"l":"⟨1 3/4⟩ ÷ 7","r":"⟨1/4⟩"}],"mis":"M6-1-u1-X10","explanation":["대분수를 먼저 가분수로 고쳐요.","⟨1 1/2⟩ ÷ 3 = ⟨1/2⟩, ⟨2 2/3⟩ ÷ 4 = ⟨2/3⟩, ⟨1 3/4⟩ ÷ 7 = ⟨1/4⟩이에요.","자연수 부분만 나누지 않도록 해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 나눗셈과 몫을 알맞게 이으세요.","pairs":[{"l":"⟨2 1/2⟩ ÷ 5","r":"⟨1/2⟩"},{"l":"⟨1 1/3⟩ ÷ 2","r":"⟨2/3⟩"},{"l":"⟨3 3/4⟩ ÷ 5","r":"⟨3/4⟩"}],"explanation":["대분수를 먼저 가분수로 고쳐요.","⟨2 1/2⟩ ÷ 5 = ⟨1/2⟩, ⟨1 1/3⟩ ÷ 2 = ⟨2/3⟩, ⟨3 3/4⟩ ÷ 5 = ⟨3/4⟩이에요.","자연수 부분만 나누지 않도록 해요."]},{"stem":"이번에는 다른 보기예요. 나눗셈과 몫을 알맞게 이으세요.","pairs":[{"l":"⟨1 4/5⟩ ÷ 3","r":"⟨3/5⟩"},{"l":"⟨2 1/3⟩ ÷ 7","r":"⟨1/3⟩"},{"l":"⟨4 1/2⟩ ÷ 3","r":"⟨1 1/2⟩"}],"explanation":["대분수를 먼저 가분수로 고쳐요.","⟨1 4/5⟩ ÷ 3 = ⟨3/5⟩, ⟨2 1/3⟩ ÷ 7 = ⟨1/3⟩, ⟨4 1/2⟩ ÷ 3 = ⟨1 1/2⟩이에요.","자연수 부분만 나누지 않도록 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L06_basic#10','math',6,1,'u1','L06','g6_1_math_u1_L06_basic','lesson_basic','M6-1-u1-C6',3,'mc','auto','몫이 1보다 작은 것은 어느 것인가요?',ARRAY['M6-1-u1-X11']::text[],true,'{"seq":10,"concept":"M6-1-u1-C6","difficulty":3,"kind":"mc","stem":"몫이 1보다 작은 것은 어느 것인가요?","options":[{"t":"⟨1 1/5⟩ ÷ 2","correct":true},{"t":"⟨3 1/2⟩ ÷ 2","mis":"M6-1-u1-X11"},{"t":"⟨2 2/3⟩ ÷ 2","mis":"M6-1-u1-X11"},{"t":"⟨4 1/2⟩ ÷ 3","mis":"M6-1-u1-X11"}],"explanation":["대분수를 가분수로 고쳐 단위분수를 곱해요.","⟨3 1/2⟩ ÷ 2 = ⟨1 3/4⟩, ⟨2 2/3⟩ ÷ 2 = ⟨1 1/3⟩, ⟨1 1/5⟩ ÷ 2 = ⟨3/5⟩, ⟨4 1/2⟩ ÷ 3 = ⟨1 1/2⟩이에요.","몫이 1보다 작은 것은 ⟨1 1/5⟩ ÷ 2예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 몫이 1보다 작은 것은 어느 것인가요?","options":[{"t":"⟨1 2/7⟩ ÷ 3","correct":true},{"t":"⟨2 1/4⟩ ÷ 2","mis":"M6-1-u1-X11"},{"t":"⟨3 1/3⟩ ÷ 3","mis":"M6-1-u1-X11"},{"t":"⟨5 1/2⟩ ÷ 4","mis":"M6-1-u1-X11"}],"explanation":["대분수를 가분수로 고쳐 단위분수를 곱해요.","⟨2 1/4⟩ ÷ 2 = ⟨1 1/8⟩, ⟨3 1/3⟩ ÷ 3 = ⟨1 1/9⟩, ⟨1 2/7⟩ ÷ 3 = ⟨3/7⟩, ⟨5 1/2⟩ ÷ 4 = ⟨1 3/8⟩이에요.","몫이 1보다 작은 것은 ⟨1 2/7⟩ ÷ 3이에요."]},{"stem":"이번에는 다른 보기예요. 몫이 1보다 작은 것은 어느 것인가요?","options":[{"t":"⟨1 1/2⟩ ÷ 2","correct":true},{"t":"⟨2 3/5⟩ ÷ 2","mis":"M6-1-u1-X11"},{"t":"⟨3 3/4⟩ ÷ 3","mis":"M6-1-u1-X11"},{"t":"⟨4 2/3⟩ ÷ 4","mis":"M6-1-u1-X11"}],"explanation":["대분수를 가분수로 고쳐 단위분수를 곱해요.","⟨1 1/2⟩ ÷ 2 = ⟨3/4⟩, ⟨2 3/5⟩ ÷ 2 = ⟨1 3/10⟩, ⟨3 3/4⟩ ÷ 3 = ⟨1 1/4⟩, ⟨4 2/3⟩ ÷ 4 = ⟨1 1/6⟩이에요.","몫이 1보다 작은 것은 ⟨1 1/2⟩ ÷ 2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L06_challenge#1','math',6,1,'u1','L06','g6_1_math_u1_L06_challenge','lesson_challenge','M6-1-u1-C6',2,'mc','auto','⟨3 1/3⟩ ÷ 5를 계산하면 얼마인가요?',ARRAY['M6-1-u1-X10','M6-1-u1-X06']::text[],true,'{"seq":1,"concept":"M6-1-u1-C6","difficulty":2,"kind":"mc","stem":"⟨3 1/3⟩ ÷ 5를 계산하면 얼마인가요?","options":[{"t":"⟨2/3⟩","correct":true},{"t":"⟨3 1/15⟩","mis":"M6-1-u1-X10"},{"t":"⟨14/15⟩","mis":"M6-1-u1-X10"},{"t":"⟨16 2/3⟩","mis":"M6-1-u1-X06"}],"explanation":["⟨3 1/3⟩을 가분수로 고치면 ⟨10/3⟩이에요.","⟨10/3⟩ ÷ 5 = ⟨10/3⟩ × ⟨1/5⟩이에요.","⟨10/3⟩ × ⟨1/5⟩ = ⟨2/3⟩예요."],"variant_rule":{"alt":[{"stem":"⟨2 2/5⟩ ÷ 4를 계산하면 얼마인가요?","options":[{"t":"⟨3/5⟩","correct":true},{"t":"⟨2 1/10⟩","mis":"M6-1-u1-X10"},{"t":"⟨9/10⟩","mis":"M6-1-u1-X10"},{"t":"⟨9 3/5⟩","mis":"M6-1-u1-X06"}],"explanation":["⟨2 2/5⟩를 가분수로 고치면 ⟨12/5⟩예요.","⟨12/5⟩ ÷ 4 = ⟨12/5⟩ × ⟨1/4⟩이에요.","⟨12/5⟩ × ⟨1/4⟩ = ⟨3/5⟩이에요."]},{"stem":"⟨4 1/2⟩ ÷ 6을 계산하면 얼마인가요?","options":[{"t":"⟨3/4⟩","correct":true},{"t":"⟨4 1/12⟩","mis":"M6-1-u1-X10"},{"t":"⟨1 1/6⟩","mis":"M6-1-u1-X10"},{"t":"27","mis":"M6-1-u1-X06"}],"explanation":["⟨4 1/2⟩을 가분수로 고치면 ⟨9/2⟩예요.","⟨9/2⟩ ÷ 6 = ⟨9/2⟩ × ⟨1/6⟩이에요.","⟨9/2⟩ × ⟨1/6⟩ = ⟨3/4⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L06_challenge#2','math',6,1,'u1','L06','g6_1_math_u1_L06_challenge','lesson_challenge','M6-1-u1-C6',2,'sa','auto','⟨3 4/7⟩ ÷ 5를 계산하려고 ⟨3 4/7⟩를 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u1-C6","difficulty":2,"kind":"sa","stem":"⟨3 4/7⟩ ÷ 5를 계산하려고 ⟨3 4/7⟩를 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["대분수는 먼저 가분수로 고쳐요.","3 × 7 + 4 = 25예요.","⟨3 4/7⟩ = ⟨25/7⟩ — 분자는 25예요."],"mis":"M6-1-u1-X05","variant_rule":{"alt":[{"stem":"⟨4 2/9⟩ ÷ 3을 계산하려고 ⟨4 2/9⟩를 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["38"],"explanation":["대분수는 먼저 가분수로 고쳐요.","4 × 9 + 2 = 38이에요.","⟨4 2/9⟩ = ⟨38/9⟩ — 분자는 38이에요."]},{"stem":"⟨5 1/6⟩ ÷ 4를 계산하려고 ⟨5 1/6⟩을 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["31"],"explanation":["대분수는 먼저 가분수로 고쳐요.","5 × 6 + 1 = 31이에요.","⟨5 1/6⟩ = ⟨31/6⟩ — 분자는 31이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L06_challenge#3','math',6,1,'u1','L06','g6_1_math_u1_L06_challenge','lesson_challenge','M6-1-u1-C6',3,'mc','auto','넓이가 ⟨5 3/4⟩ m²이고 가로가 2 m인 직사각형이 있어요. 세로는 몇 m인가요?',ARRAY['M6-1-u1-X10','M6-1-u1-X06']::text[],true,'{"seq":3,"concept":"M6-1-u1-C6","difficulty":3,"kind":"mc","stem":"넓이가 ⟨5 3/4⟩ m²이고 가로가 2 m인 직사각형이 있어요. 세로는 몇 m인가요?","options":[{"t":"⟨2 7/8⟩","correct":true},{"t":"⟨5 3/8⟩","mis":"M6-1-u1-X10"},{"t":"⟨3 1/4⟩","mis":"M6-1-u1-X10"},{"t":"⟨11 1/2⟩","mis":"M6-1-u1-X06"}],"explanation":["(직사각형의 넓이) = (가로) × (세로)이니 세로 = 넓이 ÷ 가로예요.","⟨5 3/4⟩ ÷ 2 = ⟨23/4⟩ × ⟨1/2⟩이에요.","⟨23/4⟩ × ⟨1/2⟩ = ⟨2 7/8⟩ — 세로는 ⟨2 7/8⟩ m예요."],"variant_rule":{"alt":[{"stem":"넓이가 ⟨6 2/3⟩ m²이고 가로가 4 m인 직사각형이 있어요. 세로는 몇 m인가요?","options":[{"t":"⟨1 2/3⟩","correct":true},{"t":"⟨6 1/6⟩","mis":"M6-1-u1-X10"},{"t":"⟨2 1/6⟩","mis":"M6-1-u1-X10"},{"t":"⟨26 2/3⟩","mis":"M6-1-u1-X06"}],"explanation":["(직사각형의 넓이) = (가로) × (세로)이니 세로 = 넓이 ÷ 가로예요.","⟨6 2/3⟩ ÷ 4 = ⟨20/3⟩ × ⟨1/4⟩이에요.","⟨20/3⟩ × ⟨1/4⟩ = ⟨1 2/3⟩ — 세로는 ⟨1 2/3⟩ m예요."]},{"stem":"넓이가 ⟨7 1/2⟩ m²이고 가로가 3 m인 직사각형이 있어요. 세로는 몇 m인가요?","options":[{"t":"⟨2 1/2⟩","correct":true},{"t":"⟨7 1/6⟩","mis":"M6-1-u1-X10"},{"t":"⟨2 5/6⟩","mis":"M6-1-u1-X10"},{"t":"⟨22 1/2⟩","mis":"M6-1-u1-X06"}],"explanation":["(직사각형의 넓이) = (가로) × (세로)이니 세로 = 넓이 ÷ 가로예요.","⟨7 1/2⟩ ÷ 3 = ⟨15/2⟩ × ⟨1/3⟩이에요.","⟨15/2⟩ × ⟨1/3⟩ = ⟨2 1/2⟩ — 세로는 ⟨2 1/2⟩ m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L06_challenge#4','math',6,1,'u1','L06','g6_1_math_u1_L06_challenge','lesson_challenge','M6-1-u1-C6',3,'error','auto','⟨2 3/7⟩ ÷ 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u1-X10','M6-1-u1-X15']::text[],true,'{"seq":4,"concept":"M6-1-u1-C6","difficulty":3,"kind":"error","stem":"⟨2 3/7⟩ ÷ 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「자연수 2만 4로 나누고 ⟨3/7⟩은 그대로 두면 돼.」","correct":true,"mis_target":"M6-1-u1-X10"},{"t":"도윤 — 「먼저 ⟨17/7⟩로 고쳐야 해.」","mis":"M6-1-u1-X15"},{"t":"하린 — 「몫은 ⟨17/28⟩이야.」","mis":"M6-1-u1-X15"}],"explanation":["⟨2 3/7⟩의 분수 부분 ⟨3/7⟩도 함께 나누어야 해요.","⟨17/7⟩ ÷ 4 = ⟨17/7⟩ × ⟨1/4⟩ = ⟨17/28⟩이에요.","수아는 자연수 부분만 나누었어요."],"variant_rule":{"alt":[{"stem":"⟨3 1/2⟩ ÷ 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민준 — 「자연수 3만 4로 나누고 ⟨1/2⟩은 그대로 두면 돼.」","correct":true,"mis_target":"M6-1-u1-X10"},{"t":"서연 — 「먼저 ⟨7/2⟩로 고쳐야 해.」","mis":"M6-1-u1-X15"},{"t":"지호 — 「몫은 ⟨7/8⟩이야.」","mis":"M6-1-u1-X15"}],"explanation":["⟨3 1/2⟩의 분수 부분 ⟨1/2⟩도 함께 나누어야 해요.","⟨7/2⟩ ÷ 4 = ⟨7/2⟩ × ⟨1/4⟩ = ⟨7/8⟩이에요.","민준은 자연수 부분만 나누었어요."]},{"stem":"⟨1 2/3⟩ ÷ 3을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「자연수 1만 3으로 나누고 ⟨2/3⟩는 그대로 두면 돼.」","correct":true,"mis_target":"M6-1-u1-X10"},{"t":"나린 — 「먼저 ⟨5/3⟩로 고쳐야 해.」","mis":"M6-1-u1-X15"},{"t":"유진 — 「몫은 ⟨5/9⟩야.」","mis":"M6-1-u1-X15"}],"explanation":["⟨1 2/3⟩의 분수 부분 ⟨2/3⟩도 함께 나누어야 해요.","⟨5/3⟩ ÷ 3 = ⟨5/3⟩ × ⟨1/3⟩ = ⟨5/9⟩예요.","가온은 자연수 부분만 나누었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L06_challenge#5','math',6,1,'u1','L06','g6_1_math_u1_L06_challenge','lesson_challenge','M6-1-u1-C6',3,'sa','auto','우유 ⟨2 1/3⟩ L를 4명이 똑같이 나누어 마셨어요. 한 명이 마신 우유를 분수로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u1-C6","difficulty":3,"kind":"sa","stem":"우유 ⟨2 1/3⟩ L를 4명이 똑같이 나누어 마셨어요. 한 명이 마신 우유를 분수로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["⟨2 1/3⟩ = ⟨7/3⟩이에요.","⟨7/3⟩ ÷ 4 = ⟨7/3⟩ × ⟨1/4⟩ = ⟨7/12⟩이에요.","한 명이 마신 우유는 ⟨7/12⟩ L — 분모와 분자의 합은 12 + 7 = 19예요."],"mis":"M6-1-u1-X15","variant_rule":{"alt":[{"stem":"페인트 ⟨4 1/2⟩ L를 3명이 똑같이 나누어 가졌어요. 한 명이 가지는 페인트를 분수로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["⟨4 1/2⟩ = ⟨9/2⟩예요.","⟨9/2⟩ ÷ 3 = ⟨9/2⟩ × ⟨1/3⟩ = ⟨3/2⟩이에요.","한 명이 가지는 페인트는 ⟨1 1/2⟩ L — 분모와 분자의 합은 2 + 3 = 5예요."]},{"stem":"유기견 보호소에서 사료 ⟨3 3/5⟩통을 6곳에 똑같이 나누어 주려고 해요. 한 곳에 주는 사료를 분수로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["⟨3 3/5⟩ = ⟨18/5⟩이에요.","⟨18/5⟩ ÷ 6 = ⟨18/5⟩ × ⟨1/6⟩ = ⟨3/5⟩이에요.","한 곳에 주는 사료는 ⟨3/5⟩통 — 분모와 분자의 합은 5 + 3 = 8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L06_challenge#6','math',6,1,'u1','L06','g6_1_math_u1_L06_challenge','lesson_challenge','M6-1-u1-C6',3,'ox','auto','⟨2 2/3⟩ ÷ 2 = ⟨1 1/3⟩이에요.',ARRAY['M6-1-u1-X10']::text[],true,'{"seq":6,"concept":"M6-1-u1-C6","difficulty":3,"kind":"ox","stem":"⟨2 2/3⟩ ÷ 2 = ⟨1 1/3⟩이에요.","answer":"O","reason_options":[{"t":"⟨8/3⟩ × ⟨1/2⟩ = ⟨4/3⟩ = ⟨1 1/3⟩이므로","correct":true},{"t":"자연수 2를 2로 나누면 1이므로","mis":"M6-1-u1-X10"}],"mis":"M6-1-u1-X10","explanation":["⟨2 2/3⟩ = ⟨8/3⟩이에요.","⟨8/3⟩ × ⟨1/2⟩ = ⟨4/3⟩예요.","⟨4/3⟩ = ⟨1 1/3⟩ — 맞아요."],"variant_rule":{"alt":[{"stem":"⟨3 1/2⟩ ÷ 4 = ⟨3 1/8⟩이에요.","answer":"X","reason_options":[{"t":"⟨7/2⟩ × ⟨1/4⟩ = ⟨7/8⟩이어야 하므로","correct":true},{"t":"분수 부분의 분모에 4를 곱하면 되므로","mis":"M6-1-u1-X10"}],"explanation":["⟨3 1/2⟩ = ⟨7/2⟩이에요.","⟨7/2⟩ × ⟨1/4⟩ = ⟨7/8⟩이에요.","⟨3 1/8⟩은 분수 부분만 나눈 거예요."]},{"stem":"⟨2 1/3⟩ ÷ 3의 몫은 1보다 작아요.","answer":"O","reason_options":[{"t":"⟨7/3⟩ × ⟨1/3⟩ = ⟨7/9⟩이고 이것은 1보다 작으므로","correct":true},{"t":"대분수를 나누면 몫이 늘 1보다 크므로","mis":"M6-1-u1-X11"}],"explanation":["⟨2 1/3⟩ = ⟨7/3⟩이에요.","⟨7/3⟩ × ⟨1/3⟩ = ⟨7/9⟩이에요.","⟨7/9⟩ < 1 — 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L06_challenge#7','math',6,1,'u1','L06','g6_1_math_u1_L06_challenge','lesson_challenge','M6-1-u1-C6',3,'mc','auto','몫이 1보다 작은 것은 어느 것인가요?',ARRAY['M6-1-u1-X11']::text[],true,'{"seq":7,"concept":"M6-1-u1-C6","difficulty":3,"kind":"mc","stem":"몫이 1보다 작은 것은 어느 것인가요?","options":[{"t":"⟨2 1/2⟩ ÷ 3","correct":true},{"t":"⟨3 1/4⟩ ÷ 2","mis":"M6-1-u1-X11"},{"t":"⟨4 1/3⟩ ÷ 3","mis":"M6-1-u1-X11"},{"t":"⟨5 1/2⟩ ÷ 5","mis":"M6-1-u1-X11"}],"explanation":["대분수를 가분수로 고쳐 단위분수를 곱해요.","⟨2 1/2⟩ ÷ 3 = ⟨5/6⟩, ⟨3 1/4⟩ ÷ 2 = ⟨1 5/8⟩, ⟨4 1/3⟩ ÷ 3 = ⟨1 4/9⟩, ⟨5 1/2⟩ ÷ 5 = ⟨1 1/10⟩이에요.","몫이 1보다 작은 것은 ⟨2 1/2⟩ ÷ 3이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 몫이 1보다 작은 것은 어느 것인가요?","options":[{"t":"⟨1 3/4⟩ ÷ 2","correct":true},{"t":"⟨2 4/5⟩ ÷ 2","mis":"M6-1-u1-X11"},{"t":"⟨3 2/3⟩ ÷ 2","mis":"M6-1-u1-X11"},{"t":"⟨4 3/4⟩ ÷ 4","mis":"M6-1-u1-X11"}],"explanation":["대분수를 가분수로 고쳐 단위분수를 곱해요.","⟨1 3/4⟩ ÷ 2 = ⟨7/8⟩, ⟨2 4/5⟩ ÷ 2 = ⟨1 2/5⟩, ⟨3 2/3⟩ ÷ 2 = ⟨1 5/6⟩, ⟨4 3/4⟩ ÷ 4 = ⟨1 3/16⟩이에요.","몫이 1보다 작은 것은 ⟨1 3/4⟩ ÷ 2예요."]},{"stem":"이번에는 다른 보기예요. 몫이 1보다 작은 것은 어느 것인가요?","options":[{"t":"⟨2 2/5⟩ ÷ 3","correct":true},{"t":"⟨2 5/6⟩ ÷ 2","mis":"M6-1-u1-X11"},{"t":"⟨3 1/6⟩ ÷ 2","mis":"M6-1-u1-X11"},{"t":"⟨6 1/3⟩ ÷ 5","mis":"M6-1-u1-X11"}],"explanation":["대분수를 가분수로 고쳐 단위분수를 곱해요.","⟨2 2/5⟩ ÷ 3 = ⟨4/5⟩, ⟨2 5/6⟩ ÷ 2 = ⟨1 5/12⟩, ⟨3 1/6⟩ ÷ 2 = ⟨1 7/12⟩, ⟨6 1/3⟩ ÷ 5 = ⟨1 4/15⟩예요.","몫이 1보다 작은 것은 ⟨2 2/5⟩ ÷ 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L06_challenge#8','math',6,1,'u1','L06','g6_1_math_u1_L06_challenge','lesson_challenge','M6-1-u1-C6',4,'mc','auto','수 카드 7, 5, 6, 2를 한 번씩만 써서 (대분수)÷(자연수)를 만들 때, 몫이 가장 큰 것은 어느 것인가요?',ARRAY['M6-1-u1-X11']::text[],true,'{"seq":8,"concept":"M6-1-u1-C6","difficulty":4,"kind":"mc","stem":"수 카드 7, 5, 6, 2를 한 번씩만 써서 (대분수)÷(자연수)를 만들 때, 몫이 가장 큰 것은 어느 것인가요?","options":[{"t":"⟨7 5/6⟩ ÷ 2","correct":true},{"t":"⟨5 6/7⟩ ÷ 2","mis":"M6-1-u1-X11"},{"t":"⟨6 5/7⟩ ÷ 2","mis":"M6-1-u1-X11"},{"t":"⟨5 2/6⟩ ÷ 7","mis":"M6-1-u1-X11"}],"explanation":["몫이 크려면 나누어지는 대분수는 크게, 나누는 수는 작게 해야 해요.","⟨7 5/6⟩ ÷ 2 = ⟨47/6⟩ × ⟨1/2⟩ = ⟨3 11/12⟩이에요.","다른 식의 몫은 이보다 작아요 — 답은 ⟨7 5/6⟩ ÷ 2예요."],"variant_rule":{"alt":[{"stem":"수 카드 3, 8, 4, 5를 한 번씩만 써서 (대분수)÷(자연수)를 만들 때, 몫이 가장 큰 것은 어느 것인가요?","options":[{"t":"⟨8 4/5⟩ ÷ 3","correct":true},{"t":"⟨5 4/8⟩ ÷ 3","mis":"M6-1-u1-X11"},{"t":"⟨8 3/5⟩ ÷ 4","mis":"M6-1-u1-X11"},{"t":"⟨5 3/4⟩ ÷ 8","mis":"M6-1-u1-X11"}],"explanation":["몫이 크려면 나누어지는 대분수는 크게, 나누는 수는 작게 해야 해요.","⟨8 4/5⟩ ÷ 3 = ⟨44/5⟩ × ⟨1/3⟩ = ⟨2 14/15⟩예요.","다른 식의 몫은 이보다 작아요 — 답은 ⟨8 4/5⟩ ÷ 3이에요."]},{"stem":"수 카드 2, 9, 4, 7을 한 번씩만 써서 (대분수)÷(자연수)를 만들 때, 몫이 가장 작은 것은 어느 것인가요?","options":[{"t":"⟨2 4/7⟩ ÷ 9","correct":true},{"t":"⟨4 2/7⟩ ÷ 9","mis":"M6-1-u1-X11"},{"t":"⟨2 4/9⟩ ÷ 7","mis":"M6-1-u1-X11"},{"t":"⟨9 2/7⟩ ÷ 4","mis":"M6-1-u1-X11"}],"explanation":["몫이 작려면 나누어지는 대분수는 작게, 나누는 수는 크게 해야 해요.","⟨2 4/7⟩ ÷ 9 = ⟨18/7⟩ × ⟨1/9⟩ = ⟨2/7⟩예요.","다른 식의 몫은 이보다 커요 — 답은 ⟨2 4/7⟩ ÷ 9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L06_challenge#9','math',6,1,'u1','L06','g6_1_math_u1_L06_challenge','lesson_challenge','M6-1-u1-C6',4,'sa','auto','자연수 부분이 □이고 분수 부분이 ⟨1/4⟩인 대분수를 3으로 나누었더니 ⟨3/4⟩이 되었어요. □에 알맞은 자연수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u1-C6","difficulty":4,"kind":"sa","stem":"자연수 부분이 □이고 분수 부분이 ⟨1/4⟩인 대분수를 3으로 나누었더니 ⟨3/4⟩이 되었어요. □에 알맞은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["나누기 전의 수는 ⟨3/4⟩ × 3이에요.","⟨3/4⟩ × 3 = ⟨9/4⟩ = ⟨2 1/4⟩이에요.","그래서 □는 2예요."],"mis":"M6-1-u1-X10","variant_rule":{"alt":[{"stem":"⟨2 □/5⟩ ÷ 4 = ⟨13/20⟩일 때 □에 알맞은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["나누기 전의 수는 ⟨13/20⟩ × 4예요.","⟨13/20⟩ × 4 = ⟨13/5⟩ = ⟨2 3/5⟩이에요.","그래서 □는 3이에요."]},{"stem":"자연수 부분이 □이고 분수 부분이 ⟨1/2⟩인 대분수를 7로 나누었더니 ⟨1/2⟩이 되었어요. □에 알맞은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["나누기 전의 수는 ⟨1/2⟩ × 7이에요.","⟨1/2⟩ × 7 = ⟨7/2⟩ = ⟨3 1/2⟩이에요.","그래서 □는 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L06_challenge#10','math',6,1,'u1','L06','g6_1_math_u1_L06_challenge','lesson_challenge','M6-1-u1-C6',4,'essay','teacher','⟨2 3/7⟩ ÷ 4를 계산하는 과정을 쓰고, 대분수를 먼저 가분수로 고치는 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u1-C6","difficulty":4,"kind":"essay","stem":"⟨2 3/7⟩ ÷ 4를 계산하는 과정을 쓰고, 대분수를 먼저 가분수로 고치는 까닭을 설명해 보세요.","answer_guide":{"answer":"예: ⟨2 3/7⟩을 가분수로 고치면 2 × 7 + 3 = 17이므로 ⟨17/7⟩이다. ⟨17/7⟩ ÷ 4 = ⟨17/7⟩ × ⟨1/4⟩ = ⟨17/28⟩이다. 대분수는 자연수와 분수 두 덩어리라 그대로 나누면 자연수 부분만 나누는 실수를 하기 쉬우므로, 한 덩어리인 가분수로 모아 한 번에 나눈다.","scoring_points":["⟨2 3/7⟩ = ⟨17/7⟩로 고쳤는가","⟨17/7⟩ × ⟨1/4⟩ = ⟨17/28⟩을 구했는가","두 덩어리를 한 덩어리로 모으려고 가분수로 고친다고 설명했는가"]},"explanation":["⟨2 3/7⟩ = ⟨17/7⟩이에요.","⟨17/7⟩ × ⟨1/4⟩ = ⟨17/28⟩이에요.","가분수로 모으면 한 번에 나눌 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L07_basic#1','math',6,1,'u1','L07','g6_1_math_u1_L07_basic','lesson_basic','M6-1-u1-C7',1,'mc','auto','저울에서 파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 5개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?',ARRAY['M6-1-u1-X13']::text[],true,'{"seq":1,"concept":"M6-1-u1-C7","difficulty":1,"kind":"mc","stem":"저울에서 파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 5개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?","options":[{"t":"3개","correct":true},{"t":"2개","mis":"M6-1-u1-X13"},{"t":"5개","mis":"M6-1-u1-X13"},{"t":"7개","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 뚜껑 2개씩을 덜어 내도 저울은 수평이에요.","왼쪽엔 노란 뚜껑 1개, 오른쪽엔 파란 뚜껑 5 − 2 = 3개가 남아요.","그래서 노란 뚜껑 1개는 파란 뚜껑 3개와 같아요."],"variant_rule":{"alt":[{"stem":"저울에서 파란 뚜껑 1개와 노란 뚜껑 1개의 무게가 파란 뚜껑 4개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?","options":[{"t":"3개","correct":true},{"t":"1개","mis":"M6-1-u1-X13"},{"t":"4개","mis":"M6-1-u1-X13"},{"t":"5개","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 뚜껑 1개씩을 덜어 내도 저울은 수평이에요.","왼쪽엔 노란 뚜껑 1개, 오른쪽엔 파란 뚜껑 4 − 1 = 3개가 남아요.","그래서 노란 뚜껑 1개는 파란 뚜껑 3개와 같아요."]},{"stem":"저울에서 파란 뚜껑 3개와 노란 뚜껑 1개의 무게가 파란 뚜껑 7개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?","options":[{"t":"4개","correct":true},{"t":"3개","mis":"M6-1-u1-X13"},{"t":"7개","mis":"M6-1-u1-X13"},{"t":"10개","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 뚜껑 3개씩을 덜어 내도 저울은 수평이에요.","왼쪽엔 노란 뚜껑 1개, 오른쪽엔 파란 뚜껑 7 − 3 = 4개가 남아요.","그래서 노란 뚜껑 1개는 파란 뚜껑 4개와 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L07_basic#2','math',6,1,'u1','L07','g6_1_math_u1_L07_basic','lesson_basic','M6-1-u1-C7',1,'sa','auto','노란 뚜껑 1개의 무게는 ⟨4 1/3⟩ g이에요. 이 무게를 가분수로 나타낼 때 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u1-C7","difficulty":1,"kind":"sa","stem":"노란 뚜껑 1개의 무게는 ⟨4 1/3⟩ g이에요. 이 무게를 가분수로 나타낼 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["자연수 4는 ⟨12/3⟩예요.","4 × 3 + 1 = 13이에요.","⟨4 1/3⟩ = ⟨13/3⟩ — 분자는 13이에요."],"mis":"M6-1-u1-X05","variant_rule":{"alt":[{"stem":"노란 뚜껑 1개의 무게는 ⟨3 1/2⟩ g이에요. 이 무게를 가분수로 나타낼 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["자연수 3은 ⟨6/2⟩이에요.","3 × 2 + 1 = 7이에요.","⟨3 1/2⟩ = ⟨7/2⟩ — 분자는 7이에요."]},{"stem":"노란 뚜껑 1개의 무게는 ⟨5 2/3⟩ g이에요. 이 무게를 가분수로 나타낼 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["자연수 5는 ⟨15/3⟩예요.","5 × 3 + 2 = 17이에요.","⟨5 2/3⟩ = ⟨17/3⟩ — 분자는 17이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L07_basic#3','math',6,1,'u1','L07','g6_1_math_u1_L07_basic','lesson_basic','M6-1-u1-C7',1,'mc','auto','노란 뚜껑 1개(⟨4 1/3⟩ g)가 파란 뚜껑 3개와 무게가 같아요. 파란 뚜껑 1개의 무게를 구하는 곱셈식으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X05','M6-1-u1-X07']::text[],true,'{"seq":3,"concept":"M6-1-u1-C7","difficulty":1,"kind":"mc","stem":"노란 뚜껑 1개(⟨4 1/3⟩ g)가 파란 뚜껑 3개와 무게가 같아요. 파란 뚜껑 1개의 무게를 구하는 곱셈식으로 알맞은 것은 어느 것인가요?","options":[{"t":"⟨13/3⟩ × ⟨1/3⟩","correct":true},{"t":"⟨13/3⟩ × 3","mis":"M6-1-u1-X06"},{"t":"13 × ⟨1/3⟩","mis":"M6-1-u1-X05"},{"t":"⟨1/3⟩ × ⟨3/13⟩","mis":"M6-1-u1-X07"}],"explanation":["파란 뚜껑 1개는 노란 뚜껑 무게를 3으로 나눈 거예요.","⟨4 1/3⟩ = ⟨13/3⟩이고 ÷ 3은 × ⟨1/3⟩이에요.","그래서 식은 ⟨13/3⟩ × ⟨1/3⟩이에요."],"variant_rule":{"alt":[{"stem":"노란 뚜껑 1개(⟨3 1/2⟩ g)가 파란 뚜껑 2개와 무게가 같아요. 파란 뚜껑 1개의 무게를 구하는 곱셈식으로 알맞은 것은 어느 것인가요?","options":[{"t":"⟨7/2⟩ × ⟨1/2⟩","correct":true},{"t":"⟨7/2⟩ × 2","mis":"M6-1-u1-X06"},{"t":"7 × ⟨1/2⟩","mis":"M6-1-u1-X05"},{"t":"⟨1/2⟩ × ⟨2/7⟩","mis":"M6-1-u1-X07"}],"explanation":["파란 뚜껑 1개는 노란 뚜껑 무게를 2로 나눈 거예요.","⟨3 1/2⟩ = ⟨7/2⟩이고 ÷ 2는 × ⟨1/2⟩이에요.","그래서 식은 ⟨7/2⟩ × ⟨1/2⟩이에요."]},{"stem":"노란 뚜껑 1개(⟨5 1/4⟩ g)가 파란 뚜껑 3개와 무게가 같아요. 파란 뚜껑 1개의 무게를 구하는 곱셈식으로 알맞은 것은 어느 것인가요?","options":[{"t":"⟨21/4⟩ × ⟨1/3⟩","correct":true},{"t":"⟨21/4⟩ × 3","mis":"M6-1-u1-X06"},{"t":"21 × ⟨1/3⟩","mis":"M6-1-u1-X05"},{"t":"⟨1/3⟩ × ⟨4/21⟩","mis":"M6-1-u1-X07"}],"explanation":["파란 뚜껑 1개는 노란 뚜껑 무게를 3으로 나눈 거예요.","⟨5 1/4⟩ = ⟨21/4⟩이고 ÷ 3은 × ⟨1/3⟩이에요.","그래서 식은 ⟨21/4⟩ × ⟨1/3⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L07_basic#4','math',6,1,'u1','L07','g6_1_math_u1_L07_basic','lesson_basic','M6-1-u1-C7',1,'ox','auto','수평인 저울의 양쪽에서 같은 무게를 똑같이 덜어 내도 저울은 수평이에요.',ARRAY['M6-1-u1-X13']::text[],true,'{"seq":4,"concept":"M6-1-u1-C7","difficulty":1,"kind":"ox","stem":"수평인 저울의 양쪽에서 같은 무게를 똑같이 덜어 내도 저울은 수평이에요.","answer":"O","reason_options":[{"t":"양쪽이 똑같이 줄어 균형이 그대로이므로","correct":true},{"t":"한쪽만 무거워지므로","mis":"M6-1-u1-X13"}],"mis":"M6-1-u1-X13","explanation":["수평이면 양쪽 무게가 같아요.","양쪽에서 같은 무게를 빼도 남은 무게는 서로 같아요.","그래서 맞아요."],"variant_rule":{"alt":[{"stem":"수평인 저울의 한쪽에서만 뚜껑을 덜어 내도 저울은 수평이에요.","answer":"X","reason_options":[{"t":"한쪽만 가벼워져 균형이 깨지므로","correct":true},{"t":"뚜껑 무게는 아주 가벼워 상관없으므로","mis":"M6-1-u1-X13"}],"explanation":["한쪽만 덜어 내면 그쪽이 가벼워져요.","균형을 지키려면 양쪽에서 똑같이 덜어 내야 해요.","그래서 틀렸어요."]},{"stem":"노란 뚜껑 1개가 파란 뚜껑 3개와 무게가 같으면, 파란 뚜껑 1개의 무게는 노란 뚜껑 무게 ÷ 3이에요.","answer":"O","reason_options":[{"t":"노란 뚜껑 무게를 파란 3개가 똑같이 나눈 것이므로","correct":true},{"t":"노란 뚜껑 무게 × 3이 파란 1개이므로","mis":"M6-1-u1-X06"}],"explanation":["노란 1개 = 파란 3개예요.","파란 1개는 노란 1개 무게를 3으로 똑같이 나눈 거예요.","그래서 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L07_basic#5','math',6,1,'u1','L07','g6_1_math_u1_L07_basic','lesson_basic','M6-1-u1-C7',2,'mc','auto','파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 5개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨4 1/3⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?',ARRAY['M6-1-u1-X13','M6-1-u1-X06']::text[],true,'{"seq":5,"concept":"M6-1-u1-C7","difficulty":2,"kind":"mc","stem":"파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 5개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨4 1/3⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?","options":[{"t":"⟨1 4/9⟩","correct":true},{"t":"⟨13/15⟩","mis":"M6-1-u1-X13"},{"t":"⟨2 1/6⟩","mis":"M6-1-u1-X13"},{"t":"13","mis":"M6-1-u1-X06"}],"explanation":["양쪽에서 파란 2개씩 덜어 내면 노란 1개 = 파란 3개예요.","⟨4 1/3⟩ = ⟨13/3⟩이에요.","⟨13/3⟩ × ⟨1/3⟩ = ⟨1 4/9⟩ — 파란 뚜껑 1개는 ⟨1 4/9⟩ g이에요."],"variant_rule":{"alt":[{"stem":"파란 뚜껑 1개와 노란 뚜껑 1개의 무게가 파란 뚜껑 4개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨3 3/4⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?","options":[{"t":"⟨1 1/4⟩","correct":true},{"t":"⟨15/16⟩","mis":"M6-1-u1-X13"},{"t":"⟨3 3/4⟩","mis":"M6-1-u1-X13"},{"t":"⟨11 1/4⟩","mis":"M6-1-u1-X06"}],"explanation":["양쪽에서 파란 1개씩 덜어 내면 노란 1개 = 파란 3개예요.","⟨3 3/4⟩ = ⟨15/4⟩예요.","⟨15/4⟩ × ⟨1/3⟩ = ⟨1 1/4⟩ — 파란 뚜껑 1개는 ⟨1 1/4⟩ g이에요."]},{"stem":"파란 뚜껑 3개와 노란 뚜껑 1개의 무게가 파란 뚜껑 5개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨2 1/3⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?","options":[{"t":"⟨1 1/6⟩","correct":true},{"t":"⟨7/15⟩","mis":"M6-1-u1-X13"},{"t":"⟨7/9⟩","mis":"M6-1-u1-X13"},{"t":"⟨4 2/3⟩","mis":"M6-1-u1-X06"}],"explanation":["양쪽에서 파란 3개씩 덜어 내면 노란 1개 = 파란 2개예요.","⟨2 1/3⟩ = ⟨7/3⟩이에요.","⟨7/3⟩ × ⟨1/2⟩ = ⟨1 1/6⟩ — 파란 뚜껑 1개는 ⟨1 1/6⟩ g이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L07_basic#6','math',6,1,'u1','L07','g6_1_math_u1_L07_basic','lesson_basic','M6-1-u1-C7',2,'mc','auto','저울 문제에서 파란 뚜껑 1개의 무게를 구할 때 가장 먼저 할 일은 무엇인가요?',ARRAY['M6-1-u1-X13','M6-1-u1-X06','M6-1-u1-X10']::text[],true,'{"seq":6,"concept":"M6-1-u1-C7","difficulty":2,"kind":"mc","stem":"저울 문제에서 파란 뚜껑 1개의 무게를 구할 때 가장 먼저 할 일은 무엇인가요?","options":[{"t":"양쪽에서 같은 뚜껑을 덜어 내 노란 뚜껑과 파란 뚜껑의 관계를 찾는다","correct":true},{"t":"노란 뚜껑 무게를 파란 뚜껑 전체 수로 바로 나눈다","mis":"M6-1-u1-X13"},{"t":"노란 뚜껑 무게에 파란 뚜껑 수를 곱한다","mis":"M6-1-u1-X06"},{"t":"대분수의 자연수 부분만 나눈다","mis":"M6-1-u1-X10"}],"explanation":["저울에서 양쪽의 같은 것을 덜어 내면 관계가 보여요.","노란 1개 = 파란 □개이면 파란 1개 = 노란 무게 ÷ □예요.","그래서 답은 「양쪽에서 같은 뚜껑을 덜어 내 노란 뚜껑과 파란 뚜껑의 관계를 찾는다」예요."],"variant_rule":{"alt":[{"stem":"저울 문제를 푸는 순서로 알맞은 것은 어느 것인가요?","options":[{"t":"관계 찾기 → 대분수를 가분수로 → 단위분수 곱하기","correct":true},{"t":"단위분수 곱하기 → 관계 찾기 → 가분수로","mis":"M6-1-u1-X13"},{"t":"가분수로 → 뚜껑 수 곱하기 → 관계 찾기","mis":"M6-1-u1-X06"},{"t":"관계 찾기 → 자연수 부분만 나누기","mis":"M6-1-u1-X10"}],"explanation":["저울에서 양쪽의 같은 것을 덜어 내면 관계가 보여요.","노란 1개 = 파란 □개이면 파란 1개 = 노란 무게 ÷ □예요.","그래서 답은 「관계 찾기 → 대분수를 가분수로 → 단위분수 곱하기」예요."]},{"stem":"노란 뚜껑 1개가 파란 뚜껑 몇 개와 같은지 알았어요. 그다음 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"노란 뚜껑 무게를 그 개수로 나눈다","correct":true},{"t":"노란 뚜껑 무게에 그 개수를 곱한다","mis":"M6-1-u1-X06"},{"t":"노란 뚜껑 무게를 저울 오른쪽 뚜껑 수로 나눈다","mis":"M6-1-u1-X13"},{"t":"노란 뚜껑 무게에서 그 개수를 뺀다","mis":"M6-1-u1-X09"}],"explanation":["저울에서 양쪽의 같은 것을 덜어 내면 관계가 보여요.","노란 1개 = 파란 □개이면 파란 1개 = 노란 무게 ÷ □예요.","그래서 답은 「노란 뚜껑 무게를 그 개수로 나눈다」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L07_basic#7','math',6,1,'u1','L07','g6_1_math_u1_L07_basic','lesson_basic','M6-1-u1-C7',2,'sa','auto','조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨3 1/2⟩ g이고 파란 뚜껑 2개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u1-C7","difficulty":2,"kind":"sa","stem":"조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨3 1/2⟩ g이고 파란 뚜껑 2개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["파란 뚜껑 1개 = ⟨3 1/2⟩ ÷ 2예요.","⟨7/2⟩ ÷ 2 = ⟨7/2⟩ × ⟨1/2⟩ = ⟨7/4⟩이에요.","분모와 분자의 합은 4 + 7 = 11이에요."],"mis":"M6-1-u1-X15","variant_rule":{"alt":[{"stem":"조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨2 2/5⟩ g이고 파란 뚜껑 3개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["파란 뚜껑 1개 = ⟨2 2/5⟩ ÷ 3이에요.","⟨12/5⟩ ÷ 3 = ⟨12/5⟩ × ⟨1/3⟩ = ⟨4/5⟩예요.","분모와 분자의 합은 5 + 4 = 9예요."]},{"stem":"조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨4 1/2⟩ g이고 파란 뚜껑 5개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["파란 뚜껑 1개 = ⟨4 1/2⟩ ÷ 5예요.","⟨9/2⟩ ÷ 5 = ⟨9/2⟩ × ⟨1/5⟩ = ⟨9/10⟩예요.","분모와 분자의 합은 10 + 9 = 19예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L07_basic#8','math',6,1,'u1','L07','g6_1_math_u1_L07_basic','lesson_basic','M6-1-u1-C7',2,'mc','auto','파란 뚜껑 1개의 무게가 ⟨1 4/9⟩ g이에요. 파란 뚜껑 3개의 무게는 몇 g인가요?',ARRAY['M6-1-u1-X10','M6-1-u1-X14','M6-1-u1-X12']::text[],true,'{"seq":8,"concept":"M6-1-u1-C7","difficulty":2,"kind":"mc","stem":"파란 뚜껑 1개의 무게가 ⟨1 4/9⟩ g이에요. 파란 뚜껑 3개의 무게는 몇 g인가요?","options":[{"t":"⟨4 1/3⟩","correct":true},{"t":"⟨3 4/9⟩","mis":"M6-1-u1-X10"},{"t":"⟨13/27⟩","mis":"M6-1-u1-X14"},{"t":"⟨4 4/9⟩","mis":"M6-1-u1-X12"}],"explanation":["⟨1 4/9⟩ = ⟨13/9⟩이에요.","⟨13/9⟩ × 3 = ⟨13/3⟩이에요.","⟨13/3⟩ = ⟨4 1/3⟩ — 파란 뚜껑 3개는 ⟨4 1/3⟩ g이에요."],"variant_rule":{"alt":[{"stem":"파란 뚜껑 1개의 무게가 ⟨1 2/5⟩ g이에요. 파란 뚜껑 2개의 무게는 몇 g인가요?","options":[{"t":"⟨2 4/5⟩","correct":true},{"t":"⟨2 2/5⟩","mis":"M6-1-u1-X10"},{"t":"⟨7/10⟩","mis":"M6-1-u1-X14"},{"t":"⟨1 4/5⟩","mis":"M6-1-u1-X10"}],"explanation":["⟨1 2/5⟩ = ⟨7/5⟩이에요.","⟨7/5⟩ × 2 = ⟨14/5⟩예요.","⟨14/5⟩ = ⟨2 4/5⟩ — 파란 뚜껑 2개는 ⟨2 4/5⟩ g이에요."]},{"stem":"파란 뚜껑 1개의 무게가 ⟨2 1/3⟩ g이에요. 파란 뚜껑 4개의 무게는 몇 g인가요?","options":[{"t":"⟨9 1/3⟩","correct":true},{"t":"⟨8 1/3⟩","mis":"M6-1-u1-X10"},{"t":"⟨7/12⟩","mis":"M6-1-u1-X14"},{"t":"⟨9 2/3⟩","mis":"M6-1-u1-X12"}],"explanation":["⟨2 1/3⟩ = ⟨7/3⟩이에요.","⟨7/3⟩ × 4 = ⟨28/3⟩이에요.","⟨28/3⟩ = ⟨9 1/3⟩ — 파란 뚜껑 4개는 ⟨9 1/3⟩ g이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L07_basic#9','math',6,1,'u1','L07','g6_1_math_u1_L07_basic','lesson_basic','M6-1-u1-C7',2,'mc','auto','모은 페트병 뚜껑 ⟨6 3/4⟩ g을 5묶음으로 똑같이 나누면 한 묶음은 몇 g인가요?',ARRAY['M6-1-u1-X10','M6-1-u1-X06']::text[],true,'{"seq":9,"concept":"M6-1-u1-C7","difficulty":2,"kind":"mc","stem":"모은 페트병 뚜껑 ⟨6 3/4⟩ g을 5묶음으로 똑같이 나누면 한 묶음은 몇 g인가요?","options":[{"t":"⟨1 7/20⟩","correct":true},{"t":"⟨6 3/20⟩","mis":"M6-1-u1-X10"},{"t":"⟨1 19/20⟩","mis":"M6-1-u1-X10"},{"t":"⟨33 3/4⟩","mis":"M6-1-u1-X06"}],"explanation":["⟨6 3/4⟩ = ⟨27/4⟩이에요.","⟨27/4⟩ ÷ 5 = ⟨27/4⟩ × ⟨1/5⟩이에요.","⟨27/4⟩ × ⟨1/5⟩ = ⟨1 7/20⟩ — 한 묶음은 ⟨1 7/20⟩ g이에요."],"variant_rule":{"alt":[{"stem":"모은 페트병 뚜껑 ⟨4 2/3⟩ g을 2묶음으로 똑같이 나누면 한 묶음은 몇 g인가요?","options":[{"t":"⟨2 1/3⟩","correct":true},{"t":"⟨4 1/3⟩","mis":"M6-1-u1-X10"},{"t":"⟨2 2/3⟩","mis":"M6-1-u1-X10"},{"t":"⟨9 1/3⟩","mis":"M6-1-u1-X06"}],"explanation":["⟨4 2/3⟩ = ⟨14/3⟩예요.","⟨14/3⟩ ÷ 2 = ⟨14/3⟩ × ⟨1/2⟩이에요.","⟨14/3⟩ × ⟨1/2⟩ = ⟨2 1/3⟩ — 한 묶음은 ⟨2 1/3⟩ g이에요."]},{"stem":"모은 페트병 뚜껑 ⟨5 1/2⟩ g을 3묶음으로 똑같이 나누면 한 묶음은 몇 g인가요?","options":[{"t":"⟨1 5/6⟩","correct":true},{"t":"⟨5 1/6⟩","mis":"M6-1-u1-X10"},{"t":"⟨2 1/6⟩","mis":"M6-1-u1-X10"},{"t":"⟨16 1/2⟩","mis":"M6-1-u1-X06"}],"explanation":["⟨5 1/2⟩ = ⟨11/2⟩이에요.","⟨11/2⟩ ÷ 3 = ⟨11/2⟩ × ⟨1/3⟩이에요.","⟨11/2⟩ × ⟨1/3⟩ = ⟨1 5/6⟩ — 한 묶음은 ⟨1 5/6⟩ g이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L07_basic#10','math',6,1,'u1','L07','g6_1_math_u1_L07_basic','lesson_basic','M6-1-u1-C7',3,'sa','auto','조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨5 1/3⟩ g이고 파란 뚜껑 4개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M6-1-u1-C7","difficulty":3,"kind":"sa","stem":"조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨5 1/3⟩ g이고 파란 뚜껑 4개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["파란 뚜껑 1개 = ⟨5 1/3⟩ ÷ 4예요.","⟨16/3⟩ ÷ 4 = ⟨16/3⟩ × ⟨1/4⟩ = ⟨4/3⟩예요.","분모와 분자의 합은 3 + 4 = 7이에요."],"mis":"M6-1-u1-X15","variant_rule":{"alt":[{"stem":"조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨4 2/3⟩ g이고 파란 뚜껑 7개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["파란 뚜껑 1개 = ⟨4 2/3⟩ ÷ 7이에요.","⟨14/3⟩ ÷ 7 = ⟨14/3⟩ × ⟨1/7⟩ = ⟨2/3⟩예요.","분모와 분자의 합은 3 + 2 = 5예요."]},{"stem":"조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨2 4/7⟩ g이고 파란 뚜껑 6개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["파란 뚜껑 1개 = ⟨2 4/7⟩ ÷ 6이에요.","⟨18/7⟩ ÷ 6 = ⟨18/7⟩ × ⟨1/6⟩ = ⟨3/7⟩이에요.","분모와 분자의 합은 7 + 3 = 10이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L07_challenge#1','math',6,1,'u1','L07','g6_1_math_u1_L07_challenge','lesson_challenge','M6-1-u1-C7',2,'mc','auto','저울에서 파란 뚜껑 3개와 노란 뚜껑 1개의 무게가 파란 뚜껑 8개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?',ARRAY['M6-1-u1-X13']::text[],true,'{"seq":1,"concept":"M6-1-u1-C7","difficulty":2,"kind":"mc","stem":"저울에서 파란 뚜껑 3개와 노란 뚜껑 1개의 무게가 파란 뚜껑 8개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?","options":[{"t":"5개","correct":true},{"t":"3개","mis":"M6-1-u1-X13"},{"t":"8개","mis":"M6-1-u1-X13"},{"t":"11개","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 뚜껑 3개씩을 덜어 내도 저울은 수평이에요.","왼쪽엔 노란 뚜껑 1개, 오른쪽엔 파란 뚜껑 8 − 3 = 5개가 남아요.","그래서 노란 뚜껑 1개는 파란 뚜껑 5개와 같아요."],"variant_rule":{"alt":[{"stem":"저울에서 파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 6개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?","options":[{"t":"4개","correct":true},{"t":"2개","mis":"M6-1-u1-X13"},{"t":"6개","mis":"M6-1-u1-X13"},{"t":"8개","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 뚜껑 2개씩을 덜어 내도 저울은 수평이에요.","왼쪽엔 노란 뚜껑 1개, 오른쪽엔 파란 뚜껑 6 − 2 = 4개가 남아요.","그래서 노란 뚜껑 1개는 파란 뚜껑 4개와 같아요."]},{"stem":"저울에서 파란 뚜껑 4개와 노란 뚜껑 1개의 무게가 파란 뚜껑 9개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?","options":[{"t":"5개","correct":true},{"t":"4개","mis":"M6-1-u1-X13"},{"t":"9개","mis":"M6-1-u1-X13"},{"t":"13개","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 뚜껑 4개씩을 덜어 내도 저울은 수평이에요.","왼쪽엔 노란 뚜껑 1개, 오른쪽엔 파란 뚜껑 9 − 4 = 5개가 남아요.","그래서 노란 뚜껑 1개는 파란 뚜껑 5개와 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L07_challenge#2','math',6,1,'u1','L07','g6_1_math_u1_L07_challenge','lesson_challenge','M6-1-u1-C7',2,'mc','auto','파란 뚜껑 1개와 노란 뚜껑 1개의 무게가 파란 뚜껑 3개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨3 1/2⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?',ARRAY['M6-1-u1-X13','M6-1-u1-X06']::text[],true,'{"seq":2,"concept":"M6-1-u1-C7","difficulty":2,"kind":"mc","stem":"파란 뚜껑 1개와 노란 뚜껑 1개의 무게가 파란 뚜껑 3개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨3 1/2⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?","options":[{"t":"⟨1 3/4⟩","correct":true},{"t":"⟨1 1/6⟩","mis":"M6-1-u1-X13"},{"t":"⟨3 1/2⟩","mis":"M6-1-u1-X13"},{"t":"7","mis":"M6-1-u1-X06"}],"explanation":["양쪽에서 파란 1개씩 덜어 내면 노란 1개 = 파란 2개예요.","⟨3 1/2⟩ = ⟨7/2⟩이에요.","⟨7/2⟩ × ⟨1/2⟩ = ⟨1 3/4⟩ — 파란 뚜껑 1개는 ⟨1 3/4⟩ g이에요."],"variant_rule":{"alt":[{"stem":"파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 6개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨5 1/3⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?","options":[{"t":"⟨1 1/3⟩","correct":true},{"t":"⟨8/9⟩","mis":"M6-1-u1-X13"},{"t":"⟨2 2/3⟩","mis":"M6-1-u1-X13"},{"t":"⟨21 1/3⟩","mis":"M6-1-u1-X06"}],"explanation":["양쪽에서 파란 2개씩 덜어 내면 노란 1개 = 파란 4개예요.","⟨5 1/3⟩ = ⟨16/3⟩이에요.","⟨16/3⟩ × ⟨1/4⟩ = ⟨1 1/3⟩ — 파란 뚜껑 1개는 ⟨1 1/3⟩ g이에요."]},{"stem":"파란 뚜껑 3개와 노란 뚜껑 1개의 무게가 파란 뚜껑 8개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨6 1/4⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?","options":[{"t":"⟨1 1/4⟩","correct":true},{"t":"⟨25/32⟩","mis":"M6-1-u1-X13"},{"t":"⟨2 1/12⟩","mis":"M6-1-u1-X13"},{"t":"⟨31 1/4⟩","mis":"M6-1-u1-X06"}],"explanation":["양쪽에서 파란 3개씩 덜어 내면 노란 1개 = 파란 5개예요.","⟨6 1/4⟩ = ⟨25/4⟩예요.","⟨25/4⟩ × ⟨1/5⟩ = ⟨1 1/4⟩ — 파란 뚜껑 1개는 ⟨1 1/4⟩ g이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L07_challenge#3','math',6,1,'u1','L07','g6_1_math_u1_L07_challenge','lesson_challenge','M6-1-u1-C7',3,'error','auto','파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 5개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 ⟨4 1/3⟩ g이에요. 친구들의 풀이 가운데 잘못된 것은 누구의 것인가요?',ARRAY['M6-1-u1-X13','M6-1-u1-X15']::text[],true,'{"seq":3,"concept":"M6-1-u1-C7","difficulty":3,"kind":"error","stem":"파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 5개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 ⟨4 1/3⟩ g이에요. 친구들의 풀이 가운데 잘못된 것은 누구의 것인가요?","options":[{"t":"수아 — 「파란 뚜껑이 5개니까 ⟨4 1/3⟩ ÷ 5를 계산해.」","correct":true,"mis_target":"M6-1-u1-X13"},{"t":"도윤 — 「양쪽에서 파란 2개씩 덜어 내면 노란 1개 = 파란 3개야.」","mis":"M6-1-u1-X15"},{"t":"하린 — 「파란 1개는 ⟨13/3⟩ × ⟨1/3⟩이야.」","mis":"M6-1-u1-X15"}],"explanation":["양쪽에서 파란 2개씩 덜어 내야 해요.","노란 1개 = 파란 3개이니 ⟨4 1/3⟩ ÷ 3이에요.","수아는 덜어 내지 않고 5로 나누었어요."],"variant_rule":{"alt":[{"stem":"파란 뚜껑 1개와 노란 뚜껑 1개의 무게가 파란 뚜껑 4개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 ⟨3 3/4⟩ g이에요. 친구들의 풀이 가운데 잘못된 것은 누구의 것인가요?","options":[{"t":"민준 — 「파란 뚜껑이 4개니까 ⟨3 3/4⟩ ÷ 4를 계산해.」","correct":true,"mis_target":"M6-1-u1-X13"},{"t":"서연 — 「양쪽에서 파란 1개씩 덜어 내면 노란 1개 = 파란 3개야.」","mis":"M6-1-u1-X15"},{"t":"지호 — 「파란 1개는 ⟨15/4⟩ × ⟨1/3⟩이야.」","mis":"M6-1-u1-X15"}],"explanation":["양쪽에서 파란 1개씩 덜어 내야 해요.","노란 1개 = 파란 3개이니 ⟨3 3/4⟩ ÷ 3이에요.","민준은 덜어 내지 않고 4로 나누었어요."]},{"stem":"파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 6개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 ⟨5 1/3⟩ g이에요. 친구들의 풀이 가운데 잘못된 것은 누구의 것인가요?","options":[{"t":"가온 — 「파란 뚜껑이 6개니까 ⟨5 1/3⟩ ÷ 6을 계산해.」","correct":true,"mis_target":"M6-1-u1-X13"},{"t":"나린 — 「양쪽에서 파란 2개씩 덜어 내면 노란 1개 = 파란 4개야.」","mis":"M6-1-u1-X15"},{"t":"유진 — 「파란 1개는 ⟨16/3⟩ × ⟨1/4⟩이야.」","mis":"M6-1-u1-X15"}],"explanation":["양쪽에서 파란 2개씩 덜어 내야 해요.","노란 1개 = 파란 4개이니 ⟨5 1/3⟩ ÷ 4예요.","가온은 덜어 내지 않고 6으로 나누었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L07_challenge#4','math',6,1,'u1','L07','g6_1_math_u1_L07_challenge','lesson_challenge','M6-1-u1-C7',3,'sa','auto','조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨3 3/4⟩ g이고 파란 뚜껑 5개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u1-C7","difficulty":3,"kind":"sa","stem":"조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨3 3/4⟩ g이고 파란 뚜껑 5개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["파란 뚜껑 1개 = ⟨3 3/4⟩ ÷ 5예요.","⟨15/4⟩ ÷ 5 = ⟨15/4⟩ × ⟨1/5⟩ = ⟨3/4⟩이에요.","분모와 분자의 합은 4 + 3 = 7이에요."],"mis":"M6-1-u1-X15","variant_rule":{"alt":[{"stem":"조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨2 1/3⟩ g이고 파란 뚜껑 7개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["파란 뚜껑 1개 = ⟨2 1/3⟩ ÷ 7이에요.","⟨7/3⟩ ÷ 7 = ⟨7/3⟩ × ⟨1/7⟩ = ⟨1/3⟩이에요.","분모와 분자의 합은 3 + 1 = 4예요."]},{"stem":"조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨5 2/5⟩ g이고 파란 뚜껑 9개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["파란 뚜껑 1개 = ⟨5 2/5⟩ ÷ 9예요.","⟨27/5⟩ ÷ 9 = ⟨27/5⟩ × ⟨1/9⟩ = ⟨3/5⟩이에요.","분모와 분자의 합은 5 + 3 = 8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L07_challenge#5','math',6,1,'u1','L07','g6_1_math_u1_L07_challenge','lesson_challenge','M6-1-u1-C7',3,'mc','auto','파란 뚜껑 1개의 무게가 ⟨2 3/4⟩ g이에요. 파란 뚜껑 3개의 무게는 몇 g인가요?',ARRAY['M6-1-u1-X10','M6-1-u1-X14','M6-1-u1-X12']::text[],true,'{"seq":5,"concept":"M6-1-u1-C7","difficulty":3,"kind":"mc","stem":"파란 뚜껑 1개의 무게가 ⟨2 3/4⟩ g이에요. 파란 뚜껑 3개의 무게는 몇 g인가요?","options":[{"t":"⟨8 1/4⟩","correct":true},{"t":"⟨6 3/4⟩","mis":"M6-1-u1-X10"},{"t":"⟨11/12⟩","mis":"M6-1-u1-X14"},{"t":"⟨8 1/2⟩","mis":"M6-1-u1-X12"}],"explanation":["⟨2 3/4⟩ = ⟨11/4⟩이에요.","⟨11/4⟩ × 3 = ⟨33/4⟩이에요.","⟨33/4⟩ = ⟨8 1/4⟩ — 파란 뚜껑 3개는 ⟨8 1/4⟩ g이에요."],"variant_rule":{"alt":[{"stem":"파란 뚜껑 1개의 무게가 ⟨1 5/6⟩ g이에요. 파란 뚜껑 4개의 무게는 몇 g인가요?","options":[{"t":"⟨7 1/3⟩","correct":true},{"t":"⟨4 5/6⟩","mis":"M6-1-u1-X10"},{"t":"⟨11/24⟩","mis":"M6-1-u1-X14"},{"t":"⟨7 1/2⟩","mis":"M6-1-u1-X12"}],"explanation":["⟨1 5/6⟩ = ⟨11/6⟩이에요.","⟨11/6⟩ × 4 = ⟨22/3⟩예요.","⟨22/3⟩ = ⟨7 1/3⟩ — 파란 뚜껑 4개는 ⟨7 1/3⟩ g이에요."]},{"stem":"파란 뚜껑 1개의 무게가 ⟨3 2/7⟩ g이에요. 파란 뚜껑 2개의 무게는 몇 g인가요?","options":[{"t":"⟨6 4/7⟩","correct":true},{"t":"⟨6 2/7⟩","mis":"M6-1-u1-X10"},{"t":"⟨1 9/14⟩","mis":"M6-1-u1-X14"},{"t":"⟨3 4/7⟩","mis":"M6-1-u1-X10"}],"explanation":["⟨3 2/7⟩ = ⟨23/7⟩이에요.","⟨23/7⟩ × 2 = ⟨46/7⟩이에요.","⟨46/7⟩ = ⟨6 4/7⟩ — 파란 뚜껑 2개는 ⟨6 4/7⟩ g이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L07_challenge#6','math',6,1,'u1','L07','g6_1_math_u1_L07_challenge','lesson_challenge','M6-1-u1-C7',3,'mc','auto','모은 페트병 뚜껑 ⟨7 1/2⟩ g을 6묶음으로 똑같이 나누면 한 묶음은 몇 g인가요?',ARRAY['M6-1-u1-X10','M6-1-u1-X06']::text[],true,'{"seq":6,"concept":"M6-1-u1-C7","difficulty":3,"kind":"mc","stem":"모은 페트병 뚜껑 ⟨7 1/2⟩ g을 6묶음으로 똑같이 나누면 한 묶음은 몇 g인가요?","options":[{"t":"⟨1 1/4⟩","correct":true},{"t":"⟨7 1/12⟩","mis":"M6-1-u1-X10"},{"t":"⟨1 2/3⟩","mis":"M6-1-u1-X10"},{"t":"45","mis":"M6-1-u1-X06"}],"explanation":["⟨7 1/2⟩ = ⟨15/2⟩예요.","⟨15/2⟩ ÷ 6 = ⟨15/2⟩ × ⟨1/6⟩이에요.","⟨15/2⟩ × ⟨1/6⟩ = ⟨1 1/4⟩ — 한 묶음은 ⟨1 1/4⟩ g이에요."],"variant_rule":{"alt":[{"stem":"모은 페트병 뚜껑 ⟨8 2/3⟩ g을 4묶음으로 똑같이 나누면 한 묶음은 몇 g인가요?","options":[{"t":"⟨2 1/6⟩","correct":true},{"t":"⟨8 1/6⟩","mis":"M6-1-u1-X10"},{"t":"⟨2 2/3⟩","mis":"M6-1-u1-X10"},{"t":"⟨34 2/3⟩","mis":"M6-1-u1-X06"}],"explanation":["⟨8 2/3⟩ = ⟨26/3⟩이에요.","⟨26/3⟩ ÷ 4 = ⟨26/3⟩ × ⟨1/4⟩이에요.","⟨26/3⟩ × ⟨1/4⟩ = ⟨2 1/6⟩ — 한 묶음은 ⟨2 1/6⟩ g이에요."]},{"stem":"모은 페트병 뚜껑 ⟨5 3/5⟩ g을 7묶음으로 똑같이 나누면 한 묶음은 몇 g인가요?","options":[{"t":"⟨4/5⟩","correct":true},{"t":"⟨5 3/35⟩","mis":"M6-1-u1-X10"},{"t":"⟨1 11/35⟩","mis":"M6-1-u1-X10"},{"t":"⟨39 1/5⟩","mis":"M6-1-u1-X06"}],"explanation":["⟨5 3/5⟩ = ⟨28/5⟩이에요.","⟨28/5⟩ ÷ 7 = ⟨28/5⟩ × ⟨1/7⟩이에요.","⟨28/5⟩ × ⟨1/7⟩ = ⟨4/5⟩ — 한 묶음은 ⟨4/5⟩ g이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L07_challenge#7','math',6,1,'u1','L07','g6_1_math_u1_L07_challenge','lesson_challenge','M6-1-u1-C7',3,'ox','auto','파란 뚜껑 2개와 노란 뚜껑 1개가 파란 뚜껑 5개와 무게가 같으면, 노란 뚜껑 1개는 파란 뚜껑 5개와 무게가 같아요.',ARRAY['M6-1-u1-X13']::text[],true,'{"seq":7,"concept":"M6-1-u1-C7","difficulty":3,"kind":"ox","stem":"파란 뚜껑 2개와 노란 뚜껑 1개가 파란 뚜껑 5개와 무게가 같으면, 노란 뚜껑 1개는 파란 뚜껑 5개와 무게가 같아요.","answer":"X","reason_options":[{"t":"양쪽에서 파란 2개씩 덜어 내면 노란 1개 = 파란 3개이므로","correct":true},{"t":"오른쪽 파란 뚜껑의 수가 5개이므로","mis":"M6-1-u1-X13"}],"mis":"M6-1-u1-X13","explanation":["양쪽에서 파란 뚜껑 2개씩 덜어 내요.","노란 1개, 파란 5 − 2 = 3개가 남아요.","노란 뚜껑 1개는 파란 뚜껑 3개와 같아요."],"variant_rule":{"alt":[{"stem":"노란 뚜껑 1개가 ⟨4 1/3⟩ g이고 파란 뚜껑 3개와 같으면 파란 뚜껑 1개는 ⟨1 4/9⟩ g이에요.","answer":"O","reason_options":[{"t":"⟨13/3⟩ × ⟨1/3⟩ = ⟨13/9⟩ = ⟨1 4/9⟩이므로","correct":true},{"t":"4를 3으로 나누면 되므로","mis":"M6-1-u1-X10"}],"explanation":["⟨4 1/3⟩ = ⟨13/3⟩이에요.","⟨13/3⟩ × ⟨1/3⟩ = ⟨13/9⟩이에요.","⟨13/9⟩ = ⟨1 4/9⟩ — 맞아요."]},{"stem":"파란 뚜껑 1개가 ⟨1 3/4⟩ g이면 파란 뚜껑 2개는 ⟨2 3/4⟩ g이에요.","answer":"X","reason_options":[{"t":"⟨7/4⟩ × 2 = ⟨14/4⟩ = ⟨3 1/2⟩이므로","correct":true},{"t":"자연수 부분만 2배 하면 되므로","mis":"M6-1-u1-X10"}],"explanation":["⟨1 3/4⟩ = ⟨7/4⟩이에요.","⟨7/4⟩ × 2 = ⟨14/4⟩예요.","⟨14/4⟩ = ⟨3 1/2⟩ — 분수 부분도 2배 해야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L07_challenge#8','math',6,1,'u1','L07','g6_1_math_u1_L07_challenge','lesson_challenge','M6-1-u1-C7',4,'mc','auto','파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 6개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨2 2/3⟩ g일 때, 파란 뚜껑 5개의 무게는 몇 g인가요?',ARRAY['M6-1-u1-X13','M6-1-u1-X15']::text[],true,'{"seq":8,"concept":"M6-1-u1-C7","difficulty":4,"kind":"mc","stem":"파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 6개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨2 2/3⟩ g일 때, 파란 뚜껑 5개의 무게는 몇 g인가요?","options":[{"t":"⟨3 1/3⟩","correct":true},{"t":"⟨2 2/9⟩","mis":"M6-1-u1-X13"},{"t":"⟨2/3⟩","mis":"M6-1-u1-X15"},{"t":"⟨13 1/3⟩","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 2개씩 덜어 내면 노란 1개 = 파란 4개예요.","파란 1개는 ⟨8/3⟩ × ⟨1/4⟩ = ⟨2/3⟩ g이에요.","파란 5개는 ⟨2/3⟩ × 5 = ⟨3 1/3⟩ g이에요."],"variant_rule":{"alt":[{"stem":"파란 뚜껑 1개와 노란 뚜껑 1개의 무게가 파란 뚜껑 4개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨4 1/2⟩ g일 때, 파란 뚜껑 2개의 무게는 몇 g인가요?","options":[{"t":"3","correct":true},{"t":"⟨2 1/4⟩","mis":"M6-1-u1-X13"},{"t":"⟨1 1/2⟩","mis":"M6-1-u1-X15"},{"t":"9","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 1개씩 덜어 내면 노란 1개 = 파란 3개예요.","파란 1개는 ⟨9/2⟩ × ⟨1/3⟩ = ⟨1 1/2⟩ g이에요.","파란 2개는 ⟨1 1/2⟩ × 2 = 3 g이에요."]},{"stem":"파란 뚜껑 3개와 노란 뚜껑 1개의 무게가 파란 뚜껑 7개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨3 1/5⟩ g일 때, 파란 뚜껑 3개의 무게는 몇 g인가요?","options":[{"t":"⟨2 2/5⟩","correct":true},{"t":"⟨1 13/35⟩","mis":"M6-1-u1-X13"},{"t":"⟨4/5⟩","mis":"M6-1-u1-X15"},{"t":"⟨9 3/5⟩","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 3개씩 덜어 내면 노란 1개 = 파란 4개예요.","파란 1개는 ⟨16/5⟩ × ⟨1/4⟩ = ⟨4/5⟩ g이에요.","파란 3개는 ⟨4/5⟩ × 3 = ⟨2 2/5⟩ g이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L07_challenge#9','math',6,1,'u1','L07','g6_1_math_u1_L07_challenge','lesson_challenge','M6-1-u1-C7',4,'mc','auto','빨간 뚜껑 1개는 노란 뚜껑 2개와, 노란 뚜껑 1개는 파란 뚜껑 3개와 무게가 같아요. 빨간 뚜껑 1개가 ⟨4 2/3⟩ g이면 파란 뚜껑 1개는 몇 g인가요?',ARRAY['M6-1-u1-X15','M6-1-u1-X09']::text[],true,'{"seq":9,"concept":"M6-1-u1-C7","difficulty":4,"kind":"mc","stem":"빨간 뚜껑 1개는 노란 뚜껑 2개와, 노란 뚜껑 1개는 파란 뚜껑 3개와 무게가 같아요. 빨간 뚜껑 1개가 ⟨4 2/3⟩ g이면 파란 뚜껑 1개는 몇 g인가요?","options":[{"t":"⟨7/9⟩","correct":true},{"t":"⟨2 1/3⟩","mis":"M6-1-u1-X15"},{"t":"⟨1 5/9⟩","mis":"M6-1-u1-X15"},{"t":"⟨14/15⟩","mis":"M6-1-u1-X09"}],"explanation":["빨간 1개 = 노란 2개 = 파란 2 × 3 = 6개예요.","⟨4 2/3⟩ = ⟨14/3⟩예요.","⟨14/3⟩ × ⟨1/6⟩ = ⟨7/9⟩ — 파란 뚜껑 1개는 ⟨7/9⟩ g이에요."],"variant_rule":{"alt":[{"stem":"빨간 뚜껑 1개는 노란 뚜껑 3개와, 노란 뚜껑 1개는 파란 뚜껑 2개와 무게가 같아요. 빨간 뚜껑 1개가 ⟨5 1/4⟩ g이면 파란 뚜껑 1개는 몇 g인가요?","options":[{"t":"⟨7/8⟩","correct":true},{"t":"⟨1 3/4⟩","mis":"M6-1-u1-X15"},{"t":"⟨2 5/8⟩","mis":"M6-1-u1-X15"},{"t":"⟨1 1/20⟩","mis":"M6-1-u1-X09"}],"explanation":["빨간 1개 = 노란 3개 = 파란 3 × 2 = 6개예요.","⟨5 1/4⟩ = ⟨21/4⟩이에요.","⟨21/4⟩ × ⟨1/6⟩ = ⟨7/8⟩ — 파란 뚜껑 1개는 ⟨7/8⟩ g이에요."]},{"stem":"빨간 뚜껑 1개는 노란 뚜껑 2개와, 노란 뚜껑 1개는 파란 뚜껑 4개와 무게가 같아요. 빨간 뚜껑 1개가 ⟨6 2/5⟩ g이면 파란 뚜껑 1개는 몇 g인가요?","options":[{"t":"⟨4/5⟩","correct":true},{"t":"⟨3 1/5⟩","mis":"M6-1-u1-X15"},{"t":"⟨1 3/5⟩","mis":"M6-1-u1-X15"},{"t":"⟨1 1/15⟩","mis":"M6-1-u1-X09"}],"explanation":["빨간 1개 = 노란 2개 = 파란 2 × 4 = 8개예요.","⟨6 2/5⟩ = ⟨32/5⟩예요.","⟨32/5⟩ × ⟨1/8⟩ = ⟨4/5⟩ — 파란 뚜껑 1개는 ⟨4/5⟩ g이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_L07_challenge#10','math',6,1,'u1','L07','g6_1_math_u1_L07_challenge','lesson_challenge','M6-1-u1-C7',4,'essay','teacher','저울에서 파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 5개의 무게와 같아요. 노란 뚜껑 1개가 ⟨4 1/3⟩ g일 때 파란 뚜껑 1개의 무게를 구하는 과정을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u1-C7","difficulty":4,"kind":"essay","stem":"저울에서 파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 5개의 무게와 같아요. 노란 뚜껑 1개가 ⟨4 1/3⟩ g일 때 파란 뚜껑 1개의 무게를 구하는 과정을 쓰세요.","answer_guide":{"answer":"예: 저울 양쪽에서 파란 뚜껑 2개씩을 덜어 내도 수평이므로 노란 뚜껑 1개는 파란 뚜껑 3개와 무게가 같다. 그래서 파란 뚜껑 1개는 ⟨4 1/3⟩ ÷ 3이다. ⟨4 1/3⟩ = ⟨13/3⟩이므로 ⟨13/3⟩ × ⟨1/3⟩ = ⟨13/9⟩ = ⟨1 4/9⟩ g이다.","scoring_points":["양쪽에서 같은 것을 덜어 내 노란 1개 = 파란 3개를 찾았는가","⟨4 1/3⟩ ÷ 3을 세우고 가분수로 고쳤는가","⟨1 4/9⟩ g을 구했는가"]},"explanation":["양쪽에서 파란 2개씩 덜어 내면 노란 1개 = 파란 3개예요.","⟨4 1/3⟩ = ⟨13/3⟩이에요.","⟨13/3⟩ × ⟨1/3⟩ = ⟨1 4/9⟩ g이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#1','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C2',1,'mc','auto','시루떡 3개를 4명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 시루떡은 몇 개인지 분수로 나타내면 얼마인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X09']::text[],true,'{"seq":1,"concept":"M6-1-u1-C2","difficulty":1,"kind":"mc","stem":"시루떡 3개를 4명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 시루떡은 몇 개인지 분수로 나타내면 얼마인가요?","options":[{"t":"⟨3/4⟩","correct":true},{"t":"⟨1 1/3⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/4⟩","mis":"M6-1-u1-X01"},{"t":"⟨3/7⟩","mis":"M6-1-u1-X09"}],"explanation":["시루떡 3개를 4로 똑같이 나누는 것은 3 ÷ 4예요.","나누어지는 수 3은 분자, 나누는 수 4는 분모가 돼요.","3 ÷ 4 = ⟨3/4⟩ — ⟨3/4⟩개예요."],"variant_rule":{"alt":[{"stem":"과자 반죽 2개를 5명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 과자 반죽은 몇 개인지 분수로 나타내면 얼마인가요?","options":[{"t":"⟨2/5⟩","correct":true},{"t":"⟨2 1/2⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/5⟩","mis":"M6-1-u1-X01"},{"t":"⟨2/7⟩","mis":"M6-1-u1-X09"}],"explanation":["과자 반죽 2개를 5로 똑같이 나누는 것은 2 ÷ 5예요.","나누어지는 수 2는 분자, 나누는 수 5는 분모가 돼요.","2 ÷ 5 = ⟨2/5⟩ — ⟨2/5⟩개예요."]},{"stem":"주스 3 L를 7명이 똑같이 나누어 마시려고 해요. 한 명이 마시는 주스는 몇 L인지 분수로 나타내면 얼마인가요?","options":[{"t":"⟨3/7⟩","correct":true},{"t":"⟨2 1/3⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/7⟩","mis":"M6-1-u1-X01"},{"t":"⟨3/10⟩","mis":"M6-1-u1-X09"}],"explanation":["주스 3 L를 7로 똑같이 나누는 것은 3 ÷ 7이에요.","나누어지는 수 3은 분자, 나누는 수 7은 분모가 돼요.","3 ÷ 7 = ⟨3/7⟩ — ⟨3/7⟩ L예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#2','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C2',1,'sa','auto','4 ÷ 7의 몫을 분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u1-C2","difficulty":1,"kind":"sa","stem":"4 ÷ 7의 몫을 분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["(자연수)÷(자연수)의 몫은 분수로 나타낼 수 있어요.","나누어지는 수 4는 분자, 나누는 수 7은 분모예요.","4 ÷ 7 = ⟨4/7⟩니 분자는 4예요."],"mis":"M6-1-u1-X01","variant_rule":{"alt":[{"stem":"5 ÷ 9의 몫을 분수로 나타낼 때 분모에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["(자연수)÷(자연수)의 몫은 분수로 나타낼 수 있어요.","나누어지는 수 5는 분자, 나누는 수 9는 분모예요.","5 ÷ 9 = ⟨5/9⟩니 분모는 9예요."]},{"stem":"2 ÷ 11의 몫을 분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["(자연수)÷(자연수)의 몫은 분수로 나타낼 수 있어요.","나누어지는 수 2는 분자, 나누는 수 11은 분모예요.","2 ÷ 11 = ⟨2/11⟩니 분자는 2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#3','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C3',1,'mc','auto','⟨1 3/4⟩을 가분수로 나타내면 어느 것인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X05']::text[],true,'{"seq":3,"concept":"M6-1-u1-C3","difficulty":1,"kind":"mc","stem":"⟨1 3/4⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨7/4⟩","correct":true},{"t":"⟨4/7⟩","mis":"M6-1-u1-X01"},{"t":"⟨4/4⟩","mis":"M6-1-u1-X05"},{"t":"⟨3/4⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 1은 ⟨4/4⟩예요 — 1 × 4 = 4.","여기에 ⟨3/4⟩을 더하면 분자는 4 + 3 = 7이에요.","⟨1 3/4⟩ = ⟨7/4⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨2 2/5⟩를 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨12/5⟩","correct":true},{"t":"⟨5/12⟩","mis":"M6-1-u1-X01"},{"t":"⟨4/5⟩","mis":"M6-1-u1-X05"},{"t":"⟨22/5⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 2는 ⟨10/5⟩이에요 — 2 × 5 = 10.","여기에 ⟨2/5⟩를 더하면 분자는 10 + 2 = 12예요.","⟨2 2/5⟩ = ⟨12/5⟩예요."]},{"stem":"⟨3 1/3⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨10/3⟩","correct":true},{"t":"⟨3/10⟩","mis":"M6-1-u1-X01"},{"t":"⟨4/3⟩","mis":"M6-1-u1-X05"},{"t":"⟨3/3⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 3은 ⟨9/3⟩예요 — 3 × 3 = 9.","여기에 ⟨1/3⟩을 더하면 분자는 9 + 1 = 10이에요.","⟨3 1/3⟩ = ⟨10/3⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#4','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C3',1,'sa','auto','15 ÷ 4의 몫을 대분수로 나타낼 때 자연수 부분에 오는 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u1-C3","difficulty":1,"kind":"sa","stem":"15 ÷ 4의 몫을 대분수로 나타낼 때 자연수 부분에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["15 ÷ 4는 몫 3, 나머지 3이에요.","남은 3도 4로 나누면 ⟨3/4⟩ — 몫은 ⟨3 3/4⟩이에요.","그래서 자연수 부분은 3이에요."],"mis":"M6-1-u1-X04","variant_rule":{"alt":[{"stem":"14 ÷ 3의 몫을 대분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["14 ÷ 3은 몫 4, 나머지 2예요.","남은 2도 3으로 나누면 ⟨2/3⟩ — 몫은 ⟨4 2/3⟩예요.","그래서 분자는 2예요."]},{"stem":"19 ÷ 5의 몫을 대분수로 나타낼 때 자연수 부분에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["19 ÷ 5는 몫 3, 나머지 4예요.","남은 4도 5로 나누면 ⟨4/5⟩ — 몫은 ⟨3 4/5⟩예요.","그래서 자연수 부분은 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#5','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C4',1,'mc','auto','6 ÷ 5를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X07']::text[],true,'{"seq":5,"concept":"M6-1-u1-C4","difficulty":1,"kind":"mc","stem":"6 ÷ 5를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"6 × ⟨1/5⟩","correct":true},{"t":"6 × 5","mis":"M6-1-u1-X06"},{"t":"5 × ⟨1/6⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/6⟩ × ⟨1/5⟩","mis":"M6-1-u1-X07"}],"explanation":["÷ 5는 5로 똑같이 나눈 것 중의 1이에요.","× ⟨1/5⟩도 5로 똑같이 나눈 것 중의 1이에요.","그래서 6 ÷ 5 = 6 × ⟨1/5⟩ = ⟨1 1/5⟩이에요."],"variant_rule":{"alt":[{"stem":"2 ÷ 9를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"2 × ⟨1/9⟩","correct":true},{"t":"2 × 9","mis":"M6-1-u1-X06"},{"t":"9 × ⟨1/2⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/2⟩ × ⟨1/9⟩","mis":"M6-1-u1-X07"}],"explanation":["÷ 9는 9로 똑같이 나눈 것 중의 1이에요.","× ⟨1/9⟩도 9로 똑같이 나눈 것 중의 1이에요.","그래서 2 ÷ 9 = 2 × ⟨1/9⟩ = ⟨2/9⟩예요."]},{"stem":"8 ÷ 3을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"8 × ⟨1/3⟩","correct":true},{"t":"8 × 3","mis":"M6-1-u1-X06"},{"t":"3 × ⟨1/8⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/8⟩ × ⟨1/3⟩","mis":"M6-1-u1-X07"}],"explanation":["÷ 3은 3으로 똑같이 나눈 것 중의 1이에요.","× ⟨1/3⟩도 3으로 똑같이 나눈 것 중의 1이에요.","그래서 8 ÷ 3 = 8 × ⟨1/3⟩ = ⟨2 2/3⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#6','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C5',1,'mc','auto','⟨6/11⟩ ÷ 3을 계산하면 얼마인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X09','M6-1-u1-X07']::text[],true,'{"seq":6,"concept":"M6-1-u1-C5","difficulty":1,"kind":"mc","stem":"⟨6/11⟩ ÷ 3을 계산하면 얼마인가요?","options":[{"t":"⟨2/11⟩","correct":true},{"t":"⟨1 7/11⟩","mis":"M6-1-u1-X06"},{"t":"⟨3/7⟩","mis":"M6-1-u1-X09"},{"t":"⟨11/18⟩","mis":"M6-1-u1-X07"}],"explanation":["⟨6/11⟩은 ⟨1/11⟩이 6개예요.","분자 6을 3으로 나누면 6 ÷ 3 = 2 — ⟨1/11⟩이 2개예요.","그래서 ⟨6/11⟩ ÷ 3 = ⟨2/11⟩예요."],"variant_rule":{"alt":[{"stem":"⟨4/9⟩ ÷ 2를 계산하면 얼마인가요?","options":[{"t":"⟨2/9⟩","correct":true},{"t":"⟨8/9⟩","mis":"M6-1-u1-X06"},{"t":"⟨4/11⟩","mis":"M6-1-u1-X09"},{"t":"⟨1 1/8⟩","mis":"M6-1-u1-X07"}],"explanation":["⟨4/9⟩는 ⟨1/9⟩이 4개예요.","분자 4를 2로 나누면 4 ÷ 2 = 2 — ⟨1/9⟩이 2개예요.","그래서 ⟨4/9⟩ ÷ 2 = ⟨2/9⟩예요."]},{"stem":"⟨10/13⟩ ÷ 5를 계산하면 얼마인가요?","options":[{"t":"⟨2/13⟩","correct":true},{"t":"⟨3 11/13⟩","mis":"M6-1-u1-X06"},{"t":"⟨5/9⟩","mis":"M6-1-u1-X09"},{"t":"⟨13/50⟩","mis":"M6-1-u1-X07"}],"explanation":["⟨10/13⟩은 ⟨1/13⟩이 10개예요.","분자 10을 5로 나누면 10 ÷ 5 = 2 — ⟨1/13⟩이 2개예요.","그래서 ⟨10/13⟩ ÷ 5 = ⟨2/13⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#7','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C6',1,'mc','auto','⟨1 5/6⟩를 가분수로 나타내면 어느 것인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X05']::text[],true,'{"seq":7,"concept":"M6-1-u1-C6","difficulty":1,"kind":"mc","stem":"⟨1 5/6⟩를 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨11/6⟩","correct":true},{"t":"⟨6/11⟩","mis":"M6-1-u1-X01"},{"t":"⟨6/6⟩","mis":"M6-1-u1-X05"},{"t":"⟨5/6⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 1은 ⟨6/6⟩이에요 — 1 × 6 = 6.","여기에 ⟨5/6⟩를 더하면 분자는 6 + 5 = 11이에요.","⟨1 5/6⟩ = ⟨11/6⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨3 2/7⟩를 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨23/7⟩","correct":true},{"t":"⟨7/23⟩","mis":"M6-1-u1-X01"},{"t":"⟨5/7⟩","mis":"M6-1-u1-X05"},{"t":"⟨6/7⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 3은 ⟨21/7⟩이에요 — 3 × 7 = 21.","여기에 ⟨2/7⟩를 더하면 분자는 21 + 2 = 23이에요.","⟨3 2/7⟩ = ⟨23/7⟩이에요."]},{"stem":"⟨2 4/5⟩를 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨14/5⟩","correct":true},{"t":"⟨5/14⟩","mis":"M6-1-u1-X01"},{"t":"⟨6/5⟩","mis":"M6-1-u1-X05"},{"t":"⟨8/5⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 2는 ⟨10/5⟩이에요 — 2 × 5 = 10.","여기에 ⟨4/5⟩를 더하면 분자는 10 + 4 = 14예요.","⟨2 4/5⟩ = ⟨14/5⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#8','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C7',1,'mc','auto','저울에서 파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 5개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?',ARRAY['M6-1-u1-X13']::text[],true,'{"seq":8,"concept":"M6-1-u1-C7","difficulty":1,"kind":"mc","stem":"저울에서 파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 5개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?","options":[{"t":"3개","correct":true},{"t":"2개","mis":"M6-1-u1-X13"},{"t":"5개","mis":"M6-1-u1-X13"},{"t":"7개","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 뚜껑 2개씩을 덜어 내도 저울은 수평이에요.","왼쪽엔 노란 뚜껑 1개, 오른쪽엔 파란 뚜껑 5 − 2 = 3개가 남아요.","그래서 노란 뚜껑 1개는 파란 뚜껑 3개와 같아요."],"variant_rule":{"alt":[{"stem":"저울에서 파란 뚜껑 1개와 노란 뚜껑 1개의 무게가 파란 뚜껑 5개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?","options":[{"t":"4개","correct":true},{"t":"1개","mis":"M6-1-u1-X13"},{"t":"5개","mis":"M6-1-u1-X13"},{"t":"6개","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 뚜껑 1개씩을 덜어 내도 저울은 수평이에요.","왼쪽엔 노란 뚜껑 1개, 오른쪽엔 파란 뚜껑 5 − 1 = 4개가 남아요.","그래서 노란 뚜껑 1개는 파란 뚜껑 4개와 같아요."]},{"stem":"저울에서 파란 뚜껑 3개와 노란 뚜껑 1개의 무게가 파란 뚜껑 6개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?","options":[{"t":"3개","correct":true},{"t":"6개","mis":"M6-1-u1-X13"},{"t":"9개","mis":"M6-1-u1-X13"},{"t":"4개","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 뚜껑 3개씩을 덜어 내도 저울은 수평이에요.","왼쪽엔 노란 뚜껑 1개, 오른쪽엔 파란 뚜껑 6 − 3 = 3개가 남아요.","그래서 노란 뚜껑 1개는 파란 뚜껑 3개와 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#9','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C1',2,'mc','auto','시루떡 2개를 5명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 시루떡을 구하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u1-X14']::text[],true,'{"seq":9,"concept":"M6-1-u1-C1","difficulty":2,"kind":"mc","stem":"시루떡 2개를 5명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 시루떡을 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"2 ÷ 5","correct":true},{"t":"5 ÷ 2","mis":"M6-1-u1-X14"},{"t":"2 × 5","mis":"M6-1-u1-X14"},{"t":"2 + 5","mis":"M6-1-u1-X14"}],"explanation":["전체 2개를 5로 똑같이 나누는 거예요.","나누어지는 수 2가 앞, 나누는 수 5가 뒤에 와요.","그래서 식은 2 ÷ 5예요."],"variant_rule":{"alt":[{"stem":"과자 반죽 3개를 7명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 과자 반죽을 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"3 ÷ 7","correct":true},{"t":"7 ÷ 3","mis":"M6-1-u1-X14"},{"t":"3 × 7","mis":"M6-1-u1-X14"},{"t":"3 + 7","mis":"M6-1-u1-X14"}],"explanation":["전체 3개를 7로 똑같이 나누는 거예요.","나누어지는 수 3이 앞, 나누는 수 7이 뒤에 와요.","그래서 식은 3 ÷ 7이에요."]},{"stem":"피자 4판을 9명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 피자를 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"4 ÷ 9","correct":true},{"t":"9 ÷ 4","mis":"M6-1-u1-X14"},{"t":"4 × 9","mis":"M6-1-u1-X14"},{"t":"4 + 9","mis":"M6-1-u1-X14"}],"explanation":["전체 4판을 9로 똑같이 나누는 거예요.","나누어지는 수 4가 앞, 나누는 수 9가 뒤에 와요.","그래서 식은 4 ÷ 9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#10','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C3',2,'mc','auto','흰 종이 5장을 3명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 흰 종이를 대분수로 나타내면 몇 장인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X02','M6-1-u1-X04']::text[],true,'{"seq":10,"concept":"M6-1-u1-C3","difficulty":2,"kind":"mc","stem":"흰 종이 5장을 3명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 흰 종이를 대분수로 나타내면 몇 장인가요?","options":[{"t":"⟨1 2/3⟩","correct":true},{"t":"⟨3/5⟩","mis":"M6-1-u1-X01"},{"t":"⟨2/3⟩","mis":"M6-1-u1-X02"},{"t":"⟨1 2/5⟩","mis":"M6-1-u1-X04"}],"explanation":["먼저 1씩 나누어 주면 2가 남아요 — 5 ÷ 3은 몫 1, 나머지 2예요.","남은 2도 3으로 똑같이 나누면 ⟨2/3⟩씩 더 가져요.","5 ÷ 3 = ⟨1 2/3⟩ — ⟨1 2/3⟩장예요."],"variant_rule":{"alt":[{"stem":"빵 9개를 4명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 빵을 대분수로 나타내면 몇 개인가요?","options":[{"t":"⟨2 1/4⟩","correct":true},{"t":"⟨4/9⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/4⟩","mis":"M6-1-u1-X02"},{"t":"⟨2 1/9⟩","mis":"M6-1-u1-X04"}],"explanation":["먼저 2씩 나누어 주면 1이 남아요 — 9 ÷ 4는 몫 2, 나머지 1이에요.","남은 1도 4로 똑같이 나누면 ⟨1/4⟩씩 더 가져요.","9 ÷ 4 = ⟨2 1/4⟩ — ⟨2 1/4⟩개예요."]},{"stem":"시루떡 7개를 2명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 시루떡을 대분수로 나타내면 몇 개인가요?","options":[{"t":"⟨3 1/2⟩","correct":true},{"t":"⟨2/7⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/2⟩","mis":"M6-1-u1-X02"},{"t":"⟨3 1/7⟩","mis":"M6-1-u1-X04"}],"explanation":["먼저 3씩 나누어 주면 1이 남아요 — 7 ÷ 2는 몫 3, 나머지 1이에요.","남은 1도 2로 똑같이 나누면 ⟨1/2⟩씩 더 가져요.","7 ÷ 2 = ⟨3 1/2⟩ — ⟨3 1/2⟩개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#11','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C4',2,'sa','auto','7 ÷ 8 = 7 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M6-1-u1-C4","difficulty":2,"kind":"sa","stem":"7 ÷ 8 = 7 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["÷ 8은 8로 나눈 것 중의 1이에요.","그래서 ⟨1/8⟩을 곱하는 것과 같아요.","7 ÷ 8 = 7 × ⟨1/8⟩ — □는 8이에요."],"mis":"M6-1-u1-X07","variant_rule":{"alt":[{"stem":"10 ÷ 3 = 10 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["÷ 3은 3으로 나눈 것 중의 1이에요.","그래서 ⟨1/3⟩을 곱하는 것과 같아요.","10 ÷ 3 = 10 × ⟨1/3⟩ — □는 3이에요."]},{"stem":"4 ÷ 13 = 4 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["÷ 13은 13으로 나눈 것 중의 1이에요.","그래서 ⟨1/13⟩을 곱하는 것과 같아요.","4 ÷ 13 = 4 × ⟨1/13⟩ — □는 13이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#12','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C5',2,'sa','auto','⟨8/9⟩ ÷ 4의 몫은 ⟨1/9⟩이 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M6-1-u1-C5","difficulty":2,"kind":"sa","stem":"⟨8/9⟩ ÷ 4의 몫은 ⟨1/9⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["⟨8/9⟩은 ⟨1/9⟩이 8개예요.","8개를 4로 똑같이 나누면 8 ÷ 4 = 2개예요.","⟨8/9⟩ ÷ 4 = ⟨2/9⟩ — ⟨1/9⟩이 2개예요."],"mis":"M6-1-u1-X08","variant_rule":{"alt":[{"stem":"⟨10/11⟩ ÷ 2의 몫은 ⟨1/11⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["⟨10/11⟩은 ⟨1/11⟩이 10개예요.","10개를 2로 똑같이 나누면 10 ÷ 2 = 5개예요.","⟨10/11⟩ ÷ 2 = ⟨5/11⟩ — ⟨1/11⟩이 5개예요."]},{"stem":"⟨9/13⟩ ÷ 3의 몫은 ⟨1/13⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨9/13⟩는 ⟨1/13⟩이 9개예요.","9개를 3으로 똑같이 나누면 9 ÷ 3 = 3개예요.","⟨9/13⟩ ÷ 3 = ⟨3/13⟩ — ⟨1/13⟩이 3개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#13','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C5',2,'mc','auto','⟨4/9⟩ ÷ 5를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X07']::text[],true,'{"seq":13,"concept":"M6-1-u1-C5","difficulty":2,"kind":"mc","stem":"⟨4/9⟩ ÷ 5를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨4/9⟩ × ⟨1/5⟩","correct":true},{"t":"⟨4/9⟩ × 5","mis":"M6-1-u1-X06"},{"t":"⟨9/4⟩ × ⟨1/5⟩","mis":"M6-1-u1-X07"},{"t":"5 × ⟨4/9⟩","mis":"M6-1-u1-X06"}],"explanation":["÷ 5는 5로 똑같이 나눈 것 중의 1이에요.","그래서 × ⟨1/5⟩과 같아요.","⟨4/9⟩ ÷ 5 = ⟨4/9⟩ × ⟨1/5⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨7/10⟩ ÷ 2를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨7/10⟩ × ⟨1/2⟩","correct":true},{"t":"⟨7/10⟩ × 2","mis":"M6-1-u1-X06"},{"t":"⟨10/7⟩ × ⟨1/2⟩","mis":"M6-1-u1-X07"},{"t":"2 × ⟨7/10⟩","mis":"M6-1-u1-X06"}],"explanation":["÷ 2는 2로 똑같이 나눈 것 중의 1이에요.","그래서 × ⟨1/2⟩과 같아요.","⟨7/10⟩ ÷ 2 = ⟨7/10⟩ × ⟨1/2⟩이에요."]},{"stem":"⟨1/6⟩ ÷ 3을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨1/6⟩ × ⟨1/3⟩","correct":true},{"t":"⟨1/6⟩ × 3","mis":"M6-1-u1-X06"},{"t":"⟨6/1⟩ × ⟨1/3⟩","mis":"M6-1-u1-X07"},{"t":"3 × ⟨1/6⟩","mis":"M6-1-u1-X06"}],"explanation":["÷ 3은 3으로 똑같이 나눈 것 중의 1이에요.","그래서 × ⟨1/3⟩과 같아요.","⟨1/6⟩ ÷ 3 = ⟨1/6⟩ × ⟨1/3⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#14','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C6',2,'mc','auto','⟨1 1/4⟩ ÷ 5를 계산하면 얼마인가요?',ARRAY['M6-1-u1-X10','M6-1-u1-X06']::text[],true,'{"seq":14,"concept":"M6-1-u1-C6","difficulty":2,"kind":"mc","stem":"⟨1 1/4⟩ ÷ 5를 계산하면 얼마인가요?","options":[{"t":"⟨1/4⟩","correct":true},{"t":"⟨1 1/20⟩","mis":"M6-1-u1-X10"},{"t":"⟨9/20⟩","mis":"M6-1-u1-X10"},{"t":"⟨6 1/4⟩","mis":"M6-1-u1-X06"}],"explanation":["⟨1 1/4⟩을 가분수로 고치면 ⟨5/4⟩예요.","⟨5/4⟩ ÷ 5 = ⟨5/4⟩ × ⟨1/5⟩이에요.","⟨5/4⟩ × ⟨1/5⟩ = ⟨1/4⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨2 1/3⟩ ÷ 7을 계산하면 얼마인가요?","options":[{"t":"⟨1/3⟩","correct":true},{"t":"⟨2 1/21⟩","mis":"M6-1-u1-X10"},{"t":"⟨13/21⟩","mis":"M6-1-u1-X10"},{"t":"⟨16 1/3⟩","mis":"M6-1-u1-X06"}],"explanation":["⟨2 1/3⟩을 가분수로 고치면 ⟨7/3⟩이에요.","⟨7/3⟩ ÷ 7 = ⟨7/3⟩ × ⟨1/7⟩이에요.","⟨7/3⟩ × ⟨1/7⟩ = ⟨1/3⟩이에요."]},{"stem":"⟨3 3/5⟩ ÷ 6을 계산하면 얼마인가요?","options":[{"t":"⟨3/5⟩","correct":true},{"t":"⟨3 1/10⟩","mis":"M6-1-u1-X10"},{"t":"⟨1 1/10⟩","mis":"M6-1-u1-X10"},{"t":"⟨21 3/5⟩","mis":"M6-1-u1-X06"}],"explanation":["⟨3 3/5⟩을 가분수로 고치면 ⟨18/5⟩이에요.","⟨18/5⟩ ÷ 6 = ⟨18/5⟩ × ⟨1/6⟩이에요.","⟨18/5⟩ × ⟨1/6⟩ = ⟨3/5⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#15','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C6',2,'sa','auto','⟨2 3/8⟩ ÷ 5를 계산하려고 ⟨2 3/8⟩을 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":15,"concept":"M6-1-u1-C6","difficulty":2,"kind":"sa","stem":"⟨2 3/8⟩ ÷ 5를 계산하려고 ⟨2 3/8⟩을 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["대분수는 먼저 가분수로 고쳐요.","2 × 8 + 3 = 19예요.","⟨2 3/8⟩ = ⟨19/8⟩ — 분자는 19예요."],"mis":"M6-1-u1-X05","variant_rule":{"alt":[{"stem":"⟨3 4/5⟩ ÷ 2를 계산하려고 ⟨3 4/5⟩를 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["대분수는 먼저 가분수로 고쳐요.","3 × 5 + 4 = 19예요.","⟨3 4/5⟩ = ⟨19/5⟩ — 분자는 19예요."]},{"stem":"⟨1 7/9⟩ ÷ 4를 계산하려고 ⟨1 7/9⟩을 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["대분수는 먼저 가분수로 고쳐요.","1 × 9 + 7 = 16이에요.","⟨1 7/9⟩ = ⟨16/9⟩ — 분자는 16이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#16','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C7',2,'mc','auto','파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 5개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨5 1/4⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?',ARRAY['M6-1-u1-X13','M6-1-u1-X06']::text[],true,'{"seq":16,"concept":"M6-1-u1-C7","difficulty":2,"kind":"mc","stem":"파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 5개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨5 1/4⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?","options":[{"t":"⟨1 3/4⟩","correct":true},{"t":"⟨1 1/20⟩","mis":"M6-1-u1-X13"},{"t":"⟨2 5/8⟩","mis":"M6-1-u1-X13"},{"t":"⟨15 3/4⟩","mis":"M6-1-u1-X06"}],"explanation":["양쪽에서 파란 2개씩 덜어 내면 노란 1개 = 파란 3개예요.","⟨5 1/4⟩ = ⟨21/4⟩이에요.","⟨21/4⟩ × ⟨1/3⟩ = ⟨1 3/4⟩ — 파란 뚜껑 1개는 ⟨1 3/4⟩ g이에요."],"variant_rule":{"alt":[{"stem":"파란 뚜껑 1개와 노란 뚜껑 1개의 무게가 파란 뚜껑 3개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨2 2/3⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?","options":[{"t":"⟨1 1/3⟩","correct":true},{"t":"⟨8/9⟩","mis":"M6-1-u1-X13"},{"t":"⟨2 2/3⟩","mis":"M6-1-u1-X13"},{"t":"⟨5 1/3⟩","mis":"M6-1-u1-X06"}],"explanation":["양쪽에서 파란 1개씩 덜어 내면 노란 1개 = 파란 2개예요.","⟨2 2/3⟩ = ⟨8/3⟩이에요.","⟨8/3⟩ × ⟨1/2⟩ = ⟨1 1/3⟩ — 파란 뚜껑 1개는 ⟨1 1/3⟩ g이에요."]},{"stem":"파란 뚜껑 3개와 노란 뚜껑 1개의 무게가 파란 뚜껑 7개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨6 2/3⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?","options":[{"t":"⟨1 2/3⟩","correct":true},{"t":"⟨20/21⟩","mis":"M6-1-u1-X13"},{"t":"⟨2 2/9⟩","mis":"M6-1-u1-X13"},{"t":"⟨26 2/3⟩","mis":"M6-1-u1-X06"}],"explanation":["양쪽에서 파란 3개씩 덜어 내면 노란 1개 = 파란 4개예요.","⟨6 2/3⟩ = ⟨20/3⟩이에요.","⟨20/3⟩ × ⟨1/4⟩ = ⟨1 2/3⟩ — 파란 뚜껑 1개는 ⟨1 2/3⟩ g이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#17','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C2',3,'mc','auto','가 모둠은 시루떡 2개를 5명이, 나 모둠은 시루떡 3개를 7명이 똑같이 나누었어요. 한 명이 가지는 시루떡이 더 많은 모둠은 어디인가요?',ARRAY['M6-1-u1-X11','M6-1-u1-X03']::text[],true,'{"seq":17,"concept":"M6-1-u1-C2","difficulty":3,"kind":"mc","stem":"가 모둠은 시루떡 2개를 5명이, 나 모둠은 시루떡 3개를 7명이 똑같이 나누었어요. 한 명이 가지는 시루떡이 더 많은 모둠은 어디인가요?","options":[{"t":"나 모둠","correct":true},{"t":"가 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 2 ÷ 5 = ⟨2/5⟩, 나 모둠은 3 ÷ 7 = ⟨3/7⟩이에요.","35로 통분하면 ⟨2/5⟩ = ⟨14/35⟩, ⟨3/7⟩ = ⟨15/35⟩예요.","⟨2/5⟩ < ⟨3/7⟩이라 나 모둠이 더 많아요."],"variant_rule":{"alt":[{"stem":"가 모둠은 주스 4 L를 9명이, 나 모둠은 주스 3 L를 8명이 똑같이 나누었어요. 한 명이 가지는 주스가 더 많은 모둠은 어디인가요?","options":[{"t":"가 모둠","correct":true},{"t":"나 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 4 ÷ 9 = ⟨4/9⟩, 나 모둠은 3 ÷ 8 = ⟨3/8⟩이에요.","72로 통분하면 ⟨4/9⟩ = ⟨32/72⟩, ⟨3/8⟩ = ⟨27/72⟩이에요.","⟨4/9⟩ > ⟨3/8⟩이라 가 모둠이 더 많아요."]},{"stem":"가 모둠은 빵 5개를 7명이, 나 모둠은 빵 3개를 4명이 똑같이 나누었어요. 한 명이 가지는 빵이 더 많은 모둠은 어디인가요?","options":[{"t":"나 모둠","correct":true},{"t":"가 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 5 ÷ 7 = ⟨5/7⟩, 나 모둠은 3 ÷ 4 = ⟨3/4⟩이에요.","28로 통분하면 ⟨5/7⟩ = ⟨20/28⟩, ⟨3/4⟩ = ⟨21/28⟩이에요.","⟨5/7⟩ < ⟨3/4⟩이라 나 모둠이 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#18','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C3',3,'sa','auto','쌀 19 kg을 4봉지에 똑같이 나누어 담으려고 해요. 한 봉지에 담는 쌀을 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M6-1-u1-C3","difficulty":3,"kind":"sa","stem":"쌀 19 kg을 4봉지에 똑같이 나누어 담으려고 해요. 한 봉지에 담는 쌀을 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["19 ÷ 4는 몫 4, 나머지 3이에요.","남은 3도 나누면 19 ÷ 4 = ⟨4 3/4⟩이에요.","자연수 부분과 분자의 합은 4 + 3 = 7이에요."],"mis":"M6-1-u1-X15","variant_rule":{"alt":[{"stem":"끈 17 m를 6도막으로 똑같이 나누어 자르려고 해요. 한 도막의 길이를 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["17 ÷ 6은 몫 2, 나머지 5예요.","남은 5도 나누면 17 ÷ 6 = ⟨2 5/6⟩예요.","자연수 부분과 분자의 합은 2 + 5 = 7이에요."]},{"stem":"색 모래 25 kg을 7모둠이 똑같이 나누어 가지려고 해요. 한 모둠이 가지는 색 모래를 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["25 ÷ 7은 몫 3, 나머지 4예요.","남은 4도 나누면 25 ÷ 7 = ⟨3 4/7⟩예요.","자연수 부분과 분자의 합은 3 + 4 = 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#19','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C4',3,'mc','auto','끈 9 m를 4도막으로 나눈 한 도막과 끈 7 m를 3도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?',ARRAY['M6-1-u1-X11','M6-1-u1-X03']::text[],true,'{"seq":19,"concept":"M6-1-u1-C4","difficulty":3,"kind":"mc","stem":"끈 9 m를 4도막으로 나눈 한 도막과 끈 7 m를 3도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?","options":[{"t":"끈 7 m를 3도막으로 나눈 한 도막","correct":true},{"t":"끈 9 m를 4도막으로 나눈 한 도막","mis":"M6-1-u1-X11"},{"t":"두 도막의 길이가 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["9 ÷ 4 = 9 × ⟨1/4⟩ = ⟨2 1/4⟩, 7 ÷ 3 = 7 × ⟨1/3⟩ = ⟨2 1/3⟩이에요.","12로 통분하면 ⟨2 1/4⟩ = ⟨27/12⟩, ⟨2 1/3⟩ = ⟨28/12⟩이에요.","그래서 더 긴 것은 끈 7 m를 3도막으로 나눈 한 도막이에요."],"variant_rule":{"alt":[{"stem":"끈 6 m를 5도막으로 나눈 한 도막과 끈 5 m를 4도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?","options":[{"t":"끈 5 m를 4도막으로 나눈 한 도막","correct":true},{"t":"끈 6 m를 5도막으로 나눈 한 도막","mis":"M6-1-u1-X11"},{"t":"두 도막의 길이가 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["6 ÷ 5 = 6 × ⟨1/5⟩ = ⟨1 1/5⟩, 5 ÷ 4 = 5 × ⟨1/4⟩ = ⟨1 1/4⟩이에요.","20으로 통분하면 ⟨1 1/5⟩ = ⟨24/20⟩, ⟨1 1/4⟩ = ⟨25/20⟩예요.","그래서 더 긴 것은 끈 5 m를 4도막으로 나눈 한 도막이에요."]},{"stem":"끈 10 m를 3도막으로 나눈 한 도막과 끈 13 m를 4도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?","options":[{"t":"끈 10 m를 3도막으로 나눈 한 도막","correct":true},{"t":"끈 13 m를 4도막으로 나눈 한 도막","mis":"M6-1-u1-X11"},{"t":"두 도막의 길이가 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["10 ÷ 3 = 10 × ⟨1/3⟩ = ⟨3 1/3⟩, 13 ÷ 4 = 13 × ⟨1/4⟩ = ⟨3 1/4⟩이에요.","12로 통분하면 ⟨3 1/3⟩ = ⟨40/12⟩, ⟨3 1/4⟩ = ⟨39/12⟩예요.","그래서 더 긴 것은 끈 10 m를 3도막으로 나눈 한 도막이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#20','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C5',3,'error','auto','⟨4/7⟩ ÷ 3에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X15']::text[],true,'{"seq":20,"concept":"M6-1-u1-C5","difficulty":3,"kind":"error","stem":"⟨4/7⟩ ÷ 3에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「⟨4/7⟩ × 3 = ⟨1 5/7⟩로 계산해.」","correct":true,"mis_target":"M6-1-u1-X06"},{"t":"도윤 — 「⟨4/7⟩ × ⟨1/3⟩로 바꾸어 계산하면 돼.」","mis":"M6-1-u1-X15"},{"t":"하린 — 「몫은 ⟨4/7⟩보다 작아.」","mis":"M6-1-u1-X15"}],"explanation":["3으로 나누면 양이 작아져야 해요.","⟨4/7⟩ × 3 = ⟨1 5/7⟩는 오히려 커요.","⟨4/7⟩ ÷ 3 = ⟨4/7⟩ × ⟨1/3⟩ = ⟨4/21⟩ — 수아는 나누는 수를 그대로 곱했어요."],"variant_rule":{"alt":[{"stem":"⟨5/6⟩ ÷ 2에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민준 — 「⟨5/6⟩ × 2 = ⟨1 2/3⟩로 계산해.」","correct":true,"mis_target":"M6-1-u1-X06"},{"t":"서연 — 「⟨5/6⟩ × ⟨1/2⟩로 바꾸어 계산하면 돼.」","mis":"M6-1-u1-X15"},{"t":"지호 — 「몫은 ⟨5/6⟩보다 작아.」","mis":"M6-1-u1-X15"}],"explanation":["2로 나누면 양이 작아져야 해요.","⟨5/6⟩ × 2 = ⟨1 2/3⟩는 오히려 커요.","⟨5/6⟩ ÷ 2 = ⟨5/6⟩ × ⟨1/2⟩ = ⟨5/12⟩ — 민준은 나누는 수를 그대로 곱했어요."]},{"stem":"⟨3/10⟩ ÷ 4에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「⟨3/10⟩ × 4 = ⟨1 1/5⟩로 계산해.」","correct":true,"mis_target":"M6-1-u1-X06"},{"t":"나린 — 「⟨3/10⟩ × ⟨1/4⟩로 바꾸어 계산하면 돼.」","mis":"M6-1-u1-X15"},{"t":"유진 — 「몫은 ⟨3/10⟩보다 작아.」","mis":"M6-1-u1-X15"}],"explanation":["4로 나누면 양이 작아져야 해요.","⟨3/10⟩ × 4 = ⟨1 1/5⟩은 오히려 커요.","⟨3/10⟩ ÷ 4 = ⟨3/10⟩ × ⟨1/4⟩ = ⟨3/40⟩ — 가온은 나누는 수를 그대로 곱했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#21','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C6',3,'mc','auto','넓이가 ⟨4 2/3⟩ m²이고 가로가 3 m인 직사각형이 있어요. 세로는 몇 m인가요?',ARRAY['M6-1-u1-X10','M6-1-u1-X06']::text[],true,'{"seq":21,"concept":"M6-1-u1-C6","difficulty":3,"kind":"mc","stem":"넓이가 ⟨4 2/3⟩ m²이고 가로가 3 m인 직사각형이 있어요. 세로는 몇 m인가요?","options":[{"t":"⟨1 5/9⟩","correct":true},{"t":"⟨4 2/9⟩","mis":"M6-1-u1-X10"},{"t":"2","mis":"M6-1-u1-X10"},{"t":"14","mis":"M6-1-u1-X06"}],"explanation":["(직사각형의 넓이) = (가로) × (세로)이니 세로 = 넓이 ÷ 가로예요.","⟨4 2/3⟩ ÷ 3 = ⟨14/3⟩ × ⟨1/3⟩이에요.","⟨14/3⟩ × ⟨1/3⟩ = ⟨1 5/9⟩ — 세로는 ⟨1 5/9⟩ m예요."],"variant_rule":{"alt":[{"stem":"넓이가 ⟨5 1/4⟩ m²이고 가로가 2 m인 직사각형이 있어요. 세로는 몇 m인가요?","options":[{"t":"⟨2 5/8⟩","correct":true},{"t":"⟨5 1/8⟩","mis":"M6-1-u1-X10"},{"t":"⟨2 3/4⟩","mis":"M6-1-u1-X10"},{"t":"⟨10 1/2⟩","mis":"M6-1-u1-X06"}],"explanation":["(직사각형의 넓이) = (가로) × (세로)이니 세로 = 넓이 ÷ 가로예요.","⟨5 1/4⟩ ÷ 2 = ⟨21/4⟩ × ⟨1/2⟩이에요.","⟨21/4⟩ × ⟨1/2⟩ = ⟨2 5/8⟩ — 세로는 ⟨2 5/8⟩ m예요."]},{"stem":"넓이가 ⟨3 3/5⟩ m²이고 가로가 4 m인 직사각형이 있어요. 세로는 몇 m인가요?","options":[{"t":"⟨9/10⟩","correct":true},{"t":"⟨3 3/20⟩","mis":"M6-1-u1-X10"},{"t":"⟨1 7/20⟩","mis":"M6-1-u1-X10"},{"t":"⟨14 2/5⟩","mis":"M6-1-u1-X06"}],"explanation":["(직사각형의 넓이) = (가로) × (세로)이니 세로 = 넓이 ÷ 가로예요.","⟨3 3/5⟩ ÷ 4 = ⟨18/5⟩ × ⟨1/4⟩이에요.","⟨18/5⟩ × ⟨1/4⟩ = ⟨9/10⟩ — 세로는 ⟨9/10⟩ m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#22','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C7',3,'sa','auto','조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨2 1/3⟩ g이고 파란 뚜껑 7개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M6-1-u1-C7","difficulty":3,"kind":"sa","stem":"조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨2 1/3⟩ g이고 파란 뚜껑 7개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["파란 뚜껑 1개 = ⟨2 1/3⟩ ÷ 7이에요.","⟨7/3⟩ ÷ 7 = ⟨7/3⟩ × ⟨1/7⟩ = ⟨1/3⟩이에요.","분모와 분자의 합은 3 + 1 = 4예요."],"mis":"M6-1-u1-X15","variant_rule":{"alt":[{"stem":"조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨3 3/4⟩ g이고 파란 뚜껑 5개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["파란 뚜껑 1개 = ⟨3 3/4⟩ ÷ 5예요.","⟨15/4⟩ ÷ 5 = ⟨15/4⟩ × ⟨1/5⟩ = ⟨3/4⟩이에요.","분모와 분자의 합은 4 + 3 = 7이에요."]},{"stem":"조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨4 4/5⟩ g이고 파란 뚜껑 6개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["파란 뚜껑 1개 = ⟨4 4/5⟩ ÷ 6이에요.","⟨24/5⟩ ÷ 6 = ⟨24/5⟩ × ⟨1/6⟩ = ⟨4/5⟩예요.","분모와 분자의 합은 5 + 4 = 9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#23','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C2',4,'sa','auto','□ ÷ 11의 몫이 1보다 작을 때, □에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M6-1-u1-C2","difficulty":4,"kind":"sa","stem":"□ ÷ 11의 몫이 1보다 작을 때, □에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["□ ÷ 11 = ⟨□/11⟩이에요.","몫이 1보다 작으려면 □가 11보다 작아야 해요.","1부터 10까지 10개예요."],"mis":"M6-1-u1-X03","variant_rule":{"alt":[{"stem":"□ ÷ 7의 몫이 3보다 크고 4보다 작을 때, □에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["21 ÷ 7 = 3, 28 ÷ 7 = 4예요.","□는 21보다 크고 28보다 작아야 해요.","22부터 27까지 6개예요."]},{"stem":"⟨9/13⟩ ÷ □의 몫이 ⟨1/13⟩보다 클 때, □에 들어갈 수 있는 가장 큰 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["⟨9/13⟩는 ⟨1/13⟩이 9개예요.","□로 나눈 몫이 ⟨1/13⟩보다 크려면 9개를 □로 나눈 수가 1보다 커야 해요.","□는 9보다 작아야 하니 가장 큰 수는 8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#24','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C1',4,'essay','teacher','(자연수)÷(자연수)가 나누어떨어지지 않을 때에도 몫을 하나의 수로 나타낼 수 있는 까닭을 7 ÷ 2를 예로 들어 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-1-u1-C1","difficulty":4,"kind":"essay","stem":"(자연수)÷(자연수)가 나누어떨어지지 않을 때에도 몫을 하나의 수로 나타낼 수 있는 까닭을 7 ÷ 2를 예로 들어 설명해 보세요.","answer_guide":{"answer":"예: 7 ÷ 2는 몫 3, 나머지 1이지만 남은 1도 2로 똑같이 나눌 수 있다. 남은 1을 나누면 ⟨1/2⟩씩 더 가지므로 한 사람 몫은 ⟨3 1/2⟩이다. 이렇게 남은 것까지 마저 나누면 몫을 분수인 하나의 수 ⟨3 1/2⟩(= ⟨7/2⟩)로 나타낼 수 있다.","scoring_points":["나머지 1도 나눌 수 있다고 썼는가","7 ÷ 2 = ⟨3 1/2⟩(또는 ⟨7/2⟩)을 구했는가","남은 것을 마저 나누면 하나의 수가 된다고 설명했는가"]},"explanation":["7 ÷ 2는 몫 3, 나머지 1이에요.","남은 1을 2로 나누면 ⟨1/2⟩이에요.","7 ÷ 2 = ⟨3 1/2⟩ — 하나의 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_a#25','math',6,1,'u1','','g6_1_math_u1_review_a','unit_review','M6-1-u1-C4',4,'essay','teacher','「÷ 6」을 「× ⟨1/6⟩」로 바꾸어 계산해도 되는 까닭을 쓰고, 4 ÷ 6을 분수의 곱셈으로 계산해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-1-u1-C4","difficulty":4,"kind":"essay","stem":"「÷ 6」을 「× ⟨1/6⟩」로 바꾸어 계산해도 되는 까닭을 쓰고, 4 ÷ 6을 분수의 곱셈으로 계산해 보세요.","answer_guide":{"answer":"예: ÷ 6은 6으로 똑같이 나눈 것 중의 1을 구하는 것이고, × ⟨1/6⟩도 전체의 ⟨1/6⟩, 곧 6으로 나눈 것 중의 1을 구하는 것이라 뜻이 같다. 4 ÷ 6 = 4 × ⟨1/6⟩ = ⟨4/6⟩ = ⟨2/3⟩이다.","scoring_points":["÷ 6과 × ⟨1/6⟩이 모두 6으로 나눈 것 중의 1이라고 썼는가","4 × ⟨1/6⟩ = ⟨4/6⟩를 썼는가","약분해 ⟨2/3⟩를 구했는가"]},"explanation":["÷ 6은 6으로 나눈 것 중의 1이에요.","× ⟨1/6⟩도 6으로 나눈 것 중의 1이에요.","4 ÷ 6 = 4 × ⟨1/6⟩ = ⟨2/3⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#1','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C2',1,'mc','auto','과자 반죽 2개를 5명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 과자 반죽은 몇 개인지 분수로 나타내면 얼마인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X09']::text[],true,'{"seq":1,"concept":"M6-1-u1-C2","difficulty":1,"kind":"mc","stem":"과자 반죽 2개를 5명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 과자 반죽은 몇 개인지 분수로 나타내면 얼마인가요?","options":[{"t":"⟨2/5⟩","correct":true},{"t":"⟨2 1/2⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/5⟩","mis":"M6-1-u1-X01"},{"t":"⟨2/7⟩","mis":"M6-1-u1-X09"}],"explanation":["과자 반죽 2개를 5로 똑같이 나누는 것은 2 ÷ 5예요.","나누어지는 수 2는 분자, 나누는 수 5는 분모가 돼요.","2 ÷ 5 = ⟨2/5⟩ — ⟨2/5⟩개예요."],"variant_rule":{"alt":[{"stem":"주스 3 L를 7명이 똑같이 나누어 마시려고 해요. 한 명이 마시는 주스는 몇 L인지 분수로 나타내면 얼마인가요?","options":[{"t":"⟨3/7⟩","correct":true},{"t":"⟨2 1/3⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/7⟩","mis":"M6-1-u1-X01"},{"t":"⟨3/10⟩","mis":"M6-1-u1-X09"}],"explanation":["주스 3 L를 7로 똑같이 나누는 것은 3 ÷ 7이에요.","나누어지는 수 3은 분자, 나누는 수 7은 분모가 돼요.","3 ÷ 7 = ⟨3/7⟩ — ⟨3/7⟩ L예요."]},{"stem":"식빵 1개를 3명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 식빵은 몇 개인지 분수로 나타내면 얼마인가요?","options":[{"t":"⟨1/3⟩","correct":true},{"t":"3","mis":"M6-1-u1-X01"},{"t":"⟨1/4⟩","mis":"M6-1-u1-X09"},{"t":"1","mis":"M6-1-u1-X01"}],"explanation":["식빵 1개를 3으로 똑같이 나누는 것은 1 ÷ 3이에요.","나누어지는 수 1은 분자, 나누는 수 3은 분모가 돼요.","1 ÷ 3 = ⟨1/3⟩ — ⟨1/3⟩개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#2','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C2',1,'sa','auto','5 ÷ 9의 몫을 분수로 나타낼 때 분모에 오는 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u1-C2","difficulty":1,"kind":"sa","stem":"5 ÷ 9의 몫을 분수로 나타낼 때 분모에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["(자연수)÷(자연수)의 몫은 분수로 나타낼 수 있어요.","나누어지는 수 5는 분자, 나누는 수 9는 분모예요.","5 ÷ 9 = ⟨5/9⟩니 분모는 9예요."],"mis":"M6-1-u1-X01","variant_rule":{"alt":[{"stem":"2 ÷ 11의 몫을 분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["(자연수)÷(자연수)의 몫은 분수로 나타낼 수 있어요.","나누어지는 수 2는 분자, 나누는 수 11은 분모예요.","2 ÷ 11 = ⟨2/11⟩니 분자는 2예요."]},{"stem":"6 ÷ 13의 몫을 분수로 나타낼 때 분모에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["(자연수)÷(자연수)의 몫은 분수로 나타낼 수 있어요.","나누어지는 수 6은 분자, 나누는 수 13은 분모예요.","6 ÷ 13 = ⟨6/13⟩이니 분모는 13이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#3','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C3',1,'mc','auto','⟨2 2/5⟩를 가분수로 나타내면 어느 것인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X05']::text[],true,'{"seq":3,"concept":"M6-1-u1-C3","difficulty":1,"kind":"mc","stem":"⟨2 2/5⟩를 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨12/5⟩","correct":true},{"t":"⟨5/12⟩","mis":"M6-1-u1-X01"},{"t":"⟨4/5⟩","mis":"M6-1-u1-X05"},{"t":"⟨22/5⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 2는 ⟨10/5⟩이에요 — 2 × 5 = 10.","여기에 ⟨2/5⟩를 더하면 분자는 10 + 2 = 12예요.","⟨2 2/5⟩ = ⟨12/5⟩예요."],"variant_rule":{"alt":[{"stem":"⟨3 1/3⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨10/3⟩","correct":true},{"t":"⟨3/10⟩","mis":"M6-1-u1-X01"},{"t":"⟨4/3⟩","mis":"M6-1-u1-X05"},{"t":"⟨3/3⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 3은 ⟨9/3⟩예요 — 3 × 3 = 9.","여기에 ⟨1/3⟩을 더하면 분자는 9 + 1 = 10이에요.","⟨3 1/3⟩ = ⟨10/3⟩이에요."]},{"stem":"⟨2 5/6⟩를 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨17/6⟩","correct":true},{"t":"⟨6/17⟩","mis":"M6-1-u1-X01"},{"t":"⟨7/6⟩","mis":"M6-1-u1-X05"},{"t":"⟨10/6⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 2는 ⟨12/6⟩예요 — 2 × 6 = 12.","여기에 ⟨5/6⟩를 더하면 분자는 12 + 5 = 17이에요.","⟨2 5/6⟩ = ⟨17/6⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#4','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C3',1,'sa','auto','14 ÷ 3의 몫을 대분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u1-C3","difficulty":1,"kind":"sa","stem":"14 ÷ 3의 몫을 대분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["14 ÷ 3은 몫 4, 나머지 2예요.","남은 2도 3으로 나누면 ⟨2/3⟩ — 몫은 ⟨4 2/3⟩예요.","그래서 분자는 2예요."],"mis":"M6-1-u1-X04","variant_rule":{"alt":[{"stem":"19 ÷ 5의 몫을 대분수로 나타낼 때 자연수 부분에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["19 ÷ 5는 몫 3, 나머지 4예요.","남은 4도 5로 나누면 ⟨4/5⟩ — 몫은 ⟨3 4/5⟩예요.","그래서 자연수 부분은 3이에요."]},{"stem":"23 ÷ 7의 몫을 대분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["23 ÷ 7은 몫 3, 나머지 2예요.","남은 2도 7로 나누면 ⟨2/7⟩ — 몫은 ⟨3 2/7⟩예요.","그래서 분자는 2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#5','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C4',1,'mc','auto','2 ÷ 9를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X07']::text[],true,'{"seq":5,"concept":"M6-1-u1-C4","difficulty":1,"kind":"mc","stem":"2 ÷ 9를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"2 × ⟨1/9⟩","correct":true},{"t":"2 × 9","mis":"M6-1-u1-X06"},{"t":"9 × ⟨1/2⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/2⟩ × ⟨1/9⟩","mis":"M6-1-u1-X07"}],"explanation":["÷ 9는 9로 똑같이 나눈 것 중의 1이에요.","× ⟨1/9⟩도 9로 똑같이 나눈 것 중의 1이에요.","그래서 2 ÷ 9 = 2 × ⟨1/9⟩ = ⟨2/9⟩예요."],"variant_rule":{"alt":[{"stem":"8 ÷ 3을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"8 × ⟨1/3⟩","correct":true},{"t":"8 × 3","mis":"M6-1-u1-X06"},{"t":"3 × ⟨1/8⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/8⟩ × ⟨1/3⟩","mis":"M6-1-u1-X07"}],"explanation":["÷ 3은 3으로 똑같이 나눈 것 중의 1이에요.","× ⟨1/3⟩도 3으로 똑같이 나눈 것 중의 1이에요.","그래서 8 ÷ 3 = 8 × ⟨1/3⟩ = ⟨2 2/3⟩예요."]},{"stem":"4 ÷ 11을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"4 × ⟨1/11⟩","correct":true},{"t":"4 × 11","mis":"M6-1-u1-X06"},{"t":"11 × ⟨1/4⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/4⟩ × ⟨1/11⟩","mis":"M6-1-u1-X07"}],"explanation":["÷ 11은 11로 똑같이 나눈 것 중의 1이에요.","× ⟨1/11⟩도 11로 똑같이 나눈 것 중의 1이에요.","그래서 4 ÷ 11 = 4 × ⟨1/11⟩ = ⟨4/11⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#6','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C5',1,'mc','auto','⟨4/9⟩ ÷ 2를 계산하면 얼마인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X09','M6-1-u1-X07']::text[],true,'{"seq":6,"concept":"M6-1-u1-C5","difficulty":1,"kind":"mc","stem":"⟨4/9⟩ ÷ 2를 계산하면 얼마인가요?","options":[{"t":"⟨2/9⟩","correct":true},{"t":"⟨8/9⟩","mis":"M6-1-u1-X06"},{"t":"⟨4/11⟩","mis":"M6-1-u1-X09"},{"t":"⟨1 1/8⟩","mis":"M6-1-u1-X07"}],"explanation":["⟨4/9⟩는 ⟨1/9⟩이 4개예요.","분자 4를 2로 나누면 4 ÷ 2 = 2 — ⟨1/9⟩이 2개예요.","그래서 ⟨4/9⟩ ÷ 2 = ⟨2/9⟩예요."],"variant_rule":{"alt":[{"stem":"⟨10/13⟩ ÷ 5를 계산하면 얼마인가요?","options":[{"t":"⟨2/13⟩","correct":true},{"t":"⟨3 11/13⟩","mis":"M6-1-u1-X06"},{"t":"⟨5/9⟩","mis":"M6-1-u1-X09"},{"t":"⟨13/50⟩","mis":"M6-1-u1-X07"}],"explanation":["⟨10/13⟩은 ⟨1/13⟩이 10개예요.","분자 10을 5로 나누면 10 ÷ 5 = 2 — ⟨1/13⟩이 2개예요.","그래서 ⟨10/13⟩ ÷ 5 = ⟨2/13⟩예요."]},{"stem":"⟨9/10⟩ ÷ 3을 계산하면 얼마인가요?","options":[{"t":"⟨3/10⟩","correct":true},{"t":"⟨2 7/10⟩","mis":"M6-1-u1-X06"},{"t":"⟨9/13⟩","mis":"M6-1-u1-X09"},{"t":"⟨10/27⟩","mis":"M6-1-u1-X07"}],"explanation":["⟨9/10⟩는 ⟨1/10⟩이 9개예요.","분자 9를 3으로 나누면 9 ÷ 3 = 3 — ⟨1/10⟩이 3개예요.","그래서 ⟨9/10⟩ ÷ 3 = ⟨3/10⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#7','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C6',1,'mc','auto','⟨3 2/7⟩를 가분수로 나타내면 어느 것인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X05']::text[],true,'{"seq":7,"concept":"M6-1-u1-C6","difficulty":1,"kind":"mc","stem":"⟨3 2/7⟩를 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨23/7⟩","correct":true},{"t":"⟨7/23⟩","mis":"M6-1-u1-X01"},{"t":"⟨5/7⟩","mis":"M6-1-u1-X05"},{"t":"⟨6/7⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 3은 ⟨21/7⟩이에요 — 3 × 7 = 21.","여기에 ⟨2/7⟩를 더하면 분자는 21 + 2 = 23이에요.","⟨3 2/7⟩ = ⟨23/7⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨2 4/5⟩를 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨14/5⟩","correct":true},{"t":"⟨5/14⟩","mis":"M6-1-u1-X01"},{"t":"⟨6/5⟩","mis":"M6-1-u1-X05"},{"t":"⟨8/5⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 2는 ⟨10/5⟩이에요 — 2 × 5 = 10.","여기에 ⟨4/5⟩를 더하면 분자는 10 + 4 = 14예요.","⟨2 4/5⟩ = ⟨14/5⟩예요."]},{"stem":"⟨4 1/3⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨13/3⟩","correct":true},{"t":"⟨3/13⟩","mis":"M6-1-u1-X01"},{"t":"⟨5/3⟩","mis":"M6-1-u1-X05"},{"t":"⟨4/3⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 4는 ⟨12/3⟩예요 — 4 × 3 = 12.","여기에 ⟨1/3⟩을 더하면 분자는 12 + 1 = 13이에요.","⟨4 1/3⟩ = ⟨13/3⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#8','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C7',1,'mc','auto','저울에서 파란 뚜껑 1개와 노란 뚜껑 1개의 무게가 파란 뚜껑 5개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?',ARRAY['M6-1-u1-X13']::text[],true,'{"seq":8,"concept":"M6-1-u1-C7","difficulty":1,"kind":"mc","stem":"저울에서 파란 뚜껑 1개와 노란 뚜껑 1개의 무게가 파란 뚜껑 5개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?","options":[{"t":"4개","correct":true},{"t":"1개","mis":"M6-1-u1-X13"},{"t":"5개","mis":"M6-1-u1-X13"},{"t":"6개","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 뚜껑 1개씩을 덜어 내도 저울은 수평이에요.","왼쪽엔 노란 뚜껑 1개, 오른쪽엔 파란 뚜껑 5 − 1 = 4개가 남아요.","그래서 노란 뚜껑 1개는 파란 뚜껑 4개와 같아요."],"variant_rule":{"alt":[{"stem":"저울에서 파란 뚜껑 3개와 노란 뚜껑 1개의 무게가 파란 뚜껑 6개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?","options":[{"t":"3개","correct":true},{"t":"6개","mis":"M6-1-u1-X13"},{"t":"9개","mis":"M6-1-u1-X13"},{"t":"4개","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 뚜껑 3개씩을 덜어 내도 저울은 수평이에요.","왼쪽엔 노란 뚜껑 1개, 오른쪽엔 파란 뚜껑 6 − 3 = 3개가 남아요.","그래서 노란 뚜껑 1개는 파란 뚜껑 3개와 같아요."]},{"stem":"저울에서 파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 7개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?","options":[{"t":"5개","correct":true},{"t":"2개","mis":"M6-1-u1-X13"},{"t":"7개","mis":"M6-1-u1-X13"},{"t":"9개","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 뚜껑 2개씩을 덜어 내도 저울은 수평이에요.","왼쪽엔 노란 뚜껑 1개, 오른쪽엔 파란 뚜껑 7 − 2 = 5개가 남아요.","그래서 노란 뚜껑 1개는 파란 뚜껑 5개와 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#9','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C1',2,'mc','auto','과자 반죽 3개를 7명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 과자 반죽을 구하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u1-X14']::text[],true,'{"seq":9,"concept":"M6-1-u1-C1","difficulty":2,"kind":"mc","stem":"과자 반죽 3개를 7명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 과자 반죽을 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"3 ÷ 7","correct":true},{"t":"7 ÷ 3","mis":"M6-1-u1-X14"},{"t":"3 × 7","mis":"M6-1-u1-X14"},{"t":"3 + 7","mis":"M6-1-u1-X14"}],"explanation":["전체 3개를 7로 똑같이 나누는 거예요.","나누어지는 수 3이 앞, 나누는 수 7이 뒤에 와요.","그래서 식은 3 ÷ 7이에요."],"variant_rule":{"alt":[{"stem":"피자 4판을 9명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 피자를 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"4 ÷ 9","correct":true},{"t":"9 ÷ 4","mis":"M6-1-u1-X14"},{"t":"4 × 9","mis":"M6-1-u1-X14"},{"t":"4 + 9","mis":"M6-1-u1-X14"}],"explanation":["전체 4판을 9로 똑같이 나누는 거예요.","나누어지는 수 4가 앞, 나누는 수 9가 뒤에 와요.","그래서 식은 4 ÷ 9예요."]},{"stem":"흰 종이 3장을 8명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 흰 종이를 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"3 ÷ 8","correct":true},{"t":"8 ÷ 3","mis":"M6-1-u1-X14"},{"t":"3 × 8","mis":"M6-1-u1-X14"},{"t":"3 + 8","mis":"M6-1-u1-X14"}],"explanation":["전체 3장을 8로 똑같이 나누는 거예요.","나누어지는 수 3이 앞, 나누는 수 8이 뒤에 와요.","그래서 식은 3 ÷ 8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#10','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C3',2,'mc','auto','빵 9개를 4명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 빵을 대분수로 나타내면 몇 개인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X02','M6-1-u1-X04']::text[],true,'{"seq":10,"concept":"M6-1-u1-C3","difficulty":2,"kind":"mc","stem":"빵 9개를 4명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 빵을 대분수로 나타내면 몇 개인가요?","options":[{"t":"⟨2 1/4⟩","correct":true},{"t":"⟨4/9⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/4⟩","mis":"M6-1-u1-X02"},{"t":"⟨2 1/9⟩","mis":"M6-1-u1-X04"}],"explanation":["먼저 2씩 나누어 주면 1이 남아요 — 9 ÷ 4는 몫 2, 나머지 1이에요.","남은 1도 4로 똑같이 나누면 ⟨1/4⟩씩 더 가져요.","9 ÷ 4 = ⟨2 1/4⟩ — ⟨2 1/4⟩개예요."],"variant_rule":{"alt":[{"stem":"시루떡 7개를 2명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 시루떡을 대분수로 나타내면 몇 개인가요?","options":[{"t":"⟨3 1/2⟩","correct":true},{"t":"⟨2/7⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/2⟩","mis":"M6-1-u1-X02"},{"t":"⟨3 1/7⟩","mis":"M6-1-u1-X04"}],"explanation":["먼저 3씩 나누어 주면 1이 남아요 — 7 ÷ 2는 몫 3, 나머지 1이에요.","남은 1도 2로 똑같이 나누면 ⟨1/2⟩씩 더 가져요.","7 ÷ 2 = ⟨3 1/2⟩ — ⟨3 1/2⟩개예요."]},{"stem":"피자 8판을 3명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 피자를 대분수로 나타내면 몇 판인가요?","options":[{"t":"⟨2 2/3⟩","correct":true},{"t":"⟨3/8⟩","mis":"M6-1-u1-X01"},{"t":"⟨2/3⟩","mis":"M6-1-u1-X02"},{"t":"⟨2 1/4⟩","mis":"M6-1-u1-X04"}],"explanation":["먼저 2씩 나누어 주면 2가 남아요 — 8 ÷ 3은 몫 2, 나머지 2예요.","남은 2도 3으로 똑같이 나누면 ⟨2/3⟩씩 더 가져요.","8 ÷ 3 = ⟨2 2/3⟩ — ⟨2 2/3⟩판예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#11','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C4',2,'sa','auto','10 ÷ 3 = 10 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M6-1-u1-C4","difficulty":2,"kind":"sa","stem":"10 ÷ 3 = 10 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["÷ 3은 3으로 나눈 것 중의 1이에요.","그래서 ⟨1/3⟩을 곱하는 것과 같아요.","10 ÷ 3 = 10 × ⟨1/3⟩ — □는 3이에요."],"mis":"M6-1-u1-X07","variant_rule":{"alt":[{"stem":"4 ÷ 13 = 4 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["÷ 13은 13으로 나눈 것 중의 1이에요.","그래서 ⟨1/13⟩을 곱하는 것과 같아요.","4 ÷ 13 = 4 × ⟨1/13⟩ — □는 13이에요."]},{"stem":"12 ÷ 5 = 12 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["÷ 5는 5로 나눈 것 중의 1이에요.","그래서 ⟨1/5⟩을 곱하는 것과 같아요.","12 ÷ 5 = 12 × ⟨1/5⟩ — □는 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#12','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C5',2,'sa','auto','⟨10/11⟩ ÷ 2의 몫은 ⟨1/11⟩이 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M6-1-u1-C5","difficulty":2,"kind":"sa","stem":"⟨10/11⟩ ÷ 2의 몫은 ⟨1/11⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["⟨10/11⟩은 ⟨1/11⟩이 10개예요.","10개를 2로 똑같이 나누면 10 ÷ 2 = 5개예요.","⟨10/11⟩ ÷ 2 = ⟨5/11⟩ — ⟨1/11⟩이 5개예요."],"mis":"M6-1-u1-X08","variant_rule":{"alt":[{"stem":"⟨9/13⟩ ÷ 3의 몫은 ⟨1/13⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨9/13⟩는 ⟨1/13⟩이 9개예요.","9개를 3으로 똑같이 나누면 9 ÷ 3 = 3개예요.","⟨9/13⟩ ÷ 3 = ⟨3/13⟩ — ⟨1/13⟩이 3개예요."]},{"stem":"⟨12/13⟩ ÷ 4의 몫은 ⟨1/13⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨12/13⟩는 ⟨1/13⟩이 12개예요.","12개를 4로 똑같이 나누면 12 ÷ 4 = 3개예요.","⟨12/13⟩ ÷ 4 = ⟨3/13⟩ — ⟨1/13⟩이 3개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#13','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C5',2,'mc','auto','⟨7/10⟩ ÷ 2를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X07']::text[],true,'{"seq":13,"concept":"M6-1-u1-C5","difficulty":2,"kind":"mc","stem":"⟨7/10⟩ ÷ 2를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨7/10⟩ × ⟨1/2⟩","correct":true},{"t":"⟨7/10⟩ × 2","mis":"M6-1-u1-X06"},{"t":"⟨10/7⟩ × ⟨1/2⟩","mis":"M6-1-u1-X07"},{"t":"2 × ⟨7/10⟩","mis":"M6-1-u1-X06"}],"explanation":["÷ 2는 2로 똑같이 나눈 것 중의 1이에요.","그래서 × ⟨1/2⟩과 같아요.","⟨7/10⟩ ÷ 2 = ⟨7/10⟩ × ⟨1/2⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨1/6⟩ ÷ 3을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨1/6⟩ × ⟨1/3⟩","correct":true},{"t":"⟨1/6⟩ × 3","mis":"M6-1-u1-X06"},{"t":"⟨6/1⟩ × ⟨1/3⟩","mis":"M6-1-u1-X07"},{"t":"3 × ⟨1/6⟩","mis":"M6-1-u1-X06"}],"explanation":["÷ 3은 3으로 똑같이 나눈 것 중의 1이에요.","그래서 × ⟨1/3⟩과 같아요.","⟨1/6⟩ ÷ 3 = ⟨1/6⟩ × ⟨1/3⟩이에요."]},{"stem":"⟨5/12⟩ ÷ 7을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨5/12⟩ × ⟨1/7⟩","correct":true},{"t":"⟨5/12⟩ × 7","mis":"M6-1-u1-X06"},{"t":"⟨12/5⟩ × ⟨1/7⟩","mis":"M6-1-u1-X07"},{"t":"7 × ⟨5/12⟩","mis":"M6-1-u1-X06"}],"explanation":["÷ 7은 7로 똑같이 나눈 것 중의 1이에요.","그래서 × ⟨1/7⟩과 같아요.","⟨5/12⟩ ÷ 7 = ⟨5/12⟩ × ⟨1/7⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#14','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C6',2,'mc','auto','⟨2 1/3⟩ ÷ 7을 계산하면 얼마인가요?',ARRAY['M6-1-u1-X10','M6-1-u1-X06']::text[],true,'{"seq":14,"concept":"M6-1-u1-C6","difficulty":2,"kind":"mc","stem":"⟨2 1/3⟩ ÷ 7을 계산하면 얼마인가요?","options":[{"t":"⟨1/3⟩","correct":true},{"t":"⟨2 1/21⟩","mis":"M6-1-u1-X10"},{"t":"⟨13/21⟩","mis":"M6-1-u1-X10"},{"t":"⟨16 1/3⟩","mis":"M6-1-u1-X06"}],"explanation":["⟨2 1/3⟩을 가분수로 고치면 ⟨7/3⟩이에요.","⟨7/3⟩ ÷ 7 = ⟨7/3⟩ × ⟨1/7⟩이에요.","⟨7/3⟩ × ⟨1/7⟩ = ⟨1/3⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨3 3/5⟩ ÷ 6을 계산하면 얼마인가요?","options":[{"t":"⟨3/5⟩","correct":true},{"t":"⟨3 1/10⟩","mis":"M6-1-u1-X10"},{"t":"⟨1 1/10⟩","mis":"M6-1-u1-X10"},{"t":"⟨21 3/5⟩","mis":"M6-1-u1-X06"}],"explanation":["⟨3 3/5⟩을 가분수로 고치면 ⟨18/5⟩이에요.","⟨18/5⟩ ÷ 6 = ⟨18/5⟩ × ⟨1/6⟩이에요.","⟨18/5⟩ × ⟨1/6⟩ = ⟨3/5⟩이에요."]},{"stem":"⟨1 4/5⟩ ÷ 3을 계산하면 얼마인가요?","options":[{"t":"⟨3/5⟩","correct":true},{"t":"⟨1 4/15⟩","mis":"M6-1-u1-X10"},{"t":"⟨1 2/15⟩","mis":"M6-1-u1-X10"},{"t":"⟨5 2/5⟩","mis":"M6-1-u1-X06"}],"explanation":["⟨1 4/5⟩를 가분수로 고치면 ⟨9/5⟩예요.","⟨9/5⟩ ÷ 3 = ⟨9/5⟩ × ⟨1/3⟩이에요.","⟨9/5⟩ × ⟨1/3⟩ = ⟨3/5⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#15','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C6',2,'sa','auto','⟨3 4/5⟩ ÷ 2를 계산하려고 ⟨3 4/5⟩를 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":15,"concept":"M6-1-u1-C6","difficulty":2,"kind":"sa","stem":"⟨3 4/5⟩ ÷ 2를 계산하려고 ⟨3 4/5⟩를 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["대분수는 먼저 가분수로 고쳐요.","3 × 5 + 4 = 19예요.","⟨3 4/5⟩ = ⟨19/5⟩ — 분자는 19예요."],"mis":"M6-1-u1-X05","variant_rule":{"alt":[{"stem":"⟨1 7/9⟩ ÷ 4를 계산하려고 ⟨1 7/9⟩을 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["대분수는 먼저 가분수로 고쳐요.","1 × 9 + 7 = 16이에요.","⟨1 7/9⟩ = ⟨16/9⟩ — 분자는 16이에요."]},{"stem":"⟨4 3/7⟩ ÷ 6을 계산하려고 ⟨4 3/7⟩을 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["31"],"explanation":["대분수는 먼저 가분수로 고쳐요.","4 × 7 + 3 = 31이에요.","⟨4 3/7⟩ = ⟨31/7⟩ — 분자는 31이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#16','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C7',2,'mc','auto','파란 뚜껑 1개와 노란 뚜껑 1개의 무게가 파란 뚜껑 3개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨2 2/3⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?',ARRAY['M6-1-u1-X13','M6-1-u1-X06']::text[],true,'{"seq":16,"concept":"M6-1-u1-C7","difficulty":2,"kind":"mc","stem":"파란 뚜껑 1개와 노란 뚜껑 1개의 무게가 파란 뚜껑 3개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨2 2/3⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?","options":[{"t":"⟨1 1/3⟩","correct":true},{"t":"⟨8/9⟩","mis":"M6-1-u1-X13"},{"t":"⟨2 2/3⟩","mis":"M6-1-u1-X13"},{"t":"⟨5 1/3⟩","mis":"M6-1-u1-X06"}],"explanation":["양쪽에서 파란 1개씩 덜어 내면 노란 1개 = 파란 2개예요.","⟨2 2/3⟩ = ⟨8/3⟩이에요.","⟨8/3⟩ × ⟨1/2⟩ = ⟨1 1/3⟩ — 파란 뚜껑 1개는 ⟨1 1/3⟩ g이에요."],"variant_rule":{"alt":[{"stem":"파란 뚜껑 3개와 노란 뚜껑 1개의 무게가 파란 뚜껑 7개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨6 2/3⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?","options":[{"t":"⟨1 2/3⟩","correct":true},{"t":"⟨20/21⟩","mis":"M6-1-u1-X13"},{"t":"⟨2 2/9⟩","mis":"M6-1-u1-X13"},{"t":"⟨26 2/3⟩","mis":"M6-1-u1-X06"}],"explanation":["양쪽에서 파란 3개씩 덜어 내면 노란 1개 = 파란 4개예요.","⟨6 2/3⟩ = ⟨20/3⟩이에요.","⟨20/3⟩ × ⟨1/4⟩ = ⟨1 2/3⟩ — 파란 뚜껑 1개는 ⟨1 2/3⟩ g이에요."]},{"stem":"파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 4개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨3 1/5⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?","options":[{"t":"⟨1 3/5⟩","correct":true},{"t":"⟨4/5⟩","mis":"M6-1-u1-X13"},{"t":"⟨6 2/5⟩","mis":"M6-1-u1-X06"},{"t":"⟨8/15⟩","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 2개씩 덜어 내면 노란 1개 = 파란 2개예요.","⟨3 1/5⟩ = ⟨16/5⟩이에요.","⟨16/5⟩ × ⟨1/2⟩ = ⟨1 3/5⟩ — 파란 뚜껑 1개는 ⟨1 3/5⟩ g이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#17','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C2',3,'mc','auto','가 모둠은 주스 4 L를 9명이, 나 모둠은 주스 3 L를 8명이 똑같이 나누었어요. 한 명이 가지는 주스가 더 많은 모둠은 어디인가요?',ARRAY['M6-1-u1-X11','M6-1-u1-X03']::text[],true,'{"seq":17,"concept":"M6-1-u1-C2","difficulty":3,"kind":"mc","stem":"가 모둠은 주스 4 L를 9명이, 나 모둠은 주스 3 L를 8명이 똑같이 나누었어요. 한 명이 가지는 주스가 더 많은 모둠은 어디인가요?","options":[{"t":"가 모둠","correct":true},{"t":"나 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 4 ÷ 9 = ⟨4/9⟩, 나 모둠은 3 ÷ 8 = ⟨3/8⟩이에요.","72로 통분하면 ⟨4/9⟩ = ⟨32/72⟩, ⟨3/8⟩ = ⟨27/72⟩이에요.","⟨4/9⟩ > ⟨3/8⟩이라 가 모둠이 더 많아요."],"variant_rule":{"alt":[{"stem":"가 모둠은 빵 5개를 7명이, 나 모둠은 빵 3개를 4명이 똑같이 나누었어요. 한 명이 가지는 빵이 더 많은 모둠은 어디인가요?","options":[{"t":"나 모둠","correct":true},{"t":"가 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 5 ÷ 7 = ⟨5/7⟩, 나 모둠은 3 ÷ 4 = ⟨3/4⟩이에요.","28로 통분하면 ⟨5/7⟩ = ⟨20/28⟩, ⟨3/4⟩ = ⟨21/28⟩이에요.","⟨5/7⟩ < ⟨3/4⟩이라 나 모둠이 더 많아요."]},{"stem":"가 모둠은 피자 3판을 5명이, 나 모둠은 피자 5판을 8명이 똑같이 나누었어요. 한 명이 가지는 피자가 더 많은 모둠은 어디인가요?","options":[{"t":"나 모둠","correct":true},{"t":"가 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 3 ÷ 5 = ⟨3/5⟩, 나 모둠은 5 ÷ 8 = ⟨5/8⟩예요.","40으로 통분하면 ⟨3/5⟩ = ⟨24/40⟩, ⟨5/8⟩ = ⟨25/40⟩예요.","⟨3/5⟩ < ⟨5/8⟩라 나 모둠이 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#18','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C3',3,'sa','auto','끈 17 m를 6도막으로 똑같이 나누어 자르려고 해요. 한 도막의 길이를 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M6-1-u1-C3","difficulty":3,"kind":"sa","stem":"끈 17 m를 6도막으로 똑같이 나누어 자르려고 해요. 한 도막의 길이를 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["17 ÷ 6은 몫 2, 나머지 5예요.","남은 5도 나누면 17 ÷ 6 = ⟨2 5/6⟩예요.","자연수 부분과 분자의 합은 2 + 5 = 7이에요."],"mis":"M6-1-u1-X15","variant_rule":{"alt":[{"stem":"색 모래 25 kg을 7모둠이 똑같이 나누어 가지려고 해요. 한 모둠이 가지는 색 모래를 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["25 ÷ 7은 몫 3, 나머지 4예요.","남은 4도 나누면 25 ÷ 7 = ⟨3 4/7⟩예요.","자연수 부분과 분자의 합은 3 + 4 = 7이에요."]},{"stem":"주스 13 L를 3명이 똑같이 나누어 마시려고 해요. 한 명이 마시는 주스를 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["13 ÷ 3은 몫 4, 나머지 1이에요.","남은 1도 나누면 13 ÷ 3 = ⟨4 1/3⟩이에요.","자연수 부분과 분자의 합은 4 + 1 = 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#19','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C4',3,'mc','auto','끈 6 m를 5도막으로 나눈 한 도막과 끈 5 m를 4도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?',ARRAY['M6-1-u1-X11','M6-1-u1-X03']::text[],true,'{"seq":19,"concept":"M6-1-u1-C4","difficulty":3,"kind":"mc","stem":"끈 6 m를 5도막으로 나눈 한 도막과 끈 5 m를 4도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?","options":[{"t":"끈 5 m를 4도막으로 나눈 한 도막","correct":true},{"t":"끈 6 m를 5도막으로 나눈 한 도막","mis":"M6-1-u1-X11"},{"t":"두 도막의 길이가 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["6 ÷ 5 = 6 × ⟨1/5⟩ = ⟨1 1/5⟩, 5 ÷ 4 = 5 × ⟨1/4⟩ = ⟨1 1/4⟩이에요.","20으로 통분하면 ⟨1 1/5⟩ = ⟨24/20⟩, ⟨1 1/4⟩ = ⟨25/20⟩예요.","그래서 더 긴 것은 끈 5 m를 4도막으로 나눈 한 도막이에요."],"variant_rule":{"alt":[{"stem":"끈 10 m를 3도막으로 나눈 한 도막과 끈 13 m를 4도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?","options":[{"t":"끈 10 m를 3도막으로 나눈 한 도막","correct":true},{"t":"끈 13 m를 4도막으로 나눈 한 도막","mis":"M6-1-u1-X11"},{"t":"두 도막의 길이가 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["10 ÷ 3 = 10 × ⟨1/3⟩ = ⟨3 1/3⟩, 13 ÷ 4 = 13 × ⟨1/4⟩ = ⟨3 1/4⟩이에요.","12로 통분하면 ⟨3 1/3⟩ = ⟨40/12⟩, ⟨3 1/4⟩ = ⟨39/12⟩예요.","그래서 더 긴 것은 끈 10 m를 3도막으로 나눈 한 도막이에요."]},{"stem":"끈 8 m를 7도막으로 나눈 한 도막과 끈 9 m를 8도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?","options":[{"t":"끈 8 m를 7도막으로 나눈 한 도막","correct":true},{"t":"끈 9 m를 8도막으로 나눈 한 도막","mis":"M6-1-u1-X11"},{"t":"두 도막의 길이가 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["8 ÷ 7 = 8 × ⟨1/7⟩ = ⟨1 1/7⟩, 9 ÷ 8 = 9 × ⟨1/8⟩ = ⟨1 1/8⟩이에요.","56으로 통분하면 ⟨1 1/7⟩ = ⟨64/56⟩, ⟨1 1/8⟩ = ⟨63/56⟩이에요.","그래서 더 긴 것은 끈 8 m를 7도막으로 나눈 한 도막이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#20','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C5',3,'error','auto','⟨5/6⟩ ÷ 2에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X15']::text[],true,'{"seq":20,"concept":"M6-1-u1-C5","difficulty":3,"kind":"error","stem":"⟨5/6⟩ ÷ 2에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민준 — 「⟨5/6⟩ × 2 = ⟨1 2/3⟩로 계산해.」","correct":true,"mis_target":"M6-1-u1-X06"},{"t":"서연 — 「⟨5/6⟩ × ⟨1/2⟩로 바꾸어 계산하면 돼.」","mis":"M6-1-u1-X15"},{"t":"지호 — 「몫은 ⟨5/6⟩보다 작아.」","mis":"M6-1-u1-X15"}],"explanation":["2로 나누면 양이 작아져야 해요.","⟨5/6⟩ × 2 = ⟨1 2/3⟩는 오히려 커요.","⟨5/6⟩ ÷ 2 = ⟨5/6⟩ × ⟨1/2⟩ = ⟨5/12⟩ — 민준은 나누는 수를 그대로 곱했어요."],"variant_rule":{"alt":[{"stem":"⟨3/10⟩ ÷ 4에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「⟨3/10⟩ × 4 = ⟨1 1/5⟩로 계산해.」","correct":true,"mis_target":"M6-1-u1-X06"},{"t":"나린 — 「⟨3/10⟩ × ⟨1/4⟩로 바꾸어 계산하면 돼.」","mis":"M6-1-u1-X15"},{"t":"유진 — 「몫은 ⟨3/10⟩보다 작아.」","mis":"M6-1-u1-X15"}],"explanation":["4로 나누면 양이 작아져야 해요.","⟨3/10⟩ × 4 = ⟨1 1/5⟩은 오히려 커요.","⟨3/10⟩ ÷ 4 = ⟨3/10⟩ × ⟨1/4⟩ = ⟨3/40⟩ — 가온은 나누는 수를 그대로 곱했어요."]},{"stem":"⟨7/8⟩ ÷ 2에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「⟨7/8⟩ × 2 = ⟨1 3/4⟩으로 계산해.」","correct":true,"mis_target":"M6-1-u1-X06"},{"t":"라온 — 「⟨7/8⟩ × ⟨1/2⟩로 바꾸어 계산하면 돼.」","mis":"M6-1-u1-X15"},{"t":"예준 — 「몫은 ⟨7/8⟩보다 작아.」","mis":"M6-1-u1-X15"}],"explanation":["2로 나누면 양이 작아져야 해요.","⟨7/8⟩ × 2 = ⟨1 3/4⟩은 오히려 커요.","⟨7/8⟩ ÷ 2 = ⟨7/8⟩ × ⟨1/2⟩ = ⟨7/16⟩ — 여울은 나누는 수를 그대로 곱했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#21','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C6',3,'mc','auto','넓이가 ⟨5 1/4⟩ m²이고 가로가 2 m인 직사각형이 있어요. 세로는 몇 m인가요?',ARRAY['M6-1-u1-X10','M6-1-u1-X06']::text[],true,'{"seq":21,"concept":"M6-1-u1-C6","difficulty":3,"kind":"mc","stem":"넓이가 ⟨5 1/4⟩ m²이고 가로가 2 m인 직사각형이 있어요. 세로는 몇 m인가요?","options":[{"t":"⟨2 5/8⟩","correct":true},{"t":"⟨5 1/8⟩","mis":"M6-1-u1-X10"},{"t":"⟨2 3/4⟩","mis":"M6-1-u1-X10"},{"t":"⟨10 1/2⟩","mis":"M6-1-u1-X06"}],"explanation":["(직사각형의 넓이) = (가로) × (세로)이니 세로 = 넓이 ÷ 가로예요.","⟨5 1/4⟩ ÷ 2 = ⟨21/4⟩ × ⟨1/2⟩이에요.","⟨21/4⟩ × ⟨1/2⟩ = ⟨2 5/8⟩ — 세로는 ⟨2 5/8⟩ m예요."],"variant_rule":{"alt":[{"stem":"넓이가 ⟨3 3/5⟩ m²이고 가로가 4 m인 직사각형이 있어요. 세로는 몇 m인가요?","options":[{"t":"⟨9/10⟩","correct":true},{"t":"⟨3 3/20⟩","mis":"M6-1-u1-X10"},{"t":"⟨1 7/20⟩","mis":"M6-1-u1-X10"},{"t":"⟨14 2/5⟩","mis":"M6-1-u1-X06"}],"explanation":["(직사각형의 넓이) = (가로) × (세로)이니 세로 = 넓이 ÷ 가로예요.","⟨3 3/5⟩ ÷ 4 = ⟨18/5⟩ × ⟨1/4⟩이에요.","⟨18/5⟩ × ⟨1/4⟩ = ⟨9/10⟩ — 세로는 ⟨9/10⟩ m예요."]},{"stem":"넓이가 ⟨6 2/3⟩ m²이고 가로가 5 m인 직사각형이 있어요. 세로는 몇 m인가요?","options":[{"t":"⟨1 1/3⟩","correct":true},{"t":"⟨6 2/15⟩","mis":"M6-1-u1-X10"},{"t":"⟨1 13/15⟩","mis":"M6-1-u1-X10"},{"t":"⟨33 1/3⟩","mis":"M6-1-u1-X06"}],"explanation":["(직사각형의 넓이) = (가로) × (세로)이니 세로 = 넓이 ÷ 가로예요.","⟨6 2/3⟩ ÷ 5 = ⟨20/3⟩ × ⟨1/5⟩이에요.","⟨20/3⟩ × ⟨1/5⟩ = ⟨1 1/3⟩ — 세로는 ⟨1 1/3⟩ m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#22','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C7',3,'sa','auto','조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨3 3/4⟩ g이고 파란 뚜껑 5개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M6-1-u1-C7","difficulty":3,"kind":"sa","stem":"조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨3 3/4⟩ g이고 파란 뚜껑 5개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["파란 뚜껑 1개 = ⟨3 3/4⟩ ÷ 5예요.","⟨15/4⟩ ÷ 5 = ⟨15/4⟩ × ⟨1/5⟩ = ⟨3/4⟩이에요.","분모와 분자의 합은 4 + 3 = 7이에요."],"mis":"M6-1-u1-X15","variant_rule":{"alt":[{"stem":"조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨4 4/5⟩ g이고 파란 뚜껑 6개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["파란 뚜껑 1개 = ⟨4 4/5⟩ ÷ 6이에요.","⟨24/5⟩ ÷ 6 = ⟨24/5⟩ × ⟨1/6⟩ = ⟨4/5⟩예요.","분모와 분자의 합은 5 + 4 = 9예요."]},{"stem":"조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨1 5/7⟩ g이고 파란 뚜껑 4개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["파란 뚜껑 1개 = ⟨1 5/7⟩ ÷ 4예요.","⟨12/7⟩ ÷ 4 = ⟨12/7⟩ × ⟨1/4⟩ = ⟨3/7⟩이에요.","분모와 분자의 합은 7 + 3 = 10이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#23','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C3',4,'sa','auto','□ ÷ 7의 몫이 3보다 크고 4보다 작을 때, □에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M6-1-u1-C3","difficulty":4,"kind":"sa","stem":"□ ÷ 7의 몫이 3보다 크고 4보다 작을 때, □에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["21 ÷ 7 = 3, 28 ÷ 7 = 4예요.","□는 21보다 크고 28보다 작아야 해요.","22부터 27까지 6개예요."],"mis":"M6-1-u1-X03","variant_rule":{"alt":[{"stem":"⟨9/13⟩ ÷ □의 몫이 ⟨1/13⟩보다 클 때, □에 들어갈 수 있는 가장 큰 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["⟨9/13⟩는 ⟨1/13⟩이 9개예요.","□로 나눈 몫이 ⟨1/13⟩보다 크려면 9개를 □로 나눈 수가 1보다 커야 해요.","□는 9보다 작아야 하니 가장 큰 수는 8이에요."]},{"stem":"자연수 부분이 □이고 분수 부분이 ⟨2/5⟩인 대분수를 4로 나누었더니 ⟨17/20⟩이 되었어요. □에 알맞은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["나누기 전의 수는 ⟨17/20⟩ × 4예요.","⟨17/20⟩ × 4 = ⟨17/5⟩ = ⟨3 2/5⟩예요.","그래서 □는 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#24','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C3',4,'essay','teacher','13 ÷ 5의 몫을 대분수와 가분수로 각각 나타내고, 대분수로 나타내는 과정을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-1-u1-C3","difficulty":4,"kind":"essay","stem":"13 ÷ 5의 몫을 대분수와 가분수로 각각 나타내고, 대분수로 나타내는 과정을 설명해 보세요.","answer_guide":{"answer":"예: 13 ÷ 5는 몫 2, 나머지 3이다. 남은 3을 5로 나누면 ⟨3/5⟩이므로 대분수로 ⟨2 3/5⟩이다. 나누어지는 수를 분자, 나누는 수를 분모로 하면 가분수 ⟨13/5⟩이고, ⟨13/5⟩ = ⟨2 3/5⟩으로 같은 수이다.","scoring_points":["몫 2, 나머지 3을 구했는가","대분수 ⟨2 3/5⟩을 구했는가","가분수 ⟨13/5⟩을 쓰고 같은 수라고 했는가"]},"explanation":["13 ÷ 5는 몫 2, 나머지 3이에요.","남은 3을 5로 나누면 ⟨2 3/5⟩이에요.","가분수로는 ⟨13/5⟩ — 같은 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_b#25','math',6,1,'u1','','g6_1_math_u1_review_b','unit_review','M6-1-u1-C6',4,'essay','teacher','넓이가 ⟨5 3/4⟩ m²이고 가로가 2 m인 직사각형의 세로를 구하는 식을 세우고, 계산 과정을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"M6-1-u1-C6","difficulty":4,"kind":"essay","stem":"넓이가 ⟨5 3/4⟩ m²이고 가로가 2 m인 직사각형의 세로를 구하는 식을 세우고, 계산 과정을 쓰세요.","answer_guide":{"answer":"예: 직사각형의 넓이는 가로 × 세로이므로 세로 = 넓이 ÷ 가로 = ⟨5 3/4⟩ ÷ 2이다. ⟨5 3/4⟩ = ⟨23/4⟩이므로 ⟨23/4⟩ × ⟨1/2⟩ = ⟨23/8⟩ = ⟨2 7/8⟩ m이다.","scoring_points":["세로 = 넓이 ÷ 가로로 식을 세웠는가","⟨5 3/4⟩ = ⟨23/4⟩으로 고쳤는가","⟨2 7/8⟩ m를 구했는가"]},"explanation":["세로 = 넓이 ÷ 가로예요.","⟨5 3/4⟩ = ⟨23/4⟩이에요.","⟨23/4⟩ × ⟨1/2⟩ = ⟨2 7/8⟩ m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#1','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C2',1,'mc','auto','주스 3 L를 7명이 똑같이 나누어 마시려고 해요. 한 명이 마시는 주스는 몇 L인지 분수로 나타내면 얼마인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X09']::text[],true,'{"seq":1,"concept":"M6-1-u1-C2","difficulty":1,"kind":"mc","stem":"주스 3 L를 7명이 똑같이 나누어 마시려고 해요. 한 명이 마시는 주스는 몇 L인지 분수로 나타내면 얼마인가요?","options":[{"t":"⟨3/7⟩","correct":true},{"t":"⟨2 1/3⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/7⟩","mis":"M6-1-u1-X01"},{"t":"⟨3/10⟩","mis":"M6-1-u1-X09"}],"explanation":["주스 3 L를 7로 똑같이 나누는 것은 3 ÷ 7이에요.","나누어지는 수 3은 분자, 나누는 수 7은 분모가 돼요.","3 ÷ 7 = ⟨3/7⟩ — ⟨3/7⟩ L예요."],"variant_rule":{"alt":[{"stem":"식빵 1개를 3명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 식빵은 몇 개인지 분수로 나타내면 얼마인가요?","options":[{"t":"⟨1/3⟩","correct":true},{"t":"3","mis":"M6-1-u1-X01"},{"t":"⟨1/4⟩","mis":"M6-1-u1-X09"},{"t":"1","mis":"M6-1-u1-X01"}],"explanation":["식빵 1개를 3으로 똑같이 나누는 것은 1 ÷ 3이에요.","나누어지는 수 1은 분자, 나누는 수 3은 분모가 돼요.","1 ÷ 3 = ⟨1/3⟩ — ⟨1/3⟩개예요."]},{"stem":"시루떡 3개를 4명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 시루떡은 몇 개인지 분수로 나타내면 얼마인가요?","options":[{"t":"⟨3/4⟩","correct":true},{"t":"⟨1 1/3⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/4⟩","mis":"M6-1-u1-X01"},{"t":"⟨3/7⟩","mis":"M6-1-u1-X09"}],"explanation":["시루떡 3개를 4로 똑같이 나누는 것은 3 ÷ 4예요.","나누어지는 수 3은 분자, 나누는 수 4는 분모가 돼요.","3 ÷ 4 = ⟨3/4⟩ — ⟨3/4⟩개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#2','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C2',1,'sa','auto','2 ÷ 11의 몫을 분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u1-C2","difficulty":1,"kind":"sa","stem":"2 ÷ 11의 몫을 분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["(자연수)÷(자연수)의 몫은 분수로 나타낼 수 있어요.","나누어지는 수 2는 분자, 나누는 수 11은 분모예요.","2 ÷ 11 = ⟨2/11⟩니 분자는 2예요."],"mis":"M6-1-u1-X01","variant_rule":{"alt":[{"stem":"6 ÷ 13의 몫을 분수로 나타낼 때 분모에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["(자연수)÷(자연수)의 몫은 분수로 나타낼 수 있어요.","나누어지는 수 6은 분자, 나누는 수 13은 분모예요.","6 ÷ 13 = ⟨6/13⟩이니 분모는 13이에요."]},{"stem":"4 ÷ 7의 몫을 분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["(자연수)÷(자연수)의 몫은 분수로 나타낼 수 있어요.","나누어지는 수 4는 분자, 나누는 수 7은 분모예요.","4 ÷ 7 = ⟨4/7⟩니 분자는 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#3','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C3',1,'mc','auto','⟨3 1/3⟩을 가분수로 나타내면 어느 것인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X05']::text[],true,'{"seq":3,"concept":"M6-1-u1-C3","difficulty":1,"kind":"mc","stem":"⟨3 1/3⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨10/3⟩","correct":true},{"t":"⟨3/10⟩","mis":"M6-1-u1-X01"},{"t":"⟨4/3⟩","mis":"M6-1-u1-X05"},{"t":"⟨3/3⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 3은 ⟨9/3⟩예요 — 3 × 3 = 9.","여기에 ⟨1/3⟩을 더하면 분자는 9 + 1 = 10이에요.","⟨3 1/3⟩ = ⟨10/3⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨2 5/6⟩를 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨17/6⟩","correct":true},{"t":"⟨6/17⟩","mis":"M6-1-u1-X01"},{"t":"⟨7/6⟩","mis":"M6-1-u1-X05"},{"t":"⟨10/6⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 2는 ⟨12/6⟩예요 — 2 × 6 = 12.","여기에 ⟨5/6⟩를 더하면 분자는 12 + 5 = 17이에요.","⟨2 5/6⟩ = ⟨17/6⟩이에요."]},{"stem":"⟨1 3/4⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨7/4⟩","correct":true},{"t":"⟨4/7⟩","mis":"M6-1-u1-X01"},{"t":"⟨4/4⟩","mis":"M6-1-u1-X05"},{"t":"⟨3/4⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 1은 ⟨4/4⟩예요 — 1 × 4 = 4.","여기에 ⟨3/4⟩을 더하면 분자는 4 + 3 = 7이에요.","⟨1 3/4⟩ = ⟨7/4⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#4','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C3',1,'sa','auto','19 ÷ 5의 몫을 대분수로 나타낼 때 자연수 부분에 오는 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u1-C3","difficulty":1,"kind":"sa","stem":"19 ÷ 5의 몫을 대분수로 나타낼 때 자연수 부분에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["19 ÷ 5는 몫 3, 나머지 4예요.","남은 4도 5로 나누면 ⟨4/5⟩ — 몫은 ⟨3 4/5⟩예요.","그래서 자연수 부분은 3이에요."],"mis":"M6-1-u1-X04","variant_rule":{"alt":[{"stem":"23 ÷ 7의 몫을 대분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["23 ÷ 7은 몫 3, 나머지 2예요.","남은 2도 7로 나누면 ⟨2/7⟩ — 몫은 ⟨3 2/7⟩예요.","그래서 분자는 2예요."]},{"stem":"15 ÷ 4의 몫을 대분수로 나타낼 때 자연수 부분에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["15 ÷ 4는 몫 3, 나머지 3이에요.","남은 3도 4로 나누면 ⟨3/4⟩ — 몫은 ⟨3 3/4⟩이에요.","그래서 자연수 부분은 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#5','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C4',1,'mc','auto','8 ÷ 3을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X07']::text[],true,'{"seq":5,"concept":"M6-1-u1-C4","difficulty":1,"kind":"mc","stem":"8 ÷ 3을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"8 × ⟨1/3⟩","correct":true},{"t":"8 × 3","mis":"M6-1-u1-X06"},{"t":"3 × ⟨1/8⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/8⟩ × ⟨1/3⟩","mis":"M6-1-u1-X07"}],"explanation":["÷ 3은 3으로 똑같이 나눈 것 중의 1이에요.","× ⟨1/3⟩도 3으로 똑같이 나눈 것 중의 1이에요.","그래서 8 ÷ 3 = 8 × ⟨1/3⟩ = ⟨2 2/3⟩예요."],"variant_rule":{"alt":[{"stem":"4 ÷ 11을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"4 × ⟨1/11⟩","correct":true},{"t":"4 × 11","mis":"M6-1-u1-X06"},{"t":"11 × ⟨1/4⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/4⟩ × ⟨1/11⟩","mis":"M6-1-u1-X07"}],"explanation":["÷ 11은 11로 똑같이 나눈 것 중의 1이에요.","× ⟨1/11⟩도 11로 똑같이 나눈 것 중의 1이에요.","그래서 4 ÷ 11 = 4 × ⟨1/11⟩ = ⟨4/11⟩예요."]},{"stem":"6 ÷ 5를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"6 × ⟨1/5⟩","correct":true},{"t":"6 × 5","mis":"M6-1-u1-X06"},{"t":"5 × ⟨1/6⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/6⟩ × ⟨1/5⟩","mis":"M6-1-u1-X07"}],"explanation":["÷ 5는 5로 똑같이 나눈 것 중의 1이에요.","× ⟨1/5⟩도 5로 똑같이 나눈 것 중의 1이에요.","그래서 6 ÷ 5 = 6 × ⟨1/5⟩ = ⟨1 1/5⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#6','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C5',1,'mc','auto','⟨10/13⟩ ÷ 5를 계산하면 얼마인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X09','M6-1-u1-X07']::text[],true,'{"seq":6,"concept":"M6-1-u1-C5","difficulty":1,"kind":"mc","stem":"⟨10/13⟩ ÷ 5를 계산하면 얼마인가요?","options":[{"t":"⟨2/13⟩","correct":true},{"t":"⟨3 11/13⟩","mis":"M6-1-u1-X06"},{"t":"⟨5/9⟩","mis":"M6-1-u1-X09"},{"t":"⟨13/50⟩","mis":"M6-1-u1-X07"}],"explanation":["⟨10/13⟩은 ⟨1/13⟩이 10개예요.","분자 10을 5로 나누면 10 ÷ 5 = 2 — ⟨1/13⟩이 2개예요.","그래서 ⟨10/13⟩ ÷ 5 = ⟨2/13⟩예요."],"variant_rule":{"alt":[{"stem":"⟨9/10⟩ ÷ 3을 계산하면 얼마인가요?","options":[{"t":"⟨3/10⟩","correct":true},{"t":"⟨2 7/10⟩","mis":"M6-1-u1-X06"},{"t":"⟨9/13⟩","mis":"M6-1-u1-X09"},{"t":"⟨10/27⟩","mis":"M6-1-u1-X07"}],"explanation":["⟨9/10⟩는 ⟨1/10⟩이 9개예요.","분자 9를 3으로 나누면 9 ÷ 3 = 3 — ⟨1/10⟩이 3개예요.","그래서 ⟨9/10⟩ ÷ 3 = ⟨3/10⟩이에요."]},{"stem":"⟨6/11⟩ ÷ 3을 계산하면 얼마인가요?","options":[{"t":"⟨2/11⟩","correct":true},{"t":"⟨1 7/11⟩","mis":"M6-1-u1-X06"},{"t":"⟨3/7⟩","mis":"M6-1-u1-X09"},{"t":"⟨11/18⟩","mis":"M6-1-u1-X07"}],"explanation":["⟨6/11⟩은 ⟨1/11⟩이 6개예요.","분자 6을 3으로 나누면 6 ÷ 3 = 2 — ⟨1/11⟩이 2개예요.","그래서 ⟨6/11⟩ ÷ 3 = ⟨2/11⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#7','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C6',1,'mc','auto','⟨2 4/5⟩를 가분수로 나타내면 어느 것인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X05']::text[],true,'{"seq":7,"concept":"M6-1-u1-C6","difficulty":1,"kind":"mc","stem":"⟨2 4/5⟩를 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨14/5⟩","correct":true},{"t":"⟨5/14⟩","mis":"M6-1-u1-X01"},{"t":"⟨6/5⟩","mis":"M6-1-u1-X05"},{"t":"⟨8/5⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 2는 ⟨10/5⟩이에요 — 2 × 5 = 10.","여기에 ⟨4/5⟩를 더하면 분자는 10 + 4 = 14예요.","⟨2 4/5⟩ = ⟨14/5⟩예요."],"variant_rule":{"alt":[{"stem":"⟨4 1/3⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨13/3⟩","correct":true},{"t":"⟨3/13⟩","mis":"M6-1-u1-X01"},{"t":"⟨5/3⟩","mis":"M6-1-u1-X05"},{"t":"⟨4/3⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 4는 ⟨12/3⟩예요 — 4 × 3 = 12.","여기에 ⟨1/3⟩을 더하면 분자는 12 + 1 = 13이에요.","⟨4 1/3⟩ = ⟨13/3⟩이에요."]},{"stem":"⟨1 5/6⟩를 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨11/6⟩","correct":true},{"t":"⟨6/11⟩","mis":"M6-1-u1-X01"},{"t":"⟨6/6⟩","mis":"M6-1-u1-X05"},{"t":"⟨5/6⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 1은 ⟨6/6⟩이에요 — 1 × 6 = 6.","여기에 ⟨5/6⟩를 더하면 분자는 6 + 5 = 11이에요.","⟨1 5/6⟩ = ⟨11/6⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#8','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C7',1,'mc','auto','저울에서 파란 뚜껑 3개와 노란 뚜껑 1개의 무게가 파란 뚜껑 6개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?',ARRAY['M6-1-u1-X13']::text[],true,'{"seq":8,"concept":"M6-1-u1-C7","difficulty":1,"kind":"mc","stem":"저울에서 파란 뚜껑 3개와 노란 뚜껑 1개의 무게가 파란 뚜껑 6개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?","options":[{"t":"3개","correct":true},{"t":"6개","mis":"M6-1-u1-X13"},{"t":"9개","mis":"M6-1-u1-X13"},{"t":"4개","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 뚜껑 3개씩을 덜어 내도 저울은 수평이에요.","왼쪽엔 노란 뚜껑 1개, 오른쪽엔 파란 뚜껑 6 − 3 = 3개가 남아요.","그래서 노란 뚜껑 1개는 파란 뚜껑 3개와 같아요."],"variant_rule":{"alt":[{"stem":"저울에서 파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 7개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?","options":[{"t":"5개","correct":true},{"t":"2개","mis":"M6-1-u1-X13"},{"t":"7개","mis":"M6-1-u1-X13"},{"t":"9개","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 뚜껑 2개씩을 덜어 내도 저울은 수평이에요.","왼쪽엔 노란 뚜껑 1개, 오른쪽엔 파란 뚜껑 7 − 2 = 5개가 남아요.","그래서 노란 뚜껑 1개는 파란 뚜껑 5개와 같아요."]},{"stem":"저울에서 파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 5개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?","options":[{"t":"3개","correct":true},{"t":"2개","mis":"M6-1-u1-X13"},{"t":"5개","mis":"M6-1-u1-X13"},{"t":"7개","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 뚜껑 2개씩을 덜어 내도 저울은 수평이에요.","왼쪽엔 노란 뚜껑 1개, 오른쪽엔 파란 뚜껑 5 − 2 = 3개가 남아요.","그래서 노란 뚜껑 1개는 파란 뚜껑 3개와 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#9','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C1',2,'mc','auto','피자 4판을 9명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 피자를 구하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u1-X14']::text[],true,'{"seq":9,"concept":"M6-1-u1-C1","difficulty":2,"kind":"mc","stem":"피자 4판을 9명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 피자를 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"4 ÷ 9","correct":true},{"t":"9 ÷ 4","mis":"M6-1-u1-X14"},{"t":"4 × 9","mis":"M6-1-u1-X14"},{"t":"4 + 9","mis":"M6-1-u1-X14"}],"explanation":["전체 4판을 9로 똑같이 나누는 거예요.","나누어지는 수 4가 앞, 나누는 수 9가 뒤에 와요.","그래서 식은 4 ÷ 9예요."],"variant_rule":{"alt":[{"stem":"흰 종이 3장을 8명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 흰 종이를 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"3 ÷ 8","correct":true},{"t":"8 ÷ 3","mis":"M6-1-u1-X14"},{"t":"3 × 8","mis":"M6-1-u1-X14"},{"t":"3 + 8","mis":"M6-1-u1-X14"}],"explanation":["전체 3장을 8로 똑같이 나누는 거예요.","나누어지는 수 3이 앞, 나누는 수 8이 뒤에 와요.","그래서 식은 3 ÷ 8이에요."]},{"stem":"시루떡 2개를 5명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 시루떡을 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"2 ÷ 5","correct":true},{"t":"5 ÷ 2","mis":"M6-1-u1-X14"},{"t":"2 × 5","mis":"M6-1-u1-X14"},{"t":"2 + 5","mis":"M6-1-u1-X14"}],"explanation":["전체 2개를 5로 똑같이 나누는 거예요.","나누어지는 수 2가 앞, 나누는 수 5가 뒤에 와요.","그래서 식은 2 ÷ 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#10','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C3',2,'mc','auto','시루떡 7개를 2명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 시루떡을 대분수로 나타내면 몇 개인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X02','M6-1-u1-X04']::text[],true,'{"seq":10,"concept":"M6-1-u1-C3","difficulty":2,"kind":"mc","stem":"시루떡 7개를 2명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 시루떡을 대분수로 나타내면 몇 개인가요?","options":[{"t":"⟨3 1/2⟩","correct":true},{"t":"⟨2/7⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/2⟩","mis":"M6-1-u1-X02"},{"t":"⟨3 1/7⟩","mis":"M6-1-u1-X04"}],"explanation":["먼저 3씩 나누어 주면 1이 남아요 — 7 ÷ 2는 몫 3, 나머지 1이에요.","남은 1도 2로 똑같이 나누면 ⟨1/2⟩씩 더 가져요.","7 ÷ 2 = ⟨3 1/2⟩ — ⟨3 1/2⟩개예요."],"variant_rule":{"alt":[{"stem":"피자 8판을 3명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 피자를 대분수로 나타내면 몇 판인가요?","options":[{"t":"⟨2 2/3⟩","correct":true},{"t":"⟨3/8⟩","mis":"M6-1-u1-X01"},{"t":"⟨2/3⟩","mis":"M6-1-u1-X02"},{"t":"⟨2 1/4⟩","mis":"M6-1-u1-X04"}],"explanation":["먼저 2씩 나누어 주면 2가 남아요 — 8 ÷ 3은 몫 2, 나머지 2예요.","남은 2도 3으로 똑같이 나누면 ⟨2/3⟩씩 더 가져요.","8 ÷ 3 = ⟨2 2/3⟩ — ⟨2 2/3⟩판예요."]},{"stem":"흰 종이 5장을 3명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 흰 종이를 대분수로 나타내면 몇 장인가요?","options":[{"t":"⟨1 2/3⟩","correct":true},{"t":"⟨3/5⟩","mis":"M6-1-u1-X01"},{"t":"⟨2/3⟩","mis":"M6-1-u1-X02"},{"t":"⟨1 2/5⟩","mis":"M6-1-u1-X04"}],"explanation":["먼저 1씩 나누어 주면 2가 남아요 — 5 ÷ 3은 몫 1, 나머지 2예요.","남은 2도 3으로 똑같이 나누면 ⟨2/3⟩씩 더 가져요.","5 ÷ 3 = ⟨1 2/3⟩ — ⟨1 2/3⟩장예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#11','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C4',2,'sa','auto','4 ÷ 13 = 4 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M6-1-u1-C4","difficulty":2,"kind":"sa","stem":"4 ÷ 13 = 4 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["÷ 13은 13으로 나눈 것 중의 1이에요.","그래서 ⟨1/13⟩을 곱하는 것과 같아요.","4 ÷ 13 = 4 × ⟨1/13⟩ — □는 13이에요."],"mis":"M6-1-u1-X07","variant_rule":{"alt":[{"stem":"12 ÷ 5 = 12 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["÷ 5는 5로 나눈 것 중의 1이에요.","그래서 ⟨1/5⟩을 곱하는 것과 같아요.","12 ÷ 5 = 12 × ⟨1/5⟩ — □는 5예요."]},{"stem":"7 ÷ 8 = 7 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["÷ 8은 8로 나눈 것 중의 1이에요.","그래서 ⟨1/8⟩을 곱하는 것과 같아요.","7 ÷ 8 = 7 × ⟨1/8⟩ — □는 8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#12','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C5',2,'sa','auto','⟨9/13⟩ ÷ 3의 몫은 ⟨1/13⟩이 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M6-1-u1-C5","difficulty":2,"kind":"sa","stem":"⟨9/13⟩ ÷ 3의 몫은 ⟨1/13⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨9/13⟩는 ⟨1/13⟩이 9개예요.","9개를 3으로 똑같이 나누면 9 ÷ 3 = 3개예요.","⟨9/13⟩ ÷ 3 = ⟨3/13⟩ — ⟨1/13⟩이 3개예요."],"mis":"M6-1-u1-X08","variant_rule":{"alt":[{"stem":"⟨12/13⟩ ÷ 4의 몫은 ⟨1/13⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨12/13⟩는 ⟨1/13⟩이 12개예요.","12개를 4로 똑같이 나누면 12 ÷ 4 = 3개예요.","⟨12/13⟩ ÷ 4 = ⟨3/13⟩ — ⟨1/13⟩이 3개예요."]},{"stem":"⟨8/9⟩ ÷ 4의 몫은 ⟨1/9⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["⟨8/9⟩은 ⟨1/9⟩이 8개예요.","8개를 4로 똑같이 나누면 8 ÷ 4 = 2개예요.","⟨8/9⟩ ÷ 4 = ⟨2/9⟩ — ⟨1/9⟩이 2개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#13','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C5',2,'mc','auto','⟨1/6⟩ ÷ 3을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X07']::text[],true,'{"seq":13,"concept":"M6-1-u1-C5","difficulty":2,"kind":"mc","stem":"⟨1/6⟩ ÷ 3을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨1/6⟩ × ⟨1/3⟩","correct":true},{"t":"⟨1/6⟩ × 3","mis":"M6-1-u1-X06"},{"t":"⟨6/1⟩ × ⟨1/3⟩","mis":"M6-1-u1-X07"},{"t":"3 × ⟨1/6⟩","mis":"M6-1-u1-X06"}],"explanation":["÷ 3은 3으로 똑같이 나눈 것 중의 1이에요.","그래서 × ⟨1/3⟩과 같아요.","⟨1/6⟩ ÷ 3 = ⟨1/6⟩ × ⟨1/3⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨5/12⟩ ÷ 7을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨5/12⟩ × ⟨1/7⟩","correct":true},{"t":"⟨5/12⟩ × 7","mis":"M6-1-u1-X06"},{"t":"⟨12/5⟩ × ⟨1/7⟩","mis":"M6-1-u1-X07"},{"t":"7 × ⟨5/12⟩","mis":"M6-1-u1-X06"}],"explanation":["÷ 7은 7로 똑같이 나눈 것 중의 1이에요.","그래서 × ⟨1/7⟩과 같아요.","⟨5/12⟩ ÷ 7 = ⟨5/12⟩ × ⟨1/7⟩이에요."]},{"stem":"⟨4/9⟩ ÷ 5를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨4/9⟩ × ⟨1/5⟩","correct":true},{"t":"⟨4/9⟩ × 5","mis":"M6-1-u1-X06"},{"t":"⟨9/4⟩ × ⟨1/5⟩","mis":"M6-1-u1-X07"},{"t":"5 × ⟨4/9⟩","mis":"M6-1-u1-X06"}],"explanation":["÷ 5는 5로 똑같이 나눈 것 중의 1이에요.","그래서 × ⟨1/5⟩과 같아요.","⟨4/9⟩ ÷ 5 = ⟨4/9⟩ × ⟨1/5⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#14','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C6',2,'mc','auto','⟨3 3/5⟩ ÷ 6을 계산하면 얼마인가요?',ARRAY['M6-1-u1-X10','M6-1-u1-X06']::text[],true,'{"seq":14,"concept":"M6-1-u1-C6","difficulty":2,"kind":"mc","stem":"⟨3 3/5⟩ ÷ 6을 계산하면 얼마인가요?","options":[{"t":"⟨3/5⟩","correct":true},{"t":"⟨3 1/10⟩","mis":"M6-1-u1-X10"},{"t":"⟨1 1/10⟩","mis":"M6-1-u1-X10"},{"t":"⟨21 3/5⟩","mis":"M6-1-u1-X06"}],"explanation":["⟨3 3/5⟩을 가분수로 고치면 ⟨18/5⟩이에요.","⟨18/5⟩ ÷ 6 = ⟨18/5⟩ × ⟨1/6⟩이에요.","⟨18/5⟩ × ⟨1/6⟩ = ⟨3/5⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨1 4/5⟩ ÷ 3을 계산하면 얼마인가요?","options":[{"t":"⟨3/5⟩","correct":true},{"t":"⟨1 4/15⟩","mis":"M6-1-u1-X10"},{"t":"⟨1 2/15⟩","mis":"M6-1-u1-X10"},{"t":"⟨5 2/5⟩","mis":"M6-1-u1-X06"}],"explanation":["⟨1 4/5⟩를 가분수로 고치면 ⟨9/5⟩예요.","⟨9/5⟩ ÷ 3 = ⟨9/5⟩ × ⟨1/3⟩이에요.","⟨9/5⟩ × ⟨1/3⟩ = ⟨3/5⟩이에요."]},{"stem":"⟨1 1/4⟩ ÷ 5를 계산하면 얼마인가요?","options":[{"t":"⟨1/4⟩","correct":true},{"t":"⟨1 1/20⟩","mis":"M6-1-u1-X10"},{"t":"⟨9/20⟩","mis":"M6-1-u1-X10"},{"t":"⟨6 1/4⟩","mis":"M6-1-u1-X06"}],"explanation":["⟨1 1/4⟩을 가분수로 고치면 ⟨5/4⟩예요.","⟨5/4⟩ ÷ 5 = ⟨5/4⟩ × ⟨1/5⟩이에요.","⟨5/4⟩ × ⟨1/5⟩ = ⟨1/4⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#15','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C6',2,'sa','auto','⟨1 7/9⟩ ÷ 4를 계산하려고 ⟨1 7/9⟩을 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":15,"concept":"M6-1-u1-C6","difficulty":2,"kind":"sa","stem":"⟨1 7/9⟩ ÷ 4를 계산하려고 ⟨1 7/9⟩을 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["대분수는 먼저 가분수로 고쳐요.","1 × 9 + 7 = 16이에요.","⟨1 7/9⟩ = ⟨16/9⟩ — 분자는 16이에요."],"mis":"M6-1-u1-X05","variant_rule":{"alt":[{"stem":"⟨4 3/7⟩ ÷ 6을 계산하려고 ⟨4 3/7⟩을 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["31"],"explanation":["대분수는 먼저 가분수로 고쳐요.","4 × 7 + 3 = 31이에요.","⟨4 3/7⟩ = ⟨31/7⟩ — 분자는 31이에요."]},{"stem":"⟨2 3/8⟩ ÷ 5를 계산하려고 ⟨2 3/8⟩을 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["대분수는 먼저 가분수로 고쳐요.","2 × 8 + 3 = 19예요.","⟨2 3/8⟩ = ⟨19/8⟩ — 분자는 19예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#16','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C7',2,'mc','auto','파란 뚜껑 3개와 노란 뚜껑 1개의 무게가 파란 뚜껑 7개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨6 2/3⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?',ARRAY['M6-1-u1-X13','M6-1-u1-X06']::text[],true,'{"seq":16,"concept":"M6-1-u1-C7","difficulty":2,"kind":"mc","stem":"파란 뚜껑 3개와 노란 뚜껑 1개의 무게가 파란 뚜껑 7개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨6 2/3⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?","options":[{"t":"⟨1 2/3⟩","correct":true},{"t":"⟨20/21⟩","mis":"M6-1-u1-X13"},{"t":"⟨2 2/9⟩","mis":"M6-1-u1-X13"},{"t":"⟨26 2/3⟩","mis":"M6-1-u1-X06"}],"explanation":["양쪽에서 파란 3개씩 덜어 내면 노란 1개 = 파란 4개예요.","⟨6 2/3⟩ = ⟨20/3⟩이에요.","⟨20/3⟩ × ⟨1/4⟩ = ⟨1 2/3⟩ — 파란 뚜껑 1개는 ⟨1 2/3⟩ g이에요."],"variant_rule":{"alt":[{"stem":"파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 4개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨3 1/5⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?","options":[{"t":"⟨1 3/5⟩","correct":true},{"t":"⟨4/5⟩","mis":"M6-1-u1-X13"},{"t":"⟨6 2/5⟩","mis":"M6-1-u1-X06"},{"t":"⟨8/15⟩","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 2개씩 덜어 내면 노란 1개 = 파란 2개예요.","⟨3 1/5⟩ = ⟨16/5⟩이에요.","⟨16/5⟩ × ⟨1/2⟩ = ⟨1 3/5⟩ — 파란 뚜껑 1개는 ⟨1 3/5⟩ g이에요."]},{"stem":"파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 5개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨5 1/4⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?","options":[{"t":"⟨1 3/4⟩","correct":true},{"t":"⟨1 1/20⟩","mis":"M6-1-u1-X13"},{"t":"⟨2 5/8⟩","mis":"M6-1-u1-X13"},{"t":"⟨15 3/4⟩","mis":"M6-1-u1-X06"}],"explanation":["양쪽에서 파란 2개씩 덜어 내면 노란 1개 = 파란 3개예요.","⟨5 1/4⟩ = ⟨21/4⟩이에요.","⟨21/4⟩ × ⟨1/3⟩ = ⟨1 3/4⟩ — 파란 뚜껑 1개는 ⟨1 3/4⟩ g이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#17','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C2',3,'mc','auto','가 모둠은 빵 5개를 7명이, 나 모둠은 빵 3개를 4명이 똑같이 나누었어요. 한 명이 가지는 빵이 더 많은 모둠은 어디인가요?',ARRAY['M6-1-u1-X11','M6-1-u1-X03']::text[],true,'{"seq":17,"concept":"M6-1-u1-C2","difficulty":3,"kind":"mc","stem":"가 모둠은 빵 5개를 7명이, 나 모둠은 빵 3개를 4명이 똑같이 나누었어요. 한 명이 가지는 빵이 더 많은 모둠은 어디인가요?","options":[{"t":"나 모둠","correct":true},{"t":"가 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 5 ÷ 7 = ⟨5/7⟩, 나 모둠은 3 ÷ 4 = ⟨3/4⟩이에요.","28로 통분하면 ⟨5/7⟩ = ⟨20/28⟩, ⟨3/4⟩ = ⟨21/28⟩이에요.","⟨5/7⟩ < ⟨3/4⟩이라 나 모둠이 더 많아요."],"variant_rule":{"alt":[{"stem":"가 모둠은 피자 3판을 5명이, 나 모둠은 피자 5판을 8명이 똑같이 나누었어요. 한 명이 가지는 피자가 더 많은 모둠은 어디인가요?","options":[{"t":"나 모둠","correct":true},{"t":"가 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 3 ÷ 5 = ⟨3/5⟩, 나 모둠은 5 ÷ 8 = ⟨5/8⟩예요.","40으로 통분하면 ⟨3/5⟩ = ⟨24/40⟩, ⟨5/8⟩ = ⟨25/40⟩예요.","⟨3/5⟩ < ⟨5/8⟩라 나 모둠이 더 많아요."]},{"stem":"가 모둠은 시루떡 2개를 5명이, 나 모둠은 시루떡 3개를 7명이 똑같이 나누었어요. 한 명이 가지는 시루떡이 더 많은 모둠은 어디인가요?","options":[{"t":"나 모둠","correct":true},{"t":"가 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 2 ÷ 5 = ⟨2/5⟩, 나 모둠은 3 ÷ 7 = ⟨3/7⟩이에요.","35로 통분하면 ⟨2/5⟩ = ⟨14/35⟩, ⟨3/7⟩ = ⟨15/35⟩예요.","⟨2/5⟩ < ⟨3/7⟩이라 나 모둠이 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#18','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C3',3,'sa','auto','색 모래 25 kg을 7모둠이 똑같이 나누어 가지려고 해요. 한 모둠이 가지는 색 모래를 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M6-1-u1-C3","difficulty":3,"kind":"sa","stem":"색 모래 25 kg을 7모둠이 똑같이 나누어 가지려고 해요. 한 모둠이 가지는 색 모래를 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["25 ÷ 7은 몫 3, 나머지 4예요.","남은 4도 나누면 25 ÷ 7 = ⟨3 4/7⟩예요.","자연수 부분과 분자의 합은 3 + 4 = 7이에요."],"mis":"M6-1-u1-X15","variant_rule":{"alt":[{"stem":"주스 13 L를 3명이 똑같이 나누어 마시려고 해요. 한 명이 마시는 주스를 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["13 ÷ 3은 몫 4, 나머지 1이에요.","남은 1도 나누면 13 ÷ 3 = ⟨4 1/3⟩이에요.","자연수 부분과 분자의 합은 4 + 1 = 5예요."]},{"stem":"쌀 19 kg을 4봉지에 똑같이 나누어 담으려고 해요. 한 봉지에 담는 쌀을 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["19 ÷ 4는 몫 4, 나머지 3이에요.","남은 3도 나누면 19 ÷ 4 = ⟨4 3/4⟩이에요.","자연수 부분과 분자의 합은 4 + 3 = 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#19','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C4',3,'mc','auto','끈 10 m를 3도막으로 나눈 한 도막과 끈 13 m를 4도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?',ARRAY['M6-1-u1-X11','M6-1-u1-X03']::text[],true,'{"seq":19,"concept":"M6-1-u1-C4","difficulty":3,"kind":"mc","stem":"끈 10 m를 3도막으로 나눈 한 도막과 끈 13 m를 4도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?","options":[{"t":"끈 10 m를 3도막으로 나눈 한 도막","correct":true},{"t":"끈 13 m를 4도막으로 나눈 한 도막","mis":"M6-1-u1-X11"},{"t":"두 도막의 길이가 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["10 ÷ 3 = 10 × ⟨1/3⟩ = ⟨3 1/3⟩, 13 ÷ 4 = 13 × ⟨1/4⟩ = ⟨3 1/4⟩이에요.","12로 통분하면 ⟨3 1/3⟩ = ⟨40/12⟩, ⟨3 1/4⟩ = ⟨39/12⟩예요.","그래서 더 긴 것은 끈 10 m를 3도막으로 나눈 한 도막이에요."],"variant_rule":{"alt":[{"stem":"끈 8 m를 7도막으로 나눈 한 도막과 끈 9 m를 8도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?","options":[{"t":"끈 8 m를 7도막으로 나눈 한 도막","correct":true},{"t":"끈 9 m를 8도막으로 나눈 한 도막","mis":"M6-1-u1-X11"},{"t":"두 도막의 길이가 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["8 ÷ 7 = 8 × ⟨1/7⟩ = ⟨1 1/7⟩, 9 ÷ 8 = 9 × ⟨1/8⟩ = ⟨1 1/8⟩이에요.","56으로 통분하면 ⟨1 1/7⟩ = ⟨64/56⟩, ⟨1 1/8⟩ = ⟨63/56⟩이에요.","그래서 더 긴 것은 끈 8 m를 7도막으로 나눈 한 도막이에요."]},{"stem":"끈 9 m를 4도막으로 나눈 한 도막과 끈 7 m를 3도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?","options":[{"t":"끈 7 m를 3도막으로 나눈 한 도막","correct":true},{"t":"끈 9 m를 4도막으로 나눈 한 도막","mis":"M6-1-u1-X11"},{"t":"두 도막의 길이가 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["9 ÷ 4 = 9 × ⟨1/4⟩ = ⟨2 1/4⟩, 7 ÷ 3 = 7 × ⟨1/3⟩ = ⟨2 1/3⟩이에요.","12로 통분하면 ⟨2 1/4⟩ = ⟨27/12⟩, ⟨2 1/3⟩ = ⟨28/12⟩이에요.","그래서 더 긴 것은 끈 7 m를 3도막으로 나눈 한 도막이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#20','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C5',3,'error','auto','⟨3/10⟩ ÷ 4에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X15']::text[],true,'{"seq":20,"concept":"M6-1-u1-C5","difficulty":3,"kind":"error","stem":"⟨3/10⟩ ÷ 4에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「⟨3/10⟩ × 4 = ⟨1 1/5⟩로 계산해.」","correct":true,"mis_target":"M6-1-u1-X06"},{"t":"나린 — 「⟨3/10⟩ × ⟨1/4⟩로 바꾸어 계산하면 돼.」","mis":"M6-1-u1-X15"},{"t":"유진 — 「몫은 ⟨3/10⟩보다 작아.」","mis":"M6-1-u1-X15"}],"explanation":["4로 나누면 양이 작아져야 해요.","⟨3/10⟩ × 4 = ⟨1 1/5⟩은 오히려 커요.","⟨3/10⟩ ÷ 4 = ⟨3/10⟩ × ⟨1/4⟩ = ⟨3/40⟩ — 가온은 나누는 수를 그대로 곱했어요."],"variant_rule":{"alt":[{"stem":"⟨7/8⟩ ÷ 2에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「⟨7/8⟩ × 2 = ⟨1 3/4⟩으로 계산해.」","correct":true,"mis_target":"M6-1-u1-X06"},{"t":"라온 — 「⟨7/8⟩ × ⟨1/2⟩로 바꾸어 계산하면 돼.」","mis":"M6-1-u1-X15"},{"t":"예준 — 「몫은 ⟨7/8⟩보다 작아.」","mis":"M6-1-u1-X15"}],"explanation":["2로 나누면 양이 작아져야 해요.","⟨7/8⟩ × 2 = ⟨1 3/4⟩은 오히려 커요.","⟨7/8⟩ ÷ 2 = ⟨7/8⟩ × ⟨1/2⟩ = ⟨7/16⟩ — 여울은 나누는 수를 그대로 곱했어요."]},{"stem":"⟨4/7⟩ ÷ 3에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「⟨4/7⟩ × 3 = ⟨1 5/7⟩로 계산해.」","correct":true,"mis_target":"M6-1-u1-X06"},{"t":"도윤 — 「⟨4/7⟩ × ⟨1/3⟩로 바꾸어 계산하면 돼.」","mis":"M6-1-u1-X15"},{"t":"하린 — 「몫은 ⟨4/7⟩보다 작아.」","mis":"M6-1-u1-X15"}],"explanation":["3으로 나누면 양이 작아져야 해요.","⟨4/7⟩ × 3 = ⟨1 5/7⟩는 오히려 커요.","⟨4/7⟩ ÷ 3 = ⟨4/7⟩ × ⟨1/3⟩ = ⟨4/21⟩ — 수아는 나누는 수를 그대로 곱했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#21','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C6',3,'mc','auto','넓이가 ⟨3 3/5⟩ m²이고 가로가 4 m인 직사각형이 있어요. 세로는 몇 m인가요?',ARRAY['M6-1-u1-X10','M6-1-u1-X06']::text[],true,'{"seq":21,"concept":"M6-1-u1-C6","difficulty":3,"kind":"mc","stem":"넓이가 ⟨3 3/5⟩ m²이고 가로가 4 m인 직사각형이 있어요. 세로는 몇 m인가요?","options":[{"t":"⟨9/10⟩","correct":true},{"t":"⟨3 3/20⟩","mis":"M6-1-u1-X10"},{"t":"⟨1 7/20⟩","mis":"M6-1-u1-X10"},{"t":"⟨14 2/5⟩","mis":"M6-1-u1-X06"}],"explanation":["(직사각형의 넓이) = (가로) × (세로)이니 세로 = 넓이 ÷ 가로예요.","⟨3 3/5⟩ ÷ 4 = ⟨18/5⟩ × ⟨1/4⟩이에요.","⟨18/5⟩ × ⟨1/4⟩ = ⟨9/10⟩ — 세로는 ⟨9/10⟩ m예요."],"variant_rule":{"alt":[{"stem":"넓이가 ⟨6 2/3⟩ m²이고 가로가 5 m인 직사각형이 있어요. 세로는 몇 m인가요?","options":[{"t":"⟨1 1/3⟩","correct":true},{"t":"⟨6 2/15⟩","mis":"M6-1-u1-X10"},{"t":"⟨1 13/15⟩","mis":"M6-1-u1-X10"},{"t":"⟨33 1/3⟩","mis":"M6-1-u1-X06"}],"explanation":["(직사각형의 넓이) = (가로) × (세로)이니 세로 = 넓이 ÷ 가로예요.","⟨6 2/3⟩ ÷ 5 = ⟨20/3⟩ × ⟨1/5⟩이에요.","⟨20/3⟩ × ⟨1/5⟩ = ⟨1 1/3⟩ — 세로는 ⟨1 1/3⟩ m예요."]},{"stem":"넓이가 ⟨4 2/3⟩ m²이고 가로가 3 m인 직사각형이 있어요. 세로는 몇 m인가요?","options":[{"t":"⟨1 5/9⟩","correct":true},{"t":"⟨4 2/9⟩","mis":"M6-1-u1-X10"},{"t":"2","mis":"M6-1-u1-X10"},{"t":"14","mis":"M6-1-u1-X06"}],"explanation":["(직사각형의 넓이) = (가로) × (세로)이니 세로 = 넓이 ÷ 가로예요.","⟨4 2/3⟩ ÷ 3 = ⟨14/3⟩ × ⟨1/3⟩이에요.","⟨14/3⟩ × ⟨1/3⟩ = ⟨1 5/9⟩ — 세로는 ⟨1 5/9⟩ m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#22','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C7',3,'sa','auto','조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨4 4/5⟩ g이고 파란 뚜껑 6개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M6-1-u1-C7","difficulty":3,"kind":"sa","stem":"조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨4 4/5⟩ g이고 파란 뚜껑 6개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["파란 뚜껑 1개 = ⟨4 4/5⟩ ÷ 6이에요.","⟨24/5⟩ ÷ 6 = ⟨24/5⟩ × ⟨1/6⟩ = ⟨4/5⟩예요.","분모와 분자의 합은 5 + 4 = 9예요."],"mis":"M6-1-u1-X15","variant_rule":{"alt":[{"stem":"조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨1 5/7⟩ g이고 파란 뚜껑 4개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["파란 뚜껑 1개 = ⟨1 5/7⟩ ÷ 4예요.","⟨12/7⟩ ÷ 4 = ⟨12/7⟩ × ⟨1/4⟩ = ⟨3/7⟩이에요.","분모와 분자의 합은 7 + 3 = 10이에요."]},{"stem":"조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨2 1/3⟩ g이고 파란 뚜껑 7개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["파란 뚜껑 1개 = ⟨2 1/3⟩ ÷ 7이에요.","⟨7/3⟩ ÷ 7 = ⟨7/3⟩ × ⟨1/7⟩ = ⟨1/3⟩이에요.","분모와 분자의 합은 3 + 1 = 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#23','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C5',4,'sa','auto','⟨9/13⟩ ÷ □의 몫이 ⟨1/13⟩보다 클 때, □에 들어갈 수 있는 가장 큰 자연수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M6-1-u1-C5","difficulty":4,"kind":"sa","stem":"⟨9/13⟩ ÷ □의 몫이 ⟨1/13⟩보다 클 때, □에 들어갈 수 있는 가장 큰 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["⟨9/13⟩는 ⟨1/13⟩이 9개예요.","□로 나눈 몫이 ⟨1/13⟩보다 크려면 9개를 □로 나눈 수가 1보다 커야 해요.","□는 9보다 작아야 하니 가장 큰 수는 8이에요."],"mis":"M6-1-u1-X11","variant_rule":{"alt":[{"stem":"자연수 부분이 □이고 분수 부분이 ⟨2/5⟩인 대분수를 4로 나누었더니 ⟨17/20⟩이 되었어요. □에 알맞은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["나누기 전의 수는 ⟨17/20⟩ × 4예요.","⟨17/20⟩ × 4 = ⟨17/5⟩ = ⟨3 2/5⟩예요.","그래서 □는 3이에요."]},{"stem":"□ ÷ 11의 몫이 1보다 작을 때, □에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["□ ÷ 11 = ⟨□/11⟩이에요.","몫이 1보다 작으려면 □가 11보다 작아야 해요.","1부터 10까지 10개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#24','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C2',4,'essay','teacher','3 ÷ 4의 몫이 1보다 작은 까닭을 「1 ÷ 4」를 이용해 설명하고, 몫을 분수로 나타내 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-1-u1-C2","difficulty":4,"kind":"essay","stem":"3 ÷ 4의 몫이 1보다 작은 까닭을 「1 ÷ 4」를 이용해 설명하고, 몫을 분수로 나타내 보세요.","answer_guide":{"answer":"예: 1 ÷ 4는 1을 4로 똑같이 나눈 한 조각이라 ⟨1/4⟩이다. 3 ÷ 4는 그런 조각이 3개이므로 ⟨3/4⟩이다. 나누어지는 수 3이 나누는 수 4보다 작아 4조각 가운데 3조각만 되므로 몫은 1보다 작다.","scoring_points":["1 ÷ 4 = ⟨1/4⟩을 썼는가","3 ÷ 4 = ⟨3/4⟩을 구했는가","나누어지는 수가 더 작아 1보다 작다고 설명했는가"]},"explanation":["1 ÷ 4 = ⟨1/4⟩이에요.","3 ÷ 4는 ⟨1/4⟩이 3개 — ⟨3/4⟩이에요.","3이 4보다 작아 몫은 1보다 작아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_c#25','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C7',4,'essay','teacher','조건을 바꾸어 문제를 만들었어요. 「파란 뚜껑 1개와 노란 뚜껑 1개의 무게가 파란 뚜껑 3개의 무게와 같고, 노란 뚜껑 1개는 ⟨3 1/2⟩ g이에요.」 파란 뚜껑 1개의 무게를 구하는 과정을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"M6-1-u1-C7","difficulty":4,"kind":"essay","stem":"조건을 바꾸어 문제를 만들었어요. 「파란 뚜껑 1개와 노란 뚜껑 1개의 무게가 파란 뚜껑 3개의 무게와 같고, 노란 뚜껑 1개는 ⟨3 1/2⟩ g이에요.」 파란 뚜껑 1개의 무게를 구하는 과정을 쓰세요.","answer_guide":{"answer":"예: 양쪽에서 파란 뚜껑 1개씩을 덜어 내면 노란 뚜껑 1개는 파란 뚜껑 2개와 무게가 같다. 그래서 파란 뚜껑 1개는 ⟨3 1/2⟩ ÷ 2이다. ⟨3 1/2⟩ = ⟨7/2⟩이므로 ⟨7/2⟩ × ⟨1/2⟩ = ⟨7/4⟩ = ⟨1 3/4⟩ g이다.","scoring_points":["양쪽에서 덜어 내 노란 1개 = 파란 2개를 찾았는가","⟨3 1/2⟩ = ⟨7/2⟩로 고쳤는가","⟨1 3/4⟩ g을 구했는가"]},"explanation":["노란 1개 = 파란 2개예요.","⟨3 1/2⟩ = ⟨7/2⟩이에요.","⟨7/2⟩ × ⟨1/2⟩ = ⟨1 3/4⟩ g이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#1','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C2',1,'mc','auto','식빵 1개를 3명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 식빵은 몇 개인지 분수로 나타내면 얼마인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X09']::text[],true,'{"seq":1,"concept":"M6-1-u1-C2","difficulty":1,"kind":"mc","stem":"식빵 1개를 3명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 식빵은 몇 개인지 분수로 나타내면 얼마인가요?","options":[{"t":"⟨1/3⟩","correct":true},{"t":"3","mis":"M6-1-u1-X01"},{"t":"⟨1/4⟩","mis":"M6-1-u1-X09"},{"t":"1","mis":"M6-1-u1-X01"}],"explanation":["식빵 1개를 3으로 똑같이 나누는 것은 1 ÷ 3이에요.","나누어지는 수 1은 분자, 나누는 수 3은 분모가 돼요.","1 ÷ 3 = ⟨1/3⟩ — ⟨1/3⟩개예요."],"variant_rule":{"alt":[{"stem":"시루떡 3개를 4명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 시루떡은 몇 개인지 분수로 나타내면 얼마인가요?","options":[{"t":"⟨3/4⟩","correct":true},{"t":"⟨1 1/3⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/4⟩","mis":"M6-1-u1-X01"},{"t":"⟨3/7⟩","mis":"M6-1-u1-X09"}],"explanation":["시루떡 3개를 4로 똑같이 나누는 것은 3 ÷ 4예요.","나누어지는 수 3은 분자, 나누는 수 4는 분모가 돼요.","3 ÷ 4 = ⟨3/4⟩ — ⟨3/4⟩개예요."]},{"stem":"과자 반죽 2개를 5명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 과자 반죽은 몇 개인지 분수로 나타내면 얼마인가요?","options":[{"t":"⟨2/5⟩","correct":true},{"t":"⟨2 1/2⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/5⟩","mis":"M6-1-u1-X01"},{"t":"⟨2/7⟩","mis":"M6-1-u1-X09"}],"explanation":["과자 반죽 2개를 5로 똑같이 나누는 것은 2 ÷ 5예요.","나누어지는 수 2는 분자, 나누는 수 5는 분모가 돼요.","2 ÷ 5 = ⟨2/5⟩ — ⟨2/5⟩개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#2','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C2',1,'sa','auto','6 ÷ 13의 몫을 분수로 나타낼 때 분모에 오는 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u1-C2","difficulty":1,"kind":"sa","stem":"6 ÷ 13의 몫을 분수로 나타낼 때 분모에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["(자연수)÷(자연수)의 몫은 분수로 나타낼 수 있어요.","나누어지는 수 6은 분자, 나누는 수 13은 분모예요.","6 ÷ 13 = ⟨6/13⟩이니 분모는 13이에요."],"mis":"M6-1-u1-X01","variant_rule":{"alt":[{"stem":"4 ÷ 7의 몫을 분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["(자연수)÷(자연수)의 몫은 분수로 나타낼 수 있어요.","나누어지는 수 4는 분자, 나누는 수 7은 분모예요.","4 ÷ 7 = ⟨4/7⟩니 분자는 4예요."]},{"stem":"5 ÷ 9의 몫을 분수로 나타낼 때 분모에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["(자연수)÷(자연수)의 몫은 분수로 나타낼 수 있어요.","나누어지는 수 5는 분자, 나누는 수 9는 분모예요.","5 ÷ 9 = ⟨5/9⟩니 분모는 9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#3','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C3',1,'mc','auto','⟨2 5/6⟩를 가분수로 나타내면 어느 것인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X05']::text[],true,'{"seq":3,"concept":"M6-1-u1-C3","difficulty":1,"kind":"mc","stem":"⟨2 5/6⟩를 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨17/6⟩","correct":true},{"t":"⟨6/17⟩","mis":"M6-1-u1-X01"},{"t":"⟨7/6⟩","mis":"M6-1-u1-X05"},{"t":"⟨10/6⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 2는 ⟨12/6⟩예요 — 2 × 6 = 12.","여기에 ⟨5/6⟩를 더하면 분자는 12 + 5 = 17이에요.","⟨2 5/6⟩ = ⟨17/6⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨1 3/4⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨7/4⟩","correct":true},{"t":"⟨4/7⟩","mis":"M6-1-u1-X01"},{"t":"⟨4/4⟩","mis":"M6-1-u1-X05"},{"t":"⟨3/4⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 1은 ⟨4/4⟩예요 — 1 × 4 = 4.","여기에 ⟨3/4⟩을 더하면 분자는 4 + 3 = 7이에요.","⟨1 3/4⟩ = ⟨7/4⟩이에요."]},{"stem":"⟨2 2/5⟩를 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨12/5⟩","correct":true},{"t":"⟨5/12⟩","mis":"M6-1-u1-X01"},{"t":"⟨4/5⟩","mis":"M6-1-u1-X05"},{"t":"⟨22/5⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 2는 ⟨10/5⟩이에요 — 2 × 5 = 10.","여기에 ⟨2/5⟩를 더하면 분자는 10 + 2 = 12예요.","⟨2 2/5⟩ = ⟨12/5⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#4','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C3',1,'sa','auto','23 ÷ 7의 몫을 대분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u1-C3","difficulty":1,"kind":"sa","stem":"23 ÷ 7의 몫을 대분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["23 ÷ 7은 몫 3, 나머지 2예요.","남은 2도 7로 나누면 ⟨2/7⟩ — 몫은 ⟨3 2/7⟩예요.","그래서 분자는 2예요."],"mis":"M6-1-u1-X04","variant_rule":{"alt":[{"stem":"15 ÷ 4의 몫을 대분수로 나타낼 때 자연수 부분에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["15 ÷ 4는 몫 3, 나머지 3이에요.","남은 3도 4로 나누면 ⟨3/4⟩ — 몫은 ⟨3 3/4⟩이에요.","그래서 자연수 부분은 3이에요."]},{"stem":"14 ÷ 3의 몫을 대분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["14 ÷ 3은 몫 4, 나머지 2예요.","남은 2도 3으로 나누면 ⟨2/3⟩ — 몫은 ⟨4 2/3⟩예요.","그래서 분자는 2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#5','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C4',1,'mc','auto','4 ÷ 11을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X07']::text[],true,'{"seq":5,"concept":"M6-1-u1-C4","difficulty":1,"kind":"mc","stem":"4 ÷ 11을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"4 × ⟨1/11⟩","correct":true},{"t":"4 × 11","mis":"M6-1-u1-X06"},{"t":"11 × ⟨1/4⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/4⟩ × ⟨1/11⟩","mis":"M6-1-u1-X07"}],"explanation":["÷ 11은 11로 똑같이 나눈 것 중의 1이에요.","× ⟨1/11⟩도 11로 똑같이 나눈 것 중의 1이에요.","그래서 4 ÷ 11 = 4 × ⟨1/11⟩ = ⟨4/11⟩예요."],"variant_rule":{"alt":[{"stem":"6 ÷ 5를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"6 × ⟨1/5⟩","correct":true},{"t":"6 × 5","mis":"M6-1-u1-X06"},{"t":"5 × ⟨1/6⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/6⟩ × ⟨1/5⟩","mis":"M6-1-u1-X07"}],"explanation":["÷ 5는 5로 똑같이 나눈 것 중의 1이에요.","× ⟨1/5⟩도 5로 똑같이 나눈 것 중의 1이에요.","그래서 6 ÷ 5 = 6 × ⟨1/5⟩ = ⟨1 1/5⟩이에요."]},{"stem":"2 ÷ 9를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"2 × ⟨1/9⟩","correct":true},{"t":"2 × 9","mis":"M6-1-u1-X06"},{"t":"9 × ⟨1/2⟩","mis":"M6-1-u1-X07"},{"t":"⟨1/2⟩ × ⟨1/9⟩","mis":"M6-1-u1-X07"}],"explanation":["÷ 9는 9로 똑같이 나눈 것 중의 1이에요.","× ⟨1/9⟩도 9로 똑같이 나눈 것 중의 1이에요.","그래서 2 ÷ 9 = 2 × ⟨1/9⟩ = ⟨2/9⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#6','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C5',1,'mc','auto','⟨9/10⟩ ÷ 3을 계산하면 얼마인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X09','M6-1-u1-X07']::text[],true,'{"seq":6,"concept":"M6-1-u1-C5","difficulty":1,"kind":"mc","stem":"⟨9/10⟩ ÷ 3을 계산하면 얼마인가요?","options":[{"t":"⟨3/10⟩","correct":true},{"t":"⟨2 7/10⟩","mis":"M6-1-u1-X06"},{"t":"⟨9/13⟩","mis":"M6-1-u1-X09"},{"t":"⟨10/27⟩","mis":"M6-1-u1-X07"}],"explanation":["⟨9/10⟩는 ⟨1/10⟩이 9개예요.","분자 9를 3으로 나누면 9 ÷ 3 = 3 — ⟨1/10⟩이 3개예요.","그래서 ⟨9/10⟩ ÷ 3 = ⟨3/10⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨6/11⟩ ÷ 3을 계산하면 얼마인가요?","options":[{"t":"⟨2/11⟩","correct":true},{"t":"⟨1 7/11⟩","mis":"M6-1-u1-X06"},{"t":"⟨3/7⟩","mis":"M6-1-u1-X09"},{"t":"⟨11/18⟩","mis":"M6-1-u1-X07"}],"explanation":["⟨6/11⟩은 ⟨1/11⟩이 6개예요.","분자 6을 3으로 나누면 6 ÷ 3 = 2 — ⟨1/11⟩이 2개예요.","그래서 ⟨6/11⟩ ÷ 3 = ⟨2/11⟩예요."]},{"stem":"⟨4/9⟩ ÷ 2를 계산하면 얼마인가요?","options":[{"t":"⟨2/9⟩","correct":true},{"t":"⟨8/9⟩","mis":"M6-1-u1-X06"},{"t":"⟨4/11⟩","mis":"M6-1-u1-X09"},{"t":"⟨1 1/8⟩","mis":"M6-1-u1-X07"}],"explanation":["⟨4/9⟩는 ⟨1/9⟩이 4개예요.","분자 4를 2로 나누면 4 ÷ 2 = 2 — ⟨1/9⟩이 2개예요.","그래서 ⟨4/9⟩ ÷ 2 = ⟨2/9⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#7','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C6',1,'mc','auto','⟨4 1/3⟩을 가분수로 나타내면 어느 것인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X05']::text[],true,'{"seq":7,"concept":"M6-1-u1-C6","difficulty":1,"kind":"mc","stem":"⟨4 1/3⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨13/3⟩","correct":true},{"t":"⟨3/13⟩","mis":"M6-1-u1-X01"},{"t":"⟨5/3⟩","mis":"M6-1-u1-X05"},{"t":"⟨4/3⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 4는 ⟨12/3⟩예요 — 4 × 3 = 12.","여기에 ⟨1/3⟩을 더하면 분자는 12 + 1 = 13이에요.","⟨4 1/3⟩ = ⟨13/3⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨1 5/6⟩를 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨11/6⟩","correct":true},{"t":"⟨6/11⟩","mis":"M6-1-u1-X01"},{"t":"⟨6/6⟩","mis":"M6-1-u1-X05"},{"t":"⟨5/6⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 1은 ⟨6/6⟩이에요 — 1 × 6 = 6.","여기에 ⟨5/6⟩를 더하면 분자는 6 + 5 = 11이에요.","⟨1 5/6⟩ = ⟨11/6⟩이에요."]},{"stem":"⟨3 2/7⟩를 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨23/7⟩","correct":true},{"t":"⟨7/23⟩","mis":"M6-1-u1-X01"},{"t":"⟨5/7⟩","mis":"M6-1-u1-X05"},{"t":"⟨6/7⟩","mis":"M6-1-u1-X05"}],"explanation":["자연수 3은 ⟨21/7⟩이에요 — 3 × 7 = 21.","여기에 ⟨2/7⟩를 더하면 분자는 21 + 2 = 23이에요.","⟨3 2/7⟩ = ⟨23/7⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#8','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C7',1,'mc','auto','저울에서 파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 7개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?',ARRAY['M6-1-u1-X13']::text[],true,'{"seq":8,"concept":"M6-1-u1-C7","difficulty":1,"kind":"mc","stem":"저울에서 파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 7개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?","options":[{"t":"5개","correct":true},{"t":"2개","mis":"M6-1-u1-X13"},{"t":"7개","mis":"M6-1-u1-X13"},{"t":"9개","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 뚜껑 2개씩을 덜어 내도 저울은 수평이에요.","왼쪽엔 노란 뚜껑 1개, 오른쪽엔 파란 뚜껑 7 − 2 = 5개가 남아요.","그래서 노란 뚜껑 1개는 파란 뚜껑 5개와 같아요."],"variant_rule":{"alt":[{"stem":"저울에서 파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 5개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?","options":[{"t":"3개","correct":true},{"t":"2개","mis":"M6-1-u1-X13"},{"t":"5개","mis":"M6-1-u1-X13"},{"t":"7개","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 뚜껑 2개씩을 덜어 내도 저울은 수평이에요.","왼쪽엔 노란 뚜껑 1개, 오른쪽엔 파란 뚜껑 5 − 2 = 3개가 남아요.","그래서 노란 뚜껑 1개는 파란 뚜껑 3개와 같아요."]},{"stem":"저울에서 파란 뚜껑 1개와 노란 뚜껑 1개의 무게가 파란 뚜껑 5개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?","options":[{"t":"4개","correct":true},{"t":"1개","mis":"M6-1-u1-X13"},{"t":"5개","mis":"M6-1-u1-X13"},{"t":"6개","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 뚜껑 1개씩을 덜어 내도 저울은 수평이에요.","왼쪽엔 노란 뚜껑 1개, 오른쪽엔 파란 뚜껑 5 − 1 = 4개가 남아요.","그래서 노란 뚜껑 1개는 파란 뚜껑 4개와 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#9','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C1',2,'mc','auto','흰 종이 3장을 8명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 흰 종이를 구하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u1-X14']::text[],true,'{"seq":9,"concept":"M6-1-u1-C1","difficulty":2,"kind":"mc","stem":"흰 종이 3장을 8명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 흰 종이를 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"3 ÷ 8","correct":true},{"t":"8 ÷ 3","mis":"M6-1-u1-X14"},{"t":"3 × 8","mis":"M6-1-u1-X14"},{"t":"3 + 8","mis":"M6-1-u1-X14"}],"explanation":["전체 3장을 8로 똑같이 나누는 거예요.","나누어지는 수 3이 앞, 나누는 수 8이 뒤에 와요.","그래서 식은 3 ÷ 8이에요."],"variant_rule":{"alt":[{"stem":"시루떡 2개를 5명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 시루떡을 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"2 ÷ 5","correct":true},{"t":"5 ÷ 2","mis":"M6-1-u1-X14"},{"t":"2 × 5","mis":"M6-1-u1-X14"},{"t":"2 + 5","mis":"M6-1-u1-X14"}],"explanation":["전체 2개를 5로 똑같이 나누는 거예요.","나누어지는 수 2가 앞, 나누는 수 5가 뒤에 와요.","그래서 식은 2 ÷ 5예요."]},{"stem":"과자 반죽 3개를 7명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 과자 반죽을 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"3 ÷ 7","correct":true},{"t":"7 ÷ 3","mis":"M6-1-u1-X14"},{"t":"3 × 7","mis":"M6-1-u1-X14"},{"t":"3 + 7","mis":"M6-1-u1-X14"}],"explanation":["전체 3개를 7로 똑같이 나누는 거예요.","나누어지는 수 3이 앞, 나누는 수 7이 뒤에 와요.","그래서 식은 3 ÷ 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#10','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C3',2,'mc','auto','피자 8판을 3명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 피자를 대분수로 나타내면 몇 판인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X02','M6-1-u1-X04']::text[],true,'{"seq":10,"concept":"M6-1-u1-C3","difficulty":2,"kind":"mc","stem":"피자 8판을 3명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 피자를 대분수로 나타내면 몇 판인가요?","options":[{"t":"⟨2 2/3⟩","correct":true},{"t":"⟨3/8⟩","mis":"M6-1-u1-X01"},{"t":"⟨2/3⟩","mis":"M6-1-u1-X02"},{"t":"⟨2 1/4⟩","mis":"M6-1-u1-X04"}],"explanation":["먼저 2씩 나누어 주면 2가 남아요 — 8 ÷ 3은 몫 2, 나머지 2예요.","남은 2도 3으로 똑같이 나누면 ⟨2/3⟩씩 더 가져요.","8 ÷ 3 = ⟨2 2/3⟩ — ⟨2 2/3⟩판예요."],"variant_rule":{"alt":[{"stem":"흰 종이 5장을 3명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 흰 종이를 대분수로 나타내면 몇 장인가요?","options":[{"t":"⟨1 2/3⟩","correct":true},{"t":"⟨3/5⟩","mis":"M6-1-u1-X01"},{"t":"⟨2/3⟩","mis":"M6-1-u1-X02"},{"t":"⟨1 2/5⟩","mis":"M6-1-u1-X04"}],"explanation":["먼저 1씩 나누어 주면 2가 남아요 — 5 ÷ 3은 몫 1, 나머지 2예요.","남은 2도 3으로 똑같이 나누면 ⟨2/3⟩씩 더 가져요.","5 ÷ 3 = ⟨1 2/3⟩ — ⟨1 2/3⟩장예요."]},{"stem":"빵 9개를 4명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 빵을 대분수로 나타내면 몇 개인가요?","options":[{"t":"⟨2 1/4⟩","correct":true},{"t":"⟨4/9⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/4⟩","mis":"M6-1-u1-X02"},{"t":"⟨2 1/9⟩","mis":"M6-1-u1-X04"}],"explanation":["먼저 2씩 나누어 주면 1이 남아요 — 9 ÷ 4는 몫 2, 나머지 1이에요.","남은 1도 4로 똑같이 나누면 ⟨1/4⟩씩 더 가져요.","9 ÷ 4 = ⟨2 1/4⟩ — ⟨2 1/4⟩개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#11','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C4',2,'sa','auto','12 ÷ 5 = 12 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M6-1-u1-C4","difficulty":2,"kind":"sa","stem":"12 ÷ 5 = 12 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["÷ 5는 5로 나눈 것 중의 1이에요.","그래서 ⟨1/5⟩을 곱하는 것과 같아요.","12 ÷ 5 = 12 × ⟨1/5⟩ — □는 5예요."],"mis":"M6-1-u1-X07","variant_rule":{"alt":[{"stem":"7 ÷ 8 = 7 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["÷ 8은 8로 나눈 것 중의 1이에요.","그래서 ⟨1/8⟩을 곱하는 것과 같아요.","7 ÷ 8 = 7 × ⟨1/8⟩ — □는 8이에요."]},{"stem":"10 ÷ 3 = 10 × ⟨1/□⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["÷ 3은 3으로 나눈 것 중의 1이에요.","그래서 ⟨1/3⟩을 곱하는 것과 같아요.","10 ÷ 3 = 10 × ⟨1/3⟩ — □는 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#12','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C5',2,'sa','auto','⟨12/13⟩ ÷ 4의 몫은 ⟨1/13⟩이 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M6-1-u1-C5","difficulty":2,"kind":"sa","stem":"⟨12/13⟩ ÷ 4의 몫은 ⟨1/13⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨12/13⟩는 ⟨1/13⟩이 12개예요.","12개를 4로 똑같이 나누면 12 ÷ 4 = 3개예요.","⟨12/13⟩ ÷ 4 = ⟨3/13⟩ — ⟨1/13⟩이 3개예요."],"mis":"M6-1-u1-X08","variant_rule":{"alt":[{"stem":"⟨8/9⟩ ÷ 4의 몫은 ⟨1/9⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["⟨8/9⟩은 ⟨1/9⟩이 8개예요.","8개를 4로 똑같이 나누면 8 ÷ 4 = 2개예요.","⟨8/9⟩ ÷ 4 = ⟨2/9⟩ — ⟨1/9⟩이 2개예요."]},{"stem":"⟨10/11⟩ ÷ 2의 몫은 ⟨1/11⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["⟨10/11⟩은 ⟨1/11⟩이 10개예요.","10개를 2로 똑같이 나누면 10 ÷ 2 = 5개예요.","⟨10/11⟩ ÷ 2 = ⟨5/11⟩ — ⟨1/11⟩이 5개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#13','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C5',2,'mc','auto','⟨5/12⟩ ÷ 7을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X07']::text[],true,'{"seq":13,"concept":"M6-1-u1-C5","difficulty":2,"kind":"mc","stem":"⟨5/12⟩ ÷ 7을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨5/12⟩ × ⟨1/7⟩","correct":true},{"t":"⟨5/12⟩ × 7","mis":"M6-1-u1-X06"},{"t":"⟨12/5⟩ × ⟨1/7⟩","mis":"M6-1-u1-X07"},{"t":"7 × ⟨5/12⟩","mis":"M6-1-u1-X06"}],"explanation":["÷ 7은 7로 똑같이 나눈 것 중의 1이에요.","그래서 × ⟨1/7⟩과 같아요.","⟨5/12⟩ ÷ 7 = ⟨5/12⟩ × ⟨1/7⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨4/9⟩ ÷ 5를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨4/9⟩ × ⟨1/5⟩","correct":true},{"t":"⟨4/9⟩ × 5","mis":"M6-1-u1-X06"},{"t":"⟨9/4⟩ × ⟨1/5⟩","mis":"M6-1-u1-X07"},{"t":"5 × ⟨4/9⟩","mis":"M6-1-u1-X06"}],"explanation":["÷ 5는 5로 똑같이 나눈 것 중의 1이에요.","그래서 × ⟨1/5⟩과 같아요.","⟨4/9⟩ ÷ 5 = ⟨4/9⟩ × ⟨1/5⟩이에요."]},{"stem":"⟨7/10⟩ ÷ 2를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨7/10⟩ × ⟨1/2⟩","correct":true},{"t":"⟨7/10⟩ × 2","mis":"M6-1-u1-X06"},{"t":"⟨10/7⟩ × ⟨1/2⟩","mis":"M6-1-u1-X07"},{"t":"2 × ⟨7/10⟩","mis":"M6-1-u1-X06"}],"explanation":["÷ 2는 2로 똑같이 나눈 것 중의 1이에요.","그래서 × ⟨1/2⟩과 같아요.","⟨7/10⟩ ÷ 2 = ⟨7/10⟩ × ⟨1/2⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#14','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C6',2,'mc','auto','⟨1 4/5⟩ ÷ 3을 계산하면 얼마인가요?',ARRAY['M6-1-u1-X10','M6-1-u1-X06']::text[],true,'{"seq":14,"concept":"M6-1-u1-C6","difficulty":2,"kind":"mc","stem":"⟨1 4/5⟩ ÷ 3을 계산하면 얼마인가요?","options":[{"t":"⟨3/5⟩","correct":true},{"t":"⟨1 4/15⟩","mis":"M6-1-u1-X10"},{"t":"⟨1 2/15⟩","mis":"M6-1-u1-X10"},{"t":"⟨5 2/5⟩","mis":"M6-1-u1-X06"}],"explanation":["⟨1 4/5⟩를 가분수로 고치면 ⟨9/5⟩예요.","⟨9/5⟩ ÷ 3 = ⟨9/5⟩ × ⟨1/3⟩이에요.","⟨9/5⟩ × ⟨1/3⟩ = ⟨3/5⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨1 1/4⟩ ÷ 5를 계산하면 얼마인가요?","options":[{"t":"⟨1/4⟩","correct":true},{"t":"⟨1 1/20⟩","mis":"M6-1-u1-X10"},{"t":"⟨9/20⟩","mis":"M6-1-u1-X10"},{"t":"⟨6 1/4⟩","mis":"M6-1-u1-X06"}],"explanation":["⟨1 1/4⟩을 가분수로 고치면 ⟨5/4⟩예요.","⟨5/4⟩ ÷ 5 = ⟨5/4⟩ × ⟨1/5⟩이에요.","⟨5/4⟩ × ⟨1/5⟩ = ⟨1/4⟩이에요."]},{"stem":"⟨2 1/3⟩ ÷ 7을 계산하면 얼마인가요?","options":[{"t":"⟨1/3⟩","correct":true},{"t":"⟨2 1/21⟩","mis":"M6-1-u1-X10"},{"t":"⟨13/21⟩","mis":"M6-1-u1-X10"},{"t":"⟨16 1/3⟩","mis":"M6-1-u1-X06"}],"explanation":["⟨2 1/3⟩을 가분수로 고치면 ⟨7/3⟩이에요.","⟨7/3⟩ ÷ 7 = ⟨7/3⟩ × ⟨1/7⟩이에요.","⟨7/3⟩ × ⟨1/7⟩ = ⟨1/3⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#15','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C6',2,'sa','auto','⟨4 3/7⟩ ÷ 6을 계산하려고 ⟨4 3/7⟩을 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":15,"concept":"M6-1-u1-C6","difficulty":2,"kind":"sa","stem":"⟨4 3/7⟩ ÷ 6을 계산하려고 ⟨4 3/7⟩을 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["31"],"explanation":["대분수는 먼저 가분수로 고쳐요.","4 × 7 + 3 = 31이에요.","⟨4 3/7⟩ = ⟨31/7⟩ — 분자는 31이에요."],"mis":"M6-1-u1-X05","variant_rule":{"alt":[{"stem":"⟨2 3/8⟩ ÷ 5를 계산하려고 ⟨2 3/8⟩을 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["대분수는 먼저 가분수로 고쳐요.","2 × 8 + 3 = 19예요.","⟨2 3/8⟩ = ⟨19/8⟩ — 분자는 19예요."]},{"stem":"⟨3 4/5⟩ ÷ 2를 계산하려고 ⟨3 4/5⟩를 가분수로 고쳤어요. 가분수의 분자는 얼마인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["대분수는 먼저 가분수로 고쳐요.","3 × 5 + 4 = 19예요.","⟨3 4/5⟩ = ⟨19/5⟩ — 분자는 19예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#16','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C7',2,'mc','auto','파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 4개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨3 1/5⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?',ARRAY['M6-1-u1-X13','M6-1-u1-X06']::text[],true,'{"seq":16,"concept":"M6-1-u1-C7","difficulty":2,"kind":"mc","stem":"파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 4개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨3 1/5⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?","options":[{"t":"⟨1 3/5⟩","correct":true},{"t":"⟨4/5⟩","mis":"M6-1-u1-X13"},{"t":"⟨6 2/5⟩","mis":"M6-1-u1-X06"},{"t":"⟨8/15⟩","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 2개씩 덜어 내면 노란 1개 = 파란 2개예요.","⟨3 1/5⟩ = ⟨16/5⟩이에요.","⟨16/5⟩ × ⟨1/2⟩ = ⟨1 3/5⟩ — 파란 뚜껑 1개는 ⟨1 3/5⟩ g이에요."],"variant_rule":{"alt":[{"stem":"파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 5개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨5 1/4⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?","options":[{"t":"⟨1 3/4⟩","correct":true},{"t":"⟨1 1/20⟩","mis":"M6-1-u1-X13"},{"t":"⟨2 5/8⟩","mis":"M6-1-u1-X13"},{"t":"⟨15 3/4⟩","mis":"M6-1-u1-X06"}],"explanation":["양쪽에서 파란 2개씩 덜어 내면 노란 1개 = 파란 3개예요.","⟨5 1/4⟩ = ⟨21/4⟩이에요.","⟨21/4⟩ × ⟨1/3⟩ = ⟨1 3/4⟩ — 파란 뚜껑 1개는 ⟨1 3/4⟩ g이에요."]},{"stem":"파란 뚜껑 1개와 노란 뚜껑 1개의 무게가 파란 뚜껑 3개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개의 무게가 ⟨2 2/3⟩ g일 때, 파란 뚜껑 1개의 무게는 몇 g인가요?","options":[{"t":"⟨1 1/3⟩","correct":true},{"t":"⟨8/9⟩","mis":"M6-1-u1-X13"},{"t":"⟨2 2/3⟩","mis":"M6-1-u1-X13"},{"t":"⟨5 1/3⟩","mis":"M6-1-u1-X06"}],"explanation":["양쪽에서 파란 1개씩 덜어 내면 노란 1개 = 파란 2개예요.","⟨2 2/3⟩ = ⟨8/3⟩이에요.","⟨8/3⟩ × ⟨1/2⟩ = ⟨1 1/3⟩ — 파란 뚜껑 1개는 ⟨1 1/3⟩ g이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#17','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C2',3,'mc','auto','가 모둠은 피자 3판을 5명이, 나 모둠은 피자 5판을 8명이 똑같이 나누었어요. 한 명이 가지는 피자가 더 많은 모둠은 어디인가요?',ARRAY['M6-1-u1-X11','M6-1-u1-X03']::text[],true,'{"seq":17,"concept":"M6-1-u1-C2","difficulty":3,"kind":"mc","stem":"가 모둠은 피자 3판을 5명이, 나 모둠은 피자 5판을 8명이 똑같이 나누었어요. 한 명이 가지는 피자가 더 많은 모둠은 어디인가요?","options":[{"t":"나 모둠","correct":true},{"t":"가 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 3 ÷ 5 = ⟨3/5⟩, 나 모둠은 5 ÷ 8 = ⟨5/8⟩예요.","40으로 통분하면 ⟨3/5⟩ = ⟨24/40⟩, ⟨5/8⟩ = ⟨25/40⟩예요.","⟨3/5⟩ < ⟨5/8⟩라 나 모둠이 더 많아요."],"variant_rule":{"alt":[{"stem":"가 모둠은 시루떡 2개를 5명이, 나 모둠은 시루떡 3개를 7명이 똑같이 나누었어요. 한 명이 가지는 시루떡이 더 많은 모둠은 어디인가요?","options":[{"t":"나 모둠","correct":true},{"t":"가 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 2 ÷ 5 = ⟨2/5⟩, 나 모둠은 3 ÷ 7 = ⟨3/7⟩이에요.","35로 통분하면 ⟨2/5⟩ = ⟨14/35⟩, ⟨3/7⟩ = ⟨15/35⟩예요.","⟨2/5⟩ < ⟨3/7⟩이라 나 모둠이 더 많아요."]},{"stem":"가 모둠은 주스 4 L를 9명이, 나 모둠은 주스 3 L를 8명이 똑같이 나누었어요. 한 명이 가지는 주스가 더 많은 모둠은 어디인가요?","options":[{"t":"가 모둠","correct":true},{"t":"나 모둠","mis":"M6-1-u1-X11"},{"t":"두 모둠이 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["가 모둠 한 명 몫은 4 ÷ 9 = ⟨4/9⟩, 나 모둠은 3 ÷ 8 = ⟨3/8⟩이에요.","72로 통분하면 ⟨4/9⟩ = ⟨32/72⟩, ⟨3/8⟩ = ⟨27/72⟩이에요.","⟨4/9⟩ > ⟨3/8⟩이라 가 모둠이 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#18','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C3',3,'sa','auto','주스 13 L를 3명이 똑같이 나누어 마시려고 해요. 한 명이 마시는 주스를 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M6-1-u1-C3","difficulty":3,"kind":"sa","stem":"주스 13 L를 3명이 똑같이 나누어 마시려고 해요. 한 명이 마시는 주스를 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["13 ÷ 3은 몫 4, 나머지 1이에요.","남은 1도 나누면 13 ÷ 3 = ⟨4 1/3⟩이에요.","자연수 부분과 분자의 합은 4 + 1 = 5예요."],"mis":"M6-1-u1-X15","variant_rule":{"alt":[{"stem":"쌀 19 kg을 4봉지에 똑같이 나누어 담으려고 해요. 한 봉지에 담는 쌀을 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["19 ÷ 4는 몫 4, 나머지 3이에요.","남은 3도 나누면 19 ÷ 4 = ⟨4 3/4⟩이에요.","자연수 부분과 분자의 합은 4 + 3 = 7이에요."]},{"stem":"끈 17 m를 6도막으로 똑같이 나누어 자르려고 해요. 한 도막의 길이를 대분수로 나타낼 때, 자연수 부분과 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["17 ÷ 6은 몫 2, 나머지 5예요.","남은 5도 나누면 17 ÷ 6 = ⟨2 5/6⟩예요.","자연수 부분과 분자의 합은 2 + 5 = 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#19','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C4',3,'mc','auto','끈 8 m를 7도막으로 나눈 한 도막과 끈 9 m를 8도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?',ARRAY['M6-1-u1-X11','M6-1-u1-X03']::text[],true,'{"seq":19,"concept":"M6-1-u1-C4","difficulty":3,"kind":"mc","stem":"끈 8 m를 7도막으로 나눈 한 도막과 끈 9 m를 8도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?","options":[{"t":"끈 8 m를 7도막으로 나눈 한 도막","correct":true},{"t":"끈 9 m를 8도막으로 나눈 한 도막","mis":"M6-1-u1-X11"},{"t":"두 도막의 길이가 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["8 ÷ 7 = 8 × ⟨1/7⟩ = ⟨1 1/7⟩, 9 ÷ 8 = 9 × ⟨1/8⟩ = ⟨1 1/8⟩이에요.","56으로 통분하면 ⟨1 1/7⟩ = ⟨64/56⟩, ⟨1 1/8⟩ = ⟨63/56⟩이에요.","그래서 더 긴 것은 끈 8 m를 7도막으로 나눈 한 도막이에요."],"variant_rule":{"alt":[{"stem":"끈 9 m를 4도막으로 나눈 한 도막과 끈 7 m를 3도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?","options":[{"t":"끈 7 m를 3도막으로 나눈 한 도막","correct":true},{"t":"끈 9 m를 4도막으로 나눈 한 도막","mis":"M6-1-u1-X11"},{"t":"두 도막의 길이가 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["9 ÷ 4 = 9 × ⟨1/4⟩ = ⟨2 1/4⟩, 7 ÷ 3 = 7 × ⟨1/3⟩ = ⟨2 1/3⟩이에요.","12로 통분하면 ⟨2 1/4⟩ = ⟨27/12⟩, ⟨2 1/3⟩ = ⟨28/12⟩이에요.","그래서 더 긴 것은 끈 7 m를 3도막으로 나눈 한 도막이에요."]},{"stem":"끈 6 m를 5도막으로 나눈 한 도막과 끈 5 m를 4도막으로 나눈 한 도막 가운데 더 긴 것은 어느 것인가요?","options":[{"t":"끈 5 m를 4도막으로 나눈 한 도막","correct":true},{"t":"끈 6 m를 5도막으로 나눈 한 도막","mis":"M6-1-u1-X11"},{"t":"두 도막의 길이가 같다","mis":"M6-1-u1-X11"},{"t":"비교할 수 없다","mis":"M6-1-u1-X03"}],"explanation":["6 ÷ 5 = 6 × ⟨1/5⟩ = ⟨1 1/5⟩, 5 ÷ 4 = 5 × ⟨1/4⟩ = ⟨1 1/4⟩이에요.","20으로 통분하면 ⟨1 1/5⟩ = ⟨24/20⟩, ⟨1 1/4⟩ = ⟨25/20⟩예요.","그래서 더 긴 것은 끈 5 m를 4도막으로 나눈 한 도막이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#20','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C5',3,'error','auto','⟨7/8⟩ ÷ 2에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u1-X06','M6-1-u1-X15']::text[],true,'{"seq":20,"concept":"M6-1-u1-C5","difficulty":3,"kind":"error","stem":"⟨7/8⟩ ÷ 2에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「⟨7/8⟩ × 2 = ⟨1 3/4⟩으로 계산해.」","correct":true,"mis_target":"M6-1-u1-X06"},{"t":"라온 — 「⟨7/8⟩ × ⟨1/2⟩로 바꾸어 계산하면 돼.」","mis":"M6-1-u1-X15"},{"t":"예준 — 「몫은 ⟨7/8⟩보다 작아.」","mis":"M6-1-u1-X15"}],"explanation":["2로 나누면 양이 작아져야 해요.","⟨7/8⟩ × 2 = ⟨1 3/4⟩은 오히려 커요.","⟨7/8⟩ ÷ 2 = ⟨7/8⟩ × ⟨1/2⟩ = ⟨7/16⟩ — 여울은 나누는 수를 그대로 곱했어요."],"variant_rule":{"alt":[{"stem":"⟨4/7⟩ ÷ 3에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「⟨4/7⟩ × 3 = ⟨1 5/7⟩로 계산해.」","correct":true,"mis_target":"M6-1-u1-X06"},{"t":"도윤 — 「⟨4/7⟩ × ⟨1/3⟩로 바꾸어 계산하면 돼.」","mis":"M6-1-u1-X15"},{"t":"하린 — 「몫은 ⟨4/7⟩보다 작아.」","mis":"M6-1-u1-X15"}],"explanation":["3으로 나누면 양이 작아져야 해요.","⟨4/7⟩ × 3 = ⟨1 5/7⟩는 오히려 커요.","⟨4/7⟩ ÷ 3 = ⟨4/7⟩ × ⟨1/3⟩ = ⟨4/21⟩ — 수아는 나누는 수를 그대로 곱했어요."]},{"stem":"⟨5/6⟩ ÷ 2에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민준 — 「⟨5/6⟩ × 2 = ⟨1 2/3⟩로 계산해.」","correct":true,"mis_target":"M6-1-u1-X06"},{"t":"서연 — 「⟨5/6⟩ × ⟨1/2⟩로 바꾸어 계산하면 돼.」","mis":"M6-1-u1-X15"},{"t":"지호 — 「몫은 ⟨5/6⟩보다 작아.」","mis":"M6-1-u1-X15"}],"explanation":["2로 나누면 양이 작아져야 해요.","⟨5/6⟩ × 2 = ⟨1 2/3⟩는 오히려 커요.","⟨5/6⟩ ÷ 2 = ⟨5/6⟩ × ⟨1/2⟩ = ⟨5/12⟩ — 민준은 나누는 수를 그대로 곱했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#21','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C6',3,'mc','auto','넓이가 ⟨6 2/3⟩ m²이고 가로가 5 m인 직사각형이 있어요. 세로는 몇 m인가요?',ARRAY['M6-1-u1-X10','M6-1-u1-X06']::text[],true,'{"seq":21,"concept":"M6-1-u1-C6","difficulty":3,"kind":"mc","stem":"넓이가 ⟨6 2/3⟩ m²이고 가로가 5 m인 직사각형이 있어요. 세로는 몇 m인가요?","options":[{"t":"⟨1 1/3⟩","correct":true},{"t":"⟨6 2/15⟩","mis":"M6-1-u1-X10"},{"t":"⟨1 13/15⟩","mis":"M6-1-u1-X10"},{"t":"⟨33 1/3⟩","mis":"M6-1-u1-X06"}],"explanation":["(직사각형의 넓이) = (가로) × (세로)이니 세로 = 넓이 ÷ 가로예요.","⟨6 2/3⟩ ÷ 5 = ⟨20/3⟩ × ⟨1/5⟩이에요.","⟨20/3⟩ × ⟨1/5⟩ = ⟨1 1/3⟩ — 세로는 ⟨1 1/3⟩ m예요."],"variant_rule":{"alt":[{"stem":"넓이가 ⟨4 2/3⟩ m²이고 가로가 3 m인 직사각형이 있어요. 세로는 몇 m인가요?","options":[{"t":"⟨1 5/9⟩","correct":true},{"t":"⟨4 2/9⟩","mis":"M6-1-u1-X10"},{"t":"2","mis":"M6-1-u1-X10"},{"t":"14","mis":"M6-1-u1-X06"}],"explanation":["(직사각형의 넓이) = (가로) × (세로)이니 세로 = 넓이 ÷ 가로예요.","⟨4 2/3⟩ ÷ 3 = ⟨14/3⟩ × ⟨1/3⟩이에요.","⟨14/3⟩ × ⟨1/3⟩ = ⟨1 5/9⟩ — 세로는 ⟨1 5/9⟩ m예요."]},{"stem":"넓이가 ⟨5 1/4⟩ m²이고 가로가 2 m인 직사각형이 있어요. 세로는 몇 m인가요?","options":[{"t":"⟨2 5/8⟩","correct":true},{"t":"⟨5 1/8⟩","mis":"M6-1-u1-X10"},{"t":"⟨2 3/4⟩","mis":"M6-1-u1-X10"},{"t":"⟨10 1/2⟩","mis":"M6-1-u1-X06"}],"explanation":["(직사각형의 넓이) = (가로) × (세로)이니 세로 = 넓이 ÷ 가로예요.","⟨5 1/4⟩ ÷ 2 = ⟨21/4⟩ × ⟨1/2⟩이에요.","⟨21/4⟩ × ⟨1/2⟩ = ⟨2 5/8⟩ — 세로는 ⟨2 5/8⟩ m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#22','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C7',3,'sa','auto','조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨1 5/7⟩ g이고 파란 뚜껑 4개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M6-1-u1-C7","difficulty":3,"kind":"sa","stem":"조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨1 5/7⟩ g이고 파란 뚜껑 4개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["파란 뚜껑 1개 = ⟨1 5/7⟩ ÷ 4예요.","⟨12/7⟩ ÷ 4 = ⟨12/7⟩ × ⟨1/4⟩ = ⟨3/7⟩이에요.","분모와 분자의 합은 7 + 3 = 10이에요."],"mis":"M6-1-u1-X15","variant_rule":{"alt":[{"stem":"조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨2 1/3⟩ g이고 파란 뚜껑 7개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["파란 뚜껑 1개 = ⟨2 1/3⟩ ÷ 7이에요.","⟨7/3⟩ ÷ 7 = ⟨7/3⟩ × ⟨1/7⟩ = ⟨1/3⟩이에요.","분모와 분자의 합은 3 + 1 = 4예요."]},{"stem":"조건을 바꾸어 보아요. 노란 뚜껑 1개가 ⟨3 3/4⟩ g이고 파란 뚜껑 5개와 무게가 같아요. 파란 뚜껑 1개의 무게를 기약분수(가분수)로 나타낼 때 분모와 분자의 합은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["파란 뚜껑 1개 = ⟨3 3/4⟩ ÷ 5예요.","⟨15/4⟩ ÷ 5 = ⟨15/4⟩ × ⟨1/5⟩ = ⟨3/4⟩이에요.","분모와 분자의 합은 4 + 3 = 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#23','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C6',4,'sa','auto','자연수 부분이 □이고 분수 부분이 ⟨2/5⟩인 대분수를 4로 나누었더니 ⟨17/20⟩이 되었어요. □에 알맞은 자연수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M6-1-u1-C6","difficulty":4,"kind":"sa","stem":"자연수 부분이 □이고 분수 부분이 ⟨2/5⟩인 대분수를 4로 나누었더니 ⟨17/20⟩이 되었어요. □에 알맞은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["나누기 전의 수는 ⟨17/20⟩ × 4예요.","⟨17/20⟩ × 4 = ⟨17/5⟩ = ⟨3 2/5⟩예요.","그래서 □는 3이에요."],"mis":"M6-1-u1-X10","variant_rule":{"alt":[{"stem":"□ ÷ 11의 몫이 1보다 작을 때, □에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["□ ÷ 11 = ⟨□/11⟩이에요.","몫이 1보다 작으려면 □가 11보다 작아야 해요.","1부터 10까지 10개예요."]},{"stem":"□ ÷ 7의 몫이 3보다 크고 4보다 작을 때, □에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["21 ÷ 7 = 3, 28 ÷ 7 = 4예요.","□는 21보다 크고 28보다 작아야 해요.","22부터 27까지 6개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#24','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C5',4,'essay','teacher','친구가 ⟨3/5⟩ ÷ 4를 ⟨3/5⟩ × 4 = ⟨12/5⟩로 계산했어요. 이 답이 맞지 않음을 몫의 크기로 설명하고, 바르게 계산해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-1-u1-C5","difficulty":4,"kind":"essay","stem":"친구가 ⟨3/5⟩ ÷ 4를 ⟨3/5⟩ × 4 = ⟨12/5⟩로 계산했어요. 이 답이 맞지 않음을 몫의 크기로 설명하고, 바르게 계산해 보세요.","answer_guide":{"answer":"예: ⟨3/5⟩을 4로 나누면 몫은 ⟨3/5⟩보다 작아야 하는데 ⟨12/5⟩는 ⟨3/5⟩보다 커서 맞지 않는다. ÷ 4는 × ⟨1/4⟩이므로 ⟨3/5⟩ ÷ 4 = ⟨3/5⟩ × ⟨1/4⟩ = ⟨3/20⟩이다.","scoring_points":["나누면 작아져야 하는데 ⟨12/5⟩는 커졌다고 썼는가","÷ 4를 × ⟨1/4⟩로 바꾸었는가","⟨3/20⟩을 구했는가"]},"explanation":["⟨3/5⟩ ÷ 4는 ⟨3/5⟩보다 작아야 해요.","⟨12/5⟩는 오히려 커요.","⟨3/5⟩ × ⟨1/4⟩ = ⟨3/20⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u1_review_d#25','math',6,1,'u1','','g6_1_math_u1_review_d','unit_review','M6-1-u1-C5',4,'essay','teacher','손 세정제 ⟨4/5⟩ L를 3병에 똑같이 나누어 담으려고 해요. 분자 4가 3으로 나누어떨어지지 않을 때 한 병에 담는 양을 구하는 방법을 설명하고 답을 구해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-1-u1-C5","difficulty":4,"kind":"essay","stem":"손 세정제 ⟨4/5⟩ L를 3병에 똑같이 나누어 담으려고 해요. 분자 4가 3으로 나누어떨어지지 않을 때 한 병에 담는 양을 구하는 방법을 설명하고 답을 구해 보세요.","answer_guide":{"answer":"예: 분자 4는 3으로 나누어떨어지지 않으므로 ⟨4/5⟩ 전체를 3등분한 것 중의 1을 구한다. 이것은 ⟨4/5⟩에 ⟨1/3⟩을 곱하는 것과 같아 ⟨4/5⟩ ÷ 3 = ⟨4/5⟩ × ⟨1/3⟩ = ⟨4/15⟩이다. 한 병에는 ⟨4/15⟩ L를 담는다.","scoring_points":["분자가 나누어떨어지지 않음을 짚었는가","÷ 3을 × ⟨1/3⟩로 바꾸는 방법을 썼는가","⟨4/15⟩ L를 구했는가"]},"explanation":["분자 4는 3으로 나누어떨어지지 않아요.","⟨4/5⟩ ÷ 3 = ⟨4/5⟩ × ⟨1/3⟩이에요.","한 병에는 ⟨4/15⟩ L예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u2-C1','math',6,1,'u2',2,'각기둥의 뜻 — 직육면체를 되짚고, 두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형을 각기둥이라 하며, 그 두 면이 밑면(위치가 아니라 관계로 정함), 두 밑면과 만나는 면이 옆면(모두 직사각형, 밑면과 수직)임을 알기',ARRAY['6수03-02']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u2-C2','math',6,1,'u2',3,'각기둥의 이름과 구성 요소 — 밑면의 모양에 따라 삼각기둥·사각기둥…으로 부르고, 모서리(면과 면이 만나는 선분)·꼭짓점(모서리와 모서리가 만나는 점)·높이(두 밑면 사이의 거리)를 찾고 세기',ARRAY['6수03-02']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u2-C3','math',6,1,'u2',4,'각기둥의 전개도 알기 — 모든 면이 이어지도록 모서리를 잘라 펼친 그림이 전개도이고, 실선은 잘린 모서리·점선은 접히는 모서리이며, 옆면의 수 = 한 밑면의 변의 수, 맞닿는 선분의 길이는 같음을 알기',ARRAY['6수03-03']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u2-C4','math',6,1,'u2',5,'각기둥의 전개도 그리기 — 밑면 2개와 옆면(변의 수만큼)을 그리고, 옆면의 가로는 밑면의 변의 길이·세로는 높이와 같게 맞추며, 자르는 모서리에 따라 모양이 다른 전개도가 여럿 나옴을 알기',ARRAY['6수03-03']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u2-C5','math',6,1,'u2',6,'각뿔의 뜻 — 한 면이 다각형이고 다른 면이 모두 삼각형인 입체도형을 각뿔이라 하고, 다각형인 면이 밑면(1개), 밑면과 만나는 면이 옆면(모두 삼각형)이며 각기둥·원뿔과 구별하기',ARRAY['6수03-02']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u2-C6','math',6,1,'u2',7,'각뿔의 이름과 구성 요소 — 밑면의 모양에 따라 삼각뿔·사각뿔…으로 부르고, 옆면이 모두 만나는 점(각뿔의 꼭짓점)을 빠뜨리지 않고 세며, 높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이임을 알기',ARRAY['6수03-02']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u2-C7','math',6,1,'u2',8,'규칙 찾기 — 한 밑면의 변의 수로 각기둥(면 +2·꼭짓점 ×2·모서리 ×3)과 각뿔(면 +1·꼭짓점 +1·모서리 ×2)의 수를 구하고, 거꾸로 수에서 입체도형의 이름을 찾으며 규칙이 세는 방법에서 나옴을 설명하기',ARRAY['6수03-02']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u2-X01','math',6,'u2',ARRAY['M6-1-u2-C1','M6-1-u2-C3','M6-1-u2-C5']::text[],'밑면을 「아래에 놓인 면」으로만 여겨, 눕혀 놓으면 밑면을 옆면이라 부른다','밑면은 위치가 아니라 평행·합동으로 찾아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u2-X02','math',6,'u2',ARRAY['M6-1-u2-C1']::text[],'평행한 두 면만 보고 합동인지·옆면이 직사각형인지·굽은 면이 없는지를 확인하지 않는다','평행·합동·모두 다각형 — 세 기준') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u2-X03','math',6,'u2',ARRAY['M6-1-u2-C1','M6-1-u2-C5']::text[],'옆면의 모양을 바꾸어 기억한다(각기둥 옆면을 삼각형·사다리꼴로, 각뿔 옆면을 직사각형으로)','기둥 옆면은 직사각형, 뿔 옆면은 삼각형') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u2-X04','math',6,'u2',ARRAY['M6-1-u2-C2','M6-1-u2-C6','M6-1-u2-C7']::text[],'이름을 밑면이 아니라 꼭짓점·모서리·면의 수로 붙인다(꼭짓점이 10개인 각기둥을 십각기둥으로)','이름은 밑면의 변의 수가 정해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u2-X05','math',6,'u2',ARRAY['M6-1-u2-C2','M6-1-u2-C6']::text[],'면·모서리·꼭짓점의 뜻을 서로 바꾸어 안다','면이 만나면 모서리, 모서리가 만나면 꼭짓점') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u2-X06','math',6,'u2',ARRAY['M6-1-u2-C2','M6-1-u2-C6']::text[],'높이를 잘못 잡는다(밑면의 변을 높이로, 각뿔의 옆 모서리를 높이로)','기둥은 두 밑면 사이, 뿔은 꼭짓점에서 수직으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u2-X07','math',6,'u2',ARRAY['M6-1-u2-C3','M6-1-u2-C4']::text[],'전개도의 실선·점선 뜻을 거꾸로 알거나, 면이 떨어져 있어도 전개도라 여긴다','실선은 자른 곳, 점선은 접는 곳') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u2-X08','math',6,'u2',ARRAY['M6-1-u2-C3','M6-1-u2-C4']::text[],'전개도의 밑면·옆면 수를 잘못 센다(옆면 수를 변의 수와 다르게, 밑면을 1개로)','밑면 2개, 옆면은 변의 수만큼') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u2-X09','math',6,'u2',ARRAY['M6-1-u2-C3','M6-1-u2-C4']::text[],'옆면의 가로·세로를 바꾸어 잡거나 맞닿는 선분의 길이를 맞추지 않는다','가로는 밑면의 변, 세로는 높이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u2-X10','math',6,'u2',ARRAY['M6-1-u2-C5','M6-1-u2-C6','M6-1-u2-C7']::text[],'각뿔의 꼭짓점을 빠뜨리고 세거나 각뿔의 밑면을 2개로 센다','위의 한 점을 꼭 더해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u2-X11','math',6,'u2',ARRAY['M6-1-u2-C1','M6-1-u2-C5']::text[],'각기둥과 각뿔(또는 원기둥·원뿔)을 섞어 부르거나 성질을 옮겨 쓴다','밑면이 몇 개? 옆면은 무슨 모양?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u2-X12','math',6,'u2',ARRAY['M6-1-u2-C2','M6-1-u2-C6','M6-1-u2-C7']::text[],'규칙을 섞는다 — 각기둥의 규칙(+2·×2·×3)을 각뿔에 쓰거나 면·꼭짓점·모서리 자리를 바꾼다','규칙은 세는 방법에서 나와요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u2-X13','math',6,'u2',ARRAY['M6-1-u2-C3','M6-1-u2-C4']::text[],'같은 각기둥의 전개도는 하나뿐이라 여기거나, 접으면 면이 겹치는 그림도 전개도라 여긴다','자르는 모서리가 달라지면 모양이 달라져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u2-X14','math',6,'u2',ARRAY['M6-1-u2-C1','M6-1-u2-C2','M6-1-u2-C3','M6-1-u2-C4','M6-1-u2-C5','M6-1-u2-C6','M6-1-u2-C7']::text[],'묻는 말을 거꾸로 읽거나 놓친다 — 잘못된↔알맞은, 합↔차, 밑면만↔모두','물음의 「잘못·모두·합·차」에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L02_basic#1','math',6,1,'u2','L02','g6_1_math_u2_L02_basic','lesson_basic','M6-1-u2-C1',1,'sa','auto','5학년에서 배운 직육면체의 면은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u2-C1","difficulty":1,"kind":"sa","stem":"5학년에서 배운 직육면체의 면은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["직육면체는 직사각형 6개로 둘러싸인 입체도형이에요.","앞뒤·위아래·양옆 — 직사각형이 2개씩 3쌍이에요.","그래서 면은 6개예요."],"mis":"M6-1-u2-X05","variant_rule":{"alt":[{"stem":"5학년에서 배운 직육면체의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["직육면체는 직사각형 6개로 둘러싸인 입체도형이에요.","면과 면이 만나는 선분이 4개씩 3방향 — 4 × 3 = 12개예요.","그래서 모서리는 12개예요."]},{"stem":"5학년에서 배운 직육면체의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["직육면체는 직사각형 6개로 둘러싸인 입체도형이에요.","위에 4개, 아래에 4개 — 4 + 4 = 8개예요.","그래서 꼭짓점은 8개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L02_basic#2','math',6,1,'u2','L02','g6_1_math_u2_L02_basic','lesson_basic','M6-1-u2-C1',1,'mc','auto','두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형을 무엇이라고 하나요?',ARRAY['M6-1-u2-X11']::text[],true,'{"seq":2,"concept":"M6-1-u2-C1","difficulty":1,"kind":"mc","stem":"두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형을 무엇이라고 하나요?","options":[{"t":"각기둥","correct":true},{"t":"밑면","mis":"M6-1-u2-X11"},{"t":"옆면","mis":"M6-1-u2-X11"},{"t":"각뿔","mis":"M6-1-u2-X11"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형이에요.","그 두 면이 밑면, 두 밑면과 만나는 면이 옆면이에요.","그래서 답은 「각기둥」이에요."],"variant_rule":{"alt":[{"stem":"각기둥에서 서로 평행하고 합동인 두 면을 무엇이라고 하나요?","options":[{"t":"밑면","correct":true},{"t":"각기둥","mis":"M6-1-u2-X01"},{"t":"옆면","mis":"M6-1-u2-X01"},{"t":"각뿔","mis":"M6-1-u2-X01"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형이에요.","그 두 면이 밑면, 두 밑면과 만나는 면이 옆면이에요.","그래서 답은 「밑면」이에요."]},{"stem":"두 밑면과 만나는 면을 무엇이라고 하나요?","options":[{"t":"옆면","correct":true},{"t":"각기둥","mis":"M6-1-u2-X01"},{"t":"밑면","mis":"M6-1-u2-X01"},{"t":"각뿔","mis":"M6-1-u2-X01"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형이에요.","그 두 면이 밑면, 두 밑면과 만나는 면이 옆면이에요.","그래서 답은 「옆면」이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L02_basic#3','math',6,1,'u2','L02','g6_1_math_u2_L02_basic','lesson_basic','M6-1-u2-C1',1,'mc','auto','각기둥의 옆면은 모두 어떤 도형인가요?',ARRAY['M6-1-u2-X03','M6-1-u2-X01']::text[],true,'{"seq":3,"concept":"M6-1-u2-C1","difficulty":1,"kind":"mc","stem":"각기둥의 옆면은 모두 어떤 도형인가요?","options":[{"t":"직사각형","correct":true},{"t":"삼각형","mis":"M6-1-u2-X03"},{"t":"사다리꼴","mis":"M6-1-u2-X03"},{"t":"밑면과 같은 다각형","mis":"M6-1-u2-X01"}],"explanation":["각기둥은 두 밑면이 서로 평행하고 합동인 다각형이에요.","옆면은 모두 직사각형이고 두 밑면과 수직으로 만나요.","그래서 답은 「직사각형」이에요."],"variant_rule":{"alt":[{"stem":"각기둥의 옆면은 두 밑면과 어떻게 만나나요?","options":[{"t":"수직으로 만나요","correct":true},{"t":"비스듬히 기울어져 만나요","mis":"M6-1-u2-X03"},{"t":"한 점에서 모두 만나요","mis":"M6-1-u2-X11"},{"t":"만나지 않아요","mis":"M6-1-u2-X01"}],"explanation":["각기둥은 두 밑면이 서로 평행하고 합동인 다각형이에요.","옆면은 모두 직사각형이고 두 밑면과 수직으로 만나요.","그래서 답은 「수직으로 만나요」예요."]},{"stem":"각기둥의 두 밑면은 서로 어떤 관계인가요?","options":[{"t":"서로 평행하고 합동이에요","correct":true},{"t":"서로 수직이에요","mis":"M6-1-u2-X01"},{"t":"평행하지만 크기가 달라요","mis":"M6-1-u2-X02"},{"t":"한 꼭짓점에서 만나요","mis":"M6-1-u2-X11"}],"explanation":["각기둥은 두 밑면이 서로 평행하고 합동인 다각형이에요.","옆면은 모두 직사각형이고 두 밑면과 수직으로 만나요.","그래서 답은 「서로 평행하고 합동이에요」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L02_basic#4','math',6,1,'u2','L02','g6_1_math_u2_L02_basic','lesson_basic','M6-1-u2-C1',1,'sa','auto','밑면이 육각형인 각기둥의 옆면은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u2-C1","difficulty":1,"kind":"sa","stem":"밑면이 육각형인 각기둥의 옆면은 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["각기둥의 밑면은 서로 평행하고 합동인 두 면이에요.","옆면은 밑면의 변 하나마다 하나씩 세워져요.","밑면의 변 하나마다 옆면이 하나 — 6개예요."],"mis":"M6-1-u2-X14","variant_rule":{"alt":[{"stem":"밑면이 오각형인 각기둥의 옆면은 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["각기둥의 밑면은 서로 평행하고 합동인 두 면이에요.","옆면은 밑면의 변 하나마다 하나씩 세워져요.","밑면의 변 하나마다 옆면이 하나 — 5개예요."]},{"stem":"각기둥에서 밑면은 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["각기둥의 밑면은 서로 평행하고 합동인 두 면이에요.","옆면은 밑면의 변 하나마다 하나씩 세워져요.","서로 평행하고 합동인 두 면 — 2개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L02_basic#5','math',6,1,'u2','L02','g6_1_math_u2_L02_basic','lesson_basic','M6-1-u2-C1',2,'mc','auto','기둥 모양과 뿔 모양을 가르는 기준으로 가장 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u2-X14']::text[],true,'{"seq":5,"concept":"M6-1-u2-C1","difficulty":2,"kind":"mc","stem":"기둥 모양과 뿔 모양을 가르는 기준으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"서로 평행하고 합동인 다각형이 둘인지, 하나이고 나머지가 삼각형인지","correct":true},{"t":"색깔이 서로 다른지","mis":"M6-1-u2-X14"},{"t":"크기가 큰지 작은지","mis":"M6-1-u2-X14"},{"t":"면의 수가 짝수인지","mis":"M6-1-u2-X14"}],"explanation":["입체도형은 둘러싼 면을 보고 나눠요.","위아래에 똑같은 다각형이 둘이면 기둥 모양, 다각형이 하나이고 나머지가 삼각형이면 뿔 모양이에요.","색이나 크기는 모양을 가르는 기준이 아니에요."],"variant_rule":{"alt":[{"stem":"조각 공원의 뾰족한 작품은 아래에 다각형이 하나 있고 나머지 면이 모두 한 점으로 모여요. 어떤 모양이라고 할 수 있나요?","options":[{"t":"뿔 모양","correct":true},{"t":"기둥 모양","mis":"M6-1-u2-X11"},{"t":"직육면체 모양","mis":"M6-1-u2-X11"},{"t":"공 모양","mis":"M6-1-u2-X11"}],"explanation":["입체도형은 둘러싼 면을 보고 나눠요.","위아래에 똑같은 다각형이 둘이면 기둥 모양, 다각형이 하나이고 나머지가 삼각형이면 뿔 모양이에요.","색이나 크기는 모양을 가르는 기준이 아니에요."]},{"stem":"위와 아래에 똑같은 다각형이 마주 보고 있는 작품은 어떤 모양이라고 할 수 있나요?","options":[{"t":"기둥 모양","correct":true},{"t":"뿔 모양","mis":"M6-1-u2-X11"},{"t":"공 모양","mis":"M6-1-u2-X11"},{"t":"평면도형","mis":"M6-1-u2-X14"}],"explanation":["입체도형은 둘러싼 면을 보고 나눠요.","위아래에 똑같은 다각형이 둘이면 기둥 모양, 다각형이 하나이고 나머지가 삼각형이면 뿔 모양이에요.","색이나 크기는 모양을 가르는 기준이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L02_basic#6','math',6,1,'u2','L02','g6_1_math_u2_L02_basic','lesson_basic','M6-1-u2-C1',2,'mc','auto','다음 가운데 각기둥 모양인 것은 어느 것인가요?',ARRAY['M6-1-u2-X02','M6-1-u2-X11']::text[],true,'{"seq":6,"concept":"M6-1-u2-C1","difficulty":2,"kind":"mc","stem":"다음 가운데 각기둥 모양인 것은 어느 것인가요?","options":[{"t":"서로 평행하고 합동인 두 오각형과 직사각형 5개로 둘러싸인 저금통","correct":true},{"t":"서로 평행한 두 사각형의 크기가 서로 다른 저금통","mis":"M6-1-u2-X02"},{"t":"한 면이 사각형이고 나머지 면이 모두 삼각형인 저금통","mis":"M6-1-u2-X11"},{"t":"위아래 면이 서로 평행하고 합동인 원인 저금통","mis":"M6-1-u2-X02"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형이에요.","보기를 하나씩 이 뜻에 대어 봐요 — 크기가 다르거나 굽은 면이 있으면 안 돼요.","「서로 평행하고 합동인 두 오각형과 직사각형 5개로 둘러싸인 저금통」이 각기둥이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 가운데 각기둥 모양인 것은 어느 것인가요?","options":[{"t":"서로 평행하고 합동인 두 삼각형과 직사각형 3개로 둘러싸인 상자","correct":true},{"t":"서로 평행한 두 사각형의 크기가 서로 다른 저금통","mis":"M6-1-u2-X02"},{"t":"굽은 면 하나로만 둘러싸인 공 모양 저금통","mis":"M6-1-u2-X02"},{"t":"한 원과 뾰족한 점이 있는 고깔","mis":"M6-1-u2-X11"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형이에요.","보기를 하나씩 이 뜻에 대어 봐요 — 크기가 다르거나 굽은 면이 있으면 안 돼요.","「서로 평행하고 합동인 두 삼각형과 직사각형 3개로 둘러싸인 상자」가 각기둥이에요."]},{"stem":"이번에는 다른 보기예요. 다음 가운데 각기둥 모양인 것은 어느 것인가요?","options":[{"t":"서로 평행하고 합동인 두 육각형과 직사각형 6개로 둘러싸인 연필","correct":true},{"t":"한 면이 사각형이고 나머지 면이 모두 삼각형인 저금통","mis":"M6-1-u2-X11"},{"t":"위아래 면이 서로 평행하고 합동인 원인 저금통","mis":"M6-1-u2-X02"},{"t":"서로 평행한 두 사각형의 크기가 서로 다른 저금통","mis":"M6-1-u2-X02"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형이에요.","보기를 하나씩 이 뜻에 대어 봐요 — 크기가 다르거나 굽은 면이 있으면 안 돼요.","「서로 평행하고 합동인 두 육각형과 직사각형 6개로 둘러싸인 연필」이 각기둥이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L02_basic#7','math',6,1,'u2','L02','g6_1_math_u2_L02_basic','lesson_basic','M6-1-u2-C1',2,'mc','auto','오각기둥 모양 저금통을 옆으로 눕혀 놓았어요. 이때 바닥이 아니라 양옆에 서 있는 두 오각형은 무엇인가요?',ARRAY['M6-1-u2-X01','M6-1-u2-X05']::text[],true,'{"seq":7,"concept":"M6-1-u2-C1","difficulty":2,"kind":"mc","stem":"오각기둥 모양 저금통을 옆으로 눕혀 놓았어요. 이때 바닥이 아니라 양옆에 서 있는 두 오각형은 무엇인가요?","options":[{"t":"밑면","correct":true},{"t":"옆면","mis":"M6-1-u2-X01"},{"t":"모서리","mis":"M6-1-u2-X05"},{"t":"높이","mis":"M6-1-u2-X05"}],"explanation":["밑면은 아래에 놓인 면이 아니에요.","서로 평행하고 합동인 두 오각형이 밑면이에요.","눕혀도 그 관계는 그대로라 두 오각형은 여전히 밑면이에요."],"variant_rule":{"alt":[{"stem":"육각기둥 모양 저금통을 옆으로 눕혀 놓았어요. 이때 바닥이 아니라 양옆에 서 있는 두 육각형은 무엇인가요?","options":[{"t":"밑면","correct":true},{"t":"옆면","mis":"M6-1-u2-X01"},{"t":"모서리","mis":"M6-1-u2-X05"},{"t":"높이","mis":"M6-1-u2-X05"}],"explanation":["밑면은 아래에 놓인 면이 아니에요.","서로 평행하고 합동인 두 육각형이 밑면이에요.","눕혀도 그 관계는 그대로라 두 육각형은 여전히 밑면이에요."]},{"stem":"삼각기둥 모양 저금통을 옆으로 눕혀 놓았어요. 이때 바닥이 아니라 양옆에 서 있는 두 삼각형은 무엇인가요?","options":[{"t":"밑면","correct":true},{"t":"옆면","mis":"M6-1-u2-X01"},{"t":"모서리","mis":"M6-1-u2-X05"},{"t":"높이","mis":"M6-1-u2-X05"}],"explanation":["밑면은 아래에 놓인 면이 아니에요.","서로 평행하고 합동인 두 삼각형이 밑면이에요.","눕혀도 그 관계는 그대로라 두 삼각형은 여전히 밑면이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L02_basic#8','math',6,1,'u2','L02','g6_1_math_u2_L02_basic','lesson_basic','M6-1-u2-C1',2,'ox','auto','각기둥의 밑면은 언제나 바닥에 닿은 면이에요.',ARRAY['M6-1-u2-X01']::text[],true,'{"seq":8,"concept":"M6-1-u2-C1","difficulty":2,"kind":"ox","stem":"각기둥의 밑면은 언제나 바닥에 닿은 면이에요.","answer":"X","reason_options":[{"t":"밑면은 위치가 아니라 서로 평행하고 합동인 두 면이라는 관계로 정해지기 때문에","correct":true},{"t":"각기둥은 바닥에 닿은 면을 밑면이라고 정했기 때문에","mis":"M6-1-u2-X01"}],"mis":"M6-1-u2-X01","explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형이에요.","그 두 면이 밑면, 두 밑면과 만나는 직사각형이 옆면이에요.","밑면은 놓인 위치가 아니라 관계로 정해져요."],"variant_rule":{"alt":[{"stem":"각기둥의 옆면은 모두 직사각형이에요.","answer":"O","reason_options":[{"t":"옆면은 두 밑면과 수직으로 만나는 직사각형이기 때문에","correct":true},{"t":"옆면은 밑면과 모양이 같기 때문에","mis":"M6-1-u2-X03"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형이에요.","그 두 면이 밑면, 두 밑면과 만나는 직사각형이 옆면이에요.","밑면은 놓인 위치가 아니라 관계로 정해져요."]},{"stem":"각기둥의 밑면은 2개예요.","answer":"O","reason_options":[{"t":"서로 평행하고 합동인 두 면이 밑면이기 때문에","correct":true},{"t":"위에 있는 면 하나만 밑면이기 때문에","mis":"M6-1-u2-X01"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형이에요.","그 두 면이 밑면, 두 밑면과 만나는 직사각형이 옆면이에요.","밑면은 놓인 위치가 아니라 관계로 정해져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L02_basic#9','math',6,1,'u2','L02','g6_1_math_u2_L02_basic','lesson_basic','M6-1-u2-C1',2,'sa','auto','밑면이 사각형인 각기둥은 밑면과 옆면을 합해 면이 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u2-C1","difficulty":2,"kind":"sa","stem":"밑면이 사각형인 각기둥은 밑면과 옆면을 합해 면이 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["각기둥의 밑면은 서로 평행하고 합동인 두 면이에요.","옆면은 밑면의 변 하나마다 하나씩 세워져요.","밑면 2개와 옆면 4개 — 4 + 2 = 6개예요."],"mis":"M6-1-u2-X14","variant_rule":{"alt":[{"stem":"밑면이 육각형인 각기둥은 밑면과 옆면을 합해 면이 모두 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["각기둥의 밑면은 서로 평행하고 합동인 두 면이에요.","옆면은 밑면의 변 하나마다 하나씩 세워져요.","밑면 2개와 옆면 6개 — 6 + 2 = 8개예요."]},{"stem":"밑면이 오각형인 각기둥은 밑면과 옆면을 합해 면이 모두 몇 개인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["각기둥의 밑면은 서로 평행하고 합동인 두 면이에요.","옆면은 밑면의 변 하나마다 하나씩 세워져요.","밑면 2개와 옆면 5개 — 5 + 2 = 7개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L02_basic#10','math',6,1,'u2','L02','g6_1_math_u2_L02_basic','lesson_basic','M6-1-u2-C1',3,'mc','auto','「서로 평행한 두 오각형의 크기가 다른 입체도형」은 각기둥이 아니에요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u2-X02']::text[],true,'{"seq":10,"concept":"M6-1-u2-C1","difficulty":3,"kind":"mc","stem":"「서로 평행한 두 오각형의 크기가 다른 입체도형」은 각기둥이 아니에요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"평행한 두 면이 서로 합동이 아니기 때문에","correct":true},{"t":"옆면이 직사각형이 아니고 밑면과 수직으로 만나지 않기 때문에","mis":"M6-1-u2-X02"},{"t":"밑면이 다각형이 아니고 굽은 면이 있기 때문에","mis":"M6-1-u2-X02"},{"t":"서로 평행하고 합동인 두 면이 없기 때문에","mis":"M6-1-u2-X02"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형이고, 옆면은 모두 직사각형이에요.","「서로 평행한 두 오각형의 크기가 다른 입체도형」을 이 조건에 하나씩 대어 봐요.","평행한 두 면이 서로 합동이 아니기 때문에 각기둥이 아니에요."],"variant_rule":{"alt":[{"stem":"「서로 평행하고 합동인 두 원과 굽은 옆면으로 둘러싸인 입체도형」은 각기둥이 아니에요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"밑면이 다각형이 아니고 굽은 면이 있기 때문에","correct":true},{"t":"평행한 두 면이 서로 합동이 아니기 때문에","mis":"M6-1-u2-X11"},{"t":"옆면이 직사각형이 아니고 밑면과 수직으로 만나지 않기 때문에","mis":"M6-1-u2-X11"},{"t":"서로 평행하고 합동인 두 면이 없기 때문에","mis":"M6-1-u2-X11"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형이고, 옆면은 모두 직사각형이에요.","「서로 평행하고 합동인 두 원과 굽은 옆면으로 둘러싸인 입체도형」을 이 조건에 하나씩 대어 봐요.","밑면이 다각형이 아니고 굽은 면이 있기 때문에 각기둥이 아니에요."]},{"stem":"「한 면이 육각형이고 나머지 면이 모두 삼각형인 입체도형」은 각기둥이 아니에요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"서로 평행하고 합동인 두 면이 없기 때문에","correct":true},{"t":"평행한 두 면이 서로 합동이 아니기 때문에","mis":"M6-1-u2-X11"},{"t":"옆면이 직사각형이 아니고 밑면과 수직으로 만나지 않기 때문에","mis":"M6-1-u2-X11"},{"t":"밑면이 다각형이 아니고 굽은 면이 있기 때문에","mis":"M6-1-u2-X11"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형이고, 옆면은 모두 직사각형이에요.","「한 면이 육각형이고 나머지 면이 모두 삼각형인 입체도형」을 이 조건에 하나씩 대어 봐요.","서로 평행하고 합동인 두 면이 없기 때문에 각기둥이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L02_challenge#1','math',6,1,'u2','L02','g6_1_math_u2_L02_challenge','lesson_challenge','M6-1-u2-C1',2,'sa','auto','한 모서리가 4 cm인 정육면체가 있어요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u2-C1","difficulty":2,"kind":"sa","stem":"한 모서리가 4 cm인 정육면체가 있어요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["48"],"explanation":["정육면체의 모서리는 모두 12개이고 길이가 모두 같아요.","한 모서리가 4 cm예요.","4 × 12 = 48 — 모두 48 cm예요."],"mis":"M6-1-u2-X14","variant_rule":{"alt":[{"stem":"한 모서리가 5 cm인 정육면체가 있어요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["정육면체의 모서리는 모두 12개이고 길이가 모두 같아요.","한 모서리가 5 cm예요.","5 × 12 = 60 — 모두 60 cm예요."]},{"stem":"한 모서리가 7 cm인 정육면체가 있어요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["84"],"explanation":["정육면체의 모서리는 모두 12개이고 길이가 모두 같아요.","한 모서리가 7 cm예요.","7 × 12 = 84 — 모두 84 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L02_challenge#2','math',6,1,'u2','L02','g6_1_math_u2_L02_challenge','lesson_challenge','M6-1-u2-C1',2,'match','auto','알맞은 것끼리 이으세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u2-C1","difficulty":2,"kind":"match","stem":"알맞은 것끼리 이으세요.","pairs":[{"l":"각기둥의 옆면","r":"모두 직사각형"},{"l":"각기둥의 두 밑면","r":"평행하고 합동인 다각형"},{"l":"옆면과 밑면이 만나는 모양","r":"수직"}],"mis":"M6-1-u2-X03","explanation":["각기둥의 두 밑면은 서로 평행하고 합동인 다각형이에요.","옆면은 두 밑면과 만나는 면이고 모두 직사각형이에요.","직육면체는 면 6개·모서리 12개·꼭짓점 8개예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 알맞은 것끼리 이으세요.","pairs":[{"l":"서로 평행하고 합동인 두 면","r":"밑면"},{"l":"두 밑면과 만나는 면","r":"옆면"},{"l":"평행하고 합동인 다각형으로 이루어진 입체도형","r":"각기둥"}],"explanation":["각기둥의 두 밑면은 서로 평행하고 합동인 다각형이에요.","옆면은 두 밑면과 만나는 면이고 모두 직사각형이에요.","직육면체는 면 6개·모서리 12개·꼭짓점 8개예요."]},{"stem":"이번에는 다른 보기예요. 알맞은 것끼리 이으세요.","pairs":[{"l":"직육면체의 면","r":"6개"},{"l":"직육면체의 모서리","r":"12개"},{"l":"직육면체의 꼭짓점","r":"8개"}],"explanation":["각기둥의 두 밑면은 서로 평행하고 합동인 다각형이에요.","옆면은 두 밑면과 만나는 면이고 모두 직사각형이에요.","직육면체는 면 6개·모서리 12개·꼭짓점 8개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L02_challenge#3','math',6,1,'u2','L02','g6_1_math_u2_L02_challenge','lesson_challenge','M6-1-u2-C1',3,'mc','auto','「서로 평행하고 합동인 두 오각형이 있지만 옆면이 평행사변형이고 밑면과 비스듬히 만나는 입체도형」은 각기둥이 아니에요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u2-X02']::text[],true,'{"seq":3,"concept":"M6-1-u2-C1","difficulty":3,"kind":"mc","stem":"「서로 평행하고 합동인 두 오각형이 있지만 옆면이 평행사변형이고 밑면과 비스듬히 만나는 입체도형」은 각기둥이 아니에요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"옆면이 직사각형이 아니고 밑면과 수직으로 만나지 않기 때문에","correct":true},{"t":"평행한 두 면이 서로 합동이 아니기 때문에","mis":"M6-1-u2-X02"},{"t":"밑면이 다각형이 아니고 굽은 면이 있기 때문에","mis":"M6-1-u2-X02"},{"t":"서로 평행하고 합동인 두 면이 없기 때문에","mis":"M6-1-u2-X02"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형이고, 옆면은 모두 직사각형이에요.","「서로 평행하고 합동인 두 오각형이 있지만 옆면이 평행사변형이고 밑면과 비스듬히 만나는 입체도형」을 이 조건에 하나씩 대어 봐요.","옆면이 직사각형이 아니고 밑면과 수직으로 만나지 않기 때문에 각기둥이 아니에요."],"variant_rule":{"alt":[{"stem":"「서로 평행한 두 오각형의 크기가 다른 입체도형」은 각기둥이 아니에요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"평행한 두 면이 서로 합동이 아니기 때문에","correct":true},{"t":"옆면이 직사각형이 아니고 밑면과 수직으로 만나지 않기 때문에","mis":"M6-1-u2-X02"},{"t":"밑면이 다각형이 아니고 굽은 면이 있기 때문에","mis":"M6-1-u2-X02"},{"t":"서로 평행하고 합동인 두 면이 없기 때문에","mis":"M6-1-u2-X02"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형이고, 옆면은 모두 직사각형이에요.","「서로 평행한 두 오각형의 크기가 다른 입체도형」을 이 조건에 하나씩 대어 봐요.","평행한 두 면이 서로 합동이 아니기 때문에 각기둥이 아니에요."]},{"stem":"「한 면이 육각형이고 나머지 면이 모두 삼각형인 입체도형」은 각기둥이 아니에요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"서로 평행하고 합동인 두 면이 없기 때문에","correct":true},{"t":"평행한 두 면이 서로 합동이 아니기 때문에","mis":"M6-1-u2-X11"},{"t":"옆면이 직사각형이 아니고 밑면과 수직으로 만나지 않기 때문에","mis":"M6-1-u2-X11"},{"t":"밑면이 다각형이 아니고 굽은 면이 있기 때문에","mis":"M6-1-u2-X11"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형이고, 옆면은 모두 직사각형이에요.","「한 면이 육각형이고 나머지 면이 모두 삼각형인 입체도형」을 이 조건에 하나씩 대어 봐요.","서로 평행하고 합동인 두 면이 없기 때문에 각기둥이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L02_challenge#4','math',6,1,'u2','L02','g6_1_math_u2_L02_challenge','lesson_challenge','M6-1-u2-C1',3,'error','auto','각기둥에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u2-X01','M6-1-u2-X14']::text[],true,'{"seq":4,"concept":"M6-1-u2-C1","difficulty":3,"kind":"error","stem":"각기둥에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「각기둥을 옆으로 눕히면 바닥에 닿은 옆면이 밑면이 돼.」","correct":true,"mis_target":"M6-1-u2-X01"},{"t":"이현 — 「각기둥의 옆면은 모두 직사각형이야.」","mis":"M6-1-u2-X14"},{"t":"서아 — 「두 밑면은 서로 평행하고 합동이야.」","mis":"M6-1-u2-X14"}],"explanation":["각기둥을 눕혀도 서로 평행하고 합동인 두 면이 밑면이에요.","바닥에 닿은 면이 직사각형 옆면이면 그것은 여전히 옆면이에요.","준희는 밑면을 위치로 잘못 정했어요."],"variant_rule":{"alt":[{"stem":"오각기둥에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「옆면은 오각형이야.」","correct":true,"mis_target":"M6-1-u2-X03"},{"t":"수아 — 「밑면은 오각형 2개야.」","mis":"M6-1-u2-X14"},{"t":"도윤 — 「옆면은 5개야.」","mis":"M6-1-u2-X14"}],"explanation":["오각기둥의 밑면은 오각형 2개예요.","옆면은 밑면의 변 하나마다 하나씩, 모두 직사각형이에요.","서호는 옆면의 모양을 잘못 말했어요."]},{"stem":"육각기둥에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「옆면은 육각형이야.」","correct":true,"mis_target":"M6-1-u2-X03"},{"t":"나린 — 「밑면은 육각형 2개야.」","mis":"M6-1-u2-X14"},{"t":"유진 — 「옆면은 6개야.」","mis":"M6-1-u2-X14"}],"explanation":["육각기둥의 밑면은 육각형 2개예요.","옆면은 밑면의 변 하나마다 하나씩, 모두 직사각형이에요.","가온은 옆면의 모양을 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L02_challenge#5','math',6,1,'u2','L02','g6_1_math_u2_L02_challenge','lesson_challenge','M6-1-u2-C1',3,'ox','auto','서로 평행한 두 면이 있으면 모두 각기둥이에요.',ARRAY['M6-1-u2-X02']::text[],true,'{"seq":5,"concept":"M6-1-u2-C1","difficulty":3,"kind":"ox","stem":"서로 평행한 두 면이 있으면 모두 각기둥이에요.","answer":"X","reason_options":[{"t":"두 면이 서로 합동인 다각형이고 옆면이 직사각형이어야 하기 때문에","correct":true},{"t":"평행한 면이 둘이면 각기둥이라고 정했기 때문에","mis":"M6-1-u2-X02"}],"mis":"M6-1-u2-X02","explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형이에요.","그 두 면이 밑면, 두 밑면과 만나는 직사각형이 옆면이에요.","밑면은 놓인 위치가 아니라 관계로 정해져요."],"variant_rule":{"alt":[{"stem":"직육면체도 각기둥이에요.","answer":"O","reason_options":[{"t":"서로 평행하고 합동인 두 직사각형이 밑면이고 옆면이 직사각형이기 때문에","correct":true},{"t":"직육면체는 면이 6개라서 각기둥이 아니기 때문에","mis":"M6-1-u2-X11"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형이에요.","그 두 면이 밑면, 두 밑면과 만나는 직사각형이 옆면이에요.","밑면은 놓인 위치가 아니라 관계로 정해져요."]},{"stem":"원기둥도 두 밑면이 평행하고 합동이니 각기둥이에요.","answer":"X","reason_options":[{"t":"각기둥은 밑면이 다각형이어야 하는데 원은 다각형이 아니기 때문에","correct":true},{"t":"기둥 모양은 모두 각기둥이기 때문에","mis":"M6-1-u2-X11"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형이에요.","그 두 면이 밑면, 두 밑면과 만나는 직사각형이 옆면이에요.","밑면은 놓인 위치가 아니라 관계로 정해져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L02_challenge#6','math',6,1,'u2','L02','g6_1_math_u2_L02_challenge','lesson_challenge','M6-1-u2-C1',3,'sa','auto','가 서로 평행하고 합동인 두 오각형과 직사각형 5개로 둘러싸인 저금통 · 나 서로 평행한 두 사각형의 크기가 서로 다른 저금통 · 다 서로 평행하고 합동인 두 삼각형과 직사각형 3개로 둘러싸인 상자 · 라 위아래 면이 서로 평행하고 합동인 원인 저금통 · 마 서로 평행하고 합동인 두 육각형과 직사각형 6개로 둘러싸인 연필 — 이 가운데 각기둥 모양은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u2-C1","difficulty":3,"kind":"sa","stem":"가 서로 평행하고 합동인 두 오각형과 직사각형 5개로 둘러싸인 저금통 · 나 서로 평행한 두 사각형의 크기가 서로 다른 저금통 · 다 서로 평행하고 합동인 두 삼각형과 직사각형 3개로 둘러싸인 상자 · 라 위아래 면이 서로 평행하고 합동인 원인 저금통 · 마 서로 평행하고 합동인 두 육각형과 직사각형 6개로 둘러싸인 연필 — 이 가운데 각기둥 모양은 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["각기둥의 뜻에 하나씩 대어 봐요.","각기둥인 것은 가, 다, 마예요.","모두 3개예요."],"mis":"M6-1-u2-X02","variant_rule":{"alt":[{"stem":"가 서로 평행하고 합동인 두 삼각형과 직사각형 3개로 둘러싸인 상자 · 나 한 면이 사각형이고 나머지 면이 모두 삼각형인 저금통 · 다 서로 평행하고 합동인 두 육각형과 직사각형 6개로 둘러싸인 연필 · 라 굽은 면 하나로만 둘러싸인 공 모양 저금통 · 마 서로 평행한 두 사각형의 크기가 서로 다른 저금통 — 이 가운데 각기둥 모양은 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["각기둥의 뜻에 하나씩 대어 봐요.","각기둥인 것은 가, 다예요.","모두 2개예요."]},{"stem":"가 서로 평행하고 합동인 두 오각형과 직사각형 5개로 둘러싸인 저금통 · 나 한 원과 뾰족한 점이 있는 고깔 · 다 위아래 면이 서로 평행하고 합동인 원인 저금통 · 라 한 면이 오각형이고 나머지 면이 모두 삼각형인 탑 지붕 · 마 서로 평행하고 합동인 두 삼각형과 직사각형 3개로 둘러싸인 상자 — 이 가운데 각기둥 모양은 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["각기둥의 뜻에 하나씩 대어 봐요.","각기둥인 것은 가, 마예요.","모두 2개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L02_challenge#7','math',6,1,'u2','L02','g6_1_math_u2_L02_challenge','lesson_challenge','M6-1-u2-C1',3,'mc','auto','사각기둥 모양 저금통을 옆으로 눕혀 놓았어요. 이때 바닥이 아니라 양옆에 서 있는 두 사각형은 무엇인가요?',ARRAY['M6-1-u2-X01','M6-1-u2-X05']::text[],true,'{"seq":7,"concept":"M6-1-u2-C1","difficulty":3,"kind":"mc","stem":"사각기둥 모양 저금통을 옆으로 눕혀 놓았어요. 이때 바닥이 아니라 양옆에 서 있는 두 사각형은 무엇인가요?","options":[{"t":"밑면","correct":true},{"t":"옆면","mis":"M6-1-u2-X01"},{"t":"모서리","mis":"M6-1-u2-X05"},{"t":"높이","mis":"M6-1-u2-X05"}],"explanation":["밑면은 아래에 놓인 면이 아니에요.","서로 평행하고 합동인 두 사각형이 밑면이에요.","눕혀도 그 관계는 그대로라 두 사각형은 여전히 밑면이에요."],"variant_rule":{"alt":[{"stem":"칠각기둥 모양 저금통을 옆으로 눕혀 놓았어요. 이때 바닥이 아니라 양옆에 서 있는 두 칠각형은 무엇인가요?","options":[{"t":"밑면","correct":true},{"t":"옆면","mis":"M6-1-u2-X01"},{"t":"모서리","mis":"M6-1-u2-X05"},{"t":"높이","mis":"M6-1-u2-X05"}],"explanation":["밑면은 아래에 놓인 면이 아니에요.","서로 평행하고 합동인 두 칠각형이 밑면이에요.","눕혀도 그 관계는 그대로라 두 칠각형은 여전히 밑면이에요."]},{"stem":"팔각기둥 모양 저금통을 옆으로 눕혀 놓았어요. 이때 바닥이 아니라 양옆에 서 있는 두 팔각형은 무엇인가요?","options":[{"t":"밑면","correct":true},{"t":"옆면","mis":"M6-1-u2-X01"},{"t":"모서리","mis":"M6-1-u2-X05"},{"t":"높이","mis":"M6-1-u2-X05"}],"explanation":["밑면은 아래에 놓인 면이 아니에요.","서로 평행하고 합동인 두 팔각형이 밑면이에요.","눕혀도 그 관계는 그대로라 두 팔각형은 여전히 밑면이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L02_challenge#8','math',6,1,'u2','L02','g6_1_math_u2_L02_challenge','lesson_challenge','M6-1-u2-C1',4,'sa','auto','밑면이 사각형인 각기둥과 밑면이 육각형인 각기둥이 있어요. 두 각기둥의 면의 수를 더하면 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u2-C1","difficulty":4,"kind":"sa","stem":"밑면이 사각형인 각기둥과 밑면이 육각형인 각기둥이 있어요. 두 각기둥의 면의 수를 더하면 모두 몇 개인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["밑면 2개와 옆면 4개 — 4 + 2 = 6개예요.","밑면 2개와 옆면 6개 — 6 + 2 = 8개예요.","두 수를 더하면 6 + 8 = 14개예요."],"mis":"M6-1-u2-X14","variant_rule":{"alt":[{"stem":"밑면이 오각형인 각기둥과 밑면이 팔각형인 각기둥이 있어요. 두 각기둥의 면의 수를 더하면 모두 몇 개인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["밑면 2개와 옆면 5개 — 5 + 2 = 7개예요.","밑면 2개와 옆면 8개 — 8 + 2 = 10개예요.","두 수를 더하면 7 + 10 = 17개예요."]},{"stem":"밑면이 삼각형인 각기둥과 밑면이 칠각형인 각기둥이 있어요. 두 각기둥의 면의 수를 더하면 모두 몇 개인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["밑면 2개와 옆면 3개 — 3 + 2 = 5개예요.","밑면 2개와 옆면 7개 — 7 + 2 = 9개예요.","두 수를 더하면 5 + 9 = 14개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L02_challenge#9','math',6,1,'u2','L02','g6_1_math_u2_L02_challenge','lesson_challenge','M6-1-u2-C1',4,'sa','auto','밑면이 육각형인 각기둥과 밑면이 구각형인 각기둥이 있어요. 두 각기둥의 면의 수를 더하면 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u2-C1","difficulty":4,"kind":"sa","stem":"밑면이 육각형인 각기둥과 밑면이 구각형인 각기둥이 있어요. 두 각기둥의 면의 수를 더하면 모두 몇 개인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["밑면 2개와 옆면 6개 — 6 + 2 = 8개예요.","밑면 2개와 옆면 9개 — 9 + 2 = 11개예요.","두 수를 더하면 8 + 11 = 19개예요."],"mis":"M6-1-u2-X14","variant_rule":{"alt":[{"stem":"밑면이 칠각형인 각기둥과 밑면이 십각형인 각기둥이 있어요. 두 각기둥의 면의 수를 더하면 모두 몇 개인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["밑면 2개와 옆면 7개 — 7 + 2 = 9개예요.","밑면 2개와 옆면 10개 — 10 + 2 = 12개예요.","두 수를 더하면 9 + 12 = 21개예요."]},{"stem":"밑면이 오각형인 각기둥과 밑면이 십이각형인 각기둥이 있어요. 두 각기둥의 면의 수를 더하면 모두 몇 개인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["밑면 2개와 옆면 5개 — 5 + 2 = 7개예요.","밑면 2개와 옆면 12개 — 12 + 2 = 14개예요.","두 수를 더하면 7 + 14 = 21개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L02_challenge#10','math',6,1,'u2','L02','g6_1_math_u2_L02_challenge','lesson_challenge','M6-1-u2-C1',4,'essay','teacher','기부 저금통 가운데 하나는 서로 평행하고 합동인 두 오각형이 있는데 옆면이 평행사변형이고 밑면과 비스듬히 만나요. 이 저금통이 각기둥인지 아닌지 쓰고, 그 까닭을 각기둥의 뜻으로 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u2-C1","difficulty":4,"kind":"essay","stem":"기부 저금통 가운데 하나는 서로 평행하고 합동인 두 오각형이 있는데 옆면이 평행사변형이고 밑면과 비스듬히 만나요. 이 저금통이 각기둥인지 아닌지 쓰고, 그 까닭을 각기둥의 뜻으로 설명해 보세요.","answer_guide":{"answer":"예: 각기둥이 아니다. 각기둥은 두 면이 서로 평행하고 합동인 다각형으로 이루어지고, 두 밑면과 만나는 옆면이 모두 직사각형이며 밑면과 수직으로 만나야 한다. 이 저금통은 두 오각형이 평행하고 합동이지만 옆면이 직사각형이 아니고 밑면과 비스듬히 만나므로 각기둥이 아니다.","scoring_points":["각기둥이 아니라고 답했는가","옆면이 직사각형이고 밑면과 수직이어야 한다는 조건을 썼는가","이 저금통은 옆면이 평행사변형이라 조건에 맞지 않는다고 설명했는가"]},"explanation":["각기둥의 옆면은 모두 직사각형이고 밑면과 수직으로 만나요.","이 저금통의 옆면은 평행사변형이고 비스듬해요.","그래서 각기둥이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L03_basic#1','math',6,1,'u2','L03','g6_1_math_u2_L03_basic','lesson_basic','M6-1-u2-C2',1,'mc','auto','밑면이 육각형인 각기둥의 이름은 무엇인가요?',ARRAY['M6-1-u2-X11','M6-1-u2-X04']::text[],true,'{"seq":1,"concept":"M6-1-u2-C2","difficulty":1,"kind":"mc","stem":"밑면이 육각형인 각기둥의 이름은 무엇인가요?","options":[{"t":"육각기둥","correct":true},{"t":"육각뿔","mis":"M6-1-u2-X11"},{"t":"팔각기둥","mis":"M6-1-u2-X04"},{"t":"십이각기둥","mis":"M6-1-u2-X04"}],"explanation":["각기둥의 이름은 밑면의 모양이 정해요.","밑면이 육각형이에요.","그래서 이름은 육각기둥이에요."],"variant_rule":{"alt":[{"stem":"밑면이 오각형인 각기둥의 이름은 무엇인가요?","options":[{"t":"오각기둥","correct":true},{"t":"오각뿔","mis":"M6-1-u2-X11"},{"t":"칠각기둥","mis":"M6-1-u2-X04"},{"t":"십각기둥","mis":"M6-1-u2-X04"}],"explanation":["각기둥의 이름은 밑면의 모양이 정해요.","밑면이 오각형이에요.","그래서 이름은 오각기둥이에요."]},{"stem":"밑면이 팔각형인 각기둥의 이름은 무엇인가요?","options":[{"t":"팔각기둥","correct":true},{"t":"팔각뿔","mis":"M6-1-u2-X11"},{"t":"십각기둥","mis":"M6-1-u2-X04"},{"t":"십육각기둥","mis":"M6-1-u2-X04"}],"explanation":["각기둥의 이름은 밑면의 모양이 정해요.","밑면이 팔각형이에요.","그래서 이름은 팔각기둥이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L03_basic#2','math',6,1,'u2','L03','g6_1_math_u2_L03_basic','lesson_basic','M6-1-u2-C2',1,'sa','auto','삼각기둥의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u2-C2","difficulty":1,"kind":"sa","stem":"삼각기둥의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["삼각기둥의 밑면은 삼각형이에요.","모서리를 세는 방법을 떠올려요.","위 밑면 3개, 아래 밑면 3개, 옆 모서리 3개 — 3 × 3 = 9개예요."],"mis":"M6-1-u2-X05","variant_rule":{"alt":[{"stem":"사각기둥의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["사각기둥의 밑면은 사각형이에요.","꼭짓점을 세는 방법을 떠올려요.","한 밑면의 꼭짓점 4개가 위아래로 짝을 이뤄 — 4 × 2 = 8개예요."]},{"stem":"삼각기둥의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["삼각기둥의 밑면은 삼각형이에요.","꼭짓점을 세는 방법을 떠올려요.","한 밑면의 꼭짓점 3개가 위아래로 짝을 이뤄 — 3 × 2 = 6개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L03_basic#3','math',6,1,'u2','L03','g6_1_math_u2_L03_basic','lesson_basic','M6-1-u2-C2',1,'mc','auto','각기둥에서 모서리는 무엇인가요?',ARRAY['M6-1-u2-X05','M6-1-u2-X06']::text[],true,'{"seq":3,"concept":"M6-1-u2-C2","difficulty":1,"kind":"mc","stem":"각기둥에서 모서리는 무엇인가요?","options":[{"t":"면과 면이 만나는 선분","correct":true},{"t":"모서리와 모서리가 만나는 점","mis":"M6-1-u2-X05"},{"t":"두 밑면 사이의 거리","mis":"M6-1-u2-X06"},{"t":"두 밑면과 만나는 면","mis":"M6-1-u2-X05"}],"explanation":["면과 면이 만나는 선분이 모서리, 모서리와 모서리가 만나는 점이 꼭짓점이에요.","두 밑면 사이의 거리가 높이예요.","그래서 모서리는 면과 면이 만나는 선분예요."],"variant_rule":{"alt":[{"stem":"각기둥에서 꼭짓점은 무엇인가요?","options":[{"t":"모서리와 모서리가 만나는 점","correct":true},{"t":"면과 면이 만나는 선분","mis":"M6-1-u2-X05"},{"t":"두 밑면 사이의 거리","mis":"M6-1-u2-X06"},{"t":"두 밑면과 만나는 면","mis":"M6-1-u2-X05"}],"explanation":["면과 면이 만나는 선분이 모서리, 모서리와 모서리가 만나는 점이 꼭짓점이에요.","두 밑면 사이의 거리가 높이예요.","그래서 꼭짓점은 모서리와 모서리가 만나는 점예요."]},{"stem":"각기둥에서 높이는 무엇인가요?","options":[{"t":"두 밑면 사이의 거리","correct":true},{"t":"면과 면이 만나는 선분","mis":"M6-1-u2-X06"},{"t":"모서리와 모서리가 만나는 점","mis":"M6-1-u2-X06"},{"t":"두 밑면과 만나는 면","mis":"M6-1-u2-X06"}],"explanation":["면과 면이 만나는 선분이 모서리, 모서리와 모서리가 만나는 점이 꼭짓점이에요.","두 밑면 사이의 거리가 높이예요.","그래서 높이는 두 밑면 사이의 거리예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L03_basic#4','math',6,1,'u2','L03','g6_1_math_u2_L03_basic','lesson_basic','M6-1-u2-C2',1,'sa','auto','오각기둥의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u2-C2","difficulty":1,"kind":"sa","stem":"오각기둥의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["오각기둥의 밑면은 오각형이에요.","꼭짓점을 세는 방법을 떠올려요.","한 밑면의 꼭짓점 5개가 위아래로 짝을 이뤄 — 5 × 2 = 10개예요."],"mis":"M6-1-u2-X05","variant_rule":{"alt":[{"stem":"육각기둥의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["육각기둥의 밑면은 육각형이에요.","꼭짓점을 세는 방법을 떠올려요.","한 밑면의 꼭짓점 6개가 위아래로 짝을 이뤄 — 6 × 2 = 12개예요."]},{"stem":"사각기둥의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["사각기둥의 밑면은 사각형이에요.","모서리를 세는 방법을 떠올려요.","위 밑면 4개, 아래 밑면 4개, 옆 모서리 4개 — 4 × 3 = 12개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L03_basic#5','math',6,1,'u2','L03','g6_1_math_u2_L03_basic','lesson_basic','M6-1-u2-C2',2,'mc','auto','막대 과자 상자 세 개의 옆면은 모두 직사각형으로 같아요. 세 상자의 이름을 서로 다르게 정하는 것은 무엇인가요?',ARRAY['M6-1-u2-X04','M6-1-u2-X06']::text[],true,'{"seq":5,"concept":"M6-1-u2-C2","difficulty":2,"kind":"mc","stem":"막대 과자 상자 세 개의 옆면은 모두 직사각형으로 같아요. 세 상자의 이름을 서로 다르게 정하는 것은 무엇인가요?","options":[{"t":"밑면의 모양","correct":true},{"t":"옆면의 모양","mis":"M6-1-u2-X04"},{"t":"상자의 높이","mis":"M6-1-u2-X06"},{"t":"꼭짓점의 수","mis":"M6-1-u2-X04"}],"explanation":["각기둥의 옆면은 모두 직사각형이라 모양이 같아요.","다른 것은 밑면의 모양뿐이라 이름도 밑면이 정해요.","그래서 답은 「밑면의 모양」이에요."],"variant_rule":{"alt":[{"stem":"직육면체 모양 과자 상자를 각기둥의 이름으로 부르면 무엇인가요?","options":[{"t":"사각기둥","correct":true},{"t":"육각기둥","mis":"M6-1-u2-X04"},{"t":"직사각기둥","mis":"M6-1-u2-X04"},{"t":"사각뿔","mis":"M6-1-u2-X11"}],"explanation":["각기둥의 옆면은 모두 직사각형이라 모양이 같아요.","다른 것은 밑면의 모양뿐이라 이름도 밑면이 정해요.","그래서 답은 「사각기둥」이에요."]},{"stem":"밑면이 삼각형인 막대 과자 상자의 이름은 무엇인가요?","options":[{"t":"삼각기둥","correct":true},{"t":"삼각뿔","mis":"M6-1-u2-X11"},{"t":"육각기둥","mis":"M6-1-u2-X04"},{"t":"사각기둥","mis":"M6-1-u2-X04"}],"explanation":["각기둥의 옆면은 모두 직사각형이라 모양이 같아요.","다른 것은 밑면의 모양뿐이라 이름도 밑면이 정해요.","그래서 답은 「삼각기둥」이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L03_basic#6','math',6,1,'u2','L03','g6_1_math_u2_L03_basic','lesson_basic','M6-1-u2-C2',2,'sa','auto','오각기둥의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u2-C2","difficulty":2,"kind":"sa","stem":"오각기둥의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["오각기둥의 밑면은 오각형이에요.","모서리를 세는 방법을 떠올려요.","위 밑면 5개, 아래 밑면 5개, 옆 모서리 5개 — 5 × 3 = 15개예요."],"mis":"M6-1-u2-X05","variant_rule":{"alt":[{"stem":"육각기둥의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["육각기둥의 밑면은 육각형이에요.","모서리를 세는 방법을 떠올려요.","위 밑면 6개, 아래 밑면 6개, 옆 모서리 6개 — 6 × 3 = 18개예요."]},{"stem":"칠각기둥의 면은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["칠각기둥의 밑면은 칠각형이에요.","면을 세는 방법을 떠올려요.","밑면 2개와 옆면 7개 — 7 + 2 = 9개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L03_basic#7','math',6,1,'u2','L03','g6_1_math_u2_L03_basic','lesson_basic','M6-1-u2-C2',2,'mc','auto','각기둥의 높이를 재는 곳으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u2-X06','M6-1-u2-X01']::text[],true,'{"seq":7,"concept":"M6-1-u2-C2","difficulty":2,"kind":"mc","stem":"각기둥의 높이를 재는 곳으로 알맞은 것은 어느 것인가요?","options":[{"t":"옆면과 옆면이 만나는 모서리","correct":true},{"t":"밑면의 가장 긴 변","mis":"M6-1-u2-X06"},{"t":"밑면의 둘레","mis":"M6-1-u2-X06"},{"t":"바닥에서 천장까지","mis":"M6-1-u2-X01"}],"explanation":["높이는 두 밑면 사이의 거리예요.","두 밑면이 평행해서 그 거리는 어디에서 재도 같아요.","그래서 옆면과 옆면이 만나는 모서리의 길이가 곧 높이예요."],"variant_rule":{"alt":[{"stem":"각기둥의 높이에 대한 설명으로 옳은 것은 어느 것인가요?","options":[{"t":"두 밑면 사이의 거리이고 어디에서 재도 같아요","correct":true},{"t":"밑면의 가장 긴 변의 길이예요","mis":"M6-1-u2-X06"},{"t":"재는 곳마다 달라요","mis":"M6-1-u2-X06"},{"t":"바닥에 닿은 면의 둘레예요","mis":"M6-1-u2-X01"}],"explanation":["높이는 두 밑면 사이의 거리예요.","두 밑면이 평행해서 그 거리는 어디에서 재도 같아요.","그래서 옆면과 옆면이 만나는 모서리의 길이가 곧 높이예요."]},{"stem":"눕혀 놓은 오각기둥의 높이는 어디의 길이인가요?","options":[{"t":"두 오각형 밑면 사이의 거리","correct":true},{"t":"바닥에서 가장 높은 곳까지의 길이","mis":"M6-1-u2-X01"},{"t":"밑면의 한 변의 길이","mis":"M6-1-u2-X06"},{"t":"밑면의 둘레","mis":"M6-1-u2-X06"}],"explanation":["높이는 두 밑면 사이의 거리예요.","두 밑면이 평행해서 그 거리는 어디에서 재도 같아요.","그래서 옆면과 옆면이 만나는 모서리의 길이가 곧 높이예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L03_basic#8','math',6,1,'u2','L03','g6_1_math_u2_L03_basic','lesson_basic','M6-1-u2-C2',2,'sa','auto','문 고정 받침대는 삼각기둥 모양이에요. 밑면의 세 변이 3 cm, 4 cm, 5 cm이고 옆면과 옆면이 만나는 모서리가 7 cm일 때, 이 삼각기둥의 높이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u2-C2","difficulty":2,"kind":"sa","stem":"문 고정 받침대는 삼각기둥 모양이에요. 밑면의 세 변이 3 cm, 4 cm, 5 cm이고 옆면과 옆면이 만나는 모서리가 7 cm일 때, 이 삼각기둥의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["각기둥의 높이는 두 밑면 사이의 거리예요.","옆면과 옆면이 만나는 모서리는 두 밑면과 수직이라 그 길이가 곧 높이예요.","밑면의 변 3 cm, 4 cm, 5 cm는 높이가 아니에요 — 높이는 7 cm예요."],"mis":"M6-1-u2-X06","variant_rule":{"alt":[{"stem":"문 고정 받침대는 삼각기둥 모양이에요. 밑면의 세 변이 5 cm, 12 cm, 13 cm이고 옆면과 옆면이 만나는 모서리가 9 cm일 때, 이 삼각기둥의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["각기둥의 높이는 두 밑면 사이의 거리예요.","옆면과 옆면이 만나는 모서리는 두 밑면과 수직이라 그 길이가 곧 높이예요.","밑면의 변 5 cm, 12 cm, 13 cm는 높이가 아니에요 — 높이는 9 cm예요."]},{"stem":"문 고정 받침대는 삼각기둥 모양이에요. 밑면의 세 변이 6 cm, 8 cm, 10 cm이고 옆면과 옆면이 만나는 모서리가 4 cm일 때, 이 삼각기둥의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["각기둥의 높이는 두 밑면 사이의 거리예요.","옆면과 옆면이 만나는 모서리는 두 밑면과 수직이라 그 길이가 곧 높이예요.","밑면의 변 6 cm, 8 cm, 10 cm는 높이가 아니에요 — 높이는 4 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L03_basic#9','math',6,1,'u2','L03','g6_1_math_u2_L03_basic','lesson_basic','M6-1-u2-C2',2,'ox','auto','직육면체와 정육면체는 사각기둥이에요.',ARRAY['M6-1-u2-X04']::text[],true,'{"seq":9,"concept":"M6-1-u2-C2","difficulty":2,"kind":"ox","stem":"직육면체와 정육면체는 사각기둥이에요.","answer":"O","reason_options":[{"t":"밑면이 사각형인 각기둥이기 때문에","correct":true},{"t":"면이 6개라 육각기둥이기 때문에","mis":"M6-1-u2-X04"}],"mis":"M6-1-u2-X04","explanation":["각기둥의 이름은 밑면의 모양으로 정해요.","면과 면이 만나는 선분이 모서리, 모서리와 모서리가 만나는 점이 꼭짓점이에요.","높이는 두 밑면 사이의 거리예요."],"variant_rule":{"alt":[{"stem":"각기둥의 이름은 옆면의 모양으로 정해요.","answer":"X","reason_options":[{"t":"옆면은 모두 직사각형이고 이름은 밑면의 모양으로 정하기 때문에","correct":true},{"t":"옆면의 수가 이름이 되기 때문에","mis":"M6-1-u2-X04"}],"explanation":["각기둥의 이름은 밑면의 모양으로 정해요.","면과 면이 만나는 선분이 모서리, 모서리와 모서리가 만나는 점이 꼭짓점이에요.","높이는 두 밑면 사이의 거리예요."]},{"stem":"면과 면이 만나는 선분을 꼭짓점이라고 해요.","answer":"X","reason_options":[{"t":"그 선분은 모서리이고 모서리와 모서리가 만나는 점이 꼭짓점이기 때문에","correct":true},{"t":"선분의 끝이 꼭짓점이기 때문에","mis":"M6-1-u2-X05"}],"explanation":["각기둥의 이름은 밑면의 모양으로 정해요.","면과 면이 만나는 선분이 모서리, 모서리와 모서리가 만나는 점이 꼭짓점이에요.","높이는 두 밑면 사이의 거리예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L03_basic#10','math',6,1,'u2','L03','g6_1_math_u2_L03_basic','lesson_basic','M6-1-u2-C2',3,'mc','auto','두 밑면이 서로 평행하고 합동인 다각형이고 꼭짓점이 10개인 각기둥의 이름은 무엇인가요?',ARRAY['M6-1-u2-X04','M6-1-u2-X11','M6-1-u2-X12']::text[],true,'{"seq":10,"concept":"M6-1-u2-C2","difficulty":3,"kind":"mc","stem":"두 밑면이 서로 평행하고 합동인 다각형이고 꼭짓점이 10개인 각기둥의 이름은 무엇인가요?","options":[{"t":"오각기둥","correct":true},{"t":"십각기둥","mis":"M6-1-u2-X04"},{"t":"오각뿔","mis":"M6-1-u2-X11"},{"t":"육각기둥","mis":"M6-1-u2-X12"}],"explanation":["각기둥의 꼭짓점은 변의 수 × 2예요.","꼭짓점이 10개이니 한 밑면의 변은 5개예요.","밑면이 오각형이라 이름은 오각기둥이에요."],"variant_rule":{"alt":[{"stem":"두 밑면이 서로 평행하고 합동인 다각형이고 모서리가 18개인 각기둥의 이름은 무엇인가요?","options":[{"t":"육각기둥","correct":true},{"t":"십팔각기둥","mis":"M6-1-u2-X04"},{"t":"육각뿔","mis":"M6-1-u2-X11"},{"t":"칠각기둥","mis":"M6-1-u2-X12"}],"explanation":["각기둥의 모서리는 변의 수 × 3이에요.","모서리가 18개이니 한 밑면의 변은 6개예요.","밑면이 육각형이라 이름은 육각기둥이에요."]},{"stem":"두 밑면이 서로 평행하고 합동인 다각형이고 꼭짓점이 8개인 각기둥의 이름은 무엇인가요?","options":[{"t":"사각기둥","correct":true},{"t":"팔각기둥","mis":"M6-1-u2-X04"},{"t":"사각뿔","mis":"M6-1-u2-X11"},{"t":"오각기둥","mis":"M6-1-u2-X12"}],"explanation":["각기둥의 꼭짓점은 변의 수 × 2예요.","꼭짓점이 8개이니 한 밑면의 변은 4개예요.","밑면이 사각형이라 이름은 사각기둥이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L03_challenge#1','math',6,1,'u2','L03','g6_1_math_u2_L03_challenge','lesson_challenge','M6-1-u2-C2',2,'sa','auto','팔각기둥의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u2-C2","difficulty":2,"kind":"sa","stem":"팔각기둥의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["팔각기둥의 밑면은 팔각형이에요.","모서리를 세는 방법을 떠올려요.","위 밑면 8개, 아래 밑면 8개, 옆 모서리 8개 — 8 × 3 = 24개예요."],"mis":"M6-1-u2-X05","variant_rule":{"alt":[{"stem":"칠각기둥의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["칠각기둥의 밑면은 칠각형이에요.","꼭짓점을 세는 방법을 떠올려요.","한 밑면의 꼭짓점 7개가 위아래로 짝을 이뤄 — 7 × 2 = 14개예요."]},{"stem":"구각기둥의 면은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["구각기둥의 밑면은 구각형이에요.","면을 세는 방법을 떠올려요.","밑면 2개와 옆면 9개 — 9 + 2 = 11개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L03_challenge#2','math',6,1,'u2','L03','g6_1_math_u2_L03_challenge','lesson_challenge','M6-1-u2-C2',2,'match','auto','각기둥과 그 꼭짓점 수를 알맞게 이으세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u2-C2","difficulty":2,"kind":"match","stem":"각기둥과 그 꼭짓점 수를 알맞게 이으세요.","pairs":[{"l":"삼각기둥","r":"6개"},{"l":"오각기둥","r":"10개"},{"l":"육각기둥","r":"12개"}],"mis":"M6-1-u2-X05","explanation":["꼭짓점의 수는 변의 수 × 2예요.","삼각기둥 6개, 오각기둥 10개, 육각기둥 12개예요.","밑면의 변의 수부터 보면 바로 구할 수 있어요."],"variant_rule":{"alt":[{"stem":"각기둥과 그 모서리 수를 알맞게 이으세요.","pairs":[{"l":"사각기둥","r":"12개"},{"l":"육각기둥","r":"18개"},{"l":"팔각기둥","r":"24개"}],"explanation":["모서리의 수는 변의 수 × 3이에요.","사각기둥 12개, 육각기둥 18개, 팔각기둥 24개예요.","밑면의 변의 수부터 보면 바로 구할 수 있어요."]},{"stem":"각기둥과 그 면 수를 알맞게 이으세요.","pairs":[{"l":"삼각기둥","r":"5개"},{"l":"사각기둥","r":"6개"},{"l":"칠각기둥","r":"9개"}],"explanation":["면의 수는 변의 수 + 2예요.","삼각기둥 5개, 사각기둥 6개, 칠각기둥 9개예요.","밑면의 변의 수부터 보면 바로 구할 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L03_challenge#3','math',6,1,'u2','L03','g6_1_math_u2_L03_challenge','lesson_challenge','M6-1-u2-C2',3,'error','auto','각기둥의 설명을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u2-X06','M6-1-u2-X14']::text[],true,'{"seq":3,"concept":"M6-1-u2-C2","difficulty":3,"kind":"error","stem":"각기둥의 설명을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「각기둥의 높이는 밑면의 가장 긴 변의 길이야.」","correct":true,"mis_target":"M6-1-u2-X06"},{"t":"이현 — 「각기둥의 밑면은 2개야.」","mis":"M6-1-u2-X14"},{"t":"서아 — 「각기둥의 밑면은 옆면과 수직으로 만나.」","mis":"M6-1-u2-X14"}],"explanation":["각기둥의 높이는 두 밑면 사이의 거리예요.","밑면의 변은 밑면 안의 선분이라 높이가 될 수 없어요.","준희는 높이를 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"육각기둥을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「꼭짓점이 6개야.」","correct":true,"mis_target":"M6-1-u2-X05"},{"t":"수아 — 「모서리가 18개야.」","mis":"M6-1-u2-X14"},{"t":"도윤 — 「면이 8개야.」","mis":"M6-1-u2-X14"}],"explanation":["한 밑면의 꼭짓점 6개가 위아래로 짝을 이뤄 — 6 × 2 = 12개예요.","위 밑면 6개, 아래 밑면 6개, 옆 모서리 6개 — 6 × 3 = 18개예요.","서호는 한 밑면의 꼭짓점만 세었어요."]},{"stem":"오각기둥을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「꼭짓점이 5개야.」","correct":true,"mis_target":"M6-1-u2-X05"},{"t":"나린 — 「모서리가 15개야.」","mis":"M6-1-u2-X14"},{"t":"유진 — 「면이 7개야.」","mis":"M6-1-u2-X14"}],"explanation":["한 밑면의 꼭짓점 5개가 위아래로 짝을 이뤄 — 5 × 2 = 10개예요.","위 밑면 5개, 아래 밑면 5개, 옆 모서리 5개 — 5 × 3 = 15개예요.","가온은 한 밑면의 꼭짓점만 세었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L03_challenge#4','math',6,1,'u2','L03','g6_1_math_u2_L03_challenge','lesson_challenge','M6-1-u2-C2',3,'ox','auto','각기둥의 높이는 밑면의 가장 긴 변의 길이예요.',ARRAY['M6-1-u2-X06']::text[],true,'{"seq":4,"concept":"M6-1-u2-C2","difficulty":3,"kind":"ox","stem":"각기둥의 높이는 밑면의 가장 긴 변의 길이예요.","answer":"X","reason_options":[{"t":"높이는 두 밑면 사이의 거리이기 때문에","correct":true},{"t":"밑면의 변이 길수록 높아지기 때문에","mis":"M6-1-u2-X06"}],"mis":"M6-1-u2-X06","explanation":["각기둥의 이름은 밑면의 모양으로 정해요.","면과 면이 만나는 선분이 모서리, 모서리와 모서리가 만나는 점이 꼭짓점이에요.","높이는 두 밑면 사이의 거리예요."],"variant_rule":{"alt":[{"stem":"밑면의 변의 수가 늘면 각기둥의 모서리와 꼭짓점도 늘어요.","answer":"O","reason_options":[{"t":"모서리와 꼭짓점의 수가 모두 밑면의 변의 수에서 나오기 때문에","correct":true},{"t":"옆면의 모양이 바뀌기 때문에","mis":"M6-1-u2-X12"}],"explanation":["각기둥의 이름은 밑면의 모양으로 정해요.","면과 면이 만나는 선분이 모서리, 모서리와 모서리가 만나는 점이 꼭짓점이에요.","높이는 두 밑면 사이의 거리예요."]},{"stem":"꼭짓점이 10개인 각기둥은 십각기둥이에요.","answer":"X","reason_options":[{"t":"꼭짓점은 한 밑면의 꼭짓점의 2배라 밑면이 오각형인 오각기둥이기 때문에","correct":true},{"t":"이름은 꼭짓점의 수로 정하기 때문에","mis":"M6-1-u2-X04"}],"explanation":["각기둥의 이름은 밑면의 모양으로 정해요.","면과 면이 만나는 선분이 모서리, 모서리와 모서리가 만나는 점이 꼭짓점이에요.","높이는 두 밑면 사이의 거리예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L03_challenge#5','math',6,1,'u2','L03','g6_1_math_u2_L03_challenge','lesson_challenge','M6-1-u2-C2',3,'mc','auto','두 밑면이 서로 평행하고 합동인 다각형이고 꼭짓점이 14개인 각기둥의 이름은 무엇인가요?',ARRAY['M6-1-u2-X04','M6-1-u2-X11','M6-1-u2-X12']::text[],true,'{"seq":5,"concept":"M6-1-u2-C2","difficulty":3,"kind":"mc","stem":"두 밑면이 서로 평행하고 합동인 다각형이고 꼭짓점이 14개인 각기둥의 이름은 무엇인가요?","options":[{"t":"칠각기둥","correct":true},{"t":"십사각기둥","mis":"M6-1-u2-X04"},{"t":"칠각뿔","mis":"M6-1-u2-X11"},{"t":"팔각기둥","mis":"M6-1-u2-X12"}],"explanation":["각기둥의 꼭짓점은 변의 수 × 2예요.","꼭짓점이 14개이니 한 밑면의 변은 7개예요.","밑면이 칠각형이라 이름은 칠각기둥이에요."],"variant_rule":{"alt":[{"stem":"두 밑면이 서로 평행하고 합동인 다각형이고 모서리가 24개인 각기둥의 이름은 무엇인가요?","options":[{"t":"팔각기둥","correct":true},{"t":"이십사각기둥","mis":"M6-1-u2-X04"},{"t":"팔각뿔","mis":"M6-1-u2-X11"},{"t":"구각기둥","mis":"M6-1-u2-X12"}],"explanation":["각기둥의 모서리는 변의 수 × 3이에요.","모서리가 24개이니 한 밑면의 변은 8개예요.","밑면이 팔각형이라 이름은 팔각기둥이에요."]},{"stem":"두 밑면이 서로 평행하고 합동인 다각형이고 면이 7개인 각기둥의 이름은 무엇인가요?","options":[{"t":"오각기둥","correct":true},{"t":"칠각기둥","mis":"M6-1-u2-X04"},{"t":"오각뿔","mis":"M6-1-u2-X11"},{"t":"육각기둥","mis":"M6-1-u2-X12"}],"explanation":["각기둥의 면은 변의 수 + 2예요.","면이 7개이니 한 밑면의 변은 5개예요.","밑면이 오각형이라 이름은 오각기둥이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L03_challenge#6','math',6,1,'u2','L03','g6_1_math_u2_L03_challenge','lesson_challenge','M6-1-u2-C2',3,'sa','auto','오각기둥의 모서리 수와 꼭짓점 수를 더하면 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u2-C2","difficulty":3,"kind":"sa","stem":"오각기둥의 모서리 수와 꼭짓점 수를 더하면 모두 몇 개인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["위 밑면 5개, 아래 밑면 5개, 옆 모서리 5개 — 5 × 3 = 15개예요.","한 밑면의 꼭짓점 5개가 위아래로 짝을 이뤄 — 5 × 2 = 10개예요.","두 수를 더하면 15 + 10 = 25개예요."],"mis":"M6-1-u2-X14","variant_rule":{"alt":[{"stem":"육각기둥의 면 수와 꼭짓점 수를 더하면 모두 몇 개인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["밑면 2개와 옆면 6개 — 6 + 2 = 8개예요.","한 밑면의 꼭짓점 6개가 위아래로 짝을 이뤄 — 6 × 2 = 12개예요.","두 수를 더하면 8 + 12 = 20개예요."]},{"stem":"사각기둥의 모서리 수와 면 수를 더하면 모두 몇 개인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["위 밑면 4개, 아래 밑면 4개, 옆 모서리 4개 — 4 × 3 = 12개예요.","밑면 2개와 옆면 4개 — 4 + 2 = 6개예요.","두 수를 더하면 12 + 6 = 18개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L03_challenge#7','math',6,1,'u2','L03','g6_1_math_u2_L03_challenge','lesson_challenge','M6-1-u2-C2',3,'sa','auto','문 고정 받침대는 삼각기둥 모양이에요. 밑면의 세 변이 9 cm, 12 cm, 15 cm이고 옆면과 옆면이 만나는 모서리가 11 cm일 때, 이 삼각기둥의 높이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u2-C2","difficulty":3,"kind":"sa","stem":"문 고정 받침대는 삼각기둥 모양이에요. 밑면의 세 변이 9 cm, 12 cm, 15 cm이고 옆면과 옆면이 만나는 모서리가 11 cm일 때, 이 삼각기둥의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["각기둥의 높이는 두 밑면 사이의 거리예요.","옆면과 옆면이 만나는 모서리는 두 밑면과 수직이라 그 길이가 곧 높이예요.","밑면의 변 9 cm, 12 cm, 15 cm는 높이가 아니에요 — 높이는 11 cm예요."],"mis":"M6-1-u2-X06","variant_rule":{"alt":[{"stem":"문 고정 받침대는 삼각기둥 모양이에요. 밑면의 세 변이 8 cm, 15 cm, 17 cm이고 옆면과 옆면이 만나는 모서리가 6 cm일 때, 이 삼각기둥의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["각기둥의 높이는 두 밑면 사이의 거리예요.","옆면과 옆면이 만나는 모서리는 두 밑면과 수직이라 그 길이가 곧 높이예요.","밑면의 변 8 cm, 15 cm, 17 cm는 높이가 아니에요 — 높이는 6 cm예요."]},{"stem":"문 고정 받침대는 삼각기둥 모양이에요. 밑면의 세 변이 7 cm, 24 cm, 25 cm이고 옆면과 옆면이 만나는 모서리가 10 cm일 때, 이 삼각기둥의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["각기둥의 높이는 두 밑면 사이의 거리예요.","옆면과 옆면이 만나는 모서리는 두 밑면과 수직이라 그 길이가 곧 높이예요.","밑면의 변 7 cm, 24 cm, 25 cm는 높이가 아니에요 — 높이는 10 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L03_challenge#8','math',6,1,'u2','L03','g6_1_math_u2_L03_challenge','lesson_challenge','M6-1-u2-C2',4,'sa','auto','밑면이 한 변이 4 cm인 정삼각형이고 높이가 5 cm인 삼각기둥이 있어요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u2-C2","difficulty":4,"kind":"sa","stem":"밑면이 한 변이 4 cm인 정삼각형이고 높이가 5 cm인 삼각기둥이 있어요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["39"],"explanation":["두 밑면의 변은 3개씩 — 3 × 2 = 6개이고 모두 4 cm예요.","옆 모서리는 3개이고 모두 높이와 같은 5 cm예요.","6 × 4 + 3 × 5 = 39 — 모두 39 cm예요."],"mis":"M6-1-u2-X06","variant_rule":{"alt":[{"stem":"밑면이 한 변이 3 cm인 정사각형이고 높이가 6 cm인 사각기둥이 있어요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["48"],"explanation":["두 밑면의 변은 4개씩 — 4 × 2 = 8개이고 모두 3 cm예요.","옆 모서리는 4개이고 모두 높이와 같은 6 cm예요.","8 × 3 + 4 × 6 = 48 — 모두 48 cm예요."]},{"stem":"밑면이 한 변이 2 cm인 정오각형이고 높이가 7 cm인 오각기둥이 있어요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["두 밑면의 변은 5개씩 — 5 × 2 = 10개이고 모두 2 cm예요.","옆 모서리는 5개이고 모두 높이와 같은 7 cm예요.","10 × 2 + 5 × 7 = 55 — 모두 55 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L03_challenge#9','math',6,1,'u2','L03','g6_1_math_u2_L03_challenge','lesson_challenge','M6-1-u2-C2',4,'sa','auto','밑면이 한 변이 3 cm인 정육각형이고 높이가 5 cm인 육각기둥이 있어요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u2-C2","difficulty":4,"kind":"sa","stem":"밑면이 한 변이 3 cm인 정육각형이고 높이가 5 cm인 육각기둥이 있어요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["66"],"explanation":["두 밑면의 변은 6개씩 — 6 × 2 = 12개이고 모두 3 cm예요.","옆 모서리는 6개이고 모두 높이와 같은 5 cm예요.","12 × 3 + 6 × 5 = 66 — 모두 66 cm예요."],"mis":"M6-1-u2-X06","variant_rule":{"alt":[{"stem":"밑면이 한 변이 5 cm인 정삼각형이고 높이가 9 cm인 삼각기둥이 있어요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["57"],"explanation":["두 밑면의 변은 3개씩 — 3 × 2 = 6개이고 모두 5 cm예요.","옆 모서리는 3개이고 모두 높이와 같은 9 cm예요.","6 × 5 + 3 × 9 = 57 — 모두 57 cm예요."]},{"stem":"밑면이 한 변이 5 cm인 정사각형이고 높이가 8 cm인 사각기둥이 있어요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["72"],"explanation":["두 밑면의 변은 4개씩 — 4 × 2 = 8개이고 모두 5 cm예요.","옆 모서리는 4개이고 모두 높이와 같은 8 cm예요.","8 × 5 + 4 × 8 = 72 — 모두 72 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L03_challenge#10','math',6,1,'u2','L03','g6_1_math_u2_L03_challenge','lesson_challenge','M6-1-u2-C2',4,'essay','teacher','삼각기둥 모양 문 고정 받침대의 밑면의 세 변이 3 cm, 4 cm, 5 cm이고 옆면과 옆면이 만나는 모서리가 7 cm예요. 친구가 「높이는 가장 긴 변인 5 cm야」라고 했어요. 잘못된 점을 쓰고 높이를 바르게 구해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u2-C2","difficulty":4,"kind":"essay","stem":"삼각기둥 모양 문 고정 받침대의 밑면의 세 변이 3 cm, 4 cm, 5 cm이고 옆면과 옆면이 만나는 모서리가 7 cm예요. 친구가 「높이는 가장 긴 변인 5 cm야」라고 했어요. 잘못된 점을 쓰고 높이를 바르게 구해 보세요.","answer_guide":{"answer":"예: 각기둥의 높이는 두 밑면 사이의 거리인데 5 cm는 밑면 안에 있는 변의 길이라 높이가 아니다. 두 밑면이 평행하고 옆면과 옆면이 만나는 모서리는 두 밑면과 수직이므로 그 모서리의 길이 7 cm가 높이이다.","scoring_points":["높이는 두 밑면 사이의 거리라고 썼는가","5 cm는 밑면의 변이라 높이가 아니라고 썼는가","높이를 7 cm로 구했는가"]},"explanation":["높이는 두 밑면 사이의 거리예요.","5 cm는 밑면의 변이에요.","옆 모서리 7 cm가 높이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L04_basic#1','math',6,1,'u2','L04','g6_1_math_u2_L04_basic','lesson_basic','M6-1-u2-C3',1,'mc','auto','각기둥의 전개도에서 점선은 무엇을 나타내나요?',ARRAY['M6-1-u2-X07']::text[],true,'{"seq":1,"concept":"M6-1-u2-C3","difficulty":1,"kind":"mc","stem":"각기둥의 전개도에서 점선은 무엇을 나타내나요?","options":[{"t":"잘리지 않고 접히는 모서리","correct":true},{"t":"잘린 모서리","mis":"M6-1-u2-X07"},{"t":"밑면의 둘레","mis":"M6-1-u2-X07"},{"t":"옆면의 넓이","mis":"M6-1-u2-X07"}],"explanation":["각기둥의 모든 면이 이어지도록 모서리를 잘라 펼친 그림이 전개도예요.","실선은 잘린 모서리, 점선은 잘리지 않고 접히는 모서리예요.","그래서 답은 「잘리지 않고 접히는 모서리」예요."],"variant_rule":{"alt":[{"stem":"각기둥의 전개도에서 실선은 무엇을 나타내나요?","options":[{"t":"잘린 모서리","correct":true},{"t":"잘리지 않고 접히는 모서리","mis":"M6-1-u2-X07"},{"t":"각기둥의 높이","mis":"M6-1-u2-X06"},{"t":"밑면의 대각선","mis":"M6-1-u2-X07"}],"explanation":["각기둥의 모든 면이 이어지도록 모서리를 잘라 펼친 그림이 전개도예요.","실선은 잘린 모서리, 점선은 잘리지 않고 접히는 모서리예요.","그래서 답은 「잘린 모서리」예요."]},{"stem":"각기둥의 전개도는 어떤 그림인가요?","options":[{"t":"모든 면이 이어지도록 모서리를 잘라 평면 위에 펼친 그림","correct":true},{"t":"면을 하나씩 모두 떼어 늘어놓은 그림","mis":"M6-1-u2-X07"},{"t":"각기둥을 위에서 내려다본 그림","mis":"M6-1-u2-X07"},{"t":"밑면만 따라 그린 그림","mis":"M6-1-u2-X08"}],"explanation":["각기둥의 모든 면이 이어지도록 모서리를 잘라 펼친 그림이 전개도예요.","실선은 잘린 모서리, 점선은 잘리지 않고 접히는 모서리예요.","그래서 답은 「모든 면이 이어지도록 모서리를 잘라 평면 위에 펼친 그림」이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L04_basic#2','math',6,1,'u2','L04','g6_1_math_u2_L04_basic','lesson_basic','M6-1-u2-C3',1,'sa','auto','육각기둥의 전개도에서 옆면은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u2-C3","difficulty":1,"kind":"sa","stem":"육각기둥의 전개도에서 옆면은 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["밑면의 변 하나마다 옆면이 하나씩 세워져요 — 옆면은 6개예요.","전개도에는 밑면 2개도 함께 그려져요.","밑면의 변 하나마다 옆면이 하나 — 6개예요."],"mis":"M6-1-u2-X08","variant_rule":{"alt":[{"stem":"오각기둥의 전개도에서 옆면은 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["밑면의 변 하나마다 옆면이 하나씩 세워져요 — 옆면은 5개예요.","전개도에는 밑면 2개도 함께 그려져요.","밑면의 변 하나마다 옆면이 하나 — 5개예요."]},{"stem":"팔각기둥의 전개도에서 옆면은 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["밑면의 변 하나마다 옆면이 하나씩 세워져요 — 옆면은 8개예요.","전개도에는 밑면 2개도 함께 그려져요.","밑면의 변 하나마다 옆면이 하나 — 8개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L04_basic#3','math',6,1,'u2','L04','g6_1_math_u2_L04_basic','lesson_basic','M6-1-u2-C3',1,'mc','auto','삼각형 2개와 직사각형 3개가 하나로 이어진 전개도를 접으면 어떤 입체도형이 되나요?',ARRAY['M6-1-u2-X11','M6-1-u2-X08']::text[],true,'{"seq":3,"concept":"M6-1-u2-C3","difficulty":1,"kind":"mc","stem":"삼각형 2개와 직사각형 3개가 하나로 이어진 전개도를 접으면 어떤 입체도형이 되나요?","options":[{"t":"삼각기둥","correct":true},{"t":"삼각뿔","mis":"M6-1-u2-X11"},{"t":"오각기둥","mis":"M6-1-u2-X08"},{"t":"육각기둥","mis":"M6-1-u2-X08"}],"explanation":["서로 합동인 삼각형 2개가 밑면이 돼요.","직사각형 3개는 옆면 — 밑면의 변의 수와 같아요.","그래서 접으면 삼각기둥이 돼요."],"variant_rule":{"alt":[{"stem":"오각형 2개와 직사각형 5개가 하나로 이어진 전개도를 접으면 어떤 입체도형이 되나요?","options":[{"t":"오각기둥","correct":true},{"t":"오각뿔","mis":"M6-1-u2-X11"},{"t":"칠각기둥","mis":"M6-1-u2-X08"},{"t":"십각기둥","mis":"M6-1-u2-X08"}],"explanation":["서로 합동인 오각형 2개가 밑면이 돼요.","직사각형 5개는 옆면 — 밑면의 변의 수와 같아요.","그래서 접으면 오각기둥이 돼요."]},{"stem":"육각형 2개와 직사각형 6개가 하나로 이어진 전개도를 접으면 어떤 입체도형이 되나요?","options":[{"t":"육각기둥","correct":true},{"t":"육각뿔","mis":"M6-1-u2-X11"},{"t":"팔각기둥","mis":"M6-1-u2-X08"},{"t":"십이각기둥","mis":"M6-1-u2-X08"}],"explanation":["서로 합동인 육각형 2개가 밑면이 돼요.","직사각형 6개는 옆면 — 밑면의 변의 수와 같아요.","그래서 접으면 육각기둥이 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L04_basic#4','math',6,1,'u2','L04','g6_1_math_u2_L04_basic','lesson_basic','M6-1-u2-C3',1,'sa','auto','삼각기둥 모양 집 모형을 모서리를 따라 잘라 펼쳤어요. 펼친 그림에 삼각형은 몇 개 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u2-C3","difficulty":1,"kind":"sa","stem":"삼각기둥 모양 집 모형을 모서리를 따라 잘라 펼쳤어요. 펼친 그림에 삼각형은 몇 개 있나요? 숫자로 쓰세요.","answer":["2"],"explanation":["삼각기둥의 밑면은 삼각형 2개예요.","옆면은 밑면의 변의 수만큼 — 직사각형 3개예요.","펼친 그림에는 삼각형 2개와 직사각형 3개, 모두 2 + 3 = 5개가 이어져 있어요."],"mis":"M6-1-u2-X08","variant_rule":{"alt":[{"stem":"삼각기둥 모양 집 모형을 모서리를 따라 잘라 펼쳤어요. 펼친 그림에 직사각형은 몇 개 있나요? 숫자로 쓰세요.","answer":["3"],"explanation":["삼각기둥의 밑면은 삼각형 2개예요.","옆면은 밑면의 변의 수만큼 — 직사각형 3개예요.","펼친 그림에는 삼각형 2개와 직사각형 3개, 모두 2 + 3 = 5개가 이어져 있어요."]},{"stem":"삼각기둥 모양 집 모형을 모서리를 따라 잘라 펼쳤어요. 펼친 그림에 면은 모두 몇 개 있나요? 숫자로 쓰세요.","answer":["5"],"explanation":["삼각기둥의 밑면은 삼각형 2개예요.","옆면은 밑면의 변의 수만큼 — 직사각형 3개예요.","펼친 그림에는 삼각형 2개와 직사각형 3개, 모두 2 + 3 = 5개가 이어져 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L04_basic#5','math',6,1,'u2','L04','g6_1_math_u2_L04_basic','lesson_basic','M6-1-u2-C3',2,'sa','auto','사각기둥의 전개도에는 면이 모두 몇 개 그려져 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u2-C3","difficulty":2,"kind":"sa","stem":"사각기둥의 전개도에는 면이 모두 몇 개 그려져 있나요? 숫자로 쓰세요.","answer":["6"],"explanation":["밑면의 변 하나마다 옆면이 하나씩 세워져요 — 옆면은 4개예요.","전개도에는 밑면 2개도 함께 그려져요.","밑면 2개와 옆면 4개 — 4 + 2 = 6개예요."],"mis":"M6-1-u2-X08","variant_rule":{"alt":[{"stem":"육각기둥의 전개도에는 면이 모두 몇 개 그려져 있나요? 숫자로 쓰세요.","answer":["8"],"explanation":["밑면의 변 하나마다 옆면이 하나씩 세워져요 — 옆면은 6개예요.","전개도에는 밑면 2개도 함께 그려져요.","밑면 2개와 옆면 6개 — 6 + 2 = 8개예요."]},{"stem":"오각기둥의 전개도에는 면이 모두 몇 개 그려져 있나요? 숫자로 쓰세요.","answer":["7"],"explanation":["밑면의 변 하나마다 옆면이 하나씩 세워져요 — 옆면은 5개예요.","전개도에는 밑면 2개도 함께 그려져요.","밑면 2개와 옆면 5개 — 5 + 2 = 7개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L04_basic#6','math',6,1,'u2','L04','g6_1_math_u2_L04_basic','lesson_basic','M6-1-u2-C3',2,'mc','auto','각기둥의 전개도를 접었을 때 서로 맞닿는 두 선분에 대한 설명으로 옳은 것은 어느 것인가요?',ARRAY['M6-1-u2-X09']::text[],true,'{"seq":6,"concept":"M6-1-u2-C3","difficulty":2,"kind":"mc","stem":"각기둥의 전개도를 접었을 때 서로 맞닿는 두 선분에 대한 설명으로 옳은 것은 어느 것인가요?","options":[{"t":"길이가 항상 같아요","correct":true},{"t":"길이가 항상 달라요","mis":"M6-1-u2-X09"},{"t":"긴 쪽이 밑면이 돼요","mis":"M6-1-u2-X09"},{"t":"길이는 상관없어요","mis":"M6-1-u2-X09"}],"explanation":["전개도를 접으면 떨어져 있던 두 선분이 서로 맞닿아 모서리 하나가 돼요.","그래서 맞닿는 두 선분의 길이는 같아야 해요.","길이가 다르면 접었을 때 딱 맞물리지 않아요."],"variant_rule":{"alt":[{"stem":"전개도의 양쪽 끝에 있는 두 선분은 접었을 때 어떻게 되나요?","options":[{"t":"서로 맞닿아 하나의 모서리가 돼요","correct":true},{"t":"서로 떨어져 있어요","mis":"M6-1-u2-X07"},{"t":"밑면이 돼요","mis":"M6-1-u2-X01"},{"t":"잘라서 버려요","mis":"M6-1-u2-X07"}],"explanation":["전개도를 접으면 떨어져 있던 두 선분이 서로 맞닿아 모서리 하나가 돼요.","그래서 맞닿는 두 선분의 길이는 같아야 해요.","길이가 다르면 접었을 때 딱 맞물리지 않아요."]},{"stem":"전개도에서 맞닿는 두 선분의 길이가 다르면 어떻게 되나요?","options":[{"t":"접었을 때 틈이 생기거나 남는 곳이 생겨요","correct":true},{"t":"그대로 각기둥이 돼요","mis":"M6-1-u2-X09"},{"t":"각뿔이 돼요","mis":"M6-1-u2-X11"},{"t":"면의 수가 늘어나요","mis":"M6-1-u2-X08"}],"explanation":["전개도를 접으면 떨어져 있던 두 선분이 서로 맞닿아 모서리 하나가 돼요.","그래서 맞닿는 두 선분의 길이는 같아야 해요.","길이가 다르면 접었을 때 딱 맞물리지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L04_basic#7','math',6,1,'u2','L04','g6_1_math_u2_L04_basic','lesson_basic','M6-1-u2-C3',2,'ox','auto','전개도에서 잘린 모서리는 점선으로 나타내요.',ARRAY['M6-1-u2-X07']::text[],true,'{"seq":7,"concept":"M6-1-u2-C3","difficulty":2,"kind":"ox","stem":"전개도에서 잘린 모서리는 점선으로 나타내요.","answer":"X","reason_options":[{"t":"잘린 모서리는 실선, 접히는 모서리가 점선이기 때문에","correct":true},{"t":"잘린 곳은 끊어져 보이게 점선으로 그리기 때문에","mis":"M6-1-u2-X07"}],"mis":"M6-1-u2-X07","explanation":["전개도는 모든 면이 이어지도록 모서리를 잘라 펼친 그림이에요.","실선은 잘린 모서리, 점선은 접히는 모서리예요.","밑면 2개, 옆면은 한 밑면의 변의 수만큼 그려져요."],"variant_rule":{"alt":[{"stem":"각기둥의 전개도에서 옆면의 수는 한 밑면의 변의 수와 같아요.","answer":"O","reason_options":[{"t":"밑면의 변 하나마다 옆면이 하나씩 세워지기 때문에","correct":true},{"t":"옆면은 언제나 4개이기 때문에","mis":"M6-1-u2-X08"}],"explanation":["전개도는 모든 면이 이어지도록 모서리를 잘라 펼친 그림이에요.","실선은 잘린 모서리, 점선은 접히는 모서리예요.","밑면 2개, 옆면은 한 밑면의 변의 수만큼 그려져요."]},{"stem":"면들이 서로 떨어져 있는 그림도 전개도예요.","answer":"X","reason_options":[{"t":"전개도는 모든 면이 이어지도록 펼친 그림이기 때문에","correct":true},{"t":"면의 수만 맞으면 되기 때문에","mis":"M6-1-u2-X07"}],"explanation":["전개도는 모든 면이 이어지도록 모서리를 잘라 펼친 그림이에요.","실선은 잘린 모서리, 점선은 접히는 모서리예요.","밑면 2개, 옆면은 한 밑면의 변의 수만큼 그려져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L04_basic#8','math',6,1,'u2','L04','g6_1_math_u2_L04_basic','lesson_basic','M6-1-u2-C3',2,'mc','auto','사각형 2개와 직사각형 4개가 하나로 이어진 전개도를 접으면 어떤 입체도형이 되나요?',ARRAY['M6-1-u2-X11','M6-1-u2-X08']::text[],true,'{"seq":8,"concept":"M6-1-u2-C3","difficulty":2,"kind":"mc","stem":"사각형 2개와 직사각형 4개가 하나로 이어진 전개도를 접으면 어떤 입체도형이 되나요?","options":[{"t":"사각기둥","correct":true},{"t":"사각뿔","mis":"M6-1-u2-X11"},{"t":"육각기둥","mis":"M6-1-u2-X08"},{"t":"팔각기둥","mis":"M6-1-u2-X08"}],"explanation":["서로 합동인 사각형 2개가 밑면이 돼요.","직사각형 4개는 옆면 — 밑면의 변의 수와 같아요.","그래서 접으면 사각기둥이 돼요."],"variant_rule":{"alt":[{"stem":"칠각형 2개와 직사각형 7개가 하나로 이어진 전개도를 접으면 어떤 입체도형이 되나요?","options":[{"t":"칠각기둥","correct":true},{"t":"칠각뿔","mis":"M6-1-u2-X11"},{"t":"구각기둥","mis":"M6-1-u2-X08"},{"t":"십사각기둥","mis":"M6-1-u2-X08"}],"explanation":["서로 합동인 칠각형 2개가 밑면이 돼요.","직사각형 7개는 옆면 — 밑면의 변의 수와 같아요.","그래서 접으면 칠각기둥이 돼요."]},{"stem":"팔각형 2개와 직사각형 8개가 하나로 이어진 전개도를 접으면 어떤 입체도형이 되나요?","options":[{"t":"팔각기둥","correct":true},{"t":"팔각뿔","mis":"M6-1-u2-X11"},{"t":"십각기둥","mis":"M6-1-u2-X08"},{"t":"십육각기둥","mis":"M6-1-u2-X08"}],"explanation":["서로 합동인 팔각형 2개가 밑면이 돼요.","직사각형 8개는 옆면 — 밑면의 변의 수와 같아요.","그래서 접으면 팔각기둥이 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L04_basic#9','math',6,1,'u2','L04','g6_1_math_u2_L04_basic','lesson_basic','M6-1-u2-C3',2,'mc','auto','「삼각형 2개와 직사각형 4개가 이어진 그림」은 삼각기둥의 전개도가 될 수 없어요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u2-X08']::text[],true,'{"seq":9,"concept":"M6-1-u2-C3","difficulty":2,"kind":"mc","stem":"「삼각형 2개와 직사각형 4개가 이어진 그림」은 삼각기둥의 전개도가 될 수 없어요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"옆면의 수가 한 밑면의 변의 수와 다르기 때문에","correct":true},{"t":"밑면이 1개뿐이기 때문에","mis":"M6-1-u2-X08"},{"t":"접으면 두 밑면이 겹쳐 맞닿지 않기 때문에","mis":"M6-1-u2-X08"},{"t":"두 밑면이 서로 합동이 아니기 때문에","mis":"M6-1-u2-X08"}],"explanation":["각기둥의 전개도에는 합동인 밑면 2개와 변의 수만큼의 옆면이 있어야 해요.","접었을 때 면이 겹치지 않고 맞닿는 선분의 길이가 같아야 해요.","이 그림은 옆면의 수가 한 밑면의 변의 수와 다르기 때문에 전개도가 아니에요."],"variant_rule":{"alt":[{"stem":"「삼각형 1개와 직사각형 3개가 이어진 그림」은 삼각기둥의 전개도가 될 수 없어요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"밑면이 1개뿐이기 때문에","correct":true},{"t":"옆면의 수가 한 밑면의 변의 수와 다르기 때문에","mis":"M6-1-u2-X08"},{"t":"접으면 두 밑면이 겹쳐 맞닿지 않기 때문에","mis":"M6-1-u2-X08"},{"t":"두 밑면이 서로 합동이 아니기 때문에","mis":"M6-1-u2-X08"}],"explanation":["각기둥의 전개도에는 합동인 밑면 2개와 변의 수만큼의 옆면이 있어야 해요.","접었을 때 면이 겹치지 않고 맞닿는 선분의 길이가 같아야 해요.","이 그림은 밑면이 1개뿐이기 때문에 전개도가 아니에요."]},{"stem":"「크기가 다른 사각형 2개와 직사각형 4개가 이어진 그림」은 사각기둥의 전개도가 될 수 없어요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"두 밑면이 서로 합동이 아니기 때문에","correct":true},{"t":"옆면의 수가 한 밑면의 변의 수와 다르기 때문에","mis":"M6-1-u2-X02"},{"t":"밑면이 1개뿐이기 때문에","mis":"M6-1-u2-X02"},{"t":"접으면 두 밑면이 겹쳐 맞닿지 않기 때문에","mis":"M6-1-u2-X02"}],"explanation":["각기둥의 전개도에는 합동인 밑면 2개와 변의 수만큼의 옆면이 있어야 해요.","접었을 때 면이 겹치지 않고 맞닿는 선분의 길이가 같아야 해요.","이 그림은 두 밑면이 서로 합동이 아니기 때문에 전개도가 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L04_basic#10','math',6,1,'u2','L04','g6_1_math_u2_L04_basic','lesson_basic','M6-1-u2-C3',3,'sa','auto','어떤 각기둥의 전개도에 옆면이 5개 그려져 있어요. 이 각기둥의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M6-1-u2-C3","difficulty":3,"kind":"sa","stem":"어떤 각기둥의 전개도에 옆면이 5개 그려져 있어요. 이 각기둥의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["옆면의 수는 한 밑면의 변의 수와 같아요 — 밑면은 오각형이에요.","그래서 이 입체도형은 오각기둥이에요.","위 밑면 5개, 아래 밑면 5개, 옆 모서리 5개 — 5 × 3 = 15개예요."],"mis":"M6-1-u2-X14","variant_rule":{"alt":[{"stem":"어떤 각기둥의 전개도에 옆면이 6개 그려져 있어요. 이 각기둥의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["옆면의 수는 한 밑면의 변의 수와 같아요 — 밑면은 육각형이에요.","그래서 이 입체도형은 육각기둥이에요.","위 밑면 6개, 아래 밑면 6개, 옆 모서리 6개 — 6 × 3 = 18개예요."]},{"stem":"어떤 각기둥의 전개도에 옆면이 4개 그려져 있어요. 이 각기둥의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["옆면의 수는 한 밑면의 변의 수와 같아요 — 밑면은 사각형이에요.","그래서 이 입체도형은 사각기둥이에요.","위 밑면 4개, 아래 밑면 4개, 옆 모서리 4개 — 4 × 3 = 12개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L04_challenge#1','math',6,1,'u2','L04','g6_1_math_u2_L04_challenge','lesson_challenge','M6-1-u2-C3',2,'sa','auto','팔각기둥의 전개도에는 면이 모두 몇 개 그려져 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u2-C3","difficulty":2,"kind":"sa","stem":"팔각기둥의 전개도에는 면이 모두 몇 개 그려져 있나요? 숫자로 쓰세요.","answer":["10"],"explanation":["밑면의 변 하나마다 옆면이 하나씩 세워져요 — 옆면은 8개예요.","전개도에는 밑면 2개도 함께 그려져요.","밑면 2개와 옆면 8개 — 8 + 2 = 10개예요."],"mis":"M6-1-u2-X08","variant_rule":{"alt":[{"stem":"칠각기둥의 전개도에는 면이 모두 몇 개 그려져 있나요? 숫자로 쓰세요.","answer":["9"],"explanation":["밑면의 변 하나마다 옆면이 하나씩 세워져요 — 옆면은 7개예요.","전개도에는 밑면 2개도 함께 그려져요.","밑면 2개와 옆면 7개 — 7 + 2 = 9개예요."]},{"stem":"구각기둥의 전개도에는 면이 모두 몇 개 그려져 있나요? 숫자로 쓰세요.","answer":["11"],"explanation":["밑면의 변 하나마다 옆면이 하나씩 세워져요 — 옆면은 9개예요.","전개도에는 밑면 2개도 함께 그려져요.","밑면 2개와 옆면 9개 — 9 + 2 = 11개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L04_challenge#2','math',6,1,'u2','L04','g6_1_math_u2_L04_challenge','lesson_challenge','M6-1-u2-C3',2,'ox','auto','전개도를 접을 때 맞닿는 두 선분의 길이는 같아야 해요.',ARRAY['M6-1-u2-X09']::text[],true,'{"seq":2,"concept":"M6-1-u2-C3","difficulty":2,"kind":"ox","stem":"전개도를 접을 때 맞닿는 두 선분의 길이는 같아야 해요.","answer":"O","reason_options":[{"t":"두 선분이 맞닿아 하나의 모서리가 되기 때문에","correct":true},{"t":"긴 선분이 짧은 선분을 덮기 때문에","mis":"M6-1-u2-X09"}],"mis":"M6-1-u2-X09","explanation":["전개도는 모든 면이 이어지도록 모서리를 잘라 펼친 그림이에요.","실선은 잘린 모서리, 점선은 접히는 모서리예요.","밑면 2개, 옆면은 한 밑면의 변의 수만큼 그려져요."],"variant_rule":{"alt":[{"stem":"육각기둥의 전개도에는 면이 6개 그려져요.","answer":"X","reason_options":[{"t":"밑면 2개와 옆면 6개 — 면이 8개 그려지기 때문에","correct":true},{"t":"육각기둥이니 면도 6개이기 때문에","mis":"M6-1-u2-X08"}],"explanation":["전개도는 모든 면이 이어지도록 모서리를 잘라 펼친 그림이에요.","실선은 잘린 모서리, 점선은 접히는 모서리예요.","밑면 2개, 옆면은 한 밑면의 변의 수만큼 그려져요."]},{"stem":"전개도에는 밑면이 1개만 그려져 있어도 돼요.","answer":"X","reason_options":[{"t":"각기둥은 밑면이 2개라 전개도에도 2개가 있어야 하기 때문에","correct":true},{"t":"접으면 밑면이 저절로 생기기 때문에","mis":"M6-1-u2-X08"}],"explanation":["전개도는 모든 면이 이어지도록 모서리를 잘라 펼친 그림이에요.","실선은 잘린 모서리, 점선은 접히는 모서리예요.","밑면 2개, 옆면은 한 밑면의 변의 수만큼 그려져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L04_challenge#3','math',6,1,'u2','L04','g6_1_math_u2_L04_challenge','lesson_challenge','M6-1-u2-C3',3,'mc','auto','「오각형 2개와 직사각형 5개가 이어졌는데, 두 오각형이 같은 쪽에 붙어 접으면 겹치는 그림」은 오각기둥의 전개도가 될 수 없어요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u2-X13']::text[],true,'{"seq":3,"concept":"M6-1-u2-C3","difficulty":3,"kind":"mc","stem":"「오각형 2개와 직사각형 5개가 이어졌는데, 두 오각형이 같은 쪽에 붙어 접으면 겹치는 그림」은 오각기둥의 전개도가 될 수 없어요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"접으면 두 밑면이 겹쳐 맞닿지 않기 때문에","correct":true},{"t":"옆면의 수가 한 밑면의 변의 수와 다르기 때문에","mis":"M6-1-u2-X13"},{"t":"밑면이 1개뿐이기 때문에","mis":"M6-1-u2-X13"},{"t":"두 밑면이 서로 합동이 아니기 때문에","mis":"M6-1-u2-X13"}],"explanation":["각기둥의 전개도에는 합동인 밑면 2개와 변의 수만큼의 옆면이 있어야 해요.","접었을 때 면이 겹치지 않고 맞닿는 선분의 길이가 같아야 해요.","이 그림은 접으면 두 밑면이 겹쳐 맞닿지 않기 때문에 전개도가 아니에요."],"variant_rule":{"alt":[{"stem":"「삼각형 2개와 직사각형 4개가 이어진 그림」은 삼각기둥의 전개도가 될 수 없어요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"옆면의 수가 한 밑면의 변의 수와 다르기 때문에","correct":true},{"t":"밑면이 1개뿐이기 때문에","mis":"M6-1-u2-X08"},{"t":"접으면 두 밑면이 겹쳐 맞닿지 않기 때문에","mis":"M6-1-u2-X08"},{"t":"두 밑면이 서로 합동이 아니기 때문에","mis":"M6-1-u2-X08"}],"explanation":["각기둥의 전개도에는 합동인 밑면 2개와 변의 수만큼의 옆면이 있어야 해요.","접었을 때 면이 겹치지 않고 맞닿는 선분의 길이가 같아야 해요.","이 그림은 옆면의 수가 한 밑면의 변의 수와 다르기 때문에 전개도가 아니에요."]},{"stem":"「삼각형 1개와 직사각형 3개가 이어진 그림」은 삼각기둥의 전개도가 될 수 없어요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"밑면이 1개뿐이기 때문에","correct":true},{"t":"옆면의 수가 한 밑면의 변의 수와 다르기 때문에","mis":"M6-1-u2-X08"},{"t":"접으면 두 밑면이 겹쳐 맞닿지 않기 때문에","mis":"M6-1-u2-X08"},{"t":"두 밑면이 서로 합동이 아니기 때문에","mis":"M6-1-u2-X08"}],"explanation":["각기둥의 전개도에는 합동인 밑면 2개와 변의 수만큼의 옆면이 있어야 해요.","접었을 때 면이 겹치지 않고 맞닿는 선분의 길이가 같아야 해요.","이 그림은 밑면이 1개뿐이기 때문에 전개도가 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED